# 1.1 Windows 해상도 관리 (게임 시작 시 1152x864로 변경, 종료 시 복원)
# ============================================================
_original_resolution = None  # 원래 해상도 저장

def _get_current_resolution():
    """현재 화면 해상도를 가져옵니다 (Windows 전용)"""
    if sys.platform != 'win32':
        return None
    try:
        import ctypes
        user32 = ctypes.windll.user32
        width = user32.GetSystemMetrics(0)
        height = user32.GetSystemMetrics(1)
        return (width, height)
    except Exception as e:
        print(f"해상도 가져오기 실패: {e}")
        return None

def _get_native_resolution():
    """모니터의 네이티브(물리적) 해상도를 가져옵니다 (Windows 전용)
    현재 설정된 해상도가 아닌 모니터가 지원하는 최대 해상도를 반환합니다."""
    if sys.platform != 'win32':
        return None
    try:
        import ctypes
        from ctypes import wintypes

        # EnumDisplaySettings로 모니터의 모든 지원 해상도를 가져옴
        class DEVMODE(ctypes.Structure):
            _fields_ = [
                ("dmDeviceName", ctypes.c_wchar * 32),
                ("dmSpecVersion", wintypes.WORD),
                ("dmDriverVersion", wintypes.WORD),
                ("dmSize", wintypes.WORD),
                ("dmDriverExtra", wintypes.WORD),
                ("dmFields", wintypes.DWORD),
                ("dmPositionX", wintypes.LONG),
                ("dmPositionY", wintypes.LONG),
                ("dmDisplayOrientation", wintypes.DWORD),
                ("dmDisplayFixedOutput", wintypes.DWORD),
                ("dmColor", ctypes.c_short),
                ("dmDuplex", ctypes.c_short),
                ("dmYResolution", ctypes.c_short),
                ("dmTTOption", ctypes.c_short),
                ("dmCollate", ctypes.c_short),
                ("dmFormName", ctypes.c_wchar * 32),
                ("dmLogPixels", wintypes.WORD),
                ("dmBitsPerPel", wintypes.DWORD),
                ("dmPelsWidth", wintypes.DWORD),
                ("dmPelsHeight", wintypes.DWORD),
                ("dmDisplayFlags", wintypes.DWORD),
                ("dmDisplayFrequency", wintypes.DWORD),
            ]

        user32 = ctypes.windll.user32
        max_width, max_height = 0, 0

        # 모든 지원 해상도를 순회하며 최대값 찾기
        i = 0
        devmode = DEVMODE()
        devmode.dmSize = ctypes.sizeof(DEVMODE)

        while user32.EnumDisplaySettingsW(None, i, ctypes.byref(devmode)):
            if devmode.dmPelsWidth > max_width or (devmode.dmPelsWidth == max_width and devmode.dmPelsHeight > max_height):
                max_width = devmode.dmPelsWidth
                max_height = devmode.dmPelsHeight
            i += 1

        if max_width > 0 and max_height > 0:
            return (max_width, max_height)
        return None
    except Exception as e:
        print(f"네이티브 해상도 가져오기 실패: {e}")
        return None

# 더블 모니터용: 가장 큰 모니터 정보 캐시
# 'x','y': 가상 좌표 (DPI 스케일됨, 창 배치용)
# 'w','h': 물리적 해상도 (DPI 무관, 창 크기 계산용)
# 'vw','vh': 가상 크기 (DPI 스케일됨)
_largest_monitor_info = None

def _detect_largest_monitor():
    """모든 모니터를 열거하고 물리적 해상도 기준 가장 큰 모니터 반환 (Windows 전용)
    GetMonitorInfoW = DPI 스케일된 가상 좌표 (창 위치 지정용)
    EnumDisplaySettingsW = 실제 물리적 해상도 (창 크기 계산용)"""
    global _largest_monitor_info
    if sys.platform != 'win32':
        return None
    try:
        import ctypes
        from ctypes import wintypes

        class MONITORINFOEX(ctypes.Structure):
            _fields_ = [
                ("cbSize", wintypes.DWORD),
                ("rcMonitor", wintypes.RECT),
                ("rcWork", wintypes.RECT),
                ("dwFlags", wintypes.DWORD),
                ("szDevice", ctypes.c_wchar * 32),
            ]

        class DEVMODE(ctypes.Structure):
            _fields_ = [
                ("dmDeviceName", ctypes.c_wchar * 32),
                ("dmSpecVersion", wintypes.WORD),
                ("dmDriverVersion", wintypes.WORD),
                ("dmSize", wintypes.WORD),
                ("dmDriverExtra", wintypes.WORD),
                ("dmFields", wintypes.DWORD),
                ("dmPositionX", wintypes.LONG),
                ("dmPositionY", wintypes.LONG),
                ("dmDisplayOrientation", wintypes.DWORD),
                ("dmDisplayFixedOutput", wintypes.DWORD),
                ("dmColor", ctypes.c_short),
                ("dmDuplex", ctypes.c_short),
                ("dmYResolution", ctypes.c_short),
                ("dmTTOption", ctypes.c_short),
                ("dmCollate", ctypes.c_short),
                ("dmFormName", ctypes.c_wchar * 32),
                ("dmLogPixels", wintypes.WORD),
                ("dmBitsPerPel", wintypes.DWORD),
                ("dmPelsWidth", wintypes.DWORD),
                ("dmPelsHeight", wintypes.DWORD),
                ("dmDisplayFlags", wintypes.DWORD),
                ("dmDisplayFrequency", wintypes.DWORD),
            ]

        user32 = ctypes.windll.user32
        monitors = []

        MONITORENUMPROC = ctypes.WINFUNCTYPE(
            ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p,
            ctypes.POINTER(wintypes.RECT), ctypes.c_long
        )

        def _enum_callback(hMonitor, hdcMonitor, lprcMonitor, dwData):
            info = MONITORINFOEX()
            info.cbSize = ctypes.sizeof(MONITORINFOEX)
            user32.GetMonitorInfoW(hMonitor, ctypes.byref(info))
            r = info.rcMonitor
            virt_w = r.right - r.left
            virt_h = r.bottom - r.top

            # EnumDisplaySettingsW로 물리적(실제) 해상도 가져오기
            devmode = DEVMODE()
            devmode.dmSize = ctypes.sizeof(DEVMODE)
            phys_w, phys_h = virt_w, virt_h  # 폴백: 가상 크기
            # ENUM_CURRENT_SETTINGS = -1
            if user32.EnumDisplaySettingsW(info.szDevice, -1, ctypes.byref(devmode)):
                if devmode.dmPelsWidth > 0 and devmode.dmPelsHeight > 0:
                    phys_w = devmode.dmPelsWidth
                    phys_h = devmode.dmPelsHeight

            monitors.append({
                'x': r.left, 'y': r.top,       # 가상 좌표 (창 배치용)
                'w': phys_w, 'h': phys_h,       # 물리적 해상도 (크기 계산용)
                'vw': virt_w, 'vh': virt_h,     # 가상 크기 (DPI 스케일됨)
                'device': info.szDevice,
            })
            return 1

        _cb = MONITORENUMPROC(_enum_callback)
        user32.EnumDisplayMonitors(None, None, _cb, 0)

        if not monitors:
            return None

        # 물리적 면적(w*h) 기준으로 가장 큰 모니터 선택
        largest = max(monitors, key=lambda m: m['w'] * m['h'])
        _largest_monitor_info = largest
        print(f"[모니터] 감지된 모니터 {len(monitors)}개:", flush=True)
        for m in monitors:
            _dpi_pct = round(m['w'] / m['vw'] * 100) if m['vw'] > 0 else 100
            print(f"  - {m['device'].strip()}: 물리 {m['w']}x{m['h']}, 가상 {m['vw']}x{m['vh']} ({_dpi_pct}% DPI), 위치 ({m['x']},{m['y']})", flush=True)
        print(f"[모니터] 선택: {largest['w']}x{largest['h']} @ ({largest['x']},{largest['y']})", flush=True)
        return largest
    except Exception as e:
        print(f"[모니터] 모니터 감지 실패: {e}", flush=True)
        return None

# 게임 시작 시 즉시 감지
_detect_largest_monitor()

def _get_largest_monitor_pos(win_w, win_h):
    """가장 큰 모니터의 중앙에 창을 배치하기 위한 좌표 반환 (가상 좌표 사용)
    Args: win_w, win_h - 창 크기 (가상 좌표 기준)
    Returns: (x, y) 또는 None"""
    if _largest_monitor_info is None:
        return None
    m = _largest_monitor_info
    # 가상 크기 기준으로 중앙 계산 (SDL은 가상 좌표 사용)
    cx = m['x'] + (m['vw'] - win_w) // 2
    cy = m['y'] + (m['vh'] - win_h) // 2
    return (cx, cy)

def _get_largest_monitor_resolution():
    """가장 큰 모니터의 물리적 해상도 반환. Returns: (w, h) or None"""
    if _largest_monitor_info is None:
        return None
    return (_largest_monitor_info['w'], _largest_monitor_info['h'])

def _change_windows_resolution(width, height):
    """Windows 화면 해상도를 변경합니다"""
    if sys.platform != 'win32':
        return False
    try:
        import ctypes

        # DEVMODE 구조체 정의
        class DEVMODE(ctypes.Structure):
            _fields_ = [
                ("dmDeviceName", ctypes.c_wchar * 32),
                ("dmSpecVersion", ctypes.c_ushort),
                ("dmDriverVersion", ctypes.c_ushort),
                ("dmSize", ctypes.c_ushort),
                ("dmDriverExtra", ctypes.c_ushort),
                ("dmFields", ctypes.c_ulong),
                ("dmPositionX", ctypes.c_long),
                ("dmPositionY", ctypes.c_long),
                ("dmDisplayOrientation", ctypes.c_ulong),
                ("dmDisplayFixedOutput", ctypes.c_ulong),
                ("dmColor", ctypes.c_short),
                ("dmDuplex", ctypes.c_short),
                ("dmYResolution", ctypes.c_short),
                ("dmTTOption", ctypes.c_short),
                ("dmCollate", ctypes.c_short),
                ("dmFormName", ctypes.c_wchar * 32),
                ("dmLogPixels", ctypes.c_ushort),
                ("dmBitsPerPel", ctypes.c_ulong),
                ("dmPelsWidth", ctypes.c_ulong),
                ("dmPelsHeight", ctypes.c_ulong),
                ("dmDisplayFlags", ctypes.c_ulong),
                ("dmDisplayFrequency", ctypes.c_ulong),
            ]

        DM_PELSWIDTH = 0x80000
        DM_PELSHEIGHT = 0x100000
        CDS_FULLSCREEN = 4
        DISP_CHANGE_SUCCESSFUL = 0

        devmode = DEVMODE()
        devmode.dmSize = ctypes.sizeof(DEVMODE)
        devmode.dmPelsWidth = width
        devmode.dmPelsHeight = height
        devmode.dmFields = DM_PELSWIDTH | DM_PELSHEIGHT

        user32 = ctypes.windll.user32
        result = user32.ChangeDisplaySettingsW(ctypes.byref(devmode), CDS_FULLSCREEN)

        if result == DISP_CHANGE_SUCCESSFUL:
            print(f"화면 해상도 변경: {width}x{height}")
            return True
        else:
            print(f"해상도 변경 실패 (코드: {result})")
            return False
    except Exception as e:
        print(f"해상도 변경 오류: {e}")
        return False

def _restore_windows_resolution():
    """Windows 화면 해상도를 원래대로 복원합니다"""
    global _original_resolution
    if sys.platform != 'win32':
        return
    if _original_resolution is None:
        return
    try:
        import ctypes
        # NULL을 전달하면 기본 설정으로 복원
        user32 = ctypes.windll.user32
        user32.ChangeDisplaySettingsW(None, 0)
    except Exception as e:
        print(f"해상도 복원 오류: {e}")
 
def _get_matching_resolution(original_width, original_height):
    """모니터 비율에 맞는 적절한 해상도 찾기 (게임이 세로를 꽉 채우도록)"""
    original_ratio = original_width / original_height

    # 게임 최소 세로 크기 (750 + 여백 60)
    MIN_HEIGHT = 810

    # 비율별 해상도 옵션 (세로 810 이상만, 낮은 순서대로)
    resolution_options = [
        # 16:10 비율
        (1440, 900),
        (1680, 1050),
        (1920, 1200),
        # 16:9 비율
        (1600, 900),
        (1920, 1080),
        # 4:3 비율
        (1152, 864),
        (1280, 960),
        (1400, 1050),
    ]

    # 현재 해상도가 이미 목표 해상도 목록에 있으면 그대로 사용
    if (original_width, original_height) in resolution_options:
        return (original_width, original_height)

    # 원본 비율과 가장 가까우면서 세로가 충분한 해상도 찾기
    best_match = None
    best_ratio_diff = float('inf')

    for w, h in resolution_options:
        # 원본보다 작은 해상도만 고려, 세로는 최소 크기 이상
        if w >= original_width or h >= original_height:
            continue
        if h < MIN_HEIGHT:
            continue

        ratio = w / h
        ratio_diff = abs(ratio - original_ratio)

        # 비율 차이가 1% 이내면 매칭으로 간주
        if ratio_diff < 0.01 and ratio_diff < best_ratio_diff:
            best_ratio_diff = ratio_diff
            best_match = (w, h)

    return best_match

def _setup_game_resolution():
    """게임 시작 시 모니터 비율에 맞는 낮은 해상도로 변경하고, 종료 시 복원되도록 설정합니다"""
    global _original_resolution

    if sys.platform != 'win32':
        return  # Windows가 아니면 스킵

    # 현재 해상도 저장
    current_res = _get_current_resolution()
    if current_res is None:
        return

    # 모니터 비율에 맞는 해상도 찾기
    target_res = _get_matching_resolution(current_res[0], current_res[1])

    if target_res is None:
        # 매칭되는 해상도 없으면 기본값 사용 (레터박스 발생 가능)
        target_width, target_height = 1152, 864
        print(f"[해상도] 매칭 해상도 없음, 기본값 사용: {target_width}x{target_height}")
    else:
        target_width, target_height = target_res
        print(f"[해상도] 모니터 비율 매칭: {current_res[0]}x{current_res[1]} -> {target_width}x{target_height}")

    # 이미 원하는 해상도면 변경하지 않음
    if current_res == (target_width, target_height):
        # 복원 필요 없지만 전체화면 초기화를 위해 원본 해상도 유지
        # (이미 낮은 해상도면 그것이 원본)
        _original_resolution = current_res
        print(f"[해상도] 이미 목표 해상도, 변경 없음: {current_res[0]}x{current_res[1]}")
        return

    # 해상도 변경 전 원본 저장
    _original_resolution = current_res

    # 해상도 변경
    if _change_windows_resolution(target_width, target_height):
        # 프로그램 종료 시 해상도 복원 등록
        atexit.register(_restore_windows_resolution)

# 게임 시작 시 해상도 설정 (Windows 전용)
# 창모드로 시작하므로 OS 해상도 변경 불필요 (전체화면 전환 시 switch_display_mode에서 처리)
# _setup_game_resolution()
# ============================================================
