FULLSCREEN_MODE = False  # 창모드(필러 포함)로 시작
FULLSCREEN_WIDTH = 0
FULLSCREEN_HEIGHT = 0
GAME_OFFSET_X = 0
GAME_OFFSET_Y = 0
GAME_SCALE_FACTOR = 1.0  # 전체화면 자동 스케일링 비율
GAME_SCALED_WIDTH = 0    # 스케일링된 게임 화면 너비
GAME_SCALED_HEIGHT = 0   # 스케일링된 게임 화면 높이
_use_scaled_mode = False  # True: pygame.SCALED 활성, 수동 스케일링 건너뜀 (창모드 GPU 스케일링)

def _setup_fullscreen_mode():
    global FULLSCREEN_MODE, FULLSCREEN_WIDTH, FULLSCREEN_HEIGHT
    # 더블 모니터: 가장 큰 모니터 해상도 우선 사용
    largest_res = _get_largest_monitor_resolution()
    if largest_res:
        FULLSCREEN_WIDTH, FULLSCREEN_HEIGHT = largest_res
        # print(f"[Fullscreen] Monitor (최대): {FULLSCREEN_WIDTH}x{FULLSCREEN_HEIGHT}")
    elif _original_resolution:
        FULLSCREEN_WIDTH, FULLSCREEN_HEIGHT = _original_resolution
        # print(f"[Fullscreen] Monitor (원본): {FULLSCREEN_WIDTH}x{FULLSCREEN_HEIGHT}")
    else:
        monitor_res = _get_current_resolution()
        if monitor_res:
            FULLSCREEN_WIDTH, FULLSCREEN_HEIGHT = monitor_res
            # print(f"[Fullscreen] Monitor: {FULLSCREEN_WIDTH}x{FULLSCREEN_HEIGHT}")
        else:
            FULLSCREEN_WIDTH, FULLSCREEN_HEIGHT = 1920, 1080

_setup_fullscreen_mode()

if _splash_screen:
    update_splash(0.10, "라이브러리 로딩 중...")

