# 2. 외부 라이브러리 Import
# ============================================================
import pygame
import pygame.freetype
from pygame import gfxdraw
import numpy as np

# ============================================================
# 2.1 전역 Surface 캐시 시스템 (성능 최적화)
# ============================================================
# 매 프레임 Surface 생성을 방지하여 FPS 향상
_surface_cache = {}  # 범용 Surface 캐시
_scale_cache = {}    # transform.scale 결과 캐시
_glow_surface_cache = {}  # 글로우 이펙트 Surface 캐시
_predrawn_glow_cache = {}  # 사전 렌더링된 glow 원 캐시 (크기/색상/알파 버킷)
_font_cache = {}  # 폰트 객체 캐시 (매 프레임 SysFont 생성 방지)
_static_text_cache = {}  # 정적 텍스트 Surface 캐시 (변하지 않는 라벨용)
_water_trail_cache = {}  # 물자국 타원 캐시 (크기/알파 버킷)
_pachinko_cache = {}  # 파칭코 UI 캐시 (배경 그라데이션, glow 등)
_overlay_cache = {}  # 전체화면 오버레이 캐시 (알파별로 사전 렌더링)
_boss_hp_gradient_cache = {}  # 보스 HP바 그라데이션 캐시 (색상별 사전 렌더링)
_trail_point_cache = {}  # 에너지 트레일 포인트 캐시 (크기/알파별)
_wall_impact_cache = {}  # 벽 충돌 이펙트 캐시 (크기/알파/색상별)
_gauge_gradient_cache = {}  # 게이지바 그라데이션 캐시 (스테이지/높이별)
_gold_hud_cache = None  # 골드 HUD 캐시
_gold_hud_cached_value = -1  # 캐시된 골드 값
_gold_hud_scaled_cache = {}  # 스케일된 골드 HUD 캐시 (스케일 팩터별)
_CACHE_MAX_SIZE = 500  # 캐시 최대 크기 (메모리 관리)

# Glow 최적화용 버킷 (메모리 절약을 위해 유사한 값들을 그룹화)
_GLOW_SIZE_BUCKETS = (8, 12, 16, 20, 24, 32, 40, 48, 60, 80, 100, 120, 150, 200)
_GLOW_ALPHA_BUCKETS = (32, 64, 96, 128, 160, 192, 224, 255)

# Water trail 알파 버킷 (5단계로 분류)
_WATER_ALPHA_BUCKETS = (20, 40, 60, 80, 100)

def get_cached_surface(width: int, height: int, alpha: bool = True) -> pygame.Surface:
    """캐시된 투명 Surface 반환 (재사용)"""
    key = (width, height, alpha)
    if key not in _surface_cache:
        if alpha:
            _surface_cache[key] = pygame.Surface((width, height), pygame.SRCALPHA)
        else:
            _surface_cache[key] = pygame.Surface((width, height))
    # 기존 내용 클리어
    surface = _surface_cache[key]
    surface.fill((0, 0, 0, 0) if alpha else (0, 0, 0))
    return surface

def get_cached_scale(source: pygame.Surface, width: int, height: int, cache_key: str = None) -> pygame.Surface:
    """transform.scale 결과를 캐시하여 반환"""
    # cache_key가 없으면 source의 id와 크기로 키 생성
    if cache_key is None:
        cache_key = (id(source), width, height)
    else:
        cache_key = (cache_key, width, height)

    if cache_key not in _scale_cache:
        # 캐시 크기 제한
        if len(_scale_cache) > _CACHE_MAX_SIZE:
            # 오래된 항목 일부 제거 (간단한 LRU 대신 절반 삭제)
            keys_to_remove = list(_scale_cache.keys())[:_CACHE_MAX_SIZE // 2]
            for k in keys_to_remove:
                del _scale_cache[k]
        _scale_cache[cache_key] = pygame.transform.scale(source, (width, height))
    return _scale_cache[cache_key]

def get_cached_glow_surface(size: int) -> pygame.Surface:
    """글로우 이펙트용 캐시된 Surface 반환"""
    if size not in _glow_surface_cache:
        if len(_glow_surface_cache) > 100:
            _glow_surface_cache.clear()
        _glow_surface_cache[size] = pygame.Surface((size, size), pygame.SRCALPHA)
    surface = _glow_surface_cache[size]
    surface.fill((0, 0, 0, 0))
    return surface


def _bucket_value(value: int, buckets: tuple) -> int:
    """값을 가장 가까운 버킷으로 매핑"""
    return min(buckets, key=lambda b: abs(b - value))


def get_predrawn_glow_circle(size: int, color: tuple, alpha: int) -> pygame.Surface:
    """사전 렌더링된 glow 원 반환 (크기/색상/알파 버킷팅으로 캐시 효율화)

    매 프레임 draw.circle() 호출 대신 캐시된 Surface 재사용.
    크기와 알파를 버킷팅하여 캐시 히트율 향상.
    """
    # 버킷팅으로 유사한 요청을 동일 캐시 엔트리로 매핑
    size_bucket = _bucket_value(size, _GLOW_SIZE_BUCKETS)
    alpha_bucket = _bucket_value(max(0, min(255, alpha)), _GLOW_ALPHA_BUCKETS)
    color_key = (color[0], color[1], color[2]) if len(color) >= 3 else (255, 255, 255)

    cache_key = (size_bucket, color_key, alpha_bucket)

    if cache_key not in _predrawn_glow_cache:
        # 캐시 크기 제한
        if len(_predrawn_glow_cache) > 800:
            # 절반 삭제 (간단한 eviction)
            keys_to_remove = list(_predrawn_glow_cache.keys())[:400]
            for k in keys_to_remove:
                del _predrawn_glow_cache[k]

        # 새 glow 원 렌더링
        surf = pygame.Surface((size_bucket, size_bucket), pygame.SRCALPHA)
        center = size_bucket // 2
        radius = center
        pygame.draw.circle(surf, (*color_key, alpha_bucket), (center, center), radius)
        _predrawn_glow_cache[cache_key] = surf

    return _predrawn_glow_cache[cache_key]

def get_cached_font(font_name: str, size: int, bold: bool = False, italic: bool = False) -> pygame.font.Font:
    """캐시된 폰트 객체 반환 (매 프레임 SysFont 생성 방지)

    pygame.font.SysFont()는 느린 연산이므로 캐싱 필수.
    """
    cache_key = (font_name, size, bold, italic)
    if cache_key not in _font_cache:
        if len(_font_cache) > 100:
            # 오래된 폰트 일부 제거
            keys_to_remove = list(_font_cache.keys())[:50]
            for k in keys_to_remove:
                del _font_cache[k]
        _font_cache[cache_key] = pygame.font.SysFont(font_name, size, bold=bold, italic=italic)
    return _font_cache[cache_key]


def get_cached_static_text(text: str, font_key: tuple, color: tuple, antialias: bool = True) -> pygame.Surface:
    """정적 텍스트 Surface 캐싱 (변하지 않는 라벨용)

    "HP", "PAUSE", "READY" 등 변하지 않는 텍스트를 매 프레임 렌더링하지 않음.
    font_key = (font_name, size, bold, italic)
    """
    cache_key = (text, font_key, color, antialias)
    if cache_key not in _static_text_cache:
        if len(_static_text_cache) > 300:
            # 오래된 텍스트 일부 제거
            keys_to_remove = list(_static_text_cache.keys())[:150]
            for k in keys_to_remove:
                del _static_text_cache[k]
        font = get_cached_font(*font_key)
        _static_text_cache[cache_key] = font.render(text, antialias, color)
    return _static_text_cache[cache_key]


def clear_surface_caches():
    """모든 Surface 캐시 클리어 (스테이지 전환 시 호출)"""
    global _surface_cache, _scale_cache, _glow_surface_cache, _predrawn_glow_cache, _water_trail_cache
    _surface_cache.clear()
    _scale_cache.clear()
    _glow_surface_cache.clear()
    _predrawn_glow_cache.clear()
    _water_trail_cache.clear()
    # 폰트와 텍스트 캐시는 스테이지 전환 시에도 유지 (재사용 가능)

def get_cached_overlay(width: int, height: int, alpha: int) -> pygame.Surface:
    """전체화면 오버레이 Surface 캐시 (알파값별 사전 렌더링)

    매 프레임 새로운 SRCALPHA Surface 생성을 방지하여 성능 향상.
    동일한 alpha 값의 오버레이는 캐시에서 반환.
    """
    # 알파값 버킷팅 (16단계로 분류하여 캐시 효율화)
    alpha_bucket = (alpha // 16) * 16
    alpha_bucket = max(0, min(255, alpha_bucket))

    key = (width, height, alpha_bucket)
    if key not in _overlay_cache:
        # 캐시 크기 제한
        if len(_overlay_cache) > 32:
            # 오래된 항목 제거
            keys_to_remove = list(_overlay_cache.keys())[:16]
            for k in keys_to_remove:
                del _overlay_cache[k]
        surf = pygame.Surface((width, height), pygame.SRCALPHA)
        surf.fill((0, 0, 0, alpha_bucket))
        _overlay_cache[key] = surf
    return _overlay_cache[key]

def get_boss_hp_gradient(width: int, height: int, health_color: tuple) -> pygame.Surface:
    """보스 HP바 그라데이션 Surface 캐시 (색상별 사전 렌더링)

    매 프레임 height회 draw.line 호출을 1회 blit으로 대체.
    """
    key = (width, height, health_color)
    if key not in _boss_hp_gradient_cache:
        # 캐시 크기 제한
        if len(_boss_hp_gradient_cache) > 10:
            _boss_hp_gradient_cache.clear()
        surf = pygame.Surface((width, height), pygame.SRCALPHA)
        for i in range(height):
            alpha = 1.0 - (i / height) * 0.3
            color = tuple(int(c * alpha) for c in health_color)
            pygame.draw.line(surf, color, (0, i), (width - 1, i))
        _boss_hp_gradient_cache[key] = surf
    return _boss_hp_gradient_cache[key]

def get_gauge_gradient(gauge_id: str, width: int, height: int, color_func) -> pygame.Surface:
    """게이지바 그라데이션 Surface 캐시 (스테이지/높이별 사전 렌더링)

    최대 100회 draw.line 호출을 1회 blit으로 대체.
    color_func: (row_index, total_height) -> (r, g, b) 색상 반환 함수
    """
    key = (gauge_id, width, height)
    if key not in _gauge_gradient_cache:
        if len(_gauge_gradient_cache) > 20:
            _gauge_gradient_cache.clear()
        surf = pygame.Surface((width, height), pygame.SRCALPHA)
        for i in range(height):
            color = color_func(i, height)
            pygame.draw.line(surf, color, (0, i), (width - 1, i))
        _gauge_gradient_cache[key] = surf
    return _gauge_gradient_cache[key]

def get_wall_impact_surface(size: int, color: tuple, alpha: int) -> pygame.Surface:
    """벽 충돌 파티클 Surface 캐시 (크기/색상/알파별 사전 렌더링)"""
    # 크기 버킷팅 (2픽셀 단위)
    size_bucket = max(1, (size // 2) * 2)
    # 알파 버킷팅 (20 단위)
    alpha_bucket = max(0, min(255, (alpha // 20) * 20))
    # 색상 버킷팅 (32 단위로 양자화)
    color_bucket = tuple((c // 32) * 32 for c in color[:3])

    key = (size_bucket, color_bucket, alpha_bucket)
    if key not in _wall_impact_cache:
        if len(_wall_impact_cache) > 60:
            _wall_impact_cache.clear()
        surf_size = size_bucket * 2 + 2
        surf = pygame.Surface((surf_size, surf_size), pygame.SRCALPHA)
        pygame.draw.circle(surf, (*color_bucket, alpha_bucket), (size_bucket + 1, size_bucket + 1), size_bucket)
        _wall_impact_cache[key] = surf
    return _wall_impact_cache[key]

def get_trail_point_surface(size: int, glow_alpha: int, inner_alpha: int,
                            glow_color: tuple, base_color: tuple) -> pygame.Surface:
    """에너지 트레일 포인트 Surface 캐시 (크기/알파별 사전 렌더링)

    각 트레일 포인트마다 Surface 생성 방지.
    """
    # 크기 버킷팅 (2픽셀 단위)
    size_bucket = max(2, (size // 2) * 2)
    # 알파 버킷팅 (8 단위)
    glow_bucket = (glow_alpha // 8) * 8
    inner_bucket = (inner_alpha // 8) * 8

    key = (size_bucket, glow_bucket, inner_bucket)
    if key not in _trail_point_cache:
        if len(_trail_point_cache) > 80:
            _trail_point_cache.clear()
        trail_size = size_bucket * 2 + 4
        surf = pygame.Surface((trail_size, trail_size), pygame.SRCALPHA)
        center = trail_size // 2
        # 외부 글로우
        if glow_bucket > 0:
            pygame.draw.circle(surf, (*glow_color[:3], glow_bucket), (center, center), size_bucket + 1)
        # 내부 에너지
        if inner_bucket > 0:
            pygame.draw.circle(surf, (*base_color[:3], inner_bucket), (center, center), max(1, size_bucket - 1))
        _trail_point_cache[key] = surf
    return _trail_point_cache[key]

# 눈물 이미지 스케일 캐시 (다이얼로그용)
_tear_scale_cache = {}

def get_cached_tear_scale(tear_img: pygame.Surface, size: int) -> pygame.Surface:
    """눈물 이미지 스케일 캐시"""
    if size not in _tear_scale_cache:
        if len(_tear_scale_cache) > 50:
            _tear_scale_cache.clear()
        _tear_scale_cache[size] = pygame.transform.scale(tear_img, (size, size))
    return _tear_scale_cache[size]

# 다이얼로그 배경 캐시
_dialog_bg_cache = {}

def get_cached_dialog_bg(width: int, height: int, alpha: int = 180) -> pygame.Surface:
    """다이얼로그 배경 Surface 캐시"""
    key = (width, height, alpha)
    if key not in _dialog_bg_cache:
        surf = pygame.Surface((width, height), pygame.SRCALPHA)
        surf.fill((0, 0, 0, alpha))
        _dialog_bg_cache[key] = surf
    return _dialog_bg_cache[key]

# 혈액 파티클 Surface 캐시 (크기별)
_blood_particle_cache = {}

def get_cached_blood_surface(size: int) -> pygame.Surface:
    """혈액 파티클용 캐시된 Surface"""
    size = max(1, int(size))
    if size not in _blood_particle_cache:
        if len(_blood_particle_cache) > 50:
            _blood_particle_cache.clear()
        _blood_particle_cache[size] = pygame.Surface((size * 2, size * 2), pygame.SRCALPHA)
    surface = _blood_particle_cache[size]
    surface.fill((0, 0, 0, 0))
    return surface

# 화면 크기 플래시 Surface 캐시
_flash_surface_cache = {}

def get_cached_flash_surface(width: int, height: int) -> pygame.Surface:
    """전체 화면 플래시 효과용 캐시된 Surface"""
    key = (width, height)
    if key not in _flash_surface_cache:
        _flash_surface_cache[key] = pygame.Surface((width, height), pygame.SRCALPHA)
    surface = _flash_surface_cache[key]
    surface.fill((0, 0, 0, 0))
    return surface

# ============================================================
# 패들 스케일링 캐시 (프레임 드랍 방지)
# ============================================================
_paddle_scale_cache = {}
_paddle_rotate_cache = {}
_PADDLE_CACHE_MAX_SIZE = 100

def get_scaled_paddle(base_img: pygame.Surface, scale_ratio: float, char_type: str = "") -> pygame.Surface:
    """스케일 비율에 따라 캐시된 패들 이미지 반환 (프레임 드랍 방지)"""
    # 스케일을 0.01 단위로 양자화 (캐시 효율성)
    quantized_scale = round(scale_ratio, 2)

    # 캐시 키: 원본 이미지 id + 양자화된 스케일 + 캐릭터 타입
    cache_key = (id(base_img), quantized_scale, char_type)

    if cache_key not in _paddle_scale_cache:
        # 캐시 크기 제한
        if len(_paddle_scale_cache) > _PADDLE_CACHE_MAX_SIZE:
            # 오래된 항목 절반 제거
            keys_to_remove = list(_paddle_scale_cache.keys())[:_PADDLE_CACHE_MAX_SIZE // 2]
            for k in keys_to_remove:
                del _paddle_scale_cache[k]

        new_width = max(1, int(base_img.get_width() * quantized_scale))
        new_height = max(1, int(base_img.get_height() * quantized_scale))
        _paddle_scale_cache[cache_key] = pygame.transform.scale(base_img, (new_width, new_height))

    return _paddle_scale_cache[cache_key]

def get_rotated_paddle(base_img: pygame.Surface, angle: float, char_type: str = "") -> pygame.Surface:
    """회전 각도에 따라 캐시된 패들 이미지 반환 (프레임 드랍 방지)"""
    # 각도를 1도 단위로 양자화
    quantized_angle = round(angle)

    cache_key = (id(base_img), quantized_angle, char_type)

    if cache_key not in _paddle_rotate_cache:
        if len(_paddle_rotate_cache) > _PADDLE_CACHE_MAX_SIZE:
            keys_to_remove = list(_paddle_rotate_cache.keys())[:_PADDLE_CACHE_MAX_SIZE // 2]
            for k in keys_to_remove:
                del _paddle_rotate_cache[k]

        _paddle_rotate_cache[cache_key] = pygame.transform.rotate(base_img, quantized_angle)

    return _paddle_rotate_cache[cache_key].copy()

def clear_paddle_cache():
    """패들 캐시 클리어 (캐릭터 변경 시 호출)"""
    global _paddle_scale_cache, _paddle_rotate_cache
    _paddle_scale_cache.clear()
    _paddle_rotate_cache.clear()

# ============================================================
# 게임 프리로딩 & 최적화 시스템
# ============================================================
_preload_complete = False
_preloaded_surfaces = {}  # 자주 사용되는 크기의 Surface 미리 생성
_preloaded_fonts = {}     # 자주 사용되는 폰트 미리 로드

def preload_common_surfaces():
    """자주 사용되는 크기의 Surface를 미리 생성하여 캐시 워밍업"""
    global _preloaded_surfaces

    # 게임에서 자주 사용되는 Surface 크기들
    common_sizes = [
        # 화면 관련
        (760, 750),   # INTERNAL_WIDTH x INTERNAL_HEIGHT
        (600, 750),   # GAME_PLAY_WIDTH x GAME_PLAY_HEIGHT
        (80, 750),    # 필러 크기
        # UI 관련
        (400, 300),   # 다이얼로그
        (300, 200),   # 작은 다이얼로그
        (200, 150),   # 알림창
        (100, 100),   # 아이콘 영역
        (64, 64),     # 큰 아이콘
        (48, 48),     # 중간 아이콘
        (32, 32),     # 기본 아이콘
        (24, 24),     # 작은 아이콘
        (16, 16),     # 미니 아이콘
        # 이펙트 관련
        (128, 128),   # 글로우 이펙트
        (96, 96),     # 파티클 이펙트
        (256, 256),   # 대형 이펙트
        (512, 512),   # 초대형 이펙트
    ]

    # print("[PRELOAD] Surface 캐시 워밍업 시작...", flush=True)
    for width, height in common_sizes:
        # 투명 Surface
        key_alpha = (width, height, True)
        if key_alpha not in _surface_cache:
            _surface_cache[key_alpha] = pygame.Surface((width, height), pygame.SRCALPHA)
        # 불투명 Surface
        key_opaque = (width, height, False)
        if key_opaque not in _surface_cache:
            _surface_cache[key_opaque] = pygame.Surface((width, height))

    # 글로우 Surface 프리로드
    glow_sizes = [8, 12, 16, 20, 24, 32, 48, 64, 96, 128]
    for size in glow_sizes:
        if size not in _glow_surface_cache:
            _glow_surface_cache[size] = pygame.Surface((size, size), pygame.SRCALPHA)

    # 다이얼로그 배경 프리로드
    dialog_sizes = [(400, 300, 180), (500, 350, 180), (600, 400, 200), (300, 200, 180)]
    for width, height, alpha in dialog_sizes:
        key = (width, height, alpha)
        if key not in _dialog_bg_cache:
            surf = pygame.Surface((width, height), pygame.SRCALPHA)
            surf.fill((0, 0, 0, alpha))
            _dialog_bg_cache[key] = surf

    # 플래시 Surface 프리로드
    flash_sizes = [(760, 750), (600, 750), (800, 600)]
    for width, height in flash_sizes:
        key = (width, height)
        if key not in _flash_surface_cache:
            _flash_surface_cache[key] = pygame.Surface((width, height), pygame.SRCALPHA)

    # print(f"[PRELOAD] Surface 캐시 워밍업 완료: {len(_surface_cache)} surfaces, {len(_glow_surface_cache)} glow, {len(_dialog_bg_cache)} dialog", flush=True)

def preload_fonts():
    """자주 사용되는 폰트를 미리 로드"""
    global _preloaded_fonts

    # print("[PRELOAD] 폰트 프리로드 시작...", flush=True)

    # 시스템 기본 폰트 프리로드 (크기별)
    font_sizes = [12, 14, 16, 18, 20, 22, 24, 28, 32, 36, 48]
    for size in font_sizes:
        try:
            key = ("default", size)
            if key not in _preloaded_fonts:
                _preloaded_fonts[key] = pygame.font.Font(None, size)
        except Exception as e:
            print(f"[PRELOAD] 폰트 로드 실패 (size={size}): {e}", flush=True)

    # 한글 폰트 프리로드 (NanumSquare)
    try:
        korean_font_paths = [
            os.path.join("fonts", "NanumSquareB.ttf"),
            os.path.join("fonts", "NanumSquareR.ttf"),
        ]
        for font_rel_path in korean_font_paths:
            font_path = resource_path(font_rel_path)
            if os.path.exists(font_path):
                for size in [16, 18, 20, 24, 28, 32]:
                    key = (font_rel_path, size)
                    if key not in _preloaded_fonts:
                        _preloaded_fonts[key] = pygame.font.Font(font_path, size)
    except Exception as e:
        print(f"[PRELOAD] 한글 폰트 로드 실패: {e}", flush=True)

    # print(f"[PRELOAD] 폰트 프리로드 완료: {len(_preloaded_fonts)} fonts", flush=True)

def preload_particle_surfaces():
    """파티클 이펙트용 Surface 미리 생성"""
    # print("[PRELOAD] 파티클 Surface 프리로드 시작...", flush=True)

    # 혈액 파티클 크기들
    blood_sizes = [2, 3, 4, 5, 6, 8, 10, 12]
    for size in blood_sizes:
        if size not in _blood_particle_cache:
            _blood_particle_cache[size] = pygame.Surface((size * 2, size * 2), pygame.SRCALPHA)

    # 눈물 파티클 크기들
    tear_sizes = [4, 6, 8, 10, 12, 16]
    # _tear_scale_cache는 실제 이미지 필요하므로 여기서는 스킵

    # print(f"[PRELOAD] 파티클 Surface 프리로드 완료: {len(_blood_particle_cache)} blood surfaces", flush=True)

def preload_game_images():
    """자주 사용되는 게임 이미지를 미리 로드하고 convert()"""
    # print("[PRELOAD] 게임 이미지 프리로드 시작...", flush=True)

    preloaded_count = 0

    # 스테이지 인트로 이미지 프리로드
    stage_images = [
        "stage1.png", "stage2.png", "stage3.png", "stage4.png",
        "stage5.png", "stage6.png", "stage7.png", "stage8.png"
    ]
    for img_name in stage_images:
        try:
            img_path = resource_path(img_name)
            if os.path.exists(img_path):
                # 이미지 로드 및 최적화 (convert_alpha)
                img = pygame.image.load(img_path)
                if img.get_alpha() is not None:
                    img.convert_alpha()
                else:
                    img.convert()
                preloaded_count += 1
        except Exception as e:
            pass  # 이미지가 없어도 게임 진행에 문제없음

    # print(f"[PRELOAD] 게임 이미지 프리로드 완료: {preloaded_count} images", flush=True)

def run_garbage_collection():
    """가비지 컬렉션 실행으로 메모리 정리"""
    import gc
    # print("[PRELOAD] 가비지 컬렉션 실행 중...", flush=True)

    # 가비지 컬렉션 실행
    gc.collect()

    # 가비지 컬렉션 임계값 최적화 (게임용)
    # 기본값 (700, 10, 10)에서 게임에 맞게 조정
    gc.set_threshold(1000, 15, 15)  # 더 느슨하게 설정하여 GC 빈도 감소

    # print("[PRELOAD] 가비지 컬렉션 완료", flush=True)

def preload_all_optimizations():
    """모든 최적화 작업을 한 번에 실행"""
    global _preload_complete

    if _preload_complete:
        # print("[PRELOAD] 이미 최적화 완료됨, 스킵", flush=True)
        return

    # print("=" * 50, flush=True)
    # print("[PRELOAD] 게임 최적화 시작", flush=True)
    # print("=" * 50, flush=True)

    # 1. Surface 캐시 워밍업
    preload_common_surfaces()

    # 2. 폰트 프리로드
    preload_fonts()

    # 3. 파티클 Surface 프리로드
    preload_particle_surfaces()

    # 4. 게임 이미지 프리로드
    preload_game_images()

    # 5. 가비지 컬렉션 최적화
    run_garbage_collection()

    _preload_complete = True
    # print("=" * 50, flush=True)
    # print("[PRELOAD] 게임 최적화 완료!", flush=True)
    # print("=" * 50, flush=True)

