# ---------------- 로딩 화면 상태 ----------------
_loading_progress = 0.0  # 목표 진행률 (백그라운드 스레드에서 설정)
_loading_display_progress = 0.0  # 표시 진행률 (부드럽게 보간)
_loading_start_time = None
_loading_menu_background: SimpleMenuBackground | None = None
_loading_star_field: StarField | None = None
_loading_neon_particles: list[dict] = []
_loading_scan_lines: list[dict] = []
_loading_last_frame_time: float | None = None
_loading_animation_time = 0.0
_loading_blazing_sun: BlazingSunFrame | None = None  # 불타는 태양 필러
_loading_progress_bar_cache: pygame.Surface | None = None  # 프로그레스 바 그라데이션 캐시
_loading_progress_bar_width: int = 0  # 캐시된 바 너비
_loading_message = ""  # 현재 로딩 메시지
_loading_complete = False  # 로딩 완료 플래그
_loading_lock = None  # 스레드 동기화용 락
_LOADING_SMOOTH_SPEED = 0.8  # 진행률 보간 속도 (초당) - 낮을수록 부드럽게


def _update_loading_progress(progress: float, message: str = "") -> None:
    """로딩 진행률 업데이트 (백그라운드 스레드에서 호출)"""
    global _loading_progress, _loading_message
    if _loading_lock:
        with _loading_lock:
            _loading_progress = progress
            if message:
                _loading_message = message
    else:
        _loading_progress = progress
        if message:
            _loading_message = message


def _draw_loading_frame() -> None:
    """로딩 화면 한 프레임 그리기 (메인 스레드에서 호출)"""
    global _loading_last_frame_time, _loading_animation_time
    global _loading_star_field, _loading_neon_particles, _loading_scan_lines
    global _loading_blazing_sun, _loading_menu_background
    global _loading_display_progress

    try:
        if not pygame.display.get_init():
            return

        from font_config import load_font

        pygame.event.pump()
        now = time.time()
        prev_time = _loading_last_frame_time
        _loading_last_frame_time = now
        dt = 0.0 if prev_time is None else now - prev_time
        _loading_animation_time += dt

        # 목표 진행률 가져오기
        if _loading_lock:
            with _loading_lock:
                target_progress = _loading_progress
                message = _loading_message
        else:
            target_progress = _loading_progress
            message = _loading_message

        # 부드러운 진행률 보간 (lerp)
        if _loading_display_progress < target_progress:
            _loading_display_progress += _LOADING_SMOOTH_SPEED * dt
            if _loading_display_progress > target_progress:
                _loading_display_progress = target_progress

        # 실제 표시에 사용할 진행률
        progress = _loading_display_progress

        pulse = (math.sin(now * 3) + 1) / 2

        bar_width = min(500, int(WIDTH * 0.55))
        bar_height = 8
        bar_x = (WIDTH - bar_width) // 2
        bar_y = HEIGHT // 2 + 80

        # 불타는 태양 애니메이션
        if _loading_blazing_sun is not None:
            _loading_blazing_sun.set_intensity(progress)
            _loading_blazing_sun.update(dt)
            _loading_blazing_sun.draw(SCREEN, clear_game_area=False, draw_artwork=True, artwork_opacity=0.35)

        # 배경
        if _loading_menu_background is not None:
            _loading_menu_background.update(dt)
            menu_surf = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
            _loading_menu_background.draw(menu_surf)
            bg_alpha = int(50 + progress * 180)
            menu_surf.set_alpha(bg_alpha)
            SCREEN.blit(menu_surf, (0, 0))

        # 별 필드
        star_alpha = int(30 + progress * 200)
        star_surf = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
        _loading_star_field = draw_star_field(
            star_surf, WIDTH, HEIGHT, _loading_animation_time, _loading_star_field
        )
        star_surf.set_alpha(star_alpha)
        SCREEN.blit(star_surf, (0, 0))

        if ENABLE_NEON_PARTICLES:
            _loading_neon_particles = draw_neon_particles(
                SCREEN, WIDTH, HEIGHT, _loading_animation_time, _loading_neon_particles
            )

        # 폰트 로드
        title_font = load_font(48, "bold")
        font = load_font(28, "regular")
        sub_font = load_font(18, "regular")
        small_font = load_font(14, "regular")

        # 게임 타이틀
        title_text = "PING FIGHTER"
        title_surface = title_font.render(title_text, True, (255, 255, 255))
        title_x = (WIDTH - title_surface.get_width()) // 2
        title_y = HEIGHT // 2 - 80

        glow_intensity = int(100 + pulse * 80)
        glow_color = (glow_intensity, glow_intensity // 2, 0)
        for offset in [(2, 2), (-2, -2), (2, -2), (-2, 2)]:
            glow_surf = title_font.render(title_text, True, glow_color)
            glow_surf.set_alpha(60)
            SCREEN.blit(glow_surf, (title_x + offset[0], title_y + offset[1]))
        SCREEN.blit(title_surface, (title_x, title_y))

        # 로딩 메시지
        if message:
            msg_surface = font.render(message, True, (200, 200, 200))
            msg_x = (WIDTH - msg_surface.get_width()) // 2
            msg_y = HEIGHT // 2 + 20
            SCREEN.blit(msg_surface, (msg_x, msg_y))

        # 프로그레스 바 배경
        pygame.draw.rect(SCREEN, (30, 30, 40), (bar_x - 2, bar_y - 2, bar_width + 4, bar_height + 4), border_radius=4)
        pygame.draw.rect(SCREEN, (20, 20, 30), (bar_x, bar_y, bar_width, bar_height), border_radius=3)

        # 프로그레스 바 진행
        fill_width = int(bar_width * progress)
        if fill_width > 0:
            global _loading_progress_bar_cache, _loading_progress_bar_width
            if _loading_progress_bar_cache is None or _loading_progress_bar_width != bar_width:
                _loading_progress_bar_cache = pygame.Surface((bar_width, bar_height - 2), pygame.SRCALPHA)
                _loading_progress_bar_width = bar_width
                for x in range(bar_width):
                    t = x / bar_width
                    r = int(255 * (1 - t) + 100 * t)
                    g = int(100 * (1 - t) + 200 * t)
                    b = int(50 * (1 - t) + 255 * t)
                    pygame.draw.line(_loading_progress_bar_cache, (r, g, b), (x, 0), (x, bar_height - 2))
            SCREEN.blit(_loading_progress_bar_cache, (bar_x, bar_y + 1), (0, 0, fill_width, bar_height - 2))

        # 퍼센트 표시
        percent_text = f"{int(progress * 100)}%"
        percent_surface = sub_font.render(percent_text, True, (150, 200, 255))
        percent_x = (WIDTH - percent_surface.get_width()) // 2
        percent_y = bar_y + bar_height + 15
        SCREEN.blit(percent_surface, (percent_x, percent_y))

        # 모서리 장식
        corner_len = 30
        corner_thickness = 2
        pygame.draw.line(SCREEN, (0, 200, 255), (20, 20), (20 + corner_len, 20), corner_thickness)
        pygame.draw.line(SCREEN, (0, 200, 255), (20, 20), (20, 20 + corner_len), corner_thickness)
        pygame.draw.line(SCREEN, (0, 200, 255), (WIDTH - 20, 20), (WIDTH - 20 - corner_len, 20), corner_thickness)
        pygame.draw.line(SCREEN, (0, 200, 255), (WIDTH - 20, 20), (WIDTH - 20, 20 + corner_len), corner_thickness)
        pygame.draw.line(SCREEN, (0, 200, 255), (20, HEIGHT - 20), (20 + corner_len, HEIGHT - 20), corner_thickness)
        pygame.draw.line(SCREEN, (0, 200, 255), (20, HEIGHT - 20), (20, HEIGHT - 20 - corner_len), corner_thickness)
        pygame.draw.line(SCREEN, (0, 200, 255), (WIDTH - 20, HEIGHT - 20), (WIDTH - 20 - corner_len, HEIGHT - 20), corner_thickness)
        pygame.draw.line(SCREEN, (0, 200, 255), (WIDTH - 20, HEIGHT - 20), (WIDTH - 20, HEIGHT - 20 - corner_len), corner_thickness)

        # 버전 정보
        version_surface = small_font.render("v1.0 // PING FIGHTER", True, (60, 80, 100))
        SCREEN.blit(version_surface, (30, HEIGHT - 35))

        pygame.display.flip()

    except Exception as e:
        # 인코딩 오류는 무시 (콘솔 출력 문제일 뿐 렌더링은 정상)
        if "codec can't encode" not in str(e):
            print(f"[로딩 화면 그리기 오류] {e}", flush=True)


def run_loading_with_tasks(tasks: list) -> None:
    """
    백그라운드에서 작업을 실행하면서 로딩 화면 표시

    tasks: [(weight, message, callable), ...] 형태의 리스트
           weight: 이 작업의 진행률 비중 (0.0 ~ 1.0, 합계 1.0)
           message: 로딩 중 표시할 메시지
           callable: 실행할 함수
    """
    global _loading_progress, _loading_message, _loading_complete, _loading_lock
    global _loading_menu_background, _loading_star_field, _loading_blazing_sun
    global _loading_last_frame_time, _loading_animation_time
    global _loading_display_progress

    import threading

    if not pygame.display.get_init():
        # pygame 미초기화 시 그냥 작업만 실행
        for _, _, task in tasks:
            task()
        return

    # 로딩 화면 초기화
    _loading_progress = 0.0
    _loading_display_progress = 0.0  # 표시 진행률도 초기화
    _loading_message = ""
    _loading_complete = False
    _loading_lock = threading.Lock()
    _loading_last_frame_time = None
    _loading_animation_time = 0.0

    # 배경 초기화
    if _loading_menu_background is None:
        _loading_menu_background = SimpleMenuBackground(WIDTH, HEIGHT)
        _loading_blazing_sun = BlazingSunFrame(WIDTH, HEIGHT, 0, 0)

    # 백그라운드 스레드에서 작업 실행
    def background_worker():
        global _loading_complete
        MIN_TASK_DISPLAY_TIME = 0.8  # 각 작업 메시지 최소 표시 시간 (초)
        try:
            cumulative_progress = 0.0
            for weight, message, task in tasks:
                task_start = time.time()
                _update_loading_progress(cumulative_progress, message)
                print(f"[로딩] {message} 시작 ({int(cumulative_progress * 100)}%)", flush=True)
                try:
                    task()
                except Exception as e:
                    print(f"[로딩 작업 오류] {message}: {e}", flush=True)
                # 최소 표시 시간 보장
                elapsed = time.time() - task_start
                if elapsed < MIN_TASK_DISPLAY_TIME:
                    time.sleep(MIN_TASK_DISPLAY_TIME - elapsed)
                cumulative_progress += weight
                _update_loading_progress(min(cumulative_progress, 1.0))
                print(f"[로딩] {message} 완료 ({int(min(cumulative_progress, 1.0) * 100)}%)", flush=True)
            # 마지막 메시지 유지하면서 100% 설정
            _update_loading_progress(1.0)
        finally:
            with _loading_lock:
                _loading_complete = True

    worker_thread = threading.Thread(target=background_worker, daemon=True)
    worker_thread.start()

    # 메인 스레드에서 로딩 화면 표시
    while True:
        _draw_loading_frame()

        with _loading_lock:
            if _loading_complete:
                break

        time.sleep(1 / 60)  # 60 FPS

    # 완료 후 표시 진행률이 100%에 도달할 때까지 계속 그리기 (마지막 메시지 유지)
    _update_loading_progress(1.0)
    while _loading_display_progress < 0.99:
        _draw_loading_frame()
        time.sleep(1 / 60)

    # 100% 도달 후 잠시 유지
    _loading_display_progress = 1.0
    for _ in range(20):  # 약 0.33초
        _draw_loading_frame()
        time.sleep(1 / 60)

    _loading_lock = None
    print("[로딩] 모든 작업 완료", flush=True)


def show_loading_screen(message: str, target_progress: float | None = None) -> None:
    """초기 로딩 구간에서 인트로와 동일한 배경을 사용하는 로딩 화면을 그린다."""
    global _loading_progress, _loading_start_time
    global _loading_menu_background, _loading_star_field, _loading_neon_particles
    global _loading_scan_lines, _loading_last_frame_time, _loading_animation_time
    global _loading_blazing_sun
    # print(f"[show_loading_screen] 호출됨: '{message}', target={target_progress}, 현재progress={_loading_progress}", flush=True)
    try:
        if not pygame.display.get_init():
            # print(f"[show_loading_screen] pygame.display 미초기화 - 스킵", flush=True)
            return

        if _loading_start_time is None:
            _loading_start_time = time.time()
        if (
            _loading_menu_background is None
            or _loading_menu_background.width != WIDTH
            or _loading_menu_background.height != HEIGHT
        ):
            _loading_menu_background = SimpleMenuBackground(WIDTH, HEIGHT)
            _loading_star_field = None
            _loading_neon_particles = []
            _loading_scan_lines = []
            _loading_animation_time = 0.0
            # 불타는 태양 애니메이션 초기화 (전체 화면에 적용)
            # 게임 영역을 0으로 설정하여 화면 전체가 태양 효과로 채워짐
            _loading_blazing_sun = BlazingSunFrame(WIDTH, HEIGHT, 0, 0)
        _loading_last_frame_time = None

        # font_config의 픽셀 폰트 사용
        from font_config import load_font

        target = 0.99 if target_progress is None else max(_loading_progress, min(1.0, target_progress))
        anim_duration = 1.5  # 각 단계별 최소 표시 시간 (1.5초)
        start_anim = time.time()

        # 폰트 설정 (픽셀 폰트 적용)
        title_font = load_font(48, "bold")
        font = load_font(28, "regular")
        sub_font = load_font(18, "regular")
        small_font = load_font(14, "regular")

        def draw_frame(progress: float) -> None:
            global _loading_last_frame_time, _loading_animation_time
            global _loading_star_field, _loading_neon_particles, _loading_scan_lines
            global _loading_blazing_sun

            pygame.event.pump()
            now = time.time()
            prev_time = _loading_last_frame_time
            _loading_last_frame_time = now
            dt = 0.0 if prev_time is None else now - prev_time
            _loading_animation_time += dt

            phase = (now * 0.8) % 1.0
            pulse = (math.sin(now * 3) + 1) / 2  # 0~1 펄스

            bar_width = min(500, int(WIDTH * 0.55))
            bar_height = 8
            bar_x = (WIDTH - bar_width) // 2
            bar_y = HEIGHT // 2 + 80

            # === 불타는 태양 애니메이션 업데이트 및 렌더링 ===
            # 로딩 화면 전체에 불타오르는 태양 애니메이션 적용
            # 로딩 진행률에 따라 태양이 점점 더 강렬하게 이글거림
            if _loading_blazing_sun is not None:
                _loading_blazing_sun.set_intensity(progress)
                _loading_blazing_sun.update(dt)
                # 태양 애니메이션을 전체 화면에 그리기 (아트워크 살짝 보이게)
                _loading_blazing_sun.draw(SCREEN, clear_game_area=False, draw_artwork=True, artwork_opacity=0.35)

            # === 배경: 진행률에 따라 점점 밝아지는 효과 ===
            # 처음엔 어둡다가 로딩이 진행될수록 배경이 보임
            if _loading_menu_background is not None:
                _loading_menu_background.update(dt)
                # 전체 화면에 메뉴 배경 그리기
                menu_surf = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
                _loading_menu_background.draw(menu_surf)
                # 진행률에 따라 알파값 조절 (0% -> 거의 안보임, 100% -> 완전히 보임)
                bg_alpha = int(50 + progress * 180)  # 50 ~ 230
                menu_surf.set_alpha(bg_alpha)
                SCREEN.blit(menu_surf, (0, 0))

            # 별 필드도 진행률에 따라 점점 밝아짐
            star_alpha = int(30 + progress * 200)  # 30 ~ 230
            star_surf = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
            _loading_star_field = draw_star_field(
                star_surf, WIDTH, HEIGHT, _loading_animation_time, _loading_star_field
            )
            star_surf.set_alpha(star_alpha)
            SCREEN.blit(star_surf, (0, 0))
            if ENABLE_NEON_PARTICLES:
                _loading_neon_particles = draw_neon_particles(
                    SCREEN,
                    WIDTH,
                    HEIGHT,
                    _loading_animation_time,
                    _loading_neon_particles,
                )
            elif _loading_neon_particles:
                _loading_neon_particles.clear()

            if ENABLE_SCAN_LINES:
                _loading_scan_lines = draw_scan_lines(
                    SCREEN, WIDTH, HEIGHT, _loading_scan_lines
                )
            elif _loading_scan_lines:
                _loading_scan_lines.clear()

            # 캐시된 오버레이 사용 (매 프레임 생성 방지)
            dim_overlay = get_cached_overlay(WIDTH, HEIGHT, 25)
            SCREEN.blit(dim_overlay, (0, 0))

            # === 로고/타이틀 영역 ===
            # 글로우 효과가 있는 타이틀
            title_text = "PING FIGHTER"
            glow_colors = [(255, 0, 150), (0, 255, 255), (255, 255, 255)]

            # 타이틀 글로우 레이어
            for i, color in enumerate(glow_colors[:2]):
                glow_surface = title_font.render(title_text, True, color)
                glow_rect = glow_surface.get_rect(center=(WIDTH // 2, HEIGHT // 3 - 20))
                glow_alpha = pygame.Surface(glow_surface.get_size(), pygame.SRCALPHA)
                glow_alpha.blit(glow_surface, (0, 0))
                glow_alpha.set_alpha(int(30 + pulse * 20))
                for offset in [(2, 2), (-2, -2), (2, -2), (-2, 2)]:
                    SCREEN.blit(glow_alpha, (glow_rect.x + offset[0], glow_rect.y + offset[1]))

            # 메인 타이틀
            title_color = (255, 255, 255)
            title_surface = title_font.render(title_text, True, title_color)
            title_rect = title_surface.get_rect(center=(WIDTH // 2, HEIGHT // 3 - 20))
            SCREEN.blit(title_surface, title_rect)

            # 서브타이틀 라인
            line_y = HEIGHT // 3 + 15
            line_width = 200
            line_center = WIDTH // 2
            # 그라데이션 라인 효과
            for i in range(line_width // 2):
                alpha = int(255 * (1 - i / (line_width // 2)))
                pygame.draw.line(SCREEN, (0, 255, 255, alpha),
                               (line_center - i, line_y), (line_center - i, line_y), 2)
                pygame.draw.line(SCREEN, (255, 0, 150, alpha),
                               (line_center + i, line_y), (line_center + i, line_y), 2)

            # === 로딩 상태 영역 ===
            # 현재 작업 메시지 (깜빡이는 효과)
            msg_alpha = int(180 + 75 * math.sin(now * 4))
            msg_surface = font.render(message, True, (200, 220, 255))
            msg_rect = msg_surface.get_rect(center=(WIDTH // 2, bar_y - 50))
            SCREEN.blit(msg_surface, msg_rect)

            # === 프로그레스 바 ===
            # 외곽 프레임 (네온 글로우)
            frame_rect = pygame.Rect(bar_x - 4, bar_y - 4, bar_width + 8, bar_height + 8)
            pygame.draw.rect(SCREEN, (0, 80, 100), frame_rect, border_radius=4)
            pygame.draw.rect(SCREEN, (0, 200, 255, 100), frame_rect, 2, border_radius=4)

            # 배경 바
            bg_rect = pygame.Rect(bar_x, bar_y, bar_width, bar_height)
            pygame.draw.rect(SCREEN, (20, 30, 50), bg_rect, border_radius=3)

            # 진행 바 (그라데이션 효과) - 캐시 사용으로 성능 향상
            fill_width = int(bar_width * max(0.0, min(1.0, progress)))
            if fill_width > 0:
                global _loading_progress_bar_cache, _loading_progress_bar_width

                # 그라데이션 바 캐시 생성 (한 번만)
                if _loading_progress_bar_cache is None or _loading_progress_bar_width != bar_width:
                    _loading_progress_bar_cache = pygame.Surface((bar_width, bar_height - 2), pygame.SRCALPHA)
                    _loading_progress_bar_width = bar_width
                    # 그라데이션 색상 (시안 -> 마젠타) 미리 렌더링
                    for x in range(bar_width):
                        ratio = x / max(1, bar_width)
                        r = int(0 + ratio * 255)
                        g = int(255 - ratio * 100)
                        b = int(255 - ratio * 55)
                        pygame.draw.line(_loading_progress_bar_cache, (r, g, b),
                                       (x, 0), (x, bar_height - 2))

                # 캐시된 그라데이션에서 필요한 부분만 blit
                SCREEN.blit(_loading_progress_bar_cache, (bar_x, bar_y + 1),
                           (0, 0, fill_width, bar_height - 2))

                # 상단 하이라이트
                highlight_surf = pygame.Surface((fill_width, bar_height // 3), pygame.SRCALPHA)
                highlight_surf.fill((255, 255, 255, 60))
                SCREEN.blit(highlight_surf, (bar_x, bar_y))

                # 스캔라인 효과
                scan_x = bar_x + int((bar_width * 1.2) * phase) - int(bar_width * 0.1)
                if bar_x <= scan_x <= bar_x + fill_width:
                    scan_surf = pygame.Surface((40, bar_height), pygame.SRCALPHA)
                    for sx in range(40):
                        alpha = int(150 * (1 - abs(sx - 20) / 20))
                        pygame.draw.line(scan_surf, (255, 255, 255, alpha), (sx, 0), (sx, bar_height))
                    SCREEN.blit(scan_surf, (scan_x - 20, bar_y))

            # === 퍼센트 표시 ===
            percent_value = int(progress * 100)
            percent_text = f"{percent_value:02d}%"

            # 디지털 스타일 퍼센트
            percent_surface = font.render(percent_text, True, (0, 255, 255))
            percent_rect = percent_surface.get_rect(center=(WIDTH // 2, bar_y + 35))

            # 글로우 효과
            glow_surf = font.render(percent_text, True, (0, 150, 200))
            glow_surf.set_alpha(int(100 + pulse * 50))
            SCREEN.blit(glow_surf, (percent_rect.x + 2, percent_rect.y + 2))
            SCREEN.blit(percent_surface, percent_rect)

            # === 하단 정보 ===
            # 힌트 텍스트
            hint_text = "SYSTEM INITIALIZING..."
            hint_surface = small_font.render(hint_text, True, (100, 120, 150))
            hint_rect = hint_surface.get_rect(center=(WIDTH // 2, bar_y + 65))
            SCREEN.blit(hint_surface, hint_rect)

            # 코너 장식 (HUD 스타일)
            corner_color = (0, 255, 255, 150)
            corner_len = 30
            corner_thickness = 2
            # 좌상단
            pygame.draw.line(SCREEN, (0, 200, 255), (20, 20), (20 + corner_len, 20), corner_thickness)
            pygame.draw.line(SCREEN, (0, 200, 255), (20, 20), (20, 20 + corner_len), corner_thickness)
            # 우상단
            pygame.draw.line(SCREEN, (255, 0, 150), (WIDTH - 20, 20), (WIDTH - 20 - corner_len, 20), corner_thickness)
            pygame.draw.line(SCREEN, (255, 0, 150), (WIDTH - 20, 20), (WIDTH - 20, 20 + corner_len), corner_thickness)
            # 좌하단
            pygame.draw.line(SCREEN, (255, 0, 150), (20, HEIGHT - 20), (20 + corner_len, HEIGHT - 20), corner_thickness)
            pygame.draw.line(SCREEN, (255, 0, 150), (20, HEIGHT - 20), (20, HEIGHT - 20 - corner_len), corner_thickness)
            # 우하단
            pygame.draw.line(SCREEN, (0, 200, 255), (WIDTH - 20, HEIGHT - 20), (WIDTH - 20 - corner_len, HEIGHT - 20), corner_thickness)
            pygame.draw.line(SCREEN, (0, 200, 255), (WIDTH - 20, HEIGHT - 20), (WIDTH - 20, HEIGHT - 20 - corner_len), corner_thickness)

            # 버전/저작권 정보
            version_text = "v1.0 // PING FIGHTER"
            version_surface = small_font.render(version_text, True, (60, 80, 100))
            SCREEN.blit(version_surface, (30, HEIGHT - 35))

            pygame.display.flip()

        while True:
            now = time.time()
            elapsed = now - start_anim
            t = min(1.0, elapsed / anim_duration)
            # 이징 함수 적용 (smooth step)
            t = t * t * (3 - 2 * t)
            progress = _loading_progress + (target - _loading_progress) * t
            draw_frame(progress)
            if elapsed >= anim_duration:
                _loading_progress = progress
                # print(f"[show_loading_screen] 애니메이션 완료: {anim_duration}초 경과", flush=True)
                break
            time.sleep(1 / 60)

        _loading_progress = max(_loading_progress, target)
        # print(f"[show_loading_screen] 종료: progress={_loading_progress}", flush=True)
    except Exception as e:
        # 로딩 화면 실패는 게임 진행을 막지 않도록 무시
        import traceback
        print(f"[로딩 화면 오류] {e}")
        traceback.print_exc()
