# ---- 입력 스킴 어댑터 -------------------------------------------------------
# 옵션에서 '마우스+키보드'를 선택하면 마우스 버튼을 키 입력으로 매핑한다.
# - 좌클릭 → Space (serve/스킬 등)
# - 우클릭 → Down
_orig_pygame_event_get = pygame.event.get 
_last_bgm_toggle_ms = -9999
BGM_TOGGLE_COOLDOWN_MS = 250  # ms 단위 디바운스(오동작 방지)
_bgm_toggle_held = False  # 키를 누르고 있을 때 반복 토글 방지


def _apply_global_hotkeys(events):
    """전역 핫키 처리 (인게임/광장 공통)."""
    global _last_bgm_toggle_ms, _bgm_toggle_held
    for ev in events:
        if ev.type in (pygame.KEYDOWN, pygame.KEYUP):
            key = getattr(ev, "key", None) 
            uni = getattr(ev, "unicode", "")
            is_b_toggle = (key == pygame.K_b) or (uni == "ㅠ")

            # F9: 전체화면 전환 (게임 어디서든 동작)
            if ev.type == pygame.KEYDOWN and key == pygame.K_F9:
                try:
                    if get_display_mode() != "fullscreen":
                        switch_display_mode("fullscreen")
                except Exception:
                    pass
                continue

            # F10: 창모드 전환 (게임 어디서든 동작)
            if ev.type == pygame.KEYDOWN and key == pygame.K_F10:
                try:
                    if get_display_mode() != "windowed":
                        switch_display_mode("windowed")
                except Exception:
                    pass
                continue

            # F11: 투기장(Stage 30) 신의심판 디버그 메뉴
            if ev.type == pygame.KEYDOWN and key == pygame.K_F11:
                if current_stage == 30 and animated_bg_stage30 is not None:
                    try:
                        show_judgment_debug_menu()
                    except Exception:
                        pass
                continue

            # F12: 스크린샷 (모든 스테이지에서 동작)
            if ev.type == pygame.KEYDOWN and key == pygame.K_F12:
                try:
                    # 스크린샷 저장 폴더 (EXE 파일 위치 또는 게임 폴더 내 screenshots)
                    if getattr(sys, 'frozen', False):
                        # PyInstaller 빌드 시 EXE 파일이 있는 디렉토리에 저장
                        exe_dir = os.path.dirname(sys.executable)
                        screenshot_dir = os.path.join(exe_dir, "screenshots")
                    else:
                        # 개발 환경에서는 게임 폴더에 저장
                        screenshot_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "screenshots")

                    os.makedirs(screenshot_dir, exist_ok=True)

                    from datetime import datetime as dt
                    timestamp = dt.now().strftime("%Y%m%d_%H%M%S")
                    filename = os.path.join(screenshot_dir, f"screenshot_{timestamp}.png")

                    # 전체화면 모드면 REAL_SCREEN 캡처 (필러 포함)
                    if _is_fullscreen_active and REAL_SCREEN is not None:
                        screen_surface = REAL_SCREEN
                    else:
                        screen_surface = pygame.display.get_surface()

                    if screen_surface:
                        pygame.image.save(screen_surface, filename)
                        # 로그 파일에도 기록
                        log_file = os.path.join(os.path.dirname(sys.executable if getattr(sys, 'frozen', False) else os.path.abspath(__file__)), "screenshot_log.txt")
                        with open(log_file, "a", encoding="utf-8") as f:
                            f.write(f"✅ 스크린샷 저장 성공: {filename} ({dt.now().strftime('%Y-%m-%d %H:%M:%S')})\n")
                    else:
                        # 로그 파일에 오류 기록
                        log_file = os.path.join(os.path.dirname(sys.executable if getattr(sys, 'frozen', False) else os.path.abspath(__file__)), "screenshot_log.txt")
                        with open(log_file, "a", encoding="utf-8") as f:
                            f.write(f"❌ 스크린샷 실패: screen_surface가 None ({dt.now().strftime('%Y-%m-%d %H:%M:%S')})\n")
                except Exception as e:
                    import traceback
                    error_msg = traceback.format_exc()
                    # 로그 파일에 오류 기록
                    try:
                        from datetime import datetime as dt
                        log_file = os.path.join(os.path.dirname(sys.executable if getattr(sys, 'frozen', False) else os.path.abspath(__file__)), "screenshot_log.txt")
                        with open(log_file, "a", encoding="utf-8") as f:
                            f.write(f"\n{'='*80}\n")
                            f.write(f"❌ 스크린샷 오류 발생: {dt.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
                            f.write(f"오류 메시지: {str(e)}\n")
                            f.write(f"상세 정보:\n{error_msg}\n")
                            f.write(f"{'='*80}\n\n")
                    except:
                        pass
                continue

            if ev.type == pygame.KEYDOWN and is_b_toggle:
                if _bgm_toggle_held:
                    continue  # 키 리피트 무시
                now_ms = pygame.time.get_ticks()
                if now_ms - _last_bgm_toggle_ms < BGM_TOGGLE_COOLDOWN_MS:
                    continue
                _last_bgm_toggle_ms = now_ms
                _bgm_toggle_held = True
                try:
                    bgm_manager.toggle_bgm()
                except Exception as e:  # 방어적: BGM 초기화 실패 등
                    print(f"[WARN] BGM toggle failed: {e}")

            elif ev.type == pygame.KEYUP and is_b_toggle:
                _bgm_toggle_held = False
    return events

# 입력 추적(디버그) 플래그 – 기본 끔, 필요한 경우 PINGF_INPUT_TRACE=1 로 켜기
INPUT_TRACE = os.environ.get("PINGF_INPUT_TRACE", "0").lower() not in ("0", "false", "off")
# 전역 조용 모드: 1이면 각종 디버그 출력 억제
QUIET_DEBUG = os.environ.get("PINGF_QUIET_DEBUG", "1").lower() in ("1", "true", "yes", "on")
DRIVE_DEBUG = os.environ.get("PINGF_DRIVE_DEBUG", "0").lower() in ("1", "true", "yes", "on")
_input_log_prev_left = False
_input_log_prev_right = False
_input_log_last_frame = -9999
_input_log_last_time = 0.0
# 이벤트 기반 이동 상태(포커스 상실 시 fallback)
MOVE_EVENT_LEFT = False
MOVE_EVENT_RIGHT = False
MOVE_EVENT_DOWN = False
MOVE_EVENT_UP = False


def _log_input_trace(frame: int,
                     keys,
                     left_raw: bool,
                     right_raw: bool,
                     snap_left: bool,
                     snap_right: bool,
                     stunned: bool,
                     wait_serve: bool,
                     serve_timer: int,
                     speed: float) -> None:
    """간헐적 이동 미반응을 추적하기 위한 경량 로그"""
    global _input_log_prev_left, _input_log_prev_right, _input_log_last_frame, _input_log_last_time
    if not INPUT_TRACE:
        return
    now = time.time()
    # 변화가 없으면 2초(120프레임)마다만 찍기
    changed = (left_raw != _input_log_prev_left) or (right_raw != _input_log_prev_right)
    if not changed and frame - _input_log_last_frame < 120:
        return
    _input_log_prev_left = left_raw
    _input_log_prev_right = right_raw
    _input_log_last_frame = frame
    _input_log_last_time = now
    print(
        "[INPUT_TRACE]"
        f" frame={frame}"
        f" left_raw={int(left_raw)} right_raw={int(right_raw)}"
        f" snapL={int(bool(snap_left))} snapR={int(bool(snap_right))}"
        f" K_LEFT={int(keys[pygame.K_LEFT])} K_RIGHT={int(keys[pygame.K_RIGHT])}"
        f" K_a={int(keys[pygame.K_a])} K_d={int(keys[pygame.K_d])}"
        f" evtL={int(MOVE_EVENT_LEFT)} evtR={int(MOVE_EVENT_RIGHT)}"
        f" stunned={stunned} wait_serve={wait_serve} serve_t={serve_timer}"
        f" speed={speed:.3f}"
        f" focus={pygame.key.get_focused()}"
    )


