def check_ball_speed_safety():
    """공 속도 안전성 확인 및 제한"""
    global ball_vel, blacksmith_divine_stage_owner
    import math
    
    current_speed = math.hypot(ball_vel[0], ball_vel[1])
    max_safe_speed = BALL_BASE_SPEED * 2.0  # 기본 속도의 2배가 안전 상한
    
    if current_speed > max_safe_speed:
        # 속도 제한 적용
        scale = max_safe_speed / current_speed
        ball_vel[0] *= scale
        ball_vel[1] *= scale
        pass  # print(f"⚠️ 속도 안전 제한 적용: {current_speed:.2f} → {max_safe_speed:.2f}")  # 디버그 비활성화
        return True
    return False


