_custom_cursor_enabled = True  # 커스텀 커서 활성화 여부
_cursor_animation_time = 0.0  # 커서 애니메이션 시간
_cursor_pulse_speed = 4.0  # 펄스 속도
_cursor_trail = []  # 커서 잔상 효과용 이전 위치
_cursor_trail_max = 8  # 잔상 최대 개수
_cursor_surface = None  # 커서 서피스 캐시
_cursor_glow_surface = None  # 글로우 효과 서피스

def _create_custom_cursor_surfaces():
    """커스텀 커서 서피스 생성"""
    global _cursor_surface, _cursor_glow_surface

    # 메인 커서 (24x24 크기의 에너지 크로스헤어)
    _cursor_surface = pygame.Surface((32, 32), pygame.SRCALPHA)

    # 글로우 효과 서피스 (더 큰 크기)
    _cursor_glow_surface = pygame.Surface((48, 48), pygame.SRCALPHA)

def _draw_custom_cursor(screen, mouse_x, mouse_y):
    """커스텀 마우스 커서 그리기 - 네온 사이버"""
    global _cursor_animation_time, _cursor_trail

    _cursor_animation_time += 0.016
    pulse = math.sin(_cursor_animation_time * 3.0) * 0.15 + 0.85

    _cursor_trail.append((mouse_x, mouse_y))
    if len(_cursor_trail) > _cursor_trail_max:
        _cursor_trail.pop(0)

    # 네온 사이버 색상
    cyan = (0, 255, 255)
    dark_cyan = (0, 180, 200)
    black = (5, 15, 25)

    # 심플한 화살표 형태
    arrow = [
        (mouse_x, mouse_y),
        (mouse_x, mouse_y + 24),
        (mouse_x + 5, mouse_y + 19),
        (mouse_x + 8, mouse_y + 30),
        (mouse_x + 12, mouse_y + 28),
        (mouse_x + 8, mouse_y + 18),
        (mouse_x + 17, mouse_y + 24),
    ]

    # 시안 잔상
    for i, (tx, ty) in enumerate(_cursor_trail[:-1]):
        progress = (i + 1) / len(_cursor_trail)
        alpha = int(progress * 40)
        sc = 0.4 + progress * 0.4
        trail_pts = [(tx, ty), (tx, ty + 24 * sc), (tx + 5 * sc, ty + 19 * sc),
                     (tx + 8 * sc, ty + 30 * sc), (tx + 12 * sc, ty + 28 * sc),
                     (tx + 8 * sc, ty + 18 * sc), (tx + 17 * sc, ty + 24 * sc)]
        trail_surf = pygame.Surface((int(20 * sc) + 4, int(34 * sc) + 4), pygame.SRCALPHA)
        adj = [(p[0] - tx + 2, p[1] - ty + 2) for p in trail_pts]
        pygame.draw.polygon(trail_surf, (*cyan, alpha), adj)
        screen.blit(trail_surf, (tx - 2, ty - 2))

    # 네온 글로우 (심플하게 2단계)
    for glow_size in [4, 2]:
        glow_alpha = int(35 * pulse) if glow_size == 4 else int(55 * pulse)
        glow_surf = pygame.Surface((26 + glow_size * 2, 40 + glow_size * 2), pygame.SRCALPHA)
        glow_pts = [(p[0] - mouse_x + 5 + glow_size, p[1] - mouse_y + 5 + glow_size) for p in arrow]
        pygame.draw.polygon(glow_surf, (*cyan, glow_alpha), glow_pts)
        screen.blit(glow_surf, (mouse_x - 5 - glow_size, mouse_y - 5 - glow_size))

    # 어두운 내부 (검정에 가까운 진한 색)
    pygame.draw.polygon(screen, black, arrow)

    # 시안 테두리 (네온 라인)
    pygame.draw.polygon(screen, cyan, arrow, 2)

    # 내부 하이라이트 라인
    inner_line = [(mouse_x + 2, mouse_y + 5), (mouse_x + 2, mouse_y + 18),
                  (mouse_x + 5, mouse_y + 15), (mouse_x + 7, mouse_y + 22)]
    pygame.draw.lines(screen, dark_cyan, False, inner_line, 1)

    # 팁 글로우 (밝게 빛나는 끝점)
    tip_alpha = int(180 * pulse)
    tip_surf = pygame.Surface((8, 8), pygame.SRCALPHA)
    pygame.draw.circle(tip_surf, (*cyan, tip_alpha), (4, 4), 3)
    screen.blit(tip_surf, (mouse_x - 3, mouse_y - 3))

if FULLSCREEN_MODE and FULLSCREEN_WIDTH > 0:
    # 플랫폼별 전체화면 플래그 설정
    if _current_platform == 'Darwin':
        # macOS: FULLSCREEN_DESKTOP으로 데스크탑 해상도 유지 (Retina 대응)
        _fullscreen_flags = pygame.FULLSCREEN | pygame.DOUBLEBUF
        # print("[macOS] FULLSCREEN + DOUBLEBUF 모드 사용", flush=True)
    else:
        # Windows/Linux: 기본 FULLSCREEN
        _fullscreen_flags = pygame.FULLSCREEN

    # 전체화면 모드로 화면 생성
    REAL_SCREEN = pygame.display.set_mode((FULLSCREEN_WIDTH, FULLSCREEN_HEIGHT), _fullscreen_flags)

    # 커스텀 커서 사용 시 시스템 커서 즉시 숨김
    if _custom_cursor_enabled:
        pygame.mouse.set_visible(False)

    # 실제 생성된 화면 크기 확인 (DPI 스케일링 대응)
    actual_width, actual_height = REAL_SCREEN.get_size()
    # print(f"[전체화면] 요청: {FULLSCREEN_WIDTH}x{FULLSCREEN_HEIGHT}, 실제: {actual_width}x{actual_height}", flush=True)

    # macOS에서 Retina 스케일링으로 인해 크기가 다를 수 있음
    if _current_platform == 'Darwin' and (actual_width != FULLSCREEN_WIDTH or actual_height != FULLSCREEN_HEIGHT):
        print(f"[macOS] Retina 스케일링 감지됨", flush=True)

    # 실제 화면 크기 기준으로 오프셋 재계산
    FULLSCREEN_WIDTH = actual_width
    FULLSCREEN_HEIGHT = actual_height

    # 게임 Surface 스케일링 설정
    # 세로 기준으로 화면에 맞게 자동 스케일링 (확대/축소 모두 지원)
    MARGIN = 70  # 상하 여백 동일

    # 세로 기준으로 스케일 계산 (화면 세로에 맞춤)
    scale_y = (FULLSCREEN_HEIGHT - MARGIN * 2) / HEIGHT

    # 가로가 넘치지 않도록 체크
    scaled_width_check = int(WIDTH * scale_y)
    if scaled_width_check > FULLSCREEN_WIDTH:
        # 가로가 넘치면 가로 기준으로 스케일 조정
        scale_x = FULLSCREEN_WIDTH / WIDTH
        GAME_SCALE_FACTOR = scale_x
        print(f"[전체화면] 가로 기준 스케일링: {GAME_SCALE_FACTOR:.2f}x", flush=True)
    else:
        # 세로 기준 스케일 사용
        GAME_SCALE_FACTOR = scale_y
        print(f"[전체화면] 세로 기준 스케일링: {GAME_SCALE_FACTOR:.2f}x", flush=True)
    GAME_SCALED_WIDTH = int(WIDTH * GAME_SCALE_FACTOR)
    GAME_SCALED_HEIGHT = int(HEIGHT * GAME_SCALE_FACTOR)

    # 폰트 스케일 보정 설정 (rotozoom 축소로 인한 글자 번짐 방지)
    set_fullscreen_font_scale(GAME_SCALE_FACTOR)

    print(f"[전체화면] 스케일링: {GAME_SCALE_FACTOR:.2f}x ({WIDTH}x{HEIGHT} -> {GAME_SCALED_WIDTH}x{GAME_SCALED_HEIGHT})", flush=True)

    GAME_OFFSET_X = (FULLSCREEN_WIDTH - GAME_SCALED_WIDTH) // 2
    # Y 오프셋: 화면 중앙 정렬 (상하 동일 여백)
    GAME_OFFSET_Y = (FULLSCREEN_HEIGHT - GAME_SCALED_HEIGHT) // 2

    # 게임 렌더링용 Surface (기존 코드와 호환성 유지)
    # macOS: 알파 블렌딩이 제대로 작동하려면 convert_alpha() 사용
    # Windows: convert()로도 잘 작동하지만 일관성을 위해 convert_alpha() 사용
    SCREEN = pygame.Surface((WIDTH, HEIGHT)).convert()

    # 필러 배경 렌더러 초기화 (실제 화면 크기 사용)
    # 스케일링된 게임 크기와 오프셋, 원본 게임 크기를 전달하여 좌표 변환이 정확히 되도록 함
    from pillar_background import init_pillar_background, get_pillar_renderer
    pillar_renderer = init_pillar_background(
        FULLSCREEN_WIDTH, FULLSCREEN_HEIGHT,
        GAME_SCALED_WIDTH, GAME_SCALED_HEIGHT,
        offset_x=GAME_OFFSET_X, offset_y=GAME_OFFSET_Y,
        original_game_width=WIDTH, original_game_height=HEIGHT
    )

    # display_manager에 전체화면 모드 설정 전달
    from display_manager import set_fullscreen_mode
    set_fullscreen_mode(True, SCREEN)
    # print(f"[전체화면] display_manager에 전체화면 모드 설정 완료 (SCREEN Surface 전달)", flush=True)
else:
    # === 창모드: SCALED 정수배 합성 (구 공식 창 사이즈 + SDL GPU 업스케일링) ===
    # 1단계: 구 공식으로 목표 창 사이즈 계산 (더블 모니터 시 가장 큰 모니터 사용)
    _init_largest = _get_largest_monitor_resolution()
    if _init_largest:
        _init_monitor_w, _init_monitor_h = _init_largest
    elif sys.platform == 'win32':
        _win_native = _get_native_resolution() or _get_current_resolution()
        if _win_native:
            _init_monitor_w, _init_monitor_h = _win_native
        else:
            _init_monitor_w, _init_monitor_h = 1920, 1080
    else:
        _init_dinfo = pygame.display.Info()
        _init_monitor_w, _init_monitor_h = _init_dinfo.current_w, _init_dinfo.current_h

    _init_base_h = int(_init_monitor_h * 0.85)
    _init_win_scale = _init_base_h / HEIGHT
    _init_game_w = int(WIDTH * _init_win_scale)
    _init_pillar_pad_x = int(_init_game_w * 0.30)
    _init_pillar_pad_y = max(int(_init_base_h * 0.065), 30)
    _init_target_w = _init_game_w + _init_pillar_pad_x * 2
    _init_target_h = _init_base_h + _init_pillar_pad_y * 2
    if _init_target_w > int(_init_monitor_w * 0.90):
        _init_target_w = int(_init_monitor_w * 0.90)
    if _init_target_h > int(_init_monitor_h * 0.85):
        _init_target_h = int(_init_monitor_h * 0.85)

    # 2단계: 정수배 합성 크기 결정 (target/N >= 게임 크기인 최대 N)
    _comp_w_try = _init_target_w // 2
    _comp_h_try = _init_target_h // 2
    if _comp_w_try >= WIDTH and _comp_h_try >= HEIGHT:
        _comp_w = _comp_w_try
        _comp_h = _comp_h_try
        _scale_n = 2
    else:
        _comp_w = _init_target_w
        _comp_h = _init_target_h
        _scale_n = 1
    _comp_pad_x = (_comp_w - WIDTH) // 2
    _comp_pad_y = (_comp_h - HEIGHT) // 2

    # 3단계: SCALED 모드 시도 (SDL이 자동 정수배 업스케일링)
    # 더블 모니터: 가장 큰 모니터 중앙에 창 배치
    _init_win_pos = _get_largest_monitor_pos(_init_target_w, _init_target_h)
    _scaled_ok = False
    try:
        print(f"[디스플레이] 창모드(SCALED x{_scale_n}) 시작... 합성={_comp_w}x{_comp_h} → 목표 {_init_target_w}x{_init_target_h}", flush=True)
        pygame.display.quit()
        pygame.display.init()
        if _init_win_pos:
            os.environ['SDL_VIDEO_WINDOW_POS'] = f'{_init_win_pos[0]},{_init_win_pos[1]}'
        else:
            os.environ['SDL_VIDEO_CENTERED'] = '1'
        REAL_SCREEN = pygame.display.set_mode((_comp_w, _comp_h), pygame.SCALED)
        os.environ.pop('SDL_VIDEO_WINDOW_POS', None)
        os.environ.pop('SDL_VIDEO_CENTERED', None)

        # SDL SCALED가 잘못된 디스플레이 기준으로 스케일 결정할 수 있음
        # ctypes로 윈도우 크기를 목표 크기로 강제 지정 + 정확한 위치 배치
        if _scale_n >= 2 and sys.platform == 'win32':
            try:
                import ctypes as _ct
                _sdl2_p = os.path.join(os.path.dirname(pygame.__file__), "SDL2.dll")
                _sdl2_lib = _ct.CDLL(_sdl2_p)
                _sdl2_lib.SDL_GetKeyboardFocus.restype = _ct.c_void_p
                _sdl_win = _sdl2_lib.SDL_GetKeyboardFocus()
                if _sdl_win:
                    _sdl2_lib.SDL_SetWindowSize.argtypes = [_ct.c_void_p, _ct.c_int, _ct.c_int]
                    _sdl2_lib.SDL_SetWindowSize(_sdl_win, _init_target_w, _init_target_h)
                    # 큰 모니터 중앙에 재배치
                    _repos = _get_largest_monitor_pos(_init_target_w, _init_target_h)
                    if _repos:
                        _sdl2_lib.SDL_SetWindowPosition.argtypes = [_ct.c_void_p, _ct.c_int, _ct.c_int]
                        _sdl2_lib.SDL_SetWindowPosition(_sdl_win, _repos[0], _repos[1])
                    # print(f"[디스플레이] SDL 윈도우 크기 강제: {_init_target_w}x{_init_target_h}", flush=True)
            except Exception as _resize_err:
                print(f"[디스플레이] SDL 윈도우 리사이즈 실패: {_resize_err}", flush=True)

        _scaled_ok = True
    except pygame.error as _scaled_err:
        print(f"[디스플레이] pygame.SCALED 실패({_scaled_err}), 소프트웨어 스케일링으로 폴백", flush=True)
        os.environ.pop('SDL_VIDEO_WINDOW_POS', None)
        os.environ.pop('SDL_VIDEO_CENTERED', None)

    if _scaled_ok:
        # --- SCALED 합성 모드: 게임 1:1 + 필러 배경, GPU N배 업스케일링 ---
        _use_scaled_mode = True

        if _custom_cursor_enabled:
            pygame.mouse.set_visible(False)

        FULLSCREEN_WIDTH = _comp_w
        FULLSCREEN_HEIGHT = _comp_h
        if _scale_n >= 2:
            # GPU 2배 업스케일링: 게임은 1:1로 렌더링, SDL이 2x 업스케일
            GAME_SCALE_FACTOR = 1.0
            GAME_SCALED_WIDTH = WIDTH
            GAME_SCALED_HEIGHT = HEIGHT
            GAME_OFFSET_X = _comp_pad_x
            GAME_OFFSET_Y = _comp_pad_y
        else:
            # _scale_n == 1: GPU 업스케일링 불가 → 소프트웨어 스케일링 적용
            _sw_margin = _init_pillar_pad_y
            _sw_scale_y = (_comp_h - _sw_margin * 2) / HEIGHT
            _sw_scaled_w_check = int(WIDTH * _sw_scale_y)
            if _sw_scaled_w_check > _comp_w:
                GAME_SCALE_FACTOR = _comp_w / WIDTH
            else:
                GAME_SCALE_FACTOR = _sw_scale_y
            GAME_SCALED_WIDTH = int(WIDTH * GAME_SCALE_FACTOR)
            GAME_SCALED_HEIGHT = int(HEIGHT * GAME_SCALE_FACTOR)
            GAME_OFFSET_X = (_comp_w - GAME_SCALED_WIDTH) // 2
            GAME_OFFSET_Y = (_comp_h - GAME_SCALED_HEIGHT) // 2
            print(f"[디스플레이] 창모드(SCALED x1) 소프트웨어 스케일링: {GAME_SCALE_FACTOR:.2f}x ({WIDTH}x{HEIGHT} → {GAME_SCALED_WIDTH}x{GAME_SCALED_HEIGHT})", flush=True)

        from pixel_font_manager import set_fullscreen_font_scale
        set_fullscreen_font_scale(GAME_SCALE_FACTOR)

        SCREEN = pygame.Surface((WIDTH, HEIGHT)).convert()

        from pillar_background import init_pillar_background, get_pillar_renderer
        pillar_renderer = init_pillar_background(
            _comp_w, _comp_h,
            GAME_SCALED_WIDTH, GAME_SCALED_HEIGHT,
            offset_x=GAME_OFFSET_X, offset_y=GAME_OFFSET_Y,
            original_game_width=WIDTH, original_game_height=HEIGHT
        )

        from display_manager import set_fullscreen_mode
        set_fullscreen_mode(True, SCREEN)

        # print(f"[디스플레이] 창모드(SCALED x{_scale_n}) 완료: 합성 {_comp_w}x{_comp_h}, 게임 1:1, SDL GPU 스케일링", flush=True)
    else:
        # --- 폴백: 기존 소프트웨어 스케일링 (필러 포함) ---
        _fb_largest = _get_largest_monitor_resolution()
        if _fb_largest:
            _init_monitor_w, _init_monitor_h = _fb_largest
        elif sys.platform == 'win32':
            _win_native = _get_native_resolution() or _get_current_resolution()
            if _win_native:
                _init_monitor_w, _init_monitor_h = _win_native
            else:
                _init_monitor_w, _init_monitor_h = 1920, 1080
        else:
            _init_dinfo = pygame.display.Info()
            _init_monitor_w, _init_monitor_h = _init_dinfo.current_w, _init_dinfo.current_h

        _init_base_h = int(_init_monitor_h * 0.85)
        _init_win_scale = _init_base_h / HEIGHT
        _init_game_w = int(WIDTH * _init_win_scale)
        _init_pillar_pad_x = int(_init_game_w * 0.30)
        _init_pillar_pad_y = max(int(_init_base_h * 0.065), 30)
        _init_target_w = _init_game_w + _init_pillar_pad_x * 2
        _init_target_h = _init_base_h + _init_pillar_pad_y * 2
        if _init_target_w > int(_init_monitor_w * 0.90):
            _init_target_w = int(_init_monitor_w * 0.90)
        if _init_target_h > int(_init_monitor_h * 0.85):
            _init_target_h = int(_init_monitor_h * 0.85)

        # 더블 모니터: 가장 큰 모니터 중앙에 배치
        _fb_win_pos = _get_largest_monitor_pos(_init_target_w, _init_target_h)
        if _fb_win_pos:
            os.environ['SDL_VIDEO_WINDOW_POS'] = f'{_fb_win_pos[0]},{_fb_win_pos[1]}'
        else:
            os.environ['SDL_VIDEO_CENTERED'] = '1'
        REAL_SCREEN = pygame.display.set_mode((_init_target_w, _init_target_h), pygame.DOUBLEBUF | pygame.RESIZABLE)
        os.environ.pop('SDL_VIDEO_WINDOW_POS', None)
        os.environ.pop('SDL_VIDEO_CENTERED', None)

        if _custom_cursor_enabled:
            pygame.mouse.set_visible(False)

        _init_actual_w, _init_actual_h = REAL_SCREEN.get_size()
        FULLSCREEN_WIDTH = _init_actual_w
        FULLSCREEN_HEIGHT = _init_actual_h

        _init_margin = _init_pillar_pad_y
        _init_scale_y = (_init_actual_h - _init_margin * 2) / HEIGHT
        _init_scaled_w_check = int(WIDTH * _init_scale_y)
        if _init_scaled_w_check > _init_actual_w:
            GAME_SCALE_FACTOR = _init_actual_w / WIDTH
        else:
            GAME_SCALE_FACTOR = _init_scale_y

        GAME_SCALED_WIDTH = int(WIDTH * GAME_SCALE_FACTOR)
        GAME_SCALED_HEIGHT = int(HEIGHT * GAME_SCALE_FACTOR)
        GAME_OFFSET_X = (_init_actual_w - GAME_SCALED_WIDTH) // 2
        GAME_OFFSET_Y = (_init_actual_h - GAME_SCALED_HEIGHT) // 2

        from pixel_font_manager import set_fullscreen_font_scale
        set_fullscreen_font_scale(GAME_SCALE_FACTOR)

        SCREEN = pygame.Surface((WIDTH, HEIGHT)).convert()

        from pillar_background import init_pillar_background, get_pillar_renderer
        pillar_renderer = init_pillar_background(
            _init_actual_w, _init_actual_h,
            GAME_SCALED_WIDTH, GAME_SCALED_HEIGHT,
            offset_x=GAME_OFFSET_X, offset_y=GAME_OFFSET_Y,
            original_game_width=WIDTH, original_game_height=HEIGHT
        )

        from display_manager import set_fullscreen_mode
        set_fullscreen_mode(True, SCREEN)

        print(f"[디스플레이] 창모드(폴백) 시작 완료: {_init_actual_w}x{_init_actual_h}", flush=True)

pygame.display.set_caption("PINGFIGHTER")

# 전체화면 모드에서 pygame.display.set_mode 호출 추적
_original_set_mode = pygame.display.set_mode
def _tracked_set_mode(*args, **kwargs):
    """pygame.display.set_mode 호출 추적 - 전체화면 모드에서 문제 디버깅용"""
    import traceback
    print(f"[SET_MODE WARNING] pygame.display.set_mode called with args={args}, kwargs={kwargs}", flush=True)
    traceback.print_stack()
    return _original_set_mode(*args, **kwargs)

# 전체화면 모드에서 set_mode 호출 추적 활성화
if FULLSCREEN_MODE:
    pygame.display.set_mode = _tracked_set_mode

# 전체화면 모드에서 pygame.display.flip()을 래핑하여 SCREEN을 REAL_SCREEN에 blit
