# ============================================================
# 스크린샷 기능 (] 키로 전체 화면 캡처 - 필러 포함)
# ============================================================
_screenshot_key_pressed = False  # ] 키 중복 방지
_key0_pressed = False  # 0번 키 중복 방지 (런타임 스킬 선택창)

def capture_screenshot():
    """현재 화면을 스크린샷으로 저장 (필러 포함)

    저장 경로: screenshots 폴더 (없으면 생성)
    파일명: pingfighter_YYYYMMDD_HHMMSS.png
    """
    global REAL_SCREEN, SCREEN, pillar_renderer, _is_fullscreen_active

    try:
        # 스크린샷 폴더 생성 (EXE 파일 위치 또는 게임 폴더)
        if getattr(sys, 'frozen', False):
            # PyInstaller 빌드 시 EXE 파일이 있는 디렉토리에 저장
            exe_dir = os.path.dirname(sys.executable)
            screenshot_dir = os.path.join(exe_dir, "screenshots")
        else:
            # 개발 환경에서는 게임 폴더에 저장
            script_dir = os.path.dirname(os.path.abspath(__file__))
            screenshot_dir = os.path.join(script_dir, "screenshots")
        if not os.path.exists(screenshot_dir):
            os.makedirs(screenshot_dir)

        # 파일명 생성 (타임스탬프)
        from datetime import datetime as dt
        timestamp = dt.now().strftime("%Y%m%d_%H%M%S")
        filename = f"pingfighter_{timestamp}.png"
        filepath = os.path.join(screenshot_dir, filename)

        # 전체화면 모드면 REAL_SCREEN 캡처 (필러 포함)
        if _is_fullscreen_active and REAL_SCREEN is not None:
            # REAL_SCREEN에 현재 상태 다시 그리기 (필러 + 게임화면)
            capture_surface = REAL_SCREEN.copy()
        else:
            # 창 모드면 SCREEN만 캡처
            capture_surface = SCREEN.copy()

        # 파일 저장
        pygame.image.save(capture_surface, filepath)
        # print(f"📸 스크린샷 저장: {filepath}")
        return True

    except Exception as e:
        import traceback
        from datetime import datetime as dt
        error_msg = traceback.format_exc()
        print(f"❌ 스크린샷 저장 실패: {e}")
        print(error_msg)
        # 로그 파일에 오류 기록
        try:
            log_file = os.path.join(os.path.dirname(sys.executable if getattr(sys, 'frozen', False) else os.path.abspath(__file__)), "screenshot_log.txt")
            with open(log_file, "a", encoding="utf-8") as f:
                f.write(f"\n{'='*80}\n")
                f.write(f"❌ 스크린샷 오류 발생 (] 키): {dt.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
                f.write(f"오류 메시지: {str(e)}\n")
                f.write(f"상세 정보:\n{error_msg}\n")
                f.write(f"{'='*80}\n\n")
        except:
            pass
        return False

# 전체화면 모드에서 마우스 좌표 변환 (화면 좌표 -> 게임 좌표)
_original_mouse_get_pos = pygame.mouse.get_pos
_mouse_debug_count = 0

def _fullscreen_mouse_get_pos():
    """전체화면 모드에서 마우스 좌표를 게임 좌표로 변환 (스케일링 고려)"""
    global _mouse_debug_count
    x, y = _original_mouse_get_pos()
    if _is_fullscreen_active:
        # 1. 화면 좌표에서 게임 오프셋을 뺌
        scaled_x = x - GAME_OFFSET_X
        scaled_y = y - GAME_OFFSET_Y

        # 2. 스케일링 역변환 (화면에 표시된 크기 -> 원본 게임 크기)
        if GAME_SCALE_FACTOR != 1.0:
            game_x = int(scaled_x / GAME_SCALE_FACTOR)
            game_y = int(scaled_y / GAME_SCALE_FACTOR)
        else:
            game_x = scaled_x
            game_y = scaled_y

        _mouse_debug_count += 1
        # if _mouse_debug_count <= 10 or _mouse_debug_count % 300 == 0:
        #     print(f"[MOUSE #{_mouse_debug_count}] 원본: ({x}, {y}), 스케일링후: ({scaled_x}, {scaled_y}), 게임좌표: ({game_x}, {game_y}), 스케일: {GAME_SCALE_FACTOR:.2f}x", flush=True)  # 디버그 비활성화
        return (game_x, game_y)
    return (x, y)

# pygame.mouse.get_pos를 래핑된 버전으로 교체
if _is_fullscreen_active:
    pygame.mouse.get_pos = _fullscreen_mouse_get_pos
    print(f"[MOUSE] pygame.mouse.get_pos 래핑 완료, 오프셋: ({GAME_OFFSET_X}, {GAME_OFFSET_Y})", flush=True)

# 전체화면 모드에서 마우스 이벤트 좌표도 변환
_original_event_get = pygame.event.get

def _fullscreen_event_get(*args, **kwargs):
    """전체화면 모드에서 마우스 이벤트 좌표를 게임 좌표로 변환 (스케일링 고려)"""
    events = _original_event_get(*args, **kwargs)
    if _is_fullscreen_active:
        for event in events:
            # 마우스 이벤트의 pos 속성 변환
            if hasattr(event, 'pos'):
                x, y = event.pos
                # 1. 오프셋 제거
                scaled_x = x - GAME_OFFSET_X
                scaled_y = y - GAME_OFFSET_Y

                # 2. 스케일링 역변환
                if GAME_SCALE_FACTOR != 1.0:
                    game_x = int(scaled_x / GAME_SCALE_FACTOR)
                    game_y = int(scaled_y / GAME_SCALE_FACTOR)
                else:
                    game_x = scaled_x
                    game_y = scaled_y

                # event 객체의 속성은 직접 수정 불가하므로 dict를 통해 새 이벤트 생성
                event.__dict__['pos'] = (game_x, game_y)
    return events

if _is_fullscreen_active:
    pygame.event.get = _fullscreen_event_get
    print(f"[EVENT] pygame.event.get 래핑 완료", flush=True)

# ============================================================
# 디스플레이 모드 전환 (전체화면 ↔ 창모드)
# ============================================================
def switch_display_mode(mode: str = None, *, to_windowed: bool = None):
    """전체화면 ↔ 창모드 ↔ 전체창모드 전환 (런타임)

    Parameters
    ----------
    mode : str
        "fullscreen" | "borderless" | "windowed"
    to_windowed : bool (하위호환)
        True  → 창모드로 전환, False → 전체화면으로 전환
    """
    global REAL_SCREEN, SCREEN, pillar_renderer, _is_fullscreen_active
    global GAME_OFFSET_X, GAME_OFFSET_Y, GAME_SCALE_FACTOR
    global GAME_SCALED_WIDTH, GAME_SCALED_HEIGHT
    global FULLSCREEN_MODE, FULLSCREEN_WIDTH, FULLSCREEN_HEIGHT
    global _current_display_mode, _original_resolution, _use_scaled_mode

    # 하위호환: to_windowed 파라미터 지원
    if mode is None and to_windowed is not None:
        mode = "windowed" if to_windowed else "fullscreen"
    if mode is None or mode == _current_display_mode:
        return

    from pillar_background import init_pillar_background, get_pillar_renderer as _get_pr
    from display_manager import set_fullscreen_mode as _set_dm_fullscreen
    from pixel_font_manager import set_fullscreen_font_scale as _set_font_scale

    # 모드 전환 시 GPU 스케일 힌트 정리 (전체화면 → 다른 모드)
    if mode != "fullscreen":
        os.environ.pop('SDL_RENDER_SCALE_QUALITY', None)

    if mode == "windowed":
        # === 창모드로 전환 ===
        print("[디스플레이] 창모드로 전환 시작...", flush=True)

        # Windows: 해상도 원래대로 복원
        if sys.platform == 'win32' and _original_resolution:
            _restore_windows_resolution()
            import time
            time.sleep(0.3)  # 해상도 복원 대기

        # 네이티브 모니터 해상도 가져오기 (더블 모니터: 가장 큰 모니터 사용)
        _win_largest = _get_largest_monitor_resolution()
        if _win_largest:
            monitor_w, monitor_h = _win_largest
        elif sys.platform == 'win32':
            native = _get_native_resolution() or _get_current_resolution()
            if native:
                monitor_w, monitor_h = native
            else:
                monitor_w, monitor_h = 1920, 1080
        else:
            _dinfo = pygame.display.Info()
            monitor_w, monitor_h = _dinfo.current_w, _dinfo.current_h

        FULLSCREEN_MODE = False
        _is_fullscreen_active = True

        # 구 공식으로 목표 창 사이즈 계산 → 정수배 합성
        _init_base_h = int(monitor_h * 0.85)
        _init_win_scale = _init_base_h / HEIGHT
        _init_game_w = int(WIDTH * _init_win_scale)
        _init_pillar_pad_x = int(_init_game_w * 0.30)
        _init_pillar_pad_y = max(int(_init_base_h * 0.065), 30)
        _init_target_w = _init_game_w + _init_pillar_pad_x * 2
        _init_target_h = _init_base_h + _init_pillar_pad_y * 2
        if _init_target_w > int(monitor_w * 0.90):
            _init_target_w = int(monitor_w * 0.90)
        if _init_target_h > int(monitor_h * 0.85):
            _init_target_h = int(monitor_h * 0.85)

        # 정수배 합성 크기 결정
        _comp_w_try = _init_target_w // 2
        _comp_h_try = _init_target_h // 2
        if _comp_w_try >= WIDTH and _comp_h_try >= HEIGHT:
            _comp_w = _comp_w_try
            _comp_h = _comp_h_try
            _scale_n = 2
        else:
            _comp_w = _init_target_w
            _comp_h = _init_target_h
            _scale_n = 1
        _comp_pad_x = (_comp_w - WIDTH) // 2
        _comp_pad_y = (_comp_h - HEIGHT) // 2

        # SCALED 합성 모드 시도 → 실패 시 소프트웨어 스케일링 폴백
        # 더블 모니터: 가장 큰 모니터 중앙에 창 배치
        _win_pos = _get_largest_monitor_pos(_init_target_w, _init_target_h)
        _sw_scaled_ok = False
        try:
            pygame.display.quit()
            pygame.display.init()
            if _win_pos:
                os.environ['SDL_VIDEO_WINDOW_POS'] = f'{_win_pos[0]},{_win_pos[1]}'
            else:
                os.environ['SDL_VIDEO_CENTERED'] = '1'
            REAL_SCREEN = pygame.display.set_mode((_comp_w, _comp_h), pygame.SCALED)
            os.environ.pop('SDL_VIDEO_WINDOW_POS', None)
            os.environ.pop('SDL_VIDEO_CENTERED', None)

            # SDL SCALED 윈도우 크기 강제 (더블 모니터 대응)
            if _scale_n >= 2 and sys.platform == 'win32':
                try:
                    import ctypes as _ct
                    _sdl2_p = os.path.join(os.path.dirname(pygame.__file__), "SDL2.dll")
                    _sdl2_lib = _ct.CDLL(_sdl2_p)
                    _sdl2_lib.SDL_GetKeyboardFocus.restype = _ct.c_void_p
                    _sdl_win = _sdl2_lib.SDL_GetKeyboardFocus()
                    if _sdl_win:
                        _sdl2_lib.SDL_SetWindowSize.argtypes = [_ct.c_void_p, _ct.c_int, _ct.c_int]
                        _sdl2_lib.SDL_SetWindowSize(_sdl_win, _init_target_w, _init_target_h)
                        _repos = _get_largest_monitor_pos(_init_target_w, _init_target_h)
                        if _repos:
                            _sdl2_lib.SDL_SetWindowPosition.argtypes = [_ct.c_void_p, _ct.c_int, _ct.c_int]
                            _sdl2_lib.SDL_SetWindowPosition(_sdl_win, _repos[0], _repos[1])
                except Exception:
                    pass

            _sw_scaled_ok = True
        except pygame.error:
            os.environ.pop('SDL_VIDEO_WINDOW_POS', None)
            os.environ.pop('SDL_VIDEO_CENTERED', None)

        if _sw_scaled_ok:
            _use_scaled_mode = True
            if _custom_cursor_enabled:
                pygame.mouse.set_visible(False)
            FULLSCREEN_WIDTH = _comp_w
            FULLSCREEN_HEIGHT = _comp_h
            if _scale_n >= 2:
                # GPU 2배 업스케일링: 게임은 1:1
                GAME_SCALE_FACTOR = 1.0
                GAME_SCALED_WIDTH = WIDTH
                GAME_SCALED_HEIGHT = HEIGHT
                GAME_OFFSET_X = _comp_pad_x
                GAME_OFFSET_Y = _comp_pad_y
            else:
                # _scale_n == 1: GPU 업스케일링 불가 → 소프트웨어 스케일링 적용
                _sw_margin = _init_pillar_pad_y
                _sw_scale_y = (_comp_h - _sw_margin * 2) / HEIGHT
                _sw_scaled_w = int(WIDTH * _sw_scale_y)
                if _sw_scaled_w > _comp_w:
                    GAME_SCALE_FACTOR = _comp_w / WIDTH
                else:
                    GAME_SCALE_FACTOR = _sw_scale_y
                GAME_SCALED_WIDTH = int(WIDTH * GAME_SCALE_FACTOR)
                GAME_SCALED_HEIGHT = int(HEIGHT * GAME_SCALE_FACTOR)
                GAME_OFFSET_X = (_comp_w - GAME_SCALED_WIDTH) // 2
                GAME_OFFSET_Y = (_comp_h - GAME_SCALED_HEIGHT) // 2
                print(f"[디스플레이] 창모드(SCALED x1) 소프트웨어 스케일링: {GAME_SCALE_FACTOR:.2f}x", flush=True)
            _set_font_scale(GAME_SCALE_FACTOR)
            SCREEN = pygame.Surface((WIDTH, HEIGHT)).convert()
            pillar_renderer = init_pillar_background(
                _comp_w, _comp_h, GAME_SCALED_WIDTH, GAME_SCALED_HEIGHT,
                offset_x=GAME_OFFSET_X, offset_y=GAME_OFFSET_Y,
                original_game_width=WIDTH, original_game_height=HEIGHT
            )
        else:
            _use_scaled_mode = False
            _init_base_h = int(monitor_h * 0.85)
            _init_win_scale = _init_base_h / HEIGHT
            _init_game_w = int(WIDTH * _init_win_scale)
            _init_pillar_pad_x = int(_init_game_w * 0.30)
            _init_pillar_pad_y = max(int(_init_base_h * 0.065), 30)
            _t_w = _init_game_w + _init_pillar_pad_x * 2
            _t_h = _init_base_h + _init_pillar_pad_y * 2
            if _t_w > int(monitor_w * 0.90):
                _t_w = int(monitor_w * 0.90)
            if _t_h > int(monitor_h * 0.85):
                _t_h = int(monitor_h * 0.85)
            os.environ['SDL_VIDEO_CENTERED'] = '1'
            REAL_SCREEN = pygame.display.set_mode((_t_w, _t_h), pygame.DOUBLEBUF | pygame.RESIZABLE)
            if 'SDL_VIDEO_CENTERED' in os.environ:
                del os.environ['SDL_VIDEO_CENTERED']
            if _custom_cursor_enabled:
                pygame.mouse.set_visible(False)
            _a_w, _a_h = REAL_SCREEN.get_size()
            FULLSCREEN_WIDTH = _a_w
            FULLSCREEN_HEIGHT = _a_h
            _m = _init_pillar_pad_y
            _sy = (_a_h - _m * 2) / HEIGHT
            if int(WIDTH * _sy) > _a_w:
                GAME_SCALE_FACTOR = _a_w / WIDTH
            else:
                GAME_SCALE_FACTOR = _sy
            GAME_SCALED_WIDTH = int(WIDTH * GAME_SCALE_FACTOR)
            GAME_SCALED_HEIGHT = int(HEIGHT * GAME_SCALE_FACTOR)
            GAME_OFFSET_X = (_a_w - GAME_SCALED_WIDTH) // 2
            GAME_OFFSET_Y = (_a_h - GAME_SCALED_HEIGHT) // 2
            _set_font_scale(GAME_SCALE_FACTOR)
            SCREEN = pygame.Surface((WIDTH, HEIGHT)).convert()
            pillar_renderer = init_pillar_background(
                _a_w, _a_h, GAME_SCALED_WIDTH, GAME_SCALED_HEIGHT,
                offset_x=GAME_OFFSET_X, offset_y=GAME_OFFSET_Y,
                original_game_width=WIDTH, original_game_height=HEIGHT
            )

        invalidate_pillar_bg_cache()
        _set_dm_fullscreen(True, SCREEN)

        pygame.display.flip = _fullscreen_flip
        pygame.display.update = _fullscreen_update
        pygame.mouse.get_pos = _fullscreen_mouse_get_pos
        pygame.event.get = _fullscreen_event_get

        try:
            draw.screen = SCREEN
            trade_point_system.screen = SCREEN
        except Exception:
            pass

        pygame.display.set_caption("PINGFIGHTER")
        _current_display_mode = "windowed"
        _mode_str = "SCALED 합성" if _sw_scaled_ok else "폴백"
        print(f"[디스플레이] 창모드({_mode_str}) 전환 완료", flush=True)

    elif mode == "fullscreen":
        # === 전체화면모드: GPU 프랙셔널 스케일링 (최고 화질) ===
        # SDL2의 정수배 제약을 해제 → GPU 하드웨어 선형 필터링으로 분수배 스케일
        # CPU 스케일링 없이 1:1 렌더링 → GPU가 모니터 크기에 맞춰 업스케일
        print("[디스플레이] 전체화면모드로 전환 시작...", flush=True)

        # 시네마모드에서 전환 시 해상도 복원
        if sys.platform == 'win32' and _original_resolution:
            _restore_windows_resolution()
            import time
            time.sleep(0.3)

        # 네이티브 모니터 해상도 감지 (더블 모니터: 가장 큰 모니터 사용)
        _fs_largest = _get_largest_monitor_resolution()
        if _fs_largest:
            monitor_w, monitor_h = _fs_largest
        elif sys.platform == 'win32':
            native = _get_native_resolution() or _get_current_resolution()
            if native:
                monitor_w, monitor_h = native
            else:
                monitor_w, monitor_h = 1920, 1080
        else:
            display_info = pygame.display.Info()
            monitor_w, monitor_h = display_info.current_w, display_info.current_h

        FULLSCREEN_MODE = False
        _is_fullscreen_active = True

        # display 리셋 (SCALED 또는 다른 모드에서 전환 시 필요)
        pygame.display.quit()
        pygame.display.init()

        # ====== GPU 프랙셔널 스케일링 ======
        # 원리: comp 버퍼(게임 1:1 + 마진) → GPU가 모니터 크기로 선형 보간 업스케일
        _fs_gpu_frac_ok = False

        # 화면 마진 (모니터 픽셀 기준, 상하 각각)
        if monitor_h >= 2160:       # 4K
            _fs_screen_margin = 180
        elif monitor_h >= 1440:     # 1440p
            _fs_screen_margin = 100
        else:                       # 1080p
            _fs_screen_margin = 70

        # GPU 스케일 팩터: 게임이 화면에서 차지할 크기 결정
        _fs_game_screen_h = monitor_h - _fs_screen_margin * 2
        _fs_gpu_scale = _fs_game_screen_h / HEIGHT

        # comp 버퍼 크기 = 모니터 / GPU스케일 (모니터 종횡비 유지)
        _fs_comp_w = int(round(monitor_w / _fs_gpu_scale))
        _fs_comp_h = int(round(monitor_h / _fs_gpu_scale))

        # comp 버퍼가 게임보다 작으면 안됨
        _fs_comp_w = max(_fs_comp_w, WIDTH + 40)
        _fs_comp_h = max(_fs_comp_h, HEIGHT + 20)

        # 짝수 크기 보장 (GPU 텍스처 호환성)
        _fs_comp_w += _fs_comp_w % 2
        _fs_comp_h += _fs_comp_h % 2

        try:
            # SDL 렌더 힌트: 선형(bilinear) 필터링 활성화
            os.environ['SDL_RENDER_SCALE_QUALITY'] = '1'

            REAL_SCREEN = pygame.display.set_mode(
                (_fs_comp_w, _fs_comp_h),
                pygame.SCALED | pygame.FULLSCREEN
            )

            # ctypes로 SDL2의 정수배 스케일링 제약 비활성화
            import ctypes
            _sdl2_path = os.path.join(
                os.path.dirname(pygame.__file__), "SDL2.dll"
            )
            if not os.path.exists(_sdl2_path):
                raise FileNotFoundError(f"SDL2.dll not found: {_sdl2_path}")
            _sdl2 = ctypes.CDLL(_sdl2_path)

            # SDL_GetKeyboardFocus() → SDL_Window*
            _sdl2.SDL_GetKeyboardFocus.restype = ctypes.c_void_p
            _sdl_window = _sdl2.SDL_GetKeyboardFocus()
            if not _sdl_window:
                raise RuntimeError("SDL_GetKeyboardFocus returned NULL")

            # SDL_GetRenderer(SDL_Window*) → SDL_Renderer*
            _sdl2.SDL_GetRenderer.restype = ctypes.c_void_p
            _sdl2.SDL_GetRenderer.argtypes = [ctypes.c_void_p]
            _sdl_renderer = _sdl2.SDL_GetRenderer(_sdl_window)
            if not _sdl_renderer:
                raise RuntimeError("SDL_GetRenderer returned NULL")

            # SDL_RenderSetIntegerScale(renderer, SDL_FALSE) → 분수배 허용
            _sdl2.SDL_RenderSetIntegerScale.argtypes = [ctypes.c_void_p, ctypes.c_int]
            _sdl2.SDL_RenderSetIntegerScale.restype = ctypes.c_int
            _sdl_result = _sdl2.SDL_RenderSetIntegerScale(_sdl_renderer, 0)
            if _sdl_result != 0:
                raise RuntimeError(f"SDL_RenderSetIntegerScale failed: {_sdl_result}")

            _fs_gpu_frac_ok = True
            _use_scaled_mode = True

            # GPU가 모든 스케일링 처리 → CPU 스케일링 불필요 (1:1)
            GAME_SCALE_FACTOR = 1.0
            GAME_SCALED_WIDTH = WIDTH
            GAME_SCALED_HEIGHT = HEIGHT
            GAME_OFFSET_X = (_fs_comp_w - WIDTH) // 2
            GAME_OFFSET_Y = (_fs_comp_h - HEIGHT) // 2
            FULLSCREEN_WIDTH = _fs_comp_w
            FULLSCREEN_HEIGHT = _fs_comp_h

            if _custom_cursor_enabled:
                pygame.mouse.set_visible(False)

            _set_font_scale(GAME_SCALE_FACTOR)
            SCREEN = pygame.Surface((WIDTH, HEIGHT)).convert()
            pillar_renderer = init_pillar_background(
                _fs_comp_w, _fs_comp_h, GAME_SCALED_WIDTH, GAME_SCALED_HEIGHT,
                offset_x=GAME_OFFSET_X, offset_y=GAME_OFFSET_Y,
                original_game_width=WIDTH, original_game_height=HEIGHT
            )
            _fs_mode_str = (
                f"GPU 프랙셔널 (comp {_fs_comp_w}x{_fs_comp_h}, "
                f"GPU {_fs_gpu_scale:.2f}x → {monitor_w}x{monitor_h})"
            )

        except Exception as _fs_frac_err:
            print(f"[전체화면] GPU 프랙셔널 스케일링 실패: {_fs_frac_err}, CPU 폴백", flush=True)
            _fs_gpu_frac_ok = False
            os.environ.pop('SDL_RENDER_SCALE_QUALITY', None)
            # 실패 시 display 재초기화
            try:
                pygame.display.quit()
                pygame.display.init()
            except Exception:
                pass

        if not _fs_gpu_frac_ok:
            # === 폴백: NOFRAME + CPU 스케일링 (DWM 우회) ===
            _use_scaled_mode = False
            # 더블 모니터: 가장 큰 모니터 좌상단에 배치
            _nf_pos = _largest_monitor_info
            os.environ['SDL_VIDEO_WINDOW_POS'] = f'{_nf_pos["x"]},{_nf_pos["y"]}' if _nf_pos else '0,0'
            if _current_platform == 'Darwin':
                REAL_SCREEN = pygame.display.set_mode((monitor_w, monitor_h), pygame.NOFRAME | pygame.DOUBLEBUF)
            else:
                REAL_SCREEN = pygame.display.set_mode((monitor_w, monitor_h), pygame.NOFRAME)
            if 'SDL_VIDEO_WINDOW_POS' in os.environ:
                del os.environ['SDL_VIDEO_WINDOW_POS']
            if _custom_cursor_enabled:
                pygame.mouse.set_visible(False)
            actual_w, actual_h = REAL_SCREEN.get_size()
            FULLSCREEN_WIDTH = actual_w
            FULLSCREEN_HEIGHT = actual_h
            MARGIN = 70
            scale_y = (FULLSCREEN_HEIGHT - MARGIN * 2) / HEIGHT
            scaled_width_check = int(WIDTH * scale_y)
            if scaled_width_check > FULLSCREEN_WIDTH:
                GAME_SCALE_FACTOR = FULLSCREEN_WIDTH / WIDTH
            else:
                GAME_SCALE_FACTOR = scale_y
            GAME_SCALED_WIDTH = int(WIDTH * GAME_SCALE_FACTOR)
            GAME_SCALED_HEIGHT = int(HEIGHT * GAME_SCALE_FACTOR)
            GAME_OFFSET_X = (FULLSCREEN_WIDTH - GAME_SCALED_WIDTH) // 2
            GAME_OFFSET_Y = (FULLSCREEN_HEIGHT - GAME_SCALED_HEIGHT) // 2
            _set_font_scale(GAME_SCALE_FACTOR)
            SCREEN = pygame.Surface((WIDTH, HEIGHT)).convert()
            pillar_renderer = init_pillar_background(
                actual_w, actual_h, GAME_SCALED_WIDTH, GAME_SCALED_HEIGHT,
                offset_x=GAME_OFFSET_X, offset_y=GAME_OFFSET_Y,
                original_game_width=WIDTH, original_game_height=HEIGHT
            )
            _fs_mode_str = f"NOFRAME+CPU ({FULLSCREEN_WIDTH}x{FULLSCREEN_HEIGHT})"

        invalidate_pillar_bg_cache()
        _set_dm_fullscreen(True, SCREEN)

        pygame.display.flip = _fullscreen_flip
        pygame.display.update = _fullscreen_update
        pygame.mouse.get_pos = _fullscreen_mouse_get_pos
        pygame.event.get = _fullscreen_event_get

        try:
            draw.screen = SCREEN
            trade_point_system.screen = SCREEN
        except Exception:
            pass

        pygame.display.set_caption("PINGFIGHTER")
        _current_display_mode = "fullscreen"
        # print(f"[디스플레이] 전체화면모드({_fs_mode_str}) 전환 완료: 합성 {FULLSCREEN_WIDTH}x{FULLSCREEN_HEIGHT}, 게임 {GAME_SCALED_WIDTH}x{GAME_SCALED_HEIGHT}, 스케일 {GAME_SCALE_FACTOR:.3f}x", flush=True)

    elif mode == "cinema":
        # === 시네마모드: OS 해상도를 낮춰서 전체화면 ===
        print("[디스플레이] 시네마모드로 전환 시작...", flush=True)

        if sys.platform == 'win32':
            # 네이티브 해상도 저장 (복원용)
            native_res = _get_native_resolution() or _get_current_resolution()
            if native_res:
                _original_resolution = native_res
                print(f"[시네마모드] 원본 해상도 저장: {native_res[0]}x{native_res[1]}", flush=True)

                # 모니터 비율에 맞는 저해상도 계산
                target_res = _get_matching_resolution(native_res[0], native_res[1])
                if target_res and target_res != (native_res[0], native_res[1]):
                    print(f"[시네마모드] 해상도 변경: {native_res[0]}x{native_res[1]} → {target_res[0]}x{target_res[1]}", flush=True)
                    _change_windows_resolution(target_res[0], target_res[1])
                    import time
                    time.sleep(0.3)
                    atexit.register(_restore_windows_resolution)
                else:
                    print(f"[시네마모드] 매칭 해상도 없음, 네이티브로 진행", flush=True)

        FULLSCREEN_MODE = True

        # 해상도 변경 후 모니터 해상도 재감지
        if _current_platform == 'Windows':
            _monitor_res = _get_current_resolution()
            if _monitor_res and _monitor_res[0] > 0 and _monitor_res[1] > 0:
                FULLSCREEN_WIDTH, FULLSCREEN_HEIGHT = _monitor_res
            else:
                display_info = pygame.display.Info()
                FULLSCREEN_WIDTH = display_info.current_w
                FULLSCREEN_HEIGHT = display_info.current_h
        else:
            display_info = pygame.display.Info()
            FULLSCREEN_WIDTH = display_info.current_w
            FULLSCREEN_HEIGHT = display_info.current_h

        # SCALED 모드에서 전환 시 display 리셋 필요
        if _use_scaled_mode:
            pygame.display.quit()
            pygame.display.init()

        _fs_flags = pygame.FULLSCREEN | pygame.DOUBLEBUF if _current_platform == 'Darwin' else pygame.FULLSCREEN
        REAL_SCREEN = pygame.display.set_mode((FULLSCREEN_WIDTH, FULLSCREEN_HEIGHT), _fs_flags)

        if _custom_cursor_enabled:
            pygame.mouse.set_visible(False)

        actual_w, actual_h = REAL_SCREEN.get_size()
        FULLSCREEN_WIDTH = actual_w
        FULLSCREEN_HEIGHT = actual_h

        # 스케일링 계산
        MARGIN = 70
        scale_y = (FULLSCREEN_HEIGHT - MARGIN * 2) / HEIGHT
        scaled_width_check = int(WIDTH * scale_y)
        if scaled_width_check > FULLSCREEN_WIDTH:
            GAME_SCALE_FACTOR = FULLSCREEN_WIDTH / WIDTH
        else:
            GAME_SCALE_FACTOR = scale_y

        GAME_SCALED_WIDTH = int(WIDTH * GAME_SCALE_FACTOR)
        GAME_SCALED_HEIGHT = int(HEIGHT * GAME_SCALE_FACTOR)
        GAME_OFFSET_X = (FULLSCREEN_WIDTH - GAME_SCALED_WIDTH) // 2
        GAME_OFFSET_Y = (FULLSCREEN_HEIGHT - GAME_SCALED_HEIGHT) // 2

        _set_font_scale(GAME_SCALE_FACTOR)

        SCREEN = pygame.Surface((WIDTH, HEIGHT)).convert()

        pillar_renderer = init_pillar_background(
            FULLSCREEN_WIDTH, FULLSCREEN_HEIGHT,
            GAME_SCALED_WIDTH, GAME_SCALED_HEIGHT,
            offset_x=GAME_OFFSET_X, offset_y=GAME_OFFSET_Y,
            original_game_width=WIDTH, original_game_height=HEIGHT
        )
        invalidate_pillar_bg_cache()  # 필러 캐시 무효화 (해상도 변경)
        _set_dm_fullscreen(True, SCREEN)

        _is_fullscreen_active = True
        _use_scaled_mode = False

        pygame.display.flip = _fullscreen_flip
        pygame.display.update = _fullscreen_update
        pygame.mouse.get_pos = _fullscreen_mouse_get_pos
        pygame.event.get = _fullscreen_event_get

        try:
            draw.screen = SCREEN
            trade_point_system.screen = SCREEN
        except Exception:
            pass

        pygame.display.set_caption("PINGFIGHTER")
        _current_display_mode = "cinema"
        # print(f"[디스플레이] 시네마모드 전환 완료: {FULLSCREEN_WIDTH}x{FULLSCREEN_HEIGHT}", flush=True)

    elif mode == "borderless":
        # === 전체창모드(보더리스 윈도우) 전환 ===
        print("[디스플레이] 전체창모드으로 전환 시작...", flush=True)

        # Windows: 해상도 원래대로 복원 (보더리스는 네이티브 해상도 사용)
        if sys.platform == 'win32' and _original_resolution:
            _restore_windows_resolution()
            import time
            time.sleep(0.3)

        # 네이티브 모니터 해상도 (더블 모니터: 가장 큰 모니터 사용)
        _bl_largest = _get_largest_monitor_resolution()
        if _bl_largest:
            monitor_w, monitor_h = _bl_largest
        elif sys.platform == 'win32':
            native = _get_native_resolution() or _get_current_resolution()
            if native:
                monitor_w, monitor_h = native
            else:
                monitor_w, monitor_h = 1920, 1080
        else:
            _dinfo = pygame.display.Info()
            monitor_w, monitor_h = _dinfo.current_w, _dinfo.current_h

        FULLSCREEN_MODE = False
        _is_fullscreen_active = True

        # SCALED 모드에서 전환 시 display 리셋 필요 (플래그 해제 전에 체크)
        _was_scaled = _use_scaled_mode
        _use_scaled_mode = False
        if _was_scaled:
            pygame.display.quit()
            pygame.display.init()

        # 보더리스 윈도우 (더블 모니터: 가장 큰 모니터에 배치)
        _bl_pos = _largest_monitor_info
        os.environ['SDL_VIDEO_WINDOW_POS'] = f'{_bl_pos["x"]},{_bl_pos["y"]}' if _bl_pos else '0,0'
        if _current_platform == 'Darwin':
            REAL_SCREEN = pygame.display.set_mode((monitor_w, monitor_h), pygame.NOFRAME | pygame.DOUBLEBUF)
        else:
            REAL_SCREEN = pygame.display.set_mode((monitor_w, monitor_h), pygame.NOFRAME)
        # 환경변수 정리
        if 'SDL_VIDEO_WINDOW_POS' in os.environ:
            del os.environ['SDL_VIDEO_WINDOW_POS']

        if _custom_cursor_enabled:
            pygame.mouse.set_visible(False)

        actual_w, actual_h = REAL_SCREEN.get_size()
        FULLSCREEN_WIDTH = actual_w
        FULLSCREEN_HEIGHT = actual_h

        # 전체화면과 동일한 스케일링 (MARGIN = 70)
        MARGIN = 70
        scale_y = (actual_h - MARGIN * 2) / HEIGHT
        scaled_width_check = int(WIDTH * scale_y)
        if scaled_width_check > actual_w:
            GAME_SCALE_FACTOR = actual_w / WIDTH
        else:
            GAME_SCALE_FACTOR = scale_y

        GAME_SCALED_WIDTH = int(WIDTH * GAME_SCALE_FACTOR)
        GAME_SCALED_HEIGHT = int(HEIGHT * GAME_SCALE_FACTOR)
        GAME_OFFSET_X = (actual_w - GAME_SCALED_WIDTH) // 2
        GAME_OFFSET_Y = (actual_h - GAME_SCALED_HEIGHT) // 2

        _set_font_scale(GAME_SCALE_FACTOR)

        SCREEN = pygame.Surface((WIDTH, HEIGHT)).convert()

        pillar_renderer = init_pillar_background(
            actual_w, actual_h,
            GAME_SCALED_WIDTH, GAME_SCALED_HEIGHT,
            offset_x=GAME_OFFSET_X, offset_y=GAME_OFFSET_Y,
            original_game_width=WIDTH, original_game_height=HEIGHT
        )
        invalidate_pillar_bg_cache()  # 필러 캐시 무효화 (해상도 변경)
        _set_dm_fullscreen(True, SCREEN)

        pygame.display.flip = _fullscreen_flip
        pygame.display.update = _fullscreen_update
        pygame.mouse.get_pos = _fullscreen_mouse_get_pos
        pygame.event.get = _fullscreen_event_get

        try:
            draw.screen = SCREEN
            trade_point_system.screen = SCREEN
        except Exception:
            pass

        pygame.display.set_caption("PINGFIGHTER")
        _current_display_mode = "borderless"
        print(f"[디스플레이] 전체창모드 전환 완료: {actual_w}x{actual_h}", flush=True)


def is_windowed_mode() -> bool:
    """현재 창모드인지 반환 (하위호환)"""
    return _current_display_mode != "fullscreen"


def get_display_mode() -> str:
    """현재 디스플레이 모드 반환: 'fullscreen' | 'cinema' | 'windowed'"""
    return _current_display_mode


