# ============================================================
# 발토르 성능 디버그 시스템 (F9로 토글)
# ============================================================
VALTHOR_PERF_DEBUG = False  # F9로 토글
_valthor_perf_times: dict[str, list[float]] = {}
_valthor_perf_start: dict[str, float] = {}
_valthor_perf_max_samples = 60  # 1초 분량

# 토르쉴드 프레임 드랍 전용 추적
_thor_shield_frame_times: list[float] = []
_thor_shield_deploy_active = False
_thor_shield_deploy_start_time = 0.0
_thor_shield_cache_stats = {"hits": 0, "misses": 0}

def valthor_perf_start(name: str) -> None:
    """발토르 관련 함수 성능 측정 시작"""
    if VALTHOR_PERF_DEBUG:
        _valthor_perf_start[name] = time.perf_counter()

def valthor_perf_end(name: str) -> None:
    """발토르 관련 함수 성능 측정 종료"""
    if VALTHOR_PERF_DEBUG and name in _valthor_perf_start:
        elapsed = (time.perf_counter() - _valthor_perf_start[name]) * 1000  # ms
        if name not in _valthor_perf_times:
            _valthor_perf_times[name] = []
        _valthor_perf_times[name].append(elapsed)
        if len(_valthor_perf_times[name]) > _valthor_perf_max_samples:
            _valthor_perf_times[name].pop(0)

def draw_valthor_perf_overlay(surface: pygame.Surface) -> None:
    """발토르 성능 오버레이 표시"""
    if not VALTHOR_PERF_DEBUG or not _valthor_perf_times:
        return

    # 반투명 배경
    overlay_width = 380
    overlay_height = 30 + len(_valthor_perf_times) * 22
    overlay = pygame.Surface((overlay_width, overlay_height), pygame.SRCALPHA)
    overlay.fill((0, 0, 0, 200))
    surface.blit(overlay, (10, 60))

    # 제목
    try:
        title_font = pygame.font.Font(None, 18)
        title = title_font.render("=== VALTHOR PERF DEBUG (F9) ===", True, (0, 255, 255))
        surface.blit(title, (15, 65))
    except:
        pass

    y_offset = 85
    total_ms = 0.0
    for name, times in sorted(_valthor_perf_times.items()):
        if times:
            avg_ms = sum(times) / len(times)
            max_ms = max(times)
            min_ms = min(times)
            total_ms += avg_ms

            # 색상: 1ms 이상이면 노랑, 2ms 이상이면 빨강
            if avg_ms >= 2.0:
                color = (255, 80, 80)
            elif avg_ms >= 1.0:
                color = (255, 255, 80)
            else:
                color = (80, 255, 80)

            try:
                perf_font = pygame.font.Font(None, 16)
                text = f"{name}: avg={avg_ms:.2f}ms max={max_ms:.2f}ms"
                text_surface = perf_font.render(text, True, color)
                surface.blit(text_surface, (15, y_offset))
            except:
                pass
            y_offset += 20

    # 총합
    try:
        total_color = (255, 80, 80) if total_ms >= 8.0 else (255, 255, 80) if total_ms >= 4.0 else (80, 255, 80)
        total_text = f"TOTAL: {total_ms:.2f}ms (target: <16.67ms)"
        total_surface = pygame.font.Font(None, 18).render(total_text, True, total_color)
        surface.blit(total_surface, (15, y_offset + 5))
        y_offset += 25

        # 캐시 히트율 표시
        total_cache = _blacksmith_paddle_cache_hits + _blacksmith_paddle_cache_misses
        if total_cache > 0:
            hit_rate = (_blacksmith_paddle_cache_hits / total_cache) * 100
            cache_color = (80, 255, 80) if hit_rate >= 80 else (255, 255, 80) if hit_rate >= 50 else (255, 80, 80)
            cache_text = f"CACHE: {hit_rate:.1f}% ({_blacksmith_paddle_cache_hits}/{total_cache})"
            cache_surface = pygame.font.Font(None, 16).render(cache_text, True, cache_color)
            surface.blit(cache_surface, (15, y_offset))
            y_offset += 20

        # 화면 크기 정보 표시
        if REAL_SCREEN is not None:
            real_size = REAL_SCREEN.get_size()
            screen_size = SCREEN.get_size() if SCREEN is not None else (0, 0)
            scale_info = f"SCREEN: {screen_size[0]}x{screen_size[1]} -> {real_size[0]}x{real_size[1]} (x{GAME_SCALE_FACTOR:.2f})"
            scale_surface = pygame.font.Font(None, 16).render(scale_info, True, (180, 180, 255))
            surface.blit(scale_surface, (15, y_offset))
            y_offset += 20

        # 토르쉴드 배치 상태 표시
        umbrella_open = blacksmith_umbrella_open
        anim_timer = blacksmith_umbrella_anim_timer
        if umbrella_open or anim_timer > 0:
            shield_status = f"THOR SHIELD: OPEN (anim={anim_timer})"
            shield_color = (255, 200, 100)
        else:
            shield_status = "THOR SHIELD: CLOSED"
            shield_color = (100, 100, 100)
        shield_surface = pygame.font.Font(None, 16).render(shield_status, True, shield_color)
        surface.blit(shield_surface, (15, y_offset))
        y_offset += 20

        # 프레임 타임 표시 (실시간)
        if _thor_shield_frame_times:
            avg_ft = sum(_thor_shield_frame_times) / len(_thor_shield_frame_times)
            max_ft = max(_thor_shield_frame_times)
            min_ft = min(_thor_shield_frame_times)
            fps_equiv = 1000.0 / avg_ft if avg_ft > 0 else 0
            ft_color = (255, 80, 80) if avg_ft > 20 else (255, 255, 80) if avg_ft > 16.67 else (80, 255, 80)
            ft_text = f"FRAME: {avg_ft:.1f}ms (min={min_ft:.1f} max={max_ft:.1f}) ~{fps_equiv:.0f}fps"
            ft_surface = pygame.font.Font(None, 16).render(ft_text, True, ft_color)
            surface.blit(ft_surface, (15, y_offset))
    except:
        pass
