#  동적 최대 게이지 계산 함수
def get_max_gauge():
    """
    플레이어 스킬 게이지 최대치 계산.
    - 기본값: 500 (+ 아카데미/아이템/배율 보정)
    - 튜토리얼(Stage 50)일 때만 챕터별 임시 최대치(100/300/500)를 적용
      (일반 스테이지에서 튜토리얼 잔여 상태가 영향을 주지 않도록 가드)
    """
    # 튜토리얼(Stage 50) 여부 가드
    is_tutorial = (globals().get('current_stage', 0) == 50)

    if is_tutorial:
        # 우선순위: Chapter 4 > Chapter 3 > Chapter 2 > Chapter 1
        if 'tutorial_current_chapter' in globals():
            current_chapter = tutorial_current_chapter
            if current_chapter == 4:
                # Chapter 4는 무조건 500 반환 (다른 변수 무시)
                return 500

        # Chapter 3 임시 오버라이드 (300)
        if ('tutorial_drive_chapter_max_gauge' in globals() and tutorial_drive_chapter_max_gauge is not None and
            ('tutorial_current_chapter' not in globals() or tutorial_current_chapter < 4)):
            return tutorial_drive_chapter_max_gauge

        # Chapter 2 (DASH) - 300
        if 'tutorial_chapter2_max_gauge' in globals() and tutorial_chapter2_max_gauge is not None:
            return tutorial_chapter2_max_gauge

        # Chapter 1 (BASIC) - 100
        if 'tutorial_chapter1_max_gauge' in globals() and tutorial_chapter1_max_gauge is not None:
            return tutorial_chapter1_max_gauge

    # 일반 계산 경로 (기본 500 + 보정치)
    base_max = 500
    try:
        import academy
        paddle_max_bonus = academy.get_skill_bonus("paddle_max_gauge")
        base_max = base_max + paddle_max_bonus
    except:
        pass
    
    # 연료파우치 보너스 적용
    fuel_pouch_bonus = get_fuel_pouch_gauge_bonus()
    base_max = base_max + fuel_pouch_bonus
    
    #  악마의 주사위 스킬 게이지 배율 적용
    from item_effects.devil_dice import get_devil_dice_multipliers, is_devil_dice_active
    if is_devil_dice_active():
        multipliers = get_devil_dice_multipliers()
        base_max = int(base_max * multipliers['skill_gauge'])

    # 옵티머스: 스테이지 진행 중 최대 게이지가 서서히 감소
    if globals().get('selected_character_type') == "optimus":
        scale = float(globals().get('optimus_max_scale', 1.0))
        base_max = int(base_max * max(0.0, scale))

    return int(base_max * ANGEL_GAUGE_MULT)
