# ========== 비상충전 더블탭 감지 시스템 ==========
class EmergencyChargeDoubleTap:
    """옵티머스 비상충전 스킬의 ㄴ키 더블탭 감지 클래스"""
    def __init__(self):
        self.last_tap_time = 0
        self.double_tap_threshold = 300  # 300ms 이내 더블탭 감지
        self.cooldown = 500  # 발동 후 500ms 쿨다운
        self.last_activation_time = 0

    def check_double_tap(self, current_time: int) -> bool:
        """더블탭 감지 - True 반환 시 발동"""
        # 쿨다운 체크
        if current_time - self.last_activation_time < self.cooldown:
            return False

        # 더블탭 감지
        time_since_last = current_time - self.last_tap_time
        self.last_tap_time = current_time

        if time_since_last < self.double_tap_threshold:
            return True
        return False

    def mark_activated(self, current_time: int):
        """발동 시 호출 - 쿨다운 시작"""
        self.last_activation_time = current_time
        self.last_tap_time = 0  # 탭 타이머 리셋

    def reset(self):
        """리셋"""
        self.last_tap_time = 0
        self.last_activation_time = 0

# 비상충전 더블탭 인스턴스
_emergency_charge_double_tap = None

# 비상충전 시각 효과 변수
emergency_charge_flash_timer = 0  # 화면 플래시 타이머
emergency_charge_flash_duration = 30  # 플래시 지속시간 (0.5초)
emergency_charge_particles = []  # 파티클 리스트

def get_emergency_charge_double_tap() -> EmergencyChargeDoubleTap:
    """비상충전 더블탭 인스턴스 반환"""
    global _emergency_charge_double_tap
    if _emergency_charge_double_tap is None:
        _emergency_charge_double_tap = EmergencyChargeDoubleTap()
    return _emergency_charge_double_tap

def update_emergency_charge_effects():
    """비상충전 시각 효과 업데이트"""
    global emergency_charge_flash_timer, emergency_charge_particles

    # 플래시 타이머 감소
    if emergency_charge_flash_timer > 0:
        emergency_charge_flash_timer -= 1

    # 파티클 업데이트 (최적화: remove() 대신 인덱스 순회)
    i = 0
    while i < len(emergency_charge_particles):
        p = emergency_charge_particles[i]
        p["x"] += p["vx"]
        p["y"] += p["vy"]
        p["vy"] += 0.3  # 중력
        p["life"] -= 1
        if p["life"] <= 0:
            emergency_charge_particles.pop(i)
        else:
            i += 1

def draw_emergency_charge_effects(screen: pygame.Surface):
    """비상충전 시각 효과 렌더링 (캐시 최적화)"""
    global emergency_charge_flash_timer, emergency_charge_particles

    # 화면 플래시 효과 (캐시된 Surface 사용)
    if emergency_charge_flash_timer > 0:
        flash_alpha = int(150 * (emergency_charge_flash_timer / emergency_charge_flash_duration))
        flash_surf = get_cached_flash_surface(screen.get_width(), screen.get_height())
        flash_surf.fill((255, 220, 100, flash_alpha))  # 금색 플래시
        screen.blit(flash_surf, (0, 0))

    # 전기 파티클 렌더링
    for p in emergency_charge_particles:
        alpha = min(255, int(255 * (p["life"] / 40)))
        color = (*p["color"][:3], alpha) if len(p["color"]) == 3 else p["color"]
        # 전기 효과 (작은 번개 라인)
        gfxdraw.filled_circle(screen, int(p["x"]), int(p["y"]), p["size"], color)
        # 글로우 효과 (사전 렌더링된 캐시 사용 - 매 프레임 draw.circle 제거)
        if p["size"] > 4:
            glow_size = p["size"] * 4
            glow_alpha = alpha // 4
            glow_surf = get_predrawn_glow_circle(glow_size, p["color"][:3], glow_alpha)
            half_size = glow_surf.get_width() // 2
            screen.blit(glow_surf, (int(p["x"]) - half_size, int(p["y"]) - half_size), special_flags=pygame.BLEND_ADD)

# ========== 리커버리 좌우 동시입력 감지 시스템 (스매셔 전용) ==========
class RecoveryDualInput:
    """스매셔 리커버리 스킬의 좌+우 동시 입력 감지 클래스"""
    def __init__(self):
        self.cooldown = 500  # 발동 후 500ms 쿨다운
        self.last_activation_time = 0
        self.was_both_pressed = False  # 이전 프레임 동시 입력 상태

    def check_dual_input(self, current_time: int, left_pressed: bool, right_pressed: bool) -> bool:
        """좌+우 동시 입력 감지 - True 반환 시 발동"""
        # 쿨다운 체크
        if current_time - self.last_activation_time < self.cooldown:
            return False

        both_pressed = left_pressed and right_pressed

        # 동시 입력이 새로 발생했을 때 (이전에 안 눌려있다가 눌린 경우)
        if both_pressed and not self.was_both_pressed:
            self.was_both_pressed = True
            return True

        self.was_both_pressed = both_pressed
        return False

    def mark_activated(self, current_time: int):
        """발동 시 호출 - 쿨다운 시작"""
        self.last_activation_time = current_time

    def reset(self):
        """리셋"""
        self.last_activation_time = 0
        self.was_both_pressed = False

# 리커버리 동시입력 인스턴스
_recovery_dual_input = None

# 리커버리 시각 효과 변수 - 에메랄드/골드 계열 (클렌즈와 차별화)
recovery_effect_active = False  # 리커버리 이펙트 활성화 여부
recovery_effect_timer = 0
recovery_effect_duration = 18  # 0.3초 (빠르게)
recovery_effect_center_x = 0
recovery_effect_center_y = 0
recovery_wave_rings = []
recovery_particles = []
recovery_flash_alpha = 0
RECOVERY_GAUGE_COST = 120  # 리커버리 게이지 소모량

# 리커버리 이동속도 보너스 시스템
recovery_speed_boost_active = False  # 이동속도 보너스 활성화 여부
recovery_speed_boost_timer = 0  # 남은 시간 (프레임)
RECOVERY_SPEED_BOOST_DURATION = 300  # 5초 (60fps * 5)
RECOVERY_SPEED_BOOST_PERCENT = 0.30  # 30% 이동속도 증가
recovery_light_particles = []  # 빛가루 파티클 리스트

def get_recovery_dual_input() -> RecoveryDualInput:
    """리커버리 동시입력 인스턴스 반환"""
    global _recovery_dual_input
    if _recovery_dual_input is None:
        _recovery_dual_input = RecoveryDualInput()
    return _recovery_dual_input

def trigger_recovery_effect(paddle_x: float, paddle_y: float):
    """리커버리 발동 - 에메랄드/골드 정화 이펙트 + 5초 이동속도 보너스"""
    global recovery_effect_active, recovery_effect_timer
    global recovery_effect_center_x, recovery_effect_center_y
    global recovery_wave_rings, recovery_particles, recovery_flash_alpha
    global recovery_speed_boost_active, recovery_speed_boost_timer, recovery_light_particles

    recovery_effect_active = True
    recovery_effect_timer = recovery_effect_duration
    recovery_effect_center_x = paddle_x
    recovery_effect_center_y = paddle_y
    recovery_flash_alpha = 255

    # 이동속도 보너스 활성화 (5초)
    recovery_speed_boost_active = True
    recovery_speed_boost_timer = RECOVERY_SPEED_BOOST_DURATION
    recovery_light_particles = []  # 빛가루 파티클 초기화

    # 파동 링 생성 (3개) - 빠른 속도
    recovery_wave_rings = []
    for i in range(3):
        recovery_wave_rings.append({
            'radius': 10,
            'max_radius': 80 + i * 25,
            'alpha': 255,
            'thickness': 4 - i,
            'delay': i * 2,  # 딜레이 단축
            'started': False
        })

    # 에너지 파티클 생성 - 빠른 속도
    recovery_particles = []
    for _ in range(25):
        angle = random.uniform(0, 2 * math.pi)
        speed = random.uniform(5, 10)  # 속도 증가
        recovery_particles.append({
            'x': paddle_x,
            'y': paddle_y,
            'vx': math.cos(angle) * speed,
            'vy': math.sin(angle) * speed,
            'size': random.randint(2, 5),
            'alpha': 255,
            'color_type': random.choice(['emerald', 'gold', 'white']),
            'life': random.randint(10, 18)  # 수명 단축
        })

def update_recovery_effects():
    """리커버리 시각 효과 업데이트"""
    global recovery_effect_active, recovery_effect_timer
    global recovery_wave_rings, recovery_particles, recovery_flash_alpha

    if not recovery_effect_active:
        return

    recovery_effect_timer -= 1
    if recovery_effect_timer <= 0:
        recovery_effect_active = False
        recovery_wave_rings = []
        recovery_particles = []
        recovery_flash_alpha = 0
        return

    # 플래시 감소
    if recovery_flash_alpha > 0:
        recovery_flash_alpha = max(0, recovery_flash_alpha - 30)

    # 파동 링 업데이트
    for ring in recovery_wave_rings:
        if not ring['started']:
            if ring['delay'] <= 0:
                ring['started'] = True
            else:
                ring['delay'] -= 1
            continue

        expansion_speed = (ring['max_radius'] - 10) / 10  # 더 빠른 확장
        ring['radius'] = min(ring['radius'] + expansion_speed, ring['max_radius'])
        progress = (ring['radius'] - 10) / (ring['max_radius'] - 10)
        ring['alpha'] = int(255 * (1 - progress * 0.9))

    # 파티클 업데이트
    i = 0
    while i < len(recovery_particles):
        p = recovery_particles[i]
        p['x'] += p['vx']
        p['y'] += p['vy']
        p['vx'] *= 0.93
        p['vy'] *= 0.93
        p['life'] -= 1
        p['alpha'] = int(255 * (p['life'] / 30))
        if p['life'] <= 0:
            recovery_particles.pop(i)
        else:
            i += 1


def update_recovery_speed_boost(player_x: float, player_y: float, is_moving: bool):
    """리커버리 이동속도 보너스 업데이트 및 빛가루 파티클 생성"""
    global recovery_speed_boost_active, recovery_speed_boost_timer, recovery_light_particles

    # 보너스 타이머 감소
    if recovery_speed_boost_active:
        recovery_speed_boost_timer -= 1
        if recovery_speed_boost_timer <= 0:
            recovery_speed_boost_active = False
            recovery_light_particles = []

        # 이동 중일 때 빛가루 파티클 생성
        elif is_moving:
            # 프레임당 1~2개 파티클 생성
            for _ in range(random.randint(1, 2)):
                recovery_light_particles.append({
                    'x': player_x + random.uniform(-20, 20),
                    'y': player_y + random.uniform(-5, 10),
                    'vx': random.uniform(-0.5, 0.5),
                    'vy': random.uniform(-1.5, -0.5),  # 위로 올라감
                    'size': random.uniform(2, 4),
                    'alpha': 255,
                    'life': random.randint(20, 40),
                    'color': random.choice([
                        (180, 255, 200),  # 연한 에메랄드
                        (255, 230, 150),  # 연한 골드
                        (255, 255, 220),  # 크림색
                        (200, 255, 220),  # 민트
                    ])
                })

    # 파티클 업데이트
    i = 0
    while i < len(recovery_light_particles):
        p = recovery_light_particles[i]
        p['x'] += p['vx']
        p['y'] += p['vy']
        p['vy'] -= 0.02  # 살짝 위로 가속
        p['life'] -= 1
        p['alpha'] = int(255 * (p['life'] / 40))
        p['size'] *= 0.98  # 점점 작아짐
        if p['life'] <= 0 or p['size'] < 0.5:
            recovery_light_particles.pop(i)
        else:
            i += 1


def draw_recovery_light_particles(screen: pygame.Surface):
    """리커버리 빛가루 파티클 그리기 - 캐시된 glow 사용"""
    global recovery_light_particles

    for p in recovery_light_particles:
        if p['alpha'] > 0 and p['size'] > 0:
            # 글로우 효과 - 캐시된 Surface 사용
            glow_size = int(p['size'] * 2)
            if glow_size > 0:
                glow_alpha = min(255, int(p['alpha'] * 0.4))
                glow_surf = get_predrawn_glow_circle(glow_size * 2, p['color'][:3], glow_alpha)
                half = glow_surf.get_width() // 2
                screen.blit(glow_surf, (int(p['x'] - half), int(p['y'] - half)))

            # 코어 - 캐시된 Surface 사용
            core_size = max(1, int(p['size']))
            core_alpha = min(255, int(p['alpha']))
            core_surf = get_predrawn_glow_circle(core_size * 2, p['color'][:3], core_alpha)
            half = core_surf.get_width() // 2
            screen.blit(core_surf, (int(p['x'] - half), int(p['y'] - half)))


def get_recovery_speed_boost_multiplier() -> float:
    """리커버리 이동속도 보너스 배율 반환 (1.0 = 보너스 없음, 1.3 = 30% 증가)"""
    if recovery_speed_boost_active:
        return 1.0 + RECOVERY_SPEED_BOOST_PERCENT
    return 1.0


def is_recovery_speed_boost_active() -> bool:
    """리커버리 이동속도 보너스 활성화 여부"""
    return recovery_speed_boost_active


def get_recovery_speed_boost_remaining_seconds() -> float:
    """리커버리 이동속도 보너스 남은 시간 (초)"""
    if recovery_speed_boost_active:
        return recovery_speed_boost_timer / 60.0
    return 0.0


def apply_recovery_effect_to_paddle(paddle_surface: pygame.Surface) -> pygame.Surface:
    """패들 이미지에 효과 적용 - 별도 처리 불필요"""
    return paddle_surface

def draw_recovery_paddle_overlay(screen: pygame.Surface, player_rect):
    """패들 주변 이펙트 - draw_recovery_effects에서 통합 처리"""
    pass


def draw_boost_charging_effect(screen: pygame.Surface):
    """부스트차징 발동 이펙트 - 주황-붉은빛 빠른 확산 효과 (0.2초)"""
    global boost_charging_effect_timer

    if boost_charging_effect_timer <= 0:
        return

    import math

    cx = boost_charging_effect_x
    cy = boost_charging_effect_y

    # 이펙트 진행률 (0.0 ~ 1.0)
    progress = 1.0 - (boost_charging_effect_timer / BOOST_CHARGING_EFFECT_DURATION)

    # 최대 반경 (빠르게 확산)
    max_radius = 120
    current_radius = max_radius * progress

    # 페이드아웃 (처음엔 밝고 점점 투명해짐)
    base_alpha = int(200 * (1.0 - progress * progress))  # 가속 페이드아웃

    # 이펙트 서피스 생성
    effect_size = int(max_radius * 2 + 40)
    effect_surf = pygame.Surface((effect_size, effect_size), pygame.SRCALPHA)
    center = effect_size // 2

    # 1. 외곽 주황-붉은빛 링 (다중 레이어)
    for i in range(4):
        layer_progress = min(1.0, progress + i * 0.05)  # 각 레이어 시간차
        layer_radius = int(max_radius * layer_progress)

        if layer_radius <= 0:
            continue

        # 색상: 주황 → 붉은색 그라데이션
        r = min(255, 255)
        g = int(150 - 80 * layer_progress)  # 주황 → 빨강
        b = int(50 - 30 * layer_progress)

        layer_alpha = max(0, int(base_alpha * (1.0 - i * 0.2)))
        thickness = max(1, 3 - i)

        if layer_alpha > 0:
            pygame.draw.circle(effect_surf, (r, g, b, layer_alpha),
                             (center, center), layer_radius, thickness)

    # 2. 내부 밝은 코어 (빠르게 확산하며 사라짐)
    core_alpha = max(0, int(180 * (1.0 - progress * 1.5)))
    if core_alpha > 0 and progress < 0.7:
        core_radius = int(current_radius * 0.4)
        if core_radius > 0:
            # 밝은 주황색 코어
            pygame.draw.circle(effect_surf, (255, 200, 100, core_alpha),
                             (center, center), core_radius)
            # 중심 흰색 하이라이트
            inner_core = int(core_radius * 0.5)
            if inner_core > 0:
                pygame.draw.circle(effect_surf, (255, 255, 200, min(255, core_alpha + 50)),
                                 (center, center), inner_core)

    # 3. 스파크 라인 (방사형으로 퍼져나감)
    num_sparks = 8
    for i in range(num_sparks):
        angle = (i / num_sparks) * math.pi * 2 + progress * 0.5
        spark_length = current_radius * 0.8

        start_dist = current_radius * 0.3
        end_dist = start_dist + spark_length

        start_x = center + math.cos(angle) * start_dist
        start_y = center + math.sin(angle) * start_dist
        end_x = center + math.cos(angle) * end_dist
        end_y = center + math.sin(angle) * end_dist

        spark_alpha = max(0, int(base_alpha * 0.7))
        if spark_alpha > 5:
            pygame.draw.line(effect_surf, (255, 180, 80, spark_alpha),
                           (int(start_x), int(start_y)),
                           (int(end_x), int(end_y)), 2)

    # 화면에 블렌딩
    screen.blit(effect_surf, (int(cx - center), int(cy - center)),
               special_flags=pygame.BLEND_ADD)


def draw_recovery_effects(screen: pygame.Surface):
    """리커버리 시각 효과 렌더링 - 고퀄리티 민트/청록 힐링 테마"""
    global recovery_effect_active, recovery_effect_timer
    global recovery_wave_rings, recovery_particles, recovery_flash_alpha
    global recovery_effect_center_x, recovery_effect_center_y

    if not recovery_effect_active:
        return

    cx = recovery_effect_center_x
    cy = recovery_effect_center_y

    import math

    # 1. 얇은 파동 링 (다중 레이어, 섬세한 선)
    for ring in recovery_wave_rings:
        if not ring['started'] or ring['alpha'] <= 0:
            continue

        ring_surf_size = int(ring['max_radius'] * 2 + 30)
        ring_surf = pygame.Surface((ring_surf_size, ring_surf_size), pygame.SRCALPHA)
        center = ring_surf_size // 2
        ring_progress = ring['radius'] / ring['max_radius']

        # 외곽 소프트 글로우 (얇고 부드럽게)
        outer_glow_alpha = max(0, ring['alpha'] // 4)
        if outer_glow_alpha > 3 and int(ring['radius']) > 2:
            pygame.draw.circle(ring_surf, (40, 180, 160, outer_glow_alpha),
                             (center, center), int(ring['radius']) + 4, 1)

        # 메인 링 - 그라데이션 효과 (3개의 얇은 동심원)
        if int(ring['radius']) > 0:
            for j in range(3):
                sub_radius = int(ring['radius']) - j * 2
                if sub_radius > 0:
                    layer_bright = j / 3
                    r = int(50 + 100 * ring_progress + 30 * layer_bright)
                    g = int(190 + 50 * ring_progress + 20 * layer_bright)
                    b = int(170 + 40 * ring_progress + 30 * layer_bright)
                    layer_alpha = max(0, int(ring['alpha'] * (0.4 + layer_bright * 0.6)))
                    pygame.draw.circle(ring_surf, (r, g, b, layer_alpha),
                                     (center, center), sub_radius, 1)

        # 내부 하이라이트 링
        inner_radius = int(ring['radius']) - 6
        if inner_radius > 0:
            highlight_alpha = max(0, ring['alpha'] // 2)
            pygame.draw.circle(ring_surf, (150, 250, 230, highlight_alpha),
                             (center, center), inner_radius, 1)

        screen.blit(ring_surf, (int(cx - center), int(cy - center)),
                   special_flags=pygame.BLEND_ADD)

    # 3. 섬세한 에너지 파티클 - 캐시된 glow 사용 (3겹 Surface 생성 제거)
    for p in recovery_particles:
        if p['alpha'] <= 5:
            continue

        if p['color_type'] == 'emerald':
            main_color = (60, 190, 165)
        elif p['color_type'] == 'gold':
            main_color = (100, 210, 180)
        else:
            main_color = (120, 210, 240)

        px, py = int(p['x']), int(p['y'])

        # 외부 glow (캐시된 Surface)
        outer_radius = max(2, int(p['size'] * 2.4))
        outer_alpha = int(p['alpha'] * 0.2)
        if outer_alpha > 0:
            outer_surf = get_predrawn_glow_circle(outer_radius * 2, main_color, outer_alpha)
            half = outer_surf.get_width() // 2
            screen.blit(outer_surf, (px - half, py - half), special_flags=pygame.BLEND_ADD)

        # 내부 glow (캐시된 Surface)
        inner_radius = max(1, int(p['size'] * 1.2))
        inner_alpha = int(p['alpha'] * 0.5)
        if inner_alpha > 0:
            inner_surf = get_predrawn_glow_circle(inner_radius * 2, main_color, inner_alpha)
            half = inner_surf.get_width() // 2
            screen.blit(inner_surf, (px - half, py - half), special_flags=pygame.BLEND_ADD)

        # 밝은 코어 (캐시된 Surface)
        if p['size'] > 1:
            core_radius = max(1, int(p['size'] * 0.4))
            core_surf = get_predrawn_glow_circle(core_radius * 2, (200, 255, 245), min(255, int(p['alpha'])))
            half = core_surf.get_width() // 2
            screen.blit(core_surf, (px - half, py - half), special_flags=pygame.BLEND_ADD)

    # 4. 중앙 코어 - 다중 레이어 광채
    if recovery_effect_timer > recovery_effect_duration - 10:
        core_progress = (recovery_effect_duration - recovery_effect_timer) / 10
        base_alpha = int(220 * (1 - core_progress * 0.4))
        core_size = int(8 + core_progress * 10)

        if base_alpha > 15:
            core_surf_size = (core_size + 20) * 2
            core_surf = pygame.Surface((core_surf_size, core_surf_size), pygame.SRCALPHA)
            core_center = core_surf_size // 2

            for i in range(4):
                glow_radius = core_size + 12 - i * 3
                if glow_radius > 0:
                    glow_alpha = max(0, base_alpha // (4 + i))
                    r = int(50 + i * 25)
                    g = int(180 + i * 20)
                    b = int(170 + i * 20)
                    pygame.draw.circle(core_surf, (r, g, b, glow_alpha),
                                     (core_center, core_center), glow_radius, 1)

            pygame.draw.circle(core_surf, (140, 250, 220, min(255, base_alpha)),
                             (core_center, core_center), max(2, core_size // 3))

            pygame.draw.circle(core_surf, (200, 255, 245, min(255, base_alpha)),
                             (core_center, core_center), max(1, core_size // 5))

            screen.blit(core_surf, (int(cx) - core_center, int(cy) - core_center),
                       special_flags=pygame.BLEND_ADD)

    # 5. 방사형 광선 (섬세한 라인)
    if recovery_effect_timer > recovery_effect_duration - 15:
        ray_progress = (recovery_effect_duration - recovery_effect_timer) / 15
        ray_alpha = int(100 * (1 - ray_progress * 0.7))

        if ray_alpha > 10:
            ray_surf_size = 160
            ray_surf = pygame.Surface((ray_surf_size, ray_surf_size), pygame.SRCALPHA)
            ray_center = ray_surf_size // 2

            num_rays = 8
            for i in range(num_rays):
                angle = (i / num_rays) * 2 * math.pi + ray_progress * 0.5
                ray_length = 40 + ray_progress * 30
                start_dist = 8
                start_x = ray_center + math.cos(angle) * start_dist
                start_y = ray_center + math.sin(angle) * start_dist
                end_x = ray_center + math.cos(angle) * ray_length
                end_y = ray_center + math.sin(angle) * ray_length

                for t in range(10):
                    t_ratio = t / 10
                    px = start_x + (end_x - start_x) * t_ratio
                    py = start_y + (end_y - start_y) * t_ratio
                    point_alpha = int(ray_alpha * (1 - t_ratio * 0.8))
                    if point_alpha > 5:
                        r = int(100 + 50 * (1 - t_ratio))
                        g = int(230 - 30 * t_ratio)
                        b = int(210 - 20 * t_ratio)
                        pygame.draw.circle(ray_surf, (r, g, b, point_alpha),
                                         (int(px), int(py)), 1)

            screen.blit(ray_surf, (int(cx) - ray_center, int(cy) - ray_center),
                       special_flags=pygame.BLEND_ADD)

