perk_leaf_shield = None  # 퍽 월계수잎 시스템 (ArenaLeafShield 인스턴스)
sacred_laurel_perk_bonus = 0  # 신성 월계수 장착 시 퍽 레벨 보너스

# 초월자의 관 스킬 보너스 (전설 아이템)
transcendent_crown_skill_bonus = 0  # 모든 투자된 스킬 레벨 +1~+3

# 현자의 반지 퍽 보너스 (패시브 아이템, 고정 +1)
sage_ring_perk_bonus = 0  # 장착 시 모든 투자된 퍽 레벨 +1

def get_runtime_skill_level(skill_id: str) -> int:
    """런타임 스킬 레벨 조회 (초월자의 관 보너스 포함)

    초월자의 관 착용 시: 이미 투자된 스킬(레벨 1 이상)에만 보너스 적용
    보너스는 max_level을 초과할 수 있음 (예: 연마 Lv.5 + 초월자의 관 +1 = Lv.6)
    """
    base_level = runtime_skill_levels.get(skill_id, 0)

    # 투자된 스킬에만 보너스 적용 (max_level 제한 없음)
    total_bonus = 0
    if transcendent_crown_skill_bonus > 0:
        total_bonus += transcendent_crown_skill_bonus
    if sage_ring_perk_bonus > 0:
        total_bonus += sage_ring_perk_bonus

    if base_level > 0 and total_bonus > 0:
        return base_level + total_bonus

    return base_level


def get_runtime_skill_description(skill_id: str, skill_data: dict, level: int) -> str:
    """런타임 스킬 설명 동적 생성 (레벨 6 이상도 지원)

    Args:
        skill_id: 스킬 ID
        skill_data: 스킬 데이터 딕셔너리
        level: 표시할 레벨 (초월자의 관 보너스 포함된 effective_level)

    Returns:
        해당 레벨에 맞는 스킬 설명 문자열
    """
    descriptions = skill_data.get("descriptions", {})
    max_level = skill_data.get("max_level", 5)

    # max_level이 -1이면 무한 레벨 (새로고침 등)
    if max_level == -1:
        return descriptions.get(1, "효과 없음")

    # 레벨이 max_level 이하면 기존 설명 사용
    if level <= max_level:
        return descriptions.get(level, descriptions.get(max_level, "효과 없음"))

    # 레벨이 max_level 초과 시 동적 생성
    # 스킬별 패턴에 따라 설명 생성
    skill_patterns = {
        # Dash Tree
        "dash_lightweight": ("대쉬 쿨타임 ", 10, "% 감소"),
        "dash_module_control": ("대쉬 후딜 ", 12, "% 감소"),
        "dash_jump": ("대쉬 거리 ", 7, "% 증가"),
        "dash_amplification": ("대쉬 토큰 +", 1, ""),
        # Item Tree
        "item_luck": ("아이템 스폰 대기 ", 10, "% 감소"),
        "item_cooldown_mastery": ("액티브 아이템 쿨타임 ", 12, "% 감소"),
        "item_gauge_mastery": ("액티브 사용시 게이지 +", 12, ""),
        "item_bag_expansion": ("액티브 슬롯 +", 1, ""),
        "item_caffeine": ("타이머형 아이템 지속 ", 20, "% 증가"),
        "item_polish": ("패시브 롤옵션 효율 ", 10, "% 증가"),
        "item_recycle": ("아이템 유지 확률 ", 7, "%"),
        # Downtown Tree
        "downtown_gamble": ("가챠 추가 1회 확률 ", 10, "%"),
        "downtown_treasure_map": ("신화 확률 +", 150, "%"),
        "downtown_bargain": ("상점 아이템 가격 ", 10, "% 할인"),
        # Common Tree
        "common_swiftness": ("이동속도 ", 5, "% 증가"),
        "common_expansion": ("장신구 슬롯 +", 1, ""),
        "common_bulk_up": ("패들 크기 ", 5, "% 증가"),
        # Smasher Exclusive
        "dash_acceleration": ("대쉬시 패들 크기 ", 70, "% 증가"),
        "dash_spirit": ("대쉬시 ", 7, "% 확률로 레이저 잔상"),
        # Optimus Exclusive
        "mecha_chain": ("게이지 감소율 ", 10, "% 감소"),
        "mecha_charge": ("충전량 +", 10, "%"),
        "mecha_bulk": ("패들 +", 5, "%"),
        "emergency_charge": ("ㄴ더블탭 ", 20, "%"),
        "reboot_enhance": ("스턴 -", 18, "%"),
        "bug_update": ("", 9, "% 재선택"),
        # Soldier Exclusive
        "soldier_magazine_mod": ("권총 최대 탄환 +", 1, ""),
    }

    if skill_id in skill_patterns:
        prefix, per_level, suffix = skill_patterns[skill_id]
        value = level * per_level
        return f"{prefix}{value}{suffix}"

    # 패턴이 없으면 최대 레벨 설명 반환
    return descriptions.get(max_level, "효과 없음")


def recalculate_transcendent_crown_effects():
    """초월자의 관 획득/강화 시 스킬 보너스 및 기존 투자된 스킬 효과 재계산

    ⚠️ 중요: 이 함수는 초월자의 관이 장착되어 있을 때만 효과를 적용합니다.
    장착되지 않은 상태에서는 스킬 보너스를 0으로 설정합니다.
    """
    global runtime_swiftness_bonus, runtime_accessory_slot_bonus, transcendent_crown_skill_bonus

    # 장착 상태 확인 - 장착되지 않으면 보너스를 0으로 리셋
    equipped_items = get_equipped_passive_items()
    equipped_names = {item.get("name") for item in equipped_items if isinstance(item, dict)}

    if "transcendent_crown" not in equipped_names:
        # 장착되지 않은 경우 스킬 보너스 비활성화
        transcendent_crown_skill_bonus = 0
        return  # 장착되지 않으면 효과 계산 스킵

    # 초월자의 관 스킬 보너스 재계산 (강화 보너스 포함)
    try:
        legendary_manager = get_legendary_manager()
        if legendary_manager:
            crown = legendary_manager.get_item("transcendent_crown")
            if crown and crown.unlocked:
                transcendent_crown_skill_bonus = crown.skill_bonus
    except Exception:
        pass

    # 신속 스킬 효과 재계산
    if runtime_skill_levels.get("common_swiftness", 0) > 0:
        effective_level = get_runtime_skill_level("common_swiftness")
        runtime_swiftness_bonus = effective_level * 0.05

    # 확장 스킬 효과 재계산
    if runtime_skill_levels.get("common_expansion", 0) > 0:
        effective_level = get_runtime_skill_level("common_expansion")
        runtime_accessory_slot_bonus = effective_level

    # 벌크업/패들 크기 재계산
    if runtime_skill_levels.get("common_bulk_up", 0) > 0 or runtime_skill_levels.get("mecha_bulk", 0) > 0:
        try:
            apply_equipment_paddle_modifiers()
        except Exception:
            pass

    # 연마 스킬 효과 재계산
    if runtime_skill_levels.get("item_polish", 0) > 0:
        try:
            apply_roll_bonuses_from_equipped()
        except Exception:
            pass

    # 탄창개조 효과 재계산
    if runtime_skill_levels.get("soldier_magazine_mod", 0) > 0:
        try:
            apply_soldier_magazine_mod()
        except Exception:
            pass

    # 경량화 스킬 효과 재계산 (대쉬 쿨타임 감소)
    # 이 스킬은 compute_dash_cooldown_seconds()에서 실시간으로 계산되므로
    # 별도 변수 업데이트 필요 없음 - get_runtime_skill_bonus가 자동으로 보너스 레벨 반영

# 장신구 슬롯 활성화 시스템 (기본 2개, 최대 4개)
