def apply_serve_result(serve_result):
    """serve_ball() 결과를 전역 상태에 반영한다."""
    global ball_vel, ball_impact_boost
    global player_collision_cooldown, boss_collision_cooldown, is_player_serve
    global optimus_charge_block_until_ms

    new_velocity = serve_result.get('ball_vel', [0.0, 0.0])
    if len(new_velocity) < 2:
        new_velocity = list(new_velocity) + [0.0] * (2 - len(new_velocity))

    ball_vel = [float(new_velocity[0]), float(new_velocity[1])]

    # 🔥 불 이벤트: 서브 시 공 기본 속도 20% 증가
    if is_fire_active():
        fire_base_boost = get_fire_base_speed_multiplier()
        ball_vel[0] *= fire_base_boost
        ball_vel[1] *= fire_base_boost
        # print(f"🔥 [불 이벤트] 서브 - 기본 속도 {(fire_base_boost-1)*100:.0f}% 증가")

    # 🛡 역경의 갑옷: 무적 발동 시 서브 속도 +20% 부스트
    try:
        from item_effects.adversity_armor import get_adversity_armor_instance
        aa = get_adversity_armor_instance()
        if aa and aa.active:
            boost = aa.consume_serve_speed_boost()
            if boost > 0:
                ball_vel[0] *= (1 + boost)
                ball_vel[1] *= (1 + boost)
                # print(f"🛡 역경의 갑옷: 서브 속도 +{boost*100:.0f}% 부스트!")
    except Exception:
        pass

    ball_impact_boost = float(serve_result.get('ball_impact_boost', 1.0))

    try:
        game_vars.ball.vel[0] = ball_vel[0]
        game_vars.ball.vel[1] = ball_vel[1]
    except Exception:
        pass

    try:
        game_state.ball_vel = [ball_vel[0], ball_vel[1]]
        game_state.ball_impact_boost = ball_impact_boost
    except Exception:
        pass

    # 옵티머스: 서브 직후 1초간 수동 충전 금지(플레이어/보스 서브 모두)
    try:
        if selected_character_type == "optimus":
            optimus_charge_block_until_ms = pygame.time.get_ticks() + 1000
    except Exception:
        pass

    # 서브 직후 패들과의 즉시 재충돌을 막아 속도 급증을 방지
    try:
        serve_cooldown_frames = 12  # 약 0.2초 (60fps 기준)
        half_cooldown = max(4, serve_cooldown_frames // 2)
        if is_player_serve:
            player_collision_cooldown = max(player_collision_cooldown, serve_cooldown_frames)
            boss_collision_cooldown = max(boss_collision_cooldown, half_cooldown)
        else:
            boss_collision_cooldown = max(boss_collision_cooldown, serve_cooldown_frames)
            player_collision_cooldown = max(player_collision_cooldown, half_cooldown)
        # 🔍 디버그: 서브 직후 속도 및 쿨다운 상태 출력
        _serve_speed = math.hypot(ball_vel[0], ball_vel[1])
        pass  # print(f"🔍 [서브 완료] 속도: {_serve_speed:.2f}, 쿨다운 설정: player={player_collision_cooldown}, boss={boss_collision_cooldown}")  # 디버그 비활성화
    except Exception:
        # 테스트 환경처럼 쿨다운 변수가 없는 경우를 대비한 가드
        pass

