arena_perk_comeback_base_skill_cd_bottom = 1.0    # 하단 기사회생 발동 전 원래 스킬쿨 배율
arena_perk_comeback_aura_timer = 0.0              # 기사회생 오오라 애니메이션 타이머
arena_freeze_frames = 0                           # 하수인 스킬 freeze 프레임 카운터
arena_battle_arena_obj = None                # ColosseumsArena 인스턴스 참조 (F8 퍽 선택용)

def apply_arena_perks_for_battle(arena_obj, top_hero_id, bottom_hero_id):
    """배틀 시작 시 hero_perks에서 멀티플라이어 계산 후 전역 변수에 반영"""
    global arena_perk_speed_mult_top, arena_perk_speed_mult_bottom
    global arena_perk_dash_cd_mult_top, arena_perk_dash_cd_mult_bottom
    global arena_perk_skill_cd_mult_top, arena_perk_skill_cd_mult_bottom
    global arena_perk_guard_cd_mult_top, arena_perk_guard_cd_mult_bottom
    global arena_guard_stance_mode
    global arena_active_hero_perks, arena_active_enemy_perks
    global arena_perk_dash_distance_mult_top, arena_perk_dash_distance_mult_bottom
    global arena_perk_retry_chance, arena_perk_retry_chance_top
    global arena_perk_guard_extra_skill_top, arena_perk_guard_extra_skill_bottom
    global arena_perk_magic_immunity_chance_top, arena_perk_magic_immunity_chance_bottom
    global arena_magic_immunity_timer_top, arena_magic_immunity_timer_bottom
    global arena_barrier_flash_top, arena_barrier_flash_bottom
    global arena_barrier_beam_target_top, arena_barrier_beam_target_bottom
    global arena_bottom_max_dash_charges, arena_top_max_dash_charges
    global arena_bottom_dash_charges, arena_top_dash_charges
    global arena_perk_paddle_enlarge_top, arena_perk_paddle_enlarge_bottom
    global arena_leaf_shield_top, arena_leaf_shield_bottom
    global arena_perk_draw_icon_func
    global arena_stance_popup_effects
    global arena_perk_recall_guard_top, arena_perk_recall_guard_bottom
    global arena_perk_instant_cooldown_chance_top, arena_perk_instant_cooldown_chance_bottom
    global arena_flash_inspiration_timer_top, arena_flash_inspiration_timer_bottom
    global arena_flash_inspiration_particles_top, arena_flash_inspiration_particles_bottom
    global arena_perk_comeback_has_top, arena_perk_comeback_has_bottom
    global arena_perk_comeback_value_top, arena_perk_comeback_value_bottom
    global arena_perk_comeback_active_top, arena_perk_comeback_active_bottom
    global arena_perk_comeback_pending_top, arena_perk_comeback_pending_bottom
    global arena_perk_comeback_base_skill_cd_top, arena_perk_comeback_base_skill_cd_bottom
    global arena_perk_comeback_aura_timer

    # 아이콘 그리기 함수 저장
    if arena_obj and hasattr(arena_obj, '_draw_perk_icon'):
        arena_perk_draw_icon_func = arena_obj._draw_perk_icon
    else:
        arena_perk_draw_icon_func = None

    # 초기화
    arena_perk_speed_mult_top = 1.0
    arena_perk_speed_mult_bottom = 1.0
    arena_perk_dash_cd_mult_top = 1.0
    arena_perk_dash_cd_mult_bottom = 1.0
    arena_perk_skill_cd_mult_top = 1.0
    arena_perk_skill_cd_mult_bottom = 1.0
    arena_perk_guard_cd_mult_top = 1.0
    arena_perk_guard_cd_mult_bottom = 1.0
    arena_guard_stance_mode = "attack"
    arena_perk_dash_distance_mult_top = 1.0
    arena_perk_dash_distance_mult_bottom = 1.0
    arena_perk_retry_chance = 0.0
    arena_perk_retry_chance_top = 0.0
    arena_perk_guard_extra_skill_top = False
    arena_perk_guard_extra_skill_bottom = False
    arena_perk_magic_immunity_chance_top = 0.0
    arena_perk_magic_immunity_chance_bottom = 0.0
    arena_magic_immunity_timer_top = 0.0
    arena_magic_immunity_timer_bottom = 0.0
    arena_barrier_block_effects.clear()
    arena_stance_popup_effects.clear()
    arena_barrier_flash_top = 0.0
    arena_barrier_flash_bottom = 0.0
    arena_barrier_beam_target_top = None
    arena_barrier_beam_target_bottom = None
    arena_perk_paddle_enlarge_top = 1.0
    arena_perk_paddle_enlarge_bottom = 1.0
    arena_leaf_shield_top = None
    arena_leaf_shield_bottom = None
    arena_perk_recall_guard_top = False
    arena_perk_recall_guard_bottom = False
    arena_perk_instant_cooldown_chance_top = 0.0
    arena_perk_instant_cooldown_chance_bottom = 0.0
    arena_flash_inspiration_timer_top = 0.0
    arena_flash_inspiration_timer_bottom = 0.0
    arena_flash_inspiration_particles_top.clear()
    arena_flash_inspiration_particles_bottom.clear()
    # 기사회생 초기화
    arena_perk_comeback_has_top = False
    arena_perk_comeback_has_bottom = False
    arena_perk_comeback_value_top = 0.70
    arena_perk_comeback_value_bottom = 0.70
    arena_perk_comeback_active_top = False
    arena_perk_comeback_active_bottom = False
    arena_perk_comeback_pending_top = False
    arena_perk_comeback_pending_bottom = False
    arena_perk_comeback_base_skill_cd_top = 1.0
    arena_perk_comeback_base_skill_cd_bottom = 1.0
    arena_perk_comeback_aura_timer = 0.0

    if not arena_obj or not hasattr(arena_obj, 'get_hero_perk_multipliers'):
        return

    # 상단 영웅 퍽
    top_mults = arena_obj.get_hero_perk_multipliers(top_hero_id)
    arena_perk_speed_mult_top = top_mults["move_speed"]
    arena_perk_dash_cd_mult_top = top_mults["dash_cooldown"]
    arena_perk_skill_cd_mult_top = top_mults["skill_cooldown"]
    arena_perk_guard_cd_mult_top = top_mults["guard_cooldown"]
    arena_perk_dash_distance_mult_top = top_mults["dash_distance"]
    arena_perk_guard_extra_skill_top = top_mults["guard_extra_skill"]
    arena_perk_magic_immunity_chance_top = top_mults["magic_immunity"]
    arena_top_max_dash_charges = 1 + top_mults["dash_tokens"]
    arena_perk_paddle_enlarge_top = top_mults["paddle_enlarge"]
    arena_perk_recall_guard_top = top_mults["recall_guard"]
    arena_perk_instant_cooldown_chance_top = top_mults["instant_cooldown"]
    arena_perk_retry_chance_top = top_mults["retry_chance"]  # 상단(상대) 반칙왕
    # 기사회생 퍽 (상단)
    if top_mults["comeback"] > 0:
        arena_perk_comeback_has_top = True
        arena_perk_comeback_value_top = top_mults["comeback"]
        # print(f"[DEBUG 기사회생] 초기화: 상단 기사회생 보유! value={arena_perk_comeback_value_top:.3f}")
    # 신성월계수 잎 (상단)
    if top_mults["laurel_shield"] > 0:
        from downtown.colosseum_arena import ArenaLeafShield
        arena_leaf_shield_top = ArenaLeafShield(is_top=True)
        arena_leaf_shield_top.activate(top_mults["laurel_shield"])

    # 하단 영웅 퍽
    bottom_mults = arena_obj.get_hero_perk_multipliers(bottom_hero_id)
    arena_perk_speed_mult_bottom = bottom_mults["move_speed"]
    arena_perk_dash_cd_mult_bottom = bottom_mults["dash_cooldown"]
    arena_perk_skill_cd_mult_bottom = bottom_mults["skill_cooldown"]
    arena_perk_guard_cd_mult_bottom = bottom_mults["guard_cooldown"]
    arena_perk_dash_distance_mult_bottom = bottom_mults["dash_distance"]
    arena_perk_guard_extra_skill_bottom = bottom_mults["guard_extra_skill"]
    arena_perk_magic_immunity_chance_bottom = bottom_mults["magic_immunity"]
    arena_perk_retry_chance = bottom_mults["retry_chance"]  # 하단(플레이어) 반칙왕
    arena_bottom_max_dash_charges = 1 + bottom_mults["dash_tokens"]
    arena_perk_paddle_enlarge_bottom = bottom_mults["paddle_enlarge"]
    arena_perk_recall_guard_bottom = bottom_mults["recall_guard"]
    arena_perk_instant_cooldown_chance_bottom = bottom_mults["instant_cooldown"]
    # 기사회생 퍽 (하단)
    if bottom_mults["comeback"] > 0:
        arena_perk_comeback_has_bottom = True
        arena_perk_comeback_value_bottom = bottom_mults["comeback"]
        # print(f"[DEBUG 기사회생] 초기화: 하단 기사회생 보유! value={arena_perk_comeback_value_bottom:.3f}")
    # 기사회생 기본 스킬쿨 배율 저장
    arena_perk_comeback_base_skill_cd_top = arena_perk_skill_cd_mult_top
    arena_perk_comeback_base_skill_cd_bottom = arena_perk_skill_cd_mult_bottom
    # print(f"[DEBUG 기사회생] 초기화 완료: base_cd_top={arena_perk_comeback_base_skill_cd_top:.3f}, base_cd_bottom={arena_perk_comeback_base_skill_cd_bottom:.3f}")
    # 신성월계수 잎 (하단)
    if bottom_mults["laurel_shield"] > 0:
        from downtown.colosseum_arena import ArenaLeafShield
        arena_leaf_shield_bottom = ArenaLeafShield(is_top=False)
        arena_leaf_shield_bottom.activate(bottom_mults["laurel_shield"])

    # 스킬 매니저 game_state에 퍽 멀티플라이어 전달
    if arena_skill_manager and hasattr(arena_skill_manager, 'game_state'):
        arena_skill_manager.game_state['perk_skill_cd_mult_top'] = arena_perk_skill_cd_mult_top
        arena_skill_manager.game_state['perk_skill_cd_mult_bottom'] = arena_perk_skill_cd_mult_bottom
        # 마법결계: 면역 확률 + 타이머 초기화
        arena_skill_manager.game_state['magic_immunity_chance_top'] = arena_perk_magic_immunity_chance_top
        arena_skill_manager.game_state['magic_immunity_chance_bottom'] = arena_perk_magic_immunity_chance_bottom
        arena_skill_manager.game_state['magic_immunity_top'] = False
        arena_skill_manager.game_state['magic_immunity_bottom'] = False
        arena_skill_manager.game_state['magic_immunity_timer_top'] = 0.0
        arena_skill_manager.game_state['magic_immunity_timer_bottom'] = 0.0
        # 번뜩이는 영감: 즉시쿨 확률 전달
        arena_skill_manager.game_state['instant_cooldown_chance_top'] = arena_perk_instant_cooldown_chance_top
        arena_skill_manager.game_state['instant_cooldown_chance_bottom'] = arena_perk_instant_cooldown_chance_bottom

    # 호위무사 시스템에 퍽 전달
    if arena_guard_system and hasattr(arena_guard_system, 'guard_cd_mult_top'):
        arena_guard_system.guard_cd_mult_top = arena_perk_guard_cd_mult_top
        arena_guard_system.guard_cd_mult_bottom = arena_perk_guard_cd_mult_bottom
    # 추가훈련 퍽: 호위무사 추가 스킬 해금
    if arena_guard_system:
        if arena_perk_guard_extra_skill_top:
            arena_guard_system.unlock_extra_skills(is_top=True)
        if arena_perk_guard_extra_skill_bottom:
            arena_guard_system.unlock_extra_skills(is_top=False)

    # 필러 표시용: 양쪽 영웅 퍽 데이터 저장
    if arena_obj and hasattr(arena_obj, 'hero_perks'):
        arena_active_hero_perks = list(arena_obj.hero_perks.get(bottom_hero_id, []))
        arena_active_enemy_perks = list(arena_obj.hero_perks.get(top_hero_id, []))
    else:
        arena_active_hero_perks = []
        arena_active_enemy_perks = []

    print(f"[ArenaPerk] 상단({top_hero_id}): 이속x{arena_perk_speed_mult_top:.2f} "
          f"대쉬쿨x{arena_perk_dash_cd_mult_top:.2f} 스킬쿨x{arena_perk_skill_cd_mult_top:.2f} "
          f"호위쿨x{arena_perk_guard_cd_mult_top:.2f} 재시작:{arena_perk_retry_chance_top:.0%}")
    print(f"[ArenaPerk] 하단({bottom_hero_id}): 이속x{arena_perk_speed_mult_bottom:.2f} "
          f"대쉬쿨x{arena_perk_dash_cd_mult_bottom:.2f} 스킬쿨x{arena_perk_skill_cd_mult_bottom:.2f} "
          f"호위쿨x{arena_perk_guard_cd_mult_bottom:.2f} 대쉬토큰:{arena_bottom_max_dash_charges} "
          f"대쉬거리x{arena_perk_dash_distance_mult_bottom:.2f} 재시작:{arena_perk_retry_chance:.0%}")

