def _arena_comeback_activate(is_top):
    """기사회생 퍽 발동: 스킬 쿨타임 대폭 감소 + 진행 중 쿨다운 즉시 감소"""
    global arena_perk_comeback_active_top, arena_perk_comeback_active_bottom
    global arena_perk_skill_cd_mult_top, arena_perk_skill_cd_mult_bottom
    global arena_perk_comeback_aura_timer
    _side = "상단" if is_top else "하단"
    # print(f"[DEBUG 기사회생] === ACTIVATE 호출 ({_side}) ===")
    # print(f"[DEBUG 기사회생]   active_top={arena_perk_comeback_active_top}, active_bottom={arena_perk_comeback_active_bottom}")
    # print(f"[DEBUG 기사회생]   has_top={arena_perk_comeback_has_top}, has_bottom={arena_perk_comeback_has_bottom}")
    # print(f"[DEBUG 기사회생]   base_skill_cd: top={arena_perk_comeback_base_skill_cd_top:.3f}, bottom={arena_perk_comeback_base_skill_cd_bottom:.3f}")
    # print(f"[DEBUG 기사회생]   current skill_cd_mult: top={arena_perk_skill_cd_mult_top:.3f}, bottom={arena_perk_skill_cd_mult_bottom:.3f}")
    # print(f"[DEBUG 기사회생]   comeback_value: top={arena_perk_comeback_value_top:.3f}, bottom={arena_perk_comeback_value_bottom:.3f}")
    if is_top:
        arena_perk_comeback_active_top = True
        old_mult = arena_perk_comeback_base_skill_cd_top
        arena_perk_skill_cd_mult_top = max(0.05, arena_perk_comeback_base_skill_cd_top - arena_perk_comeback_value_top)
        new_mult = arena_perk_skill_cd_mult_top
        # print(f"[DEBUG 기사회생]   상단 배율: {old_mult:.3f} → {new_mult:.3f}")
        if arena_skill_manager and hasattr(arena_skill_manager, 'game_state'):
            arena_skill_manager.game_state['perk_skill_cd_mult_top'] = new_mult
        # 진행 중인 스킬 쿨다운 즉시 비례 감소 (AI 영웅도 즉시 혜택)
        if arena_skill_manager and hasattr(arena_skill_manager, 'active_skills') and arena_top_hero:
            _hero_id = arena_top_hero.get("id", "")
            _skills = arena_skill_manager.active_skills.get(_hero_id, [])
            _ratio = (new_mult / old_mult) if old_mult > 0 else 0.3
            # print(f"[DEBUG 기사회생]   스킬쿨 비례감소 ratio={_ratio:.3f}, hero={_hero_id}, skills={len(_skills)}개")
            for _sk in _skills:
                if _sk.current_cooldown > 0:
                    _old_cd = _sk.current_cooldown
                    _sk.current_cooldown *= _ratio
                    # print(f"[DEBUG 기사회생]     '{getattr(_sk, 'skill_id', '?')}' cd: {_old_cd:.2f} → {_sk.current_cooldown:.2f}")
        # print(f"🔥 기사회생 발동! (상단) 스킬쿨 배율: {new_mult:.2f}")
    else:
        arena_perk_comeback_active_bottom = True
        old_mult = arena_perk_comeback_base_skill_cd_bottom
        arena_perk_skill_cd_mult_bottom = max(0.05, arena_perk_comeback_base_skill_cd_bottom - arena_perk_comeback_value_bottom)
        new_mult = arena_perk_skill_cd_mult_bottom
        # print(f"[DEBUG 기사회생]   하단 배율: {old_mult:.3f} → {new_mult:.3f}")
        if arena_skill_manager and hasattr(arena_skill_manager, 'game_state'):
            arena_skill_manager.game_state['perk_skill_cd_mult_bottom'] = new_mult
        # 진행 중인 스킬 쿨다운 즉시 비례 감소
        if arena_skill_manager and hasattr(arena_skill_manager, 'active_skills') and arena_bottom_hero:
            _hero_id = arena_bottom_hero.get("id", "")
            _skills = arena_skill_manager.active_skills.get(_hero_id, [])
            _ratio = (new_mult / old_mult) if old_mult > 0 else 0.3
            # print(f"[DEBUG 기사회생]   스킬쿨 비례감소 ratio={_ratio:.3f}, hero={_hero_id}, skills={len(_skills)}개")
            for _sk in _skills:
                if _sk.current_cooldown > 0:
                    _old_cd = _sk.current_cooldown
                    _sk.current_cooldown *= _ratio
                    # print(f"[DEBUG 기사회생]     '{getattr(_sk, 'skill_id', '?')}' cd: {_old_cd:.2f} → {_sk.current_cooldown:.2f}")
        # print(f"🔥 기사회생 발동! (하단) 스킬쿨 배율: {new_mult:.2f}")
    arena_perk_comeback_aura_timer = 0.0
    # print(f"[DEBUG 기사회생] === ACTIVATE 완료 ({_side}) ===")


def _arena_comeback_deactivate(is_top):
    """기사회생 퍽 해제: 스킬 쿨타임 원래대로 복원"""
    global arena_perk_comeback_active_top, arena_perk_comeback_active_bottom
    global arena_perk_skill_cd_mult_top, arena_perk_skill_cd_mult_bottom
    _side = "상단" if is_top else "하단"
    _was_active = arena_perk_comeback_active_top if is_top else arena_perk_comeback_active_bottom
    # print(f"[DEBUG 기사회생] DEACTIVATE 호출 ({_side}) was_active={_was_active}")
    if is_top and arena_perk_comeback_active_top:
        arena_perk_comeback_active_top = False
        _old = arena_perk_skill_cd_mult_top
        arena_perk_skill_cd_mult_top = arena_perk_comeback_base_skill_cd_top
        if arena_skill_manager and hasattr(arena_skill_manager, 'game_state'):
            arena_skill_manager.game_state['perk_skill_cd_mult_top'] = arena_perk_skill_cd_mult_top
        # print(f"[DEBUG 기사회생]   상단 배율 복원: {_old:.3f} → {arena_perk_skill_cd_mult_top:.3f} (base={arena_perk_comeback_base_skill_cd_top:.3f})")
        # print(f"🔥 기사회생 해제 (상단) 스킬쿨 배율 복원: {arena_perk_skill_cd_mult_top:.2f}")
    elif not is_top and arena_perk_comeback_active_bottom:
        arena_perk_comeback_active_bottom = False
        _old = arena_perk_skill_cd_mult_bottom
        arena_perk_skill_cd_mult_bottom = arena_perk_comeback_base_skill_cd_bottom
        if arena_skill_manager and hasattr(arena_skill_manager, 'game_state'):
            arena_skill_manager.game_state['perk_skill_cd_mult_bottom'] = arena_perk_skill_cd_mult_bottom
        # print(f"[DEBUG 기사회생]   하단 배율 복원: {_old:.3f} → {arena_perk_skill_cd_mult_bottom:.3f} (base={arena_perk_comeback_base_skill_cd_bottom:.3f})")
        # print(f"🔥 기사회생 해제 (하단) 스킬쿨 배율 복원: {arena_perk_skill_cd_mult_bottom:.2f}")
    else:
        # print(f"[DEBUG 기사회생]   ({_side}) 발동 중이 아니므로 해제 스킵")
        pass


def _draw_comeback_aura(screen, center_x, center_y, base_w, base_h, aura_timer):
    """기사회생 붉은 광채 오오라 이펙트"""
    t = aura_timer
    pulse = 0.7 + 0.3 * math.sin(t * 4.0)
    base_r = max(base_w, base_h) // 2 + 20

    # 외곽 소프트 글로우 (3겹)
    for i in range(3):
        r = int(base_r * (1.3 - i * 0.12) * (0.95 + 0.05 * math.sin(t * 3.0 + i)))
        alpha = int((25 - i * 6) * pulse)
        if alpha > 0 and r > 0:
            glow_surf = pygame.Surface((r * 2, r * 2), pygame.SRCALPHA)
            pygame.draw.circle(glow_surf, (220, 40, 30, alpha), (r, r), r)
            screen.blit(glow_surf, (center_x - r, center_y - r))

    # 중간 오오라 링 (회전하는 링)
    ring_r = int(base_r * 1.05 * pulse)
    ring_alpha = int(80 * pulse)
    if ring_r > 0 and ring_alpha > 0:
        ring_surf = pygame.Surface((ring_r * 2 + 4, ring_r * 2 + 4), pygame.SRCALPHA)
        cx_r, cy_r = ring_r + 2, ring_r + 2
        lw = max(2, int(ring_r * 0.08))
        pygame.draw.circle(ring_surf, (255, 60, 40, ring_alpha), (cx_r, cy_r), ring_r, lw)
        # 내부 링 (밝은 주황)
        inner_r = int(ring_r * 0.85)
        pygame.draw.circle(ring_surf, (255, 140, 60, int(ring_alpha * 0.5)), (cx_r, cy_r), inner_r, max(1, lw - 1))
        screen.blit(ring_surf, (center_x - ring_r - 2, center_y - ring_r - 2))

    # 불꽃 파티클 (8개가 원형으로 회전)
    num_particles = 8
    for i in range(num_particles):
        angle = t * 2.0 + i * (math.pi * 2 / num_particles)
        dist = base_r * (0.9 + 0.15 * math.sin(t * 5.0 + i * 1.5))
        px = center_x + int(math.cos(angle) * dist)
        py = center_y + int(math.sin(angle) * dist)
        p_size = max(2, int(4 + 2 * math.sin(t * 6.0 + i)))
        p_alpha = int(160 * pulse)
        if p_alpha > 0:
            p_surf = pygame.Surface((p_size * 2, p_size * 2), pygame.SRCALPHA)
            # 외곽 글로우
            pygame.draw.circle(p_surf, (255, 80, 30, p_alpha // 3), (p_size, p_size), p_size)
            # 코어
            pygame.draw.circle(p_surf, (255, 200, 80, p_alpha), (p_size, p_size), max(1, p_size // 2))
            screen.blit(p_surf, (px - p_size, py - p_size))


def show_arena_perk_select_menu():
    """F8 투기장 전용 퍽 선택 메뉴 (인게임 오버레이)"""
    global arena_battle_arena_obj, arena_bottom_hero, arena_top_hero
    global arena_perk_speed_mult_bottom, arena_perk_dash_cd_mult_bottom
    global arena_perk_skill_cd_mult_bottom, arena_perk_guard_cd_mult_bottom
    global arena_perk_dash_distance_mult_bottom, arena_perk_retry_chance
    global arena_perk_guard_extra_skill_bottom, arena_perk_magic_immunity_chance_bottom
    global arena_perk_paddle_enlarge_bottom, arena_perk_recall_guard_bottom
    global arena_bottom_max_dash_charges, arena_bottom_dash_charges

    arena_obj = arena_battle_arena_obj
    if not arena_obj or not arena_bottom_hero:
        print(f"[ArenaPerk F8] arena_obj={arena_obj}, arena_bottom_hero={arena_bottom_hero}")
        # fallback: colosseum_arena에서 직접 가져오기
        if not arena_obj:
            try:
                from downtown.colosseum_arena import ColosseumsArena
                if hasattr(ColosseumsArena, '_active_instance') and ColosseumsArena._active_instance:
                    arena_obj = ColosseumsArena._active_instance
                    arena_battle_arena_obj = arena_obj
                    print("[ArenaPerk F8] fallback으로 _active_instance 사용")
            except Exception:
                pass
        if not arena_obj or not arena_bottom_hero:
            print("[ArenaPerk F8] arena_obj 또는 arena_bottom_hero가 없음 - 복구 불가")
            return

    hero_id = arena_bottom_hero["id"]

    # --- 퍽 풀 구성 (이미 보유한 퍽 제외) ---
    from downtown.colosseum_arena import ARENA_PERK_POOL
    try:
        from downtown.hero_skills import HERO_SKILLS, HERO_SKILLS_AVAILABLE
    except ImportError:
        HERO_SKILLS = {}
        HERO_SKILLS_AVAILABLE = False

    owned_perk_ids = set()
    for perk in arena_obj.hero_perks.get(hero_id, []):
        owned_perk_ids.add(perk["id"])

    pool = []
    for p in ARENA_PERK_POOL:
        if p["id"] in owned_perk_ids:
            continue
        unlock_cond = p.get("unlock_condition")
        if unlock_cond == "has_henchman":
            if not getattr(arena_obj, 'henchman_list', []):
                continue
        pool.append(p)

    # 영웅의 미선택 스킬을 퍽 옵션으로 추가
    if HERO_SKILLS_AVAILABLE:
        if not arena_obj.hero_has_both_skills.get(hero_id, False):
            current_skill_idx = arena_obj.hero_selected_skills.get(hero_id, 0)
            other_skill_idx = 1 - current_skill_idx
            skills = HERO_SKILLS.get(hero_id, [])
            if len(skills) > other_skill_idx:
                other_skill = skills[other_skill_idx]
                skill_perk_id = f"skill_{other_skill.skill_id}"
                if skill_perk_id not in owned_perk_ids:
                    hero_color = tuple(arena_bottom_hero.get("color", (200, 200, 100)))
                    pool.append({
                        "id": skill_perk_id,
                        "name": other_skill.korean_name,
                        "description": _t("ui.extra_skill_perk", "추가 스킬 획득\n(쿨타임 20% 증가)"),
                        "icon_color": hero_color,
                        "effect_type": "add_skill",
                        "value": other_skill_idx,
                    })

    # 이미 보유한 퍽도 포함하여 전체 목록 구성 (보유 여부 표시용)
    all_perks = list(ARENA_PERK_POOL)

    # 영웅의 미선택 스킬을 퍽 옵션으로 추가
    if HERO_SKILLS_AVAILABLE:
        current_skill_idx = arena_obj.hero_selected_skills.get(hero_id, 0)
        other_skill_idx = 1 - current_skill_idx
        skills = HERO_SKILLS.get(hero_id, [])
        if len(skills) > other_skill_idx:
            other_skill = skills[other_skill_idx]
            skill_perk_id = f"skill_{other_skill.skill_id}"
            hero_color = tuple(arena_bottom_hero.get("color", (200, 200, 100)))
            all_perks.append({
                "id": skill_perk_id,
                "name": other_skill.korean_name,
                "description": "추가 스킬 획득\n(쿨타임 20% 증가)",
                "icon_color": hero_color,
                "effect_type": "add_skill",
                "value": other_skill_idx,
            })

    # 해금 조건 미충족 퍽 필터 (승급: 하수인 없으면 제외)
    filtered_perks = []
    for p in all_perks:
        unlock_cond = p.get("unlock_condition")
        if unlock_cond == "has_henchman":
            if not getattr(arena_obj, 'henchman_list', []):
                continue
        filtered_perks.append(p)

    if not filtered_perks:
        _show_arena_all_perks_owned_message()
        return

    selected_idx = 0
    scroll_offset = 0  # 스크롤 오프셋
    clock = pygame.time.Clock()

    font_title = FontStyle.subtitle()
    font_name = FontStyle.body()
    font_desc = FontStyle.small()
    font_hint = FontStyle.tiny()
    font_owned = FontStyle.tiny()

    # 아이콘 그리기 함수
    draw_icon_func = arena_perk_draw_icon_func

    # 그리드 레이아웃: 3열
    cols = 3
    card_w, card_h = 210, 150
    card_gap_x = 12
    card_gap_y = 12
    grid_top = 110  # 타이틀 아래
    grid_bottom = HEIGHT - 65  # 힌트 위
    visible_rows = (grid_bottom - grid_top + card_gap_y) // (card_h + card_gap_y)
    total_rows = (len(filtered_perks) + cols - 1) // cols
    max_scroll = max(0, total_rows - visible_rows)

    try:
        pygame.event.clear()
    except Exception:
        pass

    while True:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                import sys
                sys.exit()
            if event.type == pygame.KEYDOWN:
                if event.key == pygame.K_ESCAPE:
                    return  # 취소
                elif event.key == pygame.K_LEFT:
                    selected_idx = max(0, selected_idx - 1)
                elif event.key == pygame.K_RIGHT:
                    selected_idx = min(len(filtered_perks) - 1, selected_idx + 1)
                elif event.key == pygame.K_UP:
                    selected_idx = max(0, selected_idx - cols)
                elif event.key == pygame.K_DOWN:
                    selected_idx = min(len(filtered_perks) - 1, selected_idx + cols)
                elif event.key in (pygame.K_SPACE, pygame.K_RETURN):
                    perk = filtered_perks[selected_idx]
                    if perk["id"] not in owned_perk_ids:
                        _apply_arena_f8_perk(arena_obj, hero_id, perk)
                        return
            elif event.type == pygame.MOUSEBUTTONDOWN:
                if event.button == 1:
                    mx, my = event.pos
                    # 카드 클릭 판정
                    total_grid_w = card_w * cols + card_gap_x * (cols - 1)
                    gx = (WIDTH - total_grid_w) // 2
                    for i, perk in enumerate(filtered_perks):
                        row = i // cols
                        col = i % cols
                        vis_row = row - scroll_offset
                        if vis_row < 0 or vis_row >= visible_rows:
                            continue
                        cx = gx + col * (card_w + card_gap_x)
                        cy = grid_top + vis_row * (card_h + card_gap_y)
                        if cx <= mx <= cx + card_w and cy <= my <= cy + card_h:
                            if perk["id"] not in owned_perk_ids:
                                selected_idx = i
                                _apply_arena_f8_perk(arena_obj, hero_id, perk)
                                return
                            else:
                                selected_idx = i
                            break
                elif event.button == 4:  # 마우스 휠 위 (레거시)
                    scroll_offset = max(0, scroll_offset - 1)
                    # 선택 커서를 보이는 영역 안으로 이동
                    sel_r = selected_idx // cols
                    if sel_r >= scroll_offset + visible_rows:
                        selected_idx = min(len(filtered_perks) - 1, (scroll_offset + visible_rows - 1) * cols + selected_idx % cols)
                    elif sel_r < scroll_offset:
                        selected_idx = min(len(filtered_perks) - 1, scroll_offset * cols + selected_idx % cols)
                elif event.button == 5:  # 마우스 휠 아래 (레거시)
                    scroll_offset = min(max_scroll, scroll_offset + 1)
                    sel_r = selected_idx // cols
                    if sel_r < scroll_offset:
                        selected_idx = min(len(filtered_perks) - 1, scroll_offset * cols + selected_idx % cols)
                    elif sel_r >= scroll_offset + visible_rows:
                        selected_idx = min(len(filtered_perks) - 1, (scroll_offset + visible_rows - 1) * cols + selected_idx % cols)
            elif event.type == pygame.MOUSEWHEEL:
                if event.y > 0:  # 마우스 휠 위
                    scroll_offset = max(0, scroll_offset - 1)
                elif event.y < 0:  # 마우스 휠 아래
                    scroll_offset = min(max_scroll, scroll_offset + 1)
                # 선택 커서를 보이는 영역 안으로 이동
                sel_r = selected_idx // cols
                if sel_r < scroll_offset:
                    selected_idx = min(len(filtered_perks) - 1, scroll_offset * cols + selected_idx % cols)
                elif sel_r >= scroll_offset + visible_rows:
                    selected_idx = min(len(filtered_perks) - 1, (scroll_offset + visible_rows - 1) * cols + selected_idx % cols)

        # 선택된 항목이 보이도록 스크롤 조정
        sel_row = selected_idx // cols
        if sel_row < scroll_offset:
            scroll_offset = sel_row
        elif sel_row >= scroll_offset + visible_rows:
            scroll_offset = sel_row - visible_rows + 1
        scroll_offset = max(0, min(max_scroll, scroll_offset))

        # --- 렌더링 ---
        try:
            draw_field()
            draw_shaking_screen()
            draw_objects()
        except Exception:
            pass

        # 반투명 오버레이
        overlay = get_cached_overlay(WIDTH, HEIGHT, 180)
        SCREEN.blit(overlay, (0, 0))

        # 타이틀
        title_surf = font_title.render(_t("ui.arena_perk_select", "투기장 퍽 선택"), True, (255, 215, 0))
        title_rect = title_surf.get_rect(center=(WIDTH // 2, 45))
        SCREEN.blit(title_surf, title_rect)

        # 보유 현황
        owned_count = len(owned_perk_ids)
        total_count = len(filtered_perks)
        count_text = f"보유: {owned_count} / {total_count}"
        count_surf = font_hint.render(count_text, True, (180, 180, 180))
        count_rect = count_surf.get_rect(center=(WIDTH // 2, 80))
        SCREEN.blit(count_surf, count_rect)

        # 카드 그리드 렌더링
        total_grid_w = card_w * cols + card_gap_x * (cols - 1)
        gx = (WIDTH - total_grid_w) // 2

        for i, perk in enumerate(filtered_perks):
            row = i // cols
            col = i % cols
            vis_row = row - scroll_offset
            if vis_row < 0 or vis_row >= visible_rows:
                continue

            cx = gx + col * (card_w + card_gap_x)
            cy = grid_top + vis_row * (card_h + card_gap_y)
            is_sel = (i == selected_idx)
            is_owned = perk["id"] in owned_perk_ids

            # 카드 배경
            card_surf = pygame.Surface((card_w, card_h), pygame.SRCALPHA)
            if is_owned:
                # 이미 보유: 어두운 배경 + 체크 표시
                card_surf.fill((20, 20, 30, 200))
                border_color = (80, 80, 80, 180) if not is_sel else (120, 120, 60, 255)
                pygame.draw.rect(card_surf, border_color, (0, 0, card_w, card_h), 2, border_radius=8)
            elif is_sel:
                card_surf.fill((40, 40, 80, 220))
                pygame.draw.rect(card_surf, (255, 215, 0, 255), (0, 0, card_w, card_h), 3, border_radius=8)
            else:
                card_surf.fill((30, 30, 55, 190))
                pygame.draw.rect(card_surf, (100, 100, 160, 200), (0, 0, card_w, card_h), 2, border_radius=8)
            SCREEN.blit(card_surf, (cx, cy))

            # 퍽 아이콘
            icon_size = 36
            icon_cx = cx + card_w // 2
            icon_cy = cy + 32
            if draw_icon_func:
                try:
                    draw_icon_func(SCREEN, perk["id"], icon_cx, icon_cy, icon_size)
                except Exception:
                    pygame.draw.circle(SCREEN, perk.get("icon_color", (200, 200, 200)), (icon_cx, icon_cy), icon_size // 2)
            else:
                pygame.draw.circle(SCREEN, perk.get("icon_color", (200, 200, 200)), (icon_cx, icon_cy), icon_size // 2)

            # 보유 시 반투명 오버레이 + 체크 표시
            if is_owned:
                dim_surf = pygame.Surface((card_w, card_h), pygame.SRCALPHA)
                dim_surf.fill((0, 0, 0, 80))
                SCREEN.blit(dim_surf, (cx, cy))
                # 체크 마크
                chk_cx = cx + card_w - 18
                chk_cy = cy + 18
                pygame.draw.circle(SCREEN, (60, 180, 60), (chk_cx, chk_cy), 10)
                pygame.draw.line(SCREEN, (255, 255, 255), (chk_cx - 5, chk_cy), (chk_cx - 1, chk_cy + 4), 2)
                pygame.draw.line(SCREEN, (255, 255, 255), (chk_cx - 1, chk_cy + 4), (chk_cx + 5, chk_cy - 4), 2)

            # 퍽 이름
            if is_owned:
                name_color = (120, 120, 120)
            elif is_sel:
                name_color = (255, 255, 255)
            else:
                name_color = (200, 200, 200)
            name_surf = font_desc.render(perk["name"], True, name_color)
            name_rect = name_surf.get_rect(center=(cx + card_w // 2, cy + 68))
            SCREEN.blit(name_surf, name_rect)

            # 퍽 설명 (줄바꿈 처리, 짧게)
            desc_lines = perk["description"].split("\n")
            for j, line in enumerate(desc_lines[:2]):  # 최대 2줄
                if is_owned:
                    desc_color = (100, 100, 100)
                elif is_sel:
                    desc_color = (220, 220, 220)
                else:
                    desc_color = (150, 150, 150)
                desc_surf = font_hint.render(line, True, desc_color)
                desc_rect = desc_surf.get_rect(center=(cx + card_w // 2, cy + 92 + j * 18))
                SCREEN.blit(desc_surf, desc_rect)

            # "보유 중" 라벨
            if is_owned:
                owned_surf = font_hint.render(_t("ui.owned", "보유 중"), True, (60, 180, 60))
                owned_rect = owned_surf.get_rect(center=(cx + card_w // 2, cy + card_h - 16))
                SCREEN.blit(owned_surf, owned_rect)

            # 선택 인디케이터 (선택 + 미보유만)
            if is_sel and not is_owned:
                tri_y = cy + card_h + 4
                tri_cx = cx + card_w // 2
                pygame.draw.polygon(SCREEN, (255, 215, 0), [
                    (tri_cx, tri_y + 8),
                    (tri_cx - 6, tri_y),
                    (tri_cx + 6, tri_y),
                ])

        # 스크롤 인디케이터
        if total_rows > visible_rows:
            scroll_bar_x = gx + total_grid_w + 8
            scroll_area_h = grid_bottom - grid_top
            bar_h = max(20, int(scroll_area_h * visible_rows / total_rows))
            bar_y = grid_top + int((scroll_area_h - bar_h) * scroll_offset / max_scroll) if max_scroll > 0 else grid_top
            pygame.draw.rect(SCREEN, (60, 60, 80), (scroll_bar_x, grid_top, 4, scroll_area_h), border_radius=2)
            pygame.draw.rect(SCREEN, (150, 150, 180), (scroll_bar_x, bar_y, 4, bar_h), border_radius=2)

        # 하단 힌트
        hint_text = "방향키 선택  |  SPACE 확정  |  ESC 취소"
        hint_surf = font_hint.render(hint_text, True, (150, 150, 150))
        hint_rect = hint_surf.get_rect(center=(WIDTH // 2, HEIGHT - 40))
        SCREEN.blit(hint_surf, hint_rect)

        pygame.display.flip()
        clock.tick(30)


def _apply_arena_f8_perk(arena_obj, hero_id, selected_perk):
    """F8으로 선택한 퍽을 즉시 적용"""
    global arena_bottom_max_dash_charges, arena_bottom_dash_charges
    global arena_top_max_dash_charges, arena_top_dash_charges

    if selected_perk["effect_type"] == "add_skill":
        # 추가 스킬 획득
        arena_obj.hero_has_both_skills[hero_id] = True
        if hero_id not in arena_obj.hero_perks:
            arena_obj.hero_perks[hero_id] = []
        arena_obj.hero_perks[hero_id].append(dict(selected_perk))
        # 스킬 매니저 재초기화
        if arena_skill_manager:
            try:
                arena_skill_manager.init_hero_skills(hero_id, arena_obj.hero_selected_skills, arena_obj.hero_has_both_skills)
            except Exception as e:
                print(f"[ArenaPerk F8] 스킬 재초기화 실패: {e}")
        print(f"[ArenaPerk F8] {hero_id}에게 추가 스킬 '{selected_perk['name']}' 부여!")
    elif selected_perk["effect_type"] == "recall_guard":
        # 승급 - 첫 번째 하수인을 호위무사로 승급 (다음 라운드부터 적용)
        if hero_id not in arena_obj.hero_perks:
            arena_obj.hero_perks[hero_id] = []
        arena_obj.hero_perks[hero_id].append(dict(selected_perk))
        if arena_obj.henchman_list:
            promoted = arena_obj.henchman_list.pop(0)
            if hero_id not in arena_obj.guard_warrior_map:
                arena_obj.guard_warrior_map[hero_id] = []
            arena_obj.guard_warrior_map[hero_id].append(promoted)
            # 승급 호위무사 추적 (호위무사 선택 시 보존용)
            arena_obj.recalled_guard_map[hero_id] = promoted
            arena_obj.hero_selected_skills[promoted["id"]] = random.randint(0, 1)
            print(f"[ArenaPerk F8] 승급: 하수인 '{promoted['name']}' → 호위무사 승급!")
        print(f"[ArenaPerk F8] {hero_id}에게 '승급' 퍽 부여!")
    else:
        # 일반 퍽 추가
        if hero_id not in arena_obj.hero_perks:
            arena_obj.hero_perks[hero_id] = []
        arena_obj.hero_perks[hero_id].append(dict(selected_perk))
        print(f"[ArenaPerk F8] {hero_id}에게 '{selected_perk['name']}' 퍽 부여!")

    # 퍽 멀티플라이어 재계산
    top_hero_id = arena_top_hero["id"] if arena_top_hero else ""
    apply_arena_perks_for_battle(arena_obj, top_hero_id, hero_id)

    # 잔상술 퍽: 대쉬 토큰 수 반영 (상단/하단 모두)
    if selected_perk["effect_type"] == "dash_token":
        arena_bottom_dash_charges = arena_bottom_max_dash_charges
        arena_top_dash_charges = arena_top_max_dash_charges

    print(f"[ArenaPerk F8] 퍽 적용 완료 (총 {len(arena_obj.hero_perks.get(hero_id, []))}개)")


def _show_arena_all_perks_owned_message():
    """모든 퍽을 이미 보유 중일 때 안내 메시지"""
    font = FontStyle.body()
    clock = pygame.time.Clock()
    start_time = pygame.time.get_ticks()

    while True:
        elapsed = pygame.time.get_ticks() - start_time
        if elapsed > 1500:
            return
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                import sys
                sys.exit()
            if event.type == pygame.KEYDOWN:
                return
            if event.type == pygame.MOUSEBUTTONDOWN:
                return

        try:
            draw_field()
            draw_shaking_screen()
            draw_objects()
        except Exception:
            pass

        overlay = get_cached_overlay(WIDTH, HEIGHT, 150)
        SCREEN.blit(overlay, (0, 0))

        msg_surf = font.render(_t("ui.no_available_perks", "보유 가능한 퍽이 없습니다"), True, (255, 200, 100))
        msg_rect = msg_surf.get_rect(center=(WIDTH // 2, HEIGHT // 2))
        SCREEN.blit(msg_surf, msg_rect)

        pygame.display.flip()
        clock.tick(30)


def _draw_magic_immunity_barrier(screen, center_x, center_y, base_radius, imm_timer, imm_duration, flash_timer=0.0, beam_target=None, is_top=False):
    """마법결계 퍽 보호막 이펙트 (Ultra Premium - 고대 마법진 에너지 쉴드)"""
    if imm_timer <= 0:
        return

    current_time = pygame.time.get_ticks()
    t = current_time * 0.001  # 초 단위 시간
    elapsed = imm_duration - imm_timer

    # === 페이드인 / 페이드아웃 알파 계산 ===
    fade_in_dur = 0.6
    fade_out_dur = 1.8

    if elapsed < fade_in_dur:
        fp = elapsed / fade_in_dur
        alpha_mult = fp ** 0.4
        expand_mult = 1.0 + (1.0 - fp) * 0.5
    elif imm_timer < fade_out_dur:
        fp = imm_timer / fade_out_dur
        alpha_mult = fp
        expand_mult = 0.88 + 0.12 * fp
    else:
        alpha_mult = 1.0
        expand_mult = 1.0

    pulse = 0.85 + 0.15 * math.sin(t * 5.0)
    breath = 0.97 + 0.03 * math.sin(t * 2.3)
    base_a = int(230 * alpha_mult * pulse)
    if base_a <= 0:
        return

    # === 쉴드 크기/방향 ===
    shield_half_w = int(base_radius * 1.5 * expand_mult * breath)
    shield_curve_h = int(base_radius * 0.6 * expand_mult * breath)
    shield_inner_h = int(shield_curve_h * 0.4)
    offset_y = int(base_radius * 0.85)

    arc_dir = 1 if is_top else -1

    # === 서피스 생성 ===
    margin = 70
    surf_size = max(shield_half_w * 2, shield_curve_h + offset_y) * 2 + margin * 2
    surf = pygame.Surface((surf_size, surf_size), pygame.SRCALPHA)
    cx = surf_size // 2
    cy = surf_size // 2
    s_cy = cy + arc_dir * offset_y
    segments = 36  # 더 부드러운 곡선

    def arc_points(half_w, h, cy_base=None, seg_count=None):
        if cy_base is None:
            cy_base = s_cy
        if seg_count is None:
            seg_count = segments
        pts = []
        for i in range(seg_count + 1):
            angle = math.pi * i / seg_count
            px = cx + half_w * math.cos(angle)
            py = cy_base + arc_dir * h * math.sin(angle)
            pts.append((int(px), int(py)))
        return pts

    def arc_points_f(half_w, h, cy_base=None, seg_count=None):
        """float 버전 - 정밀 계산용"""
        if cy_base is None:
            cy_base = s_cy
        if seg_count is None:
            seg_count = segments
        pts = []
        for i in range(seg_count + 1):
            angle = math.pi * i / seg_count
            px = cx + half_w * math.cos(angle)
            py = cy_base + arc_dir * h * math.sin(angle)
            pts.append((px, py))
        return pts

    # ── 1. 외곽 대기 번짐 (5겹, 넓은 보라-청색 오라) ──
    for layer in range(5):
        gw = shield_half_w + 8 + layer * 9
        gh = shield_curve_h + 5 + layer * 7
        ga = max(0, int(base_a * (0.12 - layer * 0.02)))
        if ga > 0:
            s_val = math.sin(t * 1.8 + layer * 0.9)
            c_val = math.cos(t * 1.2 + layer * 1.3)
            r = int(100 + 60 * max(0, s_val))
            g = int(40 + 50 * max(0, c_val))
            b = int(200 + 55 * max(0, -s_val))
            outer = arc_points(gw, gh)
            inner = arc_points(gw, max(0, gh - 6 - layer * 4))
            poly = outer + inner[::-1]
            if len(poly) >= 3:
                pygame.draw.polygon(surf, (r, g, b, ga), poly)

    # ── 2. 멀티레이어 쉴드 바디 (4층 그라디언트 - 깊이감) ──
    body_layers = [
        (1.0, 1.0, 0.92, 0.25, (100, 40, 180)),    # 외곽 - 진한 보라
        (0.93, 0.92, 0.82, 0.18, (120, 60, 210)),   # 중간1 - 중간 보라
        (0.82, 0.78, 0.68, 0.15, (150, 90, 240)),    # 중간2 - 밝은 보라
        (0.68, 0.62, 0.5, 0.12, (180, 130, 255)),    # 내부 - 밝은 라벤더
    ]
    t_phase = t * 2.5
    for out_r, in_r, inner_r, alpha_ratio, base_color in body_layers:
        outer_pts = arc_points(int(shield_half_w * out_r), int(shield_curve_h * in_r))
        inner_pts_l = arc_points(int(shield_half_w * inner_r), int(shield_inner_h * in_r))
        body_poly = outer_pts + inner_pts_l[::-1]
        if len(body_poly) >= 3:
            color_shift = 0.5 + 0.5 * math.sin(t_phase + out_r * 2.0)
            br = min(255, int(base_color[0] + 30 * color_shift))
            bg = min(255, int(base_color[1] + 25 * color_shift))
            bb = min(255, int(base_color[2]))
            body_a = int(base_a * alpha_ratio)
            pygame.draw.polygon(surf, (br, bg, bb, body_a), body_poly)

    # ── 3. 프리즘 이리데센스 (무지개빛 표면 반사) ──
    prism_phase = t * 1.5
    for pi in range(3):
        p_t = (pi + 0.3) / 3.0
        p_w = int(shield_half_w * (0.5 + 0.45 * p_t))
        p_h = int(shield_curve_h * (0.55 + 0.35 * p_t))
        p_inner_w = int(p_w * 0.85)
        p_inner_h = int(shield_inner_h * (0.6 + 0.3 * p_t))

        # 이리데센스 색상 (시간에 따라 무지개처럼 변화)
        hue_shift = prism_phase + pi * 1.2 + p_t * 3.0
        ir = int(160 + 80 * math.sin(hue_shift))
        ig = int(140 + 80 * math.sin(hue_shift + 2.094))
        ib = int(200 + 55 * math.sin(hue_shift + 4.189))
        ir = max(0, min(255, ir))
        ig = max(0, min(255, ig))
        ib = max(0, min(255, ib))

        sweep = 0.5 + 0.5 * math.sin(t * 3.0 + pi * 2.5)
        ia = int(base_a * 0.08 * sweep)
        if ia > 0:
            p_outer = arc_points(p_w, p_h)
            p_inner_pts = arc_points(p_inner_w, p_inner_h)
            p_poly = p_outer + p_inner_pts[::-1]
            if len(p_poly) >= 3:
                pygame.draw.polygon(surf, (ir, ig, ib, ia), p_poly)

    # ── 4. 표면 에너지 웨이브 (흐르는 곡선 파동 8개) ──
    for wi in range(8):
        wt = (wi + 0.5) / 8
        wave_pulse = 0.5 + 0.5 * math.sin(t * 7.0 + wi * 1.2)
        wa = int(base_a * 0.18 * wave_pulse)
        if wa > 0:
            w_h = shield_inner_h + (shield_curve_h - shield_inner_h) * wt
            w_half_w = int(shield_half_w * (0.88 + 0.12 * wt))
            wave_off = 3.0 * math.sin(t * 4.5 + wi * 2.0)
            wave_drift = 1.5 * math.cos(t * 3.2 + wi * 1.7)
            pts = []
            for j in range(segments + 1):
                angle = math.pi * j / segments
                micro_wave = 1.5 * math.sin(angle * 5.0 + t * 8.0 + wi * 0.8)
                px = cx + (w_half_w + wave_drift) * math.cos(angle)
                py = s_cy + arc_dir * (w_h * math.sin(angle) + wave_off + micro_wave)
                pts.append((int(px), int(py)))
            if len(pts) >= 2:
                # 파동 색상 그라디언트 (위치에 따라)
                wr = int(140 + 70 * wt)
                wg = int(80 + 60 * (1.0 - wt))
                wb = 255
                pygame.draw.lines(surf, (wr, wg, wb, wa), False, pts, 1)

    # ── 5. 마법진 패턴 (회전하는 헥사곤 + 룬 문양) ──
    rune_rot = t * 0.8  # 천천히 회전
    rune_center_y = s_cy + arc_dir * int(shield_curve_h * 0.45)
    rune_radius = int(shield_half_w * 0.35)
    rune_a = int(base_a * 0.35)

    if rune_a > 0:
        # 외곽 헥사곤
        hex_pts = []
        for hi in range(6):
            h_angle = rune_rot + hi * math.pi / 3.0
            hx = cx + rune_radius * math.cos(h_angle)
            hy = rune_center_y + arc_dir * rune_radius * 0.5 * math.sin(h_angle)
            hex_pts.append((int(hx), int(hy)))
        if len(hex_pts) >= 3:
            pygame.draw.polygon(surf, (160, 120, 255, rune_a // 3), hex_pts)
            pygame.draw.lines(surf, (180, 150, 255, rune_a), True, hex_pts, 1)

        # 내곽 역헥사곤 (반대 방향 회전)
        inner_hex = []
        inner_r = int(rune_radius * 0.55)
        for hi in range(6):
            h_angle = -rune_rot * 1.3 + hi * math.pi / 3.0
            hx = cx + inner_r * math.cos(h_angle)
            hy = rune_center_y + arc_dir * inner_r * 0.5 * math.sin(h_angle)
            inner_hex.append((int(hx), int(hy)))
        if len(inner_hex) >= 3:
            pygame.draw.lines(surf, (200, 170, 255, rune_a), True, inner_hex, 1)

        # 다윗의 별 (두 삼각형 - 신비로운 문양)
        for tri_offset in [0, math.pi / 6.0]:
            tri_pts = []
            tri_r = int(rune_radius * 0.78)
            for ti in range(3):
                t_angle = rune_rot * 0.6 + tri_offset + ti * math.pi * 2.0 / 3.0
                tx = cx + tri_r * math.cos(t_angle)
                ty = rune_center_y + arc_dir * tri_r * 0.4 * math.sin(t_angle)
                tri_pts.append((int(tx), int(ty)))
            if len(tri_pts) >= 3:
                pygame.draw.lines(surf, (190, 160, 255, int(rune_a * 0.7)), True, tri_pts, 1)

        # 룬 정점 발광
        for hi in range(6):
            h_angle = rune_rot + hi * math.pi / 3.0
            hx = cx + rune_radius * math.cos(h_angle)
            hy = rune_center_y + arc_dir * rune_radius * 0.5 * math.sin(h_angle)
            glow_pulse = 0.5 + 0.5 * math.sin(t * 6.0 + hi * 1.05)
            ga = int(rune_a * glow_pulse)
            if ga > 0:
                pygame.draw.circle(surf, (220, 200, 255, ga), (int(hx), int(hy)), 3)
                pygame.draw.circle(surf, (170, 130, 255, ga // 3), (int(hx), int(hy)), 6)

        # 중심 코어 (밝은 에너지 포인트)
        core_pulse = 0.7 + 0.3 * math.sin(t * 4.0)
        core_a = int(rune_a * core_pulse)
        pygame.draw.circle(surf, (240, 230, 255, core_a), (cx, rune_center_y), 4)
        pygame.draw.circle(surf, (200, 170, 255, core_a // 2), (cx, rune_center_y), 8)
        pygame.draw.circle(surf, (160, 120, 255, core_a // 4), (cx, rune_center_y), 13)

    # ── 6. 외곽 엣지 더블 림 (밝은 이중 테두리 + 내부 글로우) ──
    # 외곽 밝은 테두리 (3겹)
    for ei in range(3):
        ea = max(0, int(base_a * (0.7 - ei * 0.18)))
        if ea > 0:
            p = t * 3.5 + ei * 0.7
            er = int(180 + 60 * math.sin(p))
            eg = int(130 + 60 * math.sin(p + 2.0))
            eb = min(255, int(230 + 25 * math.sin(p + 4.0)))
            edge = arc_points(shield_half_w + ei * 2, shield_curve_h + ei * 2)
            if len(edge) >= 2:
                pygame.draw.lines(surf, (er, eg, eb, ea), False, edge, max(1, 3 - ei))

    # 내곽 테두리 (부드러운 글로우)
    for ie_i in range(2):
        ie_a = int(base_a * (0.3 - ie_i * 0.1))
        if ie_a > 0:
            ie_scale = 0.90 - ie_i * 0.05
            ie = arc_points(int(shield_half_w * ie_scale), int(shield_inner_h * (1.0 + ie_i * 0.1)))
            if len(ie) >= 2:
                ie_color_shift = math.sin(t * 2.8 + ie_i * 1.5)
                ie_r = int(140 + 40 * ie_color_shift)
                ie_b = int(230 + 25 * ie_color_shift)
                pygame.draw.lines(surf, (ie_r, 80, ie_b, ie_a), False, ie, 1)

    # ── 7. 전기 아크 (테두리 따라 번개 효과) ──
    arc_count = 4
    for ai in range(arc_count):
        arc_phase = (t * 2.0 + ai * 0.25) % 1.0
        arc_start = arc_phase
        arc_len = 0.12 + 0.06 * math.sin(t * 12.0 + ai * 3.0)
        arc_a = int(base_a * (0.4 + 0.4 * max(0, math.sin(t * 15.0 + ai * 4.0))))
        if arc_a > 0:
            arc_pts = []
            num_seg = 8
            for si in range(num_seg + 1):
                frac = arc_start + arc_len * si / num_seg
                frac = max(0.0, min(1.0, frac))
                a_angle = math.pi * frac
                base_x = cx + (shield_half_w + 1) * math.cos(a_angle)
                base_y = s_cy + arc_dir * (shield_curve_h + 1) * math.sin(a_angle)
                # 번개 지그재그
                if 0 < si < num_seg:
                    jitter = 4.0 * math.sin(t * 25.0 + si * 7.3 + ai * 11.0)
                    norm_x = -math.sin(a_angle)
                    norm_y = arc_dir * math.cos(a_angle)
                    base_x += norm_x * jitter
                    base_y += norm_y * jitter
                arc_pts.append((int(base_x), int(base_y)))
            if len(arc_pts) >= 2:
                pygame.draw.lines(surf, (200, 180, 255, arc_a), False, arc_pts, 1)
                # 밝은 코어
                core_a = min(255, int(arc_a * 1.3))
                for pk in range(len(arc_pts) - 1):
                    mid_x = (arc_pts[pk][0] + arc_pts[pk + 1][0]) // 2
                    mid_y = (arc_pts[pk][1] + arc_pts[pk + 1][1]) // 2
                    pygame.draw.circle(surf, (230, 220, 255, core_a // 2), (mid_x, mid_y), 1)

    # ── 8. 이동하는 반사 포인트 (5개, 더 화려한 발광) ──
    for ri in range(5):
        rune_phase = (t * 0.9 + ri * 0.2) % 1.0
        rune_angle = math.pi * rune_phase
        rx = cx + (shield_half_w + 2) * math.cos(rune_angle)
        ry = s_cy + arc_dir * (shield_curve_h + 2) * math.sin(rune_angle)
        glow_cycle = 0.5 + 0.5 * math.sin(t * 12.0 + ri * 2.5)
        ra = int(base_a * (0.5 + 0.4 * glow_cycle))
        rsz = int(2 + 2.0 * glow_cycle)
        if ra > 0 and rsz > 0:
            # 3단계 발광 (외곽 → 중간 → 코어)
            pygame.draw.circle(surf, (140, 100, 240, ra // 4), (int(rx), int(ry)), rsz + 7)
            pygame.draw.circle(surf, (190, 160, 255, ra // 2), (int(rx), int(ry)), rsz + 3)
            pygame.draw.circle(surf, (235, 220, 255, ra), (int(rx), int(ry)), rsz)

    # ── 9. 엣지 파티클 (10개, 꼬리 있는 발광 입자) ──
    for pi_idx in range(10):
        p_t = (t * 1.2 + pi_idx * 0.1) % 1.0
        p_angle = math.pi * p_t
        p_drift = 5 * math.sin(t * 5.5 + pi_idx * 1.6)
        p_rise = 3 * math.cos(t * 3.8 + pi_idx * 2.1)
        px = cx + (shield_half_w + 6 + p_drift) * math.cos(p_angle)
        py = s_cy + arc_dir * (shield_curve_h + 6 + p_drift + p_rise) * math.sin(p_angle)
        p_brightness = 0.5 + 0.5 * math.sin(t * 10.0 + pi_idx * 1.3)
        pa = int(base_a * (0.3 + 0.35 * p_brightness))
        psz = max(1, int(1 + 2 * p_brightness))

        if pa > 0 and psz > 0:
            # 색상 변조 (청보라 ↔ 분홍보라)
            color_shift = math.sin(t * 4.0 + pi_idx * 0.9)
            pr = int(160 + 60 * max(0, color_shift))
            pg = int(80 + 40 * max(0, -color_shift))
            pb_c = 255

            # 파티클 꼬리 (이전 위치 2개)
            for trail in range(2):
                trail_angle = math.pi * ((t * 1.2 + pi_idx * 0.1 - (trail + 1) * 0.015) % 1.0)
                trail_x = cx + (shield_half_w + 6 + p_drift) * math.cos(trail_angle)
                trail_y = s_cy + arc_dir * (shield_curve_h + 6 + p_drift) * math.sin(trail_angle)
                trail_a = pa // (3 + trail * 2)
                trail_sz = max(1, psz - trail)
                if trail_a > 0:
                    pygame.draw.circle(surf, (pr, pg, pb_c, trail_a), (int(trail_x), int(trail_y)), trail_sz)

            # 메인 파티클
            pygame.draw.circle(surf, (pr, pg, pb_c, pa), (int(px), int(py)), psz)
            pygame.draw.circle(surf, (220, 200, 255, int(pa * 0.6)), (int(px), int(py)), max(1, psz - 1))

    # ── 10. 쉴드 표면 라이트 스윕 (좌→우 이동하는 광택 반사) ──
    sweep_pos = (math.sin(t * 2.0) + 1.0) * 0.5  # 0~1 좌우 왕복
    sweep_x = cx - shield_half_w + int(shield_half_w * 2 * sweep_pos)
    sweep_w = int(shield_half_w * 0.3)
    sweep_a = int(base_a * 0.10)
    if sweep_a > 0:
        for sw_i in range(segments + 1):
            sw_angle = math.pi * sw_i / segments
            sw_px = cx + shield_half_w * 0.95 * math.cos(sw_angle)
            sw_dist = abs(sw_px - sweep_x)
            if sw_dist < sweep_w:
                sw_intensity = 1.0 - sw_dist / sweep_w
                sw_outer_y = s_cy + arc_dir * shield_curve_h * 0.95 * math.sin(sw_angle)
                sw_inner_y = s_cy + arc_dir * shield_inner_h * math.sin(sw_angle)
                sw_alpha = int(sweep_a * sw_intensity * sw_intensity)
                if sw_alpha > 0:
                    pygame.draw.line(surf, (220, 200, 255, sw_alpha),
                                     (int(sw_px), int(sw_outer_y)), (int(sw_px), int(sw_inner_y)), 1)

    # ── 11. 페이드인 확산 효과 (마법진 전개 + 쉴드 형성) ──
    if elapsed < fade_in_dur:
        rp = elapsed / fade_in_dur
        # 확산하는 쉴드 윤곽
        exp_w = int(shield_half_w * (0.2 + rp * 0.8))
        exp_h = int(shield_curve_h * (0.2 + rp * 0.8))
        exp_a = int(200 * (1.0 - rp))
        if exp_a > 0:
            exp_pts = arc_points(exp_w, exp_h)
            if len(exp_pts) >= 2:
                pygame.draw.lines(surf, (210, 180, 255, exp_a), False, exp_pts, 3)
            # 두 번째 확산파
            exp2_w = int(shield_half_w * (0.1 + rp * 1.1))
            exp2_h = int(shield_curve_h * (0.1 + rp * 1.1))
            exp2_a = int(120 * max(0, 1.0 - rp * 1.5))
            if exp2_a > 0:
                exp2_pts = arc_points(exp2_w, exp2_h)
                if len(exp2_pts) >= 2:
                    pygame.draw.lines(surf, (180, 140, 255, exp2_a), False, exp2_pts, 2)

        # 중심 플래시 폭발
        fl_a = int(160 * (1.0 - rp) ** 1.5)
        if fl_a > 0:
            mid_y = s_cy + arc_dir * int(shield_curve_h * 0.4)
            flash_r = int(shield_half_w * 0.4 * rp)
            pygame.draw.circle(surf, (230, 210, 255, fl_a), (cx, mid_y), flash_r)
            pygame.draw.circle(surf, (255, 245, 255, min(255, fl_a * 2)), (cx, mid_y), max(1, flash_r // 3))

        # 방사형 라인 (마법진 전개)
        if rp < 0.7:
            line_a = int(140 * (1.0 - rp / 0.7))
            mid_y = s_cy + arc_dir * int(shield_curve_h * 0.4)
            for li in range(8):
                l_angle = li * math.pi / 4.0 + rp * math.pi
                l_len = int(shield_half_w * 0.6 * rp)
                lx = cx + l_len * math.cos(l_angle)
                ly = mid_y + arc_dir * l_len * 0.4 * math.sin(l_angle)
                if line_a > 0:
                    pygame.draw.line(surf, (190, 160, 255, line_a), (cx, mid_y), (int(lx), int(ly)), 1)

    # ── 12. 페이드아웃 깜빡임 + 파편화 효과 ──
    if imm_timer < fade_out_dur:
        fo_p = imm_timer / fade_out_dur
        # 깜빡임
        flicker = abs(math.sin(t * 18.0))
        fl_a = int(90 * fo_p * flicker)
        if fl_a > 0:
            fl_pts = arc_points(shield_half_w + 3, shield_curve_h + 3)
            if len(fl_pts) >= 2:
                pygame.draw.lines(surf, (200, 150, 255, fl_a), False, fl_pts, 2)
        # 파편 분리 효과 (소멸 시 쉴드 조각이 떨어져 나감)
        if fo_p < 0.5:
            frag_intensity = 1.0 - fo_p * 2.0
            for fi in range(6):
                f_angle = math.pi * (fi + 0.5) / 6.0
                f_dist = int((1.0 - fo_p * 2.0) * 8 + 3)
                f_x = cx + (shield_half_w + f_dist) * math.cos(f_angle)
                f_y = s_cy + arc_dir * (shield_curve_h + f_dist) * math.sin(f_angle)
                f_a = int(100 * frag_intensity * abs(math.sin(t * 20.0 + fi * 2.0)))
                if f_a > 0:
                    pygame.draw.circle(surf, (180, 140, 255, f_a), (int(f_x), int(f_y)), 2)

    screen.blit(surf, (center_x - cx, center_y - cy))

    # ── 13. 스킬 차단 플래시 (Ultra Premium - 다층 충격파) ──
    if flash_timer > 0:
        f_elapsed = 1.0 - flash_timer / ARENA_BARRIER_FLASH_DURATION
        _peak = 0.12
        if f_elapsed < _peak:
            fl_intensity = (f_elapsed / _peak) ** 0.5
        else:
            fl_intensity = ((1.0 - f_elapsed) / (1.0 - _peak)) ** 2.0

        fl_surf = pygame.Surface((surf_size, surf_size), pygame.SRCALPHA)
        fl_cx = surf_size // 2
        fl_cy = surf_size // 2
        fl_s_cy = fl_cy + arc_dir * offset_y

        def fl_arc(hw, h):
            pts = []
            for i in range(segments + 1):
                angle = math.pi * i / segments
                px = fl_cx + hw * math.cos(angle)
                py = fl_s_cy + arc_dir * h * math.sin(angle)
                pts.append((int(px), int(py)))
            return pts

        fw = int(shield_half_w * (1.0 + f_elapsed * 0.35))
        fh = int(shield_curve_h * (1.0 + f_elapsed * 0.35))
        fi_h = int(shield_inner_h * (1.0 + f_elapsed * 0.25))

        # 1차: 백색-보라 쉴드 형상 플래시
        f_outer = fl_arc(fw, fh)
        f_inner = fl_arc(int(fw * 0.88), fi_h)
        f_poly = f_outer + f_inner[::-1]
        w_a = int(200 * fl_intensity)
        if len(f_poly) >= 3 and w_a > 0:
            pygame.draw.polygon(fl_surf, (240, 220, 255, w_a), f_poly)

        # 2차: 내부 밝은 코어 플래시
        core_fw = int(fw * 0.6)
        core_fh = int(fh * 0.6)
        core_fi = int(fi_h * 0.5)
        c_outer = fl_arc(core_fw, core_fh)
        c_inner = fl_arc(core_fw - 5, core_fi)
        c_poly = c_outer + c_inner[::-1]
        ca = int(160 * fl_intensity)
        if len(c_poly) >= 3 and ca > 0:
            pygame.draw.polygon(fl_surf, (255, 250, 255, ca), c_poly)

        # 테두리 이중 링
        for ring_i in range(2):
            ring_a = int((250 - ring_i * 60) * fl_intensity)
            if ring_a > 0:
                ring_pts = fl_arc(fw + 2 + ring_i * 4, fh + 2 + ring_i * 4)
                if len(ring_pts) >= 2:
                    ring_th = max(2, int((4 - ring_i) * fl_intensity))
                    r_color = (220 - ring_i * 30, 180 - ring_i * 30, 255)
                    pygame.draw.lines(fl_surf, (*r_color, ring_a), False, ring_pts, ring_th)

        # 다층 확산 충격파 (3파)
        for wave_i in range(3):
            w_delay = wave_i * 0.08
            w_elapsed = max(0, f_elapsed - w_delay)
            w_ratio = min(1.0, w_elapsed / (1.0 - w_delay)) if (1.0 - w_delay) > 0 else 0
            exp_fw = int(shield_half_w * (1.0 + w_ratio * (0.6 + wave_i * 0.3)))
            exp_fh = int(shield_curve_h * (1.0 + w_ratio * (0.6 + wave_i * 0.3)))
            exp_a = int((130 - wave_i * 30) * fl_intensity * max(0, 1.0 - w_ratio * 0.8))
            if exp_a > 0:
                exp_pts = fl_arc(exp_fw, exp_fh)
                if len(exp_pts) >= 2:
                    exp_th = max(1, int((3 - wave_i) * fl_intensity))
                    pygame.draw.lines(fl_surf, (190 + wave_i * 20, 150 + wave_i * 20, 255, exp_a), False, exp_pts, exp_th)

        # 차단 지점 스파크 (쉴드 중심에서 불꽃)
        mid_flash_y = fl_s_cy + arc_dir * int(shield_curve_h * 0.45)
        spark_a = int(220 * fl_intensity)
        if spark_a > 0:
            for si in range(8):
                s_angle = si * math.pi / 4.0 + f_elapsed * math.pi * 4.0
                s_len = int(15 * fl_intensity * (1.0 + f_elapsed * 0.5))
                sx = fl_cx + s_len * math.cos(s_angle)
                sy = mid_flash_y + s_len * math.sin(s_angle)
                pygame.draw.line(fl_surf, (230, 210, 255, spark_a // 2), (fl_cx, mid_flash_y), (int(sx), int(sy)), 1)
            pygame.draw.circle(fl_surf, (255, 250, 255, min(255, spark_a)), (fl_cx, mid_flash_y), max(1, int(5 * fl_intensity)))

        screen.blit(fl_surf, (center_x - fl_cx, center_y - fl_cy))

    # ── 14. 등대빔 효과 (Ultra Premium - 다층 광선 + 임팩트 이펙트) ──
    if flash_timer > 0 and beam_target is not None:
        beam_tx, beam_ty = beam_target
        beam_sx = center_x
        beam_sy = center_y + arc_dir * offset_y + arc_dir * int(shield_curve_h * 0.5)
        dx = beam_tx - beam_sx
        dy = beam_ty - beam_sy
        dist = math.sqrt(dx * dx + dy * dy)
        if dist > 10:
            angle = math.atan2(dy, dx)
            b_elapsed = 1.0 - flash_timer / ARENA_BARRIER_FLASH_DURATION
            _peak = 0.12
            if b_elapsed < _peak:
                fl_intensity = (b_elapsed / _peak) ** 0.5
            else:
                fl_intensity = ((1.0 - b_elapsed) / (1.0 - _peak)) ** 2.0

            beam_surf = pygame.Surface((760, 750), pygame.SRCALPHA)
            perp_cos = math.cos(angle + math.pi / 2)
            perp_sin = math.sin(angle + math.pi / 2)
            cos_a = math.cos(angle)
            sin_a = math.sin(angle)

            # 5층 광선 (외곽부터 코어까지)
            for layer, (near_w, far_w, color, alpha_mult) in enumerate([
                (24, 80, (100, 60, 220), 0.15),   # 최외곽 번짐
                (18, 60, (130, 90, 245), 0.25),    # 외곽
                (12, 42, (160, 130, 255), 0.4),    # 중간
                (6, 24, (200, 180, 255), 0.6),     # 내부
                (2, 10, (245, 240, 255), 0.9),     # 코어
            ]):
                beam_alpha = int(alpha_mult * 255 * fl_intensity)
                if beam_alpha <= 0:
                    continue
                nl = (beam_sx + perp_cos * near_w, beam_sy + perp_sin * near_w)
                nr = (beam_sx - perp_cos * near_w, beam_sy - perp_sin * near_w)
                fx = beam_sx + cos_a * dist
                fy = beam_sy + sin_a * dist
                fl_pt = (fx + perp_cos * far_w, fy + perp_sin * far_w)
                fr_pt = (fx - perp_cos * far_w, fy - perp_sin * far_w)
                points = [(int(nl[0]), int(nl[1])), (int(fl_pt[0]), int(fl_pt[1])),
                          (int(fr_pt[0]), int(fr_pt[1])), (int(nr[0]), int(nr[1]))]
                pygame.draw.polygon(beam_surf, (*color, beam_alpha), points)

            # 임팩트 다층 글로우
            impact_a = int(200 * fl_intensity)
            if impact_a > 0:
                ex, ey = int(beam_tx), int(beam_ty)
                pygame.draw.circle(beam_surf, (120, 80, 230, impact_a // 5), (ex, ey), 50, 0)
                pygame.draw.circle(beam_surf, (150, 110, 245, impact_a // 4), (ex, ey), 35, 0)
                pygame.draw.circle(beam_surf, (180, 150, 255, impact_a // 3), (ex, ey), 24, 0)
                pygame.draw.circle(beam_surf, (215, 195, 255, impact_a // 2), (ex, ey), 14, 0)
                pygame.draw.circle(beam_surf, (245, 240, 255, impact_a), (ex, ey), 6, 0)

                # 임팩트 스파크 방사
                for si in range(6):
                    s_angle = si * math.pi / 3.0 + b_elapsed * math.pi * 3.0
                    s_len = int(20 * fl_intensity)
                    sx = ex + s_len * math.cos(s_angle)
                    sy = ey + s_len * math.sin(s_angle)
                    pygame.draw.line(beam_surf, (210, 190, 255, impact_a // 2), (ex, ey), (int(sx), int(sy)), 1)

            screen.blit(beam_surf, (0, 0))


def _spawn_barrier_block_effect(caster_x, caster_y, target_x, target_y,
                                 skill_name, caster_is_top, hero_color=None):
    """마법결계에 의해 차단된 스킬의 '잠깐 보였다가 녹아 사라지는' 이펙트 생성"""
    global arena_barrier_flash_top, arena_barrier_flash_bottom
    global arena_barrier_beam_target_top, arena_barrier_beam_target_bottom

    # 결계 번쩍임 트리거 + 등대빔 타겟 설정 (방어한 쪽)
    if caster_is_top:
        # 시전자가 상단이면, 방어한 건 하단 → 하단 결계가 상단 시전자를 비춤
        arena_barrier_flash_bottom = ARENA_BARRIER_FLASH_DURATION
        arena_barrier_beam_target_bottom = (caster_x, caster_y)
    else:
        # 시전자가 하단이면, 방어한 건 상단 → 상단 결계가 하단 시전자를 비춤
        arena_barrier_flash_top = ARENA_BARRIER_FLASH_DURATION
        arena_barrier_beam_target_top = (caster_x, caster_y)

    # 패링 사운드 재생
    try:
        if not hasattr(_spawn_barrier_block_effect, '_parry_sound') or getattr(_spawn_barrier_block_effect, '_parry_sound_file', '') != 'magicdefense.wav':
            import os as _os
            _parry_path = resource_path(_os.path.join("sounds", "magicdefense.wav"))
            _spawn_barrier_block_effect._parry_sound_file = 'magicdefense.wav'
            if _os.path.exists(_parry_path):
                _spawn_barrier_block_effect._parry_sound = pygame.mixer.Sound(_parry_path)
                _spawn_barrier_block_effect._parry_sound.set_volume(0.5)
            else:
                _spawn_barrier_block_effect._parry_sound = None
        if _spawn_barrier_block_effect._parry_sound:
            _spawn_barrier_block_effect._parry_sound.play()
    except Exception:
        pass

    color = hero_color if hero_color else (180, 80, 220)
    # 투사체가 시전자→타겟 방향으로 40% 정도 이동 후 녹아 사라짐
    mid_x = caster_x + (target_x - caster_x) * 0.35
    mid_y = caster_y + (target_y - caster_y) * 0.35

    # 녹아내리는 파티클 미리 생성
    particles = []
    for i in range(18):
        angle = random.uniform(0, 2 * math.pi)
        speed = random.uniform(30, 100)
        particles.append({
            'x': 0.0, 'y': 0.0,
            'vx': math.cos(angle) * speed,
            'vy': math.sin(angle) * speed + random.uniform(-20, 20),
            'size': random.uniform(3, 8),
            'alpha': 255,
            'color': (
                min(255, color[0] + random.randint(-30, 50)),
                min(255, color[1] + random.randint(-30, 50)),
                min(255, color[2] + random.randint(-30, 50))
            ),
            'decay': random.uniform(200, 400),
        })

    effect = {
        'caster_x': caster_x, 'caster_y': caster_y,
        'target_x': target_x, 'target_y': target_y,
        'mid_x': mid_x, 'mid_y': mid_y,
        'skill_name': skill_name,
        'caster_is_top': caster_is_top,
        'color': color,
        'timer': 0.0,
        'phase': 'launch',          # 'launch' → 'dissolve'
        'launch_duration': 0.3,     # 투사체 이동 시간 (초)
        'dissolve_duration': 0.55,  # 녹아내리는 시간 (초)
        'proj_x': float(caster_x),
        'proj_y': float(caster_y),
        'proj_size': 18.0,
        'proj_alpha': 255,
        'particles': particles,
        'dissolve_started': False,
        'proj_wobble': 0.0,
    }
    arena_barrier_block_effects.append(effect)


def _spawn_flash_inspiration_particles(is_top):
    """번뜩이는 영감 발동 시 반짝임 파티클 생성"""
    global arena_flash_inspiration_particles_top, arena_flash_inspiration_particles_bottom
    particles = []
    for _ in range(30):
        angle = random.uniform(0, math.pi * 2)
        speed = random.uniform(40, 120)
        life = random.uniform(0.3, 0.6)
        particles.append({
            'ox': random.uniform(-15, 15),
            'oy': random.uniform(-15, 15),
            'vx': math.cos(angle) * speed,
            'vy': math.sin(angle) * speed,
            'life': life,
            'max_life': life,
            'size': random.uniform(2, 6),
            'color_idx': random.randint(0, 2),
        })
    if is_top:
        arena_flash_inspiration_particles_top = particles
    else:
        arena_flash_inspiration_particles_bottom = particles


def _update_flash_inspiration(dt):
    """번뜩이는 영감 타이머 + 파티클 업데이트"""
    global arena_flash_inspiration_timer_top, arena_flash_inspiration_timer_bottom
    if arena_flash_inspiration_timer_top > 0:
        arena_flash_inspiration_timer_top = max(0.0, arena_flash_inspiration_timer_top - dt)
    if arena_flash_inspiration_timer_bottom > 0:
        arena_flash_inspiration_timer_bottom = max(0.0, arena_flash_inspiration_timer_bottom - dt)
    for plist in (arena_flash_inspiration_particles_top, arena_flash_inspiration_particles_bottom):
        to_remove = []
        for p in plist:
            p['life'] -= dt
            if p['life'] <= 0:
                to_remove.append(p)
                continue
            p['ox'] += p['vx'] * dt
            p['oy'] += p['vy'] * dt
            p['vx'] *= 0.95
            p['vy'] *= 0.95
        for p in to_remove:
            plist.remove(p)


_INSP_COLORS = [(0, 255, 130), (120, 255, 200), (50, 255, 160)]

def _draw_flash_inspiration_effect(screen, cx, cy, draw_w, draw_h, timer, particles):
    """번뜩이는 영감 반짝임 이펙트 렌더링"""
    if timer <= 0 and not particles:
        return
    progress = timer / ARENA_FLASH_INSPIRATION_DURATION if ARENA_FLASH_INSPIRATION_DURATION > 0 else 0
    base_r = max(draw_w, draw_h) // 2 + 20

    if timer > 0:
        if progress > 0.7:
            alpha_ratio = (1.0 - progress) / 0.3
        elif progress < 0.4:
            alpha_ratio = progress / 0.4
        else:
            alpha_ratio = 1.0
        glow_alpha = int(200 * alpha_ratio)
        if glow_alpha > 0:
            glow_size = base_r * 2 + 50
            glow_surf = pygame.Surface((glow_size, glow_size), pygame.SRCALPHA)
            gc = glow_size // 2
            # 외곽 에메랄드 글로우 (4겹으로 더 강렬하게)
            for i in range(4):
                r_val = base_r + 15 - i * 5
                a = max(0, glow_alpha - i * 25)
                pygame.draw.circle(glow_surf, (0, 255, 130, a), (gc, gc), r_val, 3)
            # 중간 에메랄드 글로우
            mid_a = max(0, glow_alpha * 2 // 3)
            pygame.draw.circle(glow_surf, (0, 220, 100, mid_a), (gc, gc), base_r)
            # 내부 밝은 에메랄드 코어
            inner_a = max(0, glow_alpha // 2)
            pygame.draw.circle(glow_surf, (100, 255, 180, inner_a), (gc, gc), base_r - 5)
            # 중심 백색 플래시 (순간 번쩍임)
            if progress > 0.6:
                flash_a = int(180 * ((progress - 0.6) / 0.4))
                pygame.draw.circle(glow_surf, (200, 255, 220, flash_a), (gc, gc), base_r // 2)
            screen.blit(glow_surf, (int(cx) - gc, int(cy) - gc))

        t = pygame.time.get_ticks() / 1000.0
        star_count = 5
        for i in range(star_count):
            angle = t * 3 + i * (math.pi * 2 / star_count)
            dist = base_r - 5
            sx = int(cx + math.cos(angle) * dist)
            sy = int(cy + math.sin(angle) * dist)
            s_alpha = int(200 * alpha_ratio)
            star_size = 4 + int(2 * math.sin(t * 8 + i * 1.5))
            if s_alpha > 0 and star_size > 0:
                star_surf = pygame.Surface((star_size * 2 + 4, star_size * 2 + 4), pygame.SRCALPHA)
                sc = star_size + 2
                pygame.draw.line(star_surf, (150, 255, 200, s_alpha),
                                 (sc - star_size, sc), (sc + star_size, sc), 2)
                pygame.draw.line(star_surf, (150, 255, 200, s_alpha),
                                 (sc, sc - star_size), (sc, sc + star_size), 2)
                screen.blit(star_surf, (sx - sc, sy - sc))

    for p in particles:
        ratio = p['life'] / p['max_life'] if p['max_life'] > 0 else 0
        alpha = int(255 * ratio)
        size = max(1, int(p['size'] * ratio))
        color = _INSP_COLORS[p['color_idx']]
        px = int(cx + p['ox'])
        py = int(cy + p['oy'])
        if alpha > 0 and size > 0:
            p_surf = pygame.Surface((size * 2 + 2, size * 2 + 2), pygame.SRCALPHA)
            pc = size + 1
            pygame.draw.circle(p_surf, (*color, alpha), (pc, pc), size)
            screen.blit(p_surf, (px - pc, py - pc))


def _update_barrier_block_effects(dt):
    """차단된 스킬 녹아내리는 이펙트 업데이트"""
    global arena_barrier_flash_top, arena_barrier_flash_bottom
    global arena_barrier_beam_target_top, arena_barrier_beam_target_bottom

    # 결계 플래시 타이머 감소
    if arena_barrier_flash_top > 0:
        arena_barrier_flash_top = max(0.0, arena_barrier_flash_top - dt)
        if arena_barrier_flash_top <= 0:
            arena_barrier_beam_target_top = None
    if arena_barrier_flash_bottom > 0:
        arena_barrier_flash_bottom = max(0.0, arena_barrier_flash_bottom - dt)
        if arena_barrier_flash_bottom <= 0:
            arena_barrier_beam_target_bottom = None

    to_remove = []
    for eff in arena_barrier_block_effects:
        eff['timer'] += dt

        if eff['phase'] == 'launch':
            # 투사체 이동 (시전자 → 중간 지점)
            prog = min(1.0, eff['timer'] / eff['launch_duration'])
            # ease-out
            ep = 1.0 - (1.0 - prog) ** 2
            eff['proj_x'] = eff['caster_x'] + (eff['mid_x'] - eff['caster_x']) * ep
            eff['proj_y'] = eff['caster_y'] + (eff['mid_y'] - eff['caster_y']) * ep
            eff['proj_alpha'] = 255
            # 투사체 크기 펄스
            eff['proj_size'] = 18 + 4 * math.sin(eff['timer'] * 15)

            if prog >= 1.0:
                eff['phase'] = 'dissolve'
                eff['timer'] = 0.0
                eff['dissolve_started'] = True

        elif eff['phase'] == 'dissolve':
            prog = min(1.0, eff['timer'] / eff['dissolve_duration'])
            # 투사체 흔들리며 줄어듦
            eff['proj_wobble'] = math.sin(eff['timer'] * 30) * (8 * (1.0 - prog))
            eff['proj_size'] = max(0, 18 * (1.0 - prog ** 0.7))
            eff['proj_alpha'] = max(0, int(255 * (1.0 - prog)))

            # 파티클 업데이트
            for p in eff['particles']:
                p['x'] += p['vx'] * dt
                p['y'] += p['vy'] * dt
                p['vy'] += 50 * dt  # 약간의 중력
                p['alpha'] = max(0, p['alpha'] - p['decay'] * dt)
                p['size'] = max(0, p['size'] - 3 * dt)

            if prog >= 1.0:
                to_remove.append(eff)

    for eff in to_remove:
        arena_barrier_block_effects.remove(eff)


def _draw_barrier_block_effects(screen):
    """차단된 스킬 녹아내리는 이펙트 렌더링"""
    for eff in arena_barrier_block_effects:
        px = int(eff['proj_x'] + eff.get('proj_wobble', 0))
        py = int(eff['proj_y'])
        color = eff['color']
        alpha = int(eff['proj_alpha'])

        if eff['phase'] == 'launch':
            # 투사체 그리기 (에너지 구체)
            sz = int(eff['proj_size'])
            if sz > 0 and alpha > 0:
                surf_sz = sz * 4 + 20
                surf = pygame.Surface((surf_sz, surf_sz), pygame.SRCALPHA)
                sc = surf_sz // 2
                # 외곽 글로우
                glow_a = max(0, alpha // 3)
                pygame.draw.circle(surf, (color[0], color[1], color[2], glow_a),
                                   (sc, sc), sz * 2, 0)
                # 중간 글로우
                mid_a = max(0, alpha // 2)
                pygame.draw.circle(surf, (min(255, color[0]+40), min(255, color[1]+40),
                                          min(255, color[2]+40), mid_a),
                                   (sc, sc), int(sz * 1.3), 0)
                # 코어
                pygame.draw.circle(surf, (min(255, color[0]+80), min(255, color[1]+80),
                                          min(255, color[2]+80), alpha),
                                   (sc, sc), sz, 0)
                # 하이라이트
                hl_a = max(0, alpha * 2 // 3)
                pygame.draw.circle(surf, (255, 255, 255, hl_a),
                                   (sc - sz // 3, sc - sz // 3), max(1, sz // 3), 0)
                screen.blit(surf, (px - sc, py - sc))

                # 트레일 (잔상)
                trail_len = 5
                for ti in range(trail_len):
                    t_prog = (ti + 1) / trail_len
                    t_x = px - int((px - eff['caster_x']) * t_prog * 0.3)
                    t_y = py - int((py - eff['caster_y']) * t_prog * 0.3)
                    t_a = max(0, int(alpha * (1.0 - t_prog) * 0.4))
                    t_sz = max(1, int(sz * (1.0 - t_prog * 0.6)))
                    if t_a > 0 and t_sz > 0:
                        t_surf = pygame.Surface((t_sz * 2 + 4, t_sz * 2 + 4), pygame.SRCALPHA)
                        pygame.draw.circle(t_surf, (color[0], color[1], color[2], t_a),
                                           (t_sz + 2, t_sz + 2), t_sz, 0)
                        screen.blit(t_surf, (t_x - t_sz - 2, t_y - t_sz - 2))

        elif eff['phase'] == 'dissolve':
            # 녹아내리는 투사체 (왜곡 + 축소)
            sz = int(eff['proj_size'])
            if sz > 0 and alpha > 0:
                surf_sz = sz * 4 + 20
                surf = pygame.Surface((surf_sz, surf_sz), pygame.SRCALPHA)
                sc = surf_sz // 2
                # 일그러진 코어
                stretch_x = 1.0 + abs(math.sin(eff['timer'] * 20)) * 0.4
                stretch_y = 1.0 / stretch_x
                ex = max(1, int(sz * stretch_x))
                ey = max(1, int(sz * stretch_y))
                pygame.draw.ellipse(surf, (color[0], color[1], color[2], alpha),
                                    (sc - ex, sc - ey, ex * 2, ey * 2), 0)
                # 글로우 잔여
                glow_a = max(0, alpha // 4)
                pygame.draw.ellipse(surf, (min(255, color[0]+50), min(255, color[1]+50),
                                           min(255, color[2]+50), glow_a),
                                    (sc - ex * 2, sc - ey * 2, ex * 4, ey * 4), 0)
                screen.blit(surf, (px - sc, py - sc))

            # 파티클 그리기 (녹아 흩어지는 조각들)
            for p in eff['particles']:
                p_a = int(p['alpha'])
                p_sz = max(0, int(p['size']))
                if p_a > 0 and p_sz > 0:
                    p_x = int(px + p['x'])
                    p_y = int(py + p['y'])
                    p_surf = pygame.Surface((p_sz * 2 + 4, p_sz * 2 + 4), pygame.SRCALPHA)
                    pc = p['color']
                    pygame.draw.circle(p_surf, (pc[0], pc[1], pc[2], p_a),
                                       (p_sz + 2, p_sz + 2), p_sz, 0)
                    screen.blit(p_surf, (p_x - p_sz - 2, p_y - p_sz - 2))


# 투기장 영웅 말풍선 시스템
arena_top_speech_text = ""           # 상단 영웅 말풍선 텍스트
arena_top_speech_timer = 0           # 상단 영웅 말풍선 타이머
arena_bottom_speech_text = ""        # 하단 영웅 말풍선 텍스트
arena_bottom_speech_timer = 0        # 하단 영웅 말풍선 타이머
ARENA_SPEECH_DURATION = 90           # 말풍선 표시 시간 (1.5초)

# 스킬/대화 말풍선 구분용
arena_top_speech_is_skill = False
arena_bottom_speech_is_skill = False
arena_top_speech_color = (200, 60, 60)
arena_bottom_speech_color = (200, 60, 60)

# 영웅별 외침 풍선 테마 컬러
HERO_SHOUT_COLORS = {
    "mugen": (130, 60, 190),
    "kraken": (40, 130, 150),
    "chronos": (130, 80, 170),
    "onimaru": (200, 50, 70),
    "maria": (180, 100, 150),
    "ignis": (220, 100, 40),
    "gear": (190, 130, 50),
    "kurokage": (90, 80, 120),
}
BOSS_SHOUT_COLOR = (200, 55, 55)  # 스테이지 보스 기본 외침 색상 (폴백)
# 스테이지별 보스 외침 풍선 테마 컬러
BOSS_STAGE_SHOUT_COLORS = {
    1: (180, 120, 50),   # 풍악보이 - 따뜻한 황금빛 (한국 전통)
    2: (60, 130, 55),    # 악어장군 - 진한 정글 초록
    3: (180, 70, 150),   # 멘헤라걸 - 병적인 핑크/보라
    4: (140, 100, 60),   # 퐁크 - 사원 갈색/황토
    5: (50, 90, 160),    # 네메시스 - 깊은 해군 파랑
    6: (200, 55, 55),    # 홍련 - 불꽃 빨강
    7: (80, 140, 210),   # 테트리서 - 디지털 하늘색
    8: (90, 60, 130),    # 아카무 리고 - 그림자 보라
}


def arena_show_speech_bubble(is_top: bool, skill_name: str, raw: bool = False, hero_id: str = ""):
    """투기장 영웅 말풍선 표시

    Args:
        raw: True면 텍스트 그대로 표시 (대사=둥근 말풍선), False면 "!" 추가 (스킬=외침 풍선)
        hero_id: 영웅 ID (외침 풍선 테마 색상용)
    """
    global arena_top_speech_text, arena_top_speech_timer
    global arena_bottom_speech_text, arena_bottom_speech_timer
    global arena_top_speech_is_skill, arena_bottom_speech_is_skill
    global arena_top_speech_color, arena_bottom_speech_color

    text = skill_name if raw else skill_name + "!"
    is_skill = not raw
    color = HERO_SHOUT_COLORS.get(hero_id, (200, 60, 60))

    if is_top:
        arena_top_speech_text = text
        arena_top_speech_timer = ARENA_SPEECH_DURATION
        arena_top_speech_is_skill = is_skill
        arena_top_speech_color = color
    else:
        arena_bottom_speech_text = text
        arena_bottom_speech_timer = ARENA_SPEECH_DURATION
        arena_bottom_speech_is_skill = is_skill
        arena_bottom_speech_color = color

# 투기장 스킬 사운드 캐시 및 재생
_arena_skill_sound_cache = {}
_arena_skill_sound_this_frame = False  # 이번 프레임에서 스킬 사운드 재생 여부 (패들 사운드 중복 방지)

def arena_play_skill_sound(result):
    """투기장 스킬 결과에서 사운드 키를 꺼내 재생. 재생 성공 시 True 반환."""
    global _arena_skill_sound_cache, _arena_skill_sound_this_frame
    if not result:
        return False
    # 🔥 안전장치: 투기장 모드가 아니면 스킬 사운드 재생 차단
    if not arena_mode_enabled:
        return False
    sound_key = result.get('sound')
    if not sound_key:
        return False

    if sound_key not in _arena_skill_sound_cache:
        try:
            filepath = resource_path(os.path.join("sounds", f"{sound_key}.wav"))
            if os.path.exists(filepath):
                _arena_skill_sound_cache[sound_key] = pygame.mixer.Sound(filepath)
            else:
                _arena_skill_sound_cache[sound_key] = None
        except Exception as e:
            _arena_skill_sound_cache[sound_key] = None

    snd = _arena_skill_sound_cache.get(sound_key)
    if snd:
        # 🔍 DEBUG: ghostwalk 사운드 재생 추적
        if sound_key == 'ghostwalk':
            import traceback
            # print(f"[DEBUG GHOSTWALK] arena_play_skill_sound 호출! arena_mode={arena_mode_enabled}")
            traceback.print_stack(limit=10)
        snd.play()
        _arena_skill_sound_this_frame = True  # 이번 프레임에서 패들 사운드 스킵
        return True
    return False

def arena_stop_all_skill_sounds():
    """투기장 스킬 사운드 전체 중지 (pingfighter 캐시 + colosseum_arena 캐시 + 개틀링 루프)"""
    try:
        if not pygame.mixer.get_init():
            return
    except Exception:
        return
    for snd in _arena_skill_sound_cache.values():
        if snd:
            try:
                snd.stop()
            except Exception:
                pass
    # ColosseumsArena의 스킬 사운드 캐시도 중지
    try:
        from downtown.colosseum_arena import ColosseumsArena
        if hasattr(ColosseumsArena, '_skill_sound_cache'):
            for snd in ColosseumsArena._skill_sound_cache.values():
                if snd:
                    snd.stop()
    except Exception:
        pass
    # 개틀링 버스트 루프 사운드 즉시 정지 (스킬 인스턴스에서 직접 관리하는 사운드)
    try:
        if arena_skill_manager:
            for hero_id, skills in arena_skill_manager.active_skills.items():
                for skill in skills:
                    if hasattr(skill, '_gatling_loop_sound') and skill._gatling_loop_sound:
                        skill._gatling_loop_sound.stop()
                        skill._gatling_loop_sound = None
    except Exception:
        pass


def arena_draw_speech_bubbles():
    """투기장 영웅 말풍선 그리기 (스킬=외침풍선, 대화=둥근말풍선)"""
    global arena_top_speech_timer, arena_bottom_speech_timer

    # 상단 영웅 말풍선 (보스 위치)
    if arena_top_speech_timer > 0 and arena_top_speech_text:
        if arena_top_speech_is_skill:
            _draw_shout_bubble(
                BOSS.centerx, BOSS.bottom + 15,
                arena_top_speech_text,
                arena_top_speech_timer, ARENA_SPEECH_DURATION,
                arena_top_speech_color
            )
        else:
            _draw_arena_speech_bubble(
                BOSS.centerx, BOSS.bottom + 15,
                arena_top_speech_text, is_top=True
            )
        arena_top_speech_timer -= arena_speed_multiplier

    # 하단 영웅 말풍선 (플레이어 위치 - 패들 위에 표시)
    if arena_bottom_speech_timer > 0 and arena_bottom_speech_text:
        if arena_bottom_speech_is_skill:
            _draw_shout_bubble(
                PLAYER.centerx, PLAYER.top - 105,
                arena_bottom_speech_text,
                arena_bottom_speech_timer, ARENA_SPEECH_DURATION,
                arena_bottom_speech_color
            )
        else:
            _draw_arena_speech_bubble(
                PLAYER.centerx, PLAYER.top - 70,
                arena_bottom_speech_text, is_top=False
            )
        arena_bottom_speech_timer -= arena_speed_multiplier


def _draw_arena_speech_bubble(x: float, y: float, text: str, is_top: bool):
    """투기장 개별 말풍선 그리기"""
    try:
        # 폰트 설정
        font = FontStyle.menu()

        text_surface = font.render(text, True, BLACK)

        # 말풍선 크기 계산
        padding = 14
        bubble_width = text_surface.get_width() + padding * 2
        bubble_height = text_surface.get_height() + padding

        # 말풍선 위치
        bubble_x = int(x - bubble_width // 2)
        bubble_y = int(y)

        # 화면 경계 체크
        bubble_x = max(5, min(bubble_x, WIDTH - bubble_width - 5))

        # 말풍선 표면 생성
        bubble_surface = pygame.Surface((bubble_width + 15, bubble_height + 25), pygame.SRCALPHA)

        # 그림자
        shadow_rect = pygame.Rect(3, 3, bubble_width, bubble_height)
        pygame.draw.rect(bubble_surface, (0, 0, 0, 80), shadow_rect, border_radius=12)

        # 메인 말풍선
        main_rect = pygame.Rect(0, 0, bubble_width, bubble_height)
        pygame.draw.rect(bubble_surface, WHITE, main_rect, border_radius=12)
        pygame.draw.rect(bubble_surface, BLACK, main_rect, 3, border_radius=12)

        # 말풍선 꼬리 (위/아래 방향)
        if is_top:
            # 상단 영웅: 꼬리가 위쪽 (영웅을 향함)
            tail_points = [
                (bubble_width // 2 - 10, 2),
                (bubble_width // 2 + 10, 2),
                (bubble_width // 2, -15)
            ]
        else:
            # 하단 영웅: 꼬리가 아래쪽 (영웅을 향함)
            tail_points = [
                (bubble_width // 2 - 10, bubble_height - 2),
                (bubble_width // 2 + 10, bubble_height - 2),
                (bubble_width // 2, bubble_height + 15)
            ]

        pygame.draw.polygon(bubble_surface, WHITE, tail_points)
        pygame.draw.polygon(bubble_surface, BLACK, tail_points, 2)

        # 텍스트 그림자
        text_shadow = font.render(text, True, (80, 80, 80))
        bubble_surface.blit(text_shadow, (padding + 1, padding // 2 + 1))

        # 메인 텍스트
        bubble_surface.blit(text_surface, (padding, padding // 2))

        # 애니메이션 (살짝 흔들림)
        timer = arena_top_speech_timer if is_top else arena_bottom_speech_timer
        float_offset = math.sin(timer * 0.15) * 2

        # 화면에 그리기
        SCREEN.blit(bubble_surface, (bubble_x, bubble_y + float_offset))

    except Exception as e:
        pass  # 오류 시 무시


def _draw_shout_bubble(x, y, text, timer, max_timer, theme_color):
    """외침 풍선 (스킬 발동용) - 뾰족한 별/톱니 모양 말풍선
    Args:
        x: 중심 X 좌표
        y: 상단 Y 좌표
        text: 표시할 텍스트
        timer: 남은 타이머 (프레임)
        max_timer: 최대 타이머 (팝업 애니메이션 계산용)
        theme_color: 배경 테마 색상 (R, G, B)
    """
    try:
        font = FontStyle.menu()
        text_surface = font.render(text, True, WHITE)
        text_w = text_surface.get_width()
        text_h = text_surface.get_height()

        # 말풍선 내부 사이즈
        pad_x, pad_y = 22, 14
        inner_w = text_w + pad_x * 2
        inner_h = text_h + pad_y * 2

        # 팝업 스케일 애니메이션 (등장 시 1.3→1.0 축소)
        elapsed = max_timer - timer
        if elapsed < 8:
            scale = 1.0 + (1.0 - elapsed / 8.0) * 0.3
        else:
            scale = 1.0

        # 서페이스 생성 (스파이크 여유 포함)
        spike_len = 14
        surf_w = int((inner_w + spike_len * 2) * scale) + 8
        surf_h = int((inner_h + spike_len * 2) * scale) + 8
        bubble_surface = pygame.Surface((surf_w, surf_h), pygame.SRCALPHA)
        cx = surf_w // 2
        cy = surf_h // 2

        # Starburst 다각형 생성
        num_spikes = 12
        outer_rx = (inner_w / 2 + spike_len) * scale
        outer_ry = (inner_h / 2 + spike_len) * scale
        inner_rx = (inner_w / 2) * scale
        inner_ry = (inner_h / 2) * scale

        points = []
        for i in range(num_spikes * 2):
            angle = 2 * math.pi * i / (num_spikes * 2) - math.pi / 2
            # 스파이크 길이에 약간의 변화 (자연스러운 느낌)
            variation = 1.0 + 0.12 * math.sin(i * 2.7)
            if i % 2 == 0:  # 뾰족한 끝
                px = cx + math.cos(angle) * outer_rx * variation
                py = cy + math.sin(angle) * outer_ry * variation
            else:  # 안쪽 골
                px = cx + math.cos(angle) * inner_rx
                py = cy + math.sin(angle) * inner_ry
            points.append((px, py))

        # 그림자
        shadow_pts = [(p[0] + 3, p[1] + 3) for p in points]
        pygame.draw.polygon(bubble_surface, (0, 0, 0, 70), shadow_pts)

        # 메인 채우기 (테마 색상)
        pygame.draw.polygon(bubble_surface, theme_color, points)

        # 안쪽 밝은 영역 (하이라이트)
        hl_color = (min(255, theme_color[0] + 50),
                    min(255, theme_color[1] + 50),
                    min(255, theme_color[2] + 50), 90)
        hl_rx = inner_rx * 0.8
        hl_ry = inner_ry * 0.6
        hl_pts = []
        for i in range(num_spikes * 2):
            angle = 2 * math.pi * i / (num_spikes * 2) - math.pi / 2
            r = hl_rx if i % 2 == 0 else hl_rx * 0.85
            ry = hl_ry if i % 2 == 0 else hl_ry * 0.85
            hl_pts.append((cx + math.cos(angle) * r, cy + math.sin(angle) * ry))
        pygame.draw.polygon(bubble_surface, hl_color, hl_pts)

        # 테두리 (어두운 색)
        border_color = (max(0, theme_color[0] - 60),
                        max(0, theme_color[1] - 60),
                        max(0, theme_color[2] - 60))
        pygame.draw.polygon(bubble_surface, border_color, points, 3)

        # 텍스트: 검정 외곽선 + 흰색 본문
        tx = int(cx - text_w / 2)
        ty = int(cy - text_h / 2)
        for dx, dy in [(-2, 0), (2, 0), (0, -2), (0, 2),
                        (-1, -1), (1, -1), (-1, 1), (1, 1)]:
            outline = font.render(text, True, (0, 0, 0))
            bubble_surface.blit(outline, (tx + dx, ty + dy))
        bubble_surface.blit(font.render(text, True, WHITE), (tx, ty))

        # 살짝 흔들림 애니메이션
        float_offset = math.sin(timer * 0.15) * 2

        # 화면에 그리기
        blit_x = int(x - surf_w // 2)
        blit_y = int(y + float_offset)
        blit_x = max(5, min(blit_x, INTERNAL_WIDTH - surf_w - 5))
        SCREEN.blit(bubble_surface, (blit_x, blit_y))
    except Exception:
        pass


# ============================================================================
# 투기장 대쉬 시스템 - 통합 공통 함수 (top/bottom 코드 중복 제거)
# ============================================================================

def _predict_x_with_walls(x: float, vx: float, frames: float) -> float:
    """벽 반사를 고려한 공의 예상 X 위치 계산 (투기장 대쉬용)"""
    if abs(vx) < 1e-3 or frames <= 0:
        return x
    remaining = frames
    x_min = 0.0
    x_max = float(WIDTH)
    for _ in range(4):
        if remaining <= 0:
            break
        if vx > 0:
            t_wall = (x_max - x) / vx if vx != 0 else float("inf")
        else:
            t_wall = (x_min - x) / vx if vx != 0 else float("inf")
        if t_wall <= 0 or t_wall >= remaining:
            x += vx * remaining
            remaining = 0
            break
        x += vx * t_wall
        remaining -= t_wall
        vx = -vx
    return max(x_min, min(x_max, x))


def _arena_trigger_hero_dash_ai(is_top: bool, target_x: float) -> bool:
    """투기장 영웅(AI) 대쉬 발동 (top/bottom 통합)"""
    g = globals()
    side = 'top' if is_top else 'bottom'

    # 스팀 배리어 시전 중에는 대쉬 발동 불가
    if arena_skill_manager and arena_skill_manager.game_state.get('steam_barrier_caster_frozen', False):
        barrier_owner_is_top = arena_skill_manager.game_state.get('barrier_owner_is_top', False)
        if barrier_owner_is_top == is_top:
            return False

    # 귀신발걸음 활성 중에는 대쉬 발동 불가 (bottom만)
    if not is_top and arena_bottom_ghost_step_active:
        return False

    # 대쉬 중이거나 후딜 중이면 발동 불가
    if g[f'arena_{side}_dashing'] or g[f'arena_{side}_dash_stun_timer'] > 0:
        return False

    # 스턴/감전 상태에서는 대쉬 불가
    stun_timer_val = g.get(f'_judgment_lightning_stun_{side}_timer', 0)
    if stun_timer_val > 0:
        return False
    if arena_skill_manager and arena_skill_manager.game_state.get(f'{side}_paddle_electric_stun', False):
        return False

    # 토큰 없으면 발동 불가
    if g[f'arena_{side}_dash_charges'] <= 0:
        return False

    paddle = BOSS if is_top else PLAYER
    paddle_half = paddle.width // 2

    direction = 1 if target_x > paddle.centerx else -1
    base_distance = abs(target_x - paddle.centerx)
    if base_distance < 30:
        return False

    # 폭풍질주 퍽: 실제 대쉬 거리 증가
    perk_mult = g[f'arena_perk_dash_distance_mult_{side}']
    dash_distance = base_distance * perk_mult
    extended_target_x = paddle.centerx + direction * dash_distance
    extended_target_x = float(max(paddle_half, min(WIDTH - paddle_half, extended_target_x)))
    dash_distance = abs(extended_target_x - paddle.centerx)

    g[f'arena_{side}_dash_direction'] = direction
    g[f'arena_{side}_dash_target_x'] = extended_target_x

    # 동적 지속시간 계산 (실제 이동 거리 기반)
    estimated_duration = dash_distance / 30.0
    g[f'arena_{side}_dash_duration_frames'] = int(max(10, min(estimated_duration, 60)))
    g[f'arena_{side}_dash_timer'] = g[f'arena_{side}_dash_duration_frames']
    g[f'arena_{side}_dashing'] = True
    g[f'arena_{side}_dash_charges'] -= 1
    g[f'arena_{side}_dash_charge_timer'] = 0

    # 폭풍질주 퍽: 버스트업 Lv3 효과 (패들 높이 증가 + 사운드 + 파티클)
    if perk_mult > 1.0:
        g[f'arena_storm_rush_burst_{side}'] = True
        g[f'arena_storm_rush_height_bonus_{side}'] = int(paddle.height * 2.1)
        _spawn_storm_rush_particles(paddle.centerx, paddle.centery)
        try:
            play_sound_with_volume(SOUND_BURST_UP)
        except Exception:
            try:
                play_dash_sound()
            except Exception:
                pass
    else:
        try:
            play_dash_sound()
        except Exception:
            pass

    return True


def _arena_update_hero_dash(is_top: bool):
    """투기장 영웅 대쉬 업데이트 (top/bottom 통합)"""
    g = globals()
    side = 'top' if is_top else 'bottom'

    # 폭풍질주 파티클 업데이트 (top에서만 1회 처리, 공유 리스트)
    if is_top:
        new_particles = []
        for p in arena_storm_rush_particles:
            p[0] += p[2]  # x += vx
            p[1] += p[3]  # y += vy
            p[4] -= 1     # life -= 1
            if p[4] > 0:
                new_particles.append(p)
        g['arena_storm_rush_particles'] = new_particles

    # 스팀 배리어 시전 중에는 대쉬 즉시 취소
    if arena_skill_manager and arena_skill_manager.game_state.get('steam_barrier_caster_frozen', False):
        barrier_owner_is_top = arena_skill_manager.game_state.get('barrier_owner_is_top', False)
        if barrier_owner_is_top == is_top:
            if g[f'arena_{side}_dashing']:
                g[f'arena_{side}_dashing'] = False
                g[f'arena_{side}_dash_timer'] = 0
                g[f'arena_storm_rush_burst_{side}'] = False
                g[f'arena_storm_rush_height_bonus_{side}'] = 0
            return False

    # 귀신발걸음 활성 중에는 대쉬 시스템 비활성화 (bottom만)
    if not is_top and arena_bottom_ghost_step_active:
        if g[f'arena_{side}_dashing']:
            g[f'arena_{side}_dashing'] = False
            g[f'arena_{side}_dash_timer'] = 0
            g[f'arena_storm_rush_burst_{side}'] = False
            g[f'arena_storm_rush_height_bonus_{side}'] = 0
        return False

    # 충전 타이머 업데이트 (대쉬 중/후딜 중에는 충전 안 함)
    max_charges = g[f'arena_{side}_max_dash_charges']
    charges = g[f'arena_{side}_dash_charges']
    cooldown = g[f'arena_{side}_dash_cooldown']
    stun_timer = g[f'arena_{side}_dash_stun_timer']
    dashing = g[f'arena_{side}_dashing']

    if charges < max_charges and cooldown <= 0 and stun_timer <= 0 and not dashing:
        g[f'arena_{side}_dash_charge_timer'] += 1
        if g[f'arena_{side}_dash_charge_timer'] >= ARENA_DASH_CHARGE_TIME:
            charged_idx = charges
            g[f'arena_{side}_dash_charges'] = min(max_charges, charges + 1)
            g[f'arena_{side}_dash_charge_timer'] = 0
            play_dash_charge_sound()
            # 하단 전용: 토큰 플래시 반짝임 효과
            if not is_top:
                while len(_token_flash_timers) <= charged_idx:
                    _token_flash_timers.append(0)
                _token_flash_timers[charged_idx] = _TOKEN_FLASH_DURATION
                if g[f'arena_{side}_dash_charges'] >= max_charges:
                    g['_all_tokens_full_sparkle_timer'] = _ALL_TOKENS_FULL_SPARKLE_DURATION

    # 쿨다운 감소
    if cooldown > 0:
        g[f'arena_{side}_dash_cooldown'] = cooldown - 1

    # 후딜(스턴) 처리
    if stun_timer > 0:
        g[f'arena_{side}_dash_stun_timer'] = stun_timer - 1
        if stun_timer > 0 and stun_timer - 1 <= 0:
            try:
                stop_dash_delay_sound()
            except Exception:
                pass
        return True

    if not dashing:
        # 잔상 페이드아웃
        afterimages = g[f'arena_{side}_dash_afterimages']
        new_afterimages = []
        for img in afterimages:
            img['alpha'] -= 25
            img['life'] = img.get('life', 10) - 1
            if img['alpha'] > 0 and img['life'] > 0:
                new_afterimages.append(img)
        g[f'arena_{side}_dash_afterimages'] = new_afterimages
        return False

    g[f'arena_{side}_dash_timer'] -= 1
    timer = g[f'arena_{side}_dash_timer']
    duration = g[f'arena_{side}_dash_duration_frames']
    speed = g[f'arena_{side}_dash_speed']
    direction = g[f'arena_{side}_dash_direction']
    target_x = g[f'arena_{side}_dash_target_x']

    paddle = BOSS if is_top else PLAYER

    # 속도 곡선: 초반 20프레임 고속, 후반 감속
    high_phase_frames = min(20, duration)
    if timer > high_phase_frames:
        move_step = speed * direction
    else:
        decel_factor = max(0.0, timer / float(high_phase_frames)) if high_phase_frames > 0 else 0.0
        move_step = speed * direction * decel_factor

    paddle.centerx += move_step

    # 목표 도달 체크
    if direction > 0 and paddle.centerx >= target_x:
        paddle.centerx = int(target_x)
    elif direction < 0 and paddle.centerx <= target_x:
        paddle.centerx = int(target_x)

    # 게임 영역 내 제한
    paddle_half = paddle.width // 2
    paddle.centerx = max(paddle_half, min(WIDTH - paddle_half, paddle.centerx))

    # 잔상 추가 (매 프레임, 최대 6개)
    afterimages = g[f'arena_{side}_dash_afterimages']
    afterimages.append({
        'x': paddle.centerx, 'y': paddle.centery,
        'width': paddle.width, 'height': paddle.height,
        'alpha': 160, 'life': 10,
        'storm_rush': g[f'arena_storm_rush_burst_{side}']
    })
    if len(afterimages) > 6:
        afterimages.pop(0)

    # 대쉬 종료
    if timer <= 0:
        g[f'arena_{side}_dashing'] = False
        g[f'arena_storm_rush_burst_{side}'] = False
        g[f'arena_storm_rush_height_bonus_{side}'] = 0
        g[f'arena_{side}_dash_stun_timer'] = ARENA_DASH_STUN_FRAMES
        perk_cd = g[f'arena_perk_dash_cd_mult_{side}']
        g[f'arena_{side}_dash_cooldown'] = int(random.randint(ARENA_DASH_COOLDOWN_MIN, ARENA_DASH_COOLDOWN_MAX) * perk_cd)
        try:
            play_dash_delay_sound()
        except Exception:
            pass

    return True


def arena_should_top_hero_dash() -> tuple[bool, float]:
    """상단 영웅(AI) 대쉬 발동 조건 체크"""
    # 스팀 배리어 시전 중에는 대쉬 발동 불가
    if arena_skill_manager and arena_skill_manager.game_state.get('steam_barrier_caster_frozen', False) and arena_skill_manager.game_state.get('barrier_owner_is_top', False):
        return False, 0.0
    if arena_top_dashing or arena_top_dash_stun_timer > 0:
        return False, 0.0
    # 스턴/감전 상태에서는 대쉬 불가
    if _judgment_lightning_stun_top_timer > 0 or (arena_skill_manager and arena_skill_manager.game_state.get('top_paddle_electric_stun', False)):
        return False, 0.0
    if arena_top_dash_charges <= 0:
        return False, 0.0
    if ball_vel[1] >= 0:
        return False, 0.0

    dy = BALL.centery - BOSS.bottom
    if dy <= 0 or dy > 100:
        return False, 0.0
    time_to_paddle = dy / max(1.0, abs(ball_vel[1]))
    if time_to_paddle > 18.0:
        return False, 0.0

    max_travel = 12.0 * time_to_paddle  # 8.0 * 1.5
    predicted_x = _predict_x_with_walls(float(BALL.centerx), float(ball_vel[0]), float(time_to_paddle))
    predicted_x = max(BOSS.width // 2, min(WIDTH - BOSS.width // 2, predicted_x))
    required = abs(predicted_x - BOSS.centerx)
    if required <= max_travel or required < BOSS.width * 0.8:
        return False, 0.0
    return True, predicted_x


def _spawn_storm_rush_particles(cx, cy):
    """폭풍질주 버스트업 플래시 파티클 생성 (버스트업 Lv3 동일)"""
    global arena_storm_rush_particles
    # 에너지 파티클 25개 (방사형, 밝은 흰색)
    for i in range(25):
        angle = (i / 25) * 2 * math.pi
        speed = random.uniform(6, 13)
        arena_storm_rush_particles.append([
            cx, cy,
            math.cos(angle) * speed, math.sin(angle) * speed,
            45,  # life
            random.randint(3, 9),  # size
            (255, 255, 240),  # 밝은 흰색
            'energy'
        ])
    # 전기 스파크 14개 (랜덤 각도, 푸른색)
    for _ in range(14):
        angle = random.uniform(0, 2 * math.pi)
        speed = random.uniform(8, 15)
        arena_storm_rush_particles.append([
            cx, cy,
            math.cos(angle) * speed, math.sin(angle) * speed,
            29,  # life
            random.randint(2, 4),  # size
            (200, 220, 255),  # 전기 푸른색
            'electric'
        ])


def arena_trigger_top_hero_dash(target_x: float) -> bool:
    """상단 영웅(AI) 대쉬 발동 → 통합 함수 위임"""
    return _arena_trigger_hero_dash_ai(True, target_x)


def arena_should_bottom_hero_dash() -> tuple[bool, float]:
    """하단 영웅(AI) 대쉬 발동 조건 체크"""
    # 스팀 배리어 시전 중에는 대쉬 발동 불가 (하단 패들이 시전자일 때)
    if arena_skill_manager and arena_skill_manager.game_state.get('steam_barrier_caster_frozen', False) and not arena_skill_manager.game_state.get('barrier_owner_is_top', False):
        return False, 0.0
    if arena_bottom_dashing or arena_bottom_dash_stun_timer > 0:
        return False, 0.0
    if ball_vel[1] <= 0:
        return False, 0.0

    dy = PLAYER.top - BALL.centery
    if dy <= 0 or dy > 100:
        return False, 0.0
    time_to_paddle = dy / max(1.0, abs(ball_vel[1]))
    if time_to_paddle > 18.0:
        return False, 0.0

    max_travel = 12.0 * time_to_paddle  # 8.0 * 1.5
    predicted_x = _predict_x_with_walls(float(BALL.centerx), float(ball_vel[0]), float(time_to_paddle))
    predicted_x = max(PLAYER.width // 2, min(WIDTH - PLAYER.width // 2, predicted_x))
    required = abs(predicted_x - PLAYER.centerx)
    if required <= max_travel or required < PLAYER.width * 0.8:
        return False, 0.0
    return True, predicted_x


def arena_trigger_bottom_hero_dash_ai(target_x: float) -> bool:
    """하단 영웅(AI) 대쉬 발동 → 통합 함수 위임"""
    return _arena_trigger_hero_dash_ai(False, target_x)


def arena_trigger_bottom_hero_dash(direction: int) -> bool:
    """하단 영웅(플레이어) 대쉬 발동 - 수동 조작용 (고정 150px 거리)"""
    # 대쉬 목표 = 현재 위치 + 방향 * 150px * 폭풍질주 퍽
    dash_px = 150 * arena_perk_dash_distance_mult_bottom
    target_x = PLAYER.centerx + direction * dash_px
    target_x = float(max(PLAYER.width // 2, min(WIDTH - PLAYER.width // 2, target_x)))
    return _arena_trigger_hero_dash_ai(False, target_x)


def update_arena_top_hero_dash():
    """상단 영웅 대쉬 업데이트 → 통합 함수 위임"""
    return _arena_update_hero_dash(True)


def update_arena_bottom_hero_dash():
    """하단 영웅 대쉬 업데이트 → 통합 함수 위임"""
    return _arena_update_hero_dash(False)


def _draw_dash_afterimages_side(screen, afterimages, hero_data, default_color):
    """대쉬 잔상 렌더링 (top/bottom 공통)"""
    for img in afterimages:
        alpha = img.get('alpha', 0)
        life = img.get('life', 0)
        if alpha > 0 and life > 0:
            w = img.get('width', 80)
            h = img.get('height', 20)
            surf = pygame.Surface((w, h), pygame.SRCALPHA)
            if img.get('storm_rush'):
                color = (255, 200, 180)  # Rose Gold
            else:
                color = hero_data.get('color', default_color) if hero_data else default_color
            surf.fill((*color, int(alpha)))
            rect = surf.get_rect(center=(img['x'], img['y']))
            screen.blit(surf, rect.topleft)


def draw_arena_dash_afterimages(screen):
    """투기장 영웅 대쉬 잔상 그리기"""
    _draw_dash_afterimages_side(screen, arena_top_dash_afterimages, arena_top_hero, (100, 100, 255))
    _draw_dash_afterimages_side(screen, arena_bottom_dash_afterimages, arena_bottom_hero, (255, 100, 100))

    # 폭풍질주 플래시 파티클 렌더링
    for p in arena_storm_rush_particles:
        p_alpha = max(0, min(255, int(255 * p[4] / 45)))
        if p_alpha <= 0:
            continue
        p_size = max(1, p[5])
        ps = pygame.Surface((p_size * 2, p_size * 2), pygame.SRCALPHA)
        p_color = p[6]
        p_type = p[7] if len(p) > 7 else 'energy'
        if p_type == 'electric':
            pygame.draw.circle(ps, (*p_color, p_alpha), (p_size, p_size), p_size)
        else:
            glow_alpha = max(0, p_alpha // 2)
            pygame.draw.circle(ps, (*p_color, glow_alpha), (p_size, p_size), p_size)
            inner = max(1, p_size // 2)
            pygame.draw.circle(ps, (*p_color, p_alpha), (p_size, p_size), inner)
        screen.blit(ps, (int(p[0]) - p_size, int(p[1]) - p_size))


#  리그별 보스 능력치 보정
def get_league_boss_multiplier(league_mode):
    """리그별 보스 능력치 배수 반환 (3단계 리그 시스템)"""
    league_multipliers = {
        "junior": 0.85,    #  주니어리그: -15% (85%) - 초보자 친화적
        "champion": 1.50,  #  챔피언리그: +50% (150%) - 신화급 (10% 광폭화)
        "mythic": 1.50     #  신화리그: +50% (150%) - 신화급 (100% 광폭화)
    }
    return league_multipliers.get(league_mode, 1.00)

def get_league_boss_paddle_scale(league_mode):
    """리그별 보스 패들 사이즈 배율 반환 (3단계 리그 시스템)"""
    paddle_scales = {
        "junior": 1.00,    # 주니어리그: 기본 (100%)
        "champion": 1.15,  # 챔피언리그: +15% (115%) - 신화급
        "mythic": 1.15     # 신화리그: +15% (115%) - 신화급
    }
    return paddle_scales.get(league_mode, 1.00)

# 🌱 주니어리그 공 속도 배율
def get_junior_ball_speed_multiplier():
    """주니어리그일 때 공 속도 배율 반환 (0.65 = -35% 감소)"""
    global ai_mode
    return 0.65 if ai_mode == "junior" else 1.0

def get_junior_speed_increase_multiplier():
    """주니어리그일 때 속도 증가율 배율 반환 (0.6 = -40% 감소, 초반 랠리 속도 안정화)"""
    global ai_mode
    return 0.6 if ai_mode == "junior" else 1.0
def apply_league_boss_config(base_config, league_mode):
    """리그별 보스 설정에 능력치 보정 적용"""
    multiplier = get_league_boss_multiplier(league_mode)
    if multiplier == 1.00:
        return base_config  # 주니어리그는 기본값 그대로
    # 능력치 보정 적용
    modified_config = base_config.copy()
    # 보스 이동 능력치 보정
    modified_config["accel"] = base_config["accel"] * multiplier
    modified_config["decel"] = base_config["decel"] * multiplier  
    modified_config["max_speed"] = base_config["max_speed"] * multiplier
    modified_config["instant_stop"] = base_config["instant_stop"] * multiplier
    # AI 능력치는 실수율로 조정되므로 여기서는 건드리지 않음
    # (predict_chance, predict_error, fail_chance는 유지)
    return modified_config
def get_final_boss_config(stage, league_mode):
    """ 통합 보스 설정: 스테이지별 + 리그별 완전 연계"""
    # 1️⃣ 스테이지별 기본 설정 가져오기
    base_config = boss_speed_config.get(stage, boss_speed_config[1])
    
    # 튜토리얼 스테이지(50)는 리그 보정 없이 기본 설정만 사용
    if stage == 50:
        if DEBUG_TUTORIAL:
            # print(f"튜토리얼 보스 설정 적용 - 속도 50% 증가된 값 사용")
            pass
        return base_config
    
    # 2️⃣ 리그별 보정 적용
    final_config = apply_league_boss_config(base_config, league_mode)
    # 3️⃣ 디버깅 정보 (가끔씩만)
    if stage == 1 and league_mode != "junior":  # Stage 1에서만 로그
        multiplier = get_league_boss_multiplier(league_mode)
        # print(f"   : Stage {stage} + {league_mode} ({multiplier:.0%}) →  {final_config['max_speed']:.2f}")
    return final_config
