def _reset_active_item_hover_state() -> None:
    """호버 상태와 툴팁·일시정지 플래그를 모두 초기화.

    Note: 스매셔 스킬 툴팁이 활성화 중이면 game_paused_by_tooltip은 리셋하지 않음.
    """
    global _active_item_hover_index, _active_item_hover_start_ms, _active_item_hover_rect
    global _active_item_tooltip_ready, _active_item_tooltip_title, _active_item_tooltip_body
    global game_paused_by_tooltip, _tooltip_prev_game_paused, _tooltip_forced_pause, game_paused

    _active_item_hover_index = None
    _active_item_hover_start_ms = None
    _active_item_hover_rect = None
    _active_item_tooltip_ready = False
    _active_item_tooltip_title = ""
    _active_item_tooltip_body = ""

    # 다른 툴팁이 활성화 중이면 일시정지 상태를 건드리지 않음
    if _smasher_skill_tooltip_active or _viper_skill_tooltip_active or _odin_swamp_tooltip_active or _rage_indicator_tooltip_active:
        return

    if game_paused_by_tooltip and _tooltip_forced_pause and game_paused:
        game_paused = _tooltip_prev_game_paused
    game_paused_by_tooltip = False
    _tooltip_forced_pause = False


# ============================================================
# 좌표계 디버그 모드 (F4 토글)
# 액티브 아이템 슬롯 + 스매셔 스킬 히트박스 + 마우스 위치 표시
# ============================================================
# COORDINATE_DEBUG_MODE는 파일 상단 디버그 설정 섹션에서 정의됨 (2659줄)


def _draw_coordinate_debug(screen):
    """좌표계 디버그 - 히트박스와 마우스 위치 시각화 (F4로 토글)

    표시 내용:
    - 빨간 점: 마우스 위치 (raw screen 좌표)
    - 초록색 박스: 액티브 아이템 슬롯 히트박스
    - 청록색 박스: 스매셔 스킬 아이콘 히트박스
    - 노란색: 호버 상태인 항목
    """
    if not COORDINATE_DEBUG_MODE:
        return

    try:
        raw_mouse_x, raw_mouse_y = _original_mouse_get_pos()
        font_small = pygame.font.Font(None, 14)
        font_info = pygame.font.Font(None, 20)

        # === 1. 액티브 아이템 슬롯 히트박스 (초록색) ===
        slot_rects = _get_active_item_slot_rects()
        for i, rect_data in enumerate(slot_rects):
            if isinstance(rect_data, tuple):
                rect = pygame.Rect(rect_data[0], rect_data[1], rect_data[2], rect_data[3])
            else:
                rect = rect_data
            is_hovered = rect.collidepoint(raw_mouse_x, raw_mouse_y)
            color = (255, 255, 0) if is_hovered else (0, 255, 0)
            pygame.draw.rect(screen, color, rect, 2)
            # 라벨
            label = font_small.render(f"Item{i}", True, color)
            screen.blit(label, (rect.x + 2, rect.y + 2))

        # === 2. 스매셔 스킬 아이콘 히트박스 (청록색) ===
        try:
            if selected_character_type == 'smasher':
                skill_rects = _smasher_skill_icon_rects
                surf_pos = _player_gauge_surface_left_screen_pos
                sf = GAME_SCALE_FACTOR

                for skill_name, local_rect in skill_rects.items():
                    # 로컬 좌표를 스크린 좌표로 변환
                    screen_x = surf_pos[0] + int(local_rect.x * sf)
                    screen_y = surf_pos[1] + int(local_rect.y * sf)
                    screen_w = int(local_rect.width * sf)
                    screen_h = int(local_rect.height * sf)
                    screen_rect = pygame.Rect(screen_x, screen_y, screen_w, screen_h)

                    is_hovered = screen_rect.collidepoint(raw_mouse_x, raw_mouse_y)
                    color = (255, 255, 0) if is_hovered else (0, 255, 255)
                    pygame.draw.rect(screen, color, screen_rect, 2)
                    # 라벨
                    label = font_small.render(skill_name[:6], True, color)
                    screen.blit(label, (screen_rect.x + 2, screen_rect.y + 2))
        except:
            pass

        # === 3. 마우스 위치 표시 (빨간 점 + 십자선) ===
        pygame.draw.circle(screen, (255, 0, 0), (raw_mouse_x, raw_mouse_y), 6)
        pygame.draw.circle(screen, (255, 255, 255), (raw_mouse_x, raw_mouse_y), 6, 1)
        # 십자선
        pygame.draw.line(screen, (255, 0, 0, 128), (raw_mouse_x - 15, raw_mouse_y), (raw_mouse_x + 15, raw_mouse_y), 1)
        pygame.draw.line(screen, (255, 0, 0, 128), (raw_mouse_x, raw_mouse_y - 15), (raw_mouse_x, raw_mouse_y + 15), 1)

        # === 4. 디버그 정보 패널 ===
        info_lines = [
            f"[F4] Coordinate Debug Mode",
            f"Mouse: ({raw_mouse_x}, {raw_mouse_y})",
            f"Item Slots: {len(slot_rects)}",
            f"Scale: {GAME_SCALE_FACTOR:.2f}x",
        ]
        panel_y = 10
        for line in info_lines:
            # 그림자
            shadow = font_info.render(line, True, (0, 0, 0))
            screen.blit(shadow, (11, panel_y + 1))
            # 텍스트
            text = font_info.render(line, True, (0, 255, 255))
            screen.blit(text, (10, panel_y))
            panel_y += 18

    except Exception as e:
        print(f"[COORDINATE_DEBUG ERROR] {e}", flush=True)


def _update_active_item_hover_state(now_ms: int) -> None:
    """마우스 호버 상태를 갱신하고 0.4초 이상 유지 시 게임을 일시정지한다."""
    global _active_item_hover_index, _active_item_hover_start_ms, _active_item_hover_rect
    global _active_item_tooltip_ready, _active_item_tooltip_title, _active_item_tooltip_body
    global game_paused_by_tooltip, _tooltip_prev_game_paused, _tooltip_forced_pause, game_paused

    # 버리기 메뉴가 활성화된 동안에는 툴팁 업데이트 안 함
    if _discard_menu_active:
        return

    if not active_item_slot:
        _reset_active_item_hover_state()
        return

    # 슬롯이 필러 영역(REAL_SCREEN 좌표)에 있으므로 원본 마우스 좌표 사용
    mouse_pos = _original_mouse_get_pos()
    slot_rects = _get_active_item_slot_rects()

    hovered = None
    for idx, rect_data in enumerate(slot_rects):
        # rect_data가 튜플이면 pygame.Rect로 변환
        if isinstance(rect_data, tuple):
            rect = pygame.Rect(rect_data[0], rect_data[1], rect_data[2], rect_data[3])
        else:
            rect = rect_data
        if rect.collidepoint(mouse_pos):
            hovered = (idx, rect)
            break

    if hovered is None:
        _reset_active_item_hover_state()
        return

    idx, rect = hovered
    if idx != _active_item_hover_index:
        _active_item_hover_index = idx
        _active_item_hover_rect = rect
        _active_item_hover_start_ms = now_ms
        _active_item_tooltip_ready = False
        # 기존 툴팁 일시정지를 해제하고 새로운 타이머 시작
        # (오딘의 늪/스매셔 스킬 툴팁 활성 시에는 건드리지 않음)
        if game_paused_by_tooltip and not _smasher_skill_tooltip_active and not _viper_skill_tooltip_active and not _odin_swamp_tooltip_active and not _quest_emblem_tooltip_active:
            game_paused = _tooltip_prev_game_paused
            game_paused_by_tooltip = False
            _tooltip_forced_pause = False
        return

    if _active_item_hover_start_ms is None:
        _active_item_hover_start_ms = now_ms
        return

    if not _active_item_tooltip_ready and now_ms - _active_item_hover_start_ms >= ACTIVE_ITEM_TOOLTIP_DELAY_MS:
        # 툴팁 정보 준비
        item = active_item_slot[idx] if idx < len(active_item_slot) else None
        if item:
            item_name = item.get("name") or item.get("effect")
            _active_item_tooltip_title = get_item_display_name(item) if 'get_item_display_name' in globals() else (item_name or "")
            _active_item_tooltip_body = get_item_description(item_name) if item_name else ""
            _active_item_tooltip_ready = True
            if not game_paused_by_tooltip:
                _tooltip_prev_game_paused = game_paused
                _tooltip_forced_pause = not _tooltip_prev_game_paused
                game_paused = True
                game_paused_by_tooltip = True


def _wrap_text_lines(text: str, font: pygame.font.Font, max_width: int) -> list[str]:
    """폰트 폭 기준으로 텍스트를 적절히 줄바꿈한다."""
    if not text:
        return []
    lines: list[str] = []
    for paragraph in text.split("\n"):
        words = paragraph.split(" ")
        current = ""
        for word in words:
            candidate = word if not current else current + " " + word
            if font.size(candidate)[0] <= max_width:
                current = candidate
            else:
                if current:
                    lines.append(current)
                current = word
        if current:
            lines.append(current)
    return lines


def _draw_active_item_hover_tooltip() -> None:
    """호버 중인 액티브 아이템의 설명 툴팁을 그린다."""
    if not _active_item_tooltip_ready:
        return

    # 슬롯 위치 복원(창 리사이즈에 대응)
    rect = _active_item_hover_rect
    slot_rects = _get_active_item_slot_rects()
    if rect is None and _active_item_hover_index is not None and _active_item_hover_index < len(slot_rects):
        rect_data = slot_rects[_active_item_hover_index]
        # rect_data가 튜플이면 pygame.Rect로 변환
        if isinstance(rect_data, tuple):
            rect = pygame.Rect(rect_data[0], rect_data[1], rect_data[2], rect_data[3])
        else:
            rect = rect_data
    # rect가 튜플이면 pygame.Rect로 변환
    if rect is not None and isinstance(rect, tuple):
        rect = pygame.Rect(rect[0], rect[1], rect[2], rect[3])
    if rect is None:
        return

    try:
        title_font = FontStyle.menu()
        body_font = FontStyle.body()
    except Exception:
        title_font = pygame.font.Font(None, 20)
        body_font = pygame.font.Font(None, 16)

    max_body_width = 280
    title_surface = title_font.render(_active_item_tooltip_title or "", True, (255, 255, 255))
    body_lines = _wrap_text_lines(_active_item_tooltip_body, body_font, max_body_width)
    body_surfaces = [body_font.render(line, True, (220, 225, 240)) for line in body_lines]

    padding = 10
    line_spacing = 4
    content_width = max([title_surface.get_width(), *[s.get_width() for s in body_surfaces]] or [0])
    content_height = title_surface.get_height() + (len(body_surfaces) * (body_font.get_height() + line_spacing))
    box_width = min(max_body_width + padding * 2, content_width + padding * 2)
    box_height = content_height + padding * 2 + (4 if body_surfaces else 0)

    # 기본 위치: 슬롯 오른쪽, 화면 밖으로 나가면 위쪽/왼쪽으로 보정
    screen_w = SCREEN.get_width() if 'SCREEN' in globals() and SCREEN else 600
    screen_h = SCREEN.get_height() if 'SCREEN' in globals() and SCREEN else 750
    box_x = rect.right + 12
    box_y = rect.top - 6
    if box_x + box_width > screen_w - 8:
        box_x = max(8, rect.left - box_width - 12)
    if box_y + box_height > screen_h - 8:
        box_y = max(8, screen_h - box_height - 8)

    box_surface = pygame.Surface((box_width, box_height), pygame.SRCALPHA)
    box_surface.fill((16, 18, 28, 230))
    pygame.draw.rect(box_surface, (90, 130, 200), box_surface.get_rect(), 1, border_radius=6)

    y = padding
    box_surface.blit(title_surface, (padding, y))
    y += title_surface.get_height() + 6
    for surface in body_surfaces:
        box_surface.blit(surface, (padding, y))
        y += surface.get_height() + line_spacing

    # 가볍게 그림자 드롭
    shadow = pygame.Surface((box_width + 4, box_height + 4), pygame.SRCALPHA)
    pygame.draw.rect(shadow, (0, 0, 0, 120), shadow.get_rect(), border_radius=8)
    SCREEN.blit(shadow, (box_x + 2, box_y + 2))
    SCREEN.blit(box_surface, (box_x, box_y))


def _draw_active_item_hover_tooltip_on_screen(target_screen) -> None:
    """호버 중인 액티브 아이템의 설명 툴팁을 지정된 screen에 그린다.

    Args:
        target_screen: 그릴 대상 surface (REAL_SCREEN)
    """
    if not _active_item_tooltip_ready:
        return

    # 슬롯 위치 복원(창 리사이즈에 대응)
    rect = _active_item_hover_rect
    slot_rects = _get_active_item_slot_rects()
    if rect is None and _active_item_hover_index is not None and _active_item_hover_index < len(slot_rects):
        rect_data = slot_rects[_active_item_hover_index]
        # rect_data가 튜플이면 pygame.Rect로 변환
        if isinstance(rect_data, tuple):
            rect = pygame.Rect(rect_data[0], rect_data[1], rect_data[2], rect_data[3])
        else:
            rect = rect_data
    # rect가 튜플이면 pygame.Rect로 변환
    if rect is not None and isinstance(rect, tuple):
        rect = pygame.Rect(rect[0], rect[1], rect[2], rect[3])
    if rect is None:
        return

    try:
        title_font = FontStyle.menu()
        body_font = FontStyle.body()
    except Exception:
        title_font = pygame.font.Font(None, 20)
        body_font = pygame.font.Font(None, 16)

    max_body_width = 280
    title_surface = title_font.render(_active_item_tooltip_title or "", True, (255, 255, 255))
    body_lines = _wrap_text_lines(_active_item_tooltip_body, body_font, max_body_width)
    body_surfaces = [body_font.render(line, True, (220, 225, 240)) for line in body_lines]

    padding = 10
    line_spacing = 4
    content_width = max([title_surface.get_width(), *[s.get_width() for s in body_surfaces]] or [0])
    content_height = title_surface.get_height() + (len(body_surfaces) * (body_font.get_height() + line_spacing))
    box_width = min(max_body_width + padding * 2, content_width + padding * 2)
    box_height = content_height + padding * 2 + (4 if body_surfaces else 0)

    # target_screen 기준으로 화면 크기 사용
    screen_w = target_screen.get_width() if target_screen else 760
    screen_h = target_screen.get_height() if target_screen else 750

    # 기본 위치: 슬롯 위쪽 (하단에 있으므로)
    box_x = rect.centerx - box_width // 2
    box_y = rect.top - box_height - 8

    # 화면 경계 보정
    if box_x < 8:
        box_x = 8
    if box_x + box_width > screen_w - 8:
        box_x = screen_w - box_width - 8
    if box_y < 8:
        box_y = rect.bottom + 8  # 위로 못 가면 아래로

    # 그림자 포함 전체를 중간 서피스에 그린 뒤 스케일링
    _total_w = box_width + 4
    _total_h = box_height + 4
    _tip_surf = pygame.Surface((_total_w, _total_h), pygame.SRCALPHA)

    # 그림자
    pygame.draw.rect(_tip_surf, (0, 0, 0, 120), (2, 2, box_width + 4, box_height + 4), border_radius=8)
    # 본체
    _box_inner = pygame.Surface((box_width, box_height), pygame.SRCALPHA)
    _box_inner.fill((16, 18, 28, 230))
    pygame.draw.rect(_box_inner, (90, 130, 200), _box_inner.get_rect(), 1, border_radius=6)

    y = padding
    _box_inner.blit(title_surface, (padding, y))
    y += title_surface.get_height() + 6
    for surface in body_surfaces:
        _box_inner.blit(surface, (padding, y))
        y += surface.get_height() + line_spacing
    _tip_surf.blit(_box_inner, (0, 0))

    _blit_scaled_tooltip(target_screen, _tip_surf, box_x, box_y, _total_w, _total_h)


# --- 액티브 아이템 버리기 메뉴 함수 ---
def _open_discard_menu(slot_index: int, slot_rect: pygame.Rect) -> None:
    """우클릭으로 버리기 메뉴를 연다."""
    global _discard_menu_active, _discard_menu_item_index, _discard_menu_rect
    global _discard_button_rect, _discard_prev_game_paused, _discard_forced_pause, game_paused

    if slot_index >= len(active_item_slot):
        return
    if active_item_slot[slot_index] is None:
        return

    # 툴팁이 열려있으면 먼저 닫기
    _reset_active_item_hover_state()

    _discard_menu_item_index = slot_index
    _discard_menu_rect = slot_rect
    _discard_menu_active = True

    # 게임 일시정지
    _discard_prev_game_paused = game_paused
    _discard_forced_pause = not game_paused
    game_paused = True


def _close_discard_menu() -> None:
    """버리기 메뉴를 닫고 일시정지를 복원한다."""
    global _discard_menu_active, _discard_menu_item_index, _discard_menu_rect
    global _discard_button_rect, _discard_prev_game_paused, _discard_forced_pause, game_paused

    if _discard_menu_active and _discard_forced_pause:
        game_paused = _discard_prev_game_paused

    _discard_menu_active = False
    _discard_menu_item_index = None
    _discard_menu_rect = None
    _discard_button_rect = None
    _discard_forced_pause = False


def _discard_active_item(slot_index: int) -> None:
    """액티브 아이템 슬롯에서 아이템을 제거한다."""
    global active_item_slot, selected_item_index

    if slot_index < 0 or slot_index >= len(active_item_slot):
        return

    removed_item = active_item_slot[slot_index]
    if removed_item is None:
        return

    item_name = removed_item.get("name") or removed_item.get("effect", "unknown")
    print(f"[DISCARD] 아이템 버림: {item_name} (슬롯 {slot_index})")

    # 슬롯에서 아이템 제거
    active_item_slot.pop(slot_index)

    # 선택된 인덱스 조정
    if selected_item_index >= len(active_item_slot):
        selected_item_index = max(0, len(active_item_slot) - 1)


def _draw_discard_menu_on_screen(target_screen) -> None:
    """버리기 메뉴를 화면에 그린다."""
    global _discard_button_rect

    if not _discard_menu_active or _discard_menu_item_index is None:
        return

    slot_rect = _discard_menu_rect
    if slot_rect is None:
        slot_rects = _get_active_item_slot_rects()
        if _discard_menu_item_index < len(slot_rects):
            rect_data = slot_rects[_discard_menu_item_index]
            if isinstance(rect_data, tuple):
                slot_rect = pygame.Rect(rect_data[0], rect_data[1], rect_data[2], rect_data[3])
            else:
                slot_rect = rect_data
    if slot_rect is None:
        return

    # 폰트 설정
    try:
        menu_font = FontStyle.menu()
    except Exception:
        menu_font = pygame.font.Font(None, 20)

    # 버튼 크기 및 위치 계산
    button_text = "버리기"
    text_surface = menu_font.render(button_text, True, (255, 255, 255))
    padding_x = 16
    padding_y = 8
    button_width = text_surface.get_width() + padding_x * 2
    button_height = text_surface.get_height() + padding_y * 2

    # 슬롯 위에 버튼 위치 (화면 경계 보정)
    screen_w = target_screen.get_width()
    screen_h = target_screen.get_height()

    button_x = slot_rect.centerx - button_width // 2
    button_y = slot_rect.top - button_height - 8

    # 화면 경계 보정
    if button_x < 8:
        button_x = 8
    if button_x + button_width > screen_w - 8:
        button_x = screen_w - button_width - 8
    if button_y < 8:
        button_y = slot_rect.bottom + 8

    _discard_button_rect = pygame.Rect(button_x, button_y, button_width, button_height)

    # 마우스 호버 체크
    mouse_pos = _original_mouse_get_pos()
    is_hovered = _discard_button_rect.collidepoint(mouse_pos)

    # 버튼 배경
    if is_hovered:
        bg_color = (180, 60, 60, 240)  # 호버 시 더 밝은 빨강
        border_color = (255, 100, 100)
    else:
        bg_color = (120, 40, 40, 230)  # 기본 어두운 빨강
        border_color = (200, 80, 80)

    # 그림자
    shadow = pygame.Surface((button_width + 4, button_height + 4), pygame.SRCALPHA)
    pygame.draw.rect(shadow, (0, 0, 0, 100), shadow.get_rect(), border_radius=6)
    target_screen.blit(shadow, (button_x + 2, button_y + 2))

    # 버튼 배경
    button_surface = pygame.Surface((button_width, button_height), pygame.SRCALPHA)
    button_surface.fill(bg_color)
    pygame.draw.rect(button_surface, border_color, button_surface.get_rect(), 2, border_radius=5)
    target_screen.blit(button_surface, (button_x, button_y))

    # 텍스트
    text_x = button_x + (button_width - text_surface.get_width()) // 2
    text_y = button_y + (button_height - text_surface.get_height()) // 2
    target_screen.blit(text_surface, (text_x, text_y))


def _handle_discard_menu_click(mouse_pos) -> bool:
    """버리기 메뉴 클릭을 처리한다. 처리했으면 True 반환."""
    global _discard_menu_active

    if not _discard_menu_active:
        return False

    # 버리기 버튼 클릭 체크
    if _discard_button_rect and _discard_button_rect.collidepoint(mouse_pos):
        if _discard_menu_item_index is not None:
            _discard_active_item(_discard_menu_item_index)
        _close_discard_menu()
        return True

    # 다른 곳 클릭 시 메뉴 닫기 (취소)
    _close_discard_menu()
    return True


