def get_item_slot_label(item_name: str) -> str | None:
    """아이템 이름을 받아 해당 장비 부위 라벨을 반환한다."""
    base_slot = ITEM_SLOT_BASE_MAP.get(item_name)
    if not base_slot:
        return None
    fallback = _BASE_SLOT_LABELS.get(base_slot, base_slot)
    return _t(f"equip.base.{base_slot}", fallback)


def roll_passive_options(item_name: str) -> list[dict]:
    """패시브 아이템 옵션을 범위 내에서 롤링해 반환."""
    rng = random.SystemRandom()  # 전역 시드와 무관하게 항상 새 난수 사용
    ranges = PASSIVE_OPTION_RANGES.get(item_name)
    if not ranges:
        return []
    rolled = []
    for opt in ranges:
        v_min, v_max = opt["min"], opt["max"]
        val = rng.randint(v_min, v_max)
        # 퍼센타일 기반 색상 구분 (reverse=True이면 낮을수록 고옵)
        reverse = opt.get("reverse", False)
        if v_max == v_min:
            pct = 1.0
        else:
            pct = (val - v_min) / (v_max - v_min)
            if reverse:
                pct = 1.0 - pct
        # 최상옵(최대치)은 빨간색, 그 외 3등분
        if (not reverse and val == v_max) or (reverse and val == v_min):
            color = _OPTION_COLOR_TOP
        elif pct <= 1/3:
            color = _OPTION_COLOR_LOW
        elif pct <= 2/3:
            color = _OPTION_COLOR_MID
        else:
            color = _OPTION_COLOR_HIGH
        text = f"{opt['label']} {opt.get('prefix','')}{val}{opt.get('unit','')}"
        rolled.append({"text": text, "color": color, "key": opt.get("key"), "value": val, "unit": opt.get("unit", "")})
    return rolled


def ensure_passive_rolls(item_data: dict) -> None:
    """패시브 아이템에 롤 옵션이 없으면 생성해서 주입."""
    try:
        if item_data.get("type") != "passive":
            return
        if "rolled_options" in item_data and item_data["rolled_options"]:
            return
        name = item_data.get("name")
        if not name:
            return
        rolled = roll_passive_options(name)
        if rolled:
            item_data["rolled_options"] = rolled
            assign_item_prefix(item_data)
    except Exception:
        # 롤링 실패 시 조용히 패스
        pass


def roll_legendary_options(item_name: str) -> list[dict]:
    """전설 아이템 옵션을 LEGENDARY_ROLL_OPTIONS에서 범위 내 롤링해 반환."""
    from legendary_items import LEGENDARY_ROLL_OPTIONS
    rng = random.SystemRandom()
    ranges = LEGENDARY_ROLL_OPTIONS.get(item_name)
    if not ranges:
        return []
    rolled = []
    for opt in ranges:
        v_min, v_max = opt["min"], opt["max"]
        step = opt.get("step", 1)
        if step < 1:
            # 소수점 스텝
            steps = int((v_max - v_min) / step) + 1
            val = v_min + rng.randint(0, steps - 1) * step
            val = round(val, 2)
        else:
            val = rng.randint(int(v_min), int(v_max))
        # 퍼센타일 기반 색상
        reverse = opt.get("reverse", False)
        if v_max == v_min:
            pct = 1.0
        else:
            pct = (val - v_min) / (v_max - v_min)
            if reverse:
                pct = 1.0 - pct
        if (not reverse and val == v_max) or (reverse and val == v_min):
            color = _OPTION_COLOR_TOP
        elif pct <= 1/3:
            color = _OPTION_COLOR_LOW
        elif pct <= 2/3:
            color = _OPTION_COLOR_MID
        else:
            color = _OPTION_COLOR_HIGH
        prefix = opt.get("prefix", "")
        text = f"{opt['label']} {prefix}{val}{opt.get('unit','')}"
        rolled.append({"text": text, "color": color, "key": opt.get("key"), "value": val, "unit": opt.get("unit", ""), "min": v_min, "max": v_max, "reverse": reverse})
    return rolled


def get_item_legendary_roll_value(item: dict, option_key: str, apply_polish: bool = False) -> float:
    """아이템의 개별 rolled_options에서 롤 값을 가져옴. 없으면 전역 딕셔너리 사용.

    Args:
        item: 아이템 딕셔너리 (rolled_options 포함 가능)
        option_key: 롤 옵션 키 (예: "speed_bonus", "cooldown")
        apply_polish: 연마 퍽 보너스 적용 여부

    Returns:
        롤 옵션 값 (개별 아이템 → 전역 딕셔너리 → 기본값 순으로 탐색)
    """
    # 1. 아이템의 개별 rolled_options에서 먼저 찾기
    rolled_opts = item.get("rolled_options", [])
    for opt in rolled_opts:
        if opt.get("key") == option_key:
            base_value = opt.get("value", 0)
            if apply_polish and base_value != 0:
                # 연마 퍽 보너스 적용
                try:
                    polish_mult = get_effective_polish_multiplier()
                    enhancement_pct = item.get("enhancement_bonus_pct", 0)
                    total_mult = polish_mult
                    if enhancement_pct > 0:
                        total_mult = total_mult * (1 + enhancement_pct / 100)

                    # reverse 옵션 확인
                    is_reverse = opt.get("reverse", False)
                    if is_reverse:
                        return base_value / total_mult
                    else:
                        return base_value * total_mult
                except Exception:
                    pass
            return base_value

    # 2. 전역 딕셔너리에서 찾기 (fallback)
    item_name = item.get("name", "")
    enhancement_pct = item.get("enhancement_bonus_pct", 0)
    return get_legendary_roll_value(item_name, option_key, apply_polish, enhancement_pct)


def ensure_legendary_rolls(item_data: dict) -> None:
    """전설 아이템에 롤 옵션이 없으면 생성해서 주입."""
    try:
        if item_data.get("type") != "legendary":
            return
        if "rolled_options" in item_data and item_data["rolled_options"]:
            return
        name = item_data.get("name")
        if not name:
            return
        rolled = roll_legendary_options(name)
        if rolled:
            item_data["rolled_options"] = rolled
            assign_item_prefix(item_data)
    except Exception:
        pass


def format_roll_option_with_polish(opt: dict, item: dict = None) -> str:
    """롤 옵션 텍스트에 연마 스킬 보너스 + 강화 보너스를 추가하여 반환.

    예: "이동속도 +6%" → "이동속도 +6% (+1%)" (연마 Lv1, 30% 보너스)
    예: "대쉬쿨타임 -20%" → "대쉬쿨타임 -20% (-5%)" (감소 효과는 더 감소)
    예: "자동대쉬 쿨타임 15초" (reverse=True) → "자동대쉬 쿨타임 15초 (-2초)" (낮을수록 좋음)
    강화 보너스도 동일하게 적용됨
    """
    base_text = opt.get("text") or ""
    base_value = opt.get("value")
    opt_key = opt.get("key", "")

    # opt에서 먼저 prefix/reverse 확인, 없으면 PASSIVE_OPTION_RANGES에서 가져오기
    prefix = opt.get("prefix")
    is_reverse = opt.get("reverse")

    # 아이템에서 옵션 메타데이터 가져오기 (reverse, prefix 정보)
    if item and opt_key and (prefix is None or is_reverse is None):
        item_name = item.get("name", "")
        option_meta = _get_option_meta(item_name, opt_key)
        if option_meta:
            if prefix is None:
                prefix = option_meta.get("prefix", "+")
            if is_reverse is None:
                is_reverse = option_meta.get("reverse", False)

    # 기본값 설정
    if prefix is None:
        prefix = "+"
    if is_reverse is None:
        is_reverse = False

    # 값이 없거나 0이면 원본 텍스트 반환
    if base_value is None or base_value == 0:
        return base_text

    # 연마 스킬 배율 확인 (아카데미 + 런타임)
    try:
        polish_multiplier = get_effective_polish_multiplier()
    except Exception:
        polish_multiplier = 1.0

    # 강화 보너스 확인
    enhancement_bonus_pct = 0
    if item:
        enhancement_bonus_pct = item.get("enhancement_bonus_pct", 0)

    # 총 배율 계산
    total_multiplier = polish_multiplier
    if enhancement_bonus_pct > 0:
        total_multiplier = total_multiplier * (1 + enhancement_bonus_pct / 100)

    # 보너스가 없으면 원본 텍스트 반환
    if total_multiplier <= 1.0:
        return base_text

    # 단위 가져오기 (%, pt, 초, px 등)
    unit = opt.get("unit", "")

    # reverse=True인 경우 (낮을수록 좋은 옵션): 값이 감소해야 함
    if is_reverse:
        # 강화 시 값이 감소 (예: 15초 → 15 / 1.36 = 11초)
        reduced_value = int(abs(base_value) / total_multiplier)
        reduction = abs(base_value) - reduced_value
        if reduction == 0:
            return base_text
        return f"{base_text} (-{reduction}{unit})"

    # 일반 옵션: 보너스 값 계산
    boosted_value = int(abs(base_value) * total_multiplier)
    bonus_value = boosted_value - abs(base_value)

    # 보너스가 없으면 원본 반환
    if bonus_value == 0:
        return base_text

    # prefix에 따라 보너스 표시 방식 결정
    # prefix가 "-"인 경우 (쿨타임 감소 등): 감소량이 증가 → "-5%" 형태로 표시
    # prefix가 "+"인 경우 (이동속도 증가 등): 증가량이 증가 → "+5%" 형태로 표시
    if prefix == "-":
        # 감소 효과: 감소량이 더 증가함을 표시 (예: -20% → -20% (-5%))
        return f"{base_text} (-{bonus_value}{unit})"
    else:
        # 증가 효과: 증가량 표시
        return f"{base_text} (+{bonus_value}{unit})"


def _reset_roll_bonuses_to_default():
    globals()["dashgear_distance_bonus_pct"] = 9  # 대쉬 거리 기본값 (6~12%)
    globals()["dashgear_boost_charge_pct"] = 7  # 부스트차징 발동확률 기본값 (4~10%)
