def get_player_stun_resist_pct() -> float:
    """방탄모자 등으로 누적된 스턴 저항(0~100)을 반환."""
    try:
        return max(0.0, min(100.0, float(bulletproof_hat_resist_pct)))
    except Exception:
        return 0.0


def get_player_knockback_resist_pct() -> float:
    """가시투구 등으로 누적된 넉백 저항(0~100)을 반환."""
    try:
        return max(0.0, min(100.0, float(spiked_helmet_knockback_resist_pct)))
    except Exception:
        return 0.0

# 넉백 디버그 토글 (환경변수 PINGF_DEBUG_KNOCKBACK=1)
_KB_DEBUG = os.environ.get("PINGF_DEBUG_KNOCKBACK", "0").lower() in ("1", "true", "yes", "on", "debug")

def _kb_debug(msg: str) -> None:
    if _KB_DEBUG:
        try:
            print(f"[KBDBG] {msg}")
        except Exception:
            pass

def _get_knockback_resist_scale() -> float:
    """넉백 저항을 거리/시간에 곱할 스케일 값(0~1)로 변환."""
    try:
        return max(0.0, 1.0 - get_player_knockback_resist_pct() / 100.0)
    except Exception:
        return 1.0


def apply_knockback_resist(value: float) -> float:
    """플레이어 넉백 속도/거리 값을 저항만큼 줄여 반환."""
    # 클렌즈 면역 상태 체크
    if is_cleanse_immune():
        _kb_debug(f"apply_knockback_resist: 클렌즈 면역으로 넉백 무시 (원래값: {value:.2f})")
        return 0.0

    scale = _get_knockback_resist_scale()
    out = value * scale
    _kb_debug(f"apply_knockback_resist: in={value:.2f}, scale={scale:.3f}, out={out:.2f}")
    return out


def clear_player_knockback_if_immune() -> None:
    """넉백 저항 100%일 때 남아있는 넉백 속도/오프셋을 즉시 제거."""
    scale = _get_knockback_resist_scale()
    if scale <= 0.0:
        global player_knockback_vel, player_missile_knockback_vel
        global player_flame_zone_knockback_vel, player_knockback_y
        global smasher_power_recoil_timer, smasher_power_recoil_vel
        _kb_debug(f"immune: clearing velocities vk={player_knockback_vel:.2f}, vm={player_missile_knockback_vel:.2f}, vf={player_flame_zone_knockback_vel:.2f}, vy={player_knockback_y:.2f}")
        player_knockback_vel = 0
        player_missile_knockback_vel = 0
        player_flame_zone_knockback_vel = 0
        player_knockback_y = 0
        smasher_power_recoil_timer = 0
        smasher_power_recoil_vel = 0.0
        smasher_power_recoil_pending_dir = 0
        smasher_power_recoil_stun_pending = False


def try_apply_player_stun(stun_seconds: float, *, source: str = "", knockback_scaled: bool = False) -> float:
    """스턴/넉백 상황에서 스턴 지속시간을 줄인 뒤 적용한다.

    Returns:
        적용된 스턴 지속시간(초). 0이면 스턴 미적용.
    """
    global player_stunned_timer

    # 클렌즈 면역 상태 체크
    if is_cleanse_immune():
        # if source:
        #     print(f"[STUN-IMMUNE] {source} 무시 (클렌즈 면역 상태)")  # 디버그 비활성화
        return 0.0

    resist_pct = get_player_stun_resist_pct()
    final_seconds = max(0.0, stun_seconds * (1.0 - resist_pct / 100.0))
    if knockback_scaled:
        final_seconds *= _get_knockback_resist_scale()
    if final_seconds <= 0:
        # if source:
        #     print(f"[STUN-RESIST] {source} 무시 (지속시간 0, 저항 {resist_pct:.1f}%)")  # 디버그 비활성화
        return 0.0
    player_stunned_timer = max(player_stunned_timer, int(final_seconds * FPS))
    # if source:
    #     print(f"[STUN] {source} 적용: {stun_seconds:.2f}s → {final_seconds:.2f}s (저항 {resist_pct:.1f}%)")  # 디버그 비활성화
    return final_seconds


def _get_roll_value(item: dict, key: str, apply_polish: bool = True) -> int | None:
    """롤 옵션 값을 가져온다. apply_polish=True면 연마 스킬 효과 + 강화 보너스 적용."""
    for opt in item.get("rolled_options") or []:
        if opt.get("key") == key:
            base_value = int(opt.get("value", 0))

            # opt에서 reverse 확인, 없으면 PASSIVE_OPTION_RANGES에서 가져오기
            is_reverse = opt.get("reverse")
            if is_reverse is None:
                item_name = item.get("name", "")
                option_meta = _get_option_meta(item_name, key)
                if option_meta:
                    is_reverse = option_meta.get("reverse", False)
                else:
                    is_reverse = False

            # 연마 스킬 효과 + 강화 보너스 적용
            if apply_polish and base_value != 0:
                # 총 배율 계산
                total_multiplier = 1.0
                try:
                    polish_multiplier = get_effective_polish_multiplier()
                    total_multiplier = polish_multiplier
                except Exception:
                    pass

                # 강화 보너스 적용 (대장간 강화 시스템)
                enhancement_bonus_pct = item.get("enhancement_bonus_pct", 0)
                if enhancement_bonus_pct > 0:
                    total_multiplier = total_multiplier * (1 + enhancement_bonus_pct / 100)

                # reverse=True인 경우 (낮을수록 좋은 옵션): 값이 감소
                # 예: 쿨타임 15초, 강화 36% → 15 / 1.36 = 11초
                if is_reverse and total_multiplier > 1.0:
                    base_value = int(base_value / total_multiplier)
                elif total_multiplier > 1.0:
                    # 일반 옵션: 값이 증가
                    base_value = int(base_value * total_multiplier)

            return base_value
    return None


def apply_sensor_cooldown_option(item_data: dict) -> None:
    """센서 롤 옵션을 전역 쿨타임(ms)으로 반영."""
    val_sec = _get_roll_value(item_data, "sensor_cooldown_sec")

    if val_sec:
        globals()["danger_sensor_cooldown_ms"] = int(val_sec * 1000)
    else:
        globals()["danger_sensor_cooldown_ms"] = 15000  # 기본값


def _get_option_range(item_name: str, key: str) -> tuple[int, int] | None:
    ranges = PASSIVE_OPTION_RANGES.get(item_name)
    if not ranges:
        return None
    for opt in ranges:
        if opt.get("key") == key:
            return opt.get("min", 0), opt.get("max", 0)
    return None


def _get_option_meta(item_name: str, key: str) -> dict | None:
    """옵션 메타데이터( reverse 포함 )를 반환."""
    ranges = PASSIVE_OPTION_RANGES.get(item_name)
    if not ranges:
        return None
    for opt in ranges:
        if opt.get("key") == key:
            return opt
    return None


def assign_item_prefix(item_data: dict, *, force: bool = False) -> None:
    """롤 옵션 평균 품질에 따라 수식어를 부여.

    force=False(기본값)일 때는 이미 계산된 수식어/등급이 있으면 그대로 유지해
    가챠 결과 화면과 캐릭터 정보창 사이의 불일치를 방지한다.
    """

    rolled = item_data.get("rolled_options")
    if not rolled:
        return

    # 가챠에서 이미 부여된 수식어/등급이 있다면 덮어쓰지 않는다.
    if not force and item_data.get("name_prefix") and item_data.get("quality_tier"):
        # 품질 색상 누락 시에만 보정
        if not item_data.get("quality_color"):
            item_data["quality_color"] = QUALITY_TIER_COLOR.get(
                item_data["quality_tier"], _OPTION_COLOR_LOW
            )
        return

    percents = []
    for opt in rolled:
        key = opt.get("key")
        meta = _get_option_meta(item_data.get("name", ""), key) if key else None
        if not meta:
            continue
        vmin, vmax = meta.get("min", 0), meta.get("max", 0)
        val = opt.get("value", vmin)
        if vmax == vmin:
            pct = 1.0
        else:
            pct_raw = max(0.0, min(1.0, (val - vmin) / (vmax - vmin)))
            pct = 1.0 - pct_raw if meta.get("reverse") else pct_raw
        percents.append(pct)
    if not percents:
        return
    avg_pct = sum(percents) / len(percents)
    if avg_pct >= 0.99:
        tier = "top"
    elif avg_pct >= 2/3:
        tier = "high"
    elif avg_pct >= 1/3:
        tier = "mid"
    else:
        tier = "low"
    import random
    prefix_list = _get_loc().get_list(f"quality.{tier}", QUALITY_PREFIXES.get(tier, [""]))
    prefix = random.choice(prefix_list) if prefix_list else ""
    item_data["name_prefix"] = prefix
    item_data["quality_tier"] = tier
    item_data["quality_color"] = QUALITY_TIER_COLOR.get(tier, _OPTION_COLOR_LOW)


def apply_roll_bonuses_from_equipped():
    """장착된 패시브 아이템들의 롤 옵션을 글로벌 보너스로 반영."""
    _reset_roll_bonuses_to_default()
    try:
        equipped = get_equipped_passive_items()
    except Exception:
        equipped = []
    fuel_pouch_total_bonus = 0
    bluetooth_ring_total_gain = 0
    chargebag_total_bonus = 0
    cooltime_total_reduction = 0
    star_detector_total_bonus = 0
    foul_whistle_total_negate = 0
    master_wall_total = 0
    master_cooldown_total = 0

    for item in equipped:
        name = item.get("name")
        if name == "dashgear":
            val = _get_roll_value(item, "dash_distance_pct")
            if val is not None:
                globals()["dashgear_distance_bonus_pct"] = val
            val = _get_roll_value(item, "boost_charge_pct")
            if val is not None:
                globals()["dashgear_boost_charge_pct"] = val
        elif name == "spikeboots":
            val = _get_roll_value(item, "dash_afterdelay_pct")
            if val is not None:
                globals()["spikeboots_afterdelay_reduction_pct"] = val
            val = _get_roll_value(item, "dash_cooldown_pct")
            if val is not None:
                globals()["spikeboots_cooldown_reduction_pct"] = val
        elif name == "speedboots":
            val = _get_roll_value(item, "speed_bonus_pct")
            if val is not None:
                globals()["PERMANENT_SPEED_BOOST"] = val / 100.0
        elif name == "master":
            val = _get_roll_value(item, "wall_length_pct")
            if val is None:
                val = 30
            master_wall_total += val
            val = _get_roll_value(item, "item_cooldown_pct")
            if val is None:
                val = 10
            master_cooldown_total += val
        elif name == "foul_whistle":
            val = _get_roll_value(item, "negate_chance_pct")
            if val is None:
                val = 10
            foul_whistle_total_negate += val
        elif name == "star_detector":
            val = _get_roll_value(item, "star_bonus_pct")
            if val is None:
                val = 30
            star_detector_total_bonus += val
        elif name == "cooltime":
            val = _get_roll_value(item, "active_cooldown_pct")
            if val is None:
                val = 30
            cooltime_total_reduction += val
        elif name == "bluetooth_ring":
            val = _get_roll_value(item, "gauge_gain_pct")
            if val is None:
                val = 15
            bluetooth_ring_total_gain += val
        elif name == "chargebag":
            val = _get_roll_value(item, "chargebag_pct")
            if val is None:
                val = 20
            chargebag_total_bonus += val
        elif name == "technical_vest":
            trigger_pct = _get_roll_value(item, "smoke_trigger_pct")
            duration_sec = _get_roll_value(item, "smoke_duration_sec")
            try:
                from item_effects.technical_vest import configure_technical_vest
                configure_technical_vest(
                    chance_pct=trigger_pct if trigger_pct is not None else 15,
                    duration_sec=duration_sec if duration_sec is not None else 5,
                )
            except Exception:
                pass
        elif name == "commando_arm":
            val = _get_roll_value(item, "throw_speed_pct")
            if val is not None:
                globals()["commando_throw_speed_pct"] = val
            val = _get_roll_value(item, "explosion_range_pct")
            if val is not None:
                globals()["commando_explosion_range_pct"] = val
            val = _get_roll_value(item, "smoke_duration_pct")
            if val is not None:
                globals()["commando_smoke_duration_pct"] = val
            val = _get_roll_value(item, "prep_reduction_pct")
            if val is not None:
                globals()["commando_prep_reduction_pct"] = val
        elif name == "knee_pads":
            val = _get_roll_value(item, "knee_charge_pct")
            if val is not None:
                globals()["knee_pads_charge_pct"] = val
        elif name == "fuel_pouch":
            val = _get_roll_value(item, "fuel_bonus_flat")
            if val is None:
                val = 100
            fuel_pouch_total_bonus += val
        elif name == "bulletproof_hat":
            val = _get_roll_value(item, "stun_resist_pct")
            if val is None:
                val = 50
            globals()["bulletproof_hat_resist_pct"] = max(bulletproof_hat_resist_pct, val)
        elif name == "spiked_helmet":
            val = _get_roll_value(item, "knockback_resist_pct")
            if val is None:
                try:
                    rng = PASSIVE_OPTION_RANGES.get("spiked_helmet", [{}])[0]
                    val = rng.get("max", 100)
                except Exception:
                    val = 100
            globals()["spiked_helmet_knockback_resist_pct"] = max(spiked_helmet_knockback_resist_pct, val)
            _kb_debug(f"equip calc spiked_helmet -> {spiked_helmet_knockback_resist_pct}")
        elif name == "bulkup":
            val = _get_roll_value(item, "body_size_pct")
            if val is not None:
                globals()["bulkup_body_size_pct"] = val
        elif name == "battery":
            val = _get_roll_value(item, "gauge_preserve_pct")
            if val is not None:
                globals()["battery_gauge_preserve_pct"] = val
        elif name == "sage_ring":
            val = _get_roll_value(item, "sage_speed_penalty_pct")
