def fire_snake_fireball(real_x: int, real_y: int, target_x: int, target_y: int, side: str = None):
    """뱀 항아리에서 화염탄 발사 (광폭화 모드 전용)

    Args:
        real_x, real_y: 발사 위치 (REAL_SCREEN 좌표)
        target_x, target_y: 플레이어 위치 (내부 게임 좌표 760x750)
        side: 'left' 또는 'right' (어느 필러에서 발사했는지)
    """
    global fireballs

    # REAL_SCREEN 좌표 → 내부 좌표 변환
    # 스케일링 시 추가 오프셋 계산
    if GAME_SCALE_FACTOR != 1.0:
        sw = int(WIDTH * GAME_SCALE_FACTOR)
        sh = int(HEIGHT * GAME_SCALE_FACTOR)
        additional_offset_x = (GAME_SCALED_WIDTH - sw) // 2
        additional_offset_y = (GAME_SCALED_HEIGHT - sh) // 2
    else:
        additional_offset_x = 0
        additional_offset_y = 0

    # 전체 오프셋 (REAL_SCREEN 상에서 게임 영역 시작점)
    total_offset_x = GAME_OFFSET_X + additional_offset_x
    total_offset_y = GAME_OFFSET_Y + additional_offset_y

    # REAL 좌표 → 내부 좌표 변환 (X와 Y 모두 동일한 공식 사용)
    game_start_x = (real_x - total_offset_x) / GAME_SCALE_FACTOR if GAME_SCALE_FACTOR > 0 else float(real_x)
    game_start_y = (real_y - total_offset_y) / GAME_SCALE_FACTOR if GAME_SCALE_FACTOR > 0 else float(real_y)

    # X 좌표가 전체 내부 영역(0~760) 밖이면 경계로 살짝 조정
    # 필러 UI 영역(0~79, 680~759)에서 시작해도 괜찮음 - 자연스럽게 게임 영역으로 이동
    if game_start_x < 0:
        game_start_x = 3.0  # 왼쪽 경계
    elif game_start_x > INTERNAL_WIDTH:
        game_start_x = float(INTERNAL_WIDTH - 3)  # 오른쪽 경계

    # 타겟은 이미 내부 좌표
    game_target_x = float(target_x)
    game_target_y = float(target_y)

    print(f"🐍 [뱀화염탄] REAL({real_x}, {real_y}) → INTERNAL({game_start_x:.0f}, {game_start_y:.0f})")

    # 방향 벡터 계산
    dx = game_target_x - game_start_x
    dy = game_target_y - game_start_y
    dist = math.sqrt(dx * dx + dy * dy)
    if dist > 0:
        dx /= dist
        dy /= dist
    else:
        dx, dy = 0, 1  # 기본값: 아래로

    # 약간의 랜덤 오프셋 추가 (±10도)
    angle_offset = random.uniform(-0.17, 0.17)  # 약 ±10도
    cos_a, sin_a = math.cos(angle_offset), math.sin(angle_offset)
    new_dx = dx * cos_a - dy * sin_a
    new_dy = dx * sin_a + dy * cos_a

    # 뱀 화염탄 속도 (기본 화염탄보다 약간 느림)
    snake_fireball_speed = 12
    vel = [new_dx * snake_fireball_speed, new_dy * snake_fireball_speed]
    pos = [game_start_x, game_start_y]

    fireballs.append([pos, vel])

    # 화염탄 발사 효과음
    try:
        play_sound_with_volume(SOUND_FIREBALL)
    except:
        pass

    print(f"🐍 [뱀 화염탄] 발사! ({game_start_x:.0f}, {game_start_y:.0f}) → ({game_target_x:.0f}, {game_target_y:.0f})")

