def _destroy_stage2_rocks_in_radius(
    center_x: float,
    center_y: float,
    radius: float,
    *,
    source: str,
) -> int:
    """스테이지 2 방어벽 바위를 폭발 반경 내에서 파괴한다."""

    if current_stage != 2 or animated_bg_stage2 is None:
        return 0

    destroyed_count = 0
    rocks_to_remove = []

    for rock in list(animated_bg_stage2.crisis_rocks):
        if rock.get("falling", False):
            continue
        rock_x = rock.get("x", 0)
        rock_y = rock.get("y", 0)
        if calculate_distance((rock_x, rock_y), (center_x, center_y)) <= radius:
            rocks_to_remove.append(rock)

    for rock in rocks_to_remove:
        if rock.get("is_golden", False):
            trade_point_system.spawn_star(rock["x"], rock["y"], "golden_rock")
            print("⭐ 황금 바위 파괴 - 별 생성")
        animated_bg_stage2.destroy_rock(rock)
        try:
            animated_bg_stage2.crisis_rocks.remove(rock)
        except ValueError:
            pass  # 동시 제거 등으로 이미 빠졌다면 무시
        destroyed_count += 1

    if destroyed_count > 0:
        print(f"🪨 {source} 폭발로 바위 {destroyed_count}개 파괴")

    return destroyed_count


def trigger_grenade_style_explosion(
    x: float,
    y: float,
    *,
    apply_commando_bonus: bool,
    source: str = "grenade",
    radius_scale: float = 1.0,
) -> None:
    """수류탄과 동일한 폭발 효과를 발생시킨다."""

    global grenade_shake_timer, boss_stunned_timer, boss_knockback_vel, boss_knockback_timer
    global special_gauge, special_ready, explosion_zones
    # NOTE(backup-restore): 백업본(0926)과 동일하게 "폭발 발생 시점"에 보스에게
    # 1회성 스턴/넉백을 즉시 적용한다. (zone 업데이트 루프 중복 적용 방지)
    # 기존 코드의 지연 적용으로 넉백 속도/지속이 어색해지는 문제를 방지.
    import items

    # 기본 반경: 190px (화력지원은 호출부에서 radius_scale=0.8 적용)
    base_radius = 190
    base_radius = max(10, int(base_radius * radius_scale))
    if apply_commando_bonus and items.commando_arm_obtained:
        explosion_radius = int(base_radius * 1.1)
        print(f"🚨 코만도암 효과 적용: 폭발 반경 {explosion_radius} (기본 {base_radius})")
    else:
        explosion_radius = base_radius

    explosion_zone = {
        "x": x,
        "y": y,
        "radius": explosion_radius,
        "duration": 15,
        "active": True,
        "source": source,
    }
    # 폭발 즉시 보스 판정 및 1회 적용(스턴 126프레임=2.1초, 넉백 40)
    try:
        # 수류탄/화력지원만 즉시 적용 (center_cube, tetro_explosion 등은 시각 효과 공유만)
        if source in ("grenade", "fire_support") and 'BOSS' in globals() and BOSS is not None:
            bx, by = get_center_pos(BOSS)
            # 중심 거리 기반 판정 (간단/일관)
            if calculate_distance((bx, by), (x, y)) <= explosion_radius:
                # 스턴(126프레임 = 2.1초)
                boss_stunned_timer = max(boss_stunned_timer, 126)
                # 폭심지로부터 멀어지는 방향
                direction = 1 if bx >= x else -1
                # 넉백 세기 (20% 증가: 16 → 19.2)
                power = 19.2
                # 넉백 타이머 설정 (짧게 하여 빠른 순간 속도)
                boss_knockback_timer = max(boss_knockback_timer, 18)  # 36 → 18 (절반)
                boss_knockback_vel = _apply_boss_knockback_velocity(direction * power * 2.0)  # 순간 속도 2배
                # 대쉬/후딜 상태 강제 해제 (넉백 즉시 적용)
                globals()["boss_dashing"] = False
                globals()["boss_dash_timer"] = 0
                globals()["boss_dash_stun_timer"] = 0
                # 이후 zone 루프에서 재적용되지 않도록 플래그 부여
                explosion_zone["boss_applied"] = True
    except Exception:
        # 안전 가드: 오류 발생 시에도 게임 루프 보호
        pass

    explosion_zones.append(explosion_zone)
    grenade_shake_timer = 40
    play_sound_with_volume(SOUND_GRENADE)
    pass  # print(f"💥 {source} 폭발 발생: X={x:.1f}, Y={y:.1f}, 반경={explosion_radius}")  # 디버그 비활성화

    # 스테이지 2: 수류탄 폭발 시 반경 내 바위 파괴
    if current_stage == 2 and source == "grenade":
        _destroy_stage2_rocks_in_radius(x, y, explosion_radius, source="grenade")

    # 🏖 사막화 모래 침식: 폭발 반경 내 모래 지형 파괴
    if sand_obstacles is not None:
        erode_sand_area(sand_obstacles, x, y, explosion_radius)


# =====================
# Stage 7 EMP 펄스(파문) 이펙트
# =====================
stage7_emp_pulses: list[dict] = []


def spawn_stage7_emp_pulse(cx: int, cy: int) -> None:
    """스테이지7 중앙 큐브 폭발 시 EMP 파문(네온 블루 링) 연속 파동을 스폰."""
    if current_stage != 7:
        return
    # 4회의 연속 링을 약간의 지연을 두고 방출
    # 과도한 누적 방지(성능 가드)
    try:
        if len(stage7_emp_pulses) > 64:
            del stage7_emp_pulses[: max(0, len(stage7_emp_pulses) - 64)]
    except Exception:
        pass

# ---- 입력 디버그 유틸 -------------------------------------------------------
INPUT_DEBUG = False  # ' (apostrophe) 키로 토글

def input_debug_log(*parts):
    if not INPUT_DEBUG:
        return
    try:
        ts = pygame.time.get_ticks()
    except Exception:
        ts = 0
    msg = " ".join(str(p) for p in parts)
    print(f"[INPUT {ts}ms] {msg}")
    # 안전한 기본 중심 좌표 계산 (Stage7 파문 시각화용)
    try:
        if 'PLAYER' in globals() and PLAYER is not None:
            cx = int(getattr(PLAYER, 'centerx', WIDTH // 2))
            cy = int(getattr(PLAYER, 'centery', HEIGHT // 2))
        else:
            cx = WIDTH // 2
            cy = HEIGHT // 2
    except Exception:
        cx = WIDTH // 2
        cy = HEIGHT // 2
    for i in range(4):
        stage7_emp_pulses.append(
            {
                "x": cx,
                "y": cy,
                "delay": i * 3,          # 프레임 단위 지연(빠르게 연속)
                "radius": 24,
                "max_radius": int(min(WIDTH, HEIGHT) * 0.9),
                "speed": 28,            # 프레임당 확장 속도(px)
                "thickness": 6,         # 링 두께(px)
                "alpha": 200,
                "alpha_decay": 9,       # 프레임당 알파 감소
                "color": (120, 200, 255),
                "active": True,
            }
        )


def update_stage7_emp_pulses() -> None:
    if current_stage != 7 or not stage7_emp_pulses:
        return
    for pulse in stage7_emp_pulses[:]:
        if not pulse.get("active", False):
            stage7_emp_pulses.remove(pulse)
            continue
        if pulse["delay"] > 0:
            pulse["delay"] -= 1
            continue
        pulse["radius"] += pulse["speed"]
        pulse["alpha"] = max(0, pulse["alpha"] - pulse["alpha_decay"])
        if pulse["radius"] >= pulse["max_radius"] or pulse["alpha"] <= 0:
            pulse["active"] = False
            stage7_emp_pulses.remove(pulse)


def draw_stage7_emp_pulses(surface: pygame.Surface) -> None:
    if current_stage != 7 or not stage7_emp_pulses:
        return
    # EMP 링은 화면 전체를 대상으로 하므로 직접 그린다(가벼운 선 그리기만 수행)
    for pulse in stage7_emp_pulses:
        if pulse["delay"] > 0:
            continue
        alpha = int(pulse["alpha"])
        if alpha <= 0:
            continue
        color = (*pulse["color"], alpha)
        # 외곽선+글로우 2중 링(네온 느낌)
        pygame.draw.circle(surface, color, (int(pulse["x"]), int(pulse["y"])), int(pulse["radius"]), width=pulse["thickness"])
        glow_alpha = max(0, alpha // 2)
        glow_color = (pulse["color"][0], pulse["color"][1], pulse["color"][2], glow_alpha)
        pygame.draw.circle(surface, glow_color, (int(pulse["x"]), int(pulse["y"])), int(pulse["radius"]) + 8, width=max(1, pulse["thickness"] // 2))

