def start_orb_spawn_animation():
    """구슬 생성 애니메이션 시작"""
    global _orb_spawn_animation
    _orb_spawn_animation['active'] = True
    _orb_spawn_animation['collapse_active'] = False  # 접기 애니메이션 비활성화
    _orb_spawn_animation['collapsed'] = False  # 접기 완료 상태 해제
    _orb_spawn_animation['start_time'] = pygame.time.get_ticks()
    _orb_spawn_animation['left_phase'] = 0
    _orb_spawn_animation['left_scale'] = 0.0
    _orb_spawn_animation['left_alpha'] = 0
    _orb_spawn_animation['left_glow'] = 0.0
    _orb_spawn_animation['left_particles'] = []
    _orb_spawn_animation['right_phase'] = 0
    _orb_spawn_animation['right_scale'] = 0.0
    _orb_spawn_animation['right_alpha'] = 0
    _orb_spawn_animation['right_glow'] = 0.0
    _orb_spawn_animation['right_particles'] = []
    _orb_spawn_animation['ring_expand'] = 0.0
    _orb_spawn_animation['sparkles'] = []

def update_orb_spawn_animation():
    """구슬 생성 애니메이션 업데이트"""
    global _orb_spawn_animation
    if not _orb_spawn_animation['active']:
        return

    current_time = pygame.time.get_ticks()
    elapsed = current_time - _orb_spawn_animation['start_time']
    duration = _orb_spawn_animation['duration']
    progress = min(1.0, elapsed / duration)

    # 애니메이션 완료 체크
    if elapsed >= duration:
        _orb_spawn_animation['active'] = False
        _orb_spawn_animation['left_scale'] = 1.0
        _orb_spawn_animation['left_alpha'] = 255
        _orb_spawn_animation['right_scale'] = 1.0
        _orb_spawn_animation['right_alpha'] = 255
        return

    # === 왼쪽 구슬 (스킬 게이지) - 먼저 시작 ===
    left_start = 0.0  # 0%에서 시작
    left_end = 0.7    # 70%에서 완료
    if progress >= left_start:
        left_progress = min(1.0, (progress - left_start) / (left_end - left_start))

        # 이징 함수 (탄성 효과)
        if left_progress < 0.5:
            # 빠르게 확장
            eased = 2 * left_progress * left_progress
        else:
            # 탄성 바운스
            t = left_progress - 0.5
            eased = 0.5 + 0.5 * (1 - (1 - 2*t) ** 3)
            # 오버슈트 효과
            if left_progress > 0.6 and left_progress < 0.8:
                eased = min(1.15, eased + 0.15 * math.sin((left_progress - 0.6) * math.pi / 0.2))
            elif left_progress >= 0.8:
                eased = 1.0 + 0.05 * math.sin((left_progress - 0.8) * math.pi * 2)

        _orb_spawn_animation['left_scale'] = min(1.0, eased)
        _orb_spawn_animation['left_alpha'] = int(255 * min(1.0, left_progress * 1.5))
        _orb_spawn_animation['left_glow'] = 1.0 - abs(left_progress - 0.5) * 2  # 중간에 최대

        # 페이즈 업데이트
        if left_progress < 0.2:
            _orb_spawn_animation['left_phase'] = 1  # 나타남
        elif left_progress < 0.6:
            _orb_spawn_animation['left_phase'] = 2  # 확장
        elif left_progress < 0.9:
            _orb_spawn_animation['left_phase'] = 3  # 안정화
        else:
            _orb_spawn_animation['left_phase'] = 4  # 완료

    # === 오른쪽 구슬 (대쉬 토큰) - 약간 늦게 시작 ===
    right_start = 0.15  # 15%에서 시작 (왼쪽보다 약간 늦게)
    right_end = 0.85    # 85%에서 완료
    if progress >= right_start:
        right_progress = min(1.0, (progress - right_start) / (right_end - right_start))

        # 이징 함수 (탄성 효과)
        if right_progress < 0.5:
            eased = 2 * right_progress * right_progress
        else:
            t = right_progress - 0.5
            eased = 0.5 + 0.5 * (1 - (1 - 2*t) ** 3)
            if right_progress > 0.6 and right_progress < 0.8:
                eased = min(1.15, eased + 0.15 * math.sin((right_progress - 0.6) * math.pi / 0.2))
            elif right_progress >= 0.8:
                eased = 1.0 + 0.05 * math.sin((right_progress - 0.8) * math.pi * 2)

        _orb_spawn_animation['right_scale'] = min(1.0, eased)
        _orb_spawn_animation['right_alpha'] = int(255 * min(1.0, right_progress * 1.5))
        _orb_spawn_animation['right_glow'] = 1.0 - abs(right_progress - 0.5) * 2

        # 페이즈 업데이트
        if right_progress < 0.2:
            _orb_spawn_animation['right_phase'] = 1
        elif right_progress < 0.6:
            _orb_spawn_animation['right_phase'] = 2
        elif right_progress < 0.9:
            _orb_spawn_animation['right_phase'] = 3
        else:
            _orb_spawn_animation['right_phase'] = 4

    # 파티클 생성
    if random.random() < 0.3 and _orb_spawn_animation['left_phase'] in [1, 2]:
        angle = random.uniform(0, math.pi * 2)
        speed = random.uniform(1, 3)
        _orb_spawn_animation['left_particles'].append({
            'x': 0, 'y': 0,
            'vx': math.cos(angle) * speed,
            'vy': math.sin(angle) * speed,
            'life': 1.0,
            'color': (100, 150, 255)
        })

    if random.random() < 0.3 and _orb_spawn_animation['right_phase'] in [1, 2]:
        angle = random.uniform(0, math.pi * 2)
        speed = random.uniform(1, 3)
        _orb_spawn_animation['right_particles'].append({
            'x': 0, 'y': 0,
            'vx': math.cos(angle) * speed,
            'vy': math.sin(angle) * speed,
            'life': 1.0,
            'color': (255, 100, 100)
        })

    # 파티클 업데이트
    for p in _orb_spawn_animation['left_particles'][:]:
        p['x'] += p['vx']
        p['y'] += p['vy']
        p['life'] -= 0.02
        if p['life'] <= 0:
            _orb_spawn_animation['left_particles'].remove(p)

    for p in _orb_spawn_animation['right_particles'][:]:
        p['x'] += p['vx']
        p['y'] += p['vy']
        p['life'] -= 0.02
        if p['life'] <= 0:
            _orb_spawn_animation['right_particles'].remove(p)

def get_orb_spawn_animation_state():
    """구슬 생성 애니메이션 상태 반환"""
    return _orb_spawn_animation

