def start_orb_collapse_animation():
    """구슬 접기 애니메이션 시작 (게임 종료 시 호출)"""
    global _orb_spawn_animation
    # 이미 접혀있거나 접기 중이면 시작하지 않음
    if _orb_spawn_animation.get('collapsed', False) or _orb_spawn_animation['collapse_active']:
        return
    # 펼침 애니메이션 비활성화
    _orb_spawn_animation['active'] = False
    _orb_spawn_animation['collapse_active'] = True
    _orb_spawn_animation['collapse_start_time'] = pygame.time.get_ticks()
    # 스케일을 1.0에서 시작 (현재 값이 무엇이든)
    _orb_spawn_animation['left_scale'] = 1.0
    _orb_spawn_animation['left_alpha'] = 255
    _orb_spawn_animation['right_scale'] = 1.0
    _orb_spawn_animation['right_alpha'] = 255

def update_orb_collapse_animation():
    """구슬 접기 애니메이션 업데이트"""
    global _orb_spawn_animation
    if not _orb_spawn_animation['collapse_active']:
        return

    current_time = pygame.time.get_ticks()
    elapsed = current_time - _orb_spawn_animation['collapse_start_time']
    duration = _orb_spawn_animation['collapse_duration']
    progress = min(1.0, elapsed / duration)

    # 이징 함수 (ease-in: 처음엔 느리게, 나중에 빠르게)
    eased = progress * progress

    # 스케일 감소 (1.0 -> 0.0)
    scale = 1.0 - eased

    # 알파 감소 (255 -> 0)
    alpha = int(255 * (1.0 - eased))

    # 왼쪽 구슬 (스킬 게이지)
    _orb_spawn_animation['left_scale'] = scale
    _orb_spawn_animation['left_alpha'] = alpha

    # 오른쪽 구슬 (대쉬 토큰) - 약간 딜레이
    right_progress = min(1.0, max(0, (progress - 0.1) / 0.9))
    right_eased = right_progress * right_progress
    _orb_spawn_animation['right_scale'] = 1.0 - right_eased
    _orb_spawn_animation['right_alpha'] = int(255 * (1.0 - right_eased))

    # 애니메이션 완료 체크
    if elapsed >= duration:
        _orb_spawn_animation['collapse_active'] = False
        _orb_spawn_animation['collapsed'] = True  # 접기 완료 상태 설정
        _orb_spawn_animation['left_scale'] = 0.0
        _orb_spawn_animation['left_alpha'] = 0
        _orb_spawn_animation['right_scale'] = 0.0
        _orb_spawn_animation['right_alpha'] = 0

def is_orb_collapse_animation_active():
    """구슬 접기 애니메이션 활성 여부"""
    return _orb_spawn_animation['collapse_active']

def reset_orb_animation_state():
    """구슬 애니메이션 상태 완전 리셋 (메인 메뉴 복귀 시)"""
    global _orb_spawn_animation
    _orb_spawn_animation['active'] = False
    _orb_spawn_animation['collapse_active'] = False
    _orb_spawn_animation['collapsed'] = False
    _orb_spawn_animation['left_scale'] = 0.0
    _orb_spawn_animation['left_alpha'] = 0
    _orb_spawn_animation['right_scale'] = 0.0
    _orb_spawn_animation['right_alpha'] = 0
    _orb_spawn_animation['left_particles'] = []
    _orb_spawn_animation['right_particles'] = []

