def _compute_optimus_base_width() -> int:
    """게이지 스케일을 제외한 현재 기준 패들 너비(장비/리그/메카벌크/벌크업 배율 반영)를 반환."""
    angel_scale = ANGEL_PADDLE_SCALE
    # 벌크업 관련 보너스 합산 방식 적용
    bulkup_bonus = _get_bulkup_scale() - 1.0
    bulk_up_bonus = get_bulk_up_scale() - 1.0
    mecha_bulk_bonus = get_mecha_bulk_scale() - 1.0
    combined_bulk_scale = 1.0 + bulkup_bonus + bulk_up_bonus + mecha_bulk_bonus
    base_scale = CURRENT_PADDLE_SIZE_SCALE * angel_scale * combined_bulk_scale
    return max(1, int(round(PADDLE_BASE_WIDTH * base_scale)))


def get_optimus_gauge_ratio() -> float:
    """옵티머스 배터리 잔량(0~1). 다른 캐릭터는 1.0을 반환."""
    if selected_character_type != "optimus":
        return 1.0
    max_gauge = max(1.0, float(special_gauge_max))
    gauge_for_scale = float(displayed_gauge)
    return max(0.0, min(1.0, gauge_for_scale / max_gauge))


def _recalculate_optimus_gauge_scale() -> None:
    """게이지 잔량에 따라 옵티머스 패들 스케일을 갱신한다."""
    global optimus_gauge_scale, optimus_drained
    if selected_character_type != "optimus":
        optimus_gauge_scale = 1.0
        optimus_drained = False
        return

    base_width = _compute_optimus_base_width()
    min_scale = min(1.0, OPTIMUS_MIN_PADDLE_WIDTH / base_width)
    ratio = get_optimus_gauge_ratio()
    optimus_gauge_scale = min_scale + (1.0 - min_scale) * ratio
    optimus_drained = special_gauge <= 0


def reset_optimus_energy(full_gauge: bool = True) -> None:
    """옵티머스 배터리/스케일 초기화."""
    global special_gauge, special_gauge_max, displayed_gauge, special_ready
    global optimus_gauge_drain_buffer, optimus_last_gauge_tick_ms, optimus_last_round_marker
    global optimus_max_scale, optimus_max_decay_last_ms, optimus_charge_block_until_ms
    global optimus_charge_shockwave_at_ms, optimus_charge_shake_until_ms
    global optimus_low_gauge_warning_triggered, optimus_low_gauge_warning_timer
    global optimus_low_gauge_warning_phase, optimus_low_gauge_energy_particles
    global optimus_critical_gauge_warning_triggered, optimus_critical_gauge_warning_timer
    global optimus_critical_gauge_energy_particles
    global optimus_mech_arm_upgrade_active, optimus_mech_arm_upgrade_timer
    global optimus_mech_arm_upgrade_complete, optimus_mech_arm_particles
    global optimus_paddle_upgrade_active, optimus_paddle_upgrade_timer
    global optimus_paddle_upgrade_complete, optimus_paddle_upgrade_particles
    if selected_character_type != "optimus":
        return

    _stop_optimus_charge_sound()

    optimus_max_scale = 1.0
    optimus_max_decay_last_ms = pygame.time.get_ticks()
    optimus_charge_block_until_ms = 0
    optimus_charge_shockwave_at_ms = 0
    optimus_charge_shake_until_ms = 0
    # 경고 애니메이션 초기화 (400 이하)
    optimus_low_gauge_warning_triggered = False
    optimus_low_gauge_warning_timer = 0
    optimus_low_gauge_warning_phase = 0
    optimus_low_gauge_energy_particles = []
    # 위험 경고 애니메이션 초기화 (300 이하)
    optimus_critical_gauge_warning_triggered = False
    optimus_critical_gauge_warning_timer = 0
    optimus_critical_gauge_energy_particles = []
    # 기계손 강화 애니메이션 초기화
    optimus_mech_arm_upgrade_active = False
    optimus_mech_arm_upgrade_timer = 0
    optimus_mech_arm_upgrade_complete = False
    optimus_mech_arm_particles = []
    # 궁극의 탁구채 강화 애니메이션 초기화
    optimus_paddle_upgrade_active = False
    optimus_paddle_upgrade_timer = 0
    optimus_paddle_upgrade_complete = False
    optimus_paddle_upgrade_particles = []
    # 옵티머스 암 스킬 초기화
    reset_optimus_arm_state()
    globals()["optimus_arm_available"] = False
    globals()["optimus_arm_cooldown_until_ms"] = 0
    special_gauge_max = get_max_gauge()
    if full_gauge:
        special_gauge = special_gauge_max
        displayed_gauge = special_gauge_max
        special_ready = True
        try:
            game_state.special_gauge = special_gauge
            game_state.displayed_gauge = displayed_gauge
            game_state.special_ready = special_ready
            game_state.special_gauge_max = special_gauge_max
        except Exception:
            pass
    optimus_gauge_drain_buffer = 0.0
    optimus_last_gauge_tick_ms = pygame.time.get_ticks()
    optimus_charge_active = False
    optimus_charge_hold_ms = 0
    optimus_charge_last_update_ms = 0
    optimus_charge_anim_tick_ms = 0
    optimus_charge_lock_until_ms = 0
    optimus_last_round_marker = round_start_time if "round_start_time" in globals() else optimus_last_round_marker
    _recalculate_optimus_gauge_scale()
    apply_equipment_paddle_modifiers()


def _freeze_optimus_energy_timers() -> None:
    """일시정지/정보창 등 메인 루프가 멈춘 동안 옵티머스 게이지 감소 타이머를 현재 시각으로 고정."""
    if selected_character_type != "optimus":
        return
    global optimus_last_gauge_tick_ms, optimus_max_decay_last_ms
    now = pygame.time.get_ticks()
    optimus_last_gauge_tick_ms = now
    optimus_max_decay_last_ms = now


def update_optimus_energy() -> None:
    """옵티머스 배터리 소모 및 패들/이동 스케일 반영."""
    global special_gauge, special_gauge_max, special_ready, displayed_gauge
    global optimus_last_gauge_tick_ms, optimus_gauge_drain_buffer, optimus_last_round_marker
    global optimus_max_scale, optimus_max_decay_last_ms
    global PADDLE_WIDTH, PADDLE_HEIGHT, PLAYER
    global optimus_low_gauge_warning_triggered, optimus_low_gauge_warning_timer
    global optimus_low_gauge_warning_phase, optimus_low_gauge_energy_particles
    global optimus_critical_gauge_warning_triggered, optimus_critical_gauge_warning_timer
    global optimus_critical_gauge_energy_particles
    global optimus_mech_arm_upgrade_active, optimus_mech_arm_upgrade_timer
    global optimus_mech_arm_upgrade_complete, optimus_mech_arm_particles
    global optimus_paddle_upgrade_active, optimus_paddle_upgrade_timer
    global optimus_paddle_upgrade_complete, optimus_paddle_upgrade_particles
    global aipill_active

    if selected_character_type != "optimus":
        return

    current_round_marker = round_start_time if "round_start_time" in globals() else None
    if current_round_marker is not None and current_round_marker != optimus_last_round_marker:
        optimus_last_round_marker = current_round_marker

    now = pygame.time.get_ticks()
    # 일시정지/정보창 등 게임 멈춤 상태에서는 배터리 소모/최대치 감소를 중단한다.
    # ESC/P 일시정지, 툴팁 강제정지는 game_paused 플래그로 처리되며
    # Tab 캐릭터정보창은 별도 프리즈 가드(_freeze_optimus_energy_timers)로 보호된다.
    # 공 생성 애니메이션 중에도 배터리 소모/최대치 감소를 중단한다.
    # 또한 애니메이션이 막 완료되었을 때도 타임스탬프를 리셋하여 누적 시간이 적용되지 않도록 한다.
    if game_paused or is_ball_spawn_animation_paused():
        optimus_last_gauge_tick_ms = now
        optimus_max_decay_last_ms = now
        return

    # 애니메이션이 막 완료되었을 때 (is_complete() True, is_active() False) 첫 프레임 보호
    # elapsed_ms가 애니메이션 전체 시간만큼 누적되는 것을 방지
    if optimus_last_gauge_tick_ms == 0 or (now - optimus_last_gauge_tick_ms) > 1000:
        # 1초 이상 경과했으면 타임스탬프 리셋 (애니메이션 종료 후 첫 프레임일 가능성)
        optimus_last_gauge_tick_ms = now
        optimus_max_decay_last_ms = now
        return  # 이번 프레임은 게이지 감소 스킵

    elapsed_ms = max(0, now - optimus_last_gauge_tick_ms)
    optimus_last_gauge_tick_ms = now

    # 최대 게이지 서서히 감소 (기본 3초마다 1%, 400 이하일 땐 1.5%)
    if optimus_max_decay_last_ms == 0:
        optimus_max_decay_last_ms = now
    decay_ms = max(0, now - optimus_max_decay_last_ms)
    if decay_ms >= 3000:
        steps = decay_ms // 3000
        # 최대 게이지가 400 이하로 떨어지면 더 빠르게(3초당 1.5%) 감소
        try:
            current_max_gauge = get_max_gauge()
        except Exception:
            current_max_gauge = None
        decay_factor = 0.985 if current_max_gauge is not None and current_max_gauge <= 400 else 0.99
        optimus_max_scale *= (decay_factor ** steps)
        optimus_max_scale = max(0.1, optimus_max_scale)  # 완전 소멸 방지 최소 배율
        optimus_max_decay_last_ms += steps * 3000

        # 최대 게이지가 400 이하로 떨어지면 경고 애니메이션 1회 트리거
        if current_max_gauge is not None and current_max_gauge <= 400 and not optimus_low_gauge_warning_triggered:
            optimus_low_gauge_warning_triggered = True
            optimus_low_gauge_warning_timer = now
            optimus_low_gauge_warning_phase = 0
            # 에너지 파티클 생성 (게이지바 주변에서 솟구치는 에너지)
            optimus_low_gauge_energy_particles = []
            gauge_width = 14
            gauge_x = GAME_AREA_OFFSET_X + GAME_PLAY_WIDTH - gauge_width - 4  # 게임 영역 오른쪽
            gauge_y = HEIGHT - 200
            gauge_height = 118
            for i in range(12):  # 12개의 에너지 파티클
                angle = random.uniform(-0.5, 0.5)  # 위로 향하는 각도
                speed = random.uniform(2.5, 4.5)
                px = gauge_x + random.randint(-8, 22)  # 게이지바 주변
                py = gauge_y + random.randint(0, gauge_height)
                lifetime = random.randint(1200, 1800)  # ms - 2초 애니메이션에 맞게 연장
                optimus_low_gauge_energy_particles.append({
                    'x': px, 'y': py,
                    'vx': math.sin(angle) * speed,
                    'vy': -speed * random.uniform(1.5, 2.5),  # 위로 솟구침
                    'life': lifetime,
                    'max_life': lifetime,
                    'size': random.uniform(2, 4),
                    'spawn_time': now
                })

            # (게이지 기반 스킬 트리거는 스타포인트 시스템으로 대체됨)

        # 최대 게이지가 300 이하로 떨어지면 위험 경고 애니메이션 1회 트리거 (더 화려함)
        if current_max_gauge is not None and current_max_gauge <= 300 and not optimus_critical_gauge_warning_triggered:
            optimus_critical_gauge_warning_triggered = True
            optimus_critical_gauge_warning_timer = now
            # 더 많은 에너지 파티클 생성 (화려한 위험 경고)
            optimus_critical_gauge_energy_particles = []
            gauge_width = 14
            gauge_x = GAME_AREA_OFFSET_X + GAME_PLAY_WIDTH - gauge_width - 4  # 게임 영역 오른쪽
            gauge_y = HEIGHT - 200
            gauge_height = 118
            for i in range(24):  # 24개의 에너지 파티클 (2배)
                angle = random.uniform(-1.0, 1.0)  # 더 넓은 각도
                speed = random.uniform(3.5, 6.0)  # 더 빠른 속도
                px = gauge_x + random.randint(-15, 30)  # 더 넓은 범위
                py = gauge_y + random.randint(0, gauge_height)
                lifetime = random.randint(1400, 2000)  # 2초 애니메이션에 맞게 연장
                optimus_critical_gauge_energy_particles.append({
                    'x': px, 'y': py,
                    'vx': math.sin(angle) * speed * 1.5,
                    'vy': -speed * random.uniform(2.0, 3.5),  # 더 높이 솟구침
                    'life': lifetime,
                    'max_life': lifetime,
                    'size': random.uniform(3, 6),  # 더 큰 파티클
                    'spawn_time': now,
                    'spiral_phase': random.uniform(0, math.pi * 2)  # 나선형 회전용
                })

            # 궁극의 탁구채 강화 애니메이션도 동시에 트리거
            optimus_paddle_upgrade_active = True
            optimus_paddle_upgrade_timer = now
            optimus_paddle_upgrade_particles = []
            # 조립 파티클 생성 (플레이어 왼팔 탁구채 주변)
            for i in range(24):
                angle = random.uniform(0, math.pi * 2)
                dist = random.uniform(40, 100)
                lifetime = random.randint(1000, 1800)
                optimus_paddle_upgrade_particles.append({
                    'angle': angle,
                    'dist': dist,
                    'target_dist': 0,
                    'life': lifetime,
                    'max_life': lifetime,
                    'size': random.uniform(4, 8),
                    'spawn_time': now,
                    'type': 'converge',
                    'color_idx': random.randint(0, 3)  # 색상 인덱스 (레드, 오렌지, 골드, 흰색)
                })

            # (게이지 기반 스킬 트리거는 스타포인트 시스템으로 대체됨)

    # 충전 중에는 기본 배터리 소모를 일시 정지
    if not optimus_charge_active:
        # 메카체인 스킬 적용: 게이지 감소율 감소
        drain_reduction = get_mecha_chain_drain_reduction()
        effective_drain_rate = OPTIMUS_GAUGE_DRAIN_PER_SEC * (1.0 - drain_reduction)
        optimus_gauge_drain_buffer += (effective_drain_rate * elapsed_ms) / 1000.0
        if optimus_gauge_drain_buffer >= 1.0:
            drain_units = int(optimus_gauge_drain_buffer)
            optimus_gauge_drain_buffer -= drain_units
            special_gauge = max(0, special_gauge - drain_units)
    else:
        # 소모 버퍼를 초기화해 충전 종료 후 바로 감소가 시작되지 않도록 방지
        optimus_gauge_drain_buffer = 0.0

    # AI 필 활성화 중 배터리가 바닥나면 즉시 효과를 종료한다.
    if aipill_active and special_gauge <= 0:
        deactivate_aipill("gauge_depleted")

    special_gauge_max = get_max_gauge()
    if special_gauge > special_gauge_max:
        special_gauge = special_gauge_max
    if displayed_gauge > special_gauge_max:
        displayed_gauge = special_gauge_max
    try:
        game_state.special_gauge_max = special_gauge_max
        game_state.special_gauge = special_gauge
    except Exception:
        pass
    special_ready = special_gauge >= 350
    # 외부 패들 크기 변형(롱패들 등)을 보존하기 위해 현재 게이지 스케일 기준 기대 크기 대비 배율을 계산
    angel_scale = ANGEL_PADDLE_SCALE
    # 벌크업 관련 보너스 합산 방식 적용
    bulkup_bonus = _get_bulkup_scale() - 1.0
    bulk_up_bonus = get_bulk_up_scale() - 1.0
    mecha_bulk_bonus = get_mecha_bulk_scale() - 1.0
    combined_bulk_scale = 1.0 + bulkup_bonus + bulk_up_bonus + mecha_bulk_bonus
    base_scale = CURRENT_PADDLE_SIZE_SCALE * angel_scale * combined_bulk_scale
    expected_width = max(1, int(round(PADDLE_BASE_WIDTH * base_scale * optimus_gauge_scale)))
    expected_height = max(1, int(round(PADDLE_BASE_HEIGHT * base_scale * optimus_gauge_scale)))
    width_factor = PADDLE_WIDTH / expected_width if expected_width else 1.0
    height_factor = PADDLE_HEIGHT / expected_height if expected_height else 1.0

    _recalculate_optimus_gauge_scale()
    apply_equipment_paddle_modifiers()

    if width_factor != 1.0 or height_factor != 1.0:
        prev_centerx = PLAYER.centerx
        prev_bottom = PLAYER.bottom
        PADDLE_WIDTH = max(1, int(round(PADDLE_WIDTH * width_factor)))
        PADDLE_HEIGHT = max(1, int(round(PADDLE_HEIGHT * height_factor)))
        PLAYER.size = (PADDLE_WIDTH, PADDLE_HEIGHT)
        PLAYER.centerx = prev_centerx
        PLAYER.bottom = prev_bottom
        PLAYER.x = max(0, min(WIDTH - PLAYER.width, PLAYER.x))


def draw_optimus_emblem(surface, emblem_x: int, emblem_y: int, emblem_radius: int,
                        time_now: int, pulse_scale: float, rotation_angle: float,
                        glow_intensity: float) -> None:
    """옵티머스 전용 엠블럼: 플라즈마 코어 + 핵융합 원자 궤도. (캐시 최적화)"""
    accent = OPTIMUS_MECHA_PALETTE["accent"]
    core_color = OPTIMUS_MECHA_PALETTE["hex_core"]
    core_inner = OPTIMUS_MECHA_PALETTE["hex_core_inner"]
    outline = OPTIMUS_MECHA_PALETTE["hex_border"]
    deep_bg = (8, 12, 20)
    chamber_bg = (22, 32, 46)

    # 호흡하듯 커지는 기본 링(다른 캐릭터와 동일한 크기/맥동)
    breathing = 1.0 + math.sin(time_now * 0.004) * 0.12
    base_radius = max(6, int(emblem_radius * pulse_scale))
    outer_radius = max(base_radius + 4, int(emblem_radius * breathing))

    # 캐시된 Surface 사용
    halo_size = outer_radius * 2 + 6
    halo_surface = get_cached_glow_surface(halo_size)
    halo_center = outer_radius + 3
    for i in range(2):
        halo_alpha = max(30, int(80 + glow_intensity * 110) - i * 25)
        pygame.draw.circle(
            halo_surface,
            (*accent, halo_alpha),
            (halo_center, halo_center),
            outer_radius + i * 2,
            2,
        )
    surface.blit(halo_surface, (emblem_x - halo_center, emblem_y - halo_center))

    # 메인 디스크(테슬라 플라즈마 챔버) - 캐시된 Surface 사용
    disc_size = base_radius * 2 + 8
    disc_surface = get_cached_glow_surface(disc_size)
    disc_center = base_radius + 4
    pygame.draw.circle(disc_surface, (*deep_bg, 200), (disc_center, disc_center), base_radius + 3)
    pygame.draw.circle(disc_surface, (*chamber_bg, 235), (disc_center, disc_center), base_radius)
    pygame.draw.circle(disc_surface, outline, (disc_center, disc_center), base_radius, 2)
    inner_ring_r = max(2, int(base_radius * 0.65))
    pygame.draw.circle(disc_surface, (*accent, 90), (disc_center, disc_center), inner_ring_r, 2)
    surface.blit(disc_surface, (emblem_x - disc_center, emblem_y - disc_center))

    # 핵융합 코어 - 사전 렌더링된 glow 캐시 사용
    core_pulse = 1.0 + math.sin(time_now * 0.009) * 0.25
    core_r = max(3, int(emblem_radius * 0.35 * core_pulse))
    glow_r = int(core_r * 1.9)
    glow_size = glow_r * 2 + 4
    glow_surface = get_predrawn_glow_circle(glow_size, accent, 80)
    half_glow = glow_surface.get_width() // 2
    surface.blit(glow_surface, (emblem_x - half_glow, emblem_y - half_glow))
    pygame.draw.circle(surface, core_color, (emblem_x, emblem_y), core_r + 1)
    pygame.draw.circle(surface, core_inner, (emblem_x, emblem_y), max(2, core_r - 1))
    pygame.draw.circle(surface, (255, 255, 255), (emblem_x, emblem_y), max(1, core_r - 2), 1)

    # 코어에서 뻗는 플라즈마 필라멘트
    for k in range(6):
        arc_angle = rotation_angle * 1.3 + k * (math.tau / 6)
        arc_len = inner_ring_r + 4
        end_x = emblem_x + math.cos(arc_angle) * arc_len
        end_y = emblem_y + math.sin(arc_angle) * arc_len
        mid_x = (emblem_x + end_x) / 2 + math.cos(arc_angle + math.pi / 2) * 2
        mid_y = (emblem_y + end_y) / 2 + math.sin(arc_angle + math.pi / 2) * 2
        pygame.draw.lines(
            surface,
            accent,
            False,
            [(emblem_x, emblem_y), (mid_x, mid_y), (end_x, end_y)],
            1,
        )

    # 원자 궤도 + 알갱이(핵융합 입자 공전 느낌)
    orbit_configs = [
        (base_radius + 3, math.radians(10), 1.1, 3, (120, 235, 255)),
        (base_radius + 7, math.radians(-22), 1.35, 4, (0, 255, 210)),
        (base_radius + 11, math.radians(28), 0.95, 5, (180, 255, 255)),
    ]
    for idx, (orbit_r, tilt, speed, bead_count, orbit_color) in enumerate(orbit_configs):
        scaled_r = orbit_r * (0.92 + 0.08 * pulse_scale)
        orbit_angle = rotation_angle * speed + idx * 0.5
        cos_t = math.cos(tilt)
        sin_t = math.sin(tilt)
        points = []
        steps = 44
        for i in range(steps):
            a = orbit_angle + math.tau * i / steps
            wobble = math.sin(a * 3 + time_now * 0.01) * 0.6
            r_mod = scaled_r + wobble
            x = r_mod * math.cos(a)
            y = r_mod * math.sin(a) * cos_t
            z = r_mod * math.sin(a) * sin_t
            points.append((emblem_x + x, emblem_y + y + z * 0.2))
        pygame.draw.aalines(surface, orbit_color, True, points)

        bead_angle = orbit_angle + time_now * 0.0025
        for j in range(bead_count):
            pa = bead_angle + j * (math.tau / bead_count)
            px = scaled_r * math.cos(pa)
            py = scaled_r * math.sin(pa) * cos_t
            pz = scaled_r * math.sin(pa) * sin_t
            bx = emblem_x + px
            by = emblem_y + py + pz * 0.2
            bead_size = 3 if idx == 0 else 2
            pygame.draw.circle(surface, orbit_color, (int(bx), int(by)), bead_size + 1)
            pygame.draw.circle(surface, (255, 255, 255), (int(bx), int(by)), max(1, bead_size - 1))



def _resolve_mecha_phase(step_phase: float | None) -> float:
    phase = 0.0 if step_phase is None else float(step_phase)
    return phase % 1.0


def _create_mecha_paddle_surface(palette: dict, step_phase: float = 0.0) -> pygame.Surface:
    """고해상도 메카 캐릭터 렌더링 (2배 스케일 - 모든 수치 2배)"""
    surface = pygame.Surface(MECHA_SPRITE_SIZE, pygame.SRCALPHA)
    cx = MECHA_CENTER_X
    base_cy = MECHA_CENTER_Y

    phase = _resolve_mecha_phase(step_phase)
    stride = math.sin(phase * math.tau)
    torso_bob = int(math.sin(phase * math.tau * 2.0) * 6)  # 3→6
    sway = math.sin(phase * math.tau * 0.5) * 4  # 2→4

    hip_y = base_cy + 32 + torso_bob      # 16→32
    shoulder_y = base_cy - 12 + torso_bob  # 6→12
    head_y = base_cy - 64 + torso_bob      # 32→64
    foot_base_y = base_cy + 120            # 60→120

    def draw_leg(side: int, leg_stride: float) -> tuple[int, int]:
        """사이언 LED로 강조된 다리 관절 애니메이션 (고해상도) + 디테일"""
        hip = (cx + side * 36, hip_y)       # 18→36
        foot_x = cx + side * 44 + int(leg_stride * 12)  # 22→44, 6→12
        foot_y = foot_base_y
        knee_x = int((hip[0] * 0.55 + foot_x * 0.45) + side * 8 - leg_stride * 6)  # 4→8, 3→6
        knee_y = int((hip[1] * 0.55 + foot_y * 0.45) + 4)  # 2→4
        knee = (knee_x, knee_y)
        foot = (foot_x, foot_y)

        pygame.draw.line(surface, palette["body"], hip, knee, 24)   # 12→24
        pygame.draw.line(surface, palette["body"], knee, foot, 24)  # 12→24
        pygame.draw.line(surface, palette["line"], hip, knee, 6)    # 3→6
        pygame.draw.line(surface, palette["line"], knee, foot, 6)   # 3→6

        # [디테일 추가] 다리 아머 플레이트
        mid_upper = ((hip[0] + knee[0]) // 2, (hip[1] + knee[1]) // 2)
        mid_lower = ((knee[0] + foot[0]) // 2, (knee[1] + foot[1]) // 2)
        pygame.draw.circle(surface, palette["helmet"], mid_upper, 10)
        pygame.draw.circle(surface, palette["accent"], mid_upper, 6, 2)
        pygame.draw.circle(surface, palette["helmet"], mid_lower, 8)
        pygame.draw.circle(surface, palette["accent"], mid_lower, 5, 2)

        for joint in (hip, knee, foot):
            pygame.draw.circle(surface, palette["hex_base"], joint, 14)  # 7→14
            pygame.draw.circle(surface, palette["accent"], joint, 8)     # 4→8
            # [디테일 추가] 관절 내부 LED 발광
            pygame.draw.circle(surface, palette["hex_core"], joint, 5)
            pygame.draw.circle(surface, palette["visor_highlight"], joint, 3)

        foot_rect = pygame.Rect(0, 0, 52, 24)  # 26→52, 12→24
        foot_rect.center = (foot_x, foot_y + 12)  # 6→12
        pygame.draw.rect(surface, palette["grip"], foot_rect, border_radius=8)   # 4→8
        pygame.draw.rect(surface, palette["grip_line"], foot_rect.inflate(-12, -4), 2, border_radius=6)  # 6→12, 2→4, 1→2, 3→6

        # [디테일 추가] 발바닥 추진기 노즐
        nozzle_x = foot_x
        nozzle_y = foot_y + 20
        pygame.draw.ellipse(surface, palette["hex_base"], (nozzle_x - 12, nozzle_y, 24, 8))
        pygame.draw.ellipse(surface, palette["accent"], (nozzle_x - 8, nozzle_y + 2, 16, 4))
        # 추진기 발광
        thruster_glow = pygame.Surface((32, 16), pygame.SRCALPHA)
        glow_alpha = int(40 + 30 * math.sin(phase * math.tau * 2 + side))
        pygame.draw.ellipse(thruster_glow, (*palette["accent"], glow_alpha), (0, 0, 32, 16))
        surface.blit(thruster_glow, (nozzle_x - 16, nozzle_y + 4))

        return hip

    left_hip = draw_leg(-1, stride)
    right_hip = draw_leg(1, -stride)

    # 하체 외곽 광택 (고해상도)
    leg_glow = pygame.Surface(MECHA_SPRITE_SIZE, pygame.SRCALPHA)
    pygame.draw.ellipse(
        leg_glow,
        (*palette["glow"], 55),
        (cx - 140, foot_base_y - 60, 280, 36),  # 70→140, 30→60, 140→280, 18→36
        4,  # 2→4
    )
    surface.blit(leg_glow, (0, 0))

    # 상체(바디+코어) - 고해상도
    torso = [
        (cx - 80, shoulder_y + 8),   # 40→80, 4→8
        (cx + 80, shoulder_y + 8),
        (cx + 64, hip_y + 8),        # 32→64
        (cx - 64, hip_y + 8),
    ]
    pygame.draw.polygon(surface, palette["body"], torso)
    pygame.draw.polygon(surface, palette["line"], torso, 4)  # 2→4

    # [디테일 추가] 가슴 패널 라인
    for panel_side in (-1, 1):
        panel_x = cx + panel_side * 50
        pygame.draw.line(surface, palette["helmet"],
                        (panel_x, shoulder_y + 16), (panel_x - panel_side * 20, hip_y), 3)
        # 패널 LED 스트립
        for led_i in range(3):
            led_y = shoulder_y + 24 + led_i * 16
            led_x = panel_x - panel_side * (4 + led_i * 4)
            pygame.draw.circle(surface, palette["accent"], (led_x, led_y), 3)
            pygame.draw.circle(surface, palette["visor_highlight"], (led_x, led_y), 2)

    # [디테일 추가] 허리 벨트
    belt_y = hip_y - 4
    belt_rect = pygame.Rect(cx - 56, belt_y, 112, 12)
    pygame.draw.rect(surface, palette["grip"], belt_rect, border_radius=4)
    pygame.draw.rect(surface, palette["grip_line"], belt_rect.inflate(-4, -4), 1, border_radius=3)
    # 벨트 버클 (중앙)
    buckle_rect = pygame.Rect(cx - 14, belt_y - 2, 28, 16)
    pygame.draw.rect(surface, palette["hex_base"], buckle_rect, border_radius=4)
    pygame.draw.rect(surface, palette["accent"], buckle_rect, 2, border_radius=4)
    pygame.draw.circle(surface, palette["hex_core"], (cx, belt_y + 6), 5)
    pygame.draw.circle(surface, palette["visor_highlight"], (cx, belt_y + 6), 3)

    # 네온 V 라인(테슬라 시그니처) - 고해상도
    v_points = [
        (cx - 44, shoulder_y + 12),  # 22→44, 6→12
        (cx, hip_y + 4),             # 2→4
        (cx + 44, shoulder_y + 12),
    ]
    pygame.draw.lines(surface, palette["accent"], False, v_points, 8)  # 4→8

    # [디테일 추가] V라인 교차점 발광
    v_glow = pygame.Surface((40, 40), pygame.SRCALPHA)
    pygame.draw.circle(v_glow, (*palette["accent"], 50), (20, 20), 20)
    surface.blit(v_glow, (cx - 20, hip_y - 16))

    # 중앙 에너지 코어 - 고해상도 + 디테일 추가
    core_rect = pygame.Rect(cx - 18, shoulder_y + 20, 36, 52)  # 9→18, 10→20, 18→36, 26→52
    pygame.draw.rect(surface, palette["hex_base"], core_rect, border_radius=8)  # 4→8
    pygame.draw.rect(surface, palette["hex_border"], core_rect.inflate(8, 8), 4, border_radius=12)  # 4→8, 2→4, 6→12
    pygame.draw.rect(surface, palette["hex_core"], core_rect.inflate(-8, -12), border_radius=6)  # 4→8, 6→12, 3→6

    # [디테일 추가] 테슬라 T 로고 (에너지 코어 중앙)
    t_color = palette["hex_base"]
    t_cx, t_cy = core_rect.centerx, core_rect.centery
    pygame.draw.line(surface, t_color, (t_cx - 8, t_cy - 10), (t_cx + 8, t_cy - 10), 4)  # T 가로
    pygame.draw.line(surface, t_color, (t_cx, t_cy - 10), (t_cx, t_cy + 12), 4)  # T 세로

    # [디테일 추가] 코어 에너지 펄스 효과
    pulse_alpha = int(80 + 40 * math.sin(phase * math.tau * 3))
    core_pulse_surf = pygame.Surface((50, 66), pygame.SRCALPHA)
    pygame.draw.rect(core_pulse_surf, (*palette["hex_core"], pulse_alpha), (0, 0, 50, 66), border_radius=10)
    surface.blit(core_pulse_surf, (core_rect.left - 7, core_rect.top - 7), special_flags=pygame.BLEND_RGBA_ADD)

    # [디테일 추가] 코어 상하 배기구
    for vent_y in (core_rect.top - 6, core_rect.bottom + 2):
        pygame.draw.rect(surface, palette["grip"], (cx - 12, vent_y, 24, 4), border_radius=2)
        for vx in range(-8, 10, 6):
            pygame.draw.line(surface, palette["accent"], (cx + vx, vent_y), (cx + vx, vent_y + 4), 1)

    # 어깨 패드 - 고해상도 + 디테일 추가
    for side in (-1, 1):
        pad_rect = pygame.Rect(0, 0, 52, 28)  # 26→52, 14→28
        pad_rect.center = (cx + side * 60, shoulder_y)  # 30→60
        pygame.draw.rect(surface, palette["helmet"], pad_rect, border_radius=12)  # 6→12
        pygame.draw.rect(surface, palette["accent"], pad_rect, 4, border_radius=12)  # 2→4
        # [디테일 추가] 어깨 패드 내부 라인
        inner_pad = pad_rect.inflate(-16, -10)
        pygame.draw.rect(surface, palette["hex_base"], inner_pad, border_radius=6)
        pygame.draw.line(surface, palette["accent"],
                        (inner_pad.left + 4, inner_pad.centery),
                        (inner_pad.right - 4, inner_pad.centery), 2)
        # [디테일 추가] 어깨 LED 인디케이터
        led_x = pad_rect.centerx + side * 12
        pygame.draw.circle(surface, palette["hex_core"], (led_x, pad_rect.centery), 4)
        pygame.draw.circle(surface, palette["visor_highlight"], (led_x, pad_rect.centery), 2)

    # 머리(사이버 바이저) - 고해상도
    helmet_rect = pygame.Rect(cx - 44, head_y - 16, 88, 68)  # 22→44, 8→16, 44→88, 34→68
    pygame.draw.rect(surface, palette["helmet"], helmet_rect, border_radius=20)  # 10→20
    pygame.draw.rect(surface, palette["helmet_inner"], helmet_rect.inflate(-20, -20), border_radius=16)  # 10→20, 8→16
    visor_rect = helmet_rect.inflate(-16, -12)  # 8→16, 6→12
    pygame.draw.rect(surface, palette["visor"], visor_rect, border_radius=16)  # 8→16
    pygame.draw.line(surface, palette["visor_highlight"], visor_rect.midleft, (visor_rect.centerx, visor_rect.top + 8), 4)  # 4→8, 2→4
    pygame.draw.line(surface, palette["visor_highlight"], (visor_rect.centerx, visor_rect.bottom - 8), visor_rect.midright, 4)  # 4→8, 2→4

    # [디테일 추가] 바이저 스캔라인 효과
    for scan_y in range(visor_rect.top + 6, visor_rect.bottom - 6, 8):
        scan_alpha = 40 + int(20 * math.sin(phase * math.tau + scan_y * 0.1))
        pygame.draw.line(surface, (*palette["visor_highlight"], scan_alpha),
                        (visor_rect.left + 8, scan_y), (visor_rect.right - 8, scan_y), 1)

    # [디테일 추가] 헬멧 상단 안테나/센서
    antenna_base = (cx, helmet_rect.top + 4)
    pygame.draw.rect(surface, palette["grip"], (cx - 6, helmet_rect.top - 12, 12, 16), border_radius=3)
    pygame.draw.circle(surface, palette["accent"], (cx, helmet_rect.top - 14), 5)
    pygame.draw.circle(surface, palette["visor_highlight"], (cx, helmet_rect.top - 14), 3)
    # 안테나 발광
    antenna_glow = pygame.Surface((20, 20), pygame.SRCALPHA)
    pygame.draw.circle(antenna_glow, (*palette["accent"], 60), (10, 10), 10)
    surface.blit(antenna_glow, (cx - 10, helmet_rect.top - 24))

    for side in (-1, 1):
        ear_center = (helmet_rect.centerx + side * 40, helmet_rect.centery + 4)  # 20→40, 2→4
        pygame.draw.circle(surface, palette["helmet"], ear_center, 14)  # 7→14
        pygame.draw.circle(surface, palette["ear_inner"], ear_center, 10)  # 5→10
        # [디테일 추가] 귀 센서 LED 링
        pygame.draw.circle(surface, palette["accent"], ear_center, 7, 2)
        pygame.draw.circle(surface, palette["visor_highlight"], ear_center, 4)

    # 팔 스윙 + 패들(플라즈마 블레이드)
    left_swing_ratio = right_swing_ratio = 0.0
    try:
        left_timer = optimus_arm_swing_left_timer
        right_timer = optimus_arm_swing_right_timer
        duration = OPTIMUS_ARM_SWING_DURATION or 1
        # 진행형 스윙: 0→1까지만 증가, 끝에서 다시 앞으로 튀지 않도록 0으로 즉시 리셋
        left_swing_ratio = 1.0 - (left_timer / duration) if left_timer > 0 else 0.0
        right_swing_ratio = 1.0 - (right_timer / duration) if right_timer > 0 else 0.0
        left_swing_ratio = max(0.0, min(1.0, left_swing_ratio))
        right_swing_ratio = max(0.0, min(1.0, right_swing_ratio))
    except Exception:
        pass

    arm_swing = int(stride * 12)      # 6→12 (고해상도)
    arm_swing_left = int(arm_swing)
    arm_swing_right = int(-arm_swing // 2)

    def _ease_out_cubic(t: float) -> float:
        t = max(0.0, min(1.0, t))
        return 1 - (1 - t) ** 3

    def _lerp_angle_deg(start_deg: float, end_deg: float, t: float) -> float:
        """start→end를 시계 방향으로 120° 이상 크게 스윙"""
        start = math.radians(start_deg % 360)
        end = math.radians(end_deg % 360)
        if end < start:
            end += math.tau
        return start + (end - start) * t

    def draw_arm(side: int, walk_swing: int, swing_ratio: float) -> None:
        """포물선 휘두름 후 자연스럽게 원위치 (고해상도)"""
        shoulder = (cx + side * 60, shoulder_y + 4)  # 30→60, 2→4
        
        # ========== 오른팔 옵티머스 암 로직 (early return) ==========
        if side > 0:
            cs_state = optimus_arm_state
            if cs_state != "idle":
                # 옵티머스 암 활성화 시 오른팔을 보스 방향으로 확장
                cs_arm_length = optimus_arm_length
                cs_target_x = optimus_arm_target_x
                cs_target_y = optimus_arm_target_y
                cs_start_ms = optimus_arm_start_ms
                cs_grabbed = optimus_arm_grabbed_boss
                now_ms = pygame.time.get_ticks()
                
                # 강화된 기계손 색상
                arm_base_color = (80, 60, 50)      # 브론즈
                arm_accent_color = (255, 180, 100)  # 오렌지
                arm_glow_color = (120, 235, 255)    # 시안
                
                # 플레이어 화면 위치 가져오기
                player_rect = PLAYER
                if player_rect:
                    # 타겟까지의 화면 거리 계산
                    screen_shoulder_x = player_rect.centerx + (shoulder[0] - MECHA_CENTER_X)
                    screen_shoulder_y = player_rect.centery + (shoulder[1] - MECHA_CENTER_Y)
                    
                    dx = cs_target_x - screen_shoulder_x
                    dy = cs_target_y - screen_shoulder_y
                    dist = math.sqrt(dx*dx + dy*dy) if (dx*dx + dy*dy) > 0 else 1
                    
                    if cs_state == "windup":
                        # 윈드업: 팔을 뒤로 젖히기
                        elapsed = now_ms - cs_start_ms
                        progress = min(1.0, elapsed / 500.0)  # OPTIMUS_ARM_WINDUP_MS = 500
                        
                        windup_offset_x = int(25 * progress)
                        windup_offset_y = int(20 * progress)
                        
                        wrist = (shoulder[0] + windup_offset_x, shoulder[1] + windup_offset_y)
                        elbow = ((shoulder[0] + wrist[0]) // 2, (shoulder[1] + wrist[1]) // 2)
                        
                        # 팔 그리기
                        pygame.draw.line(surface, arm_base_color, shoulder, elbow, 24)
                        pygame.draw.line(surface, arm_base_color, elbow, wrist, 20)
                        pygame.draw.line(surface, arm_accent_color, shoulder, elbow, 6)
                        pygame.draw.line(surface, arm_accent_color, elbow, wrist, 6)
                        
                        # 손
                        wrist_int = (int(wrist[0]), int(wrist[1]))
                        pygame.draw.circle(surface, arm_base_color, wrist_int, 30)
                        pygame.draw.circle(surface, arm_accent_color, wrist_int, 30, 3)
                        return  # early return
                        
                    elif cs_state in ("reaching", "returning", "grabbing", "throwing"):
                        # 팔 뻗기/복귀
                        arm_len = max(0, cs_arm_length)
                        
                        if arm_len > 0:
                            # 스프라이트 좌표계에서 목표 방향 계산
                            sprite_target_x = MECHA_CENTER_X + (cs_target_x - player_rect.centerx)
                            sprite_target_y = MECHA_CENTER_Y + (cs_target_y - player_rect.centery)
                            
                            sdx = sprite_target_x - shoulder[0]
                            sdy = sprite_target_y - shoulder[1]
                            sdist = math.sqrt(sdx*sdx + sdy*sdy) if (sdx*sdx + sdy*sdy) > 0 else 1
                            sdir_x = sdx / sdist
                            sdir_y = sdy / sdist
                            
                            current_reach = min(arm_len, sdist)
                            end_x = shoulder[0] + sdir_x * current_reach
                            end_y = shoulder[1] + sdir_y * current_reach
                            
                            # 팔 세그먼트로 그리기
                            segments = max(1, int(arm_len / 40))
                            prev_x, prev_y = shoulder[0], shoulder[1]
                            
                            for i in range(segments + 1):
                                ratio = i / segments
                                seg_x = shoulder[0] + (end_x - shoulder[0]) * ratio
                                seg_y = shoulder[1] + (end_y - shoulder[1]) * ratio
                                
                                # 웨이브 효과
                                perp_x = -sdir_y
                                perp_y = sdir_x
                                wave = math.sin(ratio * math.pi * 3 + now_ms / 80) * 4
                                seg_x += perp_x * wave
                                seg_y += perp_y * wave
                                
                                if i > 0:
                                    pygame.draw.line(surface, arm_base_color,
                                                   (int(prev_x), int(prev_y)), (int(seg_x), int(seg_y)), 24)
                                    pygame.draw.line(surface, arm_accent_color,
                                                   (int(prev_x), int(prev_y)), (int(seg_x), int(seg_y)), 6)
                                    
                                    if i % 2 == 0:
                                        pygame.draw.circle(surface, arm_accent_color, (int(seg_x), int(seg_y)), 10)
                                        pygame.draw.circle(surface, arm_glow_color, (int(seg_x), int(seg_y)), 6)
                                
                                prev_x, prev_y = seg_x, seg_y
                            
                            # 손바닥
                            hand_x, hand_y = int(prev_x), int(prev_y)
                            hand_size = 60  # OPTIMUS_ARM_HAND_SIZE
                            
                            if cs_state == "grabbing" and cs_grabbed:
                                # 닫힌 손
                                pygame.draw.ellipse(surface, arm_base_color,
                                                  (hand_x - hand_size//2, hand_y - hand_size//2, hand_size, int(hand_size * 0.8)))
                                pygame.draw.ellipse(surface, arm_accent_color,
                                                  (hand_x - hand_size//2, hand_y - hand_size//2, hand_size, int(hand_size * 0.8)), 4)
                                # 글로우
                                glow = pygame.Surface((hand_size * 2, hand_size * 2), pygame.SRCALPHA)
                                pygame.draw.circle(glow, (*arm_glow_color, 100), (hand_size, hand_size), hand_size)
                                surface.blit(glow, (hand_x - hand_size, hand_y - hand_size))
                            else:
                                # 열린 손
                                pygame.draw.ellipse(surface, arm_base_color,
                                                  (hand_x - hand_size//2, hand_y - hand_size//3, hand_size, int(hand_size * 0.6)))
                                for angle in [-0.5, -0.2, 0.2, 0.5]:
                                    finger_end_x = hand_x + int(hand_size * 0.5 * math.sin(angle))
                                    finger_end_y = hand_y - int(hand_size * 0.4)
                                    pygame.draw.line(surface, arm_base_color, (hand_x, hand_y - 8),
                                                   (finger_end_x, finger_end_y), 8)
                                    pygame.draw.circle(surface, arm_accent_color, (finger_end_x, finger_end_y), 4)
                                pygame.draw.ellipse(surface, arm_accent_color,
                                                  (hand_x - hand_size//2, hand_y - hand_size//3, hand_size, int(hand_size * 0.6)), 3)
                        return  # early return - 옵티머스 암 중에는 일반 오른팔 그리지 않음
        base_upper_len = 64   # 32→64
        base_fore_len = 60    # 30→60

        # 기본(걷기) 포즈 - 고해상도
        idle_elbow = (
            shoulder[0] + side * 24,       # 12→24
            shoulder[1] + 36 + walk_swing * 0.5,  # 18→36
        )
        idle_wrist = (
            idle_elbow[0] + side * 24,     # 12→24
            idle_elbow[1] + 48 + walk_swing,  # 24→48
        )

        if swing_ratio > 0:
            forward_phase = min(1.0, swing_ratio * 2.0)
            return_phase = max(0.0, swing_ratio * 2.0 - 1.0)
            ease_fwd = _ease_out_cubic(forward_phase)
            ease_ret = _ease_out_cubic(return_phase)

            arc_height = 36 * math.sin(math.pi * forward_phase)   # 18→36
            arc_forward = 24 * math.sin(math.pi * forward_phase)  # 12→24

            peak_angle_deg = 20 if side < 0 else 160
            angle = math.radians(peak_angle_deg)

            swing_lift = 20 + 32 * forward_phase   # 10→20, 16→32
            inward_pull = 28 + 24 * forward_phase  # 14→28, 12→24
            upper_len = base_upper_len + 12 * forward_phase  # 6→12
            fore_len = base_fore_len + 20 * forward_phase    # 10→20

            peak_elbow = (
                shoulder[0] + math.cos(angle) * upper_len * 0.5 + (-side) * (inward_pull + arc_forward),
                shoulder[1] + math.sin(angle) * upper_len * 0.5 - swing_lift - arc_height,
            )
            peak_wrist = (
                peak_elbow[0] + math.cos(angle) * fore_len + (-side) * (inward_pull * 0.6 + arc_forward * 0.7),
                peak_elbow[1] + math.sin(angle) * fore_len - swing_lift * 0.7 - arc_height * 0.5,
            )

            # 중앙선 넘지 않도록 클램프 - 고해상도
            if side < 0:
                peak_elbow = (min(peak_elbow[0], cx - 24), peak_elbow[1])  # 12→24
                peak_wrist = (min(peak_wrist[0], cx - 32), peak_wrist[1])  # 16→32
            else:
                peak_elbow = (max(peak_elbow[0], cx + 24), peak_elbow[1])
                peak_wrist = (max(peak_wrist[0], cx + 32), peak_wrist[1])

            def lerp_point(a, b, t):
                return (a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t)

            elbow = lerp_point(idle_elbow, peak_elbow, ease_fwd)
            wrist = lerp_point(idle_wrist, peak_wrist, ease_fwd)
            elbow = lerp_point(elbow, idle_elbow, ease_ret)
            wrist = lerp_point(wrist, idle_wrist, ease_ret)
        else:
            elbow = idle_elbow
            wrist = idle_wrist

        # 팔 그리기 - 고해상도
        pygame.draw.line(surface, palette["body"], shoulder, elbow, 24)   # 12→24
        pygame.draw.line(surface, palette["body"], elbow, wrist, 20)      # 10→20
        pygame.draw.line(surface, palette["arm_line"], shoulder, elbow, 6)  # 3→6
        pygame.draw.line(surface, palette["arm_line"], elbow, wrist, 6)     # 3→6

        # [디테일 추가] 팔꿈치 관절 LED
        elbow_int = (int(elbow[0]), int(elbow[1]))
        pygame.draw.circle(surface, palette["hex_base"], elbow_int, 10)
        pygame.draw.circle(surface, palette["accent"], elbow_int, 6, 2)
        pygame.draw.circle(surface, palette["hex_core"], elbow_int, 4)

        # [디테일 추가] 팔 중간 아머 플레이트
        mid_arm = ((int(shoulder[0]) + elbow_int[0]) // 2, (int(shoulder[1]) + elbow_int[1]) // 2)
        pygame.draw.circle(surface, palette["helmet"], mid_arm, 8)
        pygame.draw.circle(surface, palette["accent"], mid_arm, 5, 2)

        # 손 그리기
        wrist_int = (int(wrist[0]), int(wrist[1]))
        pygame.draw.circle(surface, palette["hand"], wrist_int, 12)  # 6→12

        # [디테일 추가] 손가락 (양손 모두)
        for finger_idx in range(4):
            finger_angle = math.radians(-30 + finger_idx * 20)
            finger_len = 10 + (1 if finger_idx in (1, 2) else 0) * 2
            fx = wrist_int[0] + int(math.cos(finger_angle) * finger_len) + side * 8
            fy = wrist_int[1] + int(math.sin(finger_angle) * finger_len) + 6
            pygame.draw.line(surface, palette["hand"], wrist_int, (fx, fy), 4)
            pygame.draw.circle(surface, palette["hand"], (fx, fy), 3)
        # 엄지
        thumb_x = wrist_int[0] + side * 6
        thumb_y = wrist_int[1] - 6
        pygame.draw.line(surface, palette["hand"], wrist_int, (thumb_x, thumb_y), 4)
        pygame.draw.circle(surface, palette["hand"], (thumb_x, thumb_y), 3)

        # 왼팔 사이버 전자 탁구채 (15도 오른쪽 회전)
        if side < 0:
            # 궁극의 탁구채 강화 상태 체크
            paddle_upgraded = optimus_paddle_upgrade_complete
            paddle_anim_active = optimus_paddle_upgrade_active
            paddle_anim_timer = optimus_paddle_upgrade_timer
            paddle_particles = optimus_paddle_upgrade_particles
            paddle_anim_now = pygame.time.get_ticks()
            paddle_anim_duration = 2000  # 2초 강화 애니메이션

            # 애니메이션 진행률 계산
            paddle_anim_progress = 0.0
            if paddle_anim_active and paddle_anim_timer > 0:
                paddle_anim_elapsed = paddle_anim_now - paddle_anim_timer
                paddle_anim_progress = min(1.0, paddle_anim_elapsed / paddle_anim_duration)
                if paddle_anim_progress >= 1.0:
                    # 애니메이션 완료 → 강화 완료 상태로 전환
                    globals()["optimus_paddle_upgrade_active"] = False
                    globals()["optimus_paddle_upgrade_complete"] = True
                    paddle_upgraded = True
                    paddle_anim_active = False

            # 탁구채를 별도 서피스에 그린 후 회전
            paddle_surf_size = 190 if paddle_upgraded else 140
            paddle_surface = pygame.Surface((paddle_surf_size, paddle_surf_size), pygame.SRCALPHA)
            ps_cx, ps_cy = paddle_surf_size // 2, paddle_surf_size // 2  # 서피스 중앙

            # 탁구채 라켓 면 크기 (강화 시 더 큼)
            if paddle_upgraded:
                paddle_w, paddle_h = 88, 99  # 궁극의 탁구채
            else:
                paddle_w, paddle_h = 66, 77
            # 라켓 면을 손잡이 바로 아래에 배치 (완전히 붙임)
            paddle_rect = pygame.Rect(ps_cx - paddle_w // 2, ps_cy - 8, paddle_w, paddle_h)

            # 손잡이 (그립) - 라켓 면 바로 위에 배치 (간격 없이 완전히 붙임)
            grip_offset_y = -44 if paddle_upgraded else -40  # 손잡이와 라켓 면 완전히 붙임
            if paddle_upgraded:
                # 궁극의 탁구채 그립 (골드-레드)
                pygame.draw.rect(paddle_surface, (100, 50, 30),
                               (ps_cx - 9, ps_cy + grip_offset_y - 6, 18, 40), border_radius=5)
                pygame.draw.rect(paddle_surface, (255, 180, 80),
                               (ps_cx - 7, ps_cy + grip_offset_y - 4, 14, 36), border_radius=4)
                pygame.draw.rect(paddle_surface, (255, 220, 120),
                               (ps_cx - 5, ps_cy + grip_offset_y, 10, 28), 1, border_radius=3)
                # 그립 보석 장식
                pygame.draw.circle(paddle_surface, (255, 80, 80), (ps_cx, ps_cy + grip_offset_y + 16), 6)
                pygame.draw.circle(paddle_surface, (255, 200, 200), (ps_cx, ps_cy + grip_offset_y + 16), 3)
            else:
                pygame.draw.rect(paddle_surface, palette["grip"],
                               (ps_cx - 7, ps_cy + grip_offset_y - 4, 14, 32), border_radius=4)
                pygame.draw.rect(paddle_surface, palette["grip_line"],
                               (ps_cx - 5, ps_cy + grip_offset_y, 10, 24), 1, border_radius=3)

            if paddle_upgraded:
                # === 궁극의 탁구채 디자인 ===
                # 라켓 외곽 프레임 (다크 레드-골드)
                pygame.draw.rect(paddle_surface, (80, 30, 20), paddle_rect, border_radius=8)
                pygame.draw.rect(paddle_surface, (60, 20, 15), paddle_rect.inflate(-4, -4), border_radius=6)

                # 라켓 메인 면 (크림슨-골드 그라데이션 느낌)
                inner_rect = paddle_rect.inflate(-10, -10)
                pygame.draw.rect(paddle_surface, (120, 40, 30), inner_rect, border_radius=5)

                # 궁극의 에너지 패턴 (십자형 + 대각선)
                energy_color = (255, 200, 100, 180)
                # 십자형
                pygame.draw.line(paddle_surface, energy_color,
                               (inner_rect.centerx, inner_rect.top + 4),
                               (inner_rect.centerx, inner_rect.bottom - 4), 2)
                pygame.draw.line(paddle_surface, energy_color,
                               (inner_rect.left + 4, inner_rect.centery),
                               (inner_rect.right - 4, inner_rect.centery), 2)
                # 대각선
                pygame.draw.line(paddle_surface, energy_color,
                               (inner_rect.left + 8, inner_rect.top + 8),
                               (inner_rect.right - 8, inner_rect.bottom - 8), 2)
                pygame.draw.line(paddle_surface, energy_color,
                               (inner_rect.right - 8, inner_rect.top + 8),
                               (inner_rect.left + 8, inner_rect.bottom - 8), 2)

                # 중앙 궁극의 에너지 코어 (더 크고 화려함)
                core_cx, core_cy = paddle_rect.centerx, paddle_rect.centery
                # 외곽 글로우 링
                for ring_i in range(3):
                    ring_radius = 18 - ring_i * 4
                    ring_alpha = int(80 + 60 * math.sin(phase * math.tau * 3 + ring_i))
                    ring_surf = pygame.Surface((ring_radius * 2 + 4, ring_radius * 2 + 4), pygame.SRCALPHA)
                    pygame.draw.circle(ring_surf, (255, 180, 80, ring_alpha), (ring_radius + 2, ring_radius + 2), ring_radius, 2)
                    paddle_surface.blit(ring_surf, (core_cx - ring_radius - 2, core_cy - ring_radius - 2))

                pygame.draw.circle(paddle_surface, (80, 30, 20), (core_cx, core_cy), 16)
                core_pulse = int(200 + 55 * math.sin(phase * math.tau * 2))
                pygame.draw.circle(paddle_surface, (255, core_pulse, 50), (core_cx, core_cy), 14)
                pygame.draw.circle(paddle_surface, (255, 220, 150), (core_cx, core_cy), 10)
                pygame.draw.circle(paddle_surface, (255, 255, 230), (core_cx, core_cy), 5)

                # 라켓 외곽 LED 테두리 (골드)
                pygame.draw.rect(paddle_surface, (255, 200, 100), paddle_rect, 4, border_radius=8)

                # 모서리 에너지 포인트 (더 크고 화려)
                corner_offsets = [(6, 6), (-6, 6), (6, -6), (-6, -6)]
                for ci, (ox, oy) in enumerate(corner_offsets):
                    cx_pos = paddle_rect.left + 6 if ox > 0 else paddle_rect.right - 6
                    cy_pos = paddle_rect.top + 6 if oy > 0 else paddle_rect.bottom - 6
                    corner_pulse = int(200 + 55 * math.sin(phase * math.tau * 4 + ci * 0.5))
                    pygame.draw.circle(paddle_surface, (255, corner_pulse, 80), (cx_pos, cy_pos), 5)
                    pygame.draw.circle(paddle_surface, (255, 255, 200), (cx_pos, cy_pos), 2)

                # 에너지 아크 (라켓 면에서 발산)
                for arc_i in range(4):
                    arc_angle = math.radians(arc_i * 90 + 45 + phase * 60)
                    arc_start = (core_cx + int(math.cos(arc_angle) * 12), core_cy + int(math.sin(arc_angle) * 12))
                    arc_len = 10 + 5 * math.sin(phase * math.tau * 4 + arc_i)
                    arc_end = (core_cx + int(math.cos(arc_angle) * (12 + arc_len)),
                              core_cy + int(math.sin(arc_angle) * (12 + arc_len)))
                    pygame.draw.line(paddle_surface, (255, 220, 150), arc_start, arc_end, 2)
            else:
                # === 기본 탁구채 디자인 ===
                # 라켓 외곽 프레임 (다크 메탈)
                pygame.draw.rect(paddle_surface, palette["hex_base"], paddle_rect, border_radius=6)

                # 라켓 메인 면 (네온 사이언)
                inner_rect = paddle_rect.inflate(-8, -8)
                pygame.draw.rect(paddle_surface, palette["helmet"], inner_rect, border_radius=4)

                # 사이버 그리드 패턴
                grid_color = (*palette["accent"], 120)
                for gy in range(inner_rect.top + 6, inner_rect.bottom - 4, 10):
                    pygame.draw.line(paddle_surface, grid_color, (inner_rect.left + 4, gy), (inner_rect.right - 4, gy), 1)
                for gx in range(inner_rect.left + 6, inner_rect.right - 4, 10):
                    pygame.draw.line(paddle_surface, grid_color, (gx, inner_rect.top + 4), (gx, inner_rect.bottom - 4), 1)

                # 중앙 에너지 코어 (원형)
                core_cx, core_cy = paddle_rect.centerx, paddle_rect.centery
                pygame.draw.circle(paddle_surface, palette["hex_base"], (core_cx, core_cy), 12)
                pygame.draw.circle(paddle_surface, palette["accent"], (core_cx, core_cy), 10)
                pygame.draw.circle(paddle_surface, palette["hex_core"], (core_cx, core_cy), 6)
                pygame.draw.circle(paddle_surface, palette["visor_highlight"], (core_cx, core_cy), 3)

                # 라켓 외곽 LED 테두리
                pygame.draw.rect(paddle_surface, palette["accent"], paddle_rect, 3, border_radius=6)

                # 모서리 LED 포인트
                for corner in [(paddle_rect.left + 4, paddle_rect.top + 4),
                              (paddle_rect.right - 4, paddle_rect.top + 4),
                              (paddle_rect.left + 4, paddle_rect.bottom - 4),
                              (paddle_rect.right - 4, paddle_rect.bottom - 4)]:
                    pygame.draw.circle(paddle_surface, palette["visor_highlight"], corner, 3)

            # 145도 오른쪽(시계방향) 회전 (기존 15도 + 추가 130도)
            rotated_paddle = pygame.transform.rotate(paddle_surface, -145)

            # 회전된 탁구채를 메인 서피스에 블릿
            # 위치 계산: 손목(왼손) 기준 - 손잡이가 손 위치에 오도록 위로 배치
            paddle_blit_x = wrist_int[0] - rotated_paddle.get_width() // 2 - (22 if paddle_upgraded else 17)
            paddle_blit_y = wrist_int[1] - rotated_paddle.get_height() // 2 - (11 if paddle_upgraded else 6)

            # 강화 애니메이션 진행 중일 때 조립 이펙트
            if paddle_anim_active and paddle_anim_progress > 0:
                paddle_center_x = paddle_blit_x + rotated_paddle.get_width() // 2
                paddle_center_y = paddle_blit_y + rotated_paddle.get_height() // 2

                # 배경 글로우 (강화 중 강렬한 레드-골드 빛)
                glow_intensity = int(100 + 150 * math.sin(paddle_anim_progress * math.pi))
                glow_size = int(70 + 50 * paddle_anim_progress)
                glow_surf = pygame.Surface((glow_size * 2, glow_size * 2), pygame.SRCALPHA)
                pygame.draw.circle(glow_surf, (255, 150, 80, glow_intensity), (glow_size, glow_size), glow_size)
                surface.blit(glow_surf, (paddle_center_x - glow_size, paddle_center_y - glow_size))

                # 수렴하는 파티클 그리기
                particle_colors = [(255, 80, 80), (255, 160, 80), (255, 220, 120), (255, 255, 200)]
                for p in paddle_particles:
                    p_elapsed = paddle_anim_now - p['spawn_time']
                    p_life_ratio = min(1.0, p_elapsed / p['max_life'])

                    # 파티클이 중심으로 수렴
                    current_dist = p['dist'] * (1.0 - paddle_anim_progress * 0.9)
                    px = paddle_center_x + int(math.cos(p['angle'] + paddle_anim_progress * 3) * current_dist)
                    py = paddle_center_y + int(math.sin(p['angle'] + paddle_anim_progress * 3) * current_dist)

                    p_size = int(p['size'] * (1.0 - p_life_ratio * 0.5))
                    if p_size > 0:
                        p_color = particle_colors[p['color_idx'] % len(particle_colors)]
                        p_alpha = int(255 * (1.0 - p_life_ratio * 0.6))
                        p_surf = pygame.Surface((p_size * 2 + 4, p_size * 2 + 4), pygame.SRCALPHA)
                        pygame.draw.circle(p_surf, (*p_color, p_alpha), (p_size + 2, p_size + 2), p_size)
                        # 파티클 꼬리
                        tail_len = int(10 * (1.0 - paddle_anim_progress))
                        if tail_len > 0:
                            tail_x = px + int(math.cos(p['angle']) * tail_len)
                            tail_y = py + int(math.sin(p['angle']) * tail_len)
                            pygame.draw.line(surface, (*p_color, p_alpha // 2), (px, py), (tail_x, tail_y), 2)
                        surface.blit(p_surf, (px - p_size - 2, py - p_size - 2))

                # Phase 2-3: 조립 중인 부품 그리기
                if paddle_anim_progress > 0.3:
                    assemble_progress = (paddle_anim_progress - 0.3) / 0.7
                    # 궁극의 탁구채 부품 (6방향에서 수렴)
                    for plate_idx in range(6):
                        plate_angle = math.radians(plate_idx * 60 + 30)
                        plate_start_dist = 60 * (1.0 - assemble_progress)
                        plate_x = paddle_center_x + int(math.cos(plate_angle) * plate_start_dist)
                        plate_y = paddle_center_y + int(math.sin(plate_angle) * plate_start_dist)
                        plate_size = int(10 + 6 * assemble_progress)
                        plate_alpha = int(220 * assemble_progress)
                        plate_surf = pygame.Surface((plate_size * 2, plate_size * 2), pygame.SRCALPHA)
                        pygame.draw.rect(plate_surf, (120, 50, 30, plate_alpha), (0, 0, plate_size * 2, plate_size * 2), border_radius=4)
                        pygame.draw.rect(plate_surf, (255, 180, 80, plate_alpha), (0, 0, plate_size * 2, plate_size * 2), 2, border_radius=4)
                        surface.blit(plate_surf, (plate_x - plate_size, plate_y - plate_size))

                # Phase 3: 완성 에너지 폭발
                if paddle_anim_progress > 0.7:
                    burst_progress = (paddle_anim_progress - 0.7) / 0.3
                    burst_radius = int(25 + 70 * burst_progress)
                    burst_alpha = int(200 * (1.0 - burst_progress))
                    burst_surf = pygame.Surface((burst_radius * 2, burst_radius * 2), pygame.SRCALPHA)
                    pygame.draw.circle(burst_surf, (255, 180, 80, burst_alpha), (burst_radius, burst_radius), burst_radius, 4)
                    pygame.draw.circle(burst_surf, (255, 255, 200, burst_alpha // 2), (burst_radius, burst_radius), int(burst_radius * 0.7), 3)
                    surface.blit(burst_surf, (paddle_center_x - burst_radius, paddle_center_y - burst_radius))

                    # 방사형 에너지 스파크 (더 화려함)
                    for spark_i in range(10):
                        spark_angle = math.radians(spark_i * 36 + phase * 200)
                        spark_len = int(35 * burst_progress)
                        spark_start = (paddle_center_x + int(math.cos(spark_angle) * 18),
                                      paddle_center_y + int(math.sin(spark_angle) * 18))
                        spark_end = (paddle_center_x + int(math.cos(spark_angle) * (18 + spark_len)),
                                    paddle_center_y + int(math.sin(spark_angle) * (18 + spark_len)))
                        spark_mid = ((spark_start[0] + spark_end[0]) // 2 + int(math.sin(phase * 40 + spark_i) * 6),
                                    (spark_start[1] + spark_end[1]) // 2 + int(math.cos(phase * 40 + spark_i) * 6))
                        pygame.draw.line(surface, (255, 200, 120), spark_start, spark_mid, 2)
                        pygame.draw.line(surface, (255, 255, 200), spark_mid, spark_end, 2)

            # 탁구채 블릿
            surface.blit(rotated_paddle, (paddle_blit_x, paddle_blit_y))

        # 오른팔 강철 전기 주먹
        if side > 0:
            fist_cx, fist_cy = wrist_int[0] + 8, wrist_int[1] + 4

            # 기계손 강화 상태 체크
            mech_arm_upgraded = optimus_mech_arm_upgrade_complete
            mech_arm_anim_active = optimus_mech_arm_upgrade_active
            mech_arm_timer = optimus_mech_arm_upgrade_timer
            mech_arm_particles = optimus_mech_arm_particles
            anim_now = pygame.time.get_ticks()
            anim_duration = 2000  # 2초 강화 애니메이션

            # 애니메이션 진행률 계산
            anim_progress = 0.0
            if mech_arm_anim_active and mech_arm_timer > 0:
                anim_elapsed = anim_now - mech_arm_timer
                anim_progress = min(1.0, anim_elapsed / anim_duration)
                if anim_progress >= 1.0:
                    # 애니메이션 완료 → 강화 완료 상태로 전환
                    globals()["optimus_mech_arm_upgrade_active"] = False
                    globals()["optimus_mech_arm_upgrade_complete"] = True
                    globals()["optimus_arm_available"] = True  # 옵티머스 암 스킬 활성화!
                    mech_arm_upgraded = True
                    mech_arm_anim_active = False
                    # print("🦾 기계손 강화 완료! 옵티머스 암 스킬 사용 가능!")

            # 강화 애니메이션 진행 중일 때 조립 이펙트
            if mech_arm_anim_active and anim_progress > 0:
                # 페이즈별 애니메이션
                # Phase 1 (0-0.3): 기존 주먹 분해 + 파티클 수렴
                # Phase 2 (0.3-0.7): 새 부품 조립
                # Phase 3 (0.7-1.0): 완성 + 에너지 폭발

                # 배경 글로우 (강화 중 더 강렬한 빛)
                glow_intensity = int(80 + 120 * math.sin(anim_progress * math.pi))
                glow_size = int(60 + 40 * anim_progress)
                glow_surf = pygame.Surface((glow_size * 2, glow_size * 2), pygame.SRCALPHA)
                pygame.draw.circle(glow_surf, (100, 180, 255, glow_intensity), (glow_size, glow_size), glow_size)
                surface.blit(glow_surf, (fist_cx - glow_size, fist_cy - glow_size))

                # 수렴하는 파티클 그리기
                particle_colors = [(80, 150, 255), (100, 220, 255), (200, 230, 255)]
                for p in mech_arm_particles:
                    p_elapsed = anim_now - p['spawn_time']
                    p_life_ratio = min(1.0, p_elapsed / p['max_life'])

                    # 파티클이 중심으로 수렴
                    current_dist = p['dist'] * (1.0 - anim_progress * 0.9)
                    px = fist_cx + int(math.cos(p['angle'] + anim_progress * 2) * current_dist)
                    py = fist_cy + int(math.sin(p['angle'] + anim_progress * 2) * current_dist)

                    # 파티클 크기 (수렴하면서 작아짐)
                    p_size = int(p['size'] * (1.0 - p_life_ratio * 0.5))
                    if p_size > 0:
                        p_color = particle_colors[p['color_idx']]
                        p_alpha = int(255 * (1.0 - p_life_ratio * 0.7))
                        p_surf = pygame.Surface((p_size * 2 + 4, p_size * 2 + 4), pygame.SRCALPHA)
                        pygame.draw.circle(p_surf, (*p_color, p_alpha), (p_size + 2, p_size + 2), p_size)
                        # 파티클 꼬리 (라인)
                        tail_len = int(8 * (1.0 - anim_progress))
                        if tail_len > 0:
                            tail_x = px + int(math.cos(p['angle']) * tail_len)
                            tail_y = py + int(math.sin(p['angle']) * tail_len)
                            pygame.draw.line(surface, (*p_color, p_alpha // 2), (px, py), (tail_x, tail_y), 2)
                        surface.blit(p_surf, (px - p_size - 2, py - p_size - 2))

                # Phase 2-3: 조립 중인 부품 그리기
                if anim_progress > 0.3:
                    assemble_progress = (anim_progress - 0.3) / 0.7
                    # 조립 중인 아머 플레이트 (위에서 내려옴)
                    for plate_idx in range(4):
                        plate_angle = math.radians(plate_idx * 90 + 45)
                        plate_start_dist = 50 * (1.0 - assemble_progress)
                        plate_x = fist_cx + int(math.cos(plate_angle) * plate_start_dist)
                        plate_y = fist_cy + int(math.sin(plate_angle) * plate_start_dist)
                        plate_size = int(8 + 4 * assemble_progress)
                        plate_alpha = int(200 * assemble_progress)
                        plate_surf = pygame.Surface((plate_size * 2, plate_size * 2), pygame.SRCALPHA)
                        pygame.draw.rect(plate_surf, (60, 80, 120, plate_alpha), (0, 0, plate_size * 2, plate_size * 2), border_radius=3)
                        pygame.draw.rect(plate_surf, (100, 180, 255, plate_alpha), (0, 0, plate_size * 2, plate_size * 2), 2, border_radius=3)
                        surface.blit(plate_surf, (plate_x - plate_size, plate_y - plate_size))

                # Phase 3: 완성 에너지 폭발
                if anim_progress > 0.7:
                    burst_progress = (anim_progress - 0.7) / 0.3
                    burst_radius = int(20 + 60 * burst_progress)
                    burst_alpha = int(180 * (1.0 - burst_progress))
                    burst_surf = pygame.Surface((burst_radius * 2, burst_radius * 2), pygame.SRCALPHA)
                    pygame.draw.circle(burst_surf, (150, 220, 255, burst_alpha), (burst_radius, burst_radius), burst_radius, 3)
                    pygame.draw.circle(burst_surf, (255, 255, 255, burst_alpha // 2), (burst_radius, burst_radius), int(burst_radius * 0.7), 2)
                    surface.blit(burst_surf, (fist_cx - burst_radius, fist_cy - burst_radius))

                    # 방사형 전기 스파크
                    for spark_i in range(8):
                        spark_angle = math.radians(spark_i * 45 + phase * 180)
                        spark_len = int(30 * burst_progress)
                        spark_start = (fist_cx + int(math.cos(spark_angle) * 15), fist_cy + int(math.sin(spark_angle) * 15))
                        spark_end = (fist_cx + int(math.cos(spark_angle) * (15 + spark_len)), fist_cy + int(math.sin(spark_angle) * (15 + spark_len)))
                        spark_mid = ((spark_start[0] + spark_end[0]) // 2 + int(math.sin(phase * 30 + spark_i) * 5),
                                    (spark_start[1] + spark_end[1]) // 2 + int(math.cos(phase * 30 + spark_i) * 5))
                        pygame.draw.line(surface, (200, 240, 255), spark_start, spark_mid, 2)
                        pygame.draw.line(surface, (255, 255, 255), spark_mid, spark_end, 2)

            # 기본 주먹 크기 (강화 시 더 큼)
            if mech_arm_upgraded:
                fist_w, fist_h = 44, 50  # 강화된 크기
            else:
                fist_w, fist_h = 36, 40
            fist_rect = pygame.Rect(fist_cx - fist_w // 2, fist_cy - fist_h // 2, fist_w, fist_h)

            # 주먹 글로우 효과 (강화 시 더 강렬)
            fist_glow = pygame.Surface((fist_w + 40, fist_h + 40), pygame.SRCALPHA)
            if mech_arm_upgraded:
                glow_alpha = int(60 + 50 * math.sin(phase * math.tau * 3))
                glow_color = (255, 150, 80, glow_alpha)  # 오렌지 글로우 (강화)
            else:
                glow_alpha = int(40 + 30 * math.sin(phase * math.tau * 3))
                glow_color = (100, 200, 255, glow_alpha)  # 블루 글로우 (기본)
            pygame.draw.ellipse(fist_glow, glow_color, (0, 0, fist_w + 40, fist_h + 40))
            surface.blit(fist_glow, (fist_rect.left - 20, fist_rect.top - 20))

            # 강철 주먹 베이스 (강화 시 다른 색상)
            if mech_arm_upgraded:
                pygame.draw.ellipse(surface, (80, 60, 50), fist_rect)  # 어두운 오렌지-브론즈
                pygame.draw.ellipse(surface, (100, 80, 60), fist_rect.inflate(-6, -6))
            else:
                pygame.draw.ellipse(surface, palette["hex_base"], fist_rect)
                pygame.draw.ellipse(surface, (60, 70, 85), fist_rect.inflate(-6, -6))

            # 너클 플레이트 (강화 시 더 크고 날카로움)
            knuckle_y = fist_cy - (12 if mech_arm_upgraded else 10)
            knuckle_offsets = [-12, -4, 4, 12] if mech_arm_upgraded else [-10, -3, 4, 11]
            for ki, kx_off in enumerate(knuckle_offsets):
                knuckle_w = 12 if mech_arm_upgraded else 10
                knuckle_h = 18 if mech_arm_upgraded else 14
                knuckle_rect = pygame.Rect(fist_cx + kx_off - knuckle_w // 2, knuckle_y - knuckle_h // 2, knuckle_w, knuckle_h)
                if mech_arm_upgraded:
                    # 강화된 너클: 스파이크 형태
                    pygame.draw.rect(surface, (90, 70, 55), knuckle_rect, border_radius=2)
                    pygame.draw.rect(surface, (255, 180, 100), knuckle_rect, 2, border_radius=2)
                    # 스파이크 LED (오렌지)
                    led_pulse = int(200 + 55 * math.sin(phase * math.tau * 5 + ki * 0.5))
                    pygame.draw.circle(surface, (255, led_pulse, 50), (fist_cx + kx_off, knuckle_y - 3), 3)
                else:
                    pygame.draw.rect(surface, palette["body"], knuckle_rect, border_radius=3)
                    pygame.draw.rect(surface, palette["accent"], knuckle_rect, 1, border_radius=3)
                    led_pulse = int(180 + 75 * math.sin(phase * math.tau * 4 + ki * 0.5))
                    pygame.draw.circle(surface, (led_pulse, led_pulse, 255), (fist_cx + kx_off, knuckle_y - 2), 2)

            # 전기/에너지 아크 효과 (강화 시 더 화려)
            if mech_arm_upgraded:
                # 강화된 아크: 오렌지-레드 에너지
                arc_colors = [(255, 180, 80), (255, 140, 60), (255, 200, 120)]
                arc_count = 5
            else:
                arc_colors = [(150, 220, 255)] * 3
                arc_count = 3

            for arc_i in range(arc_count):
                arc_phase = phase * math.tau * 5 + arc_i * (2.1 if not mech_arm_upgraded else 1.3)
                arc_len = (16 if mech_arm_upgraded else 12) + 6 * math.sin(arc_phase)
                arc_angle = math.radians(-60 + arc_i * (72 if mech_arm_upgraded else 40) + math.sin(phase * 10) * 15)
                arc_start_dist = 22 if mech_arm_upgraded else 18
                arc_start = (fist_cx + int(math.cos(arc_angle) * arc_start_dist), fist_cy - 8 + int(math.sin(arc_angle) * 14))
                arc_end = (arc_start[0] + int(math.cos(arc_angle + 0.3) * arc_len),
                          arc_start[1] + int(math.sin(arc_angle + 0.3) * arc_len))
                mid1 = ((arc_start[0] + arc_end[0]) // 2 + int(math.sin(phase * 20 + arc_i) * 5),
                       (arc_start[1] + arc_end[1]) // 2 + int(math.cos(phase * 20 + arc_i) * 4))
                arc_color = arc_colors[arc_i % len(arc_colors)]
                pygame.draw.line(surface, arc_color, arc_start, mid1, 3 if mech_arm_upgraded else 2)
                pygame.draw.line(surface, arc_color, mid1, arc_end, 3 if mech_arm_upgraded else 2)
                # 아크 끝 글로우
                end_glow_color = (255, 220, 150) if mech_arm_upgraded else (200, 240, 255)
                pygame.draw.circle(surface, end_glow_color, arc_end, 4 if mech_arm_upgraded else 3)

            # 손등 에너지 코어 (강화 시 더 크고 오렌지)
            core_x, core_y = fist_cx, fist_cy + (8 if mech_arm_upgraded else 6)
            core_radius = 14 if mech_arm_upgraded else 10
            pygame.draw.circle(surface, (80, 60, 50) if mech_arm_upgraded else palette["hex_base"], (core_x, core_y), core_radius)
            core_pulse = int(200 + 55 * math.sin(phase * math.tau * 2))
            if mech_arm_upgraded:
                pygame.draw.circle(surface, (255, core_pulse, 50), (core_x, core_y), core_radius - 2)
                pygame.draw.circle(surface, (255, 255, 200), (core_x, core_y), 6)
                # 추가 외곽 링
                pygame.draw.circle(surface, (255, 180, 80), (core_x, core_y), core_radius + 2, 2)
            else:
                pygame.draw.circle(surface, (core_pulse, core_pulse, 255), (core_x, core_y), 8)
                pygame.draw.circle(surface, (255, 255, 255), (core_x, core_y), 4)

            # 손가락 관절 (주먹 쥔 상태) - 강화 시 더 큼
            finger_count = 4
            finger_spread = 8 if mech_arm_upgraded else 7
            finger_y_offset = 22 if mech_arm_upgraded else 18
            for fi in range(finger_count):
                finger_x = fist_cx - int(finger_spread * 1.5) + fi * finger_spread
                finger_y = fist_cy - finger_y_offset
                finger_size = 6 if mech_arm_upgraded else 5
                pygame.draw.circle(surface, (90, 70, 55) if mech_arm_upgraded else palette["hand"], (finger_x, finger_y), finger_size)
                pygame.draw.circle(surface, (70, 55, 45) if mech_arm_upgraded else palette["body"], (finger_x, finger_y), finger_size - 1)
            # 엄지 (주먹 옆) - 강화 시 더 크고 다른 색상
            if mech_arm_upgraded:
                thumb_pts = [(fist_cx + 24, fist_cy - 5), (fist_cx + 32, fist_cy + 3), (fist_cx + 30, fist_cy + 14)]
                pygame.draw.polygon(surface, (90, 70, 55), thumb_pts)
                pygame.draw.polygon(surface, (255, 180, 100), thumb_pts, 2)
            else:
                thumb_pts = [(fist_cx + 20, fist_cy - 4), (fist_cx + 26, fist_cy + 2), (fist_cx + 24, fist_cy + 10)]
                pygame.draw.polygon(surface, palette["hand"], thumb_pts)
                pygame.draw.polygon(surface, palette["body"], thumb_pts, 2)

            # 주먹 외곽 LED 링 (강화 시 오렌지)
            if mech_arm_upgraded:
                pygame.draw.ellipse(surface, (255, 180, 100), fist_rect, 3)
            else:
                pygame.draw.ellipse(surface, palette["accent"], fist_rect, 2)

            # 스파크 파티클 (강화 시 더 많고 오렌지)
            spark_count = 6 if mech_arm_upgraded else 4
            for sp_i in range(spark_count):
                sp_phase = phase * 8 + sp_i * (1.0 if mech_arm_upgraded else 1.5)
                spark_dist = (24 if mech_arm_upgraded else 20) + sp_i * 3
                sp_x = fist_cx + int(math.cos(sp_phase) * spark_dist)
                sp_y = fist_cy - 6 + int(math.sin(sp_phase * 1.3) * (18 if mech_arm_upgraded else 15 + sp_i * 2))
                sp_alpha = int(150 + 100 * math.sin(sp_phase * 2))
                spark_surf = pygame.Surface((8, 8), pygame.SRCALPHA)
                if mech_arm_upgraded:
                    pygame.draw.circle(spark_surf, (255, 200, 100, sp_alpha), (4, 4), 3)
                else:
                    pygame.draw.circle(spark_surf, (255, 255, 255, sp_alpha), (4, 4), 2)
                surface.blit(spark_surf, (sp_x - 4, sp_y - 4))

    draw_arm(-1, arm_swing_left, left_swing_ratio)
    draw_arm(1, arm_swing_right, right_swing_ratio)

    # 상체/머리 글로우 - 고해상도
    glow_surface = pygame.Surface(MECHA_SPRITE_SIZE, pygame.SRCALPHA)
    pygame.draw.ellipse(glow_surface, (*palette["glow"], 50), (cx - 130, base_cy - 64 + torso_bob, 260, 180), 4)  # 65→130, 32→64, 130→260, 90→180, 2→4
    pygame.draw.ellipse(glow_surface, (*palette["glow"], 70), (cx - 68, head_y - 12, 136, 84), 2)  # 34→68, 6→12, 68→136, 42→84, 1→2
    surface.blit(glow_surface, (0, 0))

    # 육각 실드(얇은) - 고해상도
    for i in range(2):
        at_field_radius = 112 + i * 20  # 56→112, 10→20
        at_alpha = max(0, 28 - i * 10)
        points = []
        for j in range(6):
            angle = math.radians(j * 60 + 30)
            points.append((cx + int(math.cos(angle) * at_field_radius),
                           base_cy + int(math.sin(angle) * at_field_radius * 0.75) + torso_bob))
        at_surface = pygame.Surface(MECHA_SPRITE_SIZE, pygame.SRCALPHA)
        pygame.draw.polygon(at_surface, (*palette["at_field"], at_alpha), points, 2)  # 1→2
        surface.blit(at_surface, (0, 0))

    return surface

# === 스매셔 히트/방패/왼팔 연출 상수 및 타이머 (create_smasher_paddle_surface보다 먼저 정의 필요) ===
SMASHER_HIT_POSE_DURATION = 8  # 공을 칠 때 왼팔 히트 포즈 유지 프레임 수
SMASHER_SHIELD_RAISE_DURATION = 18  # 오른쪽 타격 시 방패 들어올리기 연출 시간
SMASHER_LEFT_RAISE_DURATION = 18  # 왼쪽 타격 시 왼팔 들어올리기 연출 시간
smasher_hit_pose_timer = 0
smasher_shield_raise_timer = 0
smasher_left_raise_timer = 0
smasher_swing_intensity = 1.0  # 스윙 강도 (일반=1.0, 드라이브=1.5, 파워스매싱=2.0)


# === 스매셔 공용 유틸리티 (구형/신형 렌더링 양쪽에서 사용) ===

def _smasher_rotate_point(origin: tuple[float, float], point: tuple[float, float], degrees: float) -> tuple[float, float]:
    """주어진 점을 화면 좌표계 기준으로 시계 방향 회전"""
    radians = math.radians(degrees)
    cos_v = math.cos(radians)
    sin_v = math.sin(radians)
    ox, oy = origin
    px, py = point
    translated_x = px - ox
    translated_y = py - oy
    return ox + translated_x * cos_v - translated_y * sin_v, oy + translated_x * sin_v + translated_y * cos_v


def _smasher_lerp_point(start: tuple[float, float], end: tuple[float, float], t: float) -> tuple[float, float]:
    return start[0] + (end[0] - start[0]) * t, start[1] + (end[1] - start[1]) * t


def _smasher_to_int(point: tuple[float, float]) -> tuple[int, int]:
    return int(round(point[0])), int(round(point[1]))


def _smasher_regular_polygon(center: tuple[float, float], radius: float, *, sides: int = 5, rotation_deg: float = -90.0) -> list[tuple[float, float]]:
    rotation = math.radians(rotation_deg)
    return [
        (
            center[0] + radius * math.cos(rotation + i * math.tau / sides),
            center[1] + radius * math.sin(rotation + i * math.tau / sides),
        )
        for i in range(sides)
    ]


def _smasher_bell_strength(timer: int, base_duration: int, intensity: float = 1.0) -> float:
    """타이머 기반 0→1→0 벨 커브 강도 계산 (intensity로 duration 스케일 + 피크 유지 조절)."""
    eff_duration = max(1, int(base_duration * intensity))
    if eff_duration <= 0 or timer <= 0:
        return 0.0
    normalized = 1.0 - (timer / eff_duration)
    normalized = max(0.0, min(1.0, normalized))
    strength = normalized * 2.0 if normalized < 0.5 else (1.0 - normalized) * 2.0
    strength = max(0.0, min(1.0, strength))
    exp = max(0.3, 0.7 / max(1.0, intensity))
    return strength ** exp


def _smasher_hit_ratio(timer: int, base_duration: int, intensity: float = 1.0) -> float:
    """히트 포즈용 ratio 계산 (타이머/유효duration, 0~1 클램프)."""
    eff_duration = max(1, int(base_duration * intensity))
    if eff_duration <= 0:
        return 0.0
    return max(0.0, min(1.0, timer / eff_duration))


def create_smasher_paddle_surface(step_phase: float = 0.0) -> pygame.Surface:
    """구형 절차적 스매셔 렌더링 — 정적 이미지 전용 (카드, 미리보기, 스킬 UI).
    실시간 인게임 렌더링은 _render_skeletal_smasher() 사용."""
    surface = pygame.Surface((250, 120), pygame.SRCALPHA)
    block = 9
    center_x = surface.get_width() // 2
    torso_base_y = 56

    global smasher_hit_pose_timer, smasher_shield_raise_timer, smasher_left_raise_timer

    _si = smasher_swing_intensity
    hit_pose_ratio = _smasher_hit_ratio(smasher_hit_pose_timer, SMASHER_HIT_POSE_DURATION, _si)
    shield_raise_strength = _smasher_bell_strength(smasher_shield_raise_timer, SMASHER_SHIELD_RAISE_DURATION, _si)
    left_raise_strength = _smasher_bell_strength(smasher_left_raise_timer, SMASHER_LEFT_RAISE_DURATION, _si)

    rotate_point = _smasher_rotate_point
    lerp_point = _smasher_lerp_point
    to_int_point = _smasher_to_int
    regular_polygon_points = _smasher_regular_polygon

    phase = _resolve_mecha_phase(step_phase)
    wave = math.sin(phase * math.tau)
    torso_bob = int(math.sin(phase * math.tau) * 2)
    arm_swing = int(wave * 5)
    shoulder_shift = int(wave * 2)
    hip_sway = int(wave * 2)
    left_leg_lift = -int(max(0.0, wave) * 4)
    right_leg_lift = -int(max(0.0, -wave) * 4)

    torso_y = torso_base_y + torso_bob

    palette = {
        "shadow": (0, 0, 0, 64),
        "helmet": (70, 102, 162),
        "helmet_side": (58, 82, 136),
        "helmet_high": (148, 182, 236),
        "face": (212, 196, 176),
        "visor": (170, 224, 255),
        "visor_core": (126, 192, 246),
        "armor_outer": (80, 96, 150),
        "armor_mid": (60, 76, 120),
        "armor_inner": (46, 58, 92),
        "trim": (190, 206, 236),
        "accent": (118, 214, 255),
        "accent_core": (82, 178, 248),
        "undersuit": (36, 40, 58),
        "undersuit_dark": (22, 26, 40),
        "arm_light": (132, 152, 204),
        "glove": (198, 182, 164),
        "glove_detail": (156, 134, 110),
        "paddle": (220, 56, 74),
        "paddle_core": (244, 116, 132),
        "paddle_shadow": (154, 42, 58),
        "handle": (174, 132, 98),
        "handle_core": (206, 166, 128),
        "belt": (88, 78, 108),
        "belt_glint": (158, 140, 196),
        "boot": (64, 74, 110),
        "boot_high": (128, 146, 190),
        "knee": (96, 118, 176),
        "outline": (20, 24, 36),
        "board_base": (58, 72, 118),
        "board_shadow": (34, 40, 68),
        "board_highlight": (142, 182, 242),
        "board_glow": (100, 198, 255),
        "thruster_core": (255, 234, 170),
        "thruster_glow": (118, 214, 255),
        "thruster_heat": (254, 156, 94),
        "shield_core": (200, 252, 255),
        "shield_ring": (120, 210, 255),
        "shield_glow": (70, 160, 255),
    }

    helmet_w = int(2.7 * block)
    helmet_h = int(2.2 * block)
    helmet_rect = pygame.Rect(center_x - helmet_w // 2, torso_y - int(3.1 * block), helmet_w, helmet_h)
    pygame.draw.ellipse(surface, palette["helmet"], helmet_rect)

    side_mod = pygame.Rect(helmet_rect.left - int(0.6 * block), helmet_rect.centery - int(0.6 * block),
                           int(0.8 * block), int(1.4 * block))
    pygame.draw.ellipse(surface, palette["helmet_side"], side_mod)
    side_mod_right = side_mod.move(helmet_rect.width + int(0.4 * block), shoulder_shift // 2)
    pygame.draw.ellipse(surface, palette["helmet_side"], side_mod_right)

    face_rect = helmet_rect.inflate(-int(0.95 * block), -int(0.85 * block))
    face_rect.move_ip(0, int(0.65 * block))
    pygame.draw.ellipse(surface, palette["face"], face_rect)

    visor_rect = face_rect.inflate(int(0.2 * block), int(-0.35 * block))
    pygame.draw.ellipse(surface, palette["visor"], visor_rect)
    pygame.draw.ellipse(surface, palette["visor_core"], visor_rect.inflate(-int(0.55 * block), -int(0.4 * block)))
    pygame.draw.line(surface, palette["helmet_high"],
                     (visor_rect.left + 1, visor_rect.centery - 1),
                     (visor_rect.right - 1, visor_rect.centery - 1), 1)

    helmet_high = helmet_rect.inflate(-int(1.3 * block), -int(1.2 * block))
    helmet_high.move_ip(-1, -1)
    pygame.draw.ellipse(surface, palette["helmet_high"], helmet_high, 1)

    ridge_rect = pygame.Rect(center_x - int(0.25 * block), helmet_rect.top + int(0.2 * block),
                             int(0.5 * block), helmet_rect.height - int(0.5 * block))
    pygame.draw.rect(surface, palette["helmet_high"], ridge_rect, border_radius=2)

    torso_width = int(3.4 * block)
    chest_height = int(2.2 * block)
    chest_rect = pygame.Rect(center_x - torso_width // 2, torso_y - int(0.4 * block), torso_width, chest_height)
    pygame.draw.rect(surface, palette["armor_outer"], chest_rect, border_radius=7)

    mid_rect = chest_rect.inflate(-int(0.6 * block), -int(0.5 * block))
    pygame.draw.rect(surface, palette["armor_mid"], mid_rect, border_radius=6)

    inner_panel = mid_rect.inflate(-int(0.7 * block), -int(0.45 * block))
    pygame.draw.rect(surface, palette["armor_inner"], inner_panel, border_radius=4)

    pygame.draw.rect(surface, palette["trim"], chest_rect, 1, border_radius=7)
    pygame.draw.rect(surface, palette["trim"], mid_rect, 1, border_radius=6)

    core_line_top = (center_x, inner_panel.top + int(0.25 * block))
    core_line_bottom = (center_x, inner_panel.bottom - int(0.25 * block))
    pygame.draw.line(surface, palette["accent"], core_line_top, core_line_bottom, 2)
    pygame.draw.line(surface, palette["accent_core"],
                     (center_x - int(0.5 * block), inner_panel.centery),
                     (center_x + int(0.5 * block), inner_panel.centery), 1)

    abs_width = int(2.4 * block)
    abs_height = int(1.4 * block)
    abs_rect = pygame.Rect(center_x - abs_width // 2, inner_panel.bottom - int(0.2 * block), abs_width, abs_height)
    pygame.draw.rect(surface, palette["undersuit"], abs_rect, border_radius=3)
    pygame.draw.rect(surface, palette["trim"], abs_rect, 1, border_radius=3)
    pygame.draw.line(surface, palette["accent_core"],
                     (abs_rect.left + 2, abs_rect.centery), (abs_rect.right - 2, abs_rect.centery), 1)

    belt_rect = pygame.Rect(center_x - int(2.0 * block), abs_rect.bottom - int(0.1 * block), int(4.0 * block), int(0.8 * block))
    pygame.draw.rect(surface, palette["belt"], belt_rect, border_radius=2)
    pygame.draw.line(surface, palette["belt_glint"],
                     (belt_rect.left + 4, belt_rect.centery - 1),
                     (belt_rect.right - 4, belt_rect.centery - 1), 1)
    buckle_rect = pygame.Rect(center_x - int(0.6 * block), belt_rect.top + 1, int(1.2 * block), belt_rect.height - 2)
    pygame.draw.rect(surface, palette["trim"], buckle_rect, border_radius=1)

    left_pauldron = [
        (center_x - int(2.2 * block) - 4, torso_y + shoulder_shift - int(0.5 * block)),
        (center_x - int(1.2 * block), torso_y - int(0.9 * block)),
        (center_x - int(0.9 * block), torso_y + int(0.8 * block)),
        (center_x - int(2.1 * block) - 3, torso_y + int(0.9 * block)),
    ]
    pygame.draw.polygon(surface, palette["armor_mid"], left_pauldron)
    pygame.draw.line(surface, palette["trim"], left_pauldron[0], left_pauldron[1], 2)
    pygame.draw.line(surface, palette["arm_light"], left_pauldron[1], left_pauldron[2], 1)

    right_pauldron = [
        (center_x + int(2.2 * block) + 4, torso_y - shoulder_shift - int(0.5 * block)),
        (center_x + int(1.2 * block), torso_y - int(0.9 * block)),
        (center_x + int(0.9 * block), torso_y + int(0.8 * block)),
        (center_x + int(2.1 * block) + 3, torso_y + int(0.9 * block)),
    ]
    pygame.draw.polygon(surface, palette["armor_mid"], right_pauldron)
    pygame.draw.line(surface, palette["trim"], right_pauldron[0], right_pauldron[1], 2)
    pygame.draw.line(surface, palette["arm_light"], right_pauldron[1], right_pauldron[2], 1)

    left_shoulder = (center_x - int(1.8 * block), torso_y + shoulder_shift)
    left_arm_swing = int(arm_swing * (1 - 0.55 * hit_pose_ratio) * (1 - 0.7 * left_raise_strength))
    default_left_elbow = (
        left_shoulder[0] - int(1.05 * block) - left_arm_swing + int(left_raise_strength * 0.35 * block),
        torso_y + int(0.05 * block) - left_arm_swing // 2 - int(left_raise_strength * 0.4 * block),
    )
    default_left_wrist = (
        default_left_elbow[0] - int(0.9 * block) + int(left_raise_strength * 0.45 * block),
        torso_y - int(0.45 * block) - int(left_arm_swing * 0.5) - int(left_raise_strength * 1.2 * block),
    )

    left_elbow_point = (float(default_left_elbow[0]), float(default_left_elbow[1]))
    left_wrist_point = (float(default_left_wrist[0]), float(default_left_wrist[1]))

    if hit_pose_ratio > 0:
        rotated_elbow = rotate_point(left_shoulder, left_elbow_point, 55.0)
        rotated_wrist_base = rotate_point(left_elbow_point, left_wrist_point, 38.0)
        elbow_delta = (
            rotated_elbow[0] - left_elbow_point[0],
            rotated_elbow[1] - left_elbow_point[1],
        )
        rotated_wrist = (
            rotated_wrist_base[0] + elbow_delta[0],
            rotated_wrist_base[1] + elbow_delta[1] + block * 0.15,
        )
        left_elbow_point = lerp_point(left_elbow_point, rotated_elbow, hit_pose_ratio)
        left_wrist_point = lerp_point(left_wrist_point, rotated_wrist, hit_pose_ratio)

    if left_raise_strength > 0:
        lifted_elbow = rotate_point(left_shoulder, left_elbow_point, 78.0)
        lifted_elbow = (
            lifted_elbow[0] + left_raise_strength * 0.55 * block,
            lifted_elbow[1] - left_raise_strength * 1.3 * block,
        )
        lifted_wrist_base = rotate_point(left_elbow_point, left_wrist_point, 92.0)
        lifted_wrist = (
            lifted_wrist_base[0] + left_raise_strength * 0.65 * block,
            lifted_wrist_base[1] - left_raise_strength * 1.8 * block,
        )
        left_elbow_point = lerp_point(left_elbow_point, lifted_elbow, left_raise_strength)
        left_wrist_point = lerp_point(left_wrist_point, lifted_wrist, left_raise_strength)

    left_elbow = to_int_point(left_elbow_point)
    left_wrist = to_int_point(left_wrist_point)

    pygame.draw.line(surface, palette["arm_light"], left_shoulder, left_elbow, block)
    pygame.draw.line(surface, palette["armor_mid"], left_shoulder, left_elbow, block - 2)
    pygame.draw.line(surface, palette["arm_light"], left_elbow, left_wrist, block - 1)
    pygame.draw.line(surface, palette["armor_mid"], left_elbow, left_wrist, block - 3)
    pygame.draw.circle(surface, palette["glove"], left_wrist, max(2, block // 2 + 1))
    pygame.draw.line(surface, palette["glove_detail"],
                     (left_wrist[0] - 2, left_wrist[1] - 1),
                     (left_wrist[0] + 2, left_wrist[1] + 2), 1)

    handle_rect = pygame.Rect(left_wrist[0] - block // 2,
                              left_wrist[1] - int(1.3 * block),
                              int(0.9 * block), int(1.6 * block))
    pygame.draw.rect(surface, palette["handle"], handle_rect)
    pygame.draw.rect(surface, palette["handle_core"], handle_rect.inflate(-max(1, block // 3), -max(1, block // 3)))

    paddle_center = (handle_rect.centerx - int(1.2 * block), handle_rect.top - int(0.4 * block))
    paddle_radius = int(1.7 * block)
    pygame.draw.circle(surface, palette["paddle"], paddle_center, paddle_radius)
    pygame.draw.circle(surface, palette["paddle_core"], paddle_center, max(2, paddle_radius - 3))
    paddle_box = pygame.Rect(paddle_center[0] - paddle_radius, paddle_center[1] - paddle_radius,
                             paddle_radius * 2, paddle_radius * 2)
    pygame.draw.arc(surface, palette["paddle_shadow"], paddle_box, math.radians(200), math.radians(320), 3)

    paddle_glow = pygame.Surface((paddle_radius * 2, paddle_radius * 2), pygame.SRCALPHA)
    pygame.draw.circle(paddle_glow, (*palette["paddle_core"], 40),
                       (paddle_radius, paddle_radius), paddle_radius)
    surface.blit(paddle_glow, (paddle_box.left, paddle_box.top), special_flags=pygame.BLEND_RGBA_ADD)

    right_shoulder = (center_x + int(1.8 * block), torso_y - shoulder_shift)
    right_arm_swing = int(arm_swing * (1 - 0.7 * shield_raise_strength))
    base_right_elbow = (
        right_shoulder[0] + int(1.2 * block) + right_arm_swing,
        torso_y + int(0.35 * block) + right_arm_swing // 2 - int(shield_raise_strength * 0.4 * block),
    )
    base_right_wrist = (
        base_right_elbow[0] + int(1.0 * block),
        torso_y + int(1.05 * block) + right_leg_lift // 2 - int(shield_raise_strength * 1.1 * block),
    )

    right_elbow_point = (float(base_right_elbow[0]), float(base_right_elbow[1]))
    right_wrist_point = (float(base_right_wrist[0]), float(base_right_wrist[1]))

    if shield_raise_strength > 0:
        lifted_elbow = rotate_point(right_shoulder, right_elbow_point, -62.0)
        lifted_elbow = (
            lifted_elbow[0] - shield_raise_strength * 0.2 * block,
            lifted_elbow[1] - shield_raise_strength * 0.8 * block,
        )
        lifted_wrist_base = rotate_point(right_elbow_point, right_wrist_point, -85.0)
        lifted_wrist = (
            lifted_wrist_base[0] - shield_raise_strength * 0.15 * block,
            lifted_wrist_base[1] - shield_raise_strength * 1.7 * block,
        )
        right_elbow_point = lerp_point(right_elbow_point, lifted_elbow, shield_raise_strength)
        right_wrist_point = lerp_point(right_wrist_point, lifted_wrist, shield_raise_strength)

    right_elbow = to_int_point(right_elbow_point)
    right_wrist = to_int_point(right_wrist_point)

    pygame.draw.line(surface, palette["arm_light"], right_shoulder, right_elbow, block)
    pygame.draw.line(surface, palette["armor_mid"], right_shoulder, right_elbow, block - 2)
    pygame.draw.line(surface, palette["arm_light"], right_elbow, right_wrist, block - 1)
    pygame.draw.line(surface, palette["armor_mid"], right_elbow, right_wrist, block - 3)
    pygame.draw.circle(surface, palette["glove"], right_wrist, max(2, block // 2 + 1))
    pygame.draw.line(surface, palette["glove_detail"],
                     (right_wrist[0] - 2, right_wrist[1]),
                     (right_wrist[0] + 2, right_wrist[1] + 2), 1)

    shield_radius = max(9, int(1.7 * block))
    shield_surface = pygame.Surface((shield_radius * 2, shield_radius * 2), pygame.SRCALPHA)
    shield_center = (shield_radius, shield_radius)

    layer_specs = (
        (1.05, 70),
        (0.85, 110),
        (0.65, 150),
        (0.45, 190),
    )
    for scale, alpha in layer_specs:
        points = [to_int_point(p) for p in regular_polygon_points(shield_center, shield_radius * scale)]
        glow_color = (
            palette["shield_glow"][0],
            palette["shield_glow"][1],
            palette["shield_glow"][2],
            min(255, alpha),
        )
        pygame.draw.polygon(shield_surface, glow_color, points)

    outline_points = [to_int_point(p) for p in regular_polygon_points(shield_center, shield_radius * 1.05)]
    pygame.draw.polygon(
        shield_surface,
        (
            palette["shield_ring"][0],
            palette["shield_ring"][1],
            palette["shield_ring"][2],
            230,
        ),
        outline_points,
        width=3,
    )

    core_points = [to_int_point(p) for p in regular_polygon_points(shield_center, shield_radius * 0.38)]
    pygame.draw.polygon(
        shield_surface,
        (
            palette["shield_core"][0],
            palette["shield_core"][1],
            palette["shield_core"][2],
            240,
        ),
        core_points,
    )

    highlight_points = [to_int_point(p) for p in regular_polygon_points(shield_center, shield_radius * 0.9)]
    pygame.draw.lines(
        shield_surface,
        (
            palette["shield_core"][0],
            palette["shield_core"][1],
            palette["shield_core"][2],
            120,
        ),
        True,
        highlight_points,
        1,
    )

    shield_offset = (
        int((0.45 + 0.25 * shield_raise_strength) * block),
        -int((0.15 + 1.05 * shield_raise_strength) * block),
    )
    shield_pos = (
        right_wrist[0] - shield_radius + shield_offset[0],
        right_wrist[1] - shield_radius + shield_offset[1],
    )
    surface.blit(shield_surface, shield_pos)
    surface.blit(shield_surface, shield_pos, special_flags=pygame.BLEND_ADD)

    hip_y = torso_y + int(1.1 * block)
    pelvis = pygame.Rect(center_x - int(1.5 * block) + hip_sway // 2, hip_y - int(0.4 * block), int(3.0 * block), int(1.0 * block))
    pygame.draw.rect(surface, palette["armor_mid"], pelvis, border_radius=3)
    pygame.draw.rect(surface, palette["trim"], pelvis, 1, border_radius=3)

    thigh_height = int(2.2 * block)
    thigh_width = int(0.9 * block)
    left_thigh = pygame.Rect(center_x - int(1.2 * block) - thigh_width, hip_y + left_leg_lift, thigh_width, thigh_height)
    right_thigh = pygame.Rect(center_x + int(0.25 * block), hip_y + right_leg_lift, thigh_width, thigh_height)
    pygame.draw.rect(surface, palette["undersuit"], left_thigh, border_radius=3)
    pygame.draw.rect(surface, palette["undersuit"], right_thigh, border_radius=3)
    pygame.draw.rect(surface, palette["undersuit_dark"], left_thigh.inflate(-2, -2), border_radius=3)
    pygame.draw.rect(surface, palette["undersuit_dark"], right_thigh.inflate(-2, -2), border_radius=3)

    knee_pad_left = pygame.Rect(left_thigh.left - 2, left_thigh.top + int(1.2 * block), thigh_width + 4, int(0.8 * block))
    knee_pad_right = pygame.Rect(right_thigh.left - 2, right_thigh.top + int(1.2 * block), thigh_width + 4, int(0.8 * block))
    pygame.draw.rect(surface, palette["knee"], knee_pad_left, border_radius=2)
    pygame.draw.rect(surface, palette["knee"], knee_pad_right, border_radius=2)
    pygame.draw.line(surface, palette["trim"],
                     (knee_pad_left.left + 1, knee_pad_left.centery),
                     (knee_pad_left.right - 1, knee_pad_left.centery), 1)
    pygame.draw.line(surface, palette["trim"],
                     (knee_pad_right.left + 1, knee_pad_right.centery),
                     (knee_pad_right.right - 1, knee_pad_right.centery), 1)

    calf_height = int(1.1 * block)
    left_calf = pygame.Rect(left_thigh.left - 2, left_thigh.bottom - 4, left_thigh.width + 4, calf_height)
    right_calf = pygame.Rect(right_thigh.left - 2, right_thigh.bottom - 4, right_thigh.width + 4, calf_height)
    pygame.draw.rect(surface, palette["boot"], left_calf, border_radius=2)
    pygame.draw.rect(surface, palette["boot"], right_calf, border_radius=2)
    pygame.draw.line(surface, palette["boot_high"],
                     (left_calf.left + 2, left_calf.centery - 1),
                     (left_calf.right - 2, left_calf.centery - 1), 1)
    pygame.draw.line(surface, palette["boot_high"],
                     (right_calf.left + 2, right_calf.centery - 1),
                     (right_calf.right - 2, right_calf.centery - 1), 1)

    thruster_height = int(1.5 * block)
    thruster_width = int(1.6 * block)
    sway_offset = int(hip_sway * 0.3)

    board_length = int(7.6 * block)
    board_thickness = max(4, int(0.62 * block))
    board_y = max(left_calf.bottom, right_calf.bottom) - int(0.25 * block)
    board_rect = pygame.Rect(center_x - board_length // 2 - sway_offset, board_y, board_length, board_thickness)

    nose_length = int(1.4 * block)
    tail_length = int(1.4 * block)

    board_shadow_poly = [
        (board_rect.left - nose_length // 2, board_rect.bottom + 2),
        (board_rect.left + nose_length, board_rect.top - 1),
        (board_rect.right - tail_length, board_rect.top - 1),
        (board_rect.right + tail_length // 2, board_rect.bottom + 2),
    ]
    pygame.draw.polygon(surface, (*palette["board_shadow"], 110), board_shadow_poly)

    board_poly = [
        (board_rect.left - nose_length, board_rect.centery + board_thickness // 2),
        (board_rect.left + nose_length // 2, board_rect.top),
        (board_rect.right - tail_length // 2, board_rect.top),
        (board_rect.right + tail_length, board_rect.centery + board_thickness // 2),
        (board_rect.right - tail_length // 2, board_rect.bottom),
        (board_rect.left + nose_length // 2, board_rect.bottom),
    ]
    pygame.draw.polygon(surface, palette["board_base"], board_poly)

    deck_poly = [
        (board_rect.left - nose_length // 2, board_rect.centery + board_thickness // 3),
        (board_rect.left + nose_length // 2, board_rect.top + board_thickness // 4),
        (board_rect.right - tail_length // 2, board_rect.top + board_thickness // 4),
        (board_rect.right + tail_length // 2, board_rect.centery + board_thickness // 3),
        (board_rect.right - tail_length // 2, board_rect.bottom - board_thickness // 4),
        (board_rect.left + nose_length // 2, board_rect.bottom - board_thickness // 4),
    ]
    pygame.draw.polygon(surface, palette["board_highlight"], deck_poly)

    routing_length = board_rect.width - nose_length - tail_length
    routing_start = board_rect.left + nose_length
    for offset, color in ((0, palette["board_highlight"]), (board_thickness // 2, palette["board_shadow"])):
        pygame.draw.line(surface, color,
                         (routing_start, board_rect.top + board_thickness // 2 - offset),
                         (routing_start + routing_length, board_rect.top + board_thickness // 2 - offset), 2)

    board_glow_surface = pygame.Surface((board_length + int(1.6 * block), thruster_height * 2), pygame.SRCALPHA)
    pygame.draw.ellipse(board_glow_surface, (*palette["board_glow"], 60), board_glow_surface.get_rect())
    surface.blit(board_glow_surface,
                 (board_rect.left - int(0.8 * block) - nose_length // 2,
                  board_rect.bottom - board_glow_surface.get_height() // 2),
                 special_flags=pygame.BLEND_ADD)

    def draw_thruster(column_rect: pygame.Rect, strength: float, horizontal_bias: int, phase_offset: float):
        base_x = column_rect.centerx + horizontal_bias
        base_y = board_rect.bottom
        flicker = 0.6 + 0.4 * math.sin(phase * math.tau * 2.0 + phase_offset)
        intensity = max(0.25, min(1.0, strength * 0.6 + flicker * 0.4))

        flame_length = int(thruster_height * (1.6 + intensity))
        flame_width = int(thruster_width * (0.9 + 0.3 * intensity))
        flame_surface = pygame.Surface((flame_width * 2, flame_length + thruster_height), pygame.SRCALPHA)

        nozzle_center_x = flame_width
        nozzle_center_y = thruster_height // 2
        nozzle_rect = pygame.Rect(nozzle_center_x - thruster_width // 2,
                                  nozzle_center_y - thruster_height // 2,
                                  thruster_width,
                                  thruster_height)

        pygame.draw.ellipse(flame_surface, (*palette["board_glow"], int(120 * intensity)),
                            nozzle_rect.inflate(int(0.5 * block), int(0.3 * block)))
        pygame.draw.ellipse(flame_surface, (*palette["thruster_heat"], int(160 * intensity)), nozzle_rect)
        pygame.draw.ellipse(flame_surface, palette["thruster_core"],
                            nozzle_rect.inflate(-max(1, thruster_width // 3), -max(1, thruster_height // 3)))

        crest = int(math.sin(phase * math.tau * 4.0 + phase_offset) * flame_width * 0.25)
        outer_points = [
            (nozzle_center_x - flame_width + 2, nozzle_rect.bottom - 1),
            (nozzle_center_x + crest, nozzle_rect.bottom - 1 + flame_length),
            (nozzle_center_x + flame_width - 2, nozzle_rect.bottom - 1),
        ]
        pygame.draw.polygon(flame_surface, (*palette["thruster_heat"], int(180 * intensity)), outer_points)

        inner_points = [
            (nozzle_center_x - flame_width // 2, nozzle_rect.bottom + flame_length // 3),
            (nozzle_center_x + crest // 2, nozzle_rect.bottom - 1 + flame_length - flame_length // 4),
            (nozzle_center_x + flame_width // 2, nozzle_rect.bottom + flame_length // 3),
        ]
        pygame.draw.polygon(flame_surface, (*palette["thruster_glow"], int(160 * intensity)), inner_points)

        surface.blit(flame_surface, (base_x - flame_width, base_y - thruster_height // 2), special_flags=pygame.BLEND_ADD)

    movement = min(1.0, abs(wave))
    base_strength = 0.25 + 0.35 * movement
    left_strength = min(1.0, base_strength + 0.4 * max(0.0, -wave))
    right_strength = min(1.0, base_strength + 0.4 * max(0.0, wave))

    draw_thruster(left_calf, left_strength, -sway_offset - int(0.4 * block), 0.0)
    draw_thruster(right_calf, right_strength, -sway_offset + int(0.4 * block), math.pi)

    outline = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
    pygame.draw.ellipse(outline, palette["outline"], helmet_rect, 1)
    pygame.draw.rect(outline, palette["outline"], chest_rect.inflate(2, 2), 1, border_radius=7)
    pygame.draw.rect(outline, palette["outline"], pelvis.inflate(2, 2), 1, border_radius=3)
    pygame.draw.rect(
        outline,
        palette["outline"],
        board_rect.inflate(2, 2),
        1,
        border_radius=board_thickness,
    )
    surface.blit(outline, (0, 0))

    return surface


# ========== 바이퍼 절차적 렌더링 (사이버 어쌔신) ==========

# === 바이퍼 타격 모션 변수 (왼팔 슬래시 / 오른발 킥) ===
VIPER_HIT_POSE_DURATION = 8            # 타격 자세 유지 프레임
VIPER_LEFT_SLASH_DURATION = 18         # 왼팔 슬래시 애니메이션 프레임
VIPER_RIGHT_KICK_DURATION = 18         # 오른발 킥 애니메이션 프레임
viper_hit_pose_timer = 0               # 타격 자세 타이머
viper_left_slash_timer = 0             # 왼팔 슬래시 타이머
viper_right_kick_timer = 0             # 오른발 킥 타이머
viper_swing_intensity = 1.0            # 타격 강도 (1.0=일반)


def create_viper_paddle_surface(step_phase: float = 0.0, kick_direction: int = 0, wall_cling: int = 0, flying_kick: int = 0, flying_kick_intensity: float = 1.0) -> pygame.Surface:
    """절차적 바이퍼 렌더링 — 고퀄리티 어쌔신 실루엣.
    다중 레이어 셰이딩, 후드 그림자, 에너지 도관, 블레이드 파티클, 다단계 스카프.
    kick_direction: 0=일반, -1=왼쪽 발차기, 1=오른쪽 발차기 (쉐도우 백스텝용)
    wall_cling: 0=일반, -1=왼쪽벽 매달림, 1=오른쪽벽 매달림 (마샬 킥 벽타기 포즈)
    flying_kick: 0=일반, -1=왼쪽으로 날라차기, 1=오른쪽으로 날라차기 (마샬 킥 돌진 포즈)
    flying_kick_intensity: 0.0~1.0 날라차기 강도 (1.0=최대, 낙하 시 서서히 0으로)"""
    surface = pygame.Surface((250, 120), pygame.SRCALPHA)
    b = 8
    cx = surface.get_width() // 2
    base_y = 46

    phase = step_phase % 1.0 if step_phase else 0.0
    wave = math.sin(phase * math.tau)
    abs_wave = abs(wave)

    # ═══ 아이들 숨쉬기 모션 (phase=0: 가만히 서 있을 때) ═══
    is_idle = (phase == 0.0 and kick_direction == 0 and wall_cling == 0 and flying_kick == 0)
    if is_idle:
        _t = pygame.time.get_ticks()
        # 메인 호흡 (느린 주기 ~1.6초)
        breath = math.sin(_t * 0.004)
        # 2차 흔들림 (비대칭 주기 ~1초, 위상 어긋남)
        sway = math.sin(_t * 0.006 + 0.5)
        torso_bob = int(breath * 1.2)
        arm_swing = int(breath * 2 + sway * 1)
        shoulder_tilt = int(sway * 1.5)
        lean_forward = int(breath * 0.6)
        left_leg_step = int(sway * 1.0)
        right_leg_step = int(-sway * 1.0)
        left_leg_lift = int(breath * 0.4)
        right_leg_lift = int(-breath * 0.4)
    else:
        torso_bob = int(abs_wave * 1.5)
        arm_swing = int(wave * 6)
        shoulder_tilt = int(wave * 2)
        lean_forward = int(abs_wave * 1.5)  # 걸을 때 약간 앞으로 기울기
        left_leg_step = int(wave * 12)   # 다리 앞뒤 교차 폭 확대 (6→12)
        right_leg_step = -left_leg_step
        left_leg_lift = -int(max(0.0, wave) * 6)   # 다리 들어올림 확대 (3→6)
        right_leg_lift = -int(max(0.0, -wave) * 6)

    # 🦵 마샬 킥 날라차기 포즈: 이소룡 스타일 플라잉 킥
    if flying_kick != 0:
        _fk = flying_kick  # 돌진 방향 (-1=왼, 1=오른)
        _fi = max(0.0, min(1.0, flying_kick_intensity))  # 강도 (1.0=최대, 0.0=일반)
        torso_bob = 0
        arm_swing = 0
        lean_forward = int(-2 * _fi)  # 몸을 살짝 뒤로 젖힘 (날라차기 역동성)
        shoulder_tilt = int(-_fk * 5 * _fi)  # 킥 반대방향으로 기울기 (역동적)
        # 앞 다리: 킥 방향으로 쭉 뻗음 (높이 차올림) - intensity로 보간
        if _fk > 0:
            right_leg_step = int(34 * _fi)
            right_leg_lift = int(-22 * _fi)
            left_leg_step = int(-16 * _fi)
            left_leg_lift = int(4 * _fi)
        else:
            left_leg_step = int(-34 * _fi)
            left_leg_lift = int(-22 * _fi)
            right_leg_step = int(16 * _fi)
            right_leg_lift = int(4 * _fi)

    # 🕷 마샬 킥 벽타기 포즈: 스파이더맨 스타일 웅크린 자세
    elif wall_cling != 0:
        torso_bob = 0
        arm_swing = 0
        lean_forward = 3  # 벽 쪽으로 약간 기울임
        shoulder_tilt = int(wall_cling * 4)  # 벽 쪽 어깨 올림
        # 벽 쪽 다리: 무릎 깊게 구부려 벽에 발 붙임 (위쪽)
        # 바깥쪽 다리: 아래로 뻗어 자연스럽게 (스파이더맨 포즈)
        if wall_cling < 0:
            # 왼쪽 벽: 왼쪽 다리=벽에 붙임(무릎 굽힘), 오른쪽=아래로 뻗음
            left_leg_step = -22   # 벽 쪽으로 접힘
            left_leg_lift = -14   # 위로 올림 (벽에 발 붙이기)
            right_leg_step = 18   # 바깥으로 뻗음
            right_leg_lift = 6    # 아래로 늘어뜨림
        else:
            # 오른쪽 벽: 오른쪽 다리=벽에 붙임, 왼쪽=아래로 뻗음
            right_leg_step = 22
            right_leg_lift = -14
            left_leg_step = -18
            left_leg_lift = 6

    # 쉐도우 백스텝 발차기 포즈: 한쪽 다리를 높이 옆으로 뻗음
    elif kick_direction != 0:
        torso_bob = 0
        arm_swing = 0
        shoulder_tilt = int(-kick_direction * 3)  # 킥 반대쪽으로 몸 기울기
        lean_forward = 0
        if kick_direction < 0:
            # 왼쪽 킥: 왼쪽 다리를 왼쪽 위로 높이 뻗음
            left_leg_step = -28   # 왼쪽으로 크게 뻗음
            left_leg_lift = -18   # 높이 올림 (태권도 옆차기)
            right_leg_step = 4    # 축발은 약간 안정
            right_leg_lift = 0
        else:
            # 오른쪽 킥: 오른쪽 다리를 오른쪽 위로 높이 뻗음
            right_leg_step = 28
            right_leg_lift = -18
            left_leg_step = -4
            left_leg_lift = 0

    # === 타격 모션: 왼팔 슬래시 / 오른발 킥 (벨 커브 0→1→0) ===
    _vsi = viper_swing_intensity
    # 왼팔 슬래시 강도 (bell curve)
    _ls_eff = max(1, int(VIPER_LEFT_SLASH_DURATION * _vsi))
    if _ls_eff > 0 and viper_left_slash_timer > 0:
        _ls_norm = 1.0 - (viper_left_slash_timer / _ls_eff)
        _ls_norm = max(0.0, min(1.0, _ls_norm))
        left_slash_strength = (_ls_norm * 2.0 if _ls_norm < 0.5 else (1.0 - _ls_norm) * 2.0)
        left_slash_strength = max(0.0, min(1.0, left_slash_strength ** 0.6))
    else:
        left_slash_strength = 0.0
    # 오른발 킥 강도 (bell curve)
    _rk_eff = max(1, int(VIPER_RIGHT_KICK_DURATION * _vsi))
    if _rk_eff > 0 and viper_right_kick_timer > 0:
        _rk_norm = 1.0 - (viper_right_kick_timer / _rk_eff)
        _rk_norm = max(0.0, min(1.0, _rk_norm))
        right_kick_strength = (_rk_norm * 2.0 if _rk_norm < 0.5 else (1.0 - _rk_norm) * 2.0)
        right_kick_strength = max(0.0, min(1.0, right_kick_strength ** 0.6))
    else:
        right_kick_strength = 0.0
    # 히트 포즈 비율 (선형 감소)
    _hp_eff = max(1, int(VIPER_HIT_POSE_DURATION * _vsi))
    viper_hit_ratio = max(0.0, min(1.0, viper_hit_pose_timer / _hp_eff)) if viper_hit_pose_timer > 0 else 0.0

    # 타격 모션 중 걷기 동작 억제
    if left_slash_strength > 0 or right_kick_strength > 0:
        arm_swing = int(arm_swing * (1.0 - max(left_slash_strength, right_kick_strength) * 0.7))
        shoulder_tilt = int(shoulder_tilt * (1.0 - max(left_slash_strength, right_kick_strength) * 0.5))

    # 오른발 킥 모션: 오른다리를 높이 차올리며 킥 (쉐도우 백스텝 킥과 별개)
    if right_kick_strength > 0 and kick_direction == 0:
        right_leg_step = int(right_leg_step * (1.0 - right_kick_strength) + 32 * right_kick_strength)
        right_leg_lift = int(right_leg_lift * (1.0 - right_kick_strength) + (-26) * right_kick_strength)
        # 축발(왼다리)은 뒤로 버티기
        left_leg_step = int(left_leg_step * (1.0 - right_kick_strength) + (-10) * right_kick_strength)
        left_leg_lift = int(left_leg_lift * (1.0 - right_kick_strength) + 2 * right_kick_strength)
        # 킥 시 몸을 왼쪽으로 기울여 역동적 자세
        shoulder_tilt += int(right_kick_strength * 5)
        # 킥 시 상체를 살짝 뒤로 젖힘
        lean_forward -= int(right_kick_strength * 2)

    ty = base_y + torso_bob

    # -- 고급 컬러 팔레트 --
    p = {
        # 후드
        "hood_dark": (28, 5, 45),
        "hood_mid": (38, 10, 60),
        "hood_light": (55, 20, 85),
        "hood_rim": (90, 35, 135),
        "hood_shadow": (15, 3, 25, 180),
        # 바이저
        "visor": (0, 255, 180),
        "visor_bright": (100, 255, 220),
        "visor_dark": (0, 160, 120),
        "visor_glow": (0, 255, 200, 70),
        # 슈트 (3단계 셰이딩)
        "suit_shadow": (15, 4, 28),
        "suit_main": (25, 8, 42),
        "suit_light": (38, 14, 60),
        "suit_highlight": (50, 20, 78),
        "suit_seam": (65, 28, 100),
        # 아머 플레이트
        "armor_dark": (32, 12, 52),
        "armor_mid": (45, 18, 72),
        "armor_light": (60, 25, 95),
        "armor_edge": (75, 32, 115),
        # 네온
        "neon": (0, 255, 180),
        "neon_bright": (120, 255, 220),
        "neon_dim": (0, 140, 100),
        "neon_purple": (160, 0, 255),
        "neon_purple_dim": (100, 0, 170),
        # 에너지 도관
        "conduit": (0, 200, 150, 120),
        "conduit_core": (0, 255, 200, 200),
        # 팔
        "arm_shadow": (22, 7, 38),
        "arm_mid": (35, 14, 55),
        "arm_light": (50, 22, 78),
        "wrap_dark": (16, 4, 28),
        "wrap_light": (28, 10, 45),
        # 장갑
        "glove_dark": (18, 6, 32),
        "glove_mid": (30, 12, 48),
        "glove_accent": (0, 220, 170),
        # 블레이드
        "blade_outer": (0, 200, 160),
        "blade_mid": (0, 255, 200),
        "blade_core": (180, 255, 240),
        "blade_white": (220, 255, 250),
        "blade_glow": (0, 200, 160, 45),
        "blade_particle": (0, 255, 200, 150),
        # 하체
        "leg_shadow": (14, 4, 26),
        "leg_mid": (24, 8, 40),
        "leg_light": (36, 14, 56),
        "knee_dark": (40, 16, 65),
        "knee_mid": (55, 24, 85),
        "knee_accent": (0, 220, 170),
        # 부츠
        "boot_dark": (20, 7, 35),
        "boot_mid": (32, 13, 52),
        "boot_light": (45, 20, 70),
        "boot_sole": (0, 200, 160),
        "boot_buckle": (70, 30, 105),
        # 벨트
        "belt_dark": (30, 10, 50),
        "belt_mid": (42, 18, 68),
        "belt_light": (55, 24, 85),
        "belt_buckle": (0, 255, 180),
        # 스카프
        "scarf_dark": (60, 20, 95),
        "scarf_mid": (80, 30, 120),
        "scarf_light": (100, 40, 150),
        "scarf_edge": (0, 160, 120, 100),
        # 아웃라인
        "outline": (8, 1, 14),
    }

    # ═══════ 스카프 (뒤쪽 레이어 — 몸 뒤에서 나부낌) ═══════
    scarf_wave = wave * 5
    scarf_segments = 5
    scarf_surf = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
    for si in range(scarf_segments):
        t = si / max(1, scarf_segments - 1)
        seg_wave = scarf_wave * (0.3 + t * 0.7) + math.sin(phase * math.tau * 2 + si) * 2
        sx1 = cx + int(0.2 * b) + int(t * 1.2 * b) + int(seg_wave * t)
        sy1 = ty - int(0.3 * b) + int(t * 2.5 * b)
        sw = max(2, int((1.0 - t * 0.4) * 0.6 * b))
        alpha = max(40, int(200 * (1.0 - t * 0.5)))
        color = p["scarf_dark"] if si % 2 == 0 else p["scarf_mid"]
        seg_rect = pygame.Rect(sx1, sy1, sw, int(0.6 * b))
        seg_s = pygame.Surface((sw + 4, int(0.6 * b) + 4), pygame.SRCALPHA)
        pygame.draw.rect(seg_s, (*color, alpha), (2, 2, sw, int(0.6 * b)), border_radius=2)
        scarf_surf.blit(seg_s, (sx1 - 2, sy1 - 2))
    # 스카프 끝 네온 엣지
    tip_x = cx + int(1.4 * b) + int(scarf_wave * 0.8)
    tip_y = ty + int(2.2 * b)
    pygame.draw.line(scarf_surf, (*p["neon_dim"], 80),
                     (tip_x - 3, tip_y), (tip_x + 3, tip_y + 4), 1)
    surface.blit(scarf_surf, (0, 0))

    # ═══════ 후드 (고급 — 패브릭 주름 + 내부 그림자) ═══════
    hood_w = int(2.1 * b)
    hood_h = int(2.3 * b)
    hx, hy = cx, ty - int(2.8 * b) - lean_forward
    hood_pts = [
        (hx, hy - hood_h // 2 - 4),
        (hx + hood_w // 2 + 3, hy + 1),
        (hx + hood_w // 2, hy + hood_h // 2 + 1),
        (hx - hood_w // 2, hy + hood_h // 2 + 1),
        (hx - hood_w // 2 - 3, hy + 1),
    ]
    # 후드 그림자 (아래쪽이 더 어두움)
    pygame.draw.polygon(surface, p["hood_dark"], hood_pts)
    # 상단 하이라이트 (빛 받는 부분)
    hood_hi_pts = [hood_pts[0], hood_pts[1], hood_pts[4]]
    pygame.draw.polygon(surface, p["hood_mid"], hood_hi_pts)
    # 중앙 릿지 (스티칭 라인)
    pygame.draw.line(surface, p["hood_light"],
                     (hx, hy - hood_h // 2 - 2), (hx, hy + hood_h // 2 - 2), 1)
    # 패브릭 주름 (좌우 대각선)
    for fi in range(3):
        fy = hy - hood_h // 4 + fi * int(0.35 * b)
        pygame.draw.line(surface, p["hood_light"],
                         (hx - 2, fy), (hx - hood_w // 3, fy + 3), 1)
        pygame.draw.line(surface, p["hood_light"],
                         (hx + 2, fy), (hx + hood_w // 3, fy + 3), 1)
    # 테두리
    pygame.draw.lines(surface, p["hood_rim"], True, hood_pts, 1)

    # 후드 내부 그림자 (얼굴 주변 어둡게)
    face_shadow = pygame.Surface((hood_w, int(0.8 * b)), pygame.SRCALPHA)
    for sy_i in range(face_shadow.get_height()):
        sa = int(100 * (sy_i / face_shadow.get_height()))
        pygame.draw.line(face_shadow, (15, 3, 25, sa),
                         (0, sy_i), (face_shadow.get_width(), sy_i))
    surface.blit(face_shadow, (hx - hood_w // 2, hy - int(0.1 * b)))

    # 바이저 (다중 레이어 발광)
    visor_w = int(1.7 * b)
    visor_h = max(4, int(0.4 * b))
    visor_y = hy + 2
    visor_rect = pygame.Rect(hx - visor_w // 2, visor_y, visor_w, visor_h)
    # 글로우 배경
    vg_w, vg_h = visor_w + 14, visor_h + 12
    vg = pygame.Surface((vg_w, vg_h), pygame.SRCALPHA)
    pygame.draw.rect(vg, p["visor_glow"], vg.get_rect(), border_radius=4)
    surface.blit(vg, (visor_rect.left - 7, visor_rect.top - 6), special_flags=pygame.BLEND_RGBA_ADD)
    # 메인 바이저
    pygame.draw.rect(surface, p["visor"], visor_rect, border_radius=2)
    # 내부 디테일 (동공 슬릿 느낌)
    inner = visor_rect.inflate(-4, -2)
    pygame.draw.rect(surface, p["visor_dark"], inner, border_radius=1)
    # 밝은 중심점
    pygame.draw.line(surface, p["visor_bright"],
                     (hx - 3, visor_rect.centery), (hx + 3, visor_rect.centery), 1)
    # 좌우 눈 하이라이트
    for ex in (-visor_w // 4, visor_w // 4):
        pygame.draw.circle(surface, p["visor_bright"], (hx + ex, visor_rect.centery), 1)

    # 턱 마스크 (벤트 디테일)
    chin_w = int(1.3 * b)
    chin_h = int(0.6 * b)
    chin_rect = pygame.Rect(hx - chin_w // 2, visor_rect.bottom + 1, chin_w, chin_h)
    pygame.draw.rect(surface, p["suit_main"], chin_rect, border_radius=2)
    pygame.draw.rect(surface, p["suit_shadow"], chin_rect.inflate(-2, -2), border_radius=1)
    # 벤트 슬릿
    for vi in range(3):
        vy = chin_rect.top + 2 + vi * 3
        pygame.draw.line(surface, p["suit_seam"],
                         (chin_rect.left + 3, vy), (chin_rect.right - 3, vy), 1)
    # 목 가드
    neck_rect = pygame.Rect(hx - int(0.5 * b), chin_rect.bottom, int(1.0 * b), int(0.3 * b))
    pygame.draw.rect(surface, p["suit_shadow"], neck_rect, border_radius=2)

    # ═══════ 상체 (고급 아머 플레이트 + 에너지 도관) ═══════
    torso_top_w = int(2.3 * b)
    torso_bot_w = int(1.6 * b)
    torso_h = int(2.5 * b)
    torso_top = ty - int(0.5 * b) + lean_forward
    torso_pts = [
        (cx - torso_top_w // 2, torso_top),
        (cx + torso_top_w // 2, torso_top),
        (cx + torso_bot_w // 2, torso_top + torso_h),
        (cx - torso_bot_w // 2, torso_top + torso_h),
    ]
    # 기본 슈트
    pygame.draw.polygon(surface, p["suit_main"], torso_pts)
    # 좌우 셰이딩 (입체감)
    left_shade = [torso_pts[0], (cx - int(0.2 * b), torso_top), (cx - int(0.1 * b), torso_top + torso_h), torso_pts[3]]
    right_shade = [(cx + int(0.2 * b), torso_top), torso_pts[1], torso_pts[2], (cx + int(0.1 * b), torso_top + torso_h)]
    shade_s = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
    pygame.draw.polygon(shade_s, (*p["suit_shadow"], 60), left_shade)
    pygame.draw.polygon(shade_s, (*p["suit_light"][:3], 40), right_shade)
    surface.blit(shade_s, (0, 0))

    # 흉갑 플레이트 (중앙 다각형)
    cp_w = int(1.2 * b)
    cp_h = int(1.4 * b)
    cp_y = torso_top + int(0.3 * b)
    chest_plate = [
        (cx, cp_y),
        (cx + cp_w // 2, cp_y + int(0.4 * b)),
        (cx + cp_w // 2 - 2, cp_y + cp_h),
        (cx - cp_w // 2 + 2, cp_y + cp_h),
        (cx - cp_w // 2, cp_y + int(0.4 * b)),
    ]
    pygame.draw.polygon(surface, p["armor_mid"], chest_plate)
    pygame.draw.polygon(surface, p["armor_edge"], chest_plate, 1)
    # 흉갑 내부 패널라인
    pygame.draw.line(surface, p["armor_light"],
                     (cx, cp_y + 2), (cx, cp_y + cp_h - 2), 1)
    pygame.draw.line(surface, p["armor_dark"],
                     (cx - 1, cp_y + 2), (cx - 1, cp_y + cp_h - 2), 1)

    # 에너지 코어 (삼각형 + 글로우)
    core_y = cp_y + int(0.5 * b)
    core_s = pygame.Surface((12, 12), pygame.SRCALPHA)
    pygame.draw.circle(core_s, (*p["neon"][:3], 40), (6, 6), 6)
    surface.blit(core_s, (cx - 6, core_y - 6), special_flags=pygame.BLEND_RGBA_ADD)
    core_pts = [(cx, core_y - 3), (cx + 3, core_y + 2), (cx - 3, core_y + 2)]
    pygame.draw.polygon(surface, p["neon"], core_pts)
    pygame.draw.polygon(surface, p["neon_bright"], core_pts, 1)

    # V자 에너지 도관 (네온 라인 + 글로우)
    conduit_s = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
    for ci in range(2):
        c_alpha = 120 - ci * 40
        c_width = 2 - ci
        pygame.draw.line(conduit_s, (*p["neon"][:3], c_alpha),
                         (cx, cp_y + 3),
                         (cx - torso_top_w // 2 + 5, torso_top + torso_h - 4), c_width)
        pygame.draw.line(conduit_s, (*p["neon"][:3], c_alpha),
                         (cx, cp_y + 3),
                         (cx + torso_top_w // 2 - 5, torso_top + torso_h - 4), c_width)
    surface.blit(conduit_s, (0, 0))

    # 복부 세그먼트 (가로 패널)
    abs_top = cp_y + cp_h + 1
    abs_h = torso_top + torso_h - abs_top - 2
    for ai in range(3):
        ay = abs_top + ai * (abs_h // 3)
        aw = int(torso_bot_w * (0.9 - ai * 0.05))
        seg_rect = pygame.Rect(cx - aw // 2, ay, aw, abs_h // 3 - 1)
        pygame.draw.rect(surface, p["suit_shadow"], seg_rect, border_radius=1)
        pygame.draw.rect(surface, p["suit_seam"], seg_rect, 1, border_radius=1)

    # 외곽 심라인
    pygame.draw.polygon(surface, p["suit_seam"], torso_pts, 1)

    # ═══════ 어깨 (다층 아머 숄더) ═══════
    for side in (-1, 1):
        sx = cx + side * int(1.3 * b)
        sy = torso_top + int(side * shoulder_tilt) + lean_forward
        # 하단 레이어 (넓은 패드)
        sh_base = [
            (sx + side * int(0.9 * b), sy - int(0.4 * b)),
            (cx + side * int(0.6 * b), torso_top - 1 + lean_forward),
            (cx + side * int(0.6 * b), torso_top + int(0.9 * b) + lean_forward),
            (sx + side * int(0.4 * b), sy + int(0.6 * b)),
        ]
        pygame.draw.polygon(surface, p["armor_dark"], sh_base)
        # 상단 레이어 (뾰족한 플레이트)
        sh_top = [
            (sx + side * int(0.85 * b), sy - int(0.35 * b)),
            (cx + side * int(0.65 * b), torso_top + lean_forward),
            (cx + side * int(0.65 * b), torso_top + int(0.5 * b) + lean_forward),
        ]
        pygame.draw.polygon(surface, p["armor_mid"], sh_top)
        pygame.draw.polygon(surface, p["armor_edge"], sh_top, 1)
        # 숄더 네온 라인
        pygame.draw.line(surface, p["neon_dim"],
                         sh_base[0], sh_top[0], 1)
        # 끝 네온 도트
        pygame.draw.circle(surface, p["neon"], sh_base[0], 2)

    # ═══════ 팔 (고급 — 상완 아머 + 전완 래핑 + 장갑) ═══════
    for side, swing_dir in [(-1, 1), (1, -1)]:
        sh_x = cx + side * int(1.2 * b)
        sh_y = torso_top + int(0.3 * b) + int(swing_dir * shoulder_tilt) + lean_forward
        el_x = sh_x + side * int(0.9 * b) + swing_dir * arm_swing
        el_y = sh_y + int(0.8 * b) + swing_dir * arm_swing // 3
        wr_x = el_x + side * int(0.7 * b)
        wr_y = el_y + int(0.5 * b) + swing_dir * int(arm_swing * 0.2)
        at = b - 2  # 팔 두께

        # 🦵 날라차기 팔 포즈 오버라이드: 양팔을 넓게 벌림 (이소룡 스타일)
        if flying_kick != 0:
            _fk = flying_kick
            _fi = max(0.0, min(1.0, flying_kick_intensity))
            # 기본 팔 위치 저장
            _base_el_x, _base_el_y = el_x, el_y
            _base_wr_x, _base_wr_y = wr_x, wr_y
            if side == _fk:
                # 킥 방향 팔: 앞으로 뻗음 (리드 핸드)
                _target_el_x = sh_x + side * int(1.5 * b)
                _target_el_y = sh_y - int(0.8 * b)
                _target_wr_x = _target_el_x + side * int(1.3 * b)
                _target_wr_y = _target_el_y - int(0.3 * b)
            else:
                # 반대 팔: 뒤로 넓게 벌림 (밸런스)
                _target_el_x = sh_x + side * int(1.8 * b)
                _target_el_y = sh_y - int(0.4 * b)
                _target_wr_x = _target_el_x + side * int(1.0 * b)
                _target_wr_y = _target_el_y + int(0.2 * b)
            # intensity로 보간 (1.0=날라차기, 0.0=일반)
            el_x = int(_base_el_x + (_target_el_x - _base_el_x) * _fi)
            el_y = int(_base_el_y + (_target_el_y - _base_el_y) * _fi)
            wr_x = int(_base_wr_x + (_target_wr_x - _base_wr_x) * _fi)
            wr_y = int(_base_wr_y + (_target_wr_y - _base_wr_y) * _fi)

        # 🕷 벽타기 팔 포즈 오버라이드
        elif wall_cling != 0:
            _wc_is_wall_side = (side == wall_cling)  # 이 팔이 벽 쪽인지
            if not _wc_is_wall_side:
                # 벽 쪽 팔: 위로 뻗어 벽을 잡는 포즈
                el_x = sh_x + side * int(0.3 * b)    # 팔꿈치를 벽 가까이
                el_y = sh_y - int(2.0 * b)            # 위로 높이 올림
                wr_x = el_x + side * int(0.2 * b)     # 손도 벽 쪽으로
                wr_y = el_y - int(1.5 * b)            # 더 위로 뻗음
            else:
                # 바깥쪽 팔: 약간 벌려 준비 자세 (아래로 자연스럽게)
                el_x = sh_x + side * int(1.2 * b)    # 바깥으로 벌림
                el_y = sh_y + int(0.5 * b)            # 약간 아래
                wr_x = el_x + side * int(0.8 * b)    # 손가락 벌린 느낌
                wr_y = el_y + int(0.8 * b)            # 아래로 늘어뜨림

        # 왼팔 슬래시 모션: 왼팔(side==-1)을 위로 힘차게 휘두르기
        elif side == -1 and left_slash_strength > 0:
            _ls = left_slash_strength
            # 어깨 → 팔꿈치: 위쪽+앞쪽으로 크게 회전 (힘찬 슬래시)
            el_x = int(el_x + _ls * 1.0 * b)         # 앞으로 밀어냄
            el_y = int(el_y - _ls * 2.8 * b)         # 크게 위로 들어올림
            # 팔꿈치 → 손목: 왼쪽 위 대각선으로 블레이드를 쭉 뻗음
            wr_x = int(el_x - _ls * 2.0 * b)         # 왼쪽으로 크게 휘두름
            wr_y = int(el_y - _ls * 2.2 * b)         # 위로 힘차게 뻗음

        # 상완 (아머 플레이트 느낌)
        pygame.draw.line(surface, p["arm_light"], (sh_x, sh_y), (el_x, el_y), at)
        pygame.draw.line(surface, p["arm_mid"], (sh_x, sh_y), (el_x, el_y), max(1, at - 2))
        # 상완 아머 스트라이프
        mid_ax = (sh_x + el_x) // 2
        mid_ay = (sh_y + el_y) // 2
        pygame.draw.circle(surface, p["armor_mid"], (mid_ax, mid_ay), 3)
        pygame.draw.circle(surface, p["neon_dim"], (mid_ax, mid_ay), 2, 1)

        # 팔꿈치 조인트
        pygame.draw.circle(surface, p["armor_dark"], (el_x, el_y), 4)
        pygame.draw.circle(surface, p["neon_dim"], (el_x, el_y), 3, 1)
        pygame.draw.circle(surface, p["neon"], (el_x, el_y), 1)

        # 전완 (래핑 패턴)
        pygame.draw.line(surface, p["arm_light"], (el_x, el_y), (wr_x, wr_y), at)
        pygame.draw.line(surface, p["wrap_dark"], (el_x, el_y), (wr_x, wr_y), max(1, at - 2))
        # 래핑 줄무늬
        wrap_segs = 4
        for wi in range(wrap_segs):
            t = (wi + 1) / (wrap_segs + 1)
            wx = int(el_x + (wr_x - el_x) * t)
            wy = int(el_y + (wr_y - el_y) * t)
            pygame.draw.circle(surface, p["wrap_light"], (wx, wy), max(1, at // 2), 1)

        # 장갑 (다층)
        gr = max(3, b // 2)
        pygame.draw.circle(surface, p["glove_dark"], (wr_x, wr_y), gr)
        pygame.draw.circle(surface, p["glove_mid"], (wr_x, wr_y), gr - 1)
        pygame.draw.circle(surface, p["glove_accent"], (wr_x, wr_y), 2, 1)
        # 너클 라인
        pygame.draw.line(surface, p["neon_dim"],
                         (wr_x - 3, wr_y - 1), (wr_x + 3, wr_y - 1), 1)

        # 왼손 플라즈마 블레이드 (고급)
        if side == -1:
            bl_len = int(2.8 * b)
            # 다중 글로우 레이어
            for gl in range(3, 0, -1):
                gw = b * gl
                gh = bl_len + b * gl // 2
                gs = pygame.Surface((gw * 2, gh), pygame.SRCALPHA)
                ga = 25 + (3 - gl) * 10
                pygame.draw.ellipse(gs, (*p["blade_outer"][:3], ga), gs.get_rect())
                surface.blit(gs, (wr_x - gw, wr_y - bl_len - b // 2),
                             special_flags=pygame.BLEND_RGBA_ADD)
            # 외곽 블레이드
            bl_w = 4
            bl_pts = [
                (wr_x, wr_y - bl_len),
                (wr_x - bl_w // 2, wr_y - 3),
                (wr_x + bl_w // 2, wr_y - 3),
            ]
            pygame.draw.polygon(surface, p["blade_outer"], bl_pts)
            # 내부 코어
            bl_inner = [
                (wr_x, wr_y - bl_len + 3),
                (wr_x - 1, wr_y - 4),
                (wr_x + 1, wr_y - 4),
            ]
            pygame.draw.polygon(surface, p["blade_mid"], bl_inner)
            # 중심선
            pygame.draw.line(surface, p["blade_core"],
                             (wr_x, wr_y - bl_len + 4), (wr_x, wr_y - 5), 1)
            # 팁 하이라이트
            pygame.draw.circle(surface, p["blade_white"], (wr_x, wr_y - bl_len + 1), 2)
            pygame.draw.circle(surface, p["blade_core"], (wr_x, wr_y - bl_len + 1), 1)
            # 에너지 파티클 (블레이드 주변)
            particle_s = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
            ticks = pygame.time.get_ticks()
            for pi in range(4):
                pp = ((ticks * 0.003 + pi * 1.5) % 2.0)
                if pp < 1.5:
                    px = wr_x + int(math.sin(pi * 2.1 + ticks * 0.005) * 4)
                    py = wr_y - int(bl_len * pp / 1.5)
                    pa = max(0, int(200 * (1.0 - pp / 1.5)))
                    pygame.draw.circle(particle_s, (*p["blade_mid"][:3], pa), (px, py), 1)
            surface.blit(particle_s, (0, 0))
            # 이미터 (손잡이)
            emit_rect = pygame.Rect(wr_x - 3, wr_y - 3, 6, 6)
            pygame.draw.rect(surface, p["armor_mid"], emit_rect, border_radius=1)
            pygame.draw.rect(surface, p["armor_edge"], emit_rect, 1, border_radius=1)

    # ═══════ 벨트 (파우치 + 장비) ═══════
    belt_y = torso_top + torso_h - 1 + lean_forward
    belt_w = int(1.9 * b)
    belt_h = int(0.5 * b)
    belt_rect = pygame.Rect(cx - belt_w // 2, belt_y, belt_w, belt_h)
    pygame.draw.rect(surface, p["belt_dark"], belt_rect, border_radius=2)
    pygame.draw.rect(surface, p["belt_mid"], belt_rect.inflate(-2, -2), border_radius=1)
    pygame.draw.rect(surface, p["suit_seam"], belt_rect, 1, border_radius=2)
    # 버클
    pygame.draw.circle(surface, p["belt_buckle"], (cx, belt_rect.centery), 3)
    pygame.draw.circle(surface, p["neon_bright"], (cx, belt_rect.centery), 1)
    # 좌우 파우치
    for side in (-1, 1):
        pouch_x = cx + side * int(0.6 * b)
        pouch_rect = pygame.Rect(pouch_x - 3, belt_rect.top + 1, 6, belt_h - 2)
        pygame.draw.rect(surface, p["belt_dark"], pouch_rect, border_radius=1)
        pygame.draw.rect(surface, p["belt_light"], pouch_rect, 1, border_radius=1)

    # ═══════ 하체 (고급 — 다층 셰이딩 + 홀스터) ═══════
    hip_y = belt_rect.bottom + lean_forward
    thigh_len = int(2.6 * b)
    thigh_w = int(0.65 * b)

    for side, l_step, l_lift in [(-1, left_leg_step, left_leg_lift),
                                  (1, right_leg_step, right_leg_lift)]:
        th_x = cx + side * int(0.75 * b)
        th_top = hip_y + l_lift
        th_bot_x = th_x + l_step // 2
        th_bot_y = th_top + thigh_len

        # 다층 허벅지
        pygame.draw.line(surface, p["leg_light"], (th_x, th_top), (th_bot_x, th_bot_y), thigh_w + 1)
        pygame.draw.line(surface, p["leg_mid"], (th_x, th_top), (th_bot_x, th_bot_y), thigh_w)
        pygame.draw.line(surface, p["leg_shadow"], (th_x, th_top), (th_bot_x, th_bot_y), max(1, thigh_w - 3))
        # 네온 스트라이프 (이중)
        stripe_off = thigh_w // 2
        pygame.draw.line(surface, p["neon_purple"],
                         (th_x + side * stripe_off, th_top + 3),
                         (th_bot_x + side * stripe_off, th_bot_y - 3), 1)
        pygame.draw.line(surface, p["neon_purple_dim"],
                         (th_x + side * (stripe_off - 2), th_top + 5),
                         (th_bot_x + side * (stripe_off - 2), th_bot_y - 5), 1)

        # 오른쪽 다리에 칼집 (홀스터)
        if side == 1:
            holster_y = th_top + int(thigh_len * 0.2)
            holster_h = int(thigh_len * 0.35)
            hol_x = th_x + (th_bot_x - th_x) * 30 // 100 + thigh_w // 2 + 1
            pygame.draw.line(surface, p["armor_dark"],
                             (hol_x, holster_y), (hol_x, holster_y + holster_h), 2)
            pygame.draw.line(surface, p["armor_edge"],
                             (hol_x, holster_y), (hol_x, holster_y + holster_h), 1)

        # 무릎 가드 (고급 — 다층)
        kn_y = th_top + int(thigh_len * 0.62)
        kn_x = th_x + (th_bot_x - th_x) * 62 // 100
        # 외곽
        kn_pts = [(kn_x, kn_y - 4), (kn_x + 4, kn_y), (kn_x, kn_y + 4), (kn_x - 4, kn_y)]
        pygame.draw.polygon(surface, p["knee_dark"], kn_pts)
        # 내부
        kn_inner = [(kn_x, kn_y - 2), (kn_x + 2, kn_y), (kn_x, kn_y + 2), (kn_x - 2, kn_y)]
        pygame.draw.polygon(surface, p["knee_mid"], kn_inner)
        pygame.draw.polygon(surface, p["knee_accent"], kn_pts, 1)

        # 부츠 (고급 — 버클 + 솔 발광)
        boot_h = int(1.1 * b)
        boot_rect = pygame.Rect(th_bot_x - thigh_w // 2 - 2, th_bot_y - 3, thigh_w + 4, boot_h)
        pygame.draw.rect(surface, p["boot_dark"], boot_rect, border_radius=3)
        pygame.draw.rect(surface, p["boot_mid"], boot_rect.inflate(-2, -2), border_radius=2)
        # 부츠 상단 림
        pygame.draw.line(surface, p["boot_light"],
                         (boot_rect.left + 1, boot_rect.top + 1),
                         (boot_rect.right - 1, boot_rect.top + 1), 1)
        # 버클
        buckle_y = boot_rect.top + boot_h // 3
        pygame.draw.line(surface, p["boot_buckle"],
                         (boot_rect.left + 2, buckle_y),
                         (boot_rect.right - 2, buckle_y), 1)
        # 솔 발광
        sole_s = pygame.Surface((boot_rect.width, 4), pygame.SRCALPHA)
        pygame.draw.rect(sole_s, (*p["boot_sole"][:3], 150), sole_s.get_rect(), border_radius=1)
        surface.blit(sole_s, (boot_rect.left, boot_rect.bottom - 2))

    # ═══════ 전체 아웃라인 ═══════
    ol_surf = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
    pygame.draw.polygon(ol_surf, p["outline"], hood_pts, 1)
    pygame.draw.polygon(ol_surf, p["outline"], torso_pts, 1)
    surface.blit(ol_surf, (0, 0))

    return surface


