def init_blacksmith_globals():
    """Blacksmith 관련 전역 변수 초기화"""
    global blacksmith_hammer_explosions, _blacksmith_hammer_explosion_surface_cache
    global _blacksmith_hammer_explosion_scaled_cache, _blacksmith_hammer_halo_cache
    global blacksmith_hammer_return_fx
    global blacksmith_hammer_swing_slow_timer, blacksmith_hammer_slow_decay_step
    blacksmith_hammer_swing_slow_timer = 0
    blacksmith_hammer_slow_decay_step = 0
    _blacksmith_hammer_explosion_surface_cache.clear()
    _blacksmith_hammer_explosion_scaled_cache.clear()
    _blacksmith_hammer_halo_cache.clear()
    blacksmith_hammer_explosions.clear()
    blacksmith_hammer_return_fx.clear()
    print("Blacksmith hammer globals initialized")

def _clamp_color(color: tuple[int, ...]) -> tuple[int, ...]:
    return tuple(max(0, min(255, int(component))) for component in color)


def _get_blacksmith_hammer_effect_center() -> tuple[float, float]:
    global blacksmith_hammer_charge_position, blacksmith_hammer_idle_position
    if blacksmith_hammer_charge_position is not None:
        return (
            float(blacksmith_hammer_charge_position[0]),
            float(blacksmith_hammer_charge_position[1]),
        )
    if blacksmith_hammer_idle_position is not None:
        return (
            float(blacksmith_hammer_idle_position[0]),
            float(blacksmith_hammer_idle_position[1]),
        )
    if 'PLAYER' in globals() and PLAYER is not None:
        return (
            float(PLAYER.right + 18),
            float(PLAYER.centery - 20),
        )
    return float(WIDTH // 2), float(HEIGHT // 2)


def _sanitize_blacksmith_hammer_position(
    pos: tuple[float, float] | None,
) -> tuple[float, float] | None:
    """Ensure hammer charge coordinates stay within sane, finite bounds."""

    if pos is None:
        return None

    try:
        x = float(pos[0])
        y = float(pos[1])
    except (TypeError, ValueError, IndexError):
        return None

    if not math.isfinite(x) or not math.isfinite(y):
        return None

    limit = 1_000_000
    if abs(x) > limit or abs(y) > limit:
        return None

    return (x, y)


def _get_blacksmith_hammer_explosion_palette(stage: int) -> dict[str, object]:
    stage_index = max(1, min(stage, BLACKSMITH_HAMMER_SHOCK_MAX_STAGE))
    return _BLACKSMITH_HAMMER_EXPLOSION_PALETTES.get(stage_index, _BLACKSMITH_HAMMER_EXPLOSION_PALETTES[1])


def _get_blacksmith_hammer_explosion_surface(stage: int) -> pygame.Surface:
    stage_index = max(1, min(stage, BLACKSMITH_HAMMER_SHOCK_MAX_STAGE))
    cached = _blacksmith_hammer_explosion_surface_cache.get(stage_index)
    if cached is not None:
        return cached

    palette = _get_blacksmith_hammer_explosion_palette(stage_index)
    radius = BLACKSMITH_HAMMER_SHOCK_BASE_RADIUS
    if stage_index == 2:
        radius *= BLACKSMITH_HAMMER_SHOCK_STAGE2_RADIUS_SCALE
    elif stage_index >= 3:
        radius *= BLACKSMITH_HAMMER_SHOCK_STAGE3_RADIUS_SCALE

    visual_radius = radius * (0.58 + 0.06 * (stage_index - 1))
    size = int(visual_radius * 2) + 12
    surface = pygame.Surface((size, size), pygame.SRCALPHA)
    center = size // 2

    gradient_steps = 32
    core_color = palette.get("core", (255, 248, 230))
    mid_color = palette.get("mid", (210, 180, 120))
    edge_color = palette.get("edge", (160, 110, 70))

    for step in range(gradient_steps):
        ratio = step / max(1, gradient_steps - 1)
        radius_step = max(1, int(visual_radius * (1.0 - ratio ** 1.22)))
        if radius_step <= 0:
            continue

        outer_mix_threshold = 0.68
        if ratio <= outer_mix_threshold:
            mix = ratio / max(outer_mix_threshold, 1e-6)
            color_rgb = tuple(int(lerp(edge_color[i], mid_color[i], mix ** 1.05)) for i in range(3))
        else:
            mix = (ratio - outer_mix_threshold) / max(1.0 - outer_mix_threshold, 1e-6)
            color_rgb = tuple(int(lerp(mid_color[i], core_color[i], mix ** 0.85)) for i in range(3))

        falloff = 1.0 - ratio
        alpha = int(lerp(60, 255, falloff ** 0.8))
        pygame.draw.circle(
            surface,
            _clamp_color((*color_rgb, alpha)),
            (center, center),
            radius_step,
        )

    pygame.draw.circle(
        surface,
        _clamp_color((*core_color, 255)),
        (center, center),
        max(2, int(visual_radius * 0.18)),
    )

    pygame.draw.circle(
        surface,
        _clamp_color((*mid_color, 140)),
        (center, center),
        max(2, int(visual_radius * 0.42)),
        width=2,
    )

    glyph_surface = pygame.Surface((size, size), pygame.SRCALPHA)
    glyph_color = palette.get("glyph", (255, 220, 180))
    # 중심부 하이라이트를 부드러운 오라로 추가
    pygame.draw.circle(
        glyph_surface,
        _clamp_color((*glyph_color, 90)),
        (center, center),
        max(2, int(visual_radius * 0.28)),
        width=1,
    )
    inner_glow_surface = pygame.Surface((size, size), pygame.SRCALPHA)
    pygame.draw.circle(
        inner_glow_surface,
        _clamp_color((*glyph_color, 70)),
        (center, center),
        max(1, int(visual_radius * 0.6)),
    )
    inner_glow_surface = pygame.transform.smoothscale(
        inner_glow_surface,
        (int(inner_glow_surface.get_width() * 0.96), int(inner_glow_surface.get_height() * 0.96)),
    )
    surface.blit(inner_glow_surface, inner_glow_surface.get_rect(center=(center, center)), special_flags=pygame.BLEND_ADD)
    surface.blit(glyph_surface, (0, 0), special_flags=pygame.BLEND_ADD)
    _blacksmith_hammer_explosion_surface_cache[stage_index] = surface
    return surface

def _quantize_explosion_scale(scale: float) -> tuple[int, float]:
    """해머쇼크 폭발 스케일(1.00~1.35)을 정해진 스텝으로 양자화한다.

    Returns: (step_index, quantized_scale)
    """
    steps = max(2, int(BLACKSMITH_EXPLOSION_SCALE_CACHE_STEPS))
    # 기대 범위 보호
    s = max(1.0, min(1.35, float(scale)))
    t = (s - 1.0) / 0.35
    idx = int(round(t * (steps - 1)))
    idx = max(0, min(steps - 1, idx))
    q = 1.0 + 0.35 * (idx / (steps - 1))
    return idx, q

def _get_scaled_explosion_surface(stage: int, scale: float) -> pygame.Surface:
    """Stage별 기본 폭발 서피스를 스케일 캐시로 제공한다.

    - 매 프레임 smoothscale 호출을 피하기 위해 스케일을 양자화하여 캐시 재사용
    - 페이드(알파)는 호출자가 set_alpha로 조절한다(공유 서피스 → set_alpha 후 복구).
    """
    stage_index = max(1, min(stage, BLACKSMITH_HAMMER_SHOCK_MAX_STAGE))
    step_idx, quantized = _quantize_explosion_scale(scale)
    key = (stage_index, step_idx)
    cached = _blacksmith_hammer_explosion_scaled_cache.get(key)
    if cached is not None:
        return cached
    base = _get_blacksmith_hammer_explosion_surface(stage_index)
    size = (
        max(1, int(base.get_width() * quantized)),
        max(1, int(base.get_height() * quantized)),
    )
    scaled = pygame.transform.smoothscale(base, size)
    _blacksmith_hammer_explosion_scaled_cache[key] = scaled
    return scaled

def _get_halo_surface(radius: float, color_rgb: tuple[int, int, int]) -> pygame.Surface:
    """반지름과 색상(RGB)으로 채워진 원형 헤일로 서피스를 캐시해 반환한다.

    - 알파는 호출 시점에 set_alpha로 조절한다.
    """
    r = max(1, int(radius))
    cr = int(color_rgb[0])
    cg = int(color_rgb[1])
    cb = int(color_rgb[2])
    key = (r, cr, cg, cb)
    cached = _blacksmith_hammer_halo_cache.get(key)
    if cached is not None:
        return cached
    surf = pygame.Surface((r * 2 + 6, r * 2 + 6), pygame.SRCALPHA)
    pygame.draw.circle(
        surf,
        (cr, cg, cb, 255),
        (surf.get_width() // 2, surf.get_height() // 2),
        r,
    )
    _blacksmith_hammer_halo_cache[key] = surf
    return surf


def _create_blacksmith_hammer_explosion(stage: int, centerx: float, centery: float, radius: float) -> dict[str, object]:
    stage_index = max(1, min(stage, BLACKSMITH_HAMMER_SHOCK_MAX_STAGE))
    palette = _get_blacksmith_hammer_explosion_palette(stage_index)
    base_surface = _get_blacksmith_hammer_explosion_surface(stage_index)

    life_frames = int((0.5 + 0.12 * (stage_index - 1)) * FPS)
    sparks: list[tuple[float, float, float]] = []
    spark_color = palette.get("sparks", (215, 240, 255))
    spark_count = 16 + stage_index * 3
    for _ in range(spark_count):
        angle = random.uniform(0, math.tau)
        distance = radius * random.uniform(0.9, 1.35)
        size = radius * 0.028 * random.uniform(0.9, 1.3)
        sparks.append((angle, distance, size))
    antimatter_color = palette.get("antimatter", (150, 220, 255, 170))

    return {
        "surface": base_surface,
        "center": (centerx, centery),
        "radius": radius,
        "stage": stage_index,
        "life": life_frames,
        "max_life": life_frames,
        "sparks": sparks,
        "first_frame": True,
        "ring_palette": palette.get("rings"),
        "glyph_color": palette.get("glyph"),
        "spark_color": spark_color,
        "halo_color": palette.get("halo"),
        "antimatter_color": antimatter_color,
    }


def _spawn_blacksmith_hammer_return_fx(centerx: float, centery: float) -> None:
    global blacksmith_hammer_return_fx
    effect_life = max(6, int(0.28 * FPS))
    anchor_offset: tuple[float, float] | None = None
    if 'PLAYER' in globals() and PLAYER is not None:
        anchor_offset = (
            float(centerx - PLAYER.centerx),
            float(centery - PLAYER.centery),
        )
    entry = {
        "center": (float(centerx), float(centery)),
        "anchor_offset": anchor_offset,
        "life": effect_life,
        "max_life": effect_life,
    }
    blacksmith_hammer_return_fx.append(entry)
    try:
        effects_manager.spawn_star_particles(int(centerx), int(centery), count=6)
    except Exception:
        pass


def _get_blacksmith_hammer_charge_surface(stage: int) -> pygame.Surface:
    clamped_stage = max(0, min(int(stage), BLACKSMITH_HAMMER_SHOCK_MAX_STAGE))
    cached = _blacksmith_hammer_charge_surface_cache.get(clamped_stage)
    if cached is not None:
        return cached

    radius = 12 + clamped_stage * 4
    padding = 20
    size = radius * 2 + padding
    surface = pygame.Surface((size, size), pygame.SRCALPHA)
    center = size // 2

    # 부드러운 외곽 그라데이션 3단계
    outer_bands = (
        (radius + 8, (40, 90 + clamped_stage * 24, 200 + clamped_stage * 30, 55 + clamped_stage * 18)),
        (radius + 4, (70, 150 + clamped_stage * 22, 240, 90 + clamped_stage * 25)),
        (radius + 1, (120, 210, 255, 140 + clamped_stage * 30)),
    )
    for band_radius, color in outer_bands:
        pygame.draw.circle(surface, _clamp_color(color), (center, center), max(0, band_radius))

    # 중심부 코어와 윤곽선
    pygame.draw.circle(surface, _clamp_color((205, 240, 255, 210)), (center, center), max(2, radius - 3))
    pygame.draw.circle(surface, _clamp_color((160, 225, 255, 250)), (center, center), radius, width=2)

    _blacksmith_hammer_charge_surface_cache[clamped_stage] = surface
    return surface


def _get_blacksmith_hammer_charge_spark(stage: int) -> pygame.Surface:
    clamped_stage = max(0, min(int(stage), BLACKSMITH_HAMMER_SHOCK_MAX_STAGE))
    cached = _blacksmith_hammer_charge_spark_cache.get(clamped_stage)
    if cached is not None:
        return cached

    size = 10 + clamped_stage * 2
    surface = pygame.Surface((size, size), pygame.SRCALPHA)
    center = size // 2
    pygame.draw.circle(surface, (230, 250, 255, 180), (center, center), max(1, center - 1))
    pygame.draw.circle(surface, (255, 255, 255, 230), (center, center), max(1, center - 3))
    pygame.draw.circle(surface, (180, 220, 255, 140), (center, center), max(1, center - 5))

    _blacksmith_hammer_charge_spark_cache[clamped_stage] = surface
    return surface


def _get_blacksmith_thrown_hammer_surface() -> pygame.Surface:
    global _blacksmith_thrown_hammer_surface
    if _blacksmith_thrown_hammer_surface is not None:
        return _blacksmith_thrown_hammer_surface

    width = 44
    height = 78
    surface = pygame.Surface((width, height), pygame.SRCALPHA)
    center_x = width // 2

    handle_width = 10
    handle_height = 48
    handle_rect = pygame.Rect(center_x - handle_width // 2, height - handle_height - 4, handle_width, handle_height)
    pygame.draw.rect(surface, (90, 60, 36), handle_rect)

    grip_segments = 5
    segment_height = handle_height // grip_segments
    for i in range(grip_segments):
        segment_rect = pygame.Rect(handle_rect.left, handle_rect.top + i * segment_height, handle_width, segment_height - 2)
        pygame.draw.rect(surface, (60, 35, 18), segment_rect)

    pommel_rect = pygame.Rect(center_x - (handle_width + 4) // 2, height - 10, handle_width + 4, 8)
    pygame.draw.rect(surface, (112, 76, 48), pommel_rect, border_radius=2)

    head_height = 26
    head_width = 40
    head_top = handle_rect.top - head_height + 6
    head_rect = pygame.Rect(center_x - head_width // 2, head_top, head_width, head_height)
    pygame.draw.rect(surface, (176, 182, 196), head_rect, border_radius=4)

    inset_rect = head_rect.inflate(-8, -6)
    pygame.draw.rect(surface, (210, 215, 228), inset_rect, border_radius=3)

    ridge_y = inset_rect.centery
    pygame.draw.line(surface, (120, 130, 142), (inset_rect.left, ridge_y), (inset_rect.right, ridge_y), 3)

    emblem_center = (center_x, ridge_y)
    pygame.draw.circle(surface, (230, 215, 130), emblem_center, 6)
    pygame.draw.circle(surface, (240, 160, 60), emblem_center, 3)

    flare_rect = pygame.Rect(center_x - head_width // 2 + 4, head_rect.top - 6, head_width - 8, 12)
    pygame.draw.ellipse(surface, (200, 235, 255, 90), flare_rect)

    _blacksmith_thrown_hammer_surface = surface
    return surface

def _clamp_blacksmith_hammer_explosion_center(cx: float, cy: float, radius: float) -> tuple[float, float]:
    """HUD와 화면 경계에 가려지는 것을 방지하기 위해 폭발 렌더링 중심을 보정한다."""
    min_visible_y = max(
        BLACKSMITH_HAMMER_EFFECT_TOP_CLEARANCE,
        radius * BLACKSMITH_HAMMER_EFFECT_RADIUS_VISIBILITY,
    )
    max_visible_y = min(
        HEIGHT - BLACKSMITH_HAMMER_EFFECT_BOTTOM_CLEARANCE,
        HEIGHT - radius * 0.35,
    )

    min_visible_x = BLACKSMITH_HAMMER_EFFECT_SIDE_CLEARANCE
    max_visible_x = WIDTH - BLACKSMITH_HAMMER_EFFECT_SIDE_CLEARANCE

    clamped_y = max(min_visible_y, min(max_visible_y, cy))
    clamped_x = max(min_visible_x, min(max_visible_x, cx))

    return clamped_x, clamped_y


def _draw_blacksmith_hammer_charge_effect(
    surface: pygame.Surface,
    center_x: int,
    center_y: int,
    stage: int,
    frame: int,
) -> None:
    base_surface = _get_blacksmith_hammer_charge_surface(stage)
    if base_surface:
        rect = base_surface.get_rect(center=(center_x, center_y))
        surface.blit(base_surface, rect)

    radius = 12 + max(0, stage) * 4
    spark_surface = _get_blacksmith_hammer_charge_spark(stage)
    spark_radius = radius * 0.55
    spark_count = 3 + max(0, stage)

    # 번개 줄기 - 프레임 기반 시드로 깜빡임을 유지
    line_seed = (frame // 2) + stage * 97
    rng = random.Random(line_seed)
    arc_count = 3 + max(0, stage)
    thickness = 2 if stage > 0 else 1

    for arc_index in range(arc_count):
        start_angle = rng.uniform(0.0, math.tau)
        angle_span = rng.uniform(0.6, 1.1)
        segments = 5 + max(0, stage)
        points: list[tuple[int, int]] = []
        for segment in range(segments):
            t = segment / max(1, segments - 1)
            wobble = math.sin(frame * 0.18 + arc_index * 1.9 + t * 3.6) * 0.18
            radial_wave = math.sin(frame * 0.22 + arc_index * 2.1 + t * 4.2) * (3.0 + stage * 2.0)
            angle = start_angle + angle_span * t + wobble
            current_radius = radius * (0.55 + t * 0.55) + radial_wave
            px = int(round(center_x + math.cos(angle) * current_radius))
            py = int(round(center_y + math.sin(angle) * current_radius))
            points.append((px, py))
        outer_color = _clamp_color((80, 170 + stage * 28, 255, 160))
        inner_color = _clamp_color((210, 245, 255, 220))
        pygame.draw.lines(surface, outer_color, False, points, thickness + 1)
        pygame.draw.lines(surface, inner_color, False, points, max(1, thickness))

    for idx in range(spark_count):
        angle = (frame * 0.3 + idx * 2.2) % math.tau
        pulse = math.sin(frame * 0.4 + idx) * (4 + stage * 2)
        radius_offset = spark_radius + pulse
        sx = int(round(center_x + math.cos(angle) * radius_offset))
        sy = int(round(center_y + math.sin(angle) * radius_offset * 0.82))
        spark_rect = spark_surface.get_rect(center=(sx, sy))
        surface.blit(spark_surface, spark_rect)


def _blacksmith_hammer_shock_stage_for_frames(frames: int) -> int:
    if frames >= BLACKSMITH_HAMMER_SHOCK_STAGE3_FRAMES:
        return 3
    if frames >= BLACKSMITH_HAMMER_SHOCK_STAGE2_FRAMES:
        return 2
    if frames >= BLACKSMITH_HAMMER_SHOCK_STAGE1_FRAMES:
        return 1
    return 0


def _blacksmith_hammer_shock_cost_for_stage(stage: int) -> int:
    """현재 스테이지에 필요한 게이지 비용을 반환한다."""

    return BLACKSMITH_HAMMER_SHOCK_STAGE_COST.get(stage, 0)


def _blacksmith_hammer_shock_max_stage_for_gauge(gauge: float) -> int:
    """보유한 게이지로 도달 가능한 최대 스테이지를 계산한다."""

    if gauge <= 0:
        return 0

    if gauge >= BLACKSMITH_HAMMER_SHOCK_MAX_STAGE_COST:
        return BLACKSMITH_HAMMER_SHOCK_MAX_STAGE

    max_stage = 0
    for stage in sorted(BLACKSMITH_HAMMER_SHOCK_STAGE_COST):
        if gauge < BLACKSMITH_HAMMER_SHOCK_STAGE_COST[stage]:
            break
        max_stage = stage
    return max_stage


def _blacksmith_hammer_shock_damage_for_stage(stage: int) -> int:
    """해머쇼크 단계에 따른 체력형 보스 피해량을 반환한다."""

    if stage is None:
        return 0

    try:
        stage_value = int(stage)
    except (TypeError, ValueError):
        return 0

    if stage_value <= 0:
        return 0

    clamped_stage = min(stage_value, BLACKSMITH_HAMMER_SHOCK_MAX_STAGE)
    return BLACKSMITH_HAMMER_SHOCK_STAGE_DAMAGE.get(clamped_stage, clamped_stage)


def _blacksmith_hammer_shock_effective_stage(frames: int, gauge: float) -> int:
    """차지 시간과 현재 게이지를 동시에 고려한 실효 스테이지를 구한다."""

    frame_stage = _blacksmith_hammer_shock_stage_for_frames(frames)
    max_stage = _blacksmith_hammer_shock_max_stage_for_gauge(gauge)

    # 해머쇼크 퍽 레벨에 따라 최대 단계를 제한한다.
    # - 퍽 없음: 0 (해머쇼크 사용 불가)
    # - 1단계 퍽: 최대 1단계
    # - 2단계 퍽: 최대 2단계
    # - 3단계 퍽: 최대 3단계
    perk_max_stage = get_blacksmith_hammer_shock_max_stage_by_perk()
    max_stage = min(max_stage, perk_max_stage)

    # 디바인쉴드 과부하 중에는 1단계까지만 (강화 디바인스톤 한정)
    try:
        divine_state = blacksmith_divine_stone_state
        if divine_state:
            overheat = int(divine_state.get("shield_overheat", 0)) > 0
            if overheat:
                max_stage = min(max_stage, 1)
    except Exception:
        pass

    return min(frame_stage, max_stage)


def release_blacksmith_hammer_shock():
    global blacksmith_hammer_shock_charging, blacksmith_hammer_shock_charge_frames
    global blacksmith_hammer_shock_stage, blacksmith_hammer_shock_projectiles
    global blacksmith_hammer_available, blacksmith_hammer_shock_cooldown_timer
    global blacksmith_hammer_shock_anchor_x, blacksmith_hammer_shock_anchor_y
    global blacksmith_hammer_shock_last_stage, blacksmith_hammer_shock_cooldown_total
    global special_gauge, special_ready, special_gauge_max
    global PLAYER, SOUND_GRENADE, SOUND_BLACKSMITH_HAMMER_THROW
    global blacksmith_hammer_charge_position, blacksmith_hammer_idle_position
    global blacksmith_divine_stone_state, space_just_pressed

    if not blacksmith_hammer_shock_charging:
        return

    stop_blacksmith_hammer_charge_sound()

    stage = _blacksmith_hammer_shock_effective_stage(
        blacksmith_hammer_shock_charge_frames,
        special_gauge,
    )
    cost = _blacksmith_hammer_shock_cost_for_stage(stage)
    if stage == 0:
        blacksmith_hammer_shock_charging = False
        blacksmith_hammer_shock_charge_frames = 0
        blacksmith_hammer_shock_stage = 0
        return

    if cost <= 0 or special_gauge < cost:
        blacksmith_hammer_shock_charging = False
        blacksmith_hammer_shock_charge_frames = 0
        blacksmith_hammer_shock_stage = 0
        return

    if blacksmith_divine_stone_state is None:
        blacksmith_hammer_shock_charging = False
        blacksmith_hammer_shock_charge_frames = 0
        blacksmith_hammer_shock_stage = 0
        return

    if 'PLAYER' not in globals() or PLAYER is None:
        blacksmith_hammer_shock_charging = False
        blacksmith_hammer_shock_charge_frames = 0
        blacksmith_hammer_shock_stage = 0
        return

    origin_x = PLAYER.right + 18
    origin_y = PLAYER.centery - 20
    if blacksmith_hammer_charge_position is not None:
        origin_x = float(blacksmith_hammer_charge_position[0])
        origin_y = float(blacksmith_hammer_charge_position[1])

    # 안전 가드: 화면 경계 밖에서 스폰되면 다음 프레임에 즉시 폭발(off_screen)하는 문제가 간헐적으로 발생.
    # 특히 플레이어가 오른쪽 벽에 밀착한 상태에서 origin_x = PLAYER.right + 18이 WIDTH를 초과할 수 있음.
    # 투사체 히트박스 반경을 고려해 원점을 화면 안쪽으로 클램핑하여 '제자리 폭발'을 방지한다.
    try:
        margin = max(10, int(BLACKSMITH_HAMMER_SHOCK_PROJECTILE_HITBOX_RADIUS) + 4)
    except Exception:
        margin = 12
    origin_x = min(WIDTH - margin, max(margin, float(origin_x)))
    origin_y = min(HEIGHT - margin, max(margin, float(origin_y)))

    current_ticks = pygame.time.get_ticks()
    projectile = {
        "x": float(origin_x),
        "y": float(origin_y),
        "vx": 0.0,
        "vy": -BLACKSMITH_HAMMER_SHOCK_PROJECTILE_SPEED,
        "stage": stage,
        "life": int(1.5 * FPS),
        "rotation": 0.0,
        "_last_update_frame": frame_counter,
        "_last_update_ms": current_ticks,
    }
    blacksmith_hammer_shock_projectiles.append(projectile)
    if blacksmith_hammer_charge_position is not None:
        sanitized_charge = _sanitize_blacksmith_hammer_position(blacksmith_hammer_charge_position)
        if sanitized_charge is not None:
            blacksmith_hammer_idle_position = sanitized_charge
        else:
            blacksmith_hammer_idle_position = None
    blacksmith_hammer_charge_position = None
    if selected_character_type != "blacksmith":
        blacksmith_hammer_head_surface_point = None

    special_gauge = max(0, special_gauge - cost)
    special_ready = special_gauge >= special_gauge_max

    blacksmith_hammer_available = False
    cooldown_frames = BLACKSMITH_HAMMER_SHOCK_NO_HAMMER_DURATION_BY_STAGE.get(
        stage, BLACKSMITH_HAMMER_SHOCK_NO_HAMMER_DURATION
    )
    blacksmith_hammer_shock_cooldown_timer = cooldown_frames
    blacksmith_hammer_shock_last_stage = stage
    blacksmith_hammer_shock_cooldown_total = cooldown_frames

    blacksmith_hammer_shock_charging = False
    blacksmith_hammer_shock_charge_frames = 0
    blacksmith_hammer_shock_stage = 0

    try:
        if SOUND_BLACKSMITH_HAMMER_THROW:
            play_sound_with_volume(SOUND_BLACKSMITH_HAMMER_THROW)
        elif SOUND_GRENADE:
            play_sound_with_volume(SOUND_GRENADE)
    except Exception:
        pass


def _complete_blacksmith_hammer_cooldown_if_ready():
    """Re-arm the hammer once cooldown has expired and no projectiles remain."""

    global blacksmith_hammer_shock_cooldown_timer, blacksmith_hammer_shock_projectiles
    global blacksmith_hammer_available, blacksmith_hammer_shock_last_stage, blacksmith_hammer_shock_cooldown_total

    if blacksmith_hammer_shock_cooldown_timer <= 0 and not blacksmith_hammer_shock_projectiles:
        if not blacksmith_hammer_available:
            fx_x, fx_y = _get_blacksmith_hammer_effect_center()
            _spawn_blacksmith_hammer_return_fx(fx_x, fx_y)
        blacksmith_hammer_available = True
        blacksmith_hammer_shock_cooldown_timer = 0
        blacksmith_hammer_shock_last_stage = 0
        blacksmith_hammer_shock_cooldown_total = 0

    _debug_blacksmith_hammer_cooldown()


def _debug_blacksmith_hammer_cooldown() -> None:
    """Log remaining cooldown buckets for debugging when enabled."""

    if not DEBUG_BLACKSMITH_HAMMER_COOLDOWN:
        return

    global blacksmith_hammer_cooldown_debug_bucket, blacksmith_hammer_shock_cooldown_timer

    try:
        remaining_frames = int(blacksmith_hammer_shock_cooldown_timer)
    except Exception:
        return

    if remaining_frames <= 0:
        if blacksmith_hammer_cooldown_debug_bucket != 0:
            # print("[DEBUG HAMMER] cooldown finished – hammer ready")
            blacksmith_hammer_cooldown_debug_bucket = 0
        return

    bucket = max(0, math.ceil(remaining_frames / FPS))
    if bucket != blacksmith_hammer_cooldown_debug_bucket:
        seconds = remaining_frames / FPS
        # print(f"[DEBUG HAMMER] cooldown remaining: {seconds:.2f}s ({remaining_frames} frames)")
        blacksmith_hammer_cooldown_debug_bucket = bucket


def _handle_blacksmith_hammer_rock_collision(proj: dict) -> None:
    """Destroy Stage 2 crisis rocks that collide with a hammer projectile."""

    animated_bg = animated_bg_stage2
    if current_stage != 2 or animated_bg is None:
        return

    rocks = getattr(animated_bg, "crisis_rocks", None)
    if not rocks:
        return

    proj_x = float(proj.get("x", 0.0))
    proj_y = float(proj.get("y", 0.0))
    radius = BLACKSMITH_HAMMER_SHOCK_PROJECTILE_HITBOX_RADIUS

    rocks_to_remove: list[dict] = []

    for rock in list(rocks):
        rect = rock.get("collision_rect")
        if rect is None:
            continue

        closest_x = max(rect.left, min(proj_x, rect.right))
        closest_y = max(rect.top, min(proj_y, rect.bottom))
        dx = proj_x - closest_x
        dy = proj_y - closest_y
        if dx * dx + dy * dy > radius * radius:
            continue

        _destroy_stage2_rock_for_blacksmith(rock)
        rocks_to_remove.append(rock)

    for rock in rocks_to_remove:
        try:
            rocks.remove(rock)
        except ValueError:
            pass


def _handle_blacksmith_hammer_tetro_collision(proj: dict) -> None:
    """Stage 7: 해머쇼크 발사체가 테트로미노에 닿으면 증발 처리.

    - 낙하형(falling)과 설치형(installed) 모두 대상.
    - 벽 설치형(wall_generated=True)은 덩어리 전체를 빠른 증발로 전환하고, 충돌 리스트를 즉시 제거.
    - 발사체는 계속 진행(폭발 없음).
    """
    try:
        if current_stage != 7:
            return
        if 'stage7_tetrominoes' not in globals() or not stage7_tetrominoes:
            return
        proj_x = float(proj.get("x", 0.0))
        proj_y = float(proj.get("y", 0.0))
        radius = BLACKSMITH_HAMMER_SHOCK_PROJECTILE_HITBOX_RADIUS

        for mino in list(stage7_tetrominoes):
            state = mino.get('state')
            if state not in ('falling', 'installed'):
                continue
            # 셀 단위 원-사각형 충돌 체크
            hit = False
            for c in mino.get('cells', []) or []:
                rect = c.get('rect')
                if not rect:
                    continue
                closest_x = max(rect.left, min(proj_x, rect.right))
                closest_y = max(rect.top, min(proj_y, rect.bottom))
                dx = proj_x - closest_x
                dy = proj_y - closest_y
                if dx * dx + dy * dy <= radius * radius:
                    hit = True
                    break
            if not hit:
                continue
            # 히트 플래시
            try:
                mino["hit_flash_duration"] = 130
                mino["hit_flash_until"] = pygame.time.get_ticks() + 130
            except Exception:
                pass
            # 벽 생성물은 충돌 리스트 즉시 제거(유령 충돌 방지)
            if mino.get('wall_generated'):
                try:
                    for c in mino.get('cells', []) or []:
                        _remove_wall_cell_rect(c.get('rect'))
                except Exception:
                    pass
            # 빠른 증발 경로로 전환 (대쉬와 동일 처리)
            destroy_stage7_tetromino(mino, by_player=True, by_dash=True)
            break

        # 가드 라인(보스 뒤 1자 블럭)도 동일하게 파괴
        if 'stage7_guard_blocks' in globals() and stage7_guard_blocks:
            for block in list(stage7_guard_blocks):
                state = block.get('state')
                if state not in ('assembling', 'hologram', 'deploy', 'active'):
                    continue
                hit = False
                for c in block.get('cells', []) or []:
                    rect = c.get('rect')
                    if not rect:
                        continue
                    closest_x = max(rect.left, min(proj_x, rect.right))
                    closest_y = max(rect.top, min(proj_y, rect.bottom))
                    dx = proj_x - closest_x
                    dy = proj_y - closest_y
                    if dx * dx + dy * dy <= radius * radius:
                        hit = True
                        break
                if hit:
                    destroy_stage7_guard_block(block, by_player=False)
                    break
    except Exception:
        pass


def _evaporate_single_tetro_cell(mino: dict, cell: dict, *, bullet_dx: float = 0.0, bullet_dy: float = 0.0) -> None:
    """테트로미노의 단일 셀만 증발 처리한다.

    - 벽 생성물(wall_generated)인 경우 충돌 리스트에서도 해당 셀을 제거한다.
    - 시각 효과는 소규모 임팩트 이펙트만 남기고, 미노 전체 상태는 유지한다.
    - 모든 셀이 제거되면 미노 자체를 목록에서 제거한다.
    """
    try:
        # 히트 플래시(짧게)
        mino["hit_flash_duration"] = 130
        mino["hit_flash_until"] = pygame.time.get_ticks() + 130
    except Exception:
        pass

    # 벽 스킬로 생성된 블럭이면 충돌 리스트에서 해당 셀 제거
    try:
        if mino.get("wall_generated") and cell.get("rect"):
            _remove_wall_cell_rect(cell["rect"])
    except Exception:
        pass

    # 소규모 충돌 이펙트 표시
    try:
        cx, cy = cell["rect"].centerx, cell["rect"].centery
        effects_manager.create_impact_effect(int(cx), int(cy), 32, is_player=False)
    except Exception:
        # effects_manager 미사용 버전(속도 벡터 기반)도 시도
        try:
            create_impact_effect(cell["rect"].centerx, cell["rect"].centery, [bullet_dx, bullet_dy], is_player=False)
        except Exception:
            pass

    # 실제 셀 제거(목록에서 제거)
    try:
        if cell in mino.get("cells", []):
            mino["cells"].remove(cell)
    except Exception:
        pass

    # 모든 셀이 제거되면 미노 정리
    try:
        if not mino.get("cells"):
            # 해체 사운드 재생 (셀 모두 제거되어 미노 해체 시)
            try:
                if SOUND_TETRISBREAK:
                    play_sound_with_volume(SOUND_TETRISBREAK)
            except Exception:
                pass
            _maybe_drop_star_for_tetro(mino)
            if mino in stage7_tetrominoes:
                stage7_tetrominoes.remove(mino)
    except Exception:
        pass


def _handle_ak47_tetro_collisions() -> None:
    """스테이지7에서 AK-47 탄환이 테트로미노에 닿았을 때, 닿은 블록 1개만 증발.

    - 낙하/설치 상태의 미노에 대해 셀 단위 충돌을 검사한다.
    - 히트 시 해당 탄환은 소모되며, 미노의 해당 셀만 제거한다.
    - 벽 생성물(wall_generated)은 충돌 리스트에서 해당 셀을 즉시 제거하여 유령 충돌을 방지한다.
    """
    if current_stage != 7:
        return
    if 'stage7_tetrominoes' not in globals() or not stage7_tetrominoes:
        return
    # 코만도 + AK-47 활성 상태가 아니면 스킵
    if selected_character_type != "soldier":
        return
    try:
        ak47 = get_ak47_instance()
    except Exception:
        return
    if not ak47 or not getattr(ak47, "active", False):
        return

    bullets = getattr(ak47, "bullets", [])
    if not bullets:
        return

    remaining: list[dict] = []
    for bullet in bullets:
        bx = float(bullet.get("x", 0.0))
        by = float(bullet.get("y", 0.0))
        bdx = float(bullet.get("dx", 0.0))
        bdy = float(bullet.get("dy", 0.0))
        brect = pygame.Rect(int(bx) - 3, int(by) - 3, 6, 6)

        hit = False
        for mino in list(stage7_tetrominoes):
            state = mino.get("state")
            if state not in ("falling", "installed"):
                continue
            cells = list(mino.get("cells", []))
            for c in cells:
                rect = c.get("rect")
                if not rect:
                    continue
                # 증발 표시가 이미 된 셀은 무시(보수적)
                if c.get("evaporated", False):
                    continue
                if brect.colliderect(rect):
                    _evaporate_single_tetro_cell(mino, c, bullet_dx=bdx, bullet_dy=bdy)
                    hit = True
                    break
            if hit:
                break
        # 가드 블록(보스 뒤 1자 방어 블록)에도 단일 셀 제거 적용
        if (not hit) and 'stage7_guard_blocks' in globals() and stage7_guard_blocks:
            for block in list(stage7_guard_blocks):
                state = block.get('state')
                if state in ('destroying', None):
                    continue
                # 활성 후보 상태만 처리
                if state not in ('assembling', 'hologram', 'deploy', 'active', 'spread'):
                    continue
                for c in list(block.get('cells', [])):
                    rect = c.get('rect')
                    if not rect:
                        continue
                    if brect.colliderect(rect):
                        _evaporate_single_guard_cell(block, c, bullet_dx=bdx, bullet_dy=bdy)
                        hit = True
                        break
                if hit:
                    break
        if not hit:
            remaining.append(bullet)

    # 명중하지 못한 탄환만 유지
    ak47.bullets = remaining


def _evaporate_single_guard_cell(block: dict, cell: dict, *, bullet_dx: float = 0.0, bullet_dy: float = 0.0) -> None:
    """가드 테트로미노(보스 뒤 1자)의 특정 셀만 제거한다."""
    try:
        # 임팩트 이펙트
        try:
            cx, cy = cell["rect"].centerx, cell["rect"].centery
            effects_manager.create_impact_effect(int(cx), int(cy), 28, is_player=False)
        except Exception:
            create_impact_effect(cell["rect"].centerx, cell["rect"].centery, [bullet_dx, bullet_dy], is_player=False)
    except Exception:
        pass

    # 실제 셀 제거
    try:
        if cell in block.get("cells", []):
            block["cells"].remove(cell)
    except Exception:
        pass

    # 모든 셀이 제거되면 블록 정리 및 보상 처리
    try:
        if not block.get("cells"):
            now = pygame.time.get_ticks()
            # 스타 포인트(황금 블럭) 드랍 처리 복제
            try:
                if block.get("golden"):
                    tps = trade_point_system
                    # 마지막 제거된 셀 위치를 사용
                    cx, cy = cell["rect"].centerx, cell["rect"].centery
                    if tps is not None and hasattr(tps, "spawn_star"):
                        tps.spawn_star(int(cx), int(cy), "rainbow_tetro")
            except Exception:
                pass
            # 해체 사운드 재생
            try:
                if SOUND_TETRISBREAK:
                    play_sound_with_volume(SOUND_TETRISBREAK)
                else:
                    play_wall_sound()
            except Exception:
                pass
            # 리스트에서 제거 및 재스폰 스케줄 보정
            try:
                stage7_guard_blocks.remove(block)
            except ValueError:
                pass
            remaining_active = sum(1 for b in stage7_guard_blocks if b.get("state") in ("assembling", "hologram", "deploy", "active"))
            if remaining_active <= 3:
                globals()['stage7_guard_next_trigger_ms'] = now
    except Exception:
        pass


def _destroy_stage2_rock_for_blacksmith(rock: dict) -> None:
    """Apply shared destruction effects when hammer projectiles break rocks."""

    animated_bg = animated_bg_stage2
    if animated_bg is not None:
        try:
            animated_bg.destroy_rock(rock)
        except Exception:
            pass

    rock_size = rock.get("size", 0)
    try:
        if rock_size <= 45:
            play_sound_with_volume(SOUND_STONEBREAK_SMALL)
        elif rock_size <= 65:
            play_sound_with_volume(SOUND_STONEBREAK_MEDIUM)
        else:
            play_sound_with_volume(SOUND_STONEBREAK_LARGE)
    except Exception:
        pass

    if rock.get("is_golden", False):
        trade_points = trade_point_system
        if trade_points is not None:
            rock_x = rock.get("x", 0)
            rock_y = rock.get("fall_y", rock.get("y", 0))
            trade_points.spawn_star(rock_x, rock_y, "golden_rock")
            try:
                coin_sound = pygame.mixer.Sound(resource_path("sounds/coin.wav"))
                play_sound_with_volume(coin_sound)
            except Exception:
                pass


def _advance_blacksmith_hammer_projectile(proj: dict, frames: int = 1) -> bool:
    """Advance a hammer shock projectile; return True while it remains active."""

    global BOSS, BALL, stopwatch_active, stopwatch_timer

    for _ in range(max(1, frames)):
        vy = float(proj.get("vy", 0.0))
        if abs(vy) < 1e-3:
            vy = -BLACKSMITH_HAMMER_SHOCK_PROJECTILE_SPEED
            proj["vy"] = vy
        vx = float(proj.get("vx", 0.0))
        proj["x"] = float(proj.get("x", 0.0)) + vx
        proj["y"] = float(proj.get("y", 0.0)) + vy

        if abs(vx) < 1e-3 and vy != 0.0:
            proj["rotation"] = 0.0
        else:
            proj["rotation"] = (float(proj.get("rotation", 0.0)) + 18.0) % 360

        proj["life"] = int(proj.get("life", 0)) - 1
        if proj["life"] < 0:
            proj["life"] = 0

        if proj.get("ball_hit_cooldown", 0) > 0:
            proj["ball_hit_cooldown"] -= 1

        exploded = False

        if 'BOSS' in globals() and BOSS is not None:
            boss_rect = BOSS
            if boss_rect.collidepoint(int(proj["x"]), int(proj["y"])):
                _trigger_blacksmith_hammer_shock_explosion(int(proj.get("stage", 1) or 1), proj["x"], proj["y"])
                exploded = True

        if (
            not exploded
            and not (stopwatch_active and stopwatch_timer > 0)
            and 'BALL' in globals()
            and BALL is not None
        ):
            ball_centerx, ball_centery = BALL.center
            dx = float(ball_centerx) - float(proj.get("x", ball_centerx))
            dy = float(ball_centery) - float(proj.get("y", ball_centery))
            ball_radius = max(BALL.width, BALL.height) * 0.5
            collision_radius = ball_radius + BLACKSMITH_HAMMER_SHOCK_PROJECTILE_HITBOX_RADIUS
            if dx * dx + dy * dy <= collision_radius * collision_radius and proj.get("ball_hit_cooldown", 0) <= 0:
                _handle_blacksmith_hammer_ball_hit(proj, dx, dy)
                proj["ball_hit_cooldown"] = BLACKSMITH_HAMMER_SHOCK_BALL_HIT_COOLDOWN_FRAMES

        if not exploded:
            _handle_blacksmith_hammer_rock_collision(proj)
            # Stage 7: 해머쇼크 발사체로 테트로미노 증발 처리
            _handle_blacksmith_hammer_tetro_collision(proj)
            off_screen = (
                proj["x"] <= 0
                or proj["x"] >= WIDTH
                or proj["y"] <= 0
                or proj["y"] >= HEIGHT
            )
            if off_screen or proj["life"] <= 0:
                clamped_x = max(10, min(WIDTH - 10, proj["x"]))
                clamped_y = max(10, min(HEIGHT - 10, proj["y"]))
                _trigger_blacksmith_hammer_shock_explosion(int(proj.get("stage", 1) or 1), clamped_x, clamped_y)
                exploded = True

        if exploded:
            return False

    return True


def _sync_blacksmith_hammer_projectiles_to_frame(target_frame: int):
    """Catch projectiles up to the provided frame if the main update was skipped."""

    global blacksmith_hammer_shock_projectiles, blacksmith_hammer_last_update_frame
    global blacksmith_hammer_shock_cooldown_timer, blacksmith_hammer_last_update_ms
    global blacksmith_hammer_cooldown_remainder_ms

    current_ticks = pygame.time.get_ticks()

    if (
        target_frame <= blacksmith_hammer_last_update_frame
        and current_ticks <= blacksmith_hammer_last_update_ms
    ):
        return

    frame_deficit = max(0, target_frame - blacksmith_hammer_last_update_frame)

    frame_duration_ms = 1000.0 / FPS
    elapsed_ms = 0.0
    if current_ticks > blacksmith_hammer_last_update_ms:
        elapsed_ms = float(current_ticks - blacksmith_hammer_last_update_ms)

    total_ms = elapsed_ms + blacksmith_hammer_cooldown_remainder_ms
    time_based_additional = 0
    if total_ms >= frame_duration_ms:
        time_based_frames = int(total_ms // frame_duration_ms)
        blacksmith_hammer_cooldown_remainder_ms = total_ms - (time_based_frames * frame_duration_ms)
        if time_based_frames > 1:
            time_based_additional = time_based_frames - 1
    else:
        blacksmith_hammer_cooldown_remainder_ms = total_ms

    frame_based_additional = 0
    if frame_deficit > 1:
        frame_based_additional = frame_deficit - 1

    additional_cooldown_frames = max(time_based_additional, frame_based_additional)
    if additional_cooldown_frames == frame_based_additional and frame_based_additional > time_based_additional:
        blacksmith_hammer_cooldown_remainder_ms = 0.0

    new_projectiles: list[dict] = []
    for proj in blacksmith_hammer_shock_projectiles:
        last_frame = int(proj.get("_last_update_frame", blacksmith_hammer_last_update_frame))
        frames_pending = max(0, target_frame - last_frame)
        if frames_pending == 0 and current_ticks > blacksmith_hammer_last_update_ms:
            last_ms = int(proj.get("_last_update_ms", blacksmith_hammer_last_update_ms))
            elapsed_ms = current_ticks - last_ms
            frames_from_time = int(elapsed_ms * FPS / 1000)
            frames_pending = max(0, frames_from_time)
        if frames_pending > 0:
            if not _advance_blacksmith_hammer_projectile(proj, frames_pending):
                continue
            if 'frame_counter' in globals():
                proj["_last_update_frame"] = target_frame
            proj["_last_update_ms"] = current_ticks
        new_projectiles.append(proj)

    blacksmith_hammer_shock_projectiles = new_projectiles

    if additional_cooldown_frames > 0 and blacksmith_hammer_shock_cooldown_timer > 0:
        blacksmith_hammer_shock_cooldown_timer = max(0, blacksmith_hammer_shock_cooldown_timer - additional_cooldown_frames)

    blacksmith_hammer_last_update_frame = target_frame
    blacksmith_hammer_last_update_ms = current_ticks
    _complete_blacksmith_hammer_cooldown_if_ready()


def _check_boss_crack_collision(boss_rect, crack):
    """Check if boss paddle collides with a ground crack using line-rectangle collision"""
    global boss_crack_ignore_until

    current_ticks = pygame.time.get_ticks()

    disabled_until = crack.get("boss_contact_disabled_until", 0)
    if disabled_until and current_ticks < disabled_until:
        return False
    if disabled_until and current_ticks >= disabled_until:
        crack.pop("boss_contact_disabled_until", None)

    if current_ticks < boss_crack_ignore_until:
        return False
        
    # Check if crack has any length left (completely broken cracks should not collide)
    if crack.get("length", 0) <= 0 or crack.get("segments_remaining", 0) <= 0:
        return False
        
    # Create a line segment for the crack
    line_start_x = crack.get("x", 0.0)
    line_start_y = crack.get("y", 0.0)
    line_end_x = line_start_x + math.cos(crack.get("angle", 0.0)) * crack.get("length", 0.0)
    line_end_y = line_start_y + math.sin(crack.get("angle", 0.0)) * crack.get("length", 0.0)

    # 더 간단하고 확실한 충돌 감지
    # 크랙의 X 범위
    crack_min_x = min(line_start_x, line_end_x)
    crack_max_x = max(line_start_x, line_end_x)
    
    # 보스와 크랙의 X 범위 겹침 검사 (여유를 조금만 둠)
    margin = 15  # 기존 20에서 15로 더 줄임
    if boss_rect.right < crack_min_x - margin or boss_rect.left > crack_max_x + margin:
        return False
    
    # Y 축 검사 (크랙은 보통 바닥 근처에 있음)
    crack_min_y = min(line_start_y, line_end_y)
    crack_max_y = max(line_start_y, line_end_y)
    
    # 보스 패들과 크랙의 Y 범위가 합리적인 거리 내에 있는지 확인
    vertical_margin = 25  # 기존 30에서 25로 줄임
    if abs(boss_rect.centery - (crack_min_y + crack_max_y) / 2) > vertical_margin:
        return False

    # 간단하고 확실한 충돌 감지
    # 크랙을 두꺼운 사각형으로 취급하여 충돌 검사
    thickness = 20  # 충돌 감지용 두께를 줄임
    
    # 크랙의 바운딩 박스 생성 (두께 포함)
    crack_rect = pygame.Rect(
        crack_min_x - thickness // 2,
        crack_min_y - thickness // 2,  
        crack_max_x - crack_min_x + thickness,
        crack_max_y - crack_min_y + thickness
    )
    
    # 보스와 크랙 바운딩 박스의 직접 충돌 검사
    collision_detected = boss_rect.colliderect(crack_rect)
    
    if collision_detected:
        # 디버그 비활성화 - 너무 많은 로그 출력 방지
        # if ENABLE_CRACK_TIMING_DEBUG:
        #     now_ms = pygame.time.get_ticks()
        #     remaining = crack.get('segments_remaining', 0)
        #     print(f"[CRACK DEBUG] collide t={now_ms} boss=({boss_rect.x},{boss_rect.y}) seg={remaining} len={crack.get('length', 0):.1f}")
        # else:
        #     print(f"[COLLISION] Boss collides with crack!")
        #     print(f"  Boss: ({boss_rect.x}, {boss_rect.y}, {boss_rect.width}x{boss_rect.height})")
        #     print(f"  Crack: length={crack.get('length', 0):.1f}, segments={crack.get('segments_remaining', 0)}")
        return True
    
    # 충돌이 없으면 False 반환
    return False


def _check_path_blocked_by_cracks(current_x, target_x, boss_width, boss_y, boss_height):
    """Check if the path from current position to target position is blocked by any crack"""
    global blacksmith_ground_cracks
    
    if 'blacksmith_ground_cracks' not in globals() or not blacksmith_ground_cracks:
        return False

    # Only check cracks that are reasonably close to the movement path
    path_min_x = min(current_x, target_x) - boss_width // 2
    path_max_x = max(current_x + boss_width, target_x + boss_width) + boss_width // 2
    movement_distance = abs(target_x - current_x)
    
    # If movement distance is very large, only check cracks near the current position
    # This prevents distant cracks from affecting the AI
    proximity_threshold = 200  # Only check cracks within 200 pixels of the path
    
    relevant_cracks = []
    for crack in blacksmith_ground_cracks:
        crack_x = crack.get("x", 0.0)
        crack_length = crack.get("length", 0.0)
        crack_angle = crack.get("angle", 0.0)
        crack_end_x = crack_x + math.cos(crack_angle) * crack_length
        
        # Get crack's X range
        crack_min_x = min(crack_x, crack_end_x)
        crack_max_x = max(crack_x, crack_end_x)
        
        # Only consider cracks that are:
        # 1. Within the path's X range (with some margin)
        # 2. Close to the boss's current position (for large movements)
        crack_in_path_range = not (crack_max_x < path_min_x - 50 or crack_min_x > path_max_x + 50)
        
        if movement_distance > proximity_threshold:
            # For long movements, only check cracks close to current position
            crack_distance_from_boss = min(
                abs(crack_min_x - current_x),
                abs(crack_max_x - current_x),
                abs((crack_min_x + crack_max_x) / 2 - current_x)
            )
            crack_close_to_boss = crack_distance_from_boss <= proximity_threshold
        else:
            # For short movements, check all cracks in path range
            crack_close_to_boss = True
        
        if crack_in_path_range and crack_close_to_boss:
            relevant_cracks.append(crack)

    # If no relevant cracks, path is clear
    if not relevant_cracks:
        return False

    movement_distance = abs(target_x - current_x)
    if movement_distance < 1e-3:
        return False

    contact_margin = max(12, int(boss_width * 0.6))
    max_sample_gap = max(10.0, contact_margin * 0.5)
    steps = max(5, int(math.ceil(movement_distance / max_sample_gap)))
    direction = 1 if target_x >= current_x else -1

    # Check multiple points along the path against relevant cracks only
    for i in range(1, steps + 1):
        t = i / steps
        check_x = current_x + (target_x - current_x) * t
        test_rect = pygame.Rect(check_x, boss_y, boss_width, boss_height)

        blocked_here = False
        for crack in relevant_cracks:
            if _check_boss_crack_collision(test_rect, crack):
                bounding_rect = _get_crack_bounding_rect(crack)
                if direction > 0:
                    boss_front = check_x + boss_width
                    crack_front = bounding_rect.left
                    distance_to_crack_front = crack_front - boss_front
                else:
                    boss_front = check_x
                    crack_front = bounding_rect.right
                    distance_to_crack_front = boss_front - crack_front

                distance_to_crack_front = max(0.0, distance_to_crack_front)
                distance_to_target = abs(target_x - check_x)

                # Allow the boss to close in and actually collide when the crack is already near the target
                if distance_to_crack_front <= contact_margin or distance_to_target <= contact_margin:
                    continue

                blocked_here = True
                break

        if blocked_here:
            return True

    return False


def _slide_boss_toward_crack_edge(current_x: float, target_x: float, crack: dict, boss_width: int) -> float:
    """Clamp boss movement so it stops right against the crack edge based on travel direction."""

    bounding_rect = _get_crack_bounding_rect(crack)
    contact_padding = max(2, boss_width // 8)

    if target_x >= current_x:
        desired = bounding_rect.left - boss_width + contact_padding
        desired = min(desired, target_x)
        desired = max(desired, current_x)
    else:
        desired = bounding_rect.right - contact_padding
        desired = max(desired, target_x)
        desired = min(desired, current_x)

    # Clamp within arena bounds
    desired = max(0, min(WIDTH - boss_width, desired))
    return desired


def _is_boss_movement_valid(new_x):
    """Check if the boss can move to the new X position (considers cracks)"""
    global BOSS, blacksmith_ground_cracks
    
    if 'blacksmith_ground_cracks' not in globals() or not blacksmith_ground_cracks:
        return True
    
    # 보스는 크랙을 자유롭게 지나갈 수 있어야 함 - 이동 제한을 제거
    # 크랙 충돌은 시각적 효과와 디버그 로그만 출력하고 이동을 막지 않음
    return True


def _boss_get_crack_collision(boss_rect: pygame.Rect, apply_response: bool = False):
    """Return the first crack colliding with the boss rect. Optionally apply contact response."""
    global blacksmith_ground_cracks

    if 'blacksmith_ground_cracks' not in globals() or not blacksmith_ground_cracks:
        return None

    for crack in list(blacksmith_ground_cracks):
        bounding_rect = _get_crack_bounding_rect(crack)

        if _should_skip_crack_for_rect(crack, boss_rect, bounding_rect):
            continue

        if bounding_rect.left - boss_rect.right > BLACKSMITH_GROUND_CRACK_DETECTION_RANGE:
            continue
        if boss_rect.left - bounding_rect.right > BLACKSMITH_GROUND_CRACK_DETECTION_RANGE:
            continue
        if _check_boss_crack_collision(boss_rect, crack):
            if apply_response:
                _handle_boss_crack_hit(crack, boss_rect)
                # After handling crack hit, don't immediately recheck collision
                # Let the boss movement system handle the resolution
                if crack not in blacksmith_ground_cracks:
                    continue
            return crack

    return None


def _get_crack_bounding_rect(crack: dict) -> pygame.Rect:
    line_start_x = crack.get("x", 0.0)
    line_start_y = crack.get("y", 0.0)
    length = crack.get("length", 0.0)
    angle = crack.get("angle", 0.0)
    line_end_x = line_start_x + math.cos(angle) * length
    line_end_y = line_start_y + math.sin(angle) * length
    boss_padding = crack.get("boss_padding", BLACKSMITH_GROUND_CRACK_BOSS_PADDING)
    thickness = crack.get("thickness", 2) + boss_padding

    min_x = min(line_start_x, line_end_x) - thickness
    max_x = max(line_start_x, line_end_x) + thickness
    min_y = min(line_start_y, line_end_y) - thickness
    max_y = max(line_start_y, line_end_y) + thickness

    width = max(1, int(math.ceil(max_x - min_x)))
    height = max(1, int(math.ceil(max_y - min_y)))

    return pygame.Rect(int(math.floor(min_x)), int(math.floor(min_y)), width, height)


def _should_skip_crack_for_rect(crack: dict, rect: pygame.Rect, bounding_rect: pygame.Rect | None = None) -> bool:
    """Return True if the crack is sufficiently far from rect to ignore for pathing/collision."""

    if bounding_rect is None:
        bounding_rect = _get_crack_bounding_rect(crack)

    horizontal_gap = 0
    if rect.right < bounding_rect.left:
        horizontal_gap = bounding_rect.left - rect.right
    elif rect.left > bounding_rect.right:
        horizontal_gap = rect.left - bounding_rect.right

    if horizontal_gap > BLACKSMITH_GROUND_CRACK_APPROACH_DISTANCE:
        return True

    vertical_gap = abs(rect.centery - bounding_rect.centery)
    if vertical_gap > BLACKSMITH_GROUND_CRACK_APPROACH_VERTICAL_MARGIN:
        return True

    return False


def _force_clear_nearest_crack(boss_rect: pygame.Rect) -> bool:
    """Force remove the nearest crack around the boss to prevent stuck."""
    if 'blacksmith_ground_cracks' not in globals() or not blacksmith_ground_cracks:
        return False

    # First try to find cracks that are directly colliding with the boss
    colliding_cracks = []
    nearby_cracks = []

    for crack in list(blacksmith_ground_cracks):
        # Check if this crack is actually colliding with the boss
        if _check_boss_crack_collision(boss_rect, crack):
            colliding_cracks.append(crack)
        else:
            # Check if crack is nearby (within a larger margin)
            bounding_rect = _get_crack_bounding_rect(crack)
            distance_x = min(abs(boss_rect.left - bounding_rect.right), abs(boss_rect.right - bounding_rect.left))
            distance_y = min(abs(boss_rect.top - bounding_rect.bottom), abs(boss_rect.bottom - bounding_rect.top))
            total_distance = distance_x + distance_y
            
            if total_distance <= 60:  # Close proximity threshold
                nearby_cracks.append((crack, total_distance))

    removed_count = 0
    
    # Remove all directly colliding cracks first
    for crack in colliding_cracks:
        _shatter_blacksmith_crack(crack, play_sound=False)
        removed_count += 1
    
    # If no colliding cracks but boss is still stuck, remove nearest cracks
    if removed_count == 0 and nearby_cracks:
        # Sort by distance and remove the closest one
        nearby_cracks.sort(key=lambda x: x[1])
        nearest_crack, _ = nearby_cracks[0]
        _shatter_blacksmith_crack(nearest_crack, play_sound=False)
        removed_count += 1
    
    if removed_count > 0:
        print(f"[CRACK STUCK] Removed {removed_count} crack(s) to free boss")
        return True

    return False


def _schedule_next_crack_auto_break(crack: dict, base_time_ms: int | None = None):
    """Schedule when this crack should naturally lose another segment."""

    if base_time_ms is None:
        base_time_ms = pygame.time.get_ticks()

    interval_min = BLACKSMITH_GROUND_CRACK_AUTO_BREAK_INTERVAL_MIN_MS
    interval_max = BLACKSMITH_GROUND_CRACK_AUTO_BREAK_INTERVAL_MAX_MS
    if interval_max < interval_min:
        interval_max = interval_min

    next_ms = base_time_ms + random.randint(interval_min, interval_max)
    crack["auto_break_next_ms"] = next_ms


def _decay_blacksmith_crack_segment(
    crack: dict,
    segments: int = 1,
    *,
    spawn_particles: bool = True,
    play_sound: bool = False,
) -> bool:
    """Reduce the crack segment count and update its visuals. Returns True if still exists."""

    if crack not in blacksmith_ground_cracks:
        return False

    if segments <= 0:
        return crack in blacksmith_ground_cracks

    segments_total = max(1, crack.get("segments_total") or 1)
    remaining = crack.get("segments_remaining", segments_total)
    if remaining <= 0:
        return False

    new_remaining = max(0, remaining - segments)
    crack["segments_remaining"] = new_remaining

    base_length = crack.get("initial_length", crack.get("length", 0.0))
    ratio = 0.0
    if segments_total > 0:
        ratio = max(0.0, (new_remaining / float(segments_total)) - BLACKSMITH_GROUND_CRACK_RATIO_OFFSET)
    crack["length"] = max(0.0, base_length * ratio)
    # 시각적 길이가 너무 짧아져 조기 파괴되는 것을 방지
    # (의도: 세그먼트가 모두 소모될 때까지는 파괴되지 않도록 유지)
    if crack["length"] <= BLACKSMITH_GROUND_CRACK_REMOVE_LENGTH and new_remaining > 0:
        crack["length"] = BLACKSMITH_GROUND_CRACK_REMOVE_LENGTH + 1.0

    base_thickness = crack.get("base_thickness", crack.get("thickness", 1))
    initial_thickness = max(1, int(round(base_thickness * BLACKSMITH_GROUND_CRACK_RANGE_SCALE)))
    thickness_ratio = max(0.1, ratio)
    crack["thickness"] = max(1, int(round(initial_thickness * thickness_ratio)))
    crack["boss_padding"] = max(
        BLACKSMITH_GROUND_CRACK_MIN_PADDING,
        int(BLACKSMITH_GROUND_CRACK_BOSS_PADDING * max(0.15, thickness_ratio)),
    )

    if "sub_cracks" in crack:
        max_pos = min(1.0, ratio + 0.05)
        crack["sub_cracks"] = [sub for sub in crack["sub_cracks"] if sub.get("pos", 0.0) <= max_pos]

    if spawn_particles:
        try:
            fragment_base = 4 + segments * 2
            origin_x = crack.get("x", 0.0)
            origin_y = crack.get("y", 0.0)
            for _ in range(fragment_base):
                angle = random.uniform(0, math.pi * 2)
                speed = random.uniform(1.5, 4.0)
                fragment = {
                    "x": origin_x,
                    "y": origin_y,
                    "vx": math.cos(angle) * speed,
                    "vy": math.sin(angle) * speed,
                    "life": random.randint(12, 24),
                    "color": (120, 120, 130),
                    "size": random.randint(1, 3),
                }
                blacksmith_hammer_shock_particles.append(fragment)
        except Exception:
            pass

    # Avoid double-playing the shatter sound: only play decay audio if crack remains.
    if play_sound and new_remaining > 0 and crack.get("length", 0.0) > BLACKSMITH_GROUND_CRACK_REMOVE_LENGTH:
        try:
            play_sound_with_volume(SOUND_STONEBREAK_SMALL)
        except Exception:
            pass

    if new_remaining <= 0 or crack.get("length", 0.0) <= BLACKSMITH_GROUND_CRACK_REMOVE_LENGTH:
        _shatter_blacksmith_crack(crack, play_sound=play_sound)
        return False

    return crack in blacksmith_ground_cracks


def _handle_blacksmith_hammer_ball_hit(projectile: dict, dx: float, _dy: float):
    """Push the ball when the hammer projectile passes through without detonating."""

    global BALL, ball_vel, last_hit_by, player_collision_handled, game_vars

    if 'BALL' not in globals() or BALL is None:
        return

    stage = max(1, int(projectile.get("stage", 1) or 1))
    impact_x = float(BALL.centerx)
    impact_y = float(BALL.centery)

    # Determine push direction relative to projectile travel or fallback to player position
    if abs(dx) < 1e-3:
        try:
            player_x = PLAYER.centerx  # type: ignore[name-defined]
        except Exception:
            player_x = impact_x
        horizontal_dir = 1 if impact_x >= player_x else -1
    else:
        horizontal_dir = 1 if dx >= 0 else -1

    # Apply horizontal and vertical velocity adjustments
    try:
        current_vx = float(ball_vel[0])
        current_vy = float(ball_vel[1])
    except Exception:
        current_vx = 0.0
        current_vy = 0.0

    stage_scale = 1.0 + 0.25 * max(0, stage - 1)
    boosted_vx = current_vx * BLACKSMITH_HAMMER_SHOCK_BALL_HORIZONTAL_DECAY + horizontal_dir * BLACKSMITH_HAMMER_SHOCK_BALL_HORIZONTAL_BOOST * stage_scale
    speed_upward = max(
        BLACKSMITH_HAMMER_SHOCK_BALL_VERTICAL_MIN_SPEED * stage_scale,
        abs(current_vy) * BLACKSMITH_HAMMER_SHOCK_BALL_VERTICAL_DECAY,
    )

    ball_vel[0] = boosted_vx
    ball_vel[1] = -speed_upward

    # Mark the player as the last hitter so scoring/AI respond correctly
    last_hit_by = "player"
    try:
        game_vars.ball.last_hit_by = "player"
    except Exception:
        pass
    player_collision_handled = True

    # Impact particles to emphasize the hit
    try:
        effects_manager.spawn_star_particles(int(impact_x), int(impact_y), count=8 + stage * 4)
    except Exception:
        pass

def _shatter_blacksmith_crack(crack: dict, play_sound: bool = True):
    """Fully destroy a crack, spawning final fragments and optionally playing sound."""
    global blacksmith_ground_cracks, blacksmith_hammer_shock_particles

    if crack not in blacksmith_ground_cracks:
        return

    segments_total = max(1, crack.get("segments_total") or 1)
    origin_x = crack.get("x", 0.0)
    origin_y = crack.get("y", 0.0)

    try:
        fragment_count = 12 + segments_total * 2
        for _ in range(fragment_count):
            angle = random.uniform(0, math.pi * 2)
            speed = random.uniform(3, 7)
            fragment = {
                "x": origin_x,
                "y": origin_y,
                "vx": math.cos(angle) * speed,
                "vy": math.sin(angle) * speed,
                "life": random.randint(20, 40),
                "color": (150, 150, 160),
                "size": random.randint(2, 5)
            }
            blacksmith_hammer_shock_particles.append(fragment)
    except Exception:
        pass

    if play_sound:
        try:
            play_sound_with_volume(SOUND_STONEBREAK_SMALL)
        except Exception:
            pass

    try:
        blacksmith_ground_cracks.remove(crack)
    except ValueError:
        pass


def _clear_blacksmith_cracks_with_shatter(play_sound: bool = True):
    """Destroy every remaining crack with shatter effects."""
    if 'blacksmith_ground_cracks' not in globals() or not blacksmith_ground_cracks:
        return

    sound_available = play_sound
    for crack in list(blacksmith_ground_cracks):
        _shatter_blacksmith_crack(crack, play_sound=sound_available)
        sound_available = False  # 한 번만 사운드 재생


def _update_boss_crack_stuck_state(can_move: bool, boss_rect: pygame.Rect):
    global boss_crack_stuck_timer, boss_crack_last_release
    global boss_crack_ignore_until

    if can_move:
        boss_crack_stuck_timer = 0
        return

    current_time = pygame.time.get_ticks()
    if current_time < boss_crack_ignore_until:
        boss_crack_stuck_timer = 0
        return

    if boss_knockback_timer > 0:
        boss_crack_stuck_timer = 0
        return

    recent_hit_time = boss_crack_recent_hit_time
    if current_time - recent_hit_time < BLACKSMITH_GROUND_CRACK_STUCK_CLEAR_DELAY_MS:
        boss_crack_stuck_timer = 0
        return

    boss_crack_stuck_timer += 1

    if (
        boss_crack_stuck_timer >= BLACKSMITH_GROUND_CRACK_STUCK_FREE_FRAMES
        and current_time - boss_crack_last_release > BLACKSMITH_GROUND_CRACK_STUCK_CLEAR_COOLDOWN_MS
    ):
        if boss_crack_stuck_timer == BLACKSMITH_GROUND_CRACK_STUCK_FREE_FRAMES:
            print(f"[CRACK STUCK] timer={boss_crack_stuck_timer}, rect={boss_rect}")
        if _force_clear_nearest_crack(boss_rect):
            boss_crack_stuck_timer = 0
            boss_crack_last_release = current_time
            if 'BOSS' in globals() and BOSS is not None:
                direction = 1 if boss_rect.centerx >= BOSS.centerx else -1
                BOSS.x += direction * 8
                BOSS.x = max(0, min(WIDTH - BOSS.width, BOSS.x))
            boss_crack_ignore_until = current_time + BLACKSMITH_GROUND_CRACK_BOSS_IGNORE_MS
            print("[CRACK STUCK] Force-cleared nearest crack")


def _handle_boss_crack_hit(crack: dict, boss_rect: pygame.Rect):
    """Apply breakage and knockback when the boss collides with a crack."""
    global blacksmith_ground_cracks, blacksmith_hammer_shock_particles, boss_crack_ignore_until

    cooldown = crack.get("boss_touch_cooldown", 0)
    if cooldown > 0:
        return

    line_start_x = crack.get("x", boss_rect.centerx)
    current_length = crack.get("length", 0.0)
    angle = crack.get("angle", 0.0)
    line_end_x = line_start_x + math.cos(angle) * current_length
    crack_center_x = (line_start_x + line_end_x) * 0.5

    segments_total = max(1, crack.get("segments_total") or 1)
    segments_remaining = crack.get("segments_remaining", segments_total)

    debug_enabled = ENABLE_CRACK_TIMING_DEBUG
    now_ms = pygame.time.get_ticks() if debug_enabled else 0
    if debug_enabled:
        last_hit = boss_crack_recent_hit_time
        delta_ms = now_ms - last_hit if last_hit else None
        print(f"[CRACK DEBUG] hit_start t={now_ms}Δ{delta_ms} seg={segments_remaining}/{segments_total} len={current_length:.1f}")

    if segments_remaining <= 0:
        return

    break_min = min(segments_remaining, BLACKSMITH_GROUND_CRACK_BOSS_BREAK_MIN)
    break_max = min(segments_remaining, BLACKSMITH_GROUND_CRACK_BOSS_BREAK_MAX)
    if break_min <= 0:
        return
    if break_max < break_min:
        break_max = break_min
    segments_break = random.randint(break_min, break_max)
    # 보스 충돌 시 크랙 제거량을 50% 감소 (최소 1 세그먼트는 유지)
    try:
        reduced = int(math.ceil(segments_break * 0.5))
    except Exception:
        reduced = (segments_break + 1) // 2  # 예비: 올림 대체
    segments_break = max(1, reduced)
    new_remaining = max(0, segments_remaining - segments_break)
    crack["segments_remaining"] = new_remaining

    base_length = crack.get("initial_length", crack.get("length", 0))
    ratio = 0.0
    if segments_total > 0:
        base_ratio = new_remaining / float(segments_total)
        ratio = max(0.0, base_ratio - BLACKSMITH_GROUND_CRACK_RATIO_OFFSET)
    crack["length"] = max(0.0, base_length * ratio)

    if debug_enabled:
        print(f"[CRACK DEBUG] break={segments_break} remaining={new_remaining} ratio={ratio:.2f} len->{crack['length']:.1f}")

    base_thickness = crack.get("base_thickness", crack.get("thickness", 1))
    initial_thickness = max(1, int(round(base_thickness * BLACKSMITH_GROUND_CRACK_RANGE_SCALE)))
    thickness_ratio = max(0.1, ratio)
    crack["thickness"] = max(1, int(round(initial_thickness * thickness_ratio)))
    crack["boss_padding"] = max(
        BLACKSMITH_GROUND_CRACK_MIN_PADDING,
        int(BLACKSMITH_GROUND_CRACK_BOSS_PADDING * max(0.15, thickness_ratio)),
    )
    crack["boss_touch_cooldown"] = BLACKSMITH_GROUND_CRACK_BOSS_HIT_COOLDOWN

    if new_remaining <= max(1, segments_total // 2):
        crack["boss_contact_disabled_until"] = pygame.time.get_ticks() + BLACKSMITH_GROUND_CRACK_PASS_THROUGH_MS
        if debug_enabled:
            print(f"[CRACK DEBUG] disable_until={crack['boss_contact_disabled_until']} remaining={new_remaining}")
    
    # If crack is completely destroyed, mark it for removal
    if new_remaining <= 0 or crack["length"] <= 0:
        # Ensure boss can pass through completely broken cracks
        crack["boss_contact_disabled_until"] = pygame.time.get_ticks() + 5000  # 5 seconds
        crack["segments_remaining"] = 0
        crack["length"] = 0

    if "sub_cracks" in crack:
        max_pos = min(1.0, ratio + 0.05)
        crack["sub_cracks"] = [sub for sub in crack["sub_cracks"] if sub.get("pos", 0.0) <= max_pos]

    # Spawn fragment particles to visualize damage
    try:
        fragment_base = 8 + segments_break * 4
        for _ in range(fragment_base):
            angle = random.uniform(0, math.pi * 2)
            speed = random.uniform(2, 6)
            fragment = {
                "x": boss_rect.centerx,
                "y": boss_rect.bottom,
                "vx": math.cos(angle) * speed,
                "vy": math.sin(angle) * speed,
                "life": random.randint(15, 30),
                "color": (120, 120, 130),
                "size": random.randint(2, 4)
            }
            blacksmith_hammer_shock_particles.append(fragment)
    except Exception:
        pass

    try:
        play_sound_with_volume(SOUND_STONEBREAK_SMALL)
    except Exception:
        pass

    # Apply knockback to the boss
    try:
        current_timer = boss_knockback_timer
        knockback_frames = max(1, BLACKSMITH_GROUND_CRACK_BOSS_KNOCKBACK_FRAMES + segments_break * BLACKSMITH_GROUND_CRACK_BOSS_KNOCKBACK_FRAME_BONUS)
        globals()["boss_knockback_timer"] = knockback_frames
        delta_x = boss_rect.centerx - crack_center_x
        if abs(delta_x) < 1.0:
            direction = random.choice([-1, 1])
        else:
            direction = 1 if delta_x > 0 else -1

        space_left = boss_rect.left
        space_right = WIDTH - boss_rect.right
        if direction > 0 and space_right <= BLACKSMITH_GROUND_CRACK_BOUNDARY_MARGIN:
            direction = -1
        elif direction < 0 and space_left <= BLACKSMITH_GROUND_CRACK_BOUNDARY_MARGIN:
            direction = 1

        # 요청사항: 크랙 접촉 시 보스 넉백 '거리'를 2배로 강화
        # 거리 = 즉시 밀기(push) + 넉백 속도 * 지속프레임 이므로
        # 속도 성분을 2배로 스케일링한다.
        crack_knockback = compute_knockback_magnitude("hammer_shock_crack") * 2.0
        _apply_boss_knockback_velocity(direction * crack_knockback)
        globals()["boss_knockback_active"] = False
        globals()["boss_knockback_offset_x"] = 0
        globals()["boss_knockback_offset_y"] = 0

        boss_obj = BOSS
        if boss_obj is not None:
            # 즉시 밀기 거리도 2배로 증대해 체감 이동 거리를 정확히 2배 수준으로 맞춘다.
            push_distance = _scale_knockback(BLACKSMITH_GROUND_CRACK_BOSS_IMMEDIATE_PUSH) * 2.0
            if direction > 0:
                push_distance = min(push_distance, max(0, WIDTH - boss_obj.right))
            else:
                push_distance = min(push_distance, max(0, boss_obj.left))
            boss_obj.x += direction * push_distance
            boss_obj.x = max(0, min(WIDTH - boss_obj.width, boss_obj.x))
        current_ticks = pygame.time.get_ticks()
        boss_crack_ignore_until = current_ticks + BLACKSMITH_GROUND_CRACK_BOSS_IGNORE_MS
        globals()["boss_crack_recent_hit_time"] = current_ticks
    except Exception:
        pass

    impact_x = crack.get("x", crack_center_x)
    impact_y = crack.get("y", boss_rect.centery)
    neighbor_radius_sq = (BLACKSMITH_GROUND_CRACK_REMOVE_LENGTH * 2) ** 2
    for other in list(blacksmith_ground_cracks):
        if other is crack:
            continue
        dx = impact_x - other.get("x", impact_x)
        dy = impact_y - other.get("y", impact_y)
        if dx * dx + dy * dy <= neighbor_radius_sq:
            _decay_blacksmith_crack_segment(other, segments=1, spawn_particles=False, play_sound=False)


def _trigger_blacksmith_hammer_shock_explosion(stage: int, centerx: float, centery: float):
    global BOSS, blacksmith_hammer_explosions
    global SOUND_BLACKSMITH_HAMMER_EXPLOSION, SOUND_GRENADE
    global boss_health_stages, boss_current_health, boss_max_health
    global stage6_boss_hit_timer, stage6_boss_hit_flash, SOUND_STAGE6_BOSS_HIT
    resolved_stage = max(1, stage)

    radius = BLACKSMITH_HAMMER_SHOCK_BASE_RADIUS
    if resolved_stage == 2:
        radius *= BLACKSMITH_HAMMER_SHOCK_STAGE2_RADIUS_SCALE
    elif resolved_stage >= 3:
        radius *= BLACKSMITH_HAMMER_SHOCK_STAGE3_RADIUS_SCALE
    stage_multiplier = 1.0 + BLACKSMITH_HAMMER_SHOCK_CRACK_SCALE_STEP * max(0, resolved_stage - 1)

    render_centerx, render_centery = _clamp_blacksmith_hammer_explosion_center(centerx, centery, radius)

    try:
        if SOUND_BLACKSMITH_HAMMER_EXPLOSION:
            play_sound_with_volume(SOUND_BLACKSMITH_HAMMER_EXPLOSION)
        elif SOUND_GRENADE:
            play_sound_with_volume(SOUND_GRENADE)
    except Exception:
        pass
    visual_centery = max(12.0, render_centery - BLACKSMITH_HAMMER_SHOCK_EXPLOSION_VISUAL_OFFSET)
    contact_adjustment = render_centery - centery
    if contact_adjustment > 1.0:
        impact_y = max(12.0, min(render_centery - radius * 0.55, render_centery - 18.0))
        try:
            effects_manager.spawn_star_particles(int(centerx), int(impact_y), count=6 + resolved_stage * 2)
            effects_manager.spawn_star_particles(int(centerx), int(impact_y + 6), count=3 + resolved_stage)
        except Exception:
            pass

    try:
        explosion_entry = _create_blacksmith_hammer_explosion(
            resolved_stage,
            render_centerx,
            visual_centery,
            radius,
        )
        blacksmith_hammer_explosions.append(explosion_entry)
    except Exception:
        pass

    # Stage 7: 폭발 반경 내 모든 테트로미노를 증발 처리
    try:
        if current_stage == 7:
            radius_sq = radius * radius
            if 'stage7_tetrominoes' in globals() and stage7_tetrominoes:
                for mino in list(stage7_tetrominoes):
                    if mino.get('state') in ('destroying', 'evaporating'):
                        continue
                    hit = False
                    for c in mino.get('cells', []) or []:
                        rect = c.get('rect')
                        if not rect:
                            continue
                        closest_x = max(rect.left, min(centerx, rect.right))
                        closest_y = max(rect.top, min(centery, rect.bottom))
                        dx = centerx - closest_x
                        dy = centery - closest_y
                        if dx * dx + dy * dy <= radius_sq:
                            hit = True
                            break
                    if not hit:
                        continue
                    try:
                        mino["hit_flash_duration"] = 130
                        mino["hit_flash_until"] = pygame.time.get_ticks() + 130
                    except Exception:
                        pass
                    if mino.get('wall_generated'):
                        try:
                            for c in mino.get('cells', []) or []:
                                _remove_wall_cell_rect(c.get('rect'))
                        except Exception:
                            pass
                    destroy_stage7_tetromino(mino, by_player=True, by_dash=True)

            # 가드 라인 블럭도 반경 내 파괴
            if 'stage7_guard_blocks' in globals() and stage7_guard_blocks:
                for block in list(stage7_guard_blocks):
                    state = block.get('state')
                    if state not in ('assembling', 'hologram', 'deploy', 'active'):
                        continue
                    hit = False
                    for c in block.get('cells', []) or []:
                        rect = c.get('rect')
                        if not rect:
                            continue
                        closest_x = max(rect.left, min(centerx, rect.right))
                        closest_y = max(rect.top, min(centery, rect.bottom))
                        dx = centerx - closest_x
                        dy = centery - closest_y
                        if dx * dx + dy * dy <= radius_sq:
                            hit = True
                            break
                    if hit:
                        destroy_stage7_guard_block(block, by_player=False)
    except Exception:
        pass

    try:
        _destroy_stage2_rocks_in_radius(centerx, centery, radius, source="hammer_shock_explosion")
    except Exception:
        pass

    # 🏖 사막화 모래 침식: 해머쇼크 폭발 반경 내 모래 파괴
    if sand_obstacles is not None:
        erode_sand_area(sand_obstacles, centerx, centery, radius)

    try:
        effects_manager.spawn_star_particles(
            int(render_centerx),
            int(visual_centery),
            count=10 + resolved_stage * 3,
        )
    except Exception:
        pass

    stage = resolved_stage

    # Add ground crack effect at explosion point
    global blacksmith_ground_cracks
    num_cracks = BLACKSMITH_HAMMER_SHOCK_CRACK_COUNTS.get(
        stage,
        BLACKSMITH_HAMMER_SHOCK_CRACK_COUNTS[max(BLACKSMITH_HAMMER_SHOCK_CRACK_COUNTS)],
    )
    for i in range(num_cracks):
        angle = (math.pi * 2 * i / num_cracks) + random.uniform(-0.2, 0.2)
        base_length = radius * stage_multiplier * random.uniform(0.8, 1.3)
        length = base_length * BLACKSMITH_GROUND_CRACK_RANGE_SCALE
        
        # Generate sub-cracks data
        sub_cracks = []
        num_sub_cracks = 2 + stage
        for j in range(num_sub_cracks):
            sub_pos = 0.3 + (j * 0.4 / num_sub_cracks) + random.uniform(-0.1, 0.1)
            sub_angle_offset = random.choice([-0.5, 0.5]) + random.uniform(-0.2, 0.2)
            sub_length_ratio = 0.3 + random.uniform(-0.1, 0.1)
            sub_cracks.append({
                "pos": sub_pos,
                "angle_offset": sub_angle_offset,
                "length_ratio": sub_length_ratio
            })
        
        base_thickness = 2 + stage
        required_hits = BLACKSMITH_GROUND_CRACK_REQUIRED_BOSS_HITS.get(stage)
        if required_hits is None:
            # 상위 단계는 3단계와 동일한 내구도로 처리
            required_hits = BLACKSMITH_GROUND_CRACK_REQUIRED_BOSS_HITS[max(BLACKSMITH_GROUND_CRACK_REQUIRED_BOSS_HITS)]
        # 요청사항: 단계별 보스 충돌 파괴 필요 횟수 범위 적용
        # 1단계: 4~5회, 2단계: 6~7회, 3단계 이상: 8~9회
        try:
            if stage == 1:
                required_hits = random.randint(4, 5)
            elif stage == 2:
                required_hits = random.randint(6, 7)
            else:
                required_hits = random.randint(8, 9)
        except Exception:
            # 예외 시 보수적으로 최소값 적용
            required_hits = 4 if stage == 1 else (6 if stage == 2 else 8)
        segment_count = max(1, required_hits)

        crack = {
            "x": centerx,
            "y": centery,
            "angle": angle,
            "length": length,
            "initial_length": length,
            "segments_total": segment_count,
            "segments_remaining": segment_count,
            "life": BLACKSMITH_GROUND_CRACK_DURATION,
            "max_life": BLACKSMITH_GROUND_CRACK_DURATION,
            "stage": stage,
            "base_thickness": base_thickness,
            "thickness": max(1, int(round(base_thickness * BLACKSMITH_GROUND_CRACK_RANGE_SCALE))),
            "boss_padding": BLACKSMITH_GROUND_CRACK_BOSS_PADDING,
            "boss_touch_cooldown": 0,
            "sub_cracks": sub_cracks,
            "required_boss_hits": required_hits,
        }
        try:
            base_time = pygame.time.get_ticks()
        except Exception:
            base_time = 0
        start_ms = base_time + BLACKSMITH_GROUND_CRACK_AUTO_BREAK_DELAY_MS
        crack["auto_break_enabled"] = True
        crack["auto_break_start_ms"] = start_ms
        crack["auto_break_next_ms"] = start_ms
        _schedule_next_crack_auto_break(crack, base_time_ms=start_ms)

        blacksmith_ground_cracks.append(crack)
        # print(f"[DEBUG] Created ground crack #{len(blacksmith_ground_cracks)}: x={crack['x']:.0f}, y={crack['y']:.0f}, angle={crack['angle']:.2f}, length={crack['length']:.0f}")  # 디버그 비활성화

    profile_key = "hammer_shock_stage3" if stage >= 3 else (
        "hammer_shock_stage2" if stage == 2 else "hammer_shock_stage1"
    )
    try:
        knockback_speed = compute_knockback_magnitude(profile_key)
    except KeyError:
        knockback_speed = BLACKSMITH_HAMMER_SHOCK_STAGE3_KNOCKBACK if stage >= 3 else (
            BLACKSMITH_HAMMER_SHOCK_STAGE2_KNOCKBACK if stage == 2 else BLACKSMITH_HAMMER_SHOCK_STAGE1_KNOCKBACK
        )

    if 'BOSS' in globals() and BOSS is not None:
        boss_rect = BOSS
        distance = abs(boss_rect.centerx - centerx)
        effective_radius = radius + boss_rect.width // 2
        if distance <= effective_radius:
            try:
                globals()["boss_knockback_timer"] = int(0.4 * FPS)
                _apply_boss_knockback_velocity(knockback_speed)
                globals()["boss_knockback_active"] = False
                globals()["boss_knockback_offset_x"] = 0
                globals()["boss_knockback_offset_y"] = 0
            except Exception:
                pass
            stun_frames = BLACKSMITH_HAMMER_SHOCK_STUN_DURATION_FRAMES.get(
                stage,
                BLACKSMITH_HAMMER_SHOCK_STUN_DURATION_FRAMES[max(BLACKSMITH_HAMMER_SHOCK_STUN_DURATION_FRAMES)],
            )

            try:
                globals()["boss_stunned_timer"] = max(boss_stunned_timer, stun_frames)
            except Exception:
                pass

            current_stage_value = current_stage
            if current_stage_value in boss_health_stages:
                damage = _blacksmith_hammer_shock_damage_for_stage(stage)
                if damage > 0:
                    damage_stage = min(max(1, stage), BLACKSMITH_HAMMER_SHOCK_MAX_STAGE)
                    previous_health = boss_current_health
                    boss_current_health = max(0, boss_current_health - damage)

                    if current_stage_value == 6:
                        try:
                            stage6_boss_hit_timer = max(stage6_boss_hit_timer, HALF_SECOND_FRAMES)
                            stage6_boss_hit_flash = True
                            if SOUND_STAGE6_BOSS_HIT:
                                SOUND_STAGE6_BOSS_HIT.play()
                        except Exception:
                            pass

                    print(
                        f"[해머쇼크] 체력형 보스에게 {damage} 데미지! (단계 {damage_stage}, {boss_current_health}/{boss_max_health})"
                    )

                    if previous_health > 0 and boss_current_health <= 0:
                        try:
                            # 네메시스(스테이지 6) 패배 시 폭발 애니메이션 시작
                            if current_stage == 6:
                                start_nemesis_death_animation()
                                return  # show_result는 애니메이션 완료 후 호출
                            show_result(True)
                        except Exception:
                            pass


def update_blacksmith_hammer_shock(keys):
    valthor_perf_start("update_hammer_shock")
    global blacksmith_hammer_shock_charging, blacksmith_hammer_shock_charge_frames
    global blacksmith_hammer_shock_stage, blacksmith_hammer_shock_projectiles
    global blacksmith_hammer_shock_cooldown_timer, blacksmith_hammer_available
    global blacksmith_hammer_shock_anchor_x, blacksmith_hammer_shock_anchor_y
    global blacksmith_ground_cracks
    global PLAYER, special_gauge, special_ready, special_gauge_max
    global BALL, ball_vel, last_hit_by, player_collision_handled
    global stopwatch_active, stopwatch_timer
    global blacksmith_hammer_charge_position, blacksmith_hammer_idle_position
    global blacksmith_umbrella_open, blacksmith_umbrella_anim_timer, blacksmith_umbrella_retracting
    global frame_counter, blacksmith_hammer_last_update_frame, blacksmith_hammer_last_update_ms
    global blacksmith_hammer_projectiles_paused
    global blacksmith_hammer_shock_particles, blacksmith_hammer_explosions
    global blacksmith_divine_stone_state
    global blacksmith_divine_slash_projectiles, blacksmith_divine_slash_scheduled
    global BOSS

    current_ticks = pygame.time.get_ticks()

    # 강화디바인스톤 검기 예약 발사 처리 (스윙 후 0.4초 지연)
    if blacksmith_divine_slash_scheduled is not None:
        try:
            trigger_time = int(blacksmith_divine_slash_scheduled.get("trigger_time", 0))
        except Exception:
            trigger_time = 0
        if current_ticks >= trigger_time:
            try:
                direction = int(blacksmith_divine_slash_scheduled.get("direction", 0))
            except Exception:
                direction = 0
            _spawn_blacksmith_divine_slash_from_shield(direction)
            blacksmith_divine_slash_scheduled = None

    umbrella_blocks_hammer_shock = blacksmith_umbrella_open and not blacksmith_umbrella_retracting
    if umbrella_blocks_hammer_shock and blacksmith_hammer_shock_charging and not blacksmith_hammer_shock_projectiles:
        blacksmith_hammer_shock_charging = False
        blacksmith_hammer_shock_charge_frames = 0
        blacksmith_hammer_shock_stage = 0
        stop_blacksmith_hammer_charge_sound()
    # Keep updating cooldowns and projectiles even while the umbrella is open.

    if blacksmith_hammer_shock_cooldown_timer > 0:
        blacksmith_hammer_shock_cooldown_timer -= 1
        _complete_blacksmith_hammer_cooldown_if_ready()

    if blacksmith_hammer_shock_charging and not umbrella_blocks_hammer_shock:
        if 'PLAYER' in globals() and PLAYER is not None:
            # 차징 중에도 플레이어 이동에 따라 차징 위치 업데이트
            # 충전 시작 시 설정된 오프셋(해머 위치 - 플레이어 위치)을 현재 플레이어 위치에 적용
            if blacksmith_hammer_charge_position is not None:
                # 기존 오프셋 계산 (충전 시작 시의 해머-플레이어 상대 위치)
                offset_x = blacksmith_hammer_charge_position[0] - blacksmith_hammer_shock_anchor_x
                offset_y = blacksmith_hammer_charge_position[1] - blacksmith_hammer_shock_anchor_y
                # 현재 플레이어 위치에 오프셋 적용
                blacksmith_hammer_charge_position = (
                    float(PLAYER.centerx + offset_x),
                    float(PLAYER.centery + offset_y)
                )
            # anchor 위치 업데이트
            blacksmith_hammer_shock_anchor_x = PLAYER.centerx
            blacksmith_hammer_shock_anchor_y = PLAYER.centery
        blacksmith_hammer_shock_charge_frames += 1
        max_stage_for_gauge = _blacksmith_hammer_shock_max_stage_for_gauge(special_gauge)
        blacksmith_hammer_shock_stage = _blacksmith_hammer_shock_effective_stage(
            blacksmith_hammer_shock_charge_frames,
            special_gauge,
        )

        if max_stage_for_gauge == 0:
            blacksmith_hammer_shock_charging = False
            blacksmith_hammer_shock_charge_frames = 0
            blacksmith_hammer_shock_stage = 0
            stop_blacksmith_hammer_charge_sound()
            if blacksmith_hammer_charge_position is not None:
                sanitized_charge = _sanitize_blacksmith_hammer_position(blacksmith_hammer_charge_position)
                if sanitized_charge is not None:
                    blacksmith_hammer_idle_position = sanitized_charge
                else:
                    blacksmith_hammer_idle_position = None
            blacksmith_hammer_charge_position = None
        else:
            try:
                # 항상 플레이어 기준 위치 사용
                origin_x = float(blacksmith_hammer_charge_position[0]) if blacksmith_hammer_charge_position else PLAYER.right + 18
                origin_y = float(blacksmith_hammer_charge_position[1]) if blacksmith_hammer_charge_position else PLAYER.centery - 20
                if blacksmith_hammer_shock_stage >= 1 and blacksmith_hammer_shock_charge_frames % 6 == 0:
                    effects_manager.spawn_star_particles(int(origin_x), int(origin_y), count=3 + blacksmith_hammer_shock_stage)
                if blacksmith_hammer_shock_stage >= 2 and blacksmith_hammer_shock_charge_frames % 10 == 0:
                    effects_manager.spawn_flame_particles(int(origin_x - 4), int(origin_y + 6), count=2 + blacksmith_hammer_shock_stage)
            except Exception:
                pass
    else:
        blacksmith_hammer_shock_stage = 0
        blacksmith_hammer_shock_charge_frames = 0
        if blacksmith_hammer_charge_position is not None:
            sanitized_charge = _sanitize_blacksmith_hammer_position(blacksmith_hammer_charge_position)
            if sanitized_charge is not None:
                blacksmith_hammer_idle_position = sanitized_charge
            else:
                blacksmith_hammer_idle_position = None
        blacksmith_hammer_charge_position = None

    advance_iterations = 2 if blacksmith_hammer_projectiles_paused else 1
    new_projectiles = []
    for proj in blacksmith_hammer_shock_projectiles:
        keep = True
        for _ in range(advance_iterations):
            if not _advance_blacksmith_hammer_projectile(proj):
                keep = False
                break
        if keep:
            proj["_last_update_frame"] = frame_counter
            proj["_last_update_ms"] = current_ticks
            new_projectiles.append(proj)

    blacksmith_hammer_shock_projectiles = new_projectiles
    blacksmith_hammer_last_update_frame = frame_counter
    blacksmith_hammer_last_update_ms = current_ticks
    if blacksmith_hammer_projectiles_paused:
        blacksmith_hammer_projectiles_paused = False
    _complete_blacksmith_hammer_cooldown_if_ready()

    # Update ground cracks auto-decay (natural shatter over time)
    try:
        current_ticks = pygame.time.get_ticks()
    except Exception:
        current_ticks = 0

    if 'blacksmith_ground_cracks' in globals() and blacksmith_ground_cracks:
        for crack in list(blacksmith_ground_cracks):
            if not crack.get("auto_break_enabled"):
                continue

            start_ms = crack.get("auto_break_start_ms", 0)
            if current_ticks < start_ms:
                continue

            next_ms = crack.get("auto_break_next_ms")
            if next_ms is None:
                _schedule_next_crack_auto_break(crack, base_time_ms=current_ticks)
                next_ms = crack.get("auto_break_next_ms")

            if next_ms is None or current_ticks < next_ms:
                continue

            if ENABLE_CRACK_TIMING_DEBUG:
                remaining = crack.get("segments_remaining", 0)
                total = crack.get("segments_total", remaining)
                print(f"[CRACK AUTO] t={current_ticks} seg={remaining}/{total}")

            still_exists = _decay_blacksmith_crack_segment(
                crack,
                segments=1,
                spawn_particles=True,
                play_sound=False,
            )

            if crack not in blacksmith_ground_cracks:
                continue

            if not still_exists:
                crack["auto_break_enabled"] = False
                continue

            _schedule_next_crack_auto_break(crack, base_time_ms=current_ticks)

    # Update divine slash projectiles (강화디바인스톤 토르쉴드 검기)
    if "blacksmith_divine_slash_projectiles" in globals() and blacksmith_divine_slash_projectiles:
        radius = BLACKSMITH_DIVINE_SLASH_RADIUS
        margin = BLACKSMITH_DIVINE_SLASH_WALL_MARGIN
        updated_slashes: list[dict[str, object]] = []

        for proj in blacksmith_divine_slash_projectiles:
            try:
                old_x = float(proj.get("x", 0.0))
                old_y = float(proj.get("y", 0.0))
                x = old_x + float(proj.get("vx", 0.0))
                y = old_y + float(proj.get("vy", 0.0))
            except Exception:
                continue

            # 궤적 업데이트 (최대 20개 포인트 유지)
            trail = proj.get("trail", [])
            if not isinstance(trail, list):
                trail = []
            trail.append((old_x, old_y))
            if len(trail) > 20:
                trail = trail[-20:]
            proj["trail"] = trail

            proj["x"] = x
            proj["y"] = y

            life = int(proj.get("life", 0)) - 1
            proj["life"] = life
            if life <= 0:
                continue

            # 좌우 벽에 한 번만 반사
            bounced = bool(proj.get("bounced", False))
            if not bounced and (x <= margin or x >= WIDTH - margin):
                try:
                    proj["vx"] = -float(proj.get("vx", 0.0))
                    proj["bounced"] = True
                except Exception:
                    pass
                if x <= margin:
                    x = margin
                elif x >= WIDTH - margin:
                    x = WIDTH - margin
                proj["x"] = x

            # 슬래시 판정 영역
            try:
                slash_rect = pygame.Rect(int(x - radius), int(y - radius), radius * 2, radius * 2)
            except Exception:
                slash_rect = None

            # 공 타격: 검기 진행 방향으로 공을 위쪽으로 쏘아 올린다.
            if (
                slash_rect is not None
                and "BALL" in globals()
                and BALL is not None
                and slash_rect.colliderect(BALL)
            ):
                try:
                    dir_x = float(proj.get("vx", 0.0))
                    dir_y = float(proj.get("vy", -1.0))
                    mag = math.hypot(dir_x, dir_y)
                    if mag <= 0.001:
                        dir_x, dir_y = 0.0, -1.0
                        mag = 1.0
                    dir_x /= mag
                    dir_y /= mag

                    speed = math.hypot(ball_vel[0], ball_vel[1])
                    if speed <= 0:
                        speed = BALL_BASE_SPEED
                    target_speed = max(speed * 1.05, BALL_BASE_SPEED * 1.1)

                    ball_vel[0] = dir_x * target_speed
                    ball_vel[1] = dir_y * target_speed

                    last_hit_by = "player"
                    player_collision_handled = True

                    try:
                        effects_manager.create_impact_effect(BALL.centerx, BALL.centery, 40, is_player=True)
                        effects_manager.spawn_star_particles(BALL.centerx, BALL.centery, count=8)
                    except Exception:
                        pass

                    # 검기로 공을 맞출 경우 플레이어 스킬 게이지 +30 (1회 한정)
                    if not proj.get("ball_gauge_given", False):
                        try:
                            gain = 30
                            # ⛏️ 골드디거 게이지 충전량 증가 적용
                            if is_gold_digger_equipped():
                                gain = apply_gold_digger_gauge_bonus(gain)
                            special_gauge = min(special_gauge_max, special_gauge + gain)
                            special_ready = special_gauge >= special_gauge_max
                        except Exception:
                            pass
                        proj["ball_gauge_given"] = True
                except Exception:
                    pass

            # 보스 타격: 한 번만 넉백 적용
            if (
                slash_rect is not None
                and not proj.get("boss_hit", False)
                and "BOSS" in globals()
                and BOSS is not None
                and slash_rect.colliderect(BOSS)
            ):
                try:
                    trigger_boss_knockback(slash_rect.centerx, slash_rect.centery)
                    # 검기 전용: 기존보다 더 빠르고 멀리 넉백되도록 즉시 추가 밀기 적용
                    try:
                        boss_obj = BOSS
                        if boss_obj is not None:
                            hit_center_x = slash_rect.centerx
                            boss_center_x = boss_obj.centerx
                            direction = 1 if boss_center_x >= hit_center_x else -1

                            extra_push = 32  # 기본 추가 넉백 거리 (픽셀)
                            if direction > 0:
                                # 오른쪽으로 밀릴 때 화면 경계 고려
                                extra_push = min(extra_push, max(0, WIDTH - boss_obj.right))
                            else:
                                # 왼쪽으로 밀릴 때 화면 경계 고려
                                extra_push = min(extra_push, max(0, boss_obj.left))

                            boss_obj.x += direction * extra_push
                            boss_obj.x = max(0, min(WIDTH - boss_obj.width, boss_obj.x))
                    except Exception:
                        pass
                except Exception:
                    pass
                # 넉백과 동시에 0.3초(18프레임) 스턴 부여
                try:
                    stun_frames = int(0.3 * FPS)
                    globals()["boss_stunned_timer"] = max(
                        boss_stunned_timer,
                        stun_frames,
                    )
                except Exception:
                    pass

                # 어둠의 폭발 이펙트 생성 (다크 스모크 + 폭발)
                try:
                    hit_x = BOSS.centerx
                    hit_y = BOSS.centery

                    # 다크 스모크 파티클 생성
                    for _ in range(15):
                        smoke_particle = {
                            "x": hit_x + random.uniform(-20, 20),
                            "y": hit_y + random.uniform(-15, 15),
                            "vx": random.uniform(-2, 2),
                            "vy": random.uniform(-3, -0.5),
                            "size": random.randint(8, 16),
                            "life": random.randint(30, 50),
                            "max_life": 50,
                            "color": random.choice([
                                (40, 20, 50),   # 어둠의 보라
                                (30, 15, 40),   # 진한 보라
                                (50, 25, 60),   # 다크 마젠타
                                (20, 10, 30),   # 검은 보라
                            ]),
                            "type": "dark_smoke"
                        }
                        blacksmith_hammer_shock_particles.append(smoke_particle)

                    # 다크 폭발 링 파티클 생성
                    for i in range(8):
                        angle = (2 * math.pi * i / 8) + random.uniform(-0.2, 0.2)
                        speed = random.uniform(3, 6)
                        explosion_particle = {
                            "x": hit_x,
                            "y": hit_y,
                            "vx": math.cos(angle) * speed,
                            "vy": math.sin(angle) * speed,
                            "size": random.randint(4, 8),
                            "life": random.randint(15, 25),
                            "max_life": 25,
                            "color": (80, 40, 100),  # 어둠의 보라 폭발
                            "type": "dark_explosion"
                        }
                        blacksmith_hammer_shock_particles.append(explosion_particle)

                    # 이펙트 매니저를 통한 추가 임팩트 효과
                    effects_manager.create_impact_effect(hit_x, hit_y, 50, is_player=True)
                except Exception:
                    pass

                proj["boss_hit"] = True

            # 화면 밖으로 완전히 벗어나면 제거
            if y < -radius * 2 or y > HEIGHT + radius * 2:
                continue

            updated_slashes.append(proj)

        blacksmith_divine_slash_projectiles = updated_slashes

    # Update hammer shock particles (for shatter effects)
    updated_particles = []
    for particle in blacksmith_hammer_shock_particles:
        # Update particle position
        particle["x"] += particle["vx"]
        particle["y"] += particle["vy"]
        # Apply gravity
        particle["vy"] += 0.5
        # Reduce life
        particle["life"] -= 1
        # Keep particle if still alive
        if particle["life"] > 0:
            updated_particles.append(particle)
    blacksmith_hammer_shock_particles = updated_particles

    blacksmith_hammer_explosions = [
        exp for exp in blacksmith_hammer_explosions if exp.get("life", 0) > 0
    ]
    valthor_perf_end("update_hammer_shock")


def draw_blacksmith_hammer_shock(surface, offset_x: float = 0.0, offset_y: float = 0.0):
    valthor_perf_start("draw_hammer_shock")
    global blacksmith_hammer_charge_position, blacksmith_hammer_idle_position
    if selected_character_type != "blacksmith":
        valthor_perf_end("draw_hammer_shock")
        return

    if blacksmith_hammer_shock_charging:
        draw_center: tuple[float, float] | None = None

        if blacksmith_hammer_charge_position is not None:
            sanitized_charge = _sanitize_blacksmith_hammer_position(blacksmith_hammer_charge_position)
            if sanitized_charge is not None:
                blacksmith_hammer_charge_position = sanitized_charge
                draw_center = (
                    sanitized_charge[0] + offset_x,
                    sanitized_charge[1] + offset_y,
                )
            else:
                blacksmith_hammer_charge_position = None

        if draw_center is None:
            fallback_base: tuple[float, float] | None = None

            if 'PLAYER' in globals() and PLAYER is not None:
                fallback_base = _sanitize_blacksmith_hammer_position(
                    (PLAYER.right + 18, PLAYER.centery - 20)
                )

            if fallback_base is None and blacksmith_hammer_idle_position is not None:
                sanitized_idle = _sanitize_blacksmith_hammer_position(blacksmith_hammer_idle_position)
                if sanitized_idle is not None:
                    blacksmith_hammer_idle_position = sanitized_idle
                    fallback_base = sanitized_idle
                else:
                    blacksmith_hammer_idle_position = None

            if fallback_base is None:
                # 플레이어 기준 기본 위치 사용 (화면 중앙 대신)
                if 'PLAYER' in globals() and PLAYER is not None:
                    fallback_base = (float(PLAYER.right + 18), float(PLAYER.centery - 20))
                else:
                    fallback_base = (float(WIDTH // 2), float(HEIGHT // 2))

            draw_center = (
                fallback_base[0] + offset_x,
                fallback_base[1] + offset_y,
            )

        sanitized_center = _sanitize_blacksmith_hammer_position(draw_center)
        if sanitized_center is not None:
            cx = int(round(sanitized_center[0]))
            cy = int(round(sanitized_center[1]))
            _draw_blacksmith_hammer_charge_effect(
                surface,
                cx,
                cy,
                blacksmith_hammer_shock_stage,
                blacksmith_hammer_shock_charge_frames,
            )

    # Draw ground cracks first (below everything)
    for crack in blacksmith_ground_cracks:
        # Cracks are now permanent, full opacity
        alpha = 200

        if crack.get("boss_touch_cooldown", 0) > 0:
            crack["boss_touch_cooldown"] -= 1

        # Calculate crack color based on stage
        stage = crack.get("stage", 1)
        if stage >= 3:
            crack_color = (120, 140, 160, alpha)  # Blue-gray
        elif stage >= 2:
            crack_color = (100, 110, 130, alpha)  # Dark blue-gray
        else:
            crack_color = (80, 90, 100, alpha)  # Dark gray

        # Draw collision bounds for debugging (semi-transparent red)
        if BLACKSMITH_DEBUG_DRAW_CRACK_BOUNDS:
            collision_padding = crack.get("boss_padding", BLACKSMITH_GROUND_CRACK_BOSS_PADDING)
            collision_thickness = crack.get("thickness", 2) + collision_padding  # Match the collision detection thickness
            
            # Draw the actual collision area that boss checks against
            # Create a thick line by drawing a polygon
            angle_perp = crack["angle"] + math.pi / 2
            x1 = crack["x"] + math.cos(angle_perp) * collision_thickness
            y1 = crack["y"] + math.sin(angle_perp) * collision_thickness
            x2 = crack["x"] - math.cos(angle_perp) * collision_thickness
            y2 = crack["y"] - math.sin(angle_perp) * collision_thickness
            
            end_x = crack["x"] + math.cos(crack["angle"]) * crack["length"]
            end_y = crack["y"] + math.sin(crack["angle"]) * crack["length"]
            
            x3 = end_x - math.cos(angle_perp) * collision_thickness
            y3 = end_y - math.sin(angle_perp) * collision_thickness
            x4 = end_x + math.cos(angle_perp) * collision_thickness
            y4 = end_y + math.sin(angle_perp) * collision_thickness
            
            # Check if boss is currently colliding with this crack
            is_colliding = False
            if 'BOSS' in globals() and BOSS is not None:
                boss_rect = pygame.Rect(BOSS.x, BOSS.y, BOSS.width, BOSS.height)
                if _check_boss_crack_collision(boss_rect, crack):
                    is_colliding = True
            
            # Draw the collision polygon with offset applied
            collision_points = [
                (x1 + offset_x, y1 + offset_y),
                (x2 + offset_x, y2 + offset_y),
                (x3 + offset_x, y3 + offset_y),
                (x4 + offset_x, y4 + offset_y)
            ]
            
            # Draw semi-transparent red polygon for collision area
            collision_surface = pygame.Surface((surface.get_width(), surface.get_height()), pygame.SRCALPHA)
            if is_colliding:
                pygame.draw.polygon(collision_surface, (200, 80, 80, 110), collision_points)
            else:
                pygame.draw.polygon(collision_surface, (255, 0, 0, 80), collision_points)
            surface.blit(collision_surface, (0, 0))
        
        # Draw main crack line
        end_x = crack["x"] + math.cos(crack["angle"]) * crack["length"]
        end_y = crack["y"] + math.sin(crack["angle"]) * crack["length"]
        
        # Draw with thickness
        for i in range(-crack["thickness"]//2, crack["thickness"]//2 + 1):
            offset_x_crack = math.sin(crack["angle"]) * i
            offset_y_crack = -math.cos(crack["angle"]) * i
            pygame.draw.line(
                surface, 
                crack_color[:3], 
                (int(crack["x"] + offset_x_crack + offset_x), int(crack["y"] + offset_y_crack + offset_y)),
                (int(end_x + offset_x_crack + offset_x), int(end_y + offset_y_crack + offset_y)),
                1
            )
        
        # Draw sub-cracks
        for sub_crack in crack.get("sub_cracks", []):
            sub_x = crack["x"] + math.cos(crack["angle"]) * crack["length"] * sub_crack["pos"]
            sub_y = crack["y"] + math.sin(crack["angle"]) * crack["length"] * sub_crack["pos"]
            sub_angle = crack["angle"] + sub_crack["angle_offset"]
            sub_length = crack["length"] * sub_crack["length_ratio"]
            sub_end_x = sub_x + math.cos(sub_angle) * sub_length
            sub_end_y = sub_y + math.sin(sub_angle) * sub_length
            pygame.draw.line(
                surface,
                crack_color[:3],
                (int(sub_x + offset_x), int(sub_y + offset_y)),
                (int(sub_end_x + offset_x), int(sub_end_y + offset_y)),
                max(1, crack["thickness"] // 2)
            )

    # Draw actual hammers
    hammer_surface = _get_blacksmith_thrown_hammer_surface()
    synced_projectiles: list[dict] = []
    current_ticks = pygame.time.get_ticks()
    for proj in blacksmith_hammer_shock_projectiles:
        frames_pending = 0
        if 'frame_counter' in globals():
            last_frame = int(proj.get("_last_update_frame", frame_counter))
            frames_pending = max(0, frame_counter - last_frame)
        if frames_pending == 0:
            last_ms = int(proj.get("_last_update_ms", blacksmith_hammer_last_update_ms))
            if current_ticks > last_ms:
                elapsed_ms = current_ticks - last_ms
                frames_pending = int(elapsed_ms * FPS / 1000)
                if frames_pending > 0:
                    proj["_last_update_ms"] = current_ticks
        if frames_pending > 0:
            if not _advance_blacksmith_hammer_projectile(proj, frames_pending):
                continue
            if 'frame_counter' in globals():
                proj["_last_update_frame"] = frame_counter
            proj["_last_update_ms"] = current_ticks
        synced_projectiles.append(proj)
        rotated = pygame.transform.rotate(hammer_surface, proj.get("rotation", 0.0))
        rect = rotated.get_rect(center=(int(proj["x"] + offset_x), int(proj["y"] + offset_y)))
        surface.blit(rotated, rect)

    # Replace the projectile list with the filtered/synced copy if any changes occurred.
    if len(synced_projectiles) != len(blacksmith_hammer_shock_projectiles):
        blacksmith_hammer_shock_projectiles[:] = synced_projectiles

    # Draw divine slash projectiles (강화디바인스톤 토르쉴드 검기)
    if "blacksmith_divine_slash_projectiles" in globals() and blacksmith_divine_slash_projectiles:
        for proj in blacksmith_divine_slash_projectiles:
            try:
                world_x = float(proj.get("x", 0.0)) + float(offset_x)
                world_y = float(proj.get("y", 0.0)) + float(offset_y)
                vx = float(proj.get("vx", 0.0))
                vy = float(proj.get("vy", -1.0))
                trail = proj.get("trail", [])
            except Exception:
                continue

            radius = float(BLACKSMITH_DIVINE_SLASH_RADIUS)

            try:
                # === 1. 검붉은보라색 궤적 그리기 (경량화 버전) ===
                #  - 매 프레임 전체 화면 서피스를 여러 번 생성하던 방식은 GPU/CPU 부하가 매우 크므로
                #    여기서는 단순 라인 드로잉만 사용해 가벼운 궤적 효과만 남긴다.
                if trail and len(trail) >= 2:
                    trail_points = [(int(tx + offset_x), int(ty + offset_y)) for tx, ty in trail]
                    trail_points.append((int(world_x), int(world_y)))

                    segment_count = len(trail_points) - 1
                    if segment_count > 0:
                        # 최근 궤적 일부만 사용해 과도한 드로잉을 방지
                        max_segments = min(segment_count, 10)
                        start_index = segment_count - max_segments

                        for i in range(start_index, segment_count):
                            progress = (i - start_index) / max(1, max_segments)
                            # 검붉은보라색 (dark red-purple) 계열 그라데이션
                            r_col = int(110 + 40 * progress)
                            g_col = int(25 + 20 * progress)
                            b_col = int(80 + 40 * progress)
                            width = max(1, int(2 + 4 * progress))
                            pygame.draw.line(
                                surface,
                                (r_col, g_col, b_col),
                                trail_points[i],
                                trail_points[i + 1],
                                width,
                            )

                # === 2. 화려한 U자형 에너지 검기 ===
                size = int(radius * 8)
                if size <= 0:
                    continue

                slash_surface = pygame.Surface((size, size), pygame.SRCALPHA)
                cx = int(size * 0.5)
                cy = int(size * 0.5)

                # 진행 방향에 따라 열린 방향 결정
                # vx > 0: 오른쪽으로 이동 → 오른쪽이 열린 호
                # vx < 0: 왼쪽으로 이동 → 왼쪽이 열린 호
                if vx >= 0:
                    arc_start = math.radians(100)  # 위에서 시작
                    arc_end = math.radians(260)    # 아래에서 끝
                else:
                    arc_start = math.radians(-80)  # 위에서 시작
                    arc_end = math.radians(80)     # 아래에서 끝

                # 멀티 레이어 에너지 아크 (참조 이미지처럼)
                layer_count = 6
                base_radius = radius * 2.0

                for layer in range(layer_count):
                    # 바깥 레이어부터 안쪽으로
                    r = base_radius + (layer_count - 1 - layer) * radius * 0.4
                    rect = pygame.Rect(0, 0, int(r * 2), int(r * 2))
                    rect.center = (cx, cy)

                    # 색상: 보라-파랑-시안 그라데이션 (더 화려하게)
                    if layer < 2:
                        # 외곽: 진한 보라 + 글로우
                        color = (180, 100, 255, 60 + layer * 20)
                    elif layer < 4:
                        # 중간: 밝은 파랑
                        color = (100, 180, 255, 100 + layer * 20)
                    else:
                        # 코어: 밝은 시안-화이트
                        color = (200, 240, 255, 200 + layer * 10)

                    width = max(2, int(radius * 0.6 - layer * 0.08 * radius))
                    pygame.draw.arc(slash_surface, color, rect, arc_start, arc_end, width)

                # 에너지 파티클/스파크 효과 (호 따라)
                spark_count = 8
                for i in range(spark_count):
                    angle = arc_start + (arc_end - arc_start) * (i / (spark_count - 1))
                    spark_r = base_radius + random.uniform(-radius * 0.3, radius * 0.5)
                    sx = cx + math.cos(angle) * spark_r
                    sy = cy + math.sin(angle) * spark_r
                    spark_alpha = random.randint(150, 255)
                    spark_size = random.randint(1, 3)
                    pygame.draw.circle(slash_surface, (220, 200, 255, spark_alpha),
                                     (int(sx), int(sy)), spark_size)

                # 중심부 글로우 효과
                glow_surf = pygame.Surface((size, size), pygame.SRCALPHA)
                for glow_layer in range(4):
                    glow_r = int(radius * (1.5 - glow_layer * 0.3))
                    glow_alpha = 30 - glow_layer * 5
                    pygame.draw.circle(glow_surf, (150, 120, 255, max(10, glow_alpha)),
                                     (cx, cy), glow_r)
                slash_surface.blit(glow_surf, (0, 0))

                # 이동 방향(vx, vy)에 맞추어 회전 (열린 방향이 진행 방향을 향하도록)
                angle_deg = 0.0
                if abs(vx) > 1e-3 or abs(vy) > 1e-3:
                    # 진행 방향 각도 계산
                    angle_deg = math.degrees(math.atan2(-vy, vx))  # Y축 반전
                    # 호의 열린 방향이 이미 오른쪽/왼쪽을 향하고 있으므로
                    # 진행 방향에 맞게 추가 회전
                    if vx >= 0:
                        angle_deg = angle_deg - 0  # 오른쪽으로 열린 호는 그대로
                    else:
                        angle_deg = angle_deg + 180  # 왼쪽으로 열린 호는 180도 보정

                rotated = pygame.transform.rotate(slash_surface, angle_deg)
                slash_rect = rotated.get_rect(center=(int(world_x), int(world_y)))
                surface.blit(rotated, slash_rect)

                # 추가 외곽 글로우 (전체 이펙트에 생동감)
                outer_glow = pygame.Surface((size * 2, size * 2), pygame.SRCALPHA)
                pygame.draw.circle(outer_glow, (120, 80, 200, 25),
                                 (size, size), int(radius * 3))
                glow_rect = outer_glow.get_rect(center=(int(world_x), int(world_y)))
                surface.blit(outer_glow, glow_rect)

            except Exception:
                pygame.draw.circle(surface, (180, 80, 200), (int(world_x), int(world_y)), int(radius), 2)
    
    # Draw shatter particles (경량화: per-frame 임시 서피스 생성 제거)
    for particle in blacksmith_hammer_shock_particles:
        alpha = min(255, particle["life"] * 10)
        color = (*particle["color"], alpha)
        px = int(particle["x"] + offset_x)
        py = int(particle["y"] + offset_y)
        psize = particle["size"]

        particle_type = particle.get("type", "default")

        if particle_type == "dark_smoke":
            # 어둠의 연기 파티클: 부드러운 원형 + 글로우
            try:
                max_life = particle.get("max_life", 50)
                life_ratio = particle["life"] / max_life
                smoke_alpha = int(180 * life_ratio)
                smoke_size = int(psize * (1.5 - 0.5 * life_ratio))  # 서서히 커짐

                # 외곽 글로우
                glow_surf = pygame.Surface((smoke_size * 3, smoke_size * 3), pygame.SRCALPHA)
                glow_center = (smoke_size * 3 // 2, smoke_size * 3 // 2)
                for glow_layer in range(3):
                    glow_r = smoke_size + (2 - glow_layer) * 4
                    glow_alpha = max(10, smoke_alpha // (glow_layer + 2))
                    glow_color = (*particle["color"], glow_alpha)
                    pygame.draw.circle(glow_surf, glow_color, glow_center, glow_r)

                # 중심부 연기
                core_color = (*particle["color"], smoke_alpha)
                pygame.draw.circle(glow_surf, core_color, glow_center, smoke_size)

                surface.blit(glow_surf, glow_surf.get_rect(center=(px, py)), special_flags=pygame.BLEND_ADD)
            except Exception:
                pygame.draw.circle(surface, color[:3], (px, py), psize // 2)

        elif particle_type == "dark_explosion":
            # 어둠의 폭발 파티클: 빛나는 원형 + 꼬리
            try:
                max_life = particle.get("max_life", 25)
                life_ratio = particle["life"] / max_life
                explosion_alpha = int(255 * life_ratio)
                explosion_size = int(psize * life_ratio)

                # 꼬리 효과 (이전 위치로부터)
                tail_length = 3
                vx = particle.get("vx", 0)
                vy = particle.get("vy", 0)
                for t in range(tail_length):
                    tail_x = px - int(vx * t * 0.5)
                    tail_y = py - int(vy * t * 0.5)
                    tail_alpha = max(20, explosion_alpha // (t + 2))
                    tail_size = max(1, explosion_size - t)
                    tail_color = (*particle["color"], tail_alpha)
                    tail_surf = pygame.Surface((tail_size * 2 + 4, tail_size * 2 + 4), pygame.SRCALPHA)
                    pygame.draw.circle(tail_surf, tail_color, (tail_size + 2, tail_size + 2), tail_size)
                    surface.blit(tail_surf, tail_surf.get_rect(center=(tail_x, tail_y)), special_flags=pygame.BLEND_ADD)

                # 메인 폭발 파티클
                explosion_surf = pygame.Surface((explosion_size * 3, explosion_size * 3), pygame.SRCALPHA)
                exp_center = (explosion_size * 3 // 2, explosion_size * 3 // 2)
                # 외곽 글로우
                pygame.draw.circle(explosion_surf, (*particle["color"], explosion_alpha // 3), exp_center, explosion_size + 4)
                # 코어
                pygame.draw.circle(explosion_surf, (150, 80, 180, explosion_alpha), exp_center, explosion_size)
                # 밝은 중심
                pygame.draw.circle(explosion_surf, (200, 150, 220, explosion_alpha), exp_center, max(1, explosion_size // 2))

                surface.blit(explosion_surf, explosion_surf.get_rect(center=(px, py)), special_flags=pygame.BLEND_ADD)
            except Exception:
                pygame.draw.circle(surface, color[:3], (px, py), psize // 2)

        else:
            # 기본 파티클 (기존 로직)
            particle_rect = pygame.Rect(
                int(particle["x"] - psize / 2 + offset_x),
                int(particle["y"] - psize / 2 + offset_y),
                psize,
                psize
            )
            # pygame.draw가 RGBA를 지원하므로 직접 그린다.
            pygame.draw.rect(surface, color, particle_rect)

    global blacksmith_hammer_explosions, screen_shake_timer, screen_shake_intensity
    global blacksmith_hammer_return_fx
    updated_explosions: list[dict[str, object]] = []
    for explosion in blacksmith_hammer_explosions:
        life = int(explosion.get("life", 0))
        if life <= 0:
            continue
        max_life = explosion.get("max_life", 1)
        remaining_ratio = max(0.0, min(1.0, life / max_life))
        progress = 1.0 - remaining_ratio  # 진행도 (0에서 1로)
        frame = max(0, int(explosion.get("max_life", 0)) - life)
        scale = 1.0 + 0.35 * (1.0 - remaining_ratio)
        base_surface: pygame.Surface = explosion["surface"]  # type: ignore[index]
        center_x, center_y = explosion["center"]  # type: ignore[index]
        base_radius = float(explosion.get("radius", max(base_surface.get_width(), base_surface.get_height()) * 0.25))
        
        # 폭발 시작 시 화면 흔들림 효과 추가 (첫 프레임에만)
        if explosion.get("first_frame", True):
            explosion["first_frame"] = False
            stage = explosion.get("stage", 1)
            # Stage별 화면 흔들림 강도
            if stage >= 3:
                screen_shake_timer = 30  # 0.5초
                screen_shake_intensity = 20  # 매우 강한 흔들림
            elif stage >= 2:
                screen_shake_timer = 20  # 0.33초
                screen_shake_intensity = 12  # 중간 흔들림
            else:
                screen_shake_timer = 15  # 0.25초
                screen_shake_intensity = 8   # 약한 흔들림
        
        # 충격파 링 효과 추가
        stage_value = int(explosion.get("stage", 1))
        ring_palette = explosion.get("ring_palette")
        glyph_color_rgb = explosion.get("glyph_color")
        spark_color_rgb = explosion.get("spark_color")
        halo_color_rgb = explosion.get("halo_color")
        antimatter_rgba = explosion.get("antimatter_color")

        num_rings = 2 + (stage_value - 1)  # Stage별 링 개수
        for ring_idx in range(num_rings):
            ring_delay = ring_idx * 0.15  # 각 링의 지연 시간
            if progress > ring_delay:
                ring_progress = (progress - ring_delay) / (1.0 - ring_delay)
                ring_radius = base_radius + ring_progress * base_radius * 2
                ring_alpha = int(100 * (1.0 - ring_progress) * remaining_ratio)
                ring_thickness = max(1, int(4 - ring_progress * 3))
                
                if ring_alpha > 10 and ring_radius < base_radius * 4:
                    ring_color: tuple[int, int, int, int]
                    custom_palette = ring_palette if isinstance(ring_palette, (list, tuple)) else None
                    if custom_palette:
                        palette_color = custom_palette[min(ring_idx, len(custom_palette) - 1)]
                        if isinstance(palette_color, (list, tuple)) and len(palette_color) >= 3:
                            ring_color = (
                                int(palette_color[0]),
                                int(palette_color[1]),
                                int(palette_color[2]),
                                ring_alpha,
                            )
                        else:
                            ring_color = (255, 255, 255, ring_alpha)
                    else:
                        if stage_value >= 3:
                            ring_color = (210, 245, 255, ring_alpha)
                        elif stage_value >= 2:
                            ring_color = (200, 224, 255, ring_alpha)
                        else:
                            ring_color = (245, 250, 255, ring_alpha)
                    
                    pygame.draw.circle(surface, ring_color, 
                                     (int(center_x + offset_x), int(center_y + offset_y)), 
                                     int(ring_radius), ring_thickness)

        # 스케일 캐시 사용으로 per-frame smoothscale 제거
        scaled_surface = _get_scaled_explosion_surface(int(explosion.get("stage", 1)), scale)
        fade_alpha = int(220 * remaining_ratio)
        rect = scaled_surface.get_rect(center=(int(center_x + offset_x), int(center_y + offset_y)))
        prev_alpha = scaled_surface.get_alpha()
        scaled_surface.set_alpha(fade_alpha)
        surface.blit(scaled_surface, rect, special_flags=pygame.BLEND_ADD)
        # 공유 서피스이므로 알파 원복
        scaled_surface.set_alpha(prev_alpha)

        halo_radius = base_radius * (1.05 + 0.25 * (1 - remaining_ratio))
        if isinstance(halo_color_rgb, (list, tuple)) and len(halo_color_rgb) >= 3:
            halo_rgb = (int(halo_color_rgb[0]), int(halo_color_rgb[1]), int(halo_color_rgb[2]))
            halo_alpha = int(110 * remaining_ratio)
        else:
            halo_rgb = (160, 205 + stage_value * 10, 255)
            halo_alpha = int(120 * remaining_ratio)
        halo_surface = _get_halo_surface(halo_radius, halo_rgb)
        prev_halo_alpha = halo_surface.get_alpha()
        halo_surface.set_alpha(halo_alpha)
        surface.blit(
            halo_surface,
            halo_surface.get_rect(center=(int(center_x + offset_x), int(center_y + offset_y))),
            special_flags=pygame.BLEND_ADD,
        )
        halo_surface.set_alpha(prev_halo_alpha)

        sparks = explosion.get("sparks", [])
        antimatter_rgb = None
        antimatter_alpha = 0
        if isinstance(antimatter_rgba, (list, tuple)) and len(antimatter_rgba) >= 3:
            antimatter_rgb = (
                int(antimatter_rgba[0]),
                int(antimatter_rgba[1]),
                int(antimatter_rgba[2]),
            )
            antimatter_alpha = int(antimatter_rgba[3]) if len(antimatter_rgba) >= 4 else 150
        base_spark_rgb = (
            int(spark_color_rgb[0]),
            int(spark_color_rgb[1]),
            int(spark_color_rgb[2]),
        ) if isinstance(spark_color_rgb, (list, tuple)) and len(spark_color_rgb) >= 3 else (215, 240, 255)
        # 성능 최적화: 스파크 렌더링 단순화 (3개 원 → 1개)
        for angle, dist, size in sparks:
            dist_scaled = dist * scale
            sx = center_x + math.cos(angle) * dist_scaled + offset_x
            sy = center_y + math.sin(angle) * dist_scaled + offset_y
            spark_alpha = int((antimatter_alpha or 160) * remaining_ratio)
            if spark_alpha <= 0:
                continue
            spark_radius = max(2, int(size * scale * 1.2))
            pygame.draw.circle(
                surface,
                (*base_spark_rgb, spark_alpha),
                (int(sx), int(sy)),
                spark_radius,
            )

        explosion["life"] = life - 1
        if explosion["life"] > 0:
            updated_explosions.append(explosion)
    blacksmith_hammer_explosions = updated_explosions

    updated_return_fx: list[dict[str, object]] = []
    for fx in blacksmith_hammer_return_fx:
        life = int(fx.get("life", 0))
        if life <= 0:
            continue
        max_life = max(1, int(fx.get("max_life", 1)))
        remaining_ratio = max(0.0, min(1.0, life / max_life))
        anchor_offset = fx.get("anchor_offset")
        base_center = fx.get("center", (0.0, 0.0))
        if anchor_offset is not None and 'PLAYER' in globals() and PLAYER is not None:
            center_x = PLAYER.centerx + float(anchor_offset[0])
            center_y = PLAYER.centery + float(anchor_offset[1])
        else:
            center_x, center_y = base_center

        size = int(24 + 14 * (1.0 - remaining_ratio))
        size = max(12, size)
        flash_surface = pygame.Surface((size, size), pygame.SRCALPHA)
        radius = size // 2
        intensity = int(220 * remaining_ratio)
        pygame.draw.circle(
            flash_surface,
            (210, 240, 255, intensity),
            (radius, radius),
            max(3, radius // 2),
        )
        pygame.draw.circle(
            flash_surface,
            (255, 255, 255, min(255, intensity + 20)),
            (radius, radius),
            max(2, radius // 3),
        )

        spoke_length = radius
        spoke_alpha = int(200 * remaining_ratio)
        spoke_color = (180, 225, 255, spoke_alpha)
        for angle in (0, math.pi / 2, math.pi / 4, -math.pi / 4):
            dx = math.cos(angle) * spoke_length
            dy = math.sin(angle) * spoke_length
            pygame.draw.aaline(
                flash_surface,
                spoke_color,
                (radius - dx, radius - dy),
                (radius + dx, radius + dy),
            )

        rect = flash_surface.get_rect(
            center=(int(center_x + offset_x), int(center_y + offset_y))
        )
        surface.blit(flash_surface, rect, special_flags=pygame.BLEND_ADD)

        fx["life"] = life - 1
        updated_return_fx.append(fx)

    blacksmith_hammer_return_fx = updated_return_fx
    valthor_perf_end("draw_hammer_shock")

def update_blacksmith_divine_stone(divine_runtime=None, *, auto_sync=True, auto_push=True):
    """디바인 스톤 상태 및 충돌 업데이트.

    Args:
        divine_runtime: 미리 획득한 런타임 객체. 없으면 컨트롤러에서 가져온다.
        auto_sync: True일 때 전역→상태 동기화를 수행한다.
        auto_push: 변경 시 상태→전역 동기화를 수행한다.

    Returns:
        bool: 상태가 변경되었는지 여부.
    """

    global ball_vel, game_vars, last_hit_by
    global blacksmith_divine_destroy_timer, blacksmith_divine_stage_owner
    global blacksmith_divine_stone_state
    global walls
    global blacksmith_divine_blueprint_active, blacksmith_divine_blueprint_rect
    global blacksmith_divine_build_progress, blacksmith_divine_partial_drain

    if divine_runtime is None:
        if auto_sync:
            sync_blacksmith_state()
        state = BLACKSMITH_CONTROLLER.state
        divine_runtime = state.divine
    divine_state = divine_runtime.state

    if divine_state is None:
        return False

    rect = divine_state["rect"]
    # 스테이지 진입 직후 중앙으로 스냅되는 문제 보정: 1프레임 동안 저장된 X로 강제 위치 고정
    try:
        lock = blacksmith_persist_lock_pos
        if lock and lock.get("divine_x") is not None:
            saved_x = int(lock["divine_x"])
            rect.centerx = max(rect.width // 2, min(WIDTH - rect.width // 2, saved_x))
            if int(lock.get("divine_frames", 0)) > 0:
                globals()["blacksmith_persist_lock_pos"]["divine_frames"] = int(lock.get("divine_frames", 0)) - 1
            if int(globals()["blacksmith_persist_lock_pos"]["divine_frames"]) <= 0:
                globals()["blacksmith_persist_lock_pos"]["divine_x"] = None
    except Exception:
        pass
    divine_state["pulse"] = (divine_state.get("pulse", 0) + 1) % 240
    deploy_frames = max(1, BLACKSMITH_DIVINE_DEPLOY_FRAMES)
    current_deploy = int(divine_state.get("deploy_timer", deploy_frames))
    if current_deploy < deploy_frames:
        divine_state["deploy_timer"] = current_deploy + 1
    else:
        divine_state.setdefault("deploy_timer", deploy_frames)
    cooldown = divine_state.get("cooldown", 0)
    if cooldown > 0:
        divine_state["cooldown"] = cooldown - 1

    # 디바인쉴드 보호막/과부하 상태 업데이트 (타이머 → 4겹 보호막 소진형)
    if divine_state.get("shield_active", False):
        shield_hits = int(divine_state.get("shield_hits", 0))
        if shield_hits >= BLACKSMITH_DIVINE_SHIELD_LAYERS:
            _end_divine_shield(divine_state)

    # 과부하 카운트다운
    overheat_timer = int(divine_state.get("shield_overheat", 0))
    if overheat_timer > 0:
        divine_state["shield_overheat"] = overheat_timer - 1
    elif overheat_timer < 0:
        divine_state["shield_overheat"] = 0
    # 건설형 디바인스톤 번개 이펙트/쿨다운 프레임 업데이트
    if divine_state.get("lightning_cd", 0) > 0:
        divine_state["lightning_cd"] = int(divine_state["lightning_cd"]) - 1
    _divine_update_effects(divine_state)

    state_changed = False

    if 'BALL' in globals() and BALL is not None:
        # 강화 디바인스톤에서만 약간 옆쪽 타격이 누락되는 느낌을 줄이기 위해
        # 충돌 판정을 소폭 넓힌 별도 히트박스를 사용한다.
        hit_rect = rect
        try:
            if divine_state.get("reinforced", False):
                # 좌우로만 살짝 확장해 시각적 실루엣과 충돌 판정을 더 잘 맞춘다.
                margin_x = max(2, rect.width // 10)
                hit_rect = rect.inflate(margin_x * 2, 0)
        except Exception:
            hit_rect = rect

        # 디바인스톤 앞에 벽돌이 있을 경우, 벽돌이 먼저 공을 막도록 하고
        # 이 프레임에서는 디바인스톤 충돌 처리를 건너뛴다.
        wall_blocked = False

        # 관통 검사를 위한 헬퍼 함수
        def _line_intersects_rect_divine(x1, y1, x2, y2, rect):
            """선분이 사각형과 교차하는지 확인 (관통 검사용)"""
            r = BALL.width // 2
            left = rect.left - r
            right = rect.right + r
            top = rect.top - r
            bottom = rect.bottom + r
            dx = x2 - x1
            dy = y2 - y1
            t_min, t_max = 0.0, 1.0
            if dx != 0:
                t1 = (left - x1) / dx
                t2 = (right - x1) / dx
                if dx < 0:
                    t1, t2 = t2, t1
                t_min = max(t_min, t1)
                t_max = min(t_max, t2)
            elif x1 < left or x1 > right:
                return False
            if dy != 0:
                t1 = (top - y1) / dy
                t2 = (bottom - y1) / dy
                if dy < 0:
                    t1, t2 = t2, t1
                t_min = max(t_min, t1)
                t_max = min(t_max, t2)
            elif y1 < top or y1 > bottom:
                return False
            return t_min <= t_max

        try:
            try:
                ball_owner = getattr(game_vars.ball, "last_hit_by", None)
            except Exception:
                ball_owner = last_hit_by
            # 이전 공 위치 가져오기
            prev_x = ball_prev_x
            prev_y = ball_prev_y
            for wall in walls:
                # 플레이어가 친 공(서브 포함)에 대해서는 건물 보호용(group_id) 벽돌은 디바인스톤을 막지 않는다.
                if ball_owner == "player" and wall.get("group_id") is not None:
                    continue
                wall_rect = wall["rect"]
                # 현재 충돌 또는 관통 체크
                if BALL.colliderect(wall_rect):
                    wall_blocked = True
                    break
                # 관통 체크
                if _line_intersects_rect_divine(prev_x + BALL.width//2, prev_y + BALL.height//2,
                                                BALL.centerx, BALL.centery, wall_rect):
                    wall_blocked = True
                    # print(f"[DEBUG] 벽돌 관통 감지 (디바인스톤 보호)!")  # 디버그 비활성화
                    break
        except Exception:
            wall_blocked = False

        # 디바인스톤 충돌 체크: 현재 충돌 또는 관통
        prev_x = ball_prev_x
        prev_y = ball_prev_y
        divine_collision = hit_rect.colliderect(BALL) or _line_intersects_rect_divine(
            prev_x + BALL.width//2, prev_y + BALL.height//2,
            BALL.centerx, BALL.centery, hit_rect
        )

        if (not wall_blocked) and divine_collision and divine_state.get("cooldown", 0) == 0:
            BALL.bottom = min(BALL.bottom, rect.top - 2)
            ball_vel[1] = -abs(ball_vel[1]) - 4
            ball_vel[0] *= 0.6

            ball_owner = None
            try:
                ball_owner = getattr(game_vars.ball, "last_hit_by", None)
            except Exception:
                ball_owner = None
            if not ball_owner:
                ball_owner = last_hit_by

            if ball_owner == "player":
                try:
                    last_hit_by = "player"
                    game_vars.ball.last_hit_by = "player"
                except Exception:
                    pass
                divine_state["cooldown"] = int(0.25 * FPS)
            else:
                smoke_protected = is_rect_in_smoke(rect)
                # 디바인쉴드 활성 중에는 체력이 감소하지 않는다.
                shield_active = bool(divine_state.get("shield_active", False))
                if not smoke_protected and not shield_active:
                    divine_state["hp"] = max(0, divine_state.get("hp", BLACKSMITH_DIVINE_STONE_MAX_HP) - 1)  # 연막 보호 시 체력 유지
                    _cancel_repair_job("divine", state=divine_state)
                    # 손상 효과 업데이트
                    damage_manager = get_damage_manager()
                    damage_manager.update_building_hp("divine_stone", divine_state["hp"])
                divine_state["cooldown"] = int(0.25 * FPS)
                effects_manager.spawn_star_particles(rect.centerx, rect.top, count=5)
                effects_manager.spawn_flame_particles(rect.centerx, rect.centery, count=4)
                state_changed = True
                if not smoke_protected and divine_state["hp"] <= 0:
                    effects_manager.create_impact_effect(rect.centerx, rect.centery, 70, is_player=False)
                    # 런타임/전역 상태를 즉시 정리해 UI와 필드에서 제거한다.
                    blacksmith_divine_destroy_timer = 0
                    blacksmith_divine_stage_owner = None
                    # 손상 효과 즉시 제거
                    damage_manager = get_damage_manager()
                    damage_manager.clear_building("divine_stone")
                    divine_runtime.state = None
                    divine_runtime.blueprint_active = False
                    divine_runtime.blueprint_rect = None
                    divine_runtime.build_progress = 0
                    divine_runtime.partial_drain = 0.0
                    # 포탑 없이도 레거시 전역 상태가 남지 않도록 즉시 동기화한다.
                    blacksmith_divine_stone_state = None
                    blacksmith_divine_blueprint_active = False
                    blacksmith_divine_blueprint_rect = None
                    blacksmith_divine_build_progress = 0
                    blacksmith_divine_partial_drain = 0.0
                    state_changed = True

    if state_changed and auto_push:
        push_blacksmith_state()
    return state_changed

# === 디바인스톤 번개 요격 이펙트 헬퍼 ===
def _divine_gen_lightning(start_xy, end_xy):
    sx, sy = start_xy
    ex, ey = end_xy
    pts = [(int(sx), int(sy)), (int(ex), int(ey))]

    def subdivide(points, disp):
        if disp < 6:
            return points
        out = [points[0]]
        for i in range(len(points) - 1):
            x1, y1 = points[i]
            x2, y2 = points[i + 1]
            mx = (x1 + x2) / 2
            my = (y1 + y2) / 2
            dx = x2 - x1
            dy = y2 - y1
            length = math.hypot(dx, dy) or 1.0
            nx = -dy / length
            ny = dx / length
            offset = random.uniform(-disp, disp)
            mx += nx * offset
            my += ny * offset
            out.append((int(mx), int(my)))
            out.append((x2, y2))
        return subdivide(out, disp * 0.55)

    main = subdivide(pts, max(12.0, math.hypot(ex - sx, ey - sy) * 0.08))

    branches = []
    if len(main) > 4:
        branch_count = 1 if random.random() < 0.6 else 2
        for _ in range(branch_count):
            idx = random.randrange(len(main) // 2, len(main) - 1)
            bx, by = main[idx]
            dirx = ex - bx
            diry = ey - by
            blen = max(18, int(math.hypot(dirx, diry) * 0.25))
            ang = math.atan2(diry, dirx) + random.uniform(-0.6, 0.6)
            ex2 = int(bx + math.cos(ang) * blen)
            ey2 = int(by + math.sin(ang) * blen)
            branches.append(subdivide([(bx, by), (ex2, ey2)], max(8.0, blen * 0.12)))
    return main, branches

def _divine_spawn_sparks(divine_state, x, y, count=14):
    sparks = divine_state.get("sparks")
    if sparks is None:
        sparks = []
        divine_state["sparks"] = sparks
    for _ in range(count):
        ang = random.uniform(0, math.tau)
        spd = random.uniform(3.0, 7.0)
        sparks.append({
            'x': float(x), 'y': float(y),
            'vx': math.cos(ang) * spd,
            'vy': math.sin(ang) * spd,
            'life': random.randint(14, 24),
            'size': random.uniform(1.5, 3.0)
        })

def _divine_update_effects(divine_state):
    # TTL 감소
    if divine_state is None:
        return
    lt = int(divine_state.get("lightning_ttl", 0))
    if lt > 0:
        divine_state["lightning_ttl"] = lt - 1
        if divine_state["lightning_ttl"] <= 0:
            divine_state.pop("lightning_path", None)
            divine_state.pop("lightning_branches", None)
    et = int(divine_state.get("explosion_ttl", 0))
    if et > 0:
        divine_state["explosion_ttl"] = et - 1
        # 반지름 업데이트는 드로우에서 계산
    # 스파크 업데이트
    sparks = divine_state.get("sparks")
    if sparks:
        kept = []
        for p in sparks:
            p['x'] += p['vx']
            p['y'] += p['vy']
            p['vy'] += 0.08
            p['life'] -= 1
            if p['life'] > 0:
                kept.append(p)
        divine_state['sparks'] = kept

def _divine_draw_effects(surface, divine_state):
    if divine_state is None:
        return
    reinforced = bool(divine_state.get("reinforced", False))
    # 번개
    if divine_state.get("lightning_ttl", 0) > 0 and divine_state.get("lightning_path"):
        if reinforced:
            core = (255, 150, 140)
            glow = (220, 70, 90, 110)
        else:
            core = (255, 255, 180)
            glow = (170, 210, 255, 90)
        all_pts = list(divine_state["lightning_path"])
        for br in divine_state.get("lightning_branches", []):
            all_pts.extend(br)
        if all_pts:
            min_x = min(p[0] for p in all_pts)
            max_x = max(p[0] for p in all_pts)
            min_y = min(p[1] for p in all_pts)
            max_y = max(p[1] for p in all_pts)
            margin = 18
            w = max(2, (max_x - min_x) + margin * 2)
            h = max(2, (max_y - min_y) + margin * 2)
            offx, offy = min_x - margin, min_y - margin
            glow_surf = pygame.Surface((w, h), pygame.SRCALPHA)
            def _off(pts):
                return [(px - offx, py - offy) for (px, py) in pts]
            pygame.draw.lines(glow_surf, glow, False, _off(divine_state["lightning_path"]), 6)
            for br in divine_state.get("lightning_branches", []):
                if len(br) >= 2:
                    pygame.draw.lines(glow_surf, glow, False, _off(br), 4)
            surface.blit(glow_surf, (offx, offy))
            pygame.draw.lines(surface, core, False, divine_state["lightning_path"], 2)
            for br in divine_state.get("lightning_branches", []):
                if len(br) >= 2:
                    pygame.draw.lines(surface, core, False, br, 1)

    # 폭발
    if divine_state.get("explosion_ttl", 0) > 0:
        cx, cy = divine_state.get("explosion_center", (0, 0))
        life = max(1, int(divine_state["explosion_ttl"]))
        max_life = max(1, int(0.22 * FPS))
        life_ratio = life / max_life
        r = int(8 + (1 - life_ratio) * 36)
        alpha = int(220 * life_ratio)
        core_surf = pygame.Surface((r * 4, r * 4), pygame.SRCALPHA)
        if reinforced:
            core_color = (255, 150, 150, alpha)
            inner_color = (255, 230, 230, int(alpha * 0.6))
            ring_color = (220, 80, 120, ring_alpha)
        else:
            core_color = (255, 255, 200, alpha)
            inner_color = (255, 255, 255, int(alpha * 0.6))
            ring_color = (180, 220, 255, ring_alpha)
        pygame.draw.circle(core_surf, core_color, (r * 2, r * 2), int(r * 0.6))
        pygame.draw.circle(core_surf, inner_color, (r * 2, r * 2), int(r * 0.35))
        surface.blit(core_surf, (cx - r * 2, cy - r * 2), special_flags=pygame.BLEND_ADD)
        ring_alpha = int(180 * life_ratio)
        if ring_alpha > 0 and r > 4:
            ring_surf = pygame.Surface((r * 2 + 6, r * 2 + 6), pygame.SRCALPHA)
            pygame.draw.circle(ring_surf, ring_color, (r + 3, r + 3), r, 2)
            surface.blit(ring_surf, (cx - r - 3, cy - r - 3))
    # 스파크
    sparks = divine_state.get("sparks") or []
    for p in sparks:
        s = max(1, int(p['size']))
        ex = int(p['x'] + p['vx'] * 0.6)
        ey = int(p['y'] + p['vy'] * 0.6)
        if reinforced:
            spark_color = (255, 170, 150)
            core_color = (255, 230, 220)
        else:
            spark_color = (255, 240, 180)
            core_color = (255, 255, 255)
        pygame.draw.line(surface, spark_color, (int(p['x']), int(p['y'])), (ex, ey), 1)
        pygame.draw.circle(surface, core_color, (int(p['x']), int(p['y'])), max(1, s // 2))

    # 디바인쉴드 비주얼: 신비로운 고대 드워프 마법 쉴드 구체가 건물들을 감싸며 회전
    shield_active = bool(divine_state.get("shield_active", False))
    if shield_active:
        try:
            centers: list[tuple[int, int]] = []
            # 디바인스톤 중심
            rect = divine_state.get("rect")
            if rect is not None:
                centers.append(rect.center)
            # 포탑 중심 (필드에 있을 때만)
            turret_state = BLACKSMITH_CONTROLLER.state.turret.state
            if turret_state and turret_state.get("rect") is not None:
                centers.append(turret_state["rect"].center)
            if centers:
                t = pygame.time.get_ticks() / 1000.0

                # 전체 건물들을 감싸는 중심점과 반경 계산
                if len(centers) == 1:
                    group_cx, group_cy = centers[0]
                    group_radius = 55
                else:
                    # 여러 건물일 경우 중심점 계산
                    sum_x = sum(c[0] for c in centers)
                    sum_y = sum(c[1] for c in centers)
                    group_cx = sum_x // len(centers)
                    group_cy = sum_y // len(centers)
                    # 모든 건물을 포함하는 반경
                    max_dist = max(math.hypot(c[0] - group_cx, c[1] - group_cy) for c in centers)
                    group_radius = int(max_dist + 50)

                # === 신비로운 고대 드워프 마법 쉴드 ===
                shield_size = max(160, int(group_radius * 2 + 120))
                shield_center = (shield_size // 2, shield_size // 2)
                shield_hits = divine_state.get("shield_hits", 0)
                cache_key = (int(group_radius), shield_hits, reinforced)

                base_surf = _divine_shield_base_cache.get(cache_key)
                if base_surf is None or base_surf.get_size() != (shield_size, shield_size):
                    base_surf = pygame.Surface((shield_size, shield_size), pygame.SRCALPHA)
                    remaining_rings = max(0, BLACKSMITH_DIVINE_SHIELD_LAYERS - shield_hits)

                    for ring_layer in range(remaining_rings):
                        ring_radius = group_radius + 10 - ring_layer * 6
                        ring_alpha = 140 - ring_layer * 25
                        # 황금빛 + 청록빛 그라데이션 (드워프 마법)
                        if ring_layer == 0:
                            ring_color = (255, 215, 100, ring_alpha)  # 금색
                        elif ring_layer == 1:
                            ring_color = (100, 200, 255, ring_alpha)  # 시안
                        elif ring_layer == 2:
                            ring_color = (180, 160, 255, ring_alpha)  # 연보라
                        else:
                            ring_color = (255, 180, 220, ring_alpha)  # 연분홍

                        pygame.draw.circle(base_surf, ring_color, shield_center, ring_radius, 2)
                    _divine_shield_base_cache[cache_key] = base_surf

                # === 디바인쉴드 렌더링 최적화 ===
                # 동적 요소(룬, 구체, 스파클)는 프레임 스킵으로 성능 향상
                global _divine_shield_frame_counter, _divine_shield_last_dynamic_surf
                global _divine_shield_dynamic_cache_key

                _divine_shield_frame_counter += 1
                dynamic_cache_key = (int(group_radius), shield_hits, reinforced, int(group_cx), int(group_cy))
                need_dynamic_update = (
                    _divine_shield_frame_counter % DIVINE_SHIELD_DYNAMIC_SKIP_FRAMES == 0
                    or _divine_shield_last_dynamic_surf is None
                    or _divine_shield_dynamic_cache_key != dynamic_cache_key
                )

                # === 최적화: 전역 캐시 서피스를 직접 사용 (copy() 제거) ===
                required_size = base_surf.get_size()
                if _divine_shield_last_dynamic_surf is None or _divine_shield_last_dynamic_surf.get_size() != required_size:
                    _divine_shield_last_dynamic_surf = pygame.Surface(required_size, pygame.SRCALPHA)
                    need_dynamic_update = True

                # 파장 출렁임 이펙트 (피격 시 발생)
                ripple_effects = divine_state.get("shield_ripple_effects", [])
                has_ripples = bool(ripple_effects)

                # 동적 요소 렌더링 (프레임 스킵 적용)
                if need_dynamic_update:
                    _divine_shield_last_dynamic_surf.fill((0, 0, 0, 0))
                    _divine_shield_last_dynamic_surf.blit(base_surf, (0, 0))

                    # 2. 회전하는 룬 심볼들 - 개수 줄임 (6 -> 4)
                    rune_count = 4
                    rune_orbit_radius = group_radius + 5
                    rune_rotation_speed = 0.8
                    for i in range(rune_count):
                        base_angle = (2 * math.pi * i / rune_count) + t * rune_rotation_speed
                        rx = shield_center[0] + math.cos(base_angle) * rune_orbit_radius
                        ry = shield_center[1] + math.sin(base_angle) * rune_orbit_radius
                        rune_size = 4
                        rune_alpha = int(180 + 50 * math.sin(t * 3 + i))
                        rune_color = (255, 230, 150, rune_alpha)
                        rune_points = [
                            (rx, ry - rune_size),
                            (rx + rune_size, ry),
                            (rx, ry + rune_size),
                            (rx - rune_size, ry)
                        ]
                        pygame.draw.polygon(_divine_shield_last_dynamic_surf, rune_color, rune_points)

                    # 3. 회전하는 에너지 구체들 - 개수 줄임 (4 -> 3), 글로우 제거
                    orb_count = 3
                    orb_orbit_radius = group_radius - 5
                    orb_rotation_speed = 1.2
                    for i in range(orb_count):
                        orb_angle = (2 * math.pi * i / orb_count) + t * orb_rotation_speed * (1 + i * 0.1)
                        orb_y_offset = math.sin(t * 2 + i * 0.5) * 8
                        ox = shield_center[0] + math.cos(orb_angle) * orb_orbit_radius
                        oy = shield_center[1] + math.sin(orb_angle) * (orb_orbit_radius * 0.6) + orb_y_offset
                        depth = math.sin(orb_angle)
                        orb_size = int(6 + 3 * depth)
                        orb_alpha = int(200 + 55 * depth)
                        if i % 3 == 0:
                            orb_base_color = (100, 255, 230)
                        elif i % 3 == 1:
                            orb_base_color = (255, 220, 100)
                        else:
                            orb_base_color = (180, 200, 255)
                        orb_color = (*orb_base_color, orb_alpha)
                        pygame.draw.circle(_divine_shield_last_dynamic_surf, orb_color, (int(ox), int(oy)), orb_size)

                    # 5. 에너지 파동 효과
                    wave_period = 2.0
                    wave_progress = (t % wave_period) / wave_period
                    wave_radius = int(group_radius * 0.3 + group_radius * 0.7 * wave_progress)
                    wave_alpha = int(80 * (1 - wave_progress))
                    pygame.draw.circle(_divine_shield_last_dynamic_surf, (200, 255, 255, wave_alpha), shield_center, wave_radius, 2)

                    # 6. 마법 입자들 (스파클) - 개수 줄임 (6 -> 4)
                    spark_pattern_key = cache_key
                    spark_pattern = divine_state.get("shield_spark_pattern")
                    if (
                        not spark_pattern
                        or divine_state.get("shield_spark_pattern_key") != spark_pattern_key
                    ):
                        rng_seed = divine_state.get("shield_seed", random.randint(1, 1_000_000))
                        divine_state["shield_seed"] = rng_seed
                        rng = random.Random(rng_seed)
                        spark_pattern = []
                        colors = [(255, 255, 200), (200, 255, 255), (255, 200, 255)]
                        for _ in range(4):
                            spark_pattern.append(
                                (
                                    rng.uniform(0, 2 * math.pi),
                                    rng.uniform(group_radius * 0.3, group_radius * 0.9),
                                    rng.randint(1, 2),
                                    colors[rng.randrange(len(colors))],
                                    rng.random(),
                                )
                            )
                        divine_state["shield_spark_pattern"] = spark_pattern
                        divine_state["shield_spark_pattern_key"] = spark_pattern_key

                    for angle_base, spark_dist, spark_size, spark_rgb, phase in spark_pattern:
                        spark_angle = angle_base + t * 0.7
                        sx = shield_center[0] + math.cos(spark_angle) * spark_dist
                        sy = shield_center[1] + math.sin(spark_angle) * spark_dist
                        spark_alpha = int(120 + 80 * (0.5 + 0.5 * math.sin(t * 2 + phase * 6)))
                        pygame.draw.circle(
                            _divine_shield_last_dynamic_surf,
                            (*spark_rgb, spark_alpha),
                            (int(sx), int(sy)),
                            spark_size,
                        )

                    _divine_shield_dynamic_cache_key = dynamic_cache_key

                # 리플이 있으면 별도 작업 서피스에서 합성 (캐시 오염 방지)
                if has_ripples:
                    shield_work = divine_state.get("_shield_work")
                    if shield_work is None or shield_work.get_size() != required_size:
                        shield_work = pygame.Surface(required_size, pygame.SRCALPHA)
                        divine_state["_shield_work"] = shield_work
                    shield_work.fill((0, 0, 0, 0))
                    shield_work.blit(_divine_shield_last_dynamic_surf, (0, 0))

                    for ripple in ripple_effects[:]:
                        ripple_progress = ripple["progress"]
                        ripple_radius = int(group_radius * (0.8 + 0.4 * ripple_progress))
                        ripple_alpha = int(200 * (1 - ripple_progress))
                        ripple_thickness = max(1, int(4 * (1 - ripple_progress)))
                        pygame.draw.circle(shield_work, (255, 255, 255, ripple_alpha),
                                         shield_center, ripple_radius, ripple_thickness)
                        ripple["progress"] += 0.05
                        if ripple["progress"] >= 1.0:
                            ripple_effects.remove(ripple)
                    divine_state["shield_ripple_effects"] = ripple_effects
                    shield_surf = shield_work
                else:
                    # 리플 없으면 캐시 직접 사용 (복사 없음!)
                    shield_surf = _divine_shield_last_dynamic_surf

                # 서피스를 화면에 그리기
                surface.blit(
                    shield_surf,
                    shield_surf.get_rect(center=(int(group_cx), int(group_cy))),
                    special_flags=pygame.BLEND_ADD,
                )

                # 7. 각 건물 주변 개별 보호막 효과 (비활성화)
                #    └ 디자인 변경: 각 건물에 덮어지는 흰색 원구체가
                #       건물 시인성을 해쳐 비활성화함.
                # for idx, (cx, cy) in enumerate(centers):
                #     # 각 건물 주위의 작은 보호 구체
                #     local_radius = 35
                #     local_pulse = 1.0 + 0.1 * math.sin(t * 3 + idx)
                #     local_r = int(local_radius * local_pulse)
                #
                #     local_surf = pygame.Surface((local_r * 2 + 20, local_r * 2 + 20), pygame.SRCALPHA)
                #     local_center = (local_r + 10, local_r + 10)
                #
                #     # 보호막 외곽
                #     pygame.draw.circle(local_surf, (100, 255, 230, 60), local_center, local_r, 2)
                #     # 보호막 내부 글로우
                #     pygame.draw.circle(local_surf, (180, 255, 240, 25), local_center, local_r - 3)
                #
                #     surface.blit(
                #         local_surf,
                #         local_surf.get_rect(center=(int(cx), int(cy))),
                #         special_flags=pygame.BLEND_ADD,
                #     )

        except Exception:
            pass

