def _finalize_blacksmith_turret_removal(turret_runtime):
    """포탑 런타임 상태를 완전히 초기화해 필드에서 제거한다."""

    # 손상 효과 매니저에서 포탑 제거
    damage_manager = get_damage_manager()
    damage_manager.clear_building("turret")
    
    # turret_runtime: BlacksmithTurretRuntime
    turret_runtime.active = False
    turret_runtime.state = None
    turret_runtime.blueprint_active = False
    turret_runtime.blueprint_rect = None
    turret_runtime.build_progress = 0
    turret_runtime.projectiles.clear()
    turret_runtime.partial_drain = 0.0
    turret_runtime.xp_partial_drain = 0.0
    turret_runtime.manual_cooldown = 0
    turret_runtime.overdrive_ui_timer = 0
    turret_runtime.overdrive_ui_divine = False
    turret_runtime.overheat_timer = 0
    turret_runtime.overheat_smoke_timer = 0
    turret_runtime.overdrive_ui_timer = 0
    stop_blacksmith_construction_sound()

    # 레거시 전역 상태도 즉시 정리해 유령 포탑이 남지 않도록 한다.
    namespace = globals()
    namespace["blacksmith_turret_active"] = False
    namespace["blacksmith_turret_state"] = None
    namespace["blacksmith_turret_projectiles"] = []
    namespace["blacksmith_turret_blueprint_active"] = False
    namespace["blacksmith_turret_blueprint_rect"] = None
    namespace["blacksmith_turret_build_progress"] = 0
    namespace["blacksmith_turret_partial_drain"] = 0.0
    namespace["blacksmith_turret_xp_partial_drain"] = 0.0
    namespace["blacksmith_turret_manual_cooldown"] = 0
    namespace["blacksmith_turret_destroy_timer"] = 0
    namespace["blacksmith_turret_overdrive_ui_timer"] = 0
    namespace["blacksmith_turret_overdrive_ui_divine"] = False
    namespace["blacksmith_turret_overheat_timer"] = 0
    namespace["blacksmith_turret_overheat_smoke_timer"] = 0


def _blacksmith_fire_turret_projectile(turret_runtime, turret_state, *, overdrive: bool = False) -> None:
    """포탑에서 포탄을 발사하고 연출을 적용한다."""

    turret_rect = turret_state.get("rect")
    # 스테이지 진입 직후 중앙으로 스냅되는 문제 보정: 1프레임 동안 저장된 X로 강제 위치 고정
    try:
        lock = blacksmith_persist_lock_pos
        if lock and lock.get("turret_x") is not None and turret_rect is not None:
            saved_x = int(lock["turret_x"])
            turret_rect.centerx = max(turret_rect.width // 2, min(WIDTH - turret_rect.width // 2, saved_x))
            if int(lock.get("turret_frames", 0)) > 0:
                globals()["blacksmith_persist_lock_pos"]["turret_frames"] = int(lock.get("turret_frames", 0)) - 1
            if int(globals()["blacksmith_persist_lock_pos"]["turret_frames"]) <= 0:
                globals()["blacksmith_persist_lock_pos"]["turret_x"] = None
    except Exception:
        pass
    if turret_rect is None:
        return

    display_angle = turret_state.get("display_angle", -math.pi / 2)
    direction = pygame.math.Vector2(math.cos(display_angle), math.sin(display_angle))
    if direction.length() == 0:
        direction = pygame.math.Vector2(0, -1)
    else:
        direction = direction.normalize()

    scale_x = turret_rect.width / BLACKSMITH_TURRET_DESIGN_WIDTH
    scale_y = turret_rect.height / BLACKSMITH_TURRET_DESIGN_HEIGHT

    recoil_frames = BLACKSMITH_TURRET_RECOIL_FRAMES
    recoil_distance = BLACKSMITH_TURRET_RECOIL_DISTANCE * (turret_state.get("overdrive_recoil_boost", 1.0) if overdrive else 1.0)

    turret_state["recoil_timer"] = int(recoil_frames * (1.2 if overdrive else 1.0))
    turret_state["recoil_base_distance"] = recoil_distance
    turret_state["recoil_offset"] = recoil_distance * scale_x

    pivot_point = pygame.math.Vector2(
        turret_rect.centerx,
        turret_rect.top + scale_y * BLACKSMITH_TURRET_HEAD_PIVOT_OFFSET,
    )
    pivot_point -= direction * turret_state.get("recoil_offset", 0.0)

    muzzle_distance = BLACKSMITH_TURRET_MUZZLE_LENGTH * scale_x
    spawn_point = pivot_point + direction * (muzzle_distance + BLACKSMITH_TURRET_PROJECTILE_RADIUS + 2)

    base_speed = BLACKSMITH_TURRET_MISSILE_SPEED
    speed_multiplier = turret_state.get("overdrive_speed_boost", 1.0) if overdrive else 1.0
    projectile_speed = base_speed * speed_multiplier

    projectile_radius = BLACKSMITH_TURRET_PROJECTILE_RADIUS
    if overdrive:
        projectile_radius = int(round(BLACKSMITH_TURRET_PROJECTILE_RADIUS * 1.2))

    divine_overdrive = overdrive and turret_state.get("overdrive_divine_active", False)

    projectile = {
        "x": float(spawn_point.x),
        "y": float(spawn_point.y),
        "vx": direction.x * projectile_speed,
        "vy": direction.y * projectile_speed,
        "speed": projectile_speed,
        "life": BLACKSMITH_TURRET_MISSILE_LIFE,
        "radius": projectile_radius,
        "grace_frames": 6,
        "overdrive": overdrive,
        "divine_overdrive": divine_overdrive,
        "trail_timer": 0,
    }
    turret_runtime.projectiles.append(projectile)

    turret_state["fire_timer"] = turret_state.get("fire_interval", BLACKSMITH_TURRET_FIRE_INTERVAL)

    try:
        play_sound_with_volume(SOUND_THROW)
    except Exception:
        pass


def _blacksmith_spawn_homing_missile(turret_runtime, turret_state) -> None:
    """강화 포탑 전용 유도 미사일 한 발을 보스 방향으로 발사."""

    turret_rect = turret_state.get("rect")
    if turret_rect is None:
        return

    boss_rect = BOSS if "BOSS" in globals() else None
    if not boss_rect:
        return

    direction = pygame.math.Vector2(
        boss_rect.centerx - turret_rect.centerx,
        boss_rect.centery - turret_rect.centery,
    )
    if direction.length() == 0:
        direction = pygame.math.Vector2(0, -1)
    else:
        direction = direction.normalize()

    scale_x = turret_rect.width / BLACKSMITH_TURRET_DESIGN_WIDTH
    scale_y = turret_rect.height / BLACKSMITH_TURRET_DESIGN_HEIGHT

    pivot_point = pygame.math.Vector2(
        turret_rect.centerx,
        turret_rect.top + scale_y * BLACKSMITH_TURRET_HEAD_PIVOT_OFFSET,
    )

    radius = int(round(BLACKSMITH_TURRET_PROJECTILE_RADIUS * BLACKSMITH_TURRET_HOMING_RADIUS_SCALE))
    muzzle_distance = BLACKSMITH_TURRET_MUZZLE_LENGTH * scale_x
    spawn_point = pivot_point + direction * (muzzle_distance + radius + 2)

    base_speed = BLACKSMITH_TURRET_MISSILE_SPEED
    initial_speed = base_speed * BLACKSMITH_TURRET_HOMING_SPEED_MULT

    projectile = {
        "x": float(spawn_point.x),
        "y": float(spawn_point.y),
        "vx": direction.x * initial_speed,
        "vy": direction.y * initial_speed,
        "speed": initial_speed,
        "life": BLACKSMITH_TURRET_MISSILE_LIFE,
        "radius": radius,
        "grace_frames": 4,
        "overdrive": False,
        "divine_overdrive": False,
        "trail_timer": 0,
        "homing": True,
        "homing_initial_speed": initial_speed,
        "homing_base_speed": base_speed,
        "homing_age": 0,
        "wobble_phase": random.uniform(0.0, math.tau) if hasattr(math, "tau") else random.uniform(0.0, 2.0 * math.pi),
    }
    turret_runtime.projectiles.append(projectile)


def _emit_blacksmith_turret_overheat_smoke(turret_state) -> None:
    """과부하 상태에서 총구 연기 이펙트를 뿜는다."""

    turret_rect = turret_state.get("rect")
    if turret_rect is None:
        return

    display_angle = turret_state.get("display_angle", -math.pi / 2)
    direction = pygame.math.Vector2(math.cos(display_angle), math.sin(display_angle))
    if direction.length() == 0:
        direction = pygame.math.Vector2(0, -1)
    else:
        direction = direction.normalize()

    scale_x = turret_rect.width / BLACKSMITH_TURRET_DESIGN_WIDTH
    scale_y = turret_rect.height / BLACKSMITH_TURRET_DESIGN_HEIGHT

    pivot_point = pygame.math.Vector2(
        turret_rect.centerx,
        turret_rect.top + scale_y * BLACKSMITH_TURRET_HEAD_PIVOT_OFFSET,
    )
    pivot_point -= direction * turret_state.get("recoil_offset", 0.0)

    muzzle_distance = BLACKSMITH_TURRET_MUZZLE_LENGTH * scale_x
    muzzle_point = pivot_point + direction * (muzzle_distance + BLACKSMITH_TURRET_PROJECTILE_RADIUS + 2)

    try:
        effects_manager.spawn_construction_smoke(
            muzzle_point.x,
            muzzle_point.y,
            count=3,
            spread=14,
        )
    except Exception:
        pass


def _spawn_blacksmith_megadrive_shards(x: float, y: float, radius: float) -> None:
    """메가드라이브 폭발 시 중입자 파편 이펙트."""

    try:
        for _ in range(12):
            angle = random.uniform(0, math.tau)
            speed = random.uniform(2.0, 5.0)
            vx = math.cos(angle) * speed
            vy = math.sin(angle) * speed
            shard_surface = pygame.Surface((8, 8), pygame.SRCALPHA)
            pygame.draw.polygon(
                shard_surface,
                (120, 230, 255, 200),
                [(4, 0), (7, 3), (4, 7), (1, 3)],
            )
            effects_manager.spawn_custom_particle(
                shard_surface,
                x + random.uniform(-radius, radius),
                y + random.uniform(-radius, radius),
                vx,
                vy,
                lifetime_frames=random.randint(int(0.25 * FPS), int(0.45 * FPS)),
                rotation_speed=random.uniform(-0.2, 0.2),
                gravity=-0.02,
                fade_out=True,
            )
    except AttributeError:
        try:
            effects_manager.spawn_star_particles(x, y, count=10)
        except Exception:
            pass


def draw_blacksmith_overheat_overlay(surface: pygame.Surface) -> None:
    """과부하 상태용 화면 오버레이/중앙 경고 출력."""

    if selected_character_type != "blacksmith":
        return

    sync_blacksmith_state()
    turret_state = BLACKSMITH_CONTROLLER.state.turret.state
    overheat_timer = 0
    if turret_state:
        overheat_timer = max(0, int(turret_state.get("overheat_timer", 0)))

    if overheat_timer <= 0:
        return

    duration = max(1, BLACKSMITH_TURRET_OVERHEAT_DURATION)
    frame_value = float(frame_counter)
    pulse = 0.5 + 0.5 * math.sin(frame_value * 0.25)
    intensity = 0.45 + 0.55 * pulse

    overlay = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
    tint_alpha = int(70 + 110 * intensity)
    overlay.fill((255, 90, 60, tint_alpha))
    surface.blit(overlay, (0, 0), special_flags=pygame.BLEND_RGBA_ADD)

    vignette = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
    for idx in range(6):
        radius = max(WIDTH, HEIGHT) - idx * 140
        if radius <= 0:
            continue
        pygame.draw.circle(
            vignette,
            (255, 120, 100, int(40 + 60 * intensity) - idx * 5),
            (WIDTH // 2, HEIGHT // 2),
            radius,
            width=10,
        )
    surface.blit(vignette, (0, 0), special_flags=pygame.BLEND_RGBA_ADD)

    remaining_seconds = overheat_timer / FPS if FPS else overheat_timer
    title_font = FontStyle.large()
    timer_font = FontStyle.medium()
    info_font = FontStyle.tiny()

    title_label = title_font.render(_t("ui.overload", "과부하"), True, (255, 235, 225))
    surface.blit(title_label, title_label.get_rect(center=(WIDTH // 2, HEIGHT // 2 - 28)))

    timer_label = timer_font.render(f"{_t('ui.recovery', '복구')} {remaining_seconds:4.1f}s", True, (255, 210, 195))
    surface.blit(timer_label, timer_label.get_rect(center=(WIDTH // 2, HEIGHT // 2 + 12)))

    info_label = info_font.render(_t("ui.overload_info", "게이지 충전/자동 발사 불가 · 수동 발사만 가능"), True, (255, 190, 175))
    surface.blit(info_label, info_label.get_rect(center=(WIDTH // 2, HEIGHT // 2 + 36)))


def _end_blacksmith_turret_overdrive(turret_state) -> None:
    """오버드라이브 종료 시 상태를 정리한다."""

    base_interval = turret_state.get("base_fire_interval", BLACKSMITH_TURRET_FIRE_INTERVAL)
    turret_state["overdrive_active"] = False
    turret_state["overdrive_timer"] = 0
    turret_state["overdrive_fire_window"] = 0
    turret_state["overdrive_shots_remaining"] = 0
    turret_state["overdrive_shot_cooldown"] = 0
    turret_state["overdrive_glow_phase"] = 0.0
    turret_state["overdrive_flash_timer"] = 0
    turret_state["overdrive_recoil_boost"] = 1.0
    turret_state["overdrive_speed_boost"] = 1.0
    turret_state["overdrive_stun_multiplier"] = 1.0
    turret_state["overdrive_knockback_multiplier"] = 1.0
    turret_state["overdrive_divine_active"] = False
    turret_state["recoil_base_distance"] = BLACKSMITH_TURRET_RECOIL_DISTANCE
    turret_state["fire_interval"] = base_interval
    turret_state["fire_timer"] = max(0, min(turret_state.get("fire_timer", base_interval), base_interval))

    overheat_total = BLACKSMITH_TURRET_OVERHEAT_DURATION
    turret_state["overheat_timer"] = overheat_total
    turret_state["overheat_smoke_timer"] = 0

    try:
        runtime = BLACKSMITH_CONTROLLER.state.turret
        runtime.overheat_timer = overheat_total
        runtime.overheat_smoke_timer = 0
    except Exception:
        pass

    globals()["blacksmith_turret_overheat_timer"] = overheat_total
    globals()["blacksmith_turret_overheat_smoke_timer"] = 0


def _get_blacksmith_overdrive_gradient_surface() -> pygame.Surface | None:
    """오버드라이브 화면 연출용 세로 그라데이션을 반환한다."""

    global BLACKSMITH_OVERDRIVE_GRADIENT_SURFACE

    existing = BLACKSMITH_OVERDRIVE_GRADIENT_SURFACE
    if existing is not None and existing.get_width() == WIDTH and existing.get_height() == HEIGHT:
        return existing

    surface = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
    band_count = 28
    band_height = max(4, HEIGHT // band_count)
    for idx in range(band_count + 2):
        t = idx / max(1, band_count + 1)
        band_alpha = int(28 + 90 * (1.0 - abs(0.5 - t) * 1.8))
        band_alpha = max(0, min(140, band_alpha))
        color = (255, 66, 42, band_alpha)
        y = int(t * HEIGHT)
        pygame.draw.rect(surface, color, (0, y, WIDTH, band_height))

    BLACKSMITH_OVERDRIVE_GRADIENT_SURFACE = surface
    return surface


def _get_blacksmith_overdrive_vignette_surface() -> pygame.Surface | None:
    """오버드라이브 화면 연출용 방사형 비네트를 반환한다."""

    global BLACKSMITH_OVERDRIVE_VIGNETTE_SURFACE

    existing = BLACKSMITH_OVERDRIVE_VIGNETTE_SURFACE
    if existing is not None and existing.get_width() == WIDTH and existing.get_height() == HEIGHT:
        return existing

    surface = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
    center_x = WIDTH // 2
    center_y = int(HEIGHT * 0.42)
    max_radius = int(math.hypot(WIDTH, HEIGHT))
    steps = 18
    for step in range(steps, 0, -1):
        t = step / steps
        alpha = int(12 + 70 * (t ** 1.8))
        radius = max(90, int(max_radius * t))
        pygame.draw.circle(surface, (255, 60, 38, alpha), (center_x, center_y), radius)

    BLACKSMITH_OVERDRIVE_VIGNETTE_SURFACE = surface
    return surface


def draw_blacksmith_overdrive_overlay(surface: pygame.Surface) -> None:
    """오버드라이브 동안 화면 전체에 붉은 파동을 입힌다."""

    if selected_character_type != "blacksmith":
        return

    sync_blacksmith_state()
    turret_runtime = BLACKSMITH_CONTROLLER.state.turret
    turret_state = turret_runtime.state

    if not turret_runtime.active or not turret_state or not turret_state.get("overdrive_active"):
        return

    timer = max(0, turret_state.get("overdrive_timer", 0))
    duration = max(1, BLACKSMITH_TURRET_OVERDRIVE_DURATION)
    elapsed = max(0, duration - timer)
    fade_in = min(1.0, elapsed / max(1.0, 0.35 * FPS))
    fade_out = min(1.0, timer / max(1.0, 0.45 * FPS))
    intensity_gate = min(fade_in, fade_out)

    if intensity_gate <= 0:
        return

    phase = turret_state.get("overdrive_glow_phase", 0.0)
    pulse = 0.5 + 0.5 * math.sin(phase * 0.85)
    base_strength = intensity_gate * (0.55 + 0.45 * pulse)

    gradient = _get_blacksmith_overdrive_gradient_surface()
    vignette = _get_blacksmith_overdrive_vignette_surface()

    if gradient:
        prev_alpha = gradient.get_alpha()
        gradient.set_alpha(int(120 * base_strength))
        surface.blit(gradient, (0, 0))
        gradient.set_alpha(prev_alpha)

    if vignette:
        prev_alpha = vignette.get_alpha()
        vignette.set_alpha(int(150 * base_strength))
        surface.blit(vignette, (0, 0), special_flags=pygame.BLEND_RGBA_ADD)
        vignette.set_alpha(prev_alpha)


def update_blacksmith_turret():
    """발토르 포탑의 발사 및 투사체 동작을 업데이트한다."""
    valthor_perf_start("update_turret")
    global player_collision_handled, last_hit_by
    global ball_vel, stopwatch_active, stopwatch_timer, game_vars, SCREEN
    global blacksmith_turret_destroy_timer, blacksmith_divine_destroy_timer
    global blacksmith_divine_stage_owner, blacksmith_turret_boss_hit_count
    global walls

    damage_manager = get_damage_manager()

    # 포탑 파괴 타이머 처리
    if blacksmith_turret_destroy_timer > 0:
        blacksmith_turret_destroy_timer -= 1
        if blacksmith_turret_destroy_timer == 0:
            # 타이머가 끝나면 포탑 완전 제거
            sync_blacksmith_state()
            state = BLACKSMITH_CONTROLLER.state
            turret_runtime = state.turret
            turret_runtime.active = False
            _finalize_blacksmith_turret_removal(turret_runtime)
            push_blacksmith_state()
    
    # 디바인스톤 파괴 타이머 처리
    if blacksmith_divine_destroy_timer > 0:
        blacksmith_divine_destroy_timer -= 1
        if blacksmith_divine_destroy_timer == 0:
            # 타이머가 끝나면 디바인스톤 완전 제거
            sync_blacksmith_state()
            state = BLACKSMITH_CONTROLLER.state
            divine_runtime = state.divine
            divine_runtime.state = None
            blacksmith_divine_stage_owner = None
            # 손상 효과 매니저에서 디바인스톤 제거
            damage_manager.clear_building("divine_stone")
            push_blacksmith_state()

    sync_blacksmith_state()
    state = BLACKSMITH_CONTROLLER.state
    turret_runtime = state.turret
    divine_runtime = state.divine

    update_blacksmith_divine_stone(divine_runtime, auto_sync=False, auto_push=False)

    turret_state = turret_runtime.state

    if turret_runtime.manual_cooldown > 0:
        turret_runtime.manual_cooldown -= 1

    if not turret_runtime.active or not turret_state:
        if turret_state is not None and (
            not turret_runtime.active
            or turret_state.get("hp", 0) <= 0
        ):
            _finalize_blacksmith_turret_removal(turret_runtime)
            turret_state = None
        else:
            turret_runtime.projectiles.clear()
            turret_runtime.manual_cooldown = 0
            turret_runtime.xp_partial_drain = 0.0
            # 포탑/디바인스톤 청사진 둘 다 비활성화이고, 망치질도 활성화 안됐을 때만 사운드 중지
            divine_runtime = BLACKSMITH_CONTROLLER.state.divine
            if not turret_runtime.blueprint_active and not divine_runtime.blueprint_active and not blacksmith_hammer_swing_active:
                stop_blacksmith_construction_sound()
        push_blacksmith_state()
        return

    turret_rect = turret_state.get("rect")
    if turret_rect is None:
        turret_runtime.active = False
        turret_runtime.projectiles.clear()
        turret_runtime.manual_cooldown = 0
        turret_runtime.xp_partial_drain = 0.0
        # 포탑/디바인스톤 청사진 둘 다 비활성화이고, 망치질도 활성화 안됐을 때만 사운드 중지
        divine_runtime = BLACKSMITH_CONTROLLER.state.divine
        if not turret_runtime.blueprint_active and not divine_runtime.blueprint_active and not blacksmith_hammer_swing_active:
            stop_blacksmith_construction_sound()
        push_blacksmith_state()
        return

    scale_factor = turret_rect.width / BLACKSMITH_TURRET_DESIGN_WIDTH
    boss_rect = BOSS if 'BOSS' in globals() else None
    target_angle = -math.pi / 2
    if boss_rect:
        target_angle = math.atan2(
            boss_rect.centery - turret_rect.centery,
            boss_rect.centerx - turret_rect.centerx,
        )

    current_angle = turret_state.get("display_angle", target_angle)
    delta_angle = ((target_angle - current_angle + math.pi) % (2 * math.pi)) - math.pi
    current_angle += delta_angle * BLACKSMITH_TURRET_AIM_LERP
    turret_state["display_angle"] = current_angle
    turret_state["aim_angle"] = target_angle

    recoil_timer = turret_state.get("recoil_timer", 0)
    if recoil_timer > 0:
        recoil_timer -= 1
    turret_state["recoil_timer"] = recoil_timer
    recoil_base = turret_state.get("recoil_base_distance", BLACKSMITH_TURRET_RECOIL_DISTANCE)
    if BLACKSMITH_TURRET_RECOIL_FRAMES > 0:
        turret_state["recoil_offset"] = (
            recoil_timer / max(1, BLACKSMITH_TURRET_RECOIL_FRAMES)
        ) * recoil_base * scale_factor
    else:
        turret_state["recoil_offset"] = 0.0

    time_frozen = stopwatch_active and stopwatch_timer > 0

    # 포탑 충돌 판정: 머리/포신까지 포함되도록 상단 여유를 둔 히트박스를 사용한다.
    turret_hit_rect = turret_rect
    if BLACKSMITH_TURRET_DESIGN_HEIGHT:
        scale_y = turret_rect.height / BLACKSMITH_TURRET_DESIGN_HEIGHT
    else:
        scale_y = 1.0
    extra_top = int(BLACKSMITH_TURRET_COLLISION_EXTRA_TOP * scale_y)
    if extra_top > 0:
        turret_hit_rect = turret_rect.copy()
        turret_hit_rect.height += extra_top
        turret_hit_rect.top -= extra_top

    # 포탑 앞에 벽돌(발토르 방어벽 포함)이 있을 경우, 우선 벽돌이 공을 막도록 하고
    # 이 프레임에서는 포탑 충돌 처리를 건너뛴다.
    wall_blocked = False

    # 관통 검사를 위한 헬퍼 함수
    def _line_intersects_rect_turret(x1, y1, x2, y2, rect):
        """선분이 사각형과 교차하는지 확인 (관통 검사용)"""
        r = BALL.width // 2
        left = rect.left - r
        right = rect.right + r
        top = rect.top - r
        bottom = rect.bottom + r
        dx = x2 - x1
        dy = y2 - y1
        t_min, t_max = 0.0, 1.0
        if dx != 0:
            t1 = (left - x1) / dx
            t2 = (right - x1) / dx
            if dx < 0:
                t1, t2 = t2, t1
            t_min = max(t_min, t1)
            t_max = min(t_max, t2)
        elif x1 < left or x1 > right:
            return False
        if dy != 0:
            t1 = (top - y1) / dy
            t2 = (bottom - y1) / dy
            if dy < 0:
                t1, t2 = t2, t1
            t_min = max(t_min, t1)
            t_max = min(t_max, t2)
        elif y1 < top or y1 > bottom:
            return False
        return t_min <= t_max

    try:
        try:
            ball_owner = getattr(game_vars.ball, "last_hit_by", None)
        except Exception:
            ball_owner = last_hit_by
        # 이전 공 위치 가져오기
        prev_x = ball_prev_x
        prev_y = ball_prev_y
        for wall in walls:
            # 플레이어가 친 공(서브 포함)에 대해서는 건물 보호용(group_id) 벽돌은 포탑을 막지 않는다.
            if ball_owner == "player" and wall.get("group_id") is not None:
                continue
            wall_rect = wall["rect"]
            # 현재 충돌 또는 관통 체크
            if BALL.colliderect(wall_rect):
                wall_blocked = True
                break
            # 관통 체크: 이전 위치에서 현재 위치로 이동하며 벽돌을 지나쳤는지
            if _line_intersects_rect_turret(prev_x + BALL.width//2, prev_y + BALL.height//2,
                                            BALL.centerx, BALL.centery, wall_rect):
                wall_blocked = True
                # print(f"[DEBUG] 벽돌 관통 감지 (포탑 보호)!")  # 디버그 비활성화
                break
    except Exception:
        wall_blocked = False

    # 포탑 충돌 체크: 현재 충돌 또는 관통
    prev_x = ball_prev_x
    prev_y = ball_prev_y
    turret_collision = turret_hit_rect.colliderect(BALL) or _line_intersects_rect_turret(
        prev_x + BALL.width//2, prev_y + BALL.height//2,
        BALL.centerx, BALL.centery, turret_hit_rect
    )

    if not time_frozen and not wall_blocked and turret_collision:
        ball_owner = getattr(game_vars.ball, "last_hit_by", "player")
        if ball_owner != "player" and turret_state.get("hp", 0) > 0:
            smoke_protected = is_rect_in_smoke(turret_hit_rect)
            # 디바인쉴드 활성 중에는 포탑 체력이 감소하지 않는다.
            shield_active = False
            try:
                divine_state = blacksmith_divine_stone_state
                shield_active = bool(divine_state and divine_state.get("shield_active", False))
            except Exception:
                shield_active = False
            if not smoke_protected and not shield_active:
                turret_state["hp"] -= 1  # 연막 밖에서만 체력 감소
                _cancel_repair_job("turret", state=turret_state)
                # 손상 효과 업데이트
                damage_manager.update_building_hp("turret", turret_state["hp"])
            BALL.bottom = min(BALL.bottom, turret_hit_rect.top - 4)
            speed_mag = max(7.0, math.hypot(ball_vel[0], ball_vel[1]))
            ball_vel[1] = -abs(speed_mag)
            ball_vel[0] *= 0.6
            last_hit_by = "player"
            game_vars.ball.last_hit_by = "player"
            player_collision_handled = True
            effects_manager.spawn_star_particles(turret_rect.centerx, turret_rect.top, count=6)
            try:
                play_paddle_sound()
            except Exception:
                pass

    overdrive_active = turret_state.get("overdrive_active", False)
    skip_regular_fire = False
    if overdrive_active:
        if not time_frozen:
            remaining = max(0, turret_state.get("overdrive_timer", 0) - 1)
            turret_state["overdrive_timer"] = remaining
            turret_state["overdrive_glow_phase"] = turret_state.get("overdrive_glow_phase", 0.0) + 0.12

            fire_window = max(0, turret_state.get("overdrive_fire_window", 0) - 1)
            turret_state["overdrive_fire_window"] = fire_window
            if fire_window > 0 and turret_state.get("overdrive_shots_remaining", 0) > 0:
                frames_left = fire_window
                shots_left = max(1, turret_state["overdrive_shots_remaining"])
                base_interval_frames = BLACKSMITH_TURRET_OVERDRIVE_BASE_INTERVAL
                min_interval_frames = BLACKSMITH_TURRET_OVERDRIVE_MIN_INTERVAL
                if turret_state.get("overdrive_divine_active"):
                    base_interval_frames = BLACKSMITH_TURRET_OVERDRIVE_BASE_INTERVAL_DIVINE
                    min_interval_frames = BLACKSMITH_TURRET_OVERDRIVE_MIN_INTERVAL_DIVINE

                interval = base_interval_frames
                dynamic_cap = frames_left // shots_left
                if dynamic_cap > 0:
                    interval = min(interval, max(min_interval_frames, dynamic_cap))
                else:
                    interval = min_interval_frames

                cooldown = max(0, turret_state.get("overdrive_shot_cooldown", 0) - 1)
                turret_state["overdrive_shot_cooldown"] = cooldown
                if cooldown <= 0 and turret_state["overdrive_shots_remaining"] > 0:
                    _blacksmith_fire_turret_projectile(turret_runtime, turret_state, overdrive=True)
                    turret_state["overdrive_shots_remaining"] -= 1
                    turret_state["overdrive_shot_cooldown"] = max(
                        min_interval_frames,
                        interval,
                    )
            elif fire_window <= 0:
                turret_state["overdrive_shots_remaining"] = 0
                turret_state["overdrive_shot_cooldown"] = 0

        if turret_state.get("overdrive_fire_window", 0) > 0 and turret_state.get("overdrive_shots_remaining", 0) > 0:
            skip_regular_fire = True

        if not time_frozen and turret_state.get("overdrive_timer", 0) <= 0:
            _end_blacksmith_turret_overdrive(turret_state)
            overdrive_active = False
        elif time_frozen and turret_state.get("overdrive_timer", 0) <= 0:
            _end_blacksmith_turret_overdrive(turret_state)
            overdrive_active = False

    overheat_timer_value = int(turret_state.get("overheat_timer", 0))
    if overheat_timer_value > 0:
        new_overheat_timer = max(0, overheat_timer_value - 1)
        turret_state["overheat_timer"] = new_overheat_timer
        turret_runtime.overheat_timer = new_overheat_timer
        smoke_timer = int(turret_state.get("overheat_smoke_timer", 0)) + 1
        turret_state["overheat_smoke_timer"] = smoke_timer
        turret_runtime.overheat_smoke_timer = smoke_timer
        globals()["blacksmith_turret_overheat_timer"] = new_overheat_timer
        globals()["blacksmith_turret_overheat_smoke_timer"] = smoke_timer
        if smoke_timer >= BLACKSMITH_TURRET_OVERHEAT_SMOKE_INTERVAL:
            if not time_frozen:
                _emit_blacksmith_turret_overheat_smoke(turret_state)
            turret_state["overheat_smoke_timer"] = 0
            turret_runtime.overheat_smoke_timer = 0
            globals()["blacksmith_turret_overheat_smoke_timer"] = 0
        skip_regular_fire = True
        if turret_state.get("fire_interval"):
            turret_state["fire_timer"] = max(
                turret_state.get("fire_interval", BLACKSMITH_TURRET_FIRE_INTERVAL),
                turret_state.get("fire_timer", 0),
            )
    else:
        turret_state["overheat_smoke_timer"] = 0
        turret_runtime.overheat_smoke_timer = 0
        turret_runtime.overheat_timer = 0
        globals()["blacksmith_turret_overheat_smoke_timer"] = 0
        globals()["blacksmith_turret_overheat_timer"] = 0

    # 강화 포탑 전용 유도 미사일 버스트 (레벨 2 이상에서만, 과부하 아닐 때)
    if (
        not time_frozen
        and turret_state.get("hp", 0) > 0
        and overheat_timer_value <= 0
        and int(turret_state.get("level", BLACKSMITH_TURRET_BASE_LEVEL)) >= BLACKSMITH_TURRET_MAX_LEVEL
    ):
        homing_cd = int(turret_state.get("homing_cooldown", 0))
        homing_timer = int(turret_state.get("homing_burst_timer", 0))
        homing_shots = int(turret_state.get("homing_burst_shots", 0))

        if homing_cd > 0:
            homing_cd -= 1
        else:
            if homing_shots <= 0:
                boss_rect_local = BOSS if "BOSS" in globals() else None
                if boss_rect_local:
                    homing_shots = BLACKSMITH_TURRET_HOMING_BURST_COUNT
                    homing_timer = 0

            if homing_shots > 0:
                if homing_timer <= 0:
                    _blacksmith_spawn_homing_missile(turret_runtime, turret_state)
                    homing_shots -= 1
                    if homing_shots > 0:
                        homing_timer = BLACKSMITH_TURRET_HOMING_INTERVAL
                    else:
                        homing_cd = random.randint(
                            BLACKSMITH_TURRET_HOMING_COOLDOWN_MIN,
                            BLACKSMITH_TURRET_HOMING_COOLDOWN_MAX,
                        )
                else:
                    homing_timer -= 1

        turret_state["homing_cooldown"] = homing_cd
        turret_state["homing_burst_timer"] = homing_timer
        turret_state["homing_burst_shots"] = homing_shots

    if turret_state.get("overdrive_flash_timer", 0) > 0 and not time_frozen:
        turret_state["overdrive_flash_timer"] = max(0, turret_state["overdrive_flash_timer"] - 1)

    if turret_runtime.overdrive_ui_timer > 0:
        turret_runtime.overdrive_ui_timer = max(0, turret_runtime.overdrive_ui_timer - 1)
        if turret_runtime.overdrive_ui_timer == 0 and not turret_state.get("overdrive_active", False):
            turret_runtime.overdrive_ui_divine = False

    if not time_frozen and not skip_regular_fire:
        turret_state["fire_timer"] -= 1
        if turret_state["fire_timer"] <= 0:
            _blacksmith_fire_turret_projectile(turret_runtime, turret_state, overdrive=False)

    boss_rect = BOSS if 'BOSS' in globals() else None
    boss_target_x = boss_rect.centerx if boss_rect else WIDTH // 2
    boss_target_y = boss_rect.centery if boss_rect else HEIGHT // 3

    projectiles = turret_runtime.projectiles
    if blacksmith_turret_state and blacksmith_turret_state.get("overheat_timer", 0) > 0 and turret_rect:
        frame_value = float(frame_counter)
        pulse = 0.5 + 0.5 * math.sin(frame_value * 0.32)
        aura_surface = pygame.Surface((turret_rect.width + 22, turret_rect.height + 24), pygame.SRCALPHA)
        aura_surface.fill((255, 70, 40, int(80 + 120 * pulse)))
        SCREEN.blit(
            aura_surface,
            (turret_rect.left - 11, turret_rect.top - 14),
            special_flags=pygame.BLEND_RGBA_ADD,
        )

    if projectiles and not (stopwatch_active and stopwatch_timer > 0):
        new_projectiles = []
        for proj in projectiles:
            speed = proj.get("speed", BLACKSMITH_TURRET_MISSILE_SPEED)
            turn_rate = BLACKSMITH_TURRET_MISSILE_TURN_RATE

            if boss_rect:
                to_target = pygame.math.Vector2(boss_target_x - proj["x"], boss_target_y - proj["y"])
                if to_target.length() > 0:
                    desired_dir = to_target.normalize()
                    desired_vx = desired_dir.x * speed
                    desired_vy = desired_dir.y * speed
                    proj["vx"] = (1 - turn_rate) * proj["vx"] + turn_rate * desired_vx
                    proj["vy"] = (1 - turn_rate) * proj["vy"] + turn_rate * desired_vy

            if proj.get("homing"):
                # 등가속도: 1초당 기본 속도의 60%씩 속도 증가 (선형)
                age = int(proj.get("homing_age", 0)) + 1
                proj["homing_age"] = age
                base_speed_val = proj.get("homing_base_speed", BLACKSMITH_TURRET_MISSILE_SPEED)
                initial_speed = proj.get("homing_initial_speed", base_speed_val * BLACKSMITH_TURRET_HOMING_SPEED_MULT)
                delta_per_sec = base_speed_val * 0.6
                speed = initial_speed + delta_per_sec * (age / FPS)
                # 상한은 일반 미사일 최대 속도와 동일하게 제한
                speed = min(BLACKSMITH_TURRET_MISSILE_MAX_SPEED, speed)
                proj["speed"] = speed
                current_speed = math.hypot(proj["vx"], proj["vy"])
                if current_speed > 0:
                    scale = speed / current_speed
                    proj["vx"] *= scale
                    proj["vy"] *= scale

                # 유도 미사일은 이동 경로에 약한 물결을 추가
                wobble_phase = float(proj.get("wobble_phase", 0.0)) + 0.18
                proj["wobble_phase"] = wobble_phase
                wobble_amp = max(2.0, proj.get("radius", BLACKSMITH_TURRET_PROJECTILE_RADIUS) * 0.6)
                base_vec = pygame.math.Vector2(proj["vx"], proj["vy"])
                if base_vec.length() > 0:
                    perp = pygame.math.Vector2(-base_vec.y, base_vec.x).normalize()
                    offset = math.sin(wobble_phase) * wobble_amp
                    proj["x"] += perp.x * offset
                    proj["y"] += perp.y * offset
            else:
                speed = min(BLACKSMITH_TURRET_MISSILE_MAX_SPEED, speed * (1 + BLACKSMITH_TURRET_MISSILE_ACCEL))
                proj["speed"] = speed
                current_speed = math.hypot(proj["vx"], proj["vy"])
                if current_speed > 0:
                    scale = speed / current_speed
                    proj["vx"] *= scale
                    proj["vy"] *= scale

            proj["x"] += proj["vx"]
            proj["y"] += proj["vy"]
            proj["life"] -= 1

            if proj.get("overdrive") or proj.get("homing"):
                trail_timer = proj.get("trail_timer", 0) + 1
                proj["trail_timer"] = trail_timer
                if proj.get("overdrive") and trail_timer % 2 == 0:
                    try:
                        effects_manager.spawn_flame_particles(proj["x"], proj["y"], count=2)
                    except Exception:
                        pass
                if proj.get("homing") and trail_timer % 2 == 0:
                    try:
                        effects_manager.spawn_construction_smoke(
                            proj["x"],
                            proj["y"],
                            count=1,
                            spread=14,
                        )
                    except Exception:
                        pass

            radius = int(proj.get("radius", BLACKSMITH_TURRET_PROJECTILE_RADIUS))
            grace_frames = proj.get("grace_frames", 0)
            if grace_frames > 0:
                proj["grace_frames"] = grace_frames - 1
                grace_frames = proj["grace_frames"]

            if proj["life"] <= 0:
                continue

            if (
                proj["x"] < -radius * 2
                or proj["x"] > WIDTH + radius * 2
                or proj["y"] < -radius * 2
                or proj["y"] > HEIGHT + radius * 2
            ):
                continue

            projectile_rect = pygame.Rect(0, 0, radius * 2, radius * 2)
            projectile_rect.center = (proj["x"], proj["y"])

            if 'PLAYER' in globals() and PLAYER is not None:
                try:
                    if projectile_rect.colliderect(PLAYER):
                        new_projectiles.append(proj)
                        continue
                except Exception:
                    pass

            if boss_rect and projectile_rect.colliderect(boss_rect):
                if proj.get("homing"):
                    stun_frames = max(1, BLACKSMITH_TURRET_HOMING_STUN_DURATION)
                    # 기존(0.5배) 대비 넉백 속도를 40%로 줄여 총 거리 약 60% 감소
                    knockback_speed = BLACKSMITH_TURRET_KNOCKBACK_SPEED * 0.2
                else:
                    stun_multiplier = 1.0
                    knockback_multiplier = 1.0
                    if proj.get("overdrive"):
                        stun_multiplier = max(1.0, float(turret_state.get("overdrive_stun_multiplier", 1.0)))
                        knockback_multiplier = max(1.0, float(turret_state.get("overdrive_knockback_multiplier", 1.0)))
                    stun_frames = max(1, int(round(BLACKSMITH_TURRET_STUN_DURATION * stun_multiplier)))
                    knockback_speed = BLACKSMITH_TURRET_KNOCKBACK_SPEED * knockback_multiplier
                    if proj.get("overdrive"):
                        intensity = 4 if not proj.get("divine_overdrive") else 7
                        global screen_shake_timer, screen_shake_intensity
                        screen_shake_timer = max(screen_shake_timer, 8)
                        screen_shake_intensity = max(screen_shake_intensity, intensity)
                try:
                    current_star_timer = boss_stunned_timer
                    current_star_timer = max(current_star_timer, stun_frames)
                    globals()["boss_stunned_timer"] = current_star_timer
                    globals()["boss_stun_timer"] = 0
                except Exception:
                    pass
                try:
                    edge_margin = max(10, boss_rect.width // 2)
                    if boss_rect.left <= edge_margin:
                        knockback_direction = 1
                    elif boss_rect.right >= WIDTH - edge_margin:
                        knockback_direction = -1
                    else:
                        knockback_direction = 1 if proj["x"] < boss_rect.centerx else -1
                    globals()["boss_knockback_timer"] = stun_frames
                    _apply_boss_knockback_velocity(knockback_direction * knockback_speed)
                    globals()["boss_knockback_active"] = False
                    globals()["boss_knockback_offset_x"] = 0
                    globals()["boss_knockback_offset_y"] = 0
                except Exception:
                    pass
                cx, cy = int(proj["x"]), int(proj["y"])
                try:
                    effects_manager.create_impact_effect(cx, cy, radius * 2.0, is_player=False)
                except Exception:
                    pass
                try:
                    effects_manager.spawn_star_particles(cx, cy, count=8)
                    effects_manager.spawn_flame_particles(cx, cy, count=7)
                    effects_manager.spawn_construction_smoke(cx, cy, count=5, spread=20)
                    if proj.get("divine_overdrive"):
                        _spawn_blacksmith_megadrive_shards(cx, cy, radius * 2.2)
                except Exception:
                    pass
                if current_stage in boss_health_stages:
                    blacksmith_turret_boss_hit_count += 1
                    if blacksmith_turret_boss_hit_count >= 4:
                        apply_health_boss_damage(1, source="blacksmith_turret")
                        blacksmith_turret_boss_hit_count = 0
                continue

            # Stage 7: 포탑 미사일 ↔ 테트로/가드 충돌 → 미사일 폭발 + 대상 파괴
            if (
                current_stage == 7
                and 'stage7_tetrominoes' in globals()
            ):
                tetro_hit = None
                # 원(미사일 반경) - 사각형(셀) 근접 판정
                if 'stage7_tetrominoes' in globals() and stage7_tetrominoes:
                    for mino in list(stage7_tetrominoes):
                        if mino.get('state') in ('destroying', 'evaporating'):
                            continue
                        hit = False
                        for c in mino.get('cells', []) or []:
                            rect = c.get('rect')
                            if not rect:
                                continue
                            closest_x = max(rect.left, min(projectile_rect.centerx, rect.right))
                            closest_y = max(rect.top, min(projectile_rect.centery, rect.bottom))
                            dx = projectile_rect.centerx - closest_x
                            dy = projectile_rect.centery - closest_y
                            if dx * dx + dy * dy <= (radius * radius):
                                hit = True
                                break
                        if hit:
                            tetro_hit = mino
                            break
                if tetro_hit is None and 'stage7_guard_blocks' in globals() and stage7_guard_blocks:
                    for block in list(stage7_guard_blocks):
                        if block.get('state') not in ('assembling', 'hologram', 'deploy', 'active'):
                            continue
                        hit = False
                        for c in (block.get('cells', []) or []):
                            rect = c.get('rect')
                            if not rect:
                                continue
                            closest_x = max(rect.left, min(projectile_rect.centerx, rect.right))
                            closest_y = max(rect.top, min(projectile_rect.centery, rect.bottom))
                            dx = projectile_rect.centerx - closest_x
                            dy = projectile_rect.centery - closest_y
                            if dx * dx + dy * dy <= (radius * radius):
                                hit = True
                                break
                        if hit:
                            # 폭발 이펙트
                            cx, cy = int(projectile_rect.centerx), int(projectile_rect.centery)
                            try:
                                effects_manager.create_impact_effect(cx, cy, radius * 2.0, is_player=False)
                                effects_manager.spawn_star_particles(cx, cy, count=8)
                                effects_manager.spawn_flame_particles(cx, cy, count=7)
                                effects_manager.spawn_construction_smoke(cx, cy, count=5, spread=20)
                            except Exception:
                                pass
                            destroy_stage7_guard_block(block, by_player=True)
                            continue
                if tetro_hit is not None:
                    # 영향 이펙트 + 파티클(보스 히트와 동일 스타일)
                    cx, cy = int(projectile_rect.centerx), int(projectile_rect.centery)
                    try:
                        effects_manager.create_impact_effect(cx, cy, radius * 2.0, is_player=False)
                        effects_manager.spawn_star_particles(cx, cy, count=8)
                        effects_manager.spawn_flame_particles(cx, cy, count=7)
                        effects_manager.spawn_construction_smoke(cx, cy, count=5, spread=20)
                    except Exception:
                        pass
                    # 히트 플래시
                    try:
                        tetro_hit["hit_flash_duration"] = 130
                        tetro_hit["hit_flash_until"] = pygame.time.get_ticks() + 130
                    except Exception:
                        pass
                    # 벽 생성물인 경우 충돌 리스트 즉시 제거
                    if tetro_hit.get('wall_generated'):
                        try:
                            for c in tetro_hit.get('cells', []) or []:
                                _remove_wall_cell_rect(c.get('rect'))
                        except Exception:
                            pass
                    # 빠른 증발로 전환
                    destroy_stage7_tetromino(tetro_hit, by_player=True, by_dash=True)
                    # 미사일은 여기서 소멸 (폭발 처리 완료)
                    continue

            current_turret_rect = turret_state.get("rect") if turret_state else None
            if grace_frames <= 0 and current_turret_rect and current_turret_rect.colliderect(projectile_rect):
                if turret_state.get("hp", 0) > 0:
                    turret_state["hp"] -= 1
                    _cancel_repair_job("turret", state=turret_state)
                    # 손상 효과 업데이트
                    damage_manager.update_building_hp("turret", turret_state["hp"])
                    spark_surface = pygame.Surface((14, 14), pygame.SRCALPHA)
                    pygame.draw.circle(spark_surface, (255, 200, 100, 200), (7, 7), 6)
                    surface_target = pygame.Surface((14, 14), pygame.SRCALPHA)
                    pygame.draw.circle(surface_target, (255, 255, 255, 240), (7, 7), 3)
                    spark_surface.blit(surface_target, (0, 0))
                    SCREEN.blit(spark_surface, (projectile_rect.centerx - 7, projectile_rect.centery - 7))
                    try:
                        play_sound_with_volume(SOUND_DEFENSE_BLOCK)
                    except Exception:
                        pass
                continue

            new_projectiles.append(proj)

        turret_runtime.projectiles = new_projectiles

    missile_img = globals().get("BLACKSMITH_TURRET_MISSILE_IMG")
    if missile_img is not None:
        try:
            missile_img.set_alpha(255 if turret_runtime.projectiles else 0)
        except Exception:
            pass

    if turret_runtime.active and turret_state:
        if turret_state.get("hp", 0) <= 0:
            turret_state["hp"] = 0
            turret_runtime.projectiles.clear()
            try:
                effects_manager.spawn_star_particles(turret_rect.centerx, turret_rect.top, count=8)
                effects_manager.spawn_construction_smoke(
                    turret_rect.centerx,
                    turret_rect.top + int(turret_rect.height * 0.3),
                    count=4,
                    spread=18,
                )
                effects_manager.create_impact_effect(
                    turret_rect.centerx,
                    turret_rect.centery,
                    max(turret_rect.width, turret_rect.height) * 1.6,
                    is_player=False,
                )
                effects_manager.spawn_star_particles(turret_rect.centerx, turret_rect.centery, count=14)
                effects_manager.spawn_flame_particles(turret_rect.centerx, turret_rect.centery, count=10)
                effects_manager.spawn_construction_smoke(
                    turret_rect.centerx,
                    turret_rect.top + int(turret_rect.height * 0.35),
                    count=3,
                    spread=20,
                )
            except Exception:
                pass
            try:
                play_sound_with_volume(SOUND_STAGE6_BOSS_HIT)
            except Exception:
                pass

            blacksmith_turret_destroy_timer = 0
            _finalize_blacksmith_turret_removal(turret_runtime)
            BLACKSMITH_CONTROLLER.state.turret = BlacksmithTurretRuntime()
            push_blacksmith_state()
            valthor_perf_end("update_turret")
            return

    push_blacksmith_state()
    valthor_perf_end("update_turret")


def trigger_blacksmith_turret_overdrive() -> bool:
    """포탑 오버드라이브(게이지 해방) 발동."""

    global blacksmith_turret_state, blacksmith_turret_overdrive_ui_timer, blacksmith_turret_overdrive_ui_divine

    sync_blacksmith_state()
    if not blacksmith_turret_active or not blacksmith_turret_state:
        return False

    # 강화되지 않은 포탑(레벨 1)에서는 오버드라이브를 사용할 수 없다.
    if int(blacksmith_turret_state.get("level", BLACKSMITH_TURRET_BASE_LEVEL)) < BLACKSMITH_TURRET_MAX_LEVEL:
        return False

    if blacksmith_turret_state.get("overdrive_active"):
        return False

    turret_runtime = BLACKSMITH_CONTROLLER.state.turret
    rect = blacksmith_turret_state.get("rect")

    base_interval = blacksmith_turret_state.get("base_fire_interval", BLACKSMITH_TURRET_FIRE_INTERVAL)
    blacksmith_turret_state.setdefault("base_fire_interval", base_interval)

    divine_active = is_blacksmith_divine_stone_active()
    fire_window = BLACKSMITH_TURRET_OVERDRIVE_FIRE_WINDOW
    stun_multiplier = 1.0
    knockback_multiplier = 1.0
    shots_remaining = BLACKSMITH_TURRET_OVERDRIVE_SHOTS
    if divine_active:
        fire_window = BLACKSMITH_TURRET_OVERDRIVE_FIRE_WINDOW_DIVINE
        stun_multiplier = 2.0  # +100%
        knockback_multiplier = 1.5  # +50%
        shots_remaining = 12

    blacksmith_turret_state["overdrive_active"] = True
    blacksmith_turret_state["overdrive_timer"] = BLACKSMITH_TURRET_OVERDRIVE_DURATION
    blacksmith_turret_state["overdrive_fire_window"] = fire_window
    blacksmith_turret_state["overdrive_shots_remaining"] = shots_remaining
    blacksmith_turret_state["overdrive_shot_cooldown"] = 0
    blacksmith_turret_state["overdrive_glow_phase"] = 0.0
    blacksmith_turret_state["overdrive_recoil_boost"] = BLACKSMITH_TURRET_OVERDRIVE_RECOIL_SCL
    blacksmith_turret_state["overdrive_speed_boost"] = BLACKSMITH_TURRET_OVERDRIVE_SPEED_BOOST
    blacksmith_turret_state["overdrive_stun_multiplier"] = stun_multiplier
    blacksmith_turret_state["overdrive_knockback_multiplier"] = knockback_multiplier
    blacksmith_turret_state["overdrive_divine_active"] = divine_active
    blacksmith_turret_state["overheat_timer"] = 0
    blacksmith_turret_state["overheat_smoke_timer"] = 0
    blacksmith_turret_state["fire_timer"] = 0
    blacksmith_turret_state["fire_interval"] = base_interval
    blacksmith_turret_state["xp_max"] = float(BLACKSMITH_TURRET_XP_REQUIRED)
    blacksmith_turret_state["xp"] = 0.0

    turret_runtime.overdrive_ui_timer = BLACKSMITH_TURRET_OVERDRIVE_UI_DURATION
    blacksmith_turret_overdrive_ui_timer = BLACKSMITH_TURRET_OVERDRIVE_UI_DURATION
    turret_runtime.overdrive_ui_divine = divine_active
    blacksmith_turret_overdrive_ui_divine = divine_active
    turret_runtime.overheat_timer = 0
    turret_runtime.overheat_smoke_timer = 0
    globals()["blacksmith_turret_overheat_timer"] = 0
    globals()["blacksmith_turret_overheat_smoke_timer"] = 0

    try:
        if rect:
            effects_manager.spawn_flame_particles(rect.centerx, rect.top - 12, count=18)
            effects_manager.spawn_star_particles(rect.centerx, rect.centery, count=10)
    except Exception:
        pass
    try:
        play_sound_with_volume(SOUND_STAGE6_BEAM_CHARGE)
    except Exception:
        pass

    push_blacksmith_state()
    return True


def draw_blacksmith_turret_elements(surface):
    """발토르 포탑과 청사진, 투사체를 그린다."""
    valthor_perf_start("draw_turret_elements")
    sync_blacksmith_state()
    state = BLACKSMITH_CONTROLLER.state
    turret = state.turret
    divine = state.divine
    turret_state = turret.state
    projectiles = turret.projectiles

    # 혹시 업데이트 루프가 중단되어 포탑 상태만 남은 경우를 대비한 안전망.
    if turret_state and turret_state.get("hp", 0) <= 0 and not turret.active:
        _finalize_blacksmith_turret_removal(turret)
        push_blacksmith_state()
        turret_state = None

    # turret_rect 초기화
    turret_rect = None
    if turret_state:
        turret_rect = turret_state.get("rect")

    draw_blacksmith_divine_stone(surface, divine.state)
    # 디바인스톤이 완성된 경우 청사진/게이지바를 그리지 않음
    if divine.blueprint_active and divine.blueprint_rect and divine.state is None:
        blueprint_rect = divine.blueprint_rect
        progress_ratio = 0.0
        if BLACKSMITH_DIVINE_BUILD_TIME > 0:
            progress_ratio = divine.build_progress / BLACKSMITH_DIVINE_BUILD_TIME
        progress_ratio = max(0.0, min(1.0, progress_ratio))

        width = blueprint_rect.width
        height = blueprint_rect.height

        # 캐시 키 생성 (크기 + 진행도 10% 단위)
        progress_stage = int(progress_ratio * 10)
        cache_key = ("divine_bp", width, height, progress_stage)

        # 캐시 히트 체크 - 캐시된 완성된 surface 재사용
        if cache_key in _blacksmith_blueprint_cache:
            cached_surface = _blacksmith_blueprint_cache[cache_key]
            # 리빌 클립 적용하여 blit
            p = progress_ratio
            reveal_h = int(height * p)
            if reveal_h > 0:
                clip = cached_surface.subsurface(pygame.Rect(0, height - reveal_h, width, reveal_h))
                surface.blit(clip, (blueprint_rect.left, blueprint_rect.top + height - reveal_h))
            else:
                surface.blit(cached_surface, blueprint_rect.topleft)
            # 게이지바 그리기
            gauge_width = blueprint_rect.width
            gauge_height = 6
            gauge_rect = pygame.Rect(blueprint_rect.left, blueprint_rect.top - gauge_height - 6, gauge_width, gauge_height)
            pygame.draw.rect(surface, (40, 50, 70), gauge_rect.inflate(4, 4), border_radius=3)
            if progress_ratio > 0:
                filled_rect = pygame.Rect(gauge_rect.left, gauge_rect.top, int(gauge_width * progress_ratio), gauge_height)
                pygame.draw.rect(surface, (110, 200, 255), filled_rect, border_radius=3)
            pygame.draw.rect(surface, (150, 200, 255), gauge_rect, 1, border_radius=3)
        else:
            # 캐시 미스 - 새로 생성 후 캐시에 저장
            if len(_blacksmith_blueprint_cache) > 30:
                _blacksmith_blueprint_cache.clear()
            base_surface = pygame.Surface((width, height), pygame.SRCALPHA)

            base_center = pygame.math.Vector2(width / 2, height - BLACKSMITH_DIVINE_BLUEPRINT_EXTRA_HEIGHT / 2)
            base_radius_x = max(18, width // 3)
            base_radius_y = max(12, BLACKSMITH_DIVINE_BLUEPRINT_EXTRA_HEIGHT // 2)
            pygame.draw.ellipse(
                base_surface,
                (90, 70, 55, 220),
                pygame.Rect(
                    int(base_center.x - base_radius_x),
                    int(base_center.y - base_radius_y),
                    int(base_radius_x * 2),
                    int(base_radius_y * 2),
                ),
            )
            pygame.draw.ellipse(
                base_surface,
                (160, 130, 95, 160),
                pygame.Rect(
                    int(base_center.x - base_radius_x + 6),
                    int(base_center.y - base_radius_y + 6),
                    int((base_radius_x - 6) * 2),
                    int((base_radius_y - 6) * 2),
                ),
                2,
            )

            stage_float = progress_ratio * 3.0
            stage_index = min(2, int(stage_float))
            stage_alpha = stage_float - stage_index

            stone_width, stone_height = BLACKSMITH_DIVINE_STONE_SIZE
            stone_surface = pygame.Surface((stone_width, stone_height), pygame.SRCALPHA)
            stone_color = (200, 210, 220)
            if stage_index >= 0:
                outline_alpha = int(110 + 100 * progress_ratio)
                pygame.draw.rect(
                    stone_surface,
                    (*stone_color, outline_alpha),
                    pygame.Rect(8, 6, stone_width - 16, stone_height - 12),
                    2,
                    border_radius=10,
                )
                glyph_alpha = int(80 + 120 * stage_alpha) if stage_index >= 1 else int(70 * progress_ratio)
                for offset, radius in ((0, 10), (12, 6), (-12, 6)):
                    pygame.draw.circle(
                        stone_surface,
                        (120, 160, 255, glyph_alpha),
                        (stone_width // 2 + offset, stone_height // 2),
                        radius,
                        1,
                    )
            if stage_index >= 2:
                fill_alpha = int(190 * progress_ratio)
                pygame.draw.rect(
                    stone_surface,
                    (220, 230, 240, fill_alpha),
                    pygame.Rect(10, 8, stone_width - 20, stone_height - 16),
                    border_radius=8,
                )
                glow_surface = pygame.Surface((stone_width, stone_height), pygame.SRCALPHA)
                pygame.draw.ellipse(
                    glow_surface,
                    (120, 200, 255, int(130 * stage_alpha)),
                    pygame.Rect(14, stone_height - 26, stone_width - 28, 18),
                )
                stone_surface.blit(glow_surface, (0, 0))

            placement_y = height - (BLACKSMITH_DIVINE_BLUEPRINT_EXTRA_HEIGHT + stone_height)

            # ▶ 고급 조립 애니메이션(디바인 스톤 전용) — 기존보다 발전된 단계 구성
            #  - 0.20~0.40: 받침대/바닥원 등장
            #  - 0.35~0.70: 좌/우/중앙 수정(크리스탈) 기둥 상승
            #  - 0.60~0.85: 외곽 링 조립 + 천천히 회전
            #  - 0.80~1.00: 중앙 코어 점화 + 수직 라이트샤프트
            assembly_surface = pygame.Surface((stone_width, stone_height), pygame.SRCALPHA)
            p = progress_ratio
            # 받침대(바닥 타원) — 하단에서 위로 점진적 등장
            if p > 0.2:
                base_h = int(6 + 10 * min(1.0, (p - 0.2) / 0.2))
                base_rect = pygame.Rect(8, stone_height - base_h - 4, stone_width - 16, base_h)
                pygame.draw.ellipse(assembly_surface, (120, 100, 85, int(140 + 80 * p)), base_rect)
                pygame.draw.ellipse(assembly_surface, (200, 180, 150, int(120 + 80 * p)), base_rect, 2)

            # 수정 기둥(좌/중앙/우) — 높이 증가
            if p > 0.35:
                shard_progress = min(1.0, (p - 0.35) / 0.35)
                max_h = int(stone_height * 0.55)
                h = int(max_h * shard_progress)
                mid_x = stone_width // 2
                def shard(x0, w, height, tilt=0):
                    poly = [
                        (x0 - w // 2 + tilt, stone_height - 8),
                        (x0 + w // 2 + tilt, stone_height - 8),
                        (x0 + w // 4, stone_height - 8 - height // 3),
                        (x0, stone_height - 8 - height),
                        (x0 - w // 4, stone_height - 8 - height // 3),
                    ]
                    pygame.draw.polygon(assembly_surface, (200, 210, 230, int(110 + 110 * shard_progress)), poly)
                    pygame.draw.lines(assembly_surface, (140, 170, 210, int(120 + 80 * shard_progress)), True, poly, 1)
                shard(mid_x - stone_width // 4, 14, h, tilt=-2)
                shard(mid_x, 18, min(stone_height - 16, int(h * 1.15)))
                shard(mid_x + stone_width // 4, 14, h, tilt=2)

            # 외곽 회전 링 — 진행도에 따라 반경/밝기 증가, 부드러운 회전
            if p > 0.6:
                ring_phase = (pygame.time.get_ticks() * 0.002) % (2 * math.pi)
                ring_alpha = int(60 + 120 * min(1.0, (p - 0.6) / 0.25))
                cx = stone_width // 2
                cy = int(stone_height * 0.42)
                for i, r in enumerate((16, 22, 28)):
                    a0 = ring_phase + i * 0.6
                    a1 = a0 + (0.8 + 0.2 * i)
                    rect = pygame.Rect(cx - r, cy - r, 2 * r, 2 * r)
                    color = (110 + i * 20, 180 + i * 10, 255, ring_alpha)
                    pygame.draw.arc(assembly_surface, color, rect, a0, a1, 2)

            # 중앙 코어 점화 + 수직 라이트 샤프트
            if p > 0.8:
                core_strength = min(1.0, (p - 0.8) / 0.2)
                core_r = int(4 + 6 * core_strength)
                core_c = (stone_width // 2, int(stone_height * 0.45))
                glow = pygame.Surface((stone_width, stone_height), pygame.SRCALPHA)
                pygame.draw.circle(glow, (140, 220, 255, int(120 * core_strength)), core_c, core_r * 2)
                assembly_surface.blit(glow, (0, 0), special_flags=pygame.BLEND_ADD)
                # 라이트 샤프트(아래→위)
                shaft_h = int(stone_height * 0.55 * core_strength)
                shaft_rect = pygame.Rect(core_c[0] - 3, core_c[1] - shaft_h, 6, shaft_h * 2)
                pygame.draw.rect(assembly_surface, (180, 240, 255, int(90 + 110 * core_strength)), shaft_rect)

            # 조립 레이어를 기본 스톤 위에 합성
            stone_surface.blit(assembly_surface, (0, 0))

            base_surface.blit(stone_surface, ((width - stone_width) // 2, placement_y))

            # 캐시에 저장
            _blacksmith_blueprint_cache[cache_key] = base_surface.copy()

            # 하단에서 위로 드러나는 리빌 클립으로 완성감 향상
            reveal_h = int(height * p)
            if reveal_h > 0:
                clip = base_surface.subsurface(pygame.Rect(0, height - reveal_h, width, reveal_h))
                surface.blit(clip, (blueprint_rect.left, blueprint_rect.top + height - reveal_h))
            else:
                surface.blit(base_surface, blueprint_rect.topleft)

            # 게이지바 그리기
            gauge_width = blueprint_rect.width
            gauge_height = 6
            gauge_rect = pygame.Rect(blueprint_rect.left, blueprint_rect.top - gauge_height - 6, gauge_width, gauge_height)
            pygame.draw.rect(surface, (40, 50, 70), gauge_rect.inflate(4, 4), border_radius=3)
            if progress_ratio > 0:
                filled_rect = pygame.Rect(gauge_rect.left, gauge_rect.top, int(gauge_width * progress_ratio), gauge_height)
                pygame.draw.rect(surface, (110, 200, 255), filled_rect, border_radius=3)
            pygame.draw.rect(surface, (150, 200, 255), gauge_rect, 1, border_radius=3)
    if turret.blueprint_active and turret.blueprint_rect:
        blueprint_rect = turret.blueprint_rect
        progress_ratio = 0.0
        if BLACKSMITH_TURRET_BUILD_TIME > 0:
            progress_ratio = turret.build_progress / BLACKSMITH_TURRET_BUILD_TIME
        progress_ratio = max(0.0, min(1.0, progress_ratio))

        stage_float = progress_ratio * 3.0
        stage_index = min(2, int(stage_float))
        stage_alpha = stage_float - stage_index

        width = blueprint_rect.width
        height = blueprint_rect.height

        # 캐시 키 생성 (크기 + 진행도 10% 단위)
        progress_stage = int(progress_ratio * 10)
        cache_key = ("turret_bp", width, height, progress_stage)

        # 캐시 히트 체크 - 캐시된 완성된 surface 재사용
        if cache_key in _blacksmith_blueprint_cache:
            cached_surface = _blacksmith_blueprint_cache[cache_key]
            surface.blit(cached_surface, blueprint_rect.topleft)
            # 게이지바 그리기
            gauge_width = blueprint_rect.width
            gauge_height = 6
            gauge_rect = pygame.Rect(blueprint_rect.left, blueprint_rect.top - gauge_height - 6, gauge_width, gauge_height)
            pygame.draw.rect(surface, (40, 50, 70), gauge_rect.inflate(4, 4), border_radius=3)
            if progress_ratio > 0:
                filled_rect = pygame.Rect(gauge_rect.left, gauge_rect.top, int(gauge_width * progress_ratio), gauge_height)
                pygame.draw.rect(surface, (220, 180, 80), filled_rect, border_radius=3)
            pygame.draw.rect(surface, (110, 120, 140), gauge_rect, 1, border_radius=3)
        else:
            # 캐시 미스 - 새로 생성 후 캐시에 저장
            if len(_blacksmith_blueprint_cache) > 30:
                _blacksmith_blueprint_cache.clear()
            base_surface = pygame.Surface((width, height), pygame.SRCALPHA)

            ground_rect = pygame.Rect(2, height - 10, width - 4, 10)
            pygame.draw.rect(base_surface, (90, 70, 55), ground_rect, border_radius=3)
            pygame.draw.rect(base_surface, (70, 55, 40), ground_rect.inflate(4, 2), 2, border_radius=4)

            stake_color = (110, 85, 65)
            rope_color = (160, 130, 95)

            if stage_index >= 0:
                # Stage 1: stake perimeter and dirt patch
                dirt_color = (120, 95, 70, 200)
                dirt_rect = pygame.Rect(6, height - 14, width - 12, 12)
                pygame.draw.rect(base_surface, dirt_color, dirt_rect, border_radius=3)
                for x in (6, width - 8):
                    for y in (height - 12, height - 6):
                        pygame.draw.rect(base_surface, stake_color, (x, y, 4, 8))
                pygame.draw.line(base_surface, rope_color, (8, height - 8), (width - 8, height - 8), 2)

            if stage_index >= 1:
                # Stage 2: wooden frame
                frame_height = height - 16
                post_positions = [8, width // 2, width - 8]
                for px in post_positions:
                    pygame.draw.rect(base_surface, (120, 100, 80), (px - 2, 4, 4, frame_height))
                pygame.draw.rect(base_surface, (150, 120, 90), (10, 8, width - 20, 6))
                pygame.draw.rect(base_surface, (135, 105, 80), (14, 20, width - 28, 4))
                for beam_y in (20, 28 + int(8 * stage_alpha)):
                    pygame.draw.line(base_surface, (160, 125, 90), (10, beam_y), (width - 10, beam_y), 3)

            if stage_index >= 2:
                # Stage 3: partial walls and scaffolding
                wall_height = max(8, int(18 * (0.4 + 0.6 * stage_alpha)))
                wall_rect = pygame.Rect(12, height - 18 - wall_height, width - 24, wall_height)
                pygame.draw.rect(base_surface, (165, 140, 110), wall_rect)
                pygame.draw.rect(base_surface, (200, 180, 150), wall_rect, 2)
                # roof beams
                roof_y = wall_rect.top - 4
                pygame.draw.rect(base_surface, (145, 115, 85), (16, roof_y, width - 32, 4))
                for idx in range(3):
                    beam_x = 18 + idx * ((width - 36) // 2)
                    pygame.draw.line(base_surface, (110, 90, 70), (beam_x, roof_y), (beam_x - 6, roof_y - 10), 2)
                    pygame.draw.line(base_surface, (110, 90, 70), (beam_x + (width - 36) // 2, roof_y), (beam_x + (width - 36) // 2 + 6, roof_y - 10), 2)

            # ▶ 포탑 조립 애니메이션(진척도 반영): 진행도에 따라 금속 부품이 순차적으로 등장
            #    - 0.25: 받침대
            #    - 0.40: 좌/우 지지대
            #    - 0.60: 몸통
            #    - 0.80: 포신/헤드 + 용접 스파크(간헐)
            assembly_surface = pygame.Surface((width, height), pygame.SRCALPHA)
            cx = width // 2
            bottom = height - 2
            top = 4
            build_alpha = int(60 + 140 * progress_ratio)
            edge_alpha = int(80 + 100 * progress_ratio)

            def poly(points, color):
                pygame.draw.polygon(assembly_surface, color, points)

            def line(color, p1, p2, w=1):
                pygame.draw.line(assembly_surface, color, p1, p2, w)

            # 받침대
            if progress_ratio >= 0.25:
                base_h = max(4, int(6 + 6 * min(1.0, (progress_ratio - 0.25) / 0.15)))
                plate = [
                    (cx - width * 0.34, bottom - base_h),
                    (cx + width * 0.34, bottom - base_h),
                    (cx + width * 0.22, bottom + 4),
                    (cx - width * 0.22, bottom + 4),
                ]
                poly([(int(x), int(y)) for x, y in plate], (200, 208, 220, build_alpha))
                line((110, 120, 140, edge_alpha), (int(cx - width * 0.34), int(bottom - base_h)), (int(cx + width * 0.34), int(bottom - base_h)), 2)

            # 좌/우 지지대
            if progress_ratio >= 0.40:
                leg_h = max(10, int(20 * min(1.0, (progress_ratio - 0.40) / 0.20)))
                left_leg = [
                    (cx - width * 0.36, bottom - 8),
                    (cx - width * 0.46, bottom - leg_h - 10),
                    (cx - width * 0.40, bottom - leg_h - 26),
                    (cx - width * 0.24, bottom - 14),
                ]
                right_leg = [
                    (cx + width * 0.36, bottom - 8),
                    (cx + width * 0.46, bottom - leg_h - 10),
                    (cx + width * 0.40, bottom - leg_h - 26),
                    (cx + width * 0.24, bottom - 14),
                ]
                poly([(int(x), int(y)) for x, y in left_leg], (186, 192, 210, build_alpha))
                poly([(int(x), int(y)) for x, y in right_leg], (186, 192, 210, build_alpha))

            # 몸통
            if progress_ratio >= 0.60:
                torso_h = max(10, int(22 * min(1.0, (progress_ratio - 0.60) / 0.20)))
                torso_w = int(width * 0.36)
                torso_rect = pygame.Rect(cx - torso_w // 2, bottom - 18 - torso_h, torso_w, torso_h)
                pygame.draw.rect(assembly_surface, (220, 234, 250, build_alpha), torso_rect)
                pygame.draw.rect(assembly_surface, (120, 130, 160, edge_alpha), torso_rect, 2)

            # 포신/헤드 + 용접 스파크
            if progress_ratio >= 0.80:
                head_w = int(width * 0.22)
                head_h = int(10 * min(1.0, (progress_ratio - 0.80) / 0.15))
                head_rect = pygame.Rect(cx - head_w // 2, top + 8, head_w, head_h)
                pygame.draw.rect(assembly_surface, (230, 210, 210, build_alpha), head_rect)
                # 포신
                barrel_len = int(width * 0.28 * min(1.0, (progress_ratio - 0.80) / 0.20))
                line((220, 180, 120, edge_alpha), (cx, head_rect.top + head_rect.height // 2), (cx, head_rect.top + head_rect.height // 2 - barrel_len), 2)
                # 용접 스파크(간헐)
                if (pygame.time.get_ticks() // 120) % 2 == 0:
                    spark_y = head_rect.bottom + 2
                    for dx in (-6, 0, 6):
                        line((255, 220, 120, 160), (cx + dx, spark_y), (cx + dx + 2, spark_y - 4), 1)

            # 하단에서 위로 드러나는 클립(전체 조립감 강화)
            reveal_h = int(height * progress_ratio)
            if reveal_h > 0:
                clip = assembly_surface.subsurface(pygame.Rect(0, height - reveal_h, width, reveal_h))
                base_surface.blit(clip, (0, height - reveal_h))

            # 캐시에 저장
            _blacksmith_blueprint_cache[cache_key] = base_surface.copy()

            surface.blit(base_surface, blueprint_rect.topleft)

            # 게이지바 그리기
            gauge_width = blueprint_rect.width
            gauge_height = 6
            gauge_rect = pygame.Rect(blueprint_rect.left, blueprint_rect.top - gauge_height - 6, gauge_width, gauge_height)
            pygame.draw.rect(surface, (40, 50, 70), gauge_rect.inflate(4, 4), border_radius=3)
            if progress_ratio > 0:
                filled_rect = pygame.Rect(gauge_rect.left, gauge_rect.top, int(gauge_width * progress_ratio), gauge_height)
                pygame.draw.rect(surface, (220, 180, 80), filled_rect, border_radius=3)
            pygame.draw.rect(surface, (110, 120, 140), gauge_rect, 1, border_radius=3)

    if blacksmith_turret_active and blacksmith_turret_state and blacksmith_turret_state.get("rect"):
        turret_rect = blacksmith_turret_state["rect"]
        turret_level = int(blacksmith_turret_state.get("level", BLACKSMITH_TURRET_BASE_LEVEL))
        cx = turret_rect.centerx
        top = turret_rect.top
        bottom = turret_rect.bottom
        left = turret_rect.left
        right = turret_rect.right
        width = turret_rect.width
        height = turret_rect.height

        scale_x = width / BLACKSMITH_TURRET_DESIGN_WIDTH
        scale_y = height / BLACKSMITH_TURRET_DESIGN_HEIGHT

        def sx_val(value):
            return value * scale_x

        def sy_val(value):
            return value * scale_y

        # 보스/플레이어 패들의 위치에 따른 방향 편향(좌우 기울기용)
        direction_factor = 0.0
        try:
            player_obj = PLAYER
            if player_obj is not None:
                dx = player_obj.centerx - cx
                direction_factor = max(-1.0, min(1.0, dx / max(1.0, sx_val(80))))
        except Exception:
            direction_factor = 0.0

        # 강화 여부에 따라 색상 팔레트 결정
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL:
            base_color = (70, 46, 120)
            base_border_color = (170, 144, 230)
            leg_fill_color = (164, 142, 216)
            leg_border_color = (96, 78, 150)
            claw_fill_color = (194, 92, 214)
            claw_edge_color = (245, 226, 255)
            torso_outer_color = (226, 218, 255)
            torso_inner_color = (156, 70, 210)
            torso_border_color = (74, 40, 96)
            column_fill_color = (90, 72, 144)
            column_inner_color = (176, 186, 242)
        else:
            base_color = (66, 60, 92)
            base_border_color = (130, 122, 170)
            leg_fill_color = (178, 182, 206)
            leg_border_color = (82, 86, 120)
            claw_fill_color = (204, 68, 76)
            claw_edge_color = (255, 220, 130)
            torso_outer_color = (228, 238, 255)
            torso_inner_color = (210, 70, 78)
            torso_border_color = (70, 40, 60)
            column_fill_color = (86, 96, 138)
            column_inner_color = (158, 198, 255)

        # 강화 포탑 전용 호흡 애니메이션(색상 펄스)
        idle_pulse = 0.0
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL:
            ticks = pygame.time.get_ticks()
            idle_phase = ticks / 280.0
            idle_pulse = 0.5 + 0.5 * math.sin(idle_phase * 2.2)

            def _brighten(color, factor: float) -> tuple[int, int, int]:
                r, g, b = color
                delta = int(24 * factor)
                r = min(255, max(0, r + delta))
                g = min(255, max(0, g + delta))
                b = min(255, max(0, b + delta))
                return (r, g, b)

            base_color = _brighten(base_color, idle_pulse)
            leg_fill_color = _brighten(leg_fill_color, idle_pulse * 0.85)
            torso_inner_color = _brighten(torso_inner_color, idle_pulse)
            column_inner_color = _brighten(column_inner_color, idle_pulse * 0.9)

        # 받침대: 강화 포탑일 때는 더 넓고 두꺼운 이중 베이스로 표현
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL:
            base_points = [
                (cx - sx_val(40), bottom - sy_val(10)),
                (cx + sx_val(40), bottom - sy_val(10)),
                (cx + sx_val(30), bottom + sy_val(10)),
                (cx - sx_val(30), bottom + sy_val(10)),
            ]
            upper_base = [
                (cx - sx_val(26), bottom - sy_val(16)),
                (cx + sx_val(26), bottom - sy_val(16)),
                (cx + sx_val(18), bottom - sy_val(8)),
                (cx - sx_val(18), bottom - sy_val(8)),
            ]
        else:
            base_points = [
                (cx - sx_val(36), bottom - sy_val(6)),
                (cx + sx_val(36), bottom - sy_val(6)),
                (cx + sx_val(24), bottom + sy_val(8)),
                (cx - sx_val(24), bottom + sy_val(8)),
            ]
            upper_base = None

        pygame.draw.polygon(surface, base_color, [(int(x), int(y)) for x, y in base_points])
        pygame.draw.lines(surface, base_border_color, True, [(int(x), int(y)) for x, y in base_points], max(1, int(sx_val(2))))
        if upper_base is not None:
            pygame.draw.polygon(surface, base_color, [(int(x), int(y)) for x, y in upper_base])
            pygame.draw.lines(surface, base_border_color, True, [(int(x), int(y)) for x, y in upper_base], max(1, int(sx_val(2))))

        # 다리: 강화 포탑은 더 길고 기울어진 지지대 형태
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL:
            left_leg = [
                (left + sx_val(4), bottom - sy_val(16)),
                (left - sx_val(18), bottom - sy_val(52)),
                (left - sx_val(10), bottom - sy_val(72)),
                (left + sx_val(8), bottom - sy_val(38)),
            ]
            right_leg = [
                (right - sx_val(4), bottom - sy_val(16)),
                (right + sx_val(18), bottom - sy_val(52)),
                (right + sx_val(10), bottom - sy_val(72)),
                (right - sx_val(8), bottom - sy_val(38)),
            ]
        else:
            left_leg = [
                (left + sx_val(2), bottom - sy_val(12)),
                (left - sx_val(12), bottom - sy_val(42)),
                (left - sx_val(6), bottom - sy_val(60)),
                (left + sx_val(10), bottom - sy_val(34)),
            ]
            right_leg = [
                (right - sx_val(2), bottom - sy_val(12)),
                (right + sx_val(12), bottom - sy_val(42)),
                (right + sx_val(6), bottom - sy_val(60)),
                (right - sx_val(10), bottom - sy_val(34)),
            ]
        pygame.draw.polygon(surface, leg_fill_color, [(int(x), int(y)) for x, y in left_leg])
        pygame.draw.polygon(surface, leg_fill_color, [(int(x), int(y)) for x, y in right_leg])
        pygame.draw.lines(surface, leg_border_color, False, [(int(x), int(y)) for x, y in left_leg], max(1, int(sx_val(2))))
        pygame.draw.lines(surface, leg_border_color, False, [(int(x), int(y)) for x, y in right_leg], max(1, int(sx_val(2))))

        # 발톱: 강화 포탑은 더 길고 뾰족한 형태
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL:
            left_claw = [
                (cx - sx_val(22), bottom - sy_val(30)),
                (cx - sx_val(48), bottom - sy_val(6)),
                (cx - sx_val(30), bottom + sy_val(6)),
                (cx - sx_val(10), bottom - sy_val(16)),
            ]
            right_claw = [
                (cx + sx_val(22), bottom - sy_val(30)),
                (cx + sx_val(48), bottom - sy_val(6)),
                (cx + sx_val(30), bottom + sy_val(6)),
                (cx + sx_val(10), bottom - sy_val(16)),
            ]
        else:
            left_claw = [
                (cx - sx_val(18), bottom - sy_val(26)),
                (cx - sx_val(40), bottom - sy_val(8)),
                (cx - sx_val(26), bottom + sy_val(4)),
                (cx - sx_val(10), bottom - sy_val(14)),
            ]
            right_claw = [
                (cx + sx_val(18), bottom - sy_val(26)),
                (cx + sx_val(40), bottom - sy_val(8)),
                (cx + sx_val(26), bottom + sy_val(4)),
                (cx + sx_val(10), bottom - sy_val(14)),
            ]
        pygame.draw.polygon(surface, claw_fill_color, [(int(x), int(y)) for x, y in left_claw])
        pygame.draw.polygon(surface, claw_fill_color, [(int(x), int(y)) for x, y in right_claw])
        pygame.draw.lines(surface, claw_edge_color, True, [(int(x), int(y)) for x, y in left_claw], max(1, int(sx_val(2))))
        pygame.draw.lines(surface, claw_edge_color, True, [(int(x), int(y)) for x, y in right_claw], max(1, int(sx_val(2))))

        # 몸통: 강화 포탑은 더 두껍고 각진 실루엣
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL:
            torso_points = [
                (cx - sx_val(20), bottom - sy_val(50)),
                (cx - sx_val(32), top + sy_val(52)),
                (cx - sx_val(16), top + sy_val(18)),
                (cx - sx_val(6), top + sy_val(8)),
                (cx + sx_val(6), top + sy_val(8)),
                (cx + sx_val(16), top + sy_val(18)),
                (cx + sx_val(32), top + sy_val(52)),
                (cx + sx_val(20), bottom - sy_val(50)),
            ]
            inner_torso = [
                (cx - sx_val(14), bottom - sy_val(46)),
                (cx - sx_val(22), top + sy_val(50)),
                (cx - sx_val(10), top + sy_val(26)),
                (cx - sx_val(2), top + sy_val(14)),
                (cx + sx_val(2), top + sy_val(14)),
                (cx + sx_val(10), top + sy_val(26)),
                (cx + sx_val(22), top + sy_val(50)),
                (cx + sx_val(14), bottom - sy_val(46)),
            ]
        else:
            torso_points = [
                (cx - sx_val(18), bottom - sy_val(46)),
                (cx - sx_val(28), top + sy_val(48)),
                (cx - sx_val(14), top + sy_val(22)),
                (cx - sx_val(6), top + sy_val(12)),
                (cx + sx_val(6), top + sy_val(12)),
                (cx + sx_val(14), top + sy_val(22)),
                (cx + sx_val(28), top + sy_val(48)),
                (cx + sx_val(18), bottom - sy_val(46)),
            ]
            inner_torso = [
                (cx - sx_val(12), bottom - sy_val(44)),
                (cx - sx_val(20), top + sy_val(46)),
                (cx - sx_val(10), top + sy_val(26)),
                (cx - sx_val(2), top + sy_val(16)),
                (cx + sx_val(2), top + sy_val(16)),
                (cx + sx_val(10), top + sy_val(26)),
                (cx + sx_val(20), top + sy_val(46)),
                (cx + sx_val(12), bottom - sy_val(44)),
            ]
        pygame.draw.polygon(surface, torso_outer_color, [(int(x), int(y)) for x, y in torso_points])
        pygame.draw.polygon(surface, torso_inner_color, [(int(x), int(y)) for x, y in inner_torso])
        pygame.draw.lines(surface, torso_border_color, True, [(int(x), int(y)) for x, y in torso_points], max(1, int(sx_val(2))))

        # 강화 포탑 전용 바닥 오로라 + 강철 보랏빛 가시
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL and idle_pulse > 0.0:
            halo_width = int(max(40, sx_val(120)))
            halo_height = int(max(16, sy_val(36)))
            halo_surface = _get_reinforced_turret_halo_surface(halo_width, halo_height)  # 캐싱
            center_x = halo_width // 2
            base_y = halo_height - 1
            outer_alpha = int(50 + 90 * idle_pulse)
            inner_alpha = int(100 + 110 * idle_pulse)
            # 붉은 융단 오로라
            pygame.draw.ellipse(
                halo_surface,
                (220, 40, 40, outer_alpha),
                pygame.Rect(0, int(halo_height * 0.25), halo_width, int(halo_height * 0.8)),
            )
            pygame.draw.ellipse(
                halo_surface,
                (255, 180, 120, inner_alpha),
                pygame.Rect(int(halo_width * 0.1), int(halo_height * 0.4), int(halo_width * 0.8), int(halo_height * 0.5)),
            )
            # 강철 보랏빛 가시들 (halo_surface에 직접 그리기 - spike_surface 생성 제거)
            spike_base_color = (130, 110, 210, 170)
            spike_edge_color = (220, 210, 255, 210)
            for idx, offset in enumerate((-0.6, -0.2, 0.2, 0.6)):
                base_x = center_x + int(offset * halo_width * 0.35)
                height = int((0.4 + 0.18 * idle_pulse) * halo_height * (1.0 + 0.15 * (idx % 2)))
                lean = int(direction_factor * height * 0.3)
                pts = [
                    (base_x - 3, base_y),
                    (base_x + 3, base_y),
                    (base_x + lean, base_y - height),
                ]
                pygame.draw.polygon(halo_surface, spike_base_color, pts)
                pygame.draw.lines(halo_surface, spike_edge_color, True, pts, 1)
            surface.blit(
                halo_surface,
                (int(cx - halo_width / 2), int(bottom - sy_val(4) - halo_height)),
                special_flags=pygame.BLEND_ADD,
            )

        # 강화 포탑일 때 추가 장식 가시(스파이크) – 실루엣은 유지하되 디테일만 증가
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL:
            spike_outer_color = (196, 176, 242)
            spike_inner_color = (236, 220, 255)
            # 받침대 좌우에 짧은 가시
            left_base_spike = [
                (cx - sx_val(40), bottom - sy_val(10)),
                (cx - sx_val(26), bottom - sy_val(10)),
                (cx - sx_val(33), bottom - sy_val(26)),
            ]
            right_base_spike = [
                (cx + sx_val(40), bottom - sy_val(10)),
                (cx + sx_val(26), bottom - sy_val(10)),
                (cx + sx_val(33), bottom - sy_val(26)),
            ]
            pygame.draw.polygon(surface, spike_outer_color, [(int(x), int(y)) for x, y in left_base_spike])
            pygame.draw.polygon(surface, spike_outer_color, [(int(x), int(y)) for x, y in right_base_spike])
            # 몸통 상단에 왕관처럼 솟은 스파이크 3개
            crown_y = top + sy_val(18)
            crown_height = sy_val(16)
            center_spike = [
                (cx - sx_val(6), crown_y),
                (cx + sx_val(6), crown_y),
                (cx, crown_y - crown_height),
            ]
            left_spike = [
                (cx - sx_val(18), crown_y + sy_val(2)),
                (cx - sx_val(8), crown_y + sy_val(2)),
                (cx - sx_val(13), crown_y - crown_height * 0.8),
            ]
            right_spike = [
                (cx + sx_val(8), crown_y + sy_val(2)),
                (cx + sx_val(18), crown_y + sy_val(2)),
                (cx + sx_val(13), crown_y - crown_height * 0.8),
            ]
            for spike in (center_spike, left_spike, right_spike):
                pygame.draw.polygon(surface, spike_outer_color, [(int(x), int(y)) for x, y in spike])
                # 안쪽에 살짝 밝은 색으로 한 번 더
                inner = [(x, y + sy_val(1)) for (x, y) in spike]
                pygame.draw.polygon(surface, spike_inner_color, [(int(x), int(y)) for x, y in inner])

        column_width = max(4, int(sx_val(14)))
        column_height = max(18, int(sy_val(24)))
        center_column = pygame.Rect(int(cx - column_width / 2), int(top + sy_val(26)), column_width, column_height)
        pygame.draw.rect(surface, column_fill_color, center_column, border_radius=int(max(2, sx_val(4))))
        inner_column = center_column.inflate(-max(2, int(sx_val(6))), -max(2, int(sy_val(8))))
        if inner_column.width > 0 and inner_column.height > 0:
            pygame.draw.rect(surface, column_inner_color, inner_column, border_radius=int(max(1, sx_val(3))))

        # 강화 포탑 전용 방향성 핀: 플레이어 패들의 위치에 따라 기울기 변경
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL and abs(direction_factor) > 0.02:
            fin_height = max(6, int(sy_val(14)))
            fin_length = max(8, int(sx_val(22)))
            tilt = fin_length * 0.4 * direction_factor
            mid_y = center_column.centery
            # 왼쪽 핀
            left_base_x = center_column.left - sx_val(4)
            left_pts = [
                (int(left_base_x), int(mid_y - fin_height // 2)),
                (int(left_base_x), int(mid_y + fin_height // 2)),
                (int(left_base_x - fin_length + tilt), int(mid_y)),
            ]
            pygame.draw.polygon(surface, leg_fill_color, left_pts)
            pygame.draw.lines(surface, leg_border_color, True, left_pts, max(1, int(sx_val(2))))
            # 오른쪽 핀
            right_base_x = center_column.right + sx_val(4)
            right_pts = [
                (int(right_base_x), int(mid_y - fin_height // 2)),
                (int(right_base_x), int(mid_y + fin_height // 2)),
                (int(right_base_x + fin_length + tilt), int(mid_y)),
            ]
            pygame.draw.polygon(surface, leg_fill_color, right_pts)
            pygame.draw.lines(surface, leg_border_color, True, right_pts, max(1, int(sx_val(2))))

        angle = blacksmith_turret_state.get("display_angle", -math.pi / 2)
        forward_vec = pygame.math.Vector2(math.cos(angle), math.sin(angle))
        if forward_vec.length() == 0:
            forward_vec = pygame.math.Vector2(0, -1)
        else:
            forward_vec = forward_vec.normalize()
        recoil_offset = blacksmith_turret_state.get("recoil_offset", 0.0)
        pivot_point = pygame.math.Vector2(
            cx,
            top + sy_val(BLACKSMITH_TURRET_HEAD_PIVOT_OFFSET)
        ) - forward_vec * recoil_offset

        head_width = max(24, int(sx_val(84)))
        head_height = max(24, int(sy_val(84)))
        padding_x = max(4, int(sx_val(12)))
        padding_top = max(6, int(sy_val(18)))
        padding_bottom = max(4, int(sy_val(12)))
        # 회전 시 터렛 헤드의 상단이 잘리지 않도록 추가 여백을 확보한다.
        head_surf_w = head_width + padding_x * 2
        head_surf_h = head_height + padding_top + padding_bottom
        head_surface = _get_reinforced_turret_head_surface(head_surf_w, head_surf_h)  # 캐싱
        pivot_local = pygame.math.Vector2(
            padding_x + head_width / 2,
            padding_top + head_height * 0.7,
        )

        def head_point(dx, dy):
            return (int(pivot_local.x + dx), int(pivot_local.y + dy))

        # 헤드 실루엣: 강화 포탑은 더 높고 날카로운 형태
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL:
            body_poly = [
                head_point(-sx_val(14), sy_val(14)),
                head_point(-sx_val(26), -sy_val(6)),
                head_point(-sx_val(14), -sy_val(40)),
                head_point(-sx_val(6), -sy_val(58)),
                head_point(0, -sy_val(66)),
                head_point(sx_val(6), -sy_val(58)),
                head_point(sx_val(14), -sy_val(40)),
                head_point(sx_val(26), -sy_val(6)),
                head_point(sx_val(14), sy_val(14)),
            ]
            head_body_color = (232, 228, 255)
            head_core_color = (168, 92, 214)
            head_border_color = (70, 38, 100)
        else:
            body_poly = [
                head_point(-sx_val(12), sy_val(12)),
                head_point(-sx_val(24), -sy_val(10)),
                head_point(-sx_val(10), -sy_val(34)),
                head_point(-sx_val(4), -sy_val(48)),
                head_point(0, -sy_val(54)),
                head_point(sx_val(4), -sy_val(48)),
                head_point(sx_val(10), -sy_val(34)),
                head_point(sx_val(24), -sy_val(10)),
                head_point(sx_val(12), sy_val(12)),
            ]
            head_body_color = (228, 238, 255)
            head_core_color = (210, 70, 78)
            head_border_color = (70, 40, 60)
        pygame.draw.polygon(head_surface, head_body_color, body_poly)

        # 헤드 중앙 코어 패널
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL:
            core_poly = [
                head_point(-sx_val(10), sy_val(8)),
                head_point(-sx_val(18), -sy_val(10)),
                head_point(-sx_val(8), -sy_val(34)),
                head_point(0, -sy_val(46)),
                head_point(sx_val(8), -sy_val(34)),
                head_point(sx_val(18), -sy_val(10)),
                head_point(sx_val(10), sy_val(8)),
            ]
        else:
            core_poly = [
                head_point(-sx_val(10), sy_val(10)),
                head_point(-sx_val(18), -sy_val(8)),
                head_point(-sx_val(6), -sy_val(30)),
                head_point(0, -sy_val(40)),
                head_point(sx_val(6), -sy_val(30)),
                head_point(sx_val(18), -sy_val(8)),
                head_point(sx_val(10), sy_val(10)),
            ]
        pygame.draw.polygon(head_surface, head_core_color, core_poly)
        pygame.draw.lines(head_surface, head_border_color, True, body_poly, max(1, int(sx_val(2))))

        # 헤드 양옆 클로: 강화 포탑은 더 크게 전개
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL:
            claw_left = [
                head_point(-sx_val(22), sy_val(6)),
                head_point(-sx_val(42), sy_val(18)),
                head_point(-sx_val(32), sy_val(34)),
                head_point(-sx_val(14), sy_val(22)),
            ]
            claw_right = [
                head_point(sx_val(22), sy_val(6)),
                head_point(sx_val(42), sy_val(18)),
                head_point(sx_val(32), sy_val(34)),
                head_point(sx_val(14), sy_val(22)),
            ]
        else:
            claw_left = [
                head_point(-sx_val(18), sy_val(8)),
                head_point(-sx_val(36), sy_val(18)),
                head_point(-sx_val(28), sy_val(30)),
                head_point(-sx_val(12), sy_val(20)),
            ]
            claw_right = [
                head_point(sx_val(18), sy_val(8)),
                head_point(sx_val(36), sy_val(18)),
                head_point(sx_val(28), sy_val(30)),
                head_point(sx_val(12), sy_val(20)),
            ]
        pygame.draw.polygon(head_surface, claw_fill_color, claw_left)
        pygame.draw.polygon(head_surface, claw_fill_color, claw_right)
        pygame.draw.lines(head_surface, claw_edge_color, True, claw_left, max(1, int(sx_val(2))))
        pygame.draw.lines(head_surface, claw_edge_color, True, claw_right, max(1, int(sx_val(2))))

        # 포신: 강화 포탑은 더 길고 각진 실루엣
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL:
            cannon_left = [
                head_point(-sx_val(18), -sy_val(16)),
                head_point(-sx_val(38), -sy_val(38)),
                head_point(-sx_val(30), -sy_val(58)),
                head_point(-sx_val(10), -sy_val(32)),
            ]
            cannon_right = [
                head_point(sx_val(18), -sy_val(16)),
                head_point(sx_val(38), -sy_val(38)),
                head_point(sx_val(30), -sy_val(58)),
                head_point(sx_val(10), -sy_val(32)),
            ]
        else:
            cannon_left = [
                head_point(-sx_val(16), -sy_val(14)),
                head_point(-sx_val(32), -sy_val(32)),
                head_point(-sx_val(26), -sy_val(48)),
                head_point(-sx_val(10), -sy_val(30)),
            ]
            cannon_right = [
                head_point(sx_val(16), -sy_val(14)),
                head_point(sx_val(32), -sy_val(32)),
                head_point(sx_val(26), -sy_val(48)),
                head_point(sx_val(10), -sy_val(30)),
            ]
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL:
            cannon_fill = (212, 178, 255)
            cannon_edge = (80, 40, 112)
        else:
            cannon_fill = (242, 182, 62)
            cannon_edge = (70, 40, 8)
        pygame.draw.polygon(head_surface, cannon_fill, cannon_left)
        pygame.draw.polygon(head_surface, cannon_fill, cannon_right)
        pygame.draw.lines(head_surface, cannon_edge, True, cannon_left, max(1, int(sx_val(2))))
        pygame.draw.lines(head_surface, cannon_edge, True, cannon_right, max(1, int(sx_val(2))))

        # 코어 크기와 광채: 강화 포탑은 더 크고 밝게
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL:
            core_radius = max(4, int(sx_val(11)))
        else:
            core_radius = max(3, int(sx_val(9)))
        core_center = (int(pivot_local.x), int(pivot_local.y - sy_val(12)))
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL:
            core_outer = (120, 220, 255, 210)
            core_inner = (255, 255, 255, 230)
        else:
            core_outer = (40, 200, 255, 180)
            core_inner = (255, 255, 255, 200)
        pygame.draw.circle(head_surface, core_outer, core_center, core_radius)
        pygame.draw.circle(head_surface, core_inner, core_center, max(1, core_radius // 2))

        muzzle_rect = pygame.Rect(0, 0, max(3, int(sx_val(6))), max(4, int(sy_val(16))))
        muzzle_rect.center = head_point(0, -sy_val(54))
        if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL:
            muzzle_fill = (148, 122, 255)
            muzzle_edge = (32, 24, 80)
        else:
            muzzle_fill = (94, 206, 255)
            muzzle_edge = (16, 36, 64)
        pygame.draw.rect(head_surface, muzzle_fill, muzzle_rect, border_radius=max(1, int(sx_val(2))))
        pygame.draw.rect(head_surface, muzzle_edge, muzzle_rect, max(1, int(sx_val(1))), border_radius=max(1, int(sx_val(2))))

        heat_vent = pygame.Rect(0, 0, max(6, int(sx_val(18))), max(4, int(sy_val(10))))
        heat_vent.center = head_point(0, sy_val(2))
        heat_color = (168, 150, 210, 190) if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL else (150, 150, 168, 190)
        pygame.draw.rect(head_surface, heat_color, heat_vent, border_radius=max(1, int(sx_val(3))))

        if blacksmith_turret_state.get("overdrive_active"):
            glow_phase = blacksmith_turret_state.get("overdrive_glow_phase", 0.0)
            pulse = 0.5 + 0.5 * math.sin(glow_phase)
            glow_surface = pygame.Surface(head_surface.get_size(), pygame.SRCALPHA)
            aura_radius = max(head_width, head_height) // 2
            glow_color = (255, 90, 60, int(90 + 110 * pulse))
            pygame.draw.circle(glow_surface, glow_color, (int(pivot_local.x), int(pivot_local.y)), aura_radius)
            head_surface.blit(glow_surface, (0, 0), special_flags=pygame.BLEND_ADD)

        angle_degrees = math.degrees(angle)
        rotated_head = pygame.transform.rotozoom(head_surface, -angle_degrees + 90, 1.0)
        rotated_rect = rotated_head.get_rect(center=(pivot_point.x, pivot_point.y))
        surface.blit(rotated_head, rotated_rect.topleft)

        if blacksmith_turret_state.get("overdrive_active"):
            aura_radius = max(28, int(scale_x * 48))
            aura_surface = pygame.Surface((aura_radius * 2, aura_radius * 2), pygame.SRCALPHA)
            pulse = 0.5 + 0.5 * math.sin(blacksmith_turret_state.get("overdrive_glow_phase", 0.0) * 0.8)
            aura_color = (255, 70, 58, int(80 + 90 * pulse))
            pygame.draw.circle(aura_surface, aura_color, (aura_radius, aura_radius), aura_radius)
            surface.blit(
                aura_surface,
                (int(pivot_point.x - aura_radius), int(pivot_point.y - aura_radius)),
                special_flags=pygame.BLEND_ADD,
            )

        muzzle_distance = BLACKSMITH_TURRET_MUZZLE_LENGTH * scale_x
        muzzle_world = pivot_point + forward_vec * muzzle_distance
        muzzle_tip = muzzle_world + forward_vec * max(4, sx_val(6))
        pygame.draw.line(surface, (180, 240, 255), (int(muzzle_world.x), int(muzzle_world.y)), (int(muzzle_tip.x), int(muzzle_tip.y)), max(1, int(sx_val(2))))

        glow_size = max(12, int(sx_val(32)))
        muzzle_glow = pygame.Surface((glow_size, glow_size), pygame.SRCALPHA)
        pygame.draw.circle(muzzle_glow, (24, 160, 220, 80), (glow_size // 2, glow_size // 2), glow_size // 2)
        pygame.draw.circle(muzzle_glow, (255, 255, 255, 120), (glow_size // 2, glow_size // 2), max(2, glow_size // 4))
        surface.blit(
            muzzle_glow,
            (int(muzzle_world.x - glow_size / 2), int(muzzle_world.y - glow_size / 2)),
            special_flags=pygame.BLEND_ADD,
        )

        flash_timer = blacksmith_turret_state.get("overdrive_flash_timer", 0)
        if flash_timer > 0:
            max_flash = max(1, int(0.18 * FPS))
            flash_ratio = min(1.0, flash_timer / max_flash)
            flash_radius = int(glow_size * (1.1 + 0.6 * flash_ratio))
            flash_surface = pygame.Surface((flash_radius * 2, flash_radius * 2), pygame.SRCALPHA)
            pygame.draw.circle(
                flash_surface,
                (255, 80, 40, int(160 * flash_ratio)),
                (flash_radius, flash_radius),
                flash_radius,
            )
            surface.blit(
                flash_surface,
                (int(muzzle_world.x - flash_radius), int(muzzle_world.y - flash_radius)),
                special_flags=pygame.BLEND_ADD,
            )

            beam_length = muzzle_distance + sx_val(40 * flash_ratio)
            beam_end = muzzle_world + forward_vec * beam_length
            pygame.draw.line(
                surface,
                (255, 140, 70),
                (int(muzzle_world.x), int(muzzle_world.y)),
                (int(beam_end.x), int(beam_end.y)),
                max(2, int(sx_val(3) + flash_ratio * 3)),
            )

        # === SPACE 키캡 힌트 (작게, 포탑 좌상단 옆, 애니메이션) ===
        try:
            if (turret_level >= BLACKSMITH_TURRET_MAX_LEVEL
                and blacksmith_turret_state.get("overdrive_ready", False)
                and not blacksmith_turret_state.get("overdrive_active", False)
                and int(blacksmith_turret_state.get("overheat_timer", 0)) <= 0):
                t_rect = blacksmith_turret_state.get("rect")
                if t_rect is not None:
                    # 살짝 위아래로 흔들리는 보빙 + 알파 펄스
                    ticks = pygame.time.get_ticks()
                    bob = int(2 * math.sin(ticks * 0.008))
                    pulse = 0.5 + 0.5 * math.sin(ticks * 0.004)
                    alpha = 170 + int(70 * pulse)
                    # 위치: 포탑 좌상단 바깥쪽으로 약간 치우치게
                    key_x = int(t_rect.left - 56)
                    key_y = int(t_rect.top - 18 + bob)
                    label = "SPACE"
                    font = FontStyle.tiny()
                    text = font.render(label, True, (28, 34, 54))
                    pad_x, pad_y = 6, 3
                    w, h = text.get_width() + pad_x * 2, text.get_height() + pad_y * 2
                    key_surf = pygame.Surface((w, h), pygame.SRCALPHA)
                    # 색상: 디바인스톤 활성 시 시안톤, 기본은 라이트 톤
                    if is_blacksmith_divine_stone_active():
                        base = (216, 238, 255, alpha)
                        inner = (232, 246, 255, alpha)
                        border = (110, 210, 255, alpha)
                    else:
                        base = (236, 240, 255, alpha)
                        inner = (248, 250, 255, alpha)
                        border = (255, 182, 110, alpha)
                    pygame.draw.rect(key_surf, base, key_surf.get_rect(), border_radius=8)
                    pygame.draw.rect(key_surf, inner, key_surf.get_rect().inflate(-4, -4), border_radius=6)
                    pygame.draw.rect(key_surf, border, key_surf.get_rect(), 1, border_radius=8)
                    key_surf.blit(text, (pad_x, pad_y))
                    surface.blit(key_surf, (key_x, key_y))
        except Exception:
            pass

    for proj in projectiles:
        proj_pos = (int(proj["x"]), int(proj["y"]))
        radius = int(proj.get("radius", BLACKSMITH_TURRET_PROJECTILE_RADIUS))
        overdrive_proj = proj.get("overdrive")
        homing_proj = proj.get("homing")

        if homing_proj:
            # 강화 포탑 유도 미사일: 고급 로켓형 디자인
            angle = math.atan2(proj["vy"], proj["vx"])
            cos_a, sin_a = math.cos(angle), math.sin(angle)

            # 애니메이션용 시간값
            anim_time = pygame.time.get_ticks() / 1000.0
            homing_age = proj.get("homing_age", 0)
            pulse = 0.5 + 0.5 * math.sin(anim_time * 8.0 + homing_age * 0.5)

            # 미사일 크기 스케일
            missile_len = max(16, radius * 2.8)
            missile_width = max(6, radius * 0.9)

            # === 1. 외곽 에너지 오라 (3중 링) ===
            aura_size = int(radius * 5)
            aura_surf = _get_homing_missile_surface(aura_size * 2)  # 캐싱
            aura_center = aura_size
            for i, (r_mult, alpha) in enumerate([(1.8, 40), (1.4, 60), (1.0, 80)]):
                ring_r = int(radius * r_mult * (1.0 + pulse * 0.15))
                ring_color = (180, 120, 255, int(alpha * (0.7 + pulse * 0.3)))
                pygame.draw.circle(aura_surf, ring_color, (aura_center, aura_center), ring_r, max(1, int(2 - i * 0.5)))
            surface.blit(aura_surf, (proj_pos[0] - aura_center, proj_pos[1] - aura_center), special_flags=pygame.BLEND_ADD)

            # === 2. 엔진 배기 불꽃 (다층 플레임) ===
            exhaust_len = missile_len * (0.8 + pulse * 0.4)
            exhaust_base_x = proj_pos[0] - cos_a * (missile_len * 0.4)
            exhaust_base_y = proj_pos[1] - sin_a * (missile_len * 0.4)

            # 외곽 불꽃 (보라색) - 직접 라인 그리기로 Surface 생성 제거
            for flame_i in range(3):
                flame_offset = (flame_i - 1) * missile_width * 0.3
                perp_x, perp_y = -sin_a * flame_offset, cos_a * flame_offset
                flame_tip_x = exhaust_base_x - cos_a * exhaust_len * (0.9 - flame_i * 0.15) + perp_x
                flame_tip_y = exhaust_base_y - sin_a * exhaust_len * (0.9 - flame_i * 0.15) + perp_y
                flame_color = (160 + flame_i * 30, 80 + flame_i * 20, 255)
                pygame.draw.line(surface, flame_color,
                    (int(exhaust_base_x + perp_x), int(exhaust_base_y + perp_y)),
                    (int(flame_tip_x), int(flame_tip_y)),
                    max(2, int(missile_width * 0.5 - flame_i * 0.8)))

            # 내부 코어 불꽃 (시안-화이트)
            core_flame_len = exhaust_len * 0.6
            core_flame_tip = (exhaust_base_x - cos_a * core_flame_len, exhaust_base_y - sin_a * core_flame_len)
            pygame.draw.line(surface, (200, 240, 255), (int(exhaust_base_x), int(exhaust_base_y)),
                (int(core_flame_tip[0]), int(core_flame_tip[1])), max(2, int(missile_width * 0.35)))

            # === 3. 미사일 본체 (유선형 로켓) ===
            # 노즈콘 (앞부분 뾰족)
            nose_tip = (proj_pos[0] + cos_a * missile_len * 0.5, proj_pos[1] + sin_a * missile_len * 0.5)
            nose_base_l = (proj_pos[0] - sin_a * missile_width * 0.4, proj_pos[1] + cos_a * missile_width * 0.4)
            nose_base_r = (proj_pos[0] + sin_a * missile_width * 0.4, proj_pos[1] - cos_a * missile_width * 0.4)

            # 본체 (뒤로 갈수록 넓어짐)
            body_end = (proj_pos[0] - cos_a * missile_len * 0.35, proj_pos[1] - sin_a * missile_len * 0.35)
            body_l = (body_end[0] - sin_a * missile_width * 0.55, body_end[1] + cos_a * missile_width * 0.55)
            body_r = (body_end[0] + sin_a * missile_width * 0.55, body_end[1] - cos_a * missile_width * 0.55)

            # 본체 폴리곤 (외곽)
            body_points = [nose_tip, nose_base_r, body_r, body_l, nose_base_l]
            body_outline = (80, 50, 140)
            body_fill = (140, 100, 200)
            body_highlight = (200, 170, 255)

            pygame.draw.polygon(surface, body_fill, [(int(p[0]), int(p[1])) for p in body_points])
            pygame.draw.polygon(surface, body_outline, [(int(p[0]), int(p[1])) for p in body_points], 2)

            # 본체 하이라이트 라인 (중앙)
            hl_start = (proj_pos[0] + cos_a * missile_len * 0.35, proj_pos[1] + sin_a * missile_len * 0.35)
            hl_end = (proj_pos[0] - cos_a * missile_len * 0.2, proj_pos[1] - sin_a * missile_len * 0.2)
            pygame.draw.line(surface, body_highlight, (int(hl_start[0]), int(hl_start[1])),
                (int(hl_end[0]), int(hl_end[1])), max(1, int(missile_width * 0.15)))

            # === 4. 날개 핀 (좌우 2개) ===
            fin_len = missile_width * 1.2
            fin_width = missile_width * 0.4
            fin_base_x = proj_pos[0] - cos_a * missile_len * 0.25
            fin_base_y = proj_pos[1] - sin_a * missile_len * 0.25

            for side in [-1, 1]:
                fin_root = (fin_base_x + sin_a * missile_width * 0.4 * side,
                            fin_base_y - cos_a * missile_width * 0.4 * side)
                fin_tip = (fin_root[0] + sin_a * fin_len * side - cos_a * fin_width,
                           fin_root[1] - cos_a * fin_len * side - sin_a * fin_width)
                fin_back = (fin_base_x - cos_a * missile_len * 0.1 + sin_a * missile_width * 0.5 * side,
                            fin_base_y - sin_a * missile_len * 0.1 - cos_a * missile_width * 0.5 * side)
                fin_points = [fin_root, fin_tip, fin_back]
                pygame.draw.polygon(surface, (100, 70, 160), [(int(p[0]), int(p[1])) for p in fin_points])
                pygame.draw.polygon(surface, (60, 40, 100), [(int(p[0]), int(p[1])) for p in fin_points], 1)

            # === 5. 코어 에너지 (펄스 애니메이션) ===
            core_x = proj_pos[0] + cos_a * missile_len * 0.1
            core_y = proj_pos[1] + sin_a * missile_len * 0.1
            core_r = max(3, int(missile_width * 0.35 * (0.8 + pulse * 0.4)))
            core_inner = (255, 220, 255, int(200 + pulse * 55))
            core_outer = (180, 140, 255, int(150 + pulse * 50))

            core_surf = _get_homing_missile_surface(core_r * 4)  # 캐싱
            pygame.draw.circle(core_surf, core_outer, (core_r * 2, core_r * 2), int(core_r * 1.5))
            pygame.draw.circle(core_surf, core_inner, (core_r * 2, core_r * 2), core_r)
            surface.blit(core_surf, (int(core_x - core_r * 2), int(core_y - core_r * 2)), special_flags=pygame.BLEND_ADD)

            # === 6. 나선형 에너지 트레일 (직접 그리기로 최적화) ===
            trail_len = missile_len * 1.5
            trail_segments = 6  # 8 → 6으로 축소
            for t_i in range(trail_segments):
                t_ratio = t_i / trail_segments
                t_dist = trail_len * t_ratio
                spiral_phase = anim_time * 12.0 + t_ratio * math.pi * 3
                spiral_amp = missile_width * 0.6 * (1.0 - t_ratio * 0.7)

                t_x = exhaust_base_x - cos_a * t_dist + sin_a * math.sin(spiral_phase) * spiral_amp
                t_y = exhaust_base_y - sin_a * t_dist - cos_a * math.sin(spiral_phase) * spiral_amp
                t_r = max(1, int(3 * (1.0 - t_ratio * 0.6)))

                trail_color = (180, 120, 255)
                pygame.draw.circle(surface, trail_color, (int(t_x), int(t_y)), t_r)

            # === 7. 글로우 오버레이 ===
            glow_size = max(20, int(missile_len * 1.2))
            glow_surface = _get_homing_missile_surface(glow_size)  # 캐싱
            glow_color = (160, 100, 255, int(60 + pulse * 30))
            pygame.draw.circle(glow_surface, glow_color, (glow_size // 2, glow_size // 2), glow_size // 2)
            surface.blit(glow_surface, (proj_pos[0] - glow_size // 2, proj_pos[1] - glow_size // 2), special_flags=pygame.BLEND_ADD)
        else:
            if 'BLACKSMITH_MISSILE_IMG' in globals() and BLACKSMITH_MISSILE_IMG:
                velocity_angle = math.degrees(math.atan2(proj["vy"], proj["vx"])) - 180
                scale = max(0.6, radius / 12)
                missile_img = pygame.transform.rotozoom(BLACKSMITH_MISSILE_IMG, -velocity_angle, scale)
                missile_rect = missile_img.get_rect(center=proj_pos)
                surface.blit(missile_img, missile_rect.topleft)
            else:
                base_color = (240, 210, 120)
                edge_color = (110, 90, 60)
                if overdrive_proj:
                    base_color = (255, 150, 80)
                    edge_color = (190, 70, 40)
                pygame.draw.circle(surface, base_color, proj_pos, radius)
                pygame.draw.circle(surface, edge_color, proj_pos, int(radius * 1.5), 2)

        if overdrive_proj and not homing_proj:
            glow_size = max(12, radius * 4)
            glow_surface = _get_homing_missile_surface(glow_size)  # 캐싱
            glow_center = glow_size // 2
            pygame.draw.circle(glow_surface, (255, 80, 48, 150), (glow_center, glow_center), glow_center)
            pygame.draw.circle(glow_surface, (255, 180, 120, 160), (glow_center, glow_center), max(6, glow_center // 2))
            surface.blit(
                glow_surface,
                (proj_pos[0] - glow_center, proj_pos[1] - glow_center),
                special_flags=pygame.BLEND_ADD,
            )

        if proj.get("divine_overdrive"):
            swirl_size = max(24, radius * 5)
            swirl_surface = _get_homing_missile_surface(swirl_size)  # 캐싱
            swirl_rect = swirl_surface.get_rect()
            phase = (proj.get("trail_timer", 0) * 0.24) % math.tau
            for idx in range(3):
                angle = phase + idx * (math.tau / 3)
                start_angle = angle
                end_angle = angle + math.pi * 0.9
                arc_rect = swirl_rect.inflate(-idx * 6, -idx * 6)
                color_alpha = int(120 - idx * 18)
                arc_color = (90, 220, 255, max(40, color_alpha))
                pygame.draw.arc(swirl_surface, arc_color, arc_rect, start_angle, end_angle, max(2, radius // 2))
            pygame.draw.circle(swirl_surface, (150, 255, 255, 90), swirl_rect.center, max(4, radius))
            surface.blit(
                swirl_surface,
                (proj_pos[0] - swirl_rect.width // 2, proj_pos[1] - swirl_rect.height // 2),
                special_flags=pygame.BLEND_ADD,
            )
    
    # 포탑 손상 오버레이 그리기 (투사체 루프 밖에서)
    if turret_rect:
        damage_manager = get_damage_manager()
        damage_manager.draw_damage_overlay(surface, "turret", turret_rect)
        # 포탑 위치 업데이트
        damage_manager.update_building_rect("turret", turret_rect)
        
    draw_blacksmith_build_menu(surface)

    # 발토르 건물 손상 효과 그리기
    damage_manager = get_damage_manager()
    damage_manager.draw(surface)
    valthor_perf_end("draw_turret_elements")


def draw_blacksmith_divine_stone(surface, divine_state=None):
    valthor_perf_start("draw_divine_stone")
    if divine_state is None:
        sync_blacksmith_state()
        divine_state = BLACKSMITH_CONTROLLER.state.divine.state

    if not _is_divine_state_active(divine_state):
        get_damage_manager().clear_building("divine_stone")
        valthor_perf_end("draw_divine_stone")
        return
    rect = divine_state["rect"]
    # 첫 프레임에서도 위치가 중앙으로 스냅되는 것을 막기 위해 드로잉 단계에서도 X 락을 1회 적용한다.
    try:
        lock = blacksmith_persist_lock_pos
        if lock and lock.get("divine_x") is not None:
            saved_x = int(lock["divine_x"])
            rect.centerx = max(rect.width // 2, min(WIDTH - rect.width // 2, saved_x))
            if int(lock.get("divine_frames", 0)) > 0:
                globals()["blacksmith_persist_lock_pos"]["divine_frames"] = int(lock.get("divine_frames", 0)) - 1
            if int(globals()["blacksmith_persist_lock_pos"]["divine_frames"]) <= 0:
                globals()["blacksmith_persist_lock_pos"]["divine_x"] = None
    except Exception:
        pass
    pulse = divine_state.get("pulse", 0)
    reinforced = bool(divine_state.get("reinforced", False))
    hp = divine_state.get("hp", BLACKSMITH_DIVINE_STONE_MAX_HP)
    max_hp = max(1, divine_state.get("max_hp", BLACKSMITH_DIVINE_STONE_MAX_HP))
    width, height = rect.size
    padding_x = max(4, width // 12)
    padding_top = max(6, height // 10)
    padding_bottom = max(6, height // 12)
    draw_width = width + padding_x * 2
    draw_height = height + padding_top + padding_bottom
    structure_surface = _get_divine_stone_structure_surface(draw_width, draw_height)  # 성능 최적화: 캐싱
    frame_value = float(frame_counter)
    deploy_frames = max(1, BLACKSMITH_DIVINE_DEPLOY_FRAMES)
    deploy_timer = min(deploy_frames, int(divine_state.get("deploy_timer", deploy_frames)))
    base_ratio = deploy_timer / deploy_frames
    structure_progress = 1.0 - pow(1.0 - base_ratio, 3)
    structure_progress = max(0.0, min(1.0, structure_progress))
    base_progress = min(1.0, structure_progress / 0.4)
    pillar_progress = max(0.0, min(1.0, (structure_progress - 0.2) / 0.5))
    cap_progress = max(0.0, min(1.0, (structure_progress - 0.45) / 0.45))
    core_progress = max(0.0, min(1.0, (structure_progress - 0.55) / 0.45))
    idle_wave = math.sin(frame_value * 0.05) * 0.5

    cx = padding_x + width // 2
    cy = padding_top + height // 2

    base_height = max(12, height // 5)
    base_bottom = padding_top + height - 2
    base_height_eff = max(2, int(base_height * base_progress))
    base_top = base_bottom - base_height_eff
    base_rect = pygame.Rect(padding_x + 6, base_top, width - 12, base_height_eff)
    pygame.draw.rect(structure_surface, (70, 60, 85), base_rect, border_radius=6)
    if base_rect.width > 0 and base_rect.height > 4:
        inner_rect = base_rect.inflate(-6, -4)
        if inner_rect.width > 0 and inner_rect.height > 0:
            pygame.draw.rect(structure_surface, (140, 120, 170), inner_rect, border_radius=4)
        outline_rect = base_rect.inflate(-10, -8)
        if outline_rect.width > 0 and outline_rect.height > 0:
            pygame.draw.rect(structure_surface, (220, 200, 255), outline_rect, border_radius=3, width=2)

    pillar_bottom = base_top
    pillar_top = pillar_bottom
    pillar_height_eff = 0
    left_pillar = None
    right_pillar = None

    if pillar_progress > 0:
        pillar_width = max(6, width // 6)
        pillar_height = max(12, height - base_height - 18)
        pillar_height_eff = max(4, int(pillar_height * pillar_progress))
        pillar_top = pillar_bottom - pillar_height_eff
        left_pillar = pygame.Rect(padding_x + 8, pillar_top, pillar_width, pillar_height_eff)
        right_pillar = pygame.Rect(padding_x + width - pillar_width - 8, pillar_top, pillar_width, pillar_height_eff)
        pygame.draw.rect(structure_surface, (120, 115, 150), left_pillar, border_radius=4)
        pygame.draw.rect(structure_surface, (120, 115, 150), right_pillar, border_radius=4)
        inner_left = left_pillar.inflate(-4, -4)
        inner_right = right_pillar.inflate(-4, -4)
        if inner_left.width > 0 and inner_left.height > 0:
            pygame.draw.rect(structure_surface, (200, 190, 240), inner_left, border_radius=3, width=2)
        if inner_right.width > 0 and inner_right.height > 0:
            pygame.draw.rect(structure_surface, (200, 190, 240), inner_right, border_radius=3, width=2)

    if cap_progress > 0 and left_pillar and right_pillar:
        cap_height = max(10, height // 6)
        cap_height_eff = max(2, int(cap_height * cap_progress))
        cap_bottom = pillar_top
        cap_top = cap_bottom - cap_height_eff + 4
        cap_rect = pygame.Rect(left_pillar.left - 6, cap_top, right_pillar.right - left_pillar.left + 12, cap_height_eff)
        pygame.draw.rect(structure_surface, (90, 80, 120), cap_rect, border_radius=6)
        inner_cap = cap_rect.inflate(-6, -4)
        if inner_cap.width > 0 and inner_cap.height > 0:
            pygame.draw.rect(structure_surface, (150, 140, 200), inner_cap, border_radius=5)
        detail_cap = cap_rect.inflate(-10, -6)
        if detail_cap.width > 0 and detail_cap.height > 0:
            pygame.draw.rect(structure_surface, (210, 200, 255), detail_cap, border_radius=4, width=2)

        arch_total_height = cap_height + 12
        arch_height = max(4, int(arch_total_height * cap_progress))
        arch_rect = pygame.Rect(
            left_pillar.left - 4,
            cap_bottom - arch_height - int(4 * cap_progress),
            right_pillar.right - left_pillar.left + 8,
            arch_height,
        )
        if arch_rect.height > 2:
            pygame.draw.arc(
                structure_surface,
                (130, 120, 200),
                arch_rect,
                math.pi,
                2 * math.pi,
                max(1, int(3 * cap_progress)),
            )

    mana_center_y = base_top - 10
    if pillar_height_eff > 0:
        mana_center_y = pillar_top + pillar_height_eff * 0.5
    float_offset = (math.sin(pulse * 0.08) + idle_wave) * 3 * core_progress
    mana_center_y = max(padding_top + 4, mana_center_y + float_offset)
    mana_center = pygame.math.Vector2(cx, mana_center_y)

    if core_progress > 0:
        base_orb_radius = max(6, width // 5)
        orbital_radius = max(2, int(base_orb_radius * core_progress))
        core_radius = max(4, int((width // 6) * max(0.35, core_progress)))
        glow_radius = core_radius + max(4, int(6 * core_progress))

        # 일반 디바인스톤: 중심 에너지 구체 응집/폭발 시스템
        if not reinforced:
            # 번개 쿨타임 기반 충전 상태 계산
            lightning_cd = divine_state.get("lightning_cd", 0)
            lightning_max_cd = int(20 * FPS)  # 평균 쿨타임 (15~25초)

            # 충전 진행도 (0.0 = 발사 직후, 1.0 = 완전 충전)
            if lightning_cd > 0:
                charge_progress = 1.0 - (lightning_cd / lightning_max_cd)
                charge_progress = max(0.0, min(1.0, charge_progress))
            else:
                charge_progress = 1.0

            # 폭발 상태 감지
            explosion_ttl = divine_state.get("explosion_ttl", 0)
            is_exploding = explosion_ttl > 0

            if is_exploding:
                # 폭발 시: 에너지 구슬이 바깥으로 터짐
                explosion_ratio = explosion_ttl / max(1, int(0.25 * FPS))

                # 폭발 파동 (바깥으로 퍼져나감) - 성능 최적화: 캐싱
                wave_radius = int(glow_radius * (1 + (1.0 - explosion_ratio) * 4))
                wave_alpha = int(220 * explosion_ratio)
                if wave_radius > 0:
                    wave_surf = _get_divine_stone_glow_surface(wave_radius)
                    pygame.draw.circle(wave_surf, (150, 200, 255, wave_alpha),
                                     (wave_radius, wave_radius), wave_radius, 3)
                    structure_surface.blit(wave_surf, (int(mana_center.x - wave_radius), int(mana_center.y - wave_radius)))

                # 두 번째 파동 - 성능 최적화: 캐싱
                wave2_radius = int(glow_radius * (1 + (1.0 - explosion_ratio) * 2.5))
                wave2_alpha = int(160 * explosion_ratio)
                if wave2_radius > 0:
                    wave2_surf = _get_divine_stone_glow_surface(wave2_radius)
                    pygame.draw.circle(wave2_surf, (200, 230, 255, wave2_alpha),
                                     (wave2_radius, wave2_radius), wave2_radius, 2)
                    structure_surface.blit(wave2_surf, (int(mana_center.x - wave2_radius), int(mana_center.y - wave2_radius)))

                # 중심 잔여 에너지 - 성능 최적화: 캐싱
                shrink_size = int(core_radius * explosion_ratio * 0.6)
                if shrink_size > 0:
                    shrink_alpha = int(255 * explosion_ratio)
                    shrink_surf = _get_divine_stone_glow_surface(shrink_size)
                    pygame.draw.circle(shrink_surf, (255, 255, 255, shrink_alpha),
                                     (shrink_size, shrink_size), shrink_size)
                    structure_surface.blit(shrink_surf, (int(mana_center.x - shrink_size), int(mana_center.y - shrink_size)))
            else:
                # 충전 중: 에너지 구슬이 점점 커짐
                # 크기가 충전에 따라 증가 (0.15 → 1.0 로 더 극적으로)
                current_glow = int(glow_radius * (0.15 + charge_progress * 0.85))
                current_core = int(core_radius * (0.15 + charge_progress * 0.85))

                # 알파값도 충전에 따라 증가 (더 밝게)
                outer_alpha = max(0, min(255, int((20 + charge_progress * 40) * core_progress)))
                inner_alpha = max(0, min(255, int((15 + charge_progress * 35) * core_progress)))
                core_alpha = max(0, min(255, int((10 + charge_progress * 30) * core_progress)))

                # 색상이 충전에 따라 변화 (파랑 → 밝은 파랑/흰색)
                r_outer = int(100 + charge_progress * 80)
                g_outer = int(150 + charge_progress * 80)
                b_outer = 255

                r_inner = int(150 + charge_progress * 80)
                g_inner = int(200 + charge_progress * 40)
                b_inner = 255

                # 외부 글로우 - 성능 최적화: 캐싱
                if current_glow > 0:
                    outer_surf = _get_divine_stone_glow_surface(current_glow)
                    pygame.draw.circle(outer_surf, (r_outer, g_outer, b_outer, outer_alpha),
                                     (current_glow, current_glow), current_glow)
                    structure_surface.blit(outer_surf, (int(mana_center.x - current_glow), int(mana_center.y - current_glow)))

                # 내부 글로우 - 성능 최적화: 캐싱
                if current_core > 0:
                    inner_surf = _get_divine_stone_glow_surface(current_core)
                    pygame.draw.circle(inner_surf, (r_inner, g_inner, b_inner, inner_alpha),
                                     (current_core, current_core), current_core)
                    structure_surface.blit(inner_surf, (int(mana_center.x - current_core), int(mana_center.y - current_core)))

                # 중심 하얀 코어 - 성능 최적화: 캐싱
                core_surf_size = max(2, current_core - 2)
                if core_surf_size > 0:
                    core_surf = _get_divine_stone_glow_surface(core_surf_size)
                    pygame.draw.circle(core_surf, (255, 255, 255, core_alpha),
                                     (core_surf_size, core_surf_size), core_surf_size)
                    structure_surface.blit(core_surf, (int(mana_center.x - core_surf_size), int(mana_center.y - core_surf_size)))

                # 충전 완료 시 맥동 효과 - 성능 최적화: 캐싱
                if charge_progress > 0.85:
                    pulse_intensity = (math.sin(pulse * 0.4) + 1) * 0.5
                    pulse_size = int(current_glow + pulse_intensity * 5)
                    pulse_alpha = int(60 * pulse_intensity)
                    if pulse_size > 0:
                        pulse_surf = _get_divine_stone_glow_surface(pulse_size)
                        pygame.draw.circle(pulse_surf, (200, 230, 255, pulse_alpha),
                                         (pulse_size, pulse_size), pulse_size)
                        structure_surface.blit(pulse_surf, (int(mana_center.x - pulse_size), int(mana_center.y - pulse_size)))

        rune_progress = (pulse % 180) / 180.0
        orb_alpha = int(180 * core_progress)

        # === 강화 디바인스톤: 에너지 응집/폭발 시스템 ===
        if reinforced and orb_alpha > 0 and orbital_radius > 1:
            # 번개 쿨타임 기반 충전 상태 계산
            lightning_cd = divine_state.get("lightning_cd", 0)
            lightning_max_cd = int(18 * FPS)  # 평균 쿨타임 (13~23초)

            # 충전 진행도 (0.0 = 충전 완료/발사 직후, 1.0 = 쿨타임 막 시작)
            if lightning_cd > 0:
                charge_progress = 1.0 - (lightning_cd / lightning_max_cd)
                charge_progress = max(0.0, min(1.0, charge_progress))
            else:
                charge_progress = 1.0  # 완전 충전

            # 폭발 상태 감지 (번개 발사 직후)
            explosion_ttl = divine_state.get("explosion_ttl", 0)
            is_exploding = explosion_ttl > 0

            # === 위/아래 떠다니는 에너지 구체 ===
            for orb_idx in range(2):
                # 기본 위치: 위쪽(0), 아래쪽(1)
                base_offset_y = -25 if orb_idx == 0 else 25

                # 둥둥 떠다니는 애니메이션
                float_anim = math.sin(pulse * 0.1 + orb_idx * math.pi) * 5

                if is_exploding:
                    # 폭발 시: 에너지 쉴드가 바깥으로 터짐
                    explosion_ratio = explosion_ttl / max(1, int(0.22 * FPS))
                    burst_distance = (1.0 - explosion_ratio) * 40
                    orb_y = mana_center.y + base_offset_y * (1 + burst_distance / 25)
                    orb_size = int(5 + (1.0 - explosion_ratio) * 8)
                    orb_intensity = int(255 * explosion_ratio)
                    # 폭발 색상: 붉은 보라색
                    orb_color = (255, 150 + int(105 * explosion_ratio), 200, orb_intensity)
                else:
                    # 충전 중: 에너지 응집
                    # 충전이 진행될수록 중심으로 모임
                    concentrate_factor = charge_progress * 0.4
                    orb_y = mana_center.y + base_offset_y * (1.0 - concentrate_factor) + float_anim

                    # 충전이 진행될수록 크기와 강도 증가
                    base_size = 4 + charge_progress * 4
                    orb_size = int(base_size)
                    orb_intensity = int(120 + charge_progress * 135)

                    # 충전 상태에 따른 색상 변화 (파랑 → 보라 → 붉은보라)
                    r = int(120 + charge_progress * 135)
                    g = int(200 - charge_progress * 100)
                    b = int(255 - charge_progress * 55)
                    orb_color = (r, g, b, orb_intensity)

                orb_x = mana_center.x

                # 에너지 구체 글로우
                glow_size = orb_size + 6
                glow_alpha = min(80, int(orb_intensity * 0.4))
                if glow_alpha > 0:
                    pygame.draw.circle(
                        structure_surface,
                        (orb_color[0], orb_color[1], orb_color[2], glow_alpha),
                        (int(orb_x), int(orb_y)),
                        glow_size,
                    )

                # 에너지 구체 본체
                pygame.draw.circle(
                    structure_surface,
                    orb_color,
                    (int(orb_x), int(orb_y)),
                    orb_size,
                )

                # 구체 중심 하이라이트
                if orb_size > 2:
                    pygame.draw.circle(
                        structure_surface,
                        (255, 255, 255, min(200, orb_intensity)),
                        (int(orb_x), int(orb_y)),
                        max(1, orb_size // 2),
                    )

            # === 충전 중 주변 회전 에너지 입자 ===
            if charge_progress > 0.3:
                particle_count = int(4 + charge_progress * 4)
                particle_radius = orbital_radius * (1.2 - charge_progress * 0.5)
                for idx in range(particle_count):
                    # 회전 속도: 충전될수록 빨라짐
                    rot_speed = 2 + charge_progress * 6
                    angle = math.radians((360 / particle_count) * idx + pulse * rot_speed)
                    px = mana_center.x + math.cos(angle) * particle_radius
                    py = mana_center.y + math.sin(angle) * particle_radius

                    # 입자 색상과 크기
                    p_intensity = int(100 + charge_progress * 155)
                    p_size = 2 + int(charge_progress * 2)
                    p_r = int(150 + charge_progress * 105)
                    p_g = int(180 - charge_progress * 80)
                    p_b = 255

                    pygame.draw.circle(
                        structure_surface,
                        (p_r, p_g, p_b, p_intensity),
                        (int(px), int(py)),
                        p_size,
                    )

            # === 폭발 파동 효과 ===
            if is_exploding:
                explosion_ratio = explosion_ttl / max(1, int(0.22 * FPS))
                wave_radius = int((1.0 - explosion_ratio) * 35)
                wave_alpha = int(200 * explosion_ratio)
                if wave_radius > 0 and wave_alpha > 0:
                    pygame.draw.circle(
                        structure_surface,
                        (255, 180, 220, wave_alpha),
                        (int(mana_center.x), int(mana_center.y)),
                        wave_radius,
                        2,
                    )

        # === 기본 디바인스톤: 기존 오비탈 구체 ===
        elif not reinforced and orb_alpha > 0 and orbital_radius > 1:
            for angle_deg in range(0, 360, 60):
                angle = math.radians(angle_deg + rune_progress * 120)
                orb_pos = mana_center + pygame.math.Vector2(math.cos(angle), math.sin(angle)) * orbital_radius
                pygame.draw.circle(structure_surface, (120, 200, 255, orb_alpha), _vec_to_int_pair(orb_pos), 3)

        spark_count = 4
        spark_alpha = int(180 * core_progress)
        if spark_alpha > 0 and orbital_radius > 1:
            for idx in range(spark_count):
                spark_angle = math.radians((360 / spark_count) * idx + pulse * 4)
                outer = mana_center + pygame.math.Vector2(math.cos(spark_angle), math.sin(spark_angle)) * (orbital_radius + 10)
                inner = mana_center + pygame.math.Vector2(math.cos(spark_angle), math.sin(spark_angle)) * (orbital_radius - 2)
                pygame.draw.line(
                    structure_surface,
                    (150, 220, 255, spark_alpha),
                    _vec_to_int_pair(inner),
                    _vec_to_int_pair(outer),
                    2,
                )

        if left_pillar and right_pillar:
            chain_alpha = int(255 * min(1.0, core_progress * 1.2))
            chain_y = mana_center.y - core_radius - 6
            pygame.draw.line(
                structure_surface,
                (180, 190, 240, chain_alpha),
                (left_pillar.centerx, int(chain_y)),
                (right_pillar.centerx, int(chain_y)),
                max(1, int(2 * core_progress)),
            )

        halo_alpha = int((40 + 30 * math.sin(pulse * 0.04)) * core_progress)
        if halo_alpha > 0:
            halo_surface = _get_divine_stone_glow_surface(max(draw_width, draw_height) // 2)  # 캐싱
            halo_radius = max(width // 2, height // 2)
            pygame.draw.circle(halo_surface, (90, 140, 240, min(255, halo_alpha)), (halo_surface.get_width() // 2, halo_surface.get_height() // 2), halo_radius)
            structure_surface.blit(halo_surface, (cx - halo_surface.get_width() // 2, cy - halo_surface.get_height() // 2))

    tower_surface = _get_divine_tower_surface(draw_width, draw_height)  # 캐싱
    if structure_progress > 0:
        visible_height = max(2, int(draw_height * structure_progress))
        clip_top = draw_height - visible_height
        clip_rect = pygame.Rect(0, clip_top, draw_width, visible_height)
        tower_surface.blit(structure_surface, (0, clip_top), clip_rect)
        if structure_progress < 1.0:
            band_height = max(3, int(6 * (1.0 - structure_progress)))
            band_y = max(0, clip_top - band_height)
            band_alpha = int(140 * (1.0 - structure_progress))
            pygame.draw.rect(tower_surface, (180, 160, 120, band_alpha), (0, band_y, draw_width, band_height))
            band_color = (150, 120, 90, int(90 * (1.0 - structure_progress)))
            scan_offset = int((frame_value * 2) % 12)
            for offset in range(-8, draw_width + 12, 12):
                start = (offset + scan_offset, band_y)
                end = (offset + scan_offset + 6, band_y + band_height)
                pygame.draw.line(tower_surface, band_color, start, end, 1)
    # 강화 디바인스톤은 구조물 자체만 약하게 검붉게 틴트 (배경 사각형 전체가 물들지 않도록 가산 오버레이는 사용하지 않는다)
    if reinforced:
        try:
            tower_surface.fill((215, 110, 135, 255), special_flags=pygame.BLEND_RGBA_MULT)
        except Exception:
            pass

    surface.blit(tower_surface, (rect.left - padding_x, rect.top - padding_top))
    
    # 디바인스톤 손상 오버레이 그리기
    damage_manager = get_damage_manager()
    damage_manager.draw_damage_overlay(surface, "divine_stone", rect)
    # 디바인스톤 위치 업데이트
    damage_manager.update_building_rect("divine_stone", rect)

    hp_ratio = 0.0
    if max_hp > 0:
        hp_ratio = max(0.0, min(1.0, hp / max_hp))

    bar_height = 8
    bar_rect = pygame.Rect(
        rect.left,
        rect.bottom + 4,
        rect.width,
        bar_height,
    )
    pygame.draw.rect(surface, (35, 35, 45), bar_rect.inflate(4, 4), border_radius=3)

    fill_width = int(bar_rect.width * hp_ratio)
    if fill_width > 0:
        fill_rect = pygame.Rect(bar_rect.left, bar_rect.top, fill_width, bar_rect.height)
        pygame.draw.rect(surface, (108, 198, 128), fill_rect, border_radius=3)
    pygame.draw.rect(surface, (90, 100, 110), bar_rect, 1, border_radius=3)

    status_font = FontStyle.tiny()
    status_text = status_font.render(f"HP {hp}/{max_hp}", True, (220, 230, 235))
    surface.blit(status_text, status_text.get_rect(center=bar_rect.center))
    valthor_perf_end("draw_divine_stone")


def draw_blacksmith_build_menu(surface):
    sync_blacksmith_state()
    state = BLACKSMITH_CONTROLLER.state
    if not state.build_menu_active or 'PLAYER' not in globals() or PLAYER is None:
        return
    turret_runtime = state.turret
    divine_runtime = state.divine
    option_states = [
        ("turret", not turret_runtime.active and not turret_runtime.blueprint_active),
        ("divine_stone", divine_runtime.state is None and not divine_runtime.blueprint_active),
    ]

    if not any(available for _, available in option_states):
        state.build_menu_active = False
        state.down_hold_frames = 0
        push_blacksmith_state()
        return

    spacing = BLACKSMITH_BUILD_ICON_SIZE[0] + 36
    base_x = PLAYER.centerx
    base_y = max(60, PLAYER.top - 60)

    option_count = len(option_states)
    # 마우스 오버 하이라이트를 위한 포지션 스냅샷
    try:
        mouse_pos = pygame.mouse.get_pos()
    except Exception:
        mouse_pos = (-1, -1)
    for idx, (option, available) in enumerate(option_states):
        icon = BLACKSMITH_TURRET_ICON if option == "turret" else BLACKSMITH_DIVINE_ICON
        icon_surface = icon.copy()
        if not available:
            dim = pygame.Surface(icon_surface.get_size(), pygame.SRCALPHA)
            dim.fill((0, 0, 0, 150))
            icon_surface.blit(dim, (0, 0))
        offset_x = (idx - (option_count - 1) / 2) * spacing
        dest_rect = icon_surface.get_rect(center=(base_x + offset_x, base_y))
        # 배경 패널
        panel_rect = dest_rect.inflate(18, 18)
        pygame.draw.rect(surface, (15, 20, 30, 180), panel_rect, border_radius=12)
        # 기본 테두리 색상
        border_color = (90, 150, 240, 220) if available else (60, 70, 90, 160)
        border_width = 2
        # 마우스 오버 하이라이트(가능 상태에서만 강조)
        is_hovered = dest_rect.collidepoint(mouse_pos)
        if available and is_hovered:
            border_color = (255, 230, 120, 255)
            border_width = 4
            # 은은한 글로우
            glow_rect = dest_rect.inflate(28, 28)
            glow_surf = pygame.Surface(glow_rect.size, pygame.SRCALPHA)
            pygame.draw.rect(glow_surf, (255, 220, 120, 60), glow_surf.get_rect(), border_radius=16)
            surface.blit(glow_surf, glow_rect.topleft)
        pygame.draw.rect(surface, border_color, dest_rect.inflate(22, 22), width=border_width, border_radius=14)
        # 좌상단 숫자 배지(1=포탑, 2=디바인스톤)
        try:
            num = '1' if option == 'turret' else '2'
            # 살짝 더 좌측 상단으로 이동
            badge_center = (dest_rect.left + 6, dest_rect.top + 6)
            # 요청: 흰색 동그라미 배경 + 검은색 숫자
            pygame.draw.circle(surface, (255, 255, 255), badge_center, 8)
            pygame.draw.circle(surface, (0, 0, 0), badge_center, 8, 2)
            font_num = FontStyle.tiny()
            num_surf = font_num.render(num, True, (0, 0, 0))
            num_rect = num_surf.get_rect(center=badge_center)
            surface.blit(num_surf, num_rect)
        except Exception:
            pass
        surface.blit(icon_surface, dest_rect)
        font = FontStyle.tiny()
        text_color = (255, 255, 255) if available else (150, 150, 150)
        name = "포탑" if option == "turret" else "디바인스톤"
        label = font.render(name, True, text_color)
        label_rect = label.get_rect(midbottom=(dest_rect.centerx, dest_rect.top - 12))
    surface.blit(label, label_rect)


_blacksmith_divine_ui_icon_cache: dict[int, pygame.Surface] = {}

def blacksmith_get_build_menu_option_rects() -> list[tuple[str, pygame.Rect, bool]]:
    """현재 발토르 건설 HUD의 옵션 버튼 사각형 목록을 계산한다.

    Returns: [(option_id, rect, available), ...]
    option_id: "turret" | "divine_stone"
    available: 현재 건설 가능 여부
    """
    sync_blacksmith_state()
    state = BLACKSMITH_CONTROLLER.state
    turret_runtime = state.turret
    divine_runtime = state.divine
    option_states = [
        ("turret", not turret_runtime.active and not turret_runtime.blueprint_active),
        ("divine_stone", divine_runtime.state is None and not divine_runtime.blueprint_active),
    ]
    spacing = BLACKSMITH_BUILD_ICON_SIZE[0] + 36
    base_x = PLAYER.centerx if 'PLAYER' in globals() and PLAYER is not None else WIDTH // 2
    base_y = max(60, PLAYER.top - 60) if 'PLAYER' in globals() and PLAYER is not None else HEIGHT // 3
    option_count = len(option_states)
    rects: list[tuple[str, pygame.Rect, bool]] = []
    for idx, (option, available) in enumerate(option_states):
        offset_x = (idx - (option_count - 1) / 2) * spacing
        dummy_icon = pygame.Surface(BLACKSMITH_BUILD_ICON_SIZE, pygame.SRCALPHA)
        dest_rect = dummy_icon.get_rect(center=(base_x + offset_x, base_y))
        rects.append((option, dest_rect, available))
    return rects

