    muzzle_rect = pygame.Rect(icon_rect.centerx - icon_rect.width * 0.05, icon_rect.y - icon_rect.height * 0.22,
                               int(icon_rect.width * 0.1), int(icon_rect.height * 0.18))
    pygame.draw.rect(surface, (94, 206, 255), muzzle_rect, border_radius=3)
    pygame.draw.rect(surface, (16, 36, 64), muzzle_rect, 2, border_radius=3)

    title_font = FontStyle.tiny()
    turret_level: int | None = None
    if blacksmith_turret_active and blacksmith_turret_state:
        turret_level = int(blacksmith_turret_state.get("level", BLACKSMITH_TURRET_BASE_LEVEL))
        if overheat_active:
            title_label = "포탑 • 과부하"
        elif overdrive_display:
            if ui_divine:
                title_label = "포탑 • 메가드라이브"
            elif overdrive_active:
                title_label = "포탑 • 오버드라이브"
            else:
                title_label = "포탑 • 점화"
        else:
            # 레벨 2 이상에서는 UI에서 '강화 포탑'으로 표시
            title_label = "강화 포탑" if turret_level >= BLACKSMITH_TURRET_MAX_LEVEL else "포탑"
    elif blacksmith_turret_blueprint_active:
        title_label = "포탑 건설중"
    else:
        title_label = "포탑"
    title_text = title_font.render(title_label, True, accent_color)
    title_rect = title_text.get_rect(midbottom=(icon_rect.centerx, icon_rect.top - 4))
    surface.blit(title_text, title_rect)

    bar_height = 8
    bar_rect = pygame.Rect(icon_rect.x, icon_rect.bottom + 6, icon_rect.width, bar_height)
    xp_rect = pygame.Rect(icon_rect.x, bar_rect.bottom + 6, icon_rect.width, bar_height)
    pygame.draw.rect(surface, (35, 35, 45), bar_rect.inflate(4, 4), border_radius=3)

    status_text = None
    xp_text = None

    if blacksmith_turret_active and blacksmith_turret_state:
        hp = blacksmith_turret_state.get("hp", BLACKSMITH_TURRET_BASE_HP)
        max_hp = max(1, blacksmith_turret_state.get("max_hp", BLACKSMITH_TURRET_BASE_HP))
        hp_ratio = max(0.0, min(1.0, hp / max_hp))
        hp_fill_rect = pygame.Rect(bar_rect.x, bar_rect.y, int(bar_rect.width * hp_ratio), bar_rect.height)
        pygame.draw.rect(surface, (108, 198, 128), hp_fill_rect, border_radius=3)
        pygame.draw.rect(surface, (90, 100, 110), bar_rect, 1, border_radius=3)
        status_text = FontStyle.tiny().render(f"HP {hp}/{max_hp}", True, (220, 230, 235))

        xp = blacksmith_turret_state.get("xp", 0.0)
        xp_max = max(1.0, blacksmith_turret_state.get("xp_max", float(BLACKSMITH_TURRET_XP_REQUIRED)))
        xp_ratio = max(0.0, min(1.0, xp / xp_max))
        pygame.draw.rect(surface, (35, 35, 45), xp_rect.inflate(4, 4), border_radius=3)
        xp_fill_rect = pygame.Rect(xp_rect.x, xp_rect.y, int(xp_rect.width * xp_ratio), xp_rect.height)
        base_fill_color = (242, 188, 96)
        if overheat_active:
            base_fill_color = (180, 120, 110)
        elif overdrive_display:
            base_fill_color = (255, 120, 70) if not ui_divine else (120, 220, 255)

        if turret_level is None:
            turret_level = int(blacksmith_turret_state.get("level", BLACKSMITH_TURRET_BASE_LEVEL))
        # 레벨 1에서는 '강화 진행도'를 강조하기 위해 색상을 차별화
        if turret_level < BLACKSMITH_TURRET_MAX_LEVEL and not overheat_active and not overdrive_display:
            base_fill_color = (120, 210, 255)

        pygame.draw.rect(surface, base_fill_color, xp_fill_rect, border_radius=3)
        pygame.draw.rect(surface, (120, 96, 64), xp_rect, 1, border_radius=3)

        if turret_level < BLACKSMITH_TURRET_MAX_LEVEL and not overheat_active and not overdrive_display:
            # 강화 게이지 표시 (레벨 1 전용)
            xp_text = FontStyle.tiny().render(_t("ui.enhance_pct", "강화 {}%").format(int(xp_ratio * 100)), True, (250, 240, 210))

            # 디바인스톤 강화 게이지 표시
            if blacksmith_divine_stone_state is not None:
                divine_xp = float(blacksmith_divine_stone_state.get("xp", 0.0))
                divine_xp_max = max(1.0, float(blacksmith_divine_stone_state.get("xp_max", 400.0)))
                if divine_xp_max > 0 and not blacksmith_divine_stone_state.get("reinforced", False):
                    divine_ratio = max(0.0, min(1.0, divine_xp / divine_xp_max))
                    divine_text = FontStyle.tiny().render(
                        f"강화 {int(divine_ratio * 100)}%",
                        True,
                        (230, 180, 190),
                    )
                    divine_surface = pygame.display.get_surface()
                    if divine_surface is not None:
                        stone_rect = blacksmith_divine_stone_state.get("rect")
                        if stone_rect is not None:
                            text_rect = divine_text.get_rect()
                            text_rect.midbottom = (stone_rect.centerx, stone_rect.top - 4)
                            divine_surface.blit(divine_text, text_rect)
        elif overheat_active:
            remaining_seconds = overheat_timer / FPS if FPS else overheat_timer
            xp_text = FontStyle.tiny().render(
                f"⚠ 과부하 {remaining_seconds:4.1f}s",
                True,
                (255, 220, 200),
            )
            overlay = pygame.Surface(xp_rect.size, pygame.SRCALPHA)
            pygame.draw.rect(overlay, (180, 110, 90, 120), overlay.get_rect(), border_radius=3)
            surface.blit(overlay, xp_rect.topleft, special_flags=pygame.BLEND_ADD)
        elif overdrive_display:
            overlay = pygame.Surface(xp_rect.size, pygame.SRCALPHA)
            glow_alpha = int(120 + 100 * overdrive_ui_pulse)
            if ui_divine:
                xp_text = FontStyle.tiny().render(_t("ui.megadrive", "💥 메가드라이브"), True, (225, 245, 255))
                pygame.draw.rect(overlay, (110, 210, 255, glow_alpha), overlay.get_rect(), border_radius=3)
            else:
                xp_text = FontStyle.tiny().render(_t("ui.overdrive", "🔥 오버드라이브"), True, (255, 234, 220))
                pygame.draw.rect(overlay, (255, 80, 48, glow_alpha), overlay.get_rect(), border_radius=3)
            surface.blit(overlay, xp_rect.topleft, special_flags=pygame.BLEND_ADD)
        else:
            # 준비완료: 포탑 앞에서 SPACE 입력으로 점화 (레벨 2 이상 전용)
            if xp_ratio >= 1.0 and not overheat_active and not blacksmith_turret_state.get("overdrive_active", False):
                ready_divine = is_blacksmith_divine_stone_active()
                label = "메가드라이브 준비 · SPACE" if ready_divine else "오버드라이브 준비 · SPACE"
                xp_text = FontStyle.tiny().render(label, True, (225, 245, 255) if ready_divine else (255, 234, 220))
                # 은은한 강조 배경
                overlay = pygame.Surface(xp_rect.size, pygame.SRCALPHA)
                glow_alpha = 90
                color = (110, 210, 255, glow_alpha) if ready_divine else (255, 120, 70, glow_alpha)
                pygame.draw.rect(overlay, color, overlay.get_rect(), border_radius=3)
                surface.blit(overlay, xp_rect.topleft, special_flags=pygame.BLEND_ADD)
                # 키캡 힌트는 월드 상 포탑 좌상단에 별도 표시(중복 방지)
            else:
                xp_text = FontStyle.tiny().render(_t("ui.gauge_pct", "게이지 {}%").format(int(xp_ratio * 100)), True, (250, 240, 210))

    if status_text:
        status_rect = status_text.get_rect(center=bar_rect.center)
        surface.blit(status_text, status_rect)

    if xp_text:
        xp_rect_center = xp_rect.center
        surface.blit(xp_text, xp_text.get_rect(center=xp_rect_center))

