ball_display_level: float = 0.0  # 현재 표시 레벨 (부드러운 전환용)
INTENSITY_TRANSITION_SPEED: float = 0.033  # 0.5초에 1레벨 전환 (60fps 기준: 1/30)

# 인텐시티 레벨별 색상 (저강도 → 고강도)
INTENSITY_COLORS = {
    0: [(100, 180, 255), (80, 160, 255), (60, 140, 255)],  # 파란색 (기본)
    1: [(180, 220, 100), (160, 200, 80), (140, 180, 60)],  # 연두색 (약간 빠름)
    2: [(255, 220, 100), (255, 200, 80), (255, 180, 60)],  # 노란색 (빠름)
    3: [(255, 160, 80), (255, 140, 60), (255, 120, 40)],   # 주황색 (매우 빠름)
    4: [(255, 100, 80), (255, 80, 60), (255, 60, 40)],     # 빨간색 (위험)
    5: [(255, 80, 150), (255, 60, 130), (255, 40, 110)],   # 핑크/마젠타 (극한)
}

# 인텐시티별 글로우 색상 (배경 글로우)
INTENSITY_GLOW_COLORS = {
    0: (60, 100, 180, 30),    # 파란색 글로우
    1: (100, 150, 50, 40),    # 연두 글로우
    2: (180, 150, 30, 50),    # 노란 글로우
    3: (200, 100, 30, 60),    # 주황 글로우
    4: (200, 50, 30, 70),     # 빨간 글로우
    5: (200, 40, 100, 80),    # 핑크 글로우
}

# 인텐시티 속도 임계값
INTENSITY_SPEED_THRESHOLDS = [8, 12, 16, 22, 28, 35]  # 각 레벨로 올라가는 속도 기준

def calculate_ball_intensity() -> float:
    """공의 현재 속도와 랠리 카운트를 기반으로 인텐시티 계산"""
    global ball_intensity_level

    # 현재 공 속도 계산
    current_speed = math.hypot(ball_vel[0], ball_vel[1])

    # 속도 기반 레벨 (0~5)
    speed_level = 0
    for i, threshold in enumerate(INTENSITY_SPEED_THRESHOLDS):
        if current_speed >= threshold:
            speed_level = i

    # 랠리 카운트 보너스 (랠리가 높을수록 인텐시티 증가)
    rally_bonus = min(ball_rally_count * 0.1, 0.5)  # 최대 0.5 보너스

    # 최종 인텐시티 레벨 (0.0 ~ 1.0)
    base_intensity = speed_level / 5.0
    ball_intensity_level = min(1.0, base_intensity + rally_bonus)

    return ball_intensity_level

def lerp_color(color1: tuple, color2: tuple, t: float) -> tuple:
    """두 색상 사이를 선형 보간"""
    t = max(0.0, min(1.0, t))
    return tuple(int(color1[i] + (color2[i] - color1[i]) * t) for i in range(len(color1)))

def lerp_color_list(colors1: list, colors2: list, t: float) -> list:
    """색상 리스트 사이를 선형 보간"""
    return [lerp_color(colors1[i], colors2[i], t) for i in range(min(len(colors1), len(colors2)))]

def update_intensity_transition() -> None:
    """인텐시티 색상/레벨 점진적 전환 업데이트 (매 프레임 호출)"""
    global ball_display_level, ball_target_level, ball_current_display_colors, ball_current_glow_color

    # 목표 레벨 계산
    intensity = calculate_ball_intensity()
    ball_target_level = min(5, int(intensity * 5))

    # 현재 표시 레벨을 목표 레벨 방향으로 점진적 전환
    if ball_display_level < ball_target_level:
        ball_display_level = min(ball_target_level, ball_display_level + INTENSITY_TRANSITION_SPEED)
    elif ball_display_level > ball_target_level:
        ball_display_level = max(ball_target_level, ball_display_level - INTENSITY_TRANSITION_SPEED)

    # 현재 레벨과 다음 레벨 사이 보간
    current_level = int(ball_display_level)
    next_level = min(5, current_level + 1)
    blend_factor = ball_display_level - current_level  # 0.0 ~ 1.0

    # 색상 보간
    current_colors = INTENSITY_COLORS.get(current_level, INTENSITY_COLORS[0])
    next_colors = INTENSITY_COLORS.get(next_level, INTENSITY_COLORS[0])
    ball_current_display_colors = lerp_color_list(current_colors, next_colors, blend_factor)

    # 글로우 색상 보간
    current_glow = INTENSITY_GLOW_COLORS.get(current_level, INTENSITY_GLOW_COLORS[0])
    next_glow = INTENSITY_GLOW_COLORS.get(next_level, INTENSITY_GLOW_COLORS[0])
    ball_current_glow_color = lerp_color(current_glow, next_glow, blend_factor)

def get_intensity_colors() -> tuple:
    """현재 인텐시티에 맞는 색상들 반환 (점진적 전환 적용)"""
    return ball_current_display_colors

def get_intensity_glow_color() -> tuple:
    """현재 인텐시티에 맞는 글로우 색상 반환 (점진적 전환 적용)"""
    return ball_current_glow_color

def get_display_intensity_level() -> int:
    """현재 표시되는 인텐시티 레벨 반환 (점진적 전환 적용)"""
    return int(ball_display_level)

# === 🏓 인텐시티 기반 패들 충돌 넉백 시스템 ===
# 화재 넉백의 20%를 기본 넉백으로 사용, 인텐시티 레벨에 따라 증가
# 기본: 화재 넉백 12의 20% = 2.4
# 레벨 1-2: +30% → 3.12
# 레벨 3-4: +50% → 3.6
# 레벨 5: +70% → 4.08
PADDLE_HIT_KNOCKBACK_BASE = 2.4  # 화재 넉백(12)의 20%
PADDLE_HIT_KNOCKBACK_INTENSITY_SCALE = {
    0: 1.5,   # 기본 (파란색) - 150%
    1: 2.2,   # 레벨 1 (청록) - 220%
    2: 2.2,   # 레벨 2 (녹색) - 220%
    3: 3.8,   # 레벨 3 (노랑) - 380%
    4: 3.8,   # 레벨 4 (주황) - 380%
    5: 5.5,   # 레벨 5 (빨강) - 550%
}

def get_paddle_hit_knockback_strength() -> float:
    """패들 충돌 시 인텐시티 기반 넉백 강도 반환

    Returns:
        넉백 강도 (화재 넉백 방식과 동일한 스케일)
    """
    intensity_level = get_display_intensity_level()
    scale = PADDLE_HIT_KNOCKBACK_INTENSITY_SCALE.get(intensity_level, 1.0)
    knockback = PADDLE_HIT_KNOCKBACK_BASE * scale
    return knockback

def apply_paddle_hit_knockback_player(ball_x: float = None) -> None:
    """플레이어 패들 충돌 시 넉백 적용 (공 위치 기반 방향 결정)

    화재 이벤트가 활성화되어 있으면 화재 넉백이 이미 처리되므로 이 함수는 호출하지 않음

    Args:
        ball_x: 공의 x 좌표 (None이면 랜덤 방향)
    """
    global player_fire_knockback_vel
    # 바이퍼 쉐도우 백스텝 홀로그램 활성 중에는 넉백 무시 (텔레포트 직후 밀려남 방지)
    if _viper_ss_hologram_active:
        return

    knockback_strength = get_paddle_hit_knockback_strength()

    # 공 위치 기반 넉백 방향 결정
    # 패들 중심 오른쪽에 공이 맞으면 왼쪽으로, 왼쪽에 맞으면 오른쪽으로
    if ball_x is not None:
        paddle_center = PLAYER.centerx
        if ball_x > paddle_center:
            knockback_dir = -1  # 공이 오른쪽에 맞음 → 왼쪽으로 넉백
        else:
            knockback_dir = 1   # 공이 왼쪽에 맞음 → 오른쪽으로 넉백
    else:
        knockback_dir = random.choice([-1, 1])

    raw_knockback = knockback_dir * knockback_strength
    player_fire_knockback_vel = apply_knockback_resist(_scale_knockback(raw_knockback))

    intensity_level = get_display_intensity_level()
    # if abs(player_fire_knockback_vel) > 0.5:
    #     print(f"🏓 [PADDLE HIT] 플레이어 넉백! 인텐시티 레벨={intensity_level}, 강도={knockback_strength:.2f}, vel={player_fire_knockback_vel:.2f}, 방향={'←' if knockback_dir < 0 else '→'}")  # 디버그 비활성화

def apply_paddle_hit_knockback_boss(ball_x: float = None) -> None:
    """보스 패들 충돌 시 넉백 적용 (공 위치 기반 방향 결정)

    화재 이벤트가 활성화되어 있으면 화재 넉백이 이미 처리되므로 이 함수는 호출하지 않음

    Args:
        ball_x: 공의 x 좌표 (None이면 랜덤 방향)
    """
    global boss_fire_knockback_vel

    knockback_strength = get_paddle_hit_knockback_strength()

    # 공 위치 기반 넉백 방향 결정
    # 패들 중심 오른쪽에 공이 맞으면 왼쪽으로, 왼쪽에 맞으면 오른쪽으로
    if ball_x is not None:
        paddle_center = BOSS.centerx
        if ball_x > paddle_center:
            knockback_dir = -1  # 공이 오른쪽에 맞음 → 왼쪽으로 넉백
        else:
            knockback_dir = 1   # 공이 왼쪽에 맞음 → 오른쪽으로 넉백
    else:
        knockback_dir = random.choice([-1, 1])

    raw_knockback = knockback_dir * knockback_strength
    boss_fire_knockback_vel = _scale_knockback(raw_knockback)

    intensity_level = get_display_intensity_level()
    # if abs(boss_fire_knockback_vel) > 0.5:
    #     print(f"🏓 [PADDLE HIT] 보스 넉백! 인텐시티 레벨={intensity_level}, 강도={knockback_strength:.2f}, vel={boss_fire_knockback_vel:.2f}, 방향={'←' if knockback_dir < 0 else '→'}")  # 디버그 비활성화

def update_ball_rally(hit_by: str) -> None:
    """공이 맞았을 때 랠리 카운트 업데이트

    Args:
        hit_by: "player" 또는 "boss"
    """
    global ball_rally_count, ball_last_hit_by

    # 다른 쪽에서 받아쳤을 때만 랠리 증가
    if ball_last_hit_by != "" and ball_last_hit_by != hit_by:
        ball_rally_count += 1

    ball_last_hit_by = hit_by

def reset_ball_rally() -> None:
    """랠리 카운트 초기화 (득점 시)"""
    global ball_rally_count, ball_last_hit_by, ball_intensity_level, ball_display_level
    global ball_current_display_colors, ball_current_glow_color, ball_intensity_trail, ball_intensity_particles
    ball_rally_count = 0
    ball_last_hit_by = ""
    ball_intensity_level = 0.0
    ball_display_level = 0.0  # 표시 레벨도 초기화
    ball_current_display_colors = INTENSITY_COLORS[0].copy()  # 파란색으로 초기화
    ball_current_glow_color = INTENSITY_GLOW_COLORS[0]
    ball_intensity_trail = []  # 궤적 클리어
    ball_intensity_particles = []  # 파티클 클리어

def update_intensity_particles(ball_x: float, ball_y: float) -> None:
    """인텐시티 파티클 업데이트 및 생성"""
    global ball_intensity_particles, ball_intensity_trail

    intensity = calculate_ball_intensity()
    current_speed = math.hypot(ball_vel[0], ball_vel[1])

    # 인텐시티가 낮으면 파티클 최소화
    if intensity < 0.1:
        # 기존 파티클만 업데이트
        new_particles = []
        for p in ball_intensity_particles:
            p['life'] -= 1
            p['x'] += p['vx']
            p['y'] += p['vy']
            p['vy'] += 0.1  # 중력
            p['size'] *= 0.95
            if p['life'] > 0:
                new_particles.append(p)
        ball_intensity_particles = new_particles
        return

    colors = get_intensity_colors()
    level = min(5, int(intensity * 5))

    # 화염 파티클 생성 (고속에서는 파티클 수 감소)
    # intensity 0.0~0.5: 기존처럼 증가, 0.5 이상: 점점 감소
    if intensity <= 0.5:
        particle_count = int(1 + intensity * 4)  # 1~3개
    else:
        # 고속에서 파티클 수 감소 (intensity 0.5일때 3개 → 1.0일때 1개)
        particle_count = max(1, int(3 - (intensity - 0.5) * 4))  # 3~1개

    # 고속에서 생성 확률도 감소
    spawn_chance = 0.3 + intensity * 0.3 if intensity <= 0.5 else 0.45 - (intensity - 0.5) * 0.3
    for _ in range(particle_count):
        if random.random() < spawn_chance:  # 30%~45%~15%
            # 공 이동 반대 방향으로 파티클 생성
            angle = math.atan2(-ball_vel[1], -ball_vel[0]) + random.uniform(-0.5, 0.5)
            speed = random.uniform(1, 3) * (1 + intensity)

            ball_intensity_particles.append({
                'x': ball_x + random.uniform(-5, 5),
                'y': ball_y + random.uniform(-5, 5),
                'vx': math.cos(angle) * speed + random.uniform(-0.5, 0.5),
                'vy': math.sin(angle) * speed + random.uniform(-0.5, 0.5),
                'size': random.uniform(3, 8) * (0.5 + intensity * 0.5),
                'life': int(15 + intensity * 25),
                'max_life': int(15 + intensity * 25),
                'color': random.choice(colors),
                'type': 'flame' if random.random() < 0.7 else 'spark'
            })

    # 궤적 포인트 추가 (화염 꼬리) - 포인트 간격을 넓혀서 끊어지는 느낌
    min_distance = 12 + intensity * 8  # 12~20 픽셀 간격 (더 넓게)
    if len(ball_intensity_trail) == 0 or \
       math.hypot(ball_x - ball_intensity_trail[-1]['x'],
                  ball_y - ball_intensity_trail[-1]['y']) > min_distance:
        trail_length = int(6 + intensity * 10)  # 6~16개 (줄임)
        ball_intensity_trail.append({
            'x': ball_x + random.uniform(-2, 2),  # 약간의 랜덤 오프셋
            'y': ball_y + random.uniform(-2, 2),
            'alpha': 200 + random.randint(0, 55),  # 약간의 랜덤 알파
            'size': 6 + intensity * 8 + random.uniform(-1, 1),  # 6~14 + 랜덤
            'color': colors[0]
        })
        while len(ball_intensity_trail) > trail_length:
            ball_intensity_trail.pop(0)

    # 궤적 페이드 및 크기 감소 (더 빠르게 사라짐)
    for i, point in enumerate(ball_intensity_trail):
        # 빠르게 페이드
        fade_speed = 0.75 + intensity * 0.1  # 0.75~0.85 (더 빠르게)
        point['alpha'] *= fade_speed
        point['size'] *= 0.92  # 크기도 더 빠르게 감소

    ball_intensity_trail = [p for p in ball_intensity_trail if p['alpha'] > 10]

    # 파티클 업데이트
    new_particles = []
    for p in ball_intensity_particles:
        p['life'] -= 1
        p['x'] += p['vx']
        p['y'] += p['vy']

        if p['type'] == 'flame':
            p['vy'] -= 0.15  # 화염은 위로 올라감
            p['size'] *= 0.96
        else:
            p['vy'] += 0.05  # 스파크는 약간 아래로
            p['size'] *= 0.93

        if p['life'] > 0 and p['size'] > 0.5:
            new_particles.append(p)

    ball_intensity_particles = new_particles

    # 파티클 수 제한 (고속에서는 더 적게 유지)
    # intensity 0.0: 최대 150개, intensity 1.0: 최대 60개
    max_particles = int(150 - intensity * 90) if intensity > 0.5 else 150
    if len(ball_intensity_particles) > max_particles:
        ball_intensity_particles = ball_intensity_particles[-max_particles:]

def draw_intensity_effects(surface: pygame.Surface, ball_x: int, ball_y: int, ball_radius: int) -> None:
    """인텐시티 기반 화염/글로우 이펙트 그리기"""
    global ball_intensity_particles, ball_intensity_trail

    # 점진적 전환 업데이트 (매 프레임)
    update_intensity_transition()

    intensity = calculate_ball_intensity()

    # 인텐시티가 낮으면 그리지 않음
    if intensity < 0.05:
        return

    # 점진적 전환 레벨 사용
    level = get_display_intensity_level()
    colors = get_intensity_colors()
    glow_color = get_intensity_glow_color()

    # === 1. 화염 궤적 그리기 (공 뒤의 불꽃 꼬리) ===
    if ball_intensity_trail:
        total_points = len(ball_intensity_trail)
        for i, point in enumerate(ball_intensity_trail):
            if point['alpha'] < 5:
                continue

            # 위치 비율에 따른 색상 보간
            position_ratio = i / max(1, total_points - 1)

            # 인텐시티에 따른 크기 조절
            size = int(point['size'] * (0.3 + position_ratio * 0.7))
            if size < 1:
                continue

            # 색상 선택 (뒤로 갈수록 진한 색)
            color_idx = min(2, int((1 - position_ratio) * 3))
            base_color = colors[color_idx]

            # 서피스 생성
            trail_surf = pygame.Surface((size * 2, size * 2), pygame.SRCALPHA)
            alpha = int(point['alpha'] * (0.5 + intensity * 0.5))

            # 외곽 글로우
            if size > 3:
                pygame.draw.circle(trail_surf, (*base_color, alpha // 3),
                                 (size, size), size)

            # 내부 밝은 부분
            inner_size = max(1, int(size * 0.6))
            inner_color = tuple(min(255, c + 50) for c in base_color)
            pygame.draw.circle(trail_surf, (*inner_color, alpha),
                             (size, size), inner_size)

            surface.blit(trail_surf,
                        (int(point['x']) - size, int(point['y']) - size),
                        special_flags=pygame.BLEND_ADD)

    # === 2. 파티클 그리기 ===
    for p in ball_intensity_particles:
        if p['life'] <= 0 or p['size'] < 0.5:
            continue

        life_ratio = p['life'] / p['max_life']
        alpha = int(255 * life_ratio * (0.5 + intensity * 0.5))
        size = max(1, int(p['size']))

        if alpha < 5:
            continue

        particle_surf = pygame.Surface((size * 2, size * 2), pygame.SRCALPHA)

        if p['type'] == 'flame':
            # 화염 파티클 (부드러운 글로우)
            pygame.draw.circle(particle_surf, (*p['color'], alpha // 2),
                             (size, size), size)
            inner_size = max(1, size // 2)
            inner_color = tuple(min(255, c + 80) for c in p['color'])
            pygame.draw.circle(particle_surf, (*inner_color, alpha),
                             (size, size), inner_size)
        else:
            # 스파크 파티클 (밝은 점)
            pygame.draw.circle(particle_surf, (255, 255, 200, alpha),
                             (size, size), size)

        surface.blit(particle_surf,
                    (int(p['x']) - size, int(p['y']) - size),
                    special_flags=pygame.BLEND_ADD)

    # === 3. 공 주위 글로우/아우라 (공 크기와 비슷하게 유지) ===
    if intensity > 0.2:
        # 글로우 크기 (공 크기와 비슷하게 - 최대 1.3배)
        glow_size = int(ball_radius * (1.0 + intensity * 0.3))  # 1.0x ~ 1.3x (더 작게)
        glow_surf = pygame.Surface((glow_size * 2 + 4, glow_size * 2 + 4), pygame.SRCALPHA)
        center = glow_size + 2

        # 부드러운 글로우 (알파값 낮게)
        glow_alpha = int(glow_color[3] * 0.5 * intensity)  # 알파값 절반으로
        if glow_alpha > 5:
            pygame.draw.circle(glow_surf,
                             (glow_color[0], glow_color[1], glow_color[2], glow_alpha),
                             (center, center), glow_size)

        surface.blit(glow_surf,
                    (ball_x - center, ball_y - center),
                    special_flags=pygame.BLEND_ADD)

# ⚡ 에너지 폭발 이펙트 변수 (패들 충돌 시)
energy_explosion_particles: list = []  # 에너지 폭발 파티클들
ENERGY_EXPLOSION_COLORS = [
    (150, 200, 255),  # 밝은 하늘색
    (100, 180, 255),  # 파란색
    (80, 160, 255),   # 진한 파란색
    (200, 230, 255),  # 밝은 흰색/파랑
    (120, 200, 255),  # 청록색
]

def create_energy_explosion(x: int, y: int, scale: float = 1.0) -> None:
    """⚡ 에너지 폭발 파티클 생성 - 패들에 공이 닿을 때 호출

    Args:
        x, y: 폭발 위치
        scale: 크기 배율 (기본 1.0, 플레이어 패들은 0.6)
    """
    global energy_explosion_particles

    # 인텐시티에 따른 파티클 수 조절 (고속에서는 감소)
    intensity = calculate_ball_intensity()
    # intensity 0.0~0.5: 기존처럼 증가, 0.5 이상: 점점 감소
    if intensity <= 0.5:
        intensity_multiplier = 0.5 + intensity * 1.0  # 0.5 ~ 1.0 배율
    else:
        # 고속에서 파티클 수 감소 (intensity 0.5: 1.0배 → 1.0: 0.5배)
        intensity_multiplier = 1.0 - (intensity - 0.5) * 1.0  # 1.0 ~ 0.5 배율

    # 파티클 수도 스케일과 인텐시티에 비례
    explosion_count = int(25 * scale * intensity_multiplier)
    spark_count = int(15 * scale * intensity_multiplier)

    # 폭발 색상은 항상 기본 파란색 사용 (인텐시티와 무관)
    explosion_colors = ENERGY_EXPLOSION_COLORS

    # 인텐시티에 따른 속도 증가 (기본 1.0 ~ 최대 1.3)
    speed_multiplier = 1.0 + intensity * 0.3

    # 폭발 파티클 생성 (더 크고 밝게)
    for _ in range(explosion_count):
        angle = random.uniform(0, math.pi * 2)
        speed = random.uniform(4, 12) * scale * speed_multiplier
        energy_explosion_particles.append({
            "x": x,
            "y": y,
            "vx": math.cos(angle) * speed,
            "vy": math.sin(angle) * speed,
            "size": random.uniform(4, 10) * scale,
            "lifetime": 0,
            "max_lifetime": int(random.randint(20, 35) * scale),
            "alpha": 1.0,
            "color": random.choice(explosion_colors),
            "type": "explosion"
        })

    # 에너지 스파크 (밝은 입자들) - 항상 기본 파란색/흰색 계열 사용
    spark_color = (200, 230, 255)  # 밝은 하늘색
    for _ in range(spark_count):
        angle = random.uniform(0, math.pi * 2)
        speed = random.uniform(6, 14) * scale * speed_multiplier
        energy_explosion_particles.append({
            "x": x,
            "y": y,
            "vx": math.cos(angle) * speed,
            "vy": math.sin(angle) * speed - 2 * scale,  # 약간 위로
            "size": random.uniform(2, 4) * scale,
            "lifetime": 0,
            "max_lifetime": int(random.randint(15, 25) * scale),
            "alpha": 1.0,
            "color": spark_color,
            "type": "spark"
        })


def update_energy_explosion_particles() -> None:
    """에너지 폭발 파티클 업데이트"""
    global energy_explosion_particles
    
    updated = []
    for p in energy_explosion_particles:
        p["lifetime"] += 1
        p["x"] += p["vx"]
        p["y"] += p["vy"]
        
        # 중력 효과 (스파크는 더 빨리 떨어짐)
        if p["type"] == "spark":
            p["vy"] += 0.3
        else:
            p["vy"] += 0.15
        
        # 감속
        p["vx"] *= 0.94
        p["vy"] *= 0.94
        
        # 크기 감소
        p["size"] *= 0.95
        
        # 알파 감소
        lifetime_ratio = p["lifetime"] / p["max_lifetime"]
        p["alpha"] = 1.0 - lifetime_ratio
        
        # 수명 종료 또는 너무 작아지면 제거
        if p["lifetime"] < p["max_lifetime"] and p["size"] >= 0.3:
            updated.append(p)
    
    energy_explosion_particles = updated


def draw_energy_explosion_particles(screen: pygame.Surface) -> None:
    """에너지 폭발 파티클 그리기"""
    for p in energy_explosion_particles:
        size = int(p["size"])
        if size < 1:
            continue
        
        alpha = int(255 * p["alpha"])
        if alpha < 10:
            continue
        
        r, g, b = p["color"]
        x, y = int(p["x"]), int(p["y"])
        
        # 글로우 효과
        surf = pygame.Surface((size * 4, size * 4), pygame.SRCALPHA)
        center = size * 2
        
        # 외부 글로우 (더 밝게)
        glow_alpha = alpha // 2
        pygame.draw.circle(surf, (r, g, b, glow_alpha), (center, center), size * 2)
        
        # 코어 (더 밝게)
        core_alpha = min(alpha, 230)
        pygame.draw.circle(surf, (r, g, b, core_alpha), (center, center), size)
        
        # 밝은 중심 (스파크만)
        if p["type"] == "spark" and size > 1:
            inner_alpha = min(200, int(alpha * 0.8))
            pygame.draw.circle(surf, (220, 240, 255, inner_alpha), (center, center), max(1, size // 2))
        
        screen.blit(surf, (x - center, y - center))


def spawn_wall_impact_effect(x: int, y: int, direction: str = 'left') -> None:
    """벽 충돌 시 이펙트 생성"""
    global wall_impact_particles, wall_impact_flash_timer, wall_impact_position

    wall_impact_flash_timer = 8  # 플래시 지속 프레임
    wall_impact_position = (x, y)

    # 파티클 방향 설정
    dir_mult = 1 if direction == 'left' else -1

    # 작은 에너지 파티클 생성
    for _ in range(6):
        angle = random.uniform(-0.8, 0.8)  # 벽에서 튕겨나가는 방향
        speed = random.uniform(2, 5)
        wall_impact_particles.append({
            'x': x,
            'y': y,
            'vx': math.cos(angle) * speed * dir_mult,
            'vy': math.sin(angle) * speed + random.uniform(-1, 1),
            'life': random.randint(12, 20),
            'max_life': 20,
            'size': random.uniform(2, 4),
            'color': random.choice([
                (150, 200, 255),
                (180, 220, 255),
                (120, 180, 240)
            ])
        })

def update_wall_impact_effects() -> None:
    """벽 충돌 이펙트 업데이트"""
    global wall_impact_particles, wall_impact_flash_timer

    if wall_impact_flash_timer > 0:
        wall_impact_flash_timer -= 1

    # 파티클 업데이트
    updated = []
    for p in wall_impact_particles:
        p['x'] += p['vx']
        p['y'] += p['vy']
        p['vx'] *= 0.92
        p['vy'] *= 0.92
        p['life'] -= 1
        p['size'] *= 0.95
        if p['life'] > 0 and p['size'] > 0.5:
            updated.append(p)
    wall_impact_particles = updated

def draw_wall_impact_effects(surface: pygame.Surface) -> None:
    """벽 충돌 이펙트 렌더링"""
    global wall_impact_particles, wall_impact_flash_timer, wall_impact_position

    # 충돌 플래시 (은은하게) - 캐시된 Surface 사용
    if wall_impact_flash_timer > 0:
        flash_alpha = int(25 * (wall_impact_flash_timer / 8))
        flash_size = 25 + (8 - wall_impact_flash_timer) * 3
        flash_surf = get_wall_impact_surface(flash_size, (180, 220, 255), flash_alpha)
        center = flash_surf.get_width() // 2
        surface.blit(flash_surf,
                    (wall_impact_position[0] - center, wall_impact_position[1] - center),
                    special_flags=pygame.BLEND_ADD)

    # 파티클 렌더링 - 캐시된 Surface 사용
    for p in wall_impact_particles:
        alpha = int(180 * (p['life'] / p['max_life']))
        if alpha > 0 and p['size'] > 0.5:
            size = int(p['size'])
            if size > 0:
                p_surf = get_wall_impact_surface(size, p['color'], alpha)
                center = p_surf.get_width() // 2
                surface.blit(p_surf, (int(p['x']) - center, int(p['y']) - center),
                            special_flags=pygame.BLEND_ADD)

def update_rainbow_ball_trail(ball_cx: int, ball_cy: int) -> None:
    """에너지 궤적 트레일 업데이트 (매 프레임 호출)"""
    global rainbow_ball_trail, rainbow_trail_hue_offset

    rainbow_trail_hue_offset = (rainbow_trail_hue_offset + 2) % 360

    # 새 포인트 추가 (최소 거리 체크)
    add_new_point = True
    if rainbow_ball_trail:
        last_point = rainbow_ball_trail[-1]
        dx = ball_cx - last_point['x']
        dy = ball_cy - last_point['y']
        if dx * dx + dy * dy < RAINBOW_TRAIL_MIN_DISTANCE * RAINBOW_TRAIL_MIN_DISTANCE:
            add_new_point = False

    if add_new_point:
        rainbow_ball_trail.append({
            'x': ball_cx,
            'y': ball_cy,
            'alpha': 35,  # 초기 알파값
            'size': 12,  # 초기 크기
            'age': 0
        })

    # 트레일 길이 제한
    while len(rainbow_ball_trail) > RAINBOW_TRAIL_MAX_LENGTH:
        rainbow_ball_trail.pop(0)

    # 기존 포인트들 페이드 및 나이 처리
    for point in rainbow_ball_trail:
        point['alpha'] *= RAINBOW_TRAIL_FADE_SPEED
        point['size'] *= 0.93
        point['age'] += 1

    # 투명해진 포인트 제거
    rainbow_ball_trail = [p for p in rainbow_ball_trail if p['alpha'] > 2]

    # 벽 충돌 이펙트 업데이트
    update_wall_impact_effects()


def draw_rainbow_ball_trail(surface: pygame.Surface) -> None:
    """에너지 궤적 트레일 렌더링 - 고퀄리티 그라데이션"""
    global rainbow_ball_trail

    if not rainbow_ball_trail or len(rainbow_ball_trail) < 2:
        return

    total_points = len(rainbow_ball_trail)

    # 궤적을 선으로 연결 (부드러운 꼬리 효과)
    if total_points >= 2:
        for i in range(total_points - 1):
            p1 = rainbow_ball_trail[i]
            p2 = rainbow_ball_trail[i + 1]

            # 위치 비율에 따른 투명도
            ratio1 = i / max(1, total_points - 1)
            ratio2 = (i + 1) / max(1, total_points - 1)

            alpha1 = int(p1['alpha'] * (ratio1 ** 0.5) * 0.3)
            alpha2 = int(p2['alpha'] * (ratio2 ** 0.5) * 0.3)
            avg_alpha = (alpha1 + alpha2) // 2

            if avg_alpha > 1:
                # 선 두께 (끝으로 갈수록 가늘게)
                thickness = max(1, int((p1['size'] + p2['size']) / 4 * ratio2))

                line_color = (*ENERGY_TRAIL_BASE_COLOR, avg_alpha)

                # 글로우 라인
                if thickness > 1:
                    line_surf = pygame.Surface((abs(int(p2['x'] - p1['x'])) + thickness * 4,
                                               abs(int(p2['y'] - p1['y'])) + thickness * 4), pygame.SRCALPHA)
                    offset_x = min(int(p1['x']), int(p2['x'])) - thickness * 2
                    offset_y = min(int(p1['y']), int(p2['y'])) - thickness * 2

                    pygame.draw.line(line_surf, (*ENERGY_TRAIL_GLOW_COLOR, avg_alpha // 2),
                                    (int(p1['x']) - offset_x, int(p1['y']) - offset_y),
                                    (int(p2['x']) - offset_x, int(p2['y']) - offset_y),
                                    thickness + 2)
                    pygame.draw.line(line_surf, line_color,
                                    (int(p1['x']) - offset_x, int(p1['y']) - offset_y),
                                    (int(p2['x']) - offset_x, int(p2['y']) - offset_y),
                                    thickness)
                    surface.blit(line_surf, (offset_x, offset_y), special_flags=pygame.BLEND_ADD)

    # 각 포인트에 작은 에너지 점
    for i, point in enumerate(rainbow_ball_trail):
        if point['alpha'] < 2 or point['size'] < 1:
            continue

        position_ratio = i / max(1, total_points - 1)
        fade_factor = position_ratio ** 0.6

        base_alpha = int(point['alpha'] * fade_factor)
        if base_alpha < 2:
            continue

        size = max(2, int(point['size'] * (0.4 + position_ratio * 0.6)))

        # 트레일 포인트 - 캐시된 Surface 사용 (매 포인트마다 생성 방지)
        glow_alpha = int(base_alpha * 0.15)
        inner_alpha = int(base_alpha * 0.25)

        if glow_alpha > 0 or inner_alpha > 0:
            trail_surface = get_trail_point_surface(
                size, glow_alpha, inner_alpha,
                ENERGY_TRAIL_GLOW_COLOR, ENERGY_TRAIL_BASE_COLOR
            )
            center = trail_surface.get_width() // 2
            surface.blit(trail_surface,
                        (int(point['x']) - center, int(point['y']) - center),
                        special_flags=pygame.BLEND_ADD)

    # 벽 충돌 이펙트 렌더링
    draw_wall_impact_effects(surface)


def draw_energy_ball(surface: pygame.Surface, cx: int, cy: int, radius: int) -> None:
    """고퀄리티 에너지볼 그리기 - 자기장처럼 회전하는 고리와 파티클이 있는 애니메이션 버전
    공 색상은 항상 기본 파란색 유지 (인텐시티와 무관)
    부스트차징 활성화 시 무지개색으로 변경"""
    global energy_ball_rotation_angle, energy_ball_pulse_phase
    global energy_ball_particles, energy_ball_ring_particles

    # 인텐시티 색상 가져오기 (파티클용)
    intensity_colors = get_intensity_colors()
    intensity_level = get_display_intensity_level()

    # 부스트차징 활성화 시 무지개색 적용
    boost_active = boost_charging_active
    if boost_active:
        # 무지개색 계산 (HSV to RGB)
        current_time = pygame.time.get_ticks()
        hue = (current_time * 0.003) % 1.0  # 빠른 무지개 색상 변화
        h = hue * 6
        c = 1.0
        x = c * (1 - abs(h % 2 - 1))
        if h < 1:
            r, g, b = c, x, 0
        elif h < 2:
            r, g, b = x, c, 0
        elif h < 3:
            r, g, b = 0, c, x
        elif h < 4:
            r, g, b = 0, x, c
        elif h < 5:
            r, g, b = x, 0, c
        else:
            r, g, b = c, 0, x

        # 무지개색 적용 (영롱한 느낌)
        rainbow_base = (int(r * 200 + 55), int(g * 200 + 55), int(b * 200 + 55))
        rainbow_bright = (int(r * 150 + 105), int(g * 150 + 105), int(b * 150 + 105))
        rainbow_core = (int(r * 100 + 155), int(g * 100 + 155), int(b * 100 + 155))

        ball_outer_color = rainbow_base
        ball_inner_color = rainbow_bright
        ball_ring_color = rainbow_base
        ball_core_color = rainbow_core
    else:
        # 공 색상은 항상 기본 파란색 사용 (인텐시티에 따라 색상 변경 안 함)
        ball_outer_color = ENERGY_BALL_OUTER_COLOR
        ball_inner_color = ENERGY_BALL_INNER_COLOR
        ball_ring_color = ENERGY_BALL_RING_COLOR
        ball_core_color = ENERGY_BALL_CORE_COLOR

    # 시간 기반 애니메이션
    current_time = pygame.time.get_ticks()
    energy_ball_rotation_angle = (current_time * 0.15) % 360  # 기본 회전
    energy_ball_pulse_phase = current_time * 0.005  # 펄스 위상

    # 각 고리별 독립적인 회전 (자기장 효과)
    # 고리 1: 빠르게 시계방향
    ring1_angle = (current_time * 0.18) % 360
    # 고리 2: 느리게 반시계방향
    ring2_angle = (360 - (current_time * 0.12) % 360)
    # 고리 3: 중간 속도로 시계방향 + 기울기 변화
    ring3_angle = (current_time * 0.15) % 360
    ring_angles = [ring1_angle, ring2_angle, ring3_angle]

    # 각 고리별 기울기도 동적으로 변화 (자기장 파동)
    ring1_tilt = 20 + math.sin(current_time * 0.002) * 10
    ring2_tilt = 45 + math.sin(current_time * 0.0015 + 1) * 12
    ring3_tilt = 70 + math.sin(current_time * 0.001 + 2) * 8
    ring_tilts = [ring1_tilt, ring2_tilt, ring3_tilt]

    # 서피스 크기 (여유있게) - 재사용 캐시로 매 프레임 할당 방지
    surf_size = radius * 6 + 20
    ball_surf = _get_reusable_surface(surf_size)
    center = surf_size // 2

    # === 펄스 효과 계산 ===
    pulse = math.sin(energy_ball_pulse_phase) * 0.12 + 1.0
    pulse2 = math.sin(energy_ball_pulse_phase * 1.5) * 0.08 + 1.0

    # === Layer 1: 외부 글로우 (추가 15% 축소) ===
    for i in range(3):
        glow_radius = int(radius * (0.795 - i * 0.11) * pulse)  # 0.935 * 0.85
        glow_alpha = int(8 - i * 2)
        if glow_alpha > 0 and glow_radius > 0:
            pygame.draw.circle(ball_surf, (*ball_outer_color, glow_alpha),
                             (center, center), glow_radius)

    # === Layer 2: 회전하는 외부 고리 (3개의 타원형 궤도 - 자기장처럼 독립 회전) ===
    for ring_idx in range(3):
        # 각 고리의 독립적인 회전 각도
        ring_rotation = ring_angles[ring_idx]
        ring_tilt = ring_tilts[ring_idx]

        # 고리 반지름 (15% 추가 축소: 1.36 * 0.85 = 1.156)
        ring_radius = radius * (1.156 + ring_idx * 0.108)

        # 고리 위의 점들 그리기
        num_points = 24
        for i in range(num_points):
            angle = math.radians(ring_rotation + i * (360 / num_points))

            # 3D 회전 효과 (타원형)
            tilt_rad = math.radians(ring_tilt)
            x_offset = math.cos(angle) * ring_radius
            y_offset = math.sin(angle) * ring_radius * math.cos(tilt_rad)
            z_depth = math.sin(angle) * math.sin(tilt_rad)

            # 뒤쪽에 있는 점은 더 어둡게
            depth_factor = (z_depth + 1) / 2

            # 점 위치
            px = center + x_offset
            py = center + y_offset

            # 점 크기와 알파 (15% 축소)
            point_size = max(1, int(1.7 + depth_factor * 1.3))
            point_alpha = int(15 + depth_factor * 35)

            # 고리 색상 (인텐시티 색상 기반)
            base_r, base_g, base_b = ball_ring_color
            r = int(min(255, base_r * 0.3 + depth_factor * base_r * 0.7 + ring_idx * 5))
            g = int(min(255, base_g * 0.3 + depth_factor * base_g * 0.7 + ring_idx * 10))
            b = int(min(255, base_b * 0.3 + depth_factor * base_b * 0.7))

            pygame.draw.circle(ball_surf, (r, g, b, point_alpha),
                             (int(px), int(py)), point_size)

    # === Layer 3: 고리 연결선 (자기장 필드라인 효과) ===
    for ring_idx in range(3):
        ring_rotation = ring_angles[ring_idx]
        ring_tilt = ring_tilts[ring_idx]
        ring_radius = radius * (1.156 + ring_idx * 0.108)

        points = []
        for i in range(36):
            angle = math.radians(ring_rotation + i * 10)
            tilt_rad = math.radians(ring_tilt)
            x_offset = math.cos(angle) * ring_radius
            y_offset = math.sin(angle) * ring_radius * math.cos(tilt_rad)
            px = center + x_offset
            py = center + y_offset
            points.append((int(px), int(py)))

        # 닫힌 다각형으로 얇은 선 그리기
        if len(points) > 2:
            for i in range(len(points)):
                start = points[i]
                end = points[(i + 1) % len(points)]
                pygame.draw.line(ball_surf, (*ball_ring_color, 10), start, end, 1)

    # === Layer 4: 내부 에너지 구체 (추가 15% 축소) ===
    # 외부 글로우 (0.425 * 0.85 = 0.361)
    outer_glow = int(radius * 0.361 * pulse2)
    pygame.draw.circle(ball_surf, (*ball_inner_color, 25),
                      (center, center), outer_glow)

    # 중간 글로우 (0.34 * 0.85 = 0.289)
    mid_glow = int(radius * 0.289 * pulse)
    # 중간 글로우 색상도 인텐시티 반영
    mid_glow_color = tuple(int(c * 0.8 + 50) for c in ball_inner_color)
    pygame.draw.circle(ball_surf, (*mid_glow_color, 40),
                      (center, center), mid_glow)

    # 내부 구체 (0.3 * 0.85 = 0.255)
    inner_sphere = int(radius * 0.255)
    # 내부 구체 색상도 인텐시티 반영
    inner_sphere_color = tuple(int(min(255, c * 0.7 + 80)) for c in ball_inner_color)
    pygame.draw.circle(ball_surf, (*inner_sphere_color, 60),
                      (center, center), inner_sphere)

    # === Layer 5: 밝은 코어 (추가 15% 축소) ===
    core_size = int(radius * 0.178)  # 0.21 * 0.85
    # 코어 외부 글로우 (인텐시티 색상 반영)
    core_glow_color = tuple(int(min(255, c * 0.5 + 128)) for c in ball_ring_color)
    pygame.draw.circle(ball_surf, (*core_glow_color, 80),
                      (center, center), core_size + 2)
    # 코어 중심
    pygame.draw.circle(ball_surf, (*ball_core_color, 150),
                      (center, center), core_size)
    # 코어 하이라이트
    pygame.draw.circle(ball_surf, (255, 255, 255, 200),
                      (center, center), max(2, core_size // 2))

    # === Layer 6: 상단 하이라이트 (추가 15% 축소) ===
    highlight_x = center - int(radius * 0.11)  # 0.13 * 0.85
    highlight_y = center - int(radius * 0.11)
    highlight_size = max(1, int(radius * 0.072))  # 0.085 * 0.85
    pygame.draw.circle(ball_surf, (255, 255, 255, 80),
                      (highlight_x, highlight_y), highlight_size)
    pygame.draw.circle(ball_surf, (255, 255, 255, 40),
                      (highlight_x - 1, highlight_y - 1), highlight_size + 1)

    # === Layer 7: 떠다니는 에너지 파티클들 (추가 15% 축소) ===
    # 공 주변 파티클은 항상 기본 파란색 사용 (인텐시티와 무관)
    particle_colors = ENERGY_BALL_PARTICLE_COLORS

    if random.random() < 0.4:
        angle = random.uniform(0, 2 * math.pi)
        dist = radius * random.uniform(0.867, 1.445)  # 1.02*0.85, 1.7*0.85
        energy_ball_particles.append({
            'x': math.cos(angle) * dist,
            'y': math.sin(angle) * dist,
            'vx': random.uniform(-0.5, 0.5),
            'vy': random.uniform(-1.5, -0.5),
            'life': random.randint(20, 40),
            'max_life': 40,
            'size': random.uniform(0.42, 1.02),  # 0.5*0.85, 1.2*0.85
            'color': random.choice(particle_colors)
        })

    # 파티클 제한
    if len(energy_ball_particles) > ENERGY_BALL_MAX_PARTICLES:
        energy_ball_particles = energy_ball_particles[-ENERGY_BALL_MAX_PARTICLES:]

    # 파티클 렌더링 및 업데이트
    new_particles = []
    for p in energy_ball_particles:
        p['x'] += p['vx']
        p['y'] += p['vy']
        p['life'] -= 1

        if p['life'] > 0:
            alpha = int(200 * (p['life'] / p['max_life']))
            size = int(p['size'] * (p['life'] / p['max_life']))

            if alpha > 0 and size > 0:
                px = int(center + p['x'])
                py = int(center + p['y'])

                if 0 < px < surf_size and 0 < py < surf_size:
                    pygame.draw.circle(ball_surf, (*p['color'][:3], alpha // 3),
                                     (px, py), size + 2)
                    pygame.draw.circle(ball_surf, (*p['color'][:3], alpha),
                                     (px, py), size)

            new_particles.append(p)

    energy_ball_particles = new_particles

    # === Layer 8: 고리 위의 밝은 점들 (자기장 노드처럼 - 추가 15% 축소) ===
    for ring_idx in range(3):
        ring_rotation = ring_angles[ring_idx]
        ring_tilt = ring_tilts[ring_idx]
        ring_radius = radius * (1.156 + ring_idx * 0.108)

        # 각 고리에 3개의 밝은 점
        for bright_idx in range(3):
            bright_angle = ring_rotation + bright_idx * 120
            angle_rad = math.radians(bright_angle)
            tilt_rad = math.radians(ring_tilt)

            x_offset = math.cos(angle_rad) * ring_radius
            y_offset = math.sin(angle_rad) * ring_radius * math.cos(tilt_rad)
            z_depth = math.sin(angle_rad) * math.sin(tilt_rad)

            # 앞쪽에 있는 점만 밝게
            if z_depth > -0.3:
                px = center + x_offset
                py = center + y_offset

                # 펄스하는 밝기 (추가 15% 축소)
                bright_pulse = (math.sin(energy_ball_pulse_phase * 2 + bright_idx) + 1) / 2
                bright_size = int(0.72 + bright_pulse * 0.85)  # 0.85*0.85, 1.0*0.85
                bright_alpha = int(40 + bright_pulse * 35)

                # 글로우
                pygame.draw.circle(ball_surf, (100, 180, 255, bright_alpha // 2),
                                 (int(px), int(py)), bright_size + 1)
                # 코어
                pygame.draw.circle(ball_surf, (150, 210, 255, bright_alpha),
                                 (int(px), int(py)), bright_size)

    # === 최종 렌더링 ===
    surface.blit(ball_surf, (cx - center, cy - center), special_flags=pygame.BLEND_ADD)


def reset_rainbow_ball_trail() -> None:
    """에너지 궤적 트레일 초기화"""
    global rainbow_ball_trail, rainbow_trail_hue_offset, wall_impact_particles, energy_wave_trail, energy_wave_phase, ball_ghost_trail
    rainbow_ball_trail = []
    rainbow_trail_hue_offset = 0
    wall_impact_particles = []
    energy_wave_trail = []
    energy_wave_phase = 0
    ball_ghost_trail = []


def update_ball_ghost_trail(ball_cx: int, ball_cy: int, ball_size: int) -> None:
    """공 잔상 궤적 업데이트 - 투명한 공 형태의 잔상"""
    global ball_ghost_trail

    # 새 포인트 추가 (최소 거리 체크)
    add_new_point = True
    if ball_ghost_trail:
        last_point = ball_ghost_trail[-1]
        dx = ball_cx - last_point['x']
        dy = ball_cy - last_point['y']
        if dx * dx + dy * dy < BALL_GHOST_MIN_DISTANCE * BALL_GHOST_MIN_DISTANCE:
            add_new_point = False

    if add_new_point:
        ball_ghost_trail.append({
            'x': ball_cx,
            'y': ball_cy,
            'alpha': BALL_GHOST_INITIAL_ALPHA,
            'size': ball_size,
            'age': 0
        })

    # 트레일 길이 제한
    while len(ball_ghost_trail) > BALL_GHOST_MAX_LENGTH:
        ball_ghost_trail.pop(0)

    # 기존 포인트들 페이드 및 나이 처리
    for point in ball_ghost_trail:
        point['alpha'] *= BALL_GHOST_FADE_SPEED
        point['age'] += 1

    # 투명해진 포인트 제거
    ball_ghost_trail = [p for p in ball_ghost_trail if p['alpha'] > 3]


def draw_ball_ghost_trail(surface: pygame.Surface, screen_offset_x: int = 0, screen_offset_y: int = 0) -> None:
    """공 잔상 궤적 렌더링 - 투명한 공 형태의 그라데이션 잔상 (배경이 비침)"""
    global ball_ghost_trail

    if not ball_ghost_trail:
        return

    total_points = len(ball_ghost_trail)
    current_time = pygame.time.get_ticks()

    # 에너지볼 색상
    core_color = ENERGY_BALL_CORE_COLOR  # 흰색 코어
    inner_color = ENERGY_BALL_INNER_COLOR  # 파란색 내부
    outer_color = ENERGY_BALL_OUTER_COLOR  # 진한 파란색 외부

    # 각 잔상 포인트 그리기 (오래된 것부터 새로운 것 순서로)
    for i, point in enumerate(ball_ghost_trail):
        if point['alpha'] < 3:
            continue

        # 위치 비율 (0: 가장 오래됨, 1: 가장 최근)
        position_ratio = i / max(1, total_points - 1)

        # 알파 계산 - 그라데이션으로 옅어짐 (끝이 더 투명)
        # position_ratio가 낮을수록 오래된 것 = 더 투명
        base_alpha = point['alpha'] * (position_ratio ** 0.7) * 0.6

        if base_alpha < 3:
            continue

        # 잔잔한 파동 효과 (미세한 크기 변화)
        wave_time = current_time * 0.008 + i * 0.5
        wave_scale = 1.0 + math.sin(wave_time) * 0.05  # 5% 크기 파동

        # 크기 계산 (오래될수록 약간 작아짐)
        ghost_size = int(point['size'] * (0.7 + position_ratio * 0.3) * wave_scale)
        if ghost_size < 2:
            continue

        # 서피스 크기 (여유있게) - 재사용 캐시로 매 프레임 할당 방지
        surf_size = ghost_size * 3 + 10
        ghost_surf = _get_reusable_surface(surf_size)
        center = surf_size // 2

        # === 잔잔한 에너지 파동 링 (바깥쪽 투명한 파동) ===
        wave_ring_offset = math.sin(wave_time * 1.2) * 2
        ring_radius = ghost_size + 4 + wave_ring_offset
        ring_alpha = int(base_alpha * 0.15)
        if ring_alpha > 1 and ring_radius > 0:
            pygame.draw.circle(ghost_surf, (*outer_color, ring_alpha),
                             (center, center), int(ring_radius))

        # === Layer 1: 외부 글로우 (투명) ===
        outer_alpha = int(base_alpha * 0.2)
        if outer_alpha > 1:
            pygame.draw.circle(ghost_surf, (*outer_color, outer_alpha),
                             (center, center), ghost_size + 2)

        # === Layer 2: 중간층 (반투명) ===
        mid_alpha = int(base_alpha * 0.35)
        if mid_alpha > 1:
            pygame.draw.circle(ghost_surf, (*inner_color, mid_alpha),
                             (center, center), int(ghost_size * 0.85))

        # === Layer 3: 내부 코어 (약간 밝음) ===
        inner_alpha = int(base_alpha * 0.5)
        if inner_alpha > 1:
            pygame.draw.circle(ghost_surf, (*core_color, inner_alpha),
                             (center, center), int(ghost_size * 0.5))

        # === 파동 효과 (미세한 원형 리플) ===
        if position_ratio > 0.3:  # 최근 잔상에만
            ripple_phase = (current_time * 0.015 + i * 0.8) % (math.pi * 2)
            ripple_alpha = int(base_alpha * 0.1 * math.sin(ripple_phase))
            if ripple_alpha > 1:
                ripple_radius = ghost_size + 6 + math.sin(ripple_phase) * 3
                pygame.draw.circle(ghost_surf, (*inner_color, ripple_alpha),
                                 (center, center), int(ripple_radius), 1)

        # 블렌딩으로 배경 위에 그리기 (투명하게)
        draw_x = int(point['x']) + screen_offset_x - center
        draw_y = int(point['y']) + screen_offset_y - center
        surface.blit(ghost_surf, (draw_x, draw_y), special_flags=pygame.BLEND_ADD)


def update_energy_wave_trail(ball_cx: int, ball_cy: int, ball_vx: float, ball_vy: float) -> None:
    """에너지 파동 궤적 업데이트 - 잔잔한 물결 효과"""
    global energy_wave_trail, energy_wave_phase

    energy_wave_phase += ENERGY_WAVE_FREQUENCY

    # 새 포인트 추가 (최소 거리 체크)
    add_new_point = True
    if energy_wave_trail:
        last_point = energy_wave_trail[-1]
        dx = ball_cx - last_point['x']
        dy = ball_cy - last_point['y']
        if dx * dx + dy * dy < ENERGY_WAVE_MIN_DISTANCE * ENERGY_WAVE_MIN_DISTANCE:
            add_new_point = False

    if add_new_point:
        # 공 이동 방향에 수직인 방향 계산 (파동 방향)
        speed = math.sqrt(ball_vx * ball_vx + ball_vy * ball_vy)
        if speed > 0.1:
            # 수직 벡터 (정규화)
            perp_x = -ball_vy / speed
            perp_y = ball_vx / speed
        else:
            perp_x, perp_y = 0, 1

        energy_wave_trail.append({
            'x': ball_cx,
            'y': ball_cy,
            'vx': ball_vx,  # 공의 속도 저장
            'vy': ball_vy,
            'perp_x': perp_x,  # 수직 방향
            'perp_y': perp_y,
            'alpha': 45,  # 초기 알파값 (투명하게)
            'wave_offset': energy_wave_phase,  # 파동 위상 오프셋
            'age': 0
        })

    # 트레일 길이 제한
    while len(energy_wave_trail) > ENERGY_WAVE_MAX_LENGTH:
        energy_wave_trail.pop(0)

    # 기존 포인트들 페이드 및 나이 처리
    for point in energy_wave_trail:
        point['alpha'] *= ENERGY_WAVE_FADE_SPEED
        point['age'] += 1

    # 투명해진 포인트 제거
    energy_wave_trail = [p for p in energy_wave_trail if p['alpha'] > 2]


def draw_energy_wave_trail(surface: pygame.Surface) -> None:
    """에너지 파동 궤적 렌더링 - 짧고 두꺼운 물결 + 그라데이션 투명도"""
    global energy_wave_trail, energy_wave_phase

    if not energy_wave_trail or len(energy_wave_trail) < 2:
        return

    total_points = len(energy_wave_trail)
    current_time = pygame.time.get_ticks()

    # 파동 색상 (부드러운 하늘색/흰색 톤)
    wave_color_inner = (200, 230, 255)  # 밝은 하늘색
    wave_color_outer = (120, 180, 240)  # 진한 하늘색
    wave_color_glow = (80, 140, 200)    # 글로우 색상

    # 각 포인트 쌍을 연결하여 파동 라인 그리기
    for i in range(total_points - 1):
        p1 = energy_wave_trail[i]
        p2 = energy_wave_trail[i + 1]

        # 위치 비율에 따른 투명도 (끝으로 갈수록 투명)
        ratio = i / max(1, total_points - 1)

        # 그라데이션 투명도 계산 (끝이 더 투명)
        base_alpha = p1['alpha'] * (ratio ** 0.5) * 0.8

        if base_alpha < 3:
            continue

        # 파동 오프셋 계산 (시간 + 위치 기반)
        wave_time = current_time * 0.01 + p1['wave_offset']
        wave_offset = math.sin(wave_time) * ENERGY_WAVE_AMPLITUDE * (1.0 - ratio * 0.3)

        # 수직 방향으로 파동 적용
        wave_x1 = p1['x'] + p1['perp_x'] * wave_offset
        wave_y1 = p1['y'] + p1['perp_y'] * wave_offset

        wave_time2 = current_time * 0.01 + p2['wave_offset']
        wave_offset2 = math.sin(wave_time2) * ENERGY_WAVE_AMPLITUDE * (1.0 - ((i + 1) / max(1, total_points - 1)) * 0.3)
        wave_x2 = p2['x'] + p2['perp_x'] * wave_offset2
        wave_y2 = p2['y'] + p2['perp_y'] * wave_offset2

        # 선 두께 (공 근처가 두껍고 끝으로 갈수록 가늘게)
        thickness = max(2, int(6 * ratio + 2))

        # 외부 글로우 라인
        glow_alpha = int(base_alpha * 0.4)
        if glow_alpha > 2 and thickness > 0:
            try:
                # 서피스 크기 계산
                padding = thickness * 3
                min_x = min(wave_x1, wave_x2) - padding
                max_x = max(wave_x1, wave_x2) + padding
                min_y = min(wave_y1, wave_y2) - padding
                max_y = max(wave_y1, wave_y2) + padding

                surf_w = max(8, int(max_x - min_x) + 8)
                surf_h = max(8, int(max_y - min_y) + 8)

                line_surf = pygame.Surface((surf_w, surf_h), pygame.SRCALPHA)

                local_x1 = wave_x1 - min_x + 4
                local_y1 = wave_y1 - min_y + 4
                local_x2 = wave_x2 - min_x + 4
                local_y2 = wave_y2 - min_y + 4

                # 가장 외부 글로우 (넓고 투명)
                pygame.draw.line(line_surf, (*wave_color_glow, glow_alpha // 2),
                               (int(local_x1), int(local_y1)),
                               (int(local_x2), int(local_y2)),
                               thickness + 4)

                # 외부 글로우
                pygame.draw.line(line_surf, (*wave_color_outer, glow_alpha),
                               (int(local_x1), int(local_y1)),
                               (int(local_x2), int(local_y2)),
                               thickness + 2)

                # 내부 밝은 라인
                inner_alpha = int(base_alpha * 0.6)
                if inner_alpha > 2:
                    pygame.draw.line(line_surf, (*wave_color_inner, inner_alpha),
                                   (int(local_x1), int(local_y1)),
                                   (int(local_x2), int(local_y2)),
                                   max(2, thickness))

                surface.blit(line_surf, (int(min_x), int(min_y)), special_flags=pygame.BLEND_ADD)
            except:
                pass  # 예외 무시

    # 반대 방향 파동 (대칭적인 잔잔한 효과)
    for i in range(total_points - 1):
        p1 = energy_wave_trail[i]
        p2 = energy_wave_trail[i + 1]

        ratio = i / max(1, total_points - 1)
        base_alpha = p1['alpha'] * (ratio ** 0.5) * 0.5  # 반대쪽은 더 연하게

        if base_alpha < 3:
            continue

        wave_time = current_time * 0.01 + p1['wave_offset'] + math.pi  # 반대 위상
        wave_offset = math.sin(wave_time) * ENERGY_WAVE_AMPLITUDE * 0.8 * (1.0 - ratio * 0.3)

        wave_x1 = p1['x'] + p1['perp_x'] * wave_offset
        wave_y1 = p1['y'] + p1['perp_y'] * wave_offset

        wave_time2 = current_time * 0.01 + p2['wave_offset'] + math.pi
        wave_offset2 = math.sin(wave_time2) * ENERGY_WAVE_AMPLITUDE * 0.8 * (1.0 - ((i + 1) / max(1, total_points - 1)) * 0.3)
        wave_x2 = p2['x'] + p2['perp_x'] * wave_offset2
        wave_y2 = p2['y'] + p2['perp_y'] * wave_offset2

        thickness = max(2, int(5 * ratio + 2))

        glow_alpha = int(base_alpha * 0.35)
        if glow_alpha > 2:
            try:
                padding = thickness * 3
                min_x = min(wave_x1, wave_x2) - padding
                max_x = max(wave_x1, wave_x2) + padding
                min_y = min(wave_y1, wave_y2) - padding
                max_y = max(wave_y1, wave_y2) + padding

                surf_w = max(8, int(max_x - min_x) + 8)
                surf_h = max(8, int(max_y - min_y) + 8)

                line_surf = pygame.Surface((surf_w, surf_h), pygame.SRCALPHA)

                local_x1 = wave_x1 - min_x + 4
                local_y1 = wave_y1 - min_y + 4
                local_x2 = wave_x2 - min_x + 4
                local_y2 = wave_y2 - min_y + 4

                pygame.draw.line(line_surf, (*wave_color_outer, glow_alpha),
                               (int(local_x1), int(local_y1)),
                               (int(local_x2), int(local_y2)),
                               thickness + 2)

                surface.blit(line_surf, (int(min_x), int(min_y)), special_flags=pygame.BLEND_ADD)
            except:
                pass


