def _is_divine_state_active(state: dict[str, object] | None) -> bool:
    """디바인스톤 상태 객체가 실제로 필드에 존재하는지 판정한다."""

    if not state:
        return False

    if state.get("hp", 0) <= 0:
        return False

    rect = state.get("rect")
    return rect is not None and getattr(rect, "width", 0) > 0 and getattr(rect, "height", 0) > 0


