_divine_shield_last_dynamic_surf: pygame.Surface | None = None
_divine_shield_dynamic_cache_key: tuple | None = None
DIVINE_SHIELD_DYNAMIC_SKIP_FRAMES = 3  # 3프레임마다 1회 동적 요소 갱신 (20fps 수준)

# 디바인쉴드 반사 부스트 효과 변수
divine_shield_boost_active = False
divine_shield_boost_timer = 0
divine_shield_boost_duration = 36  # 0.6초 (60fps)
divine_shield_boost_original_speed = [0, 0]
divine_shield_boost_curve_direction = 0  # -1: 왼쪽, 1: 오른쪽

# 디바인쉴드 어둠의 오오라 효과 변수
divine_shield_dark_aura_active = False
divine_shield_dark_aura_trail = []  # 궤적 저장 리스트 [(x, y, alpha), ...]


def _end_divine_shield(divine_state: dict) -> None:
    """4겹 보호막이 모두 소진됐을 때 쉴드를 종료하고 과부하를 시작한다."""

    if not divine_state:
        return

    divine_state["shield_active"] = False
    divine_state["shield_timer"] = 0
    divine_state["shield_ready"] = False
    divine_state["shield_xp"] = 0.0
    divine_state["shield_overheat"] = max(
        int(divine_state.get("shield_overheat", 0)),
        BLACKSMITH_DIVINE_SHIELD_OVERHEAT_FRAMES,
    )
    divine_state["shield_hits"] = 0
    divine_state["shield_ripple_effects"] = []

def check_divine_shield_ball_collision():
    """디바인쉴드 보호막과 공의 충돌을 체크하고 보스 공을 반사한다."""
    global BALL, ball_vel, last_hit_by
    global divine_shield_boost_active, divine_shield_boost_timer
    global divine_shield_boost_original_speed, divine_shield_boost_curve_direction
    global divine_shield_dark_aura_active, divine_shield_dark_aura_trail

    # 디바인쉴드 활성 확인
    try:
        divine_state = blacksmith_divine_stone_state
        if divine_state is None or not divine_state.get("shield_active", False):
            return False
    except Exception:
        return False

    # 보스가 발사한 공만 반사
    if last_hit_by != "boss":
        return False

    # 보호막 영역 계산
    centers = []
    rect = divine_state.get("rect")
    if rect is not None:
        centers.append(rect.center)

    try:
        turret_state = BLACKSMITH_CONTROLLER.state.turret.state
        if turret_state and turret_state.get("rect") is not None:
            centers.append(turret_state["rect"].center)
    except Exception:
        pass

    if not centers:
        return False

    # 그룹 중심과 반경 계산
    if len(centers) == 1:
        group_cx, group_cy = centers[0]
        group_radius = 55
    else:
        sum_x = sum(c[0] for c in centers)
        sum_y = sum(c[1] for c in centers)
        group_cx = sum_x // len(centers)
        group_cy = sum_y // len(centers)
        max_dist = max(math.hypot(c[0] - group_cx, c[1] - group_cy) for c in centers)
        group_radius = int(max_dist + 50)

    # 공과 보호막 원의 충돌 체크
    ball_cx, ball_cy = BALL.center
    dist = math.hypot(ball_cx - group_cx, ball_cy - group_cy)

    # 보호막 외곽 링 반경 (가장 바깥 링)
    shield_ring_radius = group_radius + 10
    ball_radius = BALL.width // 2

    # 충돌 감지 (공이 보호막 링에 닿았을 때)
    if abs(dist - shield_ring_radius) <= ball_radius + 3:
        # 반사 벡터 계산 (원형 표면에서의 반사)
        normal_x = (ball_cx - group_cx) / max(dist, 1)
        normal_y = (ball_cy - group_cy) / max(dist, 1)

        # 반사 공식: v' = v - 2(v·n)n
        dot = ball_vel[0] * normal_x + ball_vel[1] * normal_y
        if dot < 0:  # 공이 보호막을 향해 들어오는 경우만
            ball_vel[0] = ball_vel[0] - 2 * dot * normal_x
            ball_vel[1] = ball_vel[1] - 2 * dot * normal_y

            # === 핵심 수정: 공이 아래로 가는 것을 방지 ===
            # 반사 후 공이 아래(양수 Y)로 향하면 위(음수 Y)로 강제 전환
            if ball_vel[1] > 0:
                # 현재 속력 유지하면서 방향만 위로 변경
                speed = math.hypot(ball_vel[0], ball_vel[1])
                # Y 속도를 반전시키고, 최소한의 상향 속도 보장
                ball_vel[1] = -abs(ball_vel[1])
                # 측면에서 맞은 경우 너무 수평으로 가지 않도록 최소 상향 속도 보장
                min_upward_speed = speed * 0.5  # 속력의 최소 50%는 위로
                if abs(ball_vel[1]) < min_upward_speed:
                    ball_vel[1] = -min_upward_speed
                    # X 속도 재조정하여 전체 속력 유지
                    remaining_speed = math.sqrt(max(0, speed * speed - ball_vel[1] * ball_vel[1]))
                    ball_vel[0] = remaining_speed if ball_vel[0] >= 0 else -remaining_speed

            # 공을 보호막 바깥으로 밀어냄 (항상 위쪽으로)
            push_dist = shield_ring_radius + ball_radius + 5
            # 위쪽으로 밀어내도록 Y 방향 조정
            push_normal_y = min(normal_y, -0.3)  # 최소한 위쪽 방향 보장
            push_normal_x = normal_x
            # 정규화
            push_len = math.hypot(push_normal_x, push_normal_y)
            if push_len > 0:
                push_normal_x /= push_len
                push_normal_y /= push_len
            BALL.centerx = int(group_cx + push_normal_x * push_dist)
            BALL.centery = int(group_cy + push_normal_y * push_dist)

            # 속도 부스트 효과 적용 (0.6초간 빠르게 튕겨나감)
            divine_shield_boost_original_speed = [ball_vel[0], ball_vel[1]]
            boost_multiplier = 2.5  # 속도 2.5배 증가
            ball_vel[0] *= boost_multiplier
            ball_vel[1] *= boost_multiplier
            divine_shield_boost_active = True
            divine_shield_boost_timer = divine_shield_boost_duration
            # 커브 방향 결정 (반사 방향에 따라)
            divine_shield_boost_curve_direction = 1 if normal_x > 0 else -1

            # 어둠의 오오라 효과 활성화
            divine_shield_dark_aura_active = True
            divine_shield_dark_aura_trail = []  # 궤적 초기화

            # 보호막 피격 카운터 증가
            shield_hits = divine_state.get("shield_hits", 0) + 1
            divine_state["shield_hits"] = shield_hits

            # 디바인쉴드 피격 사운드
            try:
                play_sound_with_volume(SOUND_DIVINE_SHIELD)
            except Exception:
                pass

            # 파장 출렁임 이펙트 추가
            ripple_effects = divine_state.get("shield_ripple_effects", [])
            ripple_effects.append({"progress": 0.0})
            divine_state["shield_ripple_effects"] = ripple_effects

            # 반사 효과음 및 이펙트
            try:
                play_wall_sound()
                effects_manager.spawn_star_particles(BALL.centerx, BALL.centery, count=8)
            except Exception:
                pass

            # 모든 보호막 소진 시 즉시 과부하 시작
            if shield_hits >= BLACKSMITH_DIVINE_SHIELD_LAYERS:
                _end_divine_shield(divine_state)
                # print(f"[DEBUG] Divine shield destroyed by {BLACKSMITH_DIVINE_SHIELD_LAYERS} hits!")  # 디버그 비활성화
                # 파괴 이펙트
                try:
                    effects_manager.spawn_star_particles(int(group_cx), int(group_cy), count=20)
                    if 'SOUND_GLASS_BREAK' in globals() and SOUND_GLASS_BREAK:
                        play_sound_with_volume(SOUND_GLASS_BREAK)
                except Exception:
                    pass

            return True

    return False


def update_divine_shield_boost():
    """디바인쉴드 반사 부스트 효과를 업데이트한다."""
    global divine_shield_boost_active, divine_shield_boost_timer
    global divine_shield_boost_original_speed, divine_shield_boost_curve_direction
    global ball_vel

    if not divine_shield_boost_active:
        return

    # 커브 효과는 0.6초 동안만 적용
    if divine_shield_boost_timer > 0:
        divine_shield_boost_timer -= 1

        # 기괴한 사인/코사인 움직임 효과 적용
        elapsed = divine_shield_boost_duration - divine_shield_boost_timer  # 경과 프레임
        progress = divine_shield_boost_timer / divine_shield_boost_duration  # 0~1 (끝에서 처음)

        # 다중 주파수 사인/코사인 웨이브 조합으로 기괴한 움직임 생성
        # X축: 좌우로 급격하게 흔들리는 움직임
        wave_x1 = math.sin(elapsed * 0.8) * 1.2  # 저주파 큰 진폭
        wave_x2 = math.cos(elapsed * 2.1) * 0.7  # 고주파 중진폭
        wave_x3 = math.sin(elapsed * 3.7) * 0.4  # 초고주파 소진폭

        # Y축: 위아래로 급격하게 흔들리면서 전체적으로 위로 향함
        wave_y1 = math.cos(elapsed * 1.3) * 0.9  # 저주파 큰 진폭
        wave_y2 = math.sin(elapsed * 2.9) * 0.6  # 고주파 중진폭
        wave_y3 = math.cos(elapsed * 4.3) * 0.3  # 초고주파 소진폭
        base_upward = -0.5 * progress  # 기본 위쪽 방향 유지

        # 모든 웨이브 합산
        bizarre_x = (wave_x1 + wave_x2 + wave_x3) * progress  # 시간이 지날수록 약해짐
        bizarre_y = (wave_y1 + wave_y2 + wave_y3 + base_upward) * progress

        # 속도에 기괴한 움직임 적용
        ball_vel[0] += bizarre_x
        ball_vel[1] += bizarre_y

    # 속도 복구는 보스 패들에 닿았을 때 처리 (deactivate_divine_shield_boost에서)


def deactivate_divine_shield_boost():
    """디바인쉴드 부스트를 비활성화하고 속도를 복구한다."""
    global divine_shield_boost_active, divine_shield_boost_timer
    global divine_shield_boost_original_speed, ball_vel

    if not divine_shield_boost_active:
        return

    # 현재 방향 유지하면서 원래 속도 크기로 복구
    current_speed = math.hypot(ball_vel[0], ball_vel[1])
    original_speed = math.hypot(divine_shield_boost_original_speed[0],
                               divine_shield_boost_original_speed[1])
    if current_speed > 0:
        speed_ratio = original_speed / current_speed
        ball_vel[0] *= speed_ratio
        ball_vel[1] *= speed_ratio

    divine_shield_boost_active = False
    divine_shield_boost_timer = 0


def update_divine_shield_dark_aura():
    """디바인쉴드 어둠의 오오라 효과를 업데이트한다. (최적화 버전)"""
    global divine_shield_dark_aura_active, divine_shield_dark_aura_trail

    if not divine_shield_dark_aura_active:
        return

    # 현재 공 위치를 궤적에 추가
    ball_cx, ball_cy = BALL.center
    divine_shield_dark_aura_trail.append({"x": ball_cx, "y": ball_cy, "alpha": 255})

    # 궤적의 알파값 감소 및 제거를 한 번의 순회로 처리 (in-place)
    write_idx = 0
    for read_idx in range(len(divine_shield_dark_aura_trail)):
        trail = divine_shield_dark_aura_trail[read_idx]
        trail["alpha"] -= 12
        if trail["alpha"] > 0:
            divine_shield_dark_aura_trail[write_idx] = trail
            write_idx += 1
    # 불필요한 요소 제거
    del divine_shield_dark_aura_trail[write_idx:]

    # 최대 궤적 개수 제한 (슬라이싱 대신 del 사용)
    if len(divine_shield_dark_aura_trail) > 30:
        del divine_shield_dark_aura_trail[:-30]


# 디바인쉴드 어둠의 오오라 캐시된 Surface들
_divine_aura_trail_cache: dict[int, pygame.Surface] = {}
_divine_aura_ball_cache: dict[int, pygame.Surface] = {}
_divine_aura_particle_cache: dict[int, pygame.Surface] = {}
_divine_aura_particle_pool: list[dict] = []  # 파티클 풀링


def _get_divine_aura_trail_surface(size: int, alpha: int) -> pygame.Surface:
    """캐시된 궤적 Surface를 반환한다."""
    cache_key = (size, alpha // 20)  # alpha를 20단위로 양자화해서 캐시 키 최소화
    if cache_key not in _divine_aura_trail_cache:
        surf = pygame.Surface((size * 2, size * 2), pygame.SRCALPHA)
        pygame.draw.circle(surf, (80, 20, 120, int(alpha * 0.3)), (size, size), size)
        pygame.draw.circle(surf, (60, 10, 100, int(alpha * 0.5)), (size, size), int(size * 0.7))
        _divine_aura_trail_cache[cache_key] = surf
        # 캐시 크기 제한
        if len(_divine_aura_trail_cache) > 50:
            _divine_aura_trail_cache.pop(next(iter(_divine_aura_trail_cache)))
    return _divine_aura_trail_cache[cache_key]


def _get_divine_aura_ball_surface(aura_size: int) -> pygame.Surface:
    """캐시된 공 주변 오오라 Surface를 반환한다."""
    if aura_size not in _divine_aura_ball_cache:
        surf = pygame.Surface((aura_size * 2, aura_size * 2), pygame.SRCALPHA)
        for i in range(4):
            layer_size = int(aura_size * (1 - i * 0.15))
            layer_alpha = int(180 - i * 40)
            r = 100 - i * 15
            g = 20 - i * 5
            b = 150 - i * 20
            pygame.draw.circle(surf, (r, g, b, layer_alpha), (aura_size, aura_size), layer_size)
        _divine_aura_ball_cache[aura_size] = surf
        # 캐시 크기 제한
        if len(_divine_aura_ball_cache) > 20:
            _divine_aura_ball_cache.pop(next(iter(_divine_aura_ball_cache)))
    return _divine_aura_ball_cache[aura_size]


def _get_divine_aura_particle_surface(particle_size: int) -> pygame.Surface:
    """캐시된 파티클 Surface를 반환한다."""
    if particle_size not in _divine_aura_particle_cache:
        surf = pygame.Surface((particle_size * 2, particle_size * 2), pygame.SRCALPHA)
        pygame.draw.circle(surf, (80, 10, 130, 140), (particle_size, particle_size), particle_size)
        _divine_aura_particle_cache[particle_size] = surf
    return _divine_aura_particle_cache[particle_size]


def draw_divine_shield_dark_aura(screen):
    """디바인쉴드 어둠의 오오라를 그린다. (최적화 버전)"""
    global divine_shield_dark_aura_active, divine_shield_dark_aura_trail
    global _divine_aura_particle_pool

    if not divine_shield_dark_aura_active:
        return

    # 궤적 그리기 (캐시된 Surface 사용)
    for trail in divine_shield_dark_aura_trail:
        alpha = max(0, min(255, trail["alpha"]))
        if alpha < 10:  # 너무 투명한 건 스킵
            continue
        size = int(12 + (alpha / 255) * 8)
        trail_surf = _get_divine_aura_trail_surface(size, alpha)
        screen.blit(trail_surf, (trail["x"] - size, trail["y"] - size))

    # 공 주변 어둠의 오오라 그리기 (캐시된 Surface 사용)
    ball_cx, ball_cy = BALL.center
    ball_radius = BALL.width // 2

    # 맥동 효과 - 프레임당 1회만 계산
    pulse = math.sin(pygame.time.get_ticks() * 0.01) * 0.3 + 0.7
    aura_size = int(ball_radius * 2.5 * pulse)
    aura_surf = _get_divine_aura_ball_surface(aura_size)
    screen.blit(aura_surf, (ball_cx - aura_size, ball_cy - aura_size))

    # 어둠 파티클 효과 (풀링 + 캐시 사용, 매 프레임 생성 대신 기존 파티클 업데이트)
    # 파티클 풀이 비어있거나 너무 적으면 보충
    if len(_divine_aura_particle_pool) < 4:
        for _ in range(4 - len(_divine_aura_particle_pool)):
            _divine_aura_particle_pool.append({
                "angle": random.uniform(0, math.pi * 2),
                "dist": random.uniform(ball_radius * 1.2, ball_radius * 2.2),
                "size": random.randint(2, 4),
                "speed": random.uniform(0.05, 0.15),
            })

    # 기존 파티클 업데이트 및 렌더링
    for p in _divine_aura_particle_pool:
        p["angle"] += p["speed"]
        px = int(ball_cx + math.cos(p["angle"]) * p["dist"])
        py = int(ball_cy + math.sin(p["angle"]) * p["dist"])
        particle_surf = _get_divine_aura_particle_surface(p["size"])
        screen.blit(particle_surf, (px - p["size"], py - p["size"]))


def deactivate_divine_shield_dark_aura():
    """디바인쉴드 어둠의 오오라를 비활성화한다."""
    global divine_shield_dark_aura_active, divine_shield_dark_aura_trail
    global _divine_aura_particle_pool
    divine_shield_dark_aura_active = False
    divine_shield_dark_aura_trail.clear()  # 메모리 재할당 없이 리스트 비우기
    _divine_aura_particle_pool.clear()  # 파티클 풀도 초기화


BLACKSMITH_HAMMER_SHOCK_STAGE_COST = {
    1: 200,
    2: 260,
    3: 320,
}
BLACKSMITH_HAMMER_SHOCK_STAGE_DAMAGE = {
    1: 1,
    2: 2,
    3: 3,
}
BLACKSMITH_HAMMER_SHOCK_MIN_STAGE_COST = BLACKSMITH_HAMMER_SHOCK_STAGE_COST[1]
BLACKSMITH_HAMMER_SHOCK_MAX_STAGE_COST = BLACKSMITH_HAMMER_SHOCK_STAGE_COST[3]
