def _genie_preview_blit_scaled(surface: pygame.Surface, source: pygame.Surface, dest_rect: pygame.Rect) -> bool:
    if source is None:
        return False
    src_w, src_h = source.get_size()
    if src_w <= 0 or src_h <= 0 or dest_rect.width <= 0 or dest_rect.height <= 0:
        return False

    scale = min(dest_rect.width / src_w, dest_rect.height / src_h)
    if scale <= 0:
        return False

    new_size = (max(1, int(src_w * scale)), max(1, int(src_h * scale)))
    if new_size != source.get_size():
        scaled = pygame.transform.smoothscale(source, new_size)
    else:
        scaled = source

    blit_rect = scaled.get_rect(center=dest_rect.center)
    surface.blit(scaled, blit_rect)
    return True


def _render_thor_shield_preview(surface: pygame.Surface, rect: pygame.Rect) -> bool:
    overlay = pygame.Surface(rect.size, pygame.SRCALPHA)
    scale = 0.10
    pivot_x = rect.width * 0.26
    pivot_y = rect.height * 0.52
    base_dx = rect.width * 0.4
    base_dy = -rect.height * 0.05

    cycle_ms = 6000
    phase = pygame.time.get_ticks() % cycle_ms
    max_angle = 42.0  # degrees

    if phase < 2000:
        swing_angle = 0.0
    elif phase < 3500:
        t = (phase - 2000) / 1500.0
        swing_angle = -max_angle * t
    elif phase < 5000:
        t = (phase - 3500) / 1500.0
        swing_angle = -max_angle + (2 * max_angle * t)
    else:
        t = (phase - 5000) / 1000.0
        swing_angle = max_angle * (1.0 - t)

    angle_rad = math.radians(swing_angle)
    cos_a = math.cos(angle_rad)
    sin_a = math.sin(angle_rad)
    swing_dx = base_dx * cos_a - base_dy * sin_a
    swing_dy = base_dx * sin_a + base_dy * cos_a

    pivot_point = (pivot_x, pivot_y)
    head_point = (pivot_x + swing_dx, pivot_y + swing_dy)
    _draw_blacksmith_umbrella_overlay(
        overlay,
        pivot_point,
        head_point,
        raise_amount=1.0 * scale,
        open_amount=1.0 * scale,
    )
    surface.blit(overlay, rect.topleft, special_flags=pygame.BLEND_PREMULTIPLIED)
    return True


def _render_blacksmith_build_preview(surface: pygame.Surface, rect: pygame.Rect) -> bool:
    if BLACKSMITH_TURRET_ICON is None or BLACKSMITH_DIVINE_ICON is None:
        return False

    icon_w, icon_h = BLACKSMITH_BUILD_ICON_SIZE
    spacing = 12
    available_width = rect.width - spacing
    if available_width <= 0:
        return False

    scale = min(
        available_width / (icon_w * 2),
        rect.height / icon_h if icon_h > 0 else 1.0,
    )
    scale = max(scale, 0.1)
    scaled_size = (max(1, int(icon_w * scale)), max(1, int(icon_h * scale)))

    turret_icon = pygame.transform.smoothscale(BLACKSMITH_TURRET_ICON, scaled_size)
    divine_icon = pygame.transform.smoothscale(BLACKSMITH_DIVINE_ICON, scaled_size)

    offset_x = (scaled_size[0] // 2) + int(spacing * 0.5)
    center = rect.center

    left_rect = turret_icon.get_rect(center=(center[0] - offset_x, center[1]))
    right_rect = divine_icon.get_rect(center=(center[0] + offset_x, center[1]))

    surface.blit(turret_icon, left_rect)
    surface.blit(divine_icon, right_rect)

    return True


def _render_blacksmith_hammer_preview(surface: pygame.Surface, rect: pygame.Rect) -> bool:
    hammer_surface = _get_blacksmith_thrown_hammer_surface()
    if hammer_surface is None:
        return False

    _genie_preview_blit_scaled(surface, hammer_surface, rect)

    overlay = pygame.Surface(rect.size, pygame.SRCALPHA)
    radius = int(min(rect.width, rect.height) * 0.45)
    pygame.draw.circle(
        overlay,
        (120, 200, 255, 110),
        (rect.width // 2, rect.height // 2),
        max(1, radius),
    )
    surface.blit(overlay, rect.topleft, special_flags=pygame.BLEND_ADD)
    return True


def _draw_genie_keycap(
    surface: pygame.Surface,
    center: tuple[int, int],
    label: str,
    *,
    width: int = 64,
    height: int = 44,
    active: bool = False,
) -> None:
    """지니 미리보기에 사용하는 키캡 장식."""

    rect = pygame.Rect(0, 0, width, height)
    rect.center = center

    base = (255, 228, 168) if active else (236, 240, 255)
    border = (255, 182, 110) if active else (132, 164, 226)
    inner = (255, 246, 224) if active else (248, 250, 255)

    pygame.draw.rect(surface, base, rect, border_radius=12)
    pygame.draw.rect(surface, inner, rect.inflate(-6, -6), border_radius=10)
    pygame.draw.rect(surface, border, rect, width=2, border_radius=12)

    font = FontStyle.body() if len(label) <= 2 else FontStyle.small()
    glyph = font.render(label, True, (28, 34, 54))
    surface.blit(glyph, glyph.get_rect(center=rect.center))


def _render_smasher_genie_preview(
    surface: pygame.Surface,
    rect: pygame.Rect,
    animation_id: str,
    ticks: int,
) -> bool:
    """스매셔 전용 지니 튜토리얼 미리보기."""

    preview = pygame.Surface(rect.size, pygame.SRCALPHA)
    width, height = rect.size
    center = (width // 2, height // 2)
    title_font = FontStyle.small()
    body_font = FontStyle.tiny()
    pulse = 0.3 + 0.2 * math.sin(ticks / 260.0)

    if animation_id == "smasher_drive":
        radius = int(min(width, height) * 0.28)
        ring = pygame.Surface((radius * 2 + 48, radius * 2 + 48), pygame.SRCALPHA)
        ring_center = (ring.get_width() // 2, ring.get_height() // 2)

        inner_radius = radius + int(12 * pulse)
        pygame.draw.circle(ring, (40, 210, 255, 60), ring_center, inner_radius + 6)
        pygame.draw.circle(ring, (40, 210, 255, 150), ring_center, radius, width=4)
        pygame.draw.circle(ring, (170, 120, 255, 140), ring_center, max(4, radius // 2), width=3)
        preview.blit(ring, ring.get_rect(center=center))

        headline = title_font.render("PERFECT TIMING", True, (224, 236, 255))
        preview.blit(headline, headline.get_rect(midtop=(center[0], center[1] - radius - 58)))

        gauge = body_font.render(_t("ui.gauge_required", "게이지 160 이상"), True, (214, 230, 255))
        preview.blit(gauge, gauge.get_rect(midtop=(center[0], center[1] + radius + 14)))

        _draw_genie_keycap(preview, (center[0] - radius - 46, center[1] + 2), "←", active=True)
        _draw_genie_keycap(preview, (center[0] + radius + 46, center[1] + 2), "→", active=True)
        _draw_genie_keycap(preview, (center[0], center[1] + radius + 62), "SPACE", width=122, active=True)

        ball = pygame.Surface((28, 28), pygame.SRCALPHA)
        pygame.draw.circle(ball, (255, 255, 200), (14, 14), 14)
        pygame.draw.circle(ball, (120, 255, 210), (14, 14), 12)
        pygame.draw.circle(ball, (255, 255, 255), (11, 11), 4)
        preview.blit(ball, ball.get_rect(center=center))

    elif animation_id == "smasher_power":
        bar_width = int(width * 0.68)
        bar_height = 28
        bar_rect = pygame.Rect(0, 0, bar_width, bar_height)
        bar_rect.center = (center[0], center[1] - 12)
        bar_rect.move_ip(int(width * 0.16) - bar_rect.left, 0)

        frame = bar_rect.inflate(28, 22)
        pygame.draw.rect(preview, (24, 36, 68, 190), frame, border_radius=18)
        pygame.draw.rect(preview, (120, 150, 210, 90), frame, width=2, border_radius=18)

        ratio = min(1.0, 350 / 500)
        filled = pygame.Rect(bar_rect.left, bar_rect.top, max(1, int(bar_rect.width * ratio)), bar_rect.height)
        gradient = pygame.Surface(filled.size, pygame.SRCALPHA)
        for x in range(filled.width):
            t = x / max(1, filled.width - 1)
            color = (
                int(255 * (0.6 + 0.4 * t)),
                int(120 + 90 * t),
                int(90 + 50 * (1 - t)),
                215,
            )
            pygame.draw.line(gradient, color, (x, 0), (x, filled.height))
        preview.blit(gradient, filled.topleft)
        pygame.draw.rect(preview, (255, 214, 168), bar_rect, width=2, border_radius=12)

        gauge = title_font.render(_t("ui.gauge_amount", "350 / 500 게이지"), True, (236, 240, 255))
        preview.blit(gauge, gauge.get_rect(midtop=(center[0], bar_rect.bottom + 10)))

        _draw_genie_keycap(preview, (center[0], bar_rect.top - 54), "SPACE", width=122, active=True)
        _draw_genie_keycap(preview, (bar_rect.left - 50, bar_rect.centery + 60), "←")
        _draw_genie_keycap(preview, (center[0], bar_rect.centery + 60), "직선")
        _draw_genie_keycap(preview, (bar_rect.right + 50, bar_rect.centery + 60), "→")

        arrow_len = int(width * 0.18)
        for direction, offset in ((-1, -arrow_len), (0, 0), (1, arrow_len)):
            start = (center[0], center[1] + 18)
            end = (center[0] + offset, center[1] + (0 if direction else -38))
            pygame.draw.line(preview, (255, 205, 150), start, end, 4)
            if direction == 0:
                tip = [(end[0] - 12, end[1] - 6), (end[0] + 12, end[1] - 6), (end[0], end[1] - 18)]
            else:
                tip = [
                    (end[0], end[1] - 12),
                    (end[0] + 12 * (-direction), end[1] + 6),
                    (end[0], end[1] + 12),
                ]
            pygame.draw.polygon(preview, (255, 170, 110), tip)

    else:
        return False

    surface.blit(preview, rect.topleft)
    return True


def _render_blacksmith_turret_preview(surface: pygame.Surface, rect: pygame.Rect) -> bool:
    try:
        state_controller = BLACKSMITH_CONTROLLER.state
    except NameError:
        return False

    temp_surface = pygame.Surface(rect.size, pygame.SRCALPHA)

    scale = min(
        (rect.width / max(1, BLACKSMITH_TURRET_BASE_WIDTH)) * 0.3,
        (rect.height / max(1, BLACKSMITH_TURRET_BASE_HEIGHT)) * 0.3,
    )
    scale = max(scale, 0.15)

    turret_width = max(12, int(BLACKSMITH_TURRET_BASE_WIDTH * scale))
    turret_height = max(12, int(BLACKSMITH_TURRET_BASE_HEIGHT * scale))
    turret_rect = pygame.Rect(0, 0, turret_width, turret_height)
    turret_rect.center = (rect.width // 2, int(rect.height * 0.55))

    base_interval = BLACKSMITH_TURRET_FIRE_INTERVAL
    turret_state_preview = {
        "rect": turret_rect,
        "fire_timer": base_interval,
        "fire_interval": base_interval,
        "hp": BLACKSMITH_TURRET_BASE_HP,
        "max_hp": BLACKSMITH_TURRET_BASE_HP,
        "level": BLACKSMITH_TURRET_BASE_LEVEL,
        "xp": 0.0,
        "xp_max": float(BLACKSMITH_TURRET_XP_REQUIRED),
        "aim_angle": -math.pi / 2,
        "display_angle": -math.pi / 2,
        "recoil_timer": 0,
        "recoil_offset": 0.0,
        "base_fire_interval": base_interval,
        "overdrive_active": False,
        "overdrive_timer": 0,
        "overdrive_fire_window": 0,
        "overdrive_shots_remaining": 0,
        "overdrive_shot_cooldown": 0,
        "overdrive_glow_phase": 0.0,
        "overdrive_flash_timer": 0,
        "overdrive_recoil_boost": 1.0,
        "overdrive_speed_boost": 1.0,
        "overdrive_stun_multiplier": 1.0,
        "overdrive_knockback_multiplier": 1.0,
        "overdrive_divine_active": False,
        "overheat_timer": 0,
        "overheat_smoke_timer": 0,
        "display_angle_accel": 0.0,
        "homing_cooldown": 0,
        "homing_burst_timer": 0,
        "homing_burst_shots": 0,
    }

    fire_cycle_ms = 3000
    fire_phase = pygame.time.get_ticks() % fire_cycle_ms
    flash_duration = 220
    projectile_duration = 1200
    show_flash = fire_phase < flash_duration
    projectile_active = fire_phase < projectile_duration
    progress = min(1.0, fire_phase / projectile_duration) if projectile_active else 0.0
    flash_frames = max(1, int(0.15 * FPS))
    turret_state_preview["overdrive_flash_timer"] = flash_frames if show_flash else 0
    turret_state_preview["overdrive_glow_phase"] = pygame.time.get_ticks() / 240.0

    projectiles_preview: list[dict[str, object]] = []
    if projectile_active:
        scale_x = turret_rect.width / BLACKSMITH_TURRET_DESIGN_WIDTH
        scale_y = turret_rect.height / BLACKSMITH_TURRET_DESIGN_HEIGHT
        pivot_point = pygame.math.Vector2(
            turret_rect.centerx,
            turret_rect.top + BLACKSMITH_TURRET_HEAD_PIVOT_OFFSET * scale_y,
        )
        angle = turret_state_preview["display_angle"]
        forward_vec = pygame.math.Vector2(math.cos(angle), math.sin(angle))
        if forward_vec.length_squared() == 0:
            forward_vec = pygame.math.Vector2(0, -1)
        else:
            forward_vec = forward_vec.normalize()
        muzzle_distance = BLACKSMITH_TURRET_MUZZLE_LENGTH * scale_x
        muzzle_world = pivot_point + forward_vec * muzzle_distance
        travel_distance = muzzle_distance + rect.width * 0.9 * progress
        projectile_pos = muzzle_world + forward_vec * travel_distance
        muzzle_tip = muzzle_world + forward_vec * max(4, scale_x * 6)
        projectile_radius = max(3, int(8 * scale))
        missile_speed = 14.0
        projectiles_preview.append(
            {
                "x": float(projectile_pos.x),
                "y": float(projectile_pos.y),
                "vx": float(forward_vec.x * missile_speed),
                "vy": float(forward_vec.y * missile_speed),
                "radius": projectile_radius,
                "overdrive": False,
                "trail_timer": int(pygame.time.get_ticks() / 6),
            }
        )

    # 백업
    turret_backup = copy.deepcopy(state_controller.turret)
    divine_backup = copy.deepcopy(state_controller.divine)
    globals_backup_keys = [
        "blacksmith_turret_active",
        "blacksmith_turret_state",
        "blacksmith_turret_blueprint_active",
        "blacksmith_turret_blueprint_rect",
        "blacksmith_turret_projectiles",
        "blacksmith_turret_build_progress",
        "blacksmith_turret_partial_drain",
        "blacksmith_turret_xp_partial_drain",
        "blacksmith_turret_manual_cooldown",
        "blacksmith_turret_overdrive_ui_timer",
        "blacksmith_turret_overdrive_ui_divine",
        "blacksmith_turret_overheat_timer",
        "blacksmith_turret_overheat_smoke_timer",
        "blacksmith_divine_blueprint_active",
        "blacksmith_divine_blueprint_rect",
        "blacksmith_divine_build_progress",
        "blacksmith_divine_partial_drain",
        "blacksmith_divine_stone_state",
    ]
    globals_backup = {k: copy.deepcopy(globals().get(k)) for k in globals_backup_keys}

    try:
        # 프리뷰용 전역/상태 설정
        globals()["blacksmith_turret_active"] = True
        globals()["blacksmith_turret_state"] = turret_state_preview
        globals()["blacksmith_turret_blueprint_active"] = False
        globals()["blacksmith_turret_blueprint_rect"] = None
        globals()["blacksmith_turret_projectiles"] = projectiles_preview
        globals()["blacksmith_turret_build_progress"] = 0
        globals()["blacksmith_turret_partial_drain"] = 0.0
        globals()["blacksmith_turret_xp_partial_drain"] = 0.0
        globals()["blacksmith_turret_manual_cooldown"] = 0
        globals()["blacksmith_turret_overdrive_ui_timer"] = 0
        globals()["blacksmith_turret_overdrive_ui_divine"] = False
        globals()["blacksmith_turret_overheat_timer"] = 0
        globals()["blacksmith_turret_overheat_smoke_timer"] = 0
        globals()["blacksmith_divine_blueprint_active"] = False
        globals()["blacksmith_divine_blueprint_rect"] = None
        globals()["blacksmith_divine_build_progress"] = 0
        globals()["blacksmith_divine_partial_drain"] = 0.0
        globals()["blacksmith_divine_stone_state"] = None

        state_controller.turret.active = True
        state_controller.turret.blueprint_active = False
        state_controller.turret.blueprint_rect = None
        state_controller.turret.build_progress = 0
        state_controller.turret.state = turret_state_preview
        state_controller.turret.projectiles = projectiles_preview
        state_controller.turret.partial_drain = 0.0
        state_controller.turret.xp_partial_drain = 0.0
        state_controller.turret.manual_cooldown = 0
        state_controller.turret.overdrive_ui_timer = 0
        state_controller.turret.overdrive_ui_divine = False
        state_controller.turret.overheat_timer = 0
        state_controller.turret.overheat_smoke_timer = 0

        state_controller.divine.state = None
        state_controller.divine.blueprint_active = False
        state_controller.divine.blueprint_rect = None
        state_controller.divine.build_progress = 0
        state_controller.divine.partial_drain = 0.0

        draw_blacksmith_turret_elements(temp_surface)

        surface.blit(temp_surface, rect.topleft, special_flags=pygame.BLEND_PREMULTIPLIED)
        return True
    finally:
        # 상태 복구
        state_controller.turret = turret_backup
        state_controller.divine = divine_backup

        for key, value in globals_backup.items():
            globals()[key] = value

        # 컨트롤러와 전역 동기화
        try:
            BLACKSMITH_CONTROLLER.apply_to_globals()
        except Exception:
            pass


def _render_blacksmith_divine_preview(surface: pygame.Surface, rect: pygame.Rect) -> bool:
    try:
        state_controller = BLACKSMITH_CONTROLLER.state
    except NameError:
        return False

    temp_surface = pygame.Surface(rect.size, pygame.SRCALPHA)

    width, height = BLACKSMITH_DIVINE_STONE_SIZE
    scale = min(
        (rect.width / max(1, width)) * 0.3,
        (rect.height / max(1, height)) * 0.3,
    )
    scale = max(scale, 0.15)
    stone_width = max(12, int(width * scale))
    stone_height = max(12, int(height * scale))
    stone_rect = pygame.Rect(0, 0, stone_width, stone_height)
    stone_rect.center = (rect.width // 2, rect.height * 0.45)

    divine_state_preview = {
        "rect": stone_rect,
        "hp": BLACKSMITH_DIVINE_STONE_MAX_HP,
        "max_hp": BLACKSMITH_DIVINE_STONE_MAX_HP,
        "cooldown": 0,
        "pulse": 0,
    }

    # 백업
    turret_backup = copy.deepcopy(state_controller.turret)
    divine_backup = copy.deepcopy(state_controller.divine)
    globals_backup_keys = [
        "blacksmith_divine_stone_state",
        "blacksmith_divine_blueprint_active",
        "blacksmith_divine_blueprint_rect",
        "blacksmith_divine_build_progress",
        "blacksmith_divine_partial_drain",
    ]
    globals_backup = {k: copy.deepcopy(globals().get(k)) for k in globals_backup_keys}

    try:
        globals()["blacksmith_divine_stone_state"] = divine_state_preview
        globals()["blacksmith_divine_blueprint_active"] = False
        globals()["blacksmith_divine_blueprint_rect"] = None
        globals()["blacksmith_divine_build_progress"] = BLACKSMITH_DIVINE_BUILD_TIME
        globals()["blacksmith_divine_partial_drain"] = 0.0

        state_controller.divine.state = divine_state_preview
        state_controller.divine.blueprint_active = False
        state_controller.divine.blueprint_rect = None
        state_controller.divine.build_progress = BLACKSMITH_DIVINE_BUILD_TIME
        state_controller.divine.partial_drain = 0.0

        draw_blacksmith_turret_elements(temp_surface)

        surface.blit(temp_surface, rect.topleft, special_flags=pygame.BLEND_PREMULTIPLIED)
        return True
    finally:
        state_controller.turret = turret_backup
        state_controller.divine = divine_backup

        for key, value in globals_backup.items():
            globals()[key] = value

        try:
            BLACKSMITH_CONTROLLER.apply_to_globals()
        except Exception:
            pass


def _snapshot_soldier_genie_state() -> dict[str, object]:
    """Capture mutable globals required to render soldier previews."""

    snapshot: dict[str, object] = {}

    snapshot["soldier_ammo_count"] = soldier_ammo_count
    snapshot["soldier_max_ammo"] = soldier_max_ammo
    snapshot["soldier_reloading"] = soldier_reloading
    snapshot["soldier_reload_timer"] = soldier_reload_timer
    snapshot["soldier_last_reload_bullets"] = soldier_last_reload_bullets
    snapshot["soldier_emergency_supply_toast_timer"] = soldier_emergency_supply_toast_timer
    snapshot["round_start_time"] = round_start_time

    controller_state = {
        "weapons": list(soldier_controller.weapons),
        "current_index": soldier_controller.current_index,
        "switch_cooldown": soldier_controller.switch_cooldown,
        "reload_counts": dict(soldier_controller.reload_counts),
        "degradation_thresholds": dict(getattr(soldier_controller, "degradation_thresholds", {})),
        "degraded": set(soldier_controller.degraded),
        "ui_highlight_timer": soldier_controller.ui_highlight_timer,
    }
    snapshot["soldier_controller"] = controller_state

    supply_state = {
        "active": supply_drop_state.active,
        "timer": supply_drop_state.timer,
        "hold_time": supply_drop_state.hold_time,
        "radio_motion": supply_drop_state.radio_motion,
        "radio_timer": supply_drop_state.radio_timer,
        "radio_duration": supply_drop_state.radio_duration,
    }
    snapshot["supply_state"] = supply_state
    snapshot["supply_hold_active"] = supply_runtime.hold_active

    snapshot["player_rect"] = PLAYER.copy()

    return snapshot


def _restore_soldier_genie_state(snapshot: dict[str, object]) -> None:
    """Restore soldier preview globals from a snapshot."""

    global soldier_ammo_count
    global soldier_max_ammo
    global soldier_reloading
    global soldier_reload_timer
    global soldier_last_reload_bullets
    global soldier_emergency_supply_toast_timer
    global round_start_time

    soldier_ammo_count = snapshot["soldier_ammo_count"]  # type: ignore[assignment]
    soldier_max_ammo = snapshot["soldier_max_ammo"]  # type: ignore[assignment]
    soldier_reloading = snapshot["soldier_reloading"]  # type: ignore[assignment]
    soldier_reload_timer = snapshot["soldier_reload_timer"]  # type: ignore[assignment]
    soldier_last_reload_bullets = snapshot["soldier_last_reload_bullets"]  # type: ignore[assignment]
    soldier_emergency_supply_toast_timer = snapshot["soldier_emergency_supply_toast_timer"]  # type: ignore[assignment]
    round_start_time = snapshot["round_start_time"]  # type: ignore[assignment]

    controller_state = snapshot["soldier_controller"]  # type: ignore[assignment]
    soldier_controller.weapons[:] = controller_state["weapons"]  # type: ignore[index]
    soldier_controller.current_index = controller_state["current_index"]  # type: ignore[assignment]
    soldier_controller.switch_cooldown = controller_state["switch_cooldown"]  # type: ignore[assignment]
    soldier_controller.reload_counts = dict(controller_state["reload_counts"])
    soldier_controller.degradation_thresholds = dict(controller_state.get("degradation_thresholds", {}))
    soldier_controller.degraded = set(controller_state["degraded"])
    soldier_controller.ui_highlight_timer = controller_state["ui_highlight_timer"]  # type: ignore[assignment]

    supply_state = snapshot["supply_state"]  # type: ignore[assignment]
    supply_drop_state.active = supply_state["active"]  # type: ignore[assignment]
    supply_drop_state.timer = supply_state["timer"]  # type: ignore[assignment]
    supply_drop_state.hold_time = supply_state["hold_time"]  # type: ignore[assignment]
    supply_drop_state.radio_motion = supply_state["radio_motion"]  # type: ignore[assignment]
    supply_drop_state.radio_timer = supply_state["radio_timer"]  # type: ignore[assignment]
    supply_drop_state.radio_duration = supply_state["radio_duration"]  # type: ignore[assignment]
    supply_runtime.hold_active = snapshot["supply_hold_active"]  # type: ignore[assignment]

    player_rect: pygame.Rect = snapshot["player_rect"]  # type: ignore[assignment]
    PLAYER.update(player_rect)


def _get_soldier_weapon_ui_preview_rect() -> pygame.Rect:
    slot_size = 60
    slot_margin = 10
    bottom_margin = 80
    weapon_size = int(slot_size * 0.8)
    weapon_x = slot_margin
    weapon_y = HEIGHT - bottom_margin - slot_size - weapon_size + 15
    preview_width = max(220, weapon_size + 170)
    preview_height = weapon_size + 120
    preview_rect = pygame.Rect(weapon_x - 12, weapon_y - 24, preview_width, preview_height)
    preview_rect.clamp_ip(pygame.Rect(0, 0, WIDTH, HEIGHT))
    return preview_rect


def _configure_soldier_weapon_preview(animation_id: str) -> pygame.Rect:
    global soldier_ammo_count
    global soldier_reloading
    global soldier_reload_timer
    global soldier_last_reload_bullets
    global soldier_emergency_supply_toast_timer
    global round_start_time

    soldier_controller.switch_cooldown = 0
    soldier_controller.reload_counts.clear()
    soldier_controller.degradation_thresholds.clear()
    soldier_controller.degraded.clear()
    soldier_controller.ui_highlight_timer = 0

    round_start_time = pygame.time.get_ticks() - 6000

    if animation_id == "switch":
        soldier_controller.weapons[:] = ["pistol", "bazooka", "ak47"]
        soldier_controller.current_index = 1 if len(soldier_controller.weapons) > 1 else 0
        soldier_controller.ui_highlight_timer = soldier_controller.ui_highlight_duration
        soldier_ammo_count = soldier_max_ammo
        soldier_reloading = False
        soldier_reload_timer = SOLDIER_RELOAD_TIME
        soldier_last_reload_bullets = 0
        soldier_emergency_supply_toast_timer = 0
    else:
        soldier_controller.weapons[:] = ["pistol"]
        soldier_controller.current_index = 0
        soldier_emergency_supply_toast_timer = 0

        if animation_id == "fire":
            soldier_controller.ui_highlight_timer = soldier_controller.ui_highlight_duration
            soldier_ammo_count = max(0, soldier_max_ammo - 1)
            soldier_reloading = False
            soldier_reload_timer = SOLDIER_RELOAD_TIME
            soldier_last_reload_bullets = 0
        elif animation_id == "reload":
            soldier_ammo_count = 0
            soldier_reloading = True
            soldier_reload_timer = max(1, SOLDIER_RELOAD_TIME // 2)
            soldier_last_reload_bullets = 0
        elif animation_id == "emergency":
            soldier_ammo_count = soldier_max_ammo
            soldier_reloading = False
            soldier_reload_timer = SOLDIER_RELOAD_TIME
            soldier_last_reload_bullets = 0
            soldier_emergency_supply_toast_timer = 70
        else:
            soldier_ammo_count = soldier_max_ammo
            soldier_reloading = False
            soldier_reload_timer = SOLDIER_RELOAD_TIME
            soldier_last_reload_bullets = 0

    return _get_soldier_weapon_ui_preview_rect()


def _configure_soldier_supply_preview() -> tuple[pygame.Rect, pygame.Rect]:
    supply_drop_state.active = False
    supply_drop_state.timer = 0
    supply_runtime.hold_active = True

    threshold = supply_drop_state.config.hold_threshold
    required = supply_drop_state.config.hold_required
    progress = threshold + max(1, int((required - threshold) * 0.65))
    supply_drop_state.hold_time = progress
    supply_drop_state.radio_motion = True
    supply_drop_state.radio_duration = 45
    supply_drop_state.radio_timer = 45

    player_width = PADDLE_WIDTH
    player_height = PADDLE_HEIGHT
    player_x = WIDTH // 2 - player_width // 2
    player_y = HEIGHT - 220
    PLAYER.update(player_x, player_y, player_width, player_height)

    gauge_width = 80
    gauge_height = 12
    player_center_x = PLAYER.centerx
    player_top = PLAYER.top
    gauge_x = player_center_x - gauge_width // 2 - 6
    gauge_y = player_top - 52
    gauge_rect = pygame.Rect(gauge_x, gauge_y, gauge_width + 12, gauge_height + 54)

    radio_rect = pygame.Rect(player_center_x - 80, PLAYER.centery - 120, 160, 170)
    preview_rect = gauge_rect.union(radio_rect)
    preview_rect.clamp_ip(pygame.Rect(0, 0, WIDTH, HEIGHT))
    return gauge_rect, preview_rect


def _blit_scaled_preview(
    source_surface: pygame.Surface,
    region: pygame.Rect,
    target_surface: pygame.Surface,
    target_rect: pygame.Rect,
) -> bool:
    region = region.clamp(source_surface.get_rect())
    if region.width <= 0 or region.height <= 0:
        return False

    preview_surface = pygame.Surface((region.width, region.height), pygame.SRCALPHA)
    preview_surface.blit(source_surface, (0, 0), area=region)
    scaled = pygame.transform.smoothscale(preview_surface, (target_rect.width, target_rect.height))
    target_surface.blit(scaled, target_rect)
    return True


def _render_soldier_genie_preview(
    surface: pygame.Surface,
    rect: pygame.Rect,
    animation_id: str,
) -> bool:
    if animation_id not in {"fire", "reload", "switch", "supply", "emergency"}:
        return False

    snapshot = _snapshot_soldier_genie_state()
    temp_surface = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)

    try:
        if animation_id == "supply":
            _, preview_rect = _configure_soldier_supply_preview()
            draw_supply_drop_gauge(temp_surface)
            draw_supply_radio_motion(temp_surface)
            return _blit_scaled_preview(temp_surface, preview_rect, surface, rect)

        preview_rect = _configure_soldier_weapon_preview(animation_id)
        draw_soldier_weapon_ui(temp_surface)
        return _blit_scaled_preview(temp_surface, preview_rect, surface, rect)
    finally:
        _restore_soldier_genie_state(snapshot)


def _render_genie_animation_preview(surface: pygame.Surface, rect: pygame.Rect, animation_id: str, ticks: int) -> bool:
    if animation_id == "thor_shield":
        return _render_thor_shield_preview(surface, rect)
    if animation_id == "blacksmith_turret":
        return _render_blacksmith_turret_preview(surface, rect)
    if animation_id == "blacksmith_divine":
        return _render_blacksmith_divine_preview(surface, rect)
    if animation_id == "blacksmith_hammer_shock":
        return _render_blacksmith_hammer_preview(surface, rect)
    if animation_id == "blacksmith_build":
        return _render_blacksmith_build_preview(surface, rect)
    if animation_id in {"smasher_drive", "smasher_power"}:
        return _render_smasher_genie_preview(surface, rect, animation_id, ticks)
    if animation_id in {"fire", "reload", "switch", "supply", "emergency"}:
        return _render_soldier_genie_preview(surface, rect, animation_id)
    return False

try:
    genie_assistant.set_preview_renderer(_render_genie_animation_preview)
except NameError:
    pass

blacksmith_hammer_available = True
blacksmith_hammer_shock_charging = False
blacksmith_hammer_shock_charge_frames = 0
blacksmith_hammer_shock_stage = 0
blacksmith_hammer_shock_cooldown_timer = 0
blacksmith_hammer_shock_projectiles = []
blacksmith_hammer_shock_anchor_x = 0
blacksmith_hammer_shock_anchor_y = 0

# Ground crack effects initialization
blacksmith_ground_cracks = []
blacksmith_hammer_shock_particles = []  # Particles for crack shatter effects

blacksmith_construction_sound_playing = False
blacksmith_construction_channel = None

# 발토르 전용 상태/컨트롤러 초기화
BLACKSMITH_CONTROLLER = BlacksmithController(sys.modules[__name__])
BLACKSMITH_CONTROLLER.sync_from_globals()

BLACKSMITH_OVERDRIVE_GRADIENT_SURFACE = None
BLACKSMITH_OVERDRIVE_VIGNETTE_SURFACE = None


def sync_blacksmith_state(*, include_audio: bool = False) -> None:
    """전역 → 상태 객체 동기화.

    Args:
        include_audio: True면 오디오 상태도 동기화. 기본값 False로
                      오디오 상태가 글로벌 변수에 의해 덮어쓰이는 것을 방지.
    """
    if include_audio:
        BLACKSMITH_CONTROLLER.sync_from_globals()
    else:
        # 오디오 상태 제외하고 동기화 (오디오는 별도로 관리)
        BLACKSMITH_CONTROLLER.sync_from_globals(
            exclude_attrs=("blacksmith_construction_sound_playing", "blacksmith_construction_channel")
        )


def push_blacksmith_state() -> None:
    """상태 객체 → 전역 동기화."""
    BLACKSMITH_CONTROLLER.apply_to_globals()


def _clone_rect(rect):
    try:
        return rect.copy() if rect is not None else None
    except Exception:
        return None


def _capture_blacksmith_structures_for_persist() -> dict | None:
    """현재 발토르 건축물 상태를 다음 스테이지로 넘기기 위해 스냅샷한다."""
    sync_blacksmith_state()
    state = BLACKSMITH_CONTROLLER.state
    snapshot: dict = {}

    # 포탑 상태 스냅샷 (완성된 포탑만)
    if state.turret.active and isinstance(state.turret.state, dict):
        tstate = dict(state.turret.state)
        if tstate.get("rect") is not None:
            tstate["rect"] = _clone_rect(tstate.get("rect"))
        # 프레임/연기/과열 등 일시 상태는 초기화
        tstate["overheat_timer"] = 0
        tstate["overheat_smoke_timer"] = 0
        tstate["overdrive_active"] = False
        snapshot["turret"] = tstate
        try:
            snapshot["turret_x"] = int(tstate["rect"].centerx)
        except Exception:
            pass

    # 디바인 스톤 상태 스냅샷 (필드에 존재할 때만)
    divine_state = state.divine.state or blacksmith_divine_stone_state
    if _is_divine_state_active(divine_state):
        dstate = dict(divine_state)
        if dstate.get("rect") is not None:
            dstate["rect"] = _clone_rect(dstate.get("rect"))
        snapshot["divine"] = dstate
        try:
            snapshot["divine_x"] = int(dstate["rect"].centerx)
        except Exception:
            pass

    return snapshot or None


def _restore_blacksmith_structures_from_persist(persist: dict, *, stage_num: int) -> None:
    """스냅샷에서 발토르 건축물을 복원한다."""
    state = BLACKSMITH_CONTROLLER.state

    # 디바인 스톤 복원
    dstate = persist.get("divine")
    if isinstance(dstate, dict):
        # 위치 고정 (X: 저장값, Y: 스테이지 바닥 기준 재계산)
        try:
            rect = dstate["rect"]
            saved_x = int(persist.get("divine_x", rect.centerx))
            anchor_y = HEIGHT - BLACKSMITH_DIVINE_BLUEPRINT_EXTRA_HEIGHT
            rect.midbottom = (
                max(rect.width // 2, min(WIDTH - rect.width // 2, saved_x)),
                anchor_y,
            )
        except Exception:
            pass
        state.divine.state = dstate
        # 현재 스테이지 소유로 업데이트 (활성화 가드 통과용)
        globals()["blacksmith_divine_stage_owner"] = stage_num

    # 포탑 복원
    tstate = persist.get("turret")
    if isinstance(tstate, dict):
        # 위치 고정 (X: 저장값, Y: 스테이지 바닥 기준 재계산)
        try:
            trect = tstate["rect"]
            saved_x = int(persist.get("turret_x", trect.centerx))
            base_y = HEIGHT - 5
            trect.midbottom = (
                max(trect.width // 2, min(WIDTH - trect.width // 2, saved_x)),
                base_y,
            )
        except Exception:
            pass
        state.turret.active = True
        state.turret.blueprint_active = False
        state.turret.state = tstate
        state.turret.projectiles.clear()
        state.turret.manual_cooldown = 0
        state.turret.overheat_timer = 0
        state.turret.overheat_smoke_timer = 0

    # 전역 반영 (그리기/충돌 등 레거시 경로를 위해)
    BLACKSMITH_CONTROLLER.apply_to_globals()

    # 1프레임 보정용 락 포지션 설정 (다른 초기화 경로에서 중앙으로 스냅되는 경우 재보정)
    globals()["blacksmith_persist_lock_pos"] = {
        "turret_x": persist.get("turret_x"),
        "divine_x": persist.get("divine_x"),
        "turret_frames": 6,
        "divine_frames": 6,
    }

def reset_blacksmith_state(*, preserve_divine: bool = False, stage_num: int | None = None) -> None:
    """발토르 전용 런타임 상태 초기화.

    Args:
        preserve_divine: True일 때 동일 스테이지 내에서 디바인스톤 상태를 유지한다.
        stage_num: 현재 스테이지 번호. preserve_divine와 함께 전달되어야 한다.
    """

    # 패들 캐시 초기화 (스테이지/라운드 변경 시)
    clear_blacksmith_paddle_cache()

    stop_blacksmith_construction_sound()

    global blacksmith_divine_stage_owner

    preserved_divine: dict[str, object] | None = None
    if preserve_divine:
        sync_blacksmith_state()
        state = BLACKSMITH_CONTROLLER.state
        divine_runtime = state.divine
        stage_owner = blacksmith_divine_stage_owner

        if stage_owner is not None and (stage_num is None or stage_owner == stage_num):
            preserved_state = None
            if divine_runtime.state is not None:
                preserved_state = dict(divine_runtime.state)
                rect = preserved_state.get("rect")
                if rect is not None:
                    preserved_state["rect"] = rect.copy()

            preserved_blueprint_rect = None
            if divine_runtime.blueprint_rect is not None:
                preserved_blueprint_rect = divine_runtime.blueprint_rect.copy()

            preserved_divine = {
                "state": preserved_state,
                "blueprint_active": divine_runtime.blueprint_active,
                "blueprint_rect": preserved_blueprint_rect,
                "build_progress": divine_runtime.build_progress,
                "partial_drain": divine_runtime.partial_drain,
                "stage_owner": stage_owner,
            }

    BLACKSMITH_CONTROLLER.reset()

    if preserved_divine and (
        preserved_divine["state"] is not None or preserved_divine["blueprint_active"]
    ):
        state = BLACKSMITH_CONTROLLER.state
        divine_runtime = state.divine
        divine_runtime.state = preserved_divine["state"]
        divine_runtime.blueprint_active = preserved_divine["blueprint_active"]
        divine_runtime.blueprint_rect = preserved_divine["blueprint_rect"]
        divine_runtime.build_progress = preserved_divine["build_progress"]
        divine_runtime.partial_drain = preserved_divine["partial_drain"]
        BLACKSMITH_CONTROLLER.apply_to_globals(
            attrs=(
                "blacksmith_divine_stone_state",
                "blacksmith_divine_blueprint_active",
                "blacksmith_divine_blueprint_rect",
                "blacksmith_divine_build_progress",
                "blacksmith_divine_partial_drain",
            )
        )
        blacksmith_divine_stage_owner = preserved_divine["stage_owner"]
    else:
        blacksmith_divine_stage_owner = None

    global blacksmith_hammer_swing_slow_timer
    global blacksmith_hammer_shock_last_stage, blacksmith_hammer_shock_cooldown_total
    global blacksmith_umbrella_gauge, blacksmith_umbrella_recharge_progress
    global blacksmith_umbrella_damage_flash_timer, blacksmith_umbrella_last_hit_frame
    global blacksmith_umbrella_hit_lock
    global blacksmith_umbrella_retract_grace_timer
    global blacksmith_blocking_penalty_timer, blacksmith_blocking_toast_timer
    global blacksmith_blocking_skill_timer, blacksmith_blocking_bonus_pending
    global blacksmith_blocking_bonus_ready, blacksmith_blocking_bonus_window_timer
    global blacksmith_blocking_bonus_ready, blacksmith_blocking_bonus_window_timer
    global blacksmith_blocking_bonus_ready, blacksmith_blocking_bonus_window_timer
    global blacksmith_blocking_bonus_ready, blacksmith_blocking_bonus_window_timer
    global blacksmith_blocking_bonus_ready, blacksmith_blocking_bonus_window_timer
    global blacksmith_blocking_bonus_ready, blacksmith_blocking_bonus_window_timer
    global blacksmith_blocking_bonus_ready, blacksmith_blocking_bonus_window_timer
    blacksmith_hammer_swing_slow_timer = 0
    stop_blacksmith_hammer_charge_sound()
    blacksmith_umbrella_gauge = BLACKSMITH_UMBRELLA_GAUGE_MAX
    blacksmith_umbrella_recharge_progress = 0
    blacksmith_umbrella_damage_flash_timer = 0
    blacksmith_umbrella_last_hit_frame = -1000
    blacksmith_umbrella_retract_start_frame = -1000
    blacksmith_umbrella_retract_grace_timer = 0
    blacksmith_blocking_penalty_timer = 0
    blacksmith_blocking_toast_timer = 0
    blacksmith_blocking_skill_timer = 0
    blacksmith_blocking_bonus_pending = False
    blacksmith_blocking_bonus_ready = False
    blacksmith_blocking_bonus_window_timer = 0
    blacksmith_blocking_bonus_ready = False
    blacksmith_blocking_bonus_window_timer = 0
    blacksmith_umbrella_hit_lock = False
    blacksmith_hammer_shock_last_stage = 0
    blacksmith_hammer_shock_cooldown_total = 0
    global blacksmith_swing_input_buffer
    blacksmith_swing_input_buffer = 0


def start_blacksmith_construction_sound():
    """건설 사운드 재생 시작 또는 재개."""
    if SOUND_CONSTRUCTION is None:
        return

    audio_state = BLACKSMITH_CONTROLLER.state.construction_audio
    channel = audio_state.channel

    # 채널이 있고 활성 상태면 unpause만 하고 리턴
    if channel:
        try:
            # get_busy()는 paused 상태에서도 True를 반환할 수 있음
            # 그래서 무조건 unpause 호출 (이미 재생 중이면 아무 효과 없음)
            channel.unpause()
            audio_state.playing = True
            return
        except Exception:
            # 채널에 문제가 있으면 새로 생성
            audio_state.channel = None
            channel = None

    # 새 채널로 재생 시작
    try:
        channel = SOUND_CONSTRUCTION.play(-1)
    except Exception:
        channel = None

    audio_state.channel = channel
    audio_state.playing = True if channel else False


def stop_blacksmith_construction_sound():
    """건설 사운드 완전 정지."""
    audio_state = BLACKSMITH_CONTROLLER.state.construction_audio

    if not audio_state.channel:
        audio_state.playing = False
        return

    try:
        audio_state.channel.stop()
    except Exception:
        pass

    audio_state.channel = None
    audio_state.playing = False


def pause_blacksmith_construction_sound():
    """건설 사운드 일시정지."""
    audio_state = BLACKSMITH_CONTROLLER.state.construction_audio

    if not audio_state.channel:
        audio_state.playing = False
        return

    try:
        audio_state.channel.pause()
    except Exception:
        pass

    audio_state.playing = False

def create_soldier_paddle_animated(*, include_right_arm: bool = True) -> pygame.Surface:
    """휘두르기 애니메이션이 적용된 코만도 패들 이미지 생성"""
    global soldier_swing_timer

    if SOLDIER_SWING_DURATION <= 0:
        return create_soldier_paddle_surface()

    swing_progress = 1.0 - (soldier_swing_timer / SOLDIER_SWING_DURATION)
    swing_strength = math.sin(max(0.0, min(1.0, swing_progress)) * math.pi)
    right_hook_strength = get_soldier_right_hook_strength()
    return create_soldier_paddle_surface(
        swing_strength=swing_strength,
        right_hook_strength=right_hook_strength,
        include_right_arm=include_right_arm,
    )


def create_soldier_paddle_walking(*, include_right_arm: bool = True) -> pygame.Surface:
    """걷기 애니메이션이 적용된 코만도 패들 이미지 생성"""
    global soldier_walking_timer

    if SOLDIER_WALKING_CYCLE <= 0:
        return create_soldier_paddle_surface()

    phase = (soldier_walking_timer % SOLDIER_WALKING_CYCLE) / SOLDIER_WALKING_CYCLE
    right_hook_strength = get_soldier_right_hook_strength()
    return create_soldier_paddle_surface(
        step_phase=phase,
        right_hook_strength=right_hook_strength,
        include_right_arm=include_right_arm,
    )


