        for i in range(3):
            gy = grip_y + int(grip_h * 0.25) + i * int(grip_h * 0.22)
            pygame.draw.line(icon_surface, grip_dark, (grip_x + 1, gy), (grip_x + grip_w - 1, gy), 1)

        # === 슬라이드/본체 (3D) ===
        body_x = int(size * 0.18)
        body_y = int(size * 0.28)
        body_w = max(14, int(size * 0.58))
        body_h = max(6, int(size * 0.22))

        # 본체 하단 (어두운 부분)
        body_bottom = pygame.Rect(body_x, body_y + int(body_h * 0.5), body_w, int(body_h * 0.5))
        pygame.draw.rect(icon_surface, body_dark, body_bottom)

        # 본체 상단 (밝은 부분)
        body_top = pygame.Rect(body_x, body_y, body_w, int(body_h * 0.55))
        pygame.draw.rect(icon_surface, body_mid, body_top)

        # 하이라이트 라인 (금속 반사)
        pygame.draw.line(icon_surface, body_highlight,
            (body_x + 2, body_y + 1), (body_x + body_w - 2, body_y + 1), 1)

        # 본체 테두리
        full_body = pygame.Rect(body_x, body_y, body_w, body_h)
        pygame.draw.rect(icon_surface, body_dark, full_body, 1)

        # 슬라이드 세레이션 (후방 그립 패턴)
        serration_start = body_x + int(body_w * 0.7)
        for i in range(3):
            sx = serration_start + i * 2
            if sx < body_x + body_w - 2:
                pygame.draw.line(icon_surface, body_dark, (sx, body_y + 2), (sx, body_y + body_h - 2), 1)

        # 이젝션 포트 (탄피 배출구)
        eject_x = body_x + int(body_w * 0.45)
