        # === 총열 (3D) ===
        barrel_x = body_x + body_w
        barrel_y = body_y + int(body_h * 0.25)
        barrel_w = max(5, int(size * 0.18))
        barrel_h = max(3, int(body_h * 0.5))

        # 총열 본체
