        # 총열 하단 그림자
        pygame.draw.line(icon_surface, barrel_dark, (barrel_x, barrel_y + barrel_h - 1), (barrel_x + barrel_w, barrel_y + barrel_h - 1), 1)

        # 총구 (3D 원형)
        muzzle_cx = barrel_x + barrel_w
        muzzle_cy = barrel_y + barrel_h // 2
