        pygame.draw.rect(icon_surface, body_dark, (trigger_x, trigger_y, 2, int(tg_h * 0.8)))

        # === 조준기 (전방 사이트) ===
        sight_x = barrel_x + int(barrel_w * 0.3)
        sight_y = body_y - 2
        sight_w = 2
        sight_h = 2
