        rear_sight_y = body_y - 1
        pygame.draw.rect(icon_surface, body_dark, (rear_sight_x, rear_sight_y, 2, 2))
        pygame.draw.rect(icon_surface, body_dark, (rear_sight_x + 3, rear_sight_y, 2, 2))

