def is_player_in_magnetic_projectile():
    """플레이어가 자기장 발사체 안에 있는지 확인"""
    if not magnetic_projectile_active:
        return False
    # 플레이어 중심과 자기장 발사체 중심 사이의 거리 계산
    dist = math.hypot(PLAYER.centerx - magnetic_projectile_x, PLAYER.centery - magnetic_projectile_y)
    return dist < magnetic_projectile_radius

def apply_magnetic_distortion(surface, intensity=1.0):
    """자기장 발사체 안에 있을 때 물속 같은 왜곡 효과 적용"""
    if surface is None:
        return surface

    width, height = surface.get_size()
    if width <= 0 or height <= 0:
        return surface

    # 왜곡된 서페이스 생성
    distorted = pygame.Surface((width, height), pygame.SRCALPHA)

    electric_time = pygame.time.get_ticks()

    # 물결 왜곡 파라미터
    wave_amp_x = 3 * intensity  # X축 왜곡 진폭
    wave_amp_y = 2 * intensity  # Y축 왜곡 진폭
    wave_freq = 0.15  # 물결 주파수
    time_factor = electric_time * 0.008  # 시간에 따른 물결 움직임

    # 세로 줄 단위로 왜곡 적용 (성능 최적화)
    for x in range(0, width, 2):
        # 사인파를 이용한 Y축 오프셋
        offset_y = int(wave_amp_y * math.sin(x * wave_freq + time_factor))
        # 사인파를 이용한 X축 왜곡 (물결 효과)
        offset_x = int(wave_amp_x * math.sin((x + electric_time * 0.01) * wave_freq * 0.7))

        # 원본에서 세로 줄 복사
        src_x = max(0, min(width - 2, x + offset_x))
        strip = surface.subsurface(pygame.Rect(src_x, 0, min(2, width - src_x), height))

        # 왜곡된 위치에 그리기
        dest_y = offset_y
        distorted.blit(strip, (x, dest_y))

    # 청록색 틴트 오버레이 (물속 느낌)
    tint_surface = pygame.Surface((width, height), pygame.SRCALPHA)
    pulse = 0.5 + 0.3 * math.sin(electric_time * 0.005)
    tint_alpha = int(40 * pulse * intensity)
    tint_surface.fill((100, 200, 255, tint_alpha))
    distorted.blit(tint_surface, (0, 0), special_flags=pygame.BLEND_RGBA_ADD)

    return distorted

