def activate_stopwatch():
    """스탑워치 활성화 - 2초간 모든 것 정지 후 1초간 속도 회복"""
    global stopwatch_active, stopwatch_timer, stopwatch_flash_timer
    global stopwatch_original_ball_vel, stopwatch_recovery_timer, stopwatch_clock_angle
    global ball_vel, BALL, PLAYER
    global player_collision_handled, player_collision_cooldown, boss_collision_cooldown
    global current_speed
    
    # 패들과 공 사이 안전 거리 확인
    MIN_SAFE_DISTANCE = 35  # 최소 안전 거리
    if BALL and PLAYER:
        x_distance = abs(BALL.centerx - PLAYER.centerx)
        y_distance = abs(BALL.centery - PLAYER.centery)
        
        # 너무 가까우면 발동하지 않음
        if x_distance <= MIN_SAFE_DISTANCE and y_distance <= MIN_SAFE_DISTANCE:
            if DEBUG_MODE:
                print(f"[스탑워치] 발동 취소 - 패들과 너무 가까움 (X:{x_distance:.0f}, Y:{y_distance:.0f})")
            return False
    
    if not stopwatch_active and BALL:
        stopwatch_active = True
        stopwatch_timer = STOPWATCH_DURATION  # 2초
        stopwatch_recovery_timer = 0
        stopwatch_flash_timer = 10  # 화면 번쩍임 효과
        stopwatch_clock_angle = 0
        
        # 타임워치 발동 사운드 재생
        try:
            play_sound_with_volume(SOUND_TIMEWATCH)  # ️ 타임워치 발동 사운드
        except:
            pass
        
        # 원래 공 속도 저장
        stopwatch_original_ball_vel = ball_vel.copy() if ball_vel else [0, 0]
        
        # 공 정지
        ball_vel = [0, 0]
        
        # 플레이어 이동 속도도 정지 (스탑워치 중 속도 누적 방지)
        current_speed = 0
        
        # 충돌 플래그 리셋 (스탑워치 시작 시 충돌 상태 초기화)
        player_collision_handled = False
        player_collision_cooldown = 0
        boss_collision_cooldown = 0
        
        # 효과음 재생
        play_active_item_sound()
        
        print("!   ...")
        return True
    
    return False

def draw_stopwatch_effect():
    """스탑워치 시계 애니메이션 그리기"""
    global stopwatch_clock_angle, stopwatch_flash_timer
    
    if not stopwatch_active:
        return
    
    # 화면 번쩍임 효과
    if stopwatch_flash_timer > 0:
        flash_surface = pygame.Surface((WIDTH, HEIGHT))
        flash_surface.fill((255, 255, 200))
        flash_surface.set_alpha(stopwatch_flash_timer * 25)
        SCREEN.blit(flash_surface, (0, 0))
        stopwatch_flash_timer -= 1
    
    # 상단에 시계 그리기
    clock_x = WIDTH // 2
    clock_y = 100
    clock_radius = 60
    
    # 시계 배경 (반투명)
    clock_bg = pygame.Surface((clock_radius * 2 + 20, clock_radius * 2 + 20), pygame.SRCALPHA)
    pygame.draw.circle(clock_bg, (0, 0, 0, 150), (clock_radius + 10, clock_radius + 10), clock_radius + 10)
    SCREEN.blit(clock_bg, (clock_x - clock_radius - 10, clock_y - clock_radius - 10))
    
    # 시계 테두리
    pygame.draw.circle(SCREEN, (180, 140, 90), (clock_x, clock_y), clock_radius, 4)
    pygame.draw.circle(SCREEN, (220, 180, 120), (clock_x, clock_y), clock_radius - 2, 2)
    
    # 시계 문자판
    pygame.draw.circle(SCREEN, (255, 255, 240), (clock_x, clock_y), clock_radius - 8)
    
    # 시간 표시 (12, 3, 6, 9)
    try:
        clock_font = pygame.font.Font(get_pixel_font_path(), 16)
    except:
        clock_font = pygame.font.Font(None, 16)
    
    for i, num in enumerate(['12', '3', '6', '9']):
        angle = i * math.pi / 2 - math.pi / 2
        text_x = clock_x + int((clock_radius - 20) * math.cos(angle))
        text_y = clock_y + int((clock_radius - 20) * math.sin(angle))
        
        text = clock_font.render(num, True, (80, 60, 40))
        text_rect = text.get_rect(center=(text_x, text_y))
        SCREEN.blit(text, text_rect)
    
    # 시침 (천천히 회전)
    hour_angle = stopwatch_clock_angle * 0.5
    hour_end_x = clock_x + int(30 * math.cos(hour_angle - math.pi/2))
    hour_end_y = clock_y + int(30 * math.sin(hour_angle - math.pi/2))
    pygame.draw.line(SCREEN, (40, 30, 20), (clock_x, clock_y), (hour_end_x, hour_end_y), 4)
    
    # 분침 (빠르게 회전)
    minute_angle = stopwatch_clock_angle * 2
    minute_end_x = clock_x + int(45 * math.cos(minute_angle - math.pi/2))
    minute_end_y = clock_y + int(45 * math.sin(minute_angle - math.pi/2))
    pygame.draw.line(SCREEN, (40, 30, 20), (clock_x, clock_y), (minute_end_x, minute_end_y), 2)
    
    # 초침 (매우 빠르게 회전)
    second_angle = stopwatch_clock_angle * 6
    second_end_x = clock_x + int(50 * math.cos(second_angle - math.pi/2))
    second_end_y = clock_y + int(50 * math.sin(second_angle - math.pi/2))
    pygame.draw.line(SCREEN, (255, 0, 0), (clock_x, clock_y), (second_end_x, second_end_y), 1)
    
    # 중앙 나사
    pygame.draw.circle(SCREEN, (60, 40, 20), (clock_x, clock_y), 3)
    
    # 남은 시간 텍스트 (비활성화)
    # if stopwatch_timer > 0:
    #     time_text = f"시간 정지: {stopwatch_timer / 60:.1f}초"
    # else:
    #     time_text = f"속도 회복 중: {stopwatch_recovery_timer / 60:.1f}초"
    # 
    # time_surface = clock_font.render(time_text, True, (255, 255, 255))
