AIPILL_ALLOWED_DEACTIVATION_REASONS = {"gauge_depleted", "round_transition"}
aipill_last_deactivation_reason = None

AIPILL_BLOCKED_KEYS = (
    pygame.K_SPACE,
    pygame.K_UP,
    pygame.K_DOWN,
    pygame.K_LEFT,
    pygame.K_RIGHT,
)
_AIPILL_BLOCKED_KEY_SET = set(AIPILL_BLOCKED_KEYS)

_ORIGINAL_GET_PRESSED = pygame.key.get_pressed


class _KeyStateProxy:
    __slots__ = ("_raw",)

    def __init__(self, raw):
        self._raw = raw

    def __getitem__(self, key):
        if key in _AIPILL_BLOCKED_KEY_SET:
            return 0
        try:
            return self._raw[key]
        except (IndexError, TypeError):
            return 0

    def __len__(self):
        return len(self._raw)

    def __iter__(self):
        for idx, value in enumerate(self._raw):
            yield 0 if idx in _AIPILL_BLOCKED_KEY_SET else value

    def __getattr__(self, name):
        return getattr(self._raw, name)


def _get_effective_key_state_override():
    raw_keys = _ORIGINAL_GET_PRESSED()
    if not aipill_active:
        return raw_keys
    return _KeyStateProxy(raw_keys)


pygame.key.get_pressed = _get_effective_key_state_override


def activate_aipill(source: str | None = None) -> bool:
    """Activate AI pill effect if not already active."""

    global aipill_active, aipill_last_deactivation_reason

    if not aipill_active:
        aipill_active = True
        aipill_last_deactivation_reason = None
    else:
        # 효과가 이미 유지 중이라면 최근 종료 원인만 초기화
        aipill_last_deactivation_reason = None
    return True


def deactivate_aipill(reason: str, *, allow_override: bool = False) -> bool:
    """Disable AI pill effect only for approved reasons."""

    global aipill_active, aipill_last_deactivation_reason

    if not allow_override and reason not in AIPILL_ALLOWED_DEACTIVATION_REASONS:
        # 허용되지 않은 종료 요청은 무시하고 상태를 유지한다.
        aipill_last_deactivation_reason = f"ignored:{reason}"
        return False

    if not aipill_active:
        if allow_override:
            # 외부 초기화 흐름에서는 도핑 물약만 정리
            deactivate_doping_potion()
        return False

    aipill_active = False
    aipill_last_deactivation_reason = reason
    deactivate_doping_potion()
    return True
