def draw_soldier_gun_animation(screen, paddle_rect):
    """코만도 총 발사 애니메이션 그리기"""
    global soldier_gun_animation_active, soldier_gun_animation_frame
    global soldier_gun_target_x, soldier_gun_target_y
    global soldier_gun_muzzle_x, soldier_gun_muzzle_y

    if not soldier_gun_animation_active:
        return

    Vector2 = pygame.math.Vector2

    def clamp(value: float, minimum: float, maximum: float) -> float:
        return max(minimum, min(maximum, value))

    def ease_out_cubic(t: float) -> float:
        t = clamp(t, 0.0, 1.0)
        return 1.0 - (1.0 - t) ** 3

    def ease_in_out(t: float) -> float:
        t = clamp(t, 0.0, 1.0)
        return t * t * (3.0 - 2.0 * t)

    def lerp_vec(a: Vector2, b: Vector2, t: float) -> Vector2:
        return a + (b - a) * clamp(t, 0.0, 1.0)

    def to_int_pair(vec: Vector2) -> tuple[int, int]:
        return int(round(vec.x)), int(round(vec.y))

    # 기본 좌표 세팅
    paddle_center_x = paddle_rect.centerx
    paddle_center_y = paddle_rect.centery

    shoulder = Vector2(paddle_center_x + 28, paddle_center_y - 18)
    pocket_hand = shoulder + Vector2(-6, 18)
    ready_hand = shoulder + Vector2(4, 14)

    pocket_elbow = shoulder + Vector2(2, 14)
    ready_elbow = shoulder + Vector2(6, 12)

    target_vec = Vector2(soldier_gun_target_x, soldier_gun_target_y)
    if abs(soldier_gun_target_x) < 0.1 and abs(soldier_gun_target_y) < 0.1:
        target_vec = Vector2(paddle_center_x + 220, paddle_center_y - 40)

    aim_dir = target_vec - shoulder
    if aim_dir.length_squared() < 1e-4:
        aim_dir = Vector2(1, -0.25)
    aim_dir = aim_dir.normalize()

    arm_reach = 20.0
    aim_hand = shoulder + aim_dir * arm_reach
    perp = Vector2(-aim_dir.y, aim_dir.x)
    aim_elbow = shoulder + aim_dir * 9.0 + perp * -5.0 + Vector2(0, 8)

    target_angle = math.atan2(aim_dir.y, aim_dir.x)

    # 현재 애니메이션 단계 확인
    current_stage = SOLDIER_GUN_STAGE_DRAW
    if soldier_gun_animation_frame >= SOLDIER_GUN_DRAW_FRAMES:
        current_stage = SOLDIER_GUN_STAGE_AIM
    if soldier_gun_animation_frame >= SOLDIER_GUN_DRAW_FRAMES + SOLDIER_GUN_AIM_FRAMES:
        current_stage = SOLDIER_GUN_STAGE_FIRE

    hand = ready_hand
    elbow = ready_elbow
    pistol_angle = target_angle
    barrel_visibility = 1.0
    fire_flash_progress = None

    if current_stage == SOLDIER_GUN_STAGE_DRAW:
        frame_progress = soldier_gun_animation_frame / max(1, SOLDIER_GUN_DRAW_FRAMES - 1)
        lift_progress = ease_out_cubic(frame_progress)
        hand = lerp_vec(pocket_hand, ready_hand, lift_progress)
        elbow = lerp_vec(pocket_elbow, ready_elbow, lift_progress)

        holster_angle = math.radians(95)
        ready_angle = math.radians(-16)
        pistol_angle = holster_angle + (ready_angle - holster_angle) * lift_progress
        barrel_visibility = 0.55 + 0.45 * lift_progress

    elif current_stage == SOLDIER_GUN_STAGE_AIM:
        frame_progress = (soldier_gun_animation_frame - SOLDIER_GUN_DRAW_FRAMES) / max(1, SOLDIER_GUN_AIM_FRAMES - 1)
        aim_progress = ease_in_out(frame_progress)
        hand = lerp_vec(ready_hand, aim_hand, aim_progress)
        elbow = lerp_vec(ready_elbow, aim_elbow, aim_progress)

        ready_angle = math.radians(-16)
        pistol_angle = ready_angle + (target_angle - ready_angle) * aim_progress

    else:  # SOLDIER_GUN_STAGE_FIRE
        frame_progress = (soldier_gun_animation_frame - (SOLDIER_GUN_DRAW_FRAMES + SOLDIER_GUN_AIM_FRAMES)) / max(1, SOLDIER_GUN_FIRE_FRAMES - 1)
        fire_progress = clamp(frame_progress, 0.0, 1.0)
        recoil = math.sin(fire_progress * math.pi)

        hand = lerp_vec(aim_hand, aim_hand - aim_dir * 5.0, 0.35 * recoil)
        elbow = lerp_vec(aim_elbow, aim_elbow - aim_dir * 3.0 + Vector2(2.0, -4.0), 0.5 * recoil)
        pistol_angle = target_angle - math.radians(6.0) * recoil
        fire_flash_progress = fire_progress

    shoulder_pt = to_int_pair(shoulder)
    elbow_pt = to_int_pair(elbow)
    hand_pt = to_int_pair(hand)

    # 기본 스프라이트의 팔색과 맞추기 위해 갈색 톤 사용
    arm_mid_color = (124, 108, 74)
    arm_shadow_color = (96, 84, 54)
    glove_color = (206, 182, 150)
    glove_outline = (172, 144, 118)

    pygame.draw.line(screen, arm_shadow_color, shoulder_pt, elbow_pt, 9)
    pygame.draw.line(screen, arm_mid_color, shoulder_pt, elbow_pt, 6)
    pygame.draw.line(screen, arm_shadow_color, elbow_pt, hand_pt, 8)
    pygame.draw.line(screen, arm_mid_color, elbow_pt, hand_pt, 5)

    pygame.draw.circle(screen, glove_color, hand_pt, 6)
    pygame.draw.circle(screen, glove_outline, hand_pt, 6, 2)

    # 권총 렌더링 (손바닥 중심에서 자연스러운 각도로 배치)
    dir_vec = Vector2(math.cos(pistol_angle), math.sin(pistol_angle))
    normal_vec = Vector2(-dir_vec.y, dir_vec.x)

    grip_base = hand - dir_vec * 2.0 + normal_vec * 2.5
    barrel_start = hand + dir_vec * (6.0 + 4.0 * barrel_visibility) + normal_vec * -2.5
    barrel_length = 16.0 + 6.0 * barrel_visibility
    muzzle = barrel_start + dir_vec * barrel_length
    slide_top = barrel_start + dir_vec * (barrel_length * 0.65)
    grip_end = grip_base + normal_vec * 6.0 + dir_vec * -4.0

    body_color = (46, 46, 48)
    highlight_color = (126, 126, 132)

    pygame.draw.line(screen, body_color, to_int_pair(barrel_start), to_int_pair(muzzle), 6)
    pygame.draw.line(screen, highlight_color, to_int_pair(barrel_start), to_int_pair(slide_top), 2)
    pygame.draw.line(screen, body_color, to_int_pair(grip_base), to_int_pair(grip_end), 4)

    soldier_gun_muzzle_x, soldier_gun_muzzle_y = to_int_pair(muzzle)

    if fire_flash_progress is not None and fire_flash_progress < 0.5:
        flash_strength = 1.0 - fire_flash_progress * 2.0
        flame_length = 22.0 * flash_strength
        flame_end = muzzle + dir_vec * flame_length
        core_end = muzzle + dir_vec * (flame_length * 0.55)

        flame_color = (
            255,
            int(210 + 45 * flash_strength),
            int(64 * flash_strength),
        )
        pygame.draw.line(screen, flame_color, to_int_pair(muzzle), to_int_pair(flame_end), 6)
        pygame.draw.line(screen, (255, 255, 255), to_int_pair(muzzle), to_int_pair(core_end), 3)


# === 새총 차징/발사 포즈 애니메이션 ===
slingshot_fire_anim_timer = 0  # 발사 후 반동 애니메이션 타이머
SLINGSHOT_FIRE_ANIM_DURATION = 12  # 발사 반동 지속 (0.2초)
slingshot_fire_muzzle_x = 0  # 발사 시 새총 끝 좌표 (탄환 스폰용)
slingshot_fire_muzzle_y = 0


def draw_slingshot_pose(screen, paddle_rect):
    """코만도 새총 차징/발사 포즈 그리기
    - 차징 중: 왼손 앞으로 새총, 오른손 뒤로 시위 당기기
    - 발사 시: 시위 놓으면서 반동
    """
    global slingshot_fire_anim_timer, slingshot_fire_muzzle_x, slingshot_fire_muzzle_y

    is_charging = slingshot_charging and slingshot_charge_level >= 0
    is_fire_recoil = slingshot_fire_anim_timer > 0

    if not is_charging and not is_fire_recoil:
        return

    Vector2 = pygame.math.Vector2

    def clamp(v, lo, hi):
        return max(lo, min(hi, v))

    def to_int(vec):
        return int(round(vec.x)), int(round(vec.y))

    pcx = paddle_rect.centerx
    pcy = paddle_rect.centery

    # 보스 방향 계산
    target = Vector2(BOSS.centerx, BOSS.centery)
    aim_dir = target - Vector2(pcx, pcy)
    if aim_dir.length_squared() < 1:
        aim_dir = Vector2(0, -1)
    aim_dir = aim_dir.normalize()
    perp = Vector2(-aim_dir.y, aim_dir.x)  # 직교 벡터

    # 어깨 기준점
    shoulder_l = Vector2(pcx - 12, pcy - 16)  # 왼쪽 어깨 (새총 잡는 손)
    shoulder_r = Vector2(pcx + 12, pcy - 16)  # 오른쪽 어깨 (시위 당기는 손)

    # 색상
    arm_mid = (124, 108, 74)
    arm_shadow = (96, 84, 54)
    glove_color = (206, 182, 150)
    glove_outline = (172, 144, 118)
    frame_mid = (65, 72, 58)
    frame_dark = (40, 45, 38)
    band_outer = (60, 55, 45)
    band_inner = (140, 120, 70)
    bolt_col = (100, 100, 110)

    if is_charging:
        charge_ratio = get_slingshot_charge_ratio()
        charge_t = clamp(charge_ratio, 0, 1)

        # === 왼팔: 보스 방향으로 뻗으며 새총을 들고 있음 ===
        left_reach = 20 + 8 * charge_t  # 차징 높을수록 더 뻗음
        left_hand = shoulder_l + aim_dir * left_reach
        left_elbow = shoulder_l + aim_dir * (left_reach * 0.5) + Vector2(0, 5)

        # 왼팔 그리기
        pygame.draw.line(screen, arm_shadow, to_int(shoulder_l), to_int(left_elbow), 8)
        pygame.draw.line(screen, arm_mid, to_int(shoulder_l), to_int(left_elbow), 5)
        pygame.draw.line(screen, arm_shadow, to_int(left_elbow), to_int(left_hand), 7)
        pygame.draw.line(screen, arm_mid, to_int(left_elbow), to_int(left_hand), 4)
        pygame.draw.circle(screen, glove_color, to_int(left_hand), 5)
        pygame.draw.circle(screen, glove_outline, to_int(left_hand), 5, 1)

        # === 새총 프레임 (왼손 끝에서 보스 방향) ===
        fork_len = 10
        fork_spread = 6
        fork_base = left_hand + aim_dir * 2
        fork_tip_l = fork_base + aim_dir * fork_len + perp * fork_spread
        fork_tip_r = fork_base + aim_dir * fork_len - perp * fork_spread

        # 프레임 몸체 (손잡이 → 갈래)
        pygame.draw.line(screen, frame_mid, to_int(fork_base - aim_dir * 4), to_int(fork_base), 4)
        pygame.draw.line(screen, frame_dark, to_int(fork_base - aim_dir * 4), to_int(fork_base), 4)
        # Y자 갈래
        pygame.draw.line(screen, frame_mid, to_int(fork_base), to_int(fork_tip_l), 3)
        pygame.draw.line(screen, frame_mid, to_int(fork_base), to_int(fork_tip_r), 3)
        pygame.draw.line(screen, frame_dark, to_int(fork_base), to_int(fork_tip_l), 1)
        pygame.draw.line(screen, frame_dark, to_int(fork_base), to_int(fork_tip_r), 1)
        # 갈래 끝 볼트
        pygame.draw.circle(screen, bolt_col, to_int(fork_tip_l), 2)
        pygame.draw.circle(screen, bolt_col, to_int(fork_tip_r), 2)

        # === 오른팔: 시위를 어깨 뒤로 당김 ===
        pull_back = 8 + 18 * charge_t  # 차징 높을수록 뒤로 많이 당김
        right_hand = shoulder_r - aim_dir * pull_back + Vector2(0, -2 * charge_t)
        right_elbow = shoulder_r - aim_dir * (pull_back * 0.45) + Vector2(0, 8)

        # 오른팔 그리기
        pygame.draw.line(screen, arm_shadow, to_int(shoulder_r), to_int(right_elbow), 8)
        pygame.draw.line(screen, arm_mid, to_int(shoulder_r), to_int(right_elbow), 5)
        pygame.draw.line(screen, arm_shadow, to_int(right_elbow), to_int(right_hand), 7)
        pygame.draw.line(screen, arm_mid, to_int(right_elbow), to_int(right_hand), 4)
        pygame.draw.circle(screen, glove_color, to_int(right_hand), 5)
        pygame.draw.circle(screen, glove_outline, to_int(right_hand), 5, 1)

        # === 밴드 (갈래 끝 → 오른손) ===
        pygame.draw.line(screen, band_outer, to_int(fork_tip_l), to_int(right_hand), 3)
        pygame.draw.line(screen, band_outer, to_int(fork_tip_r), to_int(right_hand), 3)
        pygame.draw.line(screen, band_inner, to_int(fork_tip_l), to_int(right_hand), 1)
        pygame.draw.line(screen, band_inner, to_int(fork_tip_r), to_int(right_hand), 1)

        # === 차징 중 탄환 (오른손 위치에 표시) ===
        if slingshot_charge_level > 0:
            pr = 3 + slingshot_charge_level
            if slingshot_charge_level == 3:
                pc = (255, 200, 100)
            elif slingshot_charge_level == 2:
                pc = (200, 200, 210)
            else:
                pc = SLINGSHOT_PELLET_COLOR
            pygame.draw.circle(screen, pc, to_int(right_hand), pr)
            pygame.draw.circle(screen, frame_dark, to_int(right_hand), pr, 1)
            # 3단계 글로우
            if slingshot_charge_level == 3:
                gs = pygame.Surface((pr * 4, pr * 4), pygame.SRCALPHA)
                pygame.draw.circle(gs, (255, 200, 50, 60), (pr * 2, pr * 2), pr * 2)
                screen.blit(gs, (int(right_hand.x) - pr * 2, int(right_hand.y) - pr * 2))

        # 발사 위치 저장 (새총 갈래 끝 중간)
        muzzle_pos = (fork_tip_l + fork_tip_r) * 0.5 + aim_dir * 4
        slingshot_fire_muzzle_x = int(muzzle_pos.x)
        slingshot_fire_muzzle_y = int(muzzle_pos.y)

    elif is_fire_recoil:
        # === 발사 후 반동 (시위 놓은 후 튕김) ===
        recoil_t = slingshot_fire_anim_timer / SLINGSHOT_FIRE_ANIM_DURATION
        snap_t = math.sin(recoil_t * math.pi)  # 튕기는 효과

        # 왼팔 (뻗은 상태 유지 + 약간 반동)
        left_recoil = 2 * snap_t  # 발사 반동으로 약간 뒤로
        left_hand = shoulder_l + aim_dir * (28 - left_recoil)
        left_elbow = shoulder_l + aim_dir * (14 - left_recoil * 0.5) + Vector2(0, 5)
        pygame.draw.line(screen, arm_shadow, to_int(shoulder_l), to_int(left_elbow), 8)
        pygame.draw.line(screen, arm_mid, to_int(shoulder_l), to_int(left_elbow), 5)
        pygame.draw.line(screen, arm_shadow, to_int(left_elbow), to_int(left_hand), 7)
        pygame.draw.line(screen, arm_mid, to_int(left_elbow), to_int(left_hand), 4)
        pygame.draw.circle(screen, glove_color, to_int(left_hand), 5)
        pygame.draw.circle(screen, glove_outline, to_int(left_hand), 5, 1)

        # 새총 프레임 (왼손 끝)
        fork_base = left_hand + aim_dir * 2
        fork_tip_l = fork_base + aim_dir * 10 + perp * 6
        fork_tip_r = fork_base + aim_dir * 10 - perp * 6
        pygame.draw.line(screen, frame_mid, to_int(fork_base - aim_dir * 4), to_int(fork_base), 4)
        pygame.draw.line(screen, frame_mid, to_int(fork_base), to_int(fork_tip_l), 3)
        pygame.draw.line(screen, frame_mid, to_int(fork_base), to_int(fork_tip_r), 3)
        pygame.draw.circle(screen, bolt_col, to_int(fork_tip_l), 2)
        pygame.draw.circle(screen, bolt_col, to_int(fork_tip_r), 2)

        # 밴드 (발사 후 앞으로 튕김)
        band_snap = fork_base + aim_dir * (12 * snap_t)
        pygame.draw.line(screen, band_outer, to_int(fork_tip_l), to_int(band_snap), 2)
        pygame.draw.line(screen, band_outer, to_int(fork_tip_r), to_int(band_snap), 2)

        # 오른팔 (발사 후 빠르게 복귀)
        right_hand = shoulder_r - aim_dir * (6 * recoil_t)
        right_elbow = shoulder_r - aim_dir * (3 * recoil_t) + Vector2(0, 8)
        pygame.draw.line(screen, arm_shadow, to_int(shoulder_r), to_int(right_elbow), 8)
        pygame.draw.line(screen, arm_mid, to_int(shoulder_r), to_int(right_elbow), 5)
        pygame.draw.line(screen, arm_shadow, to_int(right_elbow), to_int(right_hand), 7)
        pygame.draw.line(screen, arm_mid, to_int(right_elbow), to_int(right_hand), 4)
        pygame.draw.circle(screen, glove_color, to_int(right_hand), 5)
        pygame.draw.circle(screen, glove_outline, to_int(right_hand), 5, 1)

        slingshot_fire_anim_timer -= 1


def draw_ak47_firing_pose(screen, paddle_rect, boss_rect):
    """코만도 AK-47 발사 포즈 애니메이션 그리기 - 양손으로 AK-47을 잡고 발사"""
    global ak47_firing_pose_active, ak47_firing_recoil_phase, ak47_last_fire_time

    ak47 = get_ak47_instance()
    if not ak47.active:
        ak47_firing_pose_active = False
        return

    is_firing = ak47.is_firing if hasattr(ak47, 'is_firing') else False
    current_time = pygame.time.get_ticks()

    # 발사 중일 때 반동 위상 증가
    if is_firing and ak47.current_ammo > 0:
        ak47_firing_pose_active = True
        ak47_firing_recoil_phase = min(1.0, ak47_firing_recoil_phase + 0.3)
        ak47_last_fire_time = current_time
    else:
        # 발사 중지 시 반동 회복
        ak47_firing_recoil_phase = max(0.0, ak47_firing_recoil_phase - AK47_RECOIL_RECOVERY_SPEED)
        if ak47_firing_recoil_phase <= 0:
            ak47_firing_pose_active = False

    if not ak47_firing_pose_active and not is_firing:
        return

    Vector2 = pygame.math.Vector2

    def clamp(value, minimum, maximum):
        return max(minimum, min(maximum, value))

    def to_int_pair(vec):
        return int(round(vec.x)), int(round(vec.y))

    # 플레이어 중심 좌표
    paddle_center_x = paddle_rect.centerx
    paddle_center_y = paddle_rect.centery

    # 조준 방향 계산 (보스 쪽으로)
    if boss_rect:
        target_x = boss_rect.centerx
        target_y = boss_rect.centery
    else:
        target_x = paddle_center_x
        target_y = 0  # 화면 상단

    # === 어깨 위치 (오른쪽 어깨, 왼쪽 어깨) ===
    right_shoulder = Vector2(paddle_center_x + 12, paddle_center_y - 8)
    left_shoulder = Vector2(paddle_center_x - 12, paddle_center_y - 8)

    # 조준 방향 벡터
    aim_dir = Vector2(target_x - paddle_center_x, target_y - paddle_center_y)
    if aim_dir.length_squared() < 1e-4:
        aim_dir = Vector2(0, -1)
    aim_dir = aim_dir.normalize()

    # 총기 각도
    gun_angle = math.atan2(aim_dir.y, aim_dir.x)

    # === 반동 효과 ===
    recoil_shake = 0
    recoil_angle_offset = 0
    if is_firing and ak47_firing_recoil_phase > 0:
        # 연속 발사 시 흔들림 효과
        shake_freq = current_time * 0.08
        recoil_shake = math.sin(shake_freq) * 2 * ak47_firing_recoil_phase
        recoil_angle_offset = math.sin(shake_freq * 1.3) * 0.05 * ak47_firing_recoil_phase

    gun_angle += recoil_angle_offset

    # 총기 방향 벡터 (반동 적용)
    dir_vec = Vector2(math.cos(gun_angle), math.sin(gun_angle))
    perp_vec = Vector2(-dir_vec.y, dir_vec.x)  # 수직 벡터

    # === 총기 위치 (플레이어 우측 어깨 쪽) ===
    gun_center = Vector2(paddle_center_x + 18, paddle_center_y - 8) + dir_vec * 12 + Vector2(0, recoil_shake)

    # === 색상 정의 ===
    # 팔/손 색상
    arm_mid_color = (124, 108, 74)
    arm_shadow_color = (96, 84, 54)
    glove_color = (206, 182, 150)
    glove_outline = (172, 144, 118)

    # AK-47 색상
    wood_color = (100, 65, 35)
    wood_dark = (70, 45, 25)
    metal_color = (45, 45, 50)
    metal_highlight = (80, 80, 88)

    # === 오른손 (방아쇠 손) - 손잡이 위치 ===
    grip_pos = gun_center - dir_vec * 8 + perp_vec * 6
    right_elbow = right_shoulder + (grip_pos - right_shoulder) * 0.5 + Vector2(8, 6)

    # === 왼손 (총열 잡는 손) - 핸드가드 위치 ===
    handguard_pos = gun_center + dir_vec * 12 + perp_vec * 2
    left_elbow = left_shoulder + (handguard_pos - left_shoulder) * 0.5 + Vector2(-8, 6)

    # === 오른팔 그리기 (어깨 → 팔꿈치 → 손) ===
    right_shoulder_pt = to_int_pair(right_shoulder)
    right_elbow_pt = to_int_pair(right_elbow)
    right_hand_pt = to_int_pair(grip_pos)

    pygame.draw.line(screen, arm_shadow_color, right_shoulder_pt, right_elbow_pt, 8)
    pygame.draw.line(screen, arm_mid_color, right_shoulder_pt, right_elbow_pt, 5)
    pygame.draw.line(screen, arm_shadow_color, right_elbow_pt, right_hand_pt, 7)
    pygame.draw.line(screen, arm_mid_color, right_elbow_pt, right_hand_pt, 4)

    # 오른손 (권총 그립)
    pygame.draw.circle(screen, glove_color, right_hand_pt, 5)
    pygame.draw.circle(screen, glove_outline, right_hand_pt, 5, 1)

    # === 왼팔 그리기 (어깨 → 팔꿈치 → 손) ===
    left_shoulder_pt = to_int_pair(left_shoulder)
    left_elbow_pt = to_int_pair(left_elbow)
    left_hand_pt = to_int_pair(handguard_pos)

    pygame.draw.line(screen, arm_shadow_color, left_shoulder_pt, left_elbow_pt, 8)
    pygame.draw.line(screen, arm_mid_color, left_shoulder_pt, left_elbow_pt, 5)
    pygame.draw.line(screen, arm_shadow_color, left_elbow_pt, left_hand_pt, 7)
    pygame.draw.line(screen, arm_mid_color, left_elbow_pt, left_hand_pt, 4)

    # 왼손 (핸드가드 잡기)
    pygame.draw.circle(screen, glove_color, left_hand_pt, 5)
    pygame.draw.circle(screen, glove_outline, left_hand_pt, 5, 1)

    # === AK-47 총기 그리기 ===
    # 개머리판 (Stock)
    stock_start = gun_center - dir_vec * 25 + perp_vec * 3
    stock_end = gun_center - dir_vec * 12 + perp_vec * 3
    pygame.draw.line(screen, wood_dark, to_int_pair(stock_start), to_int_pair(stock_end), 7)
    pygame.draw.line(screen, wood_color, to_int_pair(stock_start + perp_vec * -1), to_int_pair(stock_end + perp_vec * -1), 4)

    # 리시버 (Receiver) - 메인 바디
    receiver_start = gun_center - dir_vec * 12
    receiver_end = gun_center + dir_vec * 10
    pygame.draw.line(screen, metal_color, to_int_pair(receiver_start), to_int_pair(receiver_end), 8)
    pygame.draw.line(screen, metal_highlight, to_int_pair(receiver_start + perp_vec * -3), to_int_pair(receiver_end + perp_vec * -3), 2)

    # 핸드가드 (Handguard) - 목재
    handguard_start = gun_center + dir_vec * 5
    handguard_end = gun_center + dir_vec * 22
    pygame.draw.line(screen, wood_dark, to_int_pair(handguard_start + perp_vec * 2), to_int_pair(handguard_end + perp_vec * 2), 6)
    pygame.draw.line(screen, wood_color, to_int_pair(handguard_start + perp_vec * -1), to_int_pair(handguard_end + perp_vec * -1), 4)

    # 총열 (Barrel)
    barrel_start = gun_center + dir_vec * 20
    barrel_end = gun_center + dir_vec * 35
    pygame.draw.line(screen, metal_color, to_int_pair(barrel_start), to_int_pair(barrel_end), 4)
    pygame.draw.line(screen, metal_highlight, to_int_pair(barrel_start + perp_vec * -1), to_int_pair(barrel_end + perp_vec * -1), 1)

    # 탄창 (Magazine) - 커브형
    mag_top = gun_center + dir_vec * -2 + perp_vec * 6
    mag_bottom = gun_center + dir_vec * 5 + perp_vec * 18
    pygame.draw.line(screen, (30, 30, 35), to_int_pair(mag_top), to_int_pair(mag_bottom), 6)
    pygame.draw.line(screen, (50, 50, 55), to_int_pair(mag_top + dir_vec * -2), to_int_pair(mag_bottom + dir_vec * -2), 2)

    # 손잡이 (Pistol Grip)
    grip_top = gun_center - dir_vec * 5 + perp_vec * 4
    grip_bottom = gun_center - dir_vec * 8 + perp_vec * 14
    pygame.draw.line(screen, wood_dark, to_int_pair(grip_top), to_int_pair(grip_bottom), 5)
    pygame.draw.line(screen, wood_color, to_int_pair(grip_top + dir_vec * 1), to_int_pair(grip_bottom + dir_vec * 1), 3)

    # === 총구 화염 (발사 중일 때) ===
    if is_firing and ak47.current_ammo > 0 and ak47_firing_recoil_phase > 0.3:
        muzzle_pos = barrel_end + dir_vec * 3
        flash_intensity = 0.5 + 0.5 * math.sin(current_time * 0.1)

        # 메인 화염
        flame_length = 18 * flash_intensity * ak47_firing_recoil_phase
        flame_end = muzzle_pos + dir_vec * flame_length

        # 화염 색상 (노랑 → 주황)
        flame_color = (255, int(200 + 55 * flash_intensity), int(50 * flash_intensity))
        pygame.draw.line(screen, flame_color, to_int_pair(muzzle_pos), to_int_pair(flame_end), 5)

        # 중심 화염 (흰색)
        core_end = muzzle_pos + dir_vec * (flame_length * 0.5)
        pygame.draw.line(screen, (255, 255, 200), to_int_pair(muzzle_pos), to_int_pair(core_end), 3)

        # 화염 스파크
        for _ in range(3):
            spark_offset = dir_vec * random.uniform(5, flame_length) + perp_vec * random.uniform(-5, 5)
            spark_pos = muzzle_pos + spark_offset
            pygame.draw.circle(screen, (255, 255, 150), to_int_pair(spark_pos), random.randint(1, 2))


def spawn_ak47_shell_casing():
    """AK-47 탄피 생성 - 실제 총알 발사 시 호출됨"""
    global ak47_shell_casings

    try:
        # 플레이어 위치 기반 탄피 생성 위치
        spawn_x = PLAYER.centerx + 20  # 총기 우측에서 배출
        spawn_y = PLAYER.centery - 5

        # 탄피 초기 속도 (우측 위로 튀어나감)
        eject_vx = random.uniform(3, 6)  # 우측으로
        eject_vy = random.uniform(-7, -4)  # 위로 튀어오름

        ak47_shell_casings.append({
            'x': spawn_x,
            'y': spawn_y,
            'vx': eject_vx,
            'vy': eject_vy,
            'rotation': random.uniform(0, 360),
            'rotation_speed': random.uniform(15, 30),
            'bounce_count': 0,
            'lifetime': AK47_SHELL_LIFETIME
        })
    except:
        pass  # PLAYER가 없는 경우 무시


def update_ak47_shell_casings():
    """AK-47 탄피 물리 업데이트 - 바닥에 떨어지고 튀어오르는 효과"""
    global ak47_shell_casings

    # 플레이어 바닥 위치 가져오기 (코만도가 서 있는 땅)
    try:
        floor_y = PLAYER.bottom + 5  # 플레이어 발 아래 약간
    except:
        floor_y = HEIGHT - 50  # fallback

    alive_shells = []
    for shell in ak47_shell_casings:
        # 수명 감소
        shell['lifetime'] -= 1
        if shell['lifetime'] <= 0:
            continue

        # 중력 적용
        shell['vy'] += AK47_SHELL_GRAVITY

        # 위치 업데이트
        shell['x'] += shell['vx']
        shell['y'] += shell['vy']

        # 회전 업데이트
        shell['rotation'] += shell['rotation_speed']

        # 바닥 충돌 체크 (플레이어가 서 있는 바닥)
        if shell['y'] >= floor_y:
            shell['y'] = floor_y

            if shell['bounce_count'] < AK47_SHELL_MAX_BOUNCES:
                # 바운스!
                shell['vy'] = -abs(shell['vy']) * AK47_SHELL_BOUNCE_DECAY
                shell['vx'] *= 0.7  # 수평 감속
                shell['rotation_speed'] *= 0.6  # 회전 감속
                shell['bounce_count'] += 1

                # 바운스 높이가 너무 작으면 멈춤
                if abs(shell['vy']) < 1.0:
                    shell['vy'] = 0
                    shell['vx'] *= 0.5
                    shell['rotation_speed'] = 0
            else:
                # 최대 바운스 후 정지
                shell['vy'] = 0
                shell['vx'] *= 0.85
                shell['rotation_speed'] = 0

                # 거의 멈추면 완전 정지
                if abs(shell['vx']) < 0.3:
                    shell['vx'] = 0

        alive_shells.append(shell)

    ak47_shell_casings = alive_shells


def draw_ak47_shell_casings(screen):
    """AK-47 탄피 렌더링 - 황동색 탄피가 굴러다니는 효과"""
    global ak47_shell_casings

    for shell in ak47_shell_casings:
        x, y = int(shell['x']), int(shell['y'])
        rotation = shell['rotation']

        # 수명에 따른 페이드 아웃
        alpha_mult = min(1.0, shell['lifetime'] / 60.0)  # 마지막 1초 페이드

        # 탄피 크기
        shell_length = 8
        shell_width = 3

        # 회전된 탄피 그리기
        angle_rad = math.radians(rotation)
        cos_a = math.cos(angle_rad)
        sin_a = math.sin(angle_rad)

        # 탄피 끝점 계산 (중심에서 양쪽으로)
        half_len = shell_length / 2
        dx = half_len * cos_a
        dy = half_len * sin_a

        x1, y1 = x - dx, y - dy  # 탄피 바닥 (닫힌 쪽)
        x2, y2 = x + dx, y + dy  # 탄피 입구 (열린 쪽)

        # 탄피 색상 (황동색)
        brass_base = (200, 160, 80)
        brass_light = (230, 190, 110)
        brass_dark = (160, 120, 50)

        # 바운스 중이면 더 밝게
        if shell['bounce_count'] < AK47_SHELL_MAX_BOUNCES and abs(shell['vy']) > 0.5:
            brass_base = (220, 180, 100)
            brass_light = (250, 210, 130)

        # 메인 탄피 몸체
        pygame.draw.line(screen, brass_dark, (int(x1), int(y1)), (int(x2), int(y2)), shell_width + 1)
        pygame.draw.line(screen, brass_base, (int(x1), int(y1)), (int(x2), int(y2)), shell_width)

        # 탄피 바닥 (닫힌 부분 - 프라이머)
        primer_x = int(x1 - cos_a * 1)
        primer_y = int(y1 - sin_a * 1)
        pygame.draw.circle(screen, (180, 140, 60), (primer_x, primer_y), 2)
        pygame.draw.circle(screen, (220, 180, 100), (primer_x, primer_y), 1)

        # 하이라이트 (위쪽 면에 반사광)
        highlight_offset_x = -sin_a * 1
        highlight_offset_y = cos_a * 1
        pygame.draw.line(screen, brass_light,
                        (int(x1 + highlight_offset_x), int(y1 + highlight_offset_y)),
                        (int(x2 + highlight_offset_x), int(y2 + highlight_offset_y)), 1)

        # 수명이 얼마 안 남으면 깜빡임
        if shell['lifetime'] < 30 and shell['lifetime'] % 6 < 3:
            continue  # 깜빡임 효과


# === 권총 탄피 함수들 ===
def spawn_pistol_shell_casing():
    """권총 탄피 생성 - 권총 발사 시 호출됨"""
    global pistol_shell_casings

    try:
        # 플레이어 위치 기반 탄피 생성 위치 (권총은 좀 더 낮은 위치에서)
        spawn_x = PLAYER.centerx + 15  # 총기 우측에서 배출
        spawn_y = PLAYER.centery

        # 탄피 초기 속도 (우측 위로 튀어나감, 권총은 AK보다 약하게)
        eject_vx = random.uniform(2, 4.5)  # 우측으로
        eject_vy = random.uniform(-5, -3)  # 위로 튀어오름

        pistol_shell_casings.append({
            'x': spawn_x,
            'y': spawn_y,
            'vx': eject_vx,
            'vy': eject_vy,
            'rotation': random.uniform(0, 360),
            'rotation_speed': random.uniform(12, 25),
            'bounce_count': 0,
            'lifetime': PISTOL_SHELL_LIFETIME
        })
    except:
        pass  # PLAYER가 없는 경우 무시


def update_pistol_shell_casings():
    """권총 탄피 물리 업데이트 - 바닥에 떨어지고 튀어오르는 효과"""
    global pistol_shell_casings

    # 플레이어 바닥 위치 가져오기
    try:
        floor_y = PLAYER.bottom + 5
    except:
        floor_y = HEIGHT - 50

    alive_shells = []
    for shell in pistol_shell_casings:
        # 수명 감소
        shell['lifetime'] -= 1
        if shell['lifetime'] <= 0:
            continue

        # 중력 적용
        shell['vy'] += PISTOL_SHELL_GRAVITY

        # 위치 업데이트
        shell['x'] += shell['vx']
        shell['y'] += shell['vy']

        # 회전 업데이트
        shell['rotation'] += shell['rotation_speed']

        # 바닥 충돌 체크
        if shell['y'] >= floor_y:
            shell['y'] = floor_y

            if shell['bounce_count'] < PISTOL_SHELL_MAX_BOUNCES:
                # 바운스!
                shell['vy'] = -abs(shell['vy']) * PISTOL_SHELL_BOUNCE_DECAY
                shell['vx'] *= 0.65
                shell['rotation_speed'] *= 0.5
                shell['bounce_count'] += 1

                if abs(shell['vy']) < 0.8:
                    shell['vy'] = 0
                    shell['vx'] *= 0.4
                    shell['rotation_speed'] = 0
            else:
                shell['vy'] = 0
                shell['vx'] *= 0.8
                shell['rotation_speed'] = 0

                if abs(shell['vx']) < 0.2:
                    shell['vx'] = 0

        alive_shells.append(shell)

    pistol_shell_casings = alive_shells


def draw_pistol_shell_casings(screen):
    """권총 탄피 렌더링 - 좀 더 작은 황동색 탄피"""
    global pistol_shell_casings

    for shell in pistol_shell_casings:
        x, y = int(shell['x']), int(shell['y'])
        rotation = shell['rotation']

        # 탄피 크기 (권총은 AK보다 작음)
        shell_length = 6
        shell_width = 2

        # 회전된 탄피 그리기
        angle_rad = math.radians(rotation)
        cos_a = math.cos(angle_rad)
        sin_a = math.sin(angle_rad)

        half_len = shell_length / 2
        dx = half_len * cos_a
        dy = half_len * sin_a

        x1, y1 = x - dx, y - dy
        x2, y2 = x + dx, y + dy

        # 탄피 색상 (약간 더 밝은 황동색)
        brass_base = (210, 170, 90)
        brass_light = (240, 200, 120)
        brass_dark = (170, 130, 60)

        # 바운스 중이면 더 밝게
        if shell['bounce_count'] < PISTOL_SHELL_MAX_BOUNCES and abs(shell['vy']) > 0.5:
            brass_base = (230, 190, 110)
            brass_light = (255, 220, 140)

        # 메인 탄피 몸체
        pygame.draw.line(screen, brass_dark, (int(x1), int(y1)), (int(x2), int(y2)), shell_width + 1)
        pygame.draw.line(screen, brass_base, (int(x1), int(y1)), (int(x2), int(y2)), shell_width)

        # 탄피 바닥 (프라이머)
        primer_x = int(x1 - cos_a * 1)
        primer_y = int(y1 - sin_a * 1)
        pygame.draw.circle(screen, (190, 150, 70), (primer_x, primer_y), 1)

        # 하이라이트
        highlight_offset_x = -sin_a * 0.5
        highlight_offset_y = cos_a * 0.5
        pygame.draw.line(screen, brass_light,
                        (int(x1 + highlight_offset_x), int(y1 + highlight_offset_y)),
                        (int(x2 + highlight_offset_x), int(y2 + highlight_offset_y)), 1)

        # 수명이 얼마 안 남으면 깜빡임
        if shell['lifetime'] < 25 and shell['lifetime'] % 5 < 2:
            continue


