            #     f" gauge={special_gauge:.1f}/{get_max_gauge():.1f}"
            #     f" hold_ms={optimus_charge_hold_ms}"
            # )

    # ⚡ 스매셔 플라즈마 자기장 스킬 (W/상 키 홀드)
    def _handle_smasher_plasma_field(now_ms: int, up_held: bool) -> None:
        """스매셔 전용: W/↑키 홀드로 플라즈마 자기장 차징 및 발사."""
        global plasma_field_charging, plasma_field_charge_time, plasma_field_charge_start_time
        global plasma_field_gauge_consumed, plasma_field_size, plasma_field_particles
        global plasma_wave_active, plasma_wave_x, plasma_wave_y, plasma_wave_radius
        global plasma_wave_slow_amount, plasma_wave_duration, plasma_wave_particles, plasma_wave_trail
        global plasma_charge_sound_playing
        global special_gauge, special_ready

        if selected_character_type != "smasher":
            if plasma_field_charging:
                plasma_field_charging = False
                plasma_field_charge_time = 0
                plasma_field_gauge_consumed = 0
                plasma_field_size = 0.0
                plasma_field_particles.clear()
                # 차징 사운드 정지
                if plasma_charge_sound_playing and PLASMA_CHARGE_CHANNEL:
                    PLASMA_CHARGE_CHANNEL.stop()
                    plasma_charge_sound_playing = False
            return

        # 차징 불가 조건
        if (
            rolling_active
            or rolling_stun_timer > 0
            or player_stunned
            or is_waiting_for_serve
            or is_player_serve
            or power_smashing_freeze_active
            or power_smashing_parabola_active
        ):
            # 불가 조건에서 키를 떼면 자기장 발사
            if plasma_field_charging and plasma_field_gauge_consumed > 0:
                _fire_plasma_wave()
            plasma_field_charging = False
            plasma_field_charge_time = 0
            plasma_field_gauge_consumed = 0
            plasma_field_size = 0.0
            plasma_field_particles.clear()
            # 차징 사운드 정지
            if plasma_charge_sound_playing and PLASMA_CHARGE_CHANNEL:
                PLASMA_CHARGE_CHANNEL.stop()
                plasma_charge_sound_playing = False
            return

        if up_held:
            # 차징 시작 또는 지속
            if not plasma_field_charging:
                # 플라즈마 스킬이 해금되지 않았으면 사용 불가
                if not is_smasher_skill_unlocked("plasma"):
                    return
                # 플라즈마 웨이브가 이미 활성화 중이면 차징 불가 (쿨타임)
                if plasma_wave_active:
                    return
                # 스킬 쿨타임 체크
                if get_smasher_skill_cooldown_remaining("plasma") > 0:
                    return
                # 게이지가 최소 40 이상이어야 차징 가능 (최소 소모량)
                if special_gauge >= plasma_field_min_gauge_cost:
                    plasma_field_charging = True
                    plasma_field_charge_start_time = now_ms
                    plasma_field_charge_time = 0
                    plasma_field_gauge_consumed = 0
                    plasma_field_size = 0.0
                    plasma_field_particles.clear()
                    # 차징 사운드 재생 (전용 채널, 루프)
                    if SOUND_PLASMA_CHARGE and PLASMA_CHARGE_CHANNEL and not plasma_charge_sound_playing:
                        PLASMA_CHARGE_CHANNEL.play(SOUND_PLASMA_CHARGE, loops=-1)
                        plasma_charge_sound_playing = True
            else:
                # 차징 지속 중
                plasma_field_charge_time += 1

                # 매 프레임마다 일정하게 게이지 소모 (0.5초에 40 = 프레임당 40/30 ≈ 1.33)
                drain_per_frame = plasma_field_gauge_drain_amount / plasma_field_gauge_drain_interval
                if special_gauge >= drain_per_frame:
                    special_gauge -= drain_per_frame
                    plasma_field_gauge_consumed += drain_per_frame
                    if special_gauge < 350:
                        special_ready = False
                    try:
                        game_state.special_gauge = special_gauge
                        game_state.special_ready = special_ready
                    except Exception:
                        pass
                else:
                    # 게이지 부족 - 강제 발사
                    if plasma_field_gauge_consumed > 0:
                        _fire_plasma_wave()
                    plasma_field_charging = False
                    plasma_field_charge_time = 0
                    plasma_field_gauge_consumed = 0
                    plasma_field_size = 0.0
                    plasma_field_particles.clear()
                    # 차징 사운드 정지
                    if plasma_charge_sound_playing and PLASMA_CHARGE_CHANNEL:
                        PLASMA_CHARGE_CHANNEL.stop()
                        plasma_charge_sound_playing = False
                    return

                # 필드 크기 점진적 증가 (매 프레임)
                # 차징 시간에 비례해서 0.0 ~ 1.0 증가 (최대 3초 = 180프레임에서 풀차지)
                max_charge_frames = 180  # 3초
                plasma_field_size = min(1.0, plasma_field_charge_time / max_charge_frames)

                # 플라즈마 파티클 생성 (매 2프레임마다)
                if plasma_field_charge_time % 2 == 0:
                    _spawn_plasma_field_particle()
        else:
            # 키를 뗐을 때 - 0.5초(30프레임) 이상 홀딩해야 발사
            if plasma_field_charging:
                if plasma_field_charge_time >= 30 and plasma_field_gauge_consumed > 0:
                    # 0.5초 이상 홀딩 - 발사
                    _fire_plasma_wave()
                elif plasma_field_gauge_consumed > 0:
                    # 0.5초 미만 홀딩 - 게이지 반환
                    special_gauge += plasma_field_gauge_consumed
                    if special_gauge >= 350:
                        special_ready = True
                    try:
                        game_state.special_gauge = special_gauge
                        game_state.special_ready = special_ready
                    except Exception:
                        pass
            plasma_field_charging = False
            plasma_field_charge_time = 0
            plasma_field_gauge_consumed = 0
            plasma_field_size = 0.0
            plasma_field_particles.clear()
            # 차징 사운드 정지
            if plasma_charge_sound_playing and PLASMA_CHARGE_CHANNEL:
                PLASMA_CHARGE_CHANNEL.stop()
                plasma_charge_sound_playing = False

    def _spawn_plasma_field_particle():
        """플라즈마 필드 차징 파티클 생성"""
        global plasma_field_particles
        import random as rnd
        angle = rnd.uniform(0, 2 * math.pi)
        dist = rnd.uniform(5, 15)
        speed = rnd.uniform(0.5, 1.5)
        alpha = rnd.randint(150, 255)
        plasma_field_particles.append({
            'angle': angle,
            'dist': dist,
            'alpha': alpha,
            'speed': speed,
            'life': 30  # 0.5초 수명
        })
        # 파티클 수 제한
        if len(plasma_field_particles) > 50:
            plasma_field_particles = plasma_field_particles[-50:]

    def _fire_plasma_wave():
        """플라즈마 자기장 구체 발사 (magnetic_projectile 방식)"""
        global plasma_wave_active, plasma_wave_x, plasma_wave_y, plasma_wave_radius
        global plasma_wave_slow_amount
        global plasma_wave_duration, plasma_wave_particles, plasma_wave_trail
        global plasma_field_gauge_consumed, plasma_charge_sound_playing
        global special_gauge, special_ready

        # 이미 웨이브가 활성화되어 있으면 무시
        if plasma_wave_active:
            return

        # 최소 게이지 소모량 적용 (50)
        if plasma_field_gauge_consumed < plasma_field_min_gauge_cost:
            additional_drain = plasma_field_min_gauge_cost - plasma_field_gauge_consumed
            if special_gauge >= additional_drain:
                special_gauge -= additional_drain
                plasma_field_gauge_consumed = plasma_field_min_gauge_cost
                if special_gauge < 350:
                    special_ready = False
                try:
                    game_state.special_gauge = special_gauge
                    game_state.special_ready = special_ready
                except Exception:
                    pass

        # 발사 위치 (플레이어 중앙, 위쪽)
        plasma_wave_x = PLAYER.centerx
        plasma_wave_y = PLAYER.top - 20

        # 구체 반경 (차징 시간에 비례) - magnetic_projectile처럼 원형
        # 기본 반경 40, 최대 반경 100
        base_radius = 40
        max_radius = 100
        plasma_wave_radius = int(base_radius + (max_radius - base_radius) * plasma_field_size)

        # 둔화량 계산: 기본 20% + (0.5초당 5% 추가)
        # plasma_field_gauge_consumed / 40 = 0.5초 단위 횟수
        charge_ticks = plasma_field_gauge_consumed // plasma_field_gauge_drain_amount
        plasma_wave_slow_amount = plasma_field_base_slow + (charge_ticks * plasma_field_slow_per_tick)
        plasma_wave_slow_amount = min(0.80, plasma_wave_slow_amount)  # 최대 80% 둔화

        # 웨이브 활성화
        plasma_wave_active = True
        plasma_wave_duration = 180  # 3초 지속 (화면 상단까지 갈 시간)
        plasma_wave_particles.clear()
        plasma_wave_trail.clear()

        # 발사 효과음 (전용 채널)
        if SOUND_PLASMA_SHOOT and PLASMA_SHOOT_CHANNEL:
            try:
                SOUND_PLASMA_SHOOT.set_volume(sfx_volume * 0.5)
                PLASMA_SHOOT_CHANNEL.play(SOUND_PLASMA_SHOOT)
            except:
                pass

        # 차징 사운드 정지
        if plasma_charge_sound_playing and PLASMA_CHARGE_CHANNEL:
            PLASMA_CHARGE_CHANNEL.stop()
            plasma_charge_sound_playing = False

        # 스매셔 스킬 쿨타임 적용
        trigger_smasher_skill_cooldown("plasma")


    # 화기 교체 쿨다운 감소
    if soldier_controller.switch_cooldown > 0:
        soldier_controller.switch_cooldown -= 1
    global long_boost_scale, long_boost_target_scale, LONG_BOOST_TRANSITION_TIME, LONG_BOOST_DURATION
    global player_flame_zone_knockback_vel, player_flame_zone_knockback_cooldown, player_in_flame_zone  #  Stage 5 화염 넉백
    global PLAYER, speedboots_obtained, speedgear_obtained
    global acceleration_active, acceleration_height_bonus, acceleration_skill_level, acceleration_flash_particles  #  가속화 스킬 변수
    global aipill_active  #  AI 필 변수 추가
    global wall_installing  #  벽돌 설치 변수 추가
    global is_waiting_for_serve  #  서브 대기 상태 변수 추가
    global is_player_serve  #  플레이어 서브 상태 변수 추가
    global frame_counter
    
    def update_umbrella_knockback():
        """부드러운 넉백 모션 업데이트"""
        global blacksmith_umbrella_knockback_active, blacksmith_umbrella_knockback_timer
        global blacksmith_umbrella_knockback_velocity, blacksmith_umbrella_knockback_start_x
        global blacksmith_umbrella_knockback_target_x

        if not blacksmith_umbrella_knockback_active:
            return

        # 스윙 대쉬 중에는 넉백 무시 (스윙 대쉬가 우선)
        if blacksmith_swing_dash_active:
            blacksmith_umbrella_knockback_active = False
            blacksmith_umbrella_knockback_timer = 0.0
            return
            
        # 넉백 타이머 증가 (60fps 기준)
        blacksmith_umbrella_knockback_timer += 1.0
        
        # 넉백 지속 시간 (프레임): 처음 빠르게 시작해서 감속
        total_frames = 20  # 약 0.33초
        
        if blacksmith_umbrella_knockback_timer >= total_frames:
            # 넉백 완료 - 목표 위치에 정확히 맞추기
            PLAYER.x = int(blacksmith_umbrella_knockback_target_x)
            blacksmith_umbrella_knockback_active = False
            blacksmith_umbrella_knockback_timer = 0.0
            return
        
        # 진행률 (0.0 ~ 1.0)
        progress = blacksmith_umbrella_knockback_timer / total_frames
        
        # 감속 곡선 (fast start, slow end): 1 - (1-x)^3
        eased_progress = 1.0 - pow(1.0 - progress, 3.0)
        
        # 현재 위치 계산
        current_x = blacksmith_umbrella_knockback_start_x + (blacksmith_umbrella_knockback_target_x - blacksmith_umbrella_knockback_start_x) * eased_progress
        PLAYER.x = int(current_x)
    
    def start_umbrella_knockback(target_x: float):
        """넉백 모션 시작"""
        global blacksmith_umbrella_knockback_active, blacksmith_umbrella_knockback_start_x
        global blacksmith_umbrella_knockback_target_x, blacksmith_umbrella_knockback_timer
        
        blacksmith_umbrella_knockback_active = True
        blacksmith_umbrella_knockback_start_x = float(PLAYER.x)
        blacksmith_umbrella_knockback_target_x = target_x
        blacksmith_umbrella_knockback_timer = 0.0

    def request_blacksmith_umbrella_close(*, play_sound: bool = True, flash: bool = False) -> None:
        """토르쉴드를 접도록 요청한다. 이미 접는 중이면 아무 작업도 하지 않는다."""
        global blacksmith_umbrella_open, blacksmith_umbrella_retracting
        global blacksmith_umbrella_anim_direction, blacksmith_umbrella_anim_timer
        global blacksmith_umbrella_damage_flash_timer
        global blacksmith_umbrella_hit_lock
        global blacksmith_umbrella_retract_start_frame, blacksmith_umbrella_retract_grace_timer

        if not blacksmith_umbrella_open or blacksmith_umbrella_retracting:
            return

        # 스윙 통제불능 시간 중에는 토르쉴드 접기 불가
        swing_stun_timer = _rolling_get("rolling_stun_timer") if 'rolling_stun_timer' in _rolling_attr_map else 0
        if swing_stun_timer > 0 or blacksmith_swing_cooldown > 0:
            return

        blacksmith_umbrella_retracting = True
        blacksmith_umbrella_anim_direction = -1
        blacksmith_umbrella_anim_timer = BLACKSMITH_UMBRELLA_ANIM_FRAMES
        blacksmith_umbrella_hit_lock = False
        blacksmith_umbrella_retract_start_frame = frame_counter
        blacksmith_umbrella_retract_grace_timer = BLACKSMITH_UMBRELLA_RETRACT_HIT_GRACE_FRAMES

        if flash:
            blacksmith_umbrella_damage_flash_timer = max(
                blacksmith_umbrella_damage_flash_timer,
                BLACKSMITH_UMBRELLA_DAMAGE_FLASH_FRAMES,
            )

        if play_sound and SOUND_BLACKSMITH_UMBRELLA_CLOSE:
            play_sound_with_volume(SOUND_BLACKSMITH_UMBRELLA_CLOSE)
    global tutorial_drive_count, tutorial_displayed_drive_count
    global tutorial_left_drive_count, tutorial_right_drive_count
    global tutorial_displayed_left_drive_count, tutorial_displayed_right_drive_count
    # Chapter 2 대쉬 관련 변수 추가
    global tutorial_dash_count, tutorial_dash_counter_active, tutorial_dash_token_dialogue_shown
    # 쿠로미 뱉기 궤적 관련
    global kuromi_spit_trail_active, kuromi_spit_trail_positions
    global tutorial_dash_completion_dialogue_shown, tutorial_needs_dash_practice
