    # 🏟️ 투기장 영웅 스킬 상태 효과 적용 (하단 패들 = 플레이어)
    arena_player_stun_block = False
    arena_player_slow_mult = 1.0
    arena_player_speed_boost_only = 1.0  # 속도 부스트 전용 (감속도 제외)
    arena_player_confused = False
    # ⚡ 번개의 분노 스턴 (독립 메커니즘 - 다른 스킬이 paddle_stunned 덮어써도 적용)
    if _judgment_lightning_stun_bottom_timer > 0:
        _judgment_lightning_stun_bottom_timer -= (1.0 / 60.0) * arena_speed_multiplier
        if _judgment_lightning_stun_bottom_timer <= 0:
            _judgment_lightning_stun_bottom_timer = 0.0
            if arena_skill_manager and hasattr(arena_skill_manager, 'game_state'):
                arena_skill_manager.game_state['bottom_paddle_stunned'] = False
            # 상단도 감전 끝났으면 사운드 정지
            if _judgment_lightning_stun_top_timer <= 0:
                _stop_electric_shock_sound()
        else:
            arena_player_stun_block = True
            current_speed = 0
            rolling_active = False
            rolling_timer = 0
    # 🌪️ 바람의 분노 스턴 (독립 메커니즘)
    if _judgment_wind_stun_bottom_timer > 0:
        _judgment_wind_stun_bottom_timer -= (1.0 / 60.0) * arena_speed_multiplier
        if _judgment_wind_stun_bottom_timer <= 0:
            _judgment_wind_stun_bottom_timer = 0.0
            if arena_skill_manager and hasattr(arena_skill_manager, 'game_state'):
                arena_skill_manager.game_state['bottom_paddle_stunned'] = False
        else:
            arena_player_stun_block = True
            current_speed = 0
            rolling_active = False
            rolling_timer = 0
    if arena_mode_enabled and arena_skill_manager:
        try:
            game_state = arena_skill_manager.game_state
            # 스턴 체크 (하단 패들이 스턴되면 이동 불가)
            if game_state.get('bottom_paddle_stunned', False):
                arena_player_stun_block = True
                current_speed = 0
                rolling_active = False
                rolling_timer = 0
            # 스팀 배리어 시전 중 정지 (하단 패들이 시전자일 때)
            if game_state.get('steam_barrier_caster_frozen', False) and not game_state.get('barrier_owner_is_top', False):
                arena_player_stun_block = True
                current_speed = 0
                rolling_active = False
                rolling_timer = 0
            # 스팀 배리어 해동 중 (마지막 1초) - 점진적 속도 복귀
            steam_thaw = game_state.get('steam_barrier_thaw_speed', 0.0)
            if 0 < steam_thaw < 1.0 and not game_state.get('barrier_owner_is_top', False) and game_state.get('barrier_active', False):
                arena_player_slow_mult *= steam_thaw
            # 둔화 체크
            if game_state.get('bottom_paddle_slowed', False):
                arena_player_slow_mult = game_state.get('bottom_paddle_slow_amount', 0.5)
            # 속도 증가 체크 (귀신의 눈 등) - 가속도/최대속도만 부스트, 감속도는 제외
            speed_boost = game_state.get('bottom_paddle_speed_boost', 1.0)
            if speed_boost > 1.0:
                arena_player_speed_boost_only = speed_boost  # 별도 보관 (감속도 미적용)
            # 혼란 체크 (조작 반전)
            arena_player_confused = game_state.get('bottom_paddle_confused', False)
            # 패들 축소 체크 (크기 + 이동속도 15% 감소)
            if game_state.get('bottom_paddle_shrink', False):
                shrink_scale = game_state.get('bottom_paddle_shrink_scale', 0.5)
                target_width = int(130 * shrink_scale)  # 기본 패들 너비 130
                target_height = int(40 * shrink_scale)  # 기본 패들 높이 40
                # 하단 패들: 매 프레임 강제로 크기와 bottom 위치 고정
                center_x = PLAYER.centerx
                PLAYER.width = target_width
                PLAYER.height = target_height
                PLAYER.centerx = center_x
                # 귀신발걸음 Y축 이동 중에는 Y좌표 고정 스킵
                if not arena_bottom_ghost_step_active:
                    PLAYER.bottom = 750  # 하단 패들 bottom 위치 고정! (HEIGHT)
                # 🔮 이동속도 50% 감소 (축소된 패들 페널티)
                arena_player_slow_mult *= 0.5
            else:
                # 축소 효과 해제 시 원래 크기(130x40)로 복원
                if PLAYER.width != 130:
                    center_x = PLAYER.centerx
                    PLAYER.width = 130
                    PLAYER.height = 40
                    PLAYER.centerx = center_x
                    # 귀신발걸음 Y축 이동 중에는 Y좌표 고정 스킵
                    if not arena_bottom_ghost_step_active:
                        PLAYER.bottom = 750  # 하단 패들 bottom 위치 고정!
        except Exception as e:
            print(f"[Arena] Player status effect error: {e}")

    # 투기장 스턴 상태면 입력 처리 건너뛰기
    if arena_player_stun_block:
        PLAYER.x = max(0, min(WIDTH - PLAYER.width, PLAYER.x))
        return

    # 플레이어 자동조종 AI: 키 입력을 가로채어 AI가 만든 입력으로 대체
    if player_ai_enabled:
        # 전설 아이템 획득 애니메이션이 활성화되어 있으면 자동으로 진행(스페이스/클릭 대체)
        try:
            if is_legendary_effect_active():
                handle_legendary_space_press()
        except Exception:
            pass
        try:
            if selected_character_type == "blacksmith":
                controller = get_blacksmith_ai_controller()
            else:
                controller = get_player_ai_controller()
            now_ms = pygame.time.get_ticks()
            ai_state = {
                "now_ms": now_ms,
                "player_rect": PLAYER.copy(),
                "ball_rect": BALL.copy(),
                "ball_vel": tuple(ball_vel) if isinstance(ball_vel, (list, tuple)) else (0, 0),
                "width": WIDTH,
                "height": HEIGHT,
                "is_waiting_for_serve": is_waiting_for_serve,
                "special_ready": special_ready,
                "special_gauge": special_gauge,
                "special_max": special_gauge_max,
                "build_menu_active": blacksmith_build_menu_active,
                "rolling_active": get_roll("rolling_active"),
                "rolling_stun": get_roll("rolling_stun_timer"),
                "rolling_charges": get_roll("rolling_charges"),
                # 발토르 추가 정보
                "umbrella_open": blacksmith_umbrella_open,
                "turret_active": blacksmith_turret_active,
                "turret_overdrive_ready": bool((blacksmith_turret_state or {}).get("overdrive_ready", False)) if blacksmith_turret_state else False,
                "turret_rect": (blacksmith_turret_state or {}).get("rect") if blacksmith_turret_state else None,
                "turret_level": int((blacksmith_turret_state or {}).get("level", 1)) if blacksmith_turret_state else 1,
                "turret_level_max": BLACKSMITH_TURRET_MAX_LEVEL,
                "build_radius": BLACKSMITH_TURRET_BUILD_RADIUS,
                "blueprint_active": blacksmith_turret_blueprint_active,
                "build_progress": blacksmith_turret_build_progress,
                "build_needed": BLACKSMITH_TURRET_BUILD_TIME,
                "divine_active": blacksmith_divine_stone_state is not None,
                "divine_blueprint_active": blacksmith_divine_blueprint_active,
                "divine_build_progress": blacksmith_divine_build_progress,
                "divine_build_needed": BLACKSMITH_DIVINE_BUILD_TIME,
                "divine_rect": (blacksmith_divine_stone_state or {}).get("rect") if blacksmith_divine_stone_state else None,
                "divine_reinforced": bool((blacksmith_divine_stone_state or {}).get("reinforced", False)) if blacksmith_divine_stone_state else False,
                "divine_shield_ready": bool((blacksmith_divine_stone_state or {}).get("shield_ready", False)) if blacksmith_divine_stone_state else False,
                "divine_blueprint_rect": blacksmith_divine_blueprint_rect if 'blacksmith_divine_blueprint_rect' in globals() else None,
                "current_stage": current_stage,
            }
            # 발토르 AI가 청사진을 요구하면 메뉴 없이 즉시 배치
            if selected_character_type == "blacksmith":
                try:
                    if controller.wants_blueprint(ai_state):
                        plan = getattr(controller, "build_plan", "turret") or "turret"
                        target = "divine_stone" if plan == "divine" else "turret"
                        blacksmith_select_build_option(target)
                    # HUD가 열린 상태에서 divine 선택이 지연될 때를 대비한 추가 선택 로직
                    if (
                        ai_state.get("build_menu_active", False)
                        and getattr(controller, "build_plan", None) in ("divine", "upgrade_divine")
                        and not ai_state.get("divine_active", False)
                        and not ai_state.get("divine_blueprint_active", False)
                        and ai_state.get("special_gauge", 0) >= controller.MIN_GAUGE.get("divine", 200)
                    ):
                        blacksmith_select_build_option("divine_stone")
                    # HUD가 열려 있고 아무 청사진도 없을 때 기본 선택 자동화 (우선순위: 디바인 → 포탑)
                    if ai_state.get("build_menu_active", False):
                        has_any_blueprint = ai_state.get("blueprint_active", False) or ai_state.get("divine_blueprint_active", False)
                        if not has_any_blueprint:
                            gauge_now = ai_state.get("special_gauge", 0)
                            if ai_state.get("turret_active", False) and not ai_state.get("divine_active", False) and gauge_now >= 120:
                                blacksmith_select_build_option("divine_stone")
                            elif not ai_state.get("turret_active", False) and gauge_now >= 80:
                                blacksmith_select_build_option("turret")
                            else:
                                # 게이지가 부족하면 HUD를 닫아 입력 락을 방지
                                blacksmith_close_build_menu()
                except Exception:
                    pass
            pressed_keys = controller.decide(ai_state)
            keys = PlayerAIKeyState(pressed_keys, keys)

            # 스냅샷/이벤트 플래그도 AI 입력으로 동기화해 후속 로직이 동일하게 동작하도록 한다.
            ai_left = pygame.K_LEFT in pressed_keys or pygame.K_a in pressed_keys
            ai_right = pygame.K_RIGHT in pressed_keys or pygame.K_d in pressed_keys
            ai_down = pygame.K_DOWN in pressed_keys or pygame.K_s in pressed_keys
            ai_up = pygame.K_UP in pressed_keys or pygame.K_w in pressed_keys
            ai_space = pygame.K_SPACE in pressed_keys

            globals()["SNAP_left_state"] = ai_left
            globals()["SNAP_right_state"] = ai_right
            globals()["SNAP_down_state"] = ai_down
            globals()["SNAP_up_state"] = ai_up
            globals()["SNAP_space_pressed"] = ai_space
            globals()["SNAP_last_space"] = ai_space
            globals()["INPUT_SNAPSHOT_VALID"] = True

            globals()["MOVE_EVENT_LEFT"] = ai_left
            globals()["MOVE_EVENT_RIGHT"] = ai_right
            globals()["MOVE_EVENT_DOWN"] = ai_down
            globals()["MOVE_EVENT_UP"] = ai_up
        except Exception as e:
            print(f"[WARN] Player AI 입력 생성 실패: {e}")

    def _break_arrest_rope_on_dash():
        """포승줄 포박 중 대쉬 → 즉시 끊어짐 (모든 대쉬 경로에서 호출)"""
        global arrest_rope_phase, arrest_rope_active, arrest_rope_timer
        if arrest_rope_phase == "bound":
            arrest_rope_phase = "releasing"
            arrest_rope_active = False
            arrest_rope_timer = 28  # 끊어지는 연출
            show_speech("끊어냈다!", duration=60)

    def _start_dash(direction: int, *, tutorial_reset: bool = True) -> int:
        """공통 대쉬 시작 준비. 사용 가능한 토큰 수를 반환한다."""
        global dash_gold_multiplier_active, dash_key_released_since_last
        # 🔧 버그 수정: 대시 시작 시 키 릴리즈 플래그 리셋
        # 연속 대시를 막기 위해 키를 뗐다 다시 눌러야 다음 대시가 가능
        dash_key_released_since_last = False
        # 죽음의 포옹 영역 내 대쉬 차단
        if is_deadly_hug_dash_blocked():
            show_speech("대쉬 봉쇄!", duration=30)
            return 0
        charges = get_roll("rolling_charges")
        if charges <= 0:
            return 0
        if tutorial_reset and current_stage == 50 and 'tutorial_dash_already_counted' in globals():
            globals()["tutorial_dash_already_counted"] = False
        set_roll("rolling_active", True)
        # 포승줄 포박 중 대쉬 → 즉시 끊어짐
        _break_arrest_rope_on_dash()
        # 대시 골드 보너스 활성화 (다음 랠리 2배)
        dash_gold_multiplier_active = True
        set_roll("rolling_direction", direction)
        # 🧊 빙판 상태에서 대쉬 시 얼음 파티클 생성
        if is_ice_active():
            create_ice_dash_particles(PLAYER.centerx, PLAYER.bottom, direction, is_player=True)
        # 🧊 얼음 이벤트: 대쉬 시작 시 기존 미끄러짐 상태 초기화
        global ice_dash_sliding, ice_dash_slide_speed
        ice_dash_sliding = False
        ice_dash_slide_speed = 0
        # 🌑 오딘의 눈 대쉬 다이브: 변신 상태에서 대쉬 시 땅속 잠수 효과 시작
        try:
            from legendary_items import get_legendary_manager as _glm_dd
            _dd_mgr = _glm_dd()
            if _dd_mgr:
                _dd_oe = _dd_mgr.get_item("odins_eye")
                if _dd_oe and _dd_oe.active and _dd_oe.is_transformed():
                    _dd_oe.start_dash_dive(PLAYER.centerx, PLAYER.centery)
        except Exception:
            pass
        return charges

    def _execute_dash(
        direction: int,
        *,
        style: str = "full",
        tutorial_reset: bool = True,
    ) -> bool:
        """좌·우 대쉬 실행을 공용 처리한다. 실행 성공 여부를 반환."""

        if style != "full":
            # 하프 대쉬 등 다른 스타일은 후속 단계에서 통합한다.
            raise NotImplementedError(f"Unsupported dash style: {style}")

        charges_available = get_roll("rolling_charges")
        if charges_available <= 0:
            return False

        # 게이지 요구량 계산 (연속 대쉬 할인 및 장비/스킬 반영)
        base_gauge_cost = 140
        try:
            from item_effects.devil_dice import (
                get_devil_dice_multipliers,
                is_devil_dice_active,
            )
        except Exception:  # pragma: no cover - 안전 가드
            def is_devil_dice_active():
                return False

            def get_devil_dice_multipliers():
                return {}

        if is_devil_dice_active():
            multipliers = get_devil_dice_multipliers()
            base_gauge_cost = int(base_gauge_cost * multipliers.get("dash_cost", 1.0))

        next_consecutive = get_roll("rolling_consecutive_count") + 1
        consecutive_discount = 0.5 ** max(0, next_consecutive - 1)
        discounted_cost = int(base_gauge_cost * consecutive_discount)
        if selected_character_type == "optimus":
            discounted_cost = int(discounted_cost * 0.2)  # 80% 할인
        battery_bonus = get_runtime_skill_bonus("dash_battery_pack")
        required_gauge = max(10, int(discounted_cost * (1 - battery_bonus)))

        # 천사의 가호 대쉬 비용 버프 적용 (dash_manager._GLOBAL_DASH_INST 직접 참조)
        dm_inst = dash_manager._GLOBAL_DASH_INST
        if dm_inst is not None:
            external_cost_mul = getattr(dm_inst, 'external_cost_multiplier', 1.0)
            if external_cost_mul != 1.0:
                required_gauge = int(required_gauge * external_cost_mul)

        # 대쉬부스트 효과: 70% 할인 (활성화 시)
        _dash_boost_active = is_dash_boost_active()
        _before_boost_gauge = required_gauge
        if _dash_boost_active:
            required_gauge = int(required_gauge * get_dash_cost_multiplier())  # 0.3배 (70% 할인)

        # 🔧 디버그: 대쉬 발동 조건 체크
        # print(f"[DASH_DEBUG] _do_dash_common: special_gauge={special_gauge}, required_gauge={required_gauge}, dash_boost={_dash_boost_active}, before_boost={_before_boost_gauge}, pass={special_gauge >= required_gauge}")  # 디버그 비활성화

        # 게이지 체크 제거됨 - 대쉬는 토큰만 소모
        # if special_gauge < required_gauge:
        #     return False

        # 본격적인 대쉬 시작: RollingState 및 전역 상태 갱신
        if _start_dash(direction, tutorial_reset=tutorial_reset) <= 0:
            return False

        # 포승줄 끊어짐은 _start_dash() 내부의 _break_arrest_rope_on_dash()에서 처리

        global is_half_dash_active, half_dash_effect_timer, _current_dash_is_half
        global poseidon_dash_pending, poseidon_dash_x, poseidon_dash_y
        global acceleration_active, acceleration_height_bonus, acceleration_skill_level
        global recent_dash_time, mega_smashing_bonus_applied

        is_half_dash_active = False
        half_dash_effect_timer = 0
        _current_dash_is_half = False  # 일반 대쉬이므로 False

        # 포세이돈 삼지창 효과는 장착 상태일 때만 발동
        try:
            if is_passive_equipped("poseidon_trident"):
                legendary_manager = get_legendary_manager()
                if legendary_manager:
                    trident = legendary_manager.get_item("poseidon_trident")
                    if trident and trident.active:
                        poseidon_dash_pending = True
                        poseidon_dash_x = PLAYER.centerx
                        poseidon_dash_y = PLAYER.centery
            else:
                legendary_manager = get_legendary_manager()
                if legendary_manager:
                    legendary_manager.deactivate_item("poseidon_trident")
        except Exception:
            pass

        # 버스트업(가속화) 스킬 처리
        acceleration_bonus = get_runtime_skill_bonus("dash_acceleration")
        if acceleration_bonus > 0:
            acceleration_skill_level = int(acceleration_bonus * 10 / 7)
            acceleration_height_bonus = int(PADDLE_HEIGHT * acceleration_bonus)
            acceleration_active = True
            acceleration_flash_particles.clear()

        play_dash_sound()

        # 대쉬 진행 시간 및 거리 계산
        base_rolling_timer = apply_dashgear_distance(15.0)
        jump_bonus = get_runtime_skill_bonus("dash_jump")
        base_rolling_timer *= (1 + jump_bonus)
        skill_distance_boost = skill.apply_dash_distance_boost(base_rolling_timer)
        # 👁 오딘의 눈: 변신 상태 대쉬 거리 50% 증가
        skill_distance_boost *= _get_odin_dash_distance_mult()
        set_roll("rolling_timer", int(skill_distance_boost))
        # 연속대쉬 타이밍 계산을 위해 초기 타이머 및 시작 시간 저장
        globals()["_dash_initial_timer"] = int(skill_distance_boost)
        globals()["_dash_start_time"] = pygame.time.get_ticks()

        dash_spirit_chance = get_runtime_skill_bonus("dash_spirit")  # 레벨당 10%
        if dash_spirit_chance > 0:
            if random.random() < dash_spirit_chance:
                actual_dash_distance = int(get_roll("rolling_timer") * 40 * 0.7)
                dash_distance = int(actual_dash_distance * 0.5)
                create_dash_spirit_laser(PLAYER.centerx, PLAYER.centery, direction, dash_distance)

        # 토큰 차감 및 UI 동기화
        base_charges = 1
        holder_bonus = _get_dashholder_count()
        amplification_bonus = get_runtime_skill_bonus("dash_amplification")
        max_charges = int(base_charges + holder_bonus + amplification_bonus)

        # 👁 오딘의 눈 페널티: 대쉬 토큰 1개 고정
        try:
            legendary_manager = get_legendary_manager()
            if legendary_manager and items.odins_eye_obtained:
                odins_eye = legendary_manager.get_item("odins_eye")
                if odins_eye and odins_eye.active and odins_eye.penalty_active:
                    token_limit = odins_eye.get_dash_token_limit()
                    if token_limit is not None:
                        max_charges = min(max_charges, token_limit)
        except Exception:
            pass

        current_charges = max(0, charges_available - 1)
        set_roll("rolling_charges", current_charges)

        token_states_local = list(token_states)
        if token_states_local and len(token_states_local) > 0:
            for idx in range(min(len(token_states_local), max_charges) - 1, -1, -1):
                if token_states_local[idx]:
                    token_states_local[idx] = False
                    break
        else:
            token_states_local = [True] * current_charges + [False] * max(0, max_charges - current_charges)
        set_roll("token_states", token_states_local)

        # 쿨타임 및 충전 타이머 계산
        dash_cooldown_bonus = get_runtime_skill_bonus("dash_cooldown")
        cooldown_reduction = int(dash_cooldown_bonus * FPS)
        # 모든 토큰에 동일한 쿨타임 적용 (일관성 - 캐릭터 대쉬쿨타임 능력치 기준)
        base_cooldown = 300  # 5초 (300프레임) - 기본 대쉬 쿨타임
        if spikeboots_obtained:
            base_cooldown = int(base_cooldown * 0.85)
        base_timer = max(6, base_cooldown - cooldown_reduction)

        if is_devil_dice_active():
            multipliers = get_devil_dice_multipliers()
            if multipliers:
                base_timer = int(base_timer * multipliers.get("dash_cooldown", 1.0))

        # 천사의 가호 대쉬 쿨타임 버프 적용 (dash_manager._GLOBAL_DASH_INST 직접 참조)
        dm_inst = dash_manager._GLOBAL_DASH_INST
        if dm_inst is not None:
            external_cooldown_mul = getattr(dm_inst, 'external_cooldown_multiplier', 1.0)
            if external_cooldown_mul != 1.0:
                base_timer = int(base_timer * external_cooldown_mul)

        # 👁 오딘의 눈 페널티: 대쉬 쿨타임 +100%
        try:
            legendary_manager = get_legendary_manager()
            if legendary_manager and items.odins_eye_obtained:
                odins_eye = legendary_manager.get_item("odins_eye")
                if odins_eye and odins_eye.active and odins_eye.penalty_active:
                    base_timer = int(base_timer * odins_eye.get_dash_cooldown_multiplier())
        except Exception:
            pass

        set_roll("rolling_cooldown", base_timer)
        set_roll("rolling_charge_timer", base_timer)
        # _charging_state 즉시 업데이트 (균일한 게이지 애니메이션을 위해)
        _next_charge_idx = -1
        for _idx in range(len(token_states_local)):
            if not token_states_local[_idx]:
                _next_charge_idx = _idx
                break
        if _next_charge_idx >= 0:
            _charging_state["timer"] = base_timer
            _charging_state["max_time"] = base_timer
            _charging_state["index"] = _next_charge_idx
            # 각 토큰별 개별 충전 상태 업데이트 (균등 애니메이션용) - _start_dash
            while len(_token_charge_states) < max_charges:
                _token_charge_states.append({"timer": 0, "max_time": _UI_CHARGE_MAX, "ratio": 1.0})
            # UI 타이머는 90에서 시작, ratio로 실제 충전 시간에 맞춰 감소 (부드러운 애니메이션)
            # ratio = 90 / actual_timer → 실제 충전 완료 시 UI도 정확히 완료
            ui_ratio = _UI_CHARGE_MAX / base_timer if base_timer > 0 else 1.0
            _token_charge_states[_next_charge_idx] = {"timer": _UI_CHARGE_MAX, "max_time": _UI_CHARGE_MAX, "ratio": ui_ratio}
            # print(f"[TOKEN-SET-START_DASH] idx={_next_charge_idx}, actual={base_timer}, ui={_UI_CHARGE_MAX}, ratio={ui_ratio:.2f}")  # 디버그 비활성화

        # 연속 대쉬 카운트 및 튜토리얼 진행
        # 하프대쉬 여부 먼저 저장 (플래그 리셋 전)
        _was_half_dash = half_dash_used_flag
        if _was_half_dash:
            set_roll("rolling_consecutive_count", 1)
            globals()["half_dash_used_flag"] = False
        else:
            set_roll("rolling_consecutive_count", get_roll("rolling_consecutive_count") + 1)

        if (
            current_stage == 50
            and tutorial_current_chapter == 2
            and tutorial_consecutive_dash_count < 1
            and get_roll("rolling_consecutive_count") >= 2
        ):
            globals()["tutorial_consecutive_dash_count"] = (
                tutorial_consecutive_dash_count + 1
            )
            # print(
            #     f"튜토리얼: 연속대쉬 성공! {globals()['tutorial_consecutive_dash_count']}/1"
            # )
            # show_tutorial_success_feedback("연속대쉬 성공!", "great")
            check_tutorial_dash_missions_complete()

        if dash is not None:
            dash.sync_with_legacy_system(
                get_roll("rolling_charges"),
                get_roll("rolling_charge_timer"),
                get_roll("rolling_consecutive_count"),
            )

        # 게이지 소모 제거됨 - 대쉬는 토큰만 소모
        # consecutive_discount = 0.5 ** max(0, get_roll("rolling_consecutive_count") - 1)
        # discounted_cost = int(base_gauge_cost * consecutive_discount)
        # if dashgear_obtained:
        #     discounted_cost = int(discounted_cost * 0.8)
        # final_gauge_cost = max(10, int(discounted_cost * (1 - battery_bonus)))
        # dm_inst = dash_manager._GLOBAL_DASH_INST
        # if dm_inst is not None:
        #     external_cost_mul = getattr(dm_inst, 'external_cost_multiplier', 1.0)
        #     if external_cost_mul != 1.0:
        #         final_gauge_cost = int(final_gauge_cost * external_cost_mul)
        # consume_special_gauge(final_gauge_cost)
        if DEBUG_MODE:
            # print(
            #     f"    대쉬! (연속: {get_roll('rolling_consecutive_count')}, 토큰: {get_roll('rolling_charges')}, 게이지: {special_gauge})"
            # )
            # pass
            pass

        recent_dash_time = pygame.time.get_ticks()
        mega_smashing_bonus_applied = False
        record_dash_usage(success=False)

        # 실전 튜토리얼: 대쉬 종료 시 콜백 (일반 대쉬만 - 하프대쉬는 발동 시 직접 호출됨)
        # _was_half_dash가 True면 하프대쉬이므로 여기서 호출하지 않음 (이미 발동 시 호출됨)
        if not _was_half_dash:
            on_player_dash_for_tutorial(is_half_dash=False)

        # 부스트차징 발동 체크 (대쉬기어 + 퍽 합산) - 즉시 토큰 충전!
        _bc_pct = get_total_boost_charge_pct()
        if _bc_pct > 0 and _next_charge_idx >= 0:
            boost_chance = _bc_pct / 100.0
            roll_result = random.random()
            if roll_result < boost_chance:
                # 부스트차징 발동! - 토큰 즉시 충전 (연속대쉬 중 추가 대쉬 가능)
                # 해당 토큰을 즉시 True로 설정
                if _next_charge_idx < len(token_states):
                    token_states[_next_charge_idx] = True
                    new_charges = sum(1 for s in token_states if s)
                    _rolling_set("rolling_charges", new_charges)
                    rolling_charges = new_charges
                    if rolling_state is not None:
                        rolling_state.token_states = list(token_states)

                    # 충전 완료 플래시 효과 트리거
                    while len(_token_flash_timers) <= _next_charge_idx:
                        _token_flash_timers.append(0)
                    _token_flash_timers[_next_charge_idx] = _TOKEN_FLASH_DURATION

                    # UI 상태도 충전 완료로 설정
                    if _next_charge_idx < len(_token_charge_states):
                        _token_charge_states[_next_charge_idx] = {
                            "timer": 0,
                            "max_time": _UI_CHARGE_MAX,
                            "ratio": 1.0,
                            "boost_charging": False
                        }

                    # 충전 완료 사운드
                    play_dash_charge_sound()

                    # 다음 충전할 토큰 찾기
                    _next_boost_idx = -1
                    for _bidx in range(len(token_states)):
                        if not token_states[_bidx]:
                            _next_boost_idx = _bidx
                            break

                    if _next_boost_idx >= 0:
                        # 다음 토큰 충전 시작
                        _charging_state["timer"] = base_timer
                        _charging_state["max_time"] = base_timer
                        _charging_state["index"] = _next_boost_idx
                        ui_ratio = _UI_CHARGE_MAX / base_timer if base_timer > 0 else 1.0
                        while len(_token_charge_states) <= _next_boost_idx:
                            _token_charge_states.append({"timer": 0, "max_time": _UI_CHARGE_MAX, "ratio": 1.0})
                        _token_charge_states[_next_boost_idx] = {
                            "timer": _UI_CHARGE_MAX,
                            "max_time": _UI_CHARGE_MAX,
                            "ratio": ui_ratio,
                            "boost_charging": False
                        }
                    else:
                        # 모든 토큰 충전 완료
                        _charging_state["timer"] = 0
                        _charging_state["index"] = -1

                # 부스트차징 활성화 상태 설정 (이펙트용)
                globals()["boost_charging_active"] = True
                globals()["boost_charging_timer"] = 30  # 짧은 이펙트 지속 (0.5초)
                globals()["boost_charging_token_idx"] = _next_charge_idx
                # 부스트차징 사운드 재생
                if SOUND_BOOST_CHARGING and not AUDIO_DISABLED:
                    SOUND_BOOST_CHARGING.play()
                # 부스트차징 발동 이펙트 트리거
                globals()["boost_charging_effect_timer"] = BOOST_CHARGING_EFFECT_DURATION
                globals()["boost_charging_effect_x"] = PLAYER.centerx
                globals()["boost_charging_effect_y"] = PLAYER.centery

        return True

    # 서브 완료 후 타이머는 프레임 초기에 감소시켜, 아래의 조기 return 경로들(화상, 스턴, 설치 등)로 인해
    # 타이머가 영구히 감소하지 못해 물자보급/대시가 계속 금지되는 상황을 방지한다.
    if serve_completed_timer > 0:
        serve_completed_timer -= 1
        # 디버그 로그: 매 초 또는 마지막 5프레임에만 출력하여 소음 감소
        if serve_completed_timer % 60 == 0 or serve_completed_timer <= 5:
            pass  # print(f"⏱️ serve_completed_timer: {serve_completed_timer} ({serve_completed_timer/60:.1f}초 남음)")
    if serve_power_smash_lockout > 0:
        serve_power_smash_lockout -= 1
    #  새로운 보스 모드에서는 하단 보스가 플레이어 역할
    # 버그 수정: 해머쇼크 충전 중에는 charge_position을 초기화하지 않음
    # 초기화하면 기충전 애니메이션이 우측에서 딸려서 이동하고, 발사 위치가 잘못됨
    if not blacksmith_hammer_shock_charging:
        blacksmith_hammer_charge_position = None

    if new_boss_mode_active:
        if selected_bottom_boss == 1:
            handle_fire_knight_as_bottom()  # 파이어 나이트
        elif selected_bottom_boss == 2:
            handle_wind_spirit_as_bottom()  # 윈드 스피릿
        return
    # 마우스 조작 처리 (비활성화됨)
    mouse_controls = {}
    # if input_manager.get_control_mode() == "마우스":
    #     mouse_controls = input_manager.handle_mouse_controls(selected_item_index, active_item_slot)
    # 공용 다운 입력 헬퍼: IME 한글 'ㄴ'(S 위치)까지 포함해 안전하게 판정
    def _is_down_pressed_any(keys_seq) -> bool:
        try:
            if is_move_down_pressed(keys_seq):
                if os.environ.get("PINGF_CHARGE_DEBUG", "0").lower() not in ("0", "false", "off") and selected_character_type == "optimus":
                    pass  # print("[OPT_CHARGE_DEBUG] down_detect=move_down_pressed true")
                return True
            # 한글 자모 키코드도 런타임 조회해 포함 (pygame.key.key_code가 0~len(keys_seq) 범위 값을 줄 때만)
            for sym in ("ㄴ", "ᄂ"):
                try:
                    code = pygame.key.key_code(sym)
                except Exception:
                    code = None
                if code is not None and code >= 0 and code < len(keys_seq) and keys_seq[code]:
                    if os.environ.get("PINGF_CHARGE_DEBUG", "0").lower() not in ("0", "false", "off") and selected_character_type == "optimus":
                        pass  # print(f"[OPT_CHARGE_DEBUG] down_detect=hangul sym={sym} code={code}")
                    return True
            if os.environ.get("PINGF_CHARGE_DEBUG", "0").lower() not in ("0", "false", "off") and selected_character_type == "optimus":
                pass  # print(f"[OPT_CHARGE_DEBUG] down_detect=false len={len(keys_seq)} code_candidates={[pygame.key.key_code(s) for s in ('ㄴ','ᄂ') if hasattr(pygame.key,'key_code')]}")
        except Exception:
            pass
        return False

    # 키 입력 변수 초기화 (기본: 현재 스냅샷 keys)
    space_pressed_raw = keys[pygame.K_SPACE]
    # 🔧 버그 수정: down_pressed_raw는 반드시 FRESH 키 상태 사용
    # stale keys 배열은 키를 뗀 후에도 True로 남아있을 수 있음
    pygame.event.pump()
    _fresh_keys_init = pygame.key.get_pressed()
    # 🔧 pygame 2.x: K_DOWN/K_LEFT 등 SDL2 키코드는 len(keys)보다 크므로 len 비교 금지
    # keys[pygame.K_DOWN]은 내부 매핑으로 정상 동작하므로 try/except로 안전 접근
    try:
        _init_down = bool(_fresh_keys_init[pygame.K_DOWN])
    except (IndexError, TypeError):
        _init_down = False
    try:
        _init_s = bool(_fresh_keys_init[pygame.K_s])
    except (IndexError, TypeError):
        _init_s = False
    # 🔧 MOVE_EVENT_DOWN도 병합: 방향키 ↓가 이벤트로는 감지되었으나 get_pressed()에서 누락되는 경우 보완
    down_pressed_raw = _init_down or _init_s or bool(MOVE_EVENT_DOWN)
    up_pressed_raw = is_move_up_pressed(keys)
    # 마우스 클릭을 스페이스/다운 상태로 항상 병합해 검출 (패키징 기본 스킴에서도 동작)
    # 단, 필러 영역 위에서는 마우스 좌클릭을 무시
    try:
        _mb_all = pygame.mouse.get_pressed()
        _mouse_left_fire = bool(_mb_all[0])
        # 필러 영역 체크 (코만도 캐릭터일 때만)
        if _mouse_left_fire and selected_character_type == "soldier":
            try:
                raw_mx, raw_my = _original_mouse_get_pos()
                surf_ox, surf_oy = _player_gauge_surface_left_screen_pos
                pillar_w = int(250 * GAME_SCALE_FACTOR)
                pillar_h = int(650 * GAME_SCALE_FACTOR)
                if surf_ox <= raw_mx <= surf_ox + pillar_w and surf_oy <= raw_my <= surf_oy + pillar_h:
                    _mouse_left_fire = False  # 필러 영역에서는 발사 안 함
            except:
                pass
        space_pressed_raw = space_pressed_raw or _mouse_left_fire
        down_pressed_raw = down_pressed_raw or bool(_mb_all[2])
    except Exception:
        pass
    # 🛡️ 투기장 모드: 실제 플레이어 입력 완전 차단 (관람 모드)
    # AI가 생성한 입력만 사용하고, 마우스/키보드에서 오는 실제 입력은 모두 무시
    if arena_mode_enabled:
        space_pressed_raw = False
        down_pressed_raw = False
        up_pressed_raw = False
        _mouse_left_fire = False
    # 좌우 이동은 공용 헬퍼로 처리하여 IME/레이아웃 변환과 스캔코드까지 포괄
    left_pressed_raw = is_move_left_pressed(keys)
    right_pressed_raw = is_move_right_pressed(keys)
    # 🛡️ 투기장 모드: 좌우 이동도 실제 키보드 입력 차단 (AI 스냅샷만 사용)
    if arena_mode_enabled and not player_ai_enabled:
        # player_ai_enabled가 True면 keys가 이미 AI wrapper이므로 OK
        # 그렇지 않은 비정상 상태에서도 입력 차단
        left_pressed_raw = False
        right_pressed_raw = False
    # 간헐적으로 초기 프레임에서 키 상태가 비어있는 WIN+IME 조합을 대비해 한 번 더 리프레시
    if not left_pressed_raw and not right_pressed_raw:
        try:
            pygame.event.pump()
            _keys_rescanned = pygame.key.get_pressed()
            left_pressed_raw = is_move_left_pressed(_keys_rescanned)
            right_pressed_raw = is_move_right_pressed(_keys_rescanned)
        except Exception:
            pass

    # 프레임 입력 스냅샷이 유효하면 방향키/AD도 스냅샷을 우선 사용해 프레임 경계에서의 불안정 제거
    # (Prompt/오버레이 갱신 타이밍에 따른 간헐적 끊김 방지)
    try:
        if 'INPUT_SNAPSHOT_VALID' in globals() and INPUT_SNAPSHOT_VALID:
            # space 키는 아래에서 별도로 SNAP_space_pressed를 사용하므로 여기서는 방향만 적용
            left_pressed_raw = bool(SNAP_left_state)
            right_pressed_raw = bool(SNAP_right_state)
            # 🔧 버그 수정: down_pressed_raw는 스냅샷을 사용하지 않음!
            # 스냅샷은 handle_player 호출 전에 캡처되어 stale 상태가 됨
            # 대쉬 연속 발동 버그(토큰 4개 소모)의 직접 원인
            # down_pressed_raw = bool(SNAP_down_state)  # 비활성화!
            up_pressed_raw = bool(SNAP_up_state)
    except Exception:
        # 스냅샷 전역이 아직 초기화되지 않은 극초기 프레임 등은 조용히 기본값 사용
        pass

    # 스냅샷으로 덮였더라도 한글 'ㄴ' 키가 눌려 있으면 내려가기 입력으로 인정
    # 🔧 버그 수정: 이 fallback 체크도 stale keys 배열 사용으로 버그 유발
    # 최종 체크는 Line 54952-54964에서 fresh key state로 수행함
    # if not down_pressed_raw:
    #     _fallback_down = keys[pygame.K_DOWN] if pygame.K_DOWN < len(keys) else False
    #     _fallback_s = keys[pygame.K_s] if pygame.K_s < len(keys) else False
    #     down_pressed_raw = _fallback_down or _fallback_s

    # 입력 추적 로그 (간헐적 먹통 조사용)
    _log_input_trace(
        frame_counter,
        keys,
        left_pressed_raw,
        right_pressed_raw,
        SNAP_left_state if 'SNAP_left_state' in globals() else False,
        SNAP_right_state if 'SNAP_right_state' in globals() else False,
        player_stunned_timer > 0,
        is_waiting_for_serve,
        serve_completed_timer,
        current_speed,
    )

    # 컨트롤 스킴: 마우스+키보드일 때 WASD를 화살표 입력에 병합
    try:
        _sm = get_settings_manager()
        _scheme = _sm.get_setting('controls', 'control_scheme', 'keyboard')
    except Exception:
        _scheme = 'keyboard'
    if _scheme == 'mouse_keyboard':
        left_pressed_raw = left_pressed_raw or keys[pygame.K_a]
        right_pressed_raw = right_pressed_raw or keys[pygame.K_d]
        # 🔧 버그 수정: down_pressed_raw는 stale keys 사용 금지
        # 최종 체크는 Line 54952-54964에서 fresh key state로 수행함
        # _mk_down = keys[pygame.K_DOWN] if pygame.K_DOWN < len(keys) else False
        # _mk_s = keys[pygame.K_s] if pygame.K_s < len(keys) else False
        # down_pressed_raw = down_pressed_raw or _mk_down or _mk_s
    # 마우스 버튼을 Space/Down으로 항상 병합 (스킴 무관) - 코만도 입력용
    # 단, 마우스 우클릭을 먼저 누르고 방향키를 누르면 대시 발동 안 됨
    # 필러 영역 위에서는 마우스 좌클릭을 무시
    # 🛡️ 투기장 모드에서는 마우스 입력 병합도 차단
    if not arena_mode_enabled:
        try:
            mb = pygame.mouse.get_pressed()
            _mouse_left_fire2 = bool(mb[0])
            # 필러 영역 체크 (코만도 캐릭터일 때만)
            if _mouse_left_fire2 and selected_character_type == "soldier":
                try:
                    raw_mx, raw_my = _original_mouse_get_pos()
                    surf_ox, surf_oy = _player_gauge_surface_left_screen_pos
                    pillar_w = int(250 * GAME_SCALE_FACTOR)
                    pillar_h = int(650 * GAME_SCALE_FACTOR)
                    if surf_ox <= raw_mx <= surf_ox + pillar_w and surf_oy <= raw_my <= surf_oy + pillar_h:
                        _mouse_left_fire2 = False
                except:
                    pass
            space_pressed_raw = space_pressed_raw or _mouse_left_fire2
            _mouse_right_for_dash = bool(mb[2])
            # 마우스 우클릭이 눌려있고 방향키가 안 눌려있으면 락 설정
            # (방향키를 먼저 누르고 우클릭을 눌러야 대시 발동)
            if _mouse_right_for_dash and not left_pressed_raw and not right_pressed_raw:
                if not down_pressed_raw:  # 우클릭이 처음 눌린 순간
                    globals()['dash_down_first_lock'] = True
            # 마우스 우클릭을 떼면 락 해제
            elif not _mouse_right_for_dash and not down_pressed_raw:
                globals()['dash_down_first_lock'] = False
            down_pressed_raw = down_pressed_raw or _mouse_right_for_dash
        except Exception:
            pass

    # 입력 스냅샷이 유효하면 스냅샷을 우선 사용하되, AI 모드는 실제 키 상태도 병합해 누락 방지
    if 'INPUT_SNAPSHOT_VALID' in globals() and INPUT_SNAPSHOT_VALID:
        space_pressed = SNAP_space_pressed or space_pressed_raw
    else:
        space_pressed = space_pressed_raw

    # 포커스 상실 시에도 이벤트 기반 플래그로 보정하되,
    # 현재 키 스냅샷과 불일치하면 즉시 플래그를 해제해 드리프트를 방지한다.
    if MOVE_EVENT_LEFT and not left_pressed_raw:
        left_pressed_raw = True
    if MOVE_EVENT_RIGHT and not right_pressed_raw:
        right_pressed_raw = True
    # 🔧 버그 수정: MOVE_EVENT_DOWN 기반 보정 비활성화
    # 이벤트가 True로 남아있으면 down_pressed_raw가 True로 유지되어
    # 대쉬 연속 발동 버그(토큰 4개 소모)의 원인이 됨
    # if MOVE_EVENT_DOWN and not down_pressed_raw:
    #     down_pressed_raw = True
    if MOVE_EVENT_UP and not up_pressed_raw:
        up_pressed_raw = True
    if MOVE_EVENT_LEFT and not is_move_left_pressed(keys):
        MOVE_EVENT_LEFT = False
    if MOVE_EVENT_RIGHT and not is_move_right_pressed(keys):
        MOVE_EVENT_RIGHT = False
    # 한글 IME 환경에서는 get_pressed()가 ↓ 입력을 놓치는 경우가 있어
    # 이벤트 플래그로 보정하지만, 키 스냅샷과 불일치가 지속되면 드리프트를 막기 위해 해제한다.
    # 🔧 버그 수정: _is_down_pressed_any는 pump/refresh로 stale 데이터 반환 가능 -> 직접 키 체크
    try:
        _event_check_down = bool(keys[pygame.K_DOWN])
    except (IndexError, TypeError):
        _event_check_down = False
    try:
        _event_check_s = bool(keys[pygame.K_s])
    except (IndexError, TypeError):
        _event_check_s = False
    if MOVE_EVENT_DOWN and not _event_check_down and not _event_check_s:
        MOVE_EVENT_DOWN = False
    if MOVE_EVENT_UP and not is_move_up_pressed(keys):
        MOVE_EVENT_UP = False
    # 저주 보물상자: 조작 반전 디버프 (스테이지 3)
    if curse_chest_reverse_timer > 0 and current_stage == 3:
        left_pressed_raw, right_pressed_raw = right_pressed_raw, left_pressed_raw
        MOVE_EVENT_LEFT, MOVE_EVENT_RIGHT = MOVE_EVENT_RIGHT, MOVE_EVENT_LEFT

    if optimus_drain_locked:
        left_pressed_raw = False
        right_pressed_raw = False
        MOVE_EVENT_LEFT = MOVE_EVENT_RIGHT = False
    # 공 생성 애니메이션 중에는 플레이어 이동 불가
    if ball_spawn_animation_active:
        left_pressed_raw = False
        right_pressed_raw = False
        space_pressed_raw = False
        down_pressed_raw = False
        up_pressed_raw = False
        MOVE_EVENT_LEFT = MOVE_EVENT_RIGHT = MOVE_EVENT_DOWN = MOVE_EVENT_UP = False
    # 무기 HUD(↑ 홀드) 활성화 중에는 코만도 Space(좌클릭 병합 포함)를 무시해
    # HUD 클릭 선택 시 발사가 나가지 않도록 가드
    # (닫힘 억제 프레임은 연사(ak47) 홀드에 영향 주지 않도록 여기서는 고려하지 않음)
    if selected_character_type == "soldier" and (
        ('soldier_weapon_menu_active' in globals() and soldier_weapon_menu_active)
    ):
        space_pressed = False
        input_debug_log(
            "space_block:",
            f"HUD={soldier_weapon_menu_active}",
            f"sup={(soldier_weapon_menu_close_suppress_frames if 'soldier_weapon_menu_close_suppress_frames' in globals() else 0)}",
        )
    # 🔧 버그 수정: down_pressed 할당 직전 최종 키 상태 확인
    # keys 배열이 stale할 수 있으므로 새로운 get_pressed() 호출로 현재 상태 확인
    # pygame.event.pump()로 이벤트 큐를 처리해 키 상태를 최신화
    pygame.event.pump()
    _fresh_keys = pygame.key.get_pressed()
    try:
        _final_down = bool(_fresh_keys[pygame.K_DOWN])
    except (IndexError, TypeError):
        _final_down = False
    try:
        _final_s = bool(_fresh_keys[pygame.K_s])
    except (IndexError, TypeError):
        _final_s = False
    _final_mouse_right = False
    try:
        _final_mouse_right = bool(pygame.mouse.get_pressed()[2])
    except Exception:
        pass
    if down_pressed_raw and not _final_down and not _final_s and not _final_mouse_right and not MOVE_EVENT_DOWN:
        down_pressed_raw = False
    down_pressed = down_pressed_raw
    # 🔧 버그 수정: 키 릴리즈 감지 시 연속 대시 허용 플래그 설정
    # 대시 활성 중에는 플래그를 변경하지 않음 (키 상태 flickering 방지)
    # 🔧 연속대쉬 버그 수정: 후딜 상태(_is_stun_active)에서도 키 릴리즈 인식 필요
    #    후딜 상태에서 아래키를 뗐다 다시 눌러야 연속대쉬가 가능하므로
    #    _is_stun_active 조건 제거 (대쉬 활성 중일 때만 플래그 변경 차단)
    global dash_key_released_since_last
    _is_rolling_active = _rolling_get("rolling_active") if '_rolling_get' in dir() else False
    if not down_pressed and not _is_rolling_active:
        dash_key_released_since_last = True
    # 👁 오딘의 눈 변신 상태에서는 옵티머스 수동 충전 사용 불가
    optimus_down_for_charge = down_pressed
    if is_odins_eye_transformed():
        optimus_down_for_charge = False
    _handle_optimus_manual_charge(pygame.time.get_ticks(), optimus_down_for_charge)

    # ⚡ 스매셔 플라즈마 자기장 스킬 (W/↑ 키 홀드)
    # 👁 오딘의 눈 변신 상태에서는 기존 스킬 사용 불가
    up_for_plasma = up_pressed_raw or keys[pygame.K_w] or keys[pygame.K_UP]
    if is_odins_eye_transformed():
        up_for_plasma = False  # 변신 상태에서는 플라즈마 입력 무시
    _handle_smasher_plasma_field(pygame.time.get_ticks(), up_for_plasma)

    # ⚔ 바이퍼 스킬 발동 처리 (W/↑: 에어 블레이드/베놈 엣지 연계, Space/좌클릭 홀드: 제트팩, 대쉬+S: 쉐도우 백스텝, Q: 베놈 엣지, R: 마샬 킥)
    if selected_character_type == "viper" and not is_odins_eye_transformed():
        global _viper_w_key_released, _viper_s_key_released, _viper_e_key_released
        global _viper_blade_rush_active, _viper_blade_rush_x, _viper_blade_rush_y, _viper_blade_rush_fadeout, _viper_blade_rush_fadeout_timer
        global _viper_blade_rush_start_y, _viper_blade_rush_target_y, _viper_blade_rush_hit_ball
        global _viper_blade_rush_particles, _viper_blade_rush_trail, _viper_blade_rush_width
        global _viper_br_spin_active, _viper_br_spin_start_ms, _viper_br_spin_phase, _viper_br_spin_angle
        global _viper_br_jump_offset_y, _viper_br_arm_raise
        global _viper_ss_hologram_active, _viper_ss_hologram_start_ms, _viper_ss_hologram_target_x, _viper_ss_kick_ready
        global _viper_ss_hologram_origin_x, _viper_ss_hologram_origin_y, _viper_dash_origin_x, _viper_dash_was_airborne, _viper_ss_hologram_kick_dir, _viper_ss_hologram_kick_hit
        global _viper_ss_was_airborne
        global _viper_ss_wave_active, _viper_ss_wave_x, _viper_ss_wave_y, _viper_ss_wave_target_x
        global _viper_ss_wave_origin_x, _viper_ss_wave_dir, _viper_ss_wave_hit_ball, _viper_ss_wave_trail
        global _viper_ss_ball_touched, _viper_ss_ball_touched_ms
        global _viper_phantom_strike_active, _viper_phantom_strike_timer, _viper_phantom_strike_curve_dir
        global _viper_ps_curve_active, _viper_ps_curve_timer, _viper_ps_curve_direction
        global _viper_speed_boost_active, _viper_speed_boost_original
        global _viper_nerve_strike_active, _viper_nerve_strike_phase, _viper_nerve_strike_start_ms
        global _viper_nerve_strike_origin_x, _viper_nerve_strike_origin_y
        global _viper_nerve_strike_target_x, _viper_nerve_strike_target_y
        global _viper_nerve_strike_slash_shown, _viper_nerve_strike_combo_used
        global _viper_ns_hit_confirmed, _viper_ns_freeze_active
        global boss_confused_timer
        global _viper_jetpack_active, _viper_jetpack_offset_y, _viper_jetpack_gauge_timer, _viper_jetpack_particles
        global _viper_jetpack_hold_timer, _viper_jetpack_overheat
        global _viper_dive_active, _viper_dive_phase, _viper_dive_start_ms, _viper_dive_hold_start_ms, _viper_dive_charge_particles
        global _viper_dive_height_snapshot, _viper_dive_particles
        global _viper_dive_shockwave_timer, _viper_dive_shockwave_x, _viper_dive_shockwave_y
        global _viper_dive_ball_boosted
        global _viper_wall_dive_ready, _viper_wall_dive_ready_timer
        global _viper_wall_dive_active, _viper_wall_dive_phase, _viper_wall_dive_start_ms
        global _viper_wall_dive_start_x, _viper_wall_dive_start_y
        global _viper_wall_dive_wall_x, _viper_wall_dive_wall_y
        global _viper_wall_dive_charge_target_x, _viper_wall_dive_charge_target_y
        global _viper_wall_dive_charge_start_x, _viper_wall_dive_charge_start_y
        global _viper_wall_dive_ball_hit, _viper_wall_dive_particles, _viper_wall_dive_web_lines
        global _viper_wall_dive_reclimb_start_x, _viper_wall_dive_reclimb_start_y
        global _viper_starburst_active, _viper_starburst_x, _viper_starburst_y, _viper_starburst_frame, _viper_starburst_timer, _viper_starburst_is_double
        global _viper_dmk_text_active, _viper_dmk_text_timer, _viper_dmk_text_x, _viper_dmk_text_y
        global _viper_dmk_freeze_active, _viper_dmk_freeze_timer
        global _viper_phantom_aura_active, _viper_phantom_aura_start_ms, _viper_phantom_hit_particles
        global _viper_wall_dive_return_start_x, _viper_wall_dive_return_start_y
        global _viper_marshal_kick_hit_ball, _viper_marshal_kick_hit_ms, _viper_double_marshal_ready, _viper_double_marshal_ready_timer, _viper_is_double_marshal
        global screen_shake_timer, screen_shake_intensity
        global boss_fire_knockback_vel, _viper_phantom_kick_knockback_pending
        global _viper_dive_slip_timer, _viper_dive_slip_vel, _viper_dive_slip_duration

        _viper_w_pressed = keys[pygame.K_w] or keys[pygame.K_UP]  # W키 또는 ↑키 (에어 블레이드/베놈 엣지)
        _viper_e_pressed = keys[pygame.K_e]
        _viper_s_pressed = keys[pygame.K_s]

        # 키 릴리즈 감지 (연속 발동 방지)
        # 서브 중에는 릴리즈 플래그를 리셋하여 서브 발사 직후 에어 블레이드 오발동 방지
        if is_waiting_for_serve or is_player_serve:
            _viper_w_key_released = False
        elif not _viper_w_pressed:
            _viper_w_key_released = True
        if not _viper_e_pressed:
            _viper_e_key_released = True

        # S키/아래키 릴리즈: 대쉬 상태일 때만 추적 (평상시에는 리셋 유지)
        _viper_in_dash = rolling_active or rolling_stun_timer > 0
        # 쉐도우 백스텝 입력: S키 또는 아래키 (둘 다 인정)
        _viper_ss_input = _viper_s_pressed or keys[pygame.K_DOWN]
        if _viper_in_dash:
            if not _viper_ss_input:
                _viper_s_key_released = True
        else:
            _viper_s_key_released = False  # 대쉬 상태 아니면 항상 리셋 → 오발동 방지

        # 발동 불가 조건 (대쉬 중, 스턴, 서브 대기)
        _viper_can_act = not (
            rolling_active
            or player_stunned
            or is_waiting_for_serve
            or is_player_serve
        )

        # 쉐도우 백스텝: 대쉬 중/후딜 중 S키(또는 아래키) 단독 입력 시만 발동
        # 좌우 방향키가 함께 눌려있으면 대쉬 입력으로 간주 → 발동 차단
        _viper_any_dir_held = (
            keys[pygame.K_LEFT] or keys[pygame.K_RIGHT]
            or keys[pygame.K_a] or keys[pygame.K_d]
            or MOVE_EVENT_LEFT or MOVE_EVENT_RIGHT
            or is_move_left_pressed(keys) or is_move_right_pressed(keys)
        )
        if _viper_in_dash and _viper_ss_input and _viper_s_key_released and not _viper_any_dir_held:
            if is_viper_skill_unlocked("shadow_step"):
                if get_viper_skill_cooldown_remaining("shadow_step") <= 0:
                    if special_gauge >= 100 and not _viper_ss_hologram_active:
                        _viper_s_key_released = False
                        special_gauge -= 100
                        # 쉐도우 백스텝 단독: 15초 쿨타임 (마샬킥 사용 시 연장됨)
                        _viper_skill_cooldown_override.pop("shadow_step", None)  # 오버라이드 초기화 → 기본 15초
                        trigger_viper_skill_cooldown("shadow_step")
                        try:
                            _bs_snd = sound_effects.get('VIPER_BACKSTEP')
                            if _bs_snd:
                                _bs_snd.set_volume(0.5)
                                _bs_snd.play()
                        except Exception:
                            pass
                        # 대쉬/후딜 즉시 해제
                        rolling_active = False
                        rolling_stun_timer = 0
                        current_speed = 0  # 대쉬 잔여 속도 제거 (텔레포트 후 역방향 이동 방지)
                        stop_dash_delay_sound()  # 후딜 사운드 즉시 중지

                        # 원래 위치에 잔상 생성
                        _viper_ss_hologram_origin_x = PLAYER.centerx
                        _viper_ss_hologram_origin_y = PLAYER.centery
                        try:
                            _ss_afterimage_surf = pygame.Surface((PLAYER.width, PLAYER.height), pygame.SRCALPHA)
                            _ss_afterimage_surf.fill((100, 0, 180, 120))
                            dash_afterimages.append({
                                'x': PLAYER.centerx,
                                'y': PLAYER.centery,
                                'alpha': 200,
                                'image': _ss_afterimage_surf,
                                'life': 30,  # 홀로그램 동안 유지
                                'viper_ss': True,  # 쉐도우 백스텝 잔상 태그
                                'width': PLAYER.width,
                                'height': PLAYER.height,
                                'hit_ball': False,  # 공 타격 여부 (1회 제한)
                            })
                        except Exception:
                            pass

                        # 목표 위치 계산 (대쉬 시작 전 원점으로 스냅백)
                        _ss_new_x = _viper_dash_origin_x
                        _ss_new_x = max(PLAYER.width // 2, min(WIDTH - PLAYER.width // 2, _ss_new_x))
                        # 커브 방향: 원점이 현재 위치 기준 왼쪽이면 -1, 오른쪽이면 1
                        _ss_reverse_dir = 1 if _ss_new_x > PLAYER.centerx else -1

                        # 즉시 텔레포트 + 홀로그램 연출 시작
                        PLAYER.centerx = _ss_new_x
                        _viper_ss_hologram_active = True
                        _viper_ss_hologram_start_ms = pygame.time.get_ticks()
                        _viper_ss_hologram_target_x = _ss_new_x
                        _viper_ss_hologram_kick_dir = _ss_reverse_dir  # 발차기 방향
                        _viper_ss_hologram_kick_hit = False  # 킥 히트 초기화
                        _viper_ss_hit_consumed = False  # 그라데이션 타격 중복 방지 초기화
                        _viper_ss_was_airborne = (_viper_jetpack_offset_y < -10)  # 체공 중 발동 여부 기록
                        _viper_ss_kick_ready = True  # 다음 패들 히트 시 shadowkick.wav 재생 대기
                        _viper_ss_ball_touched = False  # 공 히트 추적 초기화 (카운터 연계 조건)

                        # 팬텀 스트라이크 버프 활성화 (0.3초간 다음 타격 강화)
                        _viper_phantom_strike_active = True
                        _viper_phantom_strike_timer = _VIPER_PHANTOM_STRIKE_DURATION
                        _viper_phantom_strike_curve_dir = _ss_reverse_dir  # 텔레포트 방향으로 커브

                        # 출발점 이펙트 (사라지는 연출)
                        try:
                            effects_manager.spawn_shockwave(
                                _viper_ss_hologram_origin_x, _viper_ss_hologram_origin_y - 10,
                                force=5, color=(80, 0, 160),
                            )
                        except Exception:
                            pass

                        # 에너지파 발사 (출발점 → 도착점, 공 히트 시 팬텀 스트라이크)
                        _viper_ss_wave_active = True
                        _viper_ss_wave_origin_x = float(_viper_ss_hologram_origin_x)
                        _viper_ss_wave_x = float(_viper_ss_hologram_origin_x)
                        _viper_ss_wave_y = float(_viper_ss_hologram_origin_y)
                        _viper_ss_wave_target_x = float(_ss_new_x)
                        _viper_ss_wave_dir = _ss_reverse_dir
                        _viper_ss_wave_hit_ball = False
                        _viper_ss_wave_trail.clear()

        elif _viper_can_act:
            # 에어 블레이드 (W/↑키) — 전방으로 검기 발사 또는 베놈 엣지 연계
            if _viper_w_pressed and _viper_w_key_released:
                # 연계기 판정: 에어 블레이드 Phase 2 하강 구간 (검기 발사 후 내려올 때 ~ 착지 전)
                _ns_br_elapsed = pygame.time.get_ticks() - _viper_br_spin_start_ms if _viper_br_spin_active else 0
                if (_viper_br_spin_active and _viper_br_spin_phase == 2
                        and _ns_br_elapsed >= 300  # 점프 정점 이후 (하강 시작)
                        and not _viper_nerve_strike_combo_used
                        and not _viper_nerve_strike_active
                        and is_viper_skill_unlocked("nerve_strike")
                        and special_gauge >= 80):
                    _viper_w_key_released = False
                    special_gauge -= 80
                    _viper_nerve_strike_combo_used = True
                    trigger_viper_skill_cooldown("nerve_strike")  # 베놈 엣지 쿨타임 50초

                    # 신경 타격 돌진 애니메이션 시작
                    _viper_nerve_strike_show_sound_played = False  # 텍스트 사운드 플래그 초기화
                    _viper_nerve_strike_active = True
                    _viper_nerve_strike_phase = 0  # 돌진 단계
                    _viper_nerve_strike_start_ms = pygame.time.get_ticks()
                    # 돌진 사운드 재생
                    try:
                        _vm_snd = sound_effects.get('VIPER_VENOM_MOVING')
                        if _vm_snd:
                            _vm_snd.set_volume(0.6)
                            _vm_snd.play()
                    except Exception:
                        pass
                    _viper_nerve_strike_origin_x = float(PLAYER.centerx)
                    _viper_nerve_strike_origin_y = float(PLAYER.centery)
                    _viper_nerve_strike_target_x = float(BOSS.centerx)
                    _viper_nerve_strike_target_y = float(BOSS.centery - (BOSS.height // 2) - 20)  # 보스 등뒤 (높이 기반 동적 계산)
                    _viper_nerve_strike_slash_shown = False

                    # 에어 블레이드 스핀 종료 (연계기로 전환)
                    _viper_br_spin_active = False
                    _viper_br_spin_angle = 0.0
                    _viper_br_jump_offset_y = 0.0
                    _viper_br_arm_raise = 0.0

                    try:
                        effects_manager.spawn_shockwave(
                            PLAYER.centerx, PLAYER.centery - 20,
                            force=8, color=(180, 0, 220),
                        )
                    except Exception:
                        pass

                # 일반 에어 블레이드 발동 (체공 중에만 발동 가능)
                elif is_viper_skill_unlocked("blade_rush") and _viper_jetpack_offset_y < 0:
                    if get_viper_skill_cooldown_remaining("blade_rush") <= 0:
                        if special_gauge >= 200 and not _viper_blade_rush_active and not _viper_br_spin_active and not _viper_nerve_strike_active:
                            _viper_w_key_released = False
                            special_gauge -= 200
                            trigger_viper_skill_cooldown("blade_rush")
                            _viper_nerve_strike_combo_used = False  # 새 에어 블레이드에서 연계기 초기화

                            # 회전 연출 시작 (회전 → 감속 → 정지 후 검기 발사)
                            _viper_br_spin_active = True
                            _viper_br_spin_start_ms = pygame.time.get_ticks()
                            _viper_br_spin_phase = 0  # 회전 단계
                            _viper_br_spin_angle = 0.0
                            # 회전 사운드 재생
                            try:
                                _spin_snd = sound_effects.get('VIPER_BLADE_SPIN')
                                if _spin_snd:
                                    _spin_snd.set_volume(0.8)
                                    _spin_snd.play()
                            except Exception:
                                pass

    # === 바이퍼 마샬 킥 연계기 (쉐도우 백스텝 → 0.5초 후 → S/↓키) ===
    # 쉐도우 백스텝 공 타격 후 0.5초 경과 시 마샬 킥 윈도우 자동 활성화 (쿨타임 체크)
    if _viper_ss_ball_touched and not _viper_wall_dive_ready:
        if pygame.time.get_ticks() - _viper_ss_ball_touched_ms >= _VIPER_MARSHAL_KICK_1ST_DELAY_MS:
            if get_viper_skill_cooldown_remaining("marshal_kick") <= 0 and special_gauge >= _VIPER_WALL_DIVE_GAUGE_COST:
                _viper_wall_dive_ready = True
                _viper_wall_dive_ready_timer = _VIPER_WALL_DIVE_READY_FRAMES  # 3초 윈도우
            _viper_ss_ball_touched = False  # 1회 소모

    # 연계 윈도우 타이머 감소 (게이지 부족 시 즉시 해제)
    if _viper_wall_dive_ready:
        _viper_wall_dive_ready_timer -= 1
        if _viper_wall_dive_ready_timer <= 0 or special_gauge < _VIPER_WALL_DIVE_GAUGE_COST:
            _viper_wall_dive_ready = False

    # 팬텀 킥: 1차 마샬 킥 공 타격 후 0.2초 경과 시 자동 활성화 (퍽 해금 + 쿨타임 체크)
    if _viper_marshal_kick_hit_ball and _viper_ss_was_airborne and not _viper_double_marshal_ready:
        if pygame.time.get_ticks() - _viper_marshal_kick_hit_ms >= _VIPER_MARSHAL_KICK_2ND_DELAY_MS:
            if _viper_double_marshal_kick_unlocked and get_viper_skill_cooldown_remaining("phantom_kick") <= 0 and special_gauge >= 60:
                _viper_double_marshal_ready = True
                _viper_double_marshal_ready_timer = _VIPER_WALL_DIVE_READY_FRAMES  # 3초 윈도우
            _viper_marshal_kick_hit_ball = False  # 1회 소모

    # 팬텀 킥 윈도우 타이머 감소 (게이지 부족 시 즉시 해제)
    if _viper_double_marshal_ready:
        _viper_double_marshal_ready_timer -= 1
        if _viper_double_marshal_ready_timer <= 0 or special_gauge < 60:
            _viper_double_marshal_ready = False

    # 마샬 킥 발동: 연계 윈도우 또는 더블 마샬 윈도우 중 S/↓키 단독 입력
    _wd_br_allow = False
    if _viper_br_spin_active and _viper_br_spin_phase == 2 and _viper_nerve_strike_combo_used:
        _wd_br_elapsed = pygame.time.get_ticks() - _viper_br_spin_start_ms
        if _wd_br_elapsed >= 300:
            _wd_br_allow = True
    _wd_can_fire = _viper_wall_dive_ready or _viper_double_marshal_ready
    if (selected_character_type == "viper" and not is_odins_eye_transformed()
            and _wd_can_fire and not _viper_wall_dive_active
            and not rolling_active and not _viper_dive_active
            and not _viper_nerve_strike_active
            and (not _viper_br_spin_active or _wd_br_allow)
            and not is_waiting_for_serve and not is_player_serve and not player_stunned):
        _wd_s_input = keys[pygame.K_s] or keys[pygame.K_DOWN]
        _wd_dir_held = (
            keys[pygame.K_LEFT] or keys[pygame.K_RIGHT]
            or keys[pygame.K_a] or keys[pygame.K_d]
            or MOVE_EVENT_LEFT or MOVE_EVENT_RIGHT
        )
        _wd_is_double = _viper_double_marshal_ready and not _viper_wall_dive_ready
        _wd_gauge_cost = 60 if _wd_is_double else _VIPER_WALL_DIVE_GAUGE_COST
        if (_wd_s_input and not _wd_dir_held
                and special_gauge >= _wd_gauge_cost
                and is_viper_skill_unlocked("shadow_step")):
            special_gauge -= _wd_gauge_cost
            # 팬텀 킥인지 판별 + 각자 독립 쿨타임 트리거
            _viper_is_double_marshal = _wd_is_double
            if _wd_is_double:
                trigger_viper_skill_cooldown("phantom_kick")   # 팬텀 킥 쿨타임 40초
                # 흑연 오라 활성화
                _viper_phantom_aura_active = True
                _viper_phantom_aura_start_ms = pygame.time.get_ticks()
            else:
                trigger_viper_skill_cooldown("marshal_kick")   # 마샬 킥 쿨타임 25초
            _viper_wall_dive_ready = False
            _viper_wall_dive_ready_timer = 0
            _viper_double_marshal_ready = False
            _viper_double_marshal_ready_timer = 0
            _viper_marshal_kick_hit_ball = False
            _viper_ss_kick_ready = False  # 쉐도우 킥 사운드 소모
            # 에어 블레이드 체공 중이면 스핀 즉시 종료
            if _viper_br_spin_active:
                _viper_br_spin_active = False
                _viper_br_spin_angle = 0.0
                _viper_br_jump_offset_y = 0.0
                _viper_br_arm_raise = 0.0
            _viper_wall_dive_active = True
            _viper_wall_dive_phase = 0  # 벽으로 점프
            _viper_wall_dive_start_ms = pygame.time.get_ticks()
            _viper_wall_dive_start_x = float(PLAYER.centerx)
            _viper_wall_dive_start_y = float(PLAYER.centery)
            _viper_wall_dive_ball_hit = False
            _viper_wall_dive_particles = []
            # 공 위치 기준 반대쪽 벽으로 점프 (대각선 돌진 궤적)
            _wd_ball_cx = BALL.centerx
            if _wd_ball_cx >= WIDTH // 2:
                _viper_wall_dive_wall_x = 15.0  # 공이 우측 → 좌측 벽으로
            else:
                _viper_wall_dive_wall_x = float(WIDTH - 15)  # 공이 좌측 → 우측 벽으로
            # 벽 매달림 Y: 바닥에서 200px 상승, 이미 높을수록 상승량 비례 감소 (자연스러운 벽타기)
            _wd_ground_y = 710.0   # 바닥 기준
            _wd_min_y = 200.0      # 벽타기 최소 Y (보스 영역 침범 방지)
            _wd_max_rise = 200.0   # 바닥에서의 최대 상승량
            _wd_min_rise = 50.0    # 최소 상승량 (높은 곳에서도 약간은 올라감)
            _wd_height_ratio = max(0.0, min(1.0, (float(PLAYER.centery) - _wd_min_y) / (_wd_ground_y - _wd_min_y)))
            _wd_rise = _wd_min_rise + (_wd_max_rise - _wd_min_rise) * _wd_height_ratio
            _viper_wall_dive_wall_y = float(PLAYER.centery) - _wd_rise
            _viper_wall_dive_wall_y = max(_wd_min_y, min(650.0, _viper_wall_dive_wall_y))
            # 로프를 벽 목표점까지 즉시 발사 (스파이더맨 스타일)
            _viper_wall_dive_web_lines = [
                (float(PLAYER.centerx), float(PLAYER.centery),
                 _viper_wall_dive_wall_x, _viper_wall_dive_wall_y)
            ]
            # 사운드
            try:
                _wd_snd = sound_effects.get('VIPER_BACKSTEP')
                if _wd_snd:
                    _wd_snd.set_volume(0.5)
                    _wd_snd.play()
            except Exception:
                pass

    # 마샬 킥 애니메이션 업데이트
    if _viper_wall_dive_active:
        _wd_now = pygame.time.get_ticks()
        _wd_elapsed = _wd_now - _viper_wall_dive_start_ms
        import random as _wd_rand

        if _viper_wall_dive_phase == 0:
            # Phase 0: 로프를 벽에 쏘고 끌려가며 이동 (스파이더맨/산나비 스타일)
            # 팬텀 킥(2차)은 로프 이동 30% 빠르게
            _wd_jump_ms = _VIPER_WALL_DIVE_JUMP_MS / 1.3 if _viper_is_double_marshal else _VIPER_WALL_DIVE_JUMP_MS
            _wd_t = min(1.0, _wd_elapsed / _wd_jump_ms)
            _wd_ease = 1.0 - (1.0 - _wd_t) ** 2  # ease-out quadratic (자연스러운 당김 → 벽 근처 감속)
            # 플레이어가 로프에 끌려감
            _wd_cx = _viper_wall_dive_start_x + (_viper_wall_dive_wall_x - _viper_wall_dive_start_x) * _wd_ease
            _wd_cy = _viper_wall_dive_start_y + (_viper_wall_dive_wall_y - _viper_wall_dive_start_y) * _wd_ease
            PLAYER.centerx = int(_wd_cx)
            PLAYER.centery = int(_wd_cy)
            # 로프: 플레이어 현재 위치 → 벽 목표점 (항상 벽까지 일직선)
            _viper_wall_dive_web_lines = [
                (_wd_cx, _wd_cy, _viper_wall_dive_wall_x, _viper_wall_dive_wall_y)
            ]
            # 잔상 파티클
            if _wd_rand.random() < 0.6:
                _viper_wall_dive_particles.append({
                    'x': _wd_cx + _wd_rand.uniform(-10, 10),
                    'y': _wd_cy + _wd_rand.uniform(-5, 5),
                    'vx': _wd_rand.uniform(-2, 2), 'vy': _wd_rand.uniform(-1, 1),
                    'life': _wd_rand.randint(10, 20), 'max_life': 20,
                    'size': _wd_rand.uniform(3, 8), 'type': 'trail',
                })
            if _wd_t >= 1.0:
                _viper_wall_dive_phase = 1
                _viper_wall_dive_start_ms = _wd_now
                PLAYER.centerx = int(_viper_wall_dive_wall_x)
                PLAYER.centery = int(_viper_wall_dive_wall_y)
                # 벽 착지 이펙트
                screen_shake_timer = max(screen_shake_timer, 6)
                screen_shake_intensity = max(screen_shake_intensity, 3)
                # 벽 착지: 로프 제거 (도착 완료)
                _viper_wall_dive_web_lines = []

        elif _viper_wall_dive_phase == 1:
            # Phase 1: 벽 매달림 (스파이더맨 포즈, 공 위치 스냅샷)
            _wd_t = min(1.0, _wd_elapsed / _VIPER_WALL_DIVE_CLING_MS)
            PLAYER.centerx = int(_viper_wall_dive_wall_x)
            PLAYER.centery = int(_viper_wall_dive_wall_y)
            if _wd_t >= 1.0:
                # === 벽다시타기 감지: 공의 X가 현재 벽과 너무 가까우면 반대편 벽으로 ===
                _wd_ball_dist_x = abs(BALL.centerx - _viper_wall_dive_wall_x)
                if _wd_ball_dist_x < _VIPER_WALL_DIVE_RECLIMB_THRESHOLD:
                    # 반대편 벽으로 벽다시타기 (Phase 3)
                    _viper_wall_dive_phase = 3
                    _viper_wall_dive_start_ms = _wd_now
                    _viper_wall_dive_reclimb_start_x = float(_viper_wall_dive_wall_x)
                    _viper_wall_dive_reclimb_start_y = float(_viper_wall_dive_wall_y)
                    # 반대편 벽으로 목표 설정
                    if _viper_wall_dive_wall_x < WIDTH // 2:
                        _viper_wall_dive_wall_x = float(WIDTH - 15)
                    else:
                        _viper_wall_dive_wall_x = 15.0
                    # Y는 공 높이에 맞춰 조정 (보스 영역 직전까지 허용)
                    _viper_wall_dive_wall_y = max(120.0, min(650.0, float(BALL.centery) - 50.0))
                    # 로프를 반대편 벽 목표점까지 즉시 발사
                    _viper_wall_dive_web_lines = [
                        (float(_viper_wall_dive_reclimb_start_x), float(_viper_wall_dive_reclimb_start_y),
                         _viper_wall_dive_wall_x, _viper_wall_dive_wall_y)
                    ]
                    # 벽다시타기 사운드 (빠르게)
                    try:
                        _wd_reclimb_snd = sound_effects.get('VIPER_BACKSTEP')
                        if _wd_reclimb_snd:
                            _wd_reclimb_snd.set_volume(0.4)
                            _wd_reclimb_snd.play()
                    except Exception:
                        pass
                else:
                    # 팬텀 킥이면 돌진 전에 텍스트 프리즈 연출 (Phase 6)
                    if _viper_is_double_marshal:
                        _viper_wall_dive_phase = 6  # 텍스트 프리즈 Phase
                        _viper_dmk_freeze_active = True
                        _viper_dmk_freeze_timer = _VIPER_DMK_FREEZE_DURATION
                        _viper_dmk_show_sound_played = False
                        _viper_dmk_text_active = True
                        _viper_dmk_text_timer = _VIPER_DMK_TEXT_DURATION + _VIPER_DMK_FREEZE_DURATION
                        _viper_dmk_text_x = float(WIDTH // 2)
                        _viper_dmk_text_y = float(HEIGHT // 2 - 30)
                    else:
                        _viper_wall_dive_phase = 2
                        _viper_wall_dive_start_ms = _wd_now
                        # 돌진 목표: 실시간 공 위치 추적 (매 프레임 갱신됨)
                        _viper_wall_dive_charge_target_x = float(BALL.centerx)
                        _viper_wall_dive_charge_target_y = float(BALL.centery)
                        _viper_wall_dive_charge_start_x = float(_viper_wall_dive_wall_x)
                        _viper_wall_dive_charge_start_y = float(_viper_wall_dive_wall_y)
                        _viper_wall_dive_web_lines = []  # 거미줄 제거
                        # 돌진 사운드
                        try:
                            _wd_charge_snd = sound_effects.get('VIPER_SHADOW_KICK')
                            if _wd_charge_snd:
                                _wd_charge_snd.set_volume(0.6)
                                _wd_charge_snd.play()
                        except Exception:
                            pass

        elif _viper_wall_dive_phase == 3:
            # Phase 3: 벽다시타기 - 반대편 벽으로 매우 빠르게 이동
            _wd_t = min(1.0, _wd_elapsed / _VIPER_WALL_DIVE_RECLIMB_MS)
            _wd_ease = _wd_t * _wd_t * (3.0 - 2.0 * _wd_t)  # ease-in-out
            _wd_cx = _viper_wall_dive_reclimb_start_x + (_viper_wall_dive_wall_x - _viper_wall_dive_reclimb_start_x) * _wd_ease
            _wd_cy = _viper_wall_dive_reclimb_start_y + (_viper_wall_dive_wall_y - _viper_wall_dive_reclimb_start_y) * _wd_ease
            PLAYER.centerx = int(_wd_cx)
            PLAYER.centery = int(_wd_cy)
            # 로프: 현재 위치 → 벽 목표점 (끌려가는 동안 로프 유지)
            _viper_wall_dive_web_lines = [
                (_wd_cx, _wd_cy, _viper_wall_dive_wall_x, _viper_wall_dive_wall_y)
            ]
            # 잔상 파티클 (보라색 강조)
            if _wd_rand.random() < 0.8:
                _viper_wall_dive_particles.append({
                    'x': _wd_cx + _wd_rand.uniform(-6, 6),
                    'y': _wd_cy + _wd_rand.uniform(-6, 6),
                    'vx': _wd_rand.uniform(-4, 4), 'vy': _wd_rand.uniform(-2, 2),
                    'life': _wd_rand.randint(6, 14), 'max_life': 14,
                    'size': _wd_rand.uniform(3, 7), 'type': 'trail',
                })
            if _wd_t >= 1.0:
                # 벽다시타기 완료
                PLAYER.centerx = int(_viper_wall_dive_wall_x)
                PLAYER.centery = int(_viper_wall_dive_wall_y)
                _viper_wall_dive_web_lines = []
                screen_shake_timer = max(screen_shake_timer, 4)
                screen_shake_intensity = max(screen_shake_intensity, 2)
                if _viper_is_double_marshal:
                    # 팬텀 킥: 재등반 후에도 텍스트 프리즈 연출 (Phase 6)
                    _viper_wall_dive_phase = 6
                    _viper_dmk_freeze_active = True
                    _viper_dmk_freeze_timer = _VIPER_DMK_FREEZE_DURATION
                    _viper_dmk_show_sound_played = False
                    _viper_dmk_text_active = True
                    _viper_dmk_text_timer = _VIPER_DMK_TEXT_DURATION + _VIPER_DMK_FREEZE_DURATION
                    _viper_dmk_text_x = float(WIDTH // 2)
                    _viper_dmk_text_y = float(HEIGHT // 2 - 30)
                else:
                    # 일반 마샬킥: 즉시 돌진 (Phase 2)
                    _viper_wall_dive_phase = 2
                    _viper_wall_dive_start_ms = _wd_now
                    _viper_wall_dive_charge_target_x = float(BALL.centerx)
                    _viper_wall_dive_charge_target_y = float(BALL.centery)
                    _viper_wall_dive_charge_start_x = float(_viper_wall_dive_wall_x)
                    _viper_wall_dive_charge_start_y = float(_viper_wall_dive_wall_y)
                    # 돌진 사운드
                    try:
                        _wd_charge_snd = sound_effects.get('VIPER_SHADOW_KICK')
                        if _wd_charge_snd:
                            _wd_charge_snd.set_volume(0.6)
                            _wd_charge_snd.play()
                    except Exception:
                        pass

        elif _viper_wall_dive_phase == 6:
            # Phase 6: 팬텀 킥 텍스트 프리즈 (벽 매달린 상태에서 정지)
            PLAYER.centerx = int(_viper_wall_dive_wall_x)
            PLAYER.centery = int(_viper_wall_dive_wall_y)
            # 프리즈 끝나면 돌진 Phase 2로 전환
            if not _viper_dmk_freeze_active:
                _viper_wall_dive_phase = 2
                _viper_wall_dive_start_ms = _wd_now
                _viper_wall_dive_charge_target_x = float(BALL.centerx)
                _viper_wall_dive_charge_target_y = float(BALL.centery)
                _viper_wall_dive_charge_start_x = float(_viper_wall_dive_wall_x)
                _viper_wall_dive_charge_start_y = float(_viper_wall_dive_wall_y)
                _viper_wall_dive_web_lines = []
                # 돌진 사운드
                try:
                    _wd_charge_snd = sound_effects.get('VIPER_SHADOW_KICK')
                    if _wd_charge_snd:
                        _wd_charge_snd.set_volume(0.6)
                        _wd_charge_snd.play()
                except Exception:
                    pass

        elif _viper_wall_dive_phase == 2:
            # Phase 2: 공을 향해 돌진 (실시간 추적)
            # 팬텀 킥(2차)은 돌진 30% 빠르게
            _wd_charge_ms = _VIPER_WALL_DIVE_CHARGE_MS / 1.3 if _viper_is_double_marshal else _VIPER_WALL_DIVE_CHARGE_MS
            _wd_t = min(1.0, _wd_elapsed / _wd_charge_ms)
            _wd_ease = _wd_t * _wd_t  # ease-in (가속)
            # 매 프레임 공의 실시간 위치로 목표 갱신
            _viper_wall_dive_charge_target_x = float(BALL.centerx)
            _viper_wall_dive_charge_target_y = float(BALL.centery)
            _wd_cx = _viper_wall_dive_charge_start_x + (_viper_wall_dive_charge_target_x - _viper_wall_dive_charge_start_x) * _wd_ease
            _wd_cy = _viper_wall_dive_charge_start_y + (_viper_wall_dive_charge_target_y - _viper_wall_dive_charge_start_y) * _wd_ease
            PLAYER.centerx = int(_wd_cx)
            PLAYER.centery = int(_wd_cy)
            # 돌진 파티클
            if _wd_rand.random() < 0.7:
                _viper_wall_dive_particles.append({
                    'x': _wd_cx + _wd_rand.uniform(-8, 8),
                    'y': _wd_cy + _wd_rand.uniform(-8, 8),
                    'vx': _wd_rand.uniform(-3, 3), 'vy': _wd_rand.uniform(-3, 3),
                    'life': _wd_rand.randint(8, 16), 'max_life': 16,
                    'size': _wd_rand.uniform(4, 10), 'type': 'charge',
                })
            # 공 충돌 판정 (넓은 히트박스)
            if not _viper_wall_dive_ball_hit:
                _wd_dist = math.hypot(BALL.centerx - _wd_cx, BALL.centery - _wd_cy)
                if _wd_dist <= _VIPER_WALL_DIVE_HIT_RADIUS:
                    _viper_wall_dive_ball_hit = True
                    # 팬텀 킥 퍽: 1차 마샬 킥 히트 시 플래그 설정
                    if _viper_ss_was_airborne and not _viper_is_double_marshal:
                        _viper_marshal_kick_hit_ball = True
                        _viper_marshal_kick_hit_ms = pygame.time.get_ticks()
                    # 공을 위로 강하게 반사 + 속도 증가
                    _wd_cur_spd = math.hypot(ball_vel[0], ball_vel[1])
                    # 2차 마샬 킥이면 250% 증가(3.5x), 1차는 100% 증가(2.0x)
                    if _viper_is_double_marshal:
                        _wd_new_spd = max(_wd_cur_spd * 3.5, 14.0)  # 250% 증가
                    else:
                        _wd_new_spd = max(_wd_cur_spd * 2.0, 11.0)  # 100% 증가
                    _viper_speed_boost_active = True
                    _viper_speed_boost_original = _wd_cur_spd
                    # 랜덤 발사각 (마샬/팬텀 킥: 티어별 보스 회피 편향 차등 적용)
                    # 스킬 티어별 가중치: 쉐도우 백스텝=0.2, 마샬 킥=0.5, 팬텀 킥=0.8
                    import random as _mk_rand
                    _mk_bias = 0.8 if _viper_is_double_marshal else 0.5
                    _mk_random_angle = _mk_rand.uniform(-55, 55)  # 순수 랜덤 각도
                    _mk_boss_cx = BOSS.centerx if BOSS else WIDTH // 2
                    _mk_boss_dx = _mk_boss_cx - BALL.centerx
                    _mk_away_dir = -1 if _mk_boss_dx > 0 else (1 if _mk_boss_dx < 0 else _mk_rand.choice([-1, 1]))
                    _mk_avoidance = _mk_away_dir * _mk_rand.uniform(25, 50)  # 회피 보너스 각도
                    _mk_final_angle = _mk_random_angle * (1.0 - _mk_bias) + _mk_avoidance * _mk_bias
                    _mk_final_angle = max(-60, min(60, _mk_final_angle))  # 클램프
                    _mk_rad = math.radians(-90 + _mk_final_angle)
                    ball_vel[0] = math.cos(_mk_rad) * _wd_new_spd
                    ball_vel[1] = math.sin(_mk_rad) * _wd_new_spd
                    # 스타버스트 타격 이펙트 트리거
                    _viper_starburst_active = True
                    _viper_starburst_x = float(BALL.centerx)
                    _viper_starburst_y = float(BALL.centery)
                    _viper_starburst_frame = 0
                    _viper_starburst_timer = 0
                    _viper_starburst_is_double = _viper_is_double_marshal
                    # 팬텀 킥: 공이 보스 패들에 맞을 때 넉백 적용 (플래그 설정)
                    if _viper_is_double_marshal:
                        _viper_phantom_kick_knockback_pending = True
                        # 팬텀 킥 전용 타격 사운드
                        try:
                            _pk_hit_snd = sound_effects.get('VIPER_PHANTOM_KICK_HIT')
                            if _pk_hit_snd:
                                _pk_hit_snd.set_volume(0.8)
                                _pk_hit_snd.play()
                        except Exception:
                            pass
                    # 히트 이펙트
                    _shake_force = 20 if _viper_is_double_marshal else 12
                    _shake_int = 8 if _viper_is_double_marshal else 5
                    screen_shake_timer = max(screen_shake_timer, _shake_force)
                    screen_shake_intensity = max(screen_shake_intensity, _shake_int)
                    try:
                        effects_manager.spawn_shockwave(
                            BALL.centerx, BALL.centery,
                            force=14, color=(160, 0, 255),
                        )
                    except Exception:
                        pass
                    # 검붉은 타격 이펙트 (마샬 킥)
                    try:
                        _mk_impact_intensity = 2.5 if _viper_is_double_marshal else 1.0
                        _mk_impact_count = 40 if _viper_is_double_marshal else 24
                        effects_manager.spawn_dark_red_impact(
                            BALL.centerx, BALL.centery,
                            count=_mk_impact_count, intensity=_mk_impact_intensity,
                        )
                    except Exception:
                        pass
                    # 팬텀 킥: 보랏빛 암흑 에너지 파편 폭발
                    if _viper_is_double_marshal:
                        _ph_bx, _ph_by = float(BALL.centerx), float(BALL.centery)
                        for _phi in range(85):
                            _ph_ang = _wd_rand.uniform(0, math.tau)
                            _ph_spd = _wd_rand.uniform(3.5, 13.0)
                            _ph_life = _wd_rand.randint(30, 65)
                            _ph_palette = [
                                (80, 15, 120), (110, 25, 160), (60, 8, 95),
                                (130, 30, 180), (40, 0, 65), (95, 10, 140),
                                (120, 40, 155), (70, 12, 110),
                            ]
                            _ph_col = _ph_palette[_phi % len(_ph_palette)]
                            _viper_phantom_hit_particles.append({
                                'x': _ph_bx + _wd_rand.uniform(-8, 8),
                                'y': _ph_by + _wd_rand.uniform(-8, 8),
                                'vx': math.cos(_ph_ang) * _ph_spd + _wd_rand.uniform(-1.0, 1.0),
                                'vy': math.sin(_ph_ang) * _ph_spd + _wd_rand.uniform(-1.0, 1.0),
                                'life': _ph_life, 'max_life': _ph_life,
                                'size': _wd_rand.uniform(3.5, 8.0),
                                'color': _ph_col,
                                'glow': _wd_rand.random() < 0.5,
                            })
                    # 마샬 킥 강한 커브 적용
                    _viper_ps_curve_active = True
                    if _viper_is_double_marshal:
                        _viper_ps_curve_timer = int(_VIPER_PS_CURVE_FRAMES * 2.5)  # 더블: 커브 2.5배 지속 (괴랄한 궤적)
                    else:
                        _viper_ps_curve_timer = _VIPER_PS_CURVE_FRAMES
                    # 커브 방향: 발사 방향과 같은 쪽으로 (자연스러운 커브)
                    _viper_ps_curve_direction = 1 if ball_vel[0] > 0 else -1
                    # 🪙 마샬 킥 / 팬텀 킥 타격 골드 보너스 (마샬 30, 팬텀 50, 공중 쉐도우 백스텝 연계 시 x1.5)
                    try:
                        _mk_gold = 50 if _viper_is_double_marshal else 30
                        if _viper_ss_was_airborne:
                            _mk_gold = int(_mk_gold * 1.5)
                        add_ingame_gold(_mk_gold, BALL.centerx, BALL.centery - 20, source="skill")
                        _viper_skill_gold_this_frame = True
                    except Exception:
                        pass
                    # 공 타격 후 복귀 전환
                    if _viper_is_double_marshal:
                        # 팬텀 킥: Phase 5 (프리즈 중 제자리 대기) → 프리즈 끝나면 Phase 4
                        _viper_wall_dive_phase = 5
                    else:
                        _viper_wall_dive_phase = 4
                    _viper_wall_dive_start_ms = _wd_now
                    _viper_wall_dive_return_start_x = float(PLAYER.centerx)
                    _viper_wall_dive_return_start_y = float(PLAYER.centery)
            # 종료 판정 (돌진 시간 초과 시 = 공 못 맞힘)
            if _wd_t >= 1.0 and _viper_wall_dive_phase == 2:
                _viper_wall_dive_phase = 4
                _viper_wall_dive_start_ms = _wd_now
                _viper_wall_dive_return_start_x = float(PLAYER.centerx)
                _viper_wall_dive_return_start_y = float(PLAYER.centery)

        elif _viper_wall_dive_phase == 5:
            # Phase 5: 팬텀 킥 프리즈 중 제자리 대기 (공 발사 후 바이퍼 정지)
            # 프리즈가 끝나면 Phase 4 (복귀)로 전환
            PLAYER.centerx = int(_viper_wall_dive_return_start_x)
            PLAYER.centery = int(_viper_wall_dive_return_start_y)
            if not _viper_dmk_freeze_active:
                _viper_wall_dive_phase = 4
                _viper_wall_dive_start_ms = _wd_now

        elif _viper_wall_dive_phase == 4:
            # Phase 4: 공 타격 후 바닥으로 부드럽게 복귀
            _wd_t = min(1.0, _wd_elapsed / _VIPER_WALL_DIVE_RETURN_MS)
            _wd_ease = _wd_t * _wd_t * (3.0 - 2.0 * _wd_t)  # ease-in-out
            _wd_floor = _compute_player_floor_bottom(
                CURRENT_PADDLE_EFFECTIVE_SCALE if CURRENT_PADDLE_EFFECTIVE_SCALE else CURRENT_PADDLE_SIZE_SCALE
            )
            _wd_target_y = int(_wd_floor) - PLAYER.height // 2
            _wd_target_x = max(PLAYER.width // 2, min(WIDTH - PLAYER.width // 2, _viper_wall_dive_return_start_x))
            PLAYER.centerx = int(_viper_wall_dive_return_start_x + (_wd_target_x - _viper_wall_dive_return_start_x) * _wd_ease)
            PLAYER.centery = int(_viper_wall_dive_return_start_y + (_wd_target_y - _viper_wall_dive_return_start_y) * _wd_ease)
            # 낙하 잔상 파티클
            if _wd_rand.random() < 0.4:
                _viper_wall_dive_particles.append({
                    'x': float(PLAYER.centerx) + _wd_rand.uniform(-6, 6),
                    'y': float(PLAYER.centery) + _wd_rand.uniform(-4, 4),
                    'vx': _wd_rand.uniform(-1, 1), 'vy': _wd_rand.uniform(-2, 0),
                    'life': _wd_rand.randint(8, 14), 'max_life': 14,
                    'size': _wd_rand.uniform(2, 5), 'type': 'trail',
                })
            if _wd_t >= 1.0:
                _viper_wall_dive_active = False
                _viper_wall_dive_phase = 0
                _viper_wall_dive_web_lines = []
                PLAYER.centery = _wd_target_y
                PLAYER.centerx = _wd_target_x
                # 팬텀 킥 흑연 오라 비활성화
                if _viper_is_double_marshal:
                    _viper_phantom_aura_active = False

    # 팬텀 킥 프리즈 타이머 감소
    if _viper_dmk_freeze_active:
        _viper_dmk_freeze_timer -= 1
        if _viper_dmk_freeze_timer <= 0:
            _viper_dmk_freeze_active = False

    # 마샬 킥 파티클 업데이트
    if _viper_wall_dive_particles:
        _wd_alive = []
        for _wp in _viper_wall_dive_particles:
            _wp['x'] += _wp['vx']
            _wp['y'] += _wp['vy']
            _wp['life'] -= 1
            _wp['size'] *= 0.95
            if _wp['life'] > 0 and _wp['size'] > 0.5:
                _wd_alive.append(_wp)
        _viper_wall_dive_particles = _wd_alive[-60:] if len(_wd_alive) > 60 else _wd_alive

    # 바이퍼 팬텀 스트라이크 버프 타이머 감소
    if _viper_phantom_strike_active:
        _viper_phantom_strike_timer -= 1
        if _viper_phantom_strike_timer <= 0:
            _viper_phantom_strike_active = False
            # 헛방질 시 패들 히트 경로도 차단 (마샬킥 카운터 오활성화 방지)
            if not _viper_ss_hit_consumed:
                _viper_ss_kick_ready = False

    # 바이퍼 팬텀 스트라이크 커브 (깔끔한 호 궤적 — 감쇠 각도 변경 방식)
    if _viper_ps_curve_active:
        _viper_ps_curve_timer -= 1
        if _viper_ps_curve_timer <= 0:
            _viper_ps_curve_active = False
        else:
            _curve_total = _viper_ps_curve_total_frames if _viper_ps_curve_total_frames > 0 else _VIPER_PS_CURVE_FRAMES
            _curve_progress = 1.0 - (_viper_ps_curve_timer / _curve_total)
            # 감쇠 회전 — 공속은 유지하면서 진행 방향만 회전 (초반 강→점차 약)
            _curve_rot_deg = (1.0 - _curve_progress) * _viper_ps_curve_force * 0.35
            _curve_rot_rad = math.radians(_viper_ps_curve_direction * _curve_rot_deg)
            # 현재 속도 벡터를 회전 (크기 보존, 방향만 변경)
            _old_dx = ball_vel[0]
            _old_dy = ball_vel[1]
            _cos_r = math.cos(_curve_rot_rad)
            _sin_r = math.sin(_curve_rot_rad)
            ball_vel[0] = _old_dx * _cos_r - _old_dy * _sin_r
            ball_vel[1] = _old_dx * _sin_r + _old_dy * _cos_r

    # === 바이퍼 제트팩 시스템 업데이트 ===
    if selected_character_type == "viper" and not is_odins_eye_transformed():
        # 입력 감지: Space/좌클릭 홀드 (서브 대기/스턴/신경 타격/에어 블레이드 스핀/과열/급강하 중에는 비활성)
        _jetpack_input = False
        if not (is_waiting_for_serve or is_player_serve or player_stunned
                or _viper_nerve_strike_active or _viper_br_spin_active
                or rolling_active or _viper_jetpack_overheat or _viper_dive_active
                or _viper_wall_dive_active):
            try:
                _jk = pygame.key.get_pressed()
                _mb = pygame.mouse.get_pressed()
                _jetpack_input = bool(_jk[pygame.K_SPACE]) or bool(_mb[0])
            except Exception:
                pass

        global _viper_jetpack_snd_channel
        _was_jetpack_active = _viper_jetpack_active
        if _jetpack_input:
            _viper_jetpack_active = True
            _viper_jetpack_hold_timer += 1
            # 최대 체공 시간 초과 시 과열 → 강제 하강 (제트팩 강화 퍽 반영)
            if _viper_jetpack_hold_timer >= _get_viper_jetpack_max_hold():
                _viper_jetpack_overheat = True
                _viper_jetpack_active = False
                try:
                    if _viper_jetpack_snd_channel and _viper_jetpack_snd_channel.get_busy():
                        _viper_jetpack_snd_channel.fadeout(200)
                    _viper_jetpack_snd_channel = None
                except Exception:
                    _viper_jetpack_snd_channel = None
            else:
                # 상승
                _viper_jetpack_offset_y = max(-_VIPER_JETPACK_MAX_HEIGHT,
                                              _viper_jetpack_offset_y - _VIPER_JETPACK_RISE_SPEED)
        else:
            _viper_jetpack_active = False

        # 제트팩 사운드 루프 재생/정지
        try:
            if _viper_jetpack_active and not _was_jetpack_active:
                _jp_snd = sound_effects.get('VIPER_JETPACK')
                if _jp_snd:
                    _jp_snd.set_volume(0.35)
                    _viper_jetpack_snd_channel = _jp_snd.play(loops=-1)
            elif not _viper_jetpack_active and _was_jetpack_active:
                if _viper_jetpack_snd_channel and _viper_jetpack_snd_channel.get_busy():
                    _viper_jetpack_snd_channel.fadeout(200)
                    _viper_jetpack_snd_channel = None
        except Exception:
            pass

        # 하강 (제트팩 비활성 또는 과열 시 서서히 내려옴)
        if not _viper_jetpack_active and _viper_jetpack_offset_y < 0:
            # EMP 차징 중이면 하강 속도 서서히 감소 (진행도 비례: 100% → 10%)
            _jp_fall = _VIPER_JETPACK_FALL_SPEED
            if _viper_dive_hold_start_ms > 0:
                _jp_hold_p = min(1.0, (pygame.time.get_ticks() - _viper_dive_hold_start_ms) / _VIPER_DIVE_HOLD_REQUIRED_MS)
                _jp_fall = _VIPER_JETPACK_FALL_SPEED * (1.0 - _jp_hold_p * 0.9)
            _viper_jetpack_offset_y = min(0, _viper_jetpack_offset_y + _jp_fall)

        # 착지 시 과열 해제 + 체공 타이머 서서히 충전 (비행 소모의 2배 느리게)
        if _viper_jetpack_offset_y >= 0:
            if _viper_jetpack_overheat:
                _viper_jetpack_overheat = False
            if _viper_jetpack_hold_timer > 0 and not _viper_jetpack_active:
                _jp_recharge_rate = 0.5 * (1.0 + runtime_skill_levels.get("jetpack_enhance", 0) * 0.2)  # 퍽 레벨당 충전속도 +20%
                _viper_jetpack_hold_timer = max(0, _viper_jetpack_hold_timer - _jp_recharge_rate)

        # PLAYER rect Y 위치 적용 (물리 판정에 반영)
        if _viper_jetpack_offset_y < 0:
            _jpack_baseline = _compute_player_floor_bottom(
                CURRENT_PADDLE_EFFECTIVE_SCALE if CURRENT_PADDLE_EFFECTIVE_SCALE else CURRENT_PADDLE_SIZE_SCALE
            )
            PLAYER.bottom = int(_jpack_baseline + _viper_jetpack_offset_y)

        # 제트팩 화염 + 연기 파티클 생성
        if _viper_jetpack_active:
            import random as _jp_rand
            # 화염 파티클 (시안/퍼플, 빠르게 하강)
            for _ in range(3):
                _viper_jetpack_particles.append({
                    'x': PLAYER.centerx + _jp_rand.randint(-10, 10),
                    'y': float(PLAYER.bottom),
                    'vx': _jp_rand.uniform(-1.2, 1.2),
                    'vy': _jp_rand.uniform(2.0, 5.0),
                    'life': _jp_rand.randint(8, 18),
                    'max_life': 18,
                    'size': _jp_rand.uniform(3.0, 7.0),
                    'type': 'flame',
                    'width': _jp_rand.uniform(1.5, 3.0),  # 타원 가로폭 비율
                })
            # 연기 파티클 (회색, 느리게 퍼짐)
            if _jp_rand.random() < 0.4:
                _viper_jetpack_particles.append({
                    'x': PLAYER.centerx + _jp_rand.randint(-6, 6),
                    'y': float(PLAYER.bottom + 5),
                    'vx': _jp_rand.uniform(-0.5, 0.5),
                    'vy': _jp_rand.uniform(0.5, 1.5),
                    'life': _jp_rand.randint(15, 30),
                    'max_life': 30,
                    'size': _jp_rand.uniform(4.0, 8.0),
                    'type': 'smoke',
                    'width': 1.0,
                })

        # AIR STRIKE 텍스트 타이머 감소
        global _viper_air_strike_text_timer, _viper_air_strike_text_x, _viper_air_strike_text_y, _viper_air_strike_text_pct
        if _viper_air_strike_text_timer > 0:
            _viper_air_strike_text_timer -= 1
            _viper_air_strike_text_y -= 1.2  # 위로 떠오름

        # 파티클 업데이트
        _jp_alive = []
        for _jp in _viper_jetpack_particles:
            _jp['x'] += _jp['vx']
            _jp['y'] += _jp['vy']
            _jp['life'] -= 1
            _jp['size'] = max(0.5, _jp['size'] - 0.2)
            if _jp['life'] > 0:
                _jp_alive.append(_jp)
        _viper_jetpack_particles = _jp_alive[-80:] if len(_jp_alive) > 80 else _jp_alive

    # === 바이퍼 에어 블레이드 → 마샬 킥 직접 연계 제거 ===
    # 에어블레이드 → 베놈 엣지(실패) → 마샬 킥 순서로만 연계 가능
    # 에어블레이드 중 S/↓키는 EMP 스트라이크로 연계됨
    _viper_air_marshal_triggered = False

    # === 바이퍼 급강하 어택 (EMP 스트라이크) ===
    # EMP 스트라이크: 체공 중 S/↓키 0.3초 꾹 누르기로 발동 (단독 사용만)
    if selected_character_type == "viper" and not is_odins_eye_transformed():
        _dive_s_input = keys[pygame.K_s] or keys[pygame.K_DOWN]
        _dive_dir_held = (
            keys[pygame.K_LEFT] or keys[pygame.K_RIGHT]
            or keys[pygame.K_a] or keys[pygame.K_d]
            or MOVE_EVENT_LEFT or MOVE_EVENT_RIGHT
        )
        # 다른 스킬 활성 중이면 홀드 차단
        _dive_any_skill_active = (
            rolling_active
            or _viper_ss_hologram_active
            or _viper_wall_dive_active
            or _viper_wall_dive_ready
            or _viper_double_marshal_ready
            or _viper_nerve_strike_active
            or _viper_blade_rush_active
            or _viper_br_spin_active
        )
        # S/↓키 홀드 타이머 관리
        _dive_can_hold = (
            not _viper_dive_active
            and _viper_jetpack_offset_y < -20
            and not _dive_any_skill_active
            and not _dive_dir_held
            and not is_waiting_for_serve
            and not is_player_serve and not player_stunned
            and special_gauge >= _VIPER_DIVE_GAUGE_COST
            and is_viper_skill_unlocked("dive_strike")
            and get_viper_skill_cooldown_remaining("dive_strike") <= 0
        )
        if _dive_s_input and _dive_can_hold:
            if _viper_dive_hold_start_ms == 0:
                _viper_dive_hold_start_ms = pygame.time.get_ticks()
                _viper_dive_charge_particles = []
            # 홀드 진행도 (0→1)에 따라 발밑 화염 파티클 생성
            _dive_hold_elapsed = pygame.time.get_ticks() - _viper_dive_hold_start_ms
            _dive_hold_progress = min(1.0, _dive_hold_elapsed / _VIPER_DIVE_HOLD_REQUIRED_MS)
            import random as _dcp_rand
            # 진행도에 비례해 파티클 생성량 증가 (초반 1~2개 → 후반 5~6개/프레임)
            _dcp_spawn_count = int(1 + _dive_hold_progress * 5)
            _dcp_foot_x = float(PLAYER.centerx)
            _dcp_foot_y = float(PLAYER.centery + PLAYER.height // 2)
            for _ in range(_dcp_spawn_count):
                # 발바닥 좌우로 퍼지며 위로 튀어오르는 불꽃
                _dcp_palette = [
                    (255, 180, 60), (255, 140, 30), (255, 210, 90),
                    (255, 100, 20), (255, 220, 130), (240, 160, 50),
                    (255, 240, 180), (255, 120, 40),
                ]
                _dcp_col = _dcp_palette[_dcp_rand.randint(0, len(_dcp_palette) - 1)]
                _dcp_spread = 8 + _dive_hold_progress * 14  # 진행도에 따라 넓게
                _viper_dive_charge_particles.append({
                    'x': _dcp_foot_x + _dcp_rand.uniform(-_dcp_spread, _dcp_spread),
                    'y': _dcp_foot_y + _dcp_rand.uniform(-2, 4),
                    'vx': _dcp_rand.uniform(-0.8, 0.8),
                    'vy': _dcp_rand.uniform(-3.5, -1.0) * (0.6 + _dive_hold_progress * 0.6),
                    'life': _dcp_rand.randint(12, 28),
                    'max_life': 28,
                    'size': _dcp_rand.uniform(2.0, 4.5 + _dive_hold_progress * 2.0),
                    'color': _dcp_col,
                })
        else:
            _viper_dive_hold_start_ms = 0
            _viper_dive_charge_particles = []
        # 0.5초 홀드 완료 → 발동
        if (_viper_dive_hold_start_ms > 0
                and pygame.time.get_ticks() - _viper_dive_hold_start_ms >= _VIPER_DIVE_HOLD_REQUIRED_MS):
            _viper_dive_hold_start_ms = 0
            _viper_dive_charge_particles = []
            if _dive_can_hold:
                special_gauge -= _VIPER_DIVE_GAUGE_COST
                trigger_viper_skill_cooldown("dive_strike")
                _viper_dive_active = True
                _viper_dive_phase = 0
                _viper_dive_start_ms = pygame.time.get_ticks()
                try:
                    _dp_snd = sound_effects.get('VIPER_DIVE_PREP')
                    if _dp_snd:
                        _dp_snd.set_volume(0.6)
                        _dp_snd.play()
                except Exception:
                    pass
                _viper_dive_height_snapshot = abs(_viper_jetpack_offset_y)
                _viper_dive_ball_boosted = False
                _viper_dive_particles = []
                # 제트팩 즉시 비활성 + 사운드 정지
                _viper_jetpack_active = False
                _viper_jetpack_gauge_timer = 0
                try:
                    if _viper_jetpack_snd_channel and _viper_jetpack_snd_channel.get_busy():
                        _viper_jetpack_snd_channel.fadeout(100)
                    _viper_jetpack_snd_channel = None
                except Exception:
                    _viper_jetpack_snd_channel = None

        # 급강하 업데이트
        if _viper_dive_active:
            _dive_elapsed = pygame.time.get_ticks() - _viper_dive_start_ms
            import random as _dv_rand

            if _viper_dive_phase == 0:
                # === 도움닫기 자세 (0.5초 공중 정지 + 에너지 수렴) ===
                if _dive_elapsed >= _VIPER_DIVE_PREP_MS:
                    _viper_dive_phase = 1  # 급강하 시작
                    _viper_dive_start_ms = pygame.time.get_ticks()
                else:
                    # 에너지 수렴 파티클 (패들 주위로 모여드는 입자)
                    _prep_pct = _dive_elapsed / _VIPER_DIVE_PREP_MS
                    for _ in range(int(2 + _prep_pct * 4)):
                        _angle = _dv_rand.uniform(0, math.pi * 2)
                        _dist = _dv_rand.uniform(30, 80) * (1.0 - _prep_pct * 0.5)
                        _viper_dive_particles.append({
                            'x': PLAYER.centerx + math.cos(_angle) * _dist,
                            'y': float(PLAYER.centery) + math.sin(_angle) * _dist,
                            'vx': -math.cos(_angle) * 2.0,
                            'vy': -math.sin(_angle) * 2.0,
                            'life': 12,
                            'max_life': 12,
                            'size': _dv_rand.uniform(2.0, 5.0),
                            'type': 'energy',
                        })

            elif _viper_dive_phase == 1:
                # === 급강하 (빠르게 착지) ===
                _viper_jetpack_offset_y += _VIPER_DIVE_SPEED
                if _viper_jetpack_offset_y >= 0:
                    _viper_jetpack_offset_y = 0.0
                    _viper_dive_phase = 2  # 착지
                    _viper_dive_start_ms = pygame.time.get_ticks()
                    try:
                        _ds_snd = sound_effects.get('VIPER_DIVE_STRIKE')
                        if _ds_snd:
                            _ds_snd.set_volume(0.6)
                            _ds_snd.play()
                    except Exception:
                        pass
                    # 착지 화면 흔들림
                    screen_shake_timer = max(screen_shake_timer, 12)
                    screen_shake_intensity = max(screen_shake_intensity, 4)
                    _viper_dive_shockwave_timer = _VIPER_DIVE_SHOCKWAVE_FRAMES
                    _viper_dive_shockwave_x = float(PLAYER.centerx)
                    # 착지 Y 계산
                    _dv_floor = _compute_player_floor_bottom(
                        CURRENT_PADDLE_EFFECTIVE_SCALE if CURRENT_PADDLE_EFFECTIVE_SCALE else CURRENT_PADDLE_SIZE_SCALE
                    )
                    _viper_dive_shockwave_y = float(_dv_floor)
                    _viper_jetpack_hold_timer = 0
                    _viper_jetpack_overheat = False

                    # 보스 슬립 효과 (바나나식 — 체공 높이 비례 0.9~1.5초 미끄러짐)
                    _dive_boss_dx = BALL.centerx - BOSS.centerx
                    _dive_slip_dir = 1 if _dive_boss_dx > 0 else -1
                    _dive_height_ratio = min(1.0, _viper_dive_height_snapshot / _VIPER_JETPACK_MAX_HEIGHT)
                    _viper_dive_slip_duration = int(_VIPER_DIVE_SLIP_DURATION_MIN + (_VIPER_DIVE_SLIP_DURATION_MAX - _VIPER_DIVE_SLIP_DURATION_MIN) * _dive_height_ratio)
                    _viper_dive_slip_timer = _viper_dive_slip_duration
                    _viper_dive_slip_vel = _dive_slip_dir * 4.0  # 초기 슬립 속도 (느리지만 꾸준히)

                    # 착지 연기 파티클 — 좌우 300px 범위로 넓게 퍼지는 더스트 클라우드
                    _landing_cx = _viper_dive_shockwave_x
                    _landing_cy = _viper_dive_shockwave_y
                    _dive_spread = _VIPER_DIVE_SHOCKWAVE_RADIUS  # 300px
                    # 좌우로 밀려나는 큰 연기 구름 (메인 이펙트)
                    for _ in range(50):
                        _side = _dv_rand.choice([-1, 1])
                        _viper_dive_particles.append({
                            'x': _landing_cx + _dv_rand.uniform(-40, 40),
                            'y': _landing_cy + _dv_rand.uniform(-8, 4),
                            'vx': _side * _dv_rand.uniform(4.0, 14.0),  # 빠르게 퍼져서 300px 도달
                            'vy': _dv_rand.uniform(-3.0, -0.3),
                            'life': _dv_rand.randint(35, 60),
                            'max_life': 60,
                            'size': _dv_rand.uniform(10.0, 22.0),
                            'type': 'dust_cloud',
                        })
                    # 바닥에서 솟아오르는 수직 더스트 기둥 (넓게 분포)
                    for _ in range(25):
                        _viper_dive_particles.append({
                            'x': _landing_cx + _dv_rand.uniform(-_dive_spread * 0.6, _dive_spread * 0.6),
                            'y': _landing_cy + _dv_rand.uniform(-3, 3),
                            'vx': _dv_rand.uniform(-1.2, 1.2),
                            'vy': _dv_rand.uniform(-5.0, -1.5),
                            'life': _dv_rand.randint(20, 40),
                            'max_life': 40,
                            'size': _dv_rand.uniform(5.0, 14.0),
                            'type': 'dust_pillar',
                        })
                    # 바닥 먼지 파편 (좌우 넓게 튀어나감)
                    for _ in range(30):
                        _angle = _dv_rand.uniform(-math.pi, 0)
                        _spd = _dv_rand.uniform(5.0, 16.0)  # 빠르게 퍼짐
                        _viper_dive_particles.append({
                            'x': _landing_cx + _dv_rand.uniform(-60, 60),
                            'y': _landing_cy,
                            'vx': math.cos(_angle) * _spd,
                            'vy': math.sin(_angle) * _spd * 0.5,
                            'life': _dv_rand.randint(12, 30),
                            'max_life': 30,
                            'size': _dv_rand.uniform(1.5, 5.0),
                            'type': 'debris',
                        })

                    # 공 속도 부스트 (범위 내 공에 적용 — X축 넓고 Y축 좁은 바닥 장판)
                    if not _viper_dive_ball_boosted:
                        _dv_ball_cy = BALL.centery
                        _dv_dy = _viper_dive_shockwave_y - _dv_ball_cy  # 양수 = 공이 위에 있음
                        if 0 <= _dv_dy <= _VIPER_DIVE_SHOCKWAVE_HEIGHT:
                            # 공을 위로 반사 (속도 변화 없음)
                            ball_vel[1] = -abs(ball_vel[1])
                            _viper_dive_ball_boosted = True
                            # 🪙 EMP 스트라이크 타격 골드 보너스 (20골드)
                            try:
                                add_ingame_gold(20, BALL.centerx, BALL.centery - 20, source="skill")
                                _viper_skill_gold_this_frame = True
                            except Exception:
                                pass

                            # DIVE STRIKE 텍스트 이펙트
                            _viper_air_strike_text_timer = 60
                            _viper_air_strike_text_x = _viper_dive_shockwave_x
                            _viper_air_strike_text_y = _viper_dive_shockwave_y - 40
                            _viper_air_strike_text_pct = 0
                else:
                    # 급강하 중 궤적 파티클
                    for _ in range(2):
                        _viper_dive_particles.append({
                            'x': PLAYER.centerx + _dv_rand.uniform(-8, 8),
                            'y': float(PLAYER.bottom),
                            'vx': _dv_rand.uniform(-0.8, 0.8),
                            'vy': _dv_rand.uniform(-2.0, 0.5),
                            'life': _dv_rand.randint(6, 12),
                            'max_life': 12,
                            'size': _dv_rand.uniform(2.0, 5.0),
                            'type': 'trail',
                        })

            elif _viper_dive_phase == 2:
                # === 착지 연기 지속 — 연기 범위 내 공 타격 (방어용) ===
                _viper_dive_shockwave_timer -= 1
                if _viper_dive_shockwave_timer <= 0:
                    _viper_dive_active = False
                    _viper_dive_phase = 0
                elif not _viper_dive_ball_boosted:
                    # 연기 지속 중 매 프레임 범위 내 공 충돌 체크 (X축 전체, Y축 좁은 바닥 장판)
                    _dv2_dy = _viper_dive_shockwave_y - BALL.centery  # 양수 = 공이 위에 있음
                    if 0 <= _dv2_dy <= _VIPER_DIVE_SHOCKWAVE_HEIGHT:
                        # 공을 위로 반사 (속도 변화 없음)
                        ball_vel[1] = -abs(ball_vel[1])
                        _viper_dive_ball_boosted = True
                        # 🪙 EMP 스트라이크 타격 골드 보너스 (20골드)
                        try:
                            add_ingame_gold(20, BALL.centerx, BALL.centery - 20, source="skill")
                            _viper_skill_gold_this_frame = True
                        except Exception:
                            pass
                        # DIVE STRIKE 텍스트 이펙트
                        _viper_air_strike_text_timer = 60
                        _viper_air_strike_text_x = _viper_dive_shockwave_x
                        _viper_air_strike_text_y = _viper_dive_shockwave_y - 40
                        _viper_air_strike_text_pct = 0

        # 도움닫기 자세 중 자연 하강 상쇄 (공중 정지 유지)
        if _viper_dive_active and _viper_dive_phase == 0 and _viper_jetpack_offset_y < 0:
            _viper_jetpack_offset_y -= _VIPER_JETPACK_FALL_SPEED

        # 급강하 파티클 업데이트
        if _viper_dive_particles:
            _dv_alive = []
            for _dp in _viper_dive_particles:
                _dp['x'] += _dp['vx']
                _dp['y'] += _dp['vy']
                _dp['life'] -= 1
                _dt = _dp['type']
                if _dt == 'dust_cloud':
                    # 큰 연기: 천천히 팽창하면서 감속, 위로 살짝 떠오름
                    _dp['vx'] *= 0.96  # 공기 저항
                    _dp['vy'] -= 0.03  # 부력
                    _dp['size'] += 0.2  # 팽창
                elif _dt == 'dust_pillar':
                    # 수직 더스트: 위로 솟았다가 감속, 약간 팽창
                    _dp['vy'] *= 0.94
                    _dp['vx'] += (_dp['vx'] > 0 and 0.05 or -0.05) if abs(_dp['vx']) > 0.1 else 0
                    _dp['size'] += 0.15
                elif _dt == 'debris':
                    # 먼지 파편: 중력 적용, 빠르게 축소
                    _dp['vy'] += 0.2
                    _dp['size'] = max(0.3, _dp['size'] - 0.12)
                elif _dt == 'smoke':
                    _dp['size'] = max(0.5, _dp['size'] - 0.15)
                    _dp['vy'] -= 0.05
                elif _dt == 'spark':
                    _dp['vy'] += 0.15
                    _dp['size'] = max(0.3, _dp['size'] - 0.25)
                else:
                    _dp['size'] = max(0.3, _dp['size'] - 0.2)
                if _dp['life'] > 0:
                    _dv_alive.append(_dp)
            _viper_dive_particles = _dv_alive[-150:] if len(_dv_alive) > 150 else _dv_alive

    # 바이퍼 쉐도우 백스텝 에너지파 업데이트 (이동 + 공 충돌)
    if _viper_ss_wave_active:
        # 이동 (매우 빠름)
        _viper_ss_wave_x += _viper_ss_wave_dir * _viper_ss_wave_speed
        # 잔상 기록
        _viper_ss_wave_trail.append((_viper_ss_wave_x, _viper_ss_wave_y))
        if len(_viper_ss_wave_trail) > 12:
            _viper_ss_wave_trail.pop(0)
        # 도달 판정 (방향에 따라)
        _sw_reached = False
        if _viper_ss_wave_dir > 0:
            if _viper_ss_wave_x >= _viper_ss_wave_target_x:
                _sw_reached = True
                _viper_ss_wave_active = False
                _viper_ss_wave_trail.clear()
        else:
            if _viper_ss_wave_x <= _viper_ss_wave_target_x:
                _sw_reached = True
                _viper_ss_wave_active = False
                _viper_ss_wave_trail.clear()
        if _sw_reached and not _viper_ss_wave_hit_ball and not _viper_ss_hit_consumed:
            pass
        # 에너지파 — 공 충돌 시 그라데이션 타격 적용 (공통 함수 사용)
        if _viper_ss_wave_active and not _viper_ss_wave_hit_ball and not _viper_ss_hit_consumed:
            try:
                _sw_hit_rect = pygame.Rect(
                    int(_viper_ss_wave_x - 55), int(_viper_ss_wave_y - 45),
                    110, 90
                )
                _sw_collides = _sw_hit_rect.colliderect(BALL)
                if _sw_collides:
                    _viper_ss_wave_hit_ball = True
                    # 그라데이션 계산용 히트박스는 충돌 히트박스보다 넓게 (에너지파는 빨라서 가장자리 판정 방지)
                    _viper_ss_apply_ball_hit(
                        _viper_ss_wave_x, _viper_ss_wave_y, 280, 220,
                        _viper_ss_hologram_kick_dir, source="wave"
                    )
            except Exception:
                pass
        elif _viper_ss_wave_active and _viper_ss_hit_consumed:
            pass  # 이미 소모됨 (정상)

    # 바이퍼 에어 블레이드 회전/정지 연출 업데이트
    if _viper_br_spin_active:
        _br_now = pygame.time.get_ticks()
        _br_elapsed = _br_now - _viper_br_spin_start_ms

        if _viper_br_spin_phase == 0:
            # 단계 0: 빠른 2바퀴 회전 (400ms) — 제자리
            if _br_elapsed < _VIPER_BR_SPIN_DURATION:
                _br_t = _br_elapsed / _VIPER_BR_SPIN_DURATION
                _viper_br_spin_angle = _br_t * 720.0  # 2바퀴 = 720도
                _viper_br_jump_offset_y = 0.0
                _viper_br_arm_raise = 0.0
            else:
                _viper_br_spin_phase = 1
                _viper_br_spin_start_ms = _br_now
                _viper_br_spin_angle = 720.0

        elif _viper_br_spin_phase == 1:
            # 단계 1: 감속하며 멈춤 (200ms) — 제자리
            if _br_elapsed < _VIPER_BR_DECEL_DURATION:
                _br_t = _br_elapsed / _VIPER_BR_DECEL_DURATION
                _br_decel = 1.0 - _br_t
                _viper_br_spin_angle = 720.0 + _br_decel * 90.0 * (1.0 - _br_t)
                _viper_br_jump_offset_y = 0.0
                _viper_br_arm_raise = 0.0
            else:
                _viper_br_spin_phase = 2
                _viper_br_spin_start_ms = _br_now
                _viper_br_spin_angle = 0.0  # 정면으로 리셋

                # 회전 사운드 정지 + 검기 발사 (회전 끝난 직후)
                try:
                    _spin_snd_stop = sound_effects.get('VIPER_BLADE_SPIN')
                    if _spin_snd_stop:
                        _spin_snd_stop.stop()
                except Exception:
                    pass
                try:
                    _blade_snd = sound_effects.get('VIPER_BLADE')
                    if _blade_snd:
                        _blade_snd.set_volume(0.5)
                        _blade_snd.play()
                except Exception:
                    pass
                _viper_blade_rush_active = True
                _viper_blade_rush_fadeout = False
                _viper_blade_rush_fadeout_timer = 0
                _viper_blade_rush_x = float(PLAYER.centerx)
                _viper_blade_rush_start_y = float(PLAYER.centery - 20)
                _viper_blade_rush_y = _viper_blade_rush_start_y
                _viper_blade_rush_target_y = _viper_blade_rush_start_y - 250
                _viper_blade_rush_hit_ball = False
                _viper_blade_rush_particles.clear()
                _viper_blade_rush_trail.clear()
                try:
                    effects_manager.spawn_shockwave(
                        PLAYER.centerx, PLAYER.centery - 20,
                        force=6, color=(200, 50, 255),
                    )
                except Exception:
                    pass

        elif _viper_br_spin_phase == 2:
            # 단계 2: 검기 발사 + 승룡권 점프 + 숨내쉬기 (1000ms)
            _br_rest_t = min(1.0, _br_elapsed / _VIPER_BR_REST_DURATION)

            # 올라갔다 내려오기: 전반 300ms 올라감, 후반 700ms 내려옴
            _jump_up_ms = 300
            _jump_peak = 80.0  # 최대 80px 상승
            if _br_elapsed < _jump_up_ms:
                # 올라가기 (이징: 빠르게 올라감)
                _jt = _br_elapsed / _jump_up_ms
                _viper_br_jump_offset_y = -_jump_peak * math.sin(_jt * math.pi * 0.5)
                _viper_br_arm_raise = min(1.0, _jt * 1.5)  # 팔 올리기
            else:
                # 내려오기 (이징: 천천히 착지)
                _jt = (_br_elapsed - _jump_up_ms) / max(1, _VIPER_BR_REST_DURATION - _jump_up_ms)
                _jt = min(1.0, _jt)
                _viper_br_jump_offset_y = -_jump_peak * (1.0 - _jt * _jt)  # 제곱감속 착지
                _viper_br_arm_raise = max(0.0, 1.0 - (_jt * 1.5))  # 팔 내리기

            if _br_elapsed >= _VIPER_BR_REST_DURATION:
                _viper_br_spin_active = False
                _viper_br_spin_angle = 0.0
                _viper_br_jump_offset_y = 0.0
                _viper_br_arm_raise = 0.0

    # 바이퍼 에어 블레이드 검기 업데이트 (매 프레임)
    if _viper_blade_rush_active:
        _br_speed_per_frame = 12.0  # 검기 이동 속도 (px/frame)
        _viper_blade_rush_y -= _br_speed_per_frame  # 위로 이동

        # 궤적 저장 (잔상용)
        _viper_blade_rush_trail.append((_viper_blade_rush_x, _viper_blade_rush_y))
        if len(_viper_blade_rush_trail) > 20:
            _viper_blade_rush_trail.pop(0)

        # 검기-공 충돌 판정 (1회만, 페이드아웃 중에는 판정 없음)
        if not _viper_blade_rush_hit_ball and not _viper_blade_rush_fadeout:
            try:
                _br_half_w = _viper_blade_rush_width // 2
                _br_blade_rect = pygame.Rect(
                    int(_viper_blade_rush_x - _br_half_w),
                    int(_viper_blade_rush_y - 55),
                    _viper_blade_rush_width,
                    55  # 검기 세로 히트박스 (부채꼴 비주얼 높이에 맞춤)
                )
                if _br_blade_rect.colliderect(BALL):
                    _viper_blade_rush_hit_ball = True
                    # 🪙 에어 블레이드 타격 골드 보너스 (30골드)
                    try:
                        add_ingame_gold(30, BALL.centerx, BALL.centery - 20, source="skill")
                        _viper_skill_gold_this_frame = True
                    except Exception:
                        pass
                    # 원래 속도 저장 (보스 반격 시 복귀용)
                    _br_cur_speed = math.hypot(ball_vel[0], ball_vel[1])
                    _viper_speed_boost_active = True
                    _viper_speed_boost_original = _br_cur_speed
                    if _br_cur_speed > 0.1:
                        _br_new_speed = _br_cur_speed * 2.8  # 2.8x (180% 증가)
                        _br_ratio = _br_new_speed / _br_cur_speed
                        ball_vel[0] *= _br_ratio
                        ball_vel[1] = -abs(ball_vel[1] * _br_ratio)  # 위로 보정
                    else:
                        ball_vel[1] = -10.0  # 정지 상태면 위로 발사
                    # 히트 이펙트
                    try:
                        effects_manager.spawn_shockwave(
                            BALL.centerx, BALL.centery,
                            force=10, color=(255, 100, 255),
                        )
                    except Exception:
                        pass
                    # 전기톱 불꽃 이펙트 (검보라색 스파크)
                    try:
                        effects_manager.spawn_blade_spark_particles(
                            BALL.centerx, BALL.centery,
                            count=30,
                            ball_vx=ball_vel[0],
                            ball_vy=ball_vel[1],
                        )
                    except Exception:
                        pass
            except Exception:
                pass

        # 검기-인터셉터 충돌 판정 (페이드아웃 중에는 판정 없음)
        if not _viper_blade_rush_fadeout and current_stage == 6 and interceptors:
            try:
                _br_half_w2 = _viper_blade_rush_width // 2
                _br_blade_rect2 = pygame.Rect(
                    int(_viper_blade_rush_x - _br_half_w2),
                    int(_viper_blade_rush_y - 55),
                    _viper_blade_rush_width,
                    55
                )
                for interceptor in interceptors[:]:
                    interceptor_rect = pygame.Rect(
                        interceptor['x'] - 15,
                        interceptor['y'] - 15,
                        30, 30
                    )
                    if _br_blade_rect2.colliderect(interceptor_rect):
                        interceptors.remove(interceptor)
                        # 폭발 사운드
                        try:
                            play_sound_with_volume(SOUND_STAGE6_INTERCEPTOR_HIT)
                        except Exception:
                            pass
                        # 폭발 파티클 이펙트
                        for _ in range(22):
                            spark_angle = random.uniform(0, math.pi * 2)
                            spark_dist = random.uniform(0, 25)
                            spark_x = interceptor['x'] + math.cos(spark_angle) * spark_dist
                            spark_y = interceptor['y'] + math.sin(spark_angle) * spark_dist
                            color = (255, 215, 120) if interceptor.get('golden') else (200, 130, 255)
                            draw.circle(color, (int(spark_x), int(spark_y)), random.randint(2, 5))
                        # 황금 인터셉터 보상: 스타포인트 드랍
                        try:
                            if interceptor.get('golden') and trade_point_system:
                                trade_point_system.spawn_star(interceptor['x'], interceptor['y'], "gold_interceptor")
                        except Exception:
                            pass
            except Exception:
                pass

        # 검기-테트로미노 충돌 판정 (스테이지7, 페이드아웃 중에는 판정 없음)
        if not _viper_blade_rush_fadeout and current_stage == 7 and stage7_tetrominoes:
            try:
                _br_half_w3 = _viper_blade_rush_width // 2
                _br_blade_rect3 = pygame.Rect(
                    int(_viper_blade_rush_x - _br_half_w3),
                    int(_viper_blade_rush_y - 55),
                    _viper_blade_rush_width,
                    55
                )
                for mino in stage7_tetrominoes[:]:
                    if mino.get("state") not in ("assembling", "falling", "installed"):
                        continue
                    _mino_hit = False
                    for cell in mino.get("cells", []):
                        if cell.get("evaporated"):
                            continue
                        cell_rect = cell.get("rect")
                        if cell_rect and _br_blade_rect3.colliderect(cell_rect):
                            _mino_hit = True
                            break
                    if _mino_hit:
                        destroy_stage7_tetromino(
                            mino,
                            by_player=True,
                            by_dash=True,
                        )
            except Exception:
                pass

        # 목표 도달 시 페이드아웃 시작 (즉시 소멸하지 않음)
        if _viper_blade_rush_y <= _viper_blade_rush_target_y and not _viper_blade_rush_fadeout:
            _viper_blade_rush_fadeout = True
            _viper_blade_rush_fadeout_timer = _VIPER_BLADE_RUSH_FADEOUT_FRAMES
            # 에어 블레이드 단독 사용 시 마샬 킥 연계 없음 (베놈 엣지 실패 시에만 연계)

    # 바이퍼 에어 블레이드 페이드아웃 타이머
    if _viper_blade_rush_fadeout:
        _viper_blade_rush_fadeout_timer -= 1
        if _viper_blade_rush_fadeout_timer <= 0:
            _viper_blade_rush_active = False
            _viper_blade_rush_fadeout = False
            _viper_blade_rush_trail.clear()

    # === 바이퍼 신경 타격 연계기 애니메이션 업데이트 ===
    if _viper_nerve_strike_active:
        _ns_now = pygame.time.get_ticks()
        _ns_elapsed = _ns_now - _viper_nerve_strike_start_ms

        if _viper_nerve_strike_phase == 0:
            # Phase 0: 보스에게 돌진 (부드러운 타겟 추적 — 전반부만)
            if _ns_elapsed < _VIPER_NS_DASH_DURATION:
                _ns_t = _ns_elapsed / _VIPER_NS_DASH_DURATION
                # 전반 80% 구간에서 타겟을 보스 쪽으로 보정 (후반 20%는 고정 → 빗나갈 여지)
                if _ns_t < 0.8:
                    _ns_track_strength = 0.12 * (1.0 - _ns_t / 0.8)  # 점점 약해지는 추적
                    _viper_nerve_strike_target_x += (float(BOSS.centerx) - _viper_nerve_strike_target_x) * _ns_track_strength
                    _viper_nerve_strike_target_y += (float(BOSS.centery - (BOSS.height // 2) - 20) - _viper_nerve_strike_target_y) * _ns_track_strength
                # 이징: ease-in-out (자연스러운 가감속)
                _ns_ease = _ns_t * _ns_t * (3.0 - 2.0 * _ns_t)
                _ns_cur_x = _viper_nerve_strike_origin_x + (_viper_nerve_strike_target_x - _viper_nerve_strike_origin_x) * _ns_ease
                _ns_cur_y = _viper_nerve_strike_origin_y + (_viper_nerve_strike_target_y - _viper_nerve_strike_origin_y) * _ns_ease
                PLAYER.centerx = int(_ns_cur_x)
                PLAYER.centery = int(_ns_cur_y)
            else:
                # 도착 — 보스가 히트 범위 안에 있는지 판정
                PLAYER.centerx = int(_viper_nerve_strike_target_x)
                PLAYER.centery = int(_viper_nerve_strike_target_y)
                _ns_dx = BOSS.centerx - _viper_nerve_strike_target_x
                _ns_dy = BOSS.centery - _viper_nerve_strike_target_y
                _ns_dist = math.sqrt(_ns_dx * _ns_dx + _ns_dy * _ns_dy)

                if _ns_dist <= _VIPER_NS_HIT_RADIUS:
                    # 적중! → 베기 연출로 전환 (프리즈 컷씬)
                    _viper_nerve_strike_phase = 1
                    _viper_nerve_strike_start_ms = _ns_now
                    _viper_ns_hit_confirmed = True
                    _viper_ns_freeze_active = True
                    # 🪙 베놈 엣지 보스 명중 골드 보너스 (60골드)
                    try:
                        add_ingame_gold(60, BOSS.centerx, BOSS.centery - 20, source="skill")
                        _viper_skill_gold_this_frame = True
                    except Exception:
                        pass
                    # 🧤 독안개장갑: 베놈 엣지 적중 시 독안개 발동 판정
                    try:
                        from item_effects.venom_mist_gauntlet import try_spawn_mist
                        if try_spawn_mist(float(BOSS.centerx), float(BOSS.centery)):
                            print("[VenomMistGauntlet] 독안개 영역 생성!")
                    except Exception:
                        pass
                else:
                    # 무효 (보스가 피함) → 즉시 복귀
                    _viper_nerve_strike_phase = 2
                    _viper_nerve_strike_start_ms = _ns_now

        elif _viper_nerve_strike_phase == 1:
            # Phase 1: 등뒤에서 베기 연출 (적중 시에만 진입)
            # 적중 시 프리즈 컷씬: 더 긴 연출 시간 사용
            _ns_slash_dur = _VIPER_NS_SLASH_DURATION_HIT if _viper_ns_hit_confirmed else _VIPER_NS_SLASH_DURATION
            PLAYER.centerx = int(_viper_nerve_strike_target_x)
            PLAYER.centery = int(_viper_nerve_strike_target_y)

            # 베기 사운드 + 이펙트: 후반부(45% 이후)에 재생 — 텍스트 정지 후 할퀴기와 동시
            _ns_slash_45pct = int(_ns_slash_dur * 0.45)
            if not _viper_nerve_strike_slash_shown and _ns_elapsed >= _ns_slash_45pct:
                _viper_nerve_strike_slash_shown = True
                # 베기 사운드 재생
                try:
                    _va_snd = sound_effects.get('VIPER_VENOM_ATTACK')
                    if _va_snd:
                        _va_snd.set_volume(0.6)
                        _va_snd.play()
                except Exception:
                    pass
                # 베기 이펙트 — 보스 위치에 충격파
                try:
                    effects_manager.spawn_shockwave(
                        BOSS.centerx, BOSS.centery,
                        force=12, color=(180, 0, 220),
                    )
                except Exception:
                    pass

            if _ns_elapsed >= _ns_slash_dur:
                # 혼란 효과 적용! (조명탄과 동일한 시스템)
                boss_confused_timer = _VIPER_NS_CONFUSION_FRAMES  # 5초
                # 프리즈는 착지 완료까지 유지 (Phase 2 끝에서 해제)

                # 복귀 X를 공의 X좌표로 변경 (착지 후 바로 받아칠 수 있도록)
                _ns_land_x = float(BALL.centerx)
                # 화면 밖으로 나가지 않도록 패들 반폭 고려하여 클램프
                _ns_half_pw = PLAYER.width // 2
                _ns_land_x = max(_ns_half_pw, min(WIDTH - _ns_half_pw, _ns_land_x))
                _viper_nerve_strike_origin_x = _ns_land_x

                _viper_nerve_strike_phase = 2
                _viper_nerve_strike_start_ms = _ns_now
                # 복귀 사운드 재생
                try:
                    _vm_snd2 = sound_effects.get('VIPER_VENOM_MOVING')
                    if _vm_snd2:
                        _vm_snd2.set_volume(0.6)
                        _vm_snd2.play()
                except Exception:
                    pass

        elif _viper_nerve_strike_phase == 2:
            # Phase 2: 제자리 복귀 (적중 시 천천히, 미적중 시 빠르게)
            _ns_ret_dur = _VIPER_NS_RETURN_DURATION_HIT if _viper_ns_hit_confirmed else _VIPER_NS_RETURN_DURATION
            if _ns_elapsed < _ns_ret_dur:
                _ns_t = _ns_elapsed / _ns_ret_dur
                # 이징: 적중 시 ease-out (빠르게 출발 → 천천히 착지), 미적중 시 ease-in
                _ns_ease = 1.0 - (1.0 - _ns_t) ** 2 if _viper_ns_hit_confirmed else _ns_t ** 2
                _ns_cur_x = _viper_nerve_strike_target_x + (_viper_nerve_strike_origin_x - _viper_nerve_strike_target_x) * _ns_ease
                _ns_cur_y = _viper_nerve_strike_target_y + (_viper_nerve_strike_origin_y - _viper_nerve_strike_target_y) * _ns_ease
                PLAYER.centerx = int(_ns_cur_x)
                PLAYER.centery = int(_ns_cur_y)
            else:
                # 복귀 완료
                PLAYER.centerx = int(_viper_nerve_strike_origin_x)
                PLAYER.centery = int(_viper_nerve_strike_origin_y)
                _viper_nerve_strike_active = False
                _viper_ns_hit_confirmed = False
                _viper_ns_freeze_active = False
                # 베놈 엣지 실패(보스 미적중) 시 마샬 킥 연계 없음 (블레이드 → 베놈 엣지만 연계)
                # 복귀 이펙트
                try:
                    effects_manager.spawn_shockwave(
                        PLAYER.centerx, PLAYER.centery,
                        force=6, color=(180, 0, 220),
                    )
                except Exception:
                    pass

    # 충전 해제 후 예정된 충격파 발사 처리
    if selected_character_type == "optimus":
        global optimus_charge_shockwave_at_ms
        if optimus_charge_shockwave_at_ms and pygame.time.get_ticks() >= optimus_charge_shockwave_at_ms:
            try:
                effects_manager.spawn_shockwave(
                    PLAYER.centerx,
                    PLAYER.centery,
                    force=12,
                    color=(120, 235, 255),
                )
            except Exception:
                pass
            optimus_charge_shockwave_at_ms = 0
    
    # 옵티머스 옵티머스 암 던지기 입력 처리 (잡기 상태에서 좌/우 방향키)
    # 👁 오딘의 눈 변신 상태에서는 옵티머스 암 던지기 사용 불가
    if selected_character_type == "optimus" and optimus_arm_state == "grabbing" and optimus_arm_grabbed_boss and not is_odins_eye_transformed():
        if left_pressed_raw and not right_pressed_raw:
            handle_optimus_arm_throw_input(-1)  # 왼쪽으로 던지기
        elif right_pressed_raw and not left_pressed_raw:
            handle_optimus_arm_throw_input(1)   # 오른쪽으로 던지기
    
    # 물자보급 스킬 처리 (코만도 캐릭터 전용)
    
    # 물자보급 스킬 발동 조건 확인 (스페이스 + ↑ 동시 입력)
    # ↑ 입력 역시 스냅샷이 있으면 사용해 ‘짧은 눌림’ 감지를 안정화
    if 'INPUT_SNAPSHOT_VALID' in globals() and INPUT_SNAPSHOT_VALID:
        up_pressed = bool(SNAP_up_state)
    else:
        up_pressed = is_move_up_pressed(keys) or (_scheme == 'mouse_keyboard' and is_move_up_pressed(keys))
    global player_up_pressed, player_up_pressed_prev
    player_up_pressed_prev = player_up_pressed
    player_up_pressed = bool(up_pressed)
    up_just_pressed = up_pressed and not player_up_pressed_prev

    if selected_character_type == "blacksmith":
        if blacksmith_blocking_penalty_timer > 0:
            blacksmith_blocking_penalty_timer -= 1
        if blacksmith_blocking_toast_timer > 0:
            blacksmith_blocking_toast_timer -= 1
        if blacksmith_blocking_skill_timer > 0:
            blacksmith_blocking_skill_timer -= 1
        if blacksmith_blocking_bonus_window_timer > 0:
            blacksmith_blocking_bonus_window_timer -= 1
            if blacksmith_blocking_bonus_window_timer <= 0:
                blacksmith_blocking_bonus_window_timer = 0
                blacksmith_blocking_bonus_ready = False

        if blacksmith_umbrella_damage_flash_timer > 0:
            blacksmith_umbrella_damage_flash_timer -= 1

        if blacksmith_umbrella_open:
            blacksmith_umbrella_recharge_progress = 0
            if blacksmith_umbrella_gauge <= 0:
                request_blacksmith_umbrella_close(play_sound=True, flash=True)
        else:
            if blacksmith_umbrella_gauge >= BLACKSMITH_UMBRELLA_GAUGE_MAX:
                blacksmith_umbrella_recharge_progress = 0
            else:
                recover_interval = max(1, get_blacksmith_umbrella_recover_interval_frames())
                blacksmith_umbrella_recharge_progress += 1
                if blacksmith_umbrella_recharge_progress >= recover_interval:
                    blacksmith_umbrella_gauge = min(
                        BLACKSMITH_UMBRELLA_GAUGE_MAX,
                        blacksmith_umbrella_gauge + 1,
                    )
                    blacksmith_umbrella_recharge_progress = 0

    umbrella_lock_active = False
    umbrella_action_block = False
    umbrella_swinging_main = False
    if selected_character_type == "blacksmith":
        if blacksmith_umbrella_open:
            if blacksmith_umbrella_anim_timer > 0:
                blacksmith_umbrella_anim_timer -= 1
            else:
                if blacksmith_umbrella_retracting:
                    blacksmith_umbrella_open = False
                    blacksmith_umbrella_retracting = False
                    blacksmith_umbrella_anim_direction = 1
                    blacksmith_umbrella_retract_start_frame = -1000
                    blacksmith_umbrella_retract_grace_timer = 0
                    blacksmith_umbrella_hitbox_extents = (0.0, 0.0)
                    blacksmith_umbrella_hitbox_vertical = (0.0, 0.0)
                    blacksmith_umbrella_hitbox_center_offset = (0.0, 0.0)
                    blacksmith_umbrella_hitbox_direction = (0.0, -1.0)
                    blacksmith_umbrella_swing_direction = 1
                else:
                    blacksmith_umbrella_anim_direction = 1

            if blacksmith_umbrella_retract_grace_timer > 0:
                blacksmith_umbrella_retract_grace_timer -= 1

            # 스윙 입력 감지: 좌/우 + 스페이스(또는 좌클릭)이면 스윙 시도로 판정
            global blacksmith_swing_input_buffer
            _swing_input_detected_now = (
                (left_pressed_raw or right_pressed_raw)
                and not (left_pressed_raw and right_pressed_raw)  # 둘 다 누르면 스윙 아님
                and space_pressed_raw
            )

            # 스윙 입력 버퍼 업데이트: 입력이 감지되면 버퍼 채움, 아니면 감소
            if _swing_input_detected_now:
                blacksmith_swing_input_buffer = BLACKSMITH_SWING_INPUT_BUFFER_FRAMES
            elif blacksmith_swing_input_buffer > 0:
                blacksmith_swing_input_buffer -= 1

            # 현재 입력 OR 버퍼에 입력이 남아있으면 스윙으로 인정
            _swing_input_detected = _swing_input_detected_now or blacksmith_swing_input_buffer > 0

            if (
                up_just_pressed
                and not blacksmith_umbrella_retracting
                and blacksmith_umbrella_anim_timer == 0
                and player_stunned_timer <= 0
                and not _swing_input_detected  # 스윙 입력 중이거나 버퍼에 남아있으면 토르쉴드 닫지 않음
            ):
                request_blacksmith_umbrella_close(play_sound=True, flash=False)
                if blacksmith_blocking_bonus_ready and blacksmith_blocking_bonus_window_timer > 0:
                    blacksmith_blocking_bonus_pending = True
                    blacksmith_blocking_bonus_ready = False
                    blacksmith_blocking_bonus_window_timer = 0
                    blacksmith_blocking_skill_timer = max(
                        blacksmith_blocking_skill_timer,
                        BLACKSMITH_BLOCKING_SKILL_FRAMES,
                    )

            if 'blacksmith_shield_impact_timer' in globals() and blacksmith_shield_impact_timer > 0:
                blacksmith_shield_impact_timer -= 1
        elif up_just_pressed and player_stunned_timer <= 0:
            if blacksmith_umbrella_gauge <= 0:
                blacksmith_umbrella_damage_flash_timer = max(
                    blacksmith_umbrella_damage_flash_timer,
                    int(BLACKSMITH_UMBRELLA_DAMAGE_FLASH_FRAMES * 0.75),
                )
            # 👁 오딘의 눈 변신 상태에서는 토르쉴드 사용 불가
            elif (
                not blacksmith_build_menu_active
                and not blacksmith_hammer_shock_charging
                and (blacksmith_hammer_available or blacksmith_hammer_shock_cooldown_timer > 0)
                and not is_odins_eye_transformed()  # 👁 변신 상태에서는 차단
            ):
                if blacksmith_turret_blueprint_active or blacksmith_divine_blueprint_active:
                    stop_blacksmith_construction_sound()
                blacksmith_umbrella_open = True
                blacksmith_umbrella_retracting = False
                blacksmith_umbrella_anim_direction = 1
                blacksmith_umbrella_anim_timer = BLACKSMITH_UMBRELLA_ANIM_FRAMES
                blacksmith_umbrella_retract_start_frame = -1000
                blacksmith_umbrella_retract_grace_timer = 0
                # 디버그: 토르쉴드 배치 시작 로그
                if VALTHOR_PERF_DEBUG:
                    # print(f"[THOR SHIELD] DEPLOY START - anim_frames={BLACKSMITH_UMBRELLA_ANIM_FRAMES}, cache_size={len(_blacksmith_paddle_cache)}")
                    _thor_shield_frame_times.clear()  # 프레임 타임 초기화
                if SOUND_BLACKSMITH_UMBRELLA_OPEN:
                    play_sound_with_volume(SOUND_BLACKSMITH_UMBRELLA_OPEN)
                blacksmith_walking_active = False
                blacksmith_walking_timer = 0
                blacksmith_walk_direction = 0
                blacksmith_hammer_swing_active = False
                blacksmith_hammer_swing_phase = 0
                blacksmith_hammer_swing_slow_timer = 0
                blacksmith_shield_swing_active = False
                blacksmith_shield_swing_timer = 0
                blacksmith_hammer_shock_charging = False
                blacksmith_hammer_shock_stage = 0
                blacksmith_hammer_shock_charge_frames = 0
                blacksmith_hammer_charge_position = None
                blacksmith_build_menu_active = False
                blacksmith_umbrella_swing_direction = 1
                stop_blacksmith_hammer_charge_sound()
                if blacksmith_hammer_shock_projectiles:
                    global blacksmith_hammer_projectiles_paused
                    blacksmith_hammer_projectiles_paused = True
                    current_ticks = pygame.time.get_ticks()
                    updated = []
                    for proj in blacksmith_hammer_shock_projectiles:
                        if _advance_blacksmith_hammer_projectile(proj):
                            proj["_last_update_frame"] = frame_counter
                            proj["_last_update_ms"] = current_ticks
                            updated.append(proj)
                    blacksmith_hammer_shock_projectiles[:] = updated
        if blacksmith_umbrella_open and blacksmith_umbrella_anim_timer > 0:
            umbrella_lock_active = True

        if blacksmith_umbrella_open and not blacksmith_umbrella_retracting:
            umbrella_action_block = True
        else:
            if blacksmith_umbrella_swing_active:
                blacksmith_umbrella_swing_active = False
                blacksmith_umbrella_swing_timer = 0
                blacksmith_umbrella_swing_stage = 0
                blacksmith_umbrella_swing_progress = 0.0

        if blacksmith_umbrella_swing_active:
            total_swing_frames = BLACKSMITH_UMBRELLA_SWING_PREP_FRAMES + BLACKSMITH_UMBRELLA_SWING_SWING_FRAMES
            current_elapsed = total_swing_frames - blacksmith_umbrella_swing_timer
            if current_elapsed < BLACKSMITH_UMBRELLA_SWING_PREP_FRAMES:
                stage_progress = current_elapsed / max(1, BLACKSMITH_UMBRELLA_SWING_PREP_FRAMES)
                blacksmith_umbrella_swing_stage = 0
                blend_pre = 1.0 - pow(1.0 - stage_progress, 3)
                blacksmith_umbrella_swing_recover_pre = blend_pre
                blacksmith_umbrella_swing_recover_main = 0.0
            else:
                swing_elapsed = current_elapsed - BLACKSMITH_UMBRELLA_SWING_PREP_FRAMES
                stage_progress = swing_elapsed / max(1, BLACKSMITH_UMBRELLA_SWING_SWING_FRAMES)
                blacksmith_umbrella_swing_stage = 1
                blacksmith_umbrella_swing_recover_pre = 1.0
                blacksmith_umbrella_swing_recover_main = stage_progress
            blacksmith_umbrella_swing_progress = max(0.0, min(1.0, stage_progress))

        if blacksmith_umbrella_swing_timer > 0:
            blacksmith_umbrella_swing_timer -= 1
        if blacksmith_umbrella_swing_timer <= 0 or blacksmith_umbrella_retracting:
            blacksmith_umbrella_swing_active = False
            blacksmith_umbrella_swing_timer = 0
            blacksmith_umbrella_swing_stage = 0
            blacksmith_umbrella_swing_progress = 0.0
            if blacksmith_umbrella_swing_direction < 0:
                blacksmith_umbrella_swing_direction = 1
        if not blacksmith_umbrella_swing_active:
            if blacksmith_umbrella_swing_recover_pre > 0.0 or blacksmith_umbrella_swing_recover_main > 0.0:
                blacksmith_umbrella_swing_recover_pre *= BLACKSMITH_UMBRELLA_SWING_RECOVER_DAMP
                blacksmith_umbrella_swing_recover_main *= BLACKSMITH_UMBRELLA_SWING_RECOVER_DAMP
                if blacksmith_umbrella_swing_recover_pre < 0.01:
                    blacksmith_umbrella_swing_recover_pre = 0.0
                if blacksmith_umbrella_swing_recover_main < 0.01:
                    blacksmith_umbrella_swing_recover_main = 0.0

        if blacksmith_umbrella_swing_sound_pending:
            if blacksmith_umbrella_swing_sound_timer > 0:
                blacksmith_umbrella_swing_sound_timer -= 1
            if blacksmith_umbrella_swing_sound_timer <= 0:
                blacksmith_umbrella_swing_sound_pending = False
                if SOUND_BLACKSMITH_UMBRELLA_SWING:
                    play_sound_with_volume(SOUND_BLACKSMITH_UMBRELLA_SWING)

        umbrella_swinging_main = (
            blacksmith_umbrella_swing_active and blacksmith_umbrella_swing_stage == 1
        )

        # 부드러운 넉백 모션 업데이트
        update_umbrella_knockback()

        swing_trigger_direction = 0
        if left_pressed_raw and not right_pressed_raw:
            swing_trigger_direction = 1
        elif right_pressed_raw and not left_pressed_raw:
            swing_trigger_direction = -1

        # 스윙 통제불능 시간 중에는 스윙 불가
        global blacksmith_swing_cooldown
        swing_stun_timer = _rolling_get("rolling_stun_timer") if 'rolling_stun_timer' in _rolling_attr_map else 0
        if (
            swing_trigger_direction != 0
            and blacksmith_umbrella_open
            and not blacksmith_umbrella_retracting
            and blacksmith_umbrella_anim_timer == 0
            and not blacksmith_umbrella_swing_active
            and space_pressed_raw
            and not player_stunned
            and swing_stun_timer <= 0  # 스윙 통제불능 시간 중 스윙 불가
            and blacksmith_swing_cooldown <= 0  # 스윙 쿨다운 중 스윙 불가
        ):
            total_frames = BLACKSMITH_UMBRELLA_SWING_PREP_FRAMES + BLACKSMITH_UMBRELLA_SWING_SWING_FRAMES
            blacksmith_umbrella_swing_active = True
            blacksmith_umbrella_swing_timer = total_frames
            blacksmith_umbrella_swing_stage = 0
            blacksmith_umbrella_swing_progress = 0.0
            blacksmith_umbrella_swing_direction = swing_trigger_direction
            blacksmith_umbrella_swing_sound_timer = BLACKSMITH_UMBRELLA_SWING_SOUND_DELAY_FRAMES
            blacksmith_umbrella_swing_sound_pending = True
            
            # 강화디바인스톤 시 토르쉴드 스윙 후 0.4초 뒤 보랏빛 검기 발사 예약
            try:
                global blacksmith_divine_slash_scheduled
                blacksmith_divine_slash_scheduled = {
                    "direction": swing_trigger_direction,
                    "trigger_time": pygame.time.get_ticks() + BLACKSMITH_DIVINE_SLASH_DELAY_MS,
                }
            except Exception:
                pass
            
            # 스윙 시작 시 anchor smoothing 값을 목표값에 가깝게 초기화
            # 이전 스윙의 잔여값으로 인한 부드러운 전환을 방지
            if swing_trigger_direction < 0 and blacksmith_umbrella_anchor_right is not None:
                # 오른쪽 스윙: 목표값은 anchor_right
                blacksmith_umbrella_anchor_smoothed_x = float(blacksmith_umbrella_anchor_right)
            elif swing_trigger_direction > 0 and blacksmith_umbrella_anchor_left is not None:
                # 왼쪽 스윙: 목표값은 anchor_left
                blacksmith_umbrella_anchor_smoothed_x = float(blacksmith_umbrella_anchor_left)
            
            # 넉백 효과로 패들을 부드럽게 이동시킴
            # 스윙 방향과 반대 방향으로 넉백 (더 자연스러운 물리 반응)
            scale_applied = BLACKSMITH_SCALE if abs(BLACKSMITH_SCALE) > 1e-5 else 1.0
            base_knockback_distance = 40  # 기본 넉백 거리 (픽셀)
            
            # 스윙 방향과 반대로 넉백
            if swing_trigger_direction > 0:  # 왼쪽 스윙 → 오른쪽으로 넉백
                knockback_offset = base_knockback_distance
            else:  # 오른쪽 스윙 → 왼쪽으로 넉백
                knockback_offset = -base_knockback_distance
                
            target_player_x = PLAYER.x + knockback_offset
            
            # 화면 경계 체크
            target_player_x = max(PLAYER.width // 2, min(SCREEN_WIDTH - PLAYER.width // 2, target_player_x))

            # 토르쉴드 스윙 대쉬 시작 (스윙 방향으로 이동)
            # swing_trigger_direction: 1=왼쪽키(왼쪽 스윙), -1=오른쪽키(오른쪽 스윙)
            # 스윙 방향으로 이동하기 위해 방향을 반대로 설정 (왼쪽 스윙 시 왼쪽으로 이동)
            global blacksmith_swing_dash_active, blacksmith_swing_dash_timer, blacksmith_swing_dash_direction
            global blacksmith_swing_slide_active, blacksmith_swing_slide_velocity
            # 쿨다운 중이 아닐 때만 스윙 대쉬 발동
            if blacksmith_swing_cooldown <= 0:
                blacksmith_swing_dash_active = True
                blacksmith_swing_dash_timer = BLACKSMITH_SWING_DASH_DURATION + BLACKSMITH_SWING_DASH_DELAY
                blacksmith_swing_dash_direction = -swing_trigger_direction  # 스윙 방향으로 이동 (반전)
                # 미끄러짐 중이면 취소
                blacksmith_swing_slide_active = False
                blacksmith_swing_slide_velocity = 0
            # 넉백 비활성화 (스윙 대쉬와 충돌 방지)
            blacksmith_umbrella_knockback_active = False
            blacksmith_umbrella_knockback_timer = 0.0

            if DEBUG_BLACKSMITH_UMBRELLA_ANCHOR:
                pass

    if umbrella_lock_active:
        space_pressed = False
        down_pressed = False
        current_speed = 0

    if umbrella_action_block:
        space_pressed = False
        down_pressed = False

    # 전역 선언은 함수 상단으로 이동했으므로 여기서는 불필요
    if selected_character_type == "soldier":
        apply_fire_support_slot_restore()

    allow_weapon_switch = (
        selected_character_type == "soldier"
        and len(soldier_controller.weapons) > 1
    )

    global soldier_down_tap_timer, soldier_down_tap_count, soldier_down_tap_suppress_timer
    global soldier_emergency_supply_used, soldier_emergency_supply_stage

    if selected_character_type == "soldier":
        if soldier_emergency_supply_stage != current_stage:
            soldier_emergency_supply_stage = current_stage
            soldier_emergency_supply_used = False

        if soldier_down_tap_timer > 0:
            soldier_down_tap_timer -= 1
            if soldier_down_tap_timer == 0:
                soldier_down_tap_count = 0
        if soldier_down_tap_suppress_timer > 0:
            soldier_down_tap_suppress_timer -= 1

        # 비상보급(↓ 두 번)은 좌우 이동 입력 중에만 차단하고, 입력이 없으면 즉시 허용한다.
        # (속도 잔류로 인한 오검지를 방지하기 위해 이동 속도 조건은 제거)
        soldier_idle_for_emergency = (
            not left_pressed_raw
            and not right_pressed_raw
        )

        if down_just_pressed:
            if not soldier_idle_for_emergency:
                soldier_down_tap_timer = 0
                soldier_down_tap_count = 0
            elif soldier_down_tap_timer > 0 and soldier_down_tap_count == 1:
                if trigger_soldier_emergency_supply():
                    soldier_down_tap_suppress_timer = int(0.3 * 60)
                    supply_drop_state.hold_time = 0
                    supply_runtime.hold_active = False
                soldier_down_tap_timer = 0
                soldier_down_tap_count = 0
            else:
                soldier_down_tap_count = 1
                soldier_down_tap_timer = SOLDIER_EMERGENCY_SUPPLY_TAP_WINDOW

        # 휠/중클릭 전환은 메인 이벤트 루프에서만 처리 (여기서는 비움)

        if up_pressed and not space_pressed and allow_weapon_switch and not suicide_drone_active:
            soldier_weapon_hold_frames += 1
            if soldier_weapon_hold_frames >= SOLDIER_WEAPON_MENU_HOLD_FRAMES:
                soldier_weapon_menu_active = True
        else:
            if not up_pressed:
                if soldier_weapon_menu_active and not allow_weapon_switch:
                    soldier_weapon_menu_active = False
            elif space_pressed or not allow_weapon_switch:
                soldier_weapon_hold_frames = 0
                if soldier_weapon_menu_active:
                    soldier_weapon_menu_active = False

        max_slots = min(len(soldier_controller.weapons), len(soldier_weapon_number_prev))
        for idx in range(max_slots):
            key_const = getattr(pygame, f'K_{idx + 1}')
            pressed = keys[key_const]
            if soldier_weapon_menu_active and allow_weapon_switch and pressed and not soldier_weapon_number_prev[idx]:
                soldier_switch_weapon(idx)
                soldier_weapon_menu_active = False
                # HUD 클릭/선택 직후 한 프레임 Space 입력 억제(1프레임)
                soldier_weapon_menu_close_suppress_frames = max(soldier_weapon_menu_close_suppress_frames, 1)
                soldier_weapon_hold_frames = 0
            soldier_weapon_number_prev[idx] = pressed
        for idx in range(max_slots, len(soldier_weapon_number_prev)):
            soldier_weapon_number_prev[idx] = False

        if player_up_pressed_prev and not up_pressed:
            if soldier_weapon_menu_active:
                soldier_weapon_menu_active = False
            soldier_weapon_hold_frames = 0
    else:
        soldier_weapon_hold_frames = 0
        soldier_weapon_menu_active = False
        soldier_weapon_number_prev = [False] * len(soldier_weapon_number_prev)
        soldier_down_tap_timer = 0
        soldier_down_tap_count = 0
        soldier_down_tap_suppress_timer = 0

    # 물자보급 스킬 - ↓키 홀드로 발동 (코만도 캐릭터 전용)

    # 물자보급 발동 조건 체크 (대시와 같은 방식으로 서브 상태 처리)
    can_use_supply_drop = False
    # 기본 조건 (일반 상태에서 + 서브 완료 후 3초 경과)
    if not is_waiting_for_serve and not is_player_serve and serve_completed_timer <= 0:
        can_use_supply_drop = True
    # 플레이어 서브 상태에서는 6초 후에만 사용 가능
    elif is_player_serve and is_waiting_for_serve:
        serve_wait_time = pygame.time.get_ticks() - waiting_start_time
        if serve_wait_time >= 6000:  # 6초 이상 대기했을 때만
            can_use_supply_drop = True
            
    # 디버그: 물자보급 조건 상태 확인 (↓키를 눌렀을 때만)
    if down_pressed and selected_character_type == "soldier" and supply_drop_state.hold_time == 0:
        pass  # print(f"🔍 물자보급 조건: is_waiting_for_serve={is_waiting_for_serve}, is_player_serve={is_player_serve}, serve_timer={serve_completed_timer}, can_use={can_use_supply_drop}")
    
    # ↓키 홀드 체크 (코만도 캐릭터만)
    # 👁 오딘의 눈 변신 상태에서는 물자보급 사용 불가
    if (
        down_pressed
        and selected_character_type == "soldier"
        and not supply_drop_state.active
        and soldier_down_tap_suppress_timer == 0
        and not is_odins_eye_transformed()  # 👁 변신 상태에서는 차단
    ):
        # 쿨타임 체크 추가
        if is_soldier_skill_on_cooldown("supply_drop"):
            if supply_drop_state.hold_time == 0 and frame_count % 60 == 0:  # 1초마다만 출력
                remaining = get_soldier_skill_cooldown_seconds("supply_drop")
                # print(f"⏳ 물자보급 쿨타임 중: {remaining:.1f}초 남음")
        elif can_use_supply_drop and special_gauge >= supply_drop_state.config.gauge_cost:
            supply_drop_state.hold_time += 1

            # 홀드 진행률 디버그
            if supply_drop_state.hold_time % 10 == 0:  # 0.17초마다 출력
                progress = (supply_drop_state.hold_time / supply_drop_state.config.hold_required) * 100
                # print(f"📻 물자보급 홀드 중: {progress:.1f}% ({supply_drop_state.hold_time}/{supply_drop_state.config.hold_required})")

            if (
                supply_drop_state.hold_time == supply_drop_state.config.hold_threshold
                and not supply_runtime.hold_active
            ):
                start_supply_radio_loop()

            # 1.0초 홀드 완료 시 발동
            if supply_drop_state.hold_time >= supply_drop_state.config.hold_required:
                # 물자보급 스킬 발동
                timer_value = random.randint(90, 300)  # 1.5초~5초 (60fps 기준)
                cost = supply_drop_state.config.gauge_cost
                next_gauge = max(0, special_gauge - cost)
                # print(f"✅ 물자보급 발동 성공! special_gauge: {special_gauge} -> {next_gauge}")
                # print(f"🎁 타이머 설정: {timer_value} 프레임 ({timer_value/60:.1f}초 후 비행기 출현)")
                # print(f"⏱️ serve_completed_timer 상태: {serve_completed_timer}")
                supply_drop_state.active = True
                consume_special_gauge(cost)
                supply_drop_state.timer = timer_value
                supply_drop_state.hold_time = 0  # 홀드 시간 초기화

                # 무전기 모션 활성화 (0.5초)
                start_supply_radio_loop()

                # 코만도(솔저) 전용 스킬 사용을 실력 분석에 반영
                record_character_skill_usage()

                # 입력 잠금 제거: 물자보급 발동 시 이동을 멈추지 않음
                # (기존: soldier_control_lock_timer 30프레임)
                player_knockback_vel = 0  # 넉백 없음 (유지)

                # print("📻 물자보급 요청! 무전기 모션 시작")
                # print(f"물자보급 발동! {timer_value/60:.1f}초 후 비행기 출현")

                # 스킬 쿨타임 시작 (60초)
                trigger_soldier_skill_cooldown("supply_drop")
        else:
            # 물자보급 사용 불가 이유 출력
            if supply_drop_state.hold_time == 1:  # 처음 시도할 때만
                reasons = []
                if not can_use_supply_drop:
                    reasons.append("can_use=False")
                    if serve_completed_timer > 0:
                        reasons.append(f"serve_timer={serve_completed_timer}({serve_completed_timer/60:.1f}초)")
                if special_gauge < supply_drop_state.config.gauge_cost:
                    reasons.append(f"gauge부족={special_gauge}/{supply_drop_state.config.gauge_cost}")
                # print(f"❌ 물자보급 사용 불가: {', '.join(reasons)}")
    else:
        # ↓키를 떼면 홀드 시간 초기화
        if supply_drop_state.hold_time > 0:
            pass  # print(f"📻 물자보급 홀드 중단: {supply_drop_state.hold_time}/{supply_drop_state.config.hold_required}")
        supply_drop_state.hold_time = 0

        fire_support_radio_locked = False
        fire_support_radio_active = False
        if selected_character_type == "soldier":
            fire_support_weapon = get_fire_support_instance()
            fire_support_radio_active = fire_support_weapon.radio_active
            fire_support_radio_locked = (
                fire_support_radio_active and fire_support_weapon.is_calling()
            )

        if fire_support_radio_locked:
            # 화력지원 호출 시에는 무전 애니메이션을 강제로 유지해 0.7초 연출을 보장한다.
            supply_runtime.hold_active = True
        elif not supply_drop_state.active:
            supply_runtime.hold_active = False

        if (
            fire_support_radio_loop_active
            and not fire_support_radio_active
            and not supply_drop_state.active
        ):
            stop_supply_radio_loop(force=True)
            fire_support_radio_loop_active = False
    
    
    # 튜토리얼 대쉬 도우미는 일정 시간 동안 유지 (바로 끄지 않음)
    global tutorial_dash_helper_active, tutorial_dash_helper_start_time
    if current_stage == 50 and 'tutorial_dash_helper_active' in globals() and tutorial_dash_helper_active:
        # 1.7초 후에 자동으로 끄기 또는 대쉬 성공 시 끄기
        if 'tutorial_dash_helper_start_time' in globals():
            elapsed_time = pygame.time.get_ticks() - tutorial_dash_helper_start_time
            if elapsed_time > 1700:  # 1.7초 경과
                tutorial_dash_helper_active = False  # 도우미 끄기
                if DEBUG_TUTORIAL:
                    pass  # print("튜토리얼: 대쉬 도우미 1.7초 경과로 비활성화")
    # 마우스 조작 (비활성화됨)
    # if input_manager.get_control_mode() == "마우스":
    #     if mouse_controls.get("space", False):
    #         space_pressed = True
    #     if mouse_controls.get("down", False):
    #         down_pressed = True
    special_gauge_max = get_max_gauge()  #  아카데미 스킬 적용된 최대치
    
    # Stage 4 화상 효과 처리
    global player_burn_timer, player_burn_effect, player_knockback_y

    # 넉백 Y 위치 복구 (화상 여부와 관계없이 항상 적용 - return 전에 처리해야 함)
    if player_knockback_y != 0:
        # 부드럽게 원래 위치로 복구
        player_knockback_y *= 0.9
        if abs(player_knockback_y) < 1:
            player_knockback_y = 0

    if player_burn_timer > 0:
        player_burn_timer -= 1
        if player_burn_timer <= 0:
            player_burn_effect = False
            player_knockback_y = 0  # 화상 종료 시 Y 넉백 즉시 리셋
        # 버그 수정: 너비가 변경될 때만 업데이트
        _target_width = int(PADDLE_WIDTH * long_boost_scale * strange_vial_scale)
        if PLAYER.width != _target_width:
            _prev_center = PLAYER.centerx
            PLAYER.width = _target_width  # 화상 중에도 거대화포션 효과 적용
            PLAYER.centerx = _prev_center  # 크기 변경 시에도 중심 유지해 강제 이동 방지
        return  # 화상 중에는 조작 불가
    
    #  스턴 상태 처리
    if player_stunned_timer > 0:
        player_stunned_timer -= 1
        # 넉백 적용 (스턴 중 감속 이동)
        if abs(player_knockback_vel) > 0.5:
            old_x = PLAYER.x
            PLAYER.x += int(player_knockback_vel)
            PLAYER.x = max(0, min(WIDTH - PLAYER.width, PLAYER.x))
            pass  # print(f"🔧 [STUN] 감속이동: {old_x:.1f} → {PLAYER.x:.1f} (vel={player_knockback_vel:.2f}, timer={player_stunned_timer})")  # 디버그 비활성화
        # 감속 (뿔박치기는 더 부드러운 감속 적용)
        if horn_charge_player_knockback_active:
            player_knockback_vel *= 0.92  # 부드러운 감속 (0.85 → 0.92)
            if abs(player_knockback_vel) < 0.5:
                globals()['horn_charge_player_knockback_active'] = False
        else:
            player_knockback_vel *= 0.85 * _get_knockback_resist_scale()
        if fire_support_slot_restore_pending:
            apply_fire_support_slot_restore()
        if soldier_control_lock_timer > 0:
            soldier_control_lock_timer = max(0, soldier_control_lock_timer - 1)
        # 버그 수정: 너비가 변경될 때만 업데이트
        _target_width = int(PADDLE_WIDTH * long_boost_scale * strange_vial_scale)
        if PLAYER.width != _target_width:
            _prev_center = PLAYER.centerx
            PLAYER.width = _target_width  # 스턴 중에도 거대화포션 효과 적용
            PLAYER.centerx = _prev_center
        return  #  스턴 중에는 조작 불가
    
    # serve_completed_timer는 프레임 초기에 감소 처리됨
    # 미사일/폭발 넉백 처리 (물자보급 비행기 폭발 포함)
    if player_missile_stunned_timer > 0:
        player_missile_stunned_timer -= 1
        # 넉백 적용 (감속 이동)
        if abs(player_missile_knockback_vel) > 0.5:
            old_x = PLAYER.x
            PLAYER.x += int(player_missile_knockback_vel)
            PLAYER.x = max(0, min(WIDTH - PLAYER.width, PLAYER.x))
            pass  # print(f"🚀 [MISSILE STUN] 감속이동: {old_x:.1f} → {PLAYER.x:.1f} (vel={player_missile_knockback_vel:.2f}, timer={player_missile_stunned_timer})")  # 디버그 비활성화
        # 감속 (화염탄과 동일한 0.85)
        player_missile_knockback_vel *= 0.85 * _get_knockback_resist_scale()
        # 버그 수정: 너비가 변경될 때만 업데이트
        _target_width = int(PADDLE_WIDTH * long_boost_scale * strange_vial_scale)
        if PLAYER.width != _target_width:
            _prev_center = PLAYER.centerx
            PLAYER.width = _target_width  # 스턴 중에도 거대화포션 효과 적용
            PLAYER.centerx = _prev_center
        return  # 넉백 중에는 조작 불가

    # 🔥 화재 날씨 이벤트 및 🏓 패들 충돌 넉백 처리 (스턴 없이 점진적 감속 - 조작 가능)
    global player_fire_knockback_vel
    if abs(player_fire_knockback_vel) > 0.3:
        old_x = PLAYER.x
        new_x = PLAYER.x + player_fire_knockback_vel

        # 🧱 벽 반사 처리: 벽에 닿으면 반대 방향으로 튕김 (전체 물리 영역 내로 제한)
        player_min_x = 0
        player_max_x = WIDTH - PLAYER.width
        if new_x <= player_min_x:
            # 왼쪽 벽에 충돌 → 오른쪽으로 반사
            PLAYER.x = player_min_x
            player_fire_knockback_vel = abs(player_fire_knockback_vel) * 0.7  # 반사 시 30% 에너지 손실
        elif new_x >= player_max_x:
            # 오른쪽 벽에 충돌 → 왼쪽으로 반사
            PLAYER.x = player_max_x
            player_fire_knockback_vel = -abs(player_fire_knockback_vel) * 0.7  # 반사 시 30% 에너지 손실
        else:
            PLAYER.x = new_x

        # 감속 (0.85 → 매 프레임 15% 감소, 급감 효과)
        # 🧊 빙판 이벤트: 감속이 적어서 더 길게 미끄러짐 (0.85 → 0.94)
        if is_ice_active():
            ice_decay = 0.94  # 빙판에서는 6%만 감속 → 더 길게 미끄러짐
        else:
            ice_decay = 0.85  # 일반: 15% 감속
        player_fire_knockback_vel *= ice_decay * _get_knockback_resist_scale()
        if abs(player_fire_knockback_vel) <= 0.3:
            player_fire_knockback_vel = 0.0
        # 디버그 로그 (첫 프레임만 출력 방지를 위해 큰 값만)
        # 디버그 비활성화 - 성능 영향
        # if abs(player_fire_knockback_vel) > 1.0:
        #     print(f"{'🧊' if is_ice_active() else '🔥'} [KNOCKBACK] 플레이어 감속이동: {old_x:.1f} → {PLAYER.x:.1f} (vel={player_fire_knockback_vel:.2f})")

    #  벽돌 설치 중에는 움직이지 못함
    if wall_installing:
        return
    #  화염병 투척 모션 중 처리
    if molotov_throwing:
        molotov_throw_timer -= 1
        # 0.6초 후 (36프레임 후) throw.wav 재생 - 그러나 총 시간이 0.5초이므로 재생 안됨
        # 투척 완료 직후 재생하도록 변경
        if molotov_throw_timer == 0:  # 투척 완료 시점
            play_sound_with_volume(SOUND_THROW)
        if molotov_throw_timer <= 0:
            molotov_throwing = False
            throw_molotov()  # 실제 투척
        return  # 투척 모션 중에는 조작 불가
    #  수류탄 투척 모션 중 처리
    if grenade_throwing:
        grenade_throw_timer -= 1
        # 0.6초 후 (36프레임 후) throw.wav 재생 - 그러나 총 시간이 0.5초이므로 재생 안됨
        # 투척 완료 직후 재생하도록 변경
        if grenade_throw_timer == 0:  # 투척 완료 시점
            play_sound_with_volume(SOUND_THROW)
        if grenade_throw_timer <= 0:
            grenade_throwing = False
            throw_grenade()  # 실제 투척
        return  # 투척 모션 중에는 조작 불가
    #  조명탄 투척 모션 중 처리
    if flare_throwing:
        flare_throw_timer -= 1
        # 0.6초 후 (36프레임 후) throw.wav 재생 - 그러나 총 시간이 0.5초이므로 재생 안됨
        # 투척 완료 직후 재생하도록 변경
        if flare_throw_timer == 0:  # 투척 완료 시점
            play_sound_with_volume(SOUND_THROW)
        if flare_throw_timer <= 0:
            flare_throwing = False
            throw_flare()  # 실제 투척
        return  # 투척 모션 중에는 조작 불가
    # 🧨 다이너마이트 투척 모션 중 처리
    if dynamite_throwing:
        dynamite_throw_timer -= 1
        # 투척 완료 직후 throw.wav 재생
        if dynamite_throw_timer == 0:  # 투척 완료 시점
            play_sound_with_volume(SOUND_THROW)
        if dynamite_throw_timer <= 0:
            dynamite_throwing = False
            throw_dynamite()  # 실제 투척
        return  # 투척 모션 중에는 조작 불가
    # 🍌 바나나 투척 모션 중 처리
    if banana_throwing:
        banana_throw_timer -= 1
        # 투척 완료 직후 throw.wav 재생
        if banana_throw_timer == 0:  # 투척 완료 시점
            play_sound_with_volume(SOUND_THROW)
        if banana_throw_timer <= 0:
            banana_throwing = False
            throw_banana()  # 실제 투척
        return  # 투척 모션 중에는 조작 불가
    # 🧼 비누 투척 모션 중 처리
    if soap_throwing:
        soap_throw_timer -= 1
        if soap_throw_timer == 0:  # 투척 완료 시점
            play_sound_with_volume(SOUND_THROW)
        if soap_throw_timer <= 0:
            soap_throwing = False
            throw_soap()  # 실제 투척
        return  # 투척 모션 중에는 조작 불가
    # 🪃 부메랑 투척 모션 중 처리
    if boomerang_throwing:
        boomerang_throw_timer -= 1
        if boomerang_throw_timer == 0:  # 투척 완료 시점
            play_sound_with_volume(SOUND_THROW)
        if boomerang_throw_timer <= 0:
            boomerang_throwing = False
            throw_boomerang()  # 실제 투척
        return  # 투척 모션 중에는 조작 불가
    # 연막탄 투척 모션 제거 (즉시 발동으로 변경됨)
    #  디버프 적용: 느려지는 효과
    if player_slow_timer > 0:
        speed_factor = player_slow_factor
        player_slow_timer -= 1
    else:
        speed_factor = 1.0
        player_slow_factor = 1.0  # 누적 감속 초기화

    # 포도대장 포승줄: 이동속도 50% 감소
    if arrest_rope_active:
        speed_factor *= 0.5

    # 코만도 물자보급요청(홀드) 중 이동속도 -40% 감속
    # 조건: 코만도이며 ↓키를 누르고 있고, 물자보급 대기/홀드 상태일 때만 적용
    #  - hold_time>0: 홀드 진행 중
    #  - supply_runtime.hold_active: 무전 애니메이션 유지 상태(홀드 임계 도달 등)
    #  - active=False: 비행기 호출이 이미 활성화되어 입력 잠금 중일 때는 의미 없음(무해)
    try:
        if (
            selected_character_type == "soldier"
            and down_pressed  # 현재 프레임에 ↓키를 누르는 동안만
            and not supply_drop_state.active
            and (
                supply_drop_state.hold_time > 0
                or supply_runtime.hold_active
                # 홀드 첫 프레임 보호: 조건이 충족되어 즉시 홀드에 진입 가능한 경우도 감속 적용
                or (
                    'can_use_supply_drop' in locals()
                    and can_use_supply_drop
                    and special_gauge >= supply_drop_state.config.gauge_cost
                )
            )
        ):
            speed_factor *= 0.6  # -40%
    except Exception:
        # 안전 가드: 어떤 이유로든 참조 실패 시 감속 미적용
        pass

    # 아라크네 거미줄 장판: 이동속도 60% 감소
    web_slow = get_web_trap_player_slow()
    if web_slow < 1.0:
        speed_factor *= web_slow

    umbrella_guarding = (
        selected_character_type == "blacksmith"
        and blacksmith_umbrella_open
        and not blacksmith_umbrella_retracting
    )
    if umbrella_guarding:
        speed_factor *= BLACKSMITH_UMBRELLA_MOVE_MULTIPLIER

    def apply_umbrella_turn_penalty(current_value: float, target_value: float) -> float:
        """토르쉴드 가드 중에는 좌우 전환을 점진적으로 적용한다."""
        if not umbrella_guarding:
            return target_value
        same_sign = (
            current_value > 0 and target_value > 0
        ) or (
            current_value < 0 and target_value < 0
        )
        if same_sign and target_value != 0:
            return target_value
        max_step = abs(target_value) * BLACKSMITH_UMBRELLA_TURN_MULTIPLIER
        if target_value == 0:
            max_step = max(0.08, max_step)
        max_step = max(0.00007, max_step)
        delta = target_value - current_value
        if delta > 0:
            return current_value + min(delta, max_step)
        return current_value + max(delta, -max_step)

    # === 롱부스트 타이머 체크 및 점진적 크기 변화 ===
    if long_boost_active:
        if long_boost_timer > 0:
            long_boost_timer -= 1
            # 경과 시간 = 초기 타이머 - 현재 타이머
            elapsed = long_boost_initial_timer - long_boost_timer
            # 시작 단계 (1초간 점진적 확대)
            if elapsed < LONG_BOOST_TRANSITION_TIME:
                progress = elapsed / LONG_BOOST_TRANSITION_TIME
                long_boost_scale = 1.0 + (1.5 - 1.0) * progress
            # 종료 단계 (남은 시간이 1초 이하)
            elif long_boost_timer <= LONG_BOOST_TRANSITION_TIME:
                progress = long_boost_timer / LONG_BOOST_TRANSITION_TIME
                long_boost_scale = 1.0 + (1.5 - 1.0) * progress
            # 유지 단계
            else:
                long_boost_scale = 1.5
            # 타이머 종료 시
            if long_boost_timer == 0:
                long_boost_active = False
                long_boost_scale = 1.0
                long_boost_target_scale = 1.0
                try:
                    _hg_on_deactivate('long_boost')
                except Exception:
                    pass
                # print("")
    global doping_potion_active, doping_potion_timer, doping_potion_toast_timer
    global berserk_potion_active, berserk_potion_timer
    sync_doping_potion_from_global_manager()
    if doping_potion_active:
        if doping_potion_timer > 0:
            doping_potion_timer -= 1
            if doping_potion_timer <= 0:
                deactivate_doping_potion()
        else:
            deactivate_doping_potion()
    if doping_potion_toast_timer > 0:
        doping_potion_toast_timer -= 1
    if doping_potion_active:
        _get_global_manager().set('doping_potion_timer_frames', doping_potion_timer)

    # 비타민약 타이머 갱신
    global vitamin_pill_active, vitamin_pill_timer
    if vitamin_pill_active:
        if vitamin_pill_timer > 0:
            vitamin_pill_timer -= 1
            if vitamin_pill_timer <= 0:
                deactivate_vitamin_pill()
        else:
            deactivate_vitamin_pill()

    sync_berserk_potion_from_global_manager()
    if berserk_potion_active:
        if berserk_potion_timer > 0:
            berserk_potion_timer -= 1
            if berserk_potion_timer <= 0:
                deactivate_berserk_potion()
        else:
            deactivate_berserk_potion()
    if berserk_potion_active:
        _get_global_manager().set('berserk_potion_timer_frames', berserk_potion_timer)

    # 기묘한 약병 타이머 업데이트 + 점진적 크기/속도 보간
    if strange_vial_active:
        if strange_vial_timer > 0:
            strange_vial_timer -= 1
            _sv_elapsed = strange_vial_initial_timer - strange_vial_timer
            _sv_ts = strange_vial_target_scale
            _sv_tsp = strange_vial_target_speed_mult
            # 시작 단계: 점진적으로 목표 배율까지 보간 (0.75초)
            if _sv_elapsed < STRANGE_VIAL_TRANSITION_TIME:
                _sv_p = _sv_elapsed / max(1, STRANGE_VIAL_TRANSITION_TIME)
                strange_vial_scale = 1.0 + (_sv_ts - 1.0) * _sv_p
                strange_vial_speed_mult = 1.0 + (_sv_tsp - 1.0) * _sv_p
            # 종료 단계: 점진적으로 1.0으로 복원 (마지막 0.75초)
            elif strange_vial_timer <= STRANGE_VIAL_TRANSITION_TIME:
                _sv_p = strange_vial_timer / max(1, STRANGE_VIAL_TRANSITION_TIME)
                strange_vial_scale = 1.0 + (_sv_ts - 1.0) * _sv_p
                strange_vial_speed_mult = 1.0 + (_sv_tsp - 1.0) * _sv_p
            # 유지 단계
            else:
                strange_vial_scale = _sv_ts
                strange_vial_speed_mult = _sv_tsp
            # 타이머 종료
            if strange_vial_timer <= 0:
                deactivate_strange_vial()
        else:
            deactivate_strange_vial()
    if strange_vial_active:
        _get_global_manager().set('strange_vial_timer_frames', strange_vial_timer)

    # === 킥차져 게이지 충전 애니메이션 타이머 ===
    global gauge_charge_animation_timer
    if gauge_charge_animation_timer > 0:
        gauge_charge_animation_timer -= 1
    
    #  AI 필 효과 적용
    if aipill_active:
        # AI 필 활성화 시 필살기/아이템 사용 불가 (게이지는 유지하되 획득 불가)
        special_ready = False
        special_active = False
        # AI 필 활성화 시 공을 99% 확률로 막아내는 완벽한 추적
        # 공의 중심을 패들의 중심으로 맞추기
        target_x = BALL.centerx - PLAYER.width // 2
        # 경계 처리 - 패들이 전체 게임 물리 영역(0~WIDTH) 밖으로 나가지 않도록
        player_min_x = 0
        player_max_x = WIDTH - PLAYER.width
        if target_x < player_min_x:
            target_x = player_min_x
        elif target_x > player_max_x:
            target_x = player_max_x
        # 즉시 목표 위치로 이동 (지연 없음)
        if abs(PLAYER.x - target_x) > 0.5:  # 0.5픽셀 이상 차이나면 움직임
            if PLAYER.x < target_x:
                # 오른쪽으로 이동
                current_speed = MAX_SPEED * aipill_speed_boost
            elif PLAYER.x > target_x:
                # 왼쪽으로 이동
                current_speed = -MAX_SPEED * aipill_speed_boost
        else:
            # 목표 위치에 도달하면 즉시 정지
            current_speed = 0
    else:
        #  구르기 상태 처리
        if _rolling_get("rolling_active"):
            # 구르기 중일 때
            rolling_timer_value = _rolling_get("rolling_timer") - 1
            _rolling_set("rolling_timer", rolling_timer_value)

            # 🌑 오딘의 눈 대쉬 다이브: 참조 변수 준비 (종료 훅에서 사용)
            _du_oe = None
            try:
                from legendary_items import get_legendary_manager as _glm_du
                _du_mgr = _glm_du()
                if _du_mgr:
                    _du_oe = _du_mgr.get_item("odins_eye")
            except Exception:
                pass

            # === 연속대쉬 조기 발동: 대쉬 시작 후 고정 시간이 지나면 연속대쉬 허용 ===
            # 대쉬 거리 보너스와 무관하게 동일한 타이밍에 연속대쉬 가능 (밀리초 기준)
            _elapsed_ms = pygame.time.get_ticks() - _dash_start_time
            if _elapsed_ms >= CONSECUTIVE_DASH_START_DELAY_MS and rolling_timer_value > 0:
                # 연속대쉬 조건 체크 (토큰, 방향키+아래키)
                _early_base_charges = 1
                _early_holder_bonus = _get_dashholder_count()
                _early_amplification_bonus = get_runtime_skill_bonus("dash_amplification")
                _early_max_charges = int(_early_base_charges + _early_holder_bonus + _early_amplification_bonus)
                _early_rolling_charges = sum(1 for s in token_states if s) if 'token_states' in globals() else _rolling_get("rolling_charges")
                _early_half_dash_used = 'half_dash_used_flag' in globals() and half_dash_used_flag

                # 토큰이 2개 이상이고 하프대쉬 미사용 시에만 조기 연속대쉬 가능
                if _early_max_charges > 1 and _early_rolling_charges > 0 and not _early_half_dash_used:
                    _early_left = is_move_left_pressed(keys) or MOVE_EVENT_LEFT
                    _early_right = is_move_right_pressed(keys) or MOVE_EVENT_RIGHT

                    if _early_left and down_pressed and not dash_down_first_lock:
                        # 현재 대쉬 즉시 종료하고 연속 왼쪽 대쉬 시작
                        _rolling_set("rolling_timer", 0)
                        _rolling_set("rolling_active", False)
                        _rolling_set("rolling_stun_timer", 1)  # 최소 후딜로 연속대쉬 트리거
                        # 🌑 오딘 다이브: 조기 종료 → 솟아오르기 (연속대쉬 시 start_dash_dive가 취소함)
                        try:
                            if _du_oe and _du_oe.odin_dash_underground_phase:
                                _du_oe.end_dash_dive(PLAYER.centerx, PLAYER.centery)
                        except Exception:
                            pass
                        # 연속대쉬는 stun 블록에서 처리됨
                    elif _early_right and down_pressed and not dash_down_first_lock:
                        # 현재 대쉬 즉시 종료하고 연속 오른쪽 대쉬 시작
                        _rolling_set("rolling_timer", 0)
                        _rolling_set("rolling_active", False)
                        _rolling_set("rolling_stun_timer", 1)  # 최소 후딜로 연속대쉬 트리거
                        # 🌑 오딘 다이브: 조기 종료 → 솟아오르기 (연속대쉬 시 start_dash_dive가 취소함)
                        try:
                            if _du_oe and _du_oe.odin_dash_underground_phase:
                                _du_oe.end_dash_dive(PLAYER.centerx, PLAYER.centery)
                        except Exception:
                            pass
                        # 연속대쉬는 stun 블록에서 처리됨

            if rolling_timer_value <= 0:
                # 구르기 종료, 통제 불가능 상태 시작
                _rolling_set("rolling_active", False)
                # 소울버스트 대쉬 종료
                try:
                    from item_effects.soul_burst import end_soul_dash
                    end_soul_dash()
                except Exception:
                    pass
                # 🌑 오딘의 눈 대쉬 다이브: 대쉬 종료 → 솟아오르기
                try:
                    if _du_oe and (_du_oe.odin_dash_underground_phase or _du_oe.odin_dash_sink_phase):
                        _du_oe.end_dash_dive(PLAYER.centerx, PLAYER.centery)
                except Exception:
                    pass
                # 하프대쉬 플래그는 충돌 처리가 완료될 때까지 유지

                # 튜토리얼: 대쉬 종료 시 카운팅 플래그 리셋
                if current_stage == 50 and 'tutorial_dash_already_counted' in globals():
                    tutorial_dash_already_counted = False
                
                # 튜토리얼: 연속대쉬는 이제 사용 즉시 카운팅되므로 pending 플래그 리셋 불필요
                # Consecutive dash now counts immediately when used
                
                #  가속화 스킬: 대쉬 종료 시 충돌 범위 복원
                if acceleration_active:
                    acceleration_height_bonus = 0  # 추가 높이 제거
                    acceleration_active = False
                    acceleration_flash_particles.clear()  # 섬광 파티클 제거
                #  위험감지센서 자동 대쉬는 후딜시간 없음
                if is_danger_sensor_dash:
                    _rolling_set("rolling_stun_timer", 0)
                    _rolling_set("rolling_dash_available_timer", 0)
                    is_danger_sensor_dash = False  # 플래그 리셋
                else:
                    # 일반 대쉬의 경우 기존 로직 적용
                    # 아카데미 스킬 효과: 후딜 시간 감소 (모듈제어)
                    module_control_bonus = get_runtime_skill_bonus("dash_module_control")
                    stun_reduction = int(module_control_bonus * 42)  # 기본 42프레임에서 12%씩 감소
                    # 스파이크부츠 효과: 후딜 시간 감소 (롤 옵션 적용)
                    base_stun_time = apply_spikeboots_afterdelay(42)  # 0.7초 (60fps * 0.7)
                    final_stun_time = max(1, base_stun_time - stun_reduction)  # 최소 1프레임

                    # 하프대쉬 패널티: 통제불능 시간 1.5배 (_current_dash_is_half 사용 - 대쉬 종료까지 유지되는 플래그)
                    _is_half = _current_dash_is_half
                    if _is_half:
                        final_stun_time = int(final_stun_time * 1.5)

                    # 대쉬부스트 효과: 후딜 시간 99% 감소
                    try:
                        from item_effects.dash_boost import get_dash_cooldown_multiplier
                        cooldown_multiplier = get_dash_cooldown_multiplier()
                        if cooldown_multiplier < 1.0:
                            # 대쉬부스트 활성화 시 후딜 시간도 99% 감소
                            final_stun_time = max(1, int(final_stun_time * cooldown_multiplier))
                    except ImportError:
                        pass

                    _rolling_set("rolling_stun_timer", final_stun_time)
                    _rolling_set("rolling_dash_available_timer", final_stun_time)

                    # 대쉬 후딜(통제불능) 사운드 재생 - 연속 대쉬 가능 시에는 재생하지 않음
                    # 연속 대쉬 조건: 토큰이 남아있고 방향키+아래키가 눌려있으면 다음 대쉬가 바로 발동됨
                    _remaining_tokens = sum(1 for s in token_states if s) if 'token_states' in globals() else _rolling_get("rolling_charges")
                    _can_consecutive_dash = False
                    if _remaining_tokens > 0 or is_dash_unlimited():
                        # 방향키와 아래키가 동시에 눌려있는지 확인
                        _left_held = is_move_left_pressed(keys) or MOVE_EVENT_LEFT
                        _right_held = is_move_right_pressed(keys) or MOVE_EVENT_RIGHT
                        _down_held = down_pressed  # 이미 계산된 down_pressed 사용
                        if (_left_held or _right_held) and _down_held:
                            _can_consecutive_dash = True

                    # 연속 대쉬가 불가능할 때만 후딜 사운드 재생 (마지막 대쉬)
                    if not _can_consecutive_dash:
                        play_dash_delay_sound()

                    # 하프대쉬 플래그 리셋 (다음 대쉬를 위해)
                    globals()["_current_dash_is_half"] = False

                    # 포세이돈 삼지창 효과: 후딜 상태 진입시 양쪽에 회오리 생성
                    if poseidon_dash_pending and legendary_manager:
                        trident = legendary_manager.get_item("poseidon_trident")
                        if trident and trident.active:
                            # 게이지 소모량 체크 (롤 옵션 적용)
                            _poseidon_gauge_cost = int(trident.gauge_cost)
                            if special_gauge >= _poseidon_gauge_cost:
                                # 대쉬가 완료되고 후딜 상태에 진입할 때 현재 플레이어 위치 양쪽에 회오리 생성
                                # trigger_dash_wave가 True를 반환하면 효과 발동 성공, False면 쿨타임 중
                                if trident.trigger_dash_wave(PLAYER.centerx, PLAYER.centery, _rolling_get("rolling_direction")):
                                    special_gauge -= _poseidon_gauge_cost  # 게이지 소모
                                    play_poseidon_wave_sound()  # 효과 발동 시에만 사운드 재생
                            poseidon_dash_pending = False  # 플래그 리셋

                # 🧊 얼음 이벤트: 대쉬 종료 시 미끄러짐 시작 (끝까지 미끄러짐)
                if is_ice_active() and not ice_dash_sliding:
                    # 이미 미끄러지는 중이 아닐 때만 새로 발동
                    dash_direction = _rolling_get("rolling_direction")
                    ice_dash_sliding = True
                    ice_dash_slide_timer = 999  # 벽에 닿을 때까지 무한 지속 (타이머 대신 벽 충돌로 종료)
                    ice_dash_slide_direction = dash_direction
                    ice_dash_slide_speed = 25  # 대쉬 후 미끄러지는 기본 속도 (더 빠르게)
                    # 대쉬 상태 즉시 해제하여 미끄러짐이 바로 시작되도록 함
                    _rolling_set("rolling_active", False)
                    _rolling_set("rolling_timer", 0)
                    # 🌑 오딘 다이브: 얼음 전환 시 솟아오르기
                    try:
                        if _du_oe and (_du_oe.odin_dash_underground_phase or _du_oe.odin_dash_sink_phase):
                            _du_oe.end_dash_dive(PLAYER.centerx, PLAYER.centery)
                    except Exception:
                        pass
                    # 🧊 중요: current_speed를 0으로 설정하여 일반 이동이 적용되지 않도록 함
                    current_speed = 0
                    if DEBUG_MODE:
                        pass  # print(f"[ICE DEBUG] 대쉬 종료 -> 미끄러짐 시작! dir={dash_direction}, speed={ice_dash_slide_speed}")

                    # 🧊 첫 번째 미끄러짐 이동을 즉시 실행 (지연 방지)
                    ice_slide_offset = ice_dash_slide_speed * ice_dash_slide_direction
                    PLAYER.x += int(ice_slide_offset)
                    PLAYER.x = max(0, min(WIDTH - PLAYER.width, PLAYER.x))
                    if DEBUG_MODE:
                        pass  # print(f"[ICE SLIDE] 즉시 첫 이동! offset={ice_slide_offset}, new_x={PLAYER.x}")

                    # 벽에 바로 닿았는지 체크
                    if PLAYER.x <= 0 or PLAYER.x >= WIDTH - PLAYER.width:
                        if DEBUG_MODE:
                            pass  # print(f"[ICE DEBUG] 즉시 벽에 닿음! x={PLAYER.x}")
                        ice_dash_sliding = False
                        ice_dash_slide_speed = 0
                    # 얼음에서는 미끄러짐으로 이동 처리 (current_speed = 0 유지)
                elif not is_ice_active():
                    current_speed = 0
            else:
                # 🧊 얼음 미끄러짐 중이면 대쉬 속도를 적용하지 않음
                if ice_dash_sliding:
                    current_speed = 0
                # 🧊 얼음 위에서 대쉬 중이고 감속 구간에 들어가면 즉시 미끄러짐으로 전환
                elif is_ice_active() and rolling_timer_value <= 20:
                    # 감속 구간에 진입하면 바로 미끄러짐 시작 (감속 없이 미끄러짐으로 연결)
                    dash_direction = _rolling_get("rolling_direction")
                    ice_dash_sliding = True
                    ice_dash_slide_timer = 999
                    ice_dash_slide_direction = dash_direction
                    ice_dash_slide_speed = 25  # 대쉬 후 미끄러지는 기본 속도
                    _rolling_set("rolling_active", False)
                    _rolling_set("rolling_timer", 0)
                    current_speed = 0
                    # 🌑 오딘 다이브: 감속 전환 시 솟아오르기
                    try:
                        if _du_oe and (_du_oe.odin_dash_underground_phase or _du_oe.odin_dash_sink_phase):
                            _du_oe.end_dash_dive(PLAYER.centerx, PLAYER.centery)
                    except Exception:
                        pass
                    if DEBUG_MODE:
                        pass  # print(f"[ICE DEBUG] 대쉬 감속구간 -> 즉시 미끄러짐 전환! dir={dash_direction}, speed={ice_dash_slide_speed}")
                # 구르기 중에는 순간적으로 매우 빠르게 이동 후 빠르게 감속
                elif rolling_timer_value > 20:  # 처음 10프레임은 매우 빠르게
                    current_speed = _rolling_get("rolling_direction") * 40  # 매우 빠른 속도
                else:  # 나머지는 빠르게 감속
                    decel_factor = rolling_timer_value / 20.0
                    current_speed = _rolling_get("rolling_direction") * 40 * decel_factor
                # 대쉬 중에도 토큰 충전 타이머 감소 (균일한 애니메이션을 위해)
                # 투기장 모드에서는 자체 충전 시스템 사용 (스테이지 충전 로직 스킵)
                if _charging_state["timer"] > 0 and _charging_state["index"] >= 0 and not arena_mode_enabled:
                    _charging_state["timer"] -= 1
                    # _token_charge_states도 함께 감소 (균등 애니메이션용) - ratio 적용
                    charge_idx = _charging_state["index"]
                    if charge_idx < len(_token_charge_states):
                        if _token_charge_states[charge_idx]["timer"] > 0:
                            ui_ratio = _token_charge_states[charge_idx].get("ratio", 1.0)
                            _token_charge_states[charge_idx]["timer"] -= ui_ratio
                    # 충전 완료 체크
                    if _charging_state["timer"] <= 0:
                        if charge_idx < len(token_states):
                            token_states[charge_idx] = True
                            new_charges = sum(1 for s in token_states if s)
                            _rolling_set("rolling_charges", new_charges)
                            rolling_charges = new_charges
                            # UI 타이머도 0으로 강제 설정 (실제 충전과 UI 동기화)
                            if charge_idx < len(_token_charge_states):
                                _token_charge_states[charge_idx]["timer"] = 0
                                # 부스트차징 플래그 초기화
                                _token_charge_states[charge_idx]["boost_charging"] = False
                            # 부스트차징 토큰 인덱스만 초기화 (boost_charging_active는 타이머가 남아있으면 유지)
                            if boost_charging_token_idx == charge_idx:
                                globals()["boost_charging_token_idx"] = -1
                            # 충전 완료 플래시 타이머 설정 (반짝임 효과)
                            while len(_token_flash_timers) <= charge_idx:
                                _token_flash_timers.append(0)
                            _token_flash_timers[charge_idx] = _TOKEN_FLASH_DURATION
                            # 모든 토큰 풀충전 시 화려한 반짝임 효과 활성화
                            # max_charges 계산
                            base_charges = 1
                            holder_bonus = _get_dashholder_count()
                            amplification_bonus = get_runtime_skill_bonus("dash_amplification")
                            max_charges = int(base_charges + holder_bonus + amplification_bonus)
                            if new_charges >= max_charges:
                                _all_tokens_full_sparkle_timer = _ALL_TOKENS_FULL_SPARKLE_DURATION
                                # print(f"[DEBUG] 완충! 타이머 설정: {_ALL_TOKENS_FULL_SPARKLE_DURATION}")
                            # 대쉬 토큰 충전 완료 효과음 재생
                            play_dash_charge_sound()
                        _charging_state["index"] = -1
                        # 다음 토큰 충전 즉시 시작 (대쉬 중에도 연속 충전 지원)
                        _next_idx_dash = -1
                        for _tidx in range(len(token_states)):
                            if not token_states[_tidx]:
                                _next_idx_dash = _tidx
                                break
                        if _next_idx_dash >= 0:
                            # 충전 시간 계산
                            _dash_cd_bonus = get_runtime_skill_bonus("dash_cooldown")
                            _cd_reduction = int(_dash_cd_bonus * FPS)
                            _base_cd = apply_spikeboots_cooldown(300)
                            _new_timer = max(6, _base_cd - _cd_reduction)
                            _lw_bonus = get_runtime_skill_bonus("dash_lightweight")
                            if _lw_bonus > 0:
                                _new_timer = max(6, int(_new_timer * (1 - _lw_bonus)))
                            # 부스트차징은 대쉬 사용 시에만 적용 (자동 연속 충전에서는 미적용)
                            _charging_state["timer"] = _new_timer
                            _charging_state["max_time"] = _new_timer
                            _charging_state["index"] = _next_idx_dash
                            # UI 상태도 업데이트
                            while len(_token_charge_states) <= _next_idx_dash:
                                _token_charge_states.append({"timer": 0, "max_time": _UI_CHARGE_MAX, "ratio": 1.0})
                            _ui_ratio = _UI_CHARGE_MAX / _new_timer if _new_timer > 0 else 1.0
                            _token_charge_states[_next_idx_dash] = {"timer": _UI_CHARGE_MAX, "max_time": _UI_CHARGE_MAX, "ratio": _ui_ratio}
        elif _rolling_get("rolling_stun_timer") > 0:
            # 구르기 후 통제 불가능 상태

            # ========== 리커버리 스킬 체크 (스매셔 전용) ==========
            # 통제불능 상태에서 상키(W)로 즉시 해제
            # 👁 오딘의 눈 변신 상태에서는 기존 스킬 사용 불가
            if selected_character_type == "smasher" and not is_odins_eye_transformed():
                global _recovery_up_key_released
                if '_recovery_up_key_released' not in globals():
                    _recovery_up_key_released = True

                # 상키 입력 체크
                up_pressed_for_recovery = keys[pygame.K_UP] or keys[pygame.K_w]

                # 키를 뗐다가 다시 눌렀을 때만 발동 (연속 발동 방지)
                if not up_pressed_for_recovery:
                    _recovery_up_key_released = True

                if up_pressed_for_recovery and _recovery_up_key_released:
                    _recovery_up_key_released = False

                    # 스킬 해금 확인
                    if not is_smasher_skill_unlocked("recovery"):
                        pass  # 해금되지 않으면 무시
                    # 쿨타임 체크
                    elif get_smasher_skill_cooldown_remaining("recovery") > 0:
                        pass  # print(f"[리커버리] 쿨타임 중!")
                    # 게이지 확인
                    elif special_gauge >= RECOVERY_GAUGE_COST:
                        # 리커버리 발동!
                        special_gauge -= RECOVERY_GAUGE_COST
                        _rolling_set("rolling_stun_timer", 0)  # 통제불능 즉시 해제
                        stop_dash_delay_sound()  # 후딜 사운드 즉시 중지

                        # 패들 위치 계산 (이펙트용) - PLAYER 객체에서 직접 가져옴
                        if PLAYER is not None:
                            paddle_center_x = PLAYER.x + PADDLE_WIDTH / 2
                            paddle_center_y = PLAYER.y + PADDLE_HEIGHT / 2
                        else:
                            paddle_center_x = GAME_AREA_OFFSET_X + GAME_PLAY_WIDTH // 2
                            paddle_center_y = HEIGHT - 40 + PADDLE_HEIGHT / 2
                        trigger_recovery_effect(paddle_center_x, paddle_center_y)

                        # 리커버리 사운드 효과
                        try:
                            if SOUND_RECOVERY:
                                SOUND_RECOVERY.play()
                        except:
                            pass

                        # 스매셔 스킬 쿨타임 적용
                        trigger_smasher_skill_cooldown("recovery")

                        # print(f"[리커버리] 통제불능 해제! 게이지 -{RECOVERY_GAUGE_COST}")
                    else:
                        pass  # print(f"[리커버리] 게이지 부족: {special_gauge}/{RECOVERY_GAUGE_COST}")
            # ========== 리커버리 스킬 체크 끝 ==========

            _prev_stun = _rolling_get("rolling_stun_timer")
            _rolling_set("rolling_stun_timer", _prev_stun - 1)
            # 후딜 시간이 끝나면 사운드 중지 및 튜토리얼 콜백
            if _prev_stun > 0 and _rolling_get("rolling_stun_timer") <= 0:
                stop_dash_delay_sound()
                # 실전 튜토리얼: 통제불능 종료 시 콜백
                on_player_stun_end_for_tutorial()
            if _rolling_get("rolling_dash_available_timer") > 0:
                _rolling_set("rolling_dash_available_timer", _rolling_get("rolling_dash_available_timer") - 1)
            # 스턴 중에도 토큰 충전 타이머 감소 (균일한 애니메이션을 위해)
            # 투기장 모드에서는 자체 충전 시스템 사용 (스테이지 충전 로직 스킵)
            if _charging_state["timer"] > 0 and _charging_state["index"] >= 0 and not arena_mode_enabled:
                _charging_state["timer"] -= 1
                # _token_charge_states도 함께 감소 (균등 애니메이션용) - ratio 적용
                charge_idx = _charging_state["index"]
                if charge_idx < len(_token_charge_states):
                    if _token_charge_states[charge_idx]["timer"] > 0:
                        ui_ratio = _token_charge_states[charge_idx].get("ratio", 1.0)
                        _token_charge_states[charge_idx]["timer"] -= ui_ratio
                # 충전 완료 체크
                if _charging_state["timer"] <= 0:
                    if charge_idx < len(token_states):
                        token_states[charge_idx] = True
                        new_charges = sum(1 for s in token_states if s)
                        _rolling_set("rolling_charges", new_charges)
                        rolling_charges = new_charges
                        # UI 타이머도 0으로 강제 설정 (실제 충전과 UI 동기화)
                        if charge_idx < len(_token_charge_states):
                            _token_charge_states[charge_idx]["timer"] = 0
                            # 부스트차징 플래그 리셋
                            _token_charge_states[charge_idx]["boost_charging"] = False
                            # 부스트차징 토큰 인덱스만 초기화 (boost_charging_active는 타이머가 남아있으면 유지)
                            if boost_charging_token_idx == charge_idx:
                                globals()["boost_charging_token_idx"] = -1
                        # 충전 완료 플래시 타이머 설정 (반짝임 효과)
                        while len(_token_flash_timers) <= charge_idx:
                            _token_flash_timers.append(0)
                        _token_flash_timers[charge_idx] = _TOKEN_FLASH_DURATION
                        # 모든 토큰 풀충전 시 화려한 반짝임 효과 활성화
                        # max_charges 계산 (이 scope에서 필요)
                        _base_charges = 1
                        _holder_bonus = _get_dashholder_count()
                        _amplification_bonus = get_runtime_skill_bonus("dash_amplification")
                        _max_charges = int(_base_charges + _holder_bonus + _amplification_bonus)
                        if new_charges >= _max_charges:
                            _all_tokens_full_sparkle_timer = _ALL_TOKENS_FULL_SPARKLE_DURATION
                            # print(f"[DEBUG] 완충(스턴)! 타이머 설정: {_ALL_TOKENS_FULL_SPARKLE_DURATION}, new_charges={new_charges}, max={_max_charges}")
                        # 대쉬 토큰 충전 완료 효과음 재생
                        play_dash_charge_sound()
                    _charging_state["index"] = -1
                    # 다음 토큰 충전 즉시 시작 (스턴 중에도 연속 충전 지원)
                    _next_idx_stun = -1
                    for _tidx in range(len(token_states)):
                        if not token_states[_tidx]:
                            _next_idx_stun = _tidx
                            break
                    if _next_idx_stun >= 0:
                        # 충전 시간 계산
                        _stun_cd_bonus = get_runtime_skill_bonus("dash_cooldown")
                        _stun_cd_reduction = int(_stun_cd_bonus * FPS)
                        _stun_base_cd = apply_spikeboots_cooldown(300)
                        _stun_new_timer = max(6, _stun_base_cd - _stun_cd_reduction)
                        _stun_lw_bonus = get_runtime_skill_bonus("dash_lightweight")
                        if _stun_lw_bonus > 0:
                            _stun_new_timer = max(6, int(_stun_new_timer * (1 - _stun_lw_bonus)))
                        # 부스트차징은 대쉬 사용 시에만 적용 (자동 연속 충전에서는 미적용)
                        _charging_state["timer"] = _stun_new_timer
                        _charging_state["max_time"] = _stun_new_timer
                        _charging_state["index"] = _next_idx_stun
                        # UI 상태도 업데이트
                        while len(_token_charge_states) <= _next_idx_stun:
                            _token_charge_states.append({"timer": 0, "max_time": _UI_CHARGE_MAX, "ratio": 1.0})
                        _stun_ui_ratio = _UI_CHARGE_MAX / _stun_new_timer if _stun_new_timer > 0 else 1.0
                        _token_charge_states[_next_idx_stun] = {"timer": _UI_CHARGE_MAX, "max_time": _UI_CHARGE_MAX, "ratio": _stun_ui_ratio}
            #  스턴이 끝나면 하프대쉬 플래그 리셋 및 연속 대쉬 카운터 리셋
            if _rolling_get("rolling_stun_timer") == 0:
                if 'half_dash_used_flag' in globals():
                    half_dash_used_flag = False
                # 스턴이 끝나면 연속 대쉬 카운터도 리셋 (후딜 시간 내에만 연속 대쉬 가능)
                if _rolling_get("rolling_consecutive_count") > 0:
                    _rolling_set("rolling_consecutive_count", 0)
                # 튜토리얼: 하프대쉬 스턴 종료 시 pending 리셋
                if current_stage == 50 and tutorial_dash_counter_active:
                    if tutorial_half_dash_pending:
                        tutorial_half_dash_pending = False
                        if DEBUG_TUTORIAL:
                            pass  # print(f"튜토리얼: 하프대쉬 스턴 종료 - 공 충돌 없어서 카운팅 안함")
            # 통제 불가능 중에는 조작 불가
            if not gravitybelt_obtained:
                # 무중력벨트가 없을 때만 감속 적용
                if current_speed > 0:
                    current_speed -= DECELERATION * 2  # 빠른 감속
                elif current_speed < 0:
                    current_speed += DECELERATION * 2
            #  토큰이 2개 이상 있을 때 후딜 상태에서도 추가 대쉬 가능 (대쉬홀더 또는 증폭 스킬)
            #  하프대쉬 사용 시 연속 대쉬 금지
            base_charges = 1  # 기본 1개
            holder_bonus = _get_dashholder_count()  # 대쉬홀더 +1개
            amplification_bonus = get_runtime_skill_bonus("dash_amplification")
            max_charges = int(base_charges + holder_bonus + amplification_bonus)
            # 하프대쉬를 사용한 경우 연속 대쉬를 차단
            half_dash_used_in_sequence = 'half_dash_used_flag' in globals() and half_dash_used_flag
            # token_states에서 실제 토큰 수 계산 (동기화 문제 방지)
            rolling_charges_value = sum(1 for s in token_states if s) if 'token_states' in globals() else _rolling_get("rolling_charges")
            # 연속대쉬 시간 조건: 대쉬 시작 후 0.3초 경과해야 연속대쉬 가능 (도약 스킬 유무와 무관하게 동일 타이밍)
            _stun_elapsed_ms = pygame.time.get_ticks() - _dash_start_time
            if max_charges > 1 and rolling_charges_value > 0 and not half_dash_used_in_sequence and _stun_elapsed_ms >= CONSECUTIVE_DASH_START_DELAY_MS:
                #  연속 대쉬 할인을 고려한 실제 게이지 요구량 계산
                base_gauge_cost = 140  # 대시 기본 비용: 160 → 140
                
                #  악마의 주사위 대쉬 비용 배율 적용
                from item_effects.devil_dice import get_devil_dice_multipliers, is_devil_dice_active
                if is_devil_dice_active():
                    multipliers = get_devil_dice_multipliers()
                    base_gauge_cost = int(base_gauge_cost * multipliers['dash_cost'])
                
                # 대시 실행 시 rolling_consecutive_count가 1 증가하므로 미리 계산
                current_consecutive = get_roll("rolling_consecutive_count")
                next_consecutive_count = current_consecutive + 1
                consecutive_discount = 0.5 ** (next_consecutive_count - 1)  # 실제 대시에서 사용할 할인율
                discounted_cost = int(base_gauge_cost * consecutive_discount)
                if selected_character_type == "optimus":
                    discounted_cost = int(discounted_cost * 0.2)  # 80% 할인
                battery_bonus = get_runtime_skill_bonus("dash_battery_pack")
                required_gauge = max(10, int(discounted_cost * (1 - battery_bonus)))  # 실제 필요 게이지

                # 천사의 가호 대쉬 비용 버프 적용 (dash_manager._GLOBAL_DASH_INST 직접 참조)
                dm_inst = dash_manager._GLOBAL_DASH_INST
                if dm_inst is not None:
                    external_cost_mul = getattr(dm_inst, 'external_cost_multiplier', 1.0)
                    if external_cost_mul != 1.0:
                        required_gauge = int(required_gauge * external_cost_mul)

                # 대쉬부스트 효과: 70% 할인 (활성화 시)
                if is_dash_boost_active():
                    required_gauge = int(required_gauge * get_dash_cost_multiplier())  # 0.3배 (70% 할인)

                # 좌/우는 컨트롤 스킴/IME 여부와 무관하게 인식 (스냅샷+이벤트+스캔코드)
                # 현재 방향키가 눌려 있고 ↓가 눌려 있으면 "방향+↓ 조합"으로 인정한다.
                left_before_down = (is_move_left_pressed(keys) or MOVE_EVENT_LEFT)
                right_before_down = (is_move_right_pressed(keys) or MOVE_EVENT_RIGHT)
                # token_states에서 실제 토큰 수 계산 (동기화 문제 방지)
                current_charges = sum(1 for s in token_states if s) if 'token_states' in globals() else get_roll("rolling_charges")

                if left_before_down and down_pressed and not dash_down_first_lock and current_charges > 0:
                    # 후딜 상태에서 왼쪽 대쉬 실행 (아래키 + 왼쪽키 필요)
                    # 연속대쉬는 키를 계속 누르고 있어도 발동됨 (백업본 0123 로직 복원)
                    _start_dash(-1)
                    is_half_dash_active = False  # 일반 대쉬이므로 하프대쉬 플래그 해제
                    half_dash_effect_timer = 0  # 타이머도 리셋
                    # 실전 튜토리얼: 대쉬 사용 시 콜백 (후딜 왼쪽 대쉬)
                    on_player_dash_for_tutorial(is_half_dash=False)
                    # 튜토리얼: 대쉬 시작 시 카운팅 플래그 리셋
                    if current_stage == 50 and 'tutorial_dash_already_counted' in globals():
                        tutorial_dash_already_counted = False
                    # 포세이돈의 삼지창 물결 효과 발동
                    try:
                        legendary_manager = get_legendary_manager()
                        if legendary_manager:
                            trident = legendary_manager.get_item("poseidon_trident")
                            if trident and trident.active:
                                # 대쉬 시에는 바로 발동하지 않고 플래그만 설정
                                poseidon_dash_pending = True
                                poseidon_dash_x = PLAYER.centerx
                                poseidon_dash_y = PLAYER.centery
                    except:
                        pass  # 전설 아이템 접근 실패 시 무시
                    #  가속화 스킬: 대쉬 시작 시 패들 사이즈 증가 및 섬광 효과
                    acceleration_bonus = get_runtime_skill_bonus("dash_acceleration")
                    if acceleration_bonus > 0:
                        acceleration_skill_level = int(acceleration_bonus * 10 / 7)  # 레벨 계산 (0.3 -> 1레벨)
                        acceleration_height_bonus = int(PADDLE_HEIGHT * acceleration_bonus)  # 추가 높이만 계산
                        # PLAYER.height는 수정하지 않음 (이미지 크기 유지)
                        acceleration_active = True
                        # 레이저 빔 효과는 draw_objects()에서 처리
                        acceleration_flash_particles.clear()  # 파티클 대신 레이저 빔 사용
                    #  대쉬 효과음 재생
                    play_dash_sound()
                    # 대쉬기어 효과: 대쉬 거리 증가 (롤 옵션 적용)
                    base_rolling_timer = apply_dashgear_distance(15.0)  # 기본 대쉬 시간
                    #  아카데미 스킬 효과 적용: 대쉬 거리 증가 (도약)
                    jump_bonus = get_runtime_skill_bonus("dash_jump")  # 도약: 대쉬거리 증가
                    total_distance_bonus = jump_bonus
                    base_rolling_timer *= (1 + total_distance_bonus)
                    # 스킬 효과 적용: 대쉬 거리 증가
                    skill_distance_boost = skill.apply_dash_distance_boost(base_rolling_timer)
                    # 👁 오딘의 눈: 변신 상태 대쉬 거리 50% 증가
                    skill_distance_boost *= _get_odin_dash_distance_mult()
                    set_roll("rolling_timer", int(skill_distance_boost))
                    # 연속대쉬 타이밍 계산을 위해 시작 시간 저장
                    globals()["_dash_start_time"] = pygame.time.get_ticks()
                    #  대쉬 스피릿 스킬: 확률적 레이저 생성
                    dash_spirit_chance = get_runtime_skill_bonus("dash_spirit")  # 레벨당 10%
                    if dash_spirit_chance > 0:
                        if random.random() < dash_spirit_chance:
                            actual_dash_distance = int(get_roll("rolling_timer") * 40 * 0.7)
                            dash_distance = int(actual_dash_distance * 0.5)
                            create_dash_spirit_laser(PLAYER.centerx, PLAYER.centery, -1, dash_distance)
                    #  토큰 사용 - token_states 먼저 업데이트 후 current_charges 동기화 (후딜 왼쪽 대쉬)
                    # 최대 토큰 수 계산 (먼저 계산해야 함)
                    base_charges = 1  # 기본 1개
                    holder_bonus = _get_dashholder_count()  # 대쉬홀더 +1개
                    amplification_bonus = get_runtime_skill_bonus("dash_amplification")
                    max_charges = int(base_charges + holder_bonus + amplification_bonus)
                    # 대쉬부스트 활성화 시 토큰 소모하지 않음
                    if not is_dash_unlimited():
                        # 오른쪽부터 토큰 소진 (token_states가 있을 때만)
                        if 'token_states' in globals() and len(token_states) > 0:
                            token_states_local = list(token_states)
                            for idx in range(min(len(token_states_local), max_charges) - 1, -1, -1):
                                if idx < len(token_states_local) and token_states_local[idx]:
                                    token_states_local[idx] = False
                                    break
                            token_states[:] = token_states_local
                            if rolling_state is not None:
                                rolling_state.token_states = list(token_states_local)
                        else:
                            token_states = [True] * max(0, current_charges - 1) + [False] * (max_charges - max(0, current_charges - 1))
                            if rolling_state is not None:
                                rolling_state.token_states = list(token_states)
                        # token_states에서 current_charges 동기화 (핵심!)
                        current_charges = sum(1 for s in token_states if s)
                        set_roll("rolling_charges", current_charges)
                        _rolling_set("rolling_charges", current_charges)
                        # 전역 변수도 직접 업데이트 (지역 변수 shadowing 방지)
                        globals()["rolling_charges"] = current_charges
                    # 아카데미 스킬 효과: 쿨타임 감소
                    dash_cooldown_bonus = get_runtime_skill_bonus("dash_cooldown")
                    cooldown_reduction = int(dash_cooldown_bonus * FPS)  # 초 단위를 프레임으로 변환
                    # 모든 토큰에 동일한 쿨타임 적용 (일관성 - 캐릭터 대쉬쿨타임 능력치 기준)
                    base_cooldown = 300  # 5초 (300프레임) - 기본 대쉬 쿨타임
                    # 스파이크부츠 효과: 쿨타임 감소 (롤 옵션 적용)
                    base_cooldown = apply_spikeboots_cooldown(base_cooldown)
                    base_timer = max(6, base_cooldown - cooldown_reduction)  # 최소 0.1초
                    # 경량화 스킬 효과 적용
                    lightweight_bonus = get_runtime_skill_bonus("dash_lightweight")
                    if lightweight_bonus > 0:
                        base_timer = int(base_timer * (1 - lightweight_bonus))
                        base_timer = max(6, base_timer)

                    #  악마의 주사위 대쉬 쿨타임 배율 적용
                    from item_effects.devil_dice import get_devil_dice_multipliers, is_devil_dice_active
                    if is_devil_dice_active():
                        multipliers = get_devil_dice_multipliers()
                        base_timer = int(base_timer * multipliers['dash_cooldown'])

