                                    if rolling_state is not None:
                                        rolling_state.token_states = list(token_states)

                                    # 충전 완료 플래시 효과 트리거
                                    while len(_token_flash_timers) <= _next_charge_idx:
                                        _token_flash_timers.append(0)
                                    _token_flash_timers[_next_charge_idx] = _TOKEN_FLASH_DURATION

                                    # UI 상태도 충전 완료로 설정
                                    if _next_charge_idx < len(_token_charge_states):
                                        _token_charge_states[_next_charge_idx] = {
                                            "timer": 0,
                                            "max_time": _UI_CHARGE_MAX,
                                            "ratio": 1.0,
                                            "boost_charging": False
                                        }

                                    # 충전 완료 사운드
