def try_trigger_foul_whistle(loss_type: str) -> bool:
    """반칙호루라기 발동을 시도하고 성공 여부를 반환."""

    global round_losses, deuce_losses, foul_whistle_pending_round_reset, ball_vel

    try:
        from item_effects.foul_whistle import get_foul_whistle_instance

        whistle = get_foul_whistle_instance()
    except Exception as exc:
        print(f"[WARN] 반칙호루라기 인스턴스 준비 실패: {exc}")
        return False

    if not whistle.try_trigger():
        return False

    try:
        if SOUND_FOUL_WHISTLE:
            play_sound_with_volume(SOUND_FOUL_WHISTLE, sfx_volume)
    except Exception as exc:
        print(f"[WARN] 반칙호루라기 사운드 재생 실패: {exc}")

    if loss_type == "deuce":
        deuce_losses = max(0, deuce_losses - 1)
    else:
        round_losses = max(0, round_losses - 1)
        game_state.round_losses = round_losses

    foul_whistle_pending_round_reset = True

    try:
        ball_vel[0] = 0
        ball_vel[1] = 0
    except Exception:
        pass

    try:
        BALL.centerx = WIDTH // 2
        BALL.centery = HEIGHT // 2
    except Exception:
        pass

    # print("📢 심판이 무효를 선언합니다! 라운드가 다시 시작됩니다.")
    return True
def store_active_item(item_data):
    global active_item_slot, selected_item_index, aipill_active, last_item_use_time, long_boost_active
    # Aipill 활성화 시에는 아이템 획득 불가
    if aipill_active:
        return
    # long_boost가 이미 활성화되어 있으면 long_boost 아이템 획득 불가
    if item_data["name"] == "long_boost" and long_boost_active:
        # print("!")
        return
    if item_data["name"] == "fire_support" and selected_character_type != "soldier":
        # 화력지원은 군인 전용 화기이므로 다른 캐릭터는 획득하지 않는다.
        return
    # 패시브 아이템들은 엑티브 슬롯에 추가하지 않음
    if item_data["name"] in ["speedboots", "speedgear", "battery", "slot_add", "revival", "master", "cooltime", "chargebag", "spikeboots", "dashgear", "bulkup", "sensor", "dashholder", "gravitybelt", "dowsing_pendulum", "technical_vest", "commando_arm", "fuel_pouch", "bluetooth_ring", "foul_whistle", "star_detector", "smartphone", "knee_pads", "ragnarok_hammer", "hermes_shoes", "poseidon_trident", "bulletproof_hat", "spiked_helmet", "angel_blessing", "sacred_laurel", "zeus_lightning", "hades_helm", "gold_bar", "gold_digger", "transcendent_crown", "odins_eye", "pandora_legacy", "hero_seal", "lucky_coin", "adversity_armor", "shrapnel_armor", "soul_burst", "sage_ring", "venom_mist_gauntlet"]:
        return
    allow_overflow = item_data.pop("allow_overflow", False)
    is_overflow_pickup = len(item_state_adapter.active_items()) >= get_effective_max_item_slots()
    if is_overflow_pickup and not allow_overflow:
        return

    # 모든 액티브 아이템에 대해 아이콘 설정 (아이템 관리창과 동일한 아이콘 사용)
    if "icon" not in item_data or item_data["icon"] is None:
        item_data["icon"] = get_item_icon(item_data["name"])

    if "icon_animation_frames" not in item_data:
        animation_frames = items.get_item_icon_animation(item_data["name"])
        if animation_frames:
            item_data["icon_animation_frames"] = animation_frames
            item_data.setdefault("icon_animation_speed", 6)

    # 아이템에 last_use 필드 추가 (전역 쿨타임 적용)
    current_time = pygame.time.get_ticks()
    item_data["last_use"] = last_item_use_time
    item_data["temporary_overflow"] = is_overflow_pickup

    item_state_adapter.append_active_item(item_data)
    _set_selected_item_index(len(item_state_adapter.active_items()) - 1)

    # 아이템 획득 효과 표시 (아이템 위치에서) - 옛날 버전 활성화
    show_item_obtained_effect(item_data, item_data.get("x"), item_data.get("y"))

    # 튜토리얼: 아이템 획득 체크
    on_item_collect_for_tutorial(item_data)


def store_arena_top_active_item(item_data):
    """투기장 상단 영웅 전용 액티브 아이템 저장 함수"""
    global arena_top_active_item_slot, arena_top_selected_item_index, arena_top_last_item_use_time

    # 투기장 모드가 아니면 무시
    if not arena_mode_enabled:
        return

    # 패시브 아이템들은 상단 영웅 슬롯에 추가하지 않음 (액티브 아이템만)
    if item_data["name"] in ["speedboots", "speedgear", "battery", "slot_add", "revival", "master", "cooltime", "chargebag", "spikeboots", "dashgear", "bulkup", "sensor", "dashholder", "gravitybelt", "dowsing_pendulum", "technical_vest", "commando_arm", "fuel_pouch", "bluetooth_ring", "foul_whistle", "star_detector", "smartphone", "knee_pads", "ragnarok_hammer", "hermes_shoes", "poseidon_trident", "bulletproof_hat", "spiked_helmet", "angel_blessing", "sacred_laurel", "zeus_lightning", "hades_helm", "gold_bar", "gold_digger", "transcendent_crown", "odins_eye", "pandora_legacy", "hero_seal", "lucky_coin", "adversity_armor", "shrapnel_armor", "soul_burst", "sage_ring", "venom_mist_gauntlet"]:
        return

    # 최대 3개까지만 보관
    if len(arena_top_active_item_slot) >= 3:
        return

    # 아이콘 설정
    if "icon" not in item_data or item_data["icon"] is None:
        item_data["icon"] = get_item_icon(item_data["name"])

    if "icon_animation_frames" not in item_data:
        animation_frames = items.get_item_icon_animation(item_data["name"])
        if animation_frames:
            item_data["icon_animation_frames"] = animation_frames
            item_data.setdefault("icon_animation_speed", 6)

    # 아이템에 last_use 필드 추가
    current_time = pygame.time.get_ticks()
    item_data["last_use"] = arena_top_last_item_use_time
    item_data["is_top_hero"] = True  # 상단 영웅용 아이템 표시

    arena_top_active_item_slot.append(item_data)
    arena_top_selected_item_index = len(arena_top_active_item_slot) - 1

    # 아이템 획득 효과 표시
    show_item_obtained_effect(item_data, item_data.get("x"), item_data.get("y"))


def _arena_top_hero_collect_items():
    """투기장 상단 영웅(BOSS 패들)이 아이템을 획득하는 로직"""
    global arena_top_active_item_slot

    if not arena_mode_enabled:
        return

    # 상단 영웅 아이템 슬롯이 가득 찼으면 획득하지 않음
    if len(arena_top_active_item_slot) >= 3:
        return

    # BOSS 패들 rect
    boss_rect = BOSS

    # 아이템 리스트 순회 (역순으로 순회하여 제거 시 인덱스 문제 방지)
    items_to_remove = []
    for i, item in enumerate(items.item_list):
        # 아이템 rect 생성
        item_rect = pygame.Rect(item["x"] - 15, item["y"] - 15, 30, 30)

        # BOSS 패들과 충돌 체크
        if item_rect.colliderect(boss_rect):
            # 아이템 타입 확인
            item_type_data = item.get("type")
            if isinstance(item_type_data, dict):
                item_name = item_type_data.get("name", "")
                item_color = item_type_data.get("color", (200, 200, 200))
            else:
                item_name = item.get("name", "")
                item_color = item.get("color", (200, 200, 200))

            # 패시브 아이템은 상단 영웅이 획득하지 않음 (액티브만)
            passive_items = ["speedboots", "speedgear", "battery", "slot_add", "revival", "master", "cooltime", "chargebag", "spikeboots", "dashgear", "sensor", "bulkup", "dashholder", "gravitybelt", "dowsing_pendulum", "commando_arm", "technical_vest", "fuel_pouch", "bluetooth_ring", "star_detector", "foul_whistle", "smartphone", "knee_pads", "ragnarok_hammer", "hermes_shoes", "poseidon_trident", "angel_blessing", "sacred_laurel", "transcendent_crown", "odins_eye", "bulletproof_hat", "spiked_helmet", "gold_bar", "gold_digger", "soul_burst"]
            if item_name in passive_items:
                continue  # 패시브 아이템은 하단 영웅에게 양보

            # 액티브 아이템 획득
            item_data = {
                "name": item_name,
                "color": item_color,
                "effect": item_name,
                "icon": None,
                "x": item["x"],
                "y": item["y"]
            }
            store_arena_top_active_item(item_data)

            # 아이템 획득 사운드
            try:
                if SOUND_ITEM_GET:
                    SOUND_ITEM_GET.play()
            except Exception:
                pass

            items_to_remove.append(i)

            # 슬롯 다 찼으면 중단
            if len(arena_top_active_item_slot) >= 3:
                break

    # 획득한 아이템 제거 (역순으로)
    for i in sorted(items_to_remove, reverse=True):
        if i < len(items.item_list):
            items.item_list.pop(i)


# 투기장 상단 영웅 투사체 리스트
arena_top_grenades = []  # 상단 영웅이 던진 수류탄
arena_top_bananas = []   # 상단 영웅이 던진 바나나


def _apply_arena_top_item_effect(effect_name):
    """투기장 상단 영웅용 아이템 효과 적용 (투사체는 아래로 향함)"""
    global arena_top_grenades, arena_top_bananas, walls

    # 투척형 아이템: BOSS → PLAYER 방향으로 투사체 발사 (수류탄 시스템 활용)
    throwing_items = {"grenade", "molotov", "flare", "smoke_grenade", "dynamite", "spider_mine"}

    if effect_name in throwing_items:
        target_x = PLAYER.centerx + random.uniform(-50, 50)
        target_y = PLAYER.centery

        dx = target_x - BOSS.centerx
        dy = target_y - BOSS.centery
        distance = math.sqrt(dx**2 + dy**2)
        speed = 10
        vel_x = (dx / distance) * speed if distance > 0 else 0
        vel_y = (dy / distance) * speed if distance > 0 else speed

        # 발사 오차 적용
        angle_offset = random.uniform(-10, 10)
        angle_rad = math.radians(angle_offset)
        cos_a = math.cos(angle_rad)
        sin_a = math.sin(angle_rad)
        new_vel_x = vel_x * cos_a - vel_y * sin_a
        new_vel_y = vel_x * sin_a + vel_y * cos_a

        grenade = {
            "x": float(BOSS.centerx),
            "y": float(BOSS.centery + 20),  # 패들 아래에서 시작
            "vel_x": new_vel_x,
            "vel_y": new_vel_y,
            "timer": 90,  # 1.5초 후 폭발
            "exploded": False,
            "is_from_top": True,
            "projectile_type": effect_name  # 투사체 종류 구분 (색상/이펙트용)
        }
        arena_top_grenades.append(grenade)

        # 효과음
        try:
            if SOUND_THROW_BEFORE:
                SOUND_THROW_BEFORE.play()
        except Exception:
            pass

    elif effect_name == "banana":
        # 상단 영웅 바나나: BOSS 위치에서 아래로 던짐
        target_x = PLAYER.centerx + random.uniform(-80, 80)
        target_y = HEIGHT - 100  # 화면 하단 근처

        dx = target_x - BOSS.centerx
        dy = target_y - BOSS.centery
        distance = math.sqrt(dx**2 + dy**2)
        speed = 8
        vel_x = (dx / distance) * speed if distance > 0 else 0
        vel_y = (dy / distance) * speed if distance > 0 else speed

        banana = {
            "x": float(BOSS.centerx),
            "y": float(BOSS.centery + 20),
            "vel_x": vel_x,
            "vel_y": vel_y,
            "rotation": 0,
            "landed": False,
            "slip_timer": 0,
            "is_from_top": True
        }
        arena_top_bananas.append(banana)

    elif effect_name == "wall":
        # 상단 영웅 벽돌: BOSS 패들 아래(상단 진영)에 직접 설치
        try:
            wall_width = 80
            wall_height = 20
            wall_x = BOSS.centerx - wall_width // 2
            wall_y = BOSS.bottom + 10  # BOSS 패들 바로 아래
            wall_rect = pygame.Rect(wall_x, wall_y, wall_width, wall_height)
            walls.append({
                "rect": wall_rect,
                "hit_count": 0,
                "crack_level": 0,
            })
            play_active_item_sound()
        except Exception:
            pass

    elif effect_name == "stopwatch":
        # 스탑워치: 공 속도 감소 효과
        try:
            activate_stopwatch()
        except Exception:
            pass

    elif effect_name == "pandora_box":
        # 판도라 상자: 랜덤 효과
        try:
            activate_pandora_box()
        except Exception:
            pass

    elif effect_name in ["gauge_boost", "gauge_charge"]:
        # 게이지 아이템은 상단 영웅에게 의미 없음 - 소비만
        pass

    elif effect_name == "holy_barrier":
        # 상단 영웅 홀리베리어: 화면 하단 배리어 생성
        try:
            activate_holy_barrier(None, current_stage, WIDTH, HEIGHT)
        except Exception:
            pass

    elif effect_name == "magnet_field":
        # 상단 영웅 자기장 발생기: 공 끌어당기기
        try:
            activate_magnet_field(None, current_stage, WIDTH, HEIGHT)
        except Exception:
            pass

    elif effect_name == "boomerang":
        # 상단 영웅 부메랑: 보스 넉백+스턴
        try:
            activate_boomerang(None, current_stage, WIDTH, HEIGHT,
                              player_x=PLAYER.centerx, player_y=PLAYER.centery)
        except Exception:
            pass

    elif effect_name in ["long_paddle", "long_boost"]:
        # 상단 영웅 거대화포션: 패들 확장 효과 발동
        try:
            activate_long_boost()
        except Exception:
            pass

    elif effect_name == "vitamin_pill":
        # 상단 영웅 비타민약: 이동속도 증가 효과 발동
        try:
            activate_vitamin_pill()
        except Exception:
            pass

    elif effect_name in ["aipill", "life_elixir", "repair_kit", "regeneration_potion", "devil_dice"]:
        # 유틸리티 아이템: 상단 영웅에게 의미 없음 - 소비만
        pass

    else:
        # 기타 아이템 소비
        pass


def _update_arena_top_projectiles():
    """투기장 상단 영웅 투사체 업데이트"""
    global arena_top_grenades, arena_top_bananas
    global player_stunned_timer, player_knockback_vel

    # 상단 영웅 수류탄 업데이트
    new_grenades = []
    for grenade in arena_top_grenades:
        if grenade["exploded"]:
            continue

        # 이동
        grenade["x"] += grenade["vel_x"]
        grenade["y"] += grenade["vel_y"]

        # 중력 적용
        grenade["vel_y"] += 0.3

        # 타이머 감소
        grenade["timer"] -= 1

        # 화면 밖으로 나가면 제거
        if grenade["y"] > HEIGHT + 50 or grenade["y"] < -50:
            continue
        if grenade["x"] < GAME_AREA_OFFSET_X - 50 or grenade["x"] > GAME_AREA_OFFSET_X + GAME_PLAY_WIDTH + 50:
            continue

        # 타이머 종료 또는 플레이어와 충돌 시 폭발
        grenade_rect = pygame.Rect(grenade["x"] - 10, grenade["y"] - 10, 20, 20)
        if grenade["timer"] <= 0 or grenade_rect.colliderect(PLAYER):
            # 폭발 처리
            grenade["exploded"] = True
            explosion_x, explosion_y = grenade["x"], grenade["y"]

            # 플레이어와의 거리 계산
            dist = math.sqrt((PLAYER.centerx - explosion_x)**2 + (PLAYER.centery - explosion_y)**2)

            if dist < 100:  # 폭발 범위 내
                # 스턴 적용
                player_stunned_timer = 45  # 0.75초 스턴

                # 넉백 적용
                knockback_dir = 1 if PLAYER.centerx > explosion_x else -1
                player_knockback_vel = knockback_dir * 15

            # 폭발 이펙트 (source="arena_top"으로 보스 스턴 방지, 시각 효과만)
            try:
                trigger_grenade_style_explosion(
                    int(explosion_x), int(explosion_y),
                    apply_commando_bonus=False,
                    source="arena_top",
                    radius_scale=0.8,
                )
            except Exception:
                pass

            continue

        new_grenades.append(grenade)

    arena_top_grenades = new_grenades

    # 상단 영웅 바나나 업데이트
    new_bananas = []
    for banana in arena_top_bananas:
        if banana["landed"]:
            # 바닥에 있는 바나나
            banana["slip_timer"] -= 1
            if banana["slip_timer"] <= 0:
                continue  # 제거

            # 플레이어와 충돌 체크
            banana_rect = pygame.Rect(banana["x"] - 15, banana["y"] - 15, 30, 30)
            if banana_rect.colliderect(PLAYER):
                # 미끄러짐 효과
                player_knockback_vel = random.choice([-20, 20])
                continue  # 바나나 제거

            new_bananas.append(banana)
        else:
            # 날아가는 바나나
            banana["x"] += banana["vel_x"]
            banana["y"] += banana["vel_y"]
            banana["rotation"] += 15  # 회전

            # 중력 적용
            banana["vel_y"] += 0.2

            # 화면 밖으로 나가면 제거
            if banana["y"] > HEIGHT + 50:
                continue

            # 바닥에 닿으면 착지
            if banana["y"] >= HEIGHT - 80:
                banana["landed"] = True
                banana["slip_timer"] = 300  # 5초 동안 유지
                banana["y"] = HEIGHT - 80

            new_bananas.append(banana)

    arena_top_bananas = new_bananas


def _draw_arena_top_projectiles(screen):
    """투기장 상단 영웅 투사체 그리기"""
    # 투사체 색상 매핑 (외곽, 내부)
    _projectile_colors = {
        "grenade": ((180, 50, 50), (255, 100, 100)),
        "molotov": ((255, 120, 0), (255, 180, 50)),
        "flare": ((255, 255, 100), (255, 255, 220)),
        "smoke_grenade": ((120, 120, 120), (180, 180, 180)),
        "dynamite": ((200, 50, 50), (255, 80, 80)),
        "spider_mine": ((120, 90, 160), (180, 140, 220)),
    }

    # 수류탄/투척형 투사체 그리기
    for grenade in arena_top_grenades:
        if not grenade["exploded"]:
            ptype = grenade.get("projectile_type", "grenade")
            outer, inner = _projectile_colors.get(ptype, ((180, 50, 50), (255, 100, 100)))
            gx, gy = int(grenade["x"]), int(grenade["y"])
            pygame.draw.circle(screen, outer, (gx, gy), 8)
            pygame.draw.circle(screen, inner, (gx, gy), 5)
            # 화염병/조명탄은 추가 이펙트 (꼬리)
            if ptype == "molotov":
                pygame.draw.circle(screen, (255, 200, 50), (gx - int(grenade["vel_x"] * 0.3), gy - int(grenade["vel_y"] * 0.3)), 4)
            elif ptype == "flare":
                pygame.draw.circle(screen, (255, 255, 180), (gx, gy), 12)
                pygame.draw.circle(screen, (255, 255, 255), (gx, gy), 6)

    # 바나나 그리기
    for banana in arena_top_bananas:
        x, y = int(banana["x"]), int(banana["y"])
        # 간단한 바나나 모양 (노란 타원)
        if not banana["landed"]:
            # 회전하는 바나나
            angle = banana["rotation"]
            surf = pygame.Surface((30, 15), pygame.SRCALPHA)
            pygame.draw.ellipse(surf, (255, 220, 50), (0, 0, 30, 15))
            rotated = pygame.transform.rotate(surf, angle)
            rect = rotated.get_rect(center=(x, y))
            screen.blit(rotated, rect)
        else:
            # 바닥에 있는 바나나
            pygame.draw.ellipse(screen, (255, 220, 50), (x - 15, y - 7, 30, 15))


# bosspong.py
def store_passive_item(item_data):
    global MAX_ITEM_SLOTS, passive_item_list, speedboots_obtained, speedgear_obtained
    global items, aipill_active, battery_obtained, revival_obtained, master_obtained, cooltime_obtained, chargebag_obtained, spikeboots_obtained, dashgear_obtained, bulkup_obtained
    global danger_sensor_obtained, sensor_obtained, danger_sensor_enabled, sensor_enabled, danger_sensor_auto_dash_enabled  # 센서 관련 변수들
    global dashholder_obtained  # 대쉬홀더 관련 변수
    global gravitybelt_obtained  # 무중력벨트 관련 변수
    global hermes_shoes_obtained  # 헤르메스의 신발 관련 변수
    global player_ai_enabled
    # 누락된 type 필드를 방어적으로 보정
    skip_append = False

    if "type" not in item_data or not item_data.get("type"):
        item_data["type"] = "passive"
    ensure_passive_rolls(item_data)
    apply_roll_bonuses_from_item(item_data)
    # Aipill 활성화 시에는 아이템 획득 불가
    if aipill_active:
        # print("Aipill     .")
        return
    
    # 모든 패시브 아이템에 대해 아이콘 설정 (아이템 관리창과 동일한 아이콘 사용)
    if "icon" not in item_data or item_data["icon"] is None:
        item_data["icon"] = get_item_icon(item_data["name"])

    if "icon_animation_frames" not in item_data:
        animation_frames = items.get_item_icon_animation(item_data["name"])
        if animation_frames:
            item_data["icon_animation_frames"] = animation_frames
            item_data.setdefault("icon_animation_speed", 6)
    # 패시브 옵션 롤링(해당 아이템에만)
    if item_data["type"] == "passive":
        ensure_passive_rolls(item_data)

    # 아이콘을 변수로 저장 (show_item_acquisition에서 사용)
    item_icon = item_data.get("icon")
    
    if item_data["name"] == "slot_add":
        # 최대 슬롯 5개 제한 (기본 3개 + 배낭 2개) - 배낭 1개당 +2칸
        _set_max_item_slots(min(5, MAX_ITEM_SLOTS + 2))
        # print("액티브 슬롯 +2 !")
        # 획득 개수 카운트 증가
        items.slot_add_obtained += 1
    elif item_data["name"] == "speedboots":
        # 스피드부츠 영구 효과 적용
        if not speedboots_obtained:
            speedboots_obtained = True
            items.speedboots_obtained = True  # items.py의 변수도 업데이트
            # 롤 옵션 반영 (이동속도 +4~8%)
            apply_roll_bonuses_from_item(item_data)
            # ️ 새 시스템으로도 업데이트
            handle_item_collection("speedboots")
            # print("!   6% !")
        else:
            pass  # print("이미 스피드부츠를 보유 중입니다.")
    elif item_data["name"] == "speedgear":
        # 스피드기어 영구 효과 적용
        if not speedgear_obtained:
            speedgear_obtained = True
            items.speedgear_obtained = True  # items.py의 변수도 업데이트
            # ️ 새 시스템으로도 업데이트
