def activate_emotional_overdrive():
    global emotional_overdrive_active, emotional_overdrive_timer
    global overdrive_flash_timer, overdrive_trails
    emotional_overdrive_active = True
    # 광폭화 시 사이코볼 지속시간 7.5초 (일반: 5초)
    if enraged_boss_active:
        emotional_overdrive_timer = 450  # 7.5초 (60fps * 7.5)
    else:
        emotional_overdrive_timer = 300  # 5초 (60fps * 5)
    overdrive_flash_timer = HALF_SECOND_FRAMES  # 0.5초마다 반짝임
    overdrive_trails.clear()
    
    # 사이코볼 사운드 재생 (루프)
    try:
        psycho_sound = pygame.mixer.Sound(resource_path("sounds/psychoball.wav"))
        channel = psycho_sound.play(-1)  # -1 = 무한 루프
        channel.set_volume(0.5)
        # 채널을 저장해서 나중에 중지할 수 있도록
        globals()['psycho_sound_channel'] = channel
    except:
        pass  # print(": sounds/psychoball.wav")
def handle_emotional_overdrive():
    global emotional_overdrive_active, emotional_overdrive_timer
    global overdrive_flash_timer, overdrive_trails, ball_vel
    global psycho_bg_timer  #  배경 깜빡임 타이머
    global smoke_zones, BALL  # 연막탄 체크용
    if not emotional_overdrive_active:
        return
    
    #  Stage 3: 연막탄 연기에 공이 닿으면 사이코볼 강제 종료
    if current_stage == 3:
        for smoke_zone in smoke_zones:
            if smoke_zone["opacity"] > 50:  # 연막이 충분히 진할 때만
                # 공과 연막 중심 사이의 타원형 거리 계산
                dx = BALL.centerx - smoke_zone["x"]
                dy = BALL.centery - smoke_zone["y"]
                radius_x = smoke_zone.get("radius_x", smoke_zone["radius"])
                radius_y = smoke_zone["radius"]
                # 타원 방정식: (x/a)^2 + (y/b)^2 <= 1
                if radius_x > 0 and radius_y > 0:
                    ellipse_distance = (dx / radius_x) ** 2 + (dy / radius_y) ** 2
                else:
                    ellipse_distance = float('inf')
                if ellipse_distance <= 1:
                    # 사이코볼 즉시 종료
                    # print("!")
                    emotional_overdrive_active = False
                    emotional_overdrive_timer = 0
                    overdrive_trails.clear()
                    psycho_bg_timer = 0
                    
                    # 사이코볼 사운드 중지
                    if 'psycho_sound_channel' in globals() and psycho_sound_channel:
                        psycho_sound_channel.stop()
                    
                    # 공을 보스 방향으로 보내기
                    # 보스 패들 중심 위치 계산
                    boss_center_x = BOSS.centerx if BOSS else WIDTH // 2
                    boss_center_y = BOSS.centery if BOSS else 100
                    
                    # 공에서 보스로의 방향 벡터 계산
                    dx = boss_center_x - BALL.centerx
                    dy = boss_center_y - BALL.centery
                    distance = math.sqrt(dx**2 + dy**2)
                    
                    # 방향 정규화 후 적절한 속도 적용 (플레이어가 대응 가능한 수준)
                    if distance > 0:
                        ball_vel[0] = (dx / distance) * 10  # 속도 10으로 설정
                        ball_vel[1] = (dy / distance) * 10
                    else:
                        # 거리가 0이면 위로 발사
                        ball_vel[0] = 0
                        ball_vel[1] = -10
                    
                    # print(f"    ! : ({ball_vel[0]:.1f}, {ball_vel[1]:.1f})")
                    
                    # 무효화 시각 효과 - 보라색 파티클 폭발
                    for i in range(20):
                        angle = random.uniform(0, 2 * math.pi)
                        speed = random.uniform(2, 8)
                        particle = {
                            'x': BALL.centerx,
                            'y': BALL.centery,
                            'vx': math.cos(angle) * speed,
                            'vy': math.sin(angle) * speed,
                            'life': 30,
                            'color': (random.randint(150, 200), 0, random.randint(150, 255))  # 보라색 계열
                        }
                        if 'neutralize_particles' not in globals():
                            global neutralize_particles
                            neutralize_particles = []
                        neutralize_particles.append(particle)
                    
                    # 시각적/청각적 피드백
                    try:
                        # 연막 효과음 재생
                        smoke_sound = pygame.mixer.Sound(resource_path("sounds/smoke_neutralize.wav"))
                        smoke_sound.set_volume(0.7)
                        play_sound_with_volume(smoke_sound)
                    except:
                        # 효과음 없으면 기본 사운드
                        try:
                            play_paddle_sound()
                        except:
                            pass
                    return
    
    emotional_overdrive_timer -= 1
    if emotional_overdrive_timer <= 0:
        emotional_overdrive_active = False
        overdrive_trails.clear()
        psycho_bg_timer = 0  #  배경 깜빡임 타이머 초기화
        
        # 사이코볼 사운드 중지
        if 'psycho_sound_channel' in globals() and psycho_sound_channel:
            psycho_sound_channel.stop()
        
        return
    # 1. 공 곡선 이동
    time_now = pygame.time.get_ticks()
    curve = math.sin(time_now / 80) * 3
    ball_vel[0] += curve * random.uniform(0.5, 1.2)
    # 2. 공 순간이동 (랜덤 확률)
    if random.random() < 0.01:
        BALL.centerx = random.randint(50, WIDTH - 50)
        BALL.centery = random.randint(150, HEIGHT - 150)
    # 3. 보스 잔상 추가
    overdrive_trails.append((BOSS.centerx, BOSS.centery, 200))
    overdrive_trails = [(x, y, a - 10) for x, y, a in overdrive_trails if a > 10][:15]
    # 4. 보스 반짝임 타이머
    overdrive_flash_timer -= 1
    if overdrive_flash_timer <= 0:
        overdrive_flash_timer = HALF_SECOND_FRAMES
    # 5. 배경 깜빡임 타이머 증가 (draw_field에서 사용됨)
    psycho_bg_timer += 1
