def is_point_in_smoke(x, y, opacity_threshold=50):
    """지정 좌표가 활성 연막 안에 있는지 여부를 반환한다."""
    global smoke_zones

    for smoke_zone in smoke_zones:
        if smoke_zone.get("opacity", 0) > opacity_threshold:
            radius_x = smoke_zone.get("radius_x", smoke_zone.get("radius", 0))
            radius_y = smoke_zone.get("radius", 0)
            if radius_x > 0 and radius_y > 0:
                dx = x - smoke_zone["x"]
                dy = y - smoke_zone["y"]
                if (dx / radius_x) ** 2 + (dy / radius_y) ** 2 <= 1:
                    return True
    return False


def is_rect_in_smoke(rect, opacity_threshold=50):
    """사각형의 주요 지점이 연막 안에 있는지 검사한다."""
    if rect is None:
        return False

    key_points = (
        rect.center,
        rect.midtop,
        rect.midbottom,
        rect.midleft,
        rect.midright,
        rect.topleft,
        rect.topright,
        rect.bottomleft,
        rect.bottomright,
    )

    for px, py in key_points:
        if is_point_in_smoke(px, py, opacity_threshold=opacity_threshold):
            return True
    return False


def is_player_in_smoke():
    """플레이어가 연막 안에 있는지 확인하는 함수"""
    global PLAYER

    if is_point_in_smoke(PLAYER.centerx, PLAYER.centery):
        return True

    # 테크니컬조끼 연막 체크
    if check_technical_vest_smoke_collision(PLAYER.centerx, PLAYER.centery):
        return True

    return False


def destroy_stage2_rocks_in_smoke(smoke_zone):
    """스테이지 2에서 연막 내부의 바위를 파괴한다."""
    global current_stage, animated_bg_stage2, trade_point_system

    if current_stage != 2 or animated_bg_stage2 is None:
        return

    if smoke_zone.get("opacity", 0) <= 50:
        return

    radius_y = smoke_zone.get("radius", 0)
    radius_x = smoke_zone.get("radius_x", radius_y)
    if radius_x <= 0 or radius_y <= 0:
        return

    def _contains_point(px: float, py: float) -> bool:
        dx = px - smoke_zone["x"]
        dy = py - smoke_zone["y"]
        return (dx / radius_x) ** 2 + (dy / radius_y) ** 2 <= 1

    rocks_to_remove = []
    for rock in list(animated_bg_stage2.crisis_rocks):
        if rock.get("falling", False):
            continue

        rect = rock.get("collision_rect")
        if not rect:
            continue

        rock_points = (
            rect.center,
            rect.topleft,
            rect.topright,
            rect.bottomleft,
            rect.bottomright,
        )

        if not any(_contains_point(px, py) for px, py in rock_points):
            continue

        animated_bg_stage2.destroy_rock(rock)
        rocks_to_remove.append(rock)

        rock_size = rock.get("size", 0)

        try:
            if rock_size <= 45:
                play_sound_with_volume(SOUND_STONEBREAK_SMALL)
            elif rock_size <= 65:
                play_sound_with_volume(SOUND_STONEBREAK_MEDIUM)
            else:
                play_sound_with_volume(SOUND_STONEBREAK_LARGE)
        except Exception:
            pass

        if rock.get("is_golden", False):
            trade_point_system.spawn_star(rect.centerx, rect.centery, "golden_rock")
            try:
                coin_sound = pygame.mixer.Sound(resource_path("sounds/coin.wav"))
                play_sound_with_volume(coin_sound)
            except Exception:
                pass

        # print(f"💨 연막탄이 바위를 제거했습니다! 위치=({rect.centerx}, {rect.centery})")

    for rock in rocks_to_remove:
        if rock in animated_bg_stage2.crisis_rocks:
            animated_bg_stage2.crisis_rocks.remove(rock)


def destroy_stage7_tetrominoes_in_smoke(smoke_zone):
    """스테이지 7에서 연막 내부에 들어온 테트로미노를 즉시 분해(증발) 처리한다.
    - 연막 불투명도(opacity)가 충분할 때만 작동
    - 블럭 상태가 assembling/falling/installed 인 경우에만 트리거
    - 분해 연출은 대쉬/플레이어 파괴와 동일(셀 단위로 빠르게 증발)
    """
    try:
        if current_stage != 7:
            return
        # 전역 리스트가 없거나 비어있으면 종료
        if 'stage7_tetrominoes' not in globals() or not stage7_tetrominoes:
            return
    except Exception:
        return

    if smoke_zone.get("opacity", 0) <= 50:
        return

    radius_y = smoke_zone.get("radius", 0)
    radius_x = smoke_zone.get("radius_x", radius_y)
    if radius_x <= 0 or radius_y <= 0:
        return

    def _contains(px: float, py: float) -> bool:
        dx = px - smoke_zone["x"]
        dy = py - smoke_zone["y"]
        return (dx / radius_x) ** 2 + (dy / radius_y) ** 2 <= 1

    for mino in list(stage7_tetrominoes):
        state = mino.get("state")
        if state in ("evaporating", "destroying"):
            continue
        # 셀 중 하나라도 연막 타원에 들어가면 파괴
        touched = False
        for c in mino.get("cells", []):
            if c.get("evaporated", False):
                continue
            rect = c.get("rect")
            if not rect:
                continue
            # 주요 지점 샘플링(센터+4변 중점+4코너)
            points = (
                rect.center,
                rect.midtop,
                rect.midbottom,
                rect.midleft,
                rect.midright,
                rect.topleft,
                rect.topright,
                rect.bottomleft,
                rect.bottomright,
            )
            if any(_contains(px, py) for (px, py) in points):
                touched = True
                break
        if touched:
            # 연막 접촉으로 인한 즉시 증발 처리
            destroy_stage7_tetromino(mino, by_smoke=True)
def handle_wall():
    """벽돌 설치 및 관리 함수"""
    global walls, pending_wall, wall_installing, wall_install_timer, wall_install_gauge_visible
    global boss_stunned_timer, boss_knockback_vel, explosion_zones, grenades
    global boss_confused_timer, flares, flare_zones, last_hit_by
    global spider_mines, spider_mine_slow_active, spider_mine_slow_timer, spider_mine_slow_text_timer
    global boss_current_health, boss_max_health  #  체력형 보스 체력 변수
    global boss_fire_hit_count, boss_fire_hit_timer  #  보스 화염 타격 카운터
    global special_gauge, special_ready  # 게이지 관련 변수 추가
    # 설치 중인 경우
    if wall_installing:
        # 홀드 없이도, 캐릭터 불문하고 벽돌 설치 중에는 건설 사운드가 항상 재생되도록 처리
        # 다른 건설(포탑/디바인) 로직과의 충돌을 피하기 위해 start만 호출하고,
        # 설치 종료 시점에만 일시정지로 정리한다.
        try:
            start_blacksmith_construction_sound()
        except Exception:
            pass

        wall_install_timer -= 1
        if wall_install_timer <= 0:
            wall_install_timer = 0
            wall_installing = False
            wall_install_gauge_visible = False  # 설치 게이지 숨기기
            if pending_wall is not None:
                if isinstance(pending_wall, list):
                    walls.extend(pending_wall)
                else:
                    walls.append(pending_wall)
                pending_wall = None
            # print("!    .")
            # 설치 종료 시, 벽돌 트리거로 재생 중이던 건설 사운드는 정리(다른 건설이 없으면 정지됨)
            try:
                pause_blacksmith_construction_sound()
            except Exception:
                pass
    # 파괴된 벽돌들 제거 (부서지는 이펙트 생성)
    destroyed_walls = []
    for wall in walls:
        group_id = wall.get("group_id")
        # 일반 벽돌: 2타에 파괴, 보호형(그룹) 벽돌: 3타에 파괴
        if group_id is None and wall.get("hit_count", 0) >= 2:
            destroyed_walls.append(wall)
        elif group_id is not None and wall.get("hit_count", 0) >= 3:
            destroyed_walls.append(wall)

    for wall in destroyed_walls:
        # 벽돌 부서지는 파티클 이펙트 생성
        create_brick_destruction_effect(wall["rect"])
    walls = [wall for wall in walls if wall not in destroyed_walls]
    # 스파이더지뢰 이동 업데이트
    update_spider_mines()
    # 수류탄 업데이트
    global grenade_shake_timer, boss_stunned_timer, boss_knockback_vel, explosion_zones
    for grenade in grenades[:]:
        # 중력 적용
        if grenade["gravity"] > 0:
            grenade["vel_y"] += grenade["gravity"]
        grenade["x"] += grenade["vel_x"]
        grenade["y"] += grenade["vel_y"]
        grenade["rotation"] += 15  # 회전 (화염병보다 빠름)
        # 목표 지점에 도달했는지 체크
        if abs(grenade["x"] - grenade["target_x"]) < 30 and abs(grenade["y"] - grenade["target_y"]) < 30:
            trigger_grenade_style_explosion(
                grenade["x"],
                grenade["y"],
                apply_commando_bonus=True,
                source="grenade",
            )
            grenades.remove(grenade)
            continue
        # 화면 상단 벽(보스 뒷벽)에 도달하면 폭발
        if grenade["y"] <= 10:
            trigger_grenade_style_explosion(
                grenade["x"],
                10,  # 벽 위치에서 폭발
                apply_commando_bonus=True,
                source="grenade",
            )
            grenades.remove(grenade)
            continue
        # 좌우 벽 충돌 시 반사 (벽 뒤로 넘어가지 않도록)
        wall_margin = 10  # 벽 경계 여유
        if grenade["x"] <= wall_margin:
            grenade["x"] = wall_margin
            grenade["vel_x"] = abs(grenade["vel_x"]) * 0.7  # 오른쪽으로 반사, 속도 감쇠
            # 반사 후 보스 방향(위쪽)으로 속도 조정
            if grenade["vel_y"] > 0:  # 아래로 가고 있었다면
                grenade["vel_y"] = -abs(grenade["vel_y"]) * 0.5  # 위로 방향 전환
        elif grenade["x"] >= WIDTH - wall_margin:
            grenade["x"] = WIDTH - wall_margin
            grenade["vel_x"] = -abs(grenade["vel_x"]) * 0.7  # 왼쪽으로 반사, 속도 감쇠
            # 반사 후 보스 방향(위쪽)으로 속도 조정
            if grenade["vel_y"] > 0:  # 아래로 가고 있었다면
                grenade["vel_y"] = -abs(grenade["vel_y"]) * 0.5  # 위로 방향 전환
        # 화면 완전히 밖으로 나가면 제거 (안전장치)
        if grenade["x"] < -100 or grenade["x"] > WIDTH + 100 or grenade["y"] > HEIGHT + 100:
            grenades.remove(grenade)
            continue
    # 폭발 지역 업데이트 (지속시간 감소 + 테트로 증발 처리)
    explosion_zones = [zone for zone in explosion_zones if zone["duration"] > 0]
    for zone in explosion_zones:
        zone["duration"] -= 1
        # 보스 넉백+스턴 적용 (수류탄/화력지원 폭발만 1회 적용)
        try:
            if (
                zone.get("active", False)
                and zone.get("source") in ("grenade", "fire_support")
                and not zone.get("boss_applied", False)
                and 'BOSS' in globals() and BOSS is not None
            ):
                bx, by = get_center_pos(BOSS)
                cx = float(zone.get("x", 0.0))
                cy = float(zone.get("y", 0.0))
                r = float(zone.get("radius", 0.0))
                # 중심 거리 기반 판정 (간단/일관)
                if calculate_distance((bx, by), (cx, cy)) <= r:
                    # 스턴(126프레임 = 2.1초)
                    boss_stunned_timer = max(boss_stunned_timer, 126)
                    # 폭심지로부터 멀어지는 방향
                    direction = 1 if bx >= cx else -1
                    # 넉백 세기(백업값 복구: 40)
                    power = 40.0
                    # 넉백 타이머 설정 (즉시 넉백 적용을 위해 필수)
                    boss_knockback_timer = max(boss_knockback_timer, 36)
                    boss_knockback_vel = _apply_boss_knockback_velocity(direction * power)
                    # 대쉬/후딜 상태 강제 해제 (넉백 즉시 적용)
                    globals()["boss_dashing"] = False
                    globals()["boss_dash_timer"] = 0
                    globals()["boss_dash_stun_timer"] = 0
                    zone["boss_applied"] = True
        except Exception:
            pass
        # Stage 7: 수류탄 폭발 반경 내 테트로/가드 증발(한 번만 적용)
        try:
            if (
                current_stage == 7
                and zone.get("active", False)
                and zone.get("source") in ("grenade", "fire_support")
                and not zone.get("tetro_applied", False)
                and 'stage7_tetrominoes' in globals()
                and stage7_tetrominoes
            ):
                cx = float(zone.get("x", 0.0))
                cy = float(zone.get("y", 0.0))
                r = float(zone.get("radius", 0.0))
                r2 = r * r
                affected = 0
                for mino in list(stage7_tetrominoes):
                    state = mino.get("state")
                    if state in ("destroying", "evaporating"):
                        continue
                    # 원-사각형 근접 판정: 셀 중 하나라도 반경 내면 파괴
                    touched = False
                    for c in mino.get("cells", []) or []:
                        rect = c.get("rect")
                        if not rect:
                            continue
                        closest_x = max(rect.left, min(cx, rect.right))
                        closest_y = max(rect.top, min(cy, rect.bottom))
                        dx = cx - closest_x
                        dy = cy - closest_y
                        if dx * dx + dy * dy <= r2:
                            touched = True
                            break
                    if not touched:
                        continue
                    # 히트 플래시(번쩍)
                    try:
                        mino["hit_flash_duration"] = 130
                        mino["hit_flash_until"] = pygame.time.get_ticks() + 130
                    except Exception:
                        pass
                    # 벽 생성물은 충돌 리스트 즉시 제거
                    if mino.get("wall_generated"):
                        try:
                            for c in mino.get("cells", []) or []:
                                _remove_wall_cell_rect(c.get("rect"))
                        except Exception:
                            pass
                    destroy_stage7_tetromino(mino, by_player=True, by_dash=True)
                    affected += 1
                if affected > 0:
                    zone["tetro_applied"] = True
            # 가드 라인 블럭도 동일 처리
            if (
                current_stage == 7
                and zone.get("active", False)
                and zone.get("source") in ("grenade", "fire_support")
                and not zone.get("guard_applied", False)
                and 'stage7_guard_blocks' in globals()
                and stage7_guard_blocks
            ):
                cx = float(zone.get("x", 0.0))
                cy = float(zone.get("y", 0.0))
                r = float(zone.get("radius", 0.0))
                r2 = r * r
                affected = 0
                for block in list(stage7_guard_blocks):
                    state = block.get("state")
                    if state not in ("assembling", "hologram", "deploy", "active"):
                        continue
                    hit = False
                    for c in block.get("cells", []) or []:
                        rect = c.get("rect")
                        if not rect:
                            continue
                        closest_x = max(rect.left, min(cx, rect.right))
                        closest_y = max(rect.top, min(cy, rect.bottom))
                        dx = cx - closest_x
                        dy = cy - closest_y
                        if dx * dx + dy * dy <= r2:
                            hit = True
                            break
                    if hit:
                        destroy_stage7_guard_block(block, by_player=True)
                        affected += 1
                if affected > 0:
                    zone["guard_applied"] = True
        except Exception:
            pass
    # Stage7 EMP 파문 업데이트
    update_stage7_emp_pulses()
    # 연막탄 업데이트
    for smoke_grenade in smoke_grenades[:]:
        if not smoke_grenade["arrived"]:
            # 포물선 궤적으로 비행
            smoke_grenade["vel_y"] += smoke_grenade["gravity"]  # 중력 적용
            smoke_grenade["x"] += smoke_grenade["vel_x"]
            smoke_grenade["y"] += smoke_grenade["vel_y"]
            smoke_grenade["rotation"] += 15  # 더 빠른 회전
            # 궤적 추가 (흔적 효과)
            if len(smoke_grenade["trail"]) > 10:
                smoke_grenade["trail"].pop(0)
            smoke_grenade["trail"].append((smoke_grenade["x"], smoke_grenade["y"]))
            # 목표 지점 도달 체크 (바닥에 닿으면)
            if smoke_grenade["y"] >= smoke_grenade["target_y"]:
                smoke_grenade["arrived"] = True
                smoke_grenade["y"] = smoke_grenade["target_y"]
                # print(f"  ! 1")
                # 착지 효과음
                try:
                    play_paddle_sound()
                except:
                    pass
        elif smoke_grenade["timer"] < 60:  # 1초 대기
            smoke_grenade["timer"] += 1
            # 1초 후 연막 생성
            if smoke_grenade["timer"] >= 60:
                # 연막 지역 생성
                import items
                # 코만도암 효과: 연막탄 지속시간 증가 (스택 반영)
                base_duration = 600  # 10초 지속 (9초 + 1초 페이드아웃)
                smoke_duration = _commando_duration_bonus(base_duration, per_stack_pct=0.50)
                if items.commando_arm_obtained:
                    pass  # print(f"  !  : {smoke_duration/60:.1f} (: {base_duration/60:.1f})")
                
                smoke_zone = {
                    "x": smoke_grenade["x"],
                    "y": smoke_grenade["target_y"],
                    "radius": 0,  # 초기 반경 0에서 시작
                    "max_radius": 180,  # 최대 세로 반경
                    "radius_x": 0,  # 가로 반경 (별도 관리)
                    "max_radius_x": 240,  # 최대 가로 반경 (240픽셀)
                    "duration": smoke_duration,  # 코만도암 효과 적용된 지속시간
                    "particles": [],  # 연막 파티클들
                    "opacity": 0,  # 초기 투명도
                    "expansion_rate": 5,  # 세로 확장 속도
                    "expansion_rate_x": 6.7  # 가로 확장 속도 (240/36 프레임)
                }
                # 화로 연막탄인 경우 플래그 전달
                if 'is_brazier_smoke' in smoke_grenade:
                    smoke_zone['is_brazier_smoke'] = True
                # 초기 연막 파티클 생성 (중앙에서 시작, 가로로 더 넓게)
                for i in range(40):  # 파티클 수 증가
                    angle = random.uniform(0, 2 * math.pi)
                    dist = random.uniform(0, 10)
                    particle = {
                        "x": smoke_zone["x"] + math.cos(angle) * dist * 2,  # 가로로 2배
                        "y": smoke_zone["y"] + math.sin(angle) * dist,
                        "size": random.uniform(20, 40),  # 더 큰 파티클
                        "vel_x": math.cos(angle) * random.uniform(1.0, 3.0),  # 가로로 더 빠르게 퍼짐
                        "vel_y": random.uniform(-0.5, -0.2),
                        "lifetime": random.uniform(80, 150)
                    }
                    smoke_zone["particles"].append(particle)
                smoke_zones.append(smoke_zone)
                smoke_grenades.remove(smoke_grenade)
                # 연막 분출 효과음 (이미 사용 시 재생했으므로 제거)
                # 연막이 생성되는 시각적 효과만 표시
                # print(f"  ! 9 .")
    # 연막 지역 업데이트
    for smoke_zone in smoke_zones[:]:
        smoke_zone["duration"] -= 1
        # 연막 반경 점진적 확대 (타원형)
        if smoke_zone["radius"] < smoke_zone["max_radius"]:
            smoke_zone["radius"] = min(smoke_zone["max_radius"], 
                                      smoke_zone["radius"] + smoke_zone["expansion_rate"])
        if "radius_x" in smoke_zone and smoke_zone["radius_x"] < smoke_zone["max_radius_x"]:
            smoke_zone["radius_x"] = min(smoke_zone["max_radius_x"], 
                                        smoke_zone["radius_x"] + smoke_zone["expansion_rate_x"])
        
        # Stage 4에서 화로 점화 체크 (연막이 확장되면서 화로에 닿는지 확인)
        if (current_stage == 4 and animated_bg_stage4 and 
            smoke_zone.get('is_brazier_smoke', False) and 
            not smoke_zone.get('brazier_checked', False)):
            # 연막이 충분히 확장되었을 때 화로 점화 체크
            if smoke_zone["radius"] >= 50:  # 어느 정도 확장된 후 체크
                # 디버그: 화로 위치와 연막 위치 출력
                brazier_x, brazier_y = animated_bg_stage4.get_brazier_position()
                distance = math.sqrt((smoke_zone["x"] - brazier_x)**2 + (smoke_zone["y"] - brazier_y)**2)
                # print(f"   - :({smoke_zone['x']:.0f},{smoke_zone['y']:.0f}),"
                #       f"화로위치:({brazier_x},{brazier_y}), 연막반경:{smoke_zone['radius']:.0f}, "
                #       f"거리:{distance:.1f}")
                
                lit = animated_bg_stage4.check_smoke_touches_brazier(
                    smoke_zone["x"], smoke_zone["y"], smoke_zone["radius"])
                if lit:
                    # print(f"     !")
                    smoke_zone['has_lit_brazier'] = True
                else:
                    pass  # print(f"    -")
                smoke_zone['brazier_checked'] = True  # 중복 체크 방지
        # 투명도 조절 (서서히 나타났다가 사라짐)
        if smoke_zone["duration"] > 540:  # 처음 1초: 페이드인
            smoke_zone["opacity"] = min(150, smoke_zone["opacity"] + 5)
        elif smoke_zone["duration"] > 60:  # 중간 8초: 유지
            smoke_zone["opacity"] = 150
        else:  # 마지막 1초: 페이드아웃
            smoke_zone["opacity"] = max(0, smoke_zone["opacity"] - 3)
        # 스테이지 2 바위 제거 처리
        destroy_stage2_rocks_in_smoke(smoke_zone)
        # 스테이지 7 테트로미노를 연막에 닿으면 분해 처리
        destroy_stage7_tetrominoes_in_smoke(smoke_zone)
        # 파티클 추가 생성 (지속적인 연기 효과, 타원형)
        if smoke_zone["duration"] > 60 and len(smoke_zone["particles"]) < 60:  # 파티클 수 증가
            if random.random() < 0.5:  # 50% 확률로 새 파티클
                angle = random.uniform(0, 2 * math.pi)
                # 타원형 분포
                radius_x = smoke_zone.get("radius_x", smoke_zone["radius"])
                radius_y = smoke_zone["radius"]
                dist_x = random.uniform(0, radius_x * 0.7)
                dist_y = random.uniform(0, radius_y * 0.7)
                particle = {
                    "x": smoke_zone["x"] + math.cos(angle) * dist_x,
                    "y": smoke_zone["y"] + math.sin(angle) * dist_y,
                    "size": random.uniform(30, 50),  # 더 큰 파티클
                    "vel_x": math.cos(angle) * random.uniform(0.3, 1.2),  # 가로로 더 활발한 움직임
                    "vel_y": random.uniform(-0.2, -0.05),
                    "lifetime": random.uniform(40, 80)
                }
                smoke_zone["particles"].append(particle)
        # 파티클 업데이트
        for particle in smoke_zone["particles"][:]:
            particle["x"] += particle["vel_x"]
            particle["y"] += particle["vel_y"]
            particle["lifetime"] -= 1
            particle["size"] *= 0.99  # 서서히 작아짐
            if particle["lifetime"] <= 0 or particle["size"] < 5:
                smoke_zone["particles"].remove(particle)
        # 공이 연막 안에 있는지 체크 (타원형)
        dx = BALL.centerx - smoke_zone["x"]
        dy = BALL.centery - smoke_zone["y"]
        radius_x = smoke_zone.get("radius_x", smoke_zone["radius"])
        radius_y = smoke_zone["radius"]
        # 타원 방정식: (x/a)^2 + (y/b)^2 <= 1
        if radius_x > 0 and radius_y > 0:
            ellipse_distance = (dx / radius_x) ** 2 + (dy / radius_y) ** 2
        else:
            ellipse_distance = float('inf')
        if ellipse_distance <= 1 and smoke_zone["opacity"] > 50:
            # 보스가 친 공만 연막 효과 적용 (플레이어가 친 공은 무시)
            if last_hit_by == "boss":
                # 현재 공 속도 계산
                current_speed = math.sqrt(ball_vel[0]**2 + ball_vel[1]**2)
                
                # 공속이 25 이상일 때만 연막 효과 적용
                if current_speed >= 25:
                    # 처음 진입 시 원래 속도 저장 및 즉시 60%로 감속
                    if not hasattr(smoke_zone, "affecting_ball"):
                        smoke_zone["affecting_ball"] = True
                        smoke_zone["original_speed"] = current_speed  # 원래 속도 저장
                        
                        # 즉시 60%로 감속 (40% 감소)
                        speed_factor = 0.6
                        ball_vel[0] *= speed_factor
                        ball_vel[1] *= speed_factor
                        
                        new_speed = math.sqrt(ball_vel[0]**2 + ball_vel[1]**2)
                        # print(f"     !  60% ! ({current_speed:.1f} → {new_speed:.1f})")
                    # 이미 연막 안에 있는 경우 60% 속도 유지
                    else:
                        # 60% 속도 유지 (더 이상 감속하지 않음)
                        pass
                elif current_speed > 15.0:
                    # 15~25 구간은 기존 점진적 감속 유지
                    speed_reduction = 0.97  # 매 프레임마다 3% 감속
                    ball_vel[0] *= speed_reduction
                    ball_vel[1] *= speed_reduction
                    # 최소 속도 보장
                    min_speed = 2.0
                    current_speed = math.sqrt(ball_vel[0]**2 + ball_vel[1]**2)
                    if current_speed < min_speed and current_speed > 0:
                        speed_factor = min_speed / current_speed
                        ball_vel[0] *= speed_factor
                        ball_vel[1] *= speed_factor
                    # 처음 진입 시에만 메시지 출력
                    if not hasattr(smoke_zone, "affecting_ball"):
                        smoke_zone["affecting_ball"] = True
                        # print(f"     !   ... ( : {current_speed:.1f})")
                else:
                    # 느린 공은 디버프 적용 안함
                    if not hasattr(smoke_zone, "slow_ball_ignored"):
                        smoke_zone["slow_ball_ignored"] = True
                        # print(f"     ! ( : {current_speed:.1f} <= 15.0)")
            else:
                # 플레이어가 친 공은 연막 효과 무시
                if not hasattr(smoke_zone, "player_ball_ignored"):
                    smoke_zone["player_ball_ignored"] = True
                    # print(f"      !")
        else:
            # 연막을 벗어나면 플래그 제거
            if hasattr(smoke_zone, "affecting_ball"):
                del smoke_zone["affecting_ball"]
                # print(f"")
            if hasattr(smoke_zone, "original_speed"):
                del smoke_zone["original_speed"]
            if hasattr(smoke_zone, "slow_ball_ignored"):
                del smoke_zone["slow_ball_ignored"]
            if hasattr(smoke_zone, "player_ball_ignored"):
                del smoke_zone["player_ball_ignored"]
        # 지속시간 종료 체크
        if smoke_zone["duration"] <= 0:
            # Stage 4에서 화로를 통해 소환된 몽크가 있으면 30초 후 귀환 타이머 시작
            if current_stage == 4 and animated_bg_stage4 and smoke_zone.get('has_lit_brazier', False):
                animated_bg_stage4.trigger_smoke_grenade_monk_return()
                # print(f"  !  30   .")
            smoke_zones.remove(smoke_zone)
    # 조명탄 업데이트
    for flare in flares[:]:
        if not flare["arrived"]:
            # 아직 날아가는 중이면 이동
            flare["x"] += flare["vel_x"]
            flare["y"] += flare["vel_y"]
            flare["rotation"] += 12  # 회전
            # 화면 상단 벽(보스 뒷벽)에 도달하면 즉시 도착 처리
            if flare["y"] <= 10:
                flare["arrived"] = True
                flare["y"] = 10  # 벽 위치에 고정
                # print(f"조명탄 벽에 도달! 1.5초 후 폭발.")
            # 좌우 벽 충돌 시 반사 (벽 뒤로 넘어가지 않도록)
            wall_margin = 10  # 벽 경계 여유
            if flare["x"] <= wall_margin:
                flare["x"] = wall_margin
                flare["vel_x"] = abs(flare["vel_x"]) * 0.7  # 오른쪽으로 반사, 속도 감쇠
                # 반사 후 보스 방향(위쪽)으로 속도 조정
                if flare["vel_y"] > 0:  # 아래로 가고 있었다면
                    flare["vel_y"] = -abs(flare["vel_y"]) * 0.5  # 위로 방향 전환
            elif flare["x"] >= WIDTH - wall_margin:
                flare["x"] = WIDTH - wall_margin
                flare["vel_x"] = -abs(flare["vel_x"]) * 0.7  # 왼쪽으로 반사, 속도 감쇠
                # 반사 후 보스 방향(위쪽)으로 속도 조정
                if flare["vel_y"] > 0:  # 아래로 가고 있었다면
                    flare["vel_y"] = -abs(flare["vel_y"]) * 0.5  # 위로 방향 전환
            # 화면 완전히 밖으로 나가면 제거 (안전장치)
            if flare["x"] < -100 or flare["x"] > WIDTH + 100 or flare["y"] > HEIGHT + 100:
                flares.remove(flare)
                continue
            # 목표 지점에 도달했는지 체크 (거리 기반으로 체크)
            dist_to_target = math.sqrt((flare["x"] - flare["target_x"])**2 +
                                      (flare["y"] - flare["target_y"])**2)
            if dist_to_target < 10:  # 목표 지점에 충분히 가까워졌을 때
                flare["arrived"] = True
                flare["x"] = flare["target_x"]  # 정확한 위치에 고정
                flare["y"] = flare["target_y"]
                # print(f"  ! 1.5  .")
        elif not flare["exploded"]:
            # 도착 후 타이머 증가
            flare["timer"] += 1
            # 1.5초(90프레임) 후 폭발
            if flare["timer"] >= 90:
                flare["exploded"] = True
                #  조명탄 폭발 사운드 재생
                try:
                    play_sound_with_volume(SOUND_FLASHBOMB)
                except:
                    pass  # 사운드 재생 실패 시 무시
                # 섬광 효과 생성 (0.15초 = 9프레임)
                import items
                # 코만도암 효과: 폭발 범위 10% 증가 (스택 반영)
                base_radius = 180  # 조명 반경
                flare_radius = _commando_range_bonus(base_radius, per_stack_pct=0.10)
                if items.commando_arm_obtained:
                    pass  # print(f"  !   : {flare_radius} (: {base_radius})")
                
                flare_zone = {
                    "x": flare["x"],
                    "y": flare["y"],
                    "radius": flare_radius,  # 코만도암 효과 적용된 조명 반경
                    "duration": 9,  # 0.15초 섬광 (60fps * 0.15)
                    "intensity": 1.0,
                    "flash": True  # 섬광 효과 플래그
                }
                flare_zones.append(flare_zone)
                # 보스가 폭발 범위 내에 있는지 체크
                boss_distance = calculate_distance(get_center_pos(BOSS), (flare["x"], flare["y"]))
                if boss_distance <= flare_radius:  # 폭발 반경 내에 있으면
                    boss_confused_timer = THREE_SECONDS_FRAMES  # 3초간 보스 혼란
                    # print(f"  !  3  !")
                    
                    # 코만도 캐릭터의 조명탄 보스 명중 시 게이지 증가 (스택 반영)
                    if selected_character_type == "soldier":
                        base_gauge = 50
                        gauge_increase = _commando_gauge_bonus(base_gauge, per_stack_bonus=20)
                        if items.commando_arm_obtained:
                            pass  # print(f"🎯 코만도암 보너스! 조명탄 게이지 {gauge_increase} 증가!")
                        else:
                            pass  # print("💡 조명탄 명중! 게이지 50 증가!")

                        # 게이지 증가 적용
                        gauge_increase = _apply_blacksmith_berserk_gauge_bonus(gauge_increase)
                        # ⛏️ 골드디거 게이지 충전량 증가 적용
                        if is_gold_digger_equipped():
                            gauge_increase = apply_gold_digger_gauge_bonus(gauge_increase)
                        old_gauge = special_gauge
                        special_gauge += gauge_increase
                        current_max = get_max_gauge()
                        if special_gauge > current_max:
                            special_gauge = current_max

                        # 필살기 준비 상태 업데이트
                        if special_gauge >= 350:
                            special_ready = True

                        # print(f"조명탄 게이지 충전: {old_gauge} → {special_gauge} (+{gauge_increase})")
                else:
                    pass  # print(f"  ! : {boss_distance:.0f}")
                flares.remove(flare)
                # 효과음
                try:
                    play_wall_sound()
                except:
                    pass
                # print(f"  !  5  !")
    # 조명 지대 업데이트 (섬광 효과)
    for zone in flare_zones[:]:
        zone["duration"] -= 1
        if zone.get("flash", False):
            # 섬광 효과: 빠르게 깜빡임 (0.15초 = 9프레임)
            if zone["duration"] > 6:  # 처음 0.05초는 최대 밝기
                zone["intensity"] = 1.0
            elif zone["duration"] > 3:  # 다음 0.05초는 어두워짐
                zone["intensity"] = 0.3
            else:  # 마지막 0.05초는 다시 밝아짐
                zone["intensity"] = 0.8
        else:
            zone["intensity"] = zone["duration"] / 9.0  # 일반 페이드 아웃
        if zone["duration"] <= 0:
            flare_zones.remove(zone)
    # 보스 혼란 타이머 감소
    if boss_confused_timer > 0:
        boss_confused_timer -= 1
    # 화염병 업데이트
    for molotov in molotovs[:]:
        # 중력 적용 (gravity가 0이면 적용 안함)
        if molotov["gravity"] > 0:
            molotov["vel_y"] += molotov["gravity"]
        molotov["x"] += molotov["vel_x"]
        molotov["y"] += molotov["vel_y"]
        molotov["rotation"] += 10  # 회전
        # 좌우 벽 충돌 시 반사 (벽 뒤로 넘어가지 않도록)
        wall_margin = 10  # 벽 경계 여유
        if molotov["x"] <= wall_margin:
            molotov["x"] = wall_margin
            molotov["vel_x"] = abs(molotov["vel_x"]) * 0.7  # 오른쪽으로 반사, 속도 감쇠
            # 반사 후 보스 방향(위쪽)으로 속도 조정
            if molotov["vel_y"] > 0:  # 아래로 가고 있었다면
                molotov["vel_y"] = -abs(molotov["vel_y"]) * 0.5  # 위로 방향 전환
        elif molotov["x"] >= WIDTH - wall_margin:
            molotov["x"] = WIDTH - wall_margin
            molotov["vel_x"] = -abs(molotov["vel_x"]) * 0.7  # 왼쪽으로 반사, 속도 감쇠
            # 반사 후 보스 방향(위쪽)으로 속도 조정
            if molotov["vel_y"] > 0:  # 아래로 가고 있었다면
                molotov["vel_y"] = -abs(molotov["vel_y"]) * 0.5  # 위로 방향 전환
        # 화면 완전히 밖으로 나가면 제거 (안전장치)
        if molotov["x"] < -100 or molotov["x"] > WIDTH + 100 or molotov["y"] > HEIGHT + 100:
            molotovs.remove(molotov)
            continue
        # 목표 지점에 도달하거나 화면 상단 벽(보스 뒷벽)에 도달하면 폭발
        explode_y = molotov["target_y"]
        if molotov["y"] <= 10:  # 화면 상단 벽에 도달
            explode_y = 10
        if molotov["y"] <= molotov["target_y"] or molotov["y"] <= 10:
            # 폭발 효과 - 불길이 번지는 효과
            import items
            # 코만도암 효과: 폭발 범위 증가 (스택 반영)
            base_width = 150  # 화염 지대 너비
            base_height = 60  # 화염 지대 높이
            fire_width = _commando_range_bonus(base_width, per_stack_pct=0.10)
            fire_height = _commando_range_bonus(base_height, per_stack_pct=0.10)
            if items.commando_arm_obtained:
                pass  # print(f"  !   : {fire_width}x{fire_height} (: {base_width}x{base_height})")
            
            fire_zone = {
                "x": molotov["x"],
                "y": explode_y,  # 실제 폭발 위치에 생성
                "width": fire_width,  # 코만도암 효과 적용된 화염 지대 너비
                "height": fire_height,  # 코만도암 효과 적용된 화염 지대 높이
                "duration": 150,  # 2.5초 (60fps * 2.5)
                "flames": [],  # 개별 불꽃 파티클들
                "spread_timer": 0  # 불길 번짐 타이머
            }
            # 초기 불꽃 파티클 생성 (불길이 번지는 효과)
            for i in range(15):
                flame = {
                    "x": molotov["x"] + random.uniform(-30, 30),
                    "y": explode_y + random.uniform(-10, 10),
                    "size": random.uniform(8, 20),
                    "lifetime": random.uniform(20, 40),
                    "color_phase": random.uniform(0, 1)
                }
                fire_zone["flames"].append(flame)
            fire_zones.append(fire_zone)
            molotovs.remove(molotov)
            # 폭발 효과음
            try:
                play_sound_with_volume(SOUND_FIREBOMB)  #  화염병 폭발 사운드 재생
            except:
                pass
            # print(f"  !    : X={fire_zone['x']:.1f}, Y={fire_zone['y']:.1f}")
    # 화염 지대 업데이트
    for fire_zone in fire_zones[:]:
        fire_zone["duration"] -= 1
        fire_zone["spread_timer"] += 1
        # push_timer가 없으면 초기화
        if "push_timer" not in fire_zone:
            fire_zone["push_timer"] = 0
        fire_zone["push_timer"] += 1

        # 불길 번짐 효과 - 지속적으로 새 불꽃 추가
        if fire_zone["spread_timer"] % 5 == 0 and len(fire_zone["flames"]) < 30:
            for i in range(3):
                flame = {
                    "x": fire_zone["x"] + random.uniform(-fire_zone["width"]/2, fire_zone["width"]/2),
                    "y": fire_zone["y"] + random.uniform(-fire_zone["height"]/2, fire_zone["height"]/2),
                    "size": random.uniform(10, 25),
                    "lifetime": random.uniform(15, 30),
                    "color_phase": random.uniform(0, 1)
                }
                fire_zone["flames"].append(flame)
        # 불꽃 파티클 업데이트
        for flame in fire_zone["flames"][:]:
            flame["lifetime"] -= 1
            flame["size"] *= 0.97  # 서서히 작아짐
            flame["y"] -= random.uniform(0.1, 0.5)  # 위로 살짝 올라감
            flame["x"] += random.uniform(-0.5, 0.5)  # 좌우로 흔들림
            if flame["lifetime"] <= 0 or flame["size"] < 2:
                fire_zone["flames"].remove(flame)
        # 보스가 화염 지대 안에 있는지 체크 (이동속도 감소용)
        boss_center_x = BOSS.centerx
        boss_center_y = BOSS.centery
        # 사각형 영역 체크 (불길이 번진 영역 + 패들 크기 고려) - 범위 50% 축소
        # X축 거리 체크 - 보스가 화염 지대 폭 안에 있는지
        x_in_range = abs(boss_center_x - fire_zone["x"]) < (fire_zone["width"]/4 + PADDLE_WIDTH/2)  # width/2 → width/4로 축소
        # Y축 거리 체크 - 보스와 화염 지대 사이 거리
        y_distance = abs(boss_center_y - fire_zone["y"])
        # 보스가 화염 지대 근처에 있으면 (Y축으로 60픽셀 이내)  # 120 → 60으로 축소
        y_in_range = y_distance < 60
        in_fire_zone = x_in_range and y_in_range
        #  화염 지대 내 보스 이동속도 50% 감소 효과 설정
        #  Stage 5 홍련은 화염병에 면역
        if in_fire_zone:
            if current_stage != 5:  # Stage 5 홍련은 화염병 속도 감소에 면역
                # 전역 변수로 보스 속도 감소 플래그 설정 (handle_boss에서 참조)
                fire_zone["boss_in_fire"] = True
                global boss_speed_reduction_active, boss_speed_reduction_factor
                boss_speed_reduction_active = True
                boss_speed_reduction_factor = 0.5  # 50% 감소 = 50%만 유지
            else:
                # Stage 5 홍련은 화염병 효과에 면역
                fire_zone["boss_in_fire"] = False
        else:
            # 보스가 화염 지대를 벗어났을 때
            fire_zone["boss_in_fire"] = False
        # 0.5초마다 보스를 화염 지대 밖으로 밀어내기 (스턴 없이 튕김)
        #  Stage 5 홍련은 화염병 넉백에도 면역
        if fire_zone["push_timer"] >= 30:  # 30프레임 = 0.5초 (9프레임에서 변경)
            fire_zone["push_timer"] = 0
            if in_fire_zone and current_stage != 5:  # Stage 5 홍련은 넉백에 면역
                # 스턴 없이 즉시 밀어내기 - 화염 지대 중심으로부터 반대 방향으로
                push_force = 60  # 매우 강한 밀어내기 힘 (35에서 60으로 대폭 증가)
                # 화염 지대 중심으로부터의 방향에 따라 밀어내기
                if boss_center_x < fire_zone["x"]:
                    # 보스가 화염 지대 왼쪽에 있으면 왼쪽으로 밀기
                    BOSS.x -= push_force
                else:
                    # 보스가 화염 지대 오른쪽에 있으면 오른쪽으로 밀기
                    BOSS.x += push_force
                # 화면 경계 체크
                BOSS.x = max(0, min(WIDTH - BOSS.width, BOSS.x))
                #  체력형 보스 화염 데미지 적용 (1초마다 1회씩만 카운트, 3회마다 체력 감소)
                if current_stage in boss_health_stages and boss_fire_hit_timer <= 0:
                    boss_fire_hit_count += 1
                    boss_fire_hit_timer = FPS  # 1초 쿨다운 (60프레임)
                    if boss_fire_hit_count >= 3:
                        boss_current_health = max(0, boss_current_health - 1)  # 3회마다 체력 1 감소
                        boss_fire_hit_count = 0  # 카운터 리셋
                        # print(f"  !   -1 (: {boss_current_health}/{boss_max_health})")
                    else:
                        pass  # print(f"   {boss_fire_hit_count}/3")
                # 시각적 피드백용 작은 흔들림 효과
                if random.random() < 0.3:  # 30% 확률로 작은 흔들림
                    BOSS.x += random.randint(-3, 3)
                    BOSS.x = max(0, min(WIDTH - BOSS.width, BOSS.x))
        # 지속시간 종료 체크
        if fire_zone["duration"] <= 0:
            # 화염 효과음 관련 코드 제거됨 (SOUND_FLAME 사용 안 함)
            fire_zones.remove(fire_zone)
    #  모든 화염 지대를 체크한 후, 보스가 어떤 화염 지대에도 없으면 속도 감소 효과 리셋
    if len(fire_zones) == 0 or not any(zone.get("boss_in_fire", False) for zone in fire_zones):
        boss_speed_reduction_active = False
        boss_speed_reduction_factor = 1.0  # 정상 속도로 복구

def deactivate_whip():
    """상모돌리기 완전 비활성화 - 사운드 정지 보장"""
    global whip_active, whip_timer, whip_wave_particles
    global whip_deactivation_active, whip_deactivation_timer, whip_rotation_speed
    global boss_stunned_after_whip
    whip_active = False
    whip_timer = 0
    whip_sound.stop()  # 반드시 사운드 정지
    whip_wave_particles.clear()

    # Stage 1: 종료 후 감속/정지 연출을 항상 시작
    if current_stage == 1 and not whip_deactivation_active and not boss_stunned_after_whip:
        whip_deactivation_active = True
        whip_deactivation_timer = whip_deactivation_duration
        # 이미 회전 중이었다면 기존 속도를 유지하고, 아닐 경우 최소 속도 보장
        whip_rotation_speed = max(whip_rotation_speed, 20.0)

# === 포도대장 포승줄 스킬 (상태머신: idle → throwing → bound/miss → idle) ===
def activate_arrest_rope():
    """포승줄 발동 — throwing 단계 시작 (밧줄이 보스에서 플레이어를 향해 날아감)"""
    global arrest_rope_phase, arrest_rope_timer, arrest_rope_visual_timer
    global arrest_rope_start_x, arrest_rope_start_y
    global arrest_rope_target_x, arrest_rope_target_y
    global arrest_rope_throw_progress, arrest_rope_active

    arrest_rope_phase = "throwing"
    arrest_rope_timer = 0
    arrest_rope_visual_timer = 0
    arrest_rope_throw_progress = 0.0
    arrest_rope_active = False  # throwing 중에는 아직 속도 감소 없음

    # 보스 위치 (발사 시작점)
    arrest_rope_start_x = float(BOSS.centerx if BOSS else WIDTH // 2)
    arrest_rope_start_y = float(BOSS.y + BOSS.height if BOSS else 65)
    # 플레이어 위치 (목표) — 발사 시점의 플레이어 위치
    arrest_rope_target_x = float(PLAYER.centerx if PLAYER else WIDTH // 2)
    arrest_rope_target_y = float(PLAYER.y if PLAYER else 710)

    try:
        play_sound_with_volume(SOUND_THROW_BEFORE)
    except Exception:
        pass

def deactivate_arrest_rope():
    """포승줄 해제"""
    global arrest_rope_active, arrest_rope_timer, arrest_rope_phase
    arrest_rope_active = False
    arrest_rope_timer = 0
    arrest_rope_phase = "idle"

def update_arrest_rope():
    """포승줄 상태머신 업데이트 (매 프레임 호출)"""
    global arrest_rope_phase, arrest_rope_active, arrest_rope_timer, arrest_rope_visual_timer
    global arrest_rope_throw_progress, arrest_rope_bind_x, arrest_rope_bind_y

    import math as _math

    if arrest_rope_phase == "idle":
        return

    arrest_rope_visual_timer += 1

    if arrest_rope_phase == "throwing":
        # --- 투사체 날아가는 단계 (45프레임 ≈ 0.75초) ---
        arrest_rope_timer += 1
        throw_duration = 45
        # easeOutQuad 이징: 처음 빠르고 끝에 감속
        raw_t = min(arrest_rope_timer / throw_duration, 1.0)
        arrest_rope_throw_progress = 1.0 - (1.0 - raw_t) * (1.0 - raw_t)

        if arrest_rope_timer >= throw_duration:
            # 도착 — 히트 판정
            player_cx = PLAYER.centerx if PLAYER else WIDTH // 2
            hit_range = (PLAYER.width * 0.6) if PLAYER else 93
            dist = abs(arrest_rope_target_x - player_cx)
            if dist < hit_range:
                # 히트! → bound 단계
                arrest_rope_phase = "bound"
                arrest_rope_active = True
                arrest_rope_timer = 180  # 3초
                arrest_rope_bind_x = float(player_cx)
                arrest_rope_bind_y = float(PLAYER.y if PLAYER else 710)
                try:
                    play_sound_with_volume(SOUND_THROW)
                except Exception:
                    pass
            else:
                # 미스! → miss 단계
                arrest_rope_phase = "miss"
                arrest_rope_timer = 30  # 0.5초 미스 연출
                arrest_rope_active = False

    elif arrest_rope_phase == "bound":
        # --- 포박 단계 (3초, 플레이어 따라감) ---
        arrest_rope_timer -= 1
        # 매 프레임 플레이어 위치 추적
        arrest_rope_bind_x = float(PLAYER.centerx if PLAYER else WIDTH // 2)
        arrest_rope_bind_y = float(PLAYER.y if PLAYER else 710)
        if arrest_rope_timer <= 0:
            # 끊어지는 연출로 전환
            arrest_rope_phase = "releasing"
            arrest_rope_active = False  # 속도 디버프 즉시 해제
            arrest_rope_timer = 28  # 끊어지는 연출 0.47초

    elif arrest_rope_phase == "releasing":
        # --- 줄 끊어지는 연출 ---
        arrest_rope_timer -= 1
        # 플레이어 위치 계속 추적 (끊어지는 지점 고정용)
        arrest_rope_bind_x = float(PLAYER.centerx if PLAYER else WIDTH // 2)
        arrest_rope_bind_y = float(PLAYER.y if PLAYER else 710)
        if arrest_rope_timer <= 0:
            arrest_rope_phase = "idle"

    elif arrest_rope_phase == "miss":
        # --- 미스 연출 (0.5초) ---
        arrest_rope_timer -= 1
        if arrest_rope_timer <= 0:
            arrest_rope_phase = "idle"

def draw_arrest_rope_effect(screen):
    """포승줄 시각 이펙트 렌더링 — 3개 단계별 다른 연출"""
    if arrest_rope_phase == "idle":
        return

    import math as _math

    # 공통 색상
    vt = arrest_rope_visual_timer
    flash = 0.85 + 0.15 * _math.sin(vt * 0.15)
    rope_color = (int(175 * flash), int(145 * flash), int(95 * flash))
    rope_dark = (140, 110, 65)
    rope_light = (200, 175, 125)
    rope_glow_color = (200, 170, 110, 80)

    boss_cx = arrest_rope_start_x
    boss_cy = arrest_rope_start_y

    if arrest_rope_phase == "throwing":
        _draw_rope_throwing(screen, boss_cx, boss_cy, rope_color, rope_dark, rope_light, vt)
    elif arrest_rope_phase == "bound":
        _draw_rope_bound(screen, boss_cx, boss_cy, rope_color, rope_dark, rope_light, rope_glow_color, vt)
    elif arrest_rope_phase == "releasing":
        _draw_rope_releasing(screen, boss_cx, boss_cy, rope_color, rope_dark, rope_light, vt)
    elif arrest_rope_phase == "miss":
        _draw_rope_miss(screen, boss_cx, boss_cy, rope_color, rope_dark, vt)

def _draw_rope_throwing(screen, boss_cx, boss_cy, rope_color, rope_dark, rope_light, vt):
    """포승줄 투사 — 보스→목표 날아가는 밧줄"""
    import math as _math
    prog = arrest_rope_throw_progress
    tx = arrest_rope_target_x
    ty = arrest_rope_target_y

    # 밧줄 끝(올가미) 현재 위치
    tip_x = boss_cx + (tx - boss_cx) * prog
    tip_y = boss_cy + (ty - boss_cy) * prog

    # === 보스→밧줄끝 연결 밧줄 (카테너리 곡선 처짐) ===
    segments = 14
    sag_amount = 25 * (1.0 - prog * 0.5)  # 진행될수록 팽팽해짐
    for i in range(segments):
        t1 = i / segments
        t2 = (i + 1) / segments
        # 보스→밧줄끝 보간
        x1 = boss_cx + (tip_x - boss_cx) * t1
        y1 = boss_cy + (tip_y - boss_cy) * t1
        x2 = boss_cx + (tip_x - boss_cx) * t2
        y2 = boss_cy + (tip_y - boss_cy) * t2
        # 처짐 (포물선 — 중앙이 가장 많이 처짐)
        sag1 = _math.sin(t1 * _math.pi) * sag_amount
        sag2 = _math.sin(t2 * _math.pi) * sag_amount
        # 미세한 흔들림
        wave1 = _math.sin(t1 * _math.pi * 3 + vt * 0.3) * 4 * (1.0 - prog * 0.7)
        wave2 = _math.sin(t2 * _math.pi * 3 + vt * 0.3) * 4 * (1.0 - prog * 0.7)
        # 두께: 시작 3px → 끝 2px
        w = max(1, int(3 - t1 * 1.5))
        pygame.draw.line(screen, rope_dark,
                        (int(x1 + wave1), int(y1 + sag1) + 1),
                        (int(x2 + wave2), int(y2 + sag2) + 1), w)
        pygame.draw.line(screen, rope_color,
                        (int(x1 + wave1), int(y1 + sag1)),
                        (int(x2 + wave2), int(y2 + sag2)), w)

    # === 밧줄 끝 — 올가미 (회전하며 날아감) ===
    lasso_r = max(6, int(14 * (0.5 + 0.5 * prog)))
    lasso_angle = vt * 0.4  # 회전
    # 올가미 원
    pygame.draw.circle(screen, rope_dark, (int(tip_x) + 1, int(tip_y) + 1), lasso_r, 2)
    pygame.draw.circle(screen, rope_light, (int(tip_x), int(tip_y)), lasso_r, 2)
    # 올가미 중심 십자 (회전)
    cross_dx = int(_math.cos(lasso_angle) * lasso_r * 0.5)
    cross_dy = int(_math.sin(lasso_angle) * lasso_r * 0.5)
    pygame.draw.line(screen, rope_color,
                    (int(tip_x) - cross_dx, int(tip_y) - cross_dy),
                    (int(tip_x) + cross_dx, int(tip_y) + cross_dy), 1)

    # === 잔상 트레일 ===
    for trail_i in range(3):
        trail_prog = max(0, prog - trail_i * 0.06)
        trail_x = boss_cx + (tx - boss_cx) * trail_prog
        trail_y = boss_cy + (ty - boss_cy) * trail_prog
        trail_alpha = max(0, 80 - trail_i * 25)
        trail_r = max(2, lasso_r - trail_i * 2)
        trail_surf = pygame.Surface((trail_r * 2, trail_r * 2), pygame.SRCALPHA)
        pygame.draw.circle(trail_surf, (175, 145, 95, trail_alpha), (trail_r, trail_r), trail_r)
        screen.blit(trail_surf, (int(trail_x) - trail_r, int(trail_y) - trail_r))

    # === 보스 쪽 밧줄 고정점 ===
    pygame.draw.circle(screen, rope_dark, (int(boss_cx), int(boss_cy)), 4)
    pygame.draw.circle(screen, rope_light, (int(boss_cx), int(boss_cy)), 3, 1)

def _draw_rope_bound(screen, boss_cx, boss_cy, rope_color, rope_dark, rope_light, rope_glow_color, vt):
    """포승줄 포박 — 보스↔플레이어 연결 + 묶인 이펙트"""
    import math as _math
    bind_x = arrest_rope_bind_x
    bind_y = arrest_rope_bind_y

    # 보스 현재 위치 (이동 중이므로 실시간)
    cur_boss_cx = float(BOSS.centerx if BOSS else WIDTH // 2)
    cur_boss_cy = float(BOSS.y + BOSS.height if BOSS else 65)

    # === 보스→플레이어 밧줄 (S자 곡선) ===
    dx = bind_x - cur_boss_cx
    total_dist = _math.sqrt(dx * dx + (bind_y - cur_boss_cy) ** 2)
    tension = min(total_dist / 500.0, 1.0)  # 0~1: 거리 멀수록 팽팽
    sag = 30 * (1.0 - tension * 0.7)  # 팽팽하면 처짐 줄어듦
    wave_amp = 8 * (1.0 - tension * 0.5)

    segments = 16
    for i in range(segments):
        t1 = i / segments
        t2 = (i + 1) / segments
        x1 = cur_boss_cx + (bind_x - cur_boss_cx) * t1
        y1 = cur_boss_cy + (bind_y - cur_boss_cy) * t1
        x2 = cur_boss_cx + (bind_x - cur_boss_cx) * t2
        y2 = cur_boss_cy + (bind_y - cur_boss_cy) * t2
        # 처짐 + 물결
        sag1 = _math.sin(t1 * _math.pi) * sag
        sag2 = _math.sin(t2 * _math.pi) * sag
        wave1 = _math.sin(t1 * _math.pi * 4 + vt * 0.08) * wave_amp
        wave2 = _math.sin(t2 * _math.pi * 4 + vt * 0.08) * wave_amp
        w = max(1, int(3 - abs(t1 - 0.5) * 3))
        # 그림자
        pygame.draw.line(screen, rope_dark,
                        (int(x1 + wave1) + 1, int(y1 + sag1) + 1),
                        (int(x2 + wave2) + 1, int(y2 + sag2) + 1), w)
        pygame.draw.line(screen, rope_color,
                        (int(x1 + wave1), int(y1 + sag1)),
                        (int(x2 + wave2), int(y2 + sag2)), w)

    # === 보스 쪽 고정점 ===
    pygame.draw.circle(screen, rope_dark, (int(cur_boss_cx), int(cur_boss_cy)), 4)
    pygame.draw.circle(screen, rope_light, (int(cur_boss_cx), int(cur_boss_cy)), 3, 1)

    # === 플레이어 포박 이펙트 ===
    bx, by = int(bind_x), int(bind_y)

    # 1) 묶인 글로우 (펄스)
    bind_pulse = 0.75 + 0.25 * _math.sin(vt * 0.18)
    glow_r = int(42 * bind_pulse)
    glow_surf = pygame.Surface((glow_r * 2, glow_r * 2), pygame.SRCALPHA)
    pygame.draw.circle(glow_surf, rope_glow_color, (glow_r, glow_r), glow_r)
    screen.blit(glow_surf, (bx - glow_r, by - glow_r), special_flags=pygame.BLEND_ADD)

    # 2) X자 포박 밧줄 (2겹 — 교차)
    bind_rot = vt * 0.03  # 미세 회전
    for layer in range(2):
        angle = bind_rot + layer * _math.pi / 4
        hw = 28 + layer * 4
        for thick in range(2):
            # 밧줄 가닥
            sx = bx + int(_math.cos(angle) * hw)
            sy = by + int(_math.sin(angle) * hw * 0.4) - 5
            ex = bx - int(_math.cos(angle) * hw)
            ey = by - int(_math.sin(angle) * hw * 0.4) - 5
            c = rope_dark if thick == 0 else rope_color
            offset = 1 if thick == 0 else 0
            pygame.draw.line(screen, c, (sx + offset, sy + offset), (ex + offset, ey + offset),
                           3 if thick == 0 else 2)

    # 3) 매듭 (중앙)
    knot_pulse = 0.9 + 0.1 * _math.sin(vt * 0.25)
    knot_r = max(3, int(5 * knot_pulse))
    pygame.draw.circle(screen, rope_dark, (bx + 1, by - 4), knot_r)
    pygame.draw.circle(screen, rope_light, (bx, by - 5), knot_r)
    pygame.draw.circle(screen, rope_color, (bx, by - 5), knot_r, 1)

    # 4) 남은 시간 표시 (밧줄 테두리 원 — 시간에 따라 줄어듦)
    remain_ratio = max(0, arrest_rope_timer / 180.0)
    arc_r = 35
    arc_start = -_math.pi / 2
    arc_end = arc_start + 2 * _math.pi * remain_ratio
    arc_segments = max(4, int(24 * remain_ratio))
    if arc_segments > 1:
        for i in range(arc_segments):
            a1 = arc_start + (arc_end - arc_start) * i / arc_segments
            a2 = arc_start + (arc_end - arc_start) * (i + 1) / arc_segments
            px1 = bx + int(_math.cos(a1) * arc_r)
            py1 = by - 5 + int(_math.sin(a1) * arc_r)
            px2 = bx + int(_math.cos(a2) * arc_r)
            py2 = by - 5 + int(_math.sin(a2) * arc_r)
            alpha_val = int(180 * remain_ratio)
            pygame.draw.line(screen, (175, 145, 95, alpha_val), (px1, py1), (px2, py2), 2)

def _draw_rope_miss(screen, boss_cx, boss_cy, rope_color, rope_dark, vt):
    """포승줄 미스 — 밧줄이 바닥에 떨어지는 연출"""
    import math as _math
    tx = arrest_rope_target_x
    ty = arrest_rope_target_y

    # 미스 타이머 진행 (30→0)
    miss_progress = 1.0 - (arrest_rope_timer / 30.0)  # 0→1

    # 밧줄이 바닥으로 처지면서 사라짐
    droop = miss_progress * 80  # 아래로 처짐
    fade = max(0, 1.0 - miss_progress * 1.5)  # 페이드아웃

    if fade <= 0:
        return

    # 보스→목표 밧줄 (처지면서)
    segments = 10
    for i in range(segments):
        t1 = i / segments
        t2 = (i + 1) / segments
        x1 = boss_cx + (tx - boss_cx) * t1
        y1 = boss_cy + (ty - boss_cy) * t1
        x2 = boss_cx + (tx - boss_cx) * t2
        y2 = boss_cy + (ty - boss_cy) * t2
        # 전체적으로 아래로 처짐 (끝쪽 더 많이)
        droop1 = droop * t1 * t1
        droop2 = droop * t2 * t2
        sag1 = _math.sin(t1 * _math.pi) * (30 + droop * 0.5)
        sag2 = _math.sin(t2 * _math.pi) * (30 + droop * 0.5)
        alpha = int(200 * fade)
        c = (int(175 * fade), int(145 * fade), int(95 * fade))
        w = max(1, int(2 * fade))
        pygame.draw.line(screen, c,
                        (int(x1), int(y1 + sag1 + droop1)),
                        (int(x2), int(y2 + sag2 + droop2)), w)

    # 올가미 (바닥에 펼쳐짐)
    lasso_x = int(tx)
    lasso_y = int(ty + droop * 0.3)
    lasso_r = max(3, int(12 * fade))
    # 펼쳐지는 원 (miss 시 넓어짐)
    spread_r = lasso_r + int(miss_progress * 8)
    c_fade = (int(175 * fade), int(145 * fade), int(95 * fade))
    pygame.draw.circle(screen, c_fade, (lasso_x, lasso_y), spread_r, max(1, int(2 * fade)))

    # "실패!" 텍스트 (미스 시 잠깐 표시)
    if miss_progress < 0.6:
        text_alpha = int(255 * (1.0 - miss_progress / 0.6))
        try:
            miss_font = pygame.font.Font(None, 20)
            miss_surf = miss_font.render("Miss!", True, (200, 160, 100))
            miss_surf.set_alpha(text_alpha)
            screen.blit(miss_surf, (lasso_x - miss_surf.get_width() // 2, lasso_y - 20))
        except Exception:
            pass


def _draw_rope_releasing(screen, boss_cx, boss_cy, rope_color, rope_dark, rope_light, vt):
    """포승줄 끊어지는 연출 — 밧줄이 중간에서 끊어져 양쪽으로 튕겨나감"""
    import math as _math
    release_duration = 28
    progress = 1.0 - (arrest_rope_timer / release_duration)  # 0→1

    bind_x = arrest_rope_bind_x
    bind_y = arrest_rope_bind_y
    cur_boss_cx = float(BOSS.centerx if BOSS else WIDTH // 2)
    cur_boss_cy = float(BOSS.y + BOSS.height if BOSS else 65)

    # 끊어지는 지점 (밧줄 중간)
    snap_t = 0.45  # 약간 플레이어 쪽에서 끊김
    snap_x = cur_boss_cx + (bind_x - cur_boss_cx) * snap_t
    snap_y = cur_boss_cy + (bind_y - cur_boss_cy) * snap_t

    fade = max(0, 1.0 - progress * 1.2)
    if fade <= 0:
        return

    # 끊어지는 순간 반동 (양쪽으로 튕김)
    recoil = _math.sin(progress * _math.pi) * 40  # 포물선 튕김
    shake = _math.sin(progress * 30) * max(0, 8 * (1.0 - progress * 2))  # 초반 진동

    # === 보스 쪽 밧줄 (끊어진 위쪽 절반 — 위로 튕겨 올라감) ===
    boss_segments = 8
    for i in range(boss_segments):
        t1 = i / boss_segments
        t2 = (i + 1) / boss_segments
        x1 = cur_boss_cx + (snap_x - cur_boss_cx) * t1
        y1 = cur_boss_cy + (snap_y - cur_boss_cy) * t1
        x2 = cur_boss_cx + (snap_x - cur_boss_cx) * t2
        y2 = cur_boss_cy + (snap_y - cur_boss_cy) * t2
        # 끊어진 끝쪽이 위로 튕김 + 처짐
        recoil1 = -recoil * t1 * t1 * 0.5
        recoil2 = -recoil * t2 * t2 * 0.5
        sag1 = _math.sin(t1 * _math.pi) * (15 + progress * 20) * fade
        sag2 = _math.sin(t2 * _math.pi) * (15 + progress * 20) * fade
        w = max(1, int(3 * fade))
        c = (int(175 * fade), int(145 * fade), int(95 * fade))
        pygame.draw.line(screen, c,
                        (int(x1 + shake * t1), int(y1 + sag1 + recoil1)),
                        (int(x2 + shake * t2), int(y2 + sag2 + recoil2)), w)

    # 보스쪽 끊어진 끝 — 너덜너덜한 끝
    boss_end_x = int(snap_x + shake)
    boss_end_y = int(snap_y - recoil * 0.25)
    for strand in range(3):
        strand_angle = _math.pi * 0.5 + (strand - 1) * 0.5 + progress * 2
        strand_len = int(6 * fade)
        sx = boss_end_x + int(_math.cos(strand_angle) * strand_len)
        sy = boss_end_y + int(_math.sin(strand_angle) * strand_len)
        c = (int(175 * fade), int(145 * fade), int(95 * fade))
        pygame.draw.line(screen, c, (boss_end_x, boss_end_y), (sx, sy), max(1, int(2 * fade)))

    # === 플레이어 쪽 밧줄 (끊어진 아래쪽 — 아래로 떨어짐) ===
    player_segments = 6
    droop = progress * 60  # 아래로 처짐
    for i in range(player_segments):
        t1 = i / player_segments
        t2 = (i + 1) / player_segments
        x1 = snap_x + (bind_x - snap_x) * t1
        y1 = snap_y + (bind_y - snap_y) * t1
        x2 = snap_x + (bind_x - snap_x) * t2
        y2 = snap_y + (bind_y - snap_y) * t2
        # 아래로 떨어지면서 처짐
        droop1 = droop * t1
        droop2 = droop * t2
        sag1 = _math.sin(t1 * _math.pi) * 10 * fade
        sag2 = _math.sin(t2 * _math.pi) * 10 * fade
        w = max(1, int(2 * fade))
        c = (int(175 * fade), int(145 * fade), int(95 * fade))
        pygame.draw.line(screen, c,
                        (int(x1 - shake * t1), int(y1 + sag1 + droop1)),
                        (int(x2 - shake * t2), int(y2 + sag2 + droop2)), w)

    # === 플레이어 주변 묶인 밧줄 풀리는 이펙트 ===
    unbind_expand = progress * 25  # 풀리면서 넓어짐
    unbind_alpha = int(180 * fade)
    if unbind_alpha > 0:
        unbind_r = int(30 + unbind_expand)
        c = (int(175 * fade), int(145 * fade), int(95 * fade))
        pygame.draw.circle(screen, c, (int(bind_x), int(bind_y) - 5),
                         unbind_r, max(1, int(2 * fade)))
        # 풀어지는 밧줄 파편 (작은 조각들)
        for frag in range(4):
            frag_angle = frag * _math.pi / 2 + progress * 3
            frag_dist = unbind_expand * 0.8 + 10
            fx = int(bind_x + _math.cos(frag_angle) * frag_dist)
            fy = int(bind_y - 5 + _math.sin(frag_angle) * frag_dist + droop * 0.3)
            frag_len = max(2, int(5 * fade))
            fx2 = fx + int(_math.cos(frag_angle + 0.5) * frag_len)
            fy2 = fy + int(_math.sin(frag_angle + 0.5) * frag_len)
            pygame.draw.line(screen, c, (fx, fy), (fx2, fy2), max(1, int(2 * fade)))

    # === 끊어지는 지점 — 스파크 이펙트 (초반만) ===
    if progress < 0.3:
        spark_alpha = int(255 * (1.0 - progress / 0.3))
        spark_r = max(3, int(8 * (1.0 - progress / 0.3)))
        spark_surf = pygame.Surface((spark_r * 2, spark_r * 2), pygame.SRCALPHA)
        pygame.draw.circle(spark_surf, (255, 230, 170, spark_alpha), (spark_r, spark_r), spark_r)
        screen.blit(spark_surf, (int(snap_x) - spark_r, int(snap_y) - spark_r))


def activate_whip():
    global whip_active, whip_timer, whip_wave_phase, whip_original_ball_speed, whip_wave_particles

    whip_active = True
    whip_timer = whip_duration
    whip_wave_phase = 0  # 사인 파형 초기화
    #  상모돌리기 발동 전 공 속도 저장 (Y축만 원래 속도 유지)
    whip_original_ball_speed = [0, ball_vel[1]]  # X축은 0으로 설정
    
    #  파동 파티클 초기화 - 보스에서 플레이어를 향해 나아가는 파동
    whip_wave_particles = []
    
    # 효과음이 처음 발동될 때만 플레이 (무한 반복하지 않고 제한된 시간 동안만)
    whip_sound.play(loops=0)  # 한 번만 재생하고 타이머로 제어
    
    #  X축 속도를 거의 0으로 설정 (일직선 아래로)
    ball_vel[0] = 0
    
    # Y축 속도 조정 (적당한 속도로 아래로)
    ball_vel[1] = abs(ball_vel[1]) * 0.75
    
    #  공이 무조건 플레이어 쪽(아래)으로 향하도록 Y 속도 보정
    if ball_vel[1] < 0:  # 공이 위쪽으로 가고 있다면
        ball_vel[1] = abs(ball_vel[1])  # 아래쪽으로 방향 전환
    # 최소 Y 속도 보장 (너무 수평으로 가지 않도록)
    if abs(ball_vel[1]) < 8:
        ball_vel[1] = 8


def cancel_whip_with_umbrella_block() -> bool:
    """발토르 토르쉴드로 스테이지 1 상모돌리기를 강제 종료."""

    global whip_active, whip_deactivation_active, whip_deactivation_timer
    global whip_deactivation_duration, whip_rotation_speed, whip_animation_timer

    if current_stage != 1:
        return False

    # 스테이지 1 보스가 상모돌리기를 사용 중이 아닐 때는 강제 종료 로직을 건너뛴다.
    if not whip_active and not whip_deactivation_active:
        return False

    changed = False

    if whip_active:
        deactivate_whip()
        whip_animation_timer = 0
        changed = True

    if not whip_deactivation_active:
        whip_deactivation_active = True
        changed = True

    if whip_deactivation_timer < whip_deactivation_duration:
        whip_deactivation_timer = whip_deactivation_duration
        changed = True

    if whip_rotation_speed < 20.0:
        whip_rotation_speed = 20.0
        changed = True

    return changed


def handle_whip():
    global whip_active, whip_timer, whip_wave_phase, whip_hit_by_player, whip_wave_particles
    global whip_deactivation_active, whip_deactivation_timer, whip_rotation_speed
    global boss_stunned_after_whip, boss_stunned_after_whip_timer, whip_animation_timer
    
    # 보스 후딜 상태 처리 (회전 종료 후)
    if boss_stunned_after_whip:
        if boss_stunned_after_whip_timer > 0:
            boss_stunned_after_whip_timer -= 1
        else:
            boss_stunned_after_whip = False
    
    # 강제 해제 모션 처리
    if whip_deactivation_active:
        # 강제 해제 시작 시 사운드 즉시 중지
        if whip_deactivation_timer == whip_deactivation_duration:
            whip_sound.stop()
            
        if whip_deactivation_timer > 0:
            whip_deactivation_timer -= 1
            # 회전 속도를 점차 감소 (이징 효과 적용)
            progress = 1.0 - (whip_deactivation_timer / whip_deactivation_duration)
            # 이징 함수 (ease-out cubic)
            eased_progress = 1.0 - pow(1.0 - progress, 3)
            whip_rotation_speed = (1.0 - eased_progress) * 20.0  # 20에서 0으로 감소 (더 빠른 회전)
            
            # 남은 파동 파티클 업데이트 (점차 사라짐)
            for particle in whip_wave_particles[:]:
                particle['alpha'] -= 8  # 천천히 사라짐 (1.2초 동안)
                particle['radius'] += 3
                if particle['alpha'] <= 0:
                    whip_wave_particles.remove(particle)
        else:
            # 강제 해제 모션 완료 - 후딜 상태 시작
            whip_deactivation_active = False
            whip_rotation_speed = 0.0
            whip_wave_particles.clear()

            # 이동도 완전히 멈춤
            global boss_current_speed
            boss_current_speed = 0
            if ULTRA_SMOOTH_AVAILABLE:
                try:
                    smoother = get_ultra_smooth_movement()
                    smoother.physics.velocity = 0.0
                except Exception:
                    pass
            
            # 0.5초 후딜 상태 시작
            boss_stunned_after_whip = True
            boss_stunned_after_whip_timer = 30  # 0.5초
    
    if whip_active:
        if whip_timer > 0:
            whip_timer -= 1  # 타이머 감소 (효과음의 지속시간)
            old_wave_phase = whip_wave_phase

            # 광폭화 보스일 때 상모돌리기 속도 1.5배 증가
            wave_speed = 0.45 if enraged_boss_active else 0.3
            whip_wave_phase += wave_speed  # 사인 함수로 진폭 파형 진행

            # 공이 한 바퀴 돌 때마다 효과음 재생 (사인파가 2π를 넘을 때)
            if int(old_wave_phase / (2 * math.pi)) < int(whip_wave_phase / (2 * math.pi)):
                whip_sound.play()

            # 광폭화 보스일 때 진폭도 1.5배 증가 (더 격렬한 휙휙거림)
            wave_amplitude = 22.5 if enraged_boss_active else 15
            # 진폭 계산 (사인 함수에 의해 -1에서 1 사이의 값을 가짐)
            wave = math.sin(whip_wave_phase) * wave_amplitude  # 좌우 흔들림
            # 볼륨 조정 제거 - 사운드가 계속 재생되는 문제 방지
            # 공의 속도에 진폭 적용 (X축만 약간 물결치도록)
            # 파워스매싱이 활성화되어 있지 않을 때만 상모돌리기 효과 적용
            if not power_smashing_parabola_active and not power_smashing_freeze_active:
                ball_vel[0] = wave  # 원래 속도 무시하고 파동만 적용 (중앙 기준)
            
            #  파동 파티클 생성 (10프레임마다)
            if whip_timer % 10 == 0:
                # 보스 위치에서 플레이어 방향으로 파동 생성
                whip_wave_particles.append({
                    'x': BOSS.centerx,
                    'y': BOSS.centery,
                    'radius': 10,
                    'alpha': 255,
                    'speed': 8  # 파동이 퍼지는 속도
                })
            
            # 파동 파티클 업데이트
            for particle in whip_wave_particles[:]:
                # 파동이 플레이어 패들 방향으로 이동
                direction_to_player_y = PLAYER.centery - particle['y']
                direction_to_player_x = PLAYER.centerx - particle['x']
                distance = math.sqrt(direction_to_player_x**2 + direction_to_player_y**2)
                
                if distance > 0:
                    # 정규화된 방향 벡터
                    dir_x = direction_to_player_x / distance
                    dir_y = direction_to_player_y / distance
                    
                    # 파동 이동
                    particle['y'] += dir_y * particle['speed']
                    particle['x'] += dir_x * particle['speed'] * 0.3  # X축은 덜 움직임
                    particle['radius'] += 2  # 파동이 퍼짐
                    particle['alpha'] -= 8  # 점점 투명해짐
                    
                    # 알파값이 0이 되면 제거
                    if particle['alpha'] <= 0:
                        whip_wave_particles.remove(particle)
            
            #  플레이어가 반격한 경우와 아닌 경우를 구분
            if not whip_hit_by_player:
                # 플레이어가 아직 반격하지 않은 경우: 공은 아래쪽(플레이어 방향)으로
                if ball_vel[1] < 0:  # 만약 공이 위로 가려고 하면
                    ball_vel[1] = abs(whip_original_ball_speed[1]) if whip_original_ball_speed[1] != 0 else 10
                # 최소 Y 속도 보장 (너무 수평으로 가지 않도록)
                if abs(ball_vel[1]) < 5:
                    ball_vel[1] = 5
            else:
                # 플레이어가 반격한 경우: 공은 위쪽(보스 방향)으로 유지
                if ball_vel[1] > 0:  # 만약 공이 아래로 가려고 하면
                    ball_vel[1] = -abs(ball_vel[1])  # 위쪽으로 유지
                # 최소 Y 속도 보장
                if abs(ball_vel[1]) < 8:
                    ball_vel[1] = -8
        else:
            # 상모돌리기 효과 완전 종료
            if current_stage == 1 and not whip_deactivation_active:
                # 자연 종료 시에도 회전 감속 모션 + 잠깐 멈춤 연출
                whip_active = False
                whip_deactivation_active = True
                whip_deactivation_timer = whip_deactivation_duration
                whip_rotation_speed = 20.0  # 시작은 빠르게, 이후 handle_whip에서 점감
                whip_wave_particles.clear()
                whip_sound.stop()
                whip_animation_timer = 0
            else:
                deactivate_whip()  # 통합된 비활성화 함수 사용
def activate_balloon():
    """풍선 스킬 활성화"""
    global balloon_active, balloon_timer, balloons, balloon_used_this_round
    balloon_active = True
    balloon_timer = -1  # -1은 라운드 끝까지 지속
    balloons = []  # 풍선 리스트 초기화
    balloon_used_this_round = True  # 이번 라운드에 사용됨 표시
    # 화면에 3-5개의 풍선 생성
    balloon_colors = [
        (255, 100, 100),  # 빨간색
        (100, 255, 100),  # 초록색
        (100, 100, 255),  # 파란색
        (255, 255, 100),  # 노란색
        (255, 100, 255),  # 마젠타
        (100, 255, 255),  # 시안
    ]
    for i in range(random.randint(3, 5)):
        x = random.randint(100, WIDTH-100)
        y = random.randint(100, HEIGHT-100)
        radius = random.randint(25, 35)
        color = random.choice(balloon_colors)
        # 랜덤한 방향과 속도 설정
        speed = random.uniform(1.5, 3.0)
        angle = random.uniform(0, 2 * math.pi)
        vx = math.cos(angle) * speed
        vy = math.sin(angle) * speed
        balloons.append({
            "x": x, 
            "y": y, 
            "radius": radius, 
            "color": color,
            "vx": vx,
            "vy": vy,
            "bounce": 0  # 튀는 애니메이션용
        })
    show_speech("풍선 놀이!", duration=60)
def handle_balloon():
    """풍선 스킬 처리"""
    global balloon_active, balloon_timer, balloons
    if balloon_active:
        # 타이머가 -1이면 라운드 끝까지 지속
        if balloon_timer > 0:
            balloon_timer -= 1
        elif balloon_timer == 0:
            # 풍선 스킬 종료
            # balloon_active = False  # Stage 1 보스 풍선파티 스킬 제거됨
            balloons.clear()
            return
        # 풍선 움직임과 벽 충돌 처리
        for balloon in balloons:
            # 풍선 위치 업데이트
            balloon["x"] += balloon["vx"]
            balloon["y"] += balloon["vy"]
            # 튀는 애니메이션
            balloon["bounce"] += 0.2
            balloon["y"] += int(math.sin(balloon["bounce"]) * 1)
            # 벽 충돌 감지 및 튕김 처리
            if balloon["x"] - balloon["radius"] <= 0:  # 왼쪽 벽
                balloon["x"] = balloon["radius"]
                balloon["vx"] = abs(balloon["vx"])  # 오른쪽으로 튕김
            elif balloon["x"] + balloon["radius"] >= WIDTH:  # 오른쪽 벽
                balloon["x"] = WIDTH - balloon["radius"]
                balloon["vx"] = -abs(balloon["vx"])  # 왼쪽으로 튕김
            if balloon["y"] - balloon["radius"] <= 0:  # 위쪽 벽
                balloon["y"] = balloon["radius"]
                balloon["vy"] = abs(balloon["vy"])  # 아래쪽으로 튕김
            elif balloon["y"] + balloon["radius"] >= HEIGHT:  # 아래쪽 벽
                balloon["y"] = HEIGHT - balloon["radius"]
                balloon["vy"] = -abs(balloon["vy"])  # 위쪽으로 튕김
def draw_balloons():
    """풍선 그리기"""
    if not balloon_active:
        return
    for balloon in balloons:
        x, y = balloon["x"], balloon["y"]
        radius = balloon["radius"]
        color = balloon["color"]
        # 풍선 몸체
        draw.circle(color, (int(x), int(y)), radius)
        # 풍선 테두리
        draw.circle(WHITE, (int(x), int(y)), radius, 2)
        # 풍선 줄 (위쪽으로)
        line_start = (int(x), int(y - radius))
        line_end = (int(x), int(y - radius - DEFAULT_RADIUS))
        draw.line((100, 100, 100), line_start, line_end, 2)
        # 풍선 하이라이트 (반짝이는 효과)
        highlight_x = int(x - radius // 3)
        highlight_y = int(y - radius // 3)
        draw.circle(WHITE, (highlight_x, highlight_y), radius // 4)
        # 풍선 움직임 방향 표시 (작은 화살표)
        arrow_length = 8
        arrow_x = int(x + balloon["vx"] * arrow_length)
        arrow_y = int(y + balloon["vy"] * arrow_length)
        draw.line(WHITE, (int(x), int(y)), (arrow_x, arrow_y), 2)
def check_balloon_collisions():
    """풍선과 공의 충돌 감지"""
    if not balloon_active or not balloons:
        return
    for balloon in balloons[:]:  # 복사본으로 순회
        # 풍선의 중심점과 공의 중심점 사이의 거리 계산
        dx = BALL.centerx - balloon["x"]
        dy = BALL.centery - balloon["y"]
        distance = math.sqrt(dx*dx + dy*dy)
        # 충돌 감지 (공 반지름 + 풍선 반지름)
        collision_distance = BALL_RADIUS + balloon["radius"]
        if distance <= collision_distance:
            # print(f"  !  : 30")
            #  풍선 터지는 효과음 재생
            play_sound_with_volume(SOUND_BALLOON_BOOM)
            # 풍선 터뜨리기 효과
            effects_manager.create_balloon_pop_effect(balloon["x"], balloon["y"], balloon["color"])
            # 풍선 제거
            balloons.remove(balloon)
            # 현재 공의 각도 계산
            current_angle = math.atan2(ball_vel[1], ball_vel[0])
            # 30도(약 0.524 라디안) 랜덤하게 휘어지기
            angle_change = random.uniform(-0.524, 0.524)  # -30도 ~ +30도
            new_angle = current_angle + angle_change
            # 새로운 속도 계산 (현재 속도 유지)
            speed = math.sqrt(ball_vel[0]**2 + ball_vel[1]**2)
            ball_vel[0] = math.cos(new_angle) * speed
            ball_vel[1] = math.sin(new_angle) * speed
            # 속도 정규화 제거 - 현재 속도 그대로 유지
            # 충돌 후 즉시 반환 (한 번에 하나의 풍선만 처리)
            return

def activate_spinning_top():
    """Stage 1 보스 팽이치기 스킬 활성화"""
    global spinning_top_active, spinning_top_timer, spinning_tops, spinning_top_used_this_round, whip_animation_timer

    spinning_top_active = True
    spinning_top_timer = spinning_top_duration
    spinning_top_used_this_round = True
    whip_animation_timer = 36  # 0.6초 채찍 애니메이션

    # 광폭화 보스일 때 팽이 4개, 아닐 때 2개
    top_count = 4 if enraged_boss_active else 2

    # 팽이 생성 위치 설정
    if top_count == 4:
        # 4개일 때: 좌, 중좌, 중우, 우
        offsets = [-60, -20, 20, 60]
    else:
        # 2개일 때: 좌, 우
        offsets = [-30, 30]

    spinning_tops = []
    for i in range(top_count):
        offset_x = offsets[i]
        # 15% 확률로 황금 팽이 생성 (각각 독립적으로)
        is_golden = random.random() < 0.15
        spinning_tops.append({
            "x": BOSS.centerx + offset_x,
            "y": BOSS.centery + 40,  # 보스 아래쪽
            "vx": random.uniform(-0.5, 0.5),  # 초기 좌우 속도
            "vy": 0.4,  # 천천히 아래로
            "rotation": random.uniform(0, 360),  # 랜덤 시작 회전
            "rotation_speed": 20,  # 회전 속도
            "tilt": 0,  # 기울기
            "alpha": 255,  # 투명도
            "whip_phase": "preparing",  # 채찍 애니메이션 단계
            "zigzag_timer": i * 10,  # 서로 다른 지그재그 타이밍
            "speed_boost": 0,  # 충돌 시 속도 부스트
            "boost_timer": 0,  # 부스트 지속 시간
            "is_golden": is_golden,  # 황금 팽이 여부
            "star_spawned": False  # 별을 이미 생성했는지 여부
        })
        if is_golden:
            pass  # print(f"🎲 황금 팽이 생성! (팽이 {i+1})")

    # 채찍 효과음 재생
    whip_sound.play(maxtime=600)  # 0.6초 재생

    if enraged_boss_active:
        pass  # print(f"🔥 [광폭화] 팽이치기! 4개 팽이 생성!")
    else:
        pass  # print(f"🎯 팽이치기! 2개 팽이 생성!")

# === 각시탈 부채던지기 스킬 ===
def activate_fan_throw():
    """부채던지기 발동 — 0.5초 휘두르기 애니메이션 후 투사체 발사"""
    global fan_throw_windup_active, fan_throw_windup_timer
    global fan_throw_hit
    fan_throw_windup_active = True
    fan_throw_windup_timer = 30  # 0.5초 선딜
    fan_throw_hit = False


def _launch_fan_throw():
    """휘두르기 완료 후 실제 투사체 발사"""
    global fan_throw_active, fan_throw_x, fan_throw_y, fan_throw_vx, fan_throw_vy
    global fan_throw_spin, fan_throw_timer, fan_throw_hit
    global fan_throw_extra_projectiles
    fan_throw_active = True
    fan_throw_hit = False
    fan_throw_timer = 180  # 3초 최대 지속

    # 보스 위치에서 출발
    boss_cx = float(BOSS.centerx if BOSS else WIDTH // 2)
    boss_cy = float((BOSS.y + BOSS.height) if BOSS else 65)
    fan_throw_x = boss_cx
    fan_throw_y = boss_cy

    # 플레이어를 향해 발사 (약간 예측 포함)
    player_cx = float(PLAYER.centerx if PLAYER else WIDTH // 2)
    player_cy = float(PLAYER.centery if PLAYER else 710)
    dx = player_cx - boss_cx
    dy = player_cy - boss_cy
    dist = math.sqrt(dx * dx + dy * dy)
    if dist < 1:
        dist = 1
    speed = 5.5
    fan_throw_vx = (dx / dist) * speed + random.uniform(-0.8, 0.8)
    fan_throw_vy = (dy / dist) * speed
    fan_throw_spin = 0.0

    # 광폭화 시 양옆 35도 방향으로 추가 부채 2개 발사
    fan_throw_extra_projectiles = []
    if enraged_boss_active:
        base_angle = math.atan2(dy, dx)
        for offset_deg in [-35, 35]:
            angle = base_angle + math.radians(offset_deg)
            evx = math.cos(angle) * speed + random.uniform(-0.4, 0.4)
            evy = math.sin(angle) * speed
            fan_throw_extra_projectiles.append({
                "x": boss_cx, "y": boss_cy,
                "vx": evx, "vy": evy,
                "spin": 0.0, "timer": 180, "hit": False
            })


def update_fan_throw():
    """부채던지기 휘두르기 + 투사체 이동 + 충돌"""
    global fan_throw_active, fan_throw_x, fan_throw_y, fan_throw_spin, fan_throw_timer
    global fan_throw_hit, fan_throw_knockback_timer, fan_throw_knockback_dir
    global fan_throw_windup_active, fan_throw_windup_timer
    global fan_throw_hit_effect_timer, fan_throw_hit_effect_x, fan_throw_hit_effect_y
    global player_knockback_vel

    # --- 타격 이펙트 카운트다운 (독립) ---
    if fan_throw_hit_effect_timer > 0:
        fan_throw_hit_effect_timer -= 1

    # --- 휘두르기 선딜 처리 ---
    if fan_throw_windup_active:
        fan_throw_windup_timer -= 1
        if fan_throw_windup_timer <= 0:
            fan_throw_windup_active = False
            _launch_fan_throw()
        return

    if not fan_throw_active and not fan_throw_extra_projectiles:
        return

    # --- 메인 부채 업데이트 ---
    if fan_throw_active:
        fan_throw_timer -= 1
        prev_spin = fan_throw_spin
        fan_throw_spin += 0.3
        # 회전할 때마다 부채 사운드 재생 (2π 경계를 넘을 때)
        TWO_PI = math.pi * 2
        if int(prev_spin / TWO_PI) < int(fan_throw_spin / TWO_PI):
            if SOUND_FAN:
                SOUND_FAN.set_volume(0.35)
                SOUND_FAN.play()

        # 나비 날갯짓 패턴 이동 (빠르게↔느리게 반복 + 좌우 사행)
        elapsed = 180 - fan_throw_timer  # 경과 프레임
        speed_mod = 0.6 + 0.5 * math.sin(elapsed * 0.25)  # 0.1~1.1 속도 변조
        sway = math.sin(elapsed * 0.15) * 1.8  # 좌우 사행
        fan_throw_x += fan_throw_vx * speed_mod + sway
        fan_throw_y += fan_throw_vy * speed_mod * 1.3  # Y축 30% 빠르게

        # 게임 영역 밖 소멸
        if (fan_throw_x < GAME_AREA_OFFSET_X - 30 or fan_throw_x > GAME_AREA_OFFSET_X + GAME_PLAY_WIDTH + 30
                or fan_throw_y > HEIGHT + 30 or fan_throw_y < -30):
            fan_throw_active = False

        elif fan_throw_timer <= 0:
            fan_throw_active = False

    # 플레이어 충돌 체크 (메인 부채)
    if not fan_throw_hit and PLAYER:
        hit_radius = 24
        px = PLAYER.centerx
        py = PLAYER.centery
        dx = fan_throw_x - px
        dy = fan_throw_y - py
        dist_sq = dx * dx + dy * dy
        if dist_sq < (hit_radius + PLAYER.width // 2) ** 2:
            fan_throw_hit = True
            fan_throw_active = False
            # 부채던지기 타격 사운드
            if SOUND_WHIPCRACK:
                SOUND_WHIPCRACK.set_volume(0.6)
                SOUND_WHIPCRACK.play()
            # 화염탄 방식 넉백
            if player_stun_immunity_timer <= 0:
                if try_apply_player_stun(0.3, source="stage1_fan_throw", knockback_scaled=True) > 0:
                    player_knockback_vel = apply_knockback_resist(_scale_knockback(random.choice([-12, 12])))
            # 독립 타격 이펙트 시작
            fan_throw_hit_effect_timer = 24
            fan_throw_hit_effect_x = float(px)
            fan_throw_hit_effect_y = float(py)
            show_speech("맞았지롱~!", duration=60)

    # --- 광폭화 추가 부채 투사체 업데이트 ---
    for proj in fan_throw_extra_projectiles[:]:
        proj["timer"] -= 1
        prev_sp = proj["spin"]
        proj["spin"] += 0.3
        # 회전 시 부채 사운드
        if int(prev_sp / (math.pi * 2)) < int(proj["spin"] / (math.pi * 2)):
            if SOUND_FAN:
                SOUND_FAN.set_volume(0.25)
                SOUND_FAN.play()
        elapsed_p = 180 - proj["timer"]
        speed_mod_p = 0.6 + 0.5 * math.sin(elapsed_p * 0.25)
        sway_p = math.sin(elapsed_p * 0.15) * 1.8
        proj["x"] += proj["vx"] * speed_mod_p + sway_p
        proj["y"] += proj["vy"] * speed_mod_p * 1.3

        # 영역 밖 소멸
        if (proj["x"] < -30 or proj["x"] > WIDTH + 30
                or proj["y"] > HEIGHT + 30 or proj["y"] < -30
                or proj["timer"] <= 0):
            fan_throw_extra_projectiles.remove(proj)
            continue

        # 플레이어 충돌
        if not proj["hit"] and PLAYER:
            hit_r = 24
            ppx = PLAYER.centerx
            ppy = PLAYER.centery
            ddx = proj["x"] - ppx
            ddy = proj["y"] - ppy
            if ddx * ddx + ddy * ddy < (hit_r + PLAYER.width // 2) ** 2:
                proj["hit"] = True
                fan_throw_extra_projectiles.remove(proj)
                if SOUND_WHIPCRACK:
                    SOUND_WHIPCRACK.set_volume(0.5)
                    SOUND_WHIPCRACK.play()
                if player_stun_immunity_timer <= 0:
                    if try_apply_player_stun(0.3, source="stage1_fan_throw", knockback_scaled=True) > 0:
                        player_knockback_vel = apply_knockback_resist(_scale_knockback(random.choice([-12, 12])))
                fan_throw_hit_effect_timer = 24
                fan_throw_hit_effect_x = float(ppx)
                fan_throw_hit_effect_y = float(ppy)


def _draw_fan_shape(screen, cx, cy, angle, size, alpha=255):
    """부채 모양 그리기 유틸리티 (투사체, 휘두르기 공용)"""
    surf_sz = size * 3
    fan_surf = pygame.Surface((surf_sz, surf_sz), pygame.SRCALPHA)
    fc = surf_sz // 2
    num_ribs = 6
    spread = math.radians(70)
    start_a = angle - spread / 2
    fan_r = size * 1.4

    fan_pts = [(fc, fc)]
    for i in range(num_ribs + 1):
        a = start_a + spread * i / num_ribs
        fan_pts.append((int(fc + math.cos(a) * fan_r), int(fc + math.sin(a) * fan_r)))

    if len(fan_pts) >= 3:
        shadow = [(x + 1, y + 1) for x, y in fan_pts]
        pygame.draw.polygon(fan_surf, (80, 60, 40, min(120, alpha)), shadow)
        pygame.draw.polygon(fan_surf, (220, 200, 160, alpha), fan_pts)
        pygame.draw.polygon(fan_surf, (185, 55, 55, alpha), fan_pts, 2)

    for i in range(num_ribs):
        a = start_a + spread * i / (num_ribs - 1)
        rx = fc + math.cos(a) * fan_r
        ry = fc + math.sin(a) * fan_r
        pygame.draw.line(fan_surf, (140, 110, 70, alpha), (fc, fc), (int(rx), int(ry)), 1)

    screen.blit(fan_surf, (cx - fc, cy - fc))


def draw_fan_throw_effect(screen):
    """부채던지기 전체 렌더링 (휘두르기 + 투사체 + 타격 이펙트)"""
    # --- 1) 휘두르기 애니메이션 (0.5초) ---
    if fan_throw_windup_active and BOSS:
        progress = 1.0 - (fan_throw_windup_timer / 30.0)  # 0→1
        boss_cx = BOSS.centerx
        boss_cy = BOSS.y + BOSS.height + 5

        # 부채를 좌→우→좌 빠르게 휘두르기 (사인파 3회)
        swing_angle = math.sin(progress * math.pi * 6) * math.radians(60) + math.pi * 0.5
        fan_size = int(12 + 4 * progress)  # 약간 커짐
        _draw_fan_shape(screen, boss_cx, boss_cy, swing_angle, fan_size)

        # 잔상 트레일 (2개)
        for trail_i in range(1, 3):
            trail_p = max(0.0, progress - trail_i * 0.06)
            trail_angle = math.sin(trail_p * math.pi * 6) * math.radians(60) + math.pi * 0.5
            trail_alpha = max(30, 120 - trail_i * 45)
            _draw_fan_shape(screen, boss_cx, boss_cy, trail_angle, fan_size - trail_i, trail_alpha)

        # 바람 이펙트 선 (좌우로 펄럭)
        wind_alpha = int(100 * progress)
        for wi in range(4):
            wy = boss_cy + 4 + wi * 6
            wx_off = math.sin(progress * math.pi * 8 + wi * 0.8) * 18
            pygame.draw.line(screen, (200, 220, 255, wind_alpha),
                             (boss_cx - 15 + int(wx_off), wy), (boss_cx + 15 + int(wx_off), wy), 1)

    # --- 2) 투사체 ---
    if fan_throw_active:
        _draw_fan_shape(screen, int(fan_throw_x), int(fan_throw_y), fan_throw_spin, 28)

    # --- 2b) 광폭화 추가 부채 투사체 ---
    for proj in fan_throw_extra_projectiles:
        _draw_fan_shape(screen, int(proj["x"]), int(proj["y"]), proj["spin"], 24)

    # --- 3) 독립 타격 이펙트 ---
    if fan_throw_hit_effect_timer > 0:
        max_dur = 24.0
        progress = fan_throw_hit_effect_timer / max_dur  # 1→0
        hx = int(fan_throw_hit_effect_x)
        hy = int(fan_throw_hit_effect_y)

        # 충격파 링 (바깥으로 퍼짐)
        ring_r = int(12 + 50 * (1.0 - progress))
        ring_alpha = int(200 * progress)
        ring_w = max(2, int(4 * progress))
        ring_s = pygame.Surface((ring_r * 2 + 4, ring_r * 2 + 4), pygame.SRCALPHA)
        pygame.draw.circle(ring_s, (255, 200, 100, ring_alpha), (ring_r + 2, ring_r + 2), ring_r, ring_w)
        screen.blit(ring_s, (hx - ring_r - 2, hy - ring_r - 2))

        # 두 번째 충격파 (약간 지연)
        if progress < 0.8:
            r2_p = progress / 0.8
            r2_r = int(8 + 35 * (1.0 - r2_p))
            r2_a = int(140 * r2_p)
            r2_s = pygame.Surface((r2_r * 2 + 4, r2_r * 2 + 4), pygame.SRCALPHA)
            pygame.draw.circle(r2_s, (255, 160, 80, r2_a), (r2_r + 2, r2_r + 2), r2_r, max(1, int(3 * r2_p)))
            screen.blit(r2_s, (hx - r2_r - 2, hy - r2_r - 2))

        # 초반 강한 플래시
        if fan_throw_hit_effect_timer > 18:
            flash_p = (fan_throw_hit_effect_timer - 18) / 6.0
            flash_r = int(35 * flash_p)
            if flash_r > 0:
                flash_s = pygame.Surface((flash_r * 2, flash_r * 2), pygame.SRCALPHA)
                pygame.draw.circle(flash_s, (255, 255, 220, int(200 * flash_p)), (flash_r, flash_r), flash_r)
                screen.blit(flash_s, (hx - flash_r, hy - flash_r))

        # 타격 스파크 파편 (10방향, 방사형)
        if fan_throw_hit_effect_timer > 12:
            spark_t = (fan_throw_hit_effect_timer - 12) / 12.0
            for si in range(10):
                sa = si * math.pi * 2 / 10 + 0.2
                sd = 8 + 40 * (1.0 - spark_t)
                sx = hx + int(math.cos(sa) * sd)
                sy = hy + int(math.sin(sa) * sd)
                spark_len = max(2, int(8 * spark_t))
                ex = sx + int(math.cos(sa) * spark_len)
                ey = sy + int(math.sin(sa) * spark_len)
                spark_c = (255, 230, 130, min(255, int(240 * spark_t)))
                pygame.draw.line(screen, spark_c, (sx, sy), (ex, ey), 2)

        # 부채 조각 파편 (히트 시 부채가 부서지는 느낌)
        if fan_throw_hit_effect_timer > 14:
            frag_t = (fan_throw_hit_effect_timer - 14) / 10.0
            for fi in range(5):
                fa = fi * math.pi * 2 / 5 + progress * 2
                fd = 6 + 25 * (1.0 - frag_t)
                fx = hx + int(math.cos(fa) * fd)
                fy_pos = hy + int(math.sin(fa) * fd)
                frag_sz = max(2, int(5 * frag_t))
                frag_a = int(180 * frag_t)
                fs = pygame.Surface((frag_sz * 2, frag_sz * 2), pygame.SRCALPHA)
                # 부채 색상 조각
                pygame.draw.polygon(fs, (220, 200, 160, frag_a),
                                    [(0, frag_sz), (frag_sz, 0), (frag_sz * 2, frag_sz)])
                screen.blit(fs, (fx - frag_sz, fy_pos - frag_sz))

        # 붉은 테두리 플래시 (플레이어 주변)
        if fan_throw_hit_effect_timer > 18 and PLAYER:
            edge_p = (fan_throw_hit_effect_timer - 18) / 6.0
            edge_alpha = int(120 * edge_p)
            edge_s = pygame.Surface((PLAYER.width + 14, PLAYER.height + 14), pygame.SRCALPHA)
            pygame.draw.rect(edge_s, (255, 80, 80, edge_alpha), edge_s.get_rect(), 3, border_radius=4)
            screen.blit(edge_s, (PLAYER.x - 7, PLAYER.y - 7))



# === 멘헤라걸 저주 보물상자 스킬 (Curse Chest) - Stage 3 ===
def activate_curse_chest():
    """저주 보물상자 발동 — 0.5초 선딜 후 보스 위치에서 투척"""
    global curse_chest_windup_active, curse_chest_windup_timer
    global curse_chest_target_x, curse_chest_target_y
    curse_chest_windup_active = True
    curse_chest_windup_timer = CURSE_CHEST_WINDUP_FRAMES
    # 착지 목표 좌표 미리 결정
    curse_chest_target_x = random.uniform(GAME_AREA_OFFSET_X + 60, GAME_AREA_OFFSET_X + GAME_PLAY_WIDTH - 60)
    curse_chest_target_y = random.uniform(700, 730)
    try:
        snd = pygame.mixer.Sound(resource_path(os.path.join("sounds", "dollcurse.wav")))
        snd.set_volume(0.3 * sfx_volume)
        snd.play()
    except Exception:
        pass


def _launch_curse_chest():
    """선딜 완료 후 보스 위치에서 상자 투사체 발사"""
    global curse_chest_throwing, curse_chest_throw_progress
    global curse_chest_throw_x, curse_chest_throw_y
    global curse_chest_throw_start_x, curse_chest_throw_start_y
    curse_chest_throwing = True
    curse_chest_throw_progress = 0.0
    # 보스 패들 중앙에서 발사
    curse_chest_throw_start_x = float(BOSS.centerx if BOSS else WIDTH // 2)
    curse_chest_throw_start_y = float((BOSS.bottom + 10) if BOSS else 70)
    curse_chest_throw_x = curse_chest_throw_start_x
    curse_chest_throw_y = curse_chest_throw_start_y


def _trigger_curse_chest_explode():
    """보물상자 자동 폭발 — 4초 미개방 시 파편과 함께 소멸"""
    global curse_chest_exploding, curse_chest_explode_timer, curse_chest_explode_particles
    global curse_chest_opened, curse_chest_lifetime_timer, player_knockback_vel
    curse_chest_exploding = True
    curse_chest_explode_timer = CURSE_CHEST_EXPLODE_DURATION
    curse_chest_explode_particles = []
    # 파편 파티클 생성
    for _ in range(15):
        angle = random.uniform(0, math.pi * 2)
        speed = random.uniform(2, 6)
        curse_chest_explode_particles.append({
            "x": curse_chest_x + random.uniform(-5, 5),
            "y": curse_chest_y + random.uniform(-5, 5),
            "vx": math.cos(angle) * speed,
            "vy": math.sin(angle) * speed - 2,
            "life": random.randint(20, 40),
            "size": random.uniform(3, 8),
            "color": random.choice([
                (200, 80, 130), (220, 100, 150), (255, 180, 200),
                (160, 60, 100), (180, 70, 120),
            ]),
        })
    # 폭발 사운드
    try:
        snd = pygame.mixer.Sound(resource_path(os.path.join("sounds", "weakexplosion.wav")))
        snd.set_volume(0.3 * sfx_volume)
        snd.play()
    except Exception:
        pass
    # 폭발 근처 플레이어 넉백
    if PLAYER:
        dx = PLAYER.centerx - curse_chest_x
        dy = PLAYER.centery - curse_chest_y
        dist = math.hypot(dx, dy)
        if dist < 120:  # 폭발 반경
            knockback_dir = 1 if dx >= 0 else -1
            knockback_strength = 8 * (1.0 - dist / 120)  # 가까울수록 강함
            player_knockback_vel = apply_knockback_resist(_scale_knockback(knockback_dir * knockback_strength))


def update_curse_chest():
    """저주 보물상자 업데이트: 선딜→투척→착지→대쉬 충돌→연기→조작 반전"""
    global curse_chest_active, curse_chest_opened, curse_chest_open_timer
    global curse_chest_cooldown_timer, curse_chest_reverse_timer
    global curse_chest_smoke_particles
    global curse_chest_windup_active, curse_chest_windup_timer
    global curse_chest_throwing, curse_chest_throw_progress
    global curse_chest_throw_x, curse_chest_throw_y
    global curse_chest_x, curse_chest_y
    global curse_chest_exploding, curse_chest_explode_timer, curse_chest_explode_particles
    global curse_chest_lifetime_timer
    global curse_chest_nudge_vx, curse_chest_wobble_angle, curse_chest_wobble_vel

    # 쿨다운 감소
    if curse_chest_cooldown_timer > 0:
        curse_chest_cooldown_timer -= 1

    # 1) 선딜 페이즈 (0.5초 제자리 모션)
    if curse_chest_windup_active:
        curse_chest_windup_timer -= 1
        if curse_chest_windup_timer <= 0:
            curse_chest_windup_active = False
            _launch_curse_chest()
        return

    # 2) 투사체 비행 페이즈
    if curse_chest_throwing:
        curse_chest_throw_progress += CURSE_CHEST_THROW_SPEED
        if curse_chest_throw_progress >= 1.0:
            curse_chest_throw_progress = 1.0
            curse_chest_throwing = False
            # 착지 → 필드에 보물상자 설치
            curse_chest_active = True
            curse_chest_opened = False
            curse_chest_open_timer = 0
            curse_chest_lifetime_timer = 0
            curse_chest_smoke_particles = []
            curse_chest_nudge_vx = 0.0
            curse_chest_wobble_angle = 0.0
            curse_chest_wobble_vel = 0.0
            curse_chest_x = curse_chest_target_x
            curse_chest_y = curse_chest_target_y
            # 착지 사운드
            try:
                snd = pygame.mixer.Sound(resource_path(os.path.join("sounds", "bonemake.wav")))
                snd.set_volume(0.25 * sfx_volume)
                snd.play()
            except Exception:
                pass
        else:
            # 포물선 보간: X는 선형, Y는 포물선 (위로 볼록)
            t = curse_chest_throw_progress
            curse_chest_throw_x = curse_chest_throw_start_x + (curse_chest_target_x - curse_chest_throw_start_x) * t
            arc_height = -180 * (4 * t * (1 - t))  # 포물선 높이 (최대 -180px)
            curse_chest_throw_y = curse_chest_throw_start_y + (curse_chest_target_y - curse_chest_throw_start_y) * t + arc_height
        # 조작 반전 타이머 감소 (비행 중에도)
        if curse_chest_reverse_timer > 0:
            curse_chest_reverse_timer -= 1
        return

    if not curse_chest_active:
        # 조작 반전 타이머만 감소
        if curse_chest_reverse_timer > 0:
            curse_chest_reverse_timer -= 1
        return

    # 폭발 애니메이션 처리
    if curse_chest_exploding:
        curse_chest_explode_timer -= 1
        # 폭발 파티클 업데이트
        new_ep = []
        for ep in curse_chest_explode_particles:
            ep["x"] += ep["vx"]
            ep["y"] += ep["vy"]
            ep["vy"] += 0.1  # 중력
            ep["life"] -= 1
            if ep["life"] > 0:
                new_ep.append(ep)
        curse_chest_explode_particles = new_ep
        if curse_chest_explode_timer <= 0 and len(curse_chest_explode_particles) == 0:
            curse_chest_exploding = False
            curse_chest_active = False
        # 조작 반전 타이머 감소
        if curse_chest_reverse_timer > 0:
            curse_chest_reverse_timer -= 1
        return

    if not curse_chest_opened:
        # 수명 타이머 증가
        curse_chest_lifetime_timer += 1

        # 4초 경과 시 자동 폭발
        if curse_chest_lifetime_timer >= CURSE_CHEST_LIFETIME:
            _trigger_curse_chest_explode()
            return

        # ── 물리 반응: 플레이어 패들이 근처를 지나가면 밀림/흔들림 ──
        if PLAYER:
            prox_dx = PLAYER.centerx - curse_chest_x
            prox_dy = PLAYER.centery - curse_chest_y
            prox_dist = math.hypot(prox_dx, prox_dy)
            push_range = 55  # 밀림 감지 반경
            if prox_dist < push_range and prox_dist > 1:
                # 플레이어 반대 방향으로 밀기
                push_strength = (1.0 - prox_dist / push_range) * 1.8
                push_dir_x = -prox_dx / prox_dist
                curse_chest_nudge_vx += push_dir_x * push_strength
                # 밀린 방향으로 흔들림 (기울어짐)
                curse_chest_wobble_vel += push_dir_x * push_strength * 3.0

        # 밀림 적용 + 감쇠
        if abs(curse_chest_nudge_vx) > 0.05:
            curse_chest_x += curse_chest_nudge_vx
            curse_chest_nudge_vx *= 0.85  # 마찰 감쇠
            # 게임 영역 내 클램프
            curse_chest_x = max(GAME_AREA_OFFSET_X + 20, min(GAME_AREA_OFFSET_X + GAME_PLAY_WIDTH - 20, curse_chest_x))
        else:
            curse_chest_nudge_vx = 0.0

        # 흔들림(wobble) 스프링 진동 + 감쇠
        curse_chest_wobble_vel += -curse_chest_wobble_angle * 0.25  # 복원력 (스프링)
        curse_chest_wobble_vel *= 0.88  # 감쇠
        curse_chest_wobble_angle += curse_chest_wobble_vel
        # 최대 기울기 제한
        curse_chest_wobble_angle = max(-18, min(18, curse_chest_wobble_angle))
        if abs(curse_chest_wobble_angle) < 0.3 and abs(curse_chest_wobble_vel) < 0.3:
            curse_chest_wobble_angle = 0.0
            curse_chest_wobble_vel = 0.0

        # 플레이어가 대쉬 중이고 보물상자에 충돌하면 열림
        if rolling_active and PLAYER:
            dx = PLAYER.centerx - curse_chest_x
            dy = PLAYER.centery - curse_chest_y
            dist = math.hypot(dx, dy)
            if dist < CURSE_CHEST_SIZE + 20:  # 충돌 판정
                curse_chest_opened = True
                curse_chest_open_timer = 0
                curse_chest_lifetime_timer = 0  # 열렸으면 수명 리셋
                # 연막탄과 동일한 사운드 재생
                try:
                    play_sound_with_volume(SOUND_SMOKEBOMB)
                except Exception:
                    pass
    else:
        # 보물상자 열림 — 연기 분출 페이즈
        curse_chest_open_timer += 1
        total_duration = CURSE_CHEST_SMOKE_DURATION + CURSE_CHEST_SMOKE_FADE_DURATION

        if curse_chest_open_timer <= CURSE_CHEST_SMOKE_DURATION:
            # 3초간 연기 파티클 생성
            for _ in range(3):
                angle = random.uniform(0, math.pi * 2)
                speed = random.uniform(0.3, 1.5)
                curse_chest_smoke_particles.append({
                    "x": curse_chest_x + random.uniform(-10, 10),
                    "y": curse_chest_y + random.uniform(-10, 5),
                    "vx": math.cos(angle) * speed,
                    "vy": math.sin(angle) * speed - 0.3,  # 약간 위로
                    "life": random.uniform(60, 120),
                    "max_life": 120,
                    "size": random.uniform(8, 18),
                    "alpha": 200,
                })

        # 연기 파티클 업데이트
        new_particles = []
        for p in curse_chest_smoke_particles:
            p["x"] += p["vx"]
            p["y"] += p["vy"]
            p["vy"] -= 0.01  # 약간 위로 떠오름
            p["vx"] *= 0.98  # 감속
            p["life"] -= 1
            p["size"] += 0.05  # 연기 팽창

            if curse_chest_open_timer > CURSE_CHEST_SMOKE_DURATION:
                # 걷히기 페이즈: 알파 감소
                fade_progress = (curse_chest_open_timer - CURSE_CHEST_SMOKE_DURATION) / CURSE_CHEST_SMOKE_FADE_DURATION
                p["alpha"] = max(0, 200 * (1 - fade_progress))

            if p["life"] > 0 and p["alpha"] > 5:
                new_particles.append(p)
        curse_chest_smoke_particles = new_particles

        # 플레이어가 연기 영역에 닿으면 조작 반전 발동
        if curse_chest_open_timer <= CURSE_CHEST_SMOKE_DURATION and PLAYER and curse_chest_reverse_timer <= 0:
            dx = PLAYER.centerx - curse_chest_x
            dy = PLAYER.centery - curse_chest_y
            dist = math.hypot(dx, dy)
            if dist < CURSE_CHEST_SMOKE_RADIUS:
                curse_chest_reverse_timer = CURSE_CHEST_REVERSE_DURATION
                show_speech("조작이 반전됐다!", duration=90)

        # 연기 완전 소멸 시 비활성화
        if curse_chest_open_timer >= total_duration and len(curse_chest_smoke_particles) == 0:
            curse_chest_active = False

    # 조작 반전 타이머 감소
    if curse_chest_reverse_timer > 0:
        curse_chest_reverse_timer -= 1


def _draw_curse_chest_mini(screen, cx, cy, sz, rotation=0):
    """작은 보물상자 그리기 (투사체용)"""
    body_color = (200, 80, 130)
    lid_color = (220, 100, 150)
    chest_sf = pygame.Surface((sz + 4, sz + 4), pygame.SRCALPHA)
    half = sz // 2
    qtr = sz // 4
    pygame.draw.rect(chest_sf, body_color, (2, qtr + 2, sz, half))
    pygame.draw.rect(chest_sf, lid_color, (0, qtr - 4, sz + 4, 8))
    # 하트 장식
    hx, hy = sz // 2 + 2, half + 2
    pygame.draw.circle(chest_sf, (255, 180, 200), (hx - 2, hy), 3)
    pygame.draw.circle(chest_sf, (255, 180, 200), (hx + 2, hy), 3)
    if rotation != 0:
        chest_sf = pygame.transform.rotate(chest_sf, rotation)
    rect = chest_sf.get_rect(center=(cx, cy))
    screen.blit(chest_sf, rect)


def draw_curse_chest(screen):
    """저주 보물상자 그리기 — 선딜 모션 + 투사체 비행 + 착지 보물상자 + 핑크 연기"""

    # 선딜 모션: 보스 위에 준비 이펙트
    if curse_chest_windup_active and BOSS:
        boss_cx = BOSS.centerx
        boss_cy = BOSS.bottom + 5
        t = pygame.time.get_ticks() / 150
        # 보스 앞에서 상자가 흔들리는 모션
        wobble = math.sin(t * 3) * 5
        progress = 1.0 - (curse_chest_windup_timer / CURSE_CHEST_WINDUP_FRAMES)
        scale = 0.5 + 0.5 * progress  # 점점 커짐
        mini_sz = int(CURSE_CHEST_SIZE * scale)
        _draw_curse_chest_mini(screen, int(boss_cx + wobble), int(boss_cy + 10), mini_sz, rotation=wobble * 3)
        # 핑크 파티클 (준비 이펙트)
        for i in range(2):
            px = boss_cx + random.uniform(-15, 15)
            py = boss_cy + random.uniform(0, 15)
            pygame.draw.circle(screen, (255, 150, 200, 150), (int(px), int(py)), random.randint(2, 4))

    # 투사체 비행 중: 포물선으로 날아가는 상자
    if curse_chest_throwing:
        tx, ty = int(curse_chest_throw_x), int(curse_chest_throw_y)
        # 회전 (비행 중 빙글빙글)
        spin = curse_chest_throw_progress * 720  # 2바퀴 회전
        _draw_curse_chest_mini(screen, tx, ty, CURSE_CHEST_SIZE, rotation=spin)
        # 궤적 파티클 (핑크 잔상)
        for i in range(2):
            trail_t = max(0, curse_chest_throw_progress - 0.03 * (i + 1))
            trail_x = curse_chest_throw_start_x + (curse_chest_target_x - curse_chest_throw_start_x) * trail_t
            arc = -180 * (4 * trail_t * (1 - trail_t))
            trail_y = curse_chest_throw_start_y + (curse_chest_target_y - curse_chest_throw_start_y) * trail_t + arc
            alpha = int(120 * (1 - i * 0.4))
            trail_sf = pygame.Surface((8, 8), pygame.SRCALPHA)
            pygame.draw.circle(trail_sf, (255, 130, 180, alpha), (4, 4), 4)
            screen.blit(trail_sf, (int(trail_x) - 4, int(trail_y) - 4))

    # 폭발 파티클 렌더링
    if curse_chest_exploding:
        for ep in curse_chest_explode_particles:
            sz_p = int(ep["size"])
            if sz_p < 1:
                continue
            alpha = min(255, int(255 * (ep["life"] / 40)))
            sf = pygame.Surface((sz_p * 2, sz_p * 2), pygame.SRCALPHA)
            pygame.draw.circle(sf, (*ep["color"], alpha), (sz_p, sz_p), sz_p)
            screen.blit(sf, (int(ep["x"]) - sz_p, int(ep["y"]) - sz_p))
        # 조작 반전 이펙트
        if curse_chest_reverse_timer > 0 and PLAYER:
            _draw_curse_reverse_overlay(screen)
        return

    if not curse_chest_active:
        # 조작 반전 이펙트만 그리기 (보물상자 없어도)
        if curse_chest_reverse_timer > 0 and PLAYER:
            _draw_curse_reverse_overlay(screen)
        return

    cx, cy = int(curse_chest_x), int(curse_chest_y)
    sz = CURSE_CHEST_SIZE

    if not curse_chest_opened:
        # 닫힌 보물상자 그리기 — 멘헤라 핑크 테마 (wobble 회전 적용)
        chest_w, chest_h = sz + 12, sz // 2 + 20
        chest_sf = pygame.Surface((chest_w, chest_h), pygame.SRCALPHA)
        # 로컬 좌표 기준 중심
        lcx, lcy = chest_w // 2, chest_h // 2 + 4
        # 폭발 직전 깜빡임 (남은 1초)
        if curse_chest_lifetime_timer >= CURSE_CHEST_LIFETIME - 60:
            blink_speed = 4 + (curse_chest_lifetime_timer - (CURSE_CHEST_LIFETIME - 60)) * 0.3
            if int(pygame.time.get_ticks() / (150 / blink_speed)) % 2 == 0:
                warn_sf = pygame.Surface((sz + 10, sz // 2 + 14), pygame.SRCALPHA)
                warn_sf.fill((255, 50, 50, 80))
                chest_sf.blit(warn_sf, (lcx - sz // 2 - 5, lcy - sz // 4 - 12))
        # 상자 본체
        body_color = (200, 80, 130)
        lid_color = (220, 100, 150)
        pygame.draw.rect(chest_sf, body_color, (lcx - sz // 2, lcy - sz // 4, sz, sz // 2))
        # 뚜껑
        pygame.draw.rect(chest_sf, lid_color, (lcx - sz // 2 - 2, lcy - sz // 4 - 8, sz + 4, 10))
        # 잠금 하트
        heart_color = (255, 180, 200)
        _hx, _hy = lcx, lcy
        for a in range(0, 360, 10):
            rad = math.radians(a)
            hr = 5
            hpx = _hx + int(hr * 16 * (math.sin(rad) ** 3)) // 16
            hpy = _hy - int(hr * (13 * math.cos(rad) - 5 * math.cos(2 * rad) - 2 * math.cos(3 * rad) - math.cos(4 * rad)) / 16)
            if 0 <= hpx < chest_w and 0 <= hpy < chest_h:
                chest_sf.set_at((hpx, hpy), heart_color)
        # 반짝임 이펙트 (유혹)
        t = pygame.time.get_ticks() / 300
        sparkle_alpha = int(128 + 127 * math.sin(t))
        sparkle_glow = pygame.Surface((sz + 8, sz // 2 + 12), pygame.SRCALPHA)
        sparkle_glow.fill((255, 200, 230, sparkle_alpha // 4))
        chest_sf.blit(sparkle_glow, (lcx - sz // 2 - 4, lcy - sz // 4 - 10))
        # wobble 회전 적용 후 화면에 블릿
        if abs(curse_chest_wobble_angle) > 0.3:
            rotated = pygame.transform.rotate(chest_sf, curse_chest_wobble_angle)
            r_rect = rotated.get_rect(center=(cx, cy))
            screen.blit(rotated, r_rect)
        else:
            r_rect = chest_sf.get_rect(center=(cx, cy))
            screen.blit(chest_sf, r_rect)
    else:
        # 열린 보물상자 그리기
        body_color = (160, 60, 100)
        pygame.draw.rect(screen, body_color, (cx - sz // 2, cy - sz // 4, sz, sz // 2))
        # 열린 뚜껑 (뒤로 젖혀짐)
        lid_color = (180, 70, 120)
        pts = [
            (cx - sz // 2 - 2, cy - sz // 4),
            (cx + sz // 2 + 2, cy - sz // 4),
            (cx + sz // 2 - 4, cy - sz // 4 - 16),
            (cx - sz // 2 + 4, cy - sz // 4 - 16),
        ]
        pygame.draw.polygon(screen, lid_color, pts)

    # 핑크 연기 파티클 그리기
    for p in curse_chest_smoke_particles:
        alpha = int(min(255, p["alpha"]))
        if alpha <= 5:
            continue
        size = int(p["size"])
        sf = pygame.Surface((size * 2, size * 2), pygame.SRCALPHA)
        # 핑크~마젠타 그라데이션
        r = min(255, 220 + random.randint(-20, 20))
        g = min(255, 100 + random.randint(-30, 30))
        b = min(255, 160 + random.randint(-20, 20))
        pygame.draw.circle(sf, (r, g, b, alpha), (size, size), size)
        screen.blit(sf, (int(p["x"]) - size, int(p["y"]) - size))

    # 조작 반전 이펙트
    if curse_chest_reverse_timer > 0 and PLAYER:
        _draw_curse_reverse_overlay(screen)


def _draw_curse_reverse_overlay(screen):
    """조작 반전 중 플레이어 위 이펙트 (소용돌이 아이콘만, 패들 틴트는 이미지에 직접 적용)"""
    px, py = PLAYER.centerx, PLAYER.top - 15
    t = pygame.time.get_ticks() / 200
    # 소용돌이 표시
    for i in range(3):
        angle = t + i * (math.pi * 2 / 3)
        sx = px + int(math.cos(angle) * 8)
        sy = py + int(math.sin(angle) * 4)
        pygame.draw.circle(screen, (255, 100, 180), (sx, sy), 3)
    # "?!" 반전 표시
    try:
        rev_font = pygame.font.Font(None, 16)
        rev_surf = rev_font.render("?!", True, (255, 150, 200))
        screen.blit(rev_surf, (px - rev_surf.get_width() // 2, py - 12))
    except Exception:
        pass


# === 앨리스 - 거울 세계 (Mirror World) - Stage 3 ===

def activate_alice_mirror():
    """거울 세계 궁극기 발동 - 화면 좌우반전 + 특수 배경"""
    global alice_mirror_active, alice_mirror_timer, alice_mirror_fade_timer
    global alice_mirror_bg_timer
    alice_mirror_active = True
    alice_mirror_timer = ALICE_MIRROR_DURATION
    alice_mirror_fade_timer = 30  # 0.5초 페이드인
    alice_mirror_bg_timer = 0     # 배경 타이머 초기화
    try:
        snd = pygame.mixer.Sound(resource_path(os.path.join("sounds", "clue.wav")))
        snd.set_volume(0.5 * sfx_volume)
        snd.play()
    except Exception:
        pass


def update_alice_mirror():
    """거울 세계 업데이트"""
    global alice_mirror_active, alice_mirror_timer, alice_mirror_cooldown_timer
    global alice_mirror_fade_timer, alice_mirror_bg_timer
    if alice_mirror_cooldown_timer > 0:
        alice_mirror_cooldown_timer -= 1
    if alice_mirror_fade_timer > 0:
        alice_mirror_fade_timer -= 1
    if not alice_mirror_active:
        return
    alice_mirror_timer -= 1
    alice_mirror_bg_timer += 1
    if alice_mirror_timer <= 0:
        alice_mirror_active = False
        alice_mirror_bg_timer = 0


def apply_alice_mirror_flip(screen, game_area_x, game_area_w, game_area_h):
    """게임 영역만 좌우반전 (필러 제외). 메인 렌더링 후 호출."""
    if not alice_mirror_active:
        return
    # 게임 영역 추출 → 좌우반전 → 다시 붙이기
    game_rect = pygame.Rect(game_area_x, 0, game_area_w, game_area_h)
    game_surf = screen.subsurface(game_rect).copy()
    flipped = pygame.transform.flip(game_surf, True, False)

    # 페이드 인/아웃 효과
    alpha = 255
    if alice_mirror_fade_timer > 0:
        alpha = int(255 * (1.0 - alice_mirror_fade_timer / 30.0))
    if alice_mirror_timer < 30:
        alpha = int(255 * (alice_mirror_timer / 30.0))

    if alpha < 255:
        flipped.set_alpha(alpha)
        screen.blit(flipped, (game_area_x, 0))
    else:
        screen.blit(flipped, (game_area_x, 0))


# === 앨리스 - 사이즈 시프트 (Size Shift) - Stage 3 ===

def activate_alice_size_shift():
    """공 크기 변환 발동 (랜덤 커지거나 작아짐)"""
    global alice_size_shift_active, alice_size_shift_timer, alice_size_shift_scale
    global alice_original_ball_w, alice_original_ball_h
    alice_size_shift_active = True
    alice_size_shift_timer = ALICE_SIZE_SHIFT_DURATION
    # 원본 크기 저장
    alice_original_ball_w = BALL.width
    alice_original_ball_h = BALL.height
    # 랜덤 선택: 커지거나 작아지거나
    if random.random() < 0.5:
        alice_size_shift_scale = 2.0  # 커짐 → 피하기 어려움
    else:
        alice_size_shift_scale = 0.5  # 작아짐 → 보기 어려움
    # 적용
    new_w = max(4, int(alice_original_ball_w * alice_size_shift_scale))
    new_h = max(4, int(alice_original_ball_h * alice_size_shift_scale))
    center_x = BALL.centerx
    center_y = BALL.centery
    BALL.width = new_w
    BALL.height = new_h
    BALL.centerx = center_x
    BALL.centery = center_y
    try:
        snd = pygame.mixer.Sound(resource_path(os.path.join("sounds", "gravityaccel.wav")))
        snd.set_volume(0.35 * sfx_volume)
        snd.play()
    except Exception:
        pass


def update_alice_size_shift():
    """사이즈 시프트 업데이트"""
    global alice_size_shift_active, alice_size_shift_timer, alice_size_shift_cooldown_timer
    if alice_size_shift_cooldown_timer > 0:
        alice_size_shift_cooldown_timer -= 1
    if not alice_size_shift_active:
        return
    alice_size_shift_timer -= 1
    if alice_size_shift_timer <= 0:
        _deactivate_alice_size_shift()


def _deactivate_alice_size_shift():
    """사이즈 시프트 해제 → 원래 크기로 복원"""
    global alice_size_shift_active, alice_size_shift_scale
    alice_size_shift_active = False
    alice_size_shift_scale = 1.0
    if alice_original_ball_w > 0 and alice_original_ball_h > 0:
        center_x = BALL.centerx
        center_y = BALL.centery
        BALL.width = alice_original_ball_w
        BALL.height = alice_original_ball_h
        BALL.centerx = center_x
        BALL.centery = center_y


# === 앨리스 - 토끼 투사체 (Rabbit Projectile) - Stage 3 ===

def activate_alice_rabbit():
    """토끼 투사체 발동 - 0.5초 준비 후 발사"""
    global alice_rabbit_windup_active, alice_rabbit_windup_timer
    alice_rabbit_windup_active = True
    alice_rabbit_windup_timer = 30  # 0.5초 선딜


def _launch_alice_rabbits():
    """준비 완료 후 토끼 투사체 발사 - 플레이어 위치까지 반드시 도달"""
    global alice_rabbit_active, alice_rabbit_projectiles
    alice_rabbit_active = True
    alice_rabbit_projectiles.clear()
    count = random.randint(ALICE_RABBIT_COUNT_MIN, ALICE_RABBIT_COUNT_MAX)
    boss_cx = float(BOSS.centerx if BOSS else WIDTH // 2)
    boss_cy = float((BOSS.y + BOSS.height) if BOSS else 65)
    player_cx = float(PLAYER.centerx if PLAYER else WIDTH // 2)
    player_cy = float(PLAYER.centery if PLAYER else 710)
    dist_to_player = math.sqrt((player_cx - boss_cx) ** 2 + (player_cy - boss_cy) ** 2)
    if dist_to_player < 1:
        dist_to_player = 1
    for i in range(count):
        # 스프레드 각도를 적용하되, 속도를 거리 기반으로 계산하여 반드시 도달
        spread_angle = math.radians(random.uniform(-18, 18))
        base_angle = math.atan2(player_cy - boss_cy, player_cx - boss_cx)
        angle = base_angle + spread_angle
        # 타겟까지의 비행시간을 120~180프레임(2~3초)으로 설정
        flight_frames = random.uniform(120, 180)
        speed = dist_to_player / flight_frames
        speed = max(speed, ALICE_RABBIT_SPEED * 0.8)  # 최소 속도 보장
        alice_rabbit_projectiles.append({
            "x": boss_cx + random.uniform(-15, 15),
            "y": boss_cy,
            "vx": math.cos(angle) * speed,
            "vy": math.sin(angle) * speed,
            "timer": ALICE_RABBIT_MAX_TIMER,
            "hop_phase": random.uniform(0, math.pi * 2),
            "size": random.uniform(16, 22),
            "ear_angle": random.uniform(-0.2, 0.2),
            "target_x": player_cx + random.uniform(-30, 30),  # 목표 X (약간 흩어짐)
            "target_y": player_cy,
        })
    try:
        snd = pygame.mixer.Sound(resource_path(os.path.join("sounds", "smallboyshoot.wav")))
        snd.set_volume(0.35 * sfx_volume)
        snd.play()
    except Exception:
        pass


def update_alice_rabbit():
    """토끼 투사체 업데이트: 선딜 + 깡충 이동 + 충돌 + 패들 위 깐족"""
    global alice_rabbit_active, alice_rabbit_windup_active, alice_rabbit_windup_timer
    global alice_rabbit_cooldown_timer, alice_rabbit_perched, player_fire_knockback_vel
    if alice_rabbit_cooldown_timer > 0:
        alice_rabbit_cooldown_timer -= 1
    if alice_rabbit_windup_active:
        alice_rabbit_windup_timer -= 1
        if alice_rabbit_windup_timer <= 0:
            alice_rabbit_windup_active = False
            _launch_alice_rabbits()
        return
    if not alice_rabbit_active:
        return
    to_remove = []
    for i, proj in enumerate(alice_rabbit_projectiles):
        proj["timer"] -= 1
        proj["hop_phase"] += 0.15
        # 깡충 뛰는 모션 (Y축 사인파)
        hop_offset = abs(math.sin(proj["hop_phase"])) * 8
        # 플레이어 쪽으로 약한 유도 (반드시 도달하도록)
        if PLAYER and proj["y"] < PLAYER.centery:
            target_x = proj.get("target_x", PLAYER.centerx)
            target_y = proj.get("target_y", PLAYER.centery)
            dx = target_x - proj["x"]
            dy = target_y - proj["y"]
            dist = math.sqrt(dx * dx + dy * dy)
            if dist > 1:
                # 부드러운 유도: 속도 벡터를 목표 방향으로 약간 보정
                homing_strength = 0.02
                proj["vx"] += (dx / dist) * homing_strength
                proj["vy"] += (dy / dist) * homing_strength
        proj["x"] += proj["vx"]
        proj["y"] += proj["vy"] - hop_offset * 0.1
        # 화면 밖 (플레이어 Y를 지나친 경우에만 아래쪽으로 제거)
        if (proj["x"] < -30 or
            proj["x"] > WIDTH + 30 or
                proj["y"] > HEIGHT + 60 or proj["y"] < -30):
            to_remove.append(i)
            continue
        if proj["timer"] <= 0:
            to_remove.append(i)
            continue
        # 플레이어 충돌 체크 → 패들 위에 착지하여 깐족거리기
        if PLAYER:
            px_c = PLAYER.centerx
            py_c = PLAYER.centery
            ddx = proj["x"] - px_c
            ddy = proj["y"] - py_c
            dist_sq = ddx * ddx + ddy * ddy
            if dist_sq < (ALICE_RABBIT_HIT_RADIUS + PLAYER.width // 2) ** 2:
                to_remove.append(i)
                # 패들 위에 토끼 착지 (깐족 모드)
                offset_x = proj["x"] - PLAYER.centerx  # 패들 중심 기준 상대 위치
                alice_rabbit_perched.append({
                    "offset_x": offset_x,
                    "timer": ALICE_RABBIT_PERCH_DURATION,
                    "hop_phase": proj["hop_phase"],
                    "size": proj["size"],
                    "direction": random.choice([-1, 1]),  # 좌우 이동 방향
                    "taunt_phase": 0.0,  # 깐족 애니메이션 페이즈
                })
                try:
                    snd = pygame.mixer.Sound(resource_path(os.path.join("sounds", "smallboyhit.wav")))
                    snd.set_volume(0.3 * sfx_volume)
                    snd.play()
                except Exception:
                    pass
    for i in sorted(to_remove, reverse=True):
        if i < len(alice_rabbit_projectiles):
            alice_rabbit_projectiles.pop(i)
    if not alice_rabbit_projectiles and not alice_rabbit_perched:
        alice_rabbit_active = False
    # === 패들 위 깐족토끼 업데이트 ===
    perch_remove = []
    for j, bunny in enumerate(alice_rabbit_perched):
        # 대쉬로 토끼 즉사 처리
        if rolling_active and PLAYER:
            perch_remove.append(j)
            # 터지는 파티클 이펙트
            bx = int(PLAYER.centerx + bunny["offset_x"])
            by = PLAYER.y - int(bunny["size"])
            for _ in range(10):
                angle = random.uniform(0, math.pi * 2)
                spd = random.uniform(2, 6)
                p = {
                    'x': bx, 'y': by,
                    'vx': math.cos(angle) * spd,
                    'vy': math.sin(angle) * spd - 2,
                    'life': random.randint(15, 30),
                    'color': random.choice([(255, 255, 255), (255, 220, 220), (255, 200, 200)])
                }
                if 'neutralize_particles' not in globals():
                    globals()['neutralize_particles'] = []
                neutralize_particles.append(p)
            try:
                snd = pygame.mixer.Sound(resource_path(os.path.join("sounds", "smallboyhit.wav")))
                snd.set_volume(0.25 * sfx_volume)
                snd.play()
            except Exception:
                pass
            continue
        bunny["timer"] -= 1
        bunny["hop_phase"] += 0.25  # 더 빠르게 깡충깡충
        bunny["taunt_phase"] += 0.1
        # 패들 위에서 좌우로 왔다갔다
        bunny["offset_x"] += bunny["direction"] * 1.5
        # 패들 범위를 벗어나면 방향 전환
        if PLAYER:
            half_w = PLAYER.width // 2 - 5
            if bunny["offset_x"] > half_w:
                bunny["offset_x"] = half_w
                bunny["direction"] = -1
            elif bunny["offset_x"] < -half_w:
                bunny["offset_x"] = -half_w
                bunny["direction"] = 1
        # 깐족 중 플레이어에게 주기적 방해 (0.5초마다 토끼 이동방향으로 넉백)
        if bunny["timer"] % 30 == 0 and PLAYER:
            player_fire_knockback_vel += bunny["direction"] * 8  # 토끼가 밀고 있는 방향으로 넉백
        if bunny["timer"] <= 0:
            perch_remove.append(j)
    for j in sorted(perch_remove, reverse=True):
        if j < len(alice_rabbit_perched):
            alice_rabbit_perched.pop(j)


def draw_alice_rabbit_effect(screen):
    """토끼 투사체 + 준비 모션 렌더링"""
    # 1) 준비 모션
    if alice_rabbit_windup_active and BOSS:
        progress = 1.0 - (alice_rabbit_windup_timer / 30.0)
        bcx = BOSS.centerx
        bcy = BOSS.y + BOSS.height + 5
        for i in range(3):
            a = progress * math.pi * 3 + i * (math.pi * 2 / 3)
            d = 20 * (1.0 - progress)
            ppx = int(bcx + math.cos(a) * d)
            ppy = int(bcy + math.sin(a) * d)
            sz = int(8 + 4 * progress)
            sf = pygame.Surface((sz * 2, sz * 2), pygame.SRCALPHA)
            al = int(180 * progress)
            pygame.draw.ellipse(sf, (255, 255, 255, al), (sz // 2, 0, sz, int(sz * 1.4)))
            pygame.draw.ellipse(sf, (255, 240, 240, al), (sz // 2 - 2, 0, 4, sz // 2))
            pygame.draw.ellipse(sf, (255, 240, 240, al), (sz // 2 + sz - 2, 0, 4, sz // 2))
            screen.blit(sf, (ppx - sz, ppy - sz))

    # 2) 투사체
    for proj in alice_rabbit_projectiles:
        px = int(proj["x"])
        py = int(proj["y"])
        sz = int(proj["size"])
        hop = abs(math.sin(proj["hop_phase"])) * 6
        # 그림자
        shadow_surf = pygame.Surface((sz * 2, sz // 2), pygame.SRCALPHA)
        pygame.draw.ellipse(shadow_surf, (0, 0, 0, 40), (0, 0, sz * 2, sz // 2))
        screen.blit(shadow_surf, (px - sz, py + sz // 2))
        # 토끼 본체
        ry = py - int(hop)
        body_w = sz
        body_h = int(sz * 1.3)
        pygame.draw.ellipse(screen, (255, 250, 245),
                            (px - body_w // 2, ry - body_h // 2, body_w, body_h))
        ear_h = int(sz * 0.7)
        pygame.draw.ellipse(screen, (255, 245, 240),
                            (px - body_w // 3 - 2, ry - body_h // 2 - ear_h, 4, ear_h))
        pygame.draw.ellipse(screen, (255, 200, 200),
                            (px - body_w // 3 - 1, ry - body_h // 2 - ear_h + 2, 2, ear_h - 4))
        pygame.draw.ellipse(screen, (255, 245, 240),
                            (px + body_w // 3 - 2, ry - body_h // 2 - ear_h, 4, ear_h))
        pygame.draw.ellipse(screen, (255, 200, 200),
                            (px + body_w // 3 - 1, ry - body_h // 2 - ear_h + 2, 2, ear_h - 4))
        pygame.draw.circle(screen, (200, 50, 50), (px - 3, ry - 2), 2)
        pygame.draw.circle(screen, (200, 50, 50), (px + 3, ry - 2), 2)
        pygame.draw.circle(screen, (255, 255, 255), (px, ry + body_h // 2 - 2), 3)

    # 3) 패들 위 깐족토끼 렌더링
    if PLAYER and alice_rabbit_perched:
        for bunny in alice_rabbit_perched:
            bx = int(PLAYER.centerx + bunny["offset_x"])
            by = PLAYER.y  # 패들 상단
            sz = int(bunny["size"])
            # 큰 깡충깡충 (패들 위에서 더 활발하게)
            hop = abs(math.sin(bunny["hop_phase"])) * 14
            # 좌우 흔들림 (깐족 느낌)
            taunt_wobble = math.sin(bunny["taunt_phase"] * 3) * 3
            # 그림자
            shadow_surf = pygame.Surface((sz * 2, sz // 2), pygame.SRCALPHA)
            pygame.draw.ellipse(shadow_surf, (0, 0, 0, 50), (0, 0, sz * 2, sz // 2))
            screen.blit(shadow_surf, (bx - sz, by - 2))
            # 토끼 본체 (패들 위에서 깡충)
            ry = by - int(hop) - sz
            rx = bx + int(taunt_wobble)
            body_w = sz
            body_h = int(sz * 1.3)
            # 사라지기 직전 깜빡임
            if bunny["timer"] < 30 and (bunny["timer"] // 4) % 2 == 0:
                continue
            pygame.draw.ellipse(screen, (255, 250, 245),
                                (rx - body_w // 2, ry - body_h // 2, body_w, body_h))
            # 귀
            ear_h = int(sz * 0.7)
            pygame.draw.ellipse(screen, (255, 245, 240),
                                (rx - body_w // 3 - 2, ry - body_h // 2 - ear_h, 4, ear_h))
            pygame.draw.ellipse(screen, (255, 200, 200),
                                (rx - body_w // 3 - 1, ry - body_h // 2 - ear_h + 2, 2, ear_h - 4))
            pygame.draw.ellipse(screen, (255, 245, 240),
                                (rx + body_w // 3 - 2, ry - body_h // 2 - ear_h, 4, ear_h))
            pygame.draw.ellipse(screen, (255, 200, 200),
                                (rx + body_w // 3 - 1, ry - body_h // 2 - ear_h + 2, 2, ear_h - 4))
            # 눈 (장난스러운 표정 - ^ ^ 모양)
            pygame.draw.line(screen, (200, 50, 50), (rx - 5, ry - 2), (rx - 3, ry - 4), 2)
            pygame.draw.line(screen, (200, 50, 50), (rx - 3, ry - 4), (rx - 1, ry - 2), 2)
            pygame.draw.line(screen, (200, 50, 50), (rx + 1, ry - 2), (rx + 3, ry - 4), 2)
            pygame.draw.line(screen, (200, 50, 50), (rx + 3, ry - 4), (rx + 5, ry - 2), 2)
            # 꼬리
            pygame.draw.circle(screen, (255, 255, 255), (rx, ry + body_h // 2 - 2), 3)
            # 깐족 말풍선 (주기적으로 표시)
            if bunny["timer"] % 40 < 20:
                taunt_marks = ["!", "♪", "~", "?"]
                mark = taunt_marks[(bunny["timer"] // 40) % len(taunt_marks)]
                try:
                    tiny_font = pygame.font.Font(None, 16)
                    mark_surf = tiny_font.render(mark, True, (255, 100, 150))
                    screen.blit(mark_surf, (rx + body_w // 2 + 2, ry - body_h // 2 - 8))
                except Exception:
                    pass


def draw_alice_size_shift_effect(screen):
    """사이즈 시프트 시각 효과 (공 주변 반짝이)"""
    if not alice_size_shift_active:
        return
    if BALL is None:
        return
    cx = BALL.centerx
    cy = BALL.centery
    t = alice_size_shift_timer
    for i in range(4):
        angle = (t * 0.05 + i * math.pi / 2)
        dist = 15 + BALL.width // 2
        sx = int(cx + math.cos(angle) * dist)
        sy = int(cy + math.sin(angle) * dist)
        sparkle_alpha = int(100 + 100 * abs(math.sin(t * 0.1 + i)))
        sf = pygame.Surface((8, 8), pygame.SRCALPHA)
        if alice_size_shift_scale > 1.0:
            color = (255, 100, 100, sparkle_alpha)
        else:
            color = (100, 200, 255, sparkle_alpha)
        pygame.draw.circle(sf, color, (4, 4), 3)
        screen.blit(sf, (sx - 4, sy - 4))


def draw_alice_mirror_effect(screen):
    """거울 세계 궁극기 - 화면 테두리 + 거울 균열 + 반짝임 이펙트"""
    if not alice_mirror_active:
        return
    t = alice_mirror_timer
    bg_t = alice_mirror_bg_timer

    # 페이드 알파 계산
    alpha = 120
    if t < 30:
        alpha = int(120 * t / 30)
    elif alice_mirror_fade_timer > 0:
        alpha = int(120 * (1.0 - alice_mirror_fade_timer / 30.0))

    glow_surf = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)

    # 1) 두꺼운 시안/보라 그라데이션 테두리 (궁극기급)
    border_w = 16
    outer_color = (100, 180, 255, alpha)
    inner_color = (180, 120, 255, alpha // 2)
    pygame.draw.rect(glow_surf, outer_color, (0, 0, WIDTH, HEIGHT), border_w)
    pygame.draw.rect(glow_surf, inner_color,
                     (border_w, border_w, WIDTH - border_w * 2, HEIGHT - border_w * 2),
                     border_w // 2)

    # 2) 거울 균열선 (대각선으로 화면을 가로지르는 금)
    crack_alpha = int(alpha * 0.6)
    for i in range(5):
        cx = int(WIDTH * (0.15 + 0.18 * i) + 20 * math.sin(bg_t * 0.05 + i))
        cy1 = int(30 * math.cos(bg_t * 0.03 + i * 0.7))
        cy2 = HEIGHT + int(30 * math.sin(bg_t * 0.03 + i * 0.7))
        # 주 균열선
        pygame.draw.line(glow_surf, (200, 230, 255, crack_alpha),
                         (cx, cy1), (cx + random.randint(-40, 40), cy2), 2)
        # 가지 균열
        mid_y = HEIGHT // 2 + int(50 * math.sin(bg_t * 0.04 + i))
        branch_x = cx + int(60 * math.cos(bg_t * 0.06 + i))
        pygame.draw.line(glow_surf, (180, 210, 255, crack_alpha // 2),
                         (cx, mid_y), (branch_x, mid_y + random.randint(-80, 80)), 1)

    # 3) 반짝이는 별 파티클 (거울 세계 느낌)
    for i in range(12):
        sx = int((WIDTH // 2) + 350 * math.sin(bg_t * 0.015 + i * 0.52))
        sy = int((HEIGHT // 2) + 350 * math.cos(bg_t * 0.018 + i * 0.73))
        sparkle_size = int(3 + 3 * abs(math.sin(bg_t * 0.08 + i * 0.9)))
        sparkle_alpha = int(60 + 60 * abs(math.sin(bg_t * 0.06 + i * 1.1)))
        # 십자 형태 반짝임
        pygame.draw.line(glow_surf, (220, 240, 255, sparkle_alpha),
                         (sx - sparkle_size, sy), (sx + sparkle_size, sy), 2)
        pygame.draw.line(glow_surf, (220, 240, 255, sparkle_alpha),
                         (sx, sy - sparkle_size), (sx, sy + sparkle_size), 2)

    # 4) 화면 상하단 비네팅 (어둡게)
    vignette_h = 60
    for vi in range(vignette_h):
        va = int(alpha * 0.5 * (1.0 - vi / vignette_h))
        pygame.draw.line(glow_surf, (20, 0, 40, va), (0, vi), (WIDTH, vi))
        pygame.draw.line(glow_surf, (20, 0, 40, va), (0, HEIGHT - 1 - vi), (WIDTH, HEIGHT - 1 - vi))

    screen.blit(glow_surf, (0, 0))


# === 테디베어 솜뭉치 투척 스킬 (Stage 3) ===
def activate_cotton_throw():
    """솜뭉치 투척 발동 -- 0.5초 준비 후 3~5개 솜뭉치 발사"""
    global cotton_throw_windup_active, cotton_throw_windup_timer
    cotton_throw_windup_active = True
    cotton_throw_windup_timer = 30


def _launch_cotton_throw():
    """준비 완료 후 솜뭉치 다수 발사"""
    global cotton_throw_active, cotton_throw_projectiles
    cotton_throw_active = True
    cotton_throw_projectiles.clear()
    count = random.randint(COTTON_THROW_COUNT_MIN, COTTON_THROW_COUNT_MAX)
    boss_cx = float(BOSS.centerx if BOSS else WIDTH // 2)
    boss_cy = float((BOSS.y + BOSS.height) if BOSS else 65)
    player_cx = float(PLAYER.centerx if PLAYER else WIDTH // 2)
    player_cy = float(PLAYER.centery if PLAYER else 710)
    for i in range(count):
        dx = player_cx - boss_cx
        dy = player_cy - boss_cy
        dist = math.sqrt(dx * dx + dy * dy)
        if dist < 1:
            dist = 1
        spread_angle = math.radians(random.uniform(-25, 25))
        base_angle = math.atan2(dy, dx)
        angle = base_angle + spread_angle
        speed = COTTON_THROW_SPEED + random.uniform(-0.5, 0.5)
        cotton_throw_projectiles.append({
            "x": boss_cx + random.uniform(-15, 15),
            "y": boss_cy,
            "vx": math.cos(angle) * speed,
            "vy": math.sin(angle) * speed,
            "timer": COTTON_THROW_MAX_TIMER,
            "wobble_phase": random.uniform(0, math.pi * 2),
            "size": random.uniform(18, 28),
        })
    try:
        snd = pygame.mixer.Sound(resource_path(os.path.join("sounds", "dollcurse.wav")))
        snd.set_volume(0.35 * sfx_volume)
        snd.play()
    except Exception:
        pass


def update_cotton_throw():
    """솜뭉치 투척 업데이트: 선딜 + 투사체 이동 + 충돌 + 안개"""
    global cotton_throw_active, cotton_throw_windup_active, cotton_throw_windup_timer
    global cotton_throw_cooldown_timer
    global cotton_blackout_active, cotton_blackout_timer
    if cotton_throw_cooldown_timer > 0:
        cotton_throw_cooldown_timer -= 1
    if cotton_throw_windup_active:
        cotton_throw_windup_timer -= 1
        if cotton_throw_windup_timer <= 0:
            cotton_throw_windup_active = False
            _launch_cotton_throw()
        return
    # 암전 타이머 업데이트
    if cotton_blackout_active:
        cotton_blackout_timer -= 1
        if cotton_blackout_timer <= 0:
            cotton_blackout_active = False
    if not cotton_throw_active:
        return
    to_remove = []
    for i, proj in enumerate(cotton_throw_projectiles):
        proj["timer"] -= 1
        proj["wobble_phase"] += 0.12
        wobble = math.sin(proj["wobble_phase"]) * 1.5
        proj["x"] += proj["vx"] + wobble
        proj["y"] += proj["vy"]
        proj["vx"] *= 0.998
        proj["vy"] *= 0.998
        if (proj["x"] < GAME_AREA_OFFSET_X - 30 or
            proj["x"] > GAME_AREA_OFFSET_X + GAME_PLAY_WIDTH + 30 or
                proj["y"] > HEIGHT + 30 or proj["y"] < -30):
            to_remove.append(i)
            continue
        if proj["timer"] <= 0:
            to_remove.append(i)
            continue
        if PLAYER and not cotton_blackout_active:
            px_c = PLAYER.centerx
            py_c = PLAYER.centery
            ddx = proj["x"] - px_c
            ddy = proj["y"] - py_c
            dist_sq = ddx * ddx + ddy * ddy
            if dist_sq < (COTTON_THROW_HIT_RADIUS + PLAYER.width // 2) ** 2:
                to_remove.append(i)
                _trigger_cotton_fog(proj["x"], proj["y"])
                show_speech("앞이 안 보여~!", duration=60)
    for i in sorted(to_remove, reverse=True):
        if i < len(cotton_throw_projectiles):
            cotton_throw_projectiles.pop(i)
    if not cotton_throw_projectiles:
        cotton_throw_active = False


def _trigger_cotton_fog(hit_x, hit_y):
    """솜뭉치 명중 시 화면 암전 (블랙아웃) 발동"""
    global cotton_blackout_active, cotton_blackout_timer
    cotton_blackout_active = True
    cotton_blackout_timer = COTTON_BLACKOUT_DURATION


def draw_cotton_throw_effect(screen):
    """솜뭉치 투척 전체 렌더링 (준비 모션 + 투사체 + 안개)"""
    # 1) 준비 모션
    if cotton_throw_windup_active and BOSS:
        progress = 1.0 - (cotton_throw_windup_timer / 30.0)
        bcx = BOSS.centerx
        bcy = BOSS.y + BOSS.height + 5
        for i in range(4):
            a = progress * math.pi * 4 + i * (math.pi / 2)
            d = 25 * (1.0 - progress)
            ppx = bcx + math.cos(a) * d
            ppy = bcy + math.sin(a) * d
            sz = int(6 + 4 * progress)
            al = int(150 * progress)
            sf = pygame.Surface((sz * 2, sz * 2), pygame.SRCALPHA)
            pygame.draw.circle(sf, (255, 240, 230, al), (sz, sz), sz)
            screen.blit(sf, (int(ppx) - sz, int(ppy) - sz))
    # 2) 비행 중인 솜뭉치 투사체
    for proj in cotton_throw_projectiles:
        cx, cy = int(proj["x"]), int(proj["y"])
        sz = int(proj["size"])
        breath = 1.0 + math.sin(proj["wobble_phase"] * 2) * 0.1
        draw_sz = int(sz * breath)
        sf = pygame.Surface((draw_sz * 3, draw_sz * 3), pygame.SRCALPHA)
        ct = draw_sz * 3 // 2
        pygame.draw.circle(sf, (255, 200, 220, 120), (ct, ct), draw_sz + 4)
        pygame.draw.circle(sf, (255, 250, 245, 200), (ct, ct), draw_sz)
        pygame.draw.circle(sf, (255, 255, 255, 240), (ct - 3, ct - 3), max(1, draw_sz // 2))
        for j in range(3):
            fa = proj["wobble_phase"] + j * 2.1
            fx = ct + int(math.cos(fa) * (draw_sz * 0.7))
            fy = ct + int(math.sin(fa) * (draw_sz * 0.7))
            pygame.draw.circle(sf, (255, 235, 240, 160), (fx, fy), max(1, draw_sz // 3))
        screen.blit(sf, (cx - ct, cy - ct))
    # 3) 솜뭉치 화이트아웃 효과
    if cotton_blackout_active and cotton_blackout_timer > 0:
        elapsed = COTTON_BLACKOUT_DURATION - cotton_blackout_timer
        # 0~30프레임(0~0.5초): 완전 화이트 (alpha=255)
        # 30~120프레임(0.5~2.0초): 점점 원래색으로 복귀 (alpha 255→0)
        if elapsed < COTTON_BLACKOUT_FULL_END:
            # 완전 화이트 구간 (처음 5프레임은 급속 페이드인)
            if elapsed < 5:
                alpha = int(255 * (elapsed / 5.0))
            else:
                alpha = 255
        else:
            # 점진 복귀 구간 (0.5초~2초)
            fade_frames = COTTON_BLACKOUT_DURATION - COTTON_BLACKOUT_FULL_END  # 90프레임
            fade_progress = (elapsed - COTTON_BLACKOUT_FULL_END) / fade_frames
            alpha = int(255 * (1.0 - fade_progress))
        alpha = max(0, min(255, alpha))
        if alpha > 0:
            whiteout_sf = pygame.Surface((INTERNAL_WIDTH, INTERNAL_HEIGHT), pygame.SRCALPHA)
            whiteout_sf.fill((255, 255, 255, alpha))
            screen.blit(whiteout_sf, (0, 0))


# =====================================================================
# === 테디베어 솜뭉치 폭탄 (Cotton Bomb) - Stage 3 ===
# =====================================================================
def activate_cotton_bomb():
    """솜뭉치 폭탄 발동 — 0.5초 준비 후 3~5개 솜뭉치를 필드에 배치"""
    global cotton_bomb_windup_active, cotton_bomb_windup_timer
    cotton_bomb_windup_active = True
    cotton_bomb_windup_timer = 30  # 0.5초 선딜


def _launch_cotton_bombs():
    """준비 완료 후 솜뭉치 폭탄을 필드에 배치"""
    global cotton_bomb_active, cotton_bomb_projectiles
    cotton_bomb_active = True
    count = random.randint(COTTON_BOMB_COUNT_MIN, COTTON_BOMB_COUNT_MAX)
    for _ in range(count):
        # 게임 영역 내 무작위 위치에 배치 (중립 지대 ~ 플레이어 진영)
        bx = random.uniform(GAME_AREA_OFFSET_X + 40, GAME_AREA_OFFSET_X + GAME_PLAY_WIDTH - 40)
        by = random.uniform(200, 650)
        cotton_bomb_projectiles.append({
            "x": bx,
            "y": by,
            "timer": COTTON_BOMB_LIFETIME,
            "wobble_phase": random.uniform(0, math.pi * 2),
            "size": random.uniform(20, 30),
            "pulse": 0.0,
            "hit": False,
        })
    try:
        snd = pygame.mixer.Sound(resource_path(os.path.join("sounds", "bonemake.wav")))
        snd.set_volume(0.3 * sfx_volume)
        snd.play()
    except Exception:
        pass


def _explode_cotton_bomb(bomb):
    """광폭화 시 솜뭉치 폭탄이 파편으로 분산"""
    global cotton_bomb_fragments
    for _ in range(COTTON_BOMB_FRAGMENT_COUNT):
        angle = random.uniform(0, math.pi * 2)
        speed = COTTON_BOMB_FRAGMENT_SPEED + random.uniform(-0.5, 0.5)
        cotton_bomb_fragments.append({
            "x": bomb["x"],
            "y": bomb["y"],
            "vx": math.cos(angle) * speed,
            "vy": math.sin(angle) * speed,
            "timer": COTTON_BOMB_FRAGMENT_LIFETIME,
            "size": random.uniform(8, 14),
            "wobble_phase": random.uniform(0, math.pi * 2),
        })
    try:
        snd = pygame.mixer.Sound(resource_path(os.path.join("sounds", "weakexplosion.wav")))
        snd.set_volume(0.25 * sfx_volume)
        snd.play()
    except Exception:
        pass


def _activate_ghost_curve():
    """유령 커브 발동 — 폴터가이스트 물리법칙 무시 궤적 저주"""
    global cotton_bomb_ghost_curve_active, cotton_bomb_ghost_curve_timer
    global cotton_bomb_ghost_curve_phase, cotton_bomb_ghost_curve_seed
    global cotton_bomb_ghost_curve_intensity
    global _ghost_curve_freeze_timer, _ghost_curve_saved_vel
    global _ghost_curve_next_hard_turn, _ghost_curve_next_freeze
    global _ghost_curve_trail, _ghost_curve_flicker_timer
    _ghost_curve_trail.clear()
    _ghost_curve_flicker_timer = 0
    cotton_bomb_ghost_curve_active = True
    cotton_bomb_ghost_curve_timer = COTTON_BOMB_GHOST_CURVE_DURATION
    cotton_bomb_ghost_curve_phase = random.uniform(0, math.pi * 2)
    cotton_bomb_ghost_curve_seed = random.uniform(0.7, 2.5)
    cotton_bomb_ghost_curve_intensity = 1.0
    _ghost_curve_freeze_timer = 0
    _ghost_curve_saved_vel = None
    _ghost_curve_next_hard_turn = random.randint(20, 45)
    _ghost_curve_next_freeze = random.randint(40, 70)

    # ★ 발동 순간 즉시 큰 초기 꺾임 (드라마틱한 첫 충격)
    speed = math.hypot(ball_vel[0], ball_vel[1])
    if speed > 0.5:
        kick_angle = random.uniform(0.8, 1.5) * random.choice([-1, 1])
        cur_angle = math.atan2(ball_vel[1], ball_vel[0])
        new_angle = cur_angle + kick_angle
        ball_vel[0] = math.cos(new_angle) * speed
        ball_vel[1] = math.sin(new_angle) * speed


def update_ghost_curve():
    """유령 커브 — 폴터가이스트: 하드턴 + 마이크로프리즈 + 속도펄스 + 방향반전"""
    global cotton_bomb_ghost_curve_active, cotton_bomb_ghost_curve_timer
    global cotton_bomb_ghost_curve_phase, cotton_bomb_ghost_curve_intensity
    global _ghost_curve_freeze_timer, _ghost_curve_saved_vel
    global _ghost_curve_next_hard_turn, _ghost_curve_next_freeze

    if not cotton_bomb_ghost_curve_active:
        return

    cotton_bomb_ghost_curve_timer -= 1
    if cotton_bomb_ghost_curve_timer <= 0:
        cotton_bomb_ghost_curve_active = False
        return

    t_ratio = cotton_bomb_ghost_curve_timer / COTTON_BOMB_GHOST_CURVE_DURATION
    speed = math.hypot(ball_vel[0], ball_vel[1])
    if speed < 0.5:
        return

    # === 마이크로 프리즈: 허공에서 멈칫 → 랜덤 방향 급발진 ===
    if _ghost_curve_freeze_timer > 0:
        _ghost_curve_freeze_timer -= 1
        if _ghost_curve_freeze_timer > 3:
            # 정지 구간 (공 거의 멈춤, 에너지 축적 느낌)
            ball_vel[0] *= 0.12
            ball_vel[1] *= 0.12
        elif _ghost_curve_freeze_timer == 3:
            # 급발진! 저장 속도의 1.6배로 랜덤 방향 사출
            if _ghost_curve_saved_vel:
                burst_speed = math.hypot(*_ghost_curve_saved_vel) * 1.6
                burst_angle = math.atan2(_ghost_curve_saved_vel[1], _ghost_curve_saved_vel[0])
                burst_angle += random.uniform(-1.3, 1.3)
                ball_vel[0] = math.cos(burst_angle) * burst_speed
                ball_vel[1] = math.sin(burst_angle) * burst_speed
                _ghost_curve_saved_vel = None
        return

    # 프리즈 스케줄 체크
    _ghost_curve_next_freeze -= 1
    if _ghost_curve_next_freeze <= 0 and t_ratio > 0.2:
        _ghost_curve_freeze_timer = random.randint(6, 11)  # 0.1~0.18초 정지
        _ghost_curve_saved_vel = [ball_vel[0], ball_vel[1]]
        _ghost_curve_next_freeze = random.randint(35, 65)

    cotton_bomb_ghost_curve_phase += 0.22 + cotton_bomb_ghost_curve_seed * 0.12
    phase = cotton_bomb_ghost_curve_phase
    seed = cotton_bomb_ghost_curve_seed
    cur_angle = math.atan2(ball_vel[1], ball_vel[0])

    # === 하드 턴: 갑자기 예각(60~120도)으로 팍! 꺾임 ===
    _ghost_curve_next_hard_turn -= 1
    if _ghost_curve_next_hard_turn <= 0 and t_ratio > 0.15:
        turn_angle = random.uniform(math.pi / 3, math.pi * 2 / 3) * random.choice([-1, 1])
        new_angle = cur_angle + turn_angle
        speed_mult = random.uniform(0.7, 1.4)  # 속도 불규칙 변동
        ball_vel[0] = math.cos(new_angle) * speed * speed_mult
        ball_vel[1] = math.sin(new_angle) * speed * speed_mult
        _ghost_curve_next_hard_turn = random.randint(15, 40)
        cur_angle = new_angle

    # === 3중 사인파 합성 (기존 유지) ===
    wave1 = math.sin(phase * 0.7 * seed) * 3.5
    wave2 = math.sin(phase * 2.3 + seed * 5.0) * 2.5
    wave3 = math.sin(phase * 4.1 + seed * 11.0) * 1.2

    # 수직 힘 (커브)
    perp_force = (wave1 + wave2 + wave3) * t_ratio * 0.35
    # 접선 힘 (가감속) + 큐빅 이징 속도 펄스 (울컥거림)
    tangent_wave = math.sin(phase * 1.1 + seed * 3.0) * 0.8
    cubic_pulse = math.sin(phase * 3.7 + seed * 7.3) ** 3  # 급격한 속도 스파이크
    tangent_force = (tangent_wave + cubic_pulse * 1.5) * t_ratio

    ball_vel[0] += math.cos(cur_angle + math.pi / 2) * perp_force
    ball_vel[1] += math.sin(cur_angle + math.pi / 2) * perp_force
    ball_vel[0] += math.cos(cur_angle) * tangent_force
    ball_vel[1] += math.sin(cur_angle) * tangent_force

    # === 5% 확률 속도 컴포넌트 반전 (기이한 떨림/되튀김) ===
    if random.random() < 0.05 * t_ratio:
        if random.random() < 0.5:
            ball_vel[0] = -ball_vel[0] * random.uniform(0.6, 1.0)
        else:
            ball_vel[1] = -ball_vel[1] * random.uniform(0.6, 1.0)

    # === 유령 잔상 트레일 업데이트 ===
    global _ghost_curve_trail, _ghost_curve_flicker_timer
    _ghost_curve_flicker_timer += 1
    if BALL:
        # 매 프레임 잔상 파티클 생성 (2~3개씩)
        for _ in range(random.randint(2, 3)):
            _ghost_curve_trail.append({
                "x": float(BALL.centerx) + random.uniform(-4, 4),
                "y": float(BALL.centery) + random.uniform(-4, 4),
                "alpha": 200,
                "size": BALL_RADIUS + random.uniform(-2, 3),
                "offset_x": random.uniform(-1.5, 1.5),
                "offset_y": random.uniform(-1.5, 1.5),
                "phase": random.uniform(0, math.pi * 2),
                "distort": random.uniform(0.6, 1.4),
            })
    # 잔상 업데이트 및 제거
    for p in _ghost_curve_trail:
        p["x"] += p["offset_x"]
        p["y"] += p["offset_y"]
        p["alpha"] -= random.randint(6, 12)
        p["phase"] += 0.2
        p["size"] *= 0.97
    _ghost_curve_trail = [p for p in _ghost_curve_trail if p["alpha"] > 0 and p["size"] > 1]


def update_cotton_bomb():
    """솜뭉치 폭탄 업데이트: 선딜 + 필드 잔존 + 충돌 판정 + 파편 + 유령 커브"""
    global cotton_bomb_active, cotton_bomb_windup_active, cotton_bomb_windup_timer
    global cotton_bomb_cooldown_timer, cotton_bomb_slow_timer
    global cotton_bomb_projectiles, cotton_bomb_fragments

    # 쿨다운 감소
    if cotton_bomb_cooldown_timer > 0:
        cotton_bomb_cooldown_timer -= 1

    # 플레이어 둔화 타이머 감소
    if cotton_bomb_slow_timer > 0:
        cotton_bomb_slow_timer -= 1

    # 유령 커브 업데이트
    update_ghost_curve()

    # 선딜 처리
    if cotton_bomb_windup_active:
        cotton_bomb_windup_timer -= 1
        if cotton_bomb_windup_timer <= 0:
            cotton_bomb_windup_active = False
            _launch_cotton_bombs()
        return

    # 파편 업데이트
    frag_remove = []
    for i, frag in enumerate(cotton_bomb_fragments):
        frag["timer"] -= 1
        frag["wobble_phase"] += 0.15
        frag["x"] += frag["vx"]
        frag["y"] += frag["vy"]
        frag["vx"] *= 0.97
        frag["vy"] *= 0.97
        if frag["timer"] <= 0:
            frag_remove.append(i)
            continue
        # 파편-공 충돌: 유령 커브 발동
        if BALL:
            ddx = frag["x"] - BALL.centerx
            ddy = frag["y"] - BALL.centery
            dist_sq = ddx * ddx + ddy * ddy
            if dist_sq < (frag["size"] + BALL_RADIUS) ** 2:
                _activate_ghost_curve()
                frag_remove.append(i)
        # 파편-플레이어 충돌: 둔화
        if PLAYER:
            ddx = frag["x"] - PLAYER.centerx
            ddy = frag["y"] - PLAYER.centery
            dist_sq = ddx * ddx + ddy * ddy
            if dist_sq < (frag["size"] + PLAYER.width // 2) ** 2:
                cotton_bomb_slow_timer = COTTON_BOMB_PLAYER_SLOW_DURATION
                frag_remove.append(i)
    for i in sorted(set(frag_remove), reverse=True):
        if i < len(cotton_bomb_fragments):
            cotton_bomb_fragments.pop(i)

    if not cotton_bomb_active:
        return

    # 솜뭉치 폭탄 업데이트
    to_remove = []
    for i, bomb in enumerate(cotton_bomb_projectiles):
        bomb["timer"] -= 1
        bomb["wobble_phase"] += 0.08
        bomb["pulse"] += 0.05
        if bomb["timer"] <= 0:
            to_remove.append(i)
            continue
        # 공과 충돌 판정 → 유령 커브 발동
        if BALL and not bomb["hit"]:
            ddx = bomb["x"] - BALL.centerx
            ddy = bomb["y"] - BALL.centery
            dist_sq = ddx * ddx + ddy * ddy
            if dist_sq < (COTTON_BOMB_HIT_RADIUS + BALL_RADIUS) ** 2:
                _activate_ghost_curve()
                bomb["hit"] = True
                if enraged_boss_active:
                    _explode_cotton_bomb(bomb)
                    to_remove.append(i)
                    show_speech("유령의 저주~!", duration=50)
                else:
                    to_remove.append(i)
                    show_speech("홀렸다~!", duration=50)
        # 플레이어 패들과 충돌 판정
        if PLAYER and not bomb["hit"]:
            ddx = bomb["x"] - PLAYER.centerx
            ddy = bomb["y"] - PLAYER.centery
            dist_sq = ddx * ddx + ddy * ddy
            if dist_sq < (COTTON_BOMB_HIT_RADIUS + PLAYER.width // 2) ** 2:
                cotton_bomb_slow_timer = COTTON_BOMB_PLAYER_SLOW_DURATION
                bomb["hit"] = True
                if enraged_boss_active:
                    _explode_cotton_bomb(bomb)
                    to_remove.append(i)
                    show_speech("걸렸다~!", duration=40)
                else:
                    to_remove.append(i)
                    show_speech("느려져라~!", duration=40)
    for i in sorted(set(to_remove), reverse=True):
        if i < len(cotton_bomb_projectiles):
            cotton_bomb_projectiles.pop(i)
    if not cotton_bomb_projectiles and not cotton_bomb_fragments:
        cotton_bomb_active = False


def draw_cotton_bomb_effect(screen):
    """솜뭉치 폭탄 렌더링 (선딜 + 배치된 폭탄 + 파편)"""
    # 1) 선딜 모션
    if cotton_bomb_windup_active and BOSS:
        progress = 1.0 - (cotton_bomb_windup_timer / 30.0)
        bcx = BOSS.centerx
        bcy = BOSS.y + BOSS.height + 5
        for i in range(5):
            a = progress * math.pi * 6 + i * (math.pi * 2 / 5)
            d = 30 * (1.0 - progress)
            ppx = bcx + math.cos(a) * d
            ppy = bcy + math.sin(a) * d
            sz = int(8 + 6 * progress)
            al = int(180 * progress)
            sf = pygame.Surface((sz * 2, sz * 2), pygame.SRCALPHA)
            pygame.draw.circle(sf, (255, 180, 200, al), (sz, sz), sz)
            screen.blit(sf, (int(ppx) - sz, int(ppy) - sz))

    # 2) 필드에 배치된 솜뭉치 폭탄
    for bomb in cotton_bomb_projectiles:
        cx, cy = int(bomb["x"]), int(bomb["y"])
        sz = int(bomb["size"])
        breath = 1.0 + math.sin(bomb["pulse"] * 3) * 0.15
        draw_sz = int(sz * breath)
        # 남은 시간에 따른 깜빡임 (마지막 2초)
        if bomb["timer"] < 120:
            blink = abs(math.sin(bomb["timer"] * 0.15))
            alpha_mult = 0.4 + 0.6 * blink
        else:
            alpha_mult = 1.0
        sf = pygame.Surface((draw_sz * 3, draw_sz * 3), pygame.SRCALPHA)
        ct = draw_sz * 3 // 2
        # 위험 표시 원 (빨간 외곽)
        danger_alpha = int(80 * alpha_mult)
        pygame.draw.circle(sf, (255, 100, 100, danger_alpha), (ct, ct), draw_sz + 8)
        # 메인 솜뭉치 (분홍)
        main_alpha = int(220 * alpha_mult)
        pygame.draw.circle(sf, (255, 200, 220, main_alpha), (ct, ct), draw_sz)
        pygame.draw.circle(sf, (255, 240, 245, min(255, int(240 * alpha_mult))), (ct, ct), max(1, draw_sz * 2 // 3))
        # 하이라이트
        hl_alpha = int(200 * alpha_mult)
        pygame.draw.circle(sf, (255, 255, 255, hl_alpha), (ct - 3, ct - 3), max(1, draw_sz // 3))
        screen.blit(sf, (cx - ct, cy - ct))

    # 3) 파편 렌더링
    for frag in cotton_bomb_fragments:
        cx, cy = int(frag["x"]), int(frag["y"])
        sz = int(frag["size"])
        alpha = min(255, int(255 * (frag["timer"] / COTTON_BOMB_FRAGMENT_LIFETIME)))
        wobble = math.sin(frag["wobble_phase"]) * 2
        sf = pygame.Surface((sz * 2 + 4, sz * 2 + 4), pygame.SRCALPHA)
        ct = sz + 2
        pygame.draw.circle(sf, (255, 180, 200, alpha), (ct + int(wobble), ct), sz)
        pygame.draw.circle(sf, (255, 230, 240, alpha // 2), (ct + int(wobble) - 2, ct - 2), max(1, sz // 2))
        screen.blit(sf, (cx - ct, cy - ct))

    # 4) 플레이어 둔화 상태 표시
    if cotton_bomb_slow_timer > 0 and PLAYER:
        slow_alpha = min(160, int(160 * (cotton_bomb_slow_timer / COTTON_BOMB_PLAYER_SLOW_DURATION)))
        # 플레이어 주변 끈적한 원 효과
        slow_sf = pygame.Surface((PLAYER.width + 40, 20), pygame.SRCALPHA)
        pygame.draw.ellipse(slow_sf, (255, 180, 220, slow_alpha),
                            (0, 0, PLAYER.width + 40, 20))
        screen.blit(slow_sf, (PLAYER.centerx - (PLAYER.width + 40) // 2, PLAYER.bottom - 5))


def draw_ghost_curve_ball_effect(screen):
    """유령 커브 발동 중 공에 기괴한 유령 잔상 이펙트"""
    if not cotton_bomb_ghost_curve_active:
        return
    t_ratio = cotton_bomb_ghost_curve_timer / COTTON_BOMB_GHOST_CURVE_DURATION
    flicker = _ghost_curve_flicker_timer

    # 1) 잔상 트레일 — 반투명 유령 구체들이 흩어지며 사라짐
    for p in _ghost_curve_trail:
        a = max(0, min(255, int(p["alpha"] * t_ratio)))
        sz = max(1, int(p["size"] * p["distort"]))
        w = int(sz * 2 * (0.7 + 0.6 * math.sin(p["phase"])))
        h = int(sz * 2 * (0.7 + 0.6 * math.cos(p["phase"] * 1.3)))
        w = max(2, w)
        h = max(2, h)
        sf = pygame.Surface((w, h), pygame.SRCALPHA)
        gc = int(180 + 40 * math.sin(p["phase"] * 2))
        bc = int(200 + 55 * math.sin(p["phase"] * 1.7 + 1.0))
        pygame.draw.ellipse(sf, (gc, gc, bc, a), (0, 0, w, h))
        screen.blit(sf, (int(p["x"]) - w // 2, int(p["y"]) - h // 2))

    # 2) 공 주변 일렁이는 유령 아우라
    if BALL:
        bx, by = BALL.centerx, BALL.centery
        aura_phase = flicker * 0.15
        for i in range(5):
            angle = aura_phase + i * (math.pi * 2 / 5)
            wobble = math.sin(aura_phase * 2.3 + i * 1.7) * 6
            r = BALL_RADIUS + 8 + wobble
            ax = bx + math.cos(angle) * r * 0.3
            ay = by + math.sin(angle) * r * 0.3
            ring_r = int(BALL_RADIUS + 6 + wobble)
            ring_alpha = int((40 + 30 * math.sin(aura_phase * 3 + i)) * t_ratio)
            ring_alpha = max(0, min(255, ring_alpha))
            sf = pygame.Surface((ring_r * 2 + 4, ring_r * 2 + 4), pygame.SRCALPHA)
            ct = ring_r + 2
            pygame.draw.circle(sf, (160, 220, 210, ring_alpha), (ct, ct), ring_r, 2)
            screen.blit(sf, (int(ax) - ct, int(ay) - ct))

        # 3) 공 위에 유령 얼굴 (깜빡이며 나타남)
        face_alpha = int((100 + 80 * math.sin(flicker * 0.2)) * t_ratio)
        face_alpha = max(0, min(255, face_alpha))
        if math.sin(flicker * 0.7) > 0.3:
            face_sf = pygame.Surface((BALL_RADIUS * 4, BALL_RADIUS * 4), pygame.SRCALPHA)
            fc = BALL_RADIUS * 2
            eye_l_x = fc - int(BALL_RADIUS * 0.35)
            eye_r_x = fc + int(BALL_RADIUS * 0.35)
            eye_y = fc - int(BALL_RADIUS * 0.15)
            el_w = max(2, int(3 + 2 * math.sin(flicker * 0.3)))
            el_h = max(3, int(5 + 3 * math.sin(flicker * 0.25 + 0.5)))
            er_w = max(2, int(3 + 2 * math.sin(flicker * 0.35 + 1.0)))
            er_h = max(3, int(5 + 3 * math.sin(flicker * 0.28 + 2.0)))
            pygame.draw.ellipse(face_sf, (180, 255, 230, face_alpha),
                                (eye_l_x - el_w, eye_y - el_h, el_w * 2, el_h * 2))
            pygame.draw.ellipse(face_sf, (180, 255, 230, face_alpha),
                                (eye_r_x - er_w, eye_y - er_h, er_w * 2, er_h * 2))
            mouth_y = fc + int(BALL_RADIUS * 0.3)
            mouth_w = int(BALL_RADIUS * 0.6 + 2 * math.sin(flicker * 0.18))
            pygame.draw.arc(face_sf, (180, 255, 230, face_alpha),
                            (fc - mouth_w, mouth_y - 3, mouth_w * 2, 8),
                            math.pi * 0.1, math.pi * 0.9, 2)
            screen.blit(face_sf, (bx - fc, by - fc))


# =====================================================================
# === 테디베어 죽음의 포옹 (Deadly Hug) - Stage 3 ===
# =====================================================================
def activate_deadly_hug():
    """죽음의 포옹 발동 — 보스가 화면 중앙으로 돌진 후 영역 생성"""
    global deadly_hug_rush_active, deadly_hug_rush_y, deadly_hug_active
    global deadly_hug_timer
    deadly_hug_rush_active = True
    deadly_hug_rush_y = float(BOSS.bottom if BOSS else 65)
    deadly_hug_active = False
    deadly_hug_timer = 0
    try:
        snd = pygame.mixer.Sound(resource_path(os.path.join("sounds", "grab.wav")))
        snd.set_volume(0.4 * sfx_volume)
        snd.play()
    except Exception:
        pass


def update_deadly_hug():
    """죽음의 포옹 업데이트: 돌진 + 영역 지속 + 대쉬 제한"""
    global deadly_hug_active, deadly_hug_rush_active, deadly_hug_rush_y
    global deadly_hug_timer, deadly_hug_cooldown_timer, deadly_hug_zone_y

    if deadly_hug_cooldown_timer > 0:
        deadly_hug_cooldown_timer -= 1

    # 돌진 페이즈
    if deadly_hug_rush_active:
        target_y = 630.0  # 플레이어 진영 상단 (Y=630~750)
        deadly_hug_rush_y += DEADLY_HUG_RUSH_SPEED
        if deadly_hug_rush_y >= target_y:
            deadly_hug_rush_y = target_y
            deadly_hug_rush_active = False
            deadly_hug_active = True
            deadly_hug_timer = DEADLY_HUG_DURATION
            deadly_hug_zone_y = target_y
            try:
                snd = pygame.mixer.Sound(resource_path(os.path.join("sounds", "boomstart.wav")))
                snd.set_volume(0.35 * sfx_volume)
                snd.play()
            except Exception:
                pass
        return

    if not deadly_hug_active:
        return

    deadly_hug_timer -= 1
    if deadly_hug_timer <= 0:
        deadly_hug_active = False


def is_deadly_hug_dash_blocked():
    """죽음의 포옹 영역 내에서 대쉬 사용 가능 여부 반환"""
    if not deadly_hug_active or not PLAYER:
        return False
    # 영역: 화면 중앙 기준 좌우 DEADLY_HUG_ZONE_WIDTH 폭
    zone_left = GAME_AREA_OFFSET_X + (GAME_PLAY_WIDTH - DEADLY_HUG_ZONE_WIDTH) // 2
    zone_right = zone_left + DEADLY_HUG_ZONE_WIDTH
    zone_top = int(deadly_hug_zone_y) - 30
    zone_bottom = 750  # 화면 하단까지
    px = PLAYER.centerx
    py = PLAYER.centery
    return zone_left <= px <= zone_right and zone_top <= py <= zone_bottom


def draw_deadly_hug_effect(screen):
    """죽음의 포옹 렌더링 (돌진 + 영역 표시)"""
    # 1) 돌진 모션 — 거대 테디베어 실루엣
    if deadly_hug_rush_active:
        rush_cx = GAME_AREA_OFFSET_X + GAME_PLAY_WIDTH // 2
        rush_cy = int(deadly_hug_rush_y)
        # 거대 곰 실루엣
        sf = pygame.Surface((160, 160), pygame.SRCALPHA)
        ct = 80
        pygame.draw.circle(sf, (180, 120, 100, 140), (ct, ct), 60)  # 몸통
        pygame.draw.circle(sf, (200, 140, 120, 160), (ct, ct - 30), 35)  # 머리
        pygame.draw.circle(sf, (160, 100, 80, 120), (ct - 30, ct - 55), 15)  # 왼귀
        pygame.draw.circle(sf, (160, 100, 80, 120), (ct + 30, ct - 55), 15)  # 오른귀
        # 단추 눈
        pygame.draw.circle(sf, (20, 20, 20, 200), (ct - 12, ct - 35), 5)
        pygame.draw.circle(sf, (20, 20, 20, 200), (ct + 12, ct - 35), 5)
        # X 모양 실밥 (입)
        pygame.draw.line(sf, (60, 30, 30, 180), (ct - 8, ct - 20), (ct + 8, ct - 14), 2)
        pygame.draw.line(sf, (60, 30, 30, 180), (ct - 8, ct - 14), (ct + 8, ct - 20), 2)
        screen.blit(sf, (rush_cx - ct, rush_cy - ct))

    # 2) 영역 표시
    if deadly_hug_active:
        zone_left = GAME_AREA_OFFSET_X + (GAME_PLAY_WIDTH - DEADLY_HUG_ZONE_WIDTH) // 2
        zone_top = int(deadly_hug_zone_y) - 30
        zone_w = DEADLY_HUG_ZONE_WIDTH
        zone_h = 750 - zone_top  # 화면 하단까지
        # 페이드 효과 (남은 시간 기반)
        if deadly_hug_timer < 60:
            fade = deadly_hug_timer / 60.0
        else:
            fade_in = min(1.0, (DEADLY_HUG_DURATION - deadly_hug_timer) / 30.0)
            fade = fade_in
        base_alpha = int(60 * fade)
        # 영역 배경 (어두운 갈색)
        zone_sf = pygame.Surface((zone_w, zone_h), pygame.SRCALPHA)
        zone_sf.fill((80, 40, 20, base_alpha))
        # 격자무늬 (봉제선 느낌)
        stitch_alpha = int(100 * fade)
        for sy in range(0, zone_h, 30):
            pygame.draw.line(zone_sf, (120, 80, 60, stitch_alpha),
                             (0, sy), (zone_w, sy), 1)
        for sx in range(0, zone_w, 30):
            pygame.draw.line(zone_sf, (120, 80, 60, stitch_alpha),
                             (sx, 0), (sx, zone_h), 1)
        screen.blit(zone_sf, (zone_left, zone_top))
        # 테두리 (실밥 느낌)
        border_alpha = int(160 * fade)
        border_sf = pygame.Surface((zone_w + 4, zone_h + 4), pygame.SRCALPHA)
        pygame.draw.rect(border_sf, (140, 80, 50, border_alpha),
                         (0, 0, zone_w + 4, zone_h + 4), 3)
        screen.blit(border_sf, (zone_left - 2, zone_top - 2))
        # "DASH BLOCKED" 텍스트 표시
        if deadly_hug_timer % 60 < 40:
            try:
                warn_font = pygame.font.Font(None, 20)
                warn_text = warn_font.render("NO DASH", True, (255, 100, 80))
                warn_text.set_alpha(int(200 * fade))
                screen.blit(warn_text, (zone_left + zone_w // 2 - warn_text.get_width() // 2,
                                        zone_top + 10))
            except Exception:
                pass
        # 중앙에 곰 팔 실루엣
        arm_alpha = int(80 * fade)
        arm_cx = zone_left + zone_w // 2
        arm_cy = zone_top + zone_h // 2
        arm_sf = pygame.Surface((zone_w, 80), pygame.SRCALPHA)
        # 왼팔
        pygame.draw.ellipse(arm_sf, (160, 110, 80, arm_alpha),
                            (10, 10, zone_w // 2 - 30, 60))
        # 오른팔
        pygame.draw.ellipse(arm_sf, (160, 110, 80, arm_alpha),
                            (zone_w // 2 + 20, 10, zone_w // 2 - 30, 60))
        screen.blit(arm_sf, (arm_cx - zone_w // 2, arm_cy - 40))


# =====================================================================
# === 테디베어 하트 빔 (Heart Beam, 구 단추 눈의 저주) - Stage 3 ===
# =====================================================================
def activate_button_eye():
    """하트 빔 발동 — 보스 눈에서 플레이어 방향으로 하트 투사체 발사"""
    global button_eye_active, heart_beam_projectile, heart_beam_trail
    if not BOSS or not PLAYER:
        return
    button_eye_active = True
    # 보스 눈 위치에서 플레이어 방향으로 발사
    start_x = float(BOSS.centerx)
    start_y = float(BOSS.bottom + 5)
    target_x = float(PLAYER.centerx)
    target_y = float(PLAYER.centery)
    dx = target_x - start_x
    dy = target_y - start_y
    dist = math.hypot(dx, dy)
    if dist < 1:
        dist = 1
    heart_beam_projectile = {
        "x": start_x,
        "y": start_y,
        "vx": (dx / dist) * HEART_BEAM_SPEED,
        "vy": (dy / dist) * HEART_BEAM_SPEED,
        "size": HEART_BEAM_SIZE,
    }
    heart_beam_trail = []
    try:
        snd = pygame.mixer.Sound(resource_path(os.path.join("sounds", "kissing.wav")))
        snd.set_volume(0.35 * sfx_volume)
        snd.play()
    except Exception:
        pass


def _trigger_heart_beam_knockback():
    """하트 빔 피격 — 0.5초간 3번 랜덤 좌우 넉백 스케줄 생성"""
    global heart_beam_knockback_active, heart_beam_knockback_timer
    global heart_beam_knockback_schedule
    heart_beam_knockback_active = True
    heart_beam_knockback_timer = HEART_BEAM_KNOCKBACK_DURATION
    # 3번 넉백: 0프레임, 14프레임, 28프레임에 각각 발동 (간격 넓혀서 탁-탁-탁 체감)
    heart_beam_knockback_schedule = []
    prev_dir = 0
    for i in range(3):
        frame = i * 24  # 0, 24, 48 (0초, 0.4초, 0.8초)
        # 이전과 다른 방향으로 넉백 (좌우 번갈아)
        direction = random.choice([-1, 1]) if prev_dir == 0 else -prev_dir
        prev_dir = direction
        strength = random.randint(60, 85)  # 넉백 거리 강화 (px)
        heart_beam_knockback_schedule.append({
            "frame": frame,
            "direction": direction,
            "strength": strength,
            "applied": False,
        })
    try:
        snd = pygame.mixer.Sound(resource_path(os.path.join("sounds", "bencylove.wav")))
        snd.set_volume(0.3 * sfx_volume)
        snd.play()
    except Exception:
        pass


def update_button_eye():
    """하트 빔 업데이트 — 투사체 이동 + 충돌 + 넉백"""
    global button_eye_active, button_eye_cooldown_timer
    global heart_beam_projectile, heart_beam_trail
    global heart_beam_knockback_active, heart_beam_knockback_timer
    global screen_shake_timer, screen_shake_intensity

    if button_eye_cooldown_timer > 0:
        button_eye_cooldown_timer -= 1

    # 넉백 업데이트
    if heart_beam_knockback_active:
        elapsed = HEART_BEAM_KNOCKBACK_DURATION - heart_beam_knockback_timer
        for kb in heart_beam_knockback_schedule:
            if not kb["applied"] and elapsed >= kb["frame"]:
                kb["applied"] = True
                if PLAYER:
                    # 좌우 넉백 적용
                    new_x = PLAYER.x + kb["direction"] * kb["strength"]
                    # 게임 영역 내로 클램핑
                    new_x = max(GAME_AREA_OFFSET_X, min(new_x, GAME_AREA_OFFSET_X + GAME_PLAY_WIDTH - PLAYER.width))
                    PLAYER.x = new_x
                    # 넉백마다 화면 흔들림 + 싸대기 사운드
                    screen_shake_timer = max(screen_shake_timer, 6)
                    screen_shake_intensity = max(screen_shake_intensity, 5)
                    try:
                        slap_snd = pygame.mixer.Sound(resource_path(os.path.join("sounds", "slap2.wav")))
                        slap_snd.set_volume(0.4 * sfx_volume)
                        slap_snd.play()
                    except Exception:
                        pass
                    # 하트 파편 파티클 생성 (6~10개)
                    px, py = PLAYER.centerx, PLAYER.centery - 5
                    for _ in range(random.randint(6, 10)):
                        angle = random.uniform(0, math.pi * 2)
                        spd = random.uniform(2.0, 5.5)
                        heart_beam_slap_particles.append({
                            "x": float(px), "y": float(py),
                            "vx": math.cos(angle) * spd + kb["direction"] * 2.0,
                            "vy": math.sin(angle) * spd - random.uniform(1.0, 3.0),
                            "life": 1.0,
                            "size": random.randint(3, 6),
                            "color": random.choice([
                                (255, 100, 150), (255, 140, 180), (255, 80, 130),
                                (255, 170, 200), (255, 60, 120),
                            ]),
                        })
        # 하트 파편 파티클 업데이트
        remove_idx = []
        for pi, p in enumerate(heart_beam_slap_particles):
            p["x"] += p["vx"]
            p["y"] += p["vy"]
            p["vy"] += 0.15  # 중력
            p["vx"] *= 0.96  # 감속
            p["life"] -= 0.04
            if p["life"] <= 0:
                remove_idx.append(pi)
        for pi in reversed(remove_idx):
            heart_beam_slap_particles.pop(pi)
        heart_beam_knockback_timer -= 1
        if heart_beam_knockback_timer <= 0:
            heart_beam_knockback_active = False
            heart_beam_knockback_schedule.clear()

    # 투사체 없으면 종료
    if heart_beam_projectile is None:
        if not heart_beam_knockback_active:
            button_eye_active = False
        return

    proj = heart_beam_projectile
    # 트레일 기록
    heart_beam_trail.append({"x": proj["x"], "y": proj["y"], "life": 1.0})
    # 트레일 페이드아웃
    trail_remove = []
    for i, t in enumerate(heart_beam_trail):
        t["life"] -= 0.06
        if t["life"] <= 0:
            trail_remove.append(i)
    for i in reversed(trail_remove):
        heart_beam_trail.pop(i)

    # 이동
    proj["x"] += proj["vx"]
    proj["y"] += proj["vy"]

    # 화면 밖으로 나가면 소멸
    if (proj["x"] < GAME_AREA_OFFSET_X - 40 or
        proj["x"] > GAME_AREA_OFFSET_X + GAME_PLAY_WIDTH + 40 or
            proj["y"] > HEIGHT + 40 or proj["y"] < -40):
        heart_beam_projectile = None
        return

    # 플레이어 충돌 판정
    if PLAYER and not heart_beam_knockback_active:
        ddx = proj["x"] - PLAYER.centerx
        ddy = proj["y"] - PLAYER.centery
        dist_sq = ddx * ddx + ddy * ddy
        if dist_sq < (HEART_BEAM_HIT_RADIUS + PLAYER.width // 2) ** 2:
            heart_beam_projectile = None
            heart_beam_trail.clear()
            _trigger_heart_beam_knockback()
            show_speech("하트빔~!", duration=50)
            return


def draw_button_eye_effect(screen):
    """하트 빔 렌더링 — 투사체 + 트레일 + 넉백 이펙트"""
    # 1) 트레일 (잔상)
    for t in heart_beam_trail:
        tx, ty = int(t["x"]), int(t["y"])
        alpha = int(180 * t["life"])
        sz = int(HEART_BEAM_SIZE * t["life"] * 0.8)
        if sz < 2 or alpha < 10:
            continue
        trail_sf = pygame.Surface((sz * 3, sz * 3), pygame.SRCALPHA)
        ct = sz * 3 // 2
        # 핑크 글로우
        pygame.draw.circle(trail_sf, (255, 130, 170, alpha // 3), (ct, ct), sz + 3)
        # 하트 모양 (간단)
        lobe = max(1, int(sz * 0.5))
        pygame.draw.circle(trail_sf, (255, 105, 150, alpha), (ct - lobe, ct - lobe // 2), lobe)
        pygame.draw.circle(trail_sf, (255, 105, 150, alpha), (ct + lobe, ct - lobe // 2), lobe)
        pygame.draw.polygon(trail_sf, (255, 105, 150, alpha), [
            (ct - sz, ct), (ct + sz, ct), (ct, ct + int(sz * 1.2))
        ])
        screen.blit(trail_sf, (tx - ct, ty - ct))

    # 2) 하트 빔 투사체
    if heart_beam_projectile is not None:
        proj = heart_beam_projectile
        cx, cy = int(proj["x"]), int(proj["y"])
        sz = proj["size"]

        # 글로우
        glow_r = sz + 8
        glow_sf = pygame.Surface((glow_r * 2, glow_r * 2), pygame.SRCALPHA)
        pygame.draw.circle(glow_sf, (255, 180, 210, 80), (glow_r, glow_r), glow_r)
        screen.blit(glow_sf, (cx - glow_r, cy - glow_r), special_flags=pygame.BLEND_ADD)

        # 하트 본체
        heart_sf = pygame.Surface((sz * 4, sz * 4), pygame.SRCALPHA)
        hc = sz * 2
        lobe = max(2, int(sz * 0.55))
        # 다크 아웃라인
        pygame.draw.circle(heart_sf, (210, 70, 115), (hc - lobe, hc - lobe // 2), lobe + 2)
        pygame.draw.circle(heart_sf, (210, 70, 115), (hc + lobe, hc - lobe // 2), lobe + 2)
        pygame.draw.polygon(heart_sf, (210, 70, 115), [
            (hc - sz - 2, hc + 1), (hc + sz + 2, hc + 1), (hc, hc + int(sz * 1.3))
        ])
        # 메인 핑크
        pygame.draw.circle(heart_sf, (255, 105, 150), (hc - lobe, hc - lobe // 2), lobe)
        pygame.draw.circle(heart_sf, (255, 105, 150), (hc + lobe, hc - lobe // 2), lobe)
        pygame.draw.polygon(heart_sf, (255, 105, 150), [
            (hc - sz, hc), (hc + sz, hc), (hc, hc + int(sz * 1.2))
        ])
        # 하이라이트
        hl = max(1, lobe // 2)
        pygame.draw.circle(heart_sf, (255, 180, 210), (hc - lobe, hc - lobe), hl)
        screen.blit(heart_sf, (cx - hc, cy - hc))

    # 3) 넉백 이펙트 (탁! 마다 하트 파티클 버스트)
    if heart_beam_knockback_active and PLAYER:
        elapsed = HEART_BEAM_KNOCKBACK_DURATION - heart_beam_knockback_timer
        for kb in heart_beam_knockback_schedule:
            if kb["applied"]:
                kb_age = elapsed - kb["frame"]
                if 0 <= kb_age < 8:  # 짧고 간결 (8프레임 = 0.13초)
                    t = kb_age / 8.0
                    alpha = int(255 * (1.0 - t))
                    pcx = PLAYER.centerx
                    pcy = PLAYER.centery - 5
                    # 3개 하트가 넉백 방향으로 탁! 퍼짐
                    for hi in range(3):
                        spread_x = kb["direction"] * (10 + hi * 18) * t
                        spread_y = (-12 + hi * 12) * t - 5 * (1.0 - t)
                        sz = int(6 + 3 * (1.0 - t))  # 점점 작아짐
                        hx = int(pcx + spread_x)
                        hy = int(pcy + spread_y)
                        hs = pygame.Surface((sz * 3, sz * 3), pygame.SRCALPHA)
                        hc = sz * 3 // 2
                        lb = max(1, int(sz * 0.5))
                        c = (255, 100 + hi * 30, 160, alpha)
                        pygame.draw.circle(hs, c, (hc - lb, hc - lb), lb)
                        pygame.draw.circle(hs, c, (hc + lb, hc - lb), lb)
                        pygame.draw.polygon(hs, c, [
                            (hc - sz, hc), (hc + sz, hc), (hc, hc + sz)
                        ])
                        screen.blit(hs, (hx - hc, hy - hc))

    # 4) 하트 파편 파티클 렌더링
    for p in heart_beam_slap_particles:
        alpha = int(255 * max(0, p["life"]))
        sz = p["size"]
        if sz < 1 or alpha < 10:
            continue
        ps = pygame.Surface((sz * 3, sz * 3), pygame.SRCALPHA)
        pc = sz * 3 // 2
        lb = max(1, int(sz * 0.45))
        c = (*p["color"], alpha)
        # 미니 하트 모양
        pygame.draw.circle(ps, c, (pc - lb, pc - lb), lb)
        pygame.draw.circle(ps, c, (pc + lb, pc - lb), lb)
        pygame.draw.polygon(ps, c, [
            (pc - sz, pc), (pc + sz, pc), (pc, pc + sz)
        ])
        screen.blit(ps, (int(p["x"]) - pc, int(p["y"]) - pc))


# === 각시탈 부채바람 스킬 (소용돌이) ===
def activate_fan_wind():
    """부채바람 발동 — 1초 부채질 충전 후 소용돌이 생성"""
    global fan_wind_charging, fan_wind_charge_timer, fan_wind_growth_scale
    global fan_wind_active, fan_wind_timer, fan_wind_zone_x, fan_wind_zone_y
    global fan_wind_drift_vx, fan_wind_drift_timer, fan_wind_used_this_round
    global fan_wind_captured, fan_wind_capture_timer, fan_wind_capture_angle, fan_wind_capture_radius
    fan_wind_charging = True
    fan_wind_charge_timer = 60  # 1초 부채질 선딜
    fan_wind_growth_scale = 0.0
    fan_wind_used_this_round = True
    # 소용돌이 위치: 보스 패들 바로 앞에서 생성
    boss_cx = float(BOSS.centerx if BOSS else GAME_AREA_OFFSET_X + GAME_PLAY_WIDTH // 2)
    boss_bottom = float((BOSS.y + BOSS.height + 10) if BOSS else 75)
    fan_wind_zone_x = boss_cx + random.randint(-30, 30)
    fan_wind_zone_y = boss_bottom
    # 나머지 초기화
    fan_wind_active = False
    fan_wind_timer = 240
    fan_wind_drift_vx = random.uniform(-1.2, 1.2)
    fan_wind_drift_timer = random.randint(30, 60)
    fan_wind_captured = False
    fan_wind_capture_timer = 0
    fan_wind_capture_angle = 0.0
    fan_wind_capture_radius = 0.0


def update_fan_wind():
    """부채바람 충전 + 소용돌이 이동 + 공 포획"""
    global fan_wind_active, fan_wind_timer, fan_wind_zone_x, fan_wind_zone_y
    global fan_wind_drift_vx, fan_wind_drift_timer
    global fan_wind_captured, fan_wind_capture_timer, fan_wind_capture_angle, fan_wind_capture_radius
    global fan_wind_charging, fan_wind_charge_timer, fan_wind_growth_scale
    global ball_vel

    # --- 부채질 충전 단계 (1초) ---
    if fan_wind_charging:
        fan_wind_charge_timer -= 1
        charge_progress = 1.0 - (fan_wind_charge_timer / 60.0)  # 0→1
        fan_wind_growth_scale = charge_progress  # 소용돌이 크기 성장
        if fan_wind_charge_timer <= 0:
            fan_wind_charging = False
            fan_wind_active = True
            fan_wind_growth_scale = 1.0
        return  # 충전 중에는 소용돌이 이동 안함

    if not fan_wind_active:
        return

    fan_wind_timer -= 1

    # --- 공이 소용돌이에 포획된 상태 ---
    if fan_wind_captured:
        fan_wind_capture_timer += 1
        capture_duration = 60

        if fan_wind_capture_timer >= capture_duration:
            release_angle = random.uniform(0, math.pi * 2)
            release_speed = random.uniform(12.0, 16.0)
            ball_vel[0] = math.cos(release_angle) * release_speed
            ball_vel[1] = math.sin(release_angle) * release_speed
            if ball_vel[1] < 0:
                ball_vel[1] = abs(ball_vel[1])
            fan_wind_captured = False
            fan_wind_capture_timer = 0
        else:
            progress = fan_wind_capture_timer / capture_duration
            if progress < 0.6:
                fan_wind_capture_radius = max(3.0, fan_wind_capture_radius * 0.96)
            else:
                fan_wind_capture_radius = min(55.0, fan_wind_capture_radius * 1.06)
            spin_speed = 0.25 + progress * 0.35
            fan_wind_capture_angle += spin_speed
            if BALL:
                BALL.centerx = int(fan_wind_zone_x + math.cos(fan_wind_capture_angle) * fan_wind_capture_radius)
                BALL.centery = int(fan_wind_zone_y + math.sin(fan_wind_capture_angle) * fan_wind_capture_radius)
            ball_vel[0] = 0.0
            ball_vel[1] = 0.0

    # --- 소용돌이 이동 ---
    fan_wind_zone_y += 0.6
    fan_wind_zone_x += fan_wind_drift_vx
    fan_wind_drift_timer -= 1
    if fan_wind_drift_timer <= 0:
        fan_wind_drift_vx = random.uniform(-1.5, 1.5)
        fan_wind_drift_timer = random.randint(25, 55)
    left_bound = float(GAME_AREA_OFFSET_X + 30)
    right_bound = float(GAME_AREA_OFFSET_X + GAME_PLAY_WIDTH - 30)
    if fan_wind_zone_x < left_bound:
        fan_wind_zone_x = left_bound
        fan_wind_drift_vx = abs(fan_wind_drift_vx)
    elif fan_wind_zone_x > right_bound:
        fan_wind_zone_x = right_bound
        fan_wind_drift_vx = -abs(fan_wind_drift_vx)

    if fan_wind_timer <= 0 or fan_wind_zone_y > 720:
        if fan_wind_captured:
            release_angle = random.uniform(-math.pi * 0.8, -math.pi * 0.2)
            release_speed = 13.0
            ball_vel[0] = math.cos(release_angle) * release_speed
            ball_vel[1] = abs(math.sin(release_angle)) * release_speed
            fan_wind_captured = False
        fan_wind_active = False


def check_fan_wind_effect():
    """공이 소용돌이 반경 안에 들어오면 포획"""
    global fan_wind_captured, fan_wind_capture_timer, fan_wind_capture_angle, fan_wind_capture_radius
    global ball_vel
    if not fan_wind_active or fan_wind_captured:
        return
    if not BALL:
        return
    bx = BALL.centerx
    by = BALL.centery
    dx = bx - fan_wind_zone_x
    dy = by - fan_wind_zone_y
    dist = math.sqrt(dx * dx + dy * dy)
    vortex_radius = 42  # 포획 반경 50% 확대 (28 → 42)
    if dist < vortex_radius:
        fan_wind_captured = True
        fan_wind_capture_timer = 0
        fan_wind_capture_radius = max(dist, 8.0)
        fan_wind_capture_angle = math.atan2(dy, dx)
        ball_vel[0] = 0.0
        ball_vel[1] = 0.0


def draw_fan_wind_effect(screen):
    """소용돌이 시각 이펙트 (현실적 바람 느낌 + 크기 성장 + 부채질 애니메이션)"""
    is_charging = fan_wind_charging
    is_active = fan_wind_active

    if not is_charging and not is_active:
        return

    zx = int(fan_wind_zone_x)
    zy = int(fan_wind_zone_y)
    t = pygame.time.get_ticks() / 1000.0

    # --- 부채질 충전 애니메이션 (보스 위치에서) ---
    if is_charging and BOSS:
        charge_p = 1.0 - (fan_wind_charge_timer / 60.0)  # 0→1
        boss_cx = BOSS.centerx
        boss_cy = BOSS.y + BOSS.height + 5

        # 부채를 크게 부채질 (좌→우→좌 반복, 점점 빨라짐)
        swing_freq = 3.0 + charge_p * 5.0  # 속도 증가
        swing_angle = math.sin(charge_p * math.pi * swing_freq) * math.radians(50) + math.pi * 0.5
        fan_size = int(14 + 6 * charge_p)
        _draw_fan_shape(screen, boss_cx, boss_cy, swing_angle, fan_size)

        # 잔상
        for trail_i in range(1, 3):
            trail_p = max(0.0, charge_p - trail_i * 0.05)
            trail_angle = math.sin(trail_p * math.pi * swing_freq) * math.radians(50) + math.pi * 0.5
            _draw_fan_shape(screen, boss_cx, boss_cy, trail_angle, fan_size - trail_i, max(30, 100 - trail_i * 35))

        # 바람 줄기 (보스→소용돌이 방향)
        wind_intensity = charge_p
        for wi in range(int(3 + 5 * charge_p)):
            w_progress = (wi / 8.0 + t * 2.0) % 1.0
            wx = boss_cx + (zx - boss_cx) * w_progress + math.sin(t * 10 + wi) * 8
            wy = boss_cy + (zy - boss_cy) * w_progress + math.cos(t * 8 + wi) * 4
            w_len = 6 + int(10 * wind_intensity)
            w_alpha = int(80 * wind_intensity * (1.0 - w_progress))
            dx_n = zx - boss_cx
            dy_n = zy - boss_cy
            d_n = math.sqrt(dx_n * dx_n + dy_n * dy_n)
            if d_n > 1:
                dx_n /= d_n
                dy_n /= d_n
            pygame.draw.line(screen, (200, 230, 255, w_alpha),
                             (int(wx), int(wy)),
                             (int(wx + dx_n * w_len), int(wy + dy_n * w_len)), 1)

    # --- 소용돌이 본체 (모래회오리 구조 + 바람 색상) ---
    scale = fan_wind_growth_scale if is_charging else 1.0
    fade = min(1.0, fan_wind_timer / 30.0) if (is_active and fan_wind_timer < 30) else 1.0
    eff_fade = fade * max(0.15, scale)

    base_vortex_r = 39
    vortex_r = max(4, int(base_vortex_r * scale))
    alpha = int(255 * eff_fade)
    rot = t * 200  # 회전 각도 (도)
    age = t

    surf_size = int(vortex_r * 3.5)
    if surf_size >= 4:
        vortex_surf = pygame.Surface((surf_size * 2, surf_size * 2), pygame.SRCALPHA)
        cx_s, cy_s = surf_size, surf_size

        # 1) 바깥쪽 바람구름 (8개 반투명 대형 원)
        for i in range(8):
            cloud_angle = math.radians(rot * 0.5 + i * 45 + age * 60)
            cloud_dist = vortex_r * (0.6 + 0.4 * math.sin(age * 2 + i))
            cloud_x = cx_s + math.cos(cloud_angle) * cloud_dist
            cloud_y = cy_s + math.sin(cloud_angle) * cloud_dist
            cloud_r = int(vortex_r * random.uniform(0.35, 0.6))
            cloud_alpha = max(0, min(255, int(alpha * 0.25)))
            r_c = min(255, 160 + int(40 * math.sin(i * 0.7)))
            g_c = min(255, 190 + int(30 * math.sin(i * 1.1)))
            b_c = 255
            pygame.draw.circle(vortex_surf, (r_c, g_c, b_c, cloud_alpha),
                               (int(cloud_x), int(cloud_y)), max(1, cloud_r))

        # 2) 중간층 빠른 회전 나선 (8겹)
        for layer in range(8):
            radius = vortex_r - layer * 4
            if radius < 4:
                break
            layer_alpha = max(0, min(255, int(alpha * 0.7) - layer * 20))
            r_c = min(255, 170 + layer * 8)
            g_c = min(255, 200 + layer * 5)
            b_c = 255
            color = (r_c, g_c, b_c, layer_alpha)
            points = []
            angle_start = math.radians(rot * 1.3 + layer * 40)
            for a_deg in range(0, 420, 8):
                rad = math.radians(a_deg) + angle_start
                r = radius * (1 - a_deg / 1400)
                if r < 2:
                    break
                px = cx_s + math.cos(rad) * r
                py = cy_s + math.sin(rad) * r
                points.append((int(px), int(py)))
            if len(points) > 2:
                line_w = max(1, 4 - layer // 2)
                pygame.draw.lines(vortex_surf, color, False, points, line_w)

        # 3) 내부 밝은 코어
        core_alpha = max(0, min(255, int(alpha * 0.5)))
        pygame.draw.circle(vortex_surf, (200, 220, 255, core_alpha), (cx_s, cy_s), max(1, int(vortex_r * 0.35)))
        pygame.draw.circle(vortex_surf, (220, 235, 255, max(0, min(255, int(alpha * 0.7)))),
                           (cx_s, cy_s), max(1, int(vortex_r * 0.2)))
        pygame.draw.circle(vortex_surf, (240, 248, 255, min(255, int(alpha * 0.9))),
                           (cx_s, cy_s), max(1, 5))

        # 4) 바람 알갱이 노이즈 (12개)
        for _ in range(12):
            grain_angle = random.uniform(0, math.pi * 2)
            grain_dist = random.uniform(4, vortex_r * 0.9)
            gx = cx_s + math.cos(grain_angle) * grain_dist
            gy = cy_s + math.sin(grain_angle) * grain_dist
            grain_alpha = max(0, min(255, int(alpha * random.uniform(0.3, 0.7))))
            grain_size = random.randint(1, 3)
            pygame.draw.circle(vortex_surf, (200, 220, 250, grain_alpha),
                               (int(gx), int(gy)), grain_size)

        screen.blit(vortex_surf, (zx - surf_size, zy - surf_size))

    # --- 포획 중: 공 주위 회전 링 ---
    if fan_wind_captured:
        cap_r = max(5, int(fan_wind_capture_radius))
        for i in range(6):
            a = fan_wind_capture_angle + i * (math.pi * 2 / 6)
            dot_x = zx + int(math.cos(a) * cap_r * 1.15)
            dot_y = zy + int(math.sin(a) * cap_r * 1.15)
            da = max(30, int(120 * eff_fade) - i * 15)
            pygame.draw.circle(screen, (210, 230, 255, da), (dot_x, dot_y), 2)


# === 포도대장 포졸소환 스킬 ===
def activate_patrol_guards():
    """포졸소환 스킬 활성화 — 보스 근처에 포졸 2명 배치"""
    global patrol_guards_active, patrol_guards_timer, patrol_guards, patrol_guards_used_this_round

    patrol_guards_active = True
    patrol_guards_timer = patrol_guards_duration
    patrol_guards_used_this_round = True

    boss_bottom_y = (BOSS.y + BOSS.height + 30) if BOSS else 95
    game_left = GAME_AREA_OFFSET_X + 60
    game_right = GAME_AREA_OFFSET_X + GAME_PLAY_WIDTH - 60
    third = (game_right - game_left) / 3

    patrol_guards = []
    for i in range(2):
        spawn_x = game_left + third * (i + 1)
        patrol_guards.append({
            "x": float(spawn_x),
            "y": float(boss_bottom_y),
            "target_x": None,
            "wait_timer": random.randint(10, 30),  # 소환 직후 잠시 대기
            "patrol_speed": random.uniform(110.0, 180.0),
            "direction": 1 if i == 0 else -1,
            "walk_frame": 0.0,
            "alpha": 255,
            "push_vx": 0.0,   # 공 충돌 시 밀림
            "push_timer": 0,
        })

    try:
        play_sound_with_volume(SOUND_THROW_BEFORE)
    except Exception:
        pass


def update_patrol_guards():
    """포졸 어슬렁거리기 업데이트 (매 프레임)"""
    global patrol_guards_active, patrol_guards_timer, patrol_guards

    if not patrol_guards_active or not patrol_guards:
        return

    patrol_guards_timer -= arena_speed_multiplier

    game_left = GAME_AREA_OFFSET_X + 40
    game_right = GAME_AREA_OFFSET_X + GAME_PLAY_WIDTH - 40
    dt = (1.0 / 60.0) * arena_speed_multiplier  # 배속 적용

    for guard in patrol_guards:
        # 페이드아웃 (마지막 30프레임)
        if patrol_guards_timer <= 30:
            guard["alpha"] = max(0, int(255 * (patrol_guards_timer / 30.0)))

        # 밀림 처리 (공 충돌 후)
        if guard["push_timer"] > 0:
            guard["push_timer"] -= 1
            guard["x"] += guard["push_vx"]
            guard["push_vx"] *= 0.85  # 감속
            guard["x"] = max(game_left, min(game_right, guard["x"]))
            continue

        # 대기 중
        if guard["wait_timer"] > 0:
            guard["wait_timer"] -= 1
            # 제자리 미세 흔들림
            guard["walk_frame"] += 0.02
            continue

        # 목표 없으면 새 목표 설정
        if guard["target_x"] is None:
            guard["target_x"] = random.uniform(game_left + 20, game_right - 20)
            guard["patrol_speed"] = random.uniform(110.0, 180.0)

        # 목표로 이동
        diff = guard["target_x"] - guard["x"]
        if abs(diff) < 3.0:
            # 도착
            guard["x"] = guard["target_x"]
            guard["target_x"] = None
            guard["wait_timer"] = random.randint(24, 90)  # 0.4~1.5초 대기
        else:
            direction = 1 if diff > 0 else -1
            guard["direction"] = direction
            move = direction * guard["patrol_speed"] * dt
            if abs(move) > abs(diff):
                move = diff
            guard["x"] += move
            guard["x"] = max(game_left, min(game_right, guard["x"]))
            # 걸음 애니메이션
            guard["walk_frame"] += abs(move) * 0.15

    # 타이머 종료
    if patrol_guards_timer <= 0:
        patrol_guards_active = False
        patrol_guards = []


def check_patrol_guard_collision():
    """포졸과 공의 충돌 체크"""
    global ball_vel

    if not patrol_guards_active or not patrol_guards:
        return False

    for guard in patrol_guards:
        if guard["alpha"] < 128:  # 페이드아웃 중이면 충돌 없음
            continue

        guard_radius = 18
        dx = BALL.centerx - guard["x"]
        dy = BALL.centery - guard["y"]
        distance = math.sqrt(dx * dx + dy * dy)

        if distance < guard_radius + BALL_RADIUS:
            # 공 랜덤 방향 반사
            random_angle = random.uniform(0, 2 * math.pi)
            speed = math.sqrt(ball_vel[0] ** 2 + ball_vel[1] ** 2)
            ball_vel[0] = math.cos(random_angle) * speed
            ball_vel[1] = math.sin(random_angle) * speed

            # 포졸 밀림
            if distance > 0:
                push_angle = math.atan2(-dy, -dx)
            else:
                push_angle = random.uniform(0, 2 * math.pi)
            guard["push_vx"] = math.cos(push_angle) * 8.0
            guard["push_timer"] = 10

            # 이펙트
            create_impact_effect(guard["x"], guard["y"], [0, 0], is_player=False)
            play_paddle_sound()
            return True

    return False


def draw_patrol_guards(screen):
    """포졸 프로시저럴 렌더링"""
    if not patrol_guards_active or not patrol_guards:
        return

    import math as _math

    for guard in patrol_guards:
        gx = int(guard["x"])
        gy = int(guard["y"])
        alpha = guard["alpha"]
        direction = guard["direction"]  # 1=right, -1=left
        walk = guard["walk_frame"]

        # 걸음 흔들림
        walk_offset_y = int(_math.sin(walk * 0.8) * 2)
        leg_phase = _math.sin(walk * 0.8)

        surf = pygame.Surface((32, 44), pygame.SRCALPHA)
        cx, cy = 16, 22  # 중심

        # --- 다리 (먼저 — 아래 레이어) ---
        leg_color = (50, 50, 80, alpha)   # 남색 바지
        shoe_color = (60, 40, 20, alpha)  # 갈색 신발
        leg_spread = int(leg_phase * 3)
        # 왼발
        pygame.draw.line(surf, leg_color, (cx - 3, cy + 10), (cx - 3 - leg_spread, cy + 18), 3)
        pygame.draw.circle(surf, shoe_color, (cx - 3 - leg_spread, cy + 19), 2)
        # 오른발
        pygame.draw.line(surf, leg_color, (cx + 3, cy + 10), (cx + 3 + leg_spread, cy + 18), 3)
        pygame.draw.circle(surf, shoe_color, (cx + 3 + leg_spread, cy + 19), 2)

        # --- 몸통 (남색 관복) ---
        body_color = (40, 55, 100, alpha)
        body_light = (55, 70, 120, alpha)
        # 관복 몸통 (사다리꼴)
        body_points = [(cx - 7, cy - 4), (cx + 7, cy - 4), (cx + 9, cy + 11), (cx - 9, cy + 11)]
        pygame.draw.polygon(surf, body_color, body_points)
        # 관복 밝은 앞면
        front_points = [(cx - 2, cy - 4), (cx + 2, cy - 4), (cx + 3, cy + 11), (cx - 3, cy + 11)]
        pygame.draw.polygon(surf, body_light, front_points)
        # 허리띠
        belt_color = (120, 90, 50, alpha)
        pygame.draw.line(surf, belt_color, (cx - 8, cy + 4), (cx + 8, cy + 4), 2)

        # --- 팔 ---
        arm_color = (40, 55, 100, alpha)
        skin_color = (210, 180, 140, alpha)
        arm_swing = int(leg_phase * 2)
        # 왼팔 (곤봉 들기)
        pygame.draw.line(surf, arm_color, (cx - 7, cy - 1), (cx - 11, cy + 5 - arm_swing), 2)
        pygame.draw.circle(surf, skin_color, (cx - 11, cy + 5 - arm_swing), 2)
        # 곤봉
        stick_color = (100, 60, 30, alpha)
        pygame.draw.line(surf, stick_color, (cx - 11, cy + 3 - arm_swing), (cx - 11, cy - 6 - arm_swing), 2)
        # 오른팔
        pygame.draw.line(surf, arm_color, (cx + 7, cy - 1), (cx + 11, cy + 5 + arm_swing), 2)
        pygame.draw.circle(surf, skin_color, (cx + 11, cy + 5 + arm_swing), 2)

        # --- 머리 ---
        head_color = (210, 180, 140, alpha)
        pygame.draw.circle(surf, head_color, (cx, cy - 8), 5)
        # 눈
        eye_color = (30, 30, 30, alpha)
        eye_dx = 2 * direction
        pygame.draw.circle(surf, eye_color, (cx + eye_dx - 1, cy - 9), 1)
        pygame.draw.circle(surf, eye_color, (cx + eye_dx + 2, cy - 9), 1)

        # --- 흑립 (갓 모양 모자) ---
        hat_color = (20, 20, 20, alpha)
        hat_rim_color = (35, 35, 35, alpha)
        # 모자 윗부분 (둥근 원통)
        pygame.draw.ellipse(surf, hat_color, (cx - 4, cy - 17, 8, 6))
        # 모자 챙 (넓은 타원)
        pygame.draw.ellipse(surf, hat_rim_color, (cx - 8, cy - 13, 16, 4))
        pygame.draw.ellipse(surf, hat_color, (cx - 7, cy - 13, 14, 3))

        # 방향에 따라 좌우반전
        if direction == -1:
            surf = pygame.transform.flip(surf, True, False)

        screen.blit(surf, (gx - 16, gy - 22 + walk_offset_y))


def handle_spinning_top():
    """팽이 업데이트 처리"""
    global spinning_top_active, spinning_top_timer, spinning_tops, whip_animation_timer, top_collision_cooldown, golden_top_star_cooldown
    
    if not spinning_top_active or not spinning_tops:
        return
    
    # 충돌 쿨다운 감소
    if top_collision_cooldown > 0:
        top_collision_cooldown -= 1
    
    # 황금 팽이 별 생성 쿨다운 감소
    if golden_top_star_cooldown > 0:
        golden_top_star_cooldown -= 1
    
    if spinning_top_timer > 0:
        spinning_top_timer -= 1
        
        # 채찍 애니메이션 단계 (처음 0.6초)
        if whip_animation_timer > 0:
            whip_animation_timer -= 1
            if whip_animation_timer == 18:  # 0.3초 시점에 팽이 회전 시작
                for top in spinning_tops:
                    top["whip_phase"] = "spinning"
            return  # 채찍 애니메이션 중에는 팽이가 움직이지 않음
        
        # 팽이끼리 충돌 체크
        if len(spinning_tops) == 2 and top_collision_cooldown <= 0:
            top1, top2 = spinning_tops[0], spinning_tops[1]
            dx = top1["x"] - top2["x"]
            dy = top1["y"] - top2["y"]
            distance = math.sqrt(dx*dx + dy*dy)
            
            # 충돌 판정 (두 팽이가 가까워졌을 때)
            if distance < 40:  # 충돌 거리
                # 충돌 효과
                create_impact_effect(
                    (top1["x"] + top2["x"]) / 2,
                    (top1["y"] + top2["y"]) / 2,
                    [0, 0], is_player=False
                )
                
                # 효과음
                play_paddle_sound()

                # 400% 속도 부스트 (0.3초)
                angle = math.atan2(dy, dx)
                boost_speed = 8.0  # 400% 속도
                
                # 서로 반대 방향으로 튕겨나감
                top1["vx"] = math.cos(angle) * boost_speed
                top1["vy"] = math.sin(angle) * boost_speed * 0.3  # y축은 약하게
                top1["speed_boost"] = 4.0
                top1["boost_timer"] = 18  # 0.3초
                
                top2["vx"] = -math.cos(angle) * boost_speed
                top2["vy"] = -math.sin(angle) * boost_speed * 0.3
                top2["speed_boost"] = 4.0
                top2["boost_timer"] = 18
                
                # 충돌 쿨다운 설정
                top_collision_cooldown = 60  # 1초 쿨다운
                
                # 황금 팽이 충돌 시 트레이드 별 생성
                if golden_top_star_cooldown <= 0:
                    # 둘 중 하나라도 황금 팽이면 별 생성
                    if (top1.get("is_golden", False) and not top1.get("star_spawned", False)) or \
                       (top2.get("is_golden", False) and not top2.get("star_spawned", False)):
                        if trade_point_system:
                            # 충돌 지점의 중간 위치에 별 생성
                            star_x = (top1["x"] + top2["x"]) / 2
                            star_y = (top1["y"] + top2["y"]) / 2
                            trade_point_system.spawn_star(star_x, star_y, "golden_top")
                            
                            # 황금 팽이 표시 업데이트
                            if top1.get("is_golden", False):
                                top1["star_spawned"] = True
                            if top2.get("is_golden", False):
                                top2["star_spawned"] = True
                            
                            golden_top_star_cooldown = 30  # 0.5초 쿨타임
                            # print(f"   !   !")
                
                # print(f"  !   !")
        
        # 각 팽이 업데이트
        for i, top in enumerate(spinning_tops):
            if spinning_top_timer > 30:  # 쓰러지기 전까지
                # 부스트 타이머 처리
                if top["boost_timer"] > 0:
                    top["boost_timer"] -= 1
                    if top["boost_timer"] == 0:
                        # 원래 속도로 복귀
                        top["speed_boost"] = 0
                        top["vx"] *= 0.25  # 원래 속도로
                        top["vy"] = 0.6  # 원래 하강 속도
                
                # 회전
                top["rotation"] += top["rotation_speed"]
                
                # 지그재그 움직임 타이머 증가
                top["zigzag_timer"] += 1
                
                # 부스트 상태가 아닐 때만 일반 움직임
                if top["boost_timer"] <= 0:
                    # 예측불가능한 좌우 움직임
                    if top["zigzag_timer"] % random.randint(20, 40) == 0:
                        top["vx"] = random.uniform(-2.0, 2.0)
                    
                    # 부드러운 좌우 움직임을 위한 사인파
                    wave_x = math.sin(top["zigzag_timer"] * 0.1) * 0.5
                    top["x"] += top["vx"] + wave_x
                    top["y"] += top["vy"]
                else:
                    # 부스트 중일 때는 빠른 속도로 이동
                    top["x"] += top["vx"]
                    top["y"] += top["vy"]
                
                # 화면 경계 체크
                if top["x"] < 40 or top["x"] > WIDTH - 40:
                    top["vx"] *= -1  # 방향 반전
                    top["x"] = max(40, min(WIDTH - 40, top["x"]))
                
                # 천천히 하강 (부스트 상태가 아닐 때)
                if top["y"] < HEIGHT - 100 and top["boost_timer"] <= 0:
                    top["vy"] = 0.6  # 일정한 하강 속도
                
            elif spinning_top_timer > 0:  # 마지막 0.5초 - 쓰러지는 애니메이션
                # 회전 속도 감소
                top["rotation_speed"] *= 0.92
                
                # 기울어짐
                top["tilt"] = 90 * (1 - spinning_top_timer / 30)  # 0도에서 90도로
                
                # 페이드아웃
                top["alpha"] = int(255 * (spinning_top_timer / 30))
    else:
        # 스킬 종료
        spinning_top_active = False
        spinning_tops = []
        # print("!")

def check_spinning_top_collision():
    """팽이와 공의 충돌 체크"""
    global ball_vel, golden_top_star_cooldown, trade_point_system
    
    if not spinning_top_active or not spinning_tops:
        return False
    
    # 채찍 애니메이션 중에도 충돌 체크를 해야 함 (삭제)
    
    # 각 팽이와 공의 충돌 체크
    for top in spinning_tops:
        # 쓰러진 상태에서는 충돌 없음
        if top.get("tilt", 0) > 45:
            continue
        
        # 팽이 히트박스 (원형)
        top_radius = 20  # 줄어든 크기에 맞춰 히트박스도 감소
        ball_center = (BALL.centerx, BALL.centery)
        top_center = (top["x"], top["y"])
        
        # 거리 계산
        dx = ball_center[0] - top_center[0]
        dy = ball_center[1] - top_center[1]
        distance = math.sqrt(dx*dx + dy*dy)
        
        # 충돌 판정
        if distance < top_radius + BALL_RADIUS:
            # 황금 팽이인 경우 트레이드 별 생성 (쿨타임 체크)
            if top.get("is_golden", False) and not top.get("star_spawned", False) and golden_top_star_cooldown <= 0:
                if trade_point_system:
                    # 팽이 위치에서 트레이드 별 생성
                    trade_point_system.spawn_star(top["x"], top["y"], "golden_top")
                    top["star_spawned"] = True  # 이 팽이에서 별 생성 완료
                    golden_top_star_cooldown = 30  # 0.5초 쿨타임 (60 FPS)
                    # print(f"   !   !")
            
            # 무작위 방향으로 반사
            random_angle = random.uniform(0, 2 * math.pi)
            speed = math.sqrt(ball_vel[0]**2 + ball_vel[1]**2)
            
            ball_vel[0] = math.cos(random_angle) * speed
            ball_vel[1] = math.sin(random_angle) * speed
            
            # 팽이에 튕김 효과 추가 (하프 대쉬 정도의 거리)
            # 충돌 반대 방향으로 밀려남
            if distance > 0:  # 0으로 나누기 방지
                push_angle = math.atan2(-dy, -dx)  # 공의 반대 방향
            else:
                push_angle = random.uniform(0, 2 * math.pi)
            
            # 하프 대쉬 거리 정도의 순간 가속 (약 30-40픽셀)
            push_speed = 12.0  # 순간적으로 빠른 속도
            top["vx"] = math.cos(push_angle) * push_speed
            top["vy"] = math.sin(push_angle) * push_speed * 0.5  # y축은 약간 약하게
            top["speed_boost"] = 3.0  # 속도 부스트 상태
            top["boost_timer"] = 12  # 0.2초간 지속 (짧게)
            
            # 충돌 효과 생성
            create_impact_effect(top_center[0], top_center[1], [0, 0], is_player=False)
            
            # 효과음 재생
            play_paddle_sound()

            # print(f"  !  !  : {math.degrees(random_angle):.0f}°")
            return True
    
    return False

def draw_whip_waves(screen):
    """상모돌리기 파동 효과 그리기"""
    global whip_wave_particles
    
    if not whip_active or not whip_wave_particles:
        return
    
    # 파동 그리기
    for particle in whip_wave_particles:
        # 파동 색상 (보라색 계열)
        color = (180, 100, 255)
        alpha = particle['alpha']
        
        if alpha > 0:
            # 파동 원 그리기
            wave_surface = pygame.Surface((particle['radius'] * 2, particle['radius'] * 2), pygame.SRCALPHA)
            pygame.draw.circle(wave_surface, (*color, alpha // 2), 
                             (particle['radius'], particle['radius']), 
                             particle['radius'], 3)
            
            # 내부 원 (더 밝게)
            if particle['radius'] > 5:
                pygame.draw.circle(wave_surface, (*color, alpha), 
                                 (particle['radius'], particle['radius']), 
                                 max(1, particle['radius'] - 5), 2)
            
            screen.blit(wave_surface, 
                       (particle['x'] - particle['radius'], 
                        particle['y'] - particle['radius']))

def draw_spinning_top(screen):
    """팽이 그리기"""
    if not spinning_top_active or not spinning_tops:
        return
    
    # 채찍 애니메이션 그리기 (처음 0.6초)
    if whip_animation_timer > 0:
        # 각 팽이에 대한 채찍 그리기
        for top in spinning_tops:
            whip_start = (BOSS.centerx, BOSS.centery)
            whip_end = (top["x"], top["y"])
        
            # 채찍 곡선 효과
            control_x = (whip_start[0] + whip_end[0]) / 2 + math.sin(whip_animation_timer * 0.5) * 30
            control_y = (whip_start[1] + whip_end[1]) / 2 - 20
            
            # 채찍 그리기 (베지어 곡선처럼)
            for i in range(10):
                t = i / 10
                x1 = whip_start[0] * (1-t)**2 + control_x * 2*t*(1-t) + whip_end[0] * t**2
                y1 = whip_start[1] * (1-t)**2 + control_y * 2*t*(1-t) + whip_end[1] * t**2
                t2 = (i+1) / 10
                x2 = whip_start[0] * (1-t2)**2 + control_x * 2*t2*(1-t2) + whip_end[0] * t2**2
                y2 = whip_start[1] * (1-t2)**2 + control_y * 2*t2*(1-t2) + whip_end[1] * t2**2
                
                thickness = 3 - int(i * 0.3)  # 끝으로 갈수록 얇아짐
                pygame.draw.line(screen, (139, 69, 19), (x1, y1), (x2, y2), thickness)
    
    # 각 팽이 그리기
    for top in spinning_tops:
        # 황금 팽이 은은한 빛 효과
        if top.get("is_golden", False):
            # 시간에 따라 부드럽게 변하는 빛 효과
            glow_time = pygame.time.get_ticks() / 1000.0
            glow_intensity = (math.sin(glow_time * 2) + 1) * 0.3 + 0.4  # 0.4 ~ 1.0 사이에서 부드럽게 변화
            
            # 외부 광원 효과 (가장 큰 원)
            glow_surface = pygame.Surface((120, 120), pygame.SRCALPHA)
            glow_center = (60, 60)
            for i in range(20):
                alpha = int(15 * (1 - i/20) * glow_intensity)  # 매우 투명하게
                radius = 60 - i * 2
                if radius > 0 and alpha > 0:
                    pygame.draw.circle(glow_surface, (255, 215, 0, alpha), glow_center, radius)
            screen.blit(glow_surface, (top["x"] - 60, top["y"] - 60))
            
            # 중간 광원 효과
            mid_glow_surface = pygame.Surface((80, 80), pygame.SRCALPHA)
            mid_glow_center = (40, 40)
            for i in range(15):
                alpha = int(25 * (1 - i/15) * glow_intensity)  # 조금 더 진하게
                radius = 40 - i * 2
                if radius > 0 and alpha > 0:
                    pygame.draw.circle(mid_glow_surface, (255, 223, 0, alpha), mid_glow_center, radius)
            screen.blit(mid_glow_surface, (top["x"] - 40, top["y"] - 40))
            
            # 작은 반짝임 파티클 효과
            if random.random() < 0.3:  # 30% 확률로 반짝임 생성
                for _ in range(2):
                    particle_offset_x = random.randint(-30, 30)
                    particle_offset_y = random.randint(-30, 30)
                    particle_size = random.randint(1, 3)
                    particle_alpha = int(random.uniform(100, 200) * glow_intensity)
                    particle_color = (255, random.randint(200, 255), 0, particle_alpha)
                    
                    particle_surface = pygame.Surface((particle_size * 4, particle_size * 4), pygame.SRCALPHA)
                    pygame.draw.circle(particle_surface, particle_color, 
                                     (particle_size * 2, particle_size * 2), particle_size)
                    screen.blit(particle_surface, 
                              (top["x"] + particle_offset_x - particle_size * 2, 
                               top["y"] + particle_offset_y - particle_size * 2))
        
        # 팽이 표면 생성 (작은 크기)
        size = 50  # 팽이 크기
        top_surface = pygame.Surface((size, size), pygame.SRCALPHA)
        center = size // 2
        
        # 팽이 회전 변환 준비
        if top.get("tilt", 0) > 0:
            # 쓰러지는 효과를 위한 변형
            tilt_factor = top["tilt"] / 90
            height_scale = 1 - tilt_factor * 0.5
        else:
            height_scale = 1
    
        # 팽이 몸체 (둥근 모양)
        # 아래쪽 (나무 부분 - 원뿔 형태)
        wood_color = (160, 82, 45, top["alpha"])  # 나무색
        for i in range(10):
            y_offset = center + i * height_scale
            if y_offset < size - 3:
                width = 18 - i * 1.5
                if width > 0:
                    pygame.draw.circle(top_surface, wood_color, 
                                     (center, int(y_offset)), int(width))
        
        # 윗쪽 (회전하는 색상 패턴 - 둥근 원판)
        if top.get("is_golden", False):
            # 황금 팽이는 금색 계열로
            pattern_colors = [
                (255, 215, 0, top["alpha"]),    # 금색
                (255, 223, 0, top["alpha"]),    # 밝은 금색
                (218, 165, 32, top["alpha"]),   # 골든로드
            ]
        else:
            # 일반 팽이
            pattern_colors = [
                (100, 200, 200, top["alpha"]),  # 청록색
                (220, 100, 100, top["alpha"]),  # 빨간색
                (255, 200, 50, top["alpha"]),   # 노란색
            ]
        
        # 부스트 상태일 때 색상 변화
        if top.get("boost_timer", 0) > 0:
            # 부스트 중일 때 밝게 빛나는 효과
            boost_glow = int(128 * (top["boost_timer"] / 18))
            pattern_colors = [
                (min(255, c[0] + boost_glow), 
                 min(255, c[1] + boost_glow), 
                 min(255, c[2] + boost_glow), 
                 c[3]) for c in pattern_colors
            ]
        
        # 회전 효과를 위한 색상 블렌딩
        rotation_phase = (top["rotation"] / 10) % 3
        color_index = int(rotation_phase)
        next_color_index = (color_index + 1) % 3
        blend_factor = rotation_phase - color_index
        
        # 색상 보간
        current_color = pattern_colors[color_index]
        next_color = pattern_colors[next_color_index]
        blended_color = (
            int(current_color[0] * (1 - blend_factor) + next_color[0] * blend_factor),
            int(current_color[1] * (1 - blend_factor) + next_color[1] * blend_factor),
            int(current_color[2] * (1 - blend_factor) + next_color[2] * blend_factor),
            top["alpha"]
        )
        
        # 팽이 상단 원판 (둥근 모양)
        pygame.draw.circle(top_surface, blended_color, 
                          (center, int(center * height_scale - 5)), 18)
        pygame.draw.circle(top_surface, pattern_colors[(color_index + 2) % 3], 
                          (center, int(center * height_scale - 5)), 12)
        pygame.draw.circle(top_surface, pattern_colors[color_index], 
                          (center, int(center * height_scale - 5)), 6)
        
        # 팽이 축 (중심 막대)
        axis_color = (60, 30, 15, top["alpha"])  # 진한 나무색
        pygame.draw.line(top_surface, axis_color, 
                        (center, center * height_scale - 5), 
                        (center, center + 30 * height_scale), 3)
        
        # 화면에 그리기
        screen.blit(top_surface, 
                    (top["x"] - center, top["y"] - center))
        
        # 그림자 효과
        shadow_size = 30 + int(top.get("tilt", 0) / 4)
        shadow_surface = pygame.Surface((shadow_size, 12), pygame.SRCALPHA)
        shadow_alpha = top["alpha"] // 4
        if top.get("tilt", 0) > 0:  # 쓰러질 때 그림자 옅어짐
            shadow_alpha = shadow_alpha * (1 - top["tilt"] / 90)
        shadow_color = (0, 0, 0, int(shadow_alpha))
        pygame.draw.ellipse(shadow_surface, shadow_color, shadow_surface.get_rect())
        screen.blit(shadow_surface, 
                    (top["x"] - shadow_size // 2, top["y"] + 25))

def apply_red_overlay(surface, intensity):
    """
    투명하지 않은 픽셀에만 붉은 효과를 적용하는 함수 (최적화 버전)
    :param surface: pygame.Surface (RGBA)
    :param intensity: 0~255 사이의 붉은 정도
    """
    #  성능 최적화: 매우 큰 표면에서는 효과 비활성화
    if surface.get_width() > 300 or surface.get_height() > 300:
        return
    #  성능 최적화: 블렌딩 모드를 사용한 효율적인 색상 적용
    # 임시 표면을 생성하고 블렌딩 모드 사용
    overlay = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
    # 빨간색 오버레이 색상 계산
    red_factor = min(255, 255 + int(intensity * 0.8))
    green_factor = max(0, 255 - int(intensity * 0.2))
    blue_factor = max(0, 255 - int(intensity * 0.2))
    overlay.fill((red_factor, green_factor, blue_factor, 90))  # 투명도 90
    #  블렌드 모드를 사용하여 효율적으로 색상 적용
    surface.blit(overlay, (0, 0), special_flags=pygame.BLEND_MULT)
def apply_blue_overlay(surface, intensity):
    """
    투명하지 않은 픽셀에만 파란색 효과를 적용하는 함수 (최적화 버전)
    :param surface: pygame.Surface (RGBA)
    :param intensity: 0~255 사이의 파란색 정도
    """
    #  성능 최적화: 매우 큰 표면에서는 효과 비활성화
    if surface.get_width() > 300 or surface.get_height() > 300:
        return
    #  성능 최적화: 블렌딩 모드를 사용한 효율적인 색상 적용
    # 임시 표면을 생성하고 블렌딩 모드 사용
    overlay = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
    # 파란색 오버레이 색상 계산
    blue_factor = min(255, int(intensity * 0.5))
    red_factor = max(0, 255 - int(intensity * 0.3))
    green_factor = max(0, 255 - int(intensity * 0.1))
    overlay.fill((red_factor, green_factor, blue_factor, 80))  # 투명도 80
    #  블렌드 모드를 사용하여 효율적으로 색상 적용
    surface.blit(overlay, (0, 0), special_flags=pygame.BLEND_MULT)


def apply_ai_glitch_effect(surface: pygame.Surface, time_now: int) -> pygame.Surface:
    """AI 필 활성화 동안 패들에 사이버 글리치 효과를 적용."""
    width, height = surface.get_size()
    if width == 0 or height == 0:
        return surface

    glitched = surface.copy()
    slice_height = max(4, height // 9)
    base_phase = time_now * 0.015

    for idx, y in enumerate(range(0, height, slice_height)):
        rect = pygame.Rect(0, y, width, min(slice_height, height - y))
        segment = surface.subsurface(rect).copy()
        horizontal_shift = int(math.sin(base_phase + idx * 0.6) * 5)

        tint_alpha = 50 + (idx % 3) * 25
        tint_surface = pygame.Surface((rect.width, rect.height), pygame.SRCALPHA)
        tint_surface.fill((40, 220, 255, min(180, tint_alpha)))
        segment.blit(tint_surface, (0, 0), special_flags=pygame.BLEND_ADD)

        glitched.blit(segment, (horizontal_shift, y), special_flags=pygame.BLEND_RGBA_ADD)

    original_alpha = surface.get_alpha()
    if original_alpha is not None:
        glitched.set_alpha(original_alpha)

    return glitched


# ============================================================================
# 패들 홀로그램 물질화 효과 (스테이지 시작 시)
# ============================================================================
PADDLE_HOLOGRAM_DURATION = 3.0  # 홀로그램 효과 지속 시간 (초)


def get_paddle_hologram_state() -> tuple:
    """
    패들 홀로그램 상태를 반환합니다.
    Returns:
        (should_draw, progress, effect_surface_modifier)
        - should_draw: 패들을 그려야 하는지 여부
        - progress: 0.0~1.0 사이의 물질화 진행도 (1.0 = 완전히 보임)
        - is_hologram_active: 홀로그램 효과가 활성화 상태인지
    """
    if not ball_spawn_animation_active or not is_ball_spawn_animation_active():
        return (True, 1.0, False)  # 애니메이션 비활성 시 완전히 보임

    elapsed = get_ball_spawn_animation_elapsed_time()
    total = get_ball_spawn_animation_total_duration()
    hologram_start_time = total - PADDLE_HOLOGRAM_DURATION  # 5초 (8초 - 3초)

    if elapsed < hologram_start_time:
        # 홀로그램 시작 전: 완전히 안 보임
        return (False, 0.0, False)
    else:
        # 홀로그램 효과 중: 점점 물질화
        hologram_elapsed = elapsed - hologram_start_time
        progress = min(1.0, hologram_elapsed / PADDLE_HOLOGRAM_DURATION)
        return (True, progress, True)


def apply_hologram_materialize_effect(surface: pygame.Surface, progress: float, time_now: int) -> pygame.Surface:
    """
    홀로그램 물질화 효과를 적용합니다.

    Args:
        surface: 원본 패들 서피스
        progress: 0.0~1.0 사이의 물질화 진행도
        time_now: 현재 시간 (밀리초)

    Returns:
        효과가 적용된 서피스
    """
    width, height = surface.get_size()
    if width == 0 or height == 0:
        return surface

    result = pygame.Surface((width, height), pygame.SRCALPHA)

    # 플리커(깜빡임) 효과 - 진행도가 낮을수록 더 자주 깜빡임
    flicker_frequency = 0.03 - progress * 0.025  # 0.03 -> 0.005
    flicker = math.sin(time_now * flicker_frequency * 10) > 0

    # 진행도가 낮을 때 깜빡임으로 가끔 안 보이게
    if progress < 0.7:
        random_flicker = random.random() < (0.3 - progress * 0.4)
        if random_flicker and not flicker:
            # 완전히 안 보이는 순간
            return result

    # 기본 알파값 계산 (진행도에 따라 증가)
    base_alpha = int(50 + progress * 205)  # 50 -> 255

    # 스캔라인 효과 (수평선)
    scan_line_spacing = max(2, int(8 - progress * 5))  # 8 -> 3 (점점 촘촘해짐)
    scan_line_alpha_variation = int((1 - progress) * 100)  # 100 -> 0

    for y in range(height):
        # 스캔라인 밝기 변조
        is_scan_line = (y % scan_line_spacing) == 0

        if is_scan_line and progress < 0.9:
            # 스캔라인에서는 더 밝거나 어둡게
            line_alpha = base_alpha + random.randint(-scan_line_alpha_variation, scan_line_alpha_variation)
        else:
            line_alpha = base_alpha

        line_alpha = max(0, min(255, line_alpha))

        # 해당 라인 복사
        if y < height:
            line_rect = pygame.Rect(0, y, width, 1)
            line_surf = surface.subsurface(line_rect).copy()

            # 노이즈/글리치 - 수평 이동
            h_shift = 0
            if progress < 0.8:
                noise_chance = (1 - progress) * 0.3
                if random.random() < noise_chance:
                    h_shift = random.randint(-int(10 * (1 - progress)), int(10 * (1 - progress)))

            # 알파 적용
            line_surf.set_alpha(line_alpha)
            result.blit(line_surf, (h_shift, y))

    # 사이버 틴트 (시안/마젠타 색상 분리 효과)
    if progress < 0.85:
        color_shift = int((1 - progress) * 4)  # 4 -> 0

        # 시안 고스트 (왼쪽으로)
        cyan_ghost = surface.copy()
        cyan_tint = pygame.Surface((width, height), pygame.SRCALPHA)
        cyan_tint.fill((0, 255, 255, int(30 * (1 - progress))))
        cyan_ghost.blit(cyan_tint, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
        cyan_ghost.set_alpha(int(50 * (1 - progress)))
        result.blit(cyan_ghost, (-color_shift, 0))

        # 마젠타 고스트 (오른쪽으로)
        magenta_ghost = surface.copy()
        magenta_tint = pygame.Surface((width, height), pygame.SRCALPHA)
        magenta_tint.fill((255, 0, 255, int(30 * (1 - progress))))
        magenta_ghost.blit(magenta_tint, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
        magenta_ghost.set_alpha(int(50 * (1 - progress)))
        result.blit(magenta_ghost, (color_shift, 0))

    # 디지털 노이즈 파티클
    if progress < 0.7:
        noise_count = int((1 - progress) * 20)
        for _ in range(noise_count):
            nx = random.randint(0, width - 1)
            ny = random.randint(0, height - 1)
            noise_size = random.randint(1, 3)
            noise_color = random.choice([
                (0, 255, 255, int(150 * (1 - progress))),  # 시안
                (255, 0, 255, int(150 * (1 - progress))),  # 마젠타
                (255, 255, 255, int(200 * (1 - progress))),  # 흰색
            ])
            pygame.draw.rect(result, noise_color, (nx, ny, noise_size, noise_size))

    # 가장자리 글로우 효과
    if progress > 0.3:
        glow_alpha = int((progress - 0.3) * 100)  # 0 -> 70
        glow_color = (100, 200, 255, glow_alpha)

        # 상단/하단 글로우 라인
        pygame.draw.line(result, glow_color, (0, 0), (width, 0), 1)
        pygame.draw.line(result, glow_color, (0, height-1), (width, height-1), 1)

    return result
def update_water_trail():
    """물자국 업데이트 함수"""
    global water_trail_positions, water_trail_timer
    # 디버프가 활성화되어 있을 때만 물자국 생성
    if player_slow_timer > 0:
        water_trail_timer += 1
        # 일정 간격으로 물자국 생성 (패들 바닥 중앙)
        if water_trail_timer >= 10:  # 10프레임마다 생성
            water_trail_positions.append((PLAYER.centerx, PLAYER.bottom + 5, 100))  # 초기 투명도 100
            water_trail_timer = 0
    # 물자국 점점 사라지게 하기 (시간이 지나면 투명도 감소)
    water_trail_positions = [(x, y, alpha - 3) for x, y, alpha in water_trail_positions if alpha > 0]
def draw_water_trail():
    """물자국 그리기 함수 (캐시 최적화 - 매 프레임 Surface 생성 제거)"""
    global _water_trail_cache
    for x, y, alpha in water_trail_positions:
        if alpha > 0:
            # 물자국 크기 (랜덤 대신 alpha 기반으로 결정하여 캐시 효율화)
            size = 8 + (alpha % 8)  # 8-15 범위, alpha에 따라 결정적
            alpha_clamped = min(alpha, 100)
            # 알파 버킷팅 (20, 40, 60, 80, 100)
            alpha_bucket = min(_WATER_ALPHA_BUCKETS, key=lambda b: abs(b - alpha_clamped))
            cache_key = (size, alpha_bucket)

            # 캐시에서 가져오거나 새로 생성
            if cache_key not in _water_trail_cache:
                surf = pygame.Surface((size, size // 2), pygame.SRCALPHA)
                color = (100, DEFAULT_ALPHA, 255, alpha_bucket)
                pygame.draw.ellipse(surf, color, (0, 0, size, size // 2))
                _water_trail_cache[cache_key] = surf

            SCREEN.blit(_water_trail_cache[cache_key], (x - size // 2, y - size // 4))
def draw_pachinko():
    """라스베가스 스타일 슬롯머신 그리기 함수 (캐시 최적화)"""
    global _pachinko_cache
    if not pachinko_active:
        return

    # === 배경 그라데이션 캐싱 (750회 draw.line → 1회 blit) ===
    bg_cache_key = ("pachinko_bg", WIDTH, HEIGHT)
    if bg_cache_key not in _pachinko_cache:
        import numpy as np
        bg_surf = pygame.Surface((WIDTH, HEIGHT))
        arr = np.zeros((WIDTH, HEIGHT, 3), dtype=np.uint8)
        y_indices = np.arange(HEIGHT, dtype=np.float32)
        ratios = y_indices / HEIGHT
        arr[:, :, 0] = (20 + ratios * 30).astype(np.uint8)
        arr[:, :, 1] = (10 + ratios * 20).astype(np.uint8)
        arr[:, :, 2] = (40 + ratios * 50).astype(np.uint8)
        pygame.surfarray.blit_array(bg_surf, arr)
        _pachinko_cache[bg_cache_key] = bg_surf
    SCREEN.blit(_pachinko_cache[bg_cache_key], (0, 0))

    # 메인 컨테이너 (라스베가스 카지노 스타일)
    container_width = 500
    container_height = 600
    container_x = (WIDTH - container_width) // 2
    container_y = (HEIGHT - container_height) // 2 - 20

    # === 컨테이너 글로우 캐싱 (10개 Surface → 캐시 재사용) ===
    for i in range(10):
        glow_w = container_width + i * 6
        glow_h = container_height + i * 6
        glow_alpha = 60 - i * 6
        glow_key = ("pachinko_glow", glow_w, glow_h, glow_alpha)
        if glow_key not in _pachinko_cache:
            glow_surface = pygame.Surface((glow_w, glow_h), pygame.SRCALPHA)
            glow_surface.fill((255, 215, 0, glow_alpha))
            _pachinko_cache[glow_key] = glow_surface
        SCREEN.blit(_pachinko_cache[glow_key], (container_x - i * 3, container_y - i * 3))
    # 메인 컨테이너
    main_container = pygame.Rect(container_x, container_y, container_width, container_height)
    draw.rect((25, 15, 5), main_container)
    draw.rect((255, 215, 0), main_container, 4)
    # 내부 컨테이너
    inner_container = pygame.Rect(container_x + 20, container_y + 20, container_width - 40, container_height - 40)
    draw.rect((15, 10, 5), inner_container)
    draw.rect((255, 200, 0), inner_container, 3)
    # 제목 영역
    title_area = pygame.Rect(container_x + 30, container_y + 30, container_width - 60, 80)
    draw.rect((30, 20, 10), title_area)
    draw.rect((255, 215, 0), title_area, 3)
    # 제목 텍스트
    # 픽셀 폰트 타이틀
    title_font = FontStyle.title()  # 48pt 픽셀 폰트
    title_text = title_font.render(" " + _t("ui.slot_machine", "슬롯머신"), True, (255, 215, 0))
    title_rect = title_text.get_rect(center=(container_x + container_width // 2, container_y + 70))
    SCREEN.blit(title_text, title_rect)
    # 슬롯 영역
    slot_area_x = container_x + 50
    slot_area_y = container_y + 150
    slot_area_width = container_width - 100
    slot_area_height = 300
    # 슬롯 배경
    slot_bg_rect = pygame.Rect(slot_area_x - 10, slot_area_y - 10, slot_area_width + 20, slot_area_height + 20)
    draw.rect((20, 15, 10), slot_bg_rect)
    draw.rect((255, 215, 0), slot_bg_rect, 3)
    # 3개 슬롯 그리기
    slot_width = (slot_area_width - 40) // 3
    slot_height = slot_area_height
    for reel_idx in range(3):
        reel_x = slot_area_x + reel_idx * (slot_width + 20)
        reel_y = slot_area_y
        # 릴 배경
        reel_rect = pygame.Rect(reel_x, reel_y, slot_width, slot_height)
        draw.rect((10, 8, 5), reel_rect)
        draw.rect((255, 200, 0), reel_rect, 2)
        # 릴 내부 아이템들 그리기 (세로 스크롤)
        item_size = 60
        visible_items = 5  # 한 번에 보이는 아이템 개수
        for i in range(visible_items):
            item_y = reel_y + i * (slot_height // visible_items) + 10
            item_y -= slot_positions[reel_idx]  # 스크롤 적용
            # 화면 안에 있는 아이템만 그리기
            if item_y + item_size > reel_y and item_y < reel_y + slot_height:
                # 아이템 인덱스 계산
                item_idx = (int(slot_positions[reel_idx] // 8) + i) % 30
                if item_idx < len(slot_reels[reel_idx]):
                    item = slot_reels[reel_idx][item_idx]
                    # 아이템 배경
                    item_rect = pygame.Rect(reel_x + 5, item_y, item_size, item_size)
                    draw.rect((25, 20, 15), item_rect)
                    draw.rect((255, 180, 0), item_rect, 2)
                    # 아이템 아이콘
                    if "icon" in item and item["icon"]:
                        icon = pygame.transform.scale(item["icon"], (50, 50))
                        icon_x = reel_x + 8
                        icon_y = item_y + 5
                        SCREEN.blit(icon, (icon_x, icon_y))
                    else:
                        # 아이콘이 없으면 원으로 그리기
                        center_x = reel_x + slot_width // 2
                        center_y = item_y + item_size // 2
                        draw.circle(item["color"], (center_x, center_y), 20)
        # 중앙 선택 표시 (골드 글로우) - 캐싱
        center_y = reel_y + slot_height // 2
        center_rect = pygame.Rect(reel_x - 5, center_y - 35, slot_width + 10, 70)
        # 글로우 효과 (캐시 사용)
        for i in range(3):
            glow_w = slot_width + 10 + i * 4
            glow_h = 70 + i * 4
            glow_alpha = 100 - i * 30
            reel_glow_key = ("reel_glow", glow_w, glow_h, glow_alpha)
            if reel_glow_key not in _pachinko_cache:
                glow_surface = pygame.Surface((glow_w, glow_h), pygame.SRCALPHA)
                glow_surface.fill((255, 215, 0, glow_alpha))
                _pachinko_cache[reel_glow_key] = glow_surface
            glow_x = reel_x - 5 - i * 2
            glow_y = center_y - 35 - i * 2
            SCREEN.blit(_pachinko_cache[reel_glow_key], (glow_x, glow_y))
        draw.rect((255, 215, 0), center_rect, 4)
    # 결과 표시
    if pachinko_phase == 3 and slot_final_result:
        # 당첨 애니메이션
        global slot_win_animation
        slot_win_animation += 1
        # 결과 영역
        result_width = 400
        result_height = 120
        result_x = (WIDTH - result_width) // 2
        result_y = container_y + container_height + 20
        # 화려한 배경 (캐싱 - 120회 draw.line → 1회 blit)
        result_bg_key = ("pachinko_result_bg", result_width, result_height)
        if result_bg_key not in _pachinko_cache:
            import numpy as np
            result_surf = pygame.Surface((result_width, result_height))
            arr = np.zeros((result_width, result_height, 3), dtype=np.uint8)
            y_indices = np.arange(result_height, dtype=np.float32)
            ratios = y_indices / result_height
            arr[:, :, 0] = (50 + ratios * 100).astype(np.uint8)
            arr[:, :, 1] = (30 + ratios * 80).astype(np.uint8)
            arr[:, :, 2] = (10 + ratios * 40).astype(np.uint8)
            pygame.surfarray.blit_array(result_surf, arr)
            _pachinko_cache[result_bg_key] = result_surf
        SCREEN.blit(_pachinko_cache[result_bg_key], (result_x, result_y))
        draw.rect((255, 215, 0), (result_x, result_y, result_width, result_height), 4)
        # 당첨 아이템 표시
        if "icon" in slot_final_result and slot_final_result["icon"]:
            icon = pygame.transform.scale(slot_final_result["icon"], (80, 80))
            icon_x = result_x + 30
            icon_y = result_y + 20
            SCREEN.blit(icon, (icon_x, icon_y))
        # 당첨 메시지
        item_name = get_item_name_korean(slot_final_result['name'])
        # 픽셀 폰트
        result_font = FontStyle.subtitle()  # 32pt 픽셀 폰트
        result_text = f" JACKPOT! {item_name} "
        text = result_font.render(result_text, True, WHITE)
        text_rect = text.get_rect(center=(result_x + result_width // 2, result_y + 60))
        SCREEN.blit(text, text_rect)
        # 계속하기 안내
        continue_font = FontStyle.body()  # 24pt 픽셀 폰트
        continue_text = " SPACE를 눌러 계속... "
        text_small = continue_font.render(continue_text, True, WHITE)
        text_small_rect = text_small.get_rect(center=(result_x + result_width // 2, result_y + 100))
        SCREEN.blit(text_small, text_small_rect)
    elif pachinko_phase == 3 and not slot_final_result:
        # 꽝 결과
        result_width = 400
        result_height = 120
        result_x = (WIDTH - result_width) // 2
        result_y = container_y + container_height + 20
        # 어두운 배경
        draw.rect((30, 20, 10), (result_x, result_y, result_width, result_height))
        draw.rect((100, 100, 100), (result_x, result_y, result_width, result_height), 3)
        # 꽝 메시지
        # 픽셀 폰트
        result_font = FontStyle.subtitle()  # 36pt 픽셀 폰트
        result_text = " 아쉽게도 꽝입니다... "
        text = result_font.render(result_text, True, (200, 200, 200))
        text_rect = text.get_rect(center=(result_x + result_width // 2, result_y + 60))
        SCREEN.blit(text, text_rect)
        # 계속하기 안내
        continue_font = FontStyle.body()  # 24pt 픽셀 폰트
        continue_text = " SPACE를 눌러 계속... "
        text_small = continue_font.render(continue_text, True, (200, 200, 200))
        text_small_rect = text_small.get_rect(center=(result_x + result_width // 2, result_y + 100))
        SCREEN.blit(text_small, text_small_rect)
    # 안내 텍스트
    if pachinko_phase == 0:
        # 픽셀 폰트
        guide_font = FontStyle.menu()  # 28pt 픽셀 폰트
        guide_text = " SPACE를 눌러 슬롯머신 시작! "
        text = guide_font.render(guide_text, True, (255, 215, 0))
        text_rect = text.get_rect(center=(WIDTH // 2, container_y + container_height + 80))
        SCREEN.blit(text, text_rect)
    elif slot_spinning and not slot_slowdown_mode:
        # 픽셀 폰트
        guide_font = FontStyle.menu()  # 28pt 픽셀 폰트
        guide_text = " SPACE를 눌러 첫 번째 릴 멈추기! "
        text = guide_font.render(guide_text, True, (255, 215, 0))
        text_rect = text.get_rect(center=(WIDTH // 2, container_y + container_height + 80))
        SCREEN.blit(text, text_rect)
    elif slot_slowdown_mode:
        if slot_stop_order == 0:
            # 픽셀 폰트
            guide_font = FontStyle.menu()  # 28pt 픽셀 폰트
            guide_text = " SPACE를 눌러 두 번째 릴 멈추기! "
            text = guide_font.render(guide_text, True, (255, 215, 0))
            text_rect = text.get_rect(center=(WIDTH // 2, container_y + container_height + 80))
