TUTORIAL_GUIDE_HINT_DURATION_MS = 5000
TUTORIAL_GUIDE_HINT_SCALE = 0.52
tutorial_guide_hint_start_ticks = 0
tutorial_guide_hint_visible = False


def _draw_hint_lamp(
    surface: pygame.Surface,
    center: tuple[float, float],
    elapsed_ms: float,
    scale: float = 1.0,
) -> None:
    scale = max(0.1, scale)
    wiggle = math.sin(elapsed_ms / 220.0) * 4 * scale
    base_color = (215, 176, 54)
    accent_color = (255, 222, 140)
    shadow_color = (120, 96, 32)
    x, y = center

    body_width = max(6, int(80 * scale))
    body_height = max(4, int(26 * scale))
    body_rect = pygame.Rect(0, 0, body_width, body_height)
    body_rect.center = (x + wiggle, y)
    pygame.draw.ellipse(surface, shadow_color, body_rect.inflate(6, 6))
    pygame.draw.ellipse(surface, base_color, body_rect)
    highlight_rect = body_rect.inflate(
        -max(1, int(body_rect.width * 0.45)),
        -max(1, int(body_rect.height * 0.6)),
    )
    pygame.draw.ellipse(surface, accent_color, highlight_rect)

    half_width = body_rect.width / 2
    spout = [
        (int(x + wiggle + half_width - 2 * scale), int(y - 6 * scale)),
        (int(x + wiggle + half_width + 20 * scale), int(y - 3 * scale)),
        (int(x + wiggle + half_width + 20 * scale), int(y + 3 * scale)),
        (int(x + wiggle + half_width - 2 * scale), int(y + 6 * scale)),
    ]
    pygame.draw.polygon(surface, shadow_color, spout)
    pygame.draw.polygon(surface, base_color, spout, 0)
    pygame.draw.lines(surface, accent_color, False, spout, 2)

    handle_size = max(4, int(18 * scale))
    handle_rect = pygame.Rect(0, 0, handle_size, handle_size)
    handle_rect.center = (int(x + wiggle - half_width - 8 * scale), int(y))
    pygame.draw.ellipse(surface, shadow_color, handle_rect.inflate(4, 4))
    pygame.draw.ellipse(surface, base_color, handle_rect)

    for idx in range(3):
        smoke_progress = ((elapsed_ms / 450.0) + idx * 0.33) % 1.0
        base_radius = 8 * scale
        smoke_radius = max(2, int(base_radius - smoke_progress * 5 * scale))
        smoke_alpha = max(0, int(120 * (1.0 - smoke_progress)))
        smoke_surface = pygame.Surface((smoke_radius * 4, smoke_radius * 4), pygame.SRCALPHA)
        pygame.draw.circle(
            smoke_surface,
            (220, 225, 240, smoke_alpha),
            (smoke_radius * 2, smoke_radius * 2),
            smoke_radius * 2,
        )
        offset_x = math.sin((elapsed_ms / 260.0) + idx * 1.2) * 6 * scale
        offset_y = -22 * scale - smoke_progress * 34 * scale - idx * 8 * scale
        surface.blit(
            smoke_surface,
            (
                int(x + offset_x - smoke_radius * 2),
                int(y + offset_y - smoke_radius * 2),
            ),
        )


def _draw_tutorial_guide_hint() -> None:
    global tutorial_guide_hint_visible
    if not tutorial_guide_hint_visible:
        return

    now = pygame.time.get_ticks()
    elapsed = now - tutorial_guide_hint_start_ticks
    if elapsed >= TUTORIAL_GUIDE_HINT_DURATION_MS:
        tutorial_guide_hint_visible = False
        return

    scale = TUTORIAL_GUIDE_HINT_SCALE
    pulse = (math.sin(elapsed / 160.0) + 1.0) * 0.5
    font_size = max(10, int(26 * scale))
    hint_font = get_font(font_size)
    message = "튜토리얼 가이드 → T키"

    text_color = (
        int(228 + 20 * pulse),
        int(208 + 32 * pulse),
        255,
    )
    shadow_color = (200, 210, 240)
    text_surface = hint_font.render(message, True, text_color)
    text_rect = text_surface.get_rect()

    lamp_canvas_width = max(96, int(170 * scale))
    lamp_canvas_height = max(90, int(190 * scale))
    lamp_surface = pygame.Surface((lamp_canvas_width, lamp_canvas_height), pygame.SRCALPHA)
    lamp_center = (
        lamp_canvas_width // 2,
        max(30, int(68 * scale)) + int(math.sin(elapsed / 220.0) * 2 * scale),
    )
    _draw_hint_lamp(lamp_surface, lamp_center, elapsed, scale)

    horizontal_gap = max(12, int(24 * scale))
    vertical_padding = max(6, int(10 * scale))
    width = lamp_canvas_width + horizontal_gap + text_rect.width
    height = max(lamp_canvas_height, text_rect.height + vertical_padding * 2)
    hint_surface = pygame.Surface((width, height), pygame.SRCALPHA)

    lamp_y = (height - lamp_canvas_height) // 2
    hint_surface.blit(lamp_surface, (0, lamp_y))

    bob_offset = int(math.sin(elapsed / 190.0) * 2 * scale)
    text_x = lamp_canvas_width + horizontal_gap
    text_y = (height - text_rect.height) // 2 + bob_offset

    shadow_surface = hint_font.render(message, True, shadow_color)
    hint_surface.blit(shadow_surface, (text_x, text_y + max(1, int(2 * scale))))
    hint_surface.blit(text_surface, (text_x, text_y))

    offset_x = max(12, int(30 * scale))
    offset_y = max(12, int(32 * scale))
    SCREEN.blit(hint_surface, (offset_x, offset_y))


# === 실전 튜토리얼 시스템 (주니어리그 전용) ===
