_tutorial_action_gauge_reset_start_time = 0  # 리셋 시작 시간
_tutorial_action_gauge_reset_from = 0  # 리셋 전 값 (이전 진행도)
_tutorial_action_gauge_reset_duration = 600  # 리셋 애니메이션 지속 시간 (ms)

# === 숫자 애니메이션 시스템 ===
