_tutorial_action_gauge_number_light_time = [0, 0, 0]  # 각 숫자가 켜진 시간
_tutorial_action_gauge_prev_current = 0  # 이전 프레임의 현재값 (애니메이션 트리거용)

# === 등장 애니메이션 시스템 ===
_tutorial_action_gauge_entrance_active = False  # 등장 애니메이션 활성 여부
_tutorial_action_gauge_entrance_start_time = 0  # 등장 시작 시간
_tutorial_action_gauge_entrance_duration = 400  # 등장 애니메이션 지속 시간 (ms)


def show_tutorial_action_gauge(gauge_type: str, target: int, title: str):
    """튜토리얼 액션 게이지 표시"""
    global _tutorial_action_gauge_active, _tutorial_action_gauge_type
    global _tutorial_action_gauge_current, _tutorial_action_gauge_target, _tutorial_action_gauge_title
    global _tutorial_action_gauge_complete, _tutorial_action_gauge_fill_anim
    global _tutorial_action_gauge_hide_pending
    global _tutorial_action_gauge_reset_active, _tutorial_action_gauge_number_anim
    global _tutorial_action_gauge_number_light_time, _tutorial_action_gauge_prev_current
    global _tutorial_action_gauge_entrance_active, _tutorial_action_gauge_entrance_start_time
    _tutorial_action_gauge_active = True
    _tutorial_action_gauge_type = gauge_type
    _tutorial_action_gauge_current = 0
    _tutorial_action_gauge_target = target
    _tutorial_action_gauge_title = title
    _tutorial_action_gauge_complete = False
    _tutorial_action_gauge_fill_anim = 0.0
    _tutorial_action_gauge_hide_pending = False
    # 리셋 및 숫자 애니메이션 초기화
    _tutorial_action_gauge_reset_active = False
    _tutorial_action_gauge_number_anim = [0.0] * target
    _tutorial_action_gauge_number_light_time = [0] * target
    _tutorial_action_gauge_prev_current = 0
    # 등장 애니메이션 시작
    _tutorial_action_gauge_entrance_active = True
    _tutorial_action_gauge_entrance_start_time = pygame.time.get_ticks()


def update_tutorial_action_gauge(value: int):
    """튜토리얼 액션 게이지 값 업데이트 - 완료 시 애니메이션 시작"""
    global _tutorial_action_gauge_current, _tutorial_action_gauge_complete
    global _tutorial_action_gauge_complete_time, _tutorial_action_gauge_fill_start_time
    if _tutorial_action_gauge_active:
        _tutorial_action_gauge_current = min(value, _tutorial_action_gauge_target)
        # 목표 달성 시 완료 애니메이션 시작
        if _tutorial_action_gauge_current >= _tutorial_action_gauge_target:
            _tutorial_action_gauge_complete = True
            _tutorial_action_gauge_complete_time = pygame.time.get_ticks()
            _tutorial_action_gauge_fill_start_time = pygame.time.get_ticks()


def hide_tutorial_action_gauge():
    """튜토리얼 액션 게이지 숨기기 (완료 애니메이션 후 지연 숨기기)"""
    global _tutorial_action_gauge_hide_pending, _tutorial_action_gauge_hide_time
    if _tutorial_action_gauge_complete:
        # 완료 상태면 1초 후에 숨기기
        _tutorial_action_gauge_hide_pending = True
        _tutorial_action_gauge_hide_time = pygame.time.get_ticks() + 1000
    else:
        # 완료 전이면 즉시 숨기기
        _force_hide_tutorial_action_gauge()


def _force_hide_tutorial_action_gauge():
    """튜토리얼 액션 게이지 강제 숨기기"""
    global _tutorial_action_gauge_active, _tutorial_action_gauge_complete, _tutorial_action_gauge_hide_pending
    _tutorial_action_gauge_active = False
    _tutorial_action_gauge_complete = False
    _tutorial_action_gauge_hide_pending = False


def reset_tutorial_action_gauge_with_effect():
    """튜토리얼 액션 게이지 리셋 (실패 이펙트 표시) - 대쉬 사용 시 호출"""
    global _tutorial_action_gauge_reset_active, _tutorial_action_gauge_reset_start_time
    global _tutorial_action_gauge_reset_from, _tutorial_action_gauge_current
    global _tutorial_action_gauge_number_anim, _tutorial_action_gauge_number_light_time
    global _tutorial_action_gauge_prev_current

    if not _tutorial_action_gauge_active:
        return
    if _tutorial_action_gauge_complete:
        return  # 이미 완료된 경우 리셋하지 않음
    if _tutorial_action_gauge_type not in ("combo",):
        return  # 콤보 타입만 리셋 애니메이션 적용

    # 현재 진행도 저장 및 리셋 애니메이션 시작
    _tutorial_action_gauge_reset_from = _tutorial_action_gauge_current
    _tutorial_action_gauge_reset_active = True
    _tutorial_action_gauge_reset_start_time = pygame.time.get_ticks()

    # 실제 값은 0으로 리셋
    _tutorial_action_gauge_current = 0
    _tutorial_action_gauge_prev_current = 0

    # 숫자 애니메이션 초기화 (불이 꺼지는 효과)
    for i in range(len(_tutorial_action_gauge_number_anim)):
        _tutorial_action_gauge_number_anim[i] = 0.0
        _tutorial_action_gauge_number_light_time[i] = 0


def draw_tutorial_action_gauge():
    """튜토리얼 액션 게이지 그리기 (우측 상단 필러)"""
    global _tutorial_action_gauge_fill_anim
    global _tutorial_action_gauge_reset_active, _tutorial_action_gauge_number_anim
    global _tutorial_action_gauge_number_light_time, _tutorial_action_gauge_prev_current

    if not _tutorial_action_gauge_active:
        return

    # 지연 숨기기 체크
    if _tutorial_action_gauge_hide_pending:
        current_time = pygame.time.get_ticks()
        if current_time >= _tutorial_action_gauge_hide_time:
            _force_hide_tutorial_action_gauge()
            return

    # REAL_SCREEN 또는 SCREEN 결정
    target_screen = REAL_SCREEN if (_is_fullscreen_active and REAL_SCREEN is not None) else SCREEN

    current_time = pygame.time.get_ticks()

    # 완료 상태 시 애니메이션 처리
    if _tutorial_action_gauge_complete:
        elapsed = current_time - _tutorial_action_gauge_fill_start_time
        # 0.5초 동안 게이지 채우기 애니메이션
        anim_duration = 500
        if elapsed < anim_duration:
            _tutorial_action_gauge_fill_anim = elapsed / anim_duration
        else:
            _tutorial_action_gauge_fill_anim = 1.0

    # === 리셋 애니메이션 처리 ===
    reset_progress = 0.0
    if _tutorial_action_gauge_reset_active:
        elapsed = current_time - _tutorial_action_gauge_reset_start_time
        if elapsed >= _tutorial_action_gauge_reset_duration:
            _tutorial_action_gauge_reset_active = False
            reset_progress = 0.0
        else:
            reset_progress = elapsed / _tutorial_action_gauge_reset_duration

    # === 등장 애니메이션 처리 ===
    global _tutorial_action_gauge_entrance_active
    entrance_progress = 1.0  # 기본값 (애니메이션 완료)
    if _tutorial_action_gauge_entrance_active:
        elapsed = current_time - _tutorial_action_gauge_entrance_start_time
        if elapsed >= _tutorial_action_gauge_entrance_duration:
            _tutorial_action_gauge_entrance_active = False
            entrance_progress = 1.0
        else:
            # ease-out 효과 (처음에 빠르고 끝에 느리게)
            t = elapsed / _tutorial_action_gauge_entrance_duration
            entrance_progress = 1.0 - (1.0 - t) ** 3  # cubic ease-out

    # === 숫자 애니메이션 업데이트 ===
    # 새로 켜진 숫자 감지 및 애니메이션 시작
    if _tutorial_action_gauge_current > _tutorial_action_gauge_prev_current:
        for i in range(_tutorial_action_gauge_prev_current, _tutorial_action_gauge_current):
            if i < len(_tutorial_action_gauge_number_light_time):
                _tutorial_action_gauge_number_light_time[i] = current_time
        _tutorial_action_gauge_prev_current = _tutorial_action_gauge_current

    # 각 숫자의 애니메이션 진행도 업데이트
    for i in range(len(_tutorial_action_gauge_number_anim)):
        if i < _tutorial_action_gauge_current or (_tutorial_action_gauge_complete and _tutorial_action_gauge_fill_anim >= 1.0):
            # 켜진 숫자 - 애니메이션 진행
            if _tutorial_action_gauge_number_light_time[i] > 0:
                elapsed = current_time - _tutorial_action_gauge_number_light_time[i]
                _tutorial_action_gauge_number_anim[i] = min(1.0, elapsed / 300)  # 0.3초 애니메이션
            else:
                _tutorial_action_gauge_number_anim[i] = 1.0
        else:
            # 꺼진 숫자
            _tutorial_action_gauge_number_anim[i] = 0.0

    # === 스킬 호버 타입일 때 특수 UI 렌더링 ===
    if _tutorial_action_gauge_type == "skill_hover":
        _draw_tutorial_skill_hover_gauge(target_screen, current_time, entrance_progress)
        return

    # === 스킬 사용 타입일 때 특수 UI 렌더링 ===
    if _tutorial_action_gauge_type == "skill_use":
        _draw_tutorial_skill_use_gauge(target_screen, current_time, entrance_progress)
        return

    # === 일반 게이지 렌더링 ===
    # 게이지 위치 (우측 상단 필러)
    if _is_fullscreen_active and REAL_SCREEN is not None:
        gauge_x = GAME_OFFSET_X + GAME_SCALED_WIDTH + 30
        gauge_y = GAME_OFFSET_Y + 30
        gauge_width = 120
        gauge_height = 140
    else:
        gauge_x = INTERNAL_WIDTH - 150
        gauge_y = 30
        gauge_width = 120
        gauge_height = 140

    # 배경 패널
    panel_surf = pygame.Surface((gauge_width, gauge_height), pygame.SRCALPHA)

    # 완료 시 배경 색상 변경 (황금색 글로우)
    if _tutorial_action_gauge_complete and _tutorial_action_gauge_fill_anim >= 1.0:
        bg_color = (25, 35, 20, 230)  # 약간 녹색 톤 배경
    else:
        bg_color = (15, 25, 45, 220)
    pygame.draw.rect(panel_surf, bg_color, (0, 0, gauge_width, gauge_height), border_radius=12)

    # 테두리 글로우 - 완료 시 황금색으로 변경
    glow_intensity = 0.7 + 0.3 * math.sin(current_time * 0.003)
    if _tutorial_action_gauge_complete and _tutorial_action_gauge_fill_anim >= 1.0:
        border_color = (255, 215, 0)  # 황금색
        # 완료 시 더 밝게 펄스
        pulse = int(50 * (0.5 + 0.5 * math.sin(current_time * 0.01)))
        border_color = (min(255, 255 + pulse), min(255, 215 + pulse), pulse)
    else:
        border_color = (80, 180, 255) if _tutorial_action_gauge_type == "combo" else (255, 180, 80)
    pygame.draw.rect(panel_surf, border_color, (0, 0, gauge_width, gauge_height), 3, border_radius=12)

    # 제목
    try:
        title_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), 14)
    except:
        title_font = pygame.freetype.SysFont("malgun gothic", 14)

    title_surf, title_rect = title_font.render(_tutorial_action_gauge_title, (255, 255, 255))
    title_x = (gauge_width - title_rect.width) // 2
    panel_surf.blit(title_surf, (title_x, 12))

    # 게이지 바 영역
    bar_x = 15
    bar_y = 40
    bar_width = gauge_width - 30
    bar_height = 20

    # 게이지 배경
    pygame.draw.rect(panel_surf, (30, 40, 60), (bar_x, bar_y, bar_width, bar_height), border_radius=5)

    # 게이지 채우기 - 완료 애니메이션 적용
    if _tutorial_action_gauge_complete:
        # 완료 시 애니메이션으로 채우기
        fill_ratio = _tutorial_action_gauge_fill_anim
    else:
        fill_ratio = _tutorial_action_gauge_current / _tutorial_action_gauge_target if _tutorial_action_gauge_target > 0 else 0

    fill_width = int(bar_width * fill_ratio)

    # 색상 결정
    if _tutorial_action_gauge_complete and _tutorial_action_gauge_fill_anim >= 1.0:
        fill_color = (100, 255, 100)  # 완료 시 밝은 녹색
        highlight_color = (180, 255, 180)
    else:
        fill_color = (100, 200, 255) if _tutorial_action_gauge_type == "combo" else (255, 200, 100)
        highlight_color = (180, 230, 255) if _tutorial_action_gauge_type == "combo" else (255, 230, 180)

    if fill_width > 0:
        pygame.draw.rect(panel_surf, fill_color, (bar_x, bar_y, fill_width, bar_height), border_radius=5)
        # 하이라이트
        pygame.draw.rect(panel_surf, highlight_color, (bar_x, bar_y, fill_width, 6), border_radius=3)

    # 게이지 테두리
    pygame.draw.rect(panel_surf, (80, 100, 140), (bar_x, bar_y, bar_width, bar_height), 2, border_radius=5)

    # 진행도 숫자 또는 "완료!" 텍스트
    try:
        num_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), 28)
    except:
        num_font = pygame.freetype.SysFont("malgun gothic", 28)

    if _tutorial_action_gauge_complete and _tutorial_action_gauge_fill_anim >= 1.0:
        # 완료 텍스트 표시 (펄스 효과)
        pulse_scale = 1.0 + 0.1 * math.sin(current_time * 0.008)
        try:
            complete_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), int(24 * pulse_scale))
        except:
            complete_font = pygame.freetype.SysFont("malgun gothic", int(24 * pulse_scale))

        # 완료! 텍스트 (황금색)
        complete_text = "완료!"
        complete_surf, complete_rect = complete_font.render(complete_text, (255, 215, 0))
        complete_x = (gauge_width - complete_rect.width) // 2
        panel_surf.blit(complete_surf, (complete_x, 68))
    else:
        progress_text = f"{_tutorial_action_gauge_current}/{_tutorial_action_gauge_target}"
        progress_surf, progress_rect = num_font.render(progress_text, (255, 255, 255))
        progress_x = (gauge_width - progress_rect.width) // 2
        panel_surf.blit(progress_surf, (progress_x, 70))

    # === 콤보 숫자들 (1, 2, 3...) - 점점 화려해지는 애니메이션 ===
    # 대쉬/하프대쉬는 숫자 표시 안 함 (목표가 1개라 의미 없음)
    if _tutorial_action_gauge_type not in ("dash", "half_dash") and _tutorial_action_gauge_target > 1:
        icon_y = 110
        icon_spacing = bar_width // (_tutorial_action_gauge_target + 1)

        # 숫자 색상 정의 (점점 화려해짐)
        number_colors = [
            ((100, 200, 255), (180, 230, 255)),   # 1: 하늘색
            ((255, 200, 100), (255, 230, 180)),   # 2: 주황색
            ((255, 100, 150), (255, 180, 200)),   # 3: 핑크색
        ]

        try:
            combo_num_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), 18)
        except:
            combo_num_font = pygame.freetype.SysFont("malgun gothic", 18)

        for i in range(_tutorial_action_gauge_target):
            icon_x = bar_x + icon_spacing * (i + 1)
            num_text = str(i + 1)

            # 애니메이션 진행도 가져오기
            anim_progress = _tutorial_action_gauge_number_anim[i] if i < len(_tutorial_action_gauge_number_anim) else 0.0
            is_lit = i < _tutorial_action_gauge_current or (_tutorial_action_gauge_complete and _tutorial_action_gauge_fill_anim >= 1.0)

            # 리셋 애니메이션 중일 때 깜빡임 효과
            if _tutorial_action_gauge_reset_active and i < _tutorial_action_gauge_reset_from:
                flash_speed = 15  # 깜빡임 속도
                flash_alpha = int(128 + 127 * math.sin(reset_progress * flash_speed))
                # 빨간색 깜빡임
                flash_color = (255, 80, 80, flash_alpha)
                flash_surf = pygame.Surface((24, 24), pygame.SRCALPHA)
                pygame.draw.circle(flash_surf, flash_color, (12, 12), 12)
                panel_surf.blit(flash_surf, (icon_x - 12, icon_y - 12))

            if is_lit:
                # === 켜진 숫자 (화려한 효과) ===
                color_idx = min(i, len(number_colors) - 1)
                base_color, highlight = number_colors[color_idx]

                # 펄스 효과 (숫자별로 다른 속도)
                pulse = 0.9 + 0.1 * math.sin(current_time * 0.008 + i * 0.5)

                # 애니메이션 진행 중 크기 확대 효과
                scale = 1.0 + 0.3 * (1.0 - anim_progress) if anim_progress < 1.0 else pulse

                # 글로우 효과 (배경 원)
                glow_radius = int(14 * scale)
                glow_alpha = int(150 * anim_progress)
                glow_surf = pygame.Surface((glow_radius * 2 + 4, glow_radius * 2 + 4), pygame.SRCALPHA)

                # 다중 글로우 레이어
                for layer in range(3):
                    layer_radius = glow_radius - layer * 2
                    layer_alpha = glow_alpha // (layer + 1)
                    pygame.draw.circle(glow_surf, (*base_color, layer_alpha),
                                       (glow_radius + 2, glow_radius + 2), layer_radius)
                panel_surf.blit(glow_surf, (icon_x - glow_radius - 2, icon_y - glow_radius - 2))

                # 숫자 렌더링 (밝은 색)
                font_size = int(18 * scale)
                try:
                    scaled_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), font_size)
                except:
                    scaled_font = pygame.freetype.SysFont("malgun gothic", font_size)

                # 외곽선 효과
                for ox, oy in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                    outline_surf, _ = scaled_font.render(num_text, highlight)
                    panel_surf.blit(outline_surf, (icon_x - outline_surf.get_width() // 2 + ox,
                                                   icon_y - outline_surf.get_height() // 2 + oy))

                # 메인 숫자
                num_surf, num_rect = scaled_font.render(num_text, base_color)
                panel_surf.blit(num_surf, (icon_x - num_surf.get_width() // 2, icon_y - num_surf.get_height() // 2))

                # 반짝임 파티클 (완전히 켜진 후)
                if anim_progress >= 1.0:
                    sparkle_count = i + 2  # 숫자가 높을수록 더 많은 반짝임
                    for s in range(sparkle_count):
                        sparkle_angle = (current_time * 0.003 + s * (math.pi * 2 / sparkle_count) + i) % (math.pi * 2)
                        sparkle_dist = 10 + 4 * math.sin(current_time * 0.005 + s)
                        sparkle_x = icon_x + math.cos(sparkle_angle) * sparkle_dist
                        sparkle_y = icon_y + math.sin(sparkle_angle) * sparkle_dist
                        sparkle_alpha = int(100 + 80 * math.sin(current_time * 0.01 + s))
                        sparkle_size = 2 + int(math.sin(current_time * 0.008 + s) > 0.5)
                        pygame.draw.circle(panel_surf, (*highlight[:3], sparkle_alpha),
                                           (int(sparkle_x), int(sparkle_y)), sparkle_size)
            else:
                # === 꺼진 숫자 (회색, 어둡게) ===
                # 어두운 배경 원
                pygame.draw.circle(panel_surf, (40, 50, 70), (icon_x, icon_y), 12)
                pygame.draw.circle(panel_surf, (60, 75, 100), (icon_x, icon_y), 12, 2)

                # 회색 숫자
                num_surf, num_rect = combo_num_font.render(num_text, (80, 90, 110))
                panel_surf.blit(num_surf, (icon_x - num_surf.get_width() // 2, icon_y - num_surf.get_height() // 2))

    # === 리셋 애니메이션: 실패 표시 ===
    if _tutorial_action_gauge_reset_active:
        # 전체 패널에 빨간 플래시
        flash_intensity = int(30 * (1.0 - reset_progress) * (0.5 + 0.5 * math.sin(reset_progress * 20)))
        if flash_intensity > 0:
            flash_overlay = pygame.Surface((gauge_width, gauge_height), pygame.SRCALPHA)
            flash_overlay.fill((255, 50, 50, flash_intensity))
            panel_surf.blit(flash_overlay, (0, 0))

        # "RESET!" 텍스트 (초반에만 표시)
        if reset_progress < 0.5:
            try:
                reset_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), 16)
            except:
                reset_font = pygame.freetype.SysFont("malgun gothic", 16)

            reset_alpha = int(255 * (1.0 - reset_progress * 2))
            shake_x = int(3 * math.sin(reset_progress * 30))
            reset_surf, reset_rect = reset_font.render("RESET!", (255, 100, 100))
            reset_x = (gauge_width - reset_rect.width) // 2 + shake_x
            panel_surf.blit(reset_surf, (reset_x, 45))

    # === 등장 애니메이션 적용 ===
    if entrance_progress < 1.0:
        # 스케일 효과 (작은 상태에서 커지면서 등장)
        scale = 0.5 + 0.5 * entrance_progress
        # 오른쪽에서 슬라이드 인
        slide_offset = int(50 * (1.0 - entrance_progress))
        # 투명도
        alpha = int(255 * entrance_progress)

        # 스케일 적용된 서피스 생성
        scaled_width = int(gauge_width * scale)
        scaled_height = int(gauge_height * scale)
        if scaled_width > 0 and scaled_height > 0:
            scaled_surf = pygame.transform.smoothscale(panel_surf, (scaled_width, scaled_height))
            scaled_surf.set_alpha(alpha)

            # 중심 기준으로 위치 조정
            offset_x = (gauge_width - scaled_width) // 2
            offset_y = (gauge_height - scaled_height) // 2
            final_x = gauge_x + offset_x + slide_offset
            final_y = gauge_y + offset_y

            # 글로우 효과 (등장 시 밝은 테두리)
            glow_alpha = int(200 * (1.0 - entrance_progress))
            if glow_alpha > 0:
                glow_surf = pygame.Surface((scaled_width + 20, scaled_height + 20), pygame.SRCALPHA)
                glow_color = (100, 200, 255, glow_alpha) if _tutorial_action_gauge_type == "combo" else (255, 200, 100, glow_alpha)
                pygame.draw.rect(glow_surf, glow_color, (0, 0, scaled_width + 20, scaled_height + 20), border_radius=16)
                target_screen.blit(glow_surf, (final_x - 10, final_y - 10))

            target_screen.blit(scaled_surf, (final_x, final_y))
    else:
        target_screen.blit(panel_surf, (gauge_x, gauge_y))

    # 대쉬/하프대쉬일 때 키캡 설명 추가
    if _tutorial_action_gauge_type in ("dash", "half_dash"):
        # 등장 애니메이션 중에는 키캡 힌트도 페이드인
        hint_alpha = int(255 * entrance_progress) if entrance_progress < 1.0 else 255
        _draw_dash_keycap_hint(target_screen, gauge_x, gauge_y + gauge_height + 8, gauge_width, _tutorial_action_gauge_type, hint_alpha)


def _draw_dash_keycap_hint(target_screen, x, y, width, gauge_type="dash", alpha=255):
    """대쉬 조작법 키캡 힌트 그리기"""
    # 하프대쉬는 추가 설명이 있어서 높이가 더 큼
    is_half_dash = (gauge_type == "half_dash")
    hint_height = 70 if is_half_dash else 50

    hint_surf = pygame.Surface((width, hint_height), pygame.SRCALPHA)
    pygame.draw.rect(hint_surf, (15, 25, 45, 200), (0, 0, width, hint_height), border_radius=8)

    # 하프대쉬는 주황색 테두리
    border_color = (200, 140, 60) if is_half_dash else (60, 100, 160)
    pygame.draw.rect(hint_surf, border_color, (0, 0, width, hint_height), 2, border_radius=8)

    # 폰트 설정
    try:
        key_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), 12)
        small_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), 10)
        tiny_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), 9)
    except:
        key_font = pygame.freetype.SysFont("malgun gothic", 12)
        small_font = pygame.freetype.SysFont("malgun gothic", 10)
        tiny_font = pygame.freetype.SysFont("malgun gothic", 9)

    # 첫 번째 줄: A 또는 D + S
    line1_y = 8
    current_x = 10

    # "A" 키캡
    _draw_keycap(hint_surf, current_x, line1_y, "A", key_font)
    current_x += 22

    # "or" 텍스트
    or_surf, or_rect = small_font.render("or", (180, 180, 180))
    hint_surf.blit(or_surf, (current_x, line1_y + 4))
    current_x += or_rect.width + 4

    # "D" 키캡
    _draw_keycap(hint_surf, current_x, line1_y, "D", key_font)
    current_x += 22

    # "+" 텍스트
    plus_surf, plus_rect = small_font.render("+", (200, 200, 200))
    hint_surf.blit(plus_surf, (current_x, line1_y + 3))
    current_x += plus_rect.width + 4

    # "S" 키캡 (강조)
    _draw_keycap(hint_surf, current_x, line1_y, "S", key_font, highlight=True)

    # 두 번째 줄: 설명
    desc_text = "이동 중 S키로 대쉬!"
    desc_color = (255, 200, 100) if is_half_dash else (150, 200, 255)
    desc_surf, _ = small_font.render(desc_text, desc_color)
    desc_x = (width - desc_surf.get_width()) // 2
    hint_surf.blit(desc_surf, (desc_x, 30))

    # 하프대쉬일 때 추가 설명
    if is_half_dash:
        extra_text = "토큰 완충 전에 발동!"
        extra_surf, _ = tiny_font.render(extra_text, (255, 180, 80))
        extra_x = (width - extra_surf.get_width()) // 2
        hint_surf.blit(extra_surf, (extra_x, 50))

    # 등장 애니메이션 알파 적용
    if alpha < 255:
        hint_surf.set_alpha(alpha)
    target_screen.blit(hint_surf, (x, y))


def _draw_keycap(surface, x, y, key_text, font, highlight=False):
    """키캡 아이콘 그리기"""
    cap_size = 18
    # 키캡 배경
    if highlight:
        bg_color = (80, 150, 220)
        border_color = (120, 200, 255)
        text_color = (255, 255, 255)
    else:
        bg_color = (50, 60, 80)
        border_color = (100, 120, 150)
        text_color = (220, 220, 220)

    pygame.draw.rect(surface, bg_color, (x, y, cap_size, cap_size), border_radius=4)
    pygame.draw.rect(surface, border_color, (x, y, cap_size, cap_size), 2, border_radius=4)

    # 키 텍스트
    text_surf, text_rect = font.render(key_text, text_color)
    text_x = x + (cap_size - text_rect.width) // 2
    text_y = y + (cap_size - text_rect.height) // 2
    surface.blit(text_surf, (text_x, text_y))


def _draw_tutorial_skill_hover_gauge(target_screen, current_time, entrance_progress=1.0):
    """튜토리얼 스킬 호버 미션 전용 UI 렌더링 - 드라이브/파워스매싱 아이콘 + 개별 게이지"""

    # 패널 크기 (더 넓게 - 두 스킬 아이콘을 나란히 표시)
    if _is_fullscreen_active and REAL_SCREEN is not None:
        gauge_x = GAME_OFFSET_X + GAME_SCALED_WIDTH + 15
        gauge_y = GAME_OFFSET_Y + 30
        gauge_width = 150
        gauge_height = 180
    else:
        gauge_x = INTERNAL_WIDTH - 165
        gauge_y = 30
        gauge_width = 150
        gauge_height = 180

    # 배경 패널
    panel_surf = pygame.Surface((gauge_width, gauge_height), pygame.SRCALPHA)

    # 완료 시 배경 색상 변경
    if _tutorial_action_gauge_complete and _tutorial_action_gauge_fill_anim >= 1.0:
        bg_color = (25, 35, 20, 230)
    else:
        bg_color = (15, 25, 45, 220)
    pygame.draw.rect(panel_surf, bg_color, (0, 0, gauge_width, gauge_height), border_radius=12)

    # 테두리
    if _tutorial_action_gauge_complete and _tutorial_action_gauge_fill_anim >= 1.0:
        pulse = int(50 * (0.5 + 0.5 * math.sin(current_time * 0.01)))
        border_color = (min(255, 255 + pulse), min(255, 215 + pulse), pulse)
    else:
        border_color = (255, 180, 80)
    pygame.draw.rect(panel_surf, border_color, (0, 0, gauge_width, gauge_height), 3, border_radius=12)

    # 제목
    try:
        title_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), 13)
    except:
        title_font = pygame.freetype.SysFont("malgun gothic", 13)

    title_surf, title_rect = title_font.render(_t("ui.skill_info", "스킬 정보 확인"), (255, 255, 255))
    title_x = (gauge_width - title_rect.width) // 2
    panel_surf.blit(title_surf, (title_x, 8))

    # 스킬 데이터 가져오기
    drive_data = None
    power_data = None
    for skill in SMASHER_SKILL_ICONS_DATA:
        if skill["name"] == "drive":
            drive_data = skill
        elif skill["name"] == "power_smashing":
            power_data = skill

    # 두 스킬 아이콘 좌우 배치
    icon_size = 40
    icon_y = 35
    left_icon_x = 20
    right_icon_x = gauge_width - 20 - icon_size

    # 현재 호버 진행도 계산
    drive_progress = 0.0
    power_progress = 0.0

    if _tutorial_skill_hover_drive:
        drive_progress = 1.0
    elif _tutorial_skill_hover_current == "drive":
        elapsed = current_time - _tutorial_skill_hover_start_time
        drive_progress = min(1.0, elapsed / _tutorial_skill_hover_duration)

    if _tutorial_skill_hover_power:
        power_progress = 1.0
    elif _tutorial_skill_hover_current == "power":
        elapsed = current_time - _tutorial_skill_hover_start_time
        power_progress = min(1.0, elapsed / _tutorial_skill_hover_duration)

    # === 드라이브 스킬 아이콘 및 게이지 ===
    if drive_data:
        # 아이콘 생성 및 그리기
        drive_icon = _create_smasher_skill_icon(drive_data, icon_size, active=True)
        # 아이콘 중심 맞춤 (create_smasher_skill_icon은 여백 포함)
        icon_offset = (drive_icon.get_width() - icon_size) // 2
        panel_surf.blit(drive_icon, (left_icon_x - icon_offset, icon_y - icon_offset))

        # 스킬명
        try:
            name_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), 10)
        except:
            name_font = pygame.freetype.SysFont("malgun gothic", 10)
        name_surf, name_rect = name_font.render(_t("ui.drive", "드라이브"), drive_data["color"])
        name_x = left_icon_x + (icon_size - name_rect.width) // 2
        panel_surf.blit(name_surf, (name_x, icon_y + icon_size + 5))

        # 호버 게이지 (원형)
        gauge_center_x = left_icon_x + icon_size // 2
        gauge_center_y = icon_y + icon_size + 30
        gauge_radius = 18

        # 게이지 배경
        pygame.draw.circle(panel_surf, (30, 40, 60), (gauge_center_x, gauge_center_y), gauge_radius)

        # 게이지 채우기 (원형 아크)
        if drive_progress > 0:
            if _tutorial_skill_hover_drive:
                # 완료 시 녹색
                fill_color = (100, 255, 100)
            else:
                fill_color = drive_data["color"]

            # 원형 게이지 그리기 (파이 형태)
            start_angle = -math.pi / 2  # 12시 방향부터 시작
            end_angle = start_angle + (2 * math.pi * drive_progress)

            # 채워진 부분
            points = [(gauge_center_x, gauge_center_y)]
            for i in range(int(drive_progress * 30) + 1):
                angle = start_angle + (end_angle - start_angle) * i / 30
                px = gauge_center_x + int(math.cos(angle) * (gauge_radius - 2))
                py = gauge_center_y + int(math.sin(angle) * (gauge_radius - 2))
                points.append((px, py))
            if len(points) > 2:
                pygame.draw.polygon(panel_surf, fill_color, points)

        # 게이지 테두리
        pygame.draw.circle(panel_surf, (80, 100, 140), (gauge_center_x, gauge_center_y), gauge_radius, 2)

        # 완료 체크 또는 퍼센트
        if _tutorial_skill_hover_drive:
            # 체크 마크
            pygame.draw.line(panel_surf, (255, 255, 255),
                           (gauge_center_x - 6, gauge_center_y),
                           (gauge_center_x - 2, gauge_center_y + 5), 3)
            pygame.draw.line(panel_surf, (255, 255, 255),
                           (gauge_center_x - 2, gauge_center_y + 5),
                           (gauge_center_x + 7, gauge_center_y - 6), 3)
        else:
            # 남은 시간 표시
            try:
                pct_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), 10)
            except:
                pct_font = pygame.freetype.SysFont("malgun gothic", 10)
            remaining = max(0, 3.0 - (3.0 * drive_progress))
            pct_text = f"{remaining:.1f}s"
            pct_surf, pct_rect = pct_font.render(pct_text, (255, 255, 255))
            pct_x = gauge_center_x - pct_rect.width // 2
            pct_y = gauge_center_y - pct_rect.height // 2
            panel_surf.blit(pct_surf, (pct_x, pct_y))

    # === 파워스매싱 스킬 아이콘 및 게이지 ===
    if power_data:
        # 아이콘 생성 및 그리기
        power_icon = _create_smasher_skill_icon(power_data, icon_size, active=True)
        icon_offset = (power_icon.get_width() - icon_size) // 2
        panel_surf.blit(power_icon, (right_icon_x - icon_offset, icon_y - icon_offset))

        # 스킬명
        try:
            name_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), 10)
        except:
            name_font = pygame.freetype.SysFont("malgun gothic", 10)
        name_surf, name_rect = name_font.render(_t("ui.power_smashing", "파워스매싱"), power_data["color"])
        name_x = right_icon_x + (icon_size - name_rect.width) // 2
        panel_surf.blit(name_surf, (name_x, icon_y + icon_size + 5))

        # 호버 게이지 (원형)
        gauge_center_x = right_icon_x + icon_size // 2
        gauge_center_y = icon_y + icon_size + 30
        gauge_radius = 18

        # 게이지 배경
        pygame.draw.circle(panel_surf, (30, 40, 60), (gauge_center_x, gauge_center_y), gauge_radius)

        # 게이지 채우기 (원형 아크)
        if power_progress > 0:
            if _tutorial_skill_hover_power:
                fill_color = (100, 255, 100)
            else:
                fill_color = power_data["color"]

            start_angle = -math.pi / 2
            end_angle = start_angle + (2 * math.pi * power_progress)

            points = [(gauge_center_x, gauge_center_y)]
            for i in range(int(power_progress * 30) + 1):
                angle = start_angle + (end_angle - start_angle) * i / 30
                px = gauge_center_x + int(math.cos(angle) * (gauge_radius - 2))
                py = gauge_center_y + int(math.sin(angle) * (gauge_radius - 2))
                points.append((px, py))
            if len(points) > 2:
                pygame.draw.polygon(panel_surf, fill_color, points)

        # 게이지 테두리
        pygame.draw.circle(panel_surf, (80, 100, 140), (gauge_center_x, gauge_center_y), gauge_radius, 2)

        # 완료 체크 또는 퍼센트
        if _tutorial_skill_hover_power:
            pygame.draw.line(panel_surf, (255, 255, 255),
                           (gauge_center_x - 6, gauge_center_y),
                           (gauge_center_x - 2, gauge_center_y + 5), 3)
            pygame.draw.line(panel_surf, (255, 255, 255),
                           (gauge_center_x - 2, gauge_center_y + 5),
                           (gauge_center_x + 7, gauge_center_y - 6), 3)
        else:
            try:
                pct_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), 10)
            except:
                pct_font = pygame.freetype.SysFont("malgun gothic", 10)
            remaining = max(0, 3.0 - (3.0 * power_progress))
            pct_text = f"{remaining:.1f}s"
            pct_surf, pct_rect = pct_font.render(pct_text, (255, 255, 255))
            pct_x = gauge_center_x - pct_rect.width // 2
            pct_y = gauge_center_y - pct_rect.height // 2
            panel_surf.blit(pct_surf, (pct_x, pct_y))

    # === 하단 완료 상태 표시 ===
    status_y = gauge_height - 25

    if _tutorial_action_gauge_complete and _tutorial_action_gauge_fill_anim >= 1.0:
        # 완료 텍스트
        try:
            complete_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), 16)
        except:
            complete_font = pygame.freetype.SysFont("malgun gothic", 16)
        complete_surf, complete_rect = complete_font.render(_t("ui.complete", "완료!"), (255, 215, 0))
        complete_x = (gauge_width - complete_rect.width) // 2
        panel_surf.blit(complete_surf, (complete_x, status_y))
    else:
        # 진행 상황 (x/2)
        try:
            status_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), 14)
        except:
            status_font = pygame.freetype.SysFont("malgun gothic", 14)
        completed_count = (1 if _tutorial_skill_hover_drive else 0) + (1 if _tutorial_skill_hover_power else 0)
        status_text = _t("ui.progress_fmt", "{0}/2 완료").format(completed_count)
        status_surf, status_rect = status_font.render(status_text, (200, 200, 200))
        status_x = (gauge_width - status_rect.width) // 2
        panel_surf.blit(status_surf, (status_x, status_y))

    # === 등장 애니메이션 적용 ===
    if entrance_progress < 1.0:
        scale = 0.5 + 0.5 * entrance_progress
        slide_offset = int(50 * (1.0 - entrance_progress))
        alpha = int(255 * entrance_progress)
        scaled_width = int(gauge_width * scale)
        scaled_height = int(gauge_height * scale)
        if scaled_width > 0 and scaled_height > 0:
            scaled_surf = pygame.transform.smoothscale(panel_surf, (scaled_width, scaled_height))
            scaled_surf.set_alpha(alpha)
            offset_x = (gauge_width - scaled_width) // 2
            offset_y = (gauge_height - scaled_height) // 2
            final_x = gauge_x + offset_x + slide_offset
            final_y = gauge_y + offset_y
            glow_alpha = int(200 * (1.0 - entrance_progress))
            if glow_alpha > 0:
                glow_surf = pygame.Surface((scaled_width + 20, scaled_height + 20), pygame.SRCALPHA)
                pygame.draw.rect(glow_surf, (255, 200, 100, glow_alpha), (0, 0, scaled_width + 20, scaled_height + 20), border_radius=16)
                target_screen.blit(glow_surf, (final_x - 10, final_y - 10))
            target_screen.blit(scaled_surf, (final_x, final_y))
    else:
        target_screen.blit(panel_surf, (gauge_x, gauge_y))


def _draw_tutorial_skill_use_gauge(target_screen, current_time, entrance_progress=1.0):
    """튜토리얼 스킬 사용 미션 전용 UI 렌더링 - 드라이브/파워스매싱 아이콘 + 사용 여부 표시"""

    # 패널 크기 (두 스킬 아이콘을 나란히 표시)
    if _is_fullscreen_active and REAL_SCREEN is not None:
        gauge_x = GAME_OFFSET_X + GAME_SCALED_WIDTH + 15
        gauge_y = GAME_OFFSET_Y + 30
        gauge_width = 150
        gauge_height = 160
    else:
        gauge_x = INTERNAL_WIDTH - 165
        gauge_y = 30
        gauge_width = 150
        gauge_height = 160

    # 배경 패널
    panel_surf = pygame.Surface((gauge_width, gauge_height), pygame.SRCALPHA)

    # 완료 시 배경 색상 변경
    if _tutorial_action_gauge_complete and _tutorial_action_gauge_fill_anim >= 1.0:
        bg_color = (25, 35, 20, 230)
    else:
        bg_color = (15, 25, 45, 220)
    pygame.draw.rect(panel_surf, bg_color, (0, 0, gauge_width, gauge_height), border_radius=12)

    # 테두리
    if _tutorial_action_gauge_complete and _tutorial_action_gauge_fill_anim >= 1.0:
        pulse = int(50 * (0.5 + 0.5 * math.sin(current_time * 0.01)))
        border_color = (min(255, 255 + pulse), min(255, 215 + pulse), pulse)
    else:
        border_color = (255, 150, 100)  # 스킬 사용은 주황빛
    pygame.draw.rect(panel_surf, border_color, (0, 0, gauge_width, gauge_height), 3, border_radius=12)

    # 제목
    try:
        title_font = pygame.freetype.Font(get_pixel_font_path(), 13)
    except:
        title_font = pygame.freetype.SysFont("malgun gothic", 13)

    title_surf, title_rect = title_font.render(_t("ui.skill_use", "스킬 사용"), (255, 255, 255))
    title_x = (gauge_width - title_rect.width) // 2
    panel_surf.blit(title_surf, (title_x, 8))

    # 스킬 데이터 가져오기
    drive_data = None
