def show_mission_banner(text: str, duration_ms: int = 2000):
    """미션 안내창 표시"""
    global _mission_banner_active, _mission_banner_text, _mission_banner_start_time, _mission_banner_duration
    _mission_banner_active = True
    _mission_banner_text = text
    _mission_banner_start_time = pygame.time.get_ticks()
    _mission_banner_duration = duration_ms

    # 미션 배너 효과음 재생
    if "TUTORIAL_MISSION" in sound_effects and sound_effects["TUTORIAL_MISSION"]:
        sound_effects["TUTORIAL_MISSION"].play()


def update_mission_banner():
    """미션 안내창 업데이트"""
    global _mission_banner_active
    if not _mission_banner_active:
        return

    elapsed = pygame.time.get_ticks() - _mission_banner_start_time
    total_duration = _mission_banner_duration + _mission_banner_fade_duration * 2

    if elapsed >= total_duration:
        _mission_banner_active = False


def draw_mission_banner():
    """미션 안내창 그리기 - 사이버틱한 스타일"""
    global _mission_banner_active
    if not _mission_banner_active:
        return

    # REAL_SCREEN 또는 SCREEN 결정 (전체화면 모드 여부에 따라)
    target_screen = REAL_SCREEN if (_is_fullscreen_active and REAL_SCREEN is not None) else SCREEN

    elapsed = pygame.time.get_ticks() - _mission_banner_start_time
    fade_in = _mission_banner_fade_duration
    fade_out = _mission_banner_fade_duration
    total_duration = _mission_banner_duration + fade_in + fade_out

    # 알파값 계산 (페이드 인/아웃)
    if elapsed < fade_in:
        # 페이드 인
        alpha = int(255 * (elapsed / fade_in))
        scale = 0.8 + 0.2 * (elapsed / fade_in)  # 0.8 -> 1.0 스케일
    elif elapsed < fade_in + _mission_banner_duration:
        # 유지
        alpha = 255
        scale = 1.0
    elif elapsed < total_duration:
        # 페이드 아웃
        fade_progress = (elapsed - fade_in - _mission_banner_duration) / fade_out
        alpha = int(255 * (1 - fade_progress))
        scale = 1.0 + 0.2 * fade_progress  # 1.0 -> 1.2 스케일 (확대되면서 사라짐)
    else:
        _mission_banner_active = False
        return

    # 배너 크기 및 위치 (전체화면 모드에서는 REAL_SCREEN 중앙)
    banner_width = 620
    banner_height = 70

    if _is_fullscreen_active and REAL_SCREEN is not None:
        # 전체화면 모드: 게임 영역 중앙에 표시
        center_x = GAME_OFFSET_X + GAME_SCALED_WIDTH // 2
        center_y = GAME_OFFSET_Y + GAME_SCALED_HEIGHT // 2
    else:
        # 창 모드: 기존 좌표
        center_x = WIDTH // 2 + GAME_AREA_OFFSET_X // 2
        center_y = HEIGHT // 2

    # 스케일 적용
    scaled_width = int(banner_width * scale)
    scaled_height = int(banner_height * scale)

    # 배너 서피스 생성
    banner_surface = pygame.Surface((scaled_width, scaled_height), pygame.SRCALPHA)

    # 사이버틱 배경 (그라데이션 효과)
    time_factor = pygame.time.get_ticks() * 0.002
    glow_intensity = 0.7 + 0.3 * math.sin(time_factor)

    # 메인 배경 (어두운 파란색 반투명)
    bg_color = (10, 20, 40, int(200 * alpha / 255))
    pygame.draw.rect(banner_surface, bg_color, (0, 0, scaled_width, scaled_height))

    # 테두리 글로우 효과
    glow_color_r = int(50 + 100 * glow_intensity)
    glow_color_g = int(150 + 100 * glow_intensity)
    glow_color_b = 255
    glow_alpha = int(alpha * glow_intensity)

    # 외곽 글로우 (여러 레이어)
    for i in range(3):
        glow_rect = pygame.Rect(i, i, scaled_width - i*2, scaled_height - i*2)
        glow_a = int(glow_alpha * (1 - i * 0.3))
        pygame.draw.rect(banner_surface, (glow_color_r, glow_color_g, glow_color_b, glow_a), glow_rect, 2)

    # 스캔라인 효과
    scan_y = int((elapsed * 0.1) % scaled_height)
    scan_surface = pygame.Surface((scaled_width, 3), pygame.SRCALPHA)
    scan_surface.fill((100, 200, 255, int(50 * alpha / 255)))
    banner_surface.blit(scan_surface, (0, scan_y))

    # 코너 장식 (사이버틱 모서리)
    corner_size = 15
    corner_color = (glow_color_r, glow_color_g, glow_color_b, glow_alpha)
    # 좌상단
    pygame.draw.line(banner_surface, corner_color, (0, corner_size), (0, 0), 2)
    pygame.draw.line(banner_surface, corner_color, (0, 0), (corner_size, 0), 2)
    # 우상단
    pygame.draw.line(banner_surface, corner_color, (scaled_width - corner_size, 0), (scaled_width - 1, 0), 2)
    pygame.draw.line(banner_surface, corner_color, (scaled_width - 1, 0), (scaled_width - 1, corner_size), 2)
    # 좌하단
    pygame.draw.line(banner_surface, corner_color, (0, scaled_height - corner_size), (0, scaled_height - 1), 2)
    pygame.draw.line(banner_surface, corner_color, (0, scaled_height - 1), (corner_size, scaled_height - 1), 2)
    # 우하단
    pygame.draw.line(banner_surface, corner_color, (scaled_width - corner_size, scaled_height - 1), (scaled_width - 1, scaled_height - 1), 2)
    pygame.draw.line(banner_surface, corner_color, (scaled_width - 1, scaled_height - corner_size), (scaled_width - 1, scaled_height - 1), 2)

    # 텍스트 렌더링 (한글 지원을 위해 pygame.freetype 사용)
    try:
        font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), int(18 * scale))
        key_font = pygame.freetype.Font(resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), int(14 * scale))
    except:
        font = pygame.freetype.SysFont("malgun gothic", int(18 * scale))
        key_font = pygame.freetype.SysFont("malgun gothic", int(14 * scale))

    # 텍스트 글로우 효과
    text_glow_color = (100, 200, 255)
    text_main_color = (255, 255, 255)

    # {KEY:X} 패턴 파싱하여 키캡 아이콘과 텍스트 분리 렌더링
    import re
    key_pattern = re.compile(r'\{KEY:([^}]+)\}')

    # 텍스트를 파싱하여 세그먼트 리스트 생성
    segments = []
    last_end = 0
    for match in key_pattern.finditer(_mission_banner_text):
        # 키 이전 텍스트
        if match.start() > last_end:
            segments.append(("text", _mission_banner_text[last_end:match.start()]))
        # 키캡
        segments.append(("key", match.group(1)))
        last_end = match.end()
    # 마지막 텍스트
    if last_end < len(_mission_banner_text):
        segments.append(("text", _mission_banner_text[last_end:]))

    # 전체 너비 계산
    total_width = 0
    segment_surfaces = []
    keycap_size = int(26 * scale)
    keycap_padding = int(4 * scale)

    for seg_type, seg_content in segments:
        if seg_type == "text":
            text_surf, text_r = font.render(seg_content, text_main_color)
            # (타입, 서피스, 너비, 원본텍스트) 저장
            segment_surfaces.append(("text", text_surf, text_r.width, seg_content))
            total_width += text_r.width
        else:  # key
            segment_surfaces.append(("key", seg_content, keycap_size + keycap_padding, None))
            total_width += keycap_size + keycap_padding

    # 시작 X 위치 (중앙 정렬)
    start_x = (scaled_width - total_width) // 2
    current_x = start_x
    center_y_text = scaled_height // 2

    # 세그먼트별 렌더링
    for seg_type, seg_data, seg_width, seg_original in segment_surfaces:
        if seg_type == "text":
            # 글로우 효과
            for off_x, off_y in [(-1, -1), (1, -1), (-1, 1), (1, 1)]:
                glow_surf, _ = font.render(seg_original, text_glow_color)
                glow_surf.set_alpha(int(alpha * 0.5))
                banner_surface.blit(glow_surf, (current_x + off_x, center_y_text - seg_data.get_height() // 2 + off_y))
            # 메인 텍스트
            seg_data.set_alpha(alpha)
            banner_surface.blit(seg_data, (current_x, center_y_text - seg_data.get_height() // 2))
            current_x += seg_width
        else:  # key (키캡 아이콘)
            key_char = seg_data
            key_x = current_x
            key_y = center_y_text - keycap_size // 2

            # 키캡 배경 (3D 효과)
            # 그림자
            shadow_rect = pygame.Rect(key_x + 2, key_y + 3, keycap_size, keycap_size)
            pygame.draw.rect(banner_surface, (30, 30, 40, int(alpha * 0.8)), shadow_rect, border_radius=int(5 * scale))

            # 키캡 바닥 (어두운 색)
            bottom_rect = pygame.Rect(key_x, key_y + 2, keycap_size, keycap_size)
            pygame.draw.rect(banner_surface, (60, 60, 80, alpha), bottom_rect, border_radius=int(5 * scale))

            # 키캡 상단 (밝은 색)
            top_rect = pygame.Rect(key_x, key_y, keycap_size, keycap_size - 2)
            pygame.draw.rect(banner_surface, (90, 95, 110, alpha), top_rect, border_radius=int(5 * scale))

            # 키캡 내부 (그라데이션 효과)
            inner_rect = pygame.Rect(key_x + 2, key_y + 2, keycap_size - 4, keycap_size - 6)
            pygame.draw.rect(banner_surface, (70, 75, 90, alpha), inner_rect, border_radius=int(4 * scale))

            # 키캡 하이라이트 (상단 밝은 선)
            highlight_rect = pygame.Rect(key_x + 3, key_y + 2, keycap_size - 6, int(3 * scale))
            pygame.draw.rect(banner_surface, (120, 125, 140, int(alpha * 0.7)), highlight_rect, border_radius=int(2 * scale))

            # 키캡 테두리
            border_rect = pygame.Rect(key_x, key_y, keycap_size, keycap_size)
            pygame.draw.rect(banner_surface, (50, 55, 70, alpha), border_rect, int(2 * scale), border_radius=int(5 * scale))

            # 키 문자 렌더링
            key_text_surf, key_text_rect = key_font.render(key_char, (230, 235, 245))
            key_text_surf.set_alpha(alpha)
            key_text_x = key_x + (keycap_size - key_text_rect.width) // 2
            key_text_y = key_y + (keycap_size - key_text_rect.height) // 2 - 1
            banner_surface.blit(key_text_surf, (key_text_x, key_text_y))

            current_x += seg_width

    # 미션 아이콘 (왼쪽에 삼각형)
    icon_x = 20
    icon_y = scaled_height // 2
    icon_points = [
        (icon_x, icon_y - 8),
        (icon_x + 12, icon_y),
        (icon_x, icon_y + 8)
    ]
    pygame.draw.polygon(banner_surface, (glow_color_r, glow_color_g, glow_color_b, glow_alpha), icon_points)

    # 화면에 배너 그리기
    banner_rect = banner_surface.get_rect(center=(center_x, center_y))
    target_screen.blit(banner_surface, banner_rect)

