def apply_white_glow(surface, intensity=60):
    """
    Surface 전체에 밝기를 더하는 함수 (BLEND_RGB_ADD 최적화 버전)
    :param surface: pygame.Surface (RGBA)
    :param intensity: 반짝임 밝기 (기본 60)
    """
    if surface.get_width() > 400 or surface.get_height() > 400:
        return
    intensity = max(0, min(255, int(intensity)))
    if intensity == 0:
        return
    # BLEND_RGB_ADD로 한 번에 밝기 추가 - 알파 채널은 보존됨
    surface.fill((intensity, intensity, intensity), special_flags=pygame.BLEND_RGB_ADD)
def draw_stage1_boss_gauge_bar():
    """스테이지 1 보스 필살기 게이지바 - 조선시대 궁궐 스타일"""
    global current_stage, boss_special_gauge, displayed_boss_gauge
    
    if current_stage != 1:
        return
    
    # 보스 필살기 게이지 표시
    max_gauge = 500  # 최대 게이지
    current_gauge = displayed_boss_gauge  # 부드러운 애니메이션을 위해 displayed_boss_gauge 사용
    
    # 게이지바 위치 - 플레이어 게이지바와 같은 크기 (14x100)
    bar_x = WIDTH - 45  # 살짝 왼쪽으로 이동
    bar_y = 50
    bar_width = 14  # 플레이어와 같은 크기
    bar_height = 100  # 플레이어와 같은 크기
    
    # 시간 기반 애니메이션
    time_offset = pygame.time.get_ticks() * 0.001
    
    # 한국 전통 태극문양 상단 (회전 애니메이션)
    taegeuk_x = bar_x + bar_width // 2
    taegeuk_y = bar_y - 20
    taegeuk_radius = 12
    
    # 태극 회전 각도
    rotation_angle = time_offset * 2  # 회전 속도
    
    # 태극 원형 배경 (검은 테두리)
    pygame.draw.circle(SCREEN, (40, 40, 40), (taegeuk_x, taegeuk_y), taegeuk_radius + 1)
    pygame.draw.circle(SCREEN, (240, 240, 240), (taegeuk_x, taegeuk_y), taegeuk_radius)
    
    # 태극 빨간색 반원 (양)
    red_points = []
    for angle in range(0, 181, 5):  # 상반부 반원
        rad = math.radians(angle + math.degrees(rotation_angle))
        x = taegeuk_x + (taegeuk_radius - 1) * math.cos(rad)
        y = taegeuk_y + (taegeuk_radius - 1) * math.sin(rad)
        red_points.append((x, y))
    
    # S자 곡선을 위한 중간점들 추가
    for angle in range(0, 181, 5):
        rad = math.radians(angle + math.degrees(rotation_angle))
        curve_radius = (taegeuk_radius - 1) * (0.3 + 0.4 * math.sin(math.radians(angle)))
        x = taegeuk_x - curve_radius * math.cos(rad)
        y = taegeuk_y + curve_radius * math.sin(rad)
        red_points.append((x, y))
    
    if len(red_points) > 2:
        pygame.draw.polygon(SCREEN, (220, 50, 50), red_points)
    
    # 태극 파란색 반원 (음)
    blue_points = []
    for angle in range(181, 361, 5):  # 하반부 반원
        rad = math.radians(angle + math.degrees(rotation_angle))
        x = taegeuk_x + (taegeuk_radius - 1) * math.cos(rad)
        y = taegeuk_y + (taegeuk_radius - 1) * math.sin(rad)
        blue_points.append((x, y))
    
    # S자 곡선을 위한 중간점들 추가
    for angle in range(181, 361, 5):
        rad = math.radians(angle + math.degrees(rotation_angle))
        curve_radius = (taegeuk_radius - 1) * (0.3 + 0.4 * math.sin(math.radians(angle)))
        x = taegeuk_x - curve_radius * math.cos(rad)
        y = taegeuk_y + curve_radius * math.sin(rad)
        blue_points.append((x, y))
    
    if len(blue_points) > 2:
        pygame.draw.polygon(SCREEN, (50, 50, 220), blue_points)
    
    # 작은 원점들 (양음 표시)
    small_circle_radius = 3
    yang_x = taegeuk_x + int(4 * math.cos(rotation_angle + math.pi/2))
    yang_y = taegeuk_y + int(4 * math.sin(rotation_angle + math.pi/2))
    yin_x = taegeuk_x - int(4 * math.cos(rotation_angle + math.pi/2))
    yin_y = taegeuk_y - int(4 * math.sin(rotation_angle + math.pi/2))
    
    pygame.draw.circle(SCREEN, (50, 50, 220), (yang_x, yang_y), small_circle_radius)  # 양에 음점
    pygame.draw.circle(SCREEN, (220, 50, 50), (yin_x, yin_y), small_circle_radius)   # 음에 양점
    
    # 태극 외곽 흰색 원형 테두리
    pygame.draw.circle(SCREEN, (255, 255, 255), (taegeuk_x, taegeuk_y), taegeuk_radius + 1, 2)
    
    # 조선 궁궐 기둥 스타일 프레임
    # 기둥 상단 (공포)
    pillar_top = [
        (bar_x - 4, bar_y - 2),
        (bar_x + bar_width + 4, bar_y - 2),
        (bar_x + bar_width + 6, bar_y + 5),
        (bar_x + bar_width + 2, bar_y + 8),
        (bar_x - 2, bar_y + 8),
        (bar_x - 6, bar_y + 5)
    ]
    pygame.draw.polygon(SCREEN, (160, 100, 40), pillar_top)
    pygame.draw.polygon(SCREEN, (100, 60, 20), pillar_top, 2)
    
    # 기둥 하단 (공포)
    pillar_bottom = [
        (bar_x - 2, bar_y + bar_height - 8),
        (bar_x + bar_width + 2, bar_y + bar_height - 8),
        (bar_x + bar_width + 6, bar_y + bar_height - 5),
        (bar_x + bar_width + 4, bar_y + bar_height + 2),
        (bar_x - 4, bar_y + bar_height + 2),
        (bar_x - 6, bar_y + bar_height - 5)
    ]
    pygame.draw.polygon(SCREEN, (160, 100, 40), pillar_bottom)
    pygame.draw.polygon(SCREEN, (100, 60, 20), pillar_bottom, 2)
    
    # 메인 기둥 몸체 (검은색 배경 - 깔끔한 단색)
    main_pillar = pygame.Rect(bar_x, bar_y, bar_width, bar_height)
    pygame.draw.rect(SCREEN, (25, 25, 25), main_pillar)  # 검은색 배경
    pygame.draw.rect(SCREEN, (140, 100, 60), main_pillar, 1)  # 황금 테두리
    
    # 필살기 게이지 채우기 (깔끔한 황금 스타일)
    if current_gauge > 0:
        gauge_ratio = min(current_gauge / max_gauge, 1.0)
        filled_height = int(bar_height * gauge_ratio)
        
        # 깔끔한 황금 색상 (단순화)
        if gauge_ratio > 0.8:
            gauge_color = (240, 200, 80)    # 밝은 황금
        elif gauge_ratio > 0.6:
            gauge_color = (220, 180, 60)    # 중간 황금
        elif gauge_ratio > 0.3:
            gauge_color = (200, 160, 40)    # 어두운 황금
        else:
            gauge_color = (180, 140, 30)    # 갈색 황금
        
        # 게이지 채우기 (아래에서 위로, 깔끔한 단색)
        gauge_start_y = bar_y + bar_height - filled_height
        gauge_rect = pygame.Rect(bar_x + 1, gauge_start_y, bar_width - 2, filled_height)
        pygame.draw.rect(SCREEN, gauge_color, gauge_rect)
        
        # 부드러운 상단 그라데이션 (3픽셀만)
        if filled_height > 3:
            for i in range(3):
                brightness = 1.0 + (0.3 * (2 - i) / 2)  # 위로 갈수록 밝게
                bright_color = tuple(min(255, int(c * brightness)) for c in gauge_color)
                pygame.draw.line(SCREEN, bright_color, 
                               (bar_x + 1, gauge_start_y + i), 
                               (bar_x + bar_width - 1, gauge_start_y + i))
        
        # 상단 하이라이트 (펄스 효과 최소화)
        if filled_height > 1:
            glow_intensity = abs(math.sin(time_offset * 2)) * 0.2 + 0.8
            highlight_color = tuple(min(255, int(c * glow_intensity)) for c in (255, 240, 150))
            pygame.draw.line(SCREEN, highlight_color, 
                           (bar_x + 1, gauge_start_y), 
                           (bar_x + bar_width - 1, gauge_start_y), 1)
        
        # 충전 중일 때 반짝임 효과 (부드러운 애니메이션)
        if boss_special_gauge > displayed_boss_gauge:  # 충전 중
            charge_intensity = min((boss_special_gauge - displayed_boss_gauge) / 50, 1.0)
            sparkle_count = int(charge_intensity * 2) + 1
            
            for i in range(sparkle_count):
                # 범위 검사를 통해 빈 범위 오류 방지
                min_y = gauge_start_y
                max_y = bar_y + bar_height - 2
                if max_y <= min_y:
                    sparkle_y = min_y  # 범위가 없을 때는 시작점 사용
                else:
                    sparkle_y = random.randint(min_y, max_y)
                
                # X축도 동일하게 범위 검사
                if bar_width <= 4:
                    sparkle_x = bar_x + bar_width // 2  # 너비가 너무 작을 때는 중앙 사용
                else:
                    sparkle_x = bar_x + random.randint(2, bar_width - 2)
                
                sparkle_alpha = int(charge_intensity * 150)
                pygame.draw.circle(SCREEN, (255, 255, 200), (sparkle_x, sparkle_y), 1)

        # 웨이브 애니메이션 효과 (상단)
        if filled_height > 5:
            wave_offset = math.sin(time_offset * 4) * 1.5
            wave_y = gauge_start_y + int(wave_offset)
            
            # 부드러운 웨이브 라인
            wave_brightness = abs(math.sin(time_offset * 3)) * 0.3 + 0.7
            wave_color = tuple(min(255, int(c * wave_brightness * 1.2)) for c in gauge_color)
            
            pygame.draw.line(SCREEN, wave_color, 
                           (bar_x + 1, wave_y), 
                           (bar_x + bar_width - 1, wave_y), 1)
    
    # 조선 전통 장식 요소
    # 좌우 단청 장식선
    for offset in [-3, bar_width + 3]:
        x_pos = bar_x + offset
        # 빨강 장식선
        pygame.draw.line(SCREEN, (180, 60, 40), 
                        (x_pos, bar_y + 10), (x_pos, bar_y + 30), 2)
        # 파랑 장식선  
        pygame.draw.line(SCREEN, (40, 80, 160), 
                        (x_pos, bar_y + 35), (x_pos, bar_y + 55), 2)
        # 초록 장식선
        pygame.draw.line(SCREEN, (60, 140, 80), 
                        (x_pos, bar_y + 60), (x_pos, bar_y + 80), 2)
    
    # 왕실 문양 하단 (봉황 깃털)
    feather_x = bar_x + bar_width // 2
    feather_y = bar_y + bar_height + 15
    feather_colors = [(220, 180, 50), (180, 60, 40), (40, 80, 160)]
    
    for i, color in enumerate(feather_colors):
        feather_offset = int(3 * math.sin(time_offset * 2 + i))
        pygame.draw.line(SCREEN, color, 
                        (feather_x + i * 2 - 2, feather_y), 
                        (feather_x + i * 2 - 2 + feather_offset, feather_y - 6), 2)
    
    
    # 게이지 수치 표시 (한문 느낌)
    gauge_font = FontStyle.tiny()
    gauge_text = f"{int(current_gauge)}/{max_gauge}"
    gauge_surface = gauge_font.render(gauge_text, True, (100, 60, 20))
    gauge_rect = gauge_surface.get_rect(centerx=bar_x + bar_width // 2, top=bar_y + bar_height + 25)
    SCREEN.blit(gauge_surface, gauge_rect)


stage7_gauge_debug_active = False
stage7_gauge_debug_last_log = 0
stage7_gauge_debug_last_stage = None
stage7_gauge_debug_stage_log_ticks = 0
# Stage7 디버그 플래그 일원화
STAGE7_DEBUG = {
    'GAUGE': False,  # 게이지 로그 출력
    'HUD': False,    # 화면 HUD 표시
}
try:
    import os
    if os.getenv('PINGF_STAGE7_GAUGE') == '1':
        STAGE7_DEBUG['GAUGE'] = True
    if os.getenv('PINGF_STAGE7_HUD') == '1':
        STAGE7_DEBUG['HUD'] = True
except Exception:
    pass


def reset_stage7_guard_state(*, reset_timer: bool = True) -> None:
    """Stage 7 가드 스킬 상태 초기화."""
    global stage7_guard_blocks, stage7_guard_next_trigger_ms
    stage7_guard_blocks.clear()
    if reset_timer:
        stage7_guard_next_trigger_ms = 0
        try:
            if current_stage != 7:
                global stage7_persistent_boss_gauge
                stage7_persistent_boss_gauge = 0.0
                if STAGE7_DEBUG.get('GAUGE', False):
                    pass  # print("[Stage7Gauge][ResetGuard] stage != 7 → persistent cleared")
        except NameError:
            pass


def initialize_stage7_guard_state(now: int | None = None) -> None:
    """스테이지 7 시작 또는 라운드 리셋 시 가드 스킬 초기화."""
    global stage7_guard_next_trigger_ms, stage7_gauge_charge_progress, stage7_gauge_last_update_ms
    if now is None:
        now = pygame.time.get_ticks()
    reset_stage7_guard_state(reset_timer=False)
    stage7_guard_next_trigger_ms = now + random.randint(STAGE7_GUARD_MIN_INTERVAL_MS, STAGE7_GUARD_MAX_INTERVAL_MS)
    stage7_gauge_charge_progress = 0.0
    stage7_gauge_last_update_ms = now
    global stage7_persistent_boss_gauge
    stage7_persistent_boss_gauge = boss_special_gauge
    if STAGE7_DEBUG.get('GAUGE', False):
        pass  # print(f"[Stage7Gauge][Init] persistent set to {stage7_persistent_boss_gauge}")


def update_stage7_gauge_charge(is_active: bool) -> None:
    """Stage 7 보스 게이지를 초당 25씩 자동 충전한다.
    광폭화 모드: 초인테트리서 발동 중에도 충전 계속 (드레인 없이 충전만)."""
    global stage7_gauge_last_update_ms, stage7_gauge_charge_progress, boss_special_gauge

    now = pygame.time.get_ticks()

    # 광폭화 모드 체크
    is_berserk = enraged_boss_active and current_stage == 7

    # TAB/ESC 등으로 UI가 정지된 동안에는 게이지 충전/감소를 모두 멈춘다.
    if _is_stage7_ui_paused():
        stage7_gauge_last_update_ms = now
        stage7_gauge_charge_progress = 0.0
        return

    # 초인테트리서 발동 중에는 충전을 정지 (드레인만 수행)
    # 단, 광폭화 모드에서는 초인테트리서 중에도 충전 계속!
    if stage7_super_active and not is_berserk:
        stage7_gauge_last_update_ms = now
        stage7_gauge_charge_progress = 0.0
        return

    if not is_active:
        stage7_gauge_last_update_ms = now
        stage7_gauge_charge_progress = 0.0
        return

    if stage7_gauge_last_update_ms == 0:
        stage7_gauge_last_update_ms = now
        return

    elapsed_ms = now - stage7_gauge_last_update_ms
    if elapsed_ms <= 0:
        return

    stage7_gauge_last_update_ms = now

    # 게이지 500 상한 (광폭화/일반 모두 동일)
    if boss_special_gauge >= 500:
        boss_special_gauge = 500
        stage7_gauge_charge_progress = 0.0
        return

    stage7_gauge_charge_progress += elapsed_ms * 0.025  # (ms / 1000) * 25
    charge_units = int(stage7_gauge_charge_progress)

    if charge_units <= 0:
        return

    # 500 상한으로 충전
    boss_special_gauge = min(500, boss_special_gauge + charge_units)
    stage7_gauge_charge_progress -= charge_units
    global stage7_persistent_boss_gauge
    stage7_persistent_boss_gauge = boss_special_gauge
    if STAGE7_DEBUG.get('GAUGE', False):
        mode_str = "🔥광폭화" if is_berserk else ""
        # print(f"[Stage7Gauge][Charge]{mode_str} +{charge_units} → {boss_special_gauge}")


STAGE7_GUARD_CELL_SIZE = 20
STAGE7_GUARD_GAP_Y = 40
STAGE7_GUARD_SPAWN_OFFSET_X = 90
STAGE7_GUARD_HOLOGRAM_STEP_MS = 120
STAGE7_GUARD_MOVEMENT_DURATION_MS = 320
STAGE7_GUARD_HOLOGRAM_HOLD_MS = 160

# 조립(한 조각씩) 애니메이션 – ㅗ 블럭과 동일 컨셉
STAGE7_GUARD_ASSEMBLY_TOTAL_MS = 1000
STAGE7_GUARD_ASSEMBLY_STEP_MS = 250
STAGE7_GUARD_ASSEMBLY_MOVE_MS = 200


def _schedule_stage7_guard(now: int | None = None) -> None:
    global stage7_guard_next_trigger_ms
    if now is None:
        now = pygame.time.get_ticks()
    stage7_guard_next_trigger_ms = now + random.randint(STAGE7_GUARD_MIN_INTERVAL_MS, STAGE7_GUARD_MAX_INTERVAL_MS)


def _create_stage7_guard_block(label: str, start_left: float, final_left: float, top: float, now: int) -> dict:
    cell_size = STAGE7_GUARD_CELL_SIZE
    cells: list[dict] = []
    for i in range(4):
        start = start_left + i * cell_size
        final = final_left + i * cell_size
        rect = pygame.Rect(int(round(start)), int(round(top)), cell_size, cell_size)
        cells.append({
            "rect": rect,
            "start_left": float(start),
            "final_left": float(final),
            "top": float(top),
        })
    return {
        "side": label,
        "state": "hologram",
        "visible_cells": 0,
        "hologram_timer": 0.0,
        "hologram_hold": 0.0,
        "move_timer": 0.0,
        "cells": cells,
        "last_update": now,
        "golden": True if random.random() < 0.03 else False,
        "golden_seed": random.randint(0, 1000),
    }


def spawn_stage7_guard_blocks(now: int | None = None) -> bool:
    global stage7_guard_blocks, boss_special_gauge, stage7_persistent_boss_gauge
    if now is None:
        now = pygame.time.get_ticks()

    if BOSS is None:
        return False

    # 1) 가로 블럭(4셀 가로) 개수가 4개 이상이면 발동 금지
    active_horizontal = sum(1 for b in stage7_guard_blocks if b.get("state") in ("assembling", "hologram", "deploy", "active"))
    if active_horizontal >= 4:
        return False

    # 현재 상황에서 추가로 배치 가능한 개수(최대 2)
    allowed_to_spawn = min(4 - active_horizontal, 2)
    if allowed_to_spawn <= 0:
        return False

    # 필요 게이지: 블록 1개면 50, 2개면 100
    required_gauge = 50 if allowed_to_spawn == 1 else 100
    if boss_special_gauge < required_gauge:
        return False

    cell_size = STAGE7_GUARD_CELL_SIZE
    center = float(BOSS.centerx)
    base_top = float(max(12.0, BOSS.top - cell_size - 8))

    left_start_base = center - cell_size * 4
    right_start_base = center
    left_final_base = max(12.0, BOSS.left - cell_size * 4 - 6)
    right_final_base = min(float(WIDTH - cell_size * 4 - 12), BOSS.right + 6)

    # 도우미: 새로 배치하려는 두 블록(좌/우)의 '최종' 셀 렉트 목록 생성
    def _build_final_cells(block_top: float) -> tuple[list[pygame.Rect], list[pygame.Rect]]:
        left_cells = []
        right_cells = []
        for i in range(4):
            lx = int(round(left_final_base + i * cell_size))
            rx = int(round(right_final_base + i * cell_size))
            ty = int(round(block_top))
            left_cells.append(pygame.Rect(lx, ty, cell_size, cell_size))
            right_cells.append(pygame.Rect(rx, ty, cell_size, cell_size))
        return left_cells, right_cells

    # 도우미: 기존 블록의 '최종' 셀 렉트 수집 (겹침 금지 판단용)
    def _collect_existing_final_cells() -> list[pygame.Rect]:
        rects: list[pygame.Rect] = []
        for b in stage7_guard_blocks:
            if b.get("state") not in ("assembling", "hologram", "deploy", "active"):
                continue
            for c in b.get("cells", []):
                fx = int(round(c.get("final_left", c["rect"].x)))
                fy = int(round(c.get("top", c["rect"].y)))
                rects.append(pygame.Rect(fx, fy, cell_size, cell_size))
        return rects

    existing_final = _collect_existing_final_cells()

    # 2) 겹치지 않게 설치: 위쪽으로 층을 올려 최대 4개 층까지 후보 탐색
    candidates: list[float] = []
    for n in range(4):
        t = base_top - n * max(12.0, float(STAGE7_GUARD_GAP_Y))
        if t >= 12.0:
            candidates.append(t)
    chosen_top: float | None = None
    chosen_sides: list[str] = []  # 'left'/'right'
    # 최종 정착 위치 계산 시, 해당 자리에 블럭이 있으면 약간 더 멀리로 밀어서 회피
    def _nudge_cells(cells: list[pygame.Rect], *, direction: str) -> list[pygame.Rect]:
        # direction: 'right'는 +x로, 'left'는 -x로 셀 크기 간격만큼 최대 3칸까지 이동
        max_shift = 3
        for k in range(max_shift + 1):
            if k == 0:
                test = cells
            else:
                dx = (cell_size * k) if direction == 'right' else (-cell_size * k)
                test = [r.move(dx, 0) for r in cells]
            # 경계 검사
            if any(r.left < 12 or r.right > WIDTH - 12 for r in test):
                continue
            # 기존과 겹침 검사
            if not any(any(rc.colliderect(nc) for nc in test) for rc in existing_final):
                return test
        return None  # 실패

    for t in candidates:
        left_cells, right_cells = _build_final_cells(t)
        settled_left = _nudge_cells(left_cells, direction='left')
        settled_right = _nudge_cells(right_cells, direction='right')
        sides = []
        if settled_right is not None:
            sides.append('right')
        if settled_left is not None:
            sides.append('left')
        if allowed_to_spawn == 2 and len(sides) == 2:
            chosen_top = t
            chosen_sides = ['right', 'left']
            # 선택된 셀 리스트를 저장해 놓는다
            chosen_right_cells = settled_right
            chosen_left_cells = settled_left
            break
        if allowed_to_spawn == 1 and len(sides) >= 1:
            chosen_top = t
            if 'right' in sides:
                chosen_sides = ['right']
                chosen_right_cells = settled_right
                chosen_left_cells = None
            else:
                chosen_sides = ['left']
                chosen_left_cells = settled_left
                chosen_right_cells = None
            break

    if chosen_top is None:
        # 배치할 수 있는 자리가 없으면 실패 (게이지 소모 없음)
        return False

    # 3) 최종 배치가 확정되었으므로 게이지 차감 후 실제 블록 생성 (블록수에 따라 50/100)
    boss_special_gauge = max(0, boss_special_gauge - required_gauge)
    stage7_persistent_boss_gauge = boss_special_gauge
    if STAGE7_DEBUG.get('GAUGE', False):
        pass  # print(f"[Stage7Gauge][Spawn] cost {required_gauge} → {boss_special_gauge}")

    block_top = chosen_top

    new_blocks: list[dict] = []
    # 조립은 보스 패들 옆에서 시작 → 셀 assemble_left를 패들 옆으로 잡고, spread 단계에서 최종 위치로 이동
    if 'right' in chosen_sides:
        # assemble 위치: 보스 오른쪽 붙어서 시작
        right_assemble_start = BOSS.right + 6
        # 최종 위치: chosen_right_cells 기준으로 설정
        right_block = _create_stage7_guard_block("right", right_assemble_start, right_assemble_start, block_top, now)
        # 각 셀의 최종 left를 chosen_right_cells로 갱신
        for i, c in enumerate(right_block["cells"]):
            c["assemble_left"] = float(right_assemble_start + i * cell_size)
            c["final_left"] = float(chosen_right_cells[i].x)
        new_blocks.append(right_block)
    if 'left' in chosen_sides and (allowed_to_spawn >= 2 or active_horizontal == 3):
        # assemble 위치: 보스 왼쪽 붙어서 시작
        left_assemble_start = BOSS.left - (cell_size * 4) - 6
        left_block = _create_stage7_guard_block("left", left_assemble_start, left_assemble_start, block_top, now)
        for i, c in enumerate(left_block["cells"]):
            c["assemble_left"] = float(left_assemble_start + i * cell_size)
            c["final_left"] = float(chosen_left_cells[i].x)
        new_blocks.append(left_block)

    # ㅗ 블럭과 동일한 조립 애니메이션 적용: 1초간 순차 등장 후 자리 고정
    for blk in new_blocks:
        blk["state"] = "assembling"
        blk["assembly_elapsed"] = 0.0
        blk["visible_cells"] = 0
        # 시작 위치를 소폭 랜덤 오프셋으로 조정해 모이는 느낌 강화
        for c in blk["cells"]:
            jitter = random.uniform(-8.0, 8.0)
            # assembling 동안에는 assemble_left로 모이게 하고, spread에서는 final_left로 이동
            start_l = float(c.get("assemble_left", c["rect"].x))
            c["start_left"] = start_l + jitter
            c["rect"].x = int(round(c["start_left"]))

    pass  # print(f"[Stage7Guard] spawn sides={chosen_sides} top={block_top:.1f}")  # 디버그 비활성화

    stage7_guard_blocks.extend(new_blocks)
    return True


def update_stage7_guard_blocks(now: int | None = None) -> None:
    if now is None:
        now = pygame.time.get_ticks()
    if not stage7_guard_blocks:
        return

    cell_size = STAGE7_GUARD_CELL_SIZE
    for block in stage7_guard_blocks[:]:
        elapsed = now - block.get("last_update", now)
        block["last_update"] = now
        if elapsed < 0:
            elapsed = 0

        if block["state"] == "assembling":
            # 1초간 한 조각씩(0.25초 간격) 공개하면서 각 조각은 등장 즉시 목표 위치로 선형 이동
            block["assembly_elapsed"] = block.get("assembly_elapsed", 0.0) + elapsed
            while block.get("visible_cells", 0) < 4 and block["assembly_elapsed"] >= (block["visible_cells"] + 1) * STAGE7_GUARD_ASSEMBLY_STEP_MS:
                block["visible_cells"] = block.get("visible_cells", 0) + 1
            for idx, cell in enumerate(block["cells"]):
                if idx >= block.get("visible_cells", 0):
                    current_left = cell.get("start_left", cell["rect"].x)
                else:
                    appear_t = idx * STAGE7_GUARD_ASSEMBLY_STEP_MS
                    t_since = max(0.0, block["assembly_elapsed"] - appear_t)
                    prog = min(1.0, t_since / STAGE7_GUARD_ASSEMBLY_MOVE_MS)
                    start_left = float(cell.get("start_left", cell["rect"].x))
                    target_left = float(cell.get("assemble_left", start_left))
                    current_left = start_left + (target_left - start_left) * prog
                cell["rect"].x = int(round(current_left))
                cell["rect"].y = int(round(cell.get("top", cell["rect"].y)))
                cell.pop("fade", None)
            if block["assembly_elapsed"] >= STAGE7_GUARD_ASSEMBLY_TOTAL_MS:
                # 조립 완료 → 벌어지기(spread) 단계로 전환
                for cell in block["cells"]:
                    # spread용 시작점 업데이트
                    cell["rect"].x = int(round(cell.get("assemble_left", cell["rect"].x)))
                    cell["rect"].y = int(round(cell.get("top", cell["rect"].y)))
                    cell["start_left"] = float(cell["rect"].x)
                block["state"] = "spread"
                block["move_timer"] = 0.0
        elif block["state"] == "hologram":
            # 홀로그램 단계: 셀을 순차적으로 드러낸 뒤, 전부 드러난 상태로 일정 시간 유지하고 배치 단계로 전환
            block["hologram_timer"] += elapsed
            while block["visible_cells"] < 4 and block["hologram_timer"] >= STAGE7_GUARD_HOLOGRAM_STEP_MS:
                block["hologram_timer"] -= STAGE7_GUARD_HOLOGRAM_STEP_MS
                block["visible_cells"] += 1
            # BUGFIX: 기존 코드가 hold 누적을 while 내부에서만 수행해, 마지막 셀 노출 이후 유지 시간이 누적되지 않는 문제 수정
            if block["visible_cells"] >= 4:
                block["hologram_hold"] += elapsed
                if block["hologram_hold"] >= STAGE7_GUARD_HOLOGRAM_HOLD_MS:
                    block["state"] = "deploy"
                    block["move_timer"] = 0.0
            for cell in block["cells"]:
                cell.pop("fade", None)
        elif block["state"] == "deploy":
            block["move_timer"] += elapsed
            progress = min(1.0, block["move_timer"] / STAGE7_GUARD_MOVEMENT_DURATION_MS)
            for cell in block["cells"]:
                start_left = cell["start_left"]
                final_left = cell["final_left"]
                current_left = start_left + (final_left - start_left) * progress
                cell["rect"].x = int(round(current_left))
                cell["rect"].y = int(round(cell["top"]))
                cell.pop("fade", None)
            if progress >= 1.0:
                block["state"] = "active"
        elif block["state"] == "spread":
            block["move_timer"] += elapsed
            progress = min(1.0, block["move_timer"] / STAGE7_GUARD_MOVEMENT_DURATION_MS)
            for cell in block["cells"]:
                start_left = float(cell.get("start_left", cell["rect"].x))
                final_left = float(cell.get("final_left", cell["rect"].x))
                current_left = start_left + (final_left - start_left) * progress
                cell["rect"].x = int(round(current_left))
                cell["rect"].y = int(round(cell["top"]))
                cell.pop("fade", None)
            if progress >= 1.0:
                block["state"] = "active"
        elif block["state"] == "active":
            for cell in block["cells"]:
                cell["rect"].x = int(round(cell["final_left"]))
                cell["rect"].y = int(round(cell["top"]))
                cell.pop("fade", None)
        elif block["state"] == "destroying":
            block["destroy_timer"] -= elapsed
            fade = max(0.0, block.get("destroy_timer", 0.0) / max(1.0, block.get("destroy_duration", 1.0)))
            for cell in block["cells"]:
                cell["rect"].x = int(round(cell["final_left"]))
                cell["rect"].y = int(round(cell["top"]))
                cell["fade"] = fade
            if block["destroy_timer"] <= 0:
                # 파괴 완료 → 리스트에서 제거
                try:
                    if block.get("golden"):
                        xs = [c["rect"].centerx for c in block.get("cells", []) if c.get("rect")]
                        ys = [c["rect"].centery for c in block.get("cells", []) if c.get("rect")]
                        if xs and ys:
                            cx = int(sum(xs) / len(xs))
                            cy = int(sum(ys) / len(ys))
                            tps = trade_point_system
                            if tps is not None and hasattr(tps, "spawn_star"):
                                tps.spawn_star(cx, cy, "rainbow_tetro")
                except Exception:
                    pass
                stage7_guard_blocks.remove(block)
                # 플레이어가 파괴했고, 남은 활성 블록(assembling/hologram/deploy/active)이 3개 이하라면 즉시 재스폰 예약
                remaining_active = sum(1 for b in stage7_guard_blocks if b.get("state") in ("assembling", "hologram", "deploy", "active"))
                if block.get("destroy_reason") == "player" and remaining_active <= 3:
                    globals()['stage7_guard_next_trigger_ms'] = now
                # 전부 사라진 경우도 안전하게 스케줄
                if not stage7_guard_blocks:
                    _schedule_stage7_guard(now)


def draw_stage7_guard_blocks(surface: pygame.Surface) -> None:
    if not stage7_guard_blocks:
        return

    base_color_default = (90, 190, 255)
    highlight_color_default = (200, 240, 255)
    hologram_color_default = (140, 200, 255)
    border_color_default = (30, 90, 160)

    for block in stage7_guard_blocks:
        state = block.get("state")
        # 황금 블럭 색상 적용
        if block.get("golden"):
            try:
                seed = int(block.get("golden_seed", 0))
                t = (pygame.time.get_ticks() + seed) * 0.006
                r = int(128 + 127 * math.sin(t))
                g = int(128 + 127 * math.sin(t + 2.094))
                b = int(128 + 127 * math.sin(t + 4.188))
                base_color = (_clamp(r), _clamp(g), _clamp(b)) if ' _clamp' in locals() else (max(0,min(255,r)), max(0,min(255,g)), max(0,min(255,b)))
            except Exception:
                base_color = (200, 200, 255)
            # 파생 색상(라이트/홀로그램/보더)
            highlight_color = (min(255, base_color[0] + 25), min(255, base_color[1] + 25), min(255, base_color[2] + 25))
            hologram_color = (min(255, base_color[0] + 10), min(255, base_color[1] + 10), min(255, base_color[2] + 10))
            border_color = (max(0, base_color[0] - 90), max(0, base_color[1] - 90), max(0, base_color[2] - 90))
        else:
            base_color = base_color_default
            highlight_color = highlight_color_default
            hologram_color = hologram_color_default
            border_color = border_color_default
        # 황금 번쩍(스테이지2 황금 바위 느낌) 펄스
        try:
            if block.get("golden"):
                seed = int(block.get("golden_seed", 0))
                t = (pygame.time.get_ticks() + seed) * 0.016
                pulse = 0.6 + 0.4 * math.sin(t * 0.35)
                boost = int(35 * pulse)
                base_color = (min(255, base_color[0] + boost), min(255, base_color[1] + int(boost * 0.6)), max(0, base_color[2] - int(boost * 0.35)))
                highlight_color = (min(255, highlight_color[0] + boost), min(255, highlight_color[1] + int(boost * 0.7)), highlight_color[2])
        except Exception:
            pass
        visible_cells = block.get("visible_cells", 0)
        for idx, cell in enumerate(block["cells"]):
            rect = cell["rect"]
            fade = cell.get("fade", 1.0)
            if state == "assembling" and idx >= visible_cells:
                # 조립 중 아직 공개되지 않은 셀은 표시하지 않음
                continue
            if state == "hologram" and idx >= visible_cells:
                alpha = 110
                fill_col = hologram_color
                border_alpha = 180
            elif state == "destroying":
                alpha = int(220 * fade)
                fill_col = highlight_color
                border_alpha = int(200 * fade)
            else:
                alpha = 230 if state == "active" else 200
                fill_col = base_color
                border_alpha = 255

            # 캐시된 임시 Surface 사용으로 할당/GC 부하 경감
            try:
                temp = _stage7_get_temp_surface(_stage7_cache_cell, (rect.width, rect.height))
            except Exception:
                temp = pygame.Surface((rect.width, rect.height), pygame.SRCALPHA)
            pygame.draw.rect(temp, (*fill_col, alpha), temp.get_rect(), border_radius=4)
            pygame.draw.rect(temp, (*highlight_color, min(255, alpha + 25)), temp.get_rect().inflate(-4, -4), border_radius=3)
            pygame.draw.rect(temp, (*border_color, border_alpha), temp.get_rect(), 2, border_radius=4)
            surface.blit(temp, rect.topleft)
            # 황금 십자 글린트
            if block.get("golden") and idx == 0:
                try:
                    try:
                        glint = _stage7_get_temp_surface(_stage7_cache_glint, (rect.width, rect.height))
                    except Exception:
                        glint = pygame.Surface((rect.width, rect.height), pygame.SRCALPHA)
                    seed = int(block.get("golden_seed", 0))
                    glow_alpha = int(70 + 65 * abs(math.sin((pygame.time.get_ticks() + seed) * 0.01)))
                    pygame.draw.rect(glint, (255, 245, 140, glow_alpha), (rect.width//2 - 1, 0, 2, rect.height))
                    pygame.draw.rect(glint, (255, 245, 140, glow_alpha), (0, rect.height//2 - 1, rect.width, 2))
                    surface.blit(glint, rect.topleft, special_flags=pygame.BLEND_ADD)
                    # 대각 쉬머
                    shift = int(((pygame.time.get_ticks() + seed) * 0.05) % (rect.width + rect.height))
                    try:
                        shimmer = _stage7_get_temp_surface(_stage7_cache_shimmer, (rect.width, rect.height))
                    except Exception:
                        shimmer = pygame.Surface((rect.width, rect.height), pygame.SRCALPHA)
                    c = (255, 255, 200, 85)
                    pygame.draw.line(shimmer, c, (max(0, shift - rect.height), 0), (min(rect.width, shift), min(rect.height, shift)), 2)
                    pygame.draw.line(shimmer, c, (max(0, shift - rect.height) - 5, 0), (min(rect.width, shift - 5), min(rect.height, shift - 5)), 2)
                    surface.blit(shimmer, rect.topleft, special_flags=pygame.BLEND_ADD)
                except Exception:
                    pass


def update_stage7_guard_skill(now: int | None = None) -> None:
    global stage7_guard_next_trigger_ms

    if current_stage != 7 or new_boss_mode_active:
        return

    if now is None:
        now = pygame.time.get_ticks()

    # UI 정지 상태에서는 스킬 업데이트 중단
    if _is_stage7_ui_paused():
        return

    update_stage7_guard_blocks(now)
    enforce_player_blocking_by_installed_tetro()

    # 변경 사항: 활성 블록이 남아 있어도 쿨타임 도달 시 추가 생성 허용.
    # 다만 설치/파괴 중(홀로그램/배치 이동/파괴 애니메이션)일 때는 중복 연출 충돌을 피하기 위해 대기.
    installing_or_destroying = any(
        block.get("state") in ("assembling", "spread", "hologram", "deploy", "destroying") for block in stage7_guard_blocks
    )
    if installing_or_destroying:
        return

    if stage7_guard_next_trigger_ms == 0:
        _schedule_stage7_guard(now)

    if now < stage7_guard_next_trigger_ms:
        return

    # 테트로미노 스킬이 게이지를 예약 중이면, 테트로미노가 쓸 50을 먼저 확보하도록 가드 스폰을 잠시 보류
    if stage7_tetro_reserve and boss_special_gauge < STAGE7_TETRO_GAUGE_COST:
        # 0.5초 뒤 재확인
        stage7_guard_next_trigger_ms = now + 500
        return

    # 트리거 시도 (게이지가 충분하면 기존 블록과 무관하게 추가 생성)
    if spawn_stage7_guard_blocks(now):
        _schedule_stage7_guard(now)
    else:
        # 게이지 부족 등으로 실패 시 재시도까지 짧은 대기
        stage7_guard_next_trigger_ms = now + 1000


# =====================
# Stage 7: 대량 테트로 벽 스킬
# =====================

def reset_stage7_tetro_wall_state(*, reset_timer: bool = True) -> None:
    """Stage 7 대량 테트로 벽 상태 초기화"""
    global stage7_tetro_wall_left, stage7_tetro_wall_right, stage7_tetro_wall_next_trigger_ms
    stage7_tetro_wall_left.clear()
    stage7_tetro_wall_right.clear()
    if reset_timer:
        stage7_tetro_wall_next_trigger_ms = 0
    # 시각용으로 추가했던 벽 테트로(mino) 제거
    try:
        for m in list(stage7_tetrominoes):
            if m.get('wall_generated'):
                stage7_tetrominoes.remove(m)
    except Exception:
        pass


def _tetro_wall_shapes():
    # 기본 테트로미노 셀 좌표 세트
    return {
        'I': [(0,0),(1,0),(2,0),(3,0)],
        'O': [(0,0),(1,0),(0,1),(1,1)],
        'T': [(0,0),(1,0),(2,0),(1,1)],
        'S': [(1,0),(2,0),(0,1),(1,1)],
        'Z': [(0,0),(1,0),(1,1),(2,1)],
        'J': [(0,0),(0,1),(1,1),(2,1)],
        'L': [(2,0),(0,1),(1,1),(2,1)],
    }


def _rotate_cells(cells, times: int):
    pts = cells
    for _ in range(times % 4):
        pts = [(-y, x) for (x, y) in pts]
        min_x = min(p[0] for p in pts)
        min_y = min(p[1] for p in pts)
        pts = [(x - min_x, y - min_y) for (x, y) in pts]
    return pts


def _spawn_tetro_wall_for_side(out_list: list, origin_x: int, origin_bottom_y: int, cols: int, rows: int, tile: int, *, side: str):
    """측면 하나에 테트로 10개를 쌓고, 시각용 mino(dict)도 반환.
    - out_list에는 즉시 충돌 rect를 넣지 않음(조립 완료 후 설치 단계에서 추가)
    - side: 'left' 또는 'right'
    """
    occupied = set()
    shapes = _tetro_wall_shapes()
    # 공용 스펙(레거시 호환)에서 개수 참조; 실패 시 10 유지
    try:
        from game_logic.stage7_tetriser import get_tetro_wall_spawn_spec_legacy
        spec = get_tetro_wall_spawn_spec_legacy(width=WIDTH, height=HEIGHT)
        pieces = int(spec.get('pieces_per_side', 10))
    except Exception:
        pieces = 10
    now = pygame.time.get_ticks()
    minos = []
    for _ in range(pieces):
        shape_name = random.choice(list(shapes.keys()))
        base = shapes[shape_name]
        cells = _rotate_cells(base, random.randint(0, 3))
        max_cx = max(c[0] for c in cells)
        max_cy = max(c[1] for c in cells)
        width_cells = max_cx + 1
        start_col = random.randint(0, max(0, cols - width_cells))

        row = 0
        while True:
            blocked = False
            for (cx, cy) in cells:
                nx = start_col + cx
                ny = row + cy + 1
                if ny >= rows or (nx, ny) in occupied:
                    blocked = True
                    break
            if blocked:
                break
            row += 1
            if row + max_cy >= rows - 1:
                break

        cell_rects = []
        for (cx, cy) in cells:
            col = start_col + cx
            r = row + cy
            occupied.add((col, r))
            final_left = float(origin_x + col * tile)
            final_top = float(origin_bottom_y - r * tile - tile)
            # 조립 연출: 최종 위치 주변에서 살짝 흩어져 있다가 모이는 효과
            start_left = final_left + random.uniform(-8.0, 8.0)
            start_top = final_top + random.uniform(-8.0, 8.0)
            rect = pygame.Rect(int(round(start_left)), int(round(start_top)), tile, tile)
            cell_rects.append({
                'rect': rect,
                'start_left': start_left,
                'start_top': start_top,
                'final_left': final_left,
                'final_top': final_top,
            })

        # 시각용 테트로(설치 상태) 생성
        minos.append({
            'state': 'assembling',
            'cells': cell_rects,
            'shape': shape_name,
            'visible_cells': 0,
            'assembly_elapsed': 0.0,
            'installed_duration_ms': 6000,
            'pulse_enabled': True,
            'wall_generated': True,  # 벽 스킬이 만든 것임을 표시
            'wall_side': side,
            'last_update': now,
            'golden': True if random.random() < 0.01 else False,
            'golden_seed': random.randint(0, 1000),
        })

    return minos


def spawn_stage7_tetro_walls(now: int | None = None) -> bool:
    """양쪽 벽에 테트로미노 10개씩 쌓아 스폰. 게이지 50 소모."""
    global boss_special_gauge
    if current_stage != 7:
        return False
    if now is None:
        now = pygame.time.get_ticks()
    # 스펙에서 코스트 참조(레거시 값=50), 실패 시 상수 사용
    try:
        from game_logic.stage7_tetriser import get_tetro_wall_spawn_spec_legacy
        _spec = get_tetro_wall_spawn_spec_legacy(width=WIDTH, height=HEIGHT)
        _cost = int(_spec.get('skill_cost', STAGE7_TETRO_WALL_GAUGE_COST))
    except Exception:
        _cost = STAGE7_TETRO_WALL_GAUGE_COST
    if boss_special_gauge < _cost:
        return False

    # 게이지 차감
    boss_special_gauge = max(0, boss_special_gauge - _cost)

    # 화면/그리드 파라미터
    # 스펙에서 타일/열 참조(레거시 값 유지: tile=20, cols=5)
    try:
        _spec = get_tetro_wall_spawn_spec_legacy(width=WIDTH, height=HEIGHT)  # type: ignore[name-defined]
        tile = int(_spec.get('tile', STAGE7_TETRO_WALL_TILE))
        cols = int(_spec.get('cols', STAGE7_TETRO_WALL_COLS))
    except Exception:
        tile = STAGE7_TETRO_WALL_TILE
        cols = STAGE7_TETRO_WALL_COLS
    grid_w = cols * tile
    rows = max(1, HEIGHT // tile)

    # 기존 벽 제거 후 새로 생성(누적 방지)
    stage7_tetro_wall_left.clear()
    stage7_tetro_wall_right.clear()

    # 테트로 셀 생성 + 시각용 mino 수집
    left_minos = _spawn_tetro_wall_for_side(stage7_tetro_wall_left, 0, HEIGHT - tile, cols, rows, tile, side='left')
    right_minos = _spawn_tetro_wall_for_side(stage7_tetro_wall_right, WIDTH - grid_w, HEIGHT - tile, cols, rows, tile, side='right')
    # 기존 벽 생성물 제거 후 다시 추가(중복 방지)
    try:
        for m in list(stage7_tetrominoes):
            if m.get('wall_generated'):
                stage7_tetrominoes.remove(m)
    except Exception:
        pass
    stage7_tetrominoes.extend(left_minos)
    stage7_tetrominoes.extend(right_minos)
    try:
        _cost_str = str(_cost)
    except Exception:
        _cost_str = str(STAGE7_TETRO_WALL_GAUGE_COST)
    pass  # print(f"[Stage7TetroWall] Spawned L={len(stage7_tetro_wall_left)} R={len(stage7_tetro_wall_right)} cost={_cost_str} gauge→{boss_special_gauge}")  # 디버그 비활성화
    # 소환 사운드 재생
    try:
        if SOUND_TETRISWALL:
            play_sound_with_volume(SOUND_TETRISWALL)
        else:
            # 폴백: 기존 벽 사운드 사용
            play_wall_sound()
    except Exception:
        pass
    return True


def update_stage7_tetro_wall_skill(now: int | None = None) -> None:
    """30초마다 게이지 50 소모로 대량 테트로 벽 소환"""
    global stage7_tetro_wall_next_trigger_ms
    if current_stage != 7:
        return
    if now is None:
        now = pygame.time.get_ticks()

    # UI 정지 상태에서는 스킬 업데이트 중단
    if _is_stage7_ui_paused():
        return

    # 공용 스펙(레거시 호환)에서 간격(sec) 참조; 실패 시 상수 사용
    try:
        from game_logic.stage7_tetriser import get_tetro_wall_spawn_spec_legacy
        _spec = get_tetro_wall_spawn_spec_legacy(width=WIDTH, height=HEIGHT)
        _interval_ms = int(float(_spec.get('interval_sec', STAGE7_TETRO_WALL_INTERVAL_MS / 1000.0)) * 1000)
    except Exception:
        _interval_ms = STAGE7_TETRO_WALL_INTERVAL_MS

    if stage7_tetro_wall_next_trigger_ms == 0:
        stage7_tetro_wall_next_trigger_ms = now + _interval_ms

    if now < stage7_tetro_wall_next_trigger_ms:
        return

    if spawn_stage7_tetro_walls(now):
        stage7_tetro_wall_next_trigger_ms = now + _interval_ms
    else:
        # 게이지 부족 등 → 1초 뒤 재시도
        stage7_tetro_wall_next_trigger_ms = now + 1000


def draw_stage7_tetro_walls(surface: pygame.Surface) -> None:
    if current_stage != 7:
        return
    # 반투명 채움 + 짙은 외곽선으로 가시성 보장
    color_l = (90, 180, 255, 220)
    color_r = (255, 200, 90, 220)
    border = (30, 30, 30)
    for r in stage7_tetro_wall_left:
        try:
            s = _stage7_get_temp_surface(_stage7_cache_cell, (r.width, r.height))
        except Exception:
            s = pygame.Surface((r.width, r.height), pygame.SRCALPHA)
        s.fill(color_l)
        surface.blit(s, r.topleft)
        pygame.draw.rect(surface, border, r, 2)
    for r in stage7_tetro_wall_right:
        try:
            s = _stage7_get_temp_surface(_stage7_cache_cell, (r.width, r.height))
        except Exception:
            s = pygame.Surface((r.width, r.height), pygame.SRCALPHA)
        s.fill(color_r)
        surface.blit(s, r.topleft)
        pygame.draw.rect(surface, border, r, 2)


def _remove_wall_cell_rect(rect: pygame.Rect) -> None:
    """벽 충돌리스트에서 해당 셀 rect를 제거 (양쪽 리스트 모두 시도)."""
    try:
        if rect in stage7_tetro_wall_left:
            stage7_tetro_wall_left.remove(rect)
    except Exception:
        pass
    # 오른쪽 리스트에도 동일하게 존재할 수 있으므로 보수적으로 제거 시도
    try:
        if rect in stage7_tetro_wall_right:
            stage7_tetro_wall_right.remove(rect)
    except Exception:
        pass

def _mark_wall_cell_evaporated(rect: pygame.Rect) -> None:
    """벽 스킬 미노가 공에 맞았을 때: 낙하형과 동일한 해체(증발) 애니메이션을 트리거.

    - 해당 rect를 소유한 wall_generated 미노를 찾아 destroy_stage7_tetromino(by_player=True) 호출
      → 빠른 증발(간격 111ms, 스팀 파티클)로 사라짐.
    - 찾지 못하면 보수적으로 해당 rect만 충돌 리스트에서 제거.
    """
    try:
        for m in stage7_tetrominoes:
            if not m.get('wall_generated'):
                continue
            if any(c.get('rect') is rect for c in m.get('cells', [])):
                # 히트 플래시 부여(짧게 반짝임)
                try:
                    m["hit_flash_duration"] = 130
                    m["hit_flash_until"] = pygame.time.get_ticks() + 130
                except Exception:
                    pass
                # 이미 해체 중이면 중복 호출 방지
                if m.get('state') not in ('destroying', 'evaporating'):
                    destroy_stage7_tetromino(m, by_player=True)
                # 충돌 비활성화를 즉시 보장(애니메이션은 유지)
                try:
                    for c in m.get('cells', []):
                        _remove_wall_cell_rect(c.get('rect'))
                except Exception:
                    pass
                return
    except Exception:
        pass
    # 소유 미노를 찾지 못한 경우: 해당 셀만 제거
    _remove_wall_cell_rect(rect)


def destroy_stage7_guard_block(block: dict, *, now: int | None = None, by_player: bool = False) -> None:
    if block.get("state") == "destroying":
        return
    if now is None:
        now = pygame.time.get_ticks()
    block["state"] = "destroying"
    block["destroy_duration"] = 200
    block["destroy_timer"] = 200
    block["last_update"] = now
    block["visible_cells"] = len(block.get("cells", []))
    block["destroy_reason"] = "player" if by_player else "other"
    # 해체 사운드: 테트로 해체 효과음을 우선 사용, 없으면 기본 벽 사운드
    try:
        if SOUND_TETRISBREAK:
            play_sound_with_volume(SOUND_TETRISBREAK)
        else:
            play_wall_sound()
    except Exception:
        pass


# =====================
# Stage 7: T(ㅗ) 테트로미노 낙하 스킬
# =====================

# 낙하 모션은 테트리스처럼 셀 단위(뚝뚝)로만 이동
STAGE7_TETRO_CELL_SIZE = 20
STAGE7_TETRO_STEP_MS = 110

# 발사 전 조립(모이기) 애니메이션: 1초 동안 셀들이 순차적으로 도착
STAGE7_TETRO_ASSEMBLY_TOTAL_MS = 1000
STAGE7_TETRO_ASSEMBLY_STEP_MS = 250      # 4개의 셀이 0.25초 간격으로 등장 → 총 1초
STAGE7_TETRO_ASSEMBLY_MOVE_MS = 200      # 각 셀이 등장 후 목표 위치까지 이동하는 시간

# =====================
# Stage 7: 중앙 큐브 시스템 (3x3 정사각형 그리드로 표현)
# - 맵 중앙(원형 서클) 내부에 큐브를 표시
# - 공이 원 내부를 '진입'할 때마다 큐브를 무작위로 회전/섞기
# - 큐브의 3x3 칸 색이 모두 일치하면 1초 후 폭발 → 맵의 테트로미노들을 제거(증발)
# - 이후 보스 테트로미노가 공/대쉬로 사라질 때마다 큐브 재조립 진행
# - 5개 증발 시 큐브 완성 → 다시 활성화(새 큐브 생성)
# =====================

# 중앙 큐브 전역 상태
stage7_center_cube_state: dict | None = None

STAGE7_CUBE_RADIUS = 90  # 원형 서클 반지름
STAGE7_CUBE_GRID_SIZE = 3
STAGE7_CUBE_CELL_GAP = 3
STAGE7_CUBE_SOLVE_DELAY_MS = 1000
STAGE7_CUBE_MELT_DURATION_MS = 1000  # 녹는 애니메이션 지속시간 (1초)


def _stage7_init_center_cube(now: int | None = None) -> None:
    """중앙 큐브 상태를 초기화한다 (스테이지7 전용)."""
    if now is None:
        now = pygame.time.get_ticks()
    global stage7_center_cube_state
    # 6면 색상 팔레트(루빅 느낌). 화면 가독성 높은 계열로 선정
    palette = [
        (255, 80, 80),   # R
        (80, 180, 255),  # B
        (255, 200, 60),  # Y
        (80, 230, 120),  # G
        (255, 150, 0),   # O
        (240, 240, 240), # W
    ]
    # 3x3 무작위 색 그리드 생성 (완전 단색 방지)
    grid = [[random.choice(palette) for _ in range(STAGE7_CUBE_GRID_SIZE)] for _ in range(STAGE7_CUBE_GRID_SIZE)]
    # 만약 우연히 단색이면 한 칸 바꿔 단색 해제
    flat = [c for row in grid for c in row]
    if all(c == flat[0] for c in flat):
        i = random.randrange(0, 9)
        r, c = divmod(i, 3)
        grid[r][c] = random.choice([p for p in palette if p != flat[0]])

    stage7_center_cube_state = {
        "active": True,
        "rebuild": False,
        "rebuild_progress": 0,   # 0~5
        "grid": grid,
        "palette": palette,
        "cx": WIDTH // 2,
        "cy": HEIGHT // 2,
        "ball_inside": False,
        "solve_pending": False,
        "solve_at": 0,           # ms
        # 공 통과 횟수에 따른 자발적 정답 유도(게임 진행성을 위해)
        "passes_to_solve": random.randint(10, 14),
        "last_updated": now,
    }


def _stage7_cube_is_uniform(grid: list[list[tuple]]) -> bool:
    base = grid[0][0]
    for r in range(3):
        for c in range(3):
            if grid[r][c] != base:
                return False
    return True


def _stage7_cube_random_rotate(state: dict) -> None:
    """랜덤 회전/섞기: 전체 90도 회전 또는 특정 행/열을 순환 이동."""
    grid = state["grid"]
    mode = random.choice(("rot90", "row", "col"))
    if mode == "rot90":
        # 시계방향 90도 회전
        new_grid = [[grid[2 - c][r] for c in range(3)] for r in range(3)]
        state["grid"] = new_grid
    elif mode == "row":
        r = random.randrange(0, 3)
        shift = random.choice((-1, 1))
        row = grid[r][:]
        state["grid"][r] = row[-shift:] + row[:-shift]
    else:  # col
        c = random.randrange(0, 3)
        col = [grid[r][c] for r in range(3)]
        shift = random.choice((-1, 1))
        col2 = col[-shift:] + col[:-shift]
        for r in range(3):
            grid[r][c] = col2[r]


def _stage7_cube_force_uniform(state: dict) -> None:
    """그리드를 단색으로 맞춘다(연출/진행용)."""
    palette = state.get("palette") or []
    color = random.choice(palette) if palette else (255, 255, 100)
    state["grid"] = [[color for _ in range(3)] for _ in range(3)]


def _stage7_cube_explode_and_clear_tetros(now: int | None = None, *, by_laser: bool = False) -> None:
    """큐브 폭발 연출 및 스테이지7 테트로미노 제거(증발 처리).
    by_laser=True일 경우 녹는 애니메이션 적용."""
    if now is None:
        now = pygame.time.get_ticks()
    global stage7_center_cube_state
    if not stage7_center_cube_state:
        return
    cx = stage7_center_cube_state.get("cx", WIDTH // 2)
    cy = stage7_center_cube_state.get("cy", HEIGHT // 2)

    # 레이저로 녹는 경우: 폭발 대신 녹는 애니메이션
    if by_laser:
        stage7_center_cube_state["melting"] = True
        stage7_center_cube_state["melt_start_ms"] = now
        stage7_center_cube_state["active"] = False
        stage7_center_cube_state["solve_pending"] = False
        stage7_center_cube_state["solve_at"] = 0
        # 테트로미노는 바로 제거
        try:
            if 'stage7_tetrominoes' in globals() and stage7_tetrominoes:
                for mino in list(stage7_tetrominoes):
                    if mino.get("state") not in ("evaporating", "destroying"):
                        destroy_stage7_tetromino(mino, by_smoke=True)
        except Exception:
            pass
        return

    # 일반 폭발: 시각/사운드 + 즉시 재조립 모드
    try:
        trigger_grenade_style_explosion(cx, cy, apply_commando_bonus=False, source="center_cube", radius_scale=1.2)
    except Exception:
        pass
    # 스타포인트 1개 드랍
    try:
        if 'trade_point_system' in globals() and trade_point_system:
            trade_point_system.spawn_star(cx, cy, "stage7_center_cube")
    except Exception:
        pass
    # 모든 테트로미노를 증발 처리 (연막 파괴와 동일한 경로)
    try:
        if 'stage7_tetrominoes' in globals() and stage7_tetrominoes:
            for mino in list(stage7_tetrominoes):
                if mino.get("state") not in ("evaporating", "destroying"):
                    destroy_stage7_tetromino(mino, by_smoke=True)
    except Exception:
        pass
    # 상태 전환: 재조립 모드로
    stage7_center_cube_state["active"] = False
    stage7_center_cube_state["rebuild"] = True
    stage7_center_cube_state["rebuild_progress"] = 0
    stage7_center_cube_state["solve_pending"] = False
    stage7_center_cube_state["solve_at"] = 0


def stage7_cube_notify_tetro_evaporated(reason: str) -> None:
    """테트로미노가 사라졌을 때(공/대쉬) 재조립 진행도를 증가."""
    if current_stage != 7:
        return
    global stage7_center_cube_state
    st = stage7_center_cube_state
    if not st or not st.get("rebuild"):
        return
    if reason not in ("player", "dash"):
        return
    st["rebuild_progress"] = min(5, int(st.get("rebuild_progress", 0)) + 1)
    if st["rebuild_progress"] >= 5:
        # 완성 → 새 큐브 생성
        _stage7_init_center_cube()


def update_stage7_center_cube(now: int | None = None) -> None:
    if current_stage != 7:
        return
    if now is None:
        now = pygame.time.get_ticks()
    global stage7_center_cube_state
    if stage7_center_cube_state is None:
        _stage7_init_center_cube(now)
    st = stage7_center_cube_state
    if not st:
        return
    st["last_updated"] = now

    cx, cy = st.get("cx", WIDTH // 2), st.get("cy", HEIGHT // 2)
    # 공이 원 내부에 있는지 확인
    dx = BALL.centerx - cx
    dy = BALL.centery - cy
    inside = (dx * dx + dy * dy) <= (STAGE7_CUBE_RADIUS * STAGE7_CUBE_RADIUS)
    # 진입 에지에서만 동작
    if inside and not st.get("ball_inside", False) and st.get("active", False):
        _stage7_cube_random_rotate(st)
        # 진행성 보장: 몇 번 진입하면 강제 단색
        passes_to_solve = max(0, int(st.get("passes_to_solve", 0)) - 1)
        st["passes_to_solve"] = passes_to_solve
        if passes_to_solve == 0:
            _stage7_cube_force_uniform(st)
        # 일치 판정
        if _stage7_cube_is_uniform(st["grid"]) and not st.get("solve_pending", False):
            st["solve_pending"] = True
            st["solve_at"] = now + STAGE7_CUBE_SOLVE_DELAY_MS
    st["ball_inside"] = inside

    # 폭발 예약 처리
    if st.get("solve_pending") and now >= int(st.get("solve_at", 0)):
        _stage7_cube_explode_and_clear_tetros(now)

    # 녹는 애니메이션 완료 체크
    if st.get("melting"):
        melt_start = st.get("melt_start_ms", now)
        melt_elapsed = now - melt_start
        if melt_elapsed >= STAGE7_CUBE_MELT_DURATION_MS:
            # 녹기 완료 → 재조립 모드로 전환
            st["melting"] = False
            st["rebuild"] = True
            st["rebuild_progress"] = 0
            # 스타포인트 드랍 (녹은 후)
            try:
                if 'trade_point_system' in globals() and trade_point_system:
                    trade_point_system.spawn_star(cx, cy, "stage7_center_cube_melt")
            except Exception:
                pass


def draw_stage7_center_cube(surface: pygame.Surface) -> None:
    if current_stage != 7:
        return
    st = stage7_center_cube_state
    if not st:
        return

    # 녹는 중일 때는 큐브를 그리지 않고 녹는 효과만 표시
    now = pygame.time.get_ticks()
    melting = st.get("melting", False)
    melt_progress = 0.0
    if melting:
        melt_start = st.get("melt_start_ms", now)
        melt_progress = min(1.0, (now - melt_start) / STAGE7_CUBE_MELT_DURATION_MS)

    cx, cy = st.get("cx", WIDTH // 2), st.get("cy", HEIGHT // 2)
    # 중앙 원(경계) 표시 — 캐시된 링 Surface 사용
    # 캐시: (radius, thickness, color)별 1회 생성 후 재사용
    try:
        _center_ring_cache
    except NameError:
        _center_ring_cache = {}

    def _get_center_ring(radius: int, color: tuple, thickness: int = 2) -> pygame.Surface:
        key = (int(radius), int(thickness), tuple(color))
        surf = _center_ring_cache.get(key)  # type: ignore[name-defined]
        if surf is None:
            size = int((radius + thickness) * 2)
            surf = pygame.Surface((size, size), pygame.SRCALPHA)
            # RGBA 보장
            if len(color) == 3:
                col = (*color, 255)
            else:
                col = color
            pygame.draw.circle(surf, col, (size // 2, size // 2), int(radius), width=int(thickness))
            _center_ring_cache[key] = surf  # type: ignore[name-defined]
        return surf

    # 외곽선 + 내부선 (녹는 중일 때는 페이드아웃)
    ring_alpha = int(255 * (1.0 - melt_progress)) if melting else 255
    ring_outer = _get_center_ring(STAGE7_CUBE_RADIUS + 10, (30, 40, 60, ring_alpha), 2)
    ring_inner = _get_center_ring(STAGE7_CUBE_RADIUS, (12, 18, 28, ring_alpha), 2)
    # 은은한 글로우(경량): 얇은 반투명 링을 아래에 한 겹
    glow_alpha = int(70 * (1.0 - melt_progress)) if melting else 70
    glow = _get_center_ring(STAGE7_CUBE_RADIUS + 14, (80, 140, 220, glow_alpha), 6)
    def _blit_center(s: pygame.Surface):
        surface.blit(s, (cx - s.get_width() // 2, cy - s.get_height() // 2))
    _blit_center(glow)
    _blit_center(ring_outer)
    _blit_center(ring_inner)

    # 녹는 효과: 보라색 액체가 흘러내리는 파티클
    if melting and melt_progress < 1.0:
        grid = st.get("grid", [])
        half = int(STAGE7_CUBE_RADIUS * 0.9)
        cell_size = (half * 2 - (STAGE7_CUBE_CELL_GAP * 2)) // 3

        # 각 셀이 녹아내리는 효과
        for r in range(3):
            for c in range(3):
                # 셀마다 다른 타이밍으로 녹음 (위→아래 순서)
                cell_delay = (r * 3 + c) * 0.08  # 셀마다 약간의 지연
                cell_melt = max(0, min(1.0, (melt_progress - cell_delay) / (1.0 - cell_delay * 0.9)))

                if cell_melt >= 1.0:
                    continue  # 완전히 녹음

                # 셀 위치
                cell_x = cx - half + c * (cell_size + STAGE7_CUBE_CELL_GAP)
                cell_y = cy - half + r * (cell_size + STAGE7_CUBE_CELL_GAP)

                # 녹으면서 아래로 흘러내림
                drip_offset = int(cell_melt * 60)
                cell_y += drip_offset

                # 크기 감소
                shrink = 1.0 - cell_melt * 0.5
                draw_size = int(cell_size * shrink)

                # 색상 (녹으면서 보라색으로 변함)
                if grid and r < len(grid) and c < len(grid[r]):
                    base_color = grid[r][c]
                else:
                    base_color = (180, 80, 220)

                # 보라색과 블렌딩
                melt_color = (
                    int(base_color[0] * (1 - cell_melt) + 180 * cell_melt),
                    int(base_color[1] * (1 - cell_melt) + 80 * cell_melt),
                    int(base_color[2] * (1 - cell_melt) + 220 * cell_melt),
                )

                # 투명도 감소
                alpha = int(255 * (1.0 - cell_melt * 0.8))

                if draw_size > 2 and alpha > 10:
                    cell_surf = pygame.Surface((draw_size, draw_size), pygame.SRCALPHA)
                    cell_surf.fill((*melt_color, alpha))
                    surface.blit(cell_surf, (int(cell_x), int(cell_y)))

                    # 물방울 효과 (아래로 떨어지는 작은 방울들)
                    if cell_melt > 0.2:
                        num_drops = int(3 * cell_melt)
                        for di in range(num_drops):
                            drop_y = cell_y + draw_size + di * 8 + int(cell_melt * 30)
                            drop_size = max(2, int(4 * (1.0 - cell_melt)))
                            drop_alpha = max(0, int(150 * (1.0 - cell_melt)))
                            if drop_alpha > 0:
                                drop_surf = pygame.Surface((drop_size * 2, drop_size * 2), pygame.SRCALPHA)
                                pygame.draw.circle(drop_surf, (*melt_color, drop_alpha),
                                                 (drop_size, drop_size), drop_size)
                                surface.blit(drop_surf, (int(cell_x + draw_size // 2 - drop_size),
                                                        int(drop_y)))
        return  # 녹는 중에는 일반 큐브 렌더링 스킵

    # 큐브(정면 3x3) 렌더: 활성 상태에서는 전체, 재조립 상태에서는 진행도에 따라 일부 채움
    grid = st.get("grid")
    if not grid:
        return
    # 그리드 렌더 영역 계산 (원 내부 정사각형)
    half = int(STAGE7_CUBE_RADIUS * 0.9)
    size = half * 2
    left = cx - half
    top = cy - half
    cell = (size - (STAGE7_CUBE_CELL_GAP * (STAGE7_CUBE_GRID_SIZE - 1))) // STAGE7_CUBE_GRID_SIZE

    # 재조립 모드일 때 채움 개수 계산
    rebuild = bool(st.get("rebuild", False))
    filled_count = 9
    if rebuild:
        prog = int(st.get("rebuild_progress", 0))
        # 0~5를 0~9로 매핑 (올림)
        filled_count = max(0, min(9, int(round(9 * (prog / 5.0)))))
    # 채움 순서(가독성 위주 좌→우, 상→하)
    order = [(r, c) for r in range(3) for c in range(3)]
    # 타겟 단색 (재조립 중에는 단색 목표로 보이도록)
    target_color = grid[0][0]
    if rebuild:
        # 재조립 중에는 단색 목표의 색으로 표시
        target_color = (255, 255, 100)

    idx = 0
    for r in range(3):
        for c in range(3):
            x = left + c * (cell + STAGE7_CUBE_CELL_GAP)
            y = top + r * (cell + STAGE7_CUBE_CELL_GAP)
            rect = pygame.Rect(x, y, cell, cell)
            if rebuild:
                if idx < filled_count:
                    base = target_color
                else:
                    base = (40, 40, 50)
            else:
                base = grid[r][c]
            # 셀 채움 + 하이라이트 테두리로 큐브 타일 느낌
            pygame.draw.rect(surface, base, rect, border_radius=4)
            pygame.draw.rect(surface, (20, 20, 28), rect, 2, border_radius=4)
            inner = rect.inflate(-4, -4)
            hl = tuple(min(255, int(v * 1.15)) for v in base[:3])
            pygame.draw.rect(surface, hl, inner, 1, border_radius=3)
            idx += 1


# =====================
# Stage 7 초인테트리서 테트로미노 광선 (폭발큐브 파괴)
# - 광폭화 초인테트리서 상태에서 게이지가 500에 도달하면 발동
# - 보스에서 중앙 큐브로 광선을 발사하여 큐브를 녹여버림
# - 발동 시 게이지 전량 소모
# =====================

def trigger_stage7_tetro_laser() -> bool:
    """테트로미노 광선 발동 트리거. 성공 시 True 반환."""
    global stage7_tetro_laser_charging, stage7_tetro_laser_charge_start_ms
    global boss_special_gauge, stage7_persistent_boss_gauge

    now = pygame.time.get_ticks()

    # 이미 충전/발사 중이면 무시
    if stage7_tetro_laser_charging or stage7_tetro_laser_active:
        return False

    # 쿨다운 체크
    if now - stage7_tetro_laser_last_fire_ms < STAGE7_TETRO_LASER_COOLDOWN_MS:
        return False

    # 충전 시작
    stage7_tetro_laser_charging = True
    stage7_tetro_laser_charge_start_ms = now

    # 게이지 전량 소모
    boss_special_gauge = 0
    stage7_persistent_boss_gauge = 0

    # print(f"[Stage7TetroLaser] ⚡ 테트로미노 광선 충전 시작! (게이지 전량 소모)")
    return True


def update_stage7_tetro_laser(now: int | None = None) -> None:
    """테트로미노 광선 상태 업데이트."""
    global stage7_tetro_laser_active, stage7_tetro_laser_start_ms
    global stage7_tetro_laser_charging, stage7_tetro_laser_charge_start_ms
    global stage7_tetro_laser_last_fire_ms

    if current_stage != 7:
        return

    if now is None:
        now = pygame.time.get_ticks()

    # UI 정지 중이면 업데이트 스킵
    if _is_stage7_ui_paused():
        return

    # 충전 완료 → 발사
    if stage7_tetro_laser_charging:
        if now - stage7_tetro_laser_charge_start_ms >= STAGE7_TETRO_LASER_CHARGE_MS:
            stage7_tetro_laser_charging = False
            stage7_tetro_laser_active = True
            stage7_tetro_laser_start_ms = now
            stage7_tetro_laser_last_fire_ms = now

            # 3D 폭발큐브 녹이기 (레이저로 파괴)
            if animated_bg_stage7 is not None:
                if animated_bg_stage7.is_cube_active():
                    if animated_bg_stage7.trigger_laser_melt():
                        # 테트로미노도 함께 제거
                        try:
                            if 'stage7_tetrominoes' in globals() and stage7_tetrominoes:
                                for mino in list(stage7_tetrominoes):
                                    if mino.get("state") not in ("evaporating", "destroying"):
                                        destroy_stage7_tetromino(mino, by_smoke=True)
                        except Exception:
                            pass
                        # print(f"[Stage7TetroLaser] 💥 테트로미노 광선 발사! 3D 폭발큐브 녹이기 시작!")
                    else:
                        pass  # print(f"[Stage7TetroLaser] 💥 테트로미노 광선 발사! (폭발큐브 이미 숨김/재조립 중)")
                else:
                    pass  # print(f"[Stage7TetroLaser] 💥 테트로미노 광선 발사! (폭발큐브 비활성)")
            else:
                pass  # print(f"[Stage7TetroLaser] 💥 테트로미노 광선 발사! (animated_bg_stage7 없음)")

            # 사운드 재생
            try:
                if 'SOUND_CHARACTER_LASER' in globals() and SOUND_CHARACTER_LASER:
                    play_sound_with_volume(SOUND_CHARACTER_LASER)
            except Exception:
                pass

    # 발사 종료
    if stage7_tetro_laser_active:
        if now - stage7_tetro_laser_start_ms >= STAGE7_TETRO_LASER_DURATION_MS:
            stage7_tetro_laser_active = False
            # print(f"[Stage7TetroLaser] 광선 종료")


def draw_stage7_tetro_laser(surface: pygame.Surface) -> None:
    """테트로미노 광선 시각 효과 렌더링 - 테트로미노 블럭 스트림 스타일."""
    if current_stage != 7:
        return

    now = pygame.time.get_ticks()

    # 보스 위치
    boss_cx = BOSS.centerx if BOSS else WIDTH // 2
    boss_cy = BOSS.bottom if BOSS else 65

    # 큐브 위치 (3D 폭발큐브)
    cube_cx = WIDTH // 2
    cube_cy = HEIGHT // 2
    if animated_bg_stage7 is not None:
        cube_cx, cube_cy = animated_bg_stage7.cube_center

    # 테트로미노 블럭 레이아웃 정의 (셀 좌표 기준)
    tetro_layouts = {
        'T': [(0, 0), (-1, 0), (1, 0), (0, -1)],
        'I': [(0, -1), (0, 0), (0, 1), (0, 2)],
        'L': [(-1, 0), (0, 0), (1, 0), (1, -1)],
        'J': [(-1, -1), (-1, 0), (0, 0), (1, 0)],
        'Z': [(-1, -1), (0, -1), (0, 0), (1, 0)],
        'S': [(-1, 0), (0, 0), (0, -1), (1, -1)],
        'O': [(0, 0), (1, 0), (0, 1), (1, 1)],
    }
    tetro_colors = {
        'T': (180, 80, 220),   # 보라
        'I': (80, 200, 255),   # 시안
        'L': (255, 165, 60),   # 주황
        'J': (80, 100, 220),   # 파랑
        'Z': (255, 80, 80),    # 빨강
        'S': (80, 220, 120),   # 초록
        'O': (255, 220, 60),   # 노랑
    }
    tetro_types = list(tetro_layouts.keys())

    def draw_tetromino_at(cx: float, cy: float, tetro_type: str, cell_size: int, alpha: int, rotation: int = 0):
        """지정 위치에 테트로미노 블럭 그리기."""
        if cell_size < 1 or alpha < 1:
            return
        layout = tetro_layouts[tetro_type]
        color = tetro_colors[tetro_type]
        # 회전 적용 (90도 단위)
        rotated = layout
        for _ in range(rotation % 4):
            rotated = [(-dy, dx) for dx, dy in rotated]

        for dx, dy in rotated:
            x = int(cx + dx * cell_size)
            y = int(cy + dy * cell_size)
            rect = pygame.Rect(x - cell_size // 2, y - cell_size // 2, cell_size, cell_size)
            # 블럭 본체
            block_surf = pygame.Surface((cell_size, cell_size), pygame.SRCALPHA)
            block_surf.fill((*color, alpha))
            surface.blit(block_surf, rect.topleft)
            # 하이라이트 테두리
            if alpha > 100:
                hl_color = tuple(min(255, c + 60) for c in color)
                pygame.draw.rect(surface, (*hl_color, min(255, alpha)), rect, 1)

    # 충전 이펙트 - 테트로미노 블럭 모임
    if stage7_tetro_laser_charging:
        charge_progress = min(1.0, (now - stage7_tetro_laser_charge_start_ms) / STAGE7_TETRO_LASER_CHARGE_MS)

        # 보스 주변에 테트로미노들이 모여드는 효과
        num_gathering = int(7 * charge_progress)
        gather_radius = 60 - 40 * charge_progress  # 점점 모임

        for i in range(num_gathering):
            angle = (now * 0.003 + i * (2 * math.pi / 7))
            dist = gather_radius + 10 * math.sin(now * 0.01 + i)
            px = boss_cx + math.cos(angle) * dist
            py = boss_cy + math.sin(angle) * dist
            tetro_type = tetro_types[i % len(tetro_types)]
            cell_size = int(6 + 4 * charge_progress)
            alpha = int(100 + 155 * charge_progress)
            rotation = int(now * 0.005 + i) % 4
            draw_tetromino_at(px, py, tetro_type, cell_size, alpha, rotation)

        # 충전 글로우
        glow_size = int(25 + 35 * charge_progress)
        glow_alpha = int(80 + 100 * charge_progress)
        glow_surf = pygame.Surface((glow_size * 2, glow_size * 2), pygame.SRCALPHA)
        pygame.draw.circle(glow_surf, (180, 100, 220, glow_alpha), (glow_size, glow_size), glow_size)
        surface.blit(glow_surf, (boss_cx - glow_size, boss_cy - glow_size))

        # 예고 라인 (테트로미노 점선)
        if charge_progress > 0.4:
            line_alpha = int(80 * (charge_progress - 0.4) / 0.6)
            num_dots = int(8 * charge_progress)
            for di in range(num_dots):
                t = (di + 0.5) / num_dots
                dx = boss_cx + (cube_cx - boss_cx) * t
                dy = boss_cy + (cube_cy - boss_cy) * t
                dot_surf = pygame.Surface((8, 8), pygame.SRCALPHA)
                pygame.draw.rect(dot_surf, (180, 80, 220, line_alpha), (0, 0, 8, 8))
                surface.blit(dot_surf, (int(dx - 4), int(dy - 4)))

    # 광선 발사 이펙트 - 테트로미노 스트림
    if stage7_tetro_laser_active:
        beam_time = now - stage7_tetro_laser_start_ms
        beam_progress = beam_time / STAGE7_TETRO_LASER_DURATION_MS

        # 페이드아웃 (마지막 30%)
        if beam_progress > 0.7:
            fade = 1.0 - (beam_progress - 0.7) / 0.3
        else:
            fade = 1.0

        beam_alpha = int(255 * fade)

        # 외곽 글로우 라인
        glow_surf = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
        for gi in range(4):
            glow_width = 30 - gi * 6
            glow_a = max(0, int(50 * fade) - gi * 12)
            if glow_a > 0:
                pygame.draw.line(glow_surf, (150, 80, 200, glow_a),
                               (boss_cx, boss_cy), (cube_cx, cube_cy), glow_width)
        surface.blit(glow_surf, (0, 0))

        # 테트로미노 블럭 스트림 (빔을 따라 흐름)
        num_tetros = 12
        stream_speed = 0.004  # 흐름 속도

        for ti in range(num_tetros):
            # 각 테트로미노의 위치 (시간에 따라 흐름)
            base_phase = (ti / num_tetros)
            flow_offset = (beam_time * stream_speed) % 1.0
            phase = (base_phase + flow_offset) % 1.0

            # 빔 시작~끝 사이 위치
            tx = boss_cx + (cube_cx - boss_cx) * phase
            ty = boss_cy + (cube_cy - boss_cy) * phase

            # 테트로미노 종류 (순환)
            tetro_type = tetro_types[ti % len(tetro_types)]

            # 크기와 투명도 (중앙이 가장 밝음)
            dist_from_center = abs(phase - 0.5) * 2  # 0~1 (0이 중앙)
            size_factor = 1.0 - dist_from_center * 0.3
            alpha_factor = 1.0 - dist_from_center * 0.4

            cell_size = int(10 * size_factor * fade)
            alpha = int(beam_alpha * alpha_factor)

            # 회전 (시간에 따라)
            rotation = int((beam_time * 0.008 + ti * 0.7)) % 4

            if cell_size > 2 and alpha > 20:
                draw_tetromino_at(tx, ty, tetro_type, cell_size, alpha, rotation)

        # 발사구 - 테트로미노 폭발 효과
        muzzle_tetros = 4
        for mi in range(muzzle_tetros):
            angle = now * 0.015 + mi * (2 * math.pi / muzzle_tetros)
            dist = 15 + 8 * math.sin(now * 0.02 + mi)
            mx = boss_cx + math.cos(angle) * dist
            my = boss_cy + math.sin(angle) * dist
            mtype = tetro_types[(mi + int(now * 0.01)) % len(tetro_types)]
            draw_tetromino_at(mx, my, mtype, int(8 * fade), int(200 * fade), int(now * 0.01 + mi) % 4)

        # 임팩트 - 큐브 위치에서 테트로미노 산란
        impact_tetros = 6
        impact_pulse = 0.5 + 0.5 * math.sin(beam_time * 0.015)
        for ii in range(impact_tetros):
            angle = now * 0.012 + ii * (2 * math.pi / impact_tetros)
            dist = 30 + 20 * impact_pulse
            ix = cube_cx + math.cos(angle) * dist
            iy = cube_cy + math.sin(angle) * dist
            itype = tetro_types[(ii + int(now * 0.008)) % len(tetro_types)]
            ialpha = int(180 * fade * (0.6 + 0.4 * impact_pulse))
            draw_tetromino_at(ix, iy, itype, int(7 * fade), ialpha, int(now * 0.006 + ii) % 4)

        # 중앙 임팩트 글로우
        impact_size = int(35 * fade * impact_pulse)
        if impact_size > 0:
            impact_surf = pygame.Surface((impact_size * 2, impact_size * 2), pygame.SRCALPHA)
            pygame.draw.circle(impact_surf, (255, 180, 255, int(120 * fade)),
                             (impact_size, impact_size), impact_size)
            surface.blit(impact_surf, (cube_cx - impact_size, cube_cy - impact_size))


def reset_stage7_tetro_laser_state() -> None:
    """테트로미노 광선 상태 초기화."""
    global stage7_tetro_laser_active, stage7_tetro_laser_start_ms
    global stage7_tetro_laser_charging, stage7_tetro_laser_charge_start_ms
    global stage7_tetro_laser_last_fire_ms

    stage7_tetro_laser_active = False
    stage7_tetro_laser_start_ms = 0
    stage7_tetro_laser_charging = False
    stage7_tetro_laser_charge_start_ms = 0
    stage7_tetro_laser_last_fire_ms = 0


def reset_stage7_tetromino_state(*, reset_timer: bool = True) -> None:
    """Stage 7 테트로미노 스킬 상태 초기화."""
    global stage7_tetrominoes, stage7_tetromino_next_trigger_ms, stage7_tetro_followup_due_ms, stage7_tetro_followup_remaining
    global stage7_super_active, stage7_super_ends_at_ms
    stage7_tetrominoes.clear()
    if reset_timer:
        stage7_tetromino_next_trigger_ms = 0
        stage7_tetro_followup_due_ms = 0
        stage7_tetro_followup_remaining = 0
        stage7_super_active = False
        stage7_super_ends_at_ms = 0
        try:
            stage7_super_particles.clear()
        except Exception:
            pass


def _schedule_stage7_tetro(now: int | None = None) -> None:
    global stage7_tetromino_next_trigger_ms
    if now is None:
        now = pygame.time.get_ticks()
    stage7_tetromino_next_trigger_ms = now + random.randint(STAGE7_TETRO_MIN_INTERVAL_MS, STAGE7_TETRO_MAX_INTERVAL_MS)


def _rotate_offsets(offsets: list[tuple[int, int]], rotation: int) -> list[tuple[int, int]]:
    k = (rotation // 90) % 4
    pts = offsets[:]
    for _ in range(k):
        pts = [(-y, x) for (x, y) in pts]
    return pts


def _get_shape_layout(shape: str, rotation: int) -> list[tuple[int, int]]:
    if shape == 'T':
        base = [(-1, 0), (0, 0), (1, 0), (0, -1)]
    elif shape == 'L':
        base = [(-1, 0), (0, 0), (1, 0), (1, -1)]
    elif shape == 'Z':
        base = [(-1, -1), (0, -1), (0, 0), (1, 0)]
    elif shape == 'I':
        base = [(0, -1), (0, 0), (0, 1), (0, 2)]
    elif shape == 'O':  # 정사각형 (2x2)
        base = [(-1, 0), (0, 0), (-1, -1), (0, -1)]
    else:
        base = [(-1, 0), (0, 0), (1, 0), (0, -1)]
    # O는 회전해도 동일하지만, 일반화된 회전 함수를 적용해도 문제 없음
    return _rotate_offsets(base, rotation)


def spawn_stage7_tetromino(now: int | None = None) -> bool:
    """보스 패들 중앙에서 'ㅗ' 형상 T 블록을 생성하여 수직 낙하시킨다.
    게이지 50 소모. 보스가 없거나 게이지 부족 시 실패.
    """
    global boss_special_gauge, stage7_persistent_boss_gauge, stage7_tetrominoes
    if now is None:
        now = pygame.time.get_ticks()

    if BOSS is None:
        return False

    if boss_special_gauge < STAGE7_TETRO_GAUGE_COST:
        return False

    # 게이지 차감
    boss_special_gauge = max(0, boss_special_gauge - STAGE7_TETRO_GAUGE_COST)
    stage7_persistent_boss_gauge = boss_special_gauge
    pass  # print(f"[Stage7Tetro][Spawn] cost {STAGE7_TETRO_GAUGE_COST} → {boss_special_gauge}")  # 디버그 비활성화
    # 테트로 게이지 예약 해제 (성공적으로 소모했으므로)
    try:
        globals()['stage7_tetro_reserve'] = False
    except Exception:
        pass

    # 스케일: 초인 테트리서 활성 중에는 15% 축소된 강화형(기존 2배 → 1.7배)
    super_firing = bool(stage7_super_active)
    scale = STAGE7_TETRO_SUPER_SCALE if super_firing else 1.0
    cell_size = max(1, int(round(STAGE7_TETRO_CELL_SIZE * scale)))
    s = cell_size
    cx = float(BOSS.centerx)
    # 보스 패들 바로 아래에서 시작하되, 윗부분(ㅗ의 막대) 셀이 보스에 닿지 않도록 여유를 둔다.
    base_top = float(BOSS.bottom + s + 6)

    # 5가지 블럭(T, L, Z, I, O) 중 랜덤, 각 0/90/180/270 회전 랜덤
    rotation = random.choice((0, 90, 180, 270))
    shape = random.choice(['T', 'L', 'Z', 'I', 'O'])
    layout = _get_shape_layout(shape, rotation)
    cells = []
    # 조립 애니메이션을 위해 각 셀의 시작 위치를 소폭 랜덤 오프셋으로 지정(제자리에서 모이는 느낌)
    for dx, dy in layout:
        final_left = float(cx + dx * s - s / 2)
        final_top = float(base_top + dy * s)
        # ±8px 범위의 작은 오프셋에서 시작 → 제자리 모임 연출
        start_left = final_left + random.uniform(-8.0, 8.0)
        start_top = final_top + random.uniform(-8.0, 8.0)
        rect = pygame.Rect(int(round(start_left)), int(round(start_top)), s, s)
        cells.append({
            "rect": rect,
            "start_left": start_left,
            "start_top": start_top,
            "final_left": final_left,
            "final_top": final_top,
            "assemble_timer": 0.0,
        })

    mino = {
        "state": "assembling",             # 1초간 조립 후 낙하 시작
        "cells": cells,
        "last_update": now,
        "step_accum": 0.0,
        "visible_cells": 0,
        "assembly_elapsed": 0.0,
        "rotation": rotation,
        "shape": shape,
        "scale": scale,
        "cell_size": cell_size,
        "super": super_firing,
        "golden": True if random.random() < 0.03 else False,
        # 낙하 중 가끔 좌우로 1~2칸 이동 (셀 크기 단위)
        # 40% 확률로 -2..-1..1..2 중 하나 선택, 그 외 0(이동 없음)
        "drift_cells_remaining": (random.choice([-2, -1, 1, 2]) if random.random() < 0.4 else 0),
        "drift_cooldown": 0,  # 스텝 단위 쿨다운
        # 낙하 중 가끔 회전(90도) 1~2회
        "rotate_times_remaining": (random.choice([1, 2]) if random.random() < 0.35 else 0),
        "rotate_timer_ms": 0.0,
        "rotate_interval_ms": random.randint(200, 340),
        "rotate_dir": random.choice([-1, 1]),  # -1: CCW, 1: CW
    }
    stage7_tetrominoes.append(mino)
    return True


def update_stage7_tetrominoes(now: int | None = None) -> None:
    if now is None:
        now = pygame.time.get_ticks()
    if not stage7_tetrominoes:
        return

    for mino in stage7_tetrominoes[:]:
        elapsed = now - mino.get("last_update", now)
        if elapsed < 0:
            elapsed = 0

        state = mino.get("state")
        cell_size = max(1, int(mino.get("cell_size", STAGE7_TETRO_CELL_SIZE)))
        if state == "assembling":
            # 누적 조립 시간 업데이트 (last_update는 분기 처리 후 갱신)
            mino["assembly_elapsed"] = mino.get("assembly_elapsed", 0.0) + elapsed

            # 셀 순차 공개(0.25초 간격)
            while mino.get("visible_cells", 0) < 4 and mino["assembly_elapsed"] >= (mino["visible_cells"] + 1) * STAGE7_TETRO_ASSEMBLY_STEP_MS:
                mino["visible_cells"] += 1

            # 각 셀은 공개된 이후 목표 위치까지 선형 이동
            for idx, c in enumerate(mino["cells"]):
                # 아직 공개 전이면 위치 유지(스타트 위치)
                if idx >= mino["visible_cells"]:
                    c_left = c["start_left"]
                    c_top = c["start_top"]
                else:
                    # 공개된 시간 계산 → move_ms 기준 0→1 진행
                    # 공개 시점: idx * step
                    appear_t = idx * STAGE7_TETRO_ASSEMBLY_STEP_MS
                    t_since = max(0.0, mino["assembly_elapsed"] - appear_t)
                    prog = min(1.0, t_since / STAGE7_TETRO_ASSEMBLY_MOVE_MS)
                    c_left = c["start_left"] + (c["final_left"] - c["start_left"]) * prog
                    c_top = c["start_top"] + (c["final_top"] - c["start_top"]) * prog

                c["rect"].x = int(round(c_left))
                c["rect"].y = int(round(c_top))

            # 총 1초 경과 시 다음 단계로 전환, 위치를 최종값으로 스냅
            if mino["assembly_elapsed"] >= STAGE7_TETRO_ASSEMBLY_TOTAL_MS:
                for c in mino["cells"]:
                    c["rect"].x = int(round(c["final_left"]))
                    c["rect"].y = int(round(c["final_top"]))
                # 벽 생성물은 낙하 없이 곧바로 설치 상태로 전환하고 충돌 리스트에 등록
                if mino.get("wall_generated"):
                    mino["state"] = "installed"
                    mino["installed_at"] = now
                    side = mino.get("wall_side", 'left')
                    target_list = stage7_tetro_wall_left if side == 'left' else stage7_tetro_wall_right
                    for c in mino["cells"]:
                        if c["rect"] not in target_list:
                            target_list.append(c["rect"])
                else:
                    mino["state"] = "falling"
                    mino["step_accum"] = 0.0
                    # 낙하 시작 시점 기록 및 랜덤 발동 시점(0.5~1.2초) 스케줄링
                    mino["falling_started_at"] = now
                    try:
                        if int(mino.get("drift_cells_remaining", 0)) != 0:
                            mino["drift_start_due_ms"] = now + random.randint(500, 1200)
                        else:
                            mino["drift_start_due_ms"] = 0
                        if int(mino.get("rotate_times_remaining", 0)) > 0:
                            mino["rotate_start_due_ms"] = now + random.randint(500, 1200)
                        else:
                            mino["rotate_start_due_ms"] = 0
                    except Exception:
                        mino["drift_start_due_ms"] = 0
                        mino["rotate_start_due_ms"] = 0
        elif state == "falling":
            mino["step_accum"] += elapsed
            floor_y = HEIGHT - 12
            # 설치된 ㅗ 블럭 셀 모음(자기 자신 제외)
            installed_cells: list[pygame.Rect] = []
            for other in stage7_tetrominoes:
                if other is mino:
                    continue
                if other.get("state") == "installed":
                    # 증발된 셀은 충돌 후보에서 제외
                    installed_cells.extend([c["rect"] for c in other.get("cells", []) if not c.get("evaporated", False)])

            while mino["step_accum"] >= STAGE7_TETRO_STEP_MS:
                mino["step_accum"] -= STAGE7_TETRO_STEP_MS
                step_s = cell_size

                # A) 낙하 중 좌우 드리프트(셀 단위) 시도 — 낙하 후 0.5~1.2초 사이 랜덤 시점부터 활성화
                try:
                    drift = int(mino.get("drift_cells_remaining", 0))
                    if drift != 0:
                        due = int(mino.get("drift_start_due_ms", 0))
                        if due and now < due:
                            # 아직 발동 시점이 아님
                            pass
                        else:
                            dcool = int(mino.get("drift_cooldown", 0))
                            if dcool <= 0:
                                dx_px = step_s if drift > 0 else -step_s
                                can_move = True
                                for c in mino["cells"]:
                                    test_rect = c["rect"].copy()
                                    test_rect.x += dx_px
                                    if test_rect.left < 0 or test_rect.right > WIDTH:
                                        can_move = False
                                        break
                                    for rc in installed_cells:
                                        if test_rect.colliderect(rc):
                                            can_move = False
                                            break
                                    if not can_move:
                                        break
                                if can_move:
                                    for c in mino["cells"]:
                                        c["rect"].x += dx_px
                                    # 1칸 이동 완료 → 남은 칸 수 갱신
                                    mino["drift_cells_remaining"] = drift - (1 if drift > 0 else -1)
                                    mino["drift_cooldown"] = 1  # 다음 스텝까지 대기
                                else:
                                    # 막혔으면 중단
                                    mino["drift_cells_remaining"] = 0
                            else:
                                # 쿨다운 중이면 카운트 다운
                                mino["drift_cooldown"] = max(0, dcool - 1)
                except Exception:
                    pass

                # B) 낙하 중 90도 회전 시도(최대 1~2회) — 낙하 후 0.5~1.2초 사이 랜덤 시점부터 활성화
                try:
                    rleft = int(mino.get("rotate_times_remaining", 0))
                    if rleft > 0:
                        rdue = int(mino.get("rotate_start_due_ms", 0))
                        if rdue and now < rdue:
                            # 아직 발동 시점이 아님: 타이머는 축적하지만 시도는 보류
                            mino["rotate_timer_ms"] = float(mino.get("rotate_timer_ms", 0.0)) + STAGE7_TETRO_STEP_MS
                            # 다음 스텝으로 진행
                            pass
                        else:
                            rtimer = float(mino.get("rotate_timer_ms", 0.0)) + STAGE7_TETRO_STEP_MS
                            rinterval = float(mino.get("rotate_interval_ms", 260.0))
                            if rtimer >= rinterval:
                                xs = [c["rect"].centerx for c in mino.get("cells", [])]
                                ys = [c["rect"].centery for c in mino.get("cells", [])]
                                if xs and ys:
                                    cx = sum(xs) / len(xs)
                                    cy = sum(ys) / len(ys)
                                    dir_sign = 1 if int(mino.get("rotate_dir", 1)) >= 0 else -1
                                    new_rects = []
                                    for c in mino.get("cells", []):
                                        ox = c["rect"].centerx - cx
                                        oy = c["rect"].centery - cy
                                        if dir_sign >= 0:  # CW 90°
                                            nx = cx + oy
                                            ny = cy - ox
                                        else:             # CCW 90°
                                            nx = cx - oy
                                            ny = cy + ox
                                        test_rect = c["rect"].copy()
                                        test_rect.centerx = int(round(nx))
                                        test_rect.centery = int(round(ny))
                                        new_rects.append(test_rect)
                                    ok = True
                                    for tr in new_rects:
                                        if tr.left < 0 or tr.right > WIDTH or tr.top < 0 or tr.bottom > HEIGHT:
                                            ok = False
                                            break
                                        for rc in installed_cells:
                                            if tr.colliderect(rc):
                                                ok = False
                                                break
                                        if not ok:
                                            break
                                    if ok:
                                        for i, c in enumerate(mino["cells"]):
                                            c["rect"].centerx = new_rects[i].centerx
                                            c["rect"].centery = new_rects[i].centery
                                        mino["rotation"] = (int(mino.get("rotation", 0)) + (90 if dir_sign >= 0 else -90)) % 360
                                        mino["rotate_times_remaining"] = rleft - 1
                                        mino["rotate_interval_ms"] = random.randint(200, 340)
                                        mino["rotate_dir"] = random.choice([-1, 1])  # 다음 회전 방향 랜덤
                                        mino["rotate_timer_ms"] = 0.0
                                    else:
                                        # 실패: 타이머 일부만 유지해 다음 시도까지 대기시간 축소
                                        mino["rotate_timer_ms"] = max(0.0, rtimer - rinterval * 0.5)
                                else:
                                    mino["rotate_timer_ms"] = 0.0
                            else:
                                mino["rotate_timer_ms"] = rtimer
                except Exception:
                    pass

                # 1) 바닥 충돌 예측: 다음 스텝 이동 시 바닥을 넘는지
                bottom_now = max(c["rect"].bottom for c in mino["cells"])
                if bottom_now + step_s >= floor_y:
                    dy = floor_y - bottom_now
                    for c in mino["cells"]:
                        c["rect"].y += dy
                    if mino.get("super", False):
                        stage7_tetromino_explode(mino, now=now)
                        break
                    else:
                        mino["state"] = "installed"
                        mino["installed_at"] = now
                        break

                # 2) 설치된 블럭과의 충돌 예측: 다음 스텝 이동 시 겹침 여부
                will_overlap = False
                for c in mino["cells"]:
                    test_rect = c["rect"].copy()
                    test_rect.y += step_s
                    for rc in installed_cells:
                        if test_rect.colliderect(rc):
                            will_overlap = True
                            break
                    if will_overlap:
                        break
                if will_overlap:
                    # 바로 위에 정착 (현재 위치 유지)
                    if mino.get("super", False):
                        stage7_tetromino_explode(mino, now=now)
                        break
                    else:
                        mino["state"] = "installed"
                        mino["installed_at"] = now
                        break

                # 3) 이동 수행
                for c in mino["cells"]:
                    c["rect"].y += step_s

            # 화면 밖으로 완전히 벗어나면 제거
            if all(c["rect"].top >= HEIGHT for c in mino["cells"]):
                _maybe_drop_star_for_tetro(mino)
                stage7_tetrominoes.remove(mino)
                # 삭제된 경우에는 last_update 갱신 불필요
                continue
        elif state == "installed":
            # 설치 후 일정 시간이 지나면 증발 해체 시퀀스 시작
            installed_at = int(mino.get("installed_at", now))
            since = now - installed_at
            # 모든 셀이 충돌 등으로 이미 제거되었으면 즉시 정리
            if all(c.get("evaporated", False) for c in mino.get("cells", [])):
                # 안전 정리: 남은 충돌 셀 제거
                if mino.get("wall_generated"):
                    for c in mino.get("cells", []):
                        _remove_wall_cell_rect(c["rect"])
                _maybe_drop_star_for_tetro(mino)
                stage7_tetrominoes.remove(mino)
                continue
            # 증발 상태 진입 (낙하형 기본 1.5초, 벽 생성물은 개별 지정(6초))
            expire_ms = int(mino.get("installed_duration_ms", 1500))
            if since >= expire_ms and mino.get("state") != "evaporating":
                mino["state"] = "evaporating"
                mino["evap_timer"] = 0.0
                mino["evap_interval"] = 160  # 셀 1개당 0.16초 간격으로 증발
                mino["evap_index"] = 0
                # 셀 순서를 살짝 섞어 자연스러움 부여
                order = list(range(len(mino.get("cells", []))))
                random.shuffle(order)
                mino["evap_order"] = order
                # 각 셀 증발 플래그 초기화
                for c in mino.get("cells", []):
                    c["evaporated"] = False
                # 파티클 컨테이너
                mino["steam_particles"] = []
        elif state == "evaporating":
            # 증발 파티클 및 셀 제거 진행
            mino["evap_timer"] = float(mino.get("evap_timer", 0.0)) + elapsed
            interval = max(40.0, float(mino.get("evap_interval", 160.0)))
            # 셀을 하나씩 증발 처리
            while mino["evap_timer"] >= interval and mino.get("evap_index", 0) < len(mino.get("cells", [])):
                mino["evap_timer"] -= interval
                idx = mino["evap_order"][mino["evap_index"]]
                if 0 <= idx < len(mino["cells"]):
                    c = mino["cells"][idx]
                    if not c.get("evaporated", False):
                        c["evaporated"] = True
                        # 벽 스킬 생성물: 시각적으로 사라질 때 충돌 셀도 제거
                        if mino.get("wall_generated"):
                            _remove_wall_cell_rect(c["rect"])
                        # 수증기 파티클 생성
                        cx, cy = c["rect"].centerx, c["rect"].centery
                        parts = []
                        speed_mult = float(mino.get("evap_speed_mult", 1.0))
                        for _ in range(random.randint(8, 12)):
                            vx = random.uniform(-0.35, 0.35) * speed_mult
                            vy = random.uniform(-0.9, -0.4) * speed_mult
                            life = int(420 / max(0.1, speed_mult))  # 빠를수록 수명 단축
                            parts.append({
                                "x": float(cx + random.uniform(-3, 3)),
                                "y": float(cy + random.uniform(-3, 3)),
                                "vx": vx,
                                "vy": vy,
                                "life": life,  # ms
                                "age": 0.0,
                                "size": random.randint(2, 4),
                            })
                        mino.setdefault("steam_particles", []).extend(parts)
                mino["evap_index"] += 1
            # 파티클 업데이트
            particles = mino.get("steam_particles", [])
            if particles:
                for p in particles[:]:
                    p["age"] += elapsed
                    p["x"] += p["vx"] * (elapsed / 16.0)
                    p["y"] += p["vy"] * (elapsed / 16.0)
                    # 살짝 퍼지게
                    p["vx"] *= 0.98
                    p["vy"] *= 0.99
                    if p["age"] >= p["life"]:
                        particles.remove(p)
            # 모든 셀이 증발했는지 확인
            all_gone = all(c.get("evaporated", False) for c in mino.get("cells", []))
            if all_gone and not particles:
                # 안전 정리: 남아있을 수 있는 충돌 셀 제거
                if mino.get("wall_generated"):
                    for c in mino.get("cells", []):
                        _remove_wall_cell_rect(c["rect"])
                _maybe_drop_star_for_tetro(mino)
                stage7_tetrominoes.remove(mino)
                continue
        elif state == "destroying":
            duration = max(1.0, float(mino.get("destroy_duration", 160)))
            timer = max(0.0, float(mino.get("destroy_timer", 0.0)) - elapsed)
            mino["destroy_timer"] = timer
            fade = max(0.0, timer / duration)
            for c in mino["cells"]:
                c["fade"] = fade
            if timer <= 0.0:
                if mino.get("linger_evap"):
                    # 링 이펙트 종료 → 설치 상태로 전환하여 3~5초 펄스 후 증발 루틴 적용
                    for c in mino.get("cells", []):
                        c.pop("fade", None)
                    mino["state"] = "installed"
                    # last_update는 아래에서 갱신됨
                else:
                    _maybe_drop_star_for_tetro(mino)
                    stage7_tetrominoes.remove(mino)
                    continue

        # 마지막에 업데이트 시간 반영
        mino["last_update"] = now


# Stage 7 테트로 렌더링용 임시 Surface 캐시(크기별 1장 재사용)
_stage7_cache_cell: dict[tuple[int, int], pygame.Surface] = {}
_stage7_cache_glint: dict[tuple[int, int], pygame.Surface] = {}
_stage7_cache_shimmer: dict[tuple[int, int], pygame.Surface] = {}
_stage7_cache_ring: dict[tuple[int, int], pygame.Surface] = {}
_stage7_cache_bubble: dict[tuple[int, int], pygame.Surface] = {}


def _stage7_get_temp_surface(cache: dict, size: tuple[int, int]) -> pygame.Surface:
    surf = cache.get(size)
    if surf is None:
        surf = pygame.Surface(size, pygame.SRCALPHA)
        cache[size] = surf
    else:
        # 완전 투명으로 초기화 (alpha 포함)
        surf.fill((0, 0, 0, 0))
    return surf


# 최적화: 헬퍼 함수를 모듈 레벨로 이동 (매 프레임 재정의 방지)
def _stage7_clamp(x: int) -> int:
    return max(0, min(255, x))


def _stage7_lighten(c: tuple[int, int, int], amt: int = 40) -> tuple[int, int, int]:
    return (min(255, c[0] + amt), min(255, c[1] + amt), min(255, c[2] + amt))


def _stage7_darken(c: tuple[int, int, int], amt: int = 50) -> tuple[int, int, int]:
    return (max(0, c[0] - amt), max(0, c[1] - amt), max(0, c[2] - amt))


# 테트로미노 모양별 색상 (미리 정의)
_STAGE7_TETRO_COLORS = {
    'T': (255, 105, 180),   # 핑크
    'I': (90, 160, 255),    # 파랑
    'O': (255, 220, 60),    # 노랑
    'L': (255, 165, 60),    # 주황
    'Z': (80, 220, 120),    # 초록
}
_STAGE7_TETRO_DEFAULT_COLOR = (170, 90, 255)  # 기본 보라


def draw_stage7_tetrominoes(surface: pygame.Surface) -> None:
    if not stage7_tetrominoes:
        return

    now_ms = pygame.time.get_ticks()  # 최적화: 루프 밖에서 한 번만 호출

    for mino in stage7_tetrominoes:
        state = mino.get("state")
        visible_cells = mino.get("visible_cells", 4 if state != "assembling" else 0)
        shape = mino.get("shape", 'T')

        # 도형별 색상 매핑 (특수=무지개 애니메이션)
        is_golden = bool(mino.get("golden"))
        if is_golden:
            try:
                seed = int(mino.get("golden_seed", 0))
                t = (now_ms + seed) * 0.006
                r = int(128 + 127 * math.sin(t))
                g = int(128 + 127 * math.sin(t + 2.094))  # +120°
                b = int(128 + 127 * math.sin(t + 4.188))  # +240°
                base_color = (_stage7_clamp(r), _stage7_clamp(g), _stage7_clamp(b))
            except Exception:
                base_color = (200, 200, 255)
        else:
            # 최적화: 딕셔너리 룩업 사용
            base_color = _STAGE7_TETRO_COLORS.get(shape, _STAGE7_TETRO_DEFAULT_COLOR)
        # 특수 번쩍: 주기적인 강한 펄스 적용
        if is_golden:
            try:
                seed = int(mino.get("golden_seed", 0))
                t2 = (now_ms + seed) * 0.016
                pulse = 0.55 + 0.45 * math.sin(t2 * 0.35)
                boost = int(36 * pulse)
                base_color = _stage7_lighten(base_color, boost)
            except Exception:
                pass
        # 피격 순간 반짝임(히트 플래시)
        flash_until = int(mino.get("hit_flash_until", 0))
        if flash_until > now_ms:
            duration = int(mino.get("hit_flash_duration", 130)) or 130
            strength = max(0.0, min(1.0, (flash_until - now_ms) / float(duration)))
            boost = int(120 * strength)
            base_color = _stage7_lighten(base_color, boost)
        highlight_color = _stage7_lighten(base_color, 35)
        border_color = _stage7_darken(base_color, 70)
        for idx, cell in enumerate(mino["cells"]):
            rect = cell["rect"]
            fade = cell.get("fade", 1.0)
            if state == "assembling" and idx >= visible_cells:
                # 아직 차례가 오지 않은 셀은 표시하지 않음(하나씩 모이는 연출)
                continue
            elif state == "destroying":
                alpha = int(200 * fade)
                border_alpha = int(190 * fade)
            elif state in ("installed", "evaporating"):
                # 설치 후 1~3초 구간에서 페이드 인/아웃 펄스
                installed_at = int(mino.get("installed_at", 0))
                t = now_ms - installed_at if installed_at else 0
                if 1000 <= t <= 3000 and mino.get("pulse_enabled", True):
                    # 2Hz 정도의 펄스
                    phase = (t - 1000) / 1000.0  # 0~2초
                    pulse = 0.5 + 0.5 * math.sin(phase * math.pi * 2.0)  # 0~1
                    alpha = int(150 + 100 * pulse)
                    border_alpha = int(150 + 90 * pulse)
                else:
                    alpha = 230
                    border_alpha = 255
                # 이미 사라진 셀은 표시하지 않음(벽 충돌 혹은 증발 과정)
                if cell.get("evaporated", False):
                    continue
            else:
                alpha = 230
                border_alpha = 255

            temp = _stage7_get_temp_surface(_stage7_cache_cell, (rect.width, rect.height))
            pygame.draw.rect(temp, (*base_color, alpha), temp.get_rect(), border_radius=4)
            pygame.draw.rect(temp, (*highlight_color, min(255, alpha + 20)), temp.get_rect().inflate(-4, -4), border_radius=3)
            pygame.draw.rect(temp, (*border_color, border_alpha), temp.get_rect(), 2, border_radius=4)
            surface.blit(temp, rect.topleft)
            # 특수 글린트(십자 섬광 + 슬라이딩 쉬머) 추가
            if is_golden and idx == 0:
                try:
                    glint = _stage7_get_temp_surface(_stage7_cache_glint, (rect.width, rect.height))
                    seed = int(mino.get("golden_seed", 0))
                    glow_alpha = int(80 + 70 * abs(math.sin((now_ms + seed) * 0.01)))
                    glint_color = (_stage7_clamp(base_color[0] + 40), _stage7_clamp(base_color[1] + 40), _stage7_clamp(base_color[2] + 40), glow_alpha)
                    # 수직/수평 얇은 십자
                    pygame.draw.rect(glint, glint_color, (rect.width//2 - 1, 0, 2, rect.height))
                    pygame.draw.rect(glint, glint_color, (0, rect.height//2 - 1, rect.width, 2))
                    surface.blit(glint, rect.topleft, special_flags=pygame.BLEND_ADD)
                    # 대각 쉬머 라인 (슬라이딩)
                    shift = int(((now_ms + seed) * 0.05) % (rect.width + rect.height))
                    shimmer = _stage7_get_temp_surface(_stage7_cache_shimmer, (rect.width, rect.height))
                    c = (_stage7_clamp(base_color[0] + 55), _stage7_clamp(base_color[1] + 55), _stage7_clamp(base_color[2] + 55), 85)
                    pygame.draw.line(shimmer, c, (max(0, shift - rect.height), 0), (min(rect.width, shift), min(rect.height, shift)), 2)
                    surface.blit(shimmer, rect.topleft, special_flags=pygame.BLEND_ADD)
                except Exception:
                    pass

        # 파편 대신 홀로그램 링 팝 효과(파괴 상태에서만 추가 렌더)
        if state == "destroying":
            duration = max(1.0, float(mino.get("destroy_duration", 220)))
            timer = float(mino.get("destroy_timer", 0.0))
            prog = 1.0 - max(0.0, min(timer / duration, 1.0))  # 0→1
            cx = int(mino.get("pop_cx", 0))
            cy = int(mino.get("pop_cy", 0))
            r0 = int(mino.get("pop_min_radius", 16))
            r1 = int(mino.get("pop_max_radius", 42))
            radius = int(r0 + (r1 - r0) * prog)
            ring_alpha = int(200 * (1.0 - prog))
            if radius > 2 and ring_alpha > 0:
                ring_size = radius * 2 + 4
                ring = _stage7_get_temp_surface(_stage7_cache_ring, (ring_size, ring_size))
                pygame.draw.circle(ring, (*highlight_color, ring_alpha), (ring_size // 2, ring_size // 2), radius, width=3)
                pygame.draw.circle(ring, (*border_color, int(ring_alpha * 0.8)), (ring_size // 2, ring_size // 2), max(1, radius - 2), width=1)
                surface.blit(ring, (cx - ring_size // 2, cy - ring_size // 2))

        # 증발 파티클 렌더링
        if state == "evaporating":
            for p in mino.get("steam_particles", []) or []:
                # 나이에 따라 알파/크기 보간
                life = max(1.0, float(p.get("life", 420)))
                age = min(life, float(p.get("age", 0.0)))
                k = 1.0 - (age / life)
                alpha_p = int(180 * k)
                size = int(max(1, p.get("size", 2) * (1.0 + (1.0 - k) * 0.6)))
                if alpha_p <= 0:
                    continue
                bubble = _stage7_get_temp_surface(_stage7_cache_bubble, (size * 2, size * 2))
                pygame.draw.circle(bubble, (230, 230, 255, alpha_p), (size, size), size)
                surface.blit(bubble, (int(p["x"]) - size, int(p["y"]) - size))


def spawn_stage7_tetro_debris(mino: dict, hit_x: float, hit_y: float) -> None:
    """테트로미노가 공에 맞았을 때 파편 폭발 효과 생성."""
    global stage7_tetro_debris_particles

    # 테트로미노 도형별 색상 결정
    shape = mino.get("shape", "T")
    is_golden = bool(mino.get("golden"))

    if is_golden:
        # 무지개 색상 - 현재 시간 기반
        t = pygame.time.get_ticks() * 0.006
        r = int(128 + 127 * math.sin(t))
        g = int(128 + 127 * math.sin(t + 2.094))
        b = int(128 + 127 * math.sin(t + 4.188))
        base_color = (max(0, min(255, r)), max(0, min(255, g)), max(0, min(255, b)))
    else:
        color_map = {
            'T': (255, 105, 180),   # 핑크
            'I': (90, 160, 255),    # 파랑
            'O': (255, 220, 60),    # 노랑
            'L': (255, 165, 60),    # 주황
            'Z': (80, 220, 120),    # 초록
        }
        base_color = color_map.get(shape, (170, 90, 255))

    # 셀들의 중심 좌표 계산
    cells = mino.get("cells", [])
    if not cells:
        cx, cy = hit_x, hit_y
    else:
        xs = [c["rect"].centerx for c in cells if not c.get("evaporated")]
        ys = [c["rect"].centery for c in cells if not c.get("evaporated")]
        if xs and ys:
            cx = sum(xs) / len(xs)
            cy = sum(ys) / len(ys)
        else:
            cx, cy = hit_x, hit_y

    # 파편 개수: 초인 테트로는 더 많은 파편
    is_super = bool(mino.get("super"))
    debris_count = random.randint(18, 28) if is_super else random.randint(12, 18)

    now = pygame.time.get_ticks()

    for _ in range(debris_count):
        # 파편 크기
        size = random.randint(4, 10) if is_super else random.randint(3, 7)

        # 방사형 속도 (폭발하듯 퍼져나감)
        angle = random.uniform(0, 2 * math.pi)
        speed = random.uniform(4.0, 12.0) if is_super else random.uniform(3.0, 9.0)
        vx = math.cos(angle) * speed
        vy = math.sin(angle) * speed - random.uniform(1.0, 3.0)  # 약간 위로 튀는 느낌

        # 색상 변형 (밝기/채도 약간 랜덤화)
        color_var = random.randint(-30, 30)
        color = (
            max(0, min(255, base_color[0] + color_var)),
            max(0, min(255, base_color[1] + color_var)),
            max(0, min(255, base_color[2] + color_var)),
        )

        # 파편 타입: 사각형 또는 삼각형
        shape_type = random.choice(["rect", "rect", "triangle"])

        particle = {
            "x": cx + random.uniform(-8, 8),
            "y": cy + random.uniform(-8, 8),
            "vx": vx,
            "vy": vy,
            "size": size,
            "color": color,
            "shape_type": shape_type,
            "rotation": random.uniform(0, 360),
            "rot_speed": random.uniform(-15, 15),
            "life": random.randint(500, 900),  # ms
            "spawn_time": now,
            "gravity": 0.15,
        }
        stage7_tetro_debris_particles.append(particle)

    # 폭발 중심에 작은 섬광 효과 추가
    for _ in range(5):
        spark = {
            "x": cx,
            "y": cy,
            "vx": random.uniform(-6, 6),
            "vy": random.uniform(-6, 6),
            "size": random.randint(2, 4),
            "color": (255, 255, 255),
            "shape_type": "circle",
            "rotation": 0,
            "rot_speed": 0,
            "life": random.randint(150, 300),
            "spawn_time": now,
            "gravity": 0.05,
        }
        stage7_tetro_debris_particles.append(spark)


def update_stage7_tetro_debris() -> None:
    """테트로미노 파편 파티클 업데이트."""
    global stage7_tetro_debris_particles
    if not stage7_tetro_debris_particles:
        return

    now = pygame.time.get_ticks()
    alive = []

    for p in stage7_tetro_debris_particles:
        age = now - p["spawn_time"]
        if age >= p["life"]:
            continue

        # 물리 업데이트
        p["vy"] += p["gravity"]
        p["x"] += p["vx"]
        p["y"] += p["vy"]
        p["rotation"] += p["rot_speed"]

        # 속도 감쇠
        p["vx"] *= 0.97
        p["vy"] *= 0.98

        alive.append(p)

    stage7_tetro_debris_particles = alive


def draw_stage7_tetro_debris(surface: pygame.Surface) -> None:
    """테트로미노 파편 파티클 렌더링."""
    if not stage7_tetro_debris_particles:
        return

    now = pygame.time.get_ticks()

    for p in stage7_tetro_debris_particles:
        age = now - p["spawn_time"]
        life = p["life"]
        if age >= life:
            continue

        # 페이드 아웃
        alpha = int(255 * (1.0 - age / life))
        if alpha <= 0:
            continue

        size = p["size"]
        color = p["color"]
        x, y = int(p["x"]), int(p["y"])

        if p["shape_type"] == "circle":
            # 섬광용 원
            if alpha > 0:
                s = pygame.Surface((size * 2, size * 2), pygame.SRCALPHA)
                pygame.draw.circle(s, (*color, alpha), (size, size), size)
                surface.blit(s, (x - size, y - size))
        elif p["shape_type"] == "triangle":
            # 삼각형 파편
            s = pygame.Surface((size * 2, size * 2), pygame.SRCALPHA)
            rot = math.radians(p["rotation"])
            pts = []
            for i in range(3):
                a = rot + i * (2 * math.pi / 3)
                px = size + math.cos(a) * size * 0.8
                py = size + math.sin(a) * size * 0.8
                pts.append((px, py))
            pygame.draw.polygon(s, (*color, alpha), pts)
            surface.blit(s, (x - size, y - size))
        else:
            # 사각형 파편 (회전)
            s = pygame.Surface((size, size), pygame.SRCALPHA)
            s.fill((*color, alpha))
            rotated = pygame.transform.rotate(s, p["rotation"])
            rect = rotated.get_rect(center=(x, y))
            surface.blit(rotated, rect)


def destroy_stage7_tetromino(mino: dict, *, now: int | None = None, by_player: bool = False, by_dash: bool = False, by_smoke: bool = False, by_ball: bool = False, ball_pos: tuple[float, float] | None = None) -> None:
    if mino.get("state") in ("destroying", "evaporating"):
        return
    if now is None:
        now = pygame.time.get_ticks()

    reason = "ball" if by_ball else ("dash" if by_dash else ("player" if by_player else ("smoke" if by_smoke else "other")))
    mino["destroy_reason"] = reason

    # 공에 맞아서 파괴된 경우: 파편 폭발 효과 생성
    if by_ball and ball_pos:
        try:
            spawn_stage7_tetro_debris(mino, ball_pos[0], ball_pos[1])
        except Exception:
            pass

    # 공/대쉬/연막으로 파괴된 경우: 링 이펙트 없이 즉시 증발 해체 시작
    if by_player or by_dash or by_smoke or by_ball:
        mino["state"] = "evaporating"
        mino["evap_timer"] = 0.0
        # 대쉬/플레이어/연막 접촉 시 빠르게 분해되는 동일 연출 사용
        mino["evap_interval"] = 111.0
        mino["evap_speed_mult"] = 1.5
        mino["evap_index"] = 0
        order = list(range(len(mino.get("cells", []))))
        random.shuffle(order)
        mino["evap_order"] = order
        for c in mino.get("cells", []):
            c["evaporated"] = False
            c.pop("fade", None)
        mino["steam_particles"] = []
        mino["pulse_enabled"] = False  # 깜빡임 금지
        mino["nonblocking"] = True     # 플레이어 차단하지 않음
        mino["last_update"] = now
        # 해체 사운드 재생
        try:
            if SOUND_TETRISBREAK:
                play_sound_with_volume(SOUND_TETRISBREAK)
        except Exception:
            pass
        return

    # 그 외(예: 기타 효과)에 의한 파괴: 기존 링 이펙트를 사용하고, 이후 설치→증발 순서로 진행
    mino["state"] = "destroying"
    mino["destroy_duration"] = 220
    mino["destroy_timer"] = 220
    xs = [c["rect"].centerx for c in mino["cells"]]
    ys = [c["rect"].centery for c in mino["cells"]]
    mino["pop_cx"] = int(sum(xs) / len(xs)) if xs else 0
    mino["pop_cy"] = int(sum(ys) / len(ys)) if ys else 0
    mino["pop_max_radius"] = 42
    mino["pop_min_radius"] = 16
    mino["last_update"] = now
    mino["linger_evap"] = True
    mino["installed_at"] = now
    mino["pulse_enabled"] = True
    try:
        play_wall_sound()
    except Exception:
        pass


def _maybe_drop_star_for_tetro(mino: dict) -> None:
    """무지개(특수) 테트로가 해체될 때 스타 포인트 1개 드랍."""
    try:
        if not mino.get("golden") or mino.get("star_dropped"):
            return
        # 중심 좌표 계산
        xs = [c["rect"].centerx for c in mino.get("cells", []) if c.get("rect")]
        ys = [c["rect"].centery for c in mino.get("cells", []) if c.get("rect")]
        if not xs or not ys:
            return
        cx = int(sum(xs) / len(xs))
        cy = int(sum(ys) / len(ys))
        tps = trade_point_system
        if tps is not None and hasattr(tps, "spawn_star"):
            tps.spawn_star(cx, cy, "rainbow_tetro")
            mino["star_dropped"] = True
    except Exception:
        pass


def stage7_tetromino_explode(mino: dict, *, now: int | None = None) -> None:
    """초인 테트리서 기간 중 착지 시 폭발.

    - 기본: 넉백 + 스턴 0.5s
    - 초인(슈퍼) 활성 시: 넉백 2배 + 스턴 0.9s
    """
    if now is None:
        now = pygame.time.get_ticks()
    # 폭발 중심
    xs = [c["rect"].centerx for c in mino.get("cells", [])]
    ys = [c["rect"].centery for c in mino.get("cells", [])]
    if not xs or not ys:
        if mino in stage7_tetrominoes:
            stage7_tetrominoes.remove(mino)
        return
    cx = int(sum(xs) / len(xs))
    cy = int(sum(ys) / len(ys))
    # 반경: 실제 셀 픽셀 크기 비율을 그대로 반영
    cell_size = float(mino.get("cell_size", STAGE7_TETRO_CELL_SIZE))
    cell_scale = max(0.1, cell_size / float(STAGE7_TETRO_CELL_SIZE))
    radius = STAGE7_TETRO_EXPLOSION_BASE_RADIUS * cell_scale
    # 시각/사운드 (수류탄 폭발 재사용, 코만도 보너스 없음)
    try:
        trigger_grenade_style_explosion(cx, cy, apply_commando_bonus=False, source="tetro_explosion", radius_scale=radius / 150.0)
    except Exception:
        pass
    # 플레이어 넉백/스턴 적용
    try:
        player_cx = PLAYER.centerx
        player_cy = PLAYER.centery
        dx = player_cx - cx
        dy = player_cy - cy
        dist = math.hypot(dx, dy)
        if dist <= radius:
            direction = -1 if player_cx < cx else 1
            # 초인 모드일 때 넉백 2배
            super_active = bool(stage7_super_active or mino.get('super'))
            knock_scale = 2.0 if super_active else 1.0
            knock = apply_knockback_resist((STAGE7_TETRO_EXPLOSION_KNOCKBACK * knock_scale) * direction)
            # 스턴: 기본 0.5초, 초인 시 1.0초
            stun_seconds = STAGE7_TETRO_SUPER_STUN_S if super_active else STAGE7_TETRO_EXPLOSION_STUN_S
            global player_knockback_vel
            if try_apply_player_stun(stun_seconds, source="stage7_tetro_explosion", knockback_scaled=True) > 0:
                player_knockback_vel = knock
                _kb_debug(f"tetro explosion: dir={direction}, super={super_active}, vel={player_knockback_vel:.2f}")
                # 초인 테트로 폭발 스턴 동안 STUN 텍스트 숨김
                try:
                    global player_stun_text_hidden_until_ms, player_stun_text_suppress
                    player_stun_text_hidden_until_ms = now + int(stun_seconds * 1000)
                    # 요청: 초인 폭발 스턴 동안 플레이어 머리 위 STUN 텍스트 비표시
                    if knock_scale > 1.0:
                        player_stun_text_suppress = True
                except Exception:
                    pass
    except Exception:
        pass
    # 블럭 제거
    try:
        _maybe_drop_star_for_tetro(mino)
        stage7_tetrominoes.remove(mino)
    except ValueError:
        pass


def enforce_player_blocking_by_installed_tetro() -> None:
    """플레이어 패들이 설치된 ㅗ 블럭을 가로질러 이동하지 못하도록 막는다.
    - 대쉬(rolling_active 또는 is_half_dash_active) 중 충돌 시 블럭을 파괴하며 통과 가능.
    - 일반 이동 중 충돌 시 플레이어를 블럭 밖으로 되돌린다.
    """
    if current_stage != 7 or not stage7_tetrominoes:
        return
    try:
        dash_like = bool(rolling_active or is_half_dash_active)
    except Exception:
        dash_like = False
    player_rect = pygame.Rect(PLAYER.x, PLAYER.y, PLAYER.width, PLAYER.height)
    adjusted = False
    for mino in stage7_tetrominoes[:]:
        if mino.get("state") not in ("installed", "evaporating"):
            continue
        if mino.get("nonblocking", False):
            # 대쉬/공에 의해 파괴된 뒤 남은 잔상은 차단하지 않음
            continue
        hit = False
        for c in mino.get("cells", []):
            if c.get("evaporated", False):
                continue
            if player_rect.colliderect(c["rect"]):
                hit = True
                break
        if not hit:
            continue
        if dash_like:
            destroy_stage7_tetromino(mino, by_player=True, by_dash=True)
            continue
        # 일반 이동: 플레이어를 블럭 바깥으로 밀어냄
        # 좌우 어느 쪽이 가까운지 기준으로 정리
        # 블럭 전체 경계
        minx = min(c["rect"].left for c in mino["cells"])
        maxx = max(c["rect"].right for c in mino["cells"])
        if player_rect.centerx >= (minx + maxx) // 2:
            # 오른쪽에 있다 → 오른쪽으로 밀기
            PLAYER.x = max(PLAYER.x, maxx + 1)
        else:
            # 왼쪽으로 밀기
            PLAYER.x = min(PLAYER.x, minx - PLAYER.width - 1)
        adjusted = True
    if adjusted:
        # 화면 경계 재클램프
        PLAYER.x = max(0, min(WIDTH - PLAYER.width, PLAYER.x))


def stage7_center_cube_explode_and_clear_tetros(now: int | None = None) -> None:
    """중앙 큐브 폭발: 시각 이펙트 + 스테이지7 테트로미노들을 증발 처리.

    - 폭발 위치: 화면 중앙
    - 테트로미노 제거: destroy_stage7_tetromino(by_smoke=True) 경로 재사용(연막 해체와 동일 연출)
    """
    if current_stage != 7:
        return
    if now is None:
        now = pygame.time.get_ticks()
    cx, cy = WIDTH // 2, HEIGHT // 2
    # 폭발 시각/사운드 연출 (테트로 폭발에서 사용하는 유틸 재사용)
    try:
        trigger_grenade_style_explosion(cx, cy, apply_commando_bonus=False, source="center_cube", radius_scale=1.2)
    except Exception:
        pass
    # 스타포인트 1개 드랍
    try:
        if 'trade_point_system' in globals() and trade_point_system:
            trade_point_system.spawn_star(cx, cy, "stage7_center_cube")
    except Exception:
        pass
    # EMP 파문 이펙트 스폰
    try:
        spawn_stage7_emp_pulse(cx, cy)
    except Exception:
        pass
    # 모든 테트로미노를 증발 처리(연막과 동일 경로)
    try:
        if 'stage7_tetrominoes' in globals() and stage7_tetrominoes:
            for mino in list(stage7_tetrominoes):
                if mino.get("state") not in ("evaporating", "destroying"):
                    destroy_stage7_tetromino(mino, by_smoke=True)
    except Exception:
        pass

    # 보스 진영 1자(라인) 가드 테트로미노도 모두 제거
    try:
        if 'stage7_guard_blocks' in globals() and stage7_guard_blocks:
            for block in list(stage7_guard_blocks):
                if block.get("state") != "destroying":
                    destroy_stage7_guard_block(block, now=now, by_player=False)
    except Exception:
        pass


def update_stage7_tetromino_skill(now: int | None = None) -> None:
    """15~30초 쿨타임으로 ㅗ 블록을 플레이어 방향(수직 하강)으로 투척.
    가드 스킬과 독립된 스케줄/게이지를 사용한다.
    """
    global stage7_tetromino_next_trigger_ms

    if current_stage != 7 or new_boss_mode_active:
        return

    if now is None:
        now = pygame.time.get_ticks()

    # UI 정지 상태에서는 스킬 업데이트 중단
    if _is_stage7_ui_paused():
        return

    update_stage7_tetrominoes(now)
    update_stage7_tetro_debris()

    # 50% 확률로 예약된 추가 발사 처리 (0.3~0.9초 후 1회 시도)
    global stage7_tetro_followup_due_ms, stage7_tetro_followup_remaining
    if stage7_tetro_followup_due_ms and now >= stage7_tetro_followup_due_ms:
        # 게이지가 충분하면 즉시 추가 발사 시도 (예약은 소멸)
        due = stage7_tetro_followup_due_ms
        stage7_tetro_followup_due_ms = 0
        if current_stage == 7 and not new_boss_mode_active and boss_special_gauge >= STAGE7_TETRO_GAUGE_COST:
            if spawn_stage7_tetromino(now):
                pass  # print(f"[Stage7Tetro][FollowUp] extra spawn at +{now - due}ms (remain={stage7_tetro_followup_remaining})")  # 디버그 비활성화
                # 체인 연속 시도: 남은 횟수가 있고 50% 확률이면 또 예약
                if stage7_tetro_followup_remaining > 0 and random.random() < 0.5:
                    stage7_tetro_followup_due_ms = now + random.randint(300, 900)
                # 남은 횟수 감소 (성공 시에만)
                if stage7_tetro_followup_remaining > 0:
                    stage7_tetro_followup_remaining -= 1
        else:
            # 게이지 부족 등 실패 시 체인 종료
            stage7_tetro_followup_remaining = 0

    if stage7_tetromino_next_trigger_ms == 0:
        _schedule_stage7_tetro(now)

    if now < stage7_tetromino_next_trigger_ms:
        return

    if boss_special_gauge < STAGE7_TETRO_GAUGE_COST:
        # 게이지 부족: 테트로 예약 플래그를 켜서 가드가 게이지를 잠식하지 않도록 함
        globals()['stage7_tetro_reserve'] = True
        stage7_tetromino_next_trigger_ms = now + 1000
        return

    if spawn_stage7_tetromino(now):
        _schedule_stage7_tetro(now)
        # 체인 최대 6회: 첫 성공 시 남은 횟수 6으로 설정하고 50% 확률로 첫 예약
        stage7_tetro_followup_remaining = 6
        if random.random() < 0.5:
            stage7_tetro_followup_due_ms = now + random.randint(300, 900)
    else:
        # 게이지 부족 시 1초 후 재시도
        stage7_tetromino_next_trigger_ms = now + 1000


def draw_stage7_boss_gauge_bar():
    """Stage 7 보스 스킬 게이지 - 테트리스 블록 콘셉트"""
    global current_stage, boss_special_gauge, displayed_boss_gauge
    global stage7_gauge_debug_active, stage7_gauge_debug_last_log
    global stage7_gauge_debug_last_stage, stage7_gauge_debug_stage_log_ticks
    global stage8_shuriken_casting, stage8_shuriken_cast_start_ms

    time_now = pygame.time.get_ticks()
    if STAGE7_DEBUG.get('GAUGE', False) and time_now - stage7_gauge_debug_stage_log_ticks > 1000:
        stage7_gauge_debug_stage_log_ticks = time_now
        # print(f"[Stage7Gauge] stage={current_stage}, boss={boss_special_gauge}, displayed={displayed_boss_gauge}")

    if current_stage != 7:
        time_now = pygame.time.get_ticks()
        if STAGE7_DEBUG.get('GAUGE', False) and current_stage != stage7_gauge_debug_last_stage and time_now - stage7_gauge_debug_stage_log_ticks > 500:
            stage7_gauge_debug_last_stage = current_stage
            stage7_gauge_debug_stage_log_ticks = time_now
            # print(f"[Stage7Gauge] 현재 스테이지={current_stage} → 게이지 비활성")
        if stage7_gauge_debug_active and STAGE7_DEBUG.get('GAUGE', False):
            pass  # print("[Stage7Gauge] 스테이지 7 종료 → 게이지 디버그 비활성화")
        stage7_gauge_debug_active = False
        return

    max_gauge = 500
    current_gauge = max(0, displayed_boss_gauge)

    gauge_x = WIDTH - 45
    gauge_y = 60
    gauge_width = 14
    gauge_height = 100
    time_now = pygame.time.get_ticks()

    if not stage7_gauge_debug_active:
        stage7_gauge_debug_active = True
        stage7_gauge_debug_last_log = time_now
        if STAGE7_DEBUG.get('GAUGE', False):
            # print(
            #     f"[Stage7Gauge] 활성화: boss={boss_special_gauge:.1f}, displayed={displayed_boss_gauge:.1f}, tick={time_now}"
            # )
            # pass
            pass

    # 게이지 바 외곽/배경
    outer_rect = pygame.Rect(gauge_x - 6, gauge_y - 12, gauge_width + 12, gauge_height + 24)
    pygame.draw.rect(SCREEN, (18, 18, 30), outer_rect, border_radius=4)
    pygame.draw.rect(SCREEN, (90, 150, 255), outer_rect, 2, border_radius=4)

    inner_rect = pygame.Rect(gauge_x, gauge_y, gauge_width, gauge_height)
    pygame.draw.rect(SCREEN, (10, 10, 20), inner_rect)
    pygame.draw.rect(SCREEN, (48, 68, 108), inner_rect, 1)

    # 테트로미노 색 라인 게이지 (분할 표시)
    total_rows = 10
    cell_height = 8
    cell_gap = 2
    cell_width = gauge_width - 4
    cell_x = gauge_x + 2
    block_value = max_gauge / total_rows

    tetromino_colors = [
        (0, 228, 255),   # I
        (0, 91, 255),    # J
        (255, 142, 0),   # L
        (253, 230, 48),  # O
        (0, 220, 120),   # S
        (176, 0, 255),   # T
        (240, 64, 64),   # Z
    ]

    def brighten(color, amount):
        return tuple(min(255, max(0, c + amount)) for c in color)

    for row in range(total_rows):
        row_low = row * block_value
        row_high = (row + 1) * block_value
        if current_gauge >= row_high:
            fill_ratio = 1.0
        elif current_gauge <= row_low:
            fill_ratio = 0.0
        else:
            fill_ratio = (current_gauge - row_low) / block_value

        base_y = gauge_y + gauge_height - (row + 1) * (cell_height + cell_gap) + cell_gap
        cell_rect = pygame.Rect(cell_x, base_y, cell_width, cell_height)

        pygame.draw.rect(SCREEN, (26, 30, 52), cell_rect, border_radius=2)
        pygame.draw.rect(SCREEN, (36, 42, 66), cell_rect, 1, border_radius=2)

        if fill_ratio <= 0:
            continue

        fill_height = max(1, int(cell_height * fill_ratio))
        fill_rect = pygame.Rect(
            cell_rect.left + 1,
            cell_rect.bottom - fill_height,
            cell_rect.width - 2,
            fill_height,
        )
        fill_border_radius = min(2, fill_rect.width // 2, fill_rect.height // 2)
        color = tetromino_colors[row % len(tetromino_colors)]
        pygame.draw.rect(SCREEN, color, fill_rect, border_radius=fill_border_radius)

        highlight_rect = pygame.Rect(
            fill_rect.left + 1,
            fill_rect.top,
            max(1, fill_rect.width - 2),
            min(2, fill_rect.height),
        )
        pygame.draw.rect(SCREEN, brighten(color, 40), highlight_rect)

        divider_color = brighten(color, -60)
        if fill_rect.height > 3:
            pygame.draw.line(
                SCREEN,
                divider_color,
                (fill_rect.left, fill_rect.bottom - fill_rect.height // 2),
                (fill_rect.right - 1, fill_rect.bottom - fill_rect.height // 2),
            )
        if fill_rect.width > 5:
            mid_x = fill_rect.left + fill_rect.width // 2
            pygame.draw.line(
                SCREEN,
                divider_color,
                (mid_x, fill_rect.top),
                (mid_x, fill_rect.bottom - 1),
            )

    # 초인 상태임을 나타내는 '타오르는' 임펙트 (게이지 내부 불꽃 애니메이션)
    if stage7_super_active:
        try:
            flame_surface = pygame.Surface((gauge_width - 2, gauge_height - 2), pygame.SRCALPHA)
            cx_local = (gauge_width - 2) // 2
            # 불꽃 혀 5~6가닥을 시간에 따라 위로 올리며 그리기
            for i in range(6):
                # 상승 속도/위치
                tip = (time_now * 0.12 + i * 37) % (gauge_height - 8)
                tip_y = int((gauge_height - 2) - tip)
                base_y = min(gauge_height - 3, tip_y + 10)
                # 좌우 흔들림(뫼비우스 느낌의 이어짐)
                wobble = math.sin(time_now * 0.02 + i * 0.8) * 2
                cx = cx_local + int(wobble)
                # 폭 변화
                flame_w = 4 + int(2 + 2 * math.sin(time_now * 0.03 + i))
                left_x = max(1, cx - flame_w)
                right_x = min(gauge_width - 3, cx + flame_w)
                color_outer = (255, 90, 30, 110)
                color_inner = (255, 160, 80, 140)
                # 외피(삼각형)
                pygame.draw.polygon(
                    flame_surface,
                    color_outer,
                    [(left_x, base_y), (right_x, base_y), (cx, tip_y)],
                )
                # 심지(더 밝은 중심선)
                pygame.draw.line(
                    flame_surface,
                    color_inner,
                    (cx, base_y - 2),
                    (cx, tip_y + 2),
                    1,
                )
            # 전체 붉은 펄스(가벼운 호흡감)
            pulse = 0.5 + 0.5 * math.sin(time_now * 0.01)
            tint = pygame.Surface((gauge_width - 2, gauge_height - 2), pygame.SRCALPHA)
            tint.fill((180, 30, 30, int(40 * pulse)))
            flame_surface.blit(tint, (0, 0), special_flags=pygame.BLEND_RGBA_ADD)
            SCREEN.blit(flame_surface, (gauge_x + 1, gauge_y + 1), special_flags=pygame.BLEND_RGBA_ADD)
        except Exception:
            pass

    # 상단 테트리서 엠블럼 (애니메이션: 2.5초마다 모양 크로스페이드, 지속 회전)
    icon_center_x = gauge_x + gauge_width // 2
    icon_center_y = gauge_y - 22
    block_size = 6

    # 도형 레이아웃 정의 (T, I, L, Z)
    layouts = {
        'T': [(0, 0), (-1, 0), (1, 0), (0, -1)],
        'I': [(0, -1), (0, 0), (0, 1), (0, 2)],
        'L': [(-1, 0), (0, 0), (1, 0), (1, -1)],
        'Z': [(-1, -1), (0, -1), (0, 0), (1, 0)],
    }
    colors = {
        'T': (255, 105, 180),  # 핑크
        'I': (90, 160, 255),   # 파랑
        'L': (255, 165, 60),   # 주황
        'Z': (80, 220, 120),   # 초록
    }
    seq = ['T', 'I', 'L', 'Z']
    period = 2500  # 2.5초마다 모양 전환
    t_ms = pygame.time.get_ticks()
    phase = (t_ms // period) % len(seq)
    next_phase = (phase + 1) % len(seq)
    blend = (t_ms % period) / period  # 0→1
    shape_a = seq[phase]
    shape_b = seq[next_phase]
    # 회전(연속): 약 2.2초/회전
    rot = (t_ms % 2200) / 2200.0 * math.tau

    def draw_shape(layout, color, alpha):
        # 레이아웃을 회전하여 배치(셀 위치만 회전)
        cosr = math.cos(rot)
        sinr = math.sin(rot)
        for dx, dy in layout:
            # 회전 좌표(연속) – 정수 스냅으로 부드러움 유지
            rx = dx * cosr - dy * sinr
            ry = dx * sinr + dy * cosr
            px = int(round(icon_center_x + rx * (block_size + 2))) - block_size // 2
            py = int(round(icon_center_y + ry * (block_size + 2))) - block_size // 2
            rect = pygame.Rect(px, py, block_size, block_size)
            # 그림자
            sh = rect.move(1, 1)
            shadow = pygame.Surface((block_size, block_size), pygame.SRCALPHA)
            shadow.fill((0, 0, 0, int(120 * alpha)))
            SCREEN.blit(shadow, sh.topleft)
            # 본체
            body = pygame.Surface((block_size, block_size), pygame.SRCALPHA)
            r, g, b = color
            body.fill((r, g, b, int(255 * alpha)))
            SCREEN.blit(body, rect.topleft)
            # 하이라이트 테두리
            pygame.draw.rect(SCREEN, brighten(color, 40), rect, 1)

    # 크로스페이드 렌더
    draw_shape(layouts[shape_a], colors[shape_a], 1.0 - blend)
    draw_shape(layouts[shape_b], colors[shape_b], blend)


def update_stage7_super_state(now: int | None = None) -> None:
    """초인테트리서: 500 도달 시 발동, 발동 중에는 초당 게이지 25 감소, 0이 되면 종료.
    광폭화 모드: 항상 초인테트리서 상태, 게이지 감소 없음, 게이지는 0에서 천천히 충전."""
    global stage7_super_active, boss_special_gauge, stage7_persistent_boss_gauge
    global stage7_boss_orig_size, stage7_super_target_scale, stage7_super_scale
    global stage7_super_last_update_ms, stage7_super_drain_progress

    if now is None:
        now = pygame.time.get_ticks()
    ui_paused = _is_stage7_ui_paused()

    # 광폭화 모드 체크
    is_berserk = enraged_boss_active and current_stage == 7

    if current_stage != 7 or new_boss_mode_active:
        # 스테이지 벗어나면 비활성 방향으로 자연 복귀
        stage7_super_active = False
        stage7_super_target_scale = 1.0
        try:
            stage7_super_particles.clear()
        except Exception:
            pass
    else:
        # UI 정지 상태에서는 상태 변경 없이 타이머만 갱신
        if ui_paused:
            stage7_super_last_update_ms = now
            return

        # === 광폭화 모드: 항상 초인테트리서 상태 유지 ===
        if is_berserk:
            # 광폭화 시 초인테트리서가 아직 활성화되지 않았으면 즉시 활성화
            if not stage7_super_active:
                stage7_super_active = True
                stage7_super_target_scale = 1.4  # 광폭화 초인테트리서: +40% (일반 초인: +100%)
                if stage7_boss_orig_size is None:
                    stage7_boss_orig_size = (BOSS.width, BOSS.height)
                stage7_super_last_update_ms = now
                stage7_super_drain_progress = 0.0
                # 0.6초 포효 포즈 시작: 제자리 고정 + 사운드 재생
                try:
                    globals()['stage7_super_intro_until_ms'] = now + 600
                    if SOUND_CRY:
                        play_sound_with_volume(SOUND_CRY)
                except Exception:
                    globals()['stage7_super_intro_until_ms'] = now + 600
                try:
                    play_wall_sound()
                except Exception:
                    pass
                # print(f"[Stage7Super] 🔥 광폭화 {STAGE7_SUPER_NAME} 발동! (게이지 드레인 없음, 충전 계속)")
            # 광폭화 모드에서는 게이지 드레인 없이 초인테트리서 상태 유지
            # (게이지 충전은 update_stage7_gauge_charge에서 계속됨)
            stage7_super_last_update_ms = now

            # === 광폭화 초인테트리서: 게이지 500 도달 시 테트로미노 광선 발사 ===
            # 광선이 충전/발사 중이 아니고, 게이지가 500 이상이면 발동
            if boss_special_gauge >= 500:
                if not stage7_tetro_laser_charging and not stage7_tetro_laser_active:
                    trigger_stage7_tetro_laser()
        else:
            # === 일반 모드 ===
            # 발동 트리거: 500 도달
            if not stage7_super_active and boss_special_gauge >= 500:
                stage7_super_active = True
                stage7_super_target_scale = 2.0
                if stage7_boss_orig_size is None:
                    stage7_boss_orig_size = (BOSS.width, BOSS.height)
                stage7_super_last_update_ms = now
                stage7_super_drain_progress = 0.0
                # 0.6초 포효 포즈 시작: 제자리 고정 + 사운드 재생
                try:
                    globals()['stage7_super_intro_until_ms'] = now + 600
                    if SOUND_CRY:
                        play_sound_with_volume(SOUND_CRY)
                except Exception:
                    globals()['stage7_super_intro_until_ms'] = now + 600
                try:
                    play_wall_sound()
                except Exception:
                    pass
                # print(f"[Stage7Super] {STAGE7_SUPER_NAME} 발동! (게이지 소모형)")

            # 발동 중: 초당 25 드레인, 0이면 종료
            if stage7_super_active:
                # ui_paused 체크는 위에서 이미 처리됨
                if stage7_super_last_update_ms == 0:
                    stage7_super_last_update_ms = now
                elapsed = now - stage7_super_last_update_ms
                stage7_super_last_update_ms = now
                if elapsed > 0:
                    stage7_super_drain_progress += elapsed * 0.025
                    drain_units = int(stage7_super_drain_progress)
                    if drain_units > 0:
                        boss_special_gauge = max(0, boss_special_gauge - drain_units)
                        stage7_persistent_boss_gauge = boss_special_gauge
                        stage7_super_drain_progress -= drain_units
                if boss_special_gauge <= 0:
                    stage7_super_active = False
                    stage7_super_target_scale = 1.0
                    try:
                        stage7_super_particles.clear()
                    except Exception:
                        pass

    # 스케일 스무딩/적용 (항상 호출)
    try:
        if stage7_boss_orig_size is None:
            stage7_boss_orig_size = (BOSS.width, BOSS.height)
        smoothing = 0.18
        stage7_super_scale += (stage7_super_target_scale - stage7_super_scale) * smoothing
        cx, cy = BOSS.centerx, BOSS.centery
        base_w, base_h = stage7_boss_orig_size
        new_w = max(10, int(base_w * stage7_super_scale))
        new_h = max(6, int(base_h * stage7_super_scale))
        BOSS.width = new_w
        BOSS.height = new_h
        BOSS.centerx = cx
        BOSS.centery = cy
    except Exception:
        pass


def draw_stage7_super_bar() -> None:
    """요청에 따라 초인 타이머 게이지바는 비활성(표시하지 않음)."""
    return


def draw_stage7_debug_hud(surface: pygame.Surface) -> None:
    """Stage7 상태 간단 HUD (디버그 플래그 활성 시만 표시)."""
    if not STAGE7_DEBUG.get('HUD', False) or current_stage != 7:
        return
    try:
        font = FontStyle.tiny()
    except Exception:
        try:
            font = pygame.font.Font(None, 16)
        except Exception:
            return
    now = pygame.time.get_ticks()
    def _eta(ms):
        if not ms:
            return "-"
        left = max(0, ms - now)
        return f"{left/1000:.1f}s"
    # 수집
    try:
        g_cnt = len(stage7_guard_blocks)
    except Exception:
        g_cnt = 0
    try:
        t_cnt = len(stage7_tetrominoes)
    except Exception:
        t_cnt = 0
    try:
        wl = len(stage7_tetro_wall_left)
        wr = len(stage7_tetro_wall_right)
    except Exception:
        wl = wr = 0
    try:
        g_eta = _eta(stage7_guard_next_trigger_ms)
    except Exception:
        g_eta = "-"
    try:
        t_eta = _eta(stage7_tetromino_next_trigger_ms)
    except Exception:
        t_eta = "-"
    try:
        w_eta = _eta(stage7_tetro_wall_next_trigger_ms)
    except Exception:
        w_eta = "-"
    try:
        gauge = int(boss_special_gauge)
    except Exception:
        gauge = -1
    lines = [
        f"Stage7 HUD",
        f"Gauge: {gauge}",
        f"Guard: {g_cnt} (next {g_eta})",
        f"Tetros: {t_cnt} (next {t_eta})",
        f"Walls: L{wl}/R{wr} (next {w_eta})",
    ]
    x, y = 8, 52
    pad = 6
    # 배경 박스 크기 계산
    w = 0
    h = pad
    renders = []
    for s in lines:
        r = font.render(s, True, (220, 235, 255))
        renders.append(r)
        w = max(w, r.get_width())
        h += r.get_height() + 2
    w += pad * 2
    h += pad - 2
    bg = pygame.Surface((w, h), pygame.SRCALPHA)
    bg.fill((10, 18, 30, 150))
    pygame.draw.rect(bg, (40, 80, 160, 220), bg.get_rect(), 1)
    surface.blit(bg, (x, y))
    cy = y + pad
    for r in renders:
        surface.blit(r, (x + pad, cy))
        cy += r.get_height() + 2


def draw_stage2_boss_gauge_bar():
    """Stage 2 보스 스킬 게이지"""
    global current_stage, boss_special_gauge, displayed_boss_gauge

    if current_stage != 2:
        return

    max_gauge = 500
    current_gauge = max(0, displayed_boss_gauge)
    gauge_x = WIDTH - 45
    gauge_y = 70
    gauge_width = 14
    gauge_height = 100
    time_now = pygame.time.get_ticks()

    frame_rect = pygame.Rect(gauge_x - 6, gauge_y - 10, gauge_width + 12, gauge_height + 20)
    pygame.draw.rect(SCREEN, (24, 48, 32), frame_rect, border_radius=7)
    pygame.draw.rect(SCREEN, (90, 150, 90), frame_rect, 2, border_radius=7)

    vine_phase = time_now * 0.004
    for side in (-1, 1):
        vine_points = []
        for i in range(0, gauge_height + 10, 8):
            sway = math.sin(vine_phase + i * 0.15 + side * 0.6) * 3.2
            anchor_x = gauge_x + (0 if side == -1 else gauge_width)
            vine_points.append((anchor_x + side * 6 + sway, gauge_y + i - 4))
        pygame.draw.lines(SCREEN, (62, 120, 70), False, vine_points, 2)

        for i in range(0, gauge_height, 22):
            leaf_angle = vine_phase * 1.3 + i * 0.05 + (0 if side == -1 else math.pi / 2)
            leaf_length = 7
            leaf_width = 3
            cx = gauge_x + (0 if side == -1 else gauge_width) + side * 6 + math.sin(leaf_angle) * 2
            cy = gauge_y + i + math.cos(leaf_angle) * 2
            leaf_points = [
                (cx, cy),
                (cx + math.cos(leaf_angle) * leaf_length - math.sin(leaf_angle) * leaf_width,
                 cy + math.sin(leaf_angle) * leaf_length + math.cos(leaf_angle) * leaf_width),
                (cx + math.cos(leaf_angle) * leaf_length + math.sin(leaf_angle) * leaf_width,
                 cy + math.sin(leaf_angle) * leaf_length - math.cos(leaf_angle) * leaf_width),
            ]
            pygame.draw.polygon(SCREEN, (116, 196, 120), leaf_points)

    inner_rect = pygame.Rect(gauge_x, gauge_y, gauge_width, gauge_height)
    pygame.draw.rect(SCREEN, (16, 32, 22), inner_rect)
    pygame.draw.rect(SCREEN, (70, 115, 74), inner_rect, 1)

    gauge_ratio = min(current_gauge / max_gauge, 1.0)
    filled_height = int(gauge_height * gauge_ratio)
    if filled_height > 0:
        # 캐시된 그라데이션 사용 (높이 버킷팅: 10픽셀 단위)
        height_bucket = max(10, ((filled_height + 9) // 10) * 10)
        cache_key = ("stage2_gauge", gauge_width - 5, height_bucket)
        if cache_key not in _gauge_gradient_cache:
            if len(_gauge_gradient_cache) > 30:
                _gauge_gradient_cache.clear()
            grad_surf = pygame.Surface((gauge_width - 5, height_bucket), pygame.SRCALPHA)
            for i in range(height_bucket):
                row_ratio = i / max(1, height_bucket - 1)
                r = int(38 + 22 * (1 - row_ratio))
                g = int(150 + 60 * row_ratio)
                b = int(84 + 36 * (1 - row_ratio))
                pygame.draw.line(grad_surf, (r, g, b), (0, height_bucket - i - 1), (gauge_width - 6, height_bucket - i - 1))
            _gauge_gradient_cache[cache_key] = grad_surf
        grad_surf = _gauge_gradient_cache[cache_key]
        # filled_height만큼만 blit (하단부터)
        src_rect = (0, height_bucket - filled_height, gauge_width - 5, filled_height)
        SCREEN.blit(grad_surf, (gauge_x + 2, gauge_y + gauge_height - filled_height), src_rect)

        wave_top = gauge_y + gauge_height - filled_height
        shimmer = 0.6 + 0.4 * math.sin(time_now * 0.02)
        wave_color = (int(140 * shimmer), int(220 * shimmer), int(170 * shimmer))
        pygame.draw.line(SCREEN, wave_color, (gauge_x + 1, wave_top), (gauge_x + gauge_width - 2, wave_top), 1)

        bubble_count = max(1, int(gauge_ratio * 4))
        for idx in range(bubble_count):
            t = (time_now * 0.001 + idx * 0.25) % 1.0
            bubble_y = gauge_y + gauge_height - int(filled_height * t) - 3
            if gauge_y < bubble_y < gauge_y + gauge_height - 2:
                bubble_x = gauge_x + gauge_width // 2 + int(math.sin(time_now * 0.005 + idx) * 3)
                pygame.draw.circle(SCREEN, (210, 255, 220), (bubble_x, bubble_y), 2)

        for offset in (-6, -2, 2):
            ripple_y = wave_top + offset + int(math.sin(time_now * 0.01 + offset) * 2)
            if gauge_y < ripple_y < gauge_y + gauge_height:
                pygame.draw.line(SCREEN, (70, 160, 120), (gauge_x + 2, ripple_y), (gauge_x + gauge_width - 3, ripple_y), 1)

        if boss_special_gauge > current_gauge:
            gain_ratio = min((boss_special_gauge - current_gauge) / 80, 1.0)
            pulse_height = wave_top + int((math.sin(time_now * 0.02) * 0.5 + 0.5) * max(1, filled_height - 4))
            if gauge_y < pulse_height < gauge_y + gauge_height:
                pulse_color = (
                    int(90 + 90 * gain_ratio),
                    int(210 + 40 * gain_ratio),
                    int(150 + 50 * gain_ratio)
                )
                pygame.draw.line(SCREEN, pulse_color, (gauge_x + 2, pulse_height), (gauge_x + gauge_width - 3, pulse_height), 1)

    emblem_x = gauge_x + gauge_width // 2
    emblem_y = gauge_y - 34
    pulse = 1.0 + math.sin(time_now * 0.003) * 0.08

    base_radius = 16
    base_color = (32, 70, 46)
    border_color = (120, 190, 126)
    pygame.draw.circle(SCREEN, base_color, (emblem_x, emblem_y), int(base_radius * pulse))
    pygame.draw.circle(SCREEN, border_color, (emblem_x, emblem_y), int(base_radius * pulse), 3)

    snout_points = [
        (emblem_x - 9, emblem_y + 3),
        (emblem_x + 9, emblem_y + 3),
        (emblem_x + 4, emblem_y + 12),
        (emblem_x - 4, emblem_y + 12),
    ]
    pygame.draw.polygon(SCREEN, (58, 120, 80), snout_points)
    pygame.draw.lines(SCREEN, (90, 150, 110), False, snout_points + [snout_points[0]], 1)

    for dx in (-4, 4):
        pygame.draw.circle(SCREEN, (24, 50, 30), (emblem_x + dx, emblem_y + 10), 1)

    eye_offset = 7
    eye_y = emblem_y - 4
    pygame.draw.circle(SCREEN, (252, 255, 220), (emblem_x - eye_offset, eye_y), 3)
    pygame.draw.circle(SCREEN, (252, 255, 220), (emblem_x + eye_offset, eye_y), 3)
    pupil_offset = int(math.sin(time_now * 0.004) * 1.5)
    pygame.draw.circle(SCREEN, (20, 60, 40), (emblem_x - eye_offset + pupil_offset, eye_y), 1)
    pygame.draw.circle(SCREEN, (20, 60, 40), (emblem_x + eye_offset + pupil_offset, eye_y), 1)

    fang_color = (240, 250, 220)
    left_fang = [(emblem_x - 5, emblem_y + 6), (emblem_x - 2, emblem_y + 12), (emblem_x - 7, emblem_y + 12)]
    right_fang = [(emblem_x + 5, emblem_y + 6), (emblem_x + 7, emblem_y + 12), (emblem_x + 2, emblem_y + 12)]
    pygame.draw.polygon(SCREEN, fang_color, left_fang)
    pygame.draw.polygon(SCREEN, fang_color, right_fang)

    for i in range(6):
        angle = i * math.pi / 3 + time_now * 0.004
        scale_radius = base_radius - 3
        sx = emblem_x + math.cos(angle) * scale_radius
        sy = emblem_y + math.sin(angle) * scale_radius
        pygame.draw.circle(SCREEN, (80, 150, 100), (int(sx), int(sy)), 2)

    if current_gauge >= 350:
        ring_radius = int(base_radius * 1.4 + math.sin(time_now * 0.01) * 2)
        pygame.draw.circle(SCREEN, (120, 220, 170), (emblem_x, emblem_y), ring_radius, 1)

    gauge_font = FontStyle.tiny()
    gauge_text = f"{int(current_gauge)}/{max_gauge}"
    gauge_surface = gauge_font.render(gauge_text, True, (70, 120, 80))
    gauge_rect = gauge_surface.get_rect(centerx=gauge_x + gauge_width // 2, top=gauge_y + gauge_height + 25)
    SCREEN.blit(gauge_surface, gauge_rect)


def draw_stage8_boss_gauge_bar():
    """Stage 8 아카무 리고 보스 스킬 게이지 - 수리검/연막 테마"""
    global current_stage, boss_special_gauge, displayed_boss_gauge

    if current_stage != 8:
        return

    max_gauge = 500
    current_gauge = max(0, displayed_boss_gauge)

    gauge_width = 14
    gauge_height = 108
    gauge_x = WIDTH - 52
    gauge_y = 42
    time_now = pygame.time.get_ticks()

    # 프레임: 어두운 금속 + 자홍색 포인트
    frame_rect = pygame.Rect(gauge_x - 8, gauge_y - 14, gauge_width + 16, gauge_height + 28)
    pygame.draw.rect(SCREEN, (16, 16, 22), frame_rect, border_radius=6)
    pygame.draw.rect(SCREEN, (124, 50, 94), frame_rect, 2, border_radius=6)

    # 닌자 두건 포인트 라인
    pygame.draw.line(SCREEN, (180, 40, 60), (frame_rect.left + 4, frame_rect.top + 6), (frame_rect.right - 4, frame_rect.top + 2), 2)
    pygame.draw.line(SCREEN, (32, 140, 180), (frame_rect.left + 6, frame_rect.top + 12), (frame_rect.right - 6, frame_rect.top + 18), 2)

    inner_rect = pygame.Rect(gauge_x, gauge_y, gauge_width, gauge_height)
    pygame.draw.rect(SCREEN, (10, 10, 16), inner_rect)
    pygame.draw.rect(SCREEN, (70, 32, 60), inner_rect, 1)

    # 대각선 패턴 (수리검 자국 느낌)
    pattern = pygame.Surface((gauge_width, gauge_height), pygame.SRCALPHA)
    for offset in range(-gauge_height, gauge_width + gauge_height, 6):
        pygame.draw.line(pattern, (120, 120, 140, 40), (offset, gauge_height), (offset + gauge_height, 0), 2)
    SCREEN.blit(pattern, (gauge_x, gauge_y))

    gauge_ratio = min(current_gauge / max_gauge, 1.0)
    filled_height = int(gauge_height * gauge_ratio)

    if filled_height > 0:
        for i in range(filled_height):
            row_ratio = i / max(1, filled_height - 1)
            r = int(70 + 120 * row_ratio)
            g = int(24 + 40 * (1 - row_ratio))
            b = int(120 + 80 * (1 - row_ratio))
            y_pos = gauge_y + gauge_height - i - 1
            pygame.draw.line(SCREEN, (r, g, b), (gauge_x + 2, y_pos), (gauge_x + gauge_width - 3, y_pos))

        # 상단 파도 라인 (연막 흐름)
        wave_top = gauge_y + gauge_height - filled_height
        shimmer = 0.55 + 0.45 * math.sin(time_now * 0.02)
        wave_color = (int(80 + 90 * shimmer), int(180 * shimmer), int(180 + 40 * shimmer))
        pygame.draw.line(SCREEN, wave_color, (gauge_x + 1, wave_top), (gauge_x + gauge_width - 2, wave_top), 1)

        # 연막 입자
        for idx in range(3):
            t = (time_now * 0.001 + idx * 0.33) % 1.0
            smoke_y = gauge_y + gauge_height - int(filled_height * t) - 4
            if gauge_y < smoke_y < gauge_y + gauge_height - 2:
                smoke_x = gauge_x + gauge_width // 2 + int(math.sin(time_now * 0.005 + idx) * 3)
                radius = 3 + int(2 * (1 - t))
                alpha = int(70 * (1 - t))
                smoke = pygame.Surface((radius * 2, radius * 2), pygame.SRCALPHA)
                pygame.draw.circle(smoke, (140, 140, 150, alpha), (radius, radius), radius)
                SCREEN.blit(smoke, (smoke_x - radius, smoke_y - radius))

        # 게이지 충전 펄스
        if boss_special_gauge > current_gauge:
            gain_ratio = min((boss_special_gauge - current_gauge) / 80, 1.0)
            pulse_y = wave_top + int((math.sin(time_now * 0.018) * 0.5 + 0.5) * max(1, filled_height - 6))
            pulse_color = (
                int(100 + 100 * gain_ratio),
                int(180 + 50 * gain_ratio),
                int(190 + 50 * gain_ratio)
            )
            pygame.draw.line(SCREEN, pulse_color, (gauge_x + 2, pulse_y), (gauge_x + gauge_width - 3, pulse_y), 1)

        # 준비 완료 효과
        if current_gauge >= 350:
            glow = pygame.Surface((gauge_width, 6), pygame.SRCALPHA)
            alpha = int(120 + 80 * math.sin(time_now * 0.012))
            glow.fill((220, 90, 140, alpha))
            SCREEN.blit(glow, (gauge_x, wave_top - 2))

    # 엠블럼: 회전 수리검 + 눈동자
    emblem_x = gauge_x + gauge_width // 2
    emblem_y = gauge_y - 30
    rot = time_now * 0.01
    star_points = []
    long_r = 15
    short_r = 7
    for i in range(8):
        angle = rot + i * math.pi / 4
        radius = long_r if i % 2 == 0 else short_r
        star_points.append((emblem_x + math.cos(angle) * radius, emblem_y + math.sin(angle) * radius))
    pygame.draw.polygon(SCREEN, (50, 90, 120), star_points)
    pygame.draw.polygon(SCREEN, (150, 210, 220), star_points, 2)

    eye_radius = 6
    eye_surface = pygame.Surface((eye_radius * 4, eye_radius * 2 + 2), pygame.SRCALPHA)
    pygame.draw.ellipse(eye_surface, (20, 20, 30, 160), (0, 0, eye_radius * 4, eye_radius * 2 + 2))
    pygame.draw.ellipse(eye_surface, (220, 80, 110, 220), (1, 2, eye_radius * 4 - 2, eye_radius * 2 - 2))
    pupil_x = eye_surface.get_width() // 2 + int(math.sin(time_now * 0.006) * 2)
    pygame.draw.circle(eye_surface, (10, 10, 14), (pupil_x, eye_surface.get_height() // 2), 3)
    SCREEN.blit(eye_surface, (emblem_x - eye_surface.get_width() // 2, emblem_y - eye_surface.get_height() // 2))

    ring_radius = 18 + int(2 * math.sin(time_now * 0.012))
    ring_surface = pygame.Surface((ring_radius * 2 + 4, ring_radius * 2 + 4), pygame.SRCALPHA)
    pygame.draw.circle(ring_surface, (90, 150, 190, 70), (ring_radius + 2, ring_radius + 2), ring_radius, 2)
    SCREEN.blit(ring_surface, (emblem_x - ring_radius - 2, emblem_y - ring_radius - 2))

    # 게이지 수치
    gauge_font = FontStyle.tiny()
    gauge_text = f"{int(current_gauge)}/{max_gauge}"
    gauge_surface = gauge_font.render(gauge_text, True, (150, 110, 170))
    gauge_rect = gauge_surface.get_rect(centerx=gauge_x + gauge_width // 2, top=gauge_y + gauge_height + 24)
    SCREEN.blit(gauge_surface, gauge_rect)


# === 스테이지 8 초각성 바람 오오라 시스템 함수 ===
def start_stage8_wind_burst() -> None:
    """초각성 돌입 시 바람 오오라 폭발 애니메이션 시작."""
    global stage8_wind_burst_active, stage8_wind_burst_start_ms, stage8_wind_burst_particles
    global stage8_wind_aura_active, stage8_wind_aura_particles

    stage8_wind_burst_active = True
    stage8_wind_burst_start_ms = pygame.time.get_ticks()
    stage8_wind_burst_particles = []

    # 보스 중심에서 폭발하는 파티클 생성
    boss_cx = BOSS.centerx
    boss_cy = BOSS.centery

    for i in range(STAGE8_WIND_BURST_PARTICLE_COUNT):
        angle = random.uniform(0, math.tau)
        speed = random.uniform(8, 25)
        size = random.randint(4, 12)
        # 청록색/하늘색 계열 바람 색상
        color_choice = random.choice([
            (100, 220, 255),  # 하늘색
            (150, 255, 200),  # 민트색
            (200, 240, 255),  # 흰 하늘
            (80, 200, 230),   # 청록
            (120, 180, 255),  # 파랑
        ])
        stage8_wind_burst_particles.append({
            "x": boss_cx,
            "y": boss_cy,
            "vx": math.cos(angle) * speed,
            "vy": math.sin(angle) * speed,
            "alpha": 255,
            "size": size,
            "color": color_choice,
            "rotation": random.uniform(0, 360),
            "rot_speed": random.uniform(-15, 15),
        })

    # 지속적인 오오라도 활성화
    stage8_wind_aura_active = True
    _init_stage8_wind_aura_particles()


def _init_stage8_wind_aura_particles() -> None:
    """바람 오오라 파티클 초기화."""
    global stage8_wind_aura_particles
    stage8_wind_aura_particles = []

    for i in range(STAGE8_WIND_AURA_PARTICLE_COUNT):
        angle = (i / STAGE8_WIND_AURA_PARTICLE_COUNT) * math.tau
        radius = random.uniform(50, 80)
        size = random.randint(3, 8)
        speed = random.uniform(0.02, 0.05)  # 회전 속도
        color_choice = random.choice([
            (100, 220, 255, 150),
            (150, 255, 200, 130),
            (200, 240, 255, 140),
            (80, 200, 230, 160),
        ])
        stage8_wind_aura_particles.append({
            "angle": angle,
            "radius": radius,
            "base_radius": radius,
            "size": size,
            "speed": speed,
            "color": color_choice,
            "phase": random.uniform(0, math.tau),
        })


def update_stage8_wind_effects() -> None:
    """바람 오오라 효과 업데이트."""
    global stage8_wind_burst_active, stage8_wind_burst_particles
    global stage8_wind_aura_particles, stage8_wind_aura_active

    now_ms = pygame.time.get_ticks()

    # 폭발 파티클 업데이트
    if stage8_wind_burst_active:
        elapsed = now_ms - stage8_wind_burst_start_ms
        if elapsed > STAGE8_WIND_BURST_DURATION_MS:
            stage8_wind_burst_active = False
            stage8_wind_burst_particles = []
        else:
            progress = elapsed / STAGE8_WIND_BURST_DURATION_MS
            new_particles = []
            for p in stage8_wind_burst_particles:
                # 속도 감속
                p["vx"] *= 0.94
                p["vy"] *= 0.94
                p["x"] += p["vx"]
                p["y"] += p["vy"]
                p["rotation"] += p["rot_speed"]
                # 알파 페이드아웃
                p["alpha"] = int(255 * (1 - progress))
                p["size"] = max(1, p["size"] * 0.98)
                if p["alpha"] > 10:
                    new_particles.append(p)
            stage8_wind_burst_particles = new_particles

    # 지속 오오라 파티클 업데이트
    if stage8_wind_aura_active and stage8_awakened:
        for p in stage8_wind_aura_particles:
            p["angle"] += p["speed"]
            # 반경 펄싱
            p["radius"] = p["base_radius"] + math.sin(now_ms * 0.003 + p["phase"]) * 10


def draw_stage8_wind_burst(surface: pygame.Surface) -> None:
    """초각성 폭발 파티클 렌더링."""
    if not stage8_wind_burst_active:
        return

    for p in stage8_wind_burst_particles:
        if p["alpha"] <= 0:
            continue

        size = int(p["size"])
        if size < 1:
            continue

        # 바람 파티클 (회전하는 마름모/별 형태)
        particle_surf = pygame.Surface((size * 3, size * 3), pygame.SRCALPHA)
        cx, cy = size * 1.5, size * 1.5

        # 마름모 형태의 바람 입자
        r, g, b = p["color"]
        alpha = min(255, p["alpha"])

        # 회전된 마름모
        angle_rad = math.radians(p["rotation"])
        points = []
        for i in range(4):
            a = angle_rad + i * math.pi / 2
            dist = size if i % 2 == 0 else size * 0.4
            points.append((cx + math.cos(a) * dist, cy + math.sin(a) * dist))

        pygame.draw.polygon(particle_surf, (r, g, b, alpha), points)
        pygame.draw.polygon(particle_surf, (255, 255, 255, alpha // 2), points, 1)

        surface.blit(particle_surf, (int(p["x"] - cx), int(p["y"] - cy)))


def draw_stage8_wind_aura(surface: pygame.Surface) -> None:
    """초각성 지속 바람 오오라 렌더링 (보스 패들 주변)."""
    global stage8_wind_aura_particles, stage8_wind_aura_ripple_active

    if not stage8_wind_aura_active or not stage8_awakened:
        return

    # 오오라가 소진된 상태면 그리지 않음
    if stage8_wind_aura_depleted:
        return

    boss_cx = BOSS.centerx
    boss_cy = BOSS.centery
    now_ms = pygame.time.get_ticks()

    # 바람 오오라 강도 (타격 횟수에 따라 약해짐)
    aura_strength = get_wind_aura_strength()
    ripple_intensity = get_wind_aura_ripple_intensity()

    # 출렁임 애니메이션 종료 체크
    if stage8_wind_aura_ripple_active:
        elapsed = now_ms - stage8_wind_aura_ripple_start_ms
        if elapsed >= STAGE8_WIND_AURA_RIPPLE_DURATION_MS:
            stage8_wind_aura_ripple_active = False

    # 바람 회오리 기본 원형 오오라
    aura_surface = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)

    # 극정호신(구 초신가속) 상태에 따른 색상 설정
    if stage8_superspeed_active:
        # 주황빛 색상 (극정호신)
        glow_color = (255, 150, 50)  # 주황 글로우
        stream_color_base = (255, 180, 80)  # 주황 스트림
        ring_color_main = (255, 150, 50)  # 주황 링
        ring_color_sub = (255, 200, 100)  # 밝은 주황 링
    else:
        # 기본 시안/청록 색상
        glow_color = (100, 220, 255)  # 시안 글로우
        stream_color_base = (150, 240, 255)  # 시안 스트림
        ring_color_main = (100, 220, 255)  # 시안 링
        ring_color_sub = (150, 255, 200)  # 민트 링

    # 출렁임 효과: 반경 확장/수축
    ripple_offset = int(ripple_intensity * 20 * math.sin(now_ms * 0.02))

    # 1. 내부 글로우 (보스 주변 빛나는 효과) - 강도에 따라 약해짐
    glow_radius = 70 + int(math.sin(now_ms * 0.005) * 8) + ripple_offset
    glow_alpha_mult = aura_strength  # 강도에 따라 투명도 조절
    for r in range(glow_radius, glow_radius - 30, -5):
        alpha = int(40 * (1 - (glow_radius - r) / 30) * glow_alpha_mult)
        pygame.draw.circle(aura_surface, (*glow_color, alpha), (boss_cx, boss_cy), r, 2)

    # 2. 회전하는 바람 스트림 라인 - 강도에 따라 스트림 수 감소
    num_streams = max(2, int(6 * aura_strength))  # 최소 2개
    stream_length = 60
    for i in range(num_streams):
        base_angle = (i / num_streams) * math.tau + now_ms * 0.003
        # 출렁임 효과: 각도 흔들림
        if ripple_intensity > 0:
            base_angle += math.sin(now_ms * 0.015 + i) * ripple_intensity * 0.3
        for j in range(8):
            seg_angle = base_angle + j * 0.12
            seg_radius = 45 + j * 8 + ripple_offset * 0.5
            x1 = boss_cx + math.cos(seg_angle) * seg_radius
            y1 = boss_cy + math.sin(seg_angle) * seg_radius
            x2 = boss_cx + math.cos(seg_angle + 0.1) * (seg_radius + 6)
            y2 = boss_cy + math.sin(seg_angle + 0.1) * (seg_radius + 6)
            alpha = int(120 * (1 - j / 8) * aura_strength)
            color = (*stream_color_base, alpha)
            pygame.draw.line(aura_surface, color, (x1, y1), (x2, y2), 2)

    # 3. 회전하는 파티클들 - 강도에 따라 파티클 표시 개수 조절
    visible_particles = int(len(stage8_wind_aura_particles) * aura_strength)
    for idx, p in enumerate(stage8_wind_aura_particles):
        # 강도에 따라 일부 파티클만 표시
        if idx >= visible_particles:
            continue

        # 출렁임 효과: 반경 변동
        particle_radius = p["radius"]
        if ripple_intensity > 0:
            particle_radius += math.sin(now_ms * 0.02 + p["phase"]) * ripple_intensity * 15

        px = boss_cx + math.cos(p["angle"]) * particle_radius
        py = boss_cy + math.sin(p["angle"]) * particle_radius

        # 강도에 따라 파티클 크기 감소
        size = max(1, int(p["size"] * aura_strength))

        # 극정호신 상태에서 파티클 색상도 주황빛으로 변경
        if stage8_superspeed_active:
            # 주황빛 파티클 색상
            particle_colors = [
                (255, 180, 100),  # 밝은 주황
                (255, 140, 60),   # 주황
                (255, 200, 120),  # 연한 주황
                (255, 160, 80),   # 중간 주황
            ]
            color_idx = hash((p["angle"], p["base_radius"])) % len(particle_colors)
            r, g, b = particle_colors[color_idx]
            a = int(p["color"][3] * aura_strength)  # 강도에 따라 알파값 조절
        else:
            r, g, b, base_a = p["color"]
            a = int(base_a * aura_strength)

        # 꼬리 효과
        tail_len = max(1, int(3 * aura_strength))
        for t in range(tail_len):
            tail_angle = p["angle"] - p["speed"] * (t + 1) * 3
            tail_radius = particle_radius - t * 2
            tx = boss_cx + math.cos(tail_angle) * tail_radius
            ty = boss_cy + math.sin(tail_angle) * tail_radius
            tail_alpha = int(a * (1 - t / tail_len) * 0.5)
            tail_size = max(1, size - t)
            pygame.draw.circle(aura_surface, (r, g, b, tail_alpha), (int(tx), int(ty)), tail_size)

        # 메인 파티클
        pygame.draw.circle(aura_surface, (r, g, b, a), (int(px), int(py)), size)
        if size > 1:
            pygame.draw.circle(aura_surface, (255, 255, 255, a // 2), (int(px), int(py)), size, 1)

    # 4. 외곽 펄싱 링 - 강도에 따라 투명도 및 크기 조절
    outer_ring_radius = int((90 + int(math.sin(now_ms * 0.004) * 5) + ripple_offset) * (0.7 + 0.3 * aura_strength))
    ring_alpha = int((60 + 30 * math.sin(now_ms * 0.006)) * aura_strength)
    if ring_alpha > 5:
        pygame.draw.circle(aura_surface, (*ring_color_main, ring_alpha), (boss_cx, boss_cy), outer_ring_radius, 2)
        pygame.draw.circle(aura_surface, (*ring_color_sub, ring_alpha // 2), (boss_cx, boss_cy), outer_ring_radius + 5, 1)

    # 출렁임 시 추가 이펙트: 충격파 링
    if ripple_intensity > 0.1:
        shock_radius = int(STAGE8_WIND_AURA_RADIUS * (1 + ripple_intensity * 0.5))
        shock_alpha = int(100 * ripple_intensity)
        pygame.draw.circle(aura_surface, (255, 255, 255, shock_alpha), (boss_cx, boss_cy), shock_radius, 3)

    surface.blit(aura_surface, (0, 0))


def reset_stage8_wind_effects() -> None:
    """바람 오오라 효과 초기화 (스테이지 전환/게임 오버 시)."""
    global stage8_wind_aura_active, stage8_wind_aura_particles
    global stage8_wind_burst_active, stage8_wind_burst_particles
    global stage8_afterimage_ghosts
    global stage8_wind_aura_hit_count, stage8_wind_aura_depleted
    global stage8_wind_aura_recharge_start_ms, stage8_wind_aura_ripple_active
    global stage8_wind_aura_hit_cooldown_ms

    stage8_wind_aura_active = False
    stage8_wind_aura_particles = []
    stage8_wind_burst_active = False
    stage8_wind_burst_particles = []
    stage8_afterimage_ghosts = []
    stage8_wind_aura_hit_count = 0
    stage8_wind_aura_depleted = False
    stage8_wind_aura_recharge_start_ms = 0
    stage8_wind_aura_ripple_active = False
    stage8_wind_aura_hit_cooldown_ms = 0


def check_wind_aura_ball_collision(ball_rect: pygame.Rect) -> bool:
    """공과 바람 오오라의 충돌 감지 및 처리.

    Returns:
        bool: 충돌이 발생하고 공이 튕겨나가야 하면 True
    """
    global stage8_wind_aura_hit_count, stage8_wind_aura_depleted
    global stage8_wind_aura_ripple_active, stage8_wind_aura_ripple_start_ms
    global stage8_wind_aura_hit_cooldown_ms, stage8_wind_aura_active
    global stage8_wind_aura_recharge_start_ms
    global boss_special_gauge, boss_special_ready, last_hit_by

    # 바람 오오라가 비활성이거나 소진된 상태면 처리하지 않음
    if not stage8_wind_aura_active or stage8_wind_aura_depleted:
        return False

    # 초각성 상태가 아니면 처리하지 않음
    if not stage8_awakened:
        return False

    now_ms = pygame.time.get_ticks()

    # 보스가 마지막으로 친 공(혹은 보스 서브 공)은 오오라에 맞지 않도록 제외
    ball_owner = getattr(game_vars.ball, "last_hit_by", last_hit_by)
    if ball_owner == "boss":
        return False

    # 쿨다운 중이면 충돌 무시 (연속 타격 방지)
    if now_ms < stage8_wind_aura_hit_cooldown_ms:
        return False

    # 보스 중심과 공 중심 사이의 거리 계산
    boss_cx = BOSS.centerx
    boss_cy = BOSS.centery
    ball_cx = ball_rect.centerx
    ball_cy = ball_rect.centery

    dist = math.sqrt((ball_cx - boss_cx) ** 2 + (ball_cy - boss_cy) ** 2)

    # 바람 오오라 범위 내에 공이 있는지 확인
    if dist <= STAGE8_WIND_AURA_RADIUS:
        # 타격 카운트 증가
        stage8_wind_aura_hit_count += 1

        # 출렁임 애니메이션 시작
        stage8_wind_aura_ripple_active = True
        stage8_wind_aura_ripple_start_ms = now_ms

        # 오오라가 공을 막을 때 사운드 재생
        try:
            play_sound_with_volume(SOUND_NINJA_SHIELD)
        except Exception:
            pass

        # 쿨다운 설정 (0.3초)
        stage8_wind_aura_hit_cooldown_ms = now_ms + 300

        # 초각성 오오라로 공을 막으면 보스 게이지 획득
        try:
            boss_special_gauge = min(500, boss_special_gauge + 90)
            boss_special_ready = boss_special_gauge >= STAGE8_SUPERSPEED_COST
        except Exception:
            pass

        # 30% 확률로 즉시 스킬 트리거 (쿨·게이지 무시)
        try:
            if random.random() < 0.30 and not stage8_cloud_dash_active and not stage8_cloud_active:
                _start_stage8_cloud(now_ms)
            if random.random() < 0.30 and not stage8_shadow_casting and not stage8_shadow_clones:
                stage8_shadow_casting = True
                stage8_shadow_cast_start_ms = now_ms
                stage8_shadow_freeze_posx = BOSS.centerx
                stage8_shadow_freeze_posy = BOSS.centery
        except Exception:
            pass

        # 5회 타격 시 오오라 소진
        if stage8_wind_aura_hit_count >= stage8_wind_aura_max_hits:
            stage8_wind_aura_depleted = True
            stage8_wind_aura_recharge_start_ms = now_ms
            # 소진 시 파티클 효과 (흩어지는 효과)
            _create_wind_aura_disperse_effect()

        return True

    return False


def _create_wind_aura_disperse_effect() -> None:
    """바람 오오라가 소진될 때 흩어지는 이펙트 생성."""
    global stage8_wind_burst_particles, stage8_wind_burst_active, stage8_wind_burst_start_ms

    stage8_wind_burst_active = True
    stage8_wind_burst_start_ms = pygame.time.get_ticks()
    stage8_wind_burst_particles = []

    boss_cx = BOSS.centerx
    boss_cy = BOSS.centery

    # 흩어지는 파티클 생성 (소진 효과)
    for i in range(32):
        angle = random.uniform(0, math.tau)
        speed = random.uniform(5, 15)
        size = random.randint(2, 6)
        color_choice = random.choice([
            (100, 220, 255),
            (150, 255, 200),
            (200, 240, 255),
        ])
        stage8_wind_burst_particles.append({
            "x": boss_cx + math.cos(angle) * random.uniform(30, STAGE8_WIND_AURA_RADIUS),
            "y": boss_cy + math.sin(angle) * random.uniform(30, STAGE8_WIND_AURA_RADIUS),
            "vx": math.cos(angle) * speed,
            "vy": math.sin(angle) * speed,
            "alpha": 180,
            "size": size,
            "color": color_choice,
            "rotation": random.uniform(0, 360),
            "rot_speed": random.uniform(-10, 10),
        })


def update_wind_aura_recharge() -> None:
    """바람 오오라 재충전 로직 업데이트."""
    global stage8_wind_aura_depleted, stage8_wind_aura_hit_count
    global stage8_wind_aura_active, stage8_wind_aura_recharge_start_ms
    global stage8_wind_aura_ripple_active

    if not stage8_wind_aura_depleted:
        return

    now_ms = pygame.time.get_ticks()

    # 10초 후 재충전 완료
    if now_ms >= stage8_wind_aura_recharge_start_ms + STAGE8_WIND_AURA_RECHARGE_MS:
        stage8_wind_aura_depleted = False
        stage8_wind_aura_hit_count = 0
        stage8_wind_aura_ripple_active = False
        # 파티클 재초기화
        _init_stage8_wind_aura_particles()


def get_wind_aura_strength() -> float:
    """현재 바람 오오라 강도 (0.0 ~ 1.0).

    타격 횟수에 따라 점점 약해짐.
    """
    if stage8_wind_aura_depleted:
        return 0.0

    # 5회 중 남은 횟수에 비례
    remaining = stage8_wind_aura_max_hits - stage8_wind_aura_hit_count
    return remaining / stage8_wind_aura_max_hits


def get_wind_aura_ripple_intensity() -> float:
    """출렁임 애니메이션 강도 (0.0 ~ 1.0)."""
    if not stage8_wind_aura_ripple_active:
        return 0.0

    now_ms = pygame.time.get_ticks()
    elapsed = now_ms - stage8_wind_aura_ripple_start_ms

    if elapsed >= STAGE8_WIND_AURA_RIPPLE_DURATION_MS:
        return 0.0

    # 빠르게 시작해서 서서히 감소
    progress = elapsed / STAGE8_WIND_AURA_RIPPLE_DURATION_MS
    return math.sin(progress * math.pi) * (1 - progress * 0.5)


def spawn_stage8_afterimage_ghosts() -> None:
    """극정호신 대쉬 시 환영 분신 생성."""
    global stage8_afterimage_ghosts

    if not stage8_superspeed_active:
        return

    now_ms = pygame.time.get_ticks()
    boss_x = BOSS.centerx
    boss_y = BOSS.centery

    # 여러 겹의 환영 생성 (시간차로 따라오도록)
    for i in range(STAGE8_AFTERIMAGE_COUNT):
        stage8_afterimage_ghosts.append({
            "x": boss_x,
            "y": boss_y,
            "target_x": boss_x,
            "target_y": boss_y,
            "spawn_ms": now_ms + i * STAGE8_AFTERIMAGE_DELAY_MS,
            "alpha": 180 - i * 25,  # 뒤로 갈수록 점점 투명
            "index": i,
        })


def update_stage8_afterimage_ghosts() -> None:
    """극정호신 환영 분신 업데이트 (천천히 보스를 따라다님)."""
    global stage8_afterimage_ghosts

    if not stage8_afterimage_ghosts:
        return

    now_ms = pygame.time.get_ticks()
    boss_x = BOSS.centerx
    boss_y = BOSS.centery

    new_ghosts = []
    for ghost in stage8_afterimage_ghosts:
        # 아직 스폰 시간이 안 됐으면 그대로 유지
        if now_ms < ghost["spawn_ms"]:
            new_ghosts.append(ghost)
            continue

        elapsed = now_ms - ghost["spawn_ms"]

        # 페이드아웃 시간이 지나면 제거
        if elapsed > STAGE8_AFTERIMAGE_FADE_MS:
            continue

        # 환영이 보스를 천천히 따라감 (인덱스가 클수록 더 느리게)
        follow_speed = 0.08 - ghost["index"] * 0.012
        follow_speed = max(0.02, follow_speed)

        ghost["x"] += (boss_x - ghost["x"]) * follow_speed
        ghost["y"] += (boss_y - ghost["y"]) * follow_speed

        # 알파값 페이드아웃
        fade_progress = elapsed / STAGE8_AFTERIMAGE_FADE_MS
        ghost["alpha"] = int((180 - ghost["index"] * 25) * (1 - fade_progress))

        if ghost["alpha"] > 5:
            new_ghosts.append(ghost)

    stage8_afterimage_ghosts = new_ghosts


def draw_stage8_afterimage_ghosts(surface: pygame.Surface) -> None:
    """극정호신 환영 분신 렌더링."""
    global stage8_afterimage_ghosts

    if not stage8_afterimage_ghosts:
        return

    now_ms = pygame.time.get_ticks()

    # 보스 이미지 가져오기
    try:
        boss_img = BOSS_IMG_STAGE8
    except Exception:
        return

    if boss_img is None:
        return

    for ghost in stage8_afterimage_ghosts:
        # 아직 스폰 시간이 안 됐으면 건너뜀
        if now_ms < ghost["spawn_ms"]:
            continue

        alpha = ghost["alpha"]
        if alpha <= 0:
            continue

        # 환영 이미지 생성 (주황빛 틴트 + 반투명)
        ghost_surf = boss_img.copy()
        ghost_surf.set_alpha(alpha)

        # 주황빛 오버레이 추가
        overlay = pygame.Surface(ghost_surf.get_size(), pygame.SRCALPHA)
        overlay.fill((255, 120, 30, min(80, alpha // 2)))
        ghost_surf.blit(overlay, (0, 0), special_flags=pygame.BLEND_RGBA_ADD)

        # 위치 계산
        rect = ghost_surf.get_rect(center=(int(ghost["x"]), int(ghost["y"])))
        surface.blit(ghost_surf, rect)


def _spawn_stage8_shadows(now: int) -> None:
    """아카무 리고 그림자분신 생성 (일반 2개, 초각성 시 4개)."""
    global stage8_shadow_clones, stage8_shadow_casting, stage8_shadow_next_ready_ms, stage8_awakened
    base_x = stage8_shadow_freeze_posx or BOSS.centerx
    base_y = (stage8_shadow_freeze_posy or BOSS.centery) + STAGE8_SHADOW_Y_OFFSET
    stage8_shadow_clones = []
    offsets = [-120, -60, 60, 120] if stage8_awakened else [-90, 90]
    for offset in offsets:
        direction = -1 if offset < 0 else 1
        # 실제 보스8 이미지 크기와 동일하게 설정
        rect = pygame.Rect(0, 0, BOSS_IMG_STAGE8_WIDTH, BOSS_IMG_STAGE8_HEIGHT)
        rect.center = (base_x, base_y)
        stage8_shadow_clones.append(
            {
                "rect": rect,
                "spawn_ms": now,
                "base_x": base_x,
                "base_y": base_y,
                "direction": direction,
                "offset_x": offset,
                "offset_y": 0,
                "vx": random.uniform(7.5, 12.0) * direction,
                "vy": 0.0,
            }
        )
    stage8_shadow_casting = False
    stage8_shadow_next_ready_ms = now + STAGE8_SHADOW_COOLDOWN_MS

    # 그림자분신 발동 사운드 재생
    try:
        _kuro_spawn_path = resource_path(os.path.join("sounds", "kurokake.wav"))
        if os.path.exists(_kuro_spawn_path):
            pygame.mixer.Sound(_kuro_spawn_path).play()
    except Exception:
        pass


def _spawn_stage8_shuriken(now: int) -> None:
    """표창 1개를 플레이어 방향으로 발사."""
    global stage8_shurikens, stage8_shuriken_casting, stage8_shuriken_next_ready_ms
    global stage8_shuriken_pending, stage8_awakened, stage8_shuriken_from_pending
    target_x = PLAYER.centerx
    target_y = PLAYER.centery
    dx = target_x - BOSS.centerx
    dy = target_y - BOSS.centery
    length = math.hypot(dx, dy) or 1.0
    vx = dx / length * STAGE8_SHURIKEN_SPEED
    vy = dy / length * STAGE8_SHURIKEN_SPEED
    rect = pygame.Rect(0, 0, 18, 10)
    rect.center = (BOSS.centerx, BOSS.centery)
    stage8_shurikens.append(
        {"rect": rect, "vx": vx, "vy": vy, "spawn_ms": now}
    )
    # 표창 던질 때 히트 애니메이션 트리거 (플레이어 방향으로)
    try:
        if stage8_boss_sprite:
            stage8_boss_sprite.trigger_hit(target_x, BOSS.centerx)
    except Exception:
        pass
    try:
        play_sound_with_volume(SOUND_SHURIKEN_SHOOT)
    except Exception:
        pass
    stage8_shuriken_casting = False
    stage8_shuriken_next_ready_ms = now + random.randint(
        STAGE8_SHURIKEN_MIN_COOLDOWN_MS, STAGE8_SHURIKEN_MAX_COOLDOWN_MS
    )
    # 초각성 시 0.2초 후 추가 발사 1회 예약 (본 발사 시에만)
    if stage8_awakened and not stage8_shuriken_from_pending:
        stage8_shuriken_pending.append(now + 200)


def _start_stage8_cloud(now: int) -> None:
    """구름장막 발동: 보스가 내려와서 터뜨릴 준비."""
    global stage8_cloud_dash_active, stage8_cloud_dash_phase, stage8_cloud_dash_start_ms
    global stage8_cloud_origin, stage8_cloud_target_y, stage8_cloud_start_ms, stage8_cloud_end_ms
    global stage8_cloud_rect, stage8_cloud_active, stage8_cloud_next_ready_ms, stage8_cloud_precast_ms, stage8_cloud_spawn_pos
    mid_x = WIDTH // 2
    stage8_cloud_origin = (mid_x, BOSS.centery)
    BOSS.centerx = mid_x
    stage8_cloud_target_y = max(BOSS.centery, PLAYER.centery - 40)
    stage8_cloud_spawn_pos = stage8_cloud_origin
    stage8_cloud_dash_active = True
    stage8_cloud_dash_phase = "pre"  # 0.4초 정지 + 오로라
    stage8_cloud_precast_ms = now
    stage8_cloud_dash_start_ms = now
    stage8_cloud_active = False
    stage8_cloud_rect = None
    stage8_cloud_next_ready_ms = now + random.randint(
        STAGE8_CLOUD_MIN_COOLDOWN_MS, STAGE8_CLOUD_MAX_COOLDOWN_MS
    )
    stage8_cloud_midstay_end_ms = 0


def _finish_stage8_cloud(now: int) -> None:
    """구름 폭발 및 지속 타이머 시작."""
    global stage8_cloud_active, stage8_cloud_start_ms, stage8_cloud_end_ms, stage8_cloud_rect
    global stage8_cloud_spawn_pos
    stage8_cloud_active = True
    stage8_cloud_start_ms = now
    stage8_cloud_end_ms = now + STAGE8_CLOUD_VISIBLE_MS + stage8_cloud_fade_ms + STAGE8_CLOUD_EXPAND_MS
    width = 235   # 336 * 0.7 = 235 (30% 추가 축소)
    height = 56   # 80 * 0.7 = 56 (30% 추가 축소)
    stage8_cloud_rect = pygame.Rect(0, 0, width, height)
    cx, cy = stage8_cloud_spawn_pos if stage8_cloud_spawn_pos != (0, 0) else (BOSS.centerx, BOSS.centery)
    cy += 80  # 구름 위치를 아래로 80픽셀 이동 (상단 구름 잘림 방지)
    stage8_cloud_rect.center = (cx, cy)


def _is_stage8_net_trapped() -> bool:
    """코만도 그물덫총에 보스가 포획되어 있는지 여부."""
    try:
        from item_effects.net_gun import get_net_gun_instance

        net_gun = get_net_gun_instance()
        return bool(net_gun and net_gun.boss_is_trapped())
    except Exception:
        return False


def _release_stage8_net_trap() -> int:
    """그물덫총 포획 상태 해제; 제거된 그물 수를 반환."""
    removed = 0
    try:
        from item_effects.net_gun import get_net_gun_instance

        net_gun = get_net_gun_instance()
        if net_gun and getattr(net_gun, "nets", None) is not None:
            new_nets = []
            for net in net_gun.nets:
                if net.get("boss_trapped"):
                    removed += 1
                    continue
                new_nets.append(net)
            net_gun.nets = new_nets
        if removed and "net_capture_animation_start_time" in globals():
            globals()["net_capture_animation_start_time"] = None
    except Exception:
        pass
    return removed


def _end_stage8_superspeed() -> None:
    """극정호신(구 초신가속) 종료 및 상태 초기화."""
    global stage8_superspeed_active, stage8_superspeed_end_ms, stage8_superspeed_text_end_ms, stage8_superspeed_freeze_end_ms
    global stage8_superspeed_cooldown_end_ms
    global boss_dash_cooldown_until_ms, boss_dash_cooldown_total_ms
    stage8_superspeed_active = False
    stage8_superspeed_cooldown_end_ms = pygame.time.get_ticks() + STAGE8_SUPERSPEED_COOLDOWN_MS
    stage8_superspeed_end_ms = 0
    stage8_superspeed_text_end_ms = 0
    stage8_superspeed_freeze_end_ms = 0
    boss_dash_cooldown_until_ms = 0
    boss_dash_cooldown_total_ms = 0
    # 극정호신 종료 시 즉시 대쉬를 막기 위해 대쉬 상태도 초기화
    globals()["boss_dashing"] = False
    globals()["boss_dash_timer"] = 0
    # 극정호신 어둠 기운 파티클 및 잔상 초기화
    try:
        clear_stage8_superspeed_dark_particles()
        clear_stage8_superspeed_movement_trail()
    except Exception:
        pass


def _start_stage8_superspeed(now: int) -> None:
    """극정호신 발동: 10초간 무제한 대쉬(무료, 확장거리) 상태."""
    global stage8_superspeed_active, stage8_superspeed_end_ms, stage8_superspeed_text_end_ms, stage8_superspeed_freeze_end_ms
    global boss_special_gauge, boss_dash_cooldown_until_ms, boss_dash_cooldown_total_ms, stage8_superspeed_cooldown_end_ms
    global stage8_shadow_casting, stage8_shuriken_casting, stage8_cloud_dash_active, stage8_cloud_active, stage8_cloud_rect
    global stage8_shuriken_cast_start_ms

    boss_special_gauge = max(0, boss_special_gauge - STAGE8_SUPERSPEED_COST)
    stage8_superspeed_active = True
    stage8_superspeed_end_ms = now + STAGE8_SUPERSPEED_DURATION_MS
    stage8_superspeed_text_end_ms = now + STAGE8_SUPERSPEED_TEXT_MS
    stage8_superspeed_freeze_end_ms = now + STAGE8_SUPERSPEED_FREEZE_MS
    boss_dash_cooldown_until_ms = 0
    boss_dash_cooldown_total_ms = 0
    stage8_superspeed_cooldown_end_ms = 0

    # 다른 스킬 중단
    stage8_shadow_casting = False
    stage8_shuriken_casting = False
    stage8_shuriken_cast_start_ms = 0
    stage8_cloud_dash_active = False
    stage8_cloud_active = False
    stage8_cloud_rect = None

    # 메시지는 draw_objects에서 오버레이로 표시


def _stage8_superspeed_dash(now: int) -> None:
    """극정호신 전용 즉시 대쉬. 게이지/쿨타임 소모 없음."""
    global boss_dashing, boss_dash_timer, boss_dash_duration_frames
    global boss_dash_speed, boss_dash_target_x, boss_dash_direction
    global boss_dash_cooldown_until_ms, boss_dash_cooldown_total_ms
    ball_vx = float(ball_vel[0]) if "ball_vel" in globals() else 0.0
    ball_vy = float(ball_vel[1]) if "ball_vel" in globals() else 0.0

    def _predict_x_with_walls(x: float, vx: float, frames: float) -> float:
        if abs(vx) < 1e-3 or frames <= 0:
            return x
        remaining = frames
        x_min = 0.0
        x_max = float(WIDTH)
        for _ in range(4):  # 최대 4번 반사만 고려
            if remaining <= 0:
                break
            t_wall = (x_max - x) / vx if vx > 0 else (x_min - x) / vx if vx < 0 else float("inf")
            if t_wall <= 0 or t_wall >= remaining:
                x += vx * remaining
                remaining = 0
                break
            x += vx * t_wall
            remaining -= t_wall
            vx = -vx
        return max(x_min, min(x_max, x))

    # 보스 라인까지 예상 시간 (프레임) 계산
    dy = float(BALL.centery - BOSS.centery)
    time_to_boss = abs(dy) / max(1.0, abs(ball_vy)) if abs(ball_vy) > 0 else 0.0
    predicted_x = _predict_x_with_walls(float(BALL.centerx), ball_vx, time_to_boss)

    direction = 1 if predicted_x > BOSS.centerx else -1
    raw_distance = abs(predicted_x - BOSS.centerx)
    dash_distance = max(60.0, raw_distance)  # 극정호신: 거리 제한 없음

    target_centerx = predicted_x
    # 게임 영역 내로 제한 (BOSS.width를 동적으로 사용)
    boss_min_cx = BOSS.width // 2
    boss_max_cx = WIDTH - BOSS.width // 2
    target_centerx = float(max(boss_min_cx, min(boss_max_cx, target_centerx)))
    dash_distance = abs(target_centerx - BOSS.centerx)
    if dash_distance < 12:
        return

    boss_dash_direction = direction
    boss_dash_target_x = float(target_centerx)

    # 플레이어와 동일한 고정 속도 40 픽셀/프레임 사용
    estimated_duration = dash_distance / 30.0
    boss_dash_duration_frames = int(max(10.0, min(estimated_duration, 40.0)))
    boss_dash_timer = boss_dash_duration_frames
    boss_dash_speed = 40.0

    boss_dashing = True
    boss_dash_cooldown_until_ms = 0
    boss_dash_cooldown_total_ms = 0
    # 대쉬 후 경직은 STAGE8_SUPERSPEED_DASH_STUN_FRAMES로 상단에서 처리
