                        pygame.draw.circle(_SB, (100, 70, 120, 255), (_sx, _sy), 5)
                        pygame.draw.circle(_SB, (150, 110, 180, 255), (_sx, _sy), 4)
                        pygame.draw.circle(_SB, (120, 40, 180, 255), (_sx, _sy), 3)
