    new_tear_particles = []  #  함수 시작 시 초기화

    # 🏖 모래 지형 그리기 (배경 위, 공 아래) + 녹아내림 연출
    if sand_obstacles:
        if sand_obstacles.dissolving:
            if sand_obstacles.update_dissolve():
                # 녹아내림 완료 → 제거
                sand_obstacles = None
        if sand_obstacles:
            draw_sand_obstacles(SCREEN, sand_obstacles)

    # 전설 아이템 물결 효과 그리기 (업데이트는 물리 루프에서 이미 처리됨)
    legendary_manager = None
    try:
        from legendary_items import get_legendary_manager
        legendary_manager = get_legendary_manager()
        if legendary_manager:
            trident = legendary_manager.get_item("poseidon_trident")
            if trident and trident.active:
                trident.draw_effects(SCREEN)
            # 신성 월계수: 독립 렌더링 제거됨 - 퍽 월계수잎 시스템으로 통합됨
            # 👁 오딘의 눈 어둠의 기운 효과 그리기
            odins_eye = legendary_manager.get_item("odins_eye")
            if odins_eye and odins_eye.active and odins_eye.dark_energy_active:
                odins_eye.draw_dark_energy_effect(SCREEN, PLAYER.centerx, PLAYER.centery)
            # 👻 오딘의 눈 잔상 그리기 (변신 상태에서만)
            if odins_eye and (odins_eye.penalty_active or odins_eye.dark_energy_active):
                odins_eye.draw_afterimages(SCREEN)
            # 🌑 오딘의 눈 대쉬 다이브 이펙트 그리기
            if odins_eye and (odins_eye.penalty_active or odins_eye.dark_energy_active):
                odins_eye.draw_dash_dive_effects(SCREEN)
            # 👁 오딘의 눈 부활 애니메이션 그리기 (폭발 이펙트 포함)
            if odins_eye and (odins_eye.is_revival_animating or odins_eye.dark_burst_active):
                odins_eye.draw_revival_animation(SCREEN)
            # 💀 오딘의 눈 죽음 애니메이션 그리기
            if odins_eye and odins_eye.is_death_animating:
                odins_eye.draw_death_animation(SCREEN)
            # 👁 오딘의 눈 어둠의 늪 가시 그리기
            if odins_eye and (odins_eye.dark_swamp_active or len(getattr(odins_eye, 'lurker_spikes', [])) > 0):
                odins_eye.draw_lurker_spikes(SCREEN)
            # 👁 오딘의 눈 어둠 파편 그리기
            if odins_eye and len(getattr(odins_eye, 'dark_fragments', [])) > 0:
                odins_eye.draw_dark_fragments(SCREEN)
    except:
        pass

    # 퍽 월계수잎 효과 그리기 (legendary_manager와 독립적으로 동작)
    if not arena_mode_enabled and perk_leaf_shield and perk_leaf_shield.active:
        perk_leaf_shield.draw(SCREEN)

    # 🏟️ 투기장 영웅 스킬 이펙트 그리기
    if arena_mode_enabled and arena_skill_manager:
        try:
            # 래퍼 객체 생성 (스킬 시스템용)
            class PaddleWrapperDraw:
                def __init__(self, rect, is_top):
                    self.x = rect.x
                    self.y = rect.y
                    self.width = rect.width
                    self.height = rect.height
                    self.centerx = rect.centerx
                    self.centery = rect.centery
                    self.is_top = is_top
            class BallWrapperDraw:
                def __init__(self, rect, vel):
                    self.x = rect.x
                    self.y = rect.y
                    self.width = rect.width
                    self.height = rect.height
                    self.vx = vel[0]
                    self.vy = vel[1]
            top_wrapper = PaddleWrapperDraw(BOSS, True)
            bottom_wrapper = PaddleWrapperDraw(PLAYER, False)
            ball_wrapper = BallWrapperDraw(BALL, ball_vel)
            # 스킬 이펙트 그리기
            arena_skill_manager.draw_skills(SCREEN, top_wrapper, bottom_wrapper, ball_wrapper)
            # 🗡️ 하수인 시스템 그리기 (호위무사 아래 z-order)
            if arena_henchman_system:
                try:
                    arena_henchman_system.draw(SCREEN, top_wrapper, bottom_wrapper, ball_wrapper)
                except Exception as _hench_draw_err:
                    print(f"[Henchman] draw error: {_hench_draw_err}")
            # 🗡️ AI 하수인 시스템 그리기
            if arena_ai_henchman_system:
                try:
                    arena_ai_henchman_system.draw(SCREEN, top_wrapper, bottom_wrapper, ball_wrapper)
                except Exception as _ai_hench_draw_err:
                    print(f"[Henchman] AI draw error: {_ai_hench_draw_err}")
            # 🛡️ 호위무사 시스템 그리기 (캐릭터 + 스킬 이펙트)
            if arena_guard_system:
                try:
                    arena_guard_system.draw(SCREEN, top_wrapper, bottom_wrapper, ball_wrapper)
                except Exception as _guard_draw_err:
                    print(f"[Guard] draw error: {_guard_draw_err}")
            # 화면 효과 그리기 (플래시, 흔들림 등)
            arena_skill_manager.draw_screen_effects(SCREEN)

            # 🔥 도깨비불 공 이펙트 그리기 (Ultra Premium)
            if arena_skill_manager.game_state.get('dokkaebi_ball', False) and BALL:
                _dokkaebi_time = pygame.time.get_ticks() / 1000.0
                _ball_cx, _ball_cy = BALL.centerx, BALL.centery
                _ball_r = BALL.width // 2
                _dt = _dokkaebi_time

                # ── 1. 외곽 대기 오라 (6겹, 넓은 범위 번짐) ──
                for i in range(6):
                    _glow_r = _ball_r + 10 + i * 7
                    _glow_alpha = int(100 - i * 14)
                    _flicker = 0.6 + 0.4 * math.sin(_dt * 10 + i * 1.3)
                    _glow_alpha = int(_glow_alpha * _flicker)
                    if _glow_alpha > 0:
                        _glow_surf = pygame.Surface((_glow_r * 2, _glow_r * 2), pygame.SRCALPHA)
                        # 색상 그라디언트 (층마다 변화)
                        _cr = int(40 + 60 * math.sin(_dt * 4.0 + i * 0.8))
                        _cg = int(160 + 60 * math.sin(_dt * 6.0 + i * 0.5))
                        _cb = 255
                        pygame.draw.circle(_glow_surf, (_cr, _cg, _cb, _glow_alpha), (_glow_r, _glow_r), _glow_r)
                        SCREEN.blit(_glow_surf, (_ball_cx - _glow_r, _ball_cy - _glow_r), special_flags=pygame.BLEND_ADD)

                # ── 2. 외곽 불꽃 실루엣 (크고 흔들리는 외곽 불꽃) ──
                _outer_surf_size = _ball_r * 6
                _outer_surf = pygame.Surface((_outer_surf_size, _outer_surf_size), pygame.SRCALPHA)
                _outer_cx, _outer_cy = _outer_surf_size // 2, _outer_surf_size // 2
                _outer_flame = []
                for _ai in range(24):
                    _rad = math.radians(_ai * 15)
                    _base_dist = _ball_r * (1.6 + 0.5 * math.sin(_dt * 6.0 + _ai * 0.6))
                    # 위쪽으로 길쭉하게 (불꽃 형태)
                    if 3 < _ai < 9:
                        _base_dist *= 1.6 + 0.3 * math.sin(_dt * 9.0 + _ai)
                    # 좌우 약간 넓게
                    _fx = _outer_cx + math.sin(_rad) * _base_dist * 0.85
                    _fy = _outer_cy - math.cos(_rad) * _base_dist
                    _outer_flame.append((_fx, _fy))
                if len(_outer_flame) >= 3:
                    pygame.draw.polygon(_outer_surf, (50, 140, 220, 60), _outer_flame)
                    pygame.draw.polygon(_outer_surf, (70, 170, 245, 40), _outer_flame, 2)
                SCREEN.blit(_outer_surf, (_ball_cx - _outer_cx, _ball_cy - _outer_cy), special_flags=pygame.BLEND_ADD)

                # ── 3. 메인 불꽃 본체 (다층 그라디언트 - 4레이어) ──
                _core_surf_size = _ball_r * 5
                _core_surf = pygame.Surface((_core_surf_size, _core_surf_size), pygame.SRCALPHA)
                _core_cx, _core_cy = _core_surf_size // 2, _core_surf_size // 2

                _flame_layers = [
                    (1.0, 0.85, (80, 190, 255, 140), 18),   # 외곽 - 넓고 반투명
                    (0.82, 0.75, (100, 210, 255, 180), 16),  # 중간1
                    (0.65, 0.6, (140, 230, 255, 210), 14),   # 중간2
                    (0.48, 0.45, (190, 245, 255, 230), 12),  # 내부 - 밝은 코어
                ]
                for _lr, _lr_inner, _lcolor, _lseg in _flame_layers:
                    _layer_pts = []
                    for _li in range(_lseg):
                        _rad = math.radians(_li * (360 / _lseg))
                        _ldist = _ball_r * (_lr + 0.2 * math.sin(_dt * 8.0 + _li * 0.7))
                        if math.degrees(_rad) > 30 and math.degrees(_rad) < 150:
                            _ldist *= 1.5 + 0.2 * math.sin(_dt * 10.0 + _li)
                        _lx = _core_cx + math.sin(_rad) * _ldist * 0.8
                        _ly = _core_cy - math.cos(_rad) * _ldist
                        _layer_pts.append((_lx, _ly))
                    if len(_layer_pts) >= 3:
                        pygame.draw.polygon(_core_surf, _lcolor, _layer_pts)

                # ── 4. 내부 에너지 흐름 (회전하는 나선 패턴) ──
                for _si in range(3):
                    _spiral_pts = []
                    for _sj in range(12):
                        _s_angle = _dt * 4.0 + _si * (math.pi * 2 / 3) + _sj * 0.4
                        _s_dist = _ball_r * (0.3 + _sj * 0.06)
                        _sx = _core_cx + _s_dist * math.cos(_s_angle)
                        _sy = _core_cy + _s_dist * math.sin(_s_angle) * 0.7 - _sj * 1.5
                        _spiral_pts.append((int(_sx), int(_sy)))
                    if len(_spiral_pts) >= 2:
                        _s_alpha = int(60 + 40 * math.sin(_dt * 6.0 + _si * 2.0))
                        pygame.draw.lines(_core_surf, (160, 240, 255, _s_alpha), False, _spiral_pts, 1)

                # ── 5. 중심 코어 (다층 하이라이트) ──
                pygame.draw.circle(_core_surf, (160, 240, 255, 200), (_core_cx, _core_cy), int(_ball_r * 0.7))
                pygame.draw.circle(_core_surf, (200, 250, 255, 240), (_core_cx, _core_cy), int(_ball_r * 0.5))
                pygame.draw.circle(_core_surf, (235, 255, 255, 255), (_core_cx, _core_cy), int(_ball_r * 0.3))
                # 상단 하이라이트 (불꽃 중심 위쪽)
                pygame.draw.circle(_core_surf, (255, 255, 255, 200), (_core_cx, _core_cy - 3), int(_ball_r * 0.2))

                SCREEN.blit(_core_surf, (_ball_cx - _core_cx, _ball_cy - _core_cy), special_flags=pygame.BLEND_ADD)

                # ── 6. 도깨비 형상 (불꽃 속 도깨비 얼굴 실루엣) ──
                _face_pulse = 0.5 + 0.5 * math.sin(_dt * 5.0)
                _face_base_a = int(160 * _face_pulse)
                if _face_base_a > 20:
                    _face_sz = int(_ball_r * 3.5)
                    _face_surf = pygame.Surface((_face_sz * 2, _face_sz * 2), pygame.SRCALPHA)
                    _fcx, _fcy = _face_sz, _face_sz

                    # 뿔 (2개 - 불꽃 위로 솟은 뿔 형상)
                    _horn_a = int(_face_base_a * 0.45)
                    for _hdir in [-1, 1]:
                        pygame.draw.polygon(_face_surf, (100, 220, 255, _horn_a), [
                            (_fcx + _hdir * int(_ball_r * 0.7), _fcy - int(_ball_r * 0.5)),
                            (_fcx + _hdir * int(_ball_r * 1.0), _fcy - int(_ball_r * 1.6) - int(3 * math.sin(_dt * 6.0 + _hdir))),
                            (_fcx + _hdir * int(_ball_r * 0.35), _fcy - int(_ball_r * 0.6)),
                        ])

                    # 얼굴 윤곽 (타원)
                    _face_a = int(_face_base_a * 0.25)
                    _face_w = int(_ball_r * 1.6)
                    _face_h = int(_ball_r * 1.3)
                    pygame.draw.ellipse(_face_surf, (80, 200, 255, _face_a),
                                       (_fcx - _face_w // 2, _fcy - _face_h // 2, _face_w, _face_h))

                    # 눈 (붉은 삼각형 눈 - 도깨비 특유의 날카로운 눈)
                    _eye_a = int(_face_base_a * 0.7)
                    for _edir in [-1, 1]:
                        _ex = _fcx + _edir * int(_ball_r * 0.35)
                        _ey = _fcy - int(_ball_r * 0.15)
                        # 눈 외곽 글로우
                        pygame.draw.circle(_face_surf, (255, 80, 30, _eye_a // 3), (_ex, _ey), int(_ball_r * 0.3))
                        # 삼각형 눈
                        pygame.draw.polygon(_face_surf, (255, 100, 50, _eye_a), [
                            (_ex + _edir * int(_ball_r * 0.25), _ey),
                            (_ex - _edir * int(_ball_r * 0.08), _ey - int(_ball_r * 0.25)),
                            (_ex - _edir * int(_ball_r * 0.08), _ey + int(_ball_r * 0.12)),
                        ])
                        # 눈동자 (밝은 노랑)
                        _pupil_pulse = 0.7 + 0.3 * math.sin(_dt * 10.0 + _edir * 1.5)
                        _pupil_a = int(_eye_a * _pupil_pulse)
                        pygame.draw.circle(_face_surf, (255, 200, 80, _pupil_a),
                                         (_ex + _edir * int(_ball_r * 0.05), _ey), max(1, int(_ball_r * 0.08)))
                        pygame.draw.circle(_face_surf, (255, 255, 220, min(255, _pupil_a + 30)),
                                         (_ex + _edir * int(_ball_r * 0.03), _ey - 1), max(1, int(_ball_r * 0.04)))

                    # 입 (크게 벌린 도깨비 입 + 이빨)
                    _mouth_a = int(_face_base_a * 0.35)
                    _mouth_w = int(_ball_r * 0.9)
                    _mouth_h = int(_ball_r * 0.4)
                    _mouth_y = _fcy + int(_ball_r * 0.25)
                    pygame.draw.ellipse(_face_surf, (40, 140, 220, _mouth_a),
                                       (_fcx - _mouth_w // 2, _mouth_y, _mouth_w, _mouth_h))
                    # 이빨 (톱니)
                    _teeth_a = int(_face_base_a * 0.35)
                    _tooth_count = 5
                    for _ti in range(_tooth_count):
                        _tx = _fcx - _mouth_w // 2 + int((_ti + 0.5) * _mouth_w / _tooth_count)
                        _th = int(_ball_r * 0.12) + int(2 * math.sin(_dt * 5.0 + _ti))
                        pygame.draw.polygon(_face_surf, (200, 240, 255, _teeth_a), [
                            (_tx - 2, _mouth_y + 1),
                            (_tx + 2, _mouth_y + 1),
                            (_tx, _mouth_y + _th),
                        ])

                    SCREEN.blit(_face_surf, (_ball_cx - _face_sz, _ball_cy - _face_sz), special_flags=pygame.BLEND_ADD)

                # ── 7. 엣지 스파크 (불꽃 주변 불똥) ──
                for _spi in range(5):
                    _sp_angle = _dt * 5.0 + _spi * (math.pi * 2 / 5)
                    _sp_dist = _ball_r * (1.8 + 0.6 * math.sin(_dt * 12.0 + _spi * 3.0))
                    _sp_x = _ball_cx + _sp_dist * math.sin(_sp_angle) * 0.7
                    _sp_y = _ball_cy - _sp_dist * math.cos(_sp_angle) * 0.9
                    _sp_bright = 0.3 + 0.7 * abs(math.sin(_dt * 15.0 + _spi * 2.5))
                    _sp_a = int(140 * _sp_bright)
                    if _sp_a > 10:
                        _sp_sz = max(1, int(2 * _sp_bright))
                        _sp_surf = pygame.Surface((_sp_sz * 2 + 6, _sp_sz * 2 + 6), pygame.SRCALPHA)
                        pygame.draw.circle(_sp_surf, (100, 220, 255, _sp_a // 3), (_sp_sz + 3, _sp_sz + 3), _sp_sz + 3)
                        pygame.draw.circle(_sp_surf, (200, 250, 255, _sp_a), (_sp_sz + 3, _sp_sz + 3), _sp_sz)
                        SCREEN.blit(_sp_surf, (int(_sp_x) - _sp_sz - 3, int(_sp_y) - _sp_sz - 3), special_flags=pygame.BLEND_ADD)

        except Exception:
            pass  # 스킬 그리기 오류 무시

    # 🗡️🛡️ 호위무사 스탠스 전환 팝업 아이콘 이펙트 (독립 블록 - 스킬 에러에 영향받지 않음)
    if arena_mode_enabled and arena_stance_popup_effects:
        try:
            _stance_dt = (1.0 / 60.0) * (arena_speed_multiplier if 'arena_speed_multiplier' in dir() else 1)
            _stance_remove_indices = []
            for _si, _se in enumerate(arena_stance_popup_effects):
                _se["timer"] += _stance_dt
                if _se["timer"] >= _se["duration"]:
                    _stance_remove_indices.append(_si)
                    continue
                _prog = _se["timer"] / _se["duration"]
                # 위로 떠오르기 (50px)
                _fy = _se["y"] - _prog * 50
                _fx = _se["x"]
                # 알파: 처음 0.08 페이드인, 0.08~0.45 최대, 0.45 이후 페이드아웃
                if _prog < 0.08:
                    _sa = int(255 * (_prog / 0.08))
                elif _prog < 0.45:
                    _sa = 255
                else:
                    _sa = int(255 * (1.0 - (_prog - 0.45) / 0.55))
                _sa = max(0, min(255, _sa))
                # 스케일: 처음 살짝 커졌다 정상으로
                _sscale = 1.0 + 0.3 * max(0.0, 1.0 - _prog / 0.15) if _prog < 0.15 else 1.0
                _base_sz = 72
                _isz = int(_base_sz * _sscale)
                _half = (_isz + 12) // 2
                _icon_sf = pygame.Surface((_isz + 12, _isz + 12), pygame.SRCALPHA)
                _icx = _half
                _icy = _half
                if _se["mode"] == "attack":
                    # 공격모드: 검 아이콘 (빨간/주황) + 배경 원
                    pygame.draw.circle(_icon_sf, (255, 60, 30, _sa // 3), (_icx, _icy), _half - 1)
                    pygame.draw.circle(_icon_sf, (255, 80, 40, _sa // 2), (_icx, _icy), _half - 4)
                    # 칼날
                    _bt = _icy - _isz // 2 + 4
                    _bb = _icy + _isz // 4 - 1
                    _bw = max(2, _isz // 7)
                    pygame.draw.line(_icon_sf, (255, 240, 200, _sa), (_icx, _bt), (_icx, _bb), _bw + 2)
                    pygame.draw.line(_icon_sf, (255, 100, 60, _sa), (_icx, _bt), (_icx, _bb), _bw)
                    # 칼날 끝
                    pygame.draw.polygon(_icon_sf, (255, 120, 70, _sa), [
                        (_icx, _bt - 4), (_icx - _bw, _bt + 1), (_icx + _bw, _bt + 1)])
                    # 가드
                    _gy = _bb + 2
                    _ghw = _isz // 3
                    pygame.draw.line(_icon_sf, (240, 200, 80, _sa), (_icx - _ghw, _gy), (_icx + _ghw, _gy), max(2, _bw))
                    # 손잡이
                    pygame.draw.line(_icon_sf, (180, 130, 60, _sa), (_icx, _gy + 2), (_icx, _gy + _isz // 4), max(2, _bw))
                    pygame.draw.circle(_icon_sf, (220, 170, 70, _sa), (_icx, _gy + _isz // 4 + 1), max(2, _bw))
                else:
                    # 수비모드: 방패 아이콘 (파란색) + 배경 원
                    pygame.draw.circle(_icon_sf, (30, 80, 255, _sa // 3), (_icx, _icy), _half - 1)
                    pygame.draw.circle(_icon_sf, (40, 100, 255, _sa // 2), (_icx, _icy), _half - 4)
                    # 방패 외곽
                    _sw = _isz // 3 + 1
                    _sh = _isz // 2
                    _shield_pts = [
                        (_icx, _icy - _sh + 1),
                        (_icx + _sw, _icy - _sh + 5),
                        (_icx + _sw, _icy + 3),
                        (_icx, _icy + _sh - 1),
                        (_icx - _sw, _icy + 3),
                        (_icx - _sw, _icy - _sh + 5),
                    ]
                    pygame.draw.polygon(_icon_sf, (70, 140, 255, _sa), _shield_pts)
                    pygame.draw.polygon(_icon_sf, (150, 200, 255, _sa), _shield_pts, 2)
                    # 십자 장식
                    _cr = _sw // 2
                    pygame.draw.line(_icon_sf, (200, 230, 255, _sa), (_icx, _icy - _cr - 3), (_icx, _icy + _cr + 3), 2)
                    pygame.draw.line(_icon_sf, (200, 230, 255, _sa), (_icx - _cr - 1, _icy), (_icx + _cr + 1, _icy), 2)
                SCREEN.blit(_icon_sf, (int(_fx) - _half, int(_fy) - _half))
            for _ri in reversed(_stance_remove_indices):
                arena_stance_popup_effects.pop(_ri)
        except Exception as _stance_popup_err:
            print(f"[StancePopup] draw error: {_stance_popup_err}")
            arena_stance_popup_effects.clear()

    # ⚔️ 스토리모드 호위무사 스탠스 전환 팝업 이펙트
    if not arena_mode_enabled and _bodyguard_stance_popup_effects:
        try:
            _bsp_dt = 1.0 / 60.0
            _bsp_remove = []
            for _bsi, _bse in enumerate(_bodyguard_stance_popup_effects):
                _bse["timer"] += _bsp_dt
                if _bse["timer"] >= _bse["duration"]:
                    _bsp_remove.append(_bsi)
                    continue
                _bprog = _bse["timer"] / _bse["duration"]
                _bfy = _bse["y"] - _bprog * 50
                _bfx = _bse["x"]
                if _bprog < 0.08:
                    _bsa = int(255 * (_bprog / 0.08))
                elif _bprog < 0.45:
                    _bsa = 255
                else:
                    _bsa = int(255 * (1.0 - (_bprog - 0.45) / 0.55))
                _bsa = max(0, min(255, _bsa))
                _bscale = 1.0 + 0.3 * max(0.0, 1.0 - _bprog / 0.15) if _bprog < 0.15 else 1.0
                _bisz = int(72 * _bscale)
                _bhalf = (_bisz + 12) // 2
                _bicon = pygame.Surface((_bisz + 12, _bisz + 12), pygame.SRCALPHA)
                _bicx = _bhalf
                _bicy = _bhalf
                if _bse["mode"] == "attack":
                    pygame.draw.circle(_bicon, (255, 60, 30, _bsa // 3), (_bicx, _bicy), _bhalf - 1)
                    pygame.draw.circle(_bicon, (255, 80, 40, _bsa // 2), (_bicx, _bicy), _bhalf - 4)
                    _bbt = _bicy - _bisz // 2 + 4
                    _bbb = _bicy + _bisz // 4 - 1
                    _bbw = max(2, _bisz // 7)
                    pygame.draw.line(_bicon, (255, 240, 200, _bsa), (_bicx, _bbt), (_bicx, _bbb), _bbw + 2)
                    pygame.draw.line(_bicon, (255, 100, 60, _bsa), (_bicx, _bbt), (_bicx, _bbb), _bbw)
                    pygame.draw.polygon(_bicon, (255, 120, 70, _bsa), [
                        (_bicx, _bbt - 4), (_bicx - _bbw, _bbt + 1), (_bicx + _bbw, _bbt + 1)])
                    _bgy = _bbb + 2
                    _bghw = _bisz // 3
                    pygame.draw.line(_bicon, (240, 200, 80, _bsa), (_bicx - _bghw, _bgy), (_bicx + _bghw, _bgy), max(2, _bbw))
                    pygame.draw.line(_bicon, (180, 130, 60, _bsa), (_bicx, _bgy + 2), (_bicx, _bgy + _bisz // 4), max(2, _bbw))
                    pygame.draw.circle(_bicon, (220, 170, 70, _bsa), (_bicx, _bgy + _bisz // 4 + 1), max(2, _bbw))
                else:
                    pygame.draw.circle(_bicon, (30, 80, 255, _bsa // 3), (_bicx, _bicy), _bhalf - 1)
                    pygame.draw.circle(_bicon, (40, 100, 255, _bsa // 2), (_bicx, _bicy), _bhalf - 4)
                    _bsw = _bisz // 3 + 1
                    _bsh = _bisz // 2
                    _bshield = [
                        (_bicx, _bicy - _bsh + 1), (_bicx + _bsw, _bicy - _bsh + 5),
                        (_bicx + _bsw, _bicy + 3), (_bicx, _bicy + _bsh - 1),
                        (_bicx - _bsw, _bicy + 3), (_bicx - _bsw, _bicy - _bsh + 5)]
                    pygame.draw.polygon(_bicon, (70, 140, 255, _bsa), _bshield)
                    pygame.draw.polygon(_bicon, (150, 200, 255, _bsa), _bshield, 2)
                    _bcr = _bsw // 2
                    pygame.draw.line(_bicon, (200, 230, 255, _bsa), (_bicx, _bicy - _bcr - 3), (_bicx, _bicy + _bcr + 3), 2)
                    pygame.draw.line(_bicon, (200, 230, 255, _bsa), (_bicx - _bcr - 1, _bicy), (_bicx + _bcr + 1, _bicy), 2)
                SCREEN.blit(_bicon, (int(_bfx) - _bhalf, int(_bfy) - _bhalf))
            for _bri in reversed(_bsp_remove):
                _bodyguard_stance_popup_effects.pop(_bri)
        except Exception:
            _bodyguard_stance_popup_effects.clear()

    # 옵티머스 비상충전 시각 효과 그리기
    if selected_character_type == "optimus":
        draw_emergency_charge_effects(SCREEN)

    # 스매셔 리커버리 시각 효과 그리기
    if selected_character_type == "smasher" and recovery_effect_active:
        try:
            draw_recovery_effects(SCREEN)
        except:
            pass

    # 부스트차징 발동 이펙트 그리기
    if boost_charging_effect_timer > 0:
        try:
            draw_boost_charging_effect(SCREEN)
        except:
            pass

    # 스매셔 리커버리 스피드 부스트 빛가루 파티클 그리기
    if selected_character_type == "smasher":
        try:
            draw_recovery_light_particles(SCREEN)
        except:
            pass

    draw_blacksmith_turret_elements(SCREEN)

    # 수리 이펙트를 건물 위에 그리기 위해 여기로 이동

    # 킥차져 빛나는 이펙트 그리기
    try:
        from item_effects.knee_pads import get_knee_pads_instance
        knee_pads = get_knee_pads_instance()
        if knee_pads:
            knee_pads.update()  # 타이머 업데이트
            knee_pads.draw_effect(SCREEN)  # 이펙트 그리기
            # 디버그 출력 비활성화 - F4 좌표계 디버그로 대체
    except Exception as e:
        print(f"[ERROR] 킥차져 이펙트 그리기 오류: {e}")

    # 🧪 기묘한 약병 패들 이펙트 그리기
    if strange_vial_active and PLAYER:
        try:
            from item_effects.strange_vial import draw_strange_vial_effects
            draw_strange_vial_effects(SCREEN, PLAYER)
        except Exception as _sv_e:
            print(f"[STRANGE_VIAL_EFFECT_ERROR] {_sv_e}")

    # ⚡ 스매셔 콤보 이펙트 업데이트 및 그리기
    if selected_character_type == "smasher":
        update_smasher_combo_effect()
        draw_smasher_combo_effect(SCREEN)

    # 실전 튜토리얼 딜레이 업데이트 (주니어리그)
    if ai_mode == "junior":
        update_ingame_tutorial_delay()
        check_skill_hover_for_tutorial()

    # ⚡ 스매셔 플라즈마 자기장 효과 업데이트 및 그리기
    if selected_character_type == "smasher":
        update_plasma_field_particles()
        update_plasma_wave()
        update_boss_plasma_slow()
        update_plasma_contact_effects()  # 접촉 이펙트 업데이트
        draw_plasma_field_charging(SCREEN)
        draw_plasma_wave(SCREEN)
        draw_plasma_contact_effects(SCREEN)  # 접촉 이펙트 렌더링 (굴절 + 스파크)

    # 🧤 독안개장갑 — 자욱한 독안개 영역 렌더링 (Premium Volumetric Fog)
    try:
        from item_effects.venom_mist_gauntlet import is_mist_field_active as _vmg_is_active
        if _vmg_is_active():
            from item_effects.venom_mist_gauntlet import (
                get_mist_position, get_mist_radius, get_mist_alpha,
                get_mist_particles, get_mist_elapsed_frames,
            )
            _vmg_mx, _vmg_my = get_mist_position()
            _vmg_r = get_mist_radius()
            _vmg_alpha = get_mist_alpha()
            _vmg_elapsed = get_mist_elapsed_frames()
            _vmg_t = _vmg_elapsed * 0.025

            if _vmg_alpha > 0:
                _vmg_surf = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
                _vmg_cx = int(_vmg_mx)
                _vmg_cy = int(_vmg_my)

                # ── Layer 0: 방사형 그라데이션 베이스 ──
                for _vmg_gi in range(5):
                    _vmg_ratio = 1.0 - _vmg_gi / 5.0
                    _vmg_gr = int(_vmg_r * (0.3 + _vmg_gi * 0.16))
                    _vmg_breathe = 0.08 * math.sin(_vmg_t * 1.2 + _vmg_gi * 0.9)
                    _vmg_gr = int(_vmg_gr * (1.0 + _vmg_breathe))
                    _vmg_ga = int(22 * _vmg_ratio * _vmg_alpha)
                    if _vmg_ga > 0 and _vmg_gr > 0:
                        _vmg_gg = int(130 + 50 * _vmg_ratio)
                        _vmg_gb = int(60 + 40 * (1.0 - _vmg_ratio))
                        pygame.draw.circle(_vmg_surf, (20, _vmg_gg, _vmg_gb, _vmg_ga),
                                           (_vmg_cx, _vmg_cy), _vmg_gr)

                # ── Layer 1: 3계층 파티클 안개 ──
                _vmg_particles = get_mist_particles()
                _vmg_lo = {'deep': 0, 'mid': 1, 'wisp': 2}
                _vmg_sorted = sorted(_vmg_particles,
                                     key=lambda _p: _vmg_lo.get(_p.get('layer', 'mid'), 1))
                for _vmg_p in _vmg_sorted:
                    _vmg_pa = int(_vmg_p['alpha'] * _vmg_alpha)
                    if _vmg_pa <= 0:
                        continue
                    _vmg_px = int(_vmg_p['x'])
                    _vmg_py = int(_vmg_p['y'])
                    _vmg_ps = int(_vmg_p['size'])
                    _vmg_layer = _vmg_p.get('layer', 'mid')
                    if _vmg_layer == 'deep':
                        pygame.draw.circle(_vmg_surf, (25, 140, 70, int(_vmg_pa * 0.4)),
                                           (_vmg_px, _vmg_py), _vmg_ps)
                        pygame.draw.circle(_vmg_surf, (30, 155, 80, int(_vmg_pa * 0.7)),
                                           (_vmg_px, _vmg_py), max(2, _vmg_ps * 2 // 3))
                    elif _vmg_layer == 'wisp':
                        _vmg_wdx = _vmg_px - _vmg_cx
                        _vmg_wdy = _vmg_py - _vmg_cy
                        _vmg_wd = math.sqrt(_vmg_wdx * _vmg_wdx + _vmg_wdy * _vmg_wdy)
                        if _vmg_wd > 10:
                            _vmg_sx = _vmg_cx + int(_vmg_wdx * 0.55)
                            _vmg_sy = _vmg_cy + int(_vmg_wdy * 0.55)
                            pygame.draw.line(_vmg_surf, (50, 170, 80, int(_vmg_pa * 0.5)),
                                             (_vmg_sx, _vmg_sy), (_vmg_px, _vmg_py),
                                             max(1, _vmg_ps // 4))
                        pygame.draw.circle(_vmg_surf, (60, 190, 90, int(_vmg_pa * 0.6)),
                                           (_vmg_px, _vmg_py), max(2, _vmg_ps // 2))
                    else:
                        pygame.draw.circle(_vmg_surf, (30, 150, 75, int(_vmg_pa * 0.55)),
                                           (_vmg_px, _vmg_py), _vmg_ps)
                        pygame.draw.circle(_vmg_surf, (45, 175, 90, int(_vmg_pa * 0.35)),
                                           (_vmg_px, _vmg_py), max(2, _vmg_ps * 3 // 5))

                # ── Layer 2: 독기 소용돌이 하이라이트 ──
                for _vmg_si in range(3):
                    _vmg_sa = _vmg_t * 0.8 + _vmg_si * (math.tau / 3)
                    for _vmg_sj in range(4):
                        _vmg_sd = _vmg_r * (0.25 + _vmg_sj * 0.18)
                        _vmg_sangle = _vmg_sa + _vmg_sj * 0.35
                        _vmg_sx2 = _vmg_cx + int(math.cos(_vmg_sangle) * _vmg_sd)
                        _vmg_sy2 = _vmg_cy + int(math.sin(_vmg_sangle) * _vmg_sd)
                        _vmg_sa2 = int((18 - _vmg_sj * 3) * _vmg_alpha)
                        if _vmg_sa2 > 0:
                            pygame.draw.circle(_vmg_surf, (80, 220, 120, _vmg_sa2),
                                               (_vmg_sx2, _vmg_sy2), max(2, 6 - _vmg_sj))

                # ── Layer 3: 가장자리 페더링 ──
                for _vmg_fi in range(3):
                    _vmg_fr = _vmg_r - _vmg_fi * 3
                    _vmg_fa = int((8 - _vmg_fi * 2) * _vmg_alpha)
                    if _vmg_fr > 0 and _vmg_fa > 0:
                        pygame.draw.circle(_vmg_surf, (40, 160, 70, _vmg_fa),
                                           (_vmg_cx, _vmg_cy), _vmg_fr, 2)

                # ── Layer 4: 중앙 독기 심볼 ──
                _vmg_sym_a = int(25 * _vmg_alpha * (0.6 + 0.4 * math.sin(_vmg_t * 2.0)))
                if _vmg_sym_a > 3:
                    _vmg_dp = []
                    for _vmg_di in range(12):
                        _vmg_da = _vmg_di / 12.0 * math.tau
                        _vmg_dr = 8 + 4 * math.sin(_vmg_da * 2 - math.pi / 2)
                        _vmg_dp.append((_vmg_cx + int(math.cos(_vmg_da) * _vmg_dr),
                                        _vmg_cy + int(math.sin(_vmg_da) * _vmg_dr) - 2))
                    if len(_vmg_dp) >= 3:
                        pygame.draw.polygon(_vmg_surf, (100, 255, 130, _vmg_sym_a), _vmg_dp, 1)

                SCREEN.blit(_vmg_surf, (0, 0))
    except Exception:
        pass

    # ⚔ 바이퍼 에어 블레이드 검기 렌더링 (Ultra Premium Crescent Blade Wave)
    if _viper_blade_rush_active:
        try:
            _br_cx = int(_viper_blade_rush_x)
            _br_cy = int(_viper_blade_rush_y)
            _br_hw = _viper_blade_rush_width // 2
            _br_progress = 1.0 - ((_viper_blade_rush_y - _viper_blade_rush_target_y) /
                                   (_viper_blade_rush_start_y - _viper_blade_rush_target_y)) if (_viper_blade_rush_start_y - _viper_blade_rush_target_y) > 0 else 1.0
            _br_progress = max(0.0, min(1.0, _br_progress))
            _ticks = pygame.time.get_ticks()
            _dt_sec = _ticks / 1000.0

            # 소멸 페이드
            _fade_start = 0.65
            _fade_factor = max(0.0, min(1.0, (_br_progress - _fade_start) / (1.0 - _fade_start))) if _br_progress > _fade_start else 0.0
            if _viper_blade_rush_fadeout:
                _fo_ratio = _viper_blade_rush_fadeout_timer / max(1, _VIPER_BLADE_RUSH_FADEOUT_FRAMES)
                _fade_factor = max(_fade_factor, 1.0 - _fo_ratio)
            _alive = 1.0 - _fade_factor

            # ── 부채꼴 검기파 (꼭짓점 아래, 위로 펼쳐지는 팬 형태) ──
            _fan_w = _br_hw * 2  # 부채꼴 상단 전체 폭
            _fan_h = 55          # 부채꼴 높이 (꼭짓점→상단 호까지)
            _fan_surf_w = _fan_w + 40
            _fan_surf_h = _fan_h + 30
            _fan_surf = pygame.Surface((_fan_surf_w, _fan_surf_h), pygame.SRCALPHA)
            _fcx = _fan_surf_w // 2
            _fcy = _fan_surf_h - 8  # 꼭짓점 (하단 중앙)

            # ── 0. 트레일 (라인 기반 궤적) ──
            _trail_len = len(_viper_blade_rush_trail)
            _trail_draw = min(10, _trail_len)
            if _trail_draw > 1:
                for _ti in range(1, _trail_draw):
                    _t_idx = _trail_len - _trail_draw + _ti
                    _tx, _ty = _viper_blade_rush_trail[_t_idx]
                    _prev_idx = _t_idx - 1
                    _px, _py = _viper_blade_rush_trail[_prev_idx]
                    _t_p = _ti / max(1, _trail_draw - 1)
                    _t_alpha = int((15 + 45 * _t_p) * _alive)
                    _t_w = max(1, int(1 + 3 * _t_p))
                    if _t_alpha > 2:
                        _tcr = int(85 + 55 * _t_p)
                        _tcg = int(70 + 60 * _t_p)
                        _tcb = int(110 + 50 * _t_p)
                        pygame.draw.line(SCREEN, (_tcr, _tcg, _tcb, _t_alpha),
                                         (int(_px), int(_py)), (int(_tx), int(_ty)), _t_w)

            # ── 1. 다층 부채꼴 본체 (6겹, 바깥→안쪽 점점 밝고 좁아짐) ──
            _fan_layers = [
                (1.00, (55, 30, 90),    30),   # 최외곽 — 짙은 보라
                (0.85, (80, 45, 130),   50),   # 외곽 — 진보라
                (0.70, (110, 65, 160),  75),   # 중간 — 보라
                (0.55, (140, 90, 185),  105),  # 중내곽 — 연보라
                (0.38, (170, 130, 210), 140),  # 코어 — 라벤더
                (0.18, (200, 180, 230), 180),  # 극코어 — 밝은 라벤더
            ]

            for _fi, (_f_scale, _f_rgb, _f_base_a) in enumerate(_fan_layers):
                _f_alpha = int(_f_base_a * _alive)
                if _f_alpha < 2:
                    continue
                _fw = int(_fan_w * _f_scale * 0.5)  # 반폭
                _fh = int(_fan_h * _f_scale)
                # 부채꼴 폴리곤: 하단 꼭짓점 → 호 형태 상단
                _fan_pts = [(_fcx, _fcy)]  # 꼭짓점
                _arc_steps = 12
                for _as in range(_arc_steps + 1):
                    _a_t = _as / _arc_steps  # 0→1 (좌→우)
                    _a_angle = math.pi + (math.pi * 0.15) + _a_t * (math.pi * 0.70)  # ~207°→~261°
                    _ax = _fcx + int(math.cos(_a_angle) * _fw * 1.15)
                    _ay = _fcy + int(math.sin(_a_angle) * _fh * 1.1)
                    _fan_pts.append((_ax, _ay))
                if len(_fan_pts) >= 3:
                    pygame.draw.polygon(_fan_surf, (*_f_rgb, _f_alpha), _fan_pts)

            # ── 2. 상단 호 가장자리 라인 (날의 에지) ──
            _edge_pts = []
            _edge_steps = 16
            _edge_hw = int(_fan_w * 0.5)
            for _es in range(_edge_steps + 1):
                _e_t = _es / _edge_steps
                _e_angle = math.pi + (math.pi * 0.15) + _e_t * (math.pi * 0.70)
                _ex = _fcx + int(math.cos(_e_angle) * _edge_hw * 1.15)
                _ey = _fcy + int(math.sin(_e_angle) * _fan_h * 1.1)
                _edge_pts.append((_ex, _ey))
            _edge_alpha = int(160 * _alive)
            if len(_edge_pts) > 1 and _edge_alpha > 3:
                pygame.draw.lines(_fan_surf, (190, 160, 230, _edge_alpha), False, _edge_pts, 2)
                # 안쪽 얇은 하이라이트 라인
                _inner_pts = []
                _inner_hw = int(_fan_w * 0.42)
                for _is2 in range(_edge_steps + 1):
                    _i_t = _is2 / _edge_steps
                    _i_angle = math.pi + (math.pi * 0.15) + _i_t * (math.pi * 0.70)
                    _ix = _fcx + int(math.cos(_i_angle) * _inner_hw * 1.15)
                    _iy = _fcy + int(math.sin(_i_angle) * _fan_h * 0.65 * 1.1)
                    _inner_pts.append((_ix, _iy))
                _inner_alpha = int(80 * _alive)
                if _inner_alpha > 2:
                    pygame.draw.lines(_fan_surf, (170, 140, 210, _inner_alpha), False, _inner_pts, 1)

            # ── 3. 에너지 스파크 (상단 호를 따라) ──
            for _si in range(8):
                _s_t = _si / 7.0
                _s_angle = math.pi + (math.pi * 0.15) + _s_t * (math.pi * 0.70)
                _s_hw = int(_fan_w * 0.5) + random.randint(-8, 8)
                _sx = _fcx + int(math.cos(_s_angle) * _s_hw * 1.15)
                _sy = _fcy + int(math.sin(_s_angle) * _fan_h * 1.1) + random.randint(-3, 3)
                _s_alpha = int(random.randint(100, 200) * _alive)
                if _s_alpha > 5:
                    pygame.draw.circle(_fan_surf, (185, 150, 230, _s_alpha), (_sx, _sy), random.randint(1, 2))

            # ── 4. 꼭짓점 글로우 (하단 중앙 수렴점) ──
            for _gl in range(3):
                _gl_r = 10 - _gl * 3
                _gl_a = int((20 - _gl * 5) * _alive)
                if _gl_r > 0 and _gl_a > 1:
                    pygame.draw.circle(_fan_surf, (130, 80, 180, _gl_a), (_fcx, _fcy), _gl_r)

            SCREEN.blit(_fan_surf, (_br_cx - _fcx, _br_cy - _fcy),
                        special_flags=pygame.BLEND_ADD)

            # ── 5. 외곽 앰비언트 헤일로 ──
            _amb_r = int(_fan_h * 1.2)
            _amb_a = int(15 * _alive)
            if _amb_r > 0 and _amb_a > 1:
                _amb_s = pygame.Surface((_amb_r * 2, _amb_r * 2), pygame.SRCALPHA)
                pygame.draw.circle(_amb_s, (80, 50, 130, _amb_a), (_amb_r, _amb_r), _amb_r)
                SCREEN.blit(_amb_s, (_br_cx - _amb_r, _br_cy - _amb_r),
                            special_flags=pygame.BLEND_ADD)

        except Exception:
            pass

    # ⚡ 바이퍼 신경 타격 연계기 — 돌진/베기/복귀 렌더링
    if _viper_nerve_strike_active:
        try:
            _ns_rnow = pygame.time.get_ticks()
            _ns_relapsed = _ns_rnow - _viper_nerve_strike_start_ms

            if _viper_nerve_strike_phase == 0:
                # -- Dash: Viper silhouette afterimages + speed lines --
                _ns_t = min(1.0, _ns_relapsed / _VIPER_NS_DASH_DURATION)
                try:
                    _ns_sil_base = create_viper_paddle_surface(0.0)
                    _ns_sil_w, _ns_sil_h = _ns_sil_base.get_size()
                    for _ti in range(3):
                        _tt = max(0.0, _ns_t - (_ti * 0.08))
                        _tt_ease = _tt * _tt * (3.0 - 2.0 * _tt)
                        _trail_x = _viper_nerve_strike_origin_x + (_viper_nerve_strike_target_x - _viper_nerve_strike_origin_x) * _tt_ease
                        _trail_y = _viper_nerve_strike_origin_y + (_viper_nerve_strike_target_y - _viper_nerve_strike_origin_y) * _tt_ease
                        _sil_alpha = int(140 * (1.0 - _ti / 3.0) * (0.5 + 0.5 * (1.0 - _ns_t)))
                        if _sil_alpha > 8:
                            _sil_copy = _ns_sil_base.copy()
                            _tint_s = pygame.Surface((_ns_sil_w, _ns_sil_h), pygame.SRCALPHA)
                            _tint_s.fill((180, 0, 220, _sil_alpha))
                            _sil_copy.blit(_tint_s, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
                            _sil_copy.set_alpha(_sil_alpha)
                            SCREEN.blit(_sil_copy,
                                        (int(_trail_x) - _ns_sil_w // 2, int(_trail_y) - _ns_sil_h // 2),
                                        special_flags=pygame.BLEND_ADD)
                except Exception:
                    pass
                _ns_dx = _viper_nerve_strike_target_x - _viper_nerve_strike_origin_x
                _ns_dy = _viper_nerve_strike_target_y - _viper_nerve_strike_origin_y
                _ns_dist = math.sqrt(_ns_dx * _ns_dx + _ns_dy * _ns_dy)
                if _ns_dist > 1.0:
                    _ns_px = -_ns_dy / _ns_dist
                    _ns_py = _ns_dx / _ns_dist
                    for _li in range(5):
                        _lo = (_li - 2) * 12
                        _la = int(100 * (1.0 - abs(_li - 2) / 2.5) * _ns_t * (1.0 - _ns_t * 0.5))
                        if _la > 5:
                            _lsx = int(PLAYER.centerx + _ns_px * _lo + _ns_dx * 0.15)
                            _lsy = int(PLAYER.centery + _ns_py * _lo + _ns_dy * 0.15)
                            _lex = int(PLAYER.centerx + _ns_px * _lo - _ns_dx * 0.1)
                            _ley = int(PLAYER.centery + _ns_py * _lo - _ns_dy * 0.1)
                            pygame.draw.line(SCREEN, (180, 80, 255), (_lsx, _lsy), (_lex, _ley), 1)

            elif _viper_nerve_strike_phase == 1:
                # -- Slash: dual arc slashes + sparks + screen flash --
                # 적중 시 프리즈 컷씬: 더 긴 연출 시간 사용
                _ns_slash_render_dur = _VIPER_NS_SLASH_DURATION_HIT if _viper_ns_hit_confirmed else _VIPER_NS_SLASH_DURATION
                _ns_st = min(1.0, _ns_relapsed / _ns_slash_render_dur)
                _scx = BOSS.centerx
                _scy = BOSS.centery
                _sr = 70
                _ssz = _sr * 2 + 60
                _ss = pygame.Surface((_ssz, _ssz), pygame.SRCALPHA)
                _ssc = _ssz // 2

                # ── 적중 프리즈 컷씬 전용 연출 ──
                if _viper_ns_hit_confirmed:
                    # 화면 어둡게 (반투명 검은색 오버레이)
                    _dim_alpha = int(120 * min(1.0, _ns_st * 5.0))  # 빠르게 어두워짐
                    if _dim_alpha > 3:
                        _dim_s = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
                        _dim_s.fill((0, 0, 0, _dim_alpha))
                        SCREEN.blit(_dim_s, (0, 0))

                    # "베놈 엣지!" 텍스트 (전반부: 0~0.5) → 할퀴기 (후반부: 0.5~1.0)
                    # 텍스트: 전반부에 나타나서 유지
                    _text_appear = min(1.0, _ns_st * 5.0)  # 빠르게 나타남
                    _text_fade = max(0.0, 1.0 - max(0.0, _ns_st - 0.45) * 5.0)  # 0.45 이후 페이드아웃
                    _text_alpha = int(255 * min(_text_appear, _text_fade))
                    if _text_alpha > 10:
                        # 텍스트 첫 출현 시 쇼 사운드 1회 재생
                        global _viper_nerve_strike_show_sound_played
                        if not _viper_nerve_strike_show_sound_played:
                            _viper_nerve_strike_show_sound_played = True
                            try:
                                _vs_snd = sound_effects.get('VIPER_SHOW')
                                if _vs_snd:
                                    _vs_snd.set_volume(0.7)
                                    _vs_snd.play()
                            except Exception:
                                pass
                        try:
                            _ve_font = get_font(48)
                            _ve_text = "베놈 엣지!"
                            _ve_shadow = _ve_font.render(_ve_text, True, (0, 0, 0))
                            _ve_main = _ve_font.render(_ve_text, True, (220, 80, 255))
                            _ve_glow = _ve_font.render(_ve_text, True, (255, 200, 255))
                            _ve_w = _ve_main.get_width()
                            _ve_h = _ve_main.get_height()
                            _ve_x = WIDTH // 2 - _ve_w // 2
                            _ve_y = HEIGHT // 2 - _ve_h // 2
                            # 약간의 흔들림 효과
                            _ve_shake_x = random.randint(-2, 2) if _text_appear < 0.5 else 0
                            _ve_shake_y = random.randint(-1, 1) if _text_appear < 0.5 else 0
                            # 글로우 (확대)
                            _ve_glow.set_alpha(int(_text_alpha * 0.3))
                            SCREEN.blit(_ve_glow, (_ve_x - 2 + _ve_shake_x, _ve_y - 2 + _ve_shake_y))
                            # 그림자
                            _ve_shadow.set_alpha(_text_alpha)
                            SCREEN.blit(_ve_shadow, (_ve_x + 3 + _ve_shake_x, _ve_y + 3 + _ve_shake_y))
                            # 메인 텍스트
                            _ve_main.set_alpha(_text_alpha)
                            SCREEN.blit(_ve_main, (_ve_x + _ve_shake_x, _ve_y + _ve_shake_y))
                        except Exception:
                            pass

                    # 할퀴기 자국 (후반부: _ns_st >= 0.5 이후 등장)
                    if _ns_st >= 0.45:
                        _scratch_local_t = (_ns_st - 0.45) / 0.55  # 0→1 (후반부 내에서)
                        _scratch_t = min(1.0, _scratch_local_t * 3.0)  # 빠르게 나타남
                        if _scratch_t > 0.05:
                            _scratch_len = int(100 * _scratch_t)
                            _scratch_alpha = int(255 * min(1.0, _scratch_t * 2.0) * max(0.0, 1.0 - (_scratch_local_t - 0.5) * 2.0))
                            if _scratch_alpha > 5:
                                _scratch_s = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
                                for _sci in range(3):
                                    _sc_offset = (_sci - 1) * 18
                                    _sc_x1 = _scx - 40 + _sc_offset
                                    _sc_y1 = _scy - _scratch_len // 2
                                    _sc_x2 = _scx + 40 + _sc_offset
                                    _sc_y2 = _scy + _scratch_len // 2
                                    pygame.draw.line(_scratch_s, (200, 50, 255, _scratch_alpha),
                                                    (_sc_x1, _sc_y1), (_sc_x2, _sc_y2), 3)
                                    pygame.draw.line(_scratch_s, (255, 150, 255, _scratch_alpha // 2),
                                                    (_sc_x1 - 1, _sc_y1), (_sc_x2 - 1, _sc_y2), 5)
                                SCREEN.blit(_scratch_s, (0, 0), special_flags=pygame.BLEND_ADD)

                # 원래 베기 이펙트 (프리즈 여부와 무관하게 표시)
                if _ns_st < 0.27:
                    _ft = _ns_st / 0.27
                    _fa = int(60 * (1.0 - _ft))
                    if _fa > 3:
                        _fo = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
                        _fo.fill((180, 0, 220, _fa))
                        SCREEN.blit(_fo, (0, 0))
                _a1p = min(1.0, _ns_st * 3.0)
                _a1a = int(255 * max(0.0, 1.0 - (_ns_st - 0.1) * 1.5))
                if _a1a > 5 and _a1p > 0.01:
                    _a1w = max(2, int(5 * (1.0 - _ns_st * 0.7)))
                    _a1r = pygame.Rect(_ssc - _sr, _ssc - _sr, _sr * 2, _sr * 2)
                    pygame.draw.arc(_ss, (255, 120, 255, _a1a), _a1r, -0.5, -0.5 + _a1p * 2.4, _a1w)
                    _a1ca = int(200 * max(0.0, 1.0 - _ns_st * 2.0))
                    if _a1ca > 5:
                        _a1ir = pygame.Rect(_ssc - _sr + 4, _ssc - _sr + 4, _sr * 2 - 8, _sr * 2 - 8)
                        pygame.draw.arc(_ss, (255, 220, 255, _a1ca), _a1ir, -0.5, -0.5 + _a1p * 2.4, max(1, _a1w - 2))
                _a2t = max(0.0, _ns_st - 0.15)
                _a2p = min(1.0, _a2t * 3.5)
                _a2a = int(230 * max(0.0, 1.0 - (_a2t - 0.05) * 1.5))
                if _a2a > 5 and _a2p > 0.01:
                    _a2w = max(2, int(4 * (1.0 - _a2t * 0.8)))
                    _a2r = pygame.Rect(_ssc - _sr + 8, _ssc - _sr + 8, _sr * 2 - 16, _sr * 2 - 16)
                    pygame.draw.arc(_ss, (200, 80, 255, _a2a), _a2r, 2.6, 2.6 + _a2p * 2.2, _a2w)
                    _a2ca = int(180 * max(0.0, 1.0 - _a2t * 2.2))
                    if _a2ca > 5:
                        _a2ir = pygame.Rect(_ssc - _sr + 12, _ssc - _sr + 12, _sr * 2 - 24, _sr * 2 - 24)
                        pygame.draw.arc(_ss, (255, 200, 255, _a2ca), _a2ir, 2.6, 2.6 + _a2p * 2.2, max(1, _a2w - 2))
                if _ns_st < 0.33:
                    _it = _ns_st / 0.33
                    _ir = int(30 * (1.0 - _it * 0.5))
                    _ia = int(220 * (1.0 - _it))
                    if _ia > 5:
                        pygame.draw.circle(_ss, (255, 255, 255, _ia), (_ssc, _ssc), _ir)
                        pygame.draw.circle(_ss, (255, 180, 255, int(_ia * 0.6)), (_ssc, _ssc), int(_ir * 1.5))
                for _si in range(8):
                    _spt = max(0.0, _ns_st - _si * 0.03)
                    if 0.0 < _spt < 0.6:
                        _spp = _spt / 0.6
                        _spa = (_si / 8.0) * math.pi * 2.0 + _ns_st * 4.0
                        _spd = _sr * (0.5 + 0.8 * _spp)
                        _spx = _ssc + int(math.cos(_spa) * _spd)
                        _spy = _ssc + int(math.sin(_spa) * _spd)
                        _spalpha = int(200 * (1.0 - _spp))
                        _sps = max(1, int(3 * (1.0 - _spp)))
                        if 0 <= _spx < _ssz and 0 <= _spy < _ssz and _spalpha > 5:
                            pygame.draw.circle(_ss, (255, 200, 100, _spalpha), (_spx, _spy), _sps)
                _glt = min(1.0, _ns_st * 2.0)
                _glr = int(_sr * (0.6 + 0.6 * _glt))
                _gla = int(40 * (1.0 - _glt))
                if _gla > 2:
                    pygame.draw.circle(_ss, (160, 0, 220, _gla), (_ssc, _ssc), _glr, 2)
                SCREEN.blit(_ss, (_scx - _ssc, _scy - _ssc), special_flags=pygame.BLEND_ADD)

            elif _viper_nerve_strike_phase == 2:
                # -- Return: fading silhouette + landing shockwave + dust --
                _ns_t = min(1.0, _ns_relapsed / _VIPER_NS_RETURN_DURATION)
                _fade_a = int(120 * (1.0 - _ns_t))
                if _fade_a > 5:
                    try:
                        _ret_sil = create_viper_paddle_surface(0.0)
                        _rw, _rh = _ret_sil.get_size()
                        _tint = pygame.Surface((_rw, _rh), pygame.SRCALPHA)
                        _tint.fill((180, 0, 220, _fade_a))
                        _ret_sil.blit(_tint, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
                        _ret_sil.set_alpha(_fade_a)
                        SCREEN.blit(_ret_sil,
                                    (int(_viper_nerve_strike_target_x) - _rw // 2,
                                     int(_viper_nerve_strike_target_y) - _rh // 2),
                                    special_flags=pygame.BLEND_ADD)
                    except Exception:
                        pass
                if _ns_t > 0.7:
                    _ldt = (_ns_t - 0.7) / 0.3
                    _ldx = int(PLAYER.centerx)
                    _ldy = int(_viper_nerve_strike_origin_y)
                    _rr = int(10 + 40 * _ldt)
                    _ra = int(180 * (1.0 - _ldt))
                    if _ra > 5:
                        pygame.draw.circle(SCREEN, (160, 80, 255), (_ldx, _ldy), _rr, 2)
                    for _di in range(6):
                        _da = (_di / 6.0) * math.pi - math.pi * 0.5
                        _dd = 15 + 35 * _ldt
                        _dx = _ldx + int(math.cos(_da) * _dd)
                        _dy = _ldy + int(math.sin(_da * 0.3) * 5) - int(10 * _ldt)
                        _dalpha = int(120 * (1.0 - _ldt))
                        _ds = max(1, int(3 * (1.0 - _ldt * 0.7)))
                        if _dalpha > 5:
                            pygame.draw.circle(SCREEN, (140, 100, 180), (_dx, _dy), _ds)

        except Exception:
            pass


    if _viper_ss_hologram_active:
        try:
            _holo_now = pygame.time.get_ticks()
            _holo_elapsed = _holo_now - _viper_ss_hologram_start_ms
            _holo_t = min(1.0, _holo_elapsed / _VIPER_SS_HOLOGRAM_DURATION)

            if _holo_t >= 1.0:
                _viper_ss_hologram_active = False
            else:
                _holo_x = int(_viper_ss_hologram_target_x)
                _holo_y = int(_viper_ss_hologram_origin_y)

                # 바이퍼 원본 Surface (쉐도우 백스텝 시 발차기 포즈)
                _holo_base = create_viper_paddle_surface(0.0, kick_direction=_viper_ss_hologram_kick_dir)
                _holo_w, _holo_h = _holo_base.get_size()

                # 이징 함수: 느리게 시작 → 빠르게 마무리 (ease-in-out)
                _ease_t = _holo_t * _holo_t * (3.0 - 2.0 * _holo_t)

                # 알파: 0 → 255 (신기루처럼 서서히 나타남)
                _holo_alpha = int(255 * _ease_t)

                # 캐릭터 Surface에 직접 알파 적용
                _holo_surf = _holo_base.copy()
                _holo_surf.set_alpha(_holo_alpha)

                # 미세한 흔들림 (신기루/아지랑이 느낌, 점점 안정됨)
                _shimmer = (1.0 - _ease_t)  # 1→0
                _offset_x = math.sin(_holo_now * 0.015) * 3 * _shimmer
                _offset_y = math.cos(_holo_now * 0.012) * 2 * _shimmer

                _draw_x = _holo_x - _holo_w // 2 + _offset_x
                _draw_y = _holo_y - _holo_h // 2 + _offset_y

                # 홀로그램 잔상 겹침 이펙트 (발차기 방향으로 빠르게 뻗어나감) — 본체 뒤에 깔림
                if _holo_t > 0.15:
                    _ghost_count = 8
                    _kick_dir = _viper_ss_hologram_kick_dir
                    for _gi in range(_ghost_count):
                        _g_delay = _gi * 0.02  # 촘촘한 딜레이 (연사 느낌)
                        _g_local_t = (_holo_t - 0.15 - _g_delay) / 0.25
                        if _g_local_t < 0.0 or _g_local_t > 1.0:
                            continue
                        _g_ease = min(1.0, _g_local_t * _g_local_t * 4.0)  # 빠른 가속
                        # 발차기 방향으로 뻗어나감 (확장 히트박스 끝까지 커버)
                        _g_offset_x = _kick_dir * _g_ease * (8 + _gi * 18)
                        _g_offset_y = 0
                        # 알파: 빠르게 나타나고 천천히 사라짐, 뒤쪽 잔상일수록 연함
                        _g_fade = 1.0 - max(0.0, (_g_local_t - 0.7) * 3.3)
                        _g_alpha = int(min(180, (120 - _gi * 8) * min(1.0, _g_local_t * 4.0) * _g_fade))
                        if _g_alpha <= 0:
                            continue
                        _ghost_surf = _holo_base.copy()
                        _ghost_surf.set_alpha(_g_alpha)
                        _gx = _holo_x - _holo_w // 2 + _g_offset_x
                        _gy = _holo_y - _holo_h // 2 + _g_offset_y
                        SCREEN.blit(_ghost_surf, (int(_gx), int(_gy)))

                # 본체 홀로그램 (잔상 위에 그림)
                SCREEN.blit(_holo_surf, (int(_draw_x), int(_draw_y)))

                # 홀로그램 발차기 확장 히트박스 — 공 충돌 판정 (공통 그라데이션 타격)
                if _holo_t > 0.3 and not _viper_ss_hologram_kick_hit and not _viper_ss_hit_consumed:
                    _kick_expand = 60
                    _kick_rect = pygame.Rect(
                        _holo_x - _holo_w // 2 - 30,
                        _holo_y - _holo_h // 2 - 25,
                        _holo_w + _kick_expand,
                        _holo_h + 50
                    )
                    if _kick_rect.colliderect(BALL):
                        # 그라데이션 계산용 히트박스 확대 (충돌 판정은 기존 크기 유지)
                        _viper_ss_apply_ball_hit(
                            _kick_rect.centerx, _kick_rect.centery,
                            _kick_rect.width + 120, _kick_rect.height + 160,
                            _viper_ss_hologram_kick_dir, source="hologram"
                        )

                # 도착 이펙트 (완료 시)
                if _holo_t > 0.95:
                    try:
                        effects_manager.spawn_shockwave(
                            _holo_x, _holo_y - 10,
                            force=6, color=(100, 0, 180),
                        )
                    except Exception:
                        pass
        except Exception:
            _viper_ss_hologram_active = False

    # 🔥 바이퍼 제트팩 화염 + 연기 파티클 렌더링
    if _viper_jetpack_particles or _viper_jetpack_active or _viper_air_strike_text_timer > 0:
        try:
            # 연기 먼저 (뒤에 깔림)
            for _jp in _viper_jetpack_particles:
                if _jp.get('type') != 'smoke':
                    continue
                _jp_life_ratio = max(0.0, _jp['life'] / _jp['max_life'])
                _jp_alpha = int(60 * _jp_life_ratio)
                _jp_sz = max(1, int(_jp['size']))
                _smoke_surf = pygame.Surface((_jp_sz * 2, _jp_sz * 2), pygame.SRCALPHA)
                pygame.draw.circle(_smoke_surf, (80, 80, 100, _jp_alpha),
                                   (_jp_sz, _jp_sz), _jp_sz)
                SCREEN.blit(_smoke_surf, (int(_jp['x']) - _jp_sz, int(_jp['y']) - _jp_sz))

            # 화염 파티클 (타원형, BLEND_ADD)
            for _jp in _viper_jetpack_particles:
                if _jp.get('type') != 'flame':
                    continue
                _jp_life_ratio = max(0.0, _jp['life'] / _jp['max_life'])
                _jp_alpha = int(220 * _jp_life_ratio)
                _jp_sz = max(1, int(_jp['size']))
                _jp_w = max(1, int(_jp_sz * _jp.get('width', 2.0)))
                _jp_h = max(1, int(_jp_sz * 2.5))  # 세로로 길쭉한 불꽃
                # 색상: 시안(0,255,200) → 퍼플(160,0,255)
                _jp_r = int(0 + 160 * (1.0 - _jp_life_ratio))
                _jp_g = int(255 * _jp_life_ratio)
                _jp_b = int(200 + 55 * (1.0 - _jp_life_ratio))
                _flame_surf = pygame.Surface((_jp_w * 2, _jp_h * 2), pygame.SRCALPHA)
                pygame.draw.ellipse(_flame_surf, (_jp_r, _jp_g, _jp_b, _jp_alpha),
                                    (0, 0, _jp_w * 2, _jp_h * 2))
                SCREEN.blit(_flame_surf, (int(_jp['x']) - _jp_w, int(_jp['y']) - _jp_h),
                            special_flags=pygame.BLEND_ADD)

            # 제트팩 활성 시 패들 아래 노즐 글로우
            if _viper_jetpack_active:
                _jg_t = pygame.time.get_ticks()
                _jg_pulse = 0.7 + 0.3 * math.sin(_jg_t / 60.0)
                # 내부 코어 (밝은 시안)
                _jg_cw, _jg_ch = int(20 * _jg_pulse), int(8 * _jg_pulse)
                if _jg_cw > 0 and _jg_ch > 0:
                    _jg_core = pygame.Surface((_jg_cw * 2, _jg_ch * 2), pygame.SRCALPHA)
                    pygame.draw.ellipse(_jg_core, (180, 255, 240, int(180 * _jg_pulse)),
                                        (0, 0, _jg_cw * 2, _jg_ch * 2))
                    SCREEN.blit(_jg_core,
                                (PLAYER.centerx - _jg_cw, PLAYER.bottom - _jg_ch),
                                special_flags=pygame.BLEND_ADD)
                # 외부 글로우 (시안)
                _jg_w, _jg_h = int(45 * _jg_pulse), int(18 * _jg_pulse)
                if _jg_w > 0 and _jg_h > 0:
                    _jg_surf = pygame.Surface((_jg_w * 2, _jg_h * 2), pygame.SRCALPHA)
                    pygame.draw.ellipse(_jg_surf, (0, 200, 180, int(70 * _jg_pulse)),
                                        (0, 0, _jg_w * 2, _jg_h * 2))
                    SCREEN.blit(_jg_surf,
                                (PLAYER.centerx - _jg_w, PLAYER.bottom - _jg_h + 2),
                                special_flags=pygame.BLEND_ADD)

            # AIR STRIKE / DIVE STRIKE 텍스트 렌더링
            if _viper_air_strike_text_timer > 0:
                _ast_alpha = min(255, int(255 * (_viper_air_strike_text_timer / 40.0)))
                _ast_scale = 1.0 + 0.3 * max(0, (60 - _viper_air_strike_text_timer)) / 60.0
                try:
                    # 급강하 어택이면 더 큰 폰트 + 다른 색상
                    _is_dive = _viper_dive_ball_boosted and _viper_air_strike_text_pct > 50
                    _ast_font_size = max(10, int((18 if _is_dive else 14) * _ast_scale))
                    _ast_font = pygame.font.Font(None, _ast_font_size)
                    _ast_text = f"{'DIVE STRIKE' if _is_dive else 'AIR STRIKE'} +{_viper_air_strike_text_pct}%"
                    # 글로우 (큰 글씨 뒤에)
                    _glow_color = (200, 80, 160) if _is_dive else (0, 180, 160)
                    _text_color = (255, 120, 255) if _is_dive else (0, 255, 220)
                    _ast_glow = _ast_font.render(_ast_text, True, _glow_color)
                    _ast_glow.set_alpha(max(0, _ast_alpha // 2))
                    _ast_glow_rect = _ast_glow.get_rect(center=(int(_viper_air_strike_text_x), int(_viper_air_strike_text_y)))
                    SCREEN.blit(_ast_glow, _ast_glow_rect, special_flags=pygame.BLEND_ADD)
                    # 본문
                    _ast_surf = _ast_font.render(_ast_text, True, _text_color)
                    _ast_surf.set_alpha(_ast_alpha)
                    _ast_rect = _ast_surf.get_rect(center=(int(_viper_air_strike_text_x), int(_viper_air_strike_text_y)))
                    SCREEN.blit(_ast_surf, _ast_rect)
                except Exception:
                    pass
        except Exception:
            pass

    # 💥 바이퍼 급강하 어택 렌더링 (착륙 연기 + 파티클)
    if _viper_dive_active or _viper_dive_particles or _viper_dive_shockwave_timer > 0:
        try:
            # 도움닫기 글로우 (공중 정지 중 에너지 집중 — 은은한 다중 레이어)
            if _viper_dive_active and _viper_dive_phase == 0:
                _dv_prep_elapsed = pygame.time.get_ticks() - _viper_dive_start_ms
                _dv_prep_pct = min(1.0, _dv_prep_elapsed / _VIPER_DIVE_PREP_MS)
                _dv_pulse = 0.5 + 0.5 * math.sin(_dv_prep_pct * math.pi * 4)
                _dv_foot_y = PLAYER.bottom
                _dv_cx = PLAYER.centerx
                _dv_emp_surf = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)

                # --- EMP 펄스 링 (발밑에서 동심원으로 퍼져나감) ---
                _dv_ring_count = 3 + int(_dv_prep_pct * 3)  # 3→6개 링
                _dv_time_ms = _dv_prep_elapsed
                for _ri in range(_dv_ring_count):
                    # 각 링이 시간차를 두고 퍼져나감
                    _ri_phase = (_ri / max(1, _dv_ring_count)) + _dv_time_ms * 0.003
                    _ri_t = (_ri_phase % 1.0)  # 0→1 순환
                    _ri_radius = int(10 + _ri_t * (60 + _dv_prep_pct * 50))
                    _ri_alpha = int(120 * (1.0 - _ri_t) * (0.5 + _dv_prep_pct * 0.5))
                    _ri_width = max(1, int(3 * (1.0 - _ri_t * 0.6)))
                    if _ri_alpha > 3 and _ri_radius > 2:
                        # 타원형 (수평으로 납작하게 — 발밑 시점)
                        _ri_w = _ri_radius * 2
                        _ri_h = max(4, int(_ri_radius * 0.5))
                        # 주 펄스 (주황-금색)
                        _ri_cr = min(255, 220 + int(35 * _dv_pulse))
                        _ri_cg = min(255, 140 + int(60 * (1.0 - _ri_t)))
                        _ri_cb = int(30 + 40 * _ri_t)
                        pygame.draw.ellipse(_dv_emp_surf, (_ri_cr, _ri_cg, _ri_cb, _ri_alpha),
                                            (_dv_cx - _ri_w // 2, _dv_foot_y - _ri_h // 2,
                                             _ri_w, _ri_h), _ri_width)
                        # 내부 밝은 엣지 (흰금색)
                        if _ri_t < 0.4:
                            _ri_inner_a = int(_ri_alpha * 0.4)
                            if _ri_inner_a > 2:
                                pygame.draw.ellipse(_dv_emp_surf, (255, 230, 180, _ri_inner_a),
                                                    (_dv_cx - _ri_w // 2 + 1, _dv_foot_y - _ri_h // 2 + 1,
                                                     _ri_w - 2, _ri_h - 2), max(1, _ri_width - 1))

                # --- 중심 에너지 코어 (발밑 — 작고 밝은 금색) ---
                _dv_core_r = int(6 + 8 * _dv_prep_pct * _dv_pulse)
                _dv_core_a = int(80 + 100 * _dv_prep_pct)
                _dv_core_h = max(3, int(_dv_core_r * 0.45))
                pygame.draw.ellipse(_dv_emp_surf, (255, 200, 80, _dv_core_a),
                                    (_dv_cx - _dv_core_r, _dv_foot_y - _dv_core_h,
                                     _dv_core_r * 2, _dv_core_h * 2))
                # 코어 하이라이트
                _dv_hi_r = max(2, _dv_core_r - 3)
                _dv_hi_h = max(2, _dv_core_h - 2)
                pygame.draw.ellipse(_dv_emp_surf, (255, 245, 200, int(_dv_core_a * 0.5)),
                                    (_dv_cx - _dv_hi_r, _dv_foot_y - _dv_hi_h,
                                     _dv_hi_r * 2, _dv_hi_h * 2))

                # --- 하강 방향 표시 (점선 → 전기 아크 스타일) ---
                _dv_line_a = int(30 + 70 * _dv_prep_pct)
                for _dli in range(0, 70, 6):
                    _dly = _dv_foot_y + _dli
                    _dv_dist_fade = max(0.1, 1.0 - _dli / 70.0)
                    if _dly < HEIGHT:
                        _dv_jitter_x = random.randint(-2, 2) if _dv_prep_pct > 0.3 else 0
                        _dl_ca = int(_dv_line_a * _dv_dist_fade)
                        if _dl_ca > 3:
                            pygame.draw.line(_dv_emp_surf, (255, 180, 60, _dl_ca),
                                             (_dv_cx - 1 + _dv_jitter_x, _dly),
                                             (_dv_cx + 1 + _dv_jitter_x, _dly + 3), 2)

                SCREEN.blit(_dv_emp_surf, (0, 0), special_flags=pygame.BLEND_ADD)

            # 급강하 궤적 글로우 (급강하 중 — EMP 펄스 잔상)
            if _viper_dive_active and _viper_dive_phase == 1:
                _dv_trail_surf = pygame.Surface((24, 50), pygame.SRCALPHA)
                pygame.draw.ellipse(_dv_trail_surf, (255, 160, 40, 90), (2, 0, 20, 50))
                pygame.draw.ellipse(_dv_trail_surf, (255, 220, 120, 50), (6, 5, 12, 35))
                SCREEN.blit(_dv_trail_surf,
                            (PLAYER.centerx - 12, PLAYER.bottom - 8),
                            special_flags=pygame.BLEND_ADD)

            # 착지 연기 효과 (바닥에 깔리는 넓은 연기 레이어)
            if _viper_dive_shockwave_timer > 0:
                _sw_pct = 1.0 - (_viper_dive_shockwave_timer / _VIPER_DIVE_SHOCKWAVE_FRAMES)
                _sw_cx = int(_viper_dive_shockwave_x)
                _sw_cy = int(_viper_dive_shockwave_y)
                _sw_alpha = int(80 * (1.0 - _sw_pct))
                # 바닥 연기 레이어 (넓게 퍼지는 타원형 — 착륙 지점 기준)
                _ground_w = int(80 + _VIPER_DIVE_SHOCKWAVE_RADIUS * _sw_pct)  # 최대 300px
                _ground_h = max(4, int(25 * (1.0 - _sw_pct * 0.5)))
                if _ground_w > 2 and _sw_alpha > 3:
                    _gs = pygame.Surface((_ground_w * 2, _ground_h * 2), pygame.SRCALPHA)
                    pygame.draw.ellipse(_gs, (160, 140, 170, _sw_alpha),
                                        (0, 0, _ground_w * 2, _ground_h * 2))
                    SCREEN.blit(_gs, (_sw_cx - _ground_w, _sw_cy - _ground_h))
                # 중심부 밝은 플래시 (착지 직후에만)
                if _sw_pct < 0.3:
                    _flash_a = int(120 * (1.0 - _sw_pct / 0.3))
                    _flash_r = int(25 + 30 * (_sw_pct / 0.3))
                    _flash_s = pygame.Surface((_flash_r * 2, _flash_r * 2), pygame.SRCALPHA)
                    pygame.draw.circle(_flash_s, (220, 200, 255, _flash_a),
                                       (_flash_r, _flash_r), _flash_r)
                    SCREEN.blit(_flash_s, (_sw_cx - _flash_r, _sw_cy - _flash_r - 5),
                                special_flags=pygame.BLEND_ADD)

            # 급강하 파티클 렌더링
            for _dp in _viper_dive_particles:
                _dp_life_ratio = max(0.0, _dp['life'] / _dp['max_life'])
                _dp_sz = max(1, int(_dp['size']))
                _dt = _dp['type']

                if _dt == 'dust_cloud':
                    # 큰 연기 구름 (부드럽고 넓은 타원)
                    _dp_alpha = int(55 * _dp_life_ratio)
                    _dc_w = max(2, int(_dp_sz * 1.6))
                    _dc_h = max(2, int(_dp_sz * 1.0))
                    _dc_surf = pygame.Surface((_dc_w * 2, _dc_h * 2), pygame.SRCALPHA)
                    # 회갈색 연기 (자연스러운 착륙 먼지)
                    _dc_r = int(150 + 30 * (1.0 - _dp_life_ratio))
                    _dc_g = int(130 + 20 * (1.0 - _dp_life_ratio))
                    _dc_b = int(120 + 40 * (1.0 - _dp_life_ratio))
                    pygame.draw.ellipse(_dc_surf, (_dc_r, _dc_g, _dc_b, _dp_alpha),
                                        (0, 0, _dc_w * 2, _dc_h * 2))
                    SCREEN.blit(_dc_surf, (int(_dp['x']) - _dc_w, int(_dp['y']) - _dc_h))

                elif _dt == 'dust_pillar':
                    # 수직 더스트 기둥 (세로로 긴 타원)
                    _dp_alpha = int(65 * _dp_life_ratio)
                    _dp_w = max(2, int(_dp_sz * 0.7))
                    _dp_h = max(2, int(_dp_sz * 1.4))
                    _dp_surf = pygame.Surface((_dp_w * 2, _dp_h * 2), pygame.SRCALPHA)
                    _pil_gray = int(170 + 40 * (1.0 - _dp_life_ratio))
                    pygame.draw.ellipse(_dp_surf, (_pil_gray, _pil_gray - 20, _pil_gray - 10, _dp_alpha),
                                        (0, 0, _dp_w * 2, _dp_h * 2))
                    SCREEN.blit(_dp_surf, (int(_dp['x']) - _dp_w, int(_dp['y']) - _dp_h))

                elif _dt == 'debris':
                    # 먼지 파편 (작고 밝은 입자)
                    _dp_alpha = int(200 * _dp_life_ratio)
                    _db_surf = pygame.Surface((_dp_sz * 2, _dp_sz * 2), pygame.SRCALPHA)
                    pygame.draw.circle(_db_surf, (200, 180, 160, _dp_alpha),
                                       (_dp_sz, _dp_sz), _dp_sz)
                    SCREEN.blit(_db_surf, (int(_dp['x']) - _dp_sz, int(_dp['y']) - _dp_sz))

                elif _dt == 'energy':
                    _dp_alpha = int(200 * _dp_life_ratio)
                    _dp_surf = pygame.Surface((_dp_sz * 2, _dp_sz * 2), pygame.SRCALPHA)
                    pygame.draw.circle(_dp_surf, (180, 100, 255, _dp_alpha),
                                       (_dp_sz, _dp_sz), _dp_sz)
                    SCREEN.blit(_dp_surf, (int(_dp['x']) - _dp_sz, int(_dp['y']) - _dp_sz),
                                special_flags=pygame.BLEND_ADD)

                else:  # trail
                    _dp_alpha = int(160 * _dp_life_ratio)
                    _dp_surf = pygame.Surface((_dp_sz * 2, _dp_sz * 2), pygame.SRCALPHA)
                    pygame.draw.circle(_dp_surf, (200, 120, 255, _dp_alpha),
                                       (_dp_sz, _dp_sz), _dp_sz)
                    SCREEN.blit(_dp_surf, (int(_dp['x']) - _dp_sz, int(_dp['y']) - _dp_sz),
                                special_flags=pygame.BLEND_ADD)
        except Exception:
            pass

    # 🔋 바이퍼 제트팩 체공 잔여시간 게이지바 (완충 시 숨김, 그 외 항상 표시)
    if selected_character_type == "viper" and _viper_jetpack_hold_timer > 0:
        try:
            _remain_ratio = max(0.0, 1.0 - _viper_jetpack_hold_timer / _get_viper_jetpack_max_hold())
            _alt_bar_h = 40
            _alt_bar_w = 3
            _alt_x = PLAYER.left - 8
            _alt_y = PLAYER.centery - _alt_bar_h // 2
            # 배경 바
            _alt_bg = pygame.Surface((_alt_bar_w + 2, _alt_bar_h + 2), pygame.SRCALPHA)
            _alt_bg.fill((0, 0, 0, 80))
            SCREEN.blit(_alt_bg, (_alt_x - 1, _alt_y - 1))
            # 채워진 바 (아래→위, 잔여량에 따라 시안→빨강 색상 변화)
            _alt_fill_h = max(1, int(_alt_bar_h * _remain_ratio))
            for _ai in range(_alt_fill_h):
                _a_pct = _ai / max(1, _alt_bar_h)
                if _remain_ratio > 0.3:
                    _a_r = int(0 + 160 * _a_pct)
                    _a_g = int(255 * (1.0 - _a_pct * 0.5))
                    _a_b = int(200 + 55 * _a_pct)
                else:
                    _blink = 0.6 + 0.4 * math.sin(pygame.time.get_ticks() / 80.0)
                    _a_r = int(255 * _blink)
                    _a_g = int(60 * _remain_ratio / 0.3)
                    _a_b = 0
                pygame.draw.line(SCREEN, (_a_r, _a_g, _a_b),
                                 (_alt_x, _alt_y + _alt_bar_h - _ai),
                                 (_alt_x + _alt_bar_w, _alt_y + _alt_bar_h - _ai))
        except Exception:
            pass

    # ✦ 바이퍼 스타버스트 타격 이펙트 렌더링 (쉐도우 백스텝/마샬 킥)
    if _viper_starburst_active:
        try:
            _sb_f = _viper_starburst_frame
            _sb_t = _sb_f / max(1, _VIPER_STARBURST_FRAMES - 1)  # 0→1
            _sb_cx = int(_viper_starburst_x)
            _sb_cy = int(_viper_starburst_y)
            _sb_dbl = _viper_starburst_is_double  # 팬텀 킥 강화 여부

            # 프레임별 파라미터: 팽창 → 최대 → 수축+페이드
            if _sb_f == 0:
                _sb_scale, _sb_alpha = 0.3, 200
            elif _sb_f == 1:
                _sb_scale, _sb_alpha = 0.7, 255
            elif _sb_f == 2:
                _sb_scale, _sb_alpha = 1.0, 220
            elif _sb_f == 3:
                _sb_scale, _sb_alpha = 0.85, 140
            else:
                _sb_scale, _sb_alpha = 0.5, 60

            # 팬텀 킥: 크기 2배, 알파 강화
            _sb_max_r = 90 if _sb_dbl else 50
            if _sb_dbl:
                _sb_alpha = min(255, int(_sb_alpha * 1.4))
            _sb_r = int(_sb_max_r * _sb_scale)

            # 광선 (더블: 16방향, 일반: 12방향)
            _sb_ray_count = 16 if _sb_dbl else 12
            _sb_surf_size = _sb_r * 4 + 4
            _sb_surf = pygame.Surface((_sb_surf_size, _sb_surf_size), pygame.SRCALPHA)
            _sb_center = _sb_surf_size // 2

            for _ri in range(_sb_ray_count):
                _r_angle = math.radians(_ri * (360.0 / _sb_ray_count) + _sb_f * (12 if _sb_dbl else 8))
                _is_main = (_ri % (4 if _sb_dbl else 3) == 0)
                _r_len = _sb_r * (2.2 if _sb_dbl and _is_main else 1.8 if _is_main else 1.0)
                _r_width = max(1, int((4 if _sb_dbl and _is_main else 3 if _is_main else 2) * (1.0 - _sb_t * 0.5)))
                _r_end_x = _sb_center + math.cos(_r_angle) * _r_len
                _r_end_y = _sb_center + math.sin(_r_angle) * _r_len
                _r_alpha = min(255, int(_sb_alpha * (0.95 if _is_main else 0.5)))
                # 더블: 밝은 화이트-핑크, 일반: 핑크퍼플
                if _sb_dbl:
                    _r_color = (255, 180, 255, _r_alpha) if _is_main else (220, 140, 255, _r_alpha)
                else:
                    _r_color = (220, 160, 255, _r_alpha)
                pygame.draw.line(_sb_surf, _r_color,
                                 (_sb_center, _sb_center),
                                 (int(_r_end_x), int(_r_end_y)), _r_width)

            # 중심 글로우
            _sb_glow_r = max(2, int(_sb_r * (0.6 if _sb_dbl else 0.5)))
            _glow_color = (255, 230, 255, min(255, _sb_alpha)) if _sb_dbl else (255, 220, 255, min(255, _sb_alpha))
            pygame.draw.circle(_sb_surf, _glow_color, (_sb_center, _sb_center), _sb_glow_r)
            _sb_core_r = max(1, int(_sb_r * (0.3 if _sb_dbl else 0.25)))
            pygame.draw.circle(_sb_surf, (255, 245, 255, min(255, _sb_alpha)),
                               (_sb_center, _sb_center), _sb_core_r)

            SCREEN.blit(_sb_surf, (_sb_cx - _sb_center, _sb_cy - _sb_center),
                        special_flags=pygame.BLEND_ADD)

            # 프레임 진행
            _viper_starburst_timer += 1
            if _viper_starburst_timer >= _VIPER_STARBURST_FRAME_DUR:
                _viper_starburst_timer = 0
                _viper_starburst_frame += 1
                if _viper_starburst_frame >= _VIPER_STARBURST_FRAMES:
                    _viper_starburst_active = False
        except Exception:
            _viper_starburst_active = False

    # ✦ EMP 스트라이크 차징 화염 파티클 (발밑에서 튀어오르는 불꽃)
    if _viper_dive_charge_particles:
        try:
            _dcr_surf = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
            _dcr_alive = []
            for _dcp in _viper_dive_charge_particles:
                _dcp['x'] += _dcp['vx']
                _dcp['y'] += _dcp['vy']
                _dcp['vy'] -= 0.05  # 위로 가속 (불꽃 상승)
                _dcp['vx'] *= 0.97
                _dcp['life'] -= 1
                if _dcp['life'] > 0:
                    _dcr_alive.append(_dcp)
                    _dcp_t = _dcp['life'] / _dcp['max_life']
                    _dcp_a = int(220 * _dcp_t)
                    _dcp_sz = max(1, int(_dcp['size'] * (0.3 + _dcp_t * 0.7)))
                    _dcp_c = _dcp['color']
                    # 외곽 글로우
                    if _dcp_sz > 1:
                        _dcp_ga = int(_dcp_a * 0.4)
                        if _dcp_ga > 3:
                            pygame.draw.circle(_dcr_surf, (min(255, _dcp_c[0] + 20), _dcp_c[1] // 2, 0, _dcp_ga),
                                               (int(_dcp['x']), int(_dcp['y'])), _dcp_sz + 3)
                    # 메인 불꽃
                    pygame.draw.circle(_dcr_surf, (*_dcp_c, _dcp_a),
                                       (int(_dcp['x']), int(_dcp['y'])), _dcp_sz)
                    # 밝은 코어 (수명 50% 이상일 때)
                    if _dcp_t > 0.5 and _dcp_sz > 1:
                        _dcp_ca = int(_dcp_a * 0.6)
                        pygame.draw.circle(_dcr_surf, (255, 255, 200, _dcp_ca),
                                           (int(_dcp['x']), int(_dcp['y'])), max(1, _dcp_sz - 1))
            _viper_dive_charge_particles = _dcr_alive
            SCREEN.blit(_dcr_surf, (0, 0), special_flags=pygame.BLEND_ADD)
        except Exception:
            _viper_dive_charge_particles = []

    # ✦ 팬텀 킥 흑연 오라 (다크 플레임 나선 — 패들 주변)
    if _viper_phantom_aura_active and _viper_wall_dive_active and _viper_is_double_marshal:
        try:
            _pa_now = pygame.time.get_ticks()
            _pa_elapsed = (_pa_now - _viper_phantom_aura_start_ms) * 0.001
            _pa_cx = float(PLAYER.centerx)
            _pa_cy = float(PLAYER.centery)
            _pa_surf = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)

            # --- 1. 내부 암흑 글로우 (크고 강렬한 맥동) ---
            _pa_pulse = 0.6 + 0.4 * math.sin(_pa_elapsed * 4.5)
            _pa_inner_r = int(55 * _pa_pulse)
            for _pa_ir in range(_pa_inner_r, max(0, _pa_inner_r - 40), -3):
                _pa_ia = int(70 * (1.0 - (_pa_inner_r - _pa_ir) / 40.0) * _pa_pulse)
                if _pa_ia > 1:
                    pygame.draw.circle(_pa_surf, (50, 5, 75, _pa_ia), (int(_pa_cx), int(_pa_cy)), _pa_ir)
            # 코어 글로우 (밝은 보라 핵심)
            _pa_core_r = int(18 * _pa_pulse)
            pygame.draw.circle(_pa_surf, (120, 30, 170, int(90 * _pa_pulse)), (int(_pa_cx), int(_pa_cy)), _pa_core_r)
            pygame.draw.circle(_pa_surf, (80, 15, 120, int(50 * _pa_pulse)), (int(_pa_cx), int(_pa_cy)), _pa_core_r + 8)

            # --- 2. 다크 플레임 나선 (6개, 더 길고 두껍고 강렬) ---
            for _pa_si in range(6):
                _pa_spiral_base = (_pa_si / 6.0) * math.tau + _pa_elapsed * 2.5
                for _pa_sj in range(18):
                    _pa_t = _pa_sj / 18.0
                    _pa_ang = _pa_spiral_base + _pa_t * 3.5
                    _pa_r = 12 + _pa_t * 55
                    _pa_wobble = math.sin(_pa_elapsed * 6.0 + _pa_sj * 0.6 + _pa_si) * 5.0
                    _pa_sx = _pa_cx + math.cos(_pa_ang) * (_pa_r + _pa_wobble)
                    _pa_sy = _pa_cy + math.sin(_pa_ang) * (_pa_r + _pa_wobble)
                    _pa_flame_a = int(180 * (1.0 - _pa_t * 0.6) * _pa_pulse)
                    _pa_flame_sz = max(1, int(6.0 * (1.0 - _pa_t * 0.4)))
                    if _pa_flame_a > 3:
                        _pa_cr = int(75 * (1.0 - _pa_t * 0.5))
                        _pa_cg = int(12 * (1.0 - _pa_t * 0.7))
                        _pa_cb = int(110 * (1.0 - _pa_t * 0.3))
                        pygame.draw.circle(_pa_surf, (_pa_cr, _pa_cg, _pa_cb, _pa_flame_a),
                                           (int(_pa_sx), int(_pa_sy)), _pa_flame_sz)
                        # 보라빛 속심 하이라이트 (안쪽 절반)
                        if _pa_sj < 8:
                            _pa_hi_a = int(80 * (1.0 - _pa_t * 1.5) * _pa_pulse)
                            if _pa_hi_a > 2:
                                pygame.draw.circle(_pa_surf, (140, 40, 180, _pa_hi_a),
                                                   (int(_pa_sx), int(_pa_sy)), max(1, _pa_flame_sz - 1))

            # --- 3. 외곽 암흑 연기 파티클 (14개, 크고 밝게) ---
            for _pa_pi in range(14):
                _pa_pp = (_pa_pi / 14.0) * math.tau
                _pa_p_spd = 0.8 + (_pa_pi % 3) * 0.4
                _pa_p_ang = _pa_pp + _pa_elapsed * _pa_p_spd
                _pa_p_r = 50 + math.sin(_pa_elapsed * 2.5 + _pa_pp) * 12
                _pa_px = _pa_cx + math.cos(_pa_p_ang) * _pa_p_r
                _pa_py = _pa_cy + math.sin(_pa_p_ang) * _pa_p_r
                _pa_p_a = int(100 + 50 * math.sin(_pa_elapsed * 3.5 + _pa_pi))
                _pa_p_sz = 4 + (_pa_pi % 3)
                if _pa_p_a > 5:
                    pygame.draw.circle(_pa_surf, (40, 5, 60, _pa_p_a),
                                       (int(_pa_px), int(_pa_py)), _pa_p_sz)
                    # 잔상 꼬리 (3단)
                    for _pa_pt in range(3):
                        _pa_tail_ang = _pa_p_ang - _pa_p_spd * 0.1 * (_pa_pt + 1)
                        _pa_tail_r = _pa_p_r - _pa_pt * 3
                        _pa_tx = _pa_cx + math.cos(_pa_tail_ang) * _pa_tail_r
                        _pa_ty = _pa_cy + math.sin(_pa_tail_ang) * _pa_tail_r
                        _pa_ta = int(_pa_p_a * 0.5 * (1.0 - _pa_pt * 0.3))
                        if _pa_ta > 2:
                            pygame.draw.circle(_pa_surf, (30, 3, 50, _pa_ta),
                                               (int(_pa_tx), int(_pa_ty)), max(1, _pa_p_sz - _pa_pt))

            # --- 4. 외곽 흑연 링 (이중, 강한 맥동) ---
            _pa_ring_r = int(65 + math.sin(_pa_elapsed * 3.0) * 8)
            _pa_ring_a = int(60 + 35 * math.sin(_pa_elapsed * 5.0))
            if _pa_ring_a > 3:
                pygame.draw.circle(_pa_surf, (60, 8, 90, _pa_ring_a),
                                   (int(_pa_cx), int(_pa_cy)), _pa_ring_r, 3)
                pygame.draw.circle(_pa_surf, (80, 15, 115, _pa_ring_a // 2),
                                   (int(_pa_cx), int(_pa_cy)), _pa_ring_r + 6, 2)
                # 두 번째 외곽 링 (더 크고 희미)
                _pa_ring2_r = _pa_ring_r + 18
                _pa_ring2_a = int(_pa_ring_a * 0.4)
                if _pa_ring2_a > 2:
                    pygame.draw.circle(_pa_surf, (45, 5, 70, _pa_ring2_a),
                                       (int(_pa_cx), int(_pa_cy)), _pa_ring2_r, 2)

            SCREEN.blit(_pa_surf, (0, 0))
        except Exception:
            pass

    # ✦ 팬텀 킥 암흑 에너지 파편 파티클 업데이트 + 렌더링
    if _viper_phantom_hit_particles:
        try:
            _php_surf = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
            _php_alive = []
            for _php in _viper_phantom_hit_particles:
                _php['x'] += _php['vx']
                _php['y'] += _php['vy']
                _php['vx'] *= 0.97
                _php['vy'] *= 0.97
                _php['vy'] += 0.04
                _php['life'] -= 1
                if _php['life'] > 0:
                    _php_alive.append(_php)
                    _php_t = _php['life'] / _php['max_life']
                    _php_a = int(255 * min(1.0, _php_t * 1.3))
                    _php_sz = max(1, int(_php['size'] * (0.4 + _php_t * 0.6)))
                    _php_c = _php['color']
                    # 외곽 글로우 (모든 파편에 적용)
                    if _php_sz > 1:
                        _php_ga = int(_php_a * 0.35)
                        if _php_ga > 3:
                            pygame.draw.circle(_php_surf, (min(255, _php_c[0] + 30), _php_c[1] + 5, min(255, _php_c[2] + 40), _php_ga),
                                               (int(_php['x']), int(_php['y'])), _php_sz + 3)
                    # 메인 파편
                    pygame.draw.circle(_php_surf, (*_php_c, _php_a),
                                       (int(_php['x']), int(_php['y'])), _php_sz)
                    # 밝은 코어 (50%에 적용)
                    if _php.get('glow') and _php_sz > 1:
                        _php_ca = int(_php_a * 0.5)
                        if _php_ca > 3:
                            pygame.draw.circle(_php_surf, (min(255, _php_c[0] + 80), _php_c[1] + 20, min(255, _php_c[2] + 70), _php_ca),
                                               (int(_php['x']), int(_php['y'])), max(1, _php_sz - 1))
            _viper_phantom_hit_particles = _php_alive
            SCREEN.blit(_php_surf, (0, 0))
        except Exception:
            _viper_phantom_hit_particles = []

    # ✦ 팬텀 킥 프리즈 연출 + 텍스트 렌더링
    # 🐍 팬텀 킥 텍스트 타이머 감소 (렌더링은 draw_objects 맨 끝에서 수행 - 모든 오브젝트 위에 표시)
    if _viper_dmk_freeze_active or _viper_dmk_text_active:
        _viper_dmk_text_timer -= 1
        if _viper_dmk_text_timer <= 0:
            _viper_dmk_text_active = False

    # ⚡ 바이퍼 쉐도우 백스텝 에너지파 렌더링
    if _viper_ss_wave_active:
        try:
            _sw_x = int(_viper_ss_wave_x)
            _sw_y = int(_viper_ss_wave_y)
            _sw_ticks = pygame.time.get_ticks()
            _sw_dt = _sw_ticks / 1000.0
            # 진행도 (0→1)
            _sw_total_dist = abs(_viper_ss_wave_target_x - _viper_ss_wave_origin_x)
            _sw_progress = min(1.0, abs(_viper_ss_wave_x - _viper_ss_wave_origin_x) / max(1.0, _sw_total_dist))

            # ── 잔상 트레일 (그라데이션 리본) ──
            _sw_trail_len = len(_viper_ss_wave_trail)
            for _swi in range(_sw_trail_len):
                _swt_x, _swt_y = _viper_ss_wave_trail[_swi]
                _swt_ratio = _swi / max(1, _sw_trail_len - 1)
                _swt_w = int(20 + 15 * _swt_ratio)
                _swt_h = int(6 + 10 * _swt_ratio)
                _swt_alpha = int(20 + 80 * _swt_ratio)
                _swt_r = int(100 + 60 * (1.0 - _swt_ratio))
                _swt_g = int(0 + 120 * _swt_ratio)
                _swt_b = int(180 + 60 * _swt_ratio)
                _swt_s = pygame.Surface((_swt_w * 2, _swt_h * 2), pygame.SRCALPHA)
                pygame.draw.ellipse(_swt_s, (_swt_r, _swt_g, _swt_b, _swt_alpha),
                                    (0, 0, _swt_w * 2, _swt_h * 2))
                SCREEN.blit(_swt_s, (int(_swt_x) - _swt_w, int(_swt_y) - _swt_h),
                            special_flags=pygame.BLEND_ADD)

            # ── 에너지파 본체 (초승달형 + 글로우) ──
            _sw_size = 60
            _sw_surf = pygame.Surface((_sw_size * 2, _sw_size), pygame.SRCALPHA)
            _sw_scx = _sw_size  # 서피스 중앙 X
            _sw_scy = _sw_size // 2  # 서피스 중앙 Y
            _sw_pulse = 0.8 + 0.2 * math.sin(_sw_dt * 16.0)

            # 외곽 글로우 (3겹)
            for _swg in range(3):
                _swg_r = _sw_size - _swg * 10
                _swg_h = int((30 - _swg * 6) * _sw_pulse)
                _swg_alpha = int((30 + _swg * 15) * _sw_pulse)
                if _swg_r > 0 and _swg_h > 0:
                    pygame.draw.ellipse(_sw_surf, (120 + _swg * 30, _swg * 40, 220 + _swg * 10, _swg_alpha),
                                        (_sw_scx - _swg_r, _sw_scy - _swg_h, _swg_r * 2, _swg_h * 2))

            # 코어 (밝은 크레센트)
            _sw_core_w = 35
            _sw_core_h = int(14 * _sw_pulse)
            pygame.draw.ellipse(_sw_surf, (200, 140, 255, 160),
                                (_sw_scx - _sw_core_w, _sw_scy - _sw_core_h, _sw_core_w * 2, _sw_core_h * 2))
            # 하이라이트
            _sw_hl_w = 20
            _sw_hl_h = max(2, int(6 * _sw_pulse))
            pygame.draw.ellipse(_sw_surf, (255, 240, 255, 200),
                                (_sw_scx - _sw_hl_w, _sw_scy - _sw_hl_h, _sw_hl_w * 2, _sw_hl_h * 2))

            SCREEN.blit(_sw_surf, (_sw_x - _sw_size, _sw_y - _sw_size // 2),
                        special_flags=pygame.BLEND_ADD)

            # ── 선도 스파크 (진행 방향 앞쪽) ──
            for _ssi in range(3):
                _ss_angle = _sw_dt * 10.0 + _ssi * 2.094
                _ss_dx = _viper_ss_wave_dir * (15 + 8 * math.sin(_ss_angle))
                _ss_dy = int(math.cos(_ss_angle) * 8)
                _ss_px = _sw_x + int(_ss_dx)
                _ss_py = _sw_y + _ss_dy
                _ss_r = max(1, 3 - _ssi)
                _ss_surf = pygame.Surface((_ss_r * 4, _ss_r * 4), pygame.SRCALPHA)
                pygame.draw.circle(_ss_surf, (180, 120, 255, 150), (_ss_r * 2, _ss_r * 2), _ss_r * 2)
                pygame.draw.circle(_ss_surf, (255, 240, 255, 220), (_ss_r * 2, _ss_r * 2), max(1, _ss_r))
                SCREEN.blit(_ss_surf, (_ss_px - _ss_r * 2, _ss_py - _ss_r * 2),
                            special_flags=pygame.BLEND_ADD)
        except Exception:
            pass

    # ⛓️ 바이퍼 마샬 킥 렌더링 (검보라 사슬 + 잔상 + 돌진 궤적)
    if _viper_wall_dive_active or _viper_wall_dive_particles or _viper_wall_dive_web_lines:
        try:
            _wd_ticks = pygame.time.get_ticks()
            # ⛓️ 검보라색 사슬 라인 그리기 (살짝 처지는 곡선 + 다층 글로우)
            for _wl in _viper_wall_dive_web_lines:
                _wl_x1, _wl_y1, _wl_x2, _wl_y2 = _wl
                _ch_dx = _wl_x2 - _wl_x1
                _ch_dy = _wl_y2 - _wl_y1
                _ch_dist = math.sqrt(_ch_dx * _ch_dx + _ch_dy * _ch_dy)
                if _ch_dist < 2:
                    continue
                # 수직 방향 (처짐용)
                _ch_perp_x = -_ch_dy / _ch_dist
                _ch_perp_y = _ch_dx / _ch_dist
                _ch_sag = 0.0  # 직선 로프 (처짐 없음)
                # 곡선 포인트 계산 (부드러운 카테너리)
                _ch_segs = max(6, int(_ch_dist / 8))
                _ch_points = []
                for _ci in range(_ch_segs + 1):
                    _ch_f = _ci / _ch_segs
                    _ch_px = _wl_x1 + _ch_dx * _ch_f
                    _ch_py = _wl_y1 + _ch_dy * _ch_f
                    _ch_droop = _ch_sag * math.sin(_ch_f * math.pi)
                    _ch_px += _ch_perp_x * _ch_droop
                    _ch_py += _ch_perp_y * _ch_droop
                    _ch_points.append((int(_ch_px), int(_ch_py)))
                if len(_ch_points) < 2:
                    continue
                # 글로우 서피스
                _wl_min_x = min(p[0] for p in _ch_points) - 15
                _wl_min_y = min(p[1] for p in _ch_points) - 15
                _wl_max_x = max(p[0] for p in _ch_points) + 15
                _wl_max_y = max(p[1] for p in _ch_points) + 15
                _wl_sw = max(1, _wl_max_x - _wl_min_x)
                _wl_sh = max(1, _wl_max_y - _wl_min_y)
                _wl_local = [(p[0] - _wl_min_x, p[1] - _wl_min_y) for p in _ch_points]
                _wl_gs = pygame.Surface((_wl_sw, _wl_sh), pygame.SRCALPHA)
                # 레이어 1: 넓은 외부 글로우 (어두운 보라)
                pygame.draw.lines(_wl_gs, (50, 10, 80, 30), False, _wl_local, 10)
                # 레이어 2: 중간 글로우 (검보라)
                pygame.draw.lines(_wl_gs, (70, 15, 110, 50), False, _wl_local, 6)
                SCREEN.blit(_wl_gs, (_wl_min_x, _wl_min_y), special_flags=pygame.BLEND_ADD)
                # 레이어 3: 코어 라인 (밝은 검보라, 메인)
                _wl_pulse = 0.85 + 0.15 * math.sin(_wd_ticks * 0.008)
                _wl_core_col = (int(90 * _wl_pulse), int(25 * _wl_pulse), int(140 * _wl_pulse))
                pygame.draw.lines(SCREEN, _wl_core_col, False, _ch_points, 3)
                # 레이어 4: 하이라이트 중심선 (밝은 보라 광택)
                _wl_hi_col = (int(140 * _wl_pulse), int(60 * _wl_pulse), int(200 * _wl_pulse), int(100 * _wl_pulse))
                _wl_hs = pygame.Surface((_wl_sw, _wl_sh), pygame.SRCALPHA)
                pygame.draw.lines(_wl_hs, _wl_hi_col, False, _wl_local, 1)
                SCREEN.blit(_wl_hs, (_wl_min_x, _wl_min_y))

            # 벽 매달림 글로우 (Phase 1)
            if _viper_wall_dive_active and _viper_wall_dive_phase == 1:
                _cling_pulse = 0.6 + 0.4 * math.sin(_wd_ticks * 0.02)
                _cling_r = int(35 * _cling_pulse)
                _cling_s = pygame.Surface((_cling_r * 2, _cling_r * 2), pygame.SRCALPHA)
                pygame.draw.circle(_cling_s, (70, 10, 120, int(80 * _cling_pulse)),
                                   (_cling_r, _cling_r), _cling_r)
                SCREEN.blit(_cling_s,
                            (int(_viper_wall_dive_wall_x) - _cling_r,
                             int(_viper_wall_dive_wall_y) - _cling_r),
                            special_flags=pygame.BLEND_ADD)

            # 돌진 궤적 (Phase 2)
            if _viper_wall_dive_active and _viper_wall_dive_phase == 2:
                _ch_elapsed = _wd_ticks - _viper_wall_dive_start_ms
                _ch_charge_ms = _VIPER_WALL_DIVE_CHARGE_MS / 1.3 if _viper_is_double_marshal else _VIPER_WALL_DIVE_CHARGE_MS
                _ch_t = min(1.0, _ch_elapsed / _ch_charge_ms)
                _ch_cx = PLAYER.centerx
                _ch_cy = PLAYER.centery
                # 돌진 글로우
                _ch_glow_r = int(25 + 15 * (1.0 - _ch_t))
                _ch_glow_s = pygame.Surface((_ch_glow_r * 2, _ch_glow_r * 2), pygame.SRCALPHA)
                pygame.draw.circle(_ch_glow_s, (80, 15, 140, 140),
                                   (_ch_glow_r, _ch_glow_r), _ch_glow_r)
                SCREEN.blit(_ch_glow_s,
                            (_ch_cx - _ch_glow_r, _ch_cy - _ch_glow_r),
                            special_flags=pygame.BLEND_ADD)
                # 돌진 방향 선 (검보라)
                pygame.draw.line(SCREEN, (80, 20, 130),
                                 (int(_viper_wall_dive_charge_start_x), int(_viper_wall_dive_charge_start_y)),
                                 (_ch_cx, _ch_cy), 3)

            # 파티클 렌더링 (검보라 톤)
            for _wp in _viper_wall_dive_particles:
                _wp_alpha = int(200 * (_wp['life'] / max(1, _wp['max_life'])))
                _wp_sz = max(1, int(_wp['size']))
                if _wp['type'] == 'trail':
                    _wp_col = (70, 18, 110, _wp_alpha)
                else:
                    _wp_col = (100, 30, 160, _wp_alpha)
                _wp_s = pygame.Surface((_wp_sz * 2, _wp_sz * 2), pygame.SRCALPHA)
                pygame.draw.circle(_wp_s, _wp_col, (_wp_sz, _wp_sz), _wp_sz)
                SCREEN.blit(_wp_s, (int(_wp['x']) - _wp_sz, int(_wp['y']) - _wp_sz),
                            special_flags=pygame.BLEND_ADD)
        except Exception:
            pass

    # 🛡️ 인게임 호위무사 캐릭터 및 스킬 이펙트 그리기 (일반 스테이지, 최대 2명)
    if not arena_mode_enabled:
        try:
            from game_mechanics.ingame_bodyguard import get_bodyguard, get_bodyguard2
            for _bodyguard in [get_bodyguard(), get_bodyguard2()]:
                if _bodyguard.active:
                    _bodyguard.draw(SCREEN, boss_rect=BOSS, player_rect=PLAYER, ball_rect=BALL)
                    _bodyguard.draw_entrance_speech(SCREEN, PLAYER)
        except Exception:
            pass

        # 🔥 인게임 호위무사 도깨비불 공 이펙트 그리기 (Ultra Premium)
        if _ingame_bodyguard_dokkaebi_ball and BALL:
            _dokkaebi_time = pygame.time.get_ticks() / 1000.0
            _ball_cx, _ball_cy = BALL.centerx, BALL.centery
            _ball_r = BALL.width // 2
            _dt = _dokkaebi_time

            # ── 1. 외곽 대기 오라 (6겹) ──
            for i in range(6):
                _glow_r = _ball_r + 10 + i * 7
                _glow_alpha = int(100 - i * 14)
                _flicker = 0.6 + 0.4 * math.sin(_dt * 10 + i * 1.3)
                _glow_alpha = int(_glow_alpha * _flicker)
                if _glow_alpha > 0:
                    _glow_surf = pygame.Surface((_glow_r * 2, _glow_r * 2), pygame.SRCALPHA)
                    _cr = max(0, min(255, int(40 + 60 * math.sin(_dt * 4.0 + i * 0.8))))
                    _cg = max(0, min(255, int(160 + 60 * math.sin(_dt * 6.0 + i * 0.5))))
                    _glow_alpha = max(0, min(255, _glow_alpha))
                    pygame.draw.circle(_glow_surf, (_cr, _cg, 255, _glow_alpha), (_glow_r, _glow_r), _glow_r)
                    SCREEN.blit(_glow_surf, (_ball_cx - _glow_r, _ball_cy - _glow_r), special_flags=pygame.BLEND_ADD)

            # ── 2. 외곽 불꽃 실루엣 ──
            _outer_surf_size = _ball_r * 6
            _outer_surf = pygame.Surface((_outer_surf_size, _outer_surf_size), pygame.SRCALPHA)
            _outer_cx, _outer_cy = _outer_surf_size // 2, _outer_surf_size // 2
            _outer_flame = []
            for _ai in range(24):
                _rad = math.radians(_ai * 15)
                _base_dist = _ball_r * (1.6 + 0.5 * math.sin(_dt * 6.0 + _ai * 0.6))
                if 3 < _ai < 9:
                    _base_dist *= 1.6 + 0.3 * math.sin(_dt * 9.0 + _ai)
                _fx = _outer_cx + math.sin(_rad) * _base_dist * 0.85
                _fy = _outer_cy - math.cos(_rad) * _base_dist
                _outer_flame.append((_fx, _fy))
            if len(_outer_flame) >= 3:
                pygame.draw.polygon(_outer_surf, (50, 140, 220, 60), _outer_flame)
                pygame.draw.polygon(_outer_surf, (70, 170, 245, 40), _outer_flame, 2)
            SCREEN.blit(_outer_surf, (_ball_cx - _outer_cx, _ball_cy - _outer_cy), special_flags=pygame.BLEND_ADD)

            # ── 3. 메인 불꽃 본체 (다층 그라디언트) ──
            _core_surf_size = _ball_r * 5
            _core_surf = pygame.Surface((_core_surf_size, _core_surf_size), pygame.SRCALPHA)
            _core_cx, _core_cy = _core_surf_size // 2, _core_surf_size // 2

            _flame_layers = [
                (1.0, 0.85, (80, 190, 255, 140), 18),
                (0.82, 0.75, (100, 210, 255, 180), 16),
                (0.65, 0.6, (140, 230, 255, 210), 14),
                (0.48, 0.45, (190, 245, 255, 230), 12),
            ]
            for _lr, _lr_inner, _lcolor, _lseg in _flame_layers:
                _layer_pts = []
                for _li in range(_lseg):
                    _rad = math.radians(_li * (360 / _lseg))
                    _ldist = _ball_r * (_lr + 0.2 * math.sin(_dt * 8.0 + _li * 0.7))
                    if math.degrees(_rad) > 30 and math.degrees(_rad) < 150:
                        _ldist *= 1.5 + 0.2 * math.sin(_dt * 10.0 + _li)
                    _lx = _core_cx + math.sin(_rad) * _ldist * 0.8
                    _ly = _core_cy - math.cos(_rad) * _ldist
                    _layer_pts.append((_lx, _ly))
                if len(_layer_pts) >= 3:
                    pygame.draw.polygon(_core_surf, _lcolor, _layer_pts)

            # ── 4. 내부 에너지 흐름 (나선 패턴) ──
            for _si in range(3):
                _spiral_pts = []
                for _sj in range(12):
                    _s_angle = _dt * 4.0 + _si * (math.pi * 2 / 3) + _sj * 0.4
                    _s_dist = _ball_r * (0.3 + _sj * 0.06)
                    _sx = _core_cx + _s_dist * math.cos(_s_angle)
                    _sy = _core_cy + _s_dist * math.sin(_s_angle) * 0.7 - _sj * 1.5
                    _spiral_pts.append((int(_sx), int(_sy)))
                if len(_spiral_pts) >= 2:
                    _s_alpha = int(60 + 40 * math.sin(_dt * 6.0 + _si * 2.0))
                    pygame.draw.lines(_core_surf, (160, 240, 255, _s_alpha), False, _spiral_pts, 1)

            # ── 5. 중심 코어 ──
            pygame.draw.circle(_core_surf, (160, 240, 255, 200), (_core_cx, _core_cy), int(_ball_r * 0.7))
            pygame.draw.circle(_core_surf, (200, 250, 255, 240), (_core_cx, _core_cy), int(_ball_r * 0.5))
            pygame.draw.circle(_core_surf, (235, 255, 255, 255), (_core_cx, _core_cy), int(_ball_r * 0.3))
            pygame.draw.circle(_core_surf, (255, 255, 255, 200), (_core_cx, _core_cy - 3), int(_ball_r * 0.2))

            SCREEN.blit(_core_surf, (_ball_cx - _core_cx, _ball_cy - _core_cy), special_flags=pygame.BLEND_ADD)

            # ── 6. 도깨비 형상 (불꽃 속 도깨비 얼굴 실루엣) ──
            _face_pulse = 0.5 + 0.5 * math.sin(_dt * 5.0)
            _face_base_a = int(160 * _face_pulse)
            if _face_base_a > 20:
                _face_sz = int(_ball_r * 3.5)
                _face_surf = pygame.Surface((_face_sz * 2, _face_sz * 2), pygame.SRCALPHA)
                _fcx, _fcy = _face_sz, _face_sz

                # 뿔 (2개 - 불꽃 위로 솟은 뿔 형상)
                _horn_a = int(_face_base_a * 0.45)
                for _hdir in [-1, 1]:
                    pygame.draw.polygon(_face_surf, (100, 220, 255, _horn_a), [
                        (_fcx + _hdir * int(_ball_r * 0.7), _fcy - int(_ball_r * 0.5)),
                        (_fcx + _hdir * int(_ball_r * 1.0), _fcy - int(_ball_r * 1.6) - int(3 * math.sin(_dt * 6.0 + _hdir))),
                        (_fcx + _hdir * int(_ball_r * 0.35), _fcy - int(_ball_r * 0.6)),
                    ])

                # 얼굴 윤곽 (타원)
                _face_a = int(_face_base_a * 0.25)
                _face_w = int(_ball_r * 1.6)
                _face_h = int(_ball_r * 1.3)
                pygame.draw.ellipse(_face_surf, (80, 200, 255, _face_a),
                                   (_fcx - _face_w // 2, _fcy - _face_h // 2, _face_w, _face_h))

                # 눈 (붉은 삼각형 눈 - 도깨비 특유의 날카로운 눈)
                _eye_a = int(_face_base_a * 0.7)
                for _edir in [-1, 1]:
                    _ex = _fcx + _edir * int(_ball_r * 0.35)
                    _ey = _fcy - int(_ball_r * 0.15)
                    # 눈 외곽 글로우
                    pygame.draw.circle(_face_surf, (255, 80, 30, _eye_a // 3), (_ex, _ey), int(_ball_r * 0.3))
                    # 삼각형 눈
                    pygame.draw.polygon(_face_surf, (255, 100, 50, _eye_a), [
                        (_ex + _edir * int(_ball_r * 0.25), _ey),
                        (_ex - _edir * int(_ball_r * 0.08), _ey - int(_ball_r * 0.25)),
                        (_ex - _edir * int(_ball_r * 0.08), _ey + int(_ball_r * 0.12)),
                    ])
                    # 눈동자 (밝은 노랑)
                    _pupil_pulse = 0.7 + 0.3 * math.sin(_dt * 10.0 + _edir * 1.5)
                    _pupil_a = int(_eye_a * _pupil_pulse)
                    pygame.draw.circle(_face_surf, (255, 200, 80, _pupil_a),
                                     (_ex + _edir * int(_ball_r * 0.05), _ey), max(1, int(_ball_r * 0.08)))
                    pygame.draw.circle(_face_surf, (255, 255, 220, min(255, _pupil_a + 30)),
                                     (_ex + _edir * int(_ball_r * 0.03), _ey - 1), max(1, int(_ball_r * 0.04)))

                # 입 (크게 벌린 도깨비 입 + 이빨)
                _mouth_a = int(_face_base_a * 0.35)
                _mouth_w = int(_ball_r * 0.9)
                _mouth_h = int(_ball_r * 0.4)
                _mouth_y = _fcy + int(_ball_r * 0.25)
                pygame.draw.ellipse(_face_surf, (40, 140, 220, _mouth_a),
                                   (_fcx - _mouth_w // 2, _mouth_y, _mouth_w, _mouth_h))
                # 이빨 (톱니)
                _teeth_a = int(_face_base_a * 0.35)
                _tooth_count = 5
                for _ti in range(_tooth_count):
                    _tx = _fcx - _mouth_w // 2 + int((_ti + 0.5) * _mouth_w / _tooth_count)
                    _th = int(_ball_r * 0.12) + int(2 * math.sin(_dt * 5.0 + _ti))
                    pygame.draw.polygon(_face_surf, (200, 240, 255, _teeth_a), [
                        (_tx - 2, _mouth_y + 1),
                        (_tx + 2, _mouth_y + 1),
                        (_tx, _mouth_y + _th),
                    ])

                SCREEN.blit(_face_surf, (_ball_cx - _face_sz, _ball_cy - _face_sz), special_flags=pygame.BLEND_ADD)

            # ── 7. 엣지 스파크 ──
            for _spi in range(5):
                _sp_angle = _dt * 5.0 + _spi * (math.pi * 2 / 5)
                _sp_dist = _ball_r * (1.8 + 0.6 * math.sin(_dt * 12.0 + _spi * 3.0))
                _sp_x = _ball_cx + _sp_dist * math.sin(_sp_angle) * 0.7
                _sp_y = _ball_cy - _sp_dist * math.cos(_sp_angle) * 0.9
                _sp_bright = 0.3 + 0.7 * abs(math.sin(_dt * 15.0 + _spi * 2.5))
                _sp_a = int(140 * _sp_bright)
                if _sp_a > 10:
                    _sp_sz = max(1, int(2 * _sp_bright))
                    _sp_surf = pygame.Surface((_sp_sz * 2 + 6, _sp_sz * 2 + 6), pygame.SRCALPHA)
                    pygame.draw.circle(_sp_surf, (100, 220, 255, _sp_a // 3), (_sp_sz + 3, _sp_sz + 3), _sp_sz + 3)
                    pygame.draw.circle(_sp_surf, (200, 250, 255, _sp_a), (_sp_sz + 3, _sp_sz + 3), _sp_sz)
                    SCREEN.blit(_sp_surf, (int(_sp_x) - _sp_sz - 3, int(_sp_y) - _sp_sz - 3), special_flags=pygame.BLEND_ADD)

    try:
        from item_effects.foul_whistle import get_foul_whistle_instance

        foul_whistle = get_foul_whistle_instance()
        if foul_whistle:
            foul_whistle.update()
            foul_whistle.draw(SCREEN, WIDTH, HEIGHT)
            if foul_whistle_pending_round_reset and foul_whistle.consume_reset_ready():
                foul_whistle_pending_round_reset = False
                foul_whistle.animation_active = False
                foul_whistle.animation_frame = 0
                go_to_next_round()
                return
    except Exception as e:
        print(f"[ERROR] 반칙호루라기 이펙트 처리 오류: {e}")
    #  서브 대기 상태 UI (미니멀 디자인)
    if is_waiting_for_serve:
        # 시간 계산
        current_time = pygame.time.get_ticks()
        wait_time = current_time - waiting_start_time

        # 튜토리얼 스테이지(50) 또는 공 생성 애니메이션 중에는 서브 화면 표시 생략
        if current_stage != 50 and not ball_spawn_animation_active:  # 튜토리얼이 아니고 공 생성 애니메이션 중이 아닐 때만 서브 화면 표시
            if is_player_serve:
                #  플레이어 서브 - 하단 미니멀 UI
                serve_font = FontStyle.body()  # 24pt 픽셀 폰트
                info_font = FontStyle.tiny()  # 16pt 픽셀 폰트
                # 간단한 텍스트만 표시 (투기장 모드일 때는 하단 영웅 이름 사용)
                if arena_mode_enabled and arena_bottom_hero:
                    bottom_hero_name = arena_bottom_hero.get("name", "Player")
                    serve_text = serve_font.render(f"{bottom_hero_name} Serve", True, WHITE)
                else:
                    serve_text = serve_font.render("Player Serve", True, WHITE)
                serve_rect = serve_text.get_rect(center=(WIDTH // 2, HEIGHT - 100))
                SCREEN.blit(serve_text, serve_rect)
                # 액센트 라인 (캐싱된 서피스 사용)
                line_width = serve_rect.width + 20
                line_y = serve_rect.bottom + 5
                line_surface = _get_serve_line_surface(line_width, (0, 200, 100))
                SCREEN.blit(line_surface, ((WIDTH - line_width) // 2, line_y))
                # 3초 후 자동 서브 카운트다운
                if wait_time >= MILLISECONDS_PER_SECOND:
                    remaining = max(0, 3000 - wait_time) // MILLISECONDS_PER_SECOND
                    if remaining > 0:
                        countdown_text = info_font.render(f"SPACE ({remaining}s)", True, (200, 200, 200))
                    else:
                        countdown_text = info_font.render("Auto serve", True, (255, 255, 100))
                else:
                    countdown_text = info_font.render("Manual serve", True, (200, 200, 200))
                countdown_rect = countdown_text.get_rect(center=(WIDTH // 2, serve_rect.bottom + 20))
                SCREEN.blit(countdown_text, countdown_rect)
            else:
                #  보스 서브 - 상단 미니멀 UI
                serve_font = FontStyle.body()  # 24pt 픽셀 폰트
                info_font = FontStyle.tiny()  # 16pt 픽셀 폰트
                # 간단한 텍스트만 표시 (투기장 모드일 때는 상단 영웅 이름 사용)
                if arena_mode_enabled and arena_top_hero:
                    top_hero_name = arena_top_hero.get("name", "Boss")
                    serve_text = serve_font.render(f"{top_hero_name} Serve", True, WHITE)
                else:
                    boss_name = get_boss_name(current_stage, "Boss")
                    serve_text = serve_font.render(f"{boss_name} Serve", True, WHITE)
                serve_rect = serve_text.get_rect(center=(WIDTH // 2, 80))
                SCREEN.blit(serve_text, serve_rect)
                # 액센트 라인 (캐싱된 서피스 사용)
                line_width = serve_rect.width + 20
                line_y = serve_rect.bottom + 5
                line_surface = _get_serve_line_surface(line_width, (200, 80, 80))
                SCREEN.blit(line_surface, ((WIDTH - line_width) // 2, line_y))
                # 상태 텍스트
                if boss_fake_move and wait_delay > 0:
                    remaining = max(0, wait_delay - wait_time) // 100
                    if remaining > 0:
                        status_text = info_font.render("Preparing...", True, (200, 200, 200))
                    else:
                        status_text = info_font.render("Ready", True, (255, 255, 100))
                else:
                    status_text = info_font.render("Waiting...", True, (200, 200, 200))
                status_rect = status_text.get_rect(center=(WIDTH // 2, serve_rect.bottom + 20))
                SCREEN.blit(status_text, status_rect)
    #  퍼펙트 타이밍 윈도우 시각적 표시 (드라이브 가능 시 항상 유지)
    elif (
        perfect_timing_indicator_active
        and special_gauge >= 150
        and selected_character_type == "smasher"
    ):
        # 공 주변에 퍼펙트 타이밍 인디케이터 그리기 (캐싱된 서피스 사용)
        timing_alpha = 255
        timing_radius = 30 + int(5 * math.sin(pygame.time.get_ticks() * 0.2))
        # 반투명 원 그리기 - 파워스매싱 준비 상태에 따라 색상 변경
        timing_surface = _get_timing_surface(timing_radius)
        timing_surface.fill((0, 0, 0, 0))  # 클리어
        if special_ready:
            # 파워스매싱 준비 상태일 때 - 빨간색 원
            pygame.draw.circle(timing_surface, (255, 80, 80, timing_alpha), (timing_radius, timing_radius), timing_radius, 3)
        else:
            # 일반 드라이브 상태일 때 - 노란색 원
            pygame.draw.circle(timing_surface, (255, 255, 0, timing_alpha), (timing_radius, timing_radius), timing_radius, 3)
        SCREEN.blit(timing_surface, (BALL.centerx - timing_radius, BALL.centery - timing_radius), (0, 0, timing_radius*2, timing_radius*2))
        # 텍스트 표시 - 파워스매싱 준비 상태에 따라 다르게 표시
        timing_font = FontStyle.body()  # 24pt 픽셀 폰트
        if special_ready:
            # 파워스매싱 준비 상태일 때 - 빨간색 SMASHING
            timing_text = timing_font.render("SMASHING", True, (255, 80, 80))
        else:
            # 일반 드라이브 상태일 때 - 노란색 Drive!
            timing_text = timing_font.render("Drive!", True, YELLOW)
        text_rect = timing_text.get_rect(center=(BALL.centerx, BALL.centery - 50))
        SCREEN.blit(timing_text, text_rect)
    # 화면 흔들림 효과 계산
    quake_offset_y = random.randint(-5, 5) if quake_active else 0
    # 바주카포 폭발 화면 흔들림
    bazooka_offset_x = 0
    bazooka_offset_y = 0
    if bazooka_screen_shake_timer > 0:
        # 흔들림 강도 계산 (바주카포는 더 강력)
        intensity = bazooka_screen_shake_timer / 25.0
        bazooka_offset_x = random.randint(-int(10 * intensity), int(10 * intensity))
        bazooka_offset_y = random.randint(-int(8 * intensity), int(8 * intensity))
        bazooka_screen_shake_timer -= 1
    
    #  수류탄 폭발 화면 흔들림
    grenade_offset_x = 0
    grenade_offset_y = 0
    if grenade_shake_timer > 0:
        # 흔들림 강도 계산 (시간이 지날수록 약해짐)
        intensity = grenade_shake_timer / 15.0
        grenade_offset_x = random.randint(-int(8 * intensity), int(8 * intensity))
        grenade_offset_y = random.randint(-int(6 * intensity), int(6 * intensity))
        grenade_shake_timer -= 1
    # 최종 화면 흔들림 오프셋
    total_offset_x = bazooka_offset_x + grenade_offset_x
    total_offset_y = quake_offset_y + bazooka_offset_y + grenade_offset_y
    # 헤르메스의 신발 별가루 파티클 업데이트 및 렌더링
    def update_and_draw_hermes_particles():
        """헤르메스의 신발 별가루 파티클 업데이트 및 렌더링"""
        global hermes_star_particles
        import random
        import math
        
        # 파티클 업데이트
        particles_to_remove = []
        for particle in hermes_star_particles:
            # 위치 업데이트
            particle['x'] += particle['vx']
            particle['y'] += particle['vy']
            # 수명 감소
            particle['life'] -= 1
            if particle['life'] <= 0:
                particles_to_remove.append(particle)
        
        # 죽은 파티클 제거
        for particle in particles_to_remove:
            hermes_star_particles.remove(particle)
        
        # 파티클 렌더링 (패들 뒤에 그려짐)
        for particle in hermes_star_particles:
            # 페이드 효과를 위한 알파값 계산
            alpha = int(255 * (particle['life'] / particle['max_life']))
            
            # 반짝이는 효과를 위한 색상 변화
            time_offset = pygame.time.get_ticks() / 100 + particle['color_offset']
            r = min(255, 200 + int(55 * abs(math.sin(time_offset))))
            g = min(255, 200 + int(55 * abs(math.cos(time_offset))))
            b = 255  # 파란색 계열 유지
            
            # 별 모양 그리기 (작은 십자가 + 대각선)
            center_x = int(particle['x'])
            center_y = int(particle['y'])
            size = particle['size']
            
            # 반짝이는 효과를 위해 크기도 약간 변화
            twinkle_size = size + int(math.sin(time_offset * 2) * 1)
            
            # 별 그리기 (페이드 효과 적용)
            if alpha > 20:  # 너무 투명하면 그리지 않음
                # 중심 점
                pygame.draw.circle(SCREEN, (r, g, b), (center_x, center_y), max(1, twinkle_size//2))
                # 십자 모양
                pygame.draw.line(SCREEN, (r, g, b), 
                               (center_x - twinkle_size, center_y), 
                               (center_x + twinkle_size, center_y), 1)
                pygame.draw.line(SCREEN, (r, g, b), 
                               (center_x, center_y - twinkle_size), 
                               (center_x, center_y + twinkle_size), 1)
                # 대각선 (더 작게)
                small_size = max(1, twinkle_size // 2)
                pygame.draw.line(SCREEN, (r, g, b), 
                               (center_x - small_size, center_y - small_size), 
                               (center_x + small_size, center_y + small_size), 1)
                pygame.draw.line(SCREEN, (r, g, b), 
                               (center_x - small_size, center_y + small_size), 
                               (center_x + small_size, center_y - small_size), 1)
    
    # 화면 흔들림을 적용하여 오브젝트 그리기
    def draw_with_shake(surface, pos):
        """  화면 흔들림을 적용하여 그리기"""
        SCREEN.blit(surface, (pos[0] + total_offset_x, pos[1] + total_offset_y))
    def draw_rect_with_shake(color, rect, width=0):
        """ 화면 흔들림을 적용하여 사각형 그리기"""
        shaken_rect = pygame.Rect(rect.x + total_offset_x, rect.y + total_offset_y, rect.width, rect.height)
        draw.rect(color, shaken_rect, width)
    def draw_circle_with_shake(color, pos, radius, width=0):
        """  화면 흔들림을 적용하여 원 그리기"""
        draw.circle(color, (int(pos[0] + total_offset_x), int(pos[1] + total_offset_y)), radius, width)

    # === 패들 홀로그램 물질화 효과 상태 체크 ===
    _boss_hologram_should_draw, _boss_hologram_progress, _boss_hologram_active = get_paddle_hologram_state()
    _player_hologram_should_draw, _player_hologram_progress, _player_hologram_active = _boss_hologram_should_draw, _boss_hologram_progress, _boss_hologram_active
    _hologram_time_now = pygame.time.get_ticks()  # 홀로그램 효과용 시간

    # === 홀로그램 등장 사운드 재생 ===
    global hologram_spawn_sound_played
    if _boss_hologram_should_draw and _boss_hologram_active and not hologram_spawn_sound_played:
        hologram_spawn_sound_played = True
        if SOUND_CHARACTER_SPAWN:
            play_sound_with_volume(SOUND_CHARACTER_SPAWN)

    # === 광폭화 애니메이션 홀로그램 등장 시점 트리거 ===
    global enraged_boss_pending_start, enraged_boss_growing
    if enraged_boss_pending_start:
        # 공 생성 애니메이션이 없거나 홀로그램이 등장하기 시작할 때 광폭화 애니메이션 시작
        if not ball_spawn_animation_active or (_boss_hologram_should_draw and _boss_hologram_active):
            enraged_boss_pending_start = False
            enraged_boss_growing = True
            show_speech("광폭화!", duration=120)
            # print(f"🔥 [광폭화 보스] 홀로그램 등장! 광폭화 애니메이션 시작!")

    # === 보스 이미지 선택 + 스테이지별 전용 사이즈 적용 ===
    boss_img_prescaled = False
    if new_boss_mode_active:
        #  새로운 보스 모드에서는 상단 보스 선택
        if selected_top_boss == 1:
            # 라이트닝 마스터 (임시로 stage3 이미지 사용 - 전기 속성)
            boss_img = BOSS_IMG_STAGE3
            boss_w, boss_h = BOSS_IMG_WIDTH, BOSS_IMG_HEIGHT
        elif selected_top_boss == 2:
            # 아이스 퀸 (임시로 stage4 이미지 사용 - 얼음 속성)
            boss_img = BOSS_IMG_STAGE4
