    def update_quantity_bounds(item_name: str) -> int:
        other_total = sum(count for name, count in selected_active_counts.items() if name != item_name)
        return max(0, ITEM_MANAGER_ACTIVE_LIMIT - other_total)

    def get_active_count(item_name: str) -> int:
        return selected_active_counts.get(item_name, 0)

    def set_active_count(item_name: str, new_count: int) -> None:
        if new_count > 0:
            selected_active_counts[item_name] = new_count
            if item_name not in selected_active_order:
                selected_active_order.append(item_name)
        else:
            selected_active_counts.pop(item_name, None)
            if item_name in selected_active_order:
                selected_active_order.remove(item_name)

    def adjust_active_count(item_name: str, delta: int) -> None:
        current = get_active_count(item_name)
        max_allowed = update_quantity_bounds(item_name)
        new_count = max(0, min(max_allowed, current + delta))
        set_active_count(item_name, new_count)

    def flatten_active_selection() -> list[str]:
        result: list[str] = []
        for name in selected_active_order:
            count = selected_active_counts.get(name, 0)
            if count > 0:
                result.extend([name] * count)
        return result

    def get_passive_count(item_name: str) -> int:
        return selected_passive_items.count(item_name)

    def set_passive_count(item_name: str, new_count: int) -> None:
        nonlocal selected_passive_items
        selected_passive_items = [n for n in selected_passive_items if n != item_name]
        if new_count > 0:
            selected_passive_items.extend([item_name] * new_count)

    def adjust_passive_count(item_name: str, delta: int) -> None:
        current = get_passive_count(item_name)
        new_count = max(0, min(MAX_PASSIVE_STACK, current + delta))
        set_passive_count(item_name, new_count)

    def flatten_passive_selection() -> list[str]:
        return list(selected_passive_items)

    # 롤 편집 모드 상태
    roll_edit_mode = False
    roll_edit_item: str | None = None
    roll_edit_options: list[dict] = []
    roll_edit_index = 0

    def enter_roll_edit(item_name: str) -> None:
        nonlocal roll_edit_mode, roll_edit_item, roll_edit_options, roll_edit_index
        ranges = PASSIVE_OPTION_RANGES.get(item_name)
        if not ranges:
            return
        existing = {opt["key"]: opt.get("value") for opt in custom_passive_rolls.get(item_name, [])}
        opts = []
        for r in ranges:
            vmin, vmax = r.get("min", 0), r.get("max", 0)
            default_val = existing.get(r["key"])
            if default_val is None:
                default_val = int((vmin + vmax) / 2)
            opts.append({
                "label": r.get("label", r["key"]),
                "key": r["key"],
                "min": vmin,
                "max": vmax,
                "unit": r.get("unit", ""),
                "value": int(default_val)
            })
        roll_edit_mode = True
        roll_edit_item = item_name
        roll_edit_options = opts
        roll_edit_index = 0

    def apply_roll_edit() -> None:
        nonlocal roll_edit_mode, roll_edit_item, roll_edit_options
        if roll_edit_item is None:
            roll_edit_mode = False
            return
        custom_passive_rolls[roll_edit_item] = [
            {"key": opt["key"], "value": int(opt["value"])} for opt in roll_edit_options
        ]
        roll_edit_mode = False
        roll_edit_item = None
        roll_edit_options = []

    def cancel_roll_edit() -> None:
        nonlocal roll_edit_mode, roll_edit_item, roll_edit_options
        roll_edit_mode = False
        roll_edit_item = None
        roll_edit_options = []

    # 전설 아이템 롤 편집 모드 상태
    legendary_roll_edit_mode = False
    legendary_roll_edit_item: str | None = None
    legendary_roll_edit_options: list[dict] = []
    legendary_roll_edit_index = 0

    def enter_legendary_roll_edit(item_name: str) -> None:
        nonlocal legendary_roll_edit_mode, legendary_roll_edit_item, legendary_roll_edit_options, legendary_roll_edit_index
        ranges = LEGENDARY_ROLL_OPTIONS.get(item_name)
        if not ranges:
            return
        opts = []
        for r in ranges:
            vmin, vmax = r.get("min", 0), r.get("max", 0)
            step = r.get("step", 1)
            current_val = get_legendary_roll_value(item_name, r["key"])
            opts.append({
                "label": r.get("label", r["key"]),
                "key": r["key"],
                "min": vmin,
                "max": vmax,
                "step": step,
                "unit": r.get("unit", ""),
                "value": current_val
            })
        legendary_roll_edit_mode = True
        legendary_roll_edit_item = item_name
        legendary_roll_edit_options = opts
        legendary_roll_edit_index = 0

    def apply_legendary_roll_edit() -> None:
        nonlocal legendary_roll_edit_mode, legendary_roll_edit_item, legendary_roll_edit_options
        if legendary_roll_edit_item is None:
            legendary_roll_edit_mode = False
            return
        for opt in legendary_roll_edit_options:
            set_legendary_roll_value(legendary_roll_edit_item, opt["key"], opt["value"])
        legendary_roll_edit_mode = False
        legendary_roll_edit_item = None
        legendary_roll_edit_options = []

    def cancel_legendary_roll_edit() -> None:
        nonlocal legendary_roll_edit_mode, legendary_roll_edit_item, legendary_roll_edit_options
        legendary_roll_edit_mode = False
        legendary_roll_edit_item = None
        legendary_roll_edit_options = []

    # 강화 수치 편집 모드 상태
    enhancement_edit_mode = False
    enhancement_edit_item: str | None = None
    enhancement_edit_level = 0  # 강화 레벨 (0~10)

    # 대장간 강화 시스템 연동 (downtown/constants.py 참조)
    from downtown.constants import ENHANCEMENT_BONUSES, MAX_ENHANCEMENT_LEVEL

    def enter_enhancement_edit(item_name: str) -> None:
        """강화 수치 편집 모드 진입"""
        nonlocal enhancement_edit_mode, enhancement_edit_item, enhancement_edit_level
        # 현재 아이템의 강화 수치 가져오기
        existing_enhancement = custom_passive_enhancements.get(item_name, {})
        enhancement_edit_mode = True
        enhancement_edit_item = item_name
        enhancement_edit_level = existing_enhancement.get("level", 0)

    def apply_enhancement_edit() -> None:
        """강화 수치 편집 저장"""
        nonlocal enhancement_edit_mode, enhancement_edit_item, enhancement_edit_level
        if enhancement_edit_item is None:
            enhancement_edit_mode = False
            return
        # 대장간 강화 시스템의 보너스 테이블에서 보너스 값 가져오기
        bonus = ENHANCEMENT_BONUSES.get(enhancement_edit_level, 0)
        custom_passive_enhancements[enhancement_edit_item] = {
            "level": enhancement_edit_level,
            "bonus": bonus
        }
        enhancement_edit_mode = False
        enhancement_edit_item = None
        enhancement_edit_level = 0

    def cancel_enhancement_edit() -> None:
        """강화 수치 편집 취소"""
        nonlocal enhancement_edit_mode, enhancement_edit_item, enhancement_edit_level
        enhancement_edit_mode = False
        enhancement_edit_item = None
        enhancement_edit_level = 0

    # 우클릭 컨텍스트 메뉴 상태
    context_menu_mode = False
    context_menu_item: str | None = None
    context_menu_options = [_t("ui.context_roll_edit", "롤옵션 편집"), _t("ui.context_enhance_edit", "강화 수치 편집")]
    context_menu_index = 0
    context_menu_pos = (0, 0)

    def open_context_menu(item_name: str, pos: tuple) -> None:
        """우클릭 컨텍스트 메뉴 열기"""
        nonlocal context_menu_mode, context_menu_item, context_menu_index, context_menu_pos
        context_menu_mode = True
        context_menu_item = item_name
        context_menu_index = 0
        context_menu_pos = pos

    def close_context_menu() -> None:
        """컨텍스트 메뉴 닫기"""
        nonlocal context_menu_mode, context_menu_item, context_menu_index
        context_menu_mode = False
        context_menu_item = None
        context_menu_index = 0

    def select_context_option() -> None:
        """컨텍스트 메뉴 옵션 선택"""
        nonlocal context_menu_mode, context_menu_item, context_menu_index
        if context_menu_item is None:
            close_context_menu()
            return
        if context_menu_index == 0:  # 롤옵션 편집
            enter_roll_edit(context_menu_item)
        elif context_menu_index == 1:  # 강화 수치 편집
            enter_enhancement_edit(context_menu_item)
        close_context_menu()

    # 커스텀 패시브 강화 수치 저장
    custom_passive_enhancements: dict[str, dict] = {}

    # 전설 아이템 강화 편집 모드 상태
    legendary_enhancement_edit_mode = False
    legendary_enhancement_edit_item: str | None = None
    legendary_enhancement_edit_level = 0

    # 전설 아이템 강화 수치 저장
    custom_legendary_enhancements: dict[str, dict] = {}

    def enter_legendary_enhancement_edit(item_name: str) -> None:
        """전설 아이템 강화 수치 편집 모드 진입"""
        nonlocal legendary_enhancement_edit_mode, legendary_enhancement_edit_item, legendary_enhancement_edit_level
        existing_enhancement = custom_legendary_enhancements.get(item_name, {})
        legendary_enhancement_edit_mode = True
        legendary_enhancement_edit_item = item_name
        legendary_enhancement_edit_level = existing_enhancement.get("level", 0)

    def apply_legendary_enhancement_edit() -> None:
        """전설 아이템 강화 수치 편집 저장"""
        nonlocal legendary_enhancement_edit_mode, legendary_enhancement_edit_item, legendary_enhancement_edit_level
        if legendary_enhancement_edit_item is None:
            legendary_enhancement_edit_mode = False
            return
        bonus = ENHANCEMENT_BONUSES.get(legendary_enhancement_edit_level, 0)
        custom_legendary_enhancements[legendary_enhancement_edit_item] = {
            "level": legendary_enhancement_edit_level,
            "bonus": bonus
        }
        legendary_enhancement_edit_mode = False
        legendary_enhancement_edit_item = None
        legendary_enhancement_edit_level = 0

    def cancel_legendary_enhancement_edit() -> None:
        """전설 아이템 강화 수치 편집 취소"""
        nonlocal legendary_enhancement_edit_mode, legendary_enhancement_edit_item, legendary_enhancement_edit_level
        legendary_enhancement_edit_mode = False
        legendary_enhancement_edit_item = None
        legendary_enhancement_edit_level = 0

    # 전설 아이템 우클릭 컨텍스트 메뉴 상태
    legendary_context_menu_mode = False
    legendary_context_menu_item: str | None = None
    legendary_context_menu_options = [_t("ui.context_roll_edit", "롤옵션 편집"), _t("ui.context_enhance_edit", "강화 수치 편집")]
    legendary_context_menu_index = 0
    legendary_context_menu_pos = (0, 0)

    def open_legendary_context_menu(item_name: str, pos: tuple) -> None:
        """전설 아이템 우클릭 컨텍스트 메뉴 열기"""
        nonlocal legendary_context_menu_mode, legendary_context_menu_item, legendary_context_menu_index, legendary_context_menu_pos
        legendary_context_menu_mode = True
        legendary_context_menu_item = item_name
        legendary_context_menu_index = 0
        legendary_context_menu_pos = pos

    def close_legendary_context_menu() -> None:
        """전설 아이템 컨텍스트 메뉴 닫기"""
        nonlocal legendary_context_menu_mode, legendary_context_menu_item, legendary_context_menu_index
        legendary_context_menu_mode = False
        legendary_context_menu_item = None
        legendary_context_menu_index = 0

    def select_legendary_context_option() -> None:
        """전설 아이템 컨텍스트 메뉴 옵션 선택"""
        nonlocal legendary_context_menu_mode, legendary_context_menu_item, legendary_context_menu_index
        if legendary_context_menu_item is None:
            close_legendary_context_menu()
            return
        if legendary_context_menu_index == 0:  # 롤옵션 편집
            if legendary_context_menu_item in LEGENDARY_ROLL_OPTIONS:
                enter_legendary_roll_edit(legendary_context_menu_item)
        elif legendary_context_menu_index == 1:  # 강화 수치 편집
            enter_legendary_enhancement_edit(legendary_context_menu_item)
        close_legendary_context_menu()

    def enter_quantity_mode(item_name: str) -> None:
        nonlocal quantity_selection_mode, quantity_target_item
        nonlocal quantity_current_value, quantity_original_value, quantity_max_value

        quantity_selection_mode = True
        quantity_target_item = item_name
        quantity_original_value = selected_active_counts.get(item_name, 0)
        quantity_max_value = update_quantity_bounds(item_name)
        quantity_current_value = min(quantity_original_value, quantity_max_value)

    def apply_quantity_selection() -> None:
        nonlocal quantity_selection_mode, quantity_target_item
        nonlocal quantity_current_value, quantity_original_value, quantity_max_value

        if quantity_target_item is None:
            return

        if quantity_current_value > 0:
            selected_active_counts[quantity_target_item] = quantity_current_value
            if quantity_target_item not in selected_active_order:
                selected_active_order.append(quantity_target_item)
        else:
            selected_active_counts.pop(quantity_target_item, None)
            if quantity_target_item in selected_active_order:
                selected_active_order.remove(quantity_target_item)

        play_notification_sound()
        quantity_selection_mode = False
        quantity_target_item = None
        quantity_original_value = 0
        quantity_max_value = 0

    def cancel_quantity_selection() -> None:
        nonlocal quantity_selection_mode, quantity_target_item, quantity_current_value, quantity_original_value, quantity_max_value

        quantity_selection_mode = False
        quantity_target_item = None
        quantity_current_value = 0
        quantity_original_value = 0
        quantity_max_value = 0

    # 아이템 관리자 → 스킬트리(테스트) 버튼 사각형 및 핸들러
    # 우측 하단 기준: 기존보다 100px 위, 크기 30% 축소
    skill_tree_button_rect = pygame.Rect(WIDTH - 180, HEIGHT - 196, 140, 45)

    # 패시브 탭 아이템 위치 캐시 (부위별 레이아웃용)
    passive_item_rects = []

    def open_skill_tree_test_mode() -> None:
        """런타임 스킬 현황 화면 표시 (기존 아카데미 스킬트리 대체)."""
        show_runtime_skill_status()
    
    while True:
        arrow_up_rect_screen = None
        arrow_down_rect_screen = None
        # 델타 타임 계산
        dt_seconds = clock.tick(60) / 1000.0  # 60 FPS 기준 델타(초)
        mouse_pos = pygame.mouse.get_pos()
        mouse_buttons = pygame.mouse.get_pressed()
        is_drag_select = mouse_buttons[0] and not quantity_selection_mode
        if not mouse_buttons[0]:
            drag_toggled_items.clear()

        # 전설 아이템 애니메이션 업데이트
        for item in legendary_items:
            if "item_obj" in item:
                item["item_obj"].update(dt_seconds)
        
        # 배경 그리기
        SCREEN.fill((10, 10, 40))
        # 제목
        title_text = font_large.render(_t("ui.dev_mode", "개발자모드"), True, WHITE)
        title_rect = title_text.get_rect(center=(WIDTH // 2, 80))
        SCREEN.blit(title_text, title_rect)
        # 탭 버튼 (4개: 엑티브, 패시브, 화기류, 전설)
        tab_width = 120
        tab_height = 40
        tab_y = 120
        tab_spacing = 10
        tab_names = [_t("ui.active_tab", "엑티브"), _t("ui.passive_tab", "패시브"), _t("ui.firearm", "화기류"), _t("equip.mythic", "신화")]
        tab_colors = [
            (100, 150, 255),  # 엑티브 - 파란색
            (100, 255, 150),  # 패시브 - 초록색
            (255, 200, 120),  # 화기류 - 주황색
            (255, 100, 100),  # 전설 - 빨간색
        ]
        base_colors = [
            (60, 60, 80),
            (60, 60, 80),
            (70, 40, 20),
            (80, 40, 40),
        ]
        total_tab_width = tab_width * len(tab_names) + tab_spacing * (len(tab_names) - 1)
        start_x = (WIDTH - total_tab_width) // 2

        tab_rects = []
        for idx, name in enumerate(tab_names):
            tab_x = start_x + idx * (tab_width + tab_spacing)
            rect = pygame.Rect(tab_x, tab_y, tab_width, tab_height)
            tab_rects.append(rect)
            is_active = selected_category == idx
            fill_color = tab_colors[idx] if is_active else base_colors[idx]
            border_color = WHITE if idx < 3 else (255, 100, 100)

            draw.rect(fill_color, rect)
            draw.rect(border_color, rect, 2)

            tab_text = font_medium.render(name, True, WHITE)
            SCREEN.blit(tab_text, tab_text.get_rect(center=rect.center))
        
        # 현재 선택된 카테고리의 아이템들 표시
        if selected_category == 0:
            current_items = active_items
        elif selected_category == 1:
            current_items = passive_items_sorted  # 부위별 정렬된 패시브 사용
        elif selected_category == 2:
            current_items = firearm_items
        else:  # selected_category == 3
            current_items = legendary_items_sorted  # 부위별 정렬된 전설 사용

        # 패시브 탭: 부위별 레이아웃으로 렌더링
        if selected_category == 1:
            # 패시브 탭 전용 렌더링 (부위별 정리)
            font_slot = get_font(14)
            passive_start_y = 175
            current_y = passive_start_y
            current_slot = None
            item_index = 0
            col_in_slot = 0
            max_cols_per_slot = 12  # 부위당 최대 열 수
            slot_label_width = 50  # 부위 라벨 너비
            passive_grid_start_x = 65

            # 부위별 색상
            slot_colors = {
                "머리": (180, 100, 100),
                "상의": (100, 180, 100),
                "팔": (180, 140, 80),
                "벨트": (100, 100, 180),
                "무릎": (180, 100, 180),
                "신발": (100, 180, 180),
                "등": (150, 130, 100),
                "장신구": (140, 140, 160),
                "기타": (120, 120, 120),
            }

            # 패시브 아이템 위치 캐시 (클릭/키보드 처리용)
            passive_item_rects = []

            for i, item in enumerate(current_items):
                item_slot = item.get("slot", "기타")

                # 새로운 부위 시작
                if item_slot != current_slot:
                    current_slot = item_slot
                    col_in_slot = 0
                    if i > 0:
                        current_y += passive_item_size + passive_slot_gap  # 부위 간 간격

                    # 부위 라벨 표시
                    slot_color = slot_colors.get(current_slot, (120, 120, 120))
                    _slot_key = _BASE_SLOT_REVERSE.get(current_slot, current_slot)
                    _slot_display = _t(f"equip.base.{_slot_key}", current_slot)
                    slot_label = font_slot.render(_slot_display, True, slot_color)
                    SCREEN.blit(slot_label, (15, current_y + (passive_item_size - slot_label.get_height()) // 2))

                # 아이템 위치 계산
                x = passive_grid_start_x + col_in_slot * (passive_item_size + passive_item_spacing)
                y = current_y

                # 줄바꿈 처리
                if col_in_slot >= max_cols_per_slot:
                    col_in_slot = 0
                    current_y += passive_item_size + passive_item_spacing
                    x = passive_grid_start_x
                    y = current_y

                item_rect = pygame.Rect(x, y, passive_item_size, passive_item_size)
                passive_item_rects.append((i, item_rect, item))

                # 드래그 선택
                if is_drag_select and item_rect.collidepoint(mouse_pos):
                    item_name = item["name"]
                    drag_key = f"1:{item_name}"
                    if drag_key not in drag_toggled_items:
                        if item_name in selected_passive_items:
                            selected_passive_items.remove(item_name)
                        else:
                            selected_passive_items.append(item_name)
                        drag_toggled_items.add(drag_key)

                # 선택/커서 상태
                is_selected = get_passive_count(item["name"]) > 0
                is_cursor = (i == selected_item_index)

                # 배경색
                slot_bg = slot_colors.get(current_slot, (60, 60, 80))
                if is_selected:
                    draw.rect(YELLOW, item_rect)
                elif is_cursor:
                    draw.rect((100, 150, 255), item_rect)
                else:
                    # 부위별 배경색 (어둡게)
                    dark_bg = tuple(max(20, c // 3) for c in slot_bg)
                    draw.rect(dark_bg, item_rect)

                # 테두리
                if is_cursor:
                    draw.rect(WHITE, item_rect, 3)
                else:
                    draw.rect(slot_bg, item_rect, 2)

                # 아이콘
                if item["icon"]:
                    icon_surface = pygame.transform.scale(item["icon"], (passive_item_size - 8, passive_item_size - 8))
                    icon_rect = icon_surface.get_rect(center=item_rect.center)
                    SCREEN.blit(icon_surface, icon_rect)

                # 수량 배지
                count = get_passive_count(item["name"])
                if count > 0:
                    badge_text = font_small.render(str(count), True, WHITE)
                    badge_width = badge_text.get_width() + 6
                    badge_height = badge_text.get_height() + 3
                    badge_surface = pygame.Surface((badge_width, badge_height), pygame.SRCALPHA)
                    pygame.draw.rect(badge_surface, (40, 40, 40, 220), badge_surface.get_rect(), border_radius=4)
                    pygame.draw.rect(badge_surface, (255, 220, 120), badge_surface.get_rect(), 1, border_radius=4)
                    badge_rect = badge_surface.get_rect()
                    badge_rect.right = item_rect.right - 2
                    badge_rect.bottom = item_rect.bottom - 2
                    badge_surface.blit(badge_text, ((badge_width - badge_text.get_width()) // 2, (badge_height - badge_text.get_height()) // 2))
                    SCREEN.blit(badge_surface, badge_rect.topleft)

                # 강화 수치 배지 (좌측 상단에 표시)
                item_name = item["name"]
                if item_name in custom_passive_enhancements:
                    enhancement_info = custom_passive_enhancements[item_name]
                    enh_level = enhancement_info.get("level", 0)
                    if enh_level > 0:
                        enh_text = font_small.render(f"+{enh_level}", True, (255, 200, 100))
                        enh_width = enh_text.get_width() + 4
                        enh_height = enh_text.get_height() + 2
                        enh_surface = pygame.Surface((enh_width, enh_height), pygame.SRCALPHA)
                        pygame.draw.rect(enh_surface, (80, 40, 20, 220), enh_surface.get_rect(), border_radius=3)
                        pygame.draw.rect(enh_surface, (255, 180, 80), enh_surface.get_rect(), 1, border_radius=3)
                        enh_rect = enh_surface.get_rect()
                        enh_rect.left = item_rect.left + 2
                        enh_rect.top = item_rect.top + 2
                        enh_surface.blit(enh_text, ((enh_width - enh_text.get_width()) // 2, (enh_height - enh_text.get_height()) // 2))
                        SCREEN.blit(enh_surface, enh_rect.topleft)

                col_in_slot += 1

        elif selected_category == 3:
            # 전설 탭 전용 렌더링 (부위별 정리)
            font_slot = get_font(14)
            legendary_start_y = 175
            current_y = legendary_start_y
            current_slot = None
            item_index = 0
            col_in_slot = 0
            max_cols_per_slot = 6
            slot_label_width = 50
            legendary_grid_start_x = 65

            # 부위별 색상 (전설 아이템용 - 황금빛 계열)
            slot_colors = {
                "팔": (255, 200, 100),
                "신발": (200, 180, 255),
                "장신구": (255, 180, 200),
                "기타": (180, 180, 180),
            }

            # 전설 아이템 위치 캐시 초기화
            legendary_item_rects = []

            for i, item in enumerate(current_items):
                item_slot = item.get("slot", "기타")

                # 새로운 부위 시작
                if item_slot != current_slot:
                    current_slot = item_slot
                    col_in_slot = 0
                    if i > 0:
                        current_y += legendary_item_size + legendary_slot_gap

                    # 부위 라벨 표시
                    slot_color = slot_colors.get(current_slot, (180, 180, 180))
                    _slot_key = _BASE_SLOT_REVERSE.get(current_slot, current_slot)
                    _slot_display = _t(f"equip.base.{_slot_key}", current_slot)
                    slot_label = font_slot.render(_slot_display, True, slot_color)
                    SCREEN.blit(slot_label, (15, current_y + (legendary_item_size - slot_label.get_height()) // 2))

                # 아이템 위치 계산
                x = legendary_grid_start_x + col_in_slot * (legendary_item_size + legendary_item_spacing)
                y = current_y

                # 줄바꿈 처리
                if col_in_slot >= max_cols_per_slot:
                    col_in_slot = 0
                    current_y += legendary_item_size + legendary_item_spacing
                    x = legendary_grid_start_x
                    y = current_y

                item_rect = pygame.Rect(x, y, legendary_item_size, legendary_item_size)
                legendary_item_rects.append((i, item_rect, item))

                # 드래그 선택
                if is_drag_select and item_rect.collidepoint(mouse_pos):
                    item_name = item["name"]
                    drag_key = f"3:{item_name}"
                    if drag_key not in drag_toggled_items:
                        if item_name in selected_legendary_items:
                            selected_legendary_items.remove(item_name)
                        else:
                            selected_legendary_items.append(item_name)
                        drag_toggled_items.add(drag_key)

                # 선택/커서 상태
                is_selected = item["name"] in selected_legendary_items
                is_cursor = (i == selected_item_index)

                # 배경색 (전설 아이템은 황금 테두리)
                if is_selected:
                    draw.rect((255, 215, 0), item_rect)  # 황금색
                elif is_cursor:
                    draw.rect((180, 140, 80), item_rect)
                else:
                    draw.rect((80, 60, 40), item_rect)

                # 테두리 (전설 아이템 전용 스타일)
                if is_cursor:
                    draw.rect((255, 215, 0), item_rect, 3)  # 황금 테두리
                else:
                    draw.rect((200, 160, 80), item_rect, 2)

                # 아이콘 (전설 아이템은 애니메이션)
                if "item_obj" in item:
                    item["item_obj"].draw_icon(SCREEN, x + 2, y + 2, legendary_item_size - 4)
                elif item["icon"]:
                    icon_surface = pygame.transform.scale(item["icon"], (legendary_item_size - 4, legendary_item_size - 4))
                    icon_rect = icon_surface.get_rect(center=item_rect.center)
                    SCREEN.blit(icon_surface, icon_rect)

                # 강화 레벨 뱃지 표시 (전설 아이템)
                item_name = item["name"]
                if item_name in custom_legendary_enhancements:
                    enh_level = custom_legendary_enhancements[item_name].get("level", 0)
                    if enh_level > 0:
                        enh_text = get_font(10).render(f"+{enh_level}", True, (255, 255, 200))
                        enh_width = enh_text.get_width() + 6
                        enh_height = enh_text.get_height() + 2
                        enh_surface = pygame.Surface((enh_width, enh_height), pygame.SRCALPHA)
                        pygame.draw.rect(enh_surface, (180, 120, 40, 220), enh_surface.get_rect(), border_radius=3)
                        pygame.draw.rect(enh_surface, (255, 200, 100), enh_surface.get_rect(), 1, border_radius=3)
                        enh_rect = enh_surface.get_rect()
                        enh_rect.right = item_rect.right - 2
                        enh_rect.top = item_rect.top + 2
                        enh_surface.blit(enh_text, ((enh_width - enh_text.get_width()) // 2, (enh_height - enh_text.get_height()) // 2))
                        SCREEN.blit(enh_surface, enh_rect.topleft)

                col_in_slot += 1

            # 전설 아이템 hover 툴팁 (롤옵션 포함)
            legendary_hover_info = None
            for idx, rect, item in legendary_item_rects:
                if rect.collidepoint(mouse_pos):
                    item_name = item.get("name", "")
                    korean_name = item.get("korean_name") or get_item_name_korean(item_name)
                    desc = get_item_description(item_name)
                    slot_label = item.get("slot", "기타")

                    # 롤옵션 정보 가져오기 (개별 아이템의 rolled_options 우선 사용)
                    roll_opts = LEGENDARY_ROLL_OPTIONS.get(item_name, [])
                    opt_lines = []
                    for opt in roll_opts:
                        current_val = get_item_legendary_roll_value(item, opt["key"])
                        unit = opt.get("unit", "")
                        label = opt.get("label", opt["key"])
                        step = opt.get("step", 1)
                        if isinstance(step, float) and step < 1:
                            val_str = f"{current_val:.1f}"
                        else:
                            val_str = f"{int(current_val)}"
                        opt_lines.append({
                            "text": f"• {label}: {val_str}{unit}",
                            "color": (255, 220, 150)
                        })

                    legendary_hover_info = {
                        "rect": rect,
                        "name": korean_name,
                        "raw_name": item_name,
                        "desc": desc,
                        "slot_label": slot_label,
                        "color": (255, 200, 100),  # 황금색
                        "options": opt_lines,
                    }
                    pygame.draw.rect(SCREEN, (255, 215, 0), rect, 3)  # 황금 테두리
                    break

            # 전설 아이템 툴팁 렌더링
            if legendary_hover_info:
                tooltip_font_small = get_font(18)
                tooltip_font_tiny = get_font(14)
                line_height = tooltip_font_tiny.get_height() + 2

                # 설명 텍스트 줄바꿈 (인라인 처리)
                desc_text = legendary_hover_info.get("desc", "")
                desc_lines = []
                _max_w = 200
                for _paragraph in desc_text.split("\n"):
                    _words = _paragraph.split()
                    if not _words:
                        desc_lines.append("")
                        continue
                    _cur_line = ""
                    for _word in _words:
                        _test = f"{_cur_line} {_word}".strip() if _cur_line else _word
                        if tooltip_font_tiny.size(_test)[0] <= _max_w:
                            _cur_line = _test
                        else:
                            if _cur_line:
                                desc_lines.append(_cur_line)
                            if tooltip_font_tiny.size(_word)[0] <= _max_w:
                                _cur_line = _word
                            else:
                                _chunk = ""
                                for _ch in _word:
                                    if tooltip_font_tiny.size(_chunk + _ch)[0] <= _max_w:
                                        _chunk += _ch
                                    else:
                                        if _chunk:
                                            desc_lines.append(_chunk)
                                        _chunk = _ch
                                _cur_line = _chunk
                    if _cur_line:
                        desc_lines.append(_cur_line)

                # 옵션 라인
                opt_lines = legendary_hover_info.get("options", [])

                # 왼쪽 박스 (이름 + 설명)
                name_surface = tooltip_font_small.render(legendary_hover_info["name"], True, legendary_hover_info["color"])
                slot_surface = tooltip_font_tiny.render(f"[{legendary_hover_info['slot_label']}]", True, (200, 180, 140))

                desc_width = 220
                desc_height = 16 + name_surface.get_height() + slot_surface.get_height() + 8 + len(desc_lines) * line_height + 10

                # 오른쪽 박스 (롤옵션)
                if opt_lines:
                    roll_width = 180
                    roll_height = 16 + len(opt_lines) * line_height + 10
                else:
                    roll_width = 0
                    roll_height = 0

                gap = 10
                total_width = desc_width + (gap + roll_width if roll_width > 0 else 0)
                max_height = max(desc_height, roll_height) if roll_height > 0 else desc_height

                # 툴팁 위치 계산
                tooltip_x = max(8, min(WIDTH - total_width - 8, legendary_hover_info["rect"].right + 10))
                tooltip_y = legendary_hover_info["rect"].top
                if tooltip_y + max_height > HEIGHT - 8:
                    tooltip_y = max(8, HEIGHT - max_height - 8)

                # 왼쪽 박스 (설명) 렌더링
                desc_rect = pygame.Rect(tooltip_x, tooltip_y, desc_width, desc_height)
                pygame.draw.rect(SCREEN, (40, 30, 20, 240), desc_rect, border_radius=10)
                pygame.draw.rect(SCREEN, (255, 200, 100), desc_rect, 2, border_radius=10)

                # 이름
                SCREEN.blit(name_surface, (desc_rect.x + 10, desc_rect.y + 10))
                # 슬롯
                SCREEN.blit(slot_surface, (desc_rect.x + 10, desc_rect.y + 10 + name_surface.get_height() + 2))
                # 설명
                text_y = desc_rect.y + 10 + name_surface.get_height() + slot_surface.get_height() + 8
                for line in desc_lines:
                    line_surf = tooltip_font_tiny.render(line, True, (200, 200, 200))
                    SCREEN.blit(line_surf, (desc_rect.x + 10, text_y))
                    text_y += line_height

                # 오른쪽 박스 (롤옵션) 렌더링
                if opt_lines:
                    roll_rect = pygame.Rect(tooltip_x + desc_width + gap, tooltip_y, roll_width, roll_height)
                    pygame.draw.rect(SCREEN, (50, 30, 30, 240), roll_rect, border_radius=10)
                    pygame.draw.rect(SCREEN, (255, 120, 80), roll_rect, 2, border_radius=10)

                    roll_text_y = roll_rect.y + 10
                    for opt in opt_lines:
                        opt_surf = tooltip_font_tiny.render(opt["text"], True, opt["color"])
                        SCREEN.blit(opt_surf, (roll_rect.x + 10, roll_text_y))
                        roll_text_y += line_height

        else:
            # 기존 그리드 레이아웃 (액티브/화기류)
            for i, item in enumerate(current_items):
                row = i // grid_cols
                col = i % grid_cols
                x = grid_start_x + col * (item_size + item_spacing)
                y = grid_start_y + row * (item_size + item_spacing)
                item_rect = pygame.Rect(x, y, item_size, item_size)

                # 드래그 선택
                if is_drag_select and item_rect.collidepoint(mouse_pos):
                    item_name = item["name"]
                    drag_key = f"{selected_category}:{item_name}"
                    if drag_key not in drag_toggled_items:
                        if selected_category == 0:
                            adjust_active_count(item_name, 1)
                        elif selected_category == 2:
                            if item_name in selected_firearm_items:
                                selected_firearm_items.remove(item_name)
                            else:
                                selected_firearm_items.append(item_name)
                        else:
                            if item_name in selected_legendary_items:
                                selected_legendary_items.remove(item_name)
                            else:
                                selected_legendary_items.append(item_name)
                        drag_toggled_items.add(drag_key)

                # 선택 상태
                is_selected = False
                if selected_category == 0:
                    is_selected = selected_active_counts.get(item["name"], 0) > 0
                elif selected_category == 2:
                    is_selected = item["name"] in selected_firearm_items
                else:
                    is_selected = item["name"] in selected_legendary_items

                is_cursor = (i == selected_item_index)

                # 배경색
                if is_selected:
                    draw.rect(YELLOW, item_rect)
                elif is_cursor:
                    draw.rect((100, 150, 255), item_rect)
                else:
                    draw.rect((60, 60, 80), item_rect)

                # 테두리
                if is_cursor:
                    draw.rect(WHITE, item_rect, 3)
                else:
                    draw.rect(WHITE, item_rect, 2)

                # 아이콘
                if selected_category == 3 and "item_obj" in item:
                    item["item_obj"].draw_icon(SCREEN, x + 5, y + 5, item_size - 10)
                elif item["icon"]:
                    icon_surface = pygame.transform.scale(item["icon"], (item_size - 10, item_size - 10))
                    icon_rect = icon_surface.get_rect(center=item_rect.center)
                    SCREEN.blit(icon_surface, icon_rect)

                # 수량 배지 (액티브만)
                if selected_category == 0:
                    count = selected_active_counts.get(item["name"], 0)
                    if count > 0:
                        badge_text = font_small.render(str(count), True, WHITE)
                        padding_x = 6
                        padding_y = 3
                        badge_width = badge_text.get_width() + padding_x
                        badge_height = badge_text.get_height() + padding_y
                        badge_surface = pygame.Surface((badge_width, badge_height), pygame.SRCALPHA)
                        pygame.draw.rect(badge_surface, (40, 40, 40, 220), badge_surface.get_rect(), border_radius=6)
                        pygame.draw.rect(badge_surface, (255, 220, 120), badge_surface.get_rect(), 1, border_radius=6)
                        badge_rect = badge_surface.get_rect()
                        badge_rect.right = item_rect.right - 4
                        badge_rect.bottom = item_rect.bottom - 4
                        badge_surface.blit(badge_text, ((badge_width - badge_text.get_width()) // 2, (badge_height - badge_text.get_height()) // 2))
                        SCREEN.blit(badge_surface, badge_rect.topleft)
        # 선택된 아이템 정보 표시
        info_y = grid_start_y + (grid_rows * (item_size + item_spacing)) + LARGE_SIZE
        info_text = font_medium.render(_t("ui.selected_item", "선택된 아이템:"), True, WHITE)
        SCREEN.blit(info_text, (50, info_y))
        selected_items_text = ""
        if selected_category == 0:
            if selected_active_order:
                parts = []
                for name in selected_active_order:
                    count = selected_active_counts.get(name, 0)
                    if count <= 0:
                        continue
                    label = get_item_name_korean(name)
                    if count > 1:
                        label = f"{label} x{count}"
                    parts.append(label)
                selected_items_text = ", ".join(parts) if parts else _t("ui.none", "없음")
            else:
                selected_items_text = _t("ui.none", "없음")
        elif selected_category == 1:
            if selected_passive_items:
                parts = []
                seen = set()
                for name in selected_passive_items:
                    if name in seen:
                        continue
                    seen.add(name)
                    cnt = get_passive_count(name)
                    label = get_item_name_korean(name)
                    if cnt > 1:
                        label = f"{label} x{cnt}"
                    parts.append(label)
                selected_items_text = ", ".join(parts) if parts else _t("ui.none", "없음")
            else:
                selected_items_text = _t("ui.none", "없음")
        elif selected_category == 2:
            selected_items_text = ", ".join([get_item_name_korean(name) for name in selected_firearm_items]) if selected_firearm_items else _t("ui.none", "없음")
        else:  # 전설 카테고리
            selected_items_text = ", ".join([item["korean_name"] for item in legendary_items if item["name"] in selected_legendary_items]) if selected_legendary_items else _t("ui.none", "없음")
        # 시너지 효과가 포함된 경우 보라색으로 표시
        text_color = (200, 200, 200)  # 기본 색상
        if get_passive_count("gravitybelt") > 0:
            text_color = (128, 0, 128)  # 보라색
        selected_text = font_small.render(selected_items_text, True, text_color)
        SCREEN.blit(selected_text, (50, info_y + 30))

        # 현재 커서가 가리키는 아이템 이름 표시
        hovered_items = []
        if selected_category == 0:
            hovered_items = active_items
        elif selected_category == 1:
            hovered_items = passive_items_sorted
        elif selected_category == 2:
            hovered_items = firearm_items
        else:
            hovered_items = legendary_items_sorted

        if hovered_items and 0 <= selected_item_index < len(hovered_items):
            hovered_item = hovered_items[selected_item_index]
            hovered_name = ""
            hovered_color = WHITE

            if selected_category == 3:
                hovered_name = hovered_item.get("korean_name") or get_item_name_korean(hovered_item.get("name", ""))
            else:
                hovered_name = get_item_name_korean(hovered_item["name"])

            if hovered_item.get("name") == "gravitybelt":
                hovered_color = (128, 0, 128)

            if hovered_name:
                hovered_text = font_small.render(_t("ui.current_selection_fmt", "현재 선택: {}").format(hovered_name), True, hovered_color)
                SCREEN.blit(hovered_text, (50, info_y + 60))

        # 조작법 안내
        if selected_category == 0:
            controls_message = "방향키: 아이템 선택, 마우스 클릭/휠: 수량 설정, TAB: 탭 전환, ENTER/SPACE: 스테이지 선택"
        elif selected_category == 1:
            controls_message = "방향키: 선택, 휠: 수량 조절, 우클릭: 롤/강화 편집, TAB: 탭 전환, ENTER/SPACE: 적용"
        elif selected_category == 3:
            controls_message = "방향키: 선택, 마우스 클릭: 선택/해제, 우클릭: 롤 편집, TAB: 탭 전환, ENTER/SPACE: 적용"
        else:
            controls_message = "방향키: 아이템 선택, 마우스 클릭: 선택/해제, TAB: 탭 전환, ENTER/SPACE: 스테이지 선택"
        controls_text = font_small.render(controls_message, True, (150, 150, 150))
        SCREEN.blit(controls_text, (LARGE_SIZE, HEIGHT - LARGE_SIZE))

        # 스킬트리(테스트) 버튼 - 우측 하단
        mouse_pos = pygame.mouse.get_pos()
        button_hovered = skill_tree_button_rect.collidepoint(mouse_pos)
        button_fill = (55, 90, 150) if button_hovered else (40, 70, 120)
        button_border = (255, 220, 120) if button_hovered else (200, 200, 200)

        pygame.draw.rect(SCREEN, button_fill, skill_tree_button_rect, border_radius=12)
        pygame.draw.rect(SCREEN, button_border, skill_tree_button_rect, 3, border_radius=12)

        btn_title = font_small.render(_t("ui.perk_status", "퍽 현황"), True, WHITE)
        SCREEN.blit(btn_title, btn_title.get_rect(center=skill_tree_button_rect.center))

        if quantity_selection_mode and quantity_target_item:
            dim_surface = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
            dim_surface.fill((0, 0, 0, 160))
            SCREEN.blit(dim_surface, (0, 0))

            panel_width = 360
            panel_height = 360
            panel_rect = pygame.Rect(
                (WIDTH - panel_width) // 2,
                (HEIGHT - panel_height) // 2,
                panel_width,
                panel_height,
            )

            panel_surface = pygame.Surface((panel_width, panel_height), pygame.SRCALPHA)
            pygame.draw.rect(panel_surface, (28, 32, 60, 235), panel_surface.get_rect(), border_radius=18)
            pygame.draw.rect(panel_surface, (255, 220, 120), panel_surface.get_rect(), 3, border_radius=18)

            title_surface = font_medium.render(_t("ui.active_item_count", "엑티브 아이템 수량"), True, WHITE)
            title_rect = title_surface.get_rect(center=(panel_width // 2, 40))
            panel_surface.blit(title_surface, title_rect)

            item_label = get_item_name_korean(quantity_target_item)
            item_surface = font_small.render(item_label, True, (255, 240, 200))
            item_rect = item_surface.get_rect(center=(panel_width // 2, 82))
            panel_surface.blit(item_surface, item_rect)

            arrow_button_width = 76
            arrow_button_height = 54
            number_box_width = 140
            number_box_height = 84
            spacing = 14

            arrow_up_rect = pygame.Rect(
                panel_width // 2 - arrow_button_width // 2,
                item_rect.bottom + spacing,
                arrow_button_width,
                arrow_button_height,
            )

            number_rect = pygame.Rect(
                panel_width // 2 - number_box_width // 2,
                arrow_up_rect.bottom + spacing,
                number_box_width,
                number_box_height,
            )

            arrow_down_rect = pygame.Rect(
                panel_width // 2 - arrow_button_width // 2,
                number_rect.bottom + spacing,
                arrow_button_width,
                arrow_button_height,
            )

            # Up arrow button
            pygame.draw.rect(panel_surface, (60, 78, 130), arrow_up_rect, border_radius=12)
            pygame.draw.rect(panel_surface, (255, 220, 120), arrow_up_rect, 2, border_radius=12)
            up_triangle = [
                (arrow_up_rect.centerx, arrow_up_rect.top + 12),
                (arrow_up_rect.left + 12, arrow_up_rect.bottom - 12),
                (arrow_up_rect.right - 12, arrow_up_rect.bottom - 12),
            ]
            pygame.draw.polygon(panel_surface, WHITE, up_triangle)

            # Number box
            pygame.draw.rect(panel_surface, (20, 24, 40), number_rect, border_radius=14)
            pygame.draw.rect(panel_surface, (255, 220, 120), number_rect, 3, border_radius=14)
            count_surface = font_large.render(str(quantity_current_value), True, (255, 255, 140))
            panel_surface.blit(count_surface, count_surface.get_rect(center=number_rect.center))

            # Down arrow button
            pygame.draw.rect(panel_surface, (60, 78, 130), arrow_down_rect, border_radius=12)
            pygame.draw.rect(panel_surface, (255, 220, 120), arrow_down_rect, 2, border_radius=12)
            down_triangle = [
                (arrow_down_rect.left + 12, arrow_down_rect.top + 12),
                (arrow_down_rect.right - 12, arrow_down_rect.top + 12),
                (arrow_down_rect.centerx, arrow_down_rect.bottom - 12),
            ]
            pygame.draw.polygon(panel_surface, WHITE, down_triangle)

            other_total = sum(count for name, count in selected_active_counts.items() if name != quantity_target_item)
            current_total = other_total + quantity_current_value
            manager_slot_cap = ITEM_MANAGER_ACTIVE_LIMIT
            remaining_slots = max(0, manager_slot_cap - current_total)
            limit_surface = font_small.render(
                f"이 아이템 최대 {quantity_max_value}개 | 현재 {current_total}/{manager_slot_cap} 슬롯 (남은 {remaining_slots})",
                True,
                (200, 200, 200),
            )
            limit_rect = limit_surface.get_rect(center=(panel_width // 2, panel_height - 86))
            panel_surface.blit(limit_surface, limit_rect)

            guide_surface = font_small.render(
                "↑↓ 키 또는 화살표 클릭 | Space 확인 | Esc 취소",
                True,
                (185, 185, 185),
            )
            guide_rect = guide_surface.get_rect(center=(panel_width // 2, panel_height - 40))
            panel_surface.blit(guide_surface, guide_rect)

            SCREEN.blit(panel_surface, panel_rect.topleft)
            arrow_up_rect_screen = arrow_up_rect.move(panel_rect.topleft)
            arrow_down_rect_screen = arrow_down_rect.move(panel_rect.topleft)

        if roll_edit_mode and roll_edit_item:
            dim_surface = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
            dim_surface.fill((0, 0, 0, 160))
            SCREEN.blit(dim_surface, (0, 0))

            panel_w, panel_h = 520, 420
            panel_rect = pygame.Rect((WIDTH - panel_w) // 2, (HEIGHT - panel_h) // 2, panel_w, panel_h)
            panel_surf = pygame.Surface((panel_w, panel_h), pygame.SRCALPHA)
            pygame.draw.rect(panel_surf, (24, 28, 48, 235), panel_surf.get_rect(), border_radius=18)
            pygame.draw.rect(panel_surf, (120, 190, 255), panel_surf.get_rect(), 3, border_radius=18)

            title = font_medium.render(f"{get_item_name_korean(roll_edit_item)} {_t('ui.roll_edit_title_suffix', '롤 편집')}", True, WHITE)
            panel_surf.blit(title, title.get_rect(center=(panel_w // 2, 36)))

            hint = font_small.render(_t("ui.roll_edit_hint", "우클릭으로 시작 | 휠/←→ 값 조절 | ↑↓ 옵션 이동 | Space 저장 | Esc 취소"), True, (200, 200, 200))
            panel_surf.blit(hint, hint.get_rect(center=(panel_w // 2, 70)))

            start_y = 110
            line_h = 52
            bar_w = 260
            bar_h = 12
            for idx, opt in enumerate(roll_edit_options):
                y = start_y + idx * line_h
                is_sel = idx == roll_edit_index
                label_color = (255, 230, 180) if is_sel else (200, 200, 200)
                label = font_small.render(_t(f"roll.{opt.get('key','')}", opt['label']), True, label_color)
                panel_surf.blit(label, (40, y))

                # 바/노브
                bar_rect = pygame.Rect(panel_w - bar_w - 60, y + 8, bar_w, bar_h)
                pygame.draw.rect(panel_surf, (40, 50, 80), bar_rect, border_radius=6)
                pygame.draw.rect(panel_surf, (80, 120, 200), bar_rect, 1, border_radius=6)
                span = max(1, opt["max"] - opt["min"])
                ratio = (opt["value"] - opt["min"]) / span
                fill_w = int(bar_rect.width * ratio)
                fill_rect = pygame.Rect(bar_rect.left, bar_rect.top, fill_w, bar_rect.height)
                pygame.draw.rect(panel_surf, (120, 200, 255) if is_sel else (90, 140, 200), fill_rect, border_radius=6)

