                if event.type == pygame.KEYDOWN:
                    if event.key in (pygame.K_ESCAPE, pygame.K_BACKSPACE):
                        cancel_legendary_enhancement_edit()
                    elif event.key in (pygame.K_RETURN, pygame.K_SPACE):
                        apply_legendary_enhancement_edit()
                    elif event.key in (pygame.K_LEFT, pygame.K_MINUS, pygame.K_DOWN):
                        legendary_enhancement_edit_level = max(0, legendary_enhancement_edit_level - 1)
