            pygame.draw.ellipse(icon_surface, wing_color, (ICON_SIZE - ICON_SIZE//3 - 2, cy - 8, ICON_SIZE//3, 16))
            pygame.draw.circle(icon_surface, gold_color, (cx, cy), ICON_SIZE//6)
