# ======== 인장 호위무사 퇴장 알림 ========
_seal_departure_timer = 0
_seal_departure_text = ""

def trigger_seal_departure_notification(text="호위무사가 떠났습니다"):
    """인장 호위무사 퇴장 시 화면 중앙 알림 트리거"""
    global _seal_departure_timer, _seal_departure_text
    _seal_departure_timer = 150  # 약 2.5초 (60fps 기준)
    _seal_departure_text = text

def update_and_draw_seal_departure(screen):
    """인장 호위무사 퇴장 알림 업데이트 및 그리기"""
    global _seal_departure_timer
    if _seal_departure_timer <= 0:
        return
    _seal_departure_timer -= 1

    alpha = 255
    if _seal_departure_timer > 120:
        alpha = int((150 - _seal_departure_timer) / 30 * 255)
    elif _seal_departure_timer < 30:
        alpha = int(_seal_departure_timer / 30 * 255)

    import pygame.freetype as _ft_mod
    try:
        font = _ft_mod.Font(
            resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Bold.ttf")), 22
        )
    except Exception:
        try:
            font = _ft_mod.SysFont("malgun gothic", 22)
        except Exception:
            font = _ft_mod.SysFont(None, 22)

    txt, rect = font.render(_seal_departure_text, (200, 180, 255))
    rect.center = (WIDTH // 2, HEIGHT // 3)

    bg = rect.inflate(40, 20)
    bgs = pygame.Surface((bg.width, bg.height), pygame.SRCALPHA)
    bgs.fill((20, 0, 40, min(180, alpha)))
    screen.blit(bgs, bg.topleft)
    pygame.draw.rect(screen, (150, 120, 200), bg, 2)

    if alpha < 255:
        txt.set_alpha(alpha)
    screen.blit(txt, rect)

# ======== Intro Input Tracer (디버그) ========
# 시작 인트로 입력 문제가 간헐적일 때, 프레임별 이벤트/상태를 로깅한다.
class _IntroInputTracer:
    def __init__(self, name: str, enabled: bool = True, capacity: int = 360):
        self.enabled = enabled
        self.name = name
        self.capacity = max(60, int(capacity))
        self.buf: list[str] = []
        self.start_ms = pygame.time.get_ticks()
        self.last_snapshot_ms = self.start_ms

    def record(self, tag: str, *, events: list[pygame.event.Event] | None = None, pressed_left: bool | None = None, extra: str = "") -> None:
        if not self.enabled:
            return
        now = pygame.time.get_ticks()
        parts = [f"t+{now - self.start_ms:04d}ms", tag]
        if pressed_left is not None:
            parts.append(f"mbL={'1' if pressed_left else '0'}")
        if events is not None and events:
            kinds = ",".join(_safe_event_name(e.type) for e in events[:12])
            more = "" if len(events) <= 12 else f"+{len(events) - 12}"
            parts.append(f"ev=[{kinds}{more}]")
        if extra:
            parts.append(extra)
        line = " | ".join(parts)
        self._push(line)

    def snapshot(self, tag: str) -> None:
        if not self.enabled:
            return
        now = pygame.time.get_ticks()
        if now - self.last_snapshot_ms >= 100:  # 10fps로만 스냅샷
            self.last_snapshot_ms = now
            focused = pygame.key.get_focused()
            try:
                mouse_focus = pygame.mouse.get_focused()
            except Exception:
                mouse_focus = False
            self._push(f"t+{now - self.start_ms:04d}ms | SNAP:{tag} | focus={int(bool(focused))}/{int(bool(mouse_focus))}")

    def flush(self, reason: str) -> None:
        if not self.enabled:
            return
        try:
            import os, datetime
            os.makedirs("logs", exist_ok=True)
            ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            path = os.path.join("logs", f"intro_input_{ts}.log")
            with open(path, "w", encoding="utf-8") as f:
                f.write(f"[IntroInputTrace] {self.name} - {reason}\n")
                for line in self.buf:
                    f.write(line + "\n")
            # print(f"[INTRO DEBUG] trace saved: {path}")
        except Exception as _:
            pass

    def _push(self, line: str) -> None:
        self.buf.append(line)
        if len(self.buf) > self.capacity:
            self.buf.pop(0)

def _safe_event_name(t: int) -> str:
    # 간단한 이벤트 타입 이름치환 (자주 쓰는 것만)
    try:
        if t == pygame.MOUSEBUTTONDOWN:
            return "MBDN"
        if t == pygame.MOUSEBUTTONUP:
            return "MBUP"
        if t == pygame.KEYDOWN:
            return "KDN"
        if t == pygame.KEYUP:
            return "KUP"
        if t == pygame.QUIT:
            return "QUIT"
        return str(t)
    except Exception:
        return str(t)

def _is_window_focused() -> bool:
    """키/마우스 어느 쪽이든 포커스를 얻었는지 보조 체크."""
    try:
        if pygame.key.get_focused():
            return True
    except Exception:
        pass
    try:
        if pygame.mouse.get_focused():
            return True
    except Exception:
        pass
    return False

def play_stage_intro_video(
    video_path: str | os.PathLike[str] | None,
    *,
    stage_text: str,
    boss_text: str,
    stage_color: tuple[int, int, int] = (255, 255, 255),
    boss_color: tuple[int, int, int] = (255, 255, 255),
    fade_out_on_finish: bool = True,
    auto_complete: bool = True,
    post_hold_ms: int | None = None,
) -> tuple[bool, pygame.Surface | None]:
    """인트로 영상을 재생하고 마지막 프레임을 반환한다."""

    if not video_path:
        return False, None

    absolute_path = os.fspath(video_path)
    if not os.path.isfile(absolute_path):
        # print(f"[StageIntro] Video not found: {absolute_path}")
        return False, None

    if not ensure_cv2_loaded():
        print(f"[StageIntro] OpenCV 로드 실패: {CV2_IMPORT_ERROR}")
        return False, None

    # 영상 재생 전에는 기존 BGM을 완전히 멈춘다 (인트로 영상 오디오만 재생되도록)
    try:
        bgm_manager.stop_bgm()
    except Exception as exc:
        print(f"[StageIntro] BGM 정지 실패: {exc}")

    cap = cv2.VideoCapture(absolute_path)
    if not cap.isOpened():
        # print(f"[StageIntro] Failed to open video: {absolute_path}")
        return False, None

    fps = cap.get(cv2.CAP_PROP_FPS)
    if not fps or fps <= 1:
        fps = 30.0

    overlay = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
    overlay.fill((0, 0, 0, 90))

    text_timer_start = pygame.time.get_ticks()
    TEXT_VISIBLE_MS = 2000
    TEXT_FADE_MS = 500

    audio_channel = None
    audio_sound = load_stage_intro_audio(absolute_path)
    if audio_sound is not None:
        try:
            audio_channel = audio_sound.play()
        except pygame.error as exc:
            print(f"[StageIntro] 오디오 재생 실패: {exc}")

    clock = pygame.time.Clock()
    tracer = _IntroInputTracer("video_intro", enabled=True)
    prev_focus = _is_window_focused()
    last_surface: pygame.Surface | None = None
    ai_mode_active = bool(player_ai_enabled)
    ai_min_watch_ms = 0  # AI는 바로 스킵 가능
    ai_auto_skip_ms = 600  # 자동 스킵 시도 시각(0.6초 이후)
    intro_start_ms = pygame.time.get_ticks()

    played = False
    skip_triggered = False

    while True:
        ret, frame = cap.read()
        if not ret:
            break

        played = True

        frame = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
        frame = cv2.resize(frame, (WIDTH, HEIGHT))
        frame_surface = pygame.image.frombuffer(frame.tobytes(), (WIDTH, HEIGHT), "RGB")
        frame_surface = frame_surface.convert()
        last_surface = frame_surface.copy()

        SCREEN.blit(frame_surface, (0, 0))
        SCREEN.blit(overlay, (0, 0))

        elapsed = pygame.time.get_ticks() - text_timer_start
        text_alpha = 0
        if elapsed < TEXT_VISIBLE_MS:
            if TEXT_FADE_MS > 0 and elapsed > TEXT_VISIBLE_MS - TEXT_FADE_MS:
                fade_progress = (elapsed - (TEXT_VISIBLE_MS - TEXT_FADE_MS)) / TEXT_FADE_MS
                text_alpha = int(255 * max(0.0, 1.0 - fade_progress))
            else:
                text_alpha = 255

        if text_alpha > 0:
            ui_manager.draw_centered_text(
                stage_text, 56, -120, stage_color, "elegant", alpha=text_alpha
            )
            ui_manager.draw_centered_text(
                boss_text, 42, -50, boss_color, "glow", alpha=text_alpha
            )

        pygame.display.flip()

        skip_video = False
        events_now = pygame.event.get()
        tracer.record("ev", events=events_now, pressed_left=None)
        for event in events_now:
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()
            # 스페이스 또는 마우스 클릭으로 영상 스킵
            if (event.type == pygame.KEYDOWN and event.key == pygame.K_SPACE) or (event.type == pygame.MOUSEBUTTONDOWN):
                skip_video = True
                skip_triggered = True
                break

        # 이벤트가 없더라도 현재 마우스 버튼/포커스 변화 상태를 한 번 더 확인
        try:
            mb_now = pygame.mouse.get_pressed()
            if not skip_video and mb_now and len(mb_now) >= 1 and bool(mb_now[0]):
                tracer.record("mb_now", pressed_left=True)
                skip_video = True
                skip_triggered = True
        except Exception:
            pass
        cur_focus = _is_window_focused()
        if not skip_video and (not prev_focus) and cur_focus:
            tracer.record("focus_gain_skip")
            skip_video = True
            skip_triggered = True
        prev_focus = cur_focus

        # AI 자동 스킵: 짧은 시청 후 바로 넘긴다
        if ai_mode_active and not skip_video:
            elapsed_ms = pygame.time.get_ticks() - intro_start_ms
            if elapsed_ms >= ai_auto_skip_ms:
                skip_video = True
                skip_triggered = True

        # AI 자동 플레이 최소 시청 가드 (현재 0ms)
        if ai_mode_active and skip_video:
            elapsed_ms = pygame.time.get_ticks() - intro_start_ms
            if elapsed_ms < ai_min_watch_ms:
                skip_video = False
                skip_triggered = False
                tracer.record("ai_guard", extra=f"blocked skip at {elapsed_ms}ms")

        # 포커스 변화로 인한 자동 스킵은 AI 모드에서 비활성화
        if ai_mode_active and skip_video and not skip_triggered:
            # 만약 위 가드에서 막히지 않은 포커스/마우스 자동 스킵이면 무효화
            skip_video = False

        if skip_video:
            break

        clock.tick(fps)

    cap.release()
    pygame.event.get()
    if audio_channel is not None:
        try:
            audio_channel.fadeout(INTRO_VIDEO_AUDIO_FADE_MS)
        except (AttributeError, pygame.error):
            audio_channel.stop()
        audio_channel = None

    do_fade = (fade_out_on_finish or skip_triggered) and last_surface is not None

    if do_fade:
        fade_frames = max(12, int(fps * 0.5))
        fade_surface = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
        for frame_index in range(fade_frames):
            alpha = int(255 * ((frame_index + 1) / fade_frames))
            SCREEN.blit(last_surface, (0, 0))
            fade_surface.fill((0, 0, 0, alpha))
            SCREEN.blit(fade_surface, (0, 0))
            pygame.display.flip()
            clock.tick(fps)
            pygame.event.pump()
            tracer.snapshot("fade")

    # 영상 종료 후 프레임을 남기지 않아도 부드럽게 블랙으로 전환
    if fade_out_on_finish and last_surface is None:
        fade_frames = max(12, int(fps * 0.5))
        fade_surface = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
        for frame_index in range(fade_frames):
            alpha = int(255 * ((frame_index + 1) / fade_frames))
            fade_surface.fill((0, 0, 0, alpha))
            SCREEN.blit(fade_surface, (0, 0))
            pygame.display.flip()
            clock.tick(fps)
            pygame.event.pump()
            tracer.snapshot("fade2")

    should_complete = played and auto_complete and (fade_out_on_finish or skip_triggered)
    if should_complete:
        base_hold = INTRO_TRANSITION_HOLD_MS if post_hold_ms is None else max(0, post_hold_ms)
        hold_ms = 0 if skip_triggered else base_hold
        tracer.record("complete", pressed_left=None, extra=f"hold={hold_ms}")
        complete_stage_intro_transition(hold_ms)
        tracer.flush("video_end")

    return played, last_surface


INTRO_VIDEO_AUDIO_FADE_MS = 700  # 영상 종료 시 오디오 페이드아웃 시간
INTRO_TRANSITION_HOLD_MS = 220  # 영상 종료 후 블랙 유지 시간


def complete_stage_intro_transition(hold_ms: int = INTRO_TRANSITION_HOLD_MS) -> None:
    """영상 인트로 종료 후 짧게 페이드아웃하며 입력 이벤트를 정리한다.

    변경점: 마우스 선입력으로 인한 잔류 클릭/업 이벤트까지 함께 정리한다.
    (초기 프레임에서 클릭/키 입력이 먹히지 않거나 반대로 과다 인식되는 현상 방지)
    """

    if hold_ms <= 0:
        pygame.event.pump()
        # 키/마우스 다운/업 이벤트를 함께 정리해 선입력 잔류 제거
        pygame.event.clear([pygame.KEYDOWN, pygame.KEYUP, pygame.MOUSEBUTTONDOWN, pygame.MOUSEBUTTONUP])
        try:
            pass  # print(f"[INTRO DEBUG] transition cleared (hold={hold_ms})")
        except Exception:
            pass
        return

    fade_frames = max(2, min(10, hold_ms // 30))
    frame_delay = max(10, hold_ms // fade_frames)
    overlay = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)

    for frame_index in range(fade_frames):
        alpha = int(255 * (frame_index + 1) / fade_frames)
        overlay.fill((0, 0, 0, alpha))
        SCREEN.blit(overlay, (0, 0))
        pygame.display.flip()
        pygame.time.delay(frame_delay)
        pygame.event.pump()

    remaining_delay = hold_ms - frame_delay * fade_frames
    if remaining_delay > 0:
        pygame.time.delay(remaining_delay)

    # 페이드 종료 시에도 한 번 더 정리 (업/다운 쌍이 같은 프레임에 들어온 경우 대비)
    pygame.event.clear([pygame.KEYDOWN, pygame.KEYUP, pygame.MOUSEBUTTONDOWN, pygame.MOUSEBUTTONUP])
    try:
        pass  # print(f"[INTRO DEBUG] transition cleared (hold={hold_ms})")
    except Exception:
        pass




def show_stage8_boss_dialogue():
    """
    스테이지 8 보스 대화 시스템 (JRPG 스타일)
    캐릭터가 오른쪽에 크게 표시되고, 대화창은 하단 전체에 위치
    """
    global stage8_boss_dialogue_shown, stage8_boss_portrait

    clock = pygame.time.Clock()

    # 폰트 설정
    font_name = FontStyle.subtitle()   # 28pt 화자 이름용
    font_text = FontStyle.body()       # 22pt 대사용
    font_small = FontStyle.small()     # 16pt 안내용

    # 보스 초상화 이미지 로드 (크게 표시)
    portrait_path = resource_path(os.path.join("chat", "stage8.png"))
    angry_portrait_path = resource_path(os.path.join("chat", "stage8angry.png"))
    boss_portrait = None
    boss_portrait_angry = None

    # 일반 초상화 로드
    try:
        boss_portrait = pygame.image.load(portrait_path).convert_alpha()
        # JRPG 스타일: 화면 오른쪽에 크게 표시 (화면 높이의 70% 정도)
        target_height = int(HEIGHT * 0.75)
        aspect_ratio = boss_portrait.get_width() / boss_portrait.get_height()
        target_width = int(target_height * aspect_ratio)
        boss_portrait = pygame.transform.smoothscale(boss_portrait, (target_width, target_height))
        # print(f"✅ 스테이지 8 보스 초상화 로드 (JRPG): {target_width}x{target_height}")
    except Exception as e:
        print(f"⚠️ 스테이지 8 보스 초상화 로드 실패: {e}")
        # 폴백 초상화
        boss_portrait = pygame.Surface((300, 450), pygame.SRCALPHA)
        pygame.draw.ellipse(boss_portrait, (60, 80, 120), (30, 30, 240, 380))
        pygame.draw.circle(boss_portrait, (100, 130, 180), (150, 100), 70)

    # 화난 초상화 로드
    try:
        boss_portrait_angry = pygame.image.load(angry_portrait_path).convert_alpha()
        target_height = int(HEIGHT * 0.75)
        aspect_ratio = boss_portrait_angry.get_width() / boss_portrait_angry.get_height()
        target_width = int(target_height * aspect_ratio)
        boss_portrait_angry = pygame.transform.smoothscale(boss_portrait_angry, (target_width, target_height))
        # print(f"✅ 스테이지 8 보스 화난 초상화 로드: {target_width}x{target_height}")
    except Exception as e:
        print(f"⚠️ 스테이지 8 보스 화난 초상화 로드 실패: {e}")
        # 폴백: 일반 초상화 사용
        boss_portrait_angry = boss_portrait

    # 대화 시퀀스
    dialogues = [
        {
            "speaker": "아카무 리고",
            "text": "여기까지 온 것도 용케 대단한데? 흐흐흐",
            "name_color": (120, 180, 255),  # 밝은 청색
            "is_boss": True,
            "use_angry_portrait": False  # 일반 표정
        },
        {
            "speaker": "주인공",
            "text": "시끄러 이 망할 요상한 닌자녀석",
            "name_color": (255, 220, 100),  # 황금색
            "is_boss": False,
            "use_angry_portrait": False
        },
        {
            "speaker": "아카무 리고",
            "text": "너도 멘헤라걸 곁으로 보내주지 (쑻)",
            "name_color": (255, 100, 100),  # 붉은색 (화남)
            "is_boss": True,
            "use_angry_portrait": True  # 화난 표정 사용
        }
    ]

    # 배경 캡처 (현재 게임 화면)
    background = SCREEN.copy()

    # 대화창 디자인 설정 (JRPG 스타일)
    dialogue_height = 150
    dialogue_margin = 20
    name_box_width = 160
    name_box_height = 40

    for dialogue in dialogues:
        # 타이핑 효과 변수
        displayed_text = ""
        text_complete = False
        typing_speed = 30  # 밀리초당 한 글자 (약간 빠르게)
        last_char_time = pygame.time.get_ticks()

        # 캐릭터 등장 애니메이션
        slide_progress = 0.0
        slide_duration = 0.3  # 0.3초 슬라이드 인

        running = True
        start_time = pygame.time.get_ticks()

        while running:
            current_time = pygame.time.get_ticks()
            dt = clock.tick(60) / 1000.0

            # 슬라이드 애니메이션 진행
            if slide_progress < 1.0:
                slide_progress = min(1.0, (current_time - start_time) / 1000.0 / slide_duration)
                # 이징 함수 (ease out)
                slide_progress = 1.0 - (1.0 - slide_progress) ** 2

            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    pygame.quit()
                    return False
                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_SPACE or event.key == pygame.K_RETURN:
                        if text_complete:
                            running = False
                        else:
                            displayed_text = dialogue["text"]
                            text_complete = True
                elif event.type == pygame.MOUSEBUTTONDOWN:
                    if text_complete:
                        running = False
                    else:
                        displayed_text = dialogue["text"]
                        text_complete = True

            # 타이핑 효과 (슬라이드 완료 후 시작)
            if slide_progress >= 1.0:
                if not text_complete and current_time - last_char_time >= typing_speed:
                    if len(displayed_text) < len(dialogue["text"]):
                        displayed_text += dialogue["text"][len(displayed_text)]
                        last_char_time = current_time
                    else:
                        text_complete = True

            # === 배경 그리기 ===
            SCREEN.blit(background, (0, 0))

            # 어두운 오버레이 (상단 부분만)
            overlay = pygame.Surface((WIDTH, HEIGHT - dialogue_height - dialogue_margin), pygame.SRCALPHA)
            overlay.fill((0, 0, 0, 120))
            SCREEN.blit(overlay, (0, 0))

            # === 캐릭터 초상화 (오른쪽에 크게) ===
            if dialogue["is_boss"] and boss_portrait:
                # 화난 표정 여부에 따라 초상화 선택
                current_portrait = boss_portrait_angry if dialogue.get("use_angry_portrait", False) else boss_portrait

                # 슬라이드 인 애니메이션 (오른쪽에서 들어옴)
                final_x = WIDTH - current_portrait.get_width() + 30  # 약간 오른쪽으로 걸쳐서
                start_x = WIDTH + 50
                portrait_x = int(start_x + (final_x - start_x) * slide_progress)
                portrait_y = HEIGHT - dialogue_height - current_portrait.get_height() + 40

                # 그림자 효과
                shadow = pygame.Surface((current_portrait.get_width(), current_portrait.get_height()), pygame.SRCALPHA)
                shadow.fill((0, 0, 0, 80))
                SCREEN.blit(shadow, (portrait_x + 8, portrait_y + 8))

                # 초상화 그리기
                SCREEN.blit(current_portrait, (portrait_x, portrait_y))

            # === 대화창 (하단 전체, 닌자/일본풍 프리미엄 스타일) ===
            dialogue_y = HEIGHT - dialogue_height - dialogue_margin
            box_width = WIDTH - dialogue_margin * 2

            # 대화창 배경 (그라데이션 효과)
            dialogue_bg = pygame.Surface((box_width, dialogue_height), pygame.SRCALPHA)

            # 어두운 닌자풍 배경 (짙은 남색/검정 그라데이션)
            for y in range(dialogue_height):
                progress = y / dialogue_height
                r = int(10 + 15 * progress)
                g = int(15 + 20 * progress)
                b = int(30 + 25 * progress)
                alpha = 235 - int(y * 0.2)
                pygame.draw.line(dialogue_bg, (r, g, b, alpha), (0, y), (box_width, y))

            # === 프리미엄 다중 테두리 시스템 ===
            # 색상 정의 (붉은 금색 닌자 테마)
            outer_dark = (80, 40, 30)      # 외곽 어두운 갈색
            main_gold = (200, 160, 80)     # 메인 금색
            bright_gold = (255, 220, 140)  # 밝은 금색
            red_accent = (180, 60, 40)     # 붉은 악센트
            inner_glow = (255, 240, 200, 80)  # 내부 글로우

            # 1단계: 외곽 어두운 테두리 (그림자 효과)
            pygame.draw.rect(dialogue_bg, outer_dark, (0, 0, box_width, dialogue_height), 5)

            # 2단계: 메인 금색 테두리
            pygame.draw.rect(dialogue_bg, main_gold, (3, 3, box_width - 6, dialogue_height - 6), 3)

            # 3단계: 내부 밝은 하이라이트
            pygame.draw.rect(dialogue_bg, bright_gold, (7, 7, box_width - 14, dialogue_height - 14), 1)

            # === 일본풍 모서리 장식 (대형 코너 브래킷) ===
            corner_size = 25
            corner_inner = 18

            # 코너 장식 그리기 함수
            def draw_corner_decoration(surf, cx, cy, dx, dy):
                # 외곽 L자 (금색)
                pygame.draw.line(surf, main_gold, (cx, cy), (cx + corner_size * dx, cy), 3)
                pygame.draw.line(surf, main_gold, (cx, cy), (cx, cy + corner_size * dy), 3)
                # 내부 L자 (밝은 금색)
                pygame.draw.line(surf, bright_gold, (cx + 4 * dx, cy + 4 * dy), (cx + corner_inner * dx, cy + 4 * dy), 2)
                pygame.draw.line(surf, bright_gold, (cx + 4 * dx, cy + 4 * dy), (cx + 4 * dx, cy + corner_inner * dy), 2)
                # 코너 점 장식 (붉은 악센트)
                pygame.draw.circle(surf, red_accent, (cx + 2 * dx, cy + 2 * dy), 3)

            # 네 모서리 장식
            draw_corner_decoration(dialogue_bg, 2, 2, 1, 1)  # 좌상단
            draw_corner_decoration(dialogue_bg, box_width - 3, 2, -1, 1)  # 우상단
            draw_corner_decoration(dialogue_bg, 2, dialogue_height - 3, 1, -1)  # 좌하단
            draw_corner_decoration(dialogue_bg, box_width - 3, dialogue_height - 3, -1, -1)  # 우하단

            # === 상단/하단 중앙 장식 (일본풍 패턴) ===
            center_x = box_width // 2

            # 상단 중앙 다이아몬드 장식
            diamond_size = 8
            top_diamond = [
                (center_x, 6),
                (center_x + diamond_size, 6 + diamond_size),
                (center_x, 6 + diamond_size * 2),
                (center_x - diamond_size, 6 + diamond_size)
            ]
            pygame.draw.polygon(dialogue_bg, red_accent, top_diamond)
            pygame.draw.polygon(dialogue_bg, bright_gold, top_diamond, 1)

            # 상단 좌우 가로선 장식
            line_length = 60
            pygame.draw.line(dialogue_bg, main_gold, (center_x - line_length - 15, 10), (center_x - 15, 10), 2)
            pygame.draw.line(dialogue_bg, main_gold, (center_x + 15, 10), (center_x + line_length + 15, 10), 2)

            # 하단 중앙 삼각형 장식
            bottom_tri = [
                (center_x - 10, dialogue_height - 8),
                (center_x + 10, dialogue_height - 8),
                (center_x, dialogue_height - 18)
            ]
            pygame.draw.polygon(dialogue_bg, red_accent, bottom_tri)
            pygame.draw.polygon(dialogue_bg, bright_gold, bottom_tri, 1)

            # === 측면 세로 장식선 ===
            side_margin = 15
            pygame.draw.line(dialogue_bg, (main_gold[0], main_gold[1], main_gold[2], 120),
                           (side_margin, 35), (side_margin, dialogue_height - 35), 1)
            pygame.draw.line(dialogue_bg, (main_gold[0], main_gold[1], main_gold[2], 120),
                           (box_width - side_margin, 35), (box_width - side_margin, dialogue_height - 35), 1)

            # === 내부 글로우 효과 ===
            glow_surf = pygame.Surface((box_width - 20, dialogue_height - 20), pygame.SRCALPHA)
            pygame.draw.rect(glow_surf, inner_glow, (0, 0, box_width - 20, dialogue_height - 20), 2)
            dialogue_bg.blit(glow_surf, (10, 10))

            SCREEN.blit(dialogue_bg, (dialogue_margin, dialogue_y))

            # === 이름 박스 (대화창 위에 겹쳐서, 프리미엄 스타일) ===
            name_box_x = dialogue_margin + 25
            name_box_y = dialogue_y - name_box_height // 2

            # 이름 박스 배경 (그라데이션)
            name_box = pygame.Surface((name_box_width, name_box_height), pygame.SRCALPHA)
            for ny in range(name_box_height):
                progress = ny / name_box_height
                r = int(20 + 15 * progress)
                g = int(25 + 15 * progress)
                b = int(45 + 15 * progress)
                pygame.draw.line(name_box, (r, g, b, 245), (0, ny), (name_box_width, ny))

            # 이름 박스 외곽 테두리 (어두운 색)
            pygame.draw.rect(name_box, outer_dark, (0, 0, name_box_width, name_box_height), 3)

            # 이름 박스 메인 테두리 (화자 색상 + 금색 혼합)
            name_border = tuple(int((dialogue["name_color"][i] + main_gold[i]) / 2) for i in range(3))
            pygame.draw.rect(name_box, name_border, (2, 2, name_box_width - 4, name_box_height - 4), 2)

            # 내부 하이라이트
            highlight_color = tuple(min(255, c + 50) for c in dialogue["name_color"])
            pygame.draw.rect(name_box, highlight_color, (4, 4, name_box_width - 8, name_box_height - 8), 1)

            # 좌우 작은 장식
            pygame.draw.circle(name_box, red_accent, (8, name_box_height // 2), 3)
            pygame.draw.circle(name_box, red_accent, (name_box_width - 8, name_box_height // 2), 3)

            SCREEN.blit(name_box, (name_box_x, name_box_y))

            # 화자 이름 (이름 박스 중앙)
            speaker_surface = font_name.render(dialogue["speaker"], True, dialogue["name_color"])
            speaker_rect = speaker_surface.get_rect(center=(name_box_x + name_box_width // 2, name_box_y + name_box_height // 2))
            SCREEN.blit(speaker_surface, speaker_rect)

            # === 대사 텍스트 ===
            text_x = dialogue_margin + 35
            text_y = dialogue_y + 30
            max_text_width = WIDTH - dialogue_margin * 2 - 70

            # 텍스트 줄바꿈 처리
            lines = []
            current_line = ""
            for char in displayed_text:
                test_line = current_line + char
                test_surface = font_text.render(test_line, True, WHITE)
                if test_surface.get_width() <= max_text_width:
                    current_line = test_line
                else:
                    lines.append(current_line)
                    current_line = char
            if current_line:
                lines.append(current_line)

            # 텍스트 렌더링 (그림자 포함)
            line_height = font_text.get_linesize() + 4
            for i, line in enumerate(lines[:3]):  # 최대 3줄
                # 그림자
                shadow_surface = font_text.render(line, True, (0, 0, 0))
                SCREEN.blit(shadow_surface, (text_x + 2, text_y + i * line_height + 2))
                # 메인 텍스트
                text_surface = font_text.render(line, True, (255, 255, 255))
                SCREEN.blit(text_surface, (text_x, text_y + i * line_height))

            # === 계속 표시 (프리미엄 애니메이션 아이콘) ===
            if text_complete:
                indicator_x = WIDTH - dialogue_margin - 45
                indicator_y = dialogue_y + dialogue_height - 35

                # 부드러운 바운스 효과
                bounce = math.sin(current_time * 0.008) * 4
                indicator_y += int(bounce)

                # 글로우 효과 (깜빡임)
                glow_alpha = int(150 + 100 * math.sin(current_time * 0.01))
                glow_surf = pygame.Surface((40, 30), pygame.SRCALPHA)
                pygame.draw.circle(glow_surf, (255, 200, 100, glow_alpha // 3), (20, 15), 18)
                SCREEN.blit(glow_surf, (indicator_x - 12, indicator_y - 8))

                # 이중 삼각형 (외곽 + 내부)
                # 외곽 삼각형 (금색 테두리)
                outer_tri = [
                    (indicator_x, indicator_y - 2),
                    (indicator_x + 20, indicator_y - 2),
                    (indicator_x + 10, indicator_y + 14)
                ]
                pygame.draw.polygon(SCREEN, main_gold, outer_tri, 2)

                # 내부 삼각형 (밝은 금색 채움)
                inner_tri = [
                    (indicator_x + 3, indicator_y + 1),
                    (indicator_x + 17, indicator_y + 1),
                    (indicator_x + 10, indicator_y + 11)
                ]
                pygame.draw.polygon(SCREEN, bright_gold, inner_tri)

                # 중앙 작은 점 (붉은 악센트)
                pygame.draw.circle(SCREEN, red_accent, (indicator_x + 10, indicator_y + 5), 2)

            pygame.display.flip()

    # 대화 완료
    stage8_boss_dialogue_shown = True
    # print("✅ 스테이지 8 보스 대화 완료 (JRPG 스타일)")
    return True


def draw_stage3_border():
    """스테이지 3 멘헤라 테두리 그리기"""
    if current_stage == 3:
        border_thickness = 10  # 스테이지 2와 동일한 두께
        # SCREEN Surface 전체를 감싸는 테두리 (SCREEN은 이미 게임 전체 영역)
        x_off = 0
        game_w = WIDTH
        # 스테이지 3 색상 (멘헤라 테마 - 핑크/보라색 계열)
        base_color = (60, 20, 60)  # 어두운 보라색 (베이스)
        mid_color = (100, 40, 100)  # 중간 보라색
        light_color = (140, 60, 140)  # 밝은 보라색
        accent_color = (200, 100, 150)  # 핑크 악센트

        # 메인 테두리
        pygame.draw.rect(SCREEN, base_color, (x_off, 0, game_w, border_thickness))
        pygame.draw.rect(SCREEN, base_color, (x_off, HEIGHT - border_thickness, game_w, border_thickness))
        pygame.draw.rect(SCREEN, base_color, (x_off, 0, border_thickness, HEIGHT))
        pygame.draw.rect(SCREEN, base_color, (x_off + game_w - border_thickness, 0, border_thickness, HEIGHT))

        # 내부 테두리 (깊이감 추가)
        inner_thickness = 2
        pygame.draw.rect(SCREEN, light_color, (x_off + border_thickness - inner_thickness, border_thickness - inner_thickness,
                                              game_w - 2*(border_thickness - inner_thickness), inner_thickness))
        pygame.draw.rect(SCREEN, light_color, (x_off + border_thickness - inner_thickness, HEIGHT - border_thickness,
                                              game_w - 2*(border_thickness - inner_thickness), inner_thickness))
        pygame.draw.rect(SCREEN, light_color, (x_off + border_thickness - inner_thickness, border_thickness - inner_thickness,
                                              inner_thickness, HEIGHT - 2*(border_thickness - inner_thickness)))
        pygame.draw.rect(SCREEN, light_color, (x_off + game_w - border_thickness, border_thickness - inner_thickness,
                                              inner_thickness, HEIGHT - 2*(border_thickness - inner_thickness)))

        # 코너에 하트 장식 (멘헤라 느낌)
        corner_size = 4
        # 좌상단
        draw.circle(accent_color, (x_off + border_thickness//2, border_thickness//2), corner_size)
        # 우상단
        draw.circle(accent_color, (x_off + game_w - border_thickness//2, border_thickness//2), corner_size)
        # 좌하단
        draw.circle(accent_color, (x_off + border_thickness//2, HEIGHT - border_thickness//2), corner_size)
        # 우하단
        draw.circle(accent_color, (x_off + game_w - border_thickness//2, HEIGHT - border_thickness//2), corner_size)

def draw_stage2_jungle_border():
    """스테이지 2 정글 테두리 그리기"""
    global stage2_border_timer, stage2_border_flash_timer
    # 기본 정글 테두리 (고정, 스테이지 1과 동일한 두께)
    if current_stage == 2:
        border_thickness = 10  # 스테이지 1과 동일한 두께
        # SCREEN Surface 전체를 감싸는 테두리 (SCREEN은 이미 게임 전체 영역)
        x_off = 0
        game_w = WIDTH
        # 기본 정글 색상 (진한 녹색 계열)
        base_green = (25, 51, 25)  # 매우 어두운 녹색 (베이스)
        jungle_green = (34, 70, 34)  # 어두운 녹색
        vine_green = (46, 87, 46)  # 덩굴 녹색
        leaf_green = (56, 102, 56)  # 잎사귀 녹색
        highlight_green = (76, 122, 76)  # 하이라이트 녹색
        # 메인 테두리 (그라데이션 효과를 위한 레이어링)
        # 베이스 레이어
        pygame.draw.rect(SCREEN, base_green, (x_off, 0, game_w, border_thickness))
        pygame.draw.rect(SCREEN, base_green, (x_off, HEIGHT - border_thickness, game_w, border_thickness))
        pygame.draw.rect(SCREEN, base_green, (x_off, 0, border_thickness, HEIGHT))
        pygame.draw.rect(SCREEN, base_green, (x_off + game_w - border_thickness, 0, border_thickness, HEIGHT))
        # 내부 테두리 (더 밝은 색으로 깊이감 추가)
        inner_thickness = 2
        pygame.draw.rect(SCREEN, vine_green, (x_off + border_thickness - inner_thickness, border_thickness - inner_thickness,
                                              game_w - 2*(border_thickness - inner_thickness), inner_thickness))
        pygame.draw.rect(SCREEN, vine_green, (x_off + border_thickness - inner_thickness, HEIGHT - border_thickness,
                                              game_w - 2*(border_thickness - inner_thickness), inner_thickness))
        pygame.draw.rect(SCREEN, vine_green, (x_off + border_thickness - inner_thickness, border_thickness - inner_thickness,
                                              inner_thickness, HEIGHT - 2*(border_thickness - inner_thickness)))
        pygame.draw.rect(SCREEN, vine_green, (x_off + game_w - border_thickness, border_thickness - inner_thickness,
                                              inner_thickness, HEIGHT - 2*(border_thickness - inner_thickness)))
        # 테두리 장식 패턴 (정글 느낌)
        # 나뭇가지 패턴
        for i in range(0, game_w, 30):
            # 상단 나뭇가지
            draw.line(jungle_green, (x_off + i, 2), (x_off + i + 15, 8), 1)
            draw.line(jungle_green, (x_off + i + 15, 2), (x_off + i, 8), 1)
            # 하단 나뭇가지
            draw.line(jungle_green, (x_off + i, HEIGHT - 8), (x_off + i + 15, HEIGHT - 2), 1)
            draw.line(jungle_green, (x_off + i + 15, HEIGHT - 8), (x_off + i, HEIGHT - 2), 1)
        for i in range(0, HEIGHT, 30):
            # 좌측 나뭇가지
            draw.line(jungle_green, (x_off + 2, i), (x_off + 8, i + 15), 1)
            draw.line(jungle_green, (x_off + 2, i + 15), (x_off + 8, i), 1)
            # 우측 나뭇가지
            draw.line(jungle_green, (x_off + game_w - 8, i), (x_off + game_w - 2, i + 15), 1)
            draw.line(jungle_green, (x_off + game_w - 8, i + 15), (x_off + game_w - 2, i), 1)
        # 코너 장식 (덩굴 매듭)
        corner_radius = 4
        # 좌상단
        draw.circle(highlight_green, (x_off + border_thickness//2, border_thickness//2), corner_radius)
        # 우상단
        draw.circle(highlight_green, (x_off + game_w - border_thickness//2, border_thickness//2), corner_radius)
        # 좌하단
        draw.circle(highlight_green, (x_off + border_thickness//2, HEIGHT - border_thickness//2), corner_radius)
        # 우하단
        draw.circle(highlight_green, (x_off + game_w - border_thickness//2, HEIGHT - border_thickness//2), corner_radius)
        # 벽 충돌 시 깜빡임 효과
        if stage2_border_flash_timer > 0:
            flash_alpha = stage2_border_flash_timer / stage2_border_flash_duration
            flash_color = (
                int(100 + 155 * flash_alpha),
                int(200 + 55 * flash_alpha),
                int(100 + 155 * flash_alpha)
            )
            # 테두리 하이라이트 (스테이지 1과 동일한 두께)
            pygame.draw.rect(SCREEN, flash_color, (x_off, 0, game_w, border_thickness), 0)
            pygame.draw.rect(SCREEN, flash_color, (x_off, HEIGHT - border_thickness, game_w, border_thickness), 0)
            pygame.draw.rect(SCREEN, flash_color, (x_off, 0, border_thickness, HEIGHT), 0)
            pygame.draw.rect(SCREEN, flash_color, (x_off + game_w - border_thickness, 0, border_thickness, HEIGHT), 0)
            stage2_border_flash_timer -= 1
def update_stage2_leaves():
    """떨어지는 잎사귀 업데이트"""
    global stage2_leaves
    new_leaves = []
    for leaf in stage2_leaves:
        # 물리 업데이트
        leaf['x'] += leaf['vx']
        leaf['y'] += leaf['vy']
        leaf['vy'] += 0.1  # 중력
        leaf['rotation'] += leaf['rotation_speed']
        leaf['life'] -= 1
        # 화면 안에 있고 수명이 남은 잎사귀만 유지
        if leaf['life'] > 0 and leaf['y'] < HEIGHT + 50:
            new_leaves.append(leaf)
    stage2_leaves = new_leaves

# =============================================
# 통합 트레이드 포인트 별 시스템
# =============================================

def spawn_trade_point_star(x, y, source_type="wall"):
    """트레이드 포인트 별 생성 - 새로운 시스템 사용"""
    global trade_point_system
    trade_point_system.spawn_star(x, y, source_type)
    # print(f"    ! (: {source_type})")

def update_trade_point_stars():
    """트레이드 포인트 별과 파티클 업데이트 - 새로운 시스템 사용"""
    global trade_point_system, trade_point_collected, current_stage
    global stage3_hearts_collected, stage4_crows_collected  # 레거시 호환성

    # 튜토리얼 일시정지 상태 체크 (두 가지 방식 모두 체크)
    is_tutorial_paused = (current_stage == 50 and tutorial_pause_for_dialogue) or is_ingame_tutorial_paused()

    # 플레이어 패들과 공 위치로 업데이트 (둘 다 별을 수집할 수 있음)
    player_rect = PLAYER  # PLAYER는 이미 pygame.Rect 객체
    ball_rect = BALL  # BALL도 pygame.Rect 객체
    collected = trade_point_system.update(ball_rect, player_rect, paused=is_tutorial_paused)
    
    # 수집된 개수 업데이트
    if collected > 0:
        trade_point_collected = trade_point_system.get_collected_count()
        
        # 레거시 변수 업데이트 (호환성)
        if current_stage == 3:
            stage3_hearts_collected = trade_point_collected
        elif current_stage == 4:
            stage4_crows_collected = trade_point_collected
            
        # print(f"   ! : {trade_point_collected}")
        
        # Runtime skill system: starpoint collected
        on_starpoint_collected(1)
        
        # 획득 효과음
        try:
            coin_sound = pygame.mixer.Sound(resource_path("sounds/coin.wav"))
            play_sound_with_volume(coin_sound)
        except:
            pass
    
    return  # 기존 코드는 무시
    
    # 아래는 기존 코드 (실행되지 않음)
    new_stars = []
    for star in trade_point_stars:
        if star['collected']:
            continue
            
        # 물리 업데이트
        star['x'] += star['vx']
        star['y'] += star['vy']
        star['vy'] += 0.12  # 중력 (하트보다 약간 가벼움)
        star['rotation'] += star['rotation_speed']
        star['life'] -= 1
        star['sparkle_phase'] += 0.15
        star['glow_intensity'] = 0.7 + 0.3 * abs(math.sin(star['sparkle_phase']))
        
        # 좌우 흔들림 (부드러운 떠다니는 효과)
        star['x'] += math.sin(star['y'] * 0.015 + star['sparkle_phase']) * 1.2
        
        # 플레이어 패들과 충돌 체크
        star_rect = pygame.Rect(star['x'] - star['size'], star['y'] - star['size'],
                                star['size'] * 2, star['size'] * 2)
        if star_rect.colliderect(PLAYER) and star['life'] > 0:
            # 트레이드 포인트 획득
            trade_point_collected += 1

            # Runtime skill system: starpoint collected notification
            try:
                on_starpoint_collected(1)
            except Exception as e:
                pass  # print(f"[RuntimeSkill ERROR] {e}")

            # 레거시 변수 업데이트 (호환성)
            if current_stage == 3:
                stage3_hearts_collected += 1
            elif current_stage == 4:
                stage4_crows_collected += 1
            
            # print(f"   ! : {trade_point_collected}")
            
            # 텍스트 효과 추가
            trade_point_texts.append({
                'x': star['x'],
                'y': star['y'] - 20,
                'text': '+1 Star Point',
                'life': 80,
                'alpha': 255,
                'scale': 1.0
            })
            
            # 획득 파티클 폭발 효과
            for _ in range(15):
                particle = {
                    'x': star['x'],
                    'y': star['y'],
                    'vx': random.uniform(-3, 3),
                    'vy': random.uniform(-4, 1),
                    'size': random.uniform(2, 4),
                    'life': random.randint(40, 80),
                    'alpha': 255,
                    'color_shift': random.uniform(0, 1)
                }
                trade_point_particles.append(particle)
            
            # 획득 효과음
            try:
                coin_sound = pygame.mixer.Sound(resource_path("sounds/coin.wav"))
                play_sound_with_volume(coin_sound)
            except:
                pass
            
            star['collected'] = True
            continue
        
        # 화면 안에 있고 수명이 남은 별만 유지
        if star['life'] > 0 and star['y'] < HEIGHT + 50:
            new_stars.append(star)
    
    trade_point_stars = new_stars
    
    # 파티클 업데이트
    new_particles = []
    for particle in trade_point_particles:
        particle['x'] += particle['vx']
        particle['y'] += particle['vy']
        particle['vy'] += 0.05  # 약한 중력
        particle['vx'] *= 0.98  # 공기 저항
        particle['life'] -= 1
        particle['alpha'] = int(255 * (particle['life'] / 60))  # 페이드 아웃
        particle['size'] *= 0.98  # 크기 감소
        
        if particle['life'] > 0 and particle['alpha'] > 0:
            new_particles.append(particle)
    
    trade_point_particles = new_particles

def draw_trade_point_stars():
    """트레이드 포인트 별과 파티클 그리기 - 새로운 시스템 사용"""
    global trade_point_system
    trade_point_system.draw()
    return  # 기존 코드는 무시
    
    # 아래는 기존 코드 (실행되지 않음)
    for particle in trade_point_particles:
        if particle['alpha'] <= 0:
            continue
        
        # 색상 변화 (까마귀 파티클은 검은색, 일반 파티클은 형광색)
        color_shift = particle['color_shift']
        if color_shift == 0.0:  # 까마귀 파티클
            # 검은색에서 어두운 회색으로 변화
            gray_value = int(30 + particle['alpha'] * 0.2)
            r = gray_value
            g = gray_value
            b = gray_value
        elif color_shift < 0.33:
            # 노란색 → 흰색
            t = color_shift * 3
            r = int(255)
            g = int(255)
            b = int(100 + 155 * t)
        elif color_shift < 0.66:
            # 흰색 → 연한 파란색
            t = (color_shift - 0.33) * 3
            r = int(255 - 55 * t)
            g = int(255 - 30 * t)
            b = int(255)
        else:
            # 연한 파란색 → 노란색
            t = (color_shift - 0.66) * 3
            r = int(200 + 55 * t)
            g = int(225 + 30 * t)
            b = int(255 - 155 * t)
        
        # 파티클 그리기
        particle_surface = pygame.Surface((int(particle['size'] * 4), int(particle['size'] * 4)), pygame.SRCALPHA)
        pygame.draw.circle(particle_surface, (r, g, b, min(255, particle['alpha'])),
                         (int(particle['size'] * 2), int(particle['size'] * 2)), int(particle['size']))
        SCREEN.blit(particle_surface, (particle['x'] - particle['size'] * 2, particle['y'] - particle['size'] * 2))
    
    # 별 그리기
    for star in trade_point_stars:
        if star['collected']:
            continue
        
        # 투명도 계산
        alpha = min(255, star['life'] * 2)
        
        # 별의 실제 중심 좌표
        center_x = star['x']
        center_y = star['y']
        
        # 후광 효과 직접 그리기 (3단계) - 각 후광을 개별 서페이스로
        glow_alpha = int(alpha * 0.3 * star['glow_intensity'])
        for i in range(3):
            glow_size = star['size'] * (3 - i * 0.5)
            # 정확한 크기의 후광 서페이스 생성
            glow_surf_size = int(glow_size * 2 + 4)
            glow_surface = pygame.Surface((glow_surf_size, glow_surf_size), pygame.SRCALPHA)
            glow_color = (255, 240, 180, glow_alpha // (i + 1))
            pygame.draw.circle(glow_surface, glow_color, 
                             (glow_surf_size // 2, glow_surf_size // 2), int(glow_size))
            SCREEN.blit(glow_surface, (center_x - glow_surf_size // 2, center_y - glow_surf_size // 2))
        
        # 별 그리기를 위한 최소 크기 서페이스
        star_size = star['size'] * 2 + 4
        star_surface = pygame.Surface((star_size, star_size), pygame.SRCALPHA)
        local_center = star_size // 2
        
        # 5각 별 그리기
        points = []
        for i in range(10):
            angle = star['rotation'] + (i * math.pi / 5)
            if i % 2 == 0:
                # 외부 꼭지점
                radius = star['size']
            else:
                # 내부 꼭지점
                radius = star['size'] * 0.5
            x = local_center + radius * math.cos(angle)
            y = local_center + radius * math.sin(angle)
            points.append((x, y))
        
        # 별 색상 (은은한 형광 노란색)
        star_color = (255, 245, 200, alpha)
        if len(points) >= 3:
            pygame.draw.polygon(star_surface, star_color, points)
            
            # 테두리 (더 밝은 색)
            border_color = (255, 255, 230, int(alpha * 0.8))
            pygame.draw.polygon(star_surface, border_color, points, 2)
        
        # 중앙 반짝임
        sparkle_alpha = int(alpha * star['glow_intensity'])
        pygame.draw.circle(star_surface, (255, 255, 255, sparkle_alpha), (local_center, local_center), 3)
        
        # 화면에 그리기
        SCREEN.blit(star_surface, (center_x - local_center, center_y - local_center))

def update_trade_point_texts():
    """트레이드 포인트 텍스트 효과 업데이트"""
    global trade_point_texts
    new_texts = []
    
    for text_effect in trade_point_texts:
        # 수명 감소
        text_effect['life'] -= 1
        # 위로 이동
        text_effect['y'] -= 1.8
        # 페이드 아웃
        text_effect['alpha'] = min(255, text_effect['life'] * 3)
        # 스케일 애니메이션 (처음에 크게 나타났다가 작아짐)
        if text_effect['life'] > 70:
            text_effect['scale'] = 1.0 + (text_effect['life'] - 70) * 0.02
        else:
            text_effect['scale'] = 1.0
        
        # 수명이 남은 텍스트만 유지
        if text_effect['life'] > 0:
            new_texts.append(text_effect)
    
    trade_point_texts = new_texts

def draw_trade_point_texts():
    """트레이드 포인트 텍스트 효과 그리기 - 새로운 시스템에 포함됨"""
    # 새로운 시스템의 draw() 함수에서 이미 처리됨
    return
    
    # 아래는 기존 코드 (실행되지 않음)
    try:
        font = pygame.font.Font(get_pixel_font_path(), 20)
    except:
        font = pygame.font.Font(None, 20)

    for text_effect in trade_point_texts:
        if text_effect['alpha'] > 0:
            # 텍스트 렌더링
            text_surface = font.render(text_effect['text'], True, (255, 250, 200))
            
            # 스케일 적용
            if text_effect['scale'] != 1.0:
                scaled_size = (int(text_surface.get_width() * text_effect['scale']),
                              int(text_surface.get_height() * text_effect['scale']))
                text_surface = pygame.transform.scale(text_surface, scaled_size)
            
            # 투명도 적용
            text_surface.set_alpha(text_effect['alpha'])
            
            # 중앙 정렬로 그리기
            text_rect = text_surface.get_rect(center=(text_effect['x'], text_effect['y']))
            SCREEN.blit(text_surface, text_rect)

def update_stage3_hearts():
    """Stage 3 떨어지는 하트 업데이트 및 플레이어 충돌 체크"""
    global stage3_hearts, stage3_hearts_collected, stage3_trade_point_texts
    new_hearts = []
    for heart in stage3_hearts:
        # 물리 업데이트
        heart['x'] += heart['vx']
        heart['y'] += heart['vy']
        heart['vy'] += 0.15  # 중력 (잎사귀보다 약간 빠르게)
        heart['rotation'] += heart['rotation_speed']
        heart['life'] -= 1
        heart['sparkle_phase'] += 0.2  # 반짝임 애니메이션
        
        # 좌우 흔들림
        heart['x'] += math.sin(heart['y'] * 0.02 + heart['phase']) * 1.5
        
        # 플레이어 패들과 충돌 체크
        heart_rect = pygame.Rect(heart['x'] - heart['size'], heart['y'] - heart['size'],
                                 heart['size'] * 2, heart['size'] * 2)
        if heart_rect.colliderect(PLAYER) and heart['life'] > 0:
            # 트레이드 포인트용 카운터만 증가 (스킬 게이지는 증가하지 않음)
            stage3_hearts_collected += 1
            # print(f"  !   : {stage3_hearts_collected}")
            
            # Star Point +1 텍스트 효과 추가 (세련된 버전)
            stage3_trade_point_texts.append({
                'x': heart['x'],
                'y': heart['y'] - 20,  # 하트 위에 표시
                'text': '+1 Star Point',  # 깔끔한 텍스트
                'life': 75,  # 75프레임 (1.25초) 동안 표시
                'alpha': 255
            })
            
            # 획득 효과음
            try:
                coin_sound = pygame.mixer.Sound(resource_path("sounds/coin.wav"))
                play_sound_with_volume(coin_sound)
            except:
                pass
            heart['life'] = 0  # 하트 제거
            continue
        
        # 화면 안에 있고 수명이 남은 하트만 유지
        if heart['life'] > 0 and heart['y'] < HEIGHT + 50:
            new_hearts.append(heart)
    stage3_hearts = new_hearts

def update_stage3_trade_point_texts():
    """Stage 3 트레이드 포인트 텍스트 효과 업데이트"""
    global stage3_trade_point_texts
    new_texts = []
    for text_effect in stage3_trade_point_texts:
        # 수명 감소
        text_effect['life'] -= 1
        # 위로 이동
        text_effect['y'] -= 1.5
        # 페이드 아웃
        text_effect['alpha'] = min(255, text_effect['life'] * 4)
        
        # 수명이 남은 텍스트만 유지
        if text_effect['life'] > 0:
            new_texts.append(text_effect)
    stage3_trade_point_texts = new_texts

def draw_stage3_trade_point_texts():
    """Stage 3 트레이드 포인트 텍스트 효과 그리기 (세련된 미니멀 스타일)"""
    try:
        # 적당한 크기의 폰트
        font = pygame.font.Font(get_pixel_font_path(), 20)
        font_small = pygame.font.Font(get_pixel_font_path(), 18)  # 그림자용
    except:
        font = pygame.font.Font(None, 20)
        font_small = pygame.font.Font(None, 18)
    
    for text_effect in stage3_trade_point_texts:
        if text_effect['alpha'] > 0:
            # 부드러운 스케일 애니메이션 (처음에 크게 나타났다가 작아짐)
            if text_effect['life'] > 65:  # 처음 10프레임
                scale = 1.2 - (75 - text_effect['life']) * 0.02
            else:
                scale = 1.0
            
            # 그림자 효과 (은은한 검은색)
            shadow_surface = font_small.render(text_effect['text'], True, (0, 0, 0))
            shadow_surface = pygame.transform.scale(shadow_surface,
                (int(shadow_surface.get_width() * scale),
                 int(shadow_surface.get_height() * scale)))
            shadow_alpha = int(text_effect['alpha'] * 0.3)
            shadow_surface.set_alpha(shadow_alpha)
            
            # 메인 텍스트 (흰색으로 깔끔하게)
            text_surface = font.render(text_effect['text'], True, (255, 255, 255))
            text_surface = pygame.transform.scale(text_surface,
                (int(text_surface.get_width() * scale),
                 int(text_surface.get_height() * scale)))
            text_surface.set_alpha(text_effect['alpha'])
            
            # 하이라이트 효과 (은은한 노란빛)
            highlight_surface = font.render(text_effect['text'], True, (255, 245, 200))
            highlight_surface = pygame.transform.scale(highlight_surface,
                (int(highlight_surface.get_width() * scale),
                 int(highlight_surface.get_height() * scale)))
            highlight_alpha = int(text_effect['alpha'] * 0.4 * (0.7 + 0.3 * math.sin(text_effect['life'] * 0.15)))
            highlight_surface.set_alpha(highlight_alpha)
            
            # 화면에 그리기 (위로 부드럽게 떠오르는 효과)
            float_y = text_effect['y'] - (75 - text_effect['life']) * 0.8  # 더 부드럽게 떠오름
            
            # 그림자 (약간 아래 오른쪽에)
            shadow_rect = shadow_surface.get_rect(center=(text_effect['x'] + 2, float_y + 2))
            SCREEN.blit(shadow_surface, shadow_rect)
            
            # 메인 텍스트
            text_rect = text_surface.get_rect(center=(text_effect['x'], float_y))
            SCREEN.blit(text_surface, text_rect)
            
            # 하이라이트 오버레이
            SCREEN.blit(highlight_surface, text_rect)

def draw_stage3_hearts():
    """Stage 3 떨어지는 하트 그리기"""
    for heart in stage3_hearts:
        # 투명도 계산 (페이드 아웃 효과)
        alpha = min(255, heart['life'] * 2)
        
        # 반짝임 효과
        sparkle = abs(math.sin(heart['sparkle_phase'])) * 0.5 + 0.5
        
        # 하트 그리기 (회전 적용)
        heart_surface = pygame.Surface((heart['size'] * 4, heart['size'] * 4), pygame.SRCALPHA)
        center_x = heart['size'] * 2
        center_y = heart['size'] * 2
        
        # 회전된 하트 그리기 (각도를 라디안으로 변환)
        rotation_rad = math.radians(heart['rotation'])
        cos_r = math.cos(rotation_rad)
        sin_r = math.sin(rotation_rad)
        
        # 하트 색상 (붉은빛 강조)
        # 붉은색과 핑크를 혼합하여 더 선명하게
        red_intensity = 0.7 + 0.3 * sparkle  # 반짝임에 따라 붉은색 강도 변화
        base_color = (int(255 * red_intensity), 20, 60)  # 선명한 붉은색
        sparkle_color = tuple(min(255, int(c + (255 - c) * sparkle * 0.5)) for c in base_color)
        
        # 붉은빛 후광 효과
        glow_size = heart['size'] * 2
        glow_alpha = int(alpha * 0.3 * (0.5 + 0.5 * sparkle))  # 반짝임과 함께 후광도 변화
        glow_surface = pygame.Surface((glow_size * 2, glow_size * 2), pygame.SRCALPHA)
        # 3단계 후광 그리기
        pygame.draw.circle(glow_surface, (255, 0, 0, glow_alpha // 3), 
                         (glow_size, glow_size), glow_size)
        pygame.draw.circle(glow_surface, (255, 50, 50, glow_alpha // 2), 
                         (glow_size, glow_size), int(glow_size * 0.7))
        pygame.draw.circle(glow_surface, (255, 100, 100, glow_alpha), 
                         (glow_size, glow_size), int(glow_size * 0.4))
        heart_surface.blit(glow_surface, (center_x - glow_size, center_y - glow_size))
        
        # 하트 상단 (두 원)
        left_circle_x = center_x - heart['size'] * 0.3
        left_circle_y = center_y - heart['size'] * 0.3
        right_circle_x = center_x + heart['size'] * 0.3
        right_circle_y = center_y - heart['size'] * 0.3
        
        # 회전 적용
        def rotate_point(px, py, cx, cy):
            dx = px - cx
            dy = py - cy
            return (cx + dx * cos_r - dy * sin_r,
                   cy + dx * sin_r + dy * cos_r)
        
        # 하트 모양 그리기
        # 두 원
        left_rot = rotate_point(left_circle_x, left_circle_y, center_x, center_y)
        right_rot = rotate_point(right_circle_x, right_circle_y, center_x, center_y)
        
        pygame.draw.circle(heart_surface, (*sparkle_color, alpha), 
                         (int(left_rot[0]), int(left_rot[1])), heart['size'] // 2)
        pygame.draw.circle(heart_surface, (*sparkle_color, alpha),
                         (int(right_rot[0]), int(right_rot[1])), heart['size'] // 2)
        
        # 하트 하단 (삼각형)
        points = [
            rotate_point(center_x - heart['size'], center_y, center_x, center_y),
            rotate_point(center_x, center_y + heart['size'], center_x, center_y),
            rotate_point(center_x + heart['size'], center_y, center_x, center_y)
        ]
        pygame.draw.polygon(heart_surface, (*sparkle_color, alpha), points)
        
        # 반짝임 효과 (별 모양)
        if sparkle > 0.7:
            star_size = heart['size'] // 3
            star_points = []
            for i in range(8):
                angle = i * math.pi / 4
                if i % 2 == 0:
                    dist = star_size
                else:
                    dist = star_size // 2
                px = center_x + math.cos(angle) * dist
                py = center_y + math.sin(angle) * dist
                star_points.append(rotate_point(px, py, center_x, center_y))
            pygame.draw.polygon(heart_surface, (255, 255, 255, int(alpha * sparkle)), star_points)
        
        # 화면에 그리기
        SCREEN.blit(heart_surface, (heart['x'] - center_x, heart['y'] - center_y))

def draw_stage2_leaves():
    """떨어지는 잎사귀 그리기 (디테일한 버전)"""
    for leaf in stage2_leaves:
        # 투명도 계산 (페이드 아웃 효과)
        alpha = min(255, leaf['life'] * 2)
        # 잎사귀 그리기 (회전 적용)
        leaf_surface = pygame.Surface((leaf['size'] * 3, leaf['size'] * 3), pygame.SRCALPHA)
        center = leaf['size'] * 1.5
        # 잎사귀 종류별로 다른 모양 그리기 (항상 디테일한 버전만 사용)
        leaf_type = leaf.get('type', 'tropical')  # 기본값을 tropical로 설정
        if leaf_type == 'maple':
            # 단풍잎 모양 (5개 끝)
            points = []
            for i in range(10):
                angle = leaf['rotation'] + i * 36
                rad = math.radians(angle)
                if i % 2 == 0:
                    length = leaf['size']
                else:
                    length = leaf['size'] * 0.5
                points.append((center + math.cos(rad) * length,
                             center + math.sin(rad) * length))
            pygame.draw.polygon(leaf_surface, (*leaf['color'], alpha), points)
        elif leaf_type == 'oak':
            # 물결 모양 타원 (참나무잎)
            for i in range(3):
                offset = i * 2
                pygame.draw.ellipse(leaf_surface, (*leaf['color'], max(0, alpha - i * 50)),
                                  (center - leaf['size']//2 + offset, 
                                   center - leaf['size'] + offset,
                                   leaf['size'] - offset * 2, 
                                   leaf['size'] * 2 - offset * 2))
        else:  # tropical 또는 기타
            # 열대 잎 (뾰족한 타원)
            points = [
                (center, center - leaf['size'] * 1.2),
                (center + leaf['size'] * 0.4, center),
                (center, center + leaf['size'] * 1.2),
                (center - leaf['size'] * 0.4, center)
            ]
            pygame.draw.polygon(leaf_surface, (*leaf['color'], alpha), points)
        # 잎맥 추가
        vein_color = tuple(max(0, c - 40) for c in leaf['color']) + (alpha//2,)
        pygame.draw.line(leaf_surface, vein_color,
                        (center, center - leaf['size']), 
                        (center, center + leaf['size']), 1)
        # 회전 적용
        rotated_leaf = pygame.transform.rotate(leaf_surface, leaf['rotation'])
        leaf_rect = rotated_leaf.get_rect(center=(int(leaf['x']), int(leaf['y'])))
        SCREEN.blit(rotated_leaf, leaf_rect)
def draw_tutorial_practice_room():
    """튜토리얼 연습장 배경 그리기 - Stage 2 스타일 + 사이버펑크"""
    # 중심점 먼저 정의
    center_x = WIDTH // 2
    center_y = HEIGHT // 2
    
    # 그라데이션 파란색 배경
    for i in range(HEIGHT):
        # 위에서 아래로 점점 밝아지는 그라데이션
        gradient_ratio = i / HEIGHT
        color_r = int(15 + gradient_ratio * 10)  # 15-25
        color_g = int(35 + gradient_ratio * 15)  # 35-50
        color_b = int(75 + gradient_ratio * 20)  # 75-95
        pygame.draw.line(SCREEN, (color_r, color_g, color_b), (0, i), (WIDTH, i))
    
    # 사이버펑크 바닥 그리드 패턴
    grid_color = (30, 50, 90)  # 어두운 파란색
    grid_bright = (50, 80, 140)  # 밝은 파란색
    neon_color = (0, 200, 255)  # 네온 청록색
    
    # 원근감을 위한 그리드 라인 (아래쪽이 더 넓게)
    grid_spacing = 40
    
    # 가로 그리드 라인 (원근감 적용)
    for i in range(15):
        y = HEIGHT - 100 - i * (grid_spacing - i * 2)  # 위로 갈수록 좁아짐
        if y > HEIGHT // 2:  # 중앙선 아래만
            alpha = int(100 - i * 5)  # 위로 갈수록 투명
            if alpha > 0:
                # 그리드 라인
                grid_surface = pygame.Surface((WIDTH, 2), pygame.SRCALPHA)
                grid_surface.fill((*grid_color, alpha))
                SCREEN.blit(grid_surface, (0, y))
                
                # 가끔 네온 효과
                if i % 3 == 0:
                    neon_surface = pygame.Surface((WIDTH, 1), pygame.SRCALPHA)
                    neon_surface.fill((*neon_color, alpha // 2))
                    SCREEN.blit(neon_surface, (0, y))
    
    # 세로 그리드 라인 (원근감)
    for i in range(-10, 11):
        x = center_x + i * grid_spacing
        # 중앙에서 멀수록 기울어짐
        start_x = x + i * 15
        end_x = x
        
        if 0 <= x <= WIDTH:
            # 그리드 라인
            pygame.draw.line(SCREEN, grid_color, 
                           (start_x, HEIGHT), 
                           (end_x, HEIGHT // 2), 1)
            
            # 가끔 네온 하이라이트
            if abs(i) % 4 == 0:
                neon_surface = pygame.Surface((2, HEIGHT // 2), pygame.SRCALPHA)
                for j in range(HEIGHT // 2):
                    alpha = int(50 * (j / (HEIGHT // 2)))
                    if alpha > 0:
                        neon_surface.set_at((0, j), (*neon_color, alpha))
                # 계산된 위치에 블릿
                line_x = start_x + (end_x - start_x) * j // (HEIGHT // 2)
                if 0 <= line_x < WIDTH:
                    SCREEN.blit(neon_surface, (line_x, HEIGHT // 2))
    
    # 사이버펑크 스캔라인 효과
    for y in range(0, HEIGHT, 4):
        scanline_surface = pygame.Surface((WIDTH, 1), pygame.SRCALPHA)
        scanline_surface.fill((0, 0, 0, 20))
        SCREEN.blit(scanline_surface, (0, y))
    
    # 스타디움 스타일 코트 라인 (은은한 색상)
    line_color = (150, 170, 200)  # 은은한 회청색
    line_width = 3
    
    # 중앙 원 (Stage 2처럼 하나의 원만)
    circle_radius = 80
    
    # 중앙 가로선 (원 밖에만 그리기)
    # 왼쪽 부분 (원 왼쪽까지)
    pygame.draw.line(SCREEN, line_color, 
                    (0, center_y), 
                    (center_x - circle_radius, center_y), 
                    line_width)
    
    # 오른쪽 부분 (원 오른쪽부터)
    pygame.draw.line(SCREEN, line_color, 
                    (center_x + circle_radius, center_y), 
                    (WIDTH, center_y), 
                    line_width)
    
    # 중앙 원 그리기 (네온 효과 추가)
    # 외부 글로우
    for i in range(5):
        glow_radius = circle_radius + i * 2
        glow_alpha = 30 - i * 5
        glow_surface = pygame.Surface((glow_radius * 2 + 10, glow_radius * 2 + 10), pygame.SRCALPHA)
        pygame.draw.circle(glow_surface, (*neon_color, glow_alpha), 
                         (glow_radius + 5, glow_radius + 5), glow_radius, 1)
        SCREEN.blit(glow_surface, (center_x - glow_radius - 5, center_y - glow_radius - 5))
    
    # 메인 원
    pygame.draw.circle(SCREEN, line_color, (center_x, center_y), circle_radius, line_width)

# ============================================================
# 단청 패턴 사전 렌더링 캐싱 (Stage 1 최적화)
# ============================================================
_danjeong_surface = None  # 단청 패턴 캐시
_danjeong_size = None     # 캐시된 크기

def _get_danjeong_surface(width, height):
    """단청 패턴 서피스를 캐싱하여 반환 (매 프레임 그리기 방지)"""
    global _danjeong_surface, _danjeong_size

    if _danjeong_surface is None or _danjeong_size != (width, height):
        _danjeong_surface = pygame.Surface((width, height), pygame.SRCALPHA)
        _danjeong_size = (width, height)

        border_x = 0
        border_width = width
        # 외곽선 (진한 갈색)
        pygame.draw.rect(_danjeong_surface, (101, 67, 33), (border_x, 0, border_width, height), 8)
        # 단청 패턴을 위한 내부 장식
        # 상단 단청 패턴
        pygame.draw.rect(_danjeong_surface, (220, 50, 50), (border_x + 8, 4, border_width - 16, 2), 0)  # 빨강
        pygame.draw.rect(_danjeong_surface, (255, 215, 0), (border_x + 8, 6, border_width - 16, 2), 0)  # 노랑
        # 하단 단청 패턴
        pygame.draw.rect(_danjeong_surface, (50, 50, 220), (border_x + 8, height - 6, border_width - 16, 2), 0)  # 파랑
        pygame.draw.rect(_danjeong_surface, (50, 180, 50), (border_x + 8, height - 8, border_width - 16, 2), 0)  # 초록
        # 좌측 단청 패턴
        pygame.draw.rect(_danjeong_surface, (220, 50, 50), (border_x + 4, 8, 2, height - 16), 0)  # 빨강
        pygame.draw.rect(_danjeong_surface, (255, 215, 0), (border_x + 6, 8, 2, height - 16), 0)  # 노랑
        # 우측 단청 패턴
        pygame.draw.rect(_danjeong_surface, (50, 50, 220), (border_x + border_width - 6, 8, 2, height - 16), 0)  # 파랑
        pygame.draw.rect(_danjeong_surface, (50, 180, 50), (border_x + border_width - 8, 8, 2, height - 16), 0)  # 초록

    return _danjeong_surface

def draw_field():
    global psycho_bg_timer, earthquake_offset_x, earthquake_offset_y
    global special_gauge, gauge_charge_animation_timer, gauge_charge_animation_amount, special_ready
    global alice_mirror_bg_timer

    # 필러 배경 타입 설정 (전체화면/창모드 모두, 실제 그리기는 _fullscreen_flip에서)
    if _is_fullscreen_active and pillar_renderer is not None:
        # 스테이지 진입 시 동적 배경으로 전환
        if current_stage > 0 and current_stage < 50:
            pillar_renderer.set_type('dynamic')
            # 온라인 멀티(stage 40): 필러가 없으므로 스테이지 1 필러 사용
            _pillar_stage = 1 if current_stage == 40 else current_stage
            pillar_renderer.set_stage(_pillar_stage)
        else:
            pillar_renderer.set_type('artwork')
        # 스테이지 1: 나비 흡수 이벤트용 플레이어 위치 전달 (update 전에 호출해야 함)
        if current_stage == 1:
            pillar_renderer.set_player_rect(PLAYER)
        pillar_renderer.update(1/60, is_waiting_for_serve)  # 애니메이션 업데이트 (서브 대기 중 뱀 공격 방지)
        # 스테이지 1: 나비 흡수로 인한 게이지 회복 처리
        if current_stage == 1 and pillar_renderer.check_butterfly_gauge_recovery():
            # 나비가 플레이어에게 흡수됨 - 게이지 200 회복
            current_max = get_max_gauge()
            old_gauge = special_gauge
            special_gauge = min(current_max, special_gauge + 200)
            actual_gain = special_gauge - old_gauge
            if actual_gain > 0:
                # 게이지 회복 애니메이션 트리거
                gauge_charge_animation_timer = 30  # 0.5초간 표시
                gauge_charge_animation_amount = actual_gain
                # 효과음 재생
                try:
                    play_sound_with_volume(SOUND_ITEM_GET)
                except:
                    pass
                # 게이지가 350 이상이면 special_ready 활성화
                if special_gauge >= 350:
                    special_ready = True
        # 스테이지 7: 보스 위치 포함 업데이트 (크리스탈 실드용)
        # REAL_SCREEN 좌표계로 변환 (게임 영역 오프셋 + 스케일링 고려)
        if current_stage == 7:
            # 스케일링을 고려한 보스 중심 좌표 계산
            scaled_boss_cx = (BOSS.x + BOSS.width // 2) * GAME_SCALE_FACTOR
            scaled_boss_cy = (BOSS.y + BOSS.height // 2) * GAME_SCALE_FACTOR
            # 기본 오프셋 적용
            boss_cx = scaled_boss_cx + GAME_OFFSET_X
            boss_cy = scaled_boss_cy + GAME_OFFSET_Y
            # 스케일링 시 추가 오프셋 적용 (게임 화면이 스케일 영역 내에서 중앙 정렬됨)
            if GAME_SCALE_FACTOR != 1.0:
                sw = int(WIDTH * GAME_SCALE_FACTOR)
                sh = int(HEIGHT * GAME_SCALE_FACTOR)
                additional_offset_x = (GAME_SCALED_WIDTH - sw) // 2
                additional_offset_y = (GAME_SCALED_HEIGHT - sh) // 2
                boss_cx += additional_offset_x
                boss_cy += additional_offset_y
            pillar_renderer.update_tetriser_with_boss(1/60, boss_cx, boss_cy)
        # 스테이지 2: 원숭이-바나나 이벤트용 플레이어/보스 위치 및 대쉬 방향 전달
        if current_stage == 2:
            pillar_renderer.set_player_rect(PLAYER)
            pillar_renderer.set_boss_rect(BOSS)
            # 대쉬 중이면 대쉬 방향 전달
            if rolling_active:
                pillar_renderer.set_player_dash_dir(rolling_direction)
            else:
                pillar_renderer.set_player_dash_dir(0)

        # 스테이지 5(코드=실제6 홍련): 광폭화 뱀 공격용 플레이어 위치 전달
        if current_stage == 5 and enraged_boss_active:
            # 내부 좌표 (게임 로직용)
            internal_cx = PLAYER.x + PLAYER.width // 2
            internal_cy = PLAYER.y + PLAYER.height // 2

            # REAL_SCREEN 좌표 (시각적 조준용)
            real_cx = int(internal_cx * GAME_SCALE_FACTOR) + GAME_OFFSET_X
            real_cy = int(internal_cy * GAME_SCALE_FACTOR) + GAME_OFFSET_Y
            if GAME_SCALE_FACTOR != 1.0:
                sw = int(WIDTH * GAME_SCALE_FACTOR)
                sh = int(HEIGHT * GAME_SCALE_FACTOR)
                additional_offset_x = (GAME_SCALED_WIDTH - sw) // 2
                additional_offset_y = (GAME_SCALED_HEIGHT - sh) // 2
                real_cx += additional_offset_x
                real_cy += additional_offset_y

            pillar_renderer.update_hongryeon_player_position(
                real_cx, real_cy,
                internal_x=int(internal_cx), internal_y=int(internal_cy)
            )

    # Stage 50 (튜토리얼) - 연습장 배경
    if current_stage == 50:
        draw_tutorial_practice_room()
        return
    
    if current_stage == 3 and alice_mirror_active and current_boss_name == "앨리스":
        # 거울 세계 궁극기 배경: 몽환적 반전 세계
        alice_mirror_bg_timer += 1
        t = alice_mirror_bg_timer
        # 시안/보라 계열 색상이 물결치듯 변화
        r = max(0, min(255, int(40 + 30 * math.sin(t * 0.03))))
        g = max(0, min(255, int(20 + 40 * math.sin(t * 0.05 + 1.0))))
        b = max(0, min(255, int(80 + 60 * math.sin(t * 0.04 + 2.0))))
        SCREEN.fill((r, g, b))
        # 거울 파편이 떠다니는 효과
        mirror_surf = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
        for i in range(8):
            shard_x = int((WIDTH // 2) + 250 * math.sin(t * 0.02 + i * 0.8))
            shard_y = int((HEIGHT // 2) + 200 * math.cos(t * 0.025 + i * 1.1))
            shard_size = int(20 + 15 * math.sin(t * 0.03 + i))
            shard_alpha = int(40 + 30 * math.sin(t * 0.04 + i * 0.5))
            # 다이아몬드 형태 거울 파편
            points = [
                (shard_x, shard_y - shard_size),
                (shard_x + shard_size // 2, shard_y),
                (shard_x, shard_y + shard_size),
                (shard_x - shard_size // 2, shard_y),
            ]
            pygame.draw.polygon(mirror_surf, (180, 220, 255, shard_alpha), points)
            pygame.draw.polygon(mirror_surf, (220, 240, 255, shard_alpha + 20), points, 2)
        # 화면 중앙에서 퍼져나가는 동심원 (거울 파동)
        for ring in range(3):
            ring_radius = int((t * 1.5 + ring * 100) % 400)
            ring_alpha = max(0, 60 - ring_radius // 5)
            if ring_alpha > 0:
                pygame.draw.circle(mirror_surf, (150, 200, 255, ring_alpha),
                                   (WIDTH // 2, HEIGHT // 2), ring_radius, 2)
        SCREEN.blit(mirror_surf, (0, 0))
    elif current_stage == 3 and emotional_overdrive_active:
        # 깜빡이거나 색 바뀌는 배경
        psycho_bg_timer += 1
        if psycho_bg_timer % 35 < 15:
            # 밝은 보라색 계열
            SCREEN.fill((255, 100, 255))
        else:
            # 어두운 남보라 계열
            SCREEN.fill((100, 0, 150))
        # 또는 완전 무작위 컬러 배경 효과 (좀 더 강한 사이코 느낌)
        # random_color = (random.randint(100,255), random.randint(0,100), random.randint(100,255))
        # SCREEN.fill(random_color)
    elif current_stage == 1 and animated_bg is not None:
        # Stage 2가 아니면 지진 오프셋 초기화
        earthquake_offset_x = 0
        earthquake_offset_y = 0
        # 스테이지1에서는 애니메이션 배경 사용
        animated_bg.update(clock.get_time())
        # 배경을 화면에 직접 그리기 (패럴랙스 오프셋 적용)
        animated_bg.draw(SCREEN)

        # Stage 1 필드 중앙 태극문양에 회색 테두리 추가 (백업 이미지와 동일)
        taegeuk_center_x = WIDTH // 2
        taegeuk_center_y = HEIGHT // 2
        taegeuk_radius = 80  # 태극문양 크기
        # 밝은 회색 테두리 (백업 이미지 분석 결과)
        pygame.draw.circle(SCREEN, (200, 200, 200), (taegeuk_center_x, taegeuk_center_y), taegeuk_radius + 2, 4)

        # Stage 1 필드 전체에 8픽셀 단청 스타일 테두리 추가 (캐싱된 서피스 사용)
        danjeong = _get_danjeong_surface(WIDTH, HEIGHT)
        SCREEN.blit(danjeong, (0, 0))
        # 스테이지 1: 필러에서 날아오는 나비를 게임 화면에 그리기
        if pillar_renderer is not None:
            pillar_renderer.draw_butterfly_ingame(SCREEN, WIDTH, HEIGHT)
    elif current_stage == 2 and animated_bg_stage2 is not None:
        # 스테이지2에서는 정글 사이버펑크 애니메이션 배경 사용
        # 공 위치, 패들 위치, 점수를 배경에 전달 (눈동자 추적 + 덤불 흔들림 + 위기 상황용)
        # 두더지왕/아라크네는 바위 낙석 이벤트 없음 (악어장군 전용) → 점수 전달 안 함
        if current_boss_name in ("두더지왕", "아라크네"):
            animated_bg_stage2.update(clock.get_time(), BALL.centerx, BALL.centery,
                                    BOSS.centerx, PLAYER.centerx, None, None)
        else:
            animated_bg_stage2.update(clock.get_time(), BALL.centerx, BALL.centery,
                                    BOSS.centerx, PLAYER.centerx, round_wins, round_losses)
        # 직접 SCREEN에 그리기 (패럴랙스 오프셋 적용)
        animated_bg_stage2.draw(SCREEN)
        # Stage 2 물대포 및 파편 렌더링
        draw_water_cannon_target_highlight(SCREEN)
        draw_water_cannon_charging(SCREEN)
        draw_water_cannon(SCREEN)
        draw_water_cannon_fragment_danger_glow(SCREEN)
        draw_water_cannon_fragments(SCREEN)
        draw_fragment_hit_effect(SCREEN)
        # Stage 2 두더지왕 땅굴 습격 이펙트 렌더링
        draw_tunnel_raid_effects(SCREEN)
        draw_spinning_claw_effects(SCREEN)
        # Stage 2 두더지왕 친구두더지 렌더링
        draw_friend_moles(SCREEN)
        # Stage 2 아라크네 거미줄 장판 렌더링
        draw_web_traps(SCREEN)
        draw_web_rescue(SCREEN)
        draw_spider_rage_projectiles(SCREEN)
        # 원숭이가 던진 바나나를 인게임 화면에 그리기
        if pillar_renderer is not None:
            pillar_renderer.draw_bananas_ingame(SCREEN)
    elif current_stage == 3 and animated_bg_stage3 is not None and not emotional_overdrive_active and not (alice_mirror_active and current_boss_name == "앨리스"):
        # Stage 2가 아니면 지진 오프셋 초기화
        earthquake_offset_x = 0
        earthquake_offset_y = 0
        # 스테이지3에서는 멘헤라 월드 맵 사용 (감정 폭주 시 제외)
        # 라운드 정보 전달 (라운드 승리 + 패배)
        animated_bg_stage3.update(clock.get_time(), round_wins + round_losses)
        animated_bg_stage3.draw(SCREEN, ball_pos=(BALL.centerx, BALL.centery))

        # 씹는 이펙트 그리기
        if kuromi_eating_active and animated_bg_stage3:
            animated_bg_stage3.draw_chewing_effects(SCREEN)
    elif current_stage == 4 and animated_bg_stage4 is not None:
        # 스테이지4에서는 소림사 사원 애니메이션 배경 사용
        # Calculate dt for performance monitoring
        dt = clock.get_time() / 1000.0 if 'clock' in globals() else 0.016
        animated_bg_stage4.update(dt)  # Pass dt for FPS detection
        animated_bg_stage4.draw(SCREEN)
    elif current_stage == 5 and animated_bg_stage5 is not None:
        # 스테이지5에서는 중국 전통시장 화염 맵 사용
        animated_bg_stage5.update(clock.get_time())
        animated_bg_stage5.draw(SCREEN)
    elif current_stage == 6 and animated_bg_stage6 is not None:
        # 스테이지6에서는 언더워터 사이버펑크 스타디움 애니메이션 배경 사용
        animated_bg_stage6.update()
        animated_bg_stage6.draw(SCREEN)
    elif current_stage == 7 and animated_bg_stage7 is not None:
        valthor_perf_start("stage7_bg_update")
        elapsed_ms = clock.get_time() if 'clock' in globals() else 16
        # 공 좌표를 전달해 중앙 링 진입 이벤트를 감지하고 면 채움/진동/폭발을 진행
        try:
            if 'BALL' in globals() and BALL is not None:
                animated_bg_stage7.update_ball(BALL.centerx, BALL.centery)
                # 히트 이벤트 처리: 타격 이펙트 + 사운드 + 0.5s 진동은 배경 내부에서 처리됨
                hit_pos = animated_bg_stage7.pop_hit_event()
                if hit_pos is not None:
                    # 타격 이펙트: 공 속도 벡터 사용해 강도 자동 결정
                    try:
                        create_impact_effect(BALL.centerx, BALL.centery, ball_vel, is_player=False)
                    except Exception:
                        # 폴백: 이펙트 매니저 간단 이펙트 사용
                        try:
                            effects_manager.create_impact_effect(hit_pos[0], hit_pos[1], 32, is_player=False)
                        except Exception:
                            pass
                    # 효과음: 방어 피격 SFX 재사용(조용한 짧은 타격음)
                    try:
                        play_sound_with_volume(SOUND_DEFENSE_HIT)
                    except Exception:
                        pass
        except Exception:
            pass
        animated_bg_stage7.update(elapsed_ms)
        valthor_perf_end("stage7_bg_update")
        valthor_perf_start("stage7_bg_draw")
        SCREEN.blit(STAGE7_BG, (screen_shake_offset_x, screen_shake_offset_y))
        animated_bg_stage7.draw(
            SCREEN,
            offset=(screen_shake_offset_x, screen_shake_offset_y),
        )
        valthor_perf_end("stage7_bg_draw")
        # 폭발 요청이 발생한 프레임에 테트로미노 일괄 해체 및 폭발 이펙트 실행
        try:
            if animated_bg_stage7.pop_explosion_request():
                stage7_center_cube_explode_and_clear_tetros()
        except Exception:
            pass
    elif current_stage == 8 and animated_bg_stage8 is not None:
        # 스테이지8: 닌자 저택 애니메이션 배경
        elapsed_ms = clock.get_time() if 'clock' in globals() else 16
        animated_bg_stage8.update(elapsed_ms)
        SCREEN.blit(STAGE8_BG, (screen_shake_offset_x, screen_shake_offset_y))
        animated_bg_stage8.draw(
            SCREEN,
            offset=(screen_shake_offset_x, screen_shake_offset_y),
        )
    elif current_stage == 30 and animated_bg_stage30 is not None:
        # 스테이지30: 투기장 (콜로세움) 애니메이션 배경 - 배속 연동
        elapsed_ms = clock.get_time() if 'clock' in globals() else 16
        dt = (elapsed_ms / 1000.0) * arena_speed_multiplier
        # 라운드 전환(공 서브 애니메이션) 또는 포획 페이즈 중에는 신의심판 타이머 동결
        animated_bg_stage30.judgment_logic_paused = (
            is_ball_spawn_animation_paused()
            or arena_capture_phase is not None
        )
        animated_bg_stage30.update(dt)
        animated_bg_stage30.draw(
            SCREEN,
            offset_x=screen_shake_offset_x,
            offset_y=screen_shake_offset_y,
        )
    else:
        # 기본 배경 (화면 흔들림 오프셋 적용)
        SCREEN.blit(CURRENT_BG, (screen_shake_offset_x, screen_shake_offset_y))
    #  체력형 보스전 바리케이트 그리기 (스테이지 11, 16, 21)
    if current_stage in boss_health_stages:
        global stage6_barrier_flash_timer
        barrier_height = 8
        barrier_y = 0

        # 바리케이트 기본 색상 (전기 청색)
        barrier_color = (50, 150, 255)

        # 애니메이션 효과 (깜빡임)
        time_now = pygame.time.get_ticks()
        pulse = abs(math.sin(time_now * 0.01)) * 0.5 + 0.5
        # 메인 바리케이트 바
        for i in range(0, WIDTH, 20):
            bar_width = 15
            bar_alpha = int(DEFAULT_ALPHA + pulse * 105)  # DEFAULT_ALPHA-255 사이에서 변동
            # 바리케이트 그라데이션 효과
            for y_offset in range(barrier_height):
                intensity = 1.0 - (y_offset / barrier_height) * 0.6
                color = (
                    int(barrier_color[0] * intensity),
                    int(barrier_color[1] * intensity),
                    int(barrier_color[2] * intensity)
                )
                pygame.draw.rect(SCREEN, color, (i, barrier_y + y_offset, bar_width, 1))
            # 전기 스파크 효과 (랜덤)
            if random.random() < 0.1:
                spark_x = i + random.randint(0, bar_width)
                spark_y = barrier_y + random.randint(0, barrier_height)
                draw.circle(WHITE, (spark_x, spark_y), 1)
        # 바리케이트 경고 텍스트 (중앙에 작게)
        font_barrier = get_font(12)  # 12pt 픽셀 폰트
        barrier_text = font_barrier.render(" ENERGY BARRIER ", True, WHITE)
        text_rect = barrier_text.get_rect(center=(WIDTH // 2, barrier_height + 15))
        # 텍스트 그림자
        shadow_text = font_barrier.render(" ENERGY BARRIER ", True, BLACK)
        SCREEN.blit(shadow_text, (text_rect.x + 1, text_rect.y + 1))
        SCREEN.blit(barrier_text, text_rect)

    # 스테이지 6 (네메시스) 전용 방어막 시스템 렌더링 - 비활성화됨
    if False and current_stage == 6:  # 방어막 시스템 비활성화
        time_now = pygame.time.get_ticks()
        barrier_height = 10
        barrier_y = 0

        # 방어막 타이머 체크 - 현재 적용된 시간 지나면 다시 활성화 (2.5초 또는 3.3초)
        if not nemesis_barrier_active:
            elapsed = time_now - nemesis_barrier_disabled_time
            if elapsed >= nemesis_barrier_current_duration:
                globals()['nemesis_barrier_active'] = True
                # 방어막 재활성화 시 경고 사운드 중지
                global nemesis_barrier_warning_channel
                if nemesis_barrier_warning_channel:
                    nemesis_barrier_warning_channel.stop()
                    nemesis_barrier_warning_channel = None
                pass  # print(f"🛡️ [네메시스] 방어막 재활성화!")  # 디버그 비활성화
            else:
                # 방어막 비활성화 중 - 빨간색 경고 깜빡임
                remaining = (nemesis_barrier_current_duration - elapsed) / 1000.0
                flash_speed = 0.1  # 빠른 깜빡임
                if int(time_now * flash_speed) % 2 == 0:
                    # 얇은 빨간색 경고선
                    for i in range(0, WIDTH, 4):
                        pygame.draw.rect(SCREEN, (255, 50, 50), (i, barrier_y, 2, 3))
                # 경고 텍스트 표시
                font_warning = get_font(14)
                warning_text = font_warning.render(f"⚠ BARRIER DOWN - {remaining:.1f}s ⚠", True, (255, 100, 100))
                text_rect = warning_text.get_rect(center=(WIDTH // 2, barrier_height + 12))
                SCREEN.blit(warning_text, text_rect)
        else:
            # 방어막 활성화 중
            global nemesis_barrier_rainbow_active, nemesis_barrier_rainbow_start_time
            global nemesis_barrier_rainbow_cooldown, nemesis_barrier_rainbow_hit

            # 무지개 모드 타이머 체크 및 활성화
            if not nemesis_barrier_rainbow_active:
                # 쿨타임 체크 - 쿨타임이 지나면 무지개 모드 활성화
                if nemesis_barrier_rainbow_cooldown > 0:
                    nemesis_barrier_rainbow_cooldown -= 16  # 약 60fps 기준 프레임당 감소
                else:
                    # 무지개 모드 시작!
                    nemesis_barrier_rainbow_active = True
                    nemesis_barrier_rainbow_start_time = time_now
                    nemesis_barrier_rainbow_hit = False
                    pass  # print(f"🌈 [네메시스] 무지개 모드 활성화! (1초간 공에 맞으면 스타포인트 드랍)")  # 디버그 비활성화
            else:
                # 무지개 모드 지속 시간 체크
                rainbow_elapsed = time_now - nemesis_barrier_rainbow_start_time
                if rainbow_elapsed >= NEMESIS_BARRIER_RAINBOW_DURATION:
                    # 무지개 모드 종료
                    nemesis_barrier_rainbow_active = False
                    # 다음 쿨타임 설정 (10~40초)
                    nemesis_barrier_rainbow_cooldown = random.randint(NEMESIS_BARRIER_RAINBOW_COOLDOWN_MIN, NEMESIS_BARRIER_RAINBOW_COOLDOWN_MAX)
                    pass  # print(f"🌈 [네메시스] 무지개 모드 종료! (다음까지 {nemesis_barrier_rainbow_cooldown/1000:.1f}초)")  # 디버그 비활성화

            pulse = abs(math.sin(time_now * 0.008)) * 0.5 + 0.5

            # 메인 방어막 바
            for i in range(0, WIDTH, 16):
                bar_width = 12
                # 방어막 그라데이션 효과
                for y_offset in range(barrier_height):
                    intensity = 1.0 - (y_offset / barrier_height) * 0.5
                    glow = pulse * 0.3 + 0.7

                    if nemesis_barrier_rainbow_active:
                        # 무지개 모드 - 화려한 무지개색
                        # 위치와 시간에 따라 색상 변화 (더 빠르고 화려하게)
                        hue_offset = (i / WIDTH + time_now * 0.003) % 1.0
                        # HSV to RGB 변환 (간단한 버전)
                        h = hue_offset * 6.0
                        x_val = 1 - abs(h % 2 - 1)
                        if h < 1:
                            r, g, b = 1.0, x_val, 0
                        elif h < 2:
                            r, g, b = x_val, 1.0, 0
                        elif h < 3:
                            r, g, b = 0, 1.0, x_val
                        elif h < 4:
                            r, g, b = 0, x_val, 1.0
                        elif h < 5:
                            r, g, b = x_val, 0, 1.0
                        else:
                            r, g, b = 1.0, 0, x_val
                        color = (
                            int(r * 255 * intensity * glow),
                            int(g * 255 * intensity * glow),
                            int(b * 255 * intensity * glow)
                        )
                    else:
                        # 일반 모드 - 청록색 에너지 장벽
                        color = (
                            int(50 * intensity * glow),
                            int(200 * intensity * glow),
                            int(255 * intensity * glow)
                        )
                    pygame.draw.rect(SCREEN, color, (i, barrier_y + y_offset, bar_width, 1))
                # 전기 스파크 효과
                if random.random() < 0.15:
                    spark_x = i + random.randint(0, bar_width)
                    spark_y = barrier_y + random.randint(0, barrier_height)
                    if nemesis_barrier_rainbow_active:
                        # 무지개 모드 스파크 - 다양한 색상
                        spark_color = random.choice([(255, 100, 100), (100, 255, 100), (100, 100, 255), (255, 255, 100), (255, 100, 255), (100, 255, 255)])
                    else:
                        spark_color = (100, 255, 255) if random.random() > 0.5 else (255, 255, 255)
                    draw.circle(spark_color, (spark_x, spark_y), 1)

            # 방어막 상태 텍스트
            font_barrier = get_font(11)
            if nemesis_barrier_rainbow_active:
                # 무지개 모드 텍스트 - 깜빡이는 효과
                rainbow_text_colors = [(255, 100, 100), (255, 200, 100), (255, 255, 100), (100, 255, 100), (100, 200, 255), (200, 100, 255)]
                text_color = rainbow_text_colors[int(time_now * 0.01) % len(rainbow_text_colors)]
                barrier_text = font_barrier.render("★ RAINBOW CHANCE! ★", True, text_color)
                text_rect = barrier_text.get_rect(center=(WIDTH // 2, barrier_height + 12))
                shadow_text = font_barrier.render("★ RAINBOW CHANCE! ★", True, (50, 50, 50))
            else:
                barrier_text = font_barrier.render("◆ NEMESIS BARRIER ◆", True, (100, 220, 255))
                text_rect = barrier_text.get_rect(center=(WIDTH // 2, barrier_height + 12))
                shadow_text = font_barrier.render("◆ NEMESIS BARRIER ◆", True, (0, 50, 100))
            SCREEN.blit(shadow_text, (text_rect.x + 1, text_rect.y + 1))
            SCREEN.blit(barrier_text, text_rect)
def check_deuce_system():
    """핑파이터 스타일 듀스 시스템을 체크하고 업데이트합니다."""
    global deuce_mode, deuce_wins, deuce_losses, deuce_goal
    global balloon_event_delay, balloon_event_reserved_score  #  풍선 이벤트 변수 추가
    global fire_event_delay, fire_event_reserved_score  #  화염 이벤트 변수 추가
    # 듀스 조건: 4:4 동점
    if round_wins == 4 and round_losses == 4 and not deuce_mode:
        deuce_mode = True
        deuce_wins = 4  # 4:4 상태를 유지
        deuce_losses = 4  # 4:4 상태를 유지
        deuce_goal = 6  # 첫 번째 듀스는 6점
        show_fade_text("DEUCE!")
        # print("듀스!")
        return "deuce_started"
    # 듀스 모드에서 5:5 동점이 되면 듀스 재시작 (7점으로)
    if deuce_mode and deuce_wins == 5 and deuce_losses == 5:
        deuce_wins = 5  # 5:5 상태를 유지
        deuce_losses = 5  # 5:5 상태를 유지
        deuce_goal = 7  # 두 번째 듀스는 7점 (최대 점수)
        show_fade_text("DEUCE!")
        # print("듀스! (7점 목표)")
        #  Stage 1 풍선 이벤트 - 듀스 재시작 시 3점 트리거 리셋 및 예약 취소
        if current_stage == 1 and BALLOON_EVENT_AVAILABLE and stage1_events:
            stage1_events.reset_for_deuce()
            # 예약된 이벤트도 취소해야 함!
            if balloon_event_delay > 0:
                balloon_event_delay = 0
                balloon_event_reserved_score = 0
                # print("-")
            # print("-   3")
        
        #  Stage 5 화염 이벤트 - 듀스 재시작 시 리셋 (타이머는 계속 진행)
        if current_stage == 5 and FIRE_EVENT_AVAILABLE and stage5_events:
            stage5_events.reset_for_deuce()
            # print("-    (  )")
        return "deuce_restart"
    
    # 6:6이 되어도 듀스 없음 - 7점 먼저 내면 승리
    # (추가적인 듀스 체크 없음)
    # 듀스 모드에서 승리 조건 체크
    if deuce_mode:
        if deuce_wins >= deuce_goal:
            # 승부 결과 기록 (듀스)
            record_victory_result(deuce_wins, deuce_losses)
            return "player_win"
        elif deuce_losses >= deuce_goal:
            # 듀스 패배 결과 기록 (감점)
            record_victory_result(deuce_wins, deuce_losses)
            return "boss_win"
    # 일반 모드에서 승리 조건 체크
    else:
        if round_wins >= win_goal:
            # 승부 결과 기록 (일반)
            record_victory_result(round_wins, round_losses)
            return "player_win"
        elif round_losses >= win_goal:
            # 패배 결과 기록 (감점)
            record_victory_result(round_wins, round_losses)
            return "boss_win"
    return "continue"
def draw_score():
    global perfect_victory_bonus_timer, victory_bonus_type
    global chapter4_power_helper_timer, chapter4_serve_reminder_timer, chapter4_serve_reminder_active
    
    # Chapter 4 서브 알림 표시 (대화 완료 후 1.5초간)
    if current_stage == 50 and chapter4_serve_reminder_active and chapter4_serve_reminder_timer > 0:
        chapter4_serve_reminder_timer -= 1
        
        # 알림이 끝나면 비활성화
        if chapter4_serve_reminder_timer == 0:
            chapter4_serve_reminder_active = False
        
        # 서브 알림 UI 그리기 (서브 도우미와 동일한 스타일)
        try:
            font_large = get_font(24)
        except:
            font_large = pygame.font.Font(None, 30)
        
        main_text = "세 방향으로 한번씩 파워스매싱을 날려보세요!"
        box_width = 800
        box_height = 60
        box_x = (WIDTH - box_width) // 2
        box_y = HEIGHT // 2 + 100  # 화면 중앙 아래쪽
        
        # 박스 배경 (반투명 - 스크린샷과 동일한 스타일)
        box_surface = pygame.Surface((box_width, box_height), pygame.SRCALPHA)
        box_surface.fill((20, 20, 40, 220))  # 반투명 어두운 파란색 배경
        pygame.draw.rect(box_surface, CYAN, (0, 0, box_width, box_height), 3)  # 청록색 테두리
        SCREEN.blit(box_surface, (box_x, box_y))
        
        # 메인 텍스트
        main_surface = font_large.render(main_text, True, CYAN)
        main_rect = main_surface.get_rect(center=(box_x + box_width // 2, box_y + box_height // 2))
        SCREEN.blit(main_surface, main_rect)
    
    # Chapter 4 파워스매싱 도우미 표시
    if current_stage == 50 and chapter4_power_helper_timer > 0:
        chapter4_power_helper_timer -= 1
        
        # 도우미 폰트 설정
        try:
            helper_font = get_font(20)
        except:
            helper_font = pygame.font.Font(None, 24)
        
        # 도우미 메시지
        helper_text = "각 방향별로 1회씩 파워스매싱을 발동해보세요!"
        text_surface = helper_font.render(helper_text, True, (255, 255, 100))
        
        # 반투명 배경
        bg_rect = text_surface.get_rect(center=(WIDTH // 2, HEIGHT // 2 - 100))
        bg_rect.inflate_ip(20, 10)
        bg_surface = pygame.Surface((bg_rect.width, bg_rect.height), pygame.SRCALPHA)
        bg_surface.fill((0, 0, 0, 200))
        
        # 배경과 텍스트 그리기
        SCREEN.blit(bg_surface, bg_rect)
        SCREEN.blit(text_surface, text_surface.get_rect(center=(WIDTH // 2, HEIGHT // 2 - 100)))
        
        # 추가 안내 메시지 (작은 글씨)
        try:
            small_font = get_font(14)
        except:
            small_font = pygame.font.Font(None, 18)
        
        guide_text = "↑ + SPACE (위), ← + SPACE (왼쪽), → + SPACE (오른쪽)"
        guide_surface = small_font.render(guide_text, True, (200, 200, 200))
        SCREEN.blit(guide_surface, guide_surface.get_rect(center=(WIDTH // 2, HEIGHT // 2 - 70)))
    
    # 승리 보너스 메시지 표시
    if perfect_victory_bonus_timer > 0:
        perfect_victory_bonus_timer -= 1
        
        # 메시지 설정
        try:
            if 'PIXEL_FONT' in globals() and PIXEL_FONT:
                bonus_font = pygame.font.Font(PIXEL_FONT, 36)
            else:
                bonus_font = pygame.font.Font(None, 36)
        except:
            bonus_font = pygame.font.Font(None, 36)
            
        # 승리 타입에 따른 메시지
        if victory_bonus_type == "perfect":
            bonus_text = "5:0 Perfect Victory! +3 Star Points!"
        elif victory_bonus_type == "dominant":
            bonus_text = "5:1 Victory! +2 Star Points!"
        elif victory_bonus_type == "victory":
            bonus_text = "5:2 소소한 승리! +1 Star Point!"
        else:
            bonus_text = "Victory Bonus!"
        
        # 텍스트 렌더링
        text_surface = bonus_font.render(bonus_text, True, (255, 215, 0))  # 황금색
        text_rect = text_surface.get_rect(center=(WIDTH // 2, HEIGHT // 3))
        
        # 배경 박스
        padding = 20
        bg_rect = text_rect.inflate(padding * 2, padding)
        
        # 펄스 효과
        import math
        pulse = abs(math.sin(perfect_victory_bonus_timer * 0.1)) * 0.3 + 0.7
        
        # 배경 그리기
        s = pygame.Surface((bg_rect.width, bg_rect.height), pygame.SRCALPHA)
        pygame.draw.rect(s, (50, 50, 80, int(200 * pulse)), s.get_rect(), border_radius=10)
        pygame.draw.rect(s, (255, 215, 0, int(255 * pulse)), s.get_rect(), 3, border_radius=10)
        SCREEN.blit(s, bg_rect)
        
        # 텍스트 그리기
        SCREEN.blit(text_surface, text_rect)
        
        # 별 파티클 효과
        if perfect_victory_bonus_timer % 10 == 0:
            import random
            for _ in range(3):
                star_x = text_rect.centerx + random.randint(-100, 100)
                star_y = text_rect.centery + random.randint(-30, 30)
                pygame.draw.circle(SCREEN, (255, 255, 100), (star_x, star_y), 2)
    
    if deuce_mode:
        # 듀스 모드일 때 인페르노 화염 전광판 표시
        draw_inferno_deuce_scoreboard(SCREEN, deuce_wins, deuce_losses, deuce_goal, WIDTH, HEIGHT)
    else:
        # 일반 모드 - 메탈릭 블루 전광판
        # 투기장 모드일 때는 영웅 이름 사용
        if arena_mode_enabled:
            bottom_hero_name = arena_bottom_hero.get("name", "Player") if arena_bottom_hero else "Player"
            top_hero_name = arena_top_hero.get("name", "Boss") if arena_top_hero else "Boss"
            draw_ice_crystal_scoreboard(SCREEN, round_wins, round_losses, WIDTH, HEIGHT, current_stage, bottom_hero_name, top_hero_name)
        else:
            draw_ice_crystal_scoreboard(SCREEN, round_wins, round_losses, WIDTH, HEIGHT, current_stage, top_name=current_boss_name)

    # 투기장 배속 버튼: _fullscreen_flip / _windowed_flip에서 REAL_SCREEN에 직접 그림
    _update_arena_speed_btn_rects()

def draw_laser_cannon_gauge():
    """ 레이저 캐논 쿨타임 게이지바 (야마토포 스타일)"""
    if current_stage != 6:
        return
    # 플레이어 2점 이상 획득 시에만 표시 (체력 기반에서 변경)
    if round_wins < 2:
        return
    current_time = pygame.time.get_ticks()
    # 게이지바 크기와 위치 (오른쪽 상단)
    gauge_width = 150
    gauge_height = 20
    gauge_x = WIDTH - gauge_width - 20
    gauge_y = 20
    # === 메카닉 프레임 ===
    frame_color = (100, 110, 120)
    dark_frame = (40, 45, 50)
    # 외곽 프레임 (경사진 모서리)
    frame_points = [
        (gauge_x - 3, gauge_y - 3),
        (gauge_x, gauge_y - 5),
        (gauge_x + gauge_width, gauge_y - 5),
        (gauge_x + gauge_width + 3, gauge_y - 3),
        (gauge_x + gauge_width + 3, gauge_y + gauge_height + 3),
        (gauge_x + gauge_width, gauge_y + gauge_height + 5),
        (gauge_x, gauge_y + gauge_height + 5),
        (gauge_x - 3, gauge_y + gauge_height + 3)
    ]
    draw.polygon(frame_color, frame_points)
    draw.polygon((20, 25, 30), frame_points, 2)
    # 내부 배경 (다크 그레이)
    bg_rect = pygame.Rect(gauge_x, gauge_y, gauge_width, gauge_height)
    draw.rect((10, 12, 15), bg_rect)
    # 그리드 패턴
    for i in range(0, gauge_width, 15):
        draw.line((20, 25, 30),
                        (gauge_x + i, gauge_y),
                        (gauge_x + i, gauge_y + gauge_height), 1)
    # === 쿨타임/충전 게이지 ===
    if laser_charging:
        # 충전 중 (빨간색 경고)
        charge_progress = min(1.0, (current_time - laser_charge_start) / 1500)
        fill_width = int(gauge_width * charge_progress)
        # 충전 바 (빨간색 그라데이션)
        for i in range(gauge_height):
            alpha = 1.0 - (i / gauge_height) * 0.4
            pulse = abs(math.sin(current_time * 0.01)) * 0.3 + 0.7
            color = (int(255 * alpha * pulse), int(50 * alpha), int(50 * alpha))
            draw.line(color, (gauge_x, gauge_y + i),
                           (gauge_x + fill_width, gauge_y + i))
        # 경고 텍스트
        warning_font = get_font(14)  # 14pt 픽셀 폰트
        warning_text = warning_font.render("CHARGING", True, (255, 100, 100))
        text_x = gauge_x + (gauge_width - warning_text.get_width()) // 2
        text_y = gauge_y + (gauge_height - warning_text.get_height()) // 2
        SCREEN.blit(warning_text, (text_x, text_y))
    elif laser_cannon_active:
        # 레이저 발사 중 (파란색)
        beam_progress = 1.0 - min(1.0, (current_time - last_laser_time) / laser_beam_duration)
        fill_width = int(gauge_width * beam_progress)
        # 빔 바 (파란색 플라즈마)
        for i in range(gauge_height):
            alpha = 1.0 - (i / gauge_height) * 0.4
            pulse = abs(math.sin(current_time * 0.02)) * 0.3 + 0.7
            color = (int(100 * alpha), int(DEFAULT_ALPHA * alpha * pulse), int(255 * alpha * pulse))
            draw.line(color, (gauge_x, gauge_y + i),
                           (gauge_x + fill_width, gauge_y + i))
        # 발사 텍스트
        fire_font = get_font(14)  # 14pt 픽셀 폰트
        fire_text = fire_font.render("FIRING", True, (100, 200, 255))
        text_x = gauge_x + (gauge_width - fire_text.get_width()) // 2
        text_y = gauge_y + (gauge_height - fire_text.get_height()) // 2
        SCREEN.blit(fire_text, (text_x, text_y))
    else:
        # 쿨타임 중 (녹색 충전)
        cooldown_progress = min(1.0, (current_time - last_laser_time) / 5000)
        fill_width = int(gauge_width * cooldown_progress)
        # 쿨타임 바 (녹색 그라데이션)
        for i in range(gauge_height):
            alpha = 1.0 - (i / gauge_height) * 0.4
            if cooldown_progress >= 1.0:
                # 준비 완료 (밝은 녹색)
                pulse = abs(math.sin(current_time * 0.005)) * 0.3 + 0.7
                color = (int(50 * alpha), int(255 * alpha * pulse), int(100 * alpha))
            else:
                # 충전 중 (어두운 녹색)
                color = (int(30 * alpha), int(100 * alpha), int(50 * alpha))
            draw.line(color, (gauge_x, gauge_y + i),
                           (gauge_x + fill_width, gauge_y + i))
        # 준비 상태 표시
        if cooldown_progress >= 1.0:
            ready_font = get_font(14)  # 14pt 픽셀 폰트
            ready_text = ready_font.render("READY", True, (50, 255, 100))
            text_x = gauge_x + (gauge_width - ready_text.get_width()) // 2
            text_y = gauge_y + (gauge_height - ready_text.get_height()) // 2
            SCREEN.blit(ready_text, (text_x, text_y))
    # === 레이벨 ===
    # YAMATO 텍스트 (왼쪽)
    label_font = get_font(12)  # 12pt 픽셀 폰트
    label_text = label_font.render("YAMATO", True, (150, 160, 170))
    SCREEN.blit(label_text, (gauge_x - label_text.get_width() - 5, gauge_y))
    # 전력 아이콘 (오른쪽)
    icon_x = gauge_x + gauge_width + 8
    icon_y = gauge_y + gauge_height // 2
    # 번개 모양 아이콘
    pygame.draw.lines(SCREEN, (100, 150, 200), False,
                     [(icon_x, icon_y - 5), (icon_x + 3, icon_y), 
                      (icon_x - 2, icon_y + 2), (icon_x + 5, icon_y + 5)], 2)
# 배속 버튼 옵션: (배속값, 화살표 개수, 툴팁 텍스트)
_ARENA_SPEED_OPTIONS = [
    (1, 1, "x1"),
    (1.5, 2, "x1.5"),
    (2, 3, "x2"),
    (3, 4, "x3"),
]


def _get_arena_speed_btn_layout():
    """투기장 배속 버튼 레이아웃 계산 (REAL_SCREEN 좌표, 가로 정렬)

    Returns:
        (sx, sy, rw, rh, rgap) - 시작좌표, 버튼크기, 간격 (REAL_SCREEN 좌표)
    """
    btn_w_base, btn_h_base, gap_base = 44, 32, 6
    btn_count = len(_ARENA_SPEED_OPTIONS)

    if _is_fullscreen_active:
        scale = GAME_SCALE_FACTOR
        rw = max(1, int(btn_w_base * scale))
        rh = max(1, int(btn_h_base * scale))
        rgap = max(1, int(gap_base * scale))

        # 맨 좌측 배치 (화면 왼쪽 끝 + 마진)
        sx = max(4, int(4 * scale))
        # 게임 영역 바로 아래 + 14px 마진
        game_height = int(INTERNAL_HEIGHT * scale)
        sy = GAME_OFFSET_Y + game_height + 14
    else:
        # 윈도우 모드: 좌측 필러 영역 맨 왼쪽
        rw, rh, rgap = btn_w_base, btn_h_base, gap_base
        sx = 4
        sy = HEIGHT - btn_h_base - 30

    return sx, sy, rw, rh, rgap


def _update_arena_speed_btn_rects():
    """투기장 배속 버튼 히트영역 갱신 (REAL_SCREEN 좌표, 클릭 판정용)"""
    global arena_speed_btn_rects
    if not arena_mode_enabled:
        return
    sx, sy, rw, rh, rgap = _get_arena_speed_btn_layout()
    arena_speed_btn_rects = {}
    for i, (mult, _, _tip) in enumerate(_ARENA_SPEED_OPTIONS):
        rx = sx + i * (rw + rgap)
        arena_speed_btn_rects[mult] = pygame.Rect(rx, sy, rw, rh)


