    global friend_moles_pending, friend_moles_active, friend_moles_timer, friend_moles_triggered, friend_moles_list, friend_moles_spawn_timer, friend_moles_dirt_particles, friend_moles_round_count  # 두더지왕 친구두더지

    # ⚡ 스매셔 콤보 리셋 (라운드 시작 시)
