def _process_bazooka_collisions():
    """바주카포 발사체 충돌 체크 및 폭발 처리 (스턴 중에도 실행)"""
    global boss_stunned_timer, boss_knockback_vel
    if selected_character_type != "soldier":
        return
    from item_effects.bazooka import get_bazooka_instance
    bazooka_inst = get_bazooka_instance()
    # 발사된 로켓이 없으면 종료
    if not bazooka_inst.equipped and not getattr(bazooka_inst, 'projectiles', None):
        return
    # 벽과의 충돌 체크
    wall_explosions = bazooka_inst.check_wall_collision()
    # 보스와의 직접 충돌 체크
    direct_explosions = bazooka_inst.check_boss_collision(BOSS, WIDTH)
    all_explosions = wall_explosions + direct_explosions
    # 모든 폭발에 대해 처리
    for explosion in all_explosions:
        create_bazooka_explosion(explosion["x"], explosion["y"])
        _destroy_stage2_rocks_in_radius(
            explosion["x"], explosion["y"], explosion["radius"], source="bazooka"
        )
        # 🏖 사막화 모래 침식: 바주카포 폭발 반경 내 모래 파괴
        if sand_obstacles is not None:
            erode_sand_area(sand_obstacles, explosion["x"], explosion["y"], explosion["radius"])
        # 폭발 사운드 재생
        try:
            if 'SOUND_GRENADE' in globals():
                play_sound_with_volume(SOUND_GRENADE)
        except:
            pass
        # 폭발 범위 내 보스 체크
        boss_center_x = BOSS.centerx
        boss_center_y = BOSS.centery
        distance = calculate_distance((boss_center_x, boss_center_y), (explosion["x"], explosion["y"]))
        if distance < explosion["radius"]:
            boss_stunned_timer = 90  # 1.5초 스턴
            direction = 1 if explosion["x"] < WIDTH / 2 else -1
            knockback_power = compute_knockback_magnitude("bazooka")
            boss_knockback_vel = _apply_boss_knockback_velocity(direction * knockback_power)
            # print(f"🚀💥 바주카포 폭발! 보스 스턴 1.5초, 넉백: {boss_knockback_vel}")
            apply_health_boss_damage(2, source="bazooka")

def _handle_boss_online_sync():
    """온라인 멀티플레이: 상대방의 PLAYER 위치를 BOSS에 적용 + 서브 처리.
    호스트: P2(클라이언트)의 PLAYER.x → BOSS.x
    클라이언트: P1(호스트)의 PLAYER.x → BOSS.x
    """
    global BOSS, _online_opponent_anim
    global is_waiting_for_serve, is_player_serve, ball_vel
    global serve_completed_timer, boss_fake_during_player_serve

    if _online_net_manager is None:
        return

    if online_is_host:
        # 호스트: 클라이언트가 보낸 위치 + 애니메이션 상태 적용
        remote = _online_net_manager.online_remote_input
        if remote is not None and 'x' in remote:
            BOSS.x = int(remote['x'])
            if 'anim' in remote:
                _online_opponent_anim = remote['anim']
    else:
        # 클라이언트: 호스트가 보낸 P1 위치를 BOSS에 적용
        frame = _online_net_manager.online_game_frame
        if frame is not None:
            p1 = frame.get('p1', None)
            if p1:
                BOSS.x = int(p1[0])

    # 경계 클램핑
    if BOSS.x < 0:
        BOSS.x = 0
    elif BOSS.x > WIDTH - BOSS.width:
        BOSS.x = WIDTH - BOSS.width

    # ── 바이퍼 제트팩 오프셋 적용 (상대방이 체공 중일 때 BOSS.y 변경) ──
    if _online_opponent_anim and _online_opponent_anim.get('state') == 'flying':
        _opp_jp_offset = _online_opponent_anim.get('jetpack_offset', 0)
        # 상대방이 위로 올라갈수록(offset 음수) → 상대 화면의 BOSS는 아래로 내려옴 (Y 증가)
        # 시점 반전: 내 화면에서 위로 = 상대 화면에서 아래로
        BOSS.y = BOSS_Y - int(_opp_jp_offset)  # 부호 반전! -(-200) = +200 → 아래로
    else:
        BOSS.y = BOSS_Y  # 체공이 아닐 때는 기본 위치

    # ── 온라인 서브 처리 (handle_boss() 안의 서브 로직을 대체) ──
    if is_waiting_for_serve and not ball_spawn_animation_active:
        _dbg_role = "HOST" if online_is_host else "CLIENT"
        _dbg_tick = pygame.time.get_ticks()
        _dbg_last_key = '_online_dbg_last_serve_tick'
        if _dbg_tick - globals().get(_dbg_last_key, 0) >= 500:  # 0.5초 간격
            globals()[_dbg_last_key] = _dbg_tick
            print(f"[Online Serve DEBUG] {_dbg_role} | is_player_serve={is_player_serve} | is_waiting={is_waiting_for_serve} | BALL=({BALL.x},{BALL.y}) | ball_vel={ball_vel}")
        if is_player_serve and online_is_host:
            # 호스트 본인 서브: space/enter로 아래에서 위로 발사
            keys = pygame.key.get_pressed()
            if keys[pygame.K_RETURN] or keys[pygame.K_SPACE]:
                try:
                    serve_result = physics_manager.serve_ball(True, current_stage, ai_mode)
                    apply_serve_result(serve_result)
                    is_waiting_for_serve = serve_result.get('is_waiting_for_serve', False)
                    serve_completed_timer = 180
                    boss_fake_during_player_serve = False
                    play_serve_sound()
                    create_impact_effect(BALL.centerx, BALL.centery, ball_vel, is_player=True)
                    print(f"[Online Serve DEBUG] HOST 서브 완료! BALL=({BALL.x},{BALL.y}) vel={ball_vel}")
                except Exception as e:
                    print(f"[Online Serve] 플레이어 서브 에러: {e}")
            else:
                boss_fake_during_player_serve = True
        elif is_player_serve and not online_is_host:
            # 클라이언트 본인 서브: 입력은 _online_send_player_position()에서 호스트로 전송
            # 호스트가 처리한 공 위치를 _online_client_apply_state()에서 수신
            boss_fake_during_player_serve = True  # 서브 대기 중 보스 움직임 방지
        elif online_is_host:
            # 상대(클라이언트) 서브: 클라이언트가 space/enter를 누르면 서브
            _client_serve = False
            remote = _online_net_manager.online_remote_input
            if remote is not None and remote.get('serve', False):
                _client_serve = True
                print(f"[Online Serve DEBUG] HOST: 클라이언트 서브 입력 수신!")
            # 클라이언트 서브 입력이 없으면 3초 후 자동 서브 (타임아웃 안전장치)
            time_now = pygame.time.get_ticks()
            _elapsed = time_now - waiting_start_time
            if _client_serve or (_elapsed >= 3000):
                print(f"[Online Serve DEBUG] HOST: 보스(클라이언트) 서브 실행 | client_input={_client_serve} | elapsed={_elapsed}ms")
                try:
                    serve_result = physics_manager.serve_ball(False, current_stage, ai_mode)
                    apply_serve_result(serve_result)
                    is_waiting_for_serve = serve_result.get('is_waiting_for_serve', False)
                    serve_completed_timer = 180
                    play_serve_sound()
                    create_impact_effect(BALL.centerx, BALL.centery, ball_vel, is_player=False)
                    print(f"[Online Serve DEBUG] HOST: 보스 서브 완료! BALL=({BALL.x},{BALL.y}) vel={ball_vel}")
                except Exception as e:
                    print(f"[Online Serve] 보스 서브 에러: {e}")
        else:
            # 클라이언트인데 is_player_serve=False (상대방 서브) → 호스트가 서브 처리, 공 위치는 프레임 데이터로 수신
            print(f"[Online Serve DEBUG] CLIENT: 상대방(호스트) 서브 대기 중... BALL=({BALL.x},{BALL.y})")


def _handle_boss_with_soap_debuff():
    """비누 디버프 / 빙판 날씨: 관성 블렌딩 방식.

    AI를 정상 실행한 뒤, 결과를 관성(이전 속도)과 블렌딩한다.
    보스가 움직이려 하지만 미끄러워서 마음대로 안 되는 느낌.

    비누: blend=0.18, friction=0.985 (강하게 미끄러짐)
    빙판: blend=0.35, friction=0.975 (비누보다 약한 미끄러짐)
    동시: blend≈0.126, friction≈0.990 (더 미끄러움)
    """
    global boss_current_speed, BOSS

    # ── 온라인 멀티플레이: 상대방 위치 동기화 (호스트/클라이언트 모두) ──
    if online_multiplayer_enabled:
        _handle_boss_online_sync()
        return
    # ── 비누 디버프 체크 ──
    soap_active = False
    soap_blend = 0.18
    soap_friction = 0.985
    try:
        from item_effects.soap import get_soap_instance
        soap_inst = get_soap_instance()
        if soap_inst.is_boss_soaped():
            soap_active = True
            soap_blend = soap_inst.get_blend_factor()
            soap_friction = soap_inst.get_friction()
    except Exception:
        pass

    # ── 빙판 날씨 체크 ──
    ice_active = is_ice_active()

    # 둘 중 하나라도 활성이면 관성 블렌딩 적용
    if soap_active or ice_active:
        if soap_active and ice_active:
            # 비누 + 빙판 동시: 더 미끄럽게
            blend = min(soap_blend, 0.18) * 0.7   # ~0.126 (12.6% AI)
            friction = min(max(soap_friction, 0.985) * 1.005, 0.998)  # ~0.990
        elif soap_active:
            blend = soap_blend
            friction = soap_friction
        else:
            # 빙판만: 비누보다 약한 관성 효과 (35% AI 반영, 마찰도 더 강해 빨리 멈춤)
            blend = 0.35
            friction = 0.975

        # ── 1. AI 실행 전 상태 저장 ──
        old_x = float(BOSS.x)
        old_speed = float(boss_current_speed)

        # ── 2. AI 정상 실행 (보스가 원하는 대로 움직임) ──
        handle_boss()

        # ── 3. AI 결과 vs 관성 블렌딩 ──
        ai_speed = boss_current_speed       # AI가 결정한 속도
        ai_x = float(BOSS.x)                # AI가 결정한 위치

        # 관성 위치 (이전 속도로 그냥 밀렸을 때)
        momentum_x = old_x + old_speed

        # 속도 블렌딩
        boss_current_speed = old_speed + (ai_speed - old_speed) * blend

        # 위치 블렌딩
        BOSS.x = momentum_x + (ai_x - momentum_x) * blend

        # 약간의 마찰 (서서히 감속, 영원히 밀리지 않도록)
        boss_current_speed *= friction

        # 경계 처리 + 벽에 부딪히면 속도 반감
        if BOSS.x < 0:
            BOSS.x = 0
            boss_current_speed = abs(boss_current_speed) * 0.3
        elif BOSS.x > WIDTH - BOSS.width:
            BOSS.x = WIDTH - BOSS.width
            boss_current_speed = -abs(boss_current_speed) * 0.3

        return
    handle_boss()

def handle_boss():
    global boss_speed_boost_timer, BOSS_SPEED
    global boss_fake_move, boss_fake_start_time
    global is_player_serve, is_waiting_for_serve
    global boss_fake_during_player_serve
    global speed_defense_active, speed_defense_timer, speed_defense_last_activation, SPEED_DEFENSE_INTERVAL
    global serve_grace_period  # 난이도 하향 - 서브 유예 기간
    global boss_current_speed, boss_fail_timer
    global BOSS_ACCELERATION, BOSS_DECELERATION, BOSS_MAX_SPEED, BOSS_INSTANT_STOP_DECELERATION
    global waiting_start_time, wait_delay
    global boss_throwing, boss_throw_timer  #  Stage 5 화염탄 관련 변수
    global ball_vel, boss_special_gauge
    global hongryun_hit_count, hongryun_ready, HONGRYUN_MAX_HITS  # 독안개장갑 게이지 감소용
    global ragnarok_shock_playing  #  라그나로크 전기 감전 사운드 상태
    global _judgment_lightning_stun_top_timer, _judgment_wind_stun_top_timer
    global boss_stunned_timer, boss_knockback_vel  #  화염병 스턴 관련 변수
    global stopwatch_active, stopwatch_timer  # ️ 스탑워치 관련 변수
    global whip_deactivation_active, boss_stunned_after_whip  #  상모돌리기 강제 해제 관련 변수
    global boss_knockback_timer, boss_knockback_distance  #  라그나로크 해머 넉백 관련 변수
    global boss_stun_timer, ragnarok_stun_pending  #  라그나로크 해머 스턴 관련 변수
    global boss_dashing, boss_dash_timer, boss_dash_duration_frames
    global boss_dash_speed, boss_dash_target_x, boss_dash_direction, boss_dash_afterimages
    global head_shot_active, head_shot_timer  # 헤드샷 스턴 관련 변수
    global boss_dash_stun_timer
    global stage8_shadow_casting, stage8_shadow_cast_start_ms, stage8_shadow_clones, stage8_shadow_next_ready_ms
    global stage8_shadow_freeze_posx, stage8_shadow_freeze_posy
    global stage8_shuriken_casting, stage8_shuriken_cast_start_ms, stage8_shuriken_next_ready_ms
    global stage8_stun_escape_active, stage8_stun_escape_ready_ms, stage8_stun_escape_attempted
    global stage8_stun_escape_start_ms, stage8_stun_escape_start_x, stage8_stun_escape_target_x, stage8_stun_escape_dx
    global stage8_stun_hologram_active, stage8_stun_hologram_rect, stage8_stun_hologram_end_ms
    global stage8_stun_escape_ghosts
    global stage8_awakened, player_score, round_wins
    global stage8_superspeed_active, stage8_superspeed_end_ms, stage8_superspeed_text_end_ms, stage8_superspeed_freeze_end_ms
    global stage8_awaken_intro_pending, stage8_awaken_intro_done, stage8_awaken_freeze_end_ms
    global boss_fire_knockback_vel
    global _viper_dive_slip_timer, _viper_dive_slip_vel

    now_ms = pygame.time.get_ticks()
    stage8_in_superspeed = False

    # 🔍 [DEBUG] 투기장 상단 영웅 AI 디버그 로깅
    # 공 생성 애니메이션 중에는 보스 AI 정지
    if ball_spawn_animation_active:
        return

    # 🐍 바이퍼 베놈 엣지 / 팬텀 킥 프리즈 중에는 보스 AI 정지
    # 단, 넉백 물리는 프리즈 중에도 적용 (팬텀 킥 넉백)
    if _viper_ns_freeze_active or _viper_dmk_freeze_active:
        if abs(boss_fire_knockback_vel) > 0.3:
            _kb_new_x = BOSS.x + boss_fire_knockback_vel
            _kb_min_x = 0
            _kb_max_x = WIDTH - BOSS.width
            if _kb_new_x <= _kb_min_x:
                BOSS.x = _kb_min_x
                boss_fire_knockback_vel = abs(boss_fire_knockback_vel) * 0.7
            elif _kb_new_x >= _kb_max_x:
                BOSS.x = _kb_max_x
                boss_fire_knockback_vel = -abs(boss_fire_knockback_vel) * 0.7
            else:
                BOSS.x = _kb_new_x
            boss_fire_knockback_vel *= 0.85
            if abs(boss_fire_knockback_vel) <= 0.3:
                boss_fire_knockback_vel = 0.0
        return

    # 🏓 넉백 처리 (화재/EMP 스트라이크/팬텀 킥 등)
    if abs(boss_fire_knockback_vel) > 0.3:
        _kb_new_x = BOSS.x + boss_fire_knockback_vel
        _kb_min_x = 0
        _kb_max_x = WIDTH - BOSS.width
        if _kb_new_x <= _kb_min_x:
            BOSS.x = _kb_min_x
            boss_fire_knockback_vel = abs(boss_fire_knockback_vel) * 0.7
        elif _kb_new_x >= _kb_max_x:
            BOSS.x = _kb_max_x
            boss_fire_knockback_vel = -abs(boss_fire_knockback_vel) * 0.7
        else:
            BOSS.x = _kb_new_x
        boss_fire_knockback_vel *= 0.85
        if abs(boss_fire_knockback_vel) <= 0.3:
            boss_fire_knockback_vel = 0.0

    # 🏟️ 투기장 영웅 스킬 상태 효과 적용 (상단 패들 = 보스)
    arena_boss_slow_multiplier = 1.0
    arena_boss_confused = False
    # ⚡ 번개의 분노 스턴 (독립 메커니즘 - 다른 스킬이 paddle_stunned 덮어써도 적용)
    if _judgment_lightning_stun_top_timer > 0:
        _judgment_lightning_stun_top_timer -= (1.0 / 60.0) * arena_speed_multiplier
        if _judgment_lightning_stun_top_timer <= 0:
            _judgment_lightning_stun_top_timer = 0.0
            if arena_skill_manager and hasattr(arena_skill_manager, 'game_state'):
                arena_skill_manager.game_state['top_paddle_stunned'] = False
            # 하단도 감전 끝났으면 사운드 정지
            if _judgment_lightning_stun_bottom_timer <= 0:
                _stop_electric_shock_sound()
        else:
            boss_current_speed = 0
            return  # 번개 스턴 중 모든 처리 차단
    # 🌪️ 바람의 분노 스턴 (독립 메커니즘)
    if _judgment_wind_stun_top_timer > 0:
        _judgment_wind_stun_top_timer -= (1.0 / 60.0) * arena_speed_multiplier
        if _judgment_wind_stun_top_timer <= 0:
            _judgment_wind_stun_top_timer = 0.0
            if arena_skill_manager and hasattr(arena_skill_manager, 'game_state'):
                arena_skill_manager.game_state['top_paddle_stunned'] = False
        else:
            boss_current_speed = 0
            return  # 바람 스턴 중 모든 처리 차단
    if arena_mode_enabled and arena_skill_manager:
        try:
            game_state = arena_skill_manager.game_state
            # 스턴 체크 (상단 패들이 스턴되면 이동 불가)
            if game_state.get('top_paddle_stunned', False):
                boss_current_speed = 0
                return  # 스턴 중에는 모든 처리 차단
            # 스팀 배리어 시전 중 정지 (상단 패들이 시전자일 때)
            if game_state.get('steam_barrier_caster_frozen', False) and game_state.get('barrier_owner_is_top', False):
                boss_current_speed = 0
                return  # 배리어 시전 중 이동 불가
            # 스팀 배리어 해동 중 (마지막 1초) - 점진적 속도 복귀
            steam_thaw = game_state.get('steam_barrier_thaw_speed', 0.0)
            if 0 < steam_thaw < 1.0 and game_state.get('barrier_owner_is_top', False) and game_state.get('barrier_active', False):
                arena_boss_slow_multiplier *= steam_thaw
            # 둔화 체크
            if game_state.get('top_paddle_slowed', False):
                arena_boss_slow_multiplier = game_state.get('top_paddle_slow_amount', 0.5)
            # 속도 증가 체크 (귀신의 눈 등)
            speed_boost = game_state.get('top_paddle_speed_boost', 1.0)
            if speed_boost > 1.0:
                arena_boss_slow_multiplier *= speed_boost  # 속도 배율 적용
            # 혼란 체크 (조작 반전)
            arena_boss_confused = game_state.get('top_paddle_confused', False)
            # 패들 축소 체크 (크기 + 이동속도 15% 감소)
            if game_state.get('top_paddle_shrink', False):
                shrink_scale = game_state.get('top_paddle_shrink_scale', 0.5)
                target_width = int(130 * shrink_scale)  # 기본 패들 너비 130
                target_height = int(40 * shrink_scale)  # 기본 패들 높이 40
                # 상단 패들: 매 프레임 강제로 크기와 Y 위치 고정 (다른 코드의 복원 방지)
                center_x = BOSS.centerx
                BOSS.width = target_width
                BOSS.height = target_height
                BOSS.centerx = center_x
                # 귀신발걸음 Y축 이동 중에는 Y좌표 고정 스킵
                if not arena_top_ghost_step_active:
                    BOSS.y = 25  # 상단 패들 Y 위치 고정! (BOSS_Y 상수값)
                # 🔮 이동속도 50% 감소 (축소된 패들 페널티)
                arena_boss_slow_multiplier *= 0.5
            else:
                # 축소 효과 해제 시 원래 크기(130x40)로 복원
                if BOSS.width != 130:
                    center_x = BOSS.centerx
                    BOSS.width = 130
                    BOSS.height = 40
                    BOSS.centerx = center_x
                    # 귀신발걸음 Y축 이동 중에는 Y좌표 고정 스킵
                    if not arena_top_ghost_step_active:
                        BOSS.y = 25  # 상단 패들 Y 위치 고정!
        except Exception as e:
            print(f"[Arena] Boss status effect error: {e}")

    # 🏟️ 투기장 상단 영웅 대쉬 처리
    if arena_mode_enabled and arena_top_hero:
        # 대쉬 업데이트
        if update_arena_top_hero_dash():
            return  # 대쉬 중에는 다른 AI 처리 건너뜀

        # 대쉬 발동 조건 체크 (보스와 동일한 조건: 공이 가까이 + 막지 못할 것 같을 때만)
        should_dash, target_x = arena_should_top_hero_dash()
        if should_dash:
            arena_trigger_top_hero_dash(target_x)

    # 🏟️ 투기장 하단 영웅 대쉬 처리 (AI)
    if arena_mode_enabled and arena_bottom_hero:
        # 대쉬 업데이트
        if update_arena_bottom_hero_dash():
            pass  # 대쉬/후딜 중에는 처리 완료

        # 대쉬 발동 조건 체크 (보스와 동일한 조건: 공이 가까이 + 막지 못할 것 같을 때만)
        should_dash, target_x = arena_should_bottom_hero_dash()
        if should_dash:
            arena_trigger_bottom_hero_dash_ai(target_x)

    # 라운드 시작 시 극정호신 텍스트는 1회만; 다음 라운드엔 숨김
    if is_waiting_for_serve:
        stage8_superspeed_text_end_ms = 0

    # 스테이지 8 전용 스턴 탈출 상태 정리 (다른 스테이지 전환 시 초기화)
    if current_stage != 8:
        stage8_stun_escape_active = False
        stage8_stun_escape_ready_ms = 0
        stage8_stun_escape_attempted = False
        stage8_stun_escape_dx = 0.0
        stage8_stun_escape_ghosts = []
        stage8_stun_hologram_active = False
        stage8_stun_hologram_rect = None
        stage8_stun_hologram_end_ms = 0
        # 초각성은 지속 상태를 유지해야 하므로 상태를 초기화하지 않는다.
        # 단, 라운드 재시작 시 진행 중 연출은 취소
        if stage8_awaken_intro_pending:
            stage8_awaken_intro_pending = False
            stage8_awaken_freeze_end_ms = 0
        stage8_superspeed_active = False
        stage8_superspeed_end_ms = 0
        stage8_superspeed_text_end_ms = 0
        stage8_superspeed_freeze_end_ms = 0

    # 스테이지 8: 그물 포획/스턴 시 영체탈주 우선 시도
    if current_stage == 8:
        try:
            score_reached = (round_wins >= 3) or (player_score >= 3)
            if not stage8_awaken_intro_done and score_reached:
                if not stage8_awaken_intro_pending:
                    stage8_awaken_intro_pending = True
                    stage8_awaken_freeze_end_ms = now_ms + 3000
            elif stage8_awaken_intro_done and not stage8_awakened:
                stage8_awakened = True
        except Exception:
            pass
        # 극정호신 종료 타이밍 체크
        if stage8_superspeed_active and stage8_superspeed_end_ms and now_ms >= stage8_superspeed_end_ms:
            _end_stage8_superspeed()
        # 초각성 연출 완료 시점 체크
        if stage8_awaken_intro_pending and now_ms >= stage8_awaken_freeze_end_ms:
            stage8_awaken_intro_pending = False
            stage8_awaken_intro_done = True
            stage8_awakened = True
            try:
                show_speech("초각성!", duration=90)
                # 바람 오오라 폭발 애니메이션 시작
                start_stage8_wind_burst()
            except Exception:
                pass
        # 극정호신 발동 조건 체크 (게이지 250)
        if (
            stage8_awakened
            and not stage8_superspeed_active
            and now_ms >= stage8_superspeed_cooldown_end_ms
            and boss_special_gauge >= STAGE8_SUPERSPEED_COST
            and not stage8_stun_escape_active
        ):
            _start_stage8_superspeed(now_ms)
        stage8_in_superspeed = stage8_superspeed_active

        # 극정호신 중에는 모든 이동을 대쉬로 처리 (쿨타임 0)
        if stage8_superspeed_active:
            boss_dash_cooldown_until_ms = 0
            if not boss_dashing and boss_dash_stun_timer <= 0 and now_ms >= stage8_superspeed_freeze_end_ms:
                _stage8_superspeed_dash(now_ms)

        if not stage8_in_superspeed:
            net_trapped = _is_stage8_net_trapped()
            if net_trapped and not stage8_stun_escape_active:
                if _try_stage8_stun_escape(now_ms):
                    return
            if boss_stunned_timer <= 0 and not net_trapped and not stage8_stun_escape_active:
                stage8_stun_escape_ready_ms = 0
                stage8_stun_escape_attempted = False

    # 스테이지8 스턴 탈출 모션 진행 중이면 우선 처리
    if current_stage == 8 and stage8_stun_escape_active:
        _update_stage8_stun_escape(now_ms)
        return

    #  수평 넉백 처리 (라그나로크 해머 + 코만도 총알 + 수류탄/화력지원)
    #  대쉬/후딜보다 우선 처리하여 즉시 넉백 적용
    if boss_knockback_timer > 0:
        # Stage 8: 스턴 중이면 넉백 구간에서도 영체탈주 발동 시도
        if _try_stage8_stun_escape(now_ms):
            return

        boss_knockback_timer -= 1

        if head_shot_active and head_shot_timer > 0:
            head_shot_timer -= 1
            if head_shot_timer <= 0:
                head_shot_active = False

        # 라그나로크 해머 체크
        legendary_manager = get_legendary_manager()
        is_ragnarok_knockback = "ragnarok_hammer" in legendary_manager.active_items

        # 수평 넉백 속도 적용 (라그나로크 해머, 코만도 총알, 수류탄/화력지원)
        if abs(boss_knockback_vel) > 0.1:
            BOSS.x += boss_knockback_vel

            # 벽 충돌 처리
            if is_ragnarok_knockback:
                # 라그나로크: 벽에 부딪히면 반대로 살짝 튕김 (역동적)
                if BOSS.x <= 0:
                    BOSS.x = 0
                    boss_knockback_vel = -boss_knockback_vel * 0.3  # 30% 반발
                elif BOSS.x >= WIDTH - BOSS.width:
                    BOSS.x = WIDTH - BOSS.width
                    boss_knockback_vel = -boss_knockback_vel * 0.3
            else:
                # 일반 넉백: 벽에서 멈춤
                if BOSS.x <= 0:
                    BOSS.x = 0
                    boss_knockback_vel = 0
                elif BOSS.x >= WIDTH - BOSS.width:
                    BOSS.x = WIDTH - BOSS.width
                    boss_knockback_vel = 0

            # 넉백 감속 처리
            if is_ragnarok_knockback:
                # 라그나로크: 폭발적 초기속도 → 급감속 → 즉시 감전
                progress = 1.0 - (boss_knockback_timer / 36.0)  # 0→1 (시작→끝)
                if progress < 0.15:
                    boss_knockback_vel *= 0.98  # 극초반: 거의 감속 없음 (폭발적 이탈)
                elif progress < 0.35:
                    boss_knockback_vel *= 0.92  # 초반: 약간 감속
                elif progress < 0.55:
                    boss_knockback_vel *= 0.82  # 중반: 급감속
                else:
                    boss_knockback_vel *= 0.70  # 후반: 빠르게 정지
            else:
                # 일반 넉백 (코만도 총알 등)
                boss_knockback_vel *= 0.85

        # 라그나로크 해머만의 추가 효과
        if is_ragnarok_knockback:
            progress = 1.0 - (boss_knockback_timer / 36.0)
            # 넉백 초반: Y축 미세 진동 (충격으로 위아래로 흔들림)
            if progress < 0.4 and abs(boss_knockback_vel) > 2.0:
                shake_y = random.uniform(-2.5, 2.5) * (1.0 - progress * 2)
                BOSS.y += shake_y
                BOSS.y = max(0, min(120, BOSS.y))
            # X축 흔들림 (날아가는 느낌)
            if progress < 0.6 and abs(boss_knockback_vel) > 1.0:
                shake_intensity = 4.0 * (1.0 - progress)
                shake_x = random.uniform(-shake_intensity, shake_intensity)
                BOSS.x += shake_x
                BOSS.x = max(0, min(WIDTH - BOSS.width, BOSS.x))

            # 넉백 속도가 충분히 줄었거나 타이머 종료 시 즉시 감전
            if ragnarok_stun_pending > 0 and (abs(boss_knockback_vel) < 1.5 or boss_knockback_timer <= 1):
                boss_stun_timer = ragnarok_stun_pending
                ragnarok_stun_pending = 0
                boss_knockback_vel = 0
                boss_knockback_timer = 0
                play_ragnarok_shock_sound()
                ragnarok_shock_playing = True

        # 넉백 중에는 보스 이동 불가
        boss_current_speed = 0
        return

    # 🔥 화재 이벤트 공 충돌 넉백 - 이제 X축으로 처리됨 (boss_knockback_vel 사용)
    # Y축 넉백 코드 제거됨 - 우박과 동일한 방식으로 충돌 시점에 즉시 적용

    #  보스 대쉬 모션 처리 (플레이어 대쉬와 유사: 초반 고속, 이후 감속)
    #  스테이지8 그림자분신 주문 중에는 패들을 고정
    if current_stage == 8 and (stage8_shadow_casting or stage8_shuriken_casting):
        try:
            if stage8_shadow_freeze_posx and stage8_shadow_freeze_posy:
                BOSS.centerx = stage8_shadow_freeze_posx
                BOSS.centery = stage8_shadow_freeze_posy
        except Exception:
            pass
        # 주문 중에는 이동 로직만 묶어서 건너뛰고, 이후 로직은 계속 진행
        # 표창 캐스팅 시 위치를 최신으로 유지
        if stage8_shuriken_casting:
            stage8_shadow_freeze_posx = BOSS.centerx
            stage8_shadow_freeze_posy = BOSS.centery
    if boss_dashing and boss_dash_timer > 0:
        boss_dash_timer -= 1

        # 플레이어 rolling 대쉬 패턴과 유사한 속도 곡선
        high_phase_frames = min(20, boss_dash_duration_frames)
        if boss_dash_timer > high_phase_frames:
            move_step = boss_dash_speed * boss_dash_direction
        else:
            decel_factor = max(0.0, boss_dash_timer / float(high_phase_frames)) if high_phase_frames > 0 else 0.0
            move_step = boss_dash_speed * boss_dash_direction * decel_factor

        _boss_pre_dash_x = float(BOSS.centerx)
        BOSS.centerx += move_step

        # 🏖 사막화: 보스 대쉬 시 상단 벽면 모래 대량 침식
        if sand_obstacles and not sand_obstacles.dissolving:
            erode_sand_by_dash(sand_obstacles, _boss_pre_dash_x, float(BOSS.centerx), "top")

        # 목표를 크게 지나치지 않도록 보정
        if boss_dash_direction > 0 and BOSS.centerx > boss_dash_target_x:
            BOSS.centerx = int(boss_dash_target_x)
        elif boss_dash_direction < 0 and BOSS.centerx < boss_dash_target_x:
            BOSS.centerx = int(boss_dash_target_x)

        # 게임 영역 내로 제한 (BOSS.width를 동적으로 사용)
        boss_min_cx = BOSS.width // 2
        boss_max_cx = WIDTH - BOSS.width // 2
        BOSS.centerx = max(boss_min_cx, min(boss_max_cx, BOSS.centerx))

        if boss_dash_timer <= 0:
            boss_dashing = False
            # 대쉬 애니메이션 종료 (스테이지 8)
            try:
                if current_stage == 8 and stage8_boss_sprite:
                    stage8_boss_sprite.stop_dash()
            except Exception:
                pass
            # 대쉬 종료 후 후딜 시간 설정 (스테이지별 설정 기반)
            try:
                stage_cfg = BOSS_CONFIGS.get(current_stage, {})
                stun_seconds = float(stage_cfg.get("dash_stun_duration", 0.5))
            except Exception:
                stun_seconds = 0.5
            if stage8_superspeed_active and current_stage == 8:
                boss_dash_stun_timer = STAGE8_SUPERSPEED_DASH_STUN_FRAMES
            else:
                boss_dash_stun_timer = max(1, int(stun_seconds * FPS))

            # 🔊 보스 대쉬 후딜 시작 - 플레이어와 동일한 후딜 사운드 재생
            try:
                play_dash_delay_sound()
            except Exception:
                pass

        # 대쉬 중에도 바주카포 충돌 체크
        _process_bazooka_collisions()
        # 대쉬 중에는 다른 AI 처리 건너뜀
        return

    # 대쉬 후 후딜 시간 처리
    if boss_dash_stun_timer > 0:
        _prev_boss_stun = boss_dash_stun_timer
        boss_dash_stun_timer -= 1
        boss_current_speed = 0
        # 🔊 보스 대쉬 후딜 종료 시 사운드 중지
        if _prev_boss_stun > 0 and boss_dash_stun_timer <= 0:
            try:
                stop_dash_delay_sound()
            except Exception:
                pass
        _process_bazooka_collisions()  # 스턴 중에도 바주카포 충돌 체크
        return

    # 극정호신 상태에서는 일반 AI를 건너뛰되, 서브 대기 중이면 서브 로직은 그대로 진행
    if stage8_in_superspeed and not is_waiting_for_serve:
        _process_bazooka_collisions()  # 극정호신 중에도 바주카포 충돌 체크
        return

    #  라그나로크 해머 스턴 체크 - 스턴 중이면 모든 처리 차단
    if boss_stun_timer > 0:
        boss_stun_timer -= 1
        boss_current_speed = 0  # 속도를 0으로
        BOSS.x = BOSS.x  # 위치 고정 (현재 위치 유지)

        # 스턴이 끝나면 전기 감전 사운드 중지
        if boss_stun_timer == 0 and ragnarok_shock_playing:
            stop_ragnarok_shock_sound()
            ragnarok_shock_playing = False
            # print("-")

        if boss_stun_timer % 20 == 0:  # 매 20프레임마다 디버그 출력
            # print(f"   !  : {boss_stun_timer/60:.1f}, : {boss_current_speed}")

        # 스턴 중에도 바주카포 발사체 충돌 체크는 계속 수행
            pass
        _process_bazooka_collisions()
        return  # 스턴 중에는 모든 처리 차단
    
    # 바주카포 충돌 체크 및 폭발 처리
    if selected_character_type == "soldier":
        from item_effects.bazooka import get_bazooka_instance
        bazooka_inst = get_bazooka_instance()
        # 발사된 로켓이 있으면 장착 여부와 무관하게 충돌/폭발 처리
        if bazooka_inst.equipped or (getattr(bazooka_inst, 'projectiles', None)):
            # 모든 폭발 수집 (발사체-테트로/가드 접촉, 직접 명중, 벽 충돌)
            all_explosions = []

            # A) 발사체 ↔ 테트로/가드 사전 충돌 검사 → 즉시 폭발 생성
            try:
                if current_stage == 7 and getattr(bazooka_inst, 'projectiles', None):
                    for proj in list(bazooka_inst.projectiles):
                        if not proj.get('active', False):
                            continue
                        proj_rect = pygame.Rect(
                            int(proj.get('x', 0)) - 10,
                            int(proj.get('y', 0)) - 10,
                            20, 30
                        )
                        hit_any = False
                        # 테트로미노 충돌
                        if 'stage7_tetrominoes' in globals() and stage7_tetrominoes:
                            for mino in list(stage7_tetrominoes):
                                if mino.get('state') in ('destroying', 'evaporating'):
                                    continue
                                for c in (mino.get('cells', []) or []):
                                    rect = c.get('rect')
                                    if rect and proj_rect.colliderect(rect):
                                        hit_any = True
                                        break
                                if hit_any:
                                    break
                        # 가드 블럭 충돌
                        if not hit_any and 'stage7_guard_blocks' in globals() and stage7_guard_blocks:
                            for block in list(stage7_guard_blocks):
                                if block.get('state') not in ('assembling', 'hologram', 'deploy', 'active'):
                                    continue
                                if any(proj_rect.colliderect(c.get('rect')) for c in (block.get('cells', []) or []) if c.get('rect')):
                                    hit_any = True
                                    break
                        if hit_any:
                            all_explosions.append({
                                'x': float(proj.get('x', 0.0)),
                                'y': float(proj.get('y', 0.0)),
                                'radius': float(getattr(bazooka_inst, 'EXPLOSION_RADIUS', 110)),
                            })
                            proj['active'] = False
            except Exception:
                pass
            
            # 보스와의 직접 충돌 체크
            direct_explosions = bazooka_inst.check_boss_collision(BOSS, WIDTH)
            all_explosions.extend(direct_explosions)
            
            # 벽과의 충돌 체크
            wall_explosions = bazooka_inst.check_wall_collision()
            all_explosions.extend(wall_explosions)
            
            # 모든 폭발에 대해 처리
            for explosion in all_explosions:
                # 폭발 이펙트 생성
                create_bazooka_explosion(explosion["x"], explosion["y"])
                _destroy_stage2_rocks_in_radius(
                    explosion["x"], explosion["y"], explosion["radius"], source="bazooka"
                )
                # 🏖 사막화 모래 침식: 바주카포 폭발 반경 내 모래 파괴
                if sand_obstacles is not None:
                    erode_sand_area(sand_obstacles, explosion["x"], explosion["y"], explosion["radius"])
                # Stage 7: 바주카포 폭발 반경 내 테트로/가드 파괴
                try:
                    if current_stage == 7:
                        cx = float(explosion["x"])
                        cy = float(explosion["y"])
                        r = float(explosion.get("radius", 0))
                        r2 = r * r
                        # 테트로미노
                        if 'stage7_tetrominoes' in globals() and stage7_tetrominoes:
                            for mino in list(stage7_tetrominoes):
                                if mino.get('state') in ('destroying', 'evaporating'):
                                    continue
                                hit = False
                                for c in mino.get('cells', []) or []:
                                    rect = c.get('rect')
                                    if not rect:
                                        continue
                                    closest_x = max(rect.left, min(cx, rect.right))
                                    closest_y = max(rect.top, min(cy, rect.bottom))
                                    dx = cx - closest_x
                                    dy = cy - closest_y
                                    if dx * dx + dy * dy <= r2:
                                        hit = True
                                        break
                                if not hit:
                                    continue
                                try:
                                    mino["hit_flash_duration"] = 130
                                    mino["hit_flash_until"] = pygame.time.get_ticks() + 130
                                except Exception:
                                    pass
                                if mino.get('wall_generated'):
                                    try:
                                        for c in mino.get('cells', []) or []:
                                            _remove_wall_cell_rect(c.get('rect'))
                                    except Exception:
                                        pass
                                destroy_stage7_tetromino(mino, by_player=True, by_dash=True)
                        # 가드 라인(1자 블럭)
                        if 'stage7_guard_blocks' in globals() and stage7_guard_blocks:
                            for block in list(stage7_guard_blocks):
                                state = block.get('state')
                                if state not in ('assembling', 'hologram', 'deploy', 'active'):
                                    continue
                                hit = False
                                for c in block.get('cells', []) or []:
                                    rect = c.get('rect')
                                    if not rect:
                                        continue
                                    closest_x = max(rect.left, min(cx, rect.right))
                                    closest_y = max(rect.top, min(cy, rect.bottom))
                                    dx = cx - closest_x
                                    dy = cy - closest_y
                                    if dx * dx + dy * dy <= r2:
                                        hit = True
                                        break
                                if hit:
                                    destroy_stage7_guard_block(block, by_player=True)
                except Exception:
                    pass
                
                # 폭발 사운드 재생
                try:
                    if 'SOUND_GRENADE' in globals():
                        play_sound_with_volume(SOUND_GRENADE)  # 폭발 사운드
                    else:
                        pass  # print("🔊 바주카포 폭발 사운드 재생 (사운드 파일 없음)")
                except:
                    print("🔊 바주카포 사운드 재생 실패")
                
                # 폭발 범위 내 보스 체크 (수류탄과 동일한 로직)
                boss_center_x = BOSS.centerx
                boss_center_y = BOSS.centery
                distance = calculate_distance((boss_center_x, boss_center_y), (explosion["x"], explosion["y"]))
                
                if distance < explosion["radius"]:
                    # 보스 스턴 적용 (1.5초 = 90프레임)
                    boss_stunned_timer = 90  # 수류탄(126프레임)보다 짧음

                    # 넉백 방향 결정 (수류탄과 동일)
                    direction = 1 if explosion["x"] < WIDTH / 2 else -1
                    knockback_power = compute_knockback_magnitude("bazooka")
                    boss_knockback_vel = _apply_boss_knockback_velocity(direction * knockback_power)

                    # print(f"🚀💥 바주카포 폭발! 보스 스턴 1.5초, 넉백: {boss_knockback_vel}")
                    apply_health_boss_damage(2, source="bazooka")

    # 헤드샷 스턴 상태 처리 - 1초간 보스 완전 정지
    if head_shot_active and head_shot_timer > 0:
        head_shot_timer -= 1
        boss_current_speed = 0  # 스턴 중에는 속도를 0으로
        BOSS.x = BOSS.x  # 위치 고정 (현재 위치 유지)
        if head_shot_timer <= 0:
            head_shot_active = False
            # print("🎯 헤드샷 스턴 종료!")
        return  # 헤드샷 스턴 중에는 AI 완전 정지

    # 스테이지 2: 보스 이동 방향 추적 (바나나 미끄러짐용)
    _track_boss_movement()

    # 스테이지 2: 플레이어 연막 상태 업데이트 (바나나 미끄러짐 면역)
    _update_player_smoke_state()

    # 스테이지 2: 보스가 바나나 미끄러짐 중이면 AI 비활성화하고 미끄러짐만 적용
    if _is_boss_banana_slipping():
        _apply_boss_banana_slip()
        return  # 미끄러짐 중에는 AI 완전 정지 (통제불능)

    # 🍌 EMP 스트라이크 슬립 (바나나식 — AI 통제불능 + 미끄러짐)
    if _viper_dive_slip_timer > 0:
        _viper_dive_slip_timer -= 1
        _slip_ratio = _viper_dive_slip_timer / max(1, _viper_dive_slip_duration)
        BOSS.x += _viper_dive_slip_vel * _slip_ratio
        if BOSS.x <= 0:
            BOSS.x = 0
            _viper_dive_slip_vel = abs(_viper_dive_slip_vel) * 0.5
        elif BOSS.x >= WIDTH - BOSS.width:
            BOSS.x = WIDTH - BOSS.width
            _viper_dive_slip_vel = -abs(_viper_dive_slip_vel) * 0.5
        return  # 슬립 중 AI 완전 정지 (바나나와 동일)

    # 일반 AI 움직임 전에 긴급 대쉬 시도
    if _boss_try_emergency_dash():
        return

    # 최종 경계 보정 헬퍼 함수 (공과 동일하게 0 ~ WIDTH 범위 사용)
    def _ensure_boss_in_bounds():
        final_min_x = 0
        final_max_x = WIDTH - BOSS.width
        corrected = False
        if BOSS.x < final_min_x:
            BOSS.x = final_min_x
            corrected = True
        elif BOSS.x > final_max_x:
            BOSS.x = final_max_x
            corrected = True
        # 디버그: 보스가 경계에 도달했을 때 출력
        if BOSS.x <= final_min_x + 2 or BOSS.x >= final_max_x - 2:
            pass  # print(f"[EDGE OK] width={BOSS.width}, x={BOSS.x}, right={BOSS.x + BOSS.width}, bounds=[{final_min_x}, {final_max_x + BOSS.width}], corrected={corrected}")

    #  리그별 AI 모드 체크 및 분기 (4단계 리그 시스템)
    if ai_enabled and ai_mode == "junior":
        #  주니어리그: 초심자용 쉬운 AI (실수 25%)
        handle_boss_junior()
        _apply_boss_banana_slip()  # 바나나 미끄러짐 적용
        _ensure_boss_in_bounds()  # 최종 경계 보정
        return
    elif ai_enabled and ai_mode == "champion":
        #  챔피언리그: 신화급 AI (실수 2%) + 10% 광폭화
        handle_boss_mythic()  # 신화급 AI 사용
        _apply_boss_banana_slip()  # 바나나 미끄러짐 적용
        _ensure_boss_in_bounds()  # 최종 경계 보정
        return
    elif ai_enabled and ai_mode == "mythic":
        #  신화리그: 최강 AI (실수 2%) + 100% 광폭화
        handle_boss_mythic()
        _apply_boss_banana_slip()  # 바나나 미끄러짐 적용
        _ensure_boss_in_bounds()  # 최종 경계 보정
        return
    #  새로운 보스 모드에서는 상단 보스가 handle_boss 역할
    if new_boss_mode_active:
        if selected_top_boss == 1:
            handle_lightning_master_as_top()  # 라이트닝 마스터
        elif selected_top_boss == 2:
            handle_ice_queen_as_top()  # 아이스 퀸
        _ensure_boss_in_bounds()  # 최종 경계 보정
        return
    #  넉백 후 원위치 복귀 처리 (넉백이 없을 때만)
    if boss_knockback_timer == 0:
        # 라그나로크 해머가 활성화되어 있으면 복귀 속도 감소
        # Import already done globally at line 141
        legendary_manager = get_legendary_manager()
        
        if "ragnarok_hammer" in legendary_manager.active_items:
            # 라그나로크 해머 활성 시 복귀 완전 차단 (넉백 상태 유지)
            pass  # 아무것도 하지 않음 - 보스가 밀려난 위치에 그대로 유지
        else:
            # 원래 위치로 부드럽게 복귀
            if BOSS.y < BOSS_Y:
                BOSS.y += 2
                BOSS.y = min(BOSS_Y, BOSS.y)
    #  보스 스턴 상태 처리 (화염병 효과) - AI 비활성화 상태에서도 작동
    if boss_stunned_timer > 0:
        if current_stage == 8 and _try_stage8_stun_escape(now_ms):
            return

        boss_stunned_timer -= 1
        # 넉백 적용
        BOSS.x += boss_knockback_vel

        # 벽 충돌 시 멈춤 (튕기지 않음) - 게임 영역 내로 제한
        if BOSS.x <= 0:
            BOSS.x = 0
            boss_knockback_vel = 0
        elif BOSS.x >= WIDTH - BOSS.width:
            BOSS.x = WIDTH - BOSS.width
            boss_knockback_vel = 0

        # 감속
        boss_knockback_vel *= 0.85

        # 스턴 종료 후 준비 상태 초기화
        if current_stage == 8 and boss_stunned_timer <= 0 and not stage8_stun_escape_active:
            stage8_stun_escape_ready_ms = 0
            stage8_stun_escape_attempted = False
        return  # 스턴 중에는 AI 비활성화
    # Stage 50 (튜토리얼) - 매우 쉬운 AI
    if current_stage == 50:
        # 튜토리얼에서 필요한 전역 변수 추가
        global fireball_last_cast, fireball_cooldown, ball_impact_boost
        
        # 튜토리얼 서브 대기 상태 처리
        # 공 생성 애니메이션 중에는 서브 무시
        if is_waiting_for_serve and not ball_spawn_animation_active:
            time_now = pygame.time.get_ticks()

            # 보스 서브 차례
            if not is_player_serve:
                # 보스 패들 간보기 움직임
                def fake_motion():
                    style = random.randint(1, 4)
                    if style == 1:
                        return math.sin(time_now / 100) * 2.5
                    elif style == 2 and random.random() < 0.02:
                        return random.choice([-1, 1]) * random.randint(20, 30)
                    elif style == 3:
                        return math.sin(time_now / 300) * 4
                    elif style == 4 and random.random() < 0.015:
                        return random.choice([-1, 1]) * 10
                    return 0
                
                if boss_fake_move and time_now - boss_fake_start_time < wait_delay:
                    BOSS.centerx += fake_motion()
                
                if wait_delay > 0 and time_now - waiting_start_time >= wait_delay:
                    # 서브 실행 및 상태 업데이트
                    serve_result = physics_manager.serve_ball(is_player_serve, current_stage, ai_mode)
                    apply_serve_result(serve_result)
                    is_waiting_for_serve = serve_result['is_waiting_for_serve']
                    if serve_result['fireball_last_cast'] is not None:
                        fireball_last_cast = serve_result['fireball_last_cast']
                        fireball_cooldown = 1500  # 1.5초 쿨타임 강제 설정
                    play_serve_sound()
                    create_impact_effect(BALL.centerx, BALL.centery, ball_vel, is_player=False)
                elif wait_delay == 0:
                    # 즉시 서브 실행
                    serve_result = physics_manager.serve_ball(is_player_serve, current_stage, ai_mode)
                    apply_serve_result(serve_result)
                    is_waiting_for_serve = serve_result['is_waiting_for_serve']
                    if serve_result['fireball_last_cast'] is not None:
                        fireball_last_cast = serve_result['fireball_last_cast']
                        fireball_cooldown = 1500  # 1.5초 쿨타임 강제 설정
                    play_serve_sound()
                    create_impact_effect(BALL.centerx, BALL.centery, ball_vel, is_player=False)
            
            return  # 서브 중에는 일반 AI 실행 안함
        
        # 튜토리얼 전용 매우 쉬운 AI
        # 공의 미래 위치 예측 (매우 부정확하게)
        future_x = BALL.x
        
        # 큰 오차 추가 (초보자가 이길 수 있도록)
        error = random.randint(-150, 150)
        future_x += error
        
        # boss_speed_config[50]의 설정값 사용 (이미 50% 증가된 값)
        # BOSS_ACCELERATION, BOSS_MAX_SPEED 등은 start_stage에서 이미 설정됨
        max_speed = BOSS_MAX_SPEED  # boss_speed_config[50]에서 설정된 값 사용
        accel = BOSS_ACCELERATION   # boss_speed_config[50]에서 설정된 값 사용
        
        target_distance = future_x - BOSS.centerx
        
        # 때때로 완전히 잘못된 방향으로 이동 (20% 확률)
        if random.random() < 0.2:
            target_distance = -target_distance
        
        if abs(target_distance) < 50:  # 매우 큰 허용 범위
            boss_current_speed *= 0.7
        elif target_distance < 0:
            boss_current_speed = max(-max_speed, boss_current_speed - accel)
        else:
            boss_current_speed = min(max_speed, boss_current_speed + accel)
        
        # 위치 업데이트 with ground crack collision check
        proposed_x = BOSS.x + boss_current_speed
        proposed_boss_rect = pygame.Rect(proposed_x, BOSS.y, BOSS.width, BOSS.height)

        collision_crack = _boss_get_crack_collision(proposed_boss_rect, apply_response=True)
        if collision_crack:
            boss_current_speed = 0  # Stop the boss
            contact_x = _slide_boss_toward_crack_edge(BOSS.x, proposed_x, collision_crack, BOSS.width)
            if abs(contact_x - BOSS.x) > 0.01:
                BOSS.x = contact_x
                BOSS.x = max(0, min(WIDTH - BOSS.width, BOSS.x))
            if random.random() < 0.1:  # 10% chance to print
                # print(f"[CRACK BLOCKED - Tutorial] Boss cannot move from x={BOSS.x} to x={proposed_x}")
                pass
        else:
            BOSS.x = proposed_x
            BOSS.x = max(0, min(WIDTH - BOSS.width, BOSS.x))
        return  # 튜토리얼 AI 완료
    
    # Stage 1 각시탈 스킬 시전 중 보스 이동 불가 (부채질 1초 / 부채던지기 0.5초)
    if current_stage == 1 and (fan_wind_charging or fan_throw_windup_active):
        boss_current_speed = 0
        return

    # Stage 1 상모돌리기 강제 해제 모션 중 후딜 상태
    if current_stage == 1 and boss_stunned_after_whip:
        # 완전 통제 불능 - 이동 불가
        boss_current_speed = 0
        BOSS.y = BOSS_Y  # Y 좌표를 기본 위치로 고정
        return  # AI 로직 완전 스킵
    
    # Stage 1 상모돌리기 중에는 이동 속도 제한
    if current_stage == 1 and whip_active:
        # 상모돌리기 중에는 이동 속도를 크게 제한 (30%로 감소)
        # 특히 플레이어 쪽(아래)으로 이동할 때 더 제한
        max_whip_speed = 1.5  # 최대 속도 제한
        
        # 현재 보스 속도를 크게 제한
        if abs(boss_current_speed) > max_whip_speed:
            boss_current_speed = max_whip_speed if boss_current_speed > 0 else -max_whip_speed
        
        # 속도를 추가로 30%로 감소
        boss_current_speed *= 0.3

        # 보스 위치 업데이트
        BOSS.x += boss_current_speed
        BOSS.x = max(0, min(WIDTH - BOSS.width, BOSS.x))
        
        # Y축 이동 차단 (앞으로 전진하지 못하게)
        BOSS.y = BOSS_Y  # Y 좌표를 기본 위치로 고정
        
        return  # 일반 AI 로직 스킵
    
    # 일반 보스 AI: 통합 보스 설정 (스테이지별 + 리그별 완전 연계)
    config = get_final_boss_config(current_stage, ai_mode)
    # --- Stage 5 화염탄 던지는 중에는 0.5초간 이동 금지 ---
    if current_stage == 5 and boss_throwing:
        boss_current_speed = 0
        # boss_throw_timer를 프레임 단위로 사용하고 있다면 30fps 기준 약 15프레임 = 0.5초
        boss_throw_timer -= 1
        if boss_throw_timer <= 0:
            boss_throwing = False
        return  #  이동 로직을 아예 스킵
    # --- Stage 6 해양 드론 보스: 일반 AI 로직 사용 (공 궤적 예측) ---
    # 스테이지 6도 다른 보스와 동일한 AI 루틴을 사용 (return 제거)
    # --- 서브 대기 상태 처리 ---
    if is_waiting_for_serve:
        time_now = pygame.time.get_ticks()
        # 보스 패들 간보기 움직임 (모든 스테이지 동일)
        def fake_motion():
                style = random.randint(1, 4)
                if style == 1:
                    return math.sin(time_now / 100) * 2.5
                elif style == 2 and random.random() < 0.02:
                    return random.choice([-1, 1]) * random.randint(20, 30)
                elif style == 3:
                    return math.sin(time_now / 300) * 4
                elif style == 4 and random.random() < 0.015:
                    return random.choice([-1, 1]) * 10
                return 0
        # --- 보스 서브 차례 ---
        if not is_player_serve and not ball_spawn_animation_active:
            if boss_fake_move and time_now - boss_fake_start_time < wait_delay:
                BOSS.centerx += fake_motion()
            # 모든 스테이지에서 서브 로직 실행 (스테이지 6 포함)
            if wait_delay > 0 and time_now - waiting_start_time >= wait_delay:
                # 서브 실행 및 상태 업데이트
                serve_result = physics_manager.serve_ball(is_player_serve, current_stage, ai_mode)
                apply_serve_result(serve_result)
                is_waiting_for_serve = serve_result['is_waiting_for_serve']
                # Stage 2에서 서브 후 유예 기간 설정 (난이도 하향)
                if current_stage == 2:
                    serve_grace_period = SERVE_GRACE_DURATION
                if serve_result['fireball_last_cast'] is not None:
                    fireball_last_cast = serve_result['fireball_last_cast']
                    fireball_cooldown = 1500  # 1.5초 쿨타임 강제 설정
                play_serve_sound()
                #  보스 서브 시 타격 이펙트 생성
                create_impact_effect(BALL.centerx, BALL.centery, ball_vel, is_player=False)
            if wait_delay == 0:
                # 서브 실행 및 상태 업데이트
                serve_result = physics_manager.serve_ball(is_player_serve, current_stage, ai_mode)
                apply_serve_result(serve_result)
                is_waiting_for_serve = serve_result['is_waiting_for_serve']
                # Stage 2에서 서브 후 유예 기간 설정 (난이도 하향)
                if current_stage == 2:
                    serve_grace_period = SERVE_GRACE_DURATION
                if serve_result['fireball_last_cast'] is not None:
                    fireball_last_cast = serve_result['fireball_last_cast']
                    fireball_cooldown = 1500  # 1.5초 쿨타임 강제 설정
                play_serve_sound()
                #  보스 서브 시 타격 이펙트 생성
                create_impact_effect(BALL.centerx, BALL.centery, ball_vel, is_player=False)
        # --- 플레이어 서브 차례 ---
        elif boss_fake_during_player_serve:
            BOSS.centerx += fake_motion()
        return  # 서브 중에는 아래 일반 이동 로직 실행 안 함
    # --- 일반 AI 이동 로직 ---
    predict_frame = max(10, min(30, int(FPS / max(1, abs(ball_vel[0])))))
    # --- 기존 AI 로직 ---
    enhanced_fail_chance = config["fail_chance"]
    enhanced_predict_chance = config["predict_chance"]
    enhanced_predict_error = config["predict_error"]
    enhanced_fail_error = config["fail_error"]

    # 🏟️ 투기장 모드: AI 오차 파라미터 대폭 축소 (영웅 vs 영웅 공정성)
    if arena_mode_enabled:
        enhanced_predict_error = min(enhanced_predict_error, 25)   # 예측 오차: 최대 ±25px (기존 95)
        enhanced_fail_error = min(enhanced_fail_error, 60)         # 실수 오차: 최대 ±60px (기존 315)
        enhanced_predict_chance = max(enhanced_predict_chance, 0.85)  # 예측 확률: 최소 85% (기존 45%)
        enhanced_fail_chance = min(enhanced_fail_chance, 0.005)    # 실수 확률: 최대 0.5% (기존 1%)
    
    # Check if current position is blocked by cracks (stuck detection)
    if 'blacksmith_ground_cracks' in globals() and blacksmith_ground_cracks:
        # If boss has been trying to move but stuck for too long, try alternative direction
        if not hasattr(handle_boss, 'stuck_timer'):
            handle_boss.stuck_timer = 0
            handle_boss.last_x = BOSS.x
        
        # Check if boss hasn't moved much
        if abs(BOSS.x - handle_boss.last_x) < 2:  # Less than 2 pixels movement
            handle_boss.stuck_timer += 1
        else:
            handle_boss.stuck_timer = 0
            handle_boss.last_x = BOSS.x
        
        # If stuck for more than 30 frames, try to find alternative path
        if handle_boss.stuck_timer > 30:
            # Try to move to nearest free space
            for offset in [30, -30, 60, -60, 90, -90]:
                test_x = BOSS.x + offset
                if 0 <= test_x <= WIDTH - BOSS.width and _is_boss_movement_valid(test_x):
                    # Found a free space, set as temporary target
                    enhanced_predict_error = abs(offset) * 2
                    handle_boss.stuck_timer = 0
                    break
    
    # 조명탄 혼란 효과 체크 (최우선)
    if boss_confused_timer > 0:
        # 혼란 상태일 때는 완전히 랜덤하게 움직임 (공을 무시)
        if not hasattr(handle_boss, 'confusion_target_ai'):
            handle_boss.confusion_target_ai = random.randint(BOSS.width // 2, WIDTH - BOSS.width // 2)
            handle_boss.confusion_direction_timer_ai = 0
        # 30프레임마다 새로운 랜덤 위치 선택
        handle_boss.confusion_direction_timer_ai = getattr(handle_boss, 'confusion_direction_timer_ai', 0) + 1
        if handle_boss.confusion_direction_timer_ai >= HALF_SECOND_FRAMES:
            handle_boss.confusion_target_ai = random.randint(BOSS.width // 2, WIDTH - BOSS.width // 2)
            handle_boss.confusion_direction_timer_ai = 0
        # 랜덤 목표 지점으로 이동
        future_x = handle_boss.confusion_target_ai
        # 가끔 갑자기 방향 전환 (20% 확률)
        if random.random() < 0.2:
            future_x = random.randint(BOSS.width // 2, WIDTH - BOSS.width // 2)
    # --- 멍청 모드 처리 ---
    elif boss_fail_timer > 0:
        # 🏟️ 투기장: 공이 보스쪽으로 오고 있으면 멍청모드 즉시 해제 (반응성 향상)
        if arena_mode_enabled and ball_vel[1] < -3:
            boss_fail_timer = 0
            if random.random() < enhanced_predict_chance:
                future_x = BALL.centerx + ball_vel[0] * predict_frame
            else:
                future_x = BALL.centerx
            future_x += random.randint(-enhanced_predict_error, enhanced_predict_error)
        else:
            future_x = BALL.centerx + ball_vel[0] * predict_frame
            future_x += random.randint(-enhanced_fail_error, enhanced_fail_error)
            boss_fail_timer -= 1
    else:
        if random.random() < enhanced_fail_chance:
            # 🏟️ 투기장: 멍청모드 지속 시간 단축 (60→20프레임, 약 0.33초)
            boss_fail_timer = 20 if arena_mode_enabled else 60
            future_x = BALL.centerx + ball_vel[0] * predict_frame
            future_x += random.randint(-enhanced_fail_error, enhanced_fail_error)
        else:
            if random.random() < enhanced_predict_chance:
                future_x = BALL.centerx + ball_vel[0] * predict_frame
            else:
                future_x = BALL.centerx
            future_x += random.randint(-enhanced_predict_error, enhanced_predict_error)
    # Check if target is blocked by cracks and adjust if needed
    target_x = future_x
    if 'blacksmith_ground_cracks' in globals() and blacksmith_ground_cracks:
        # Check if the path to target is blocked
        if _check_path_blocked_by_cracks(BOSS.x, target_x, BOSS.width, BOSS.y, BOSS.height):
            # Target is blocked, find alternative target
            # Check both sides of the crack
            left_clear = False
            right_clear = False
            left_target = BOSS.x
            right_target = BOSS.x
            
            # Check left side (0 ~ WIDTH 범위)
            for test_x in range(int(BOSS.x) - 10, 0, -10):
                if not _check_path_blocked_by_cracks(BOSS.x, test_x, BOSS.width, BOSS.y, BOSS.height):
                    left_target = test_x
                    left_clear = True
                    break

            # Check right side (0 ~ WIDTH 범위)
            for test_x in range(int(BOSS.x) + 10, WIDTH - BOSS.width, 10):
                if not _check_path_blocked_by_cracks(BOSS.x, test_x, BOSS.width, BOSS.y, BOSS.height):
                    right_target = test_x
                    right_clear = True
                    break
            
            # Choose the side that's closer to the original target but not blocked
            if left_clear and right_clear:
                if abs(left_target - target_x) < abs(right_target - target_x):
                    future_x = left_target
                else:
                    future_x = right_target
            elif left_clear:
                future_x = left_target
            elif right_clear:
                future_x = right_target
            else:
                # Both sides blocked, stop moving
                future_x = BOSS.centerx
                boss_current_speed = 0
    
    # --- 가속/감속 로직: 통합 설정 기반 ---
    # 스피드디펜스 활성화 시 전역 변수 사용, 아니면 config 사용
    if current_stage == 2 and speed_defense_active:
        enhanced_accel = BOSS_ACCELERATION
        enhanced_decel = BOSS_DECELERATION
        enhanced_max_speed = BOSS_MAX_SPEED
        enhanced_instant_stop = BOSS_INSTANT_STOP_DECELERATION
    else:
        enhanced_accel = config["accel"]
        enhanced_decel = config["decel"]
        enhanced_max_speed = config["max_speed"]
        enhanced_instant_stop = config["instant_stop"]

    # 🏟️ 투기장 모드: BOSS 능력치를 PLAYER와 동일하게 설정 (공정성)
    if arena_mode_enabled:
        enhanced_max_speed = 6.0       # PLAYER MAX_SPEED (MAX_SPEED=6과 동일)
        enhanced_accel = 0.4           # PLAYER ACCELERATION
        enhanced_decel = 0.4           # PLAYER DECELERATION

    #  화염 지대 내에서 속도 감소 효과 적용
    if boss_speed_reduction_active:
        enhanced_accel *= boss_speed_reduction_factor  # 가속도 50% 감소
        enhanced_max_speed *= boss_speed_reduction_factor  # 최대 속도 50% 감소
        # 현재 속도도 즉시 감소
        boss_current_speed *= boss_speed_reduction_factor
    
    # 이동 속도 감소 효과 적용
    slow_multiplier = 1.0
    if leg_shot_active:
        slow_multiplier *= LEG_SHOT_SPEED_REDUCTION
    if spider_mine_slow_active:
        slow_multiplier *= SPIDER_MINE_SLOW_FACTOR
    # ⚡ 플라즈마 자기장 둔화 효과 적용
    if boss_plasma_slowed:
        plasma_slow_mult = get_boss_plasma_slow_multiplier()
        slow_multiplier *= plasma_slow_mult
    # 🧤 독안개장갑 둔화 효과 적용
    try:
        from item_effects.venom_mist_gauntlet import is_mist_field_active, update_mist
        if is_mist_field_active():
            _vmg_result = update_mist(
                float(BOSS.centerx), float(BOSS.centery), current_stage, {}
            )
            if _vmg_result['slow_active']:
                slow_multiplier *= (1.0 - _vmg_result['slow_amount'])
            if _vmg_result['gauge_drained'] > 0:
                boss_special_gauge = max(0, boss_special_gauge - _vmg_result['gauge_drained'])
            if _vmg_result['hongryun_orb_drained'] > 0 and current_stage == 5:
                hongryun_hit_count = max(0, hongryun_hit_count - _vmg_result['hongryun_orb_drained'])
                if hongryun_hit_count < HONGRYUN_MAX_HITS:
                    hongryun_ready = False
    except Exception:
        pass
    # 🏟️ 투기장 영웅 스킬 둔화/속도증가 효과 적용
    if arena_mode_enabled and arena_skill_manager:
        try:
            game_state = arena_skill_manager.game_state
            if game_state.get('top_paddle_slowed', False):
                arena_slow = game_state.get('top_paddle_slow_amount', 0.5)
                slow_multiplier *= arena_slow
            # 🔮 난쟁이마술 축소 시 이동속도 50% 감소 (패들 축소 페널티)
            if game_state.get('top_paddle_shrink', False):
                slow_multiplier *= 0.5  # 50% 감속
            # 👁️ 귀신의 눈 등 속도 증가 효과
            arena_speed_boost = game_state.get('top_paddle_speed_boost', 1.0)
            if arena_speed_boost > 1.0:
                enhanced_accel *= arena_speed_boost
                enhanced_max_speed *= arena_speed_boost
        except:
            pass
    # 🏟️ 투기장 퍽: 이동속도 증가 (질풍각) - 상단 영웅
    if arena_perk_speed_mult_top != 1.0 and arena_mode_enabled:
        enhanced_accel *= arena_perk_speed_mult_top
        enhanced_max_speed *= arena_perk_speed_mult_top
    # 🏟️ 투기장 관중 모멘텀 버프 - 상단 영웅: 최대 +10% 이속
    if arena_mode_enabled and current_stage == 30 and pillar_renderer is not None:
        _m_bg = pillar_renderer.get_colosseum_bg() if pillar_renderer else None
        if _m_bg and hasattr(_m_bg, 'get_momentum_level'):
            _momentum = _m_bg.get_momentum_level()
            if _momentum > 0.3:
                _m_bonus = 1.0 + _momentum * 0.1  # 최대 1.1배
                enhanced_accel *= _m_bonus
                enhanced_max_speed *= _m_bonus
    # 🏟️ 투기장 신의심판: 상단 영웅 이동속도 -50%
    if arena_mode_enabled and current_stage == 30 and animated_bg_stage30 is not None:
        if animated_bg_stage30.is_judgment_earthquake_active():
            enhanced_accel *= 0.5
            enhanced_max_speed *= 0.5
    if slow_multiplier != 1.0:
        enhanced_accel *= slow_multiplier
        enhanced_max_speed *= slow_multiplier
        enhanced_decel *= slow_multiplier
        # 즉시 속도 제한: 현재 속도가 둔화된 최대속도 초과 시 클램핑
        if boss_current_speed > enhanced_max_speed:
            boss_current_speed = enhanced_max_speed
        elif boss_current_speed < -enhanced_max_speed:
            boss_current_speed = -enhanced_max_speed
    # 🏟️ 투기장 영웅 스킬 혼란 효과 (조명탄과 동일한 랜덤 움직임)
    global arena_top_confusion_target, arena_top_confusion_timer
    arena_confused = False
    if arena_mode_enabled and arena_skill_manager:
        try:
            game_state = arena_skill_manager.game_state
            arena_confused = game_state.get('top_paddle_confused', False)
        except:
            pass
    # 혼란 상태면 랜덤하게 움직임 (조명탄 혼란 효과와 동일)
    effective_target_x = future_x
    if arena_confused:
        # 혼란 상태일 때는 완전히 랜덤하게 움직임 (공을 무시) - 조명탄과 동일
        if arena_top_confusion_target == 0:
            arena_top_confusion_target = random.randint(BOSS.width // 2, WIDTH - BOSS.width // 2)
            arena_top_confusion_timer = 0
        # 30프레임마다 새로운 랜덤 위치 선택
        arena_top_confusion_timer += arena_speed_multiplier
        if arena_top_confusion_timer >= HALF_SECOND_FRAMES:
            arena_top_confusion_target = random.randint(BOSS.width // 2, WIDTH - BOSS.width // 2)
            arena_top_confusion_timer = 0
        # 랜덤 목표 지점으로 이동
        effective_target_x = arena_top_confusion_target
        # 가끔 갑자기 방향 전환 (20% 확률) - 조명탄과 동일
        if random.random() < 0.2:
            effective_target_x = random.randint(BOSS.width // 2, WIDTH - BOSS.width // 2)
    else:
        # 혼란 상태가 아니면 랜덤 타겟 초기화
        arena_top_confusion_target = 0
        arena_top_confusion_timer = 0
    # 기존 AI 움직임 로직
    if effective_target_x < BOSS.centerx:
        if boss_current_speed > -enhanced_max_speed:
            boss_current_speed -= enhanced_accel
    elif effective_target_x > BOSS.centerx:
        if boss_current_speed < enhanced_max_speed:
            boss_current_speed += enhanced_accel
    else:
        if boss_current_speed > 0:
            boss_current_speed -= enhanced_decel
        elif boss_current_speed < 0:
            boss_current_speed += enhanced_decel
    # 급정지 처리
    if effective_target_x < BOSS.centerx and boss_current_speed > 0:
        boss_current_speed -= enhanced_instant_stop
    elif effective_target_x > BOSS.centerx and boss_current_speed < 0:
        boss_current_speed += enhanced_instant_stop
    # 최종 속도 클램프 (급정지 후 max_speed 초과 방지)
    if boss_current_speed > enhanced_max_speed:
        boss_current_speed = enhanced_max_speed
    elif boss_current_speed < -enhanced_max_speed:
        boss_current_speed = -enhanced_max_speed
    # 이동 적용 with ground crack collision check
    proposed_x = BOSS.x + boss_current_speed
    proposed_boss_rect = pygame.Rect(proposed_x, BOSS.y, BOSS.width, BOSS.height)

    collision_crack = None
    if 'blacksmith_ground_cracks' in globals() and blacksmith_ground_cracks:
        collision_crack = _boss_get_crack_collision(proposed_boss_rect, apply_response=True)

    if collision_crack:
        boss_current_speed = 0
        contact_x = _slide_boss_toward_crack_edge(BOSS.x, proposed_x, collision_crack, BOSS.width)
        if abs(contact_x - BOSS.x) > 0.01:
            BOSS.x = contact_x
            BOSS.centerx = BOSS.x + BOSS.width // 2
        if random.random() < 0.1:  # 10% chance to print debug
            # print(f"[CRACK BLOCKED - Main AI] Boss cannot move from x={BOSS.x} to x={proposed_x}")
            pass
    else:
        BOSS.centerx += boss_current_speed
        # 게임 영역 내로 제한 (공과 동일하게 0 ~ WIDTH 범위 사용)
        boss_min_cx = BOSS.width // 2
        boss_max_cx = WIDTH - BOSS.width // 2
        old_cx = BOSS.centerx
        BOSS.centerx = max(boss_min_cx, min(boss_max_cx, BOSS.centerx))
        BOSS.x = BOSS.centerx - BOSS.width // 2

    # 최종 경계 보정 (공과 동일하게 0 ~ WIDTH 범위 사용)
    final_min_x = 0
    final_max_x = WIDTH - BOSS.width
    if BOSS.x < final_min_x:
        BOSS.x = final_min_x
    elif BOSS.x > final_max_x:
        BOSS.x = final_max_x

    # 🏖 사막화: 보스 이동 시 상단 벽면 모래 침식 (걷기)
    if sand_obstacles and not sand_obstacles.dissolving and abs(boss_current_speed) > 0.5:
        erode_sand_by_paddle(sand_obstacles, BOSS, "top")

    # --- Stage 2 보스 스피드 디펜스 (악어장군 전용) ---
    if current_stage == 2 and current_boss_name == "악어장군":
        # 서브 유예 기간 카운트다운 (난이도 하향)
        if serve_grace_period > 0:
            serve_grace_period -= 1
        
        # 플레이어가 친 공이 보스에게 위험할 때 발동 (유예 기간 제외)
        if not speed_defense_active and speed_defense_timer <= 0 and ball_vel[1] < 0 and serve_grace_period <= 0:  # 공이 위로 향할 때
            # 공이 보스 근처에 도달할 시간 예측
            if BALL.centery < HEIGHT * 0.5:  # 공이 화면 상단 50% 지점 이상 (더 일찍 감지)
                time_to_reach_boss = abs((BOSS.centery - BALL.centery) / ball_vel[1]) if ball_vel[1] < 0 else float('inf')
                if time_to_reach_boss < 60:  # 1초 이내에 도달 예정 (더 여유있게)
                    predicted_x = BALL.centerx + ball_vel[0] * time_to_reach_boss
                    distance_to_predicted = abs(predicted_x - BOSS.centerx)
                    # 보스가 현재 속도로 이동해도 도달하기 어려운 위치인지 확인
                    boss_max_move = BOSS_MAX_SPEED_DEFAULT * time_to_reach_boss
                    # 위험 감지: 보스가 도달하기 어려운 거리 (더 민감하게)
                    if distance_to_predicted > boss_max_move * 0.8:  # 80% 이상 도달 어려움 (덜 민감) - 난이도 하향
                        # 10% 확률로 스피드디펜스 발동 (확률 증가)
                        if random.random() < 0.06:  # 6% 확률로 발동 (기존 10%) - 난이도 하향
                            # 발동 간격 체크 (25초)
                            current_time = pygame.time.get_ticks() // 16  # 프레임으로 변환
                            if current_time - speed_defense_last_activation >= SPEED_DEFENSE_INTERVAL:
                                speed_defense_active = True
                                speed_defense_timer = speed_defense_cooldown  # 3초 지속
                                speed_defense_last_activation = current_time
                                
                                # 현재 보스 속도의 200% (+100%)로 스피드디펜스 설정
                                # 리그와 스테이지에 따른 현재 보스 속도 가져오기
                                current_config = get_final_boss_config(current_stage, ai_mode if ai_enabled else "junior")
                                # 스피드디펜스: 이동속도 200% 증가 (3배), 방향전환속도 100% 증가 (2배)
                                speed_multiplier = 3.0  # 200% 증가 (3배속)
                                direction_change_multiplier = 2.0  # 방향전환 100% 증가 (2배)
                                BOSS_ACCELERATION = current_config["accel"] * speed_multiplier
                                BOSS_DECELERATION = current_config["decel"] * speed_multiplier
                                BOSS_MAX_SPEED = current_config["max_speed"] * speed_multiplier
                                BOSS_INSTANT_STOP_DECELERATION = current_config["instant_stop"] * direction_change_multiplier
                                # 즉시 목표 지점으로 가속 시작
                                if predicted_x < BOSS.centerx:
                                    boss_current_speed = -BOSS_MAX_SPEED * 0.2  # 왼쪽으로 초기 속도 부여 (최대속도의 20%) - 난이도 하향
                                else:
                                    boss_current_speed = BOSS_MAX_SPEED * 0.2   # 오른쪽으로 초기 속도 부여 (최대속도의 20%) - 난이도 하향
                                play_sound_with_volume(SOUND_DEFENSE_START)
                                # Stage 2 악어장군: 스피드디펜스 발동 시 게이지 80 소모
                                if current_stage == 2:
                                    boss_special_gauge = max(0, boss_special_gauge - 80)
                                    # print(f"스피드 디펜스 발동! 게이지 80 소모 (현재: {boss_special_gauge}/500)")
                                else:
                                    pass  # print(f"스피드 디펜스 발동! 거리 차이: {distance_to_predicted:.1f}, 최대 이동 가능: {boss_max_move:.1f}")
        if speed_defense_timer > 0:
            speed_defense_timer -= 1
        if speed_defense_active and speed_defense_timer <= 0:
            speed_defense_active = False
            boss_trail.clear()  #  스피드 디펜스 종료 시 꼬리 효과 즉시 정리
            BOSS_ACCELERATION = BOSS_ACCELERATION_DEFAULT
            BOSS_DECELERATION = BOSS_DECELERATION_DEFAULT
            BOSS_MAX_SPEED = BOSS_MAX_SPEED_DEFAULT
            BOSS_INSTANT_STOP_DECELERATION = BOSS_INSTANT_STOP_DECELERATION_DEFAULT
def show_death_evaluation():
    """게임 오버 시 요약 화면 표시 - 골드, 시간, 아이템, 퍽, 보스 정보"""
    global player_analyzer, current_stage

    # 투기장 모드에서는 게임 오버 요약 화면 건너뛰기
    # (투기장 자체 결과 UI 사용)
    if arena_mode_enabled:
        return

    # 패배 BGM 재생
    try:
        bgm_manager.stop_bgm()
        bgm_manager.bgm_manager.play_bgm('defeat', loop=0)
    except Exception:
        pass

    # === 데이터 스냅샷 (리셋 전에 캡처) ===
    accumulated_gold = downtown_gold

    # 게임 시간 계산
    game_time_seconds = 0
    try:
        if player_analyzer and hasattr(player_analyzer, 'stats') and hasattr(player_analyzer.stats, 'session_start_time'):
            game_time_seconds = max(0, time.time() - player_analyzer.stats.session_start_time)
    except Exception:
        pass
    game_minutes = int(game_time_seconds) // 60
    game_seconds = int(game_time_seconds) % 60

    # 획득 아이템 목록 (패시브/액티브 분리)
    # 패시브: 세션 동안 획득한 모든 패시브 아이템 (가챠, 상점, 필드 등)
    # 액티브: 세션 동안 사용한 모든 액티브 아이템
    acquired_passive_items = []
    acquired_active_items = []
    try:
        # 세션 동안 획득한 패시브 아이템 사용 (없으면 현재 passive_item_list 사용)
        source_passive = session_acquired_passive_items if session_acquired_passive_items else passive_item_list
        for item in source_passive:
            if item and item.get("name"):
                # 중복 제거 (같은 이름의 아이템은 한 번만 표시)
                if not any(i.get("name") == item.get("name") for i in acquired_passive_items):
                    acquired_passive_items.append(item)
    except Exception:
        pass
    try:
        # 세션 동안 사용한 액티브 아이템 + 현재 슬롯에 있는 아이템
        # 먼저 세션 동안 사용한 아이템 추가
        for item in session_used_active_items:
            if item and item.get("name"):
                if not any(i.get("name") == item.get("name") for i in acquired_active_items):
                    acquired_active_items.append(item)
        # 현재 슬롯에 있는 아이템도 추가 (아직 사용하지 않은 것들)
        for item in active_item_slot:
            if item and item.get("name"):
                if not any(i.get("name") == item.get("name") for i in acquired_active_items):
                    acquired_active_items.append(item)
    except Exception:
        pass

    # 획득 퍽 목록 (runtime_skill_levels 사용 - 인게임에서 실제 획득한 퍽)
    acquired_perks = []
    try:
        all_skill_pools = {}
        all_skill_pools.update(RUNTIME_SKILL_POOL)
        all_skill_pools.update(SMASHER_EXCLUSIVE_SKILLS)
        all_skill_pools.update(OPTIMUS_EXCLUSIVE_SKILLS)
        all_skill_pools.update(SOLDIER_EXCLUSIVE_SKILLS)
        all_skill_pools.update(VIPER_EXCLUSIVE_SKILLS)
        all_skill_pools.update(INSTANT_RUNTIME_SKILLS)
        for skill_id, level in runtime_skill_levels.items():
            if level > 0 and skill_id in all_skill_pools:
                skill_data = all_skill_pools[skill_id]
                acquired_perks.append({
                    "id": skill_id,
                    "name": skill_data.get("name", skill_id),
                    "level": level,
                    "icon_color": skill_data.get("icon_color", (150, 150, 150)),
                    "skill_data": skill_data,
                })
    except Exception:
        pass

    # 클리어한 보스 목록 (이미지 포함)
    # 실제 게임 진행 순서: 1→2→3→4→5(네메시스)→6(홍련)→7→8
    # 스왑 맵을 사용하지 않고 직접 logic_stage 기준으로 표시
    cleared_bosses = []
    boss_thumb_size = 48

    def _create_nemesis_battlecruiser_thumb(size):
        """네메시스 보스 썸네일 - 울트라 배틀크루저 직접 그리기"""
        surf = pygame.Surface((size, size), pygame.SRCALPHA)
        # 배경 (바다색)
        pygame.draw.rect(surf, (30, 50, 80), (0, 0, size, size))
        # 전함 본체 (회색 금속)
        ship_w = int(size * 0.85)
        ship_h = int(size * 0.35)
        ship_x = (size - ship_w) // 2
        ship_y = int(size * 0.35)
        # 선체 그림자
        pygame.draw.rect(surf, (45, 55, 65), (ship_x + 2, ship_y + 2, ship_w, ship_h))
        # 선체 본체
        pygame.draw.rect(surf, (75, 90, 105), (ship_x, ship_y, ship_w, ship_h))
        # 상부 구조물 (함교)
        bridge_w = int(size * 0.25)
        bridge_h = int(size * 0.2)
        bridge_x = (size - bridge_w) // 2
        bridge_y = ship_y - bridge_h + 2
        pygame.draw.rect(surf, (85, 100, 115), (bridge_x, bridge_y, bridge_w, bridge_h))
        pygame.draw.rect(surf, (100, 115, 130), (bridge_x, bridge_y, bridge_w, 2))
        # 안테나/레이더
        ant_x = size // 2
        pygame.draw.line(surf, (120, 130, 145), (ant_x, bridge_y), (ant_x, bridge_y - 6), 1)
        pygame.draw.circle(surf, (140, 180, 220), (ant_x, bridge_y - 6), 2)
        # 갑판 디테일 (장갑판)
        for i in range(4):
            px = ship_x + 4 + i * int(ship_w * 0.22)
            pygame.draw.rect(surf, (95, 110, 125), (px, ship_y + 3, int(ship_w * 0.18), ship_h - 6))
        # 포탑들
        turret_color = (100, 115, 130)
        pygame.draw.circle(surf, turret_color, (ship_x + 6, ship_y + ship_h // 2), 3)
        pygame.draw.circle(surf, turret_color, (ship_x + ship_w - 6, ship_y + ship_h // 2), 3)
        # 엔진 불꽃 (후방)
        pygame.draw.rect(surf, (255, 150, 50), (ship_x + ship_w - 2, ship_y + 4, 4, 3))
        pygame.draw.rect(surf, (255, 150, 50), (ship_x + ship_w - 2, ship_y + ship_h - 7, 4, 3))
        # 파도 효과
        wave_y = ship_y + ship_h + 3
        pygame.draw.arc(surf, (100, 150, 200), (ship_x - 5, wave_y, 20, 8), 3.14, 6.28, 1)
        pygame.draw.arc(surf, (100, 150, 200), (ship_x + ship_w - 15, wave_y, 20, 8), 3.14, 6.28, 1)
        return surf

    try:
        for logic_stage in range(1, current_stage):
            # 세션 중 저장된 보스 이름 우선 사용 (변형 보스 반영)
            name = session_cleared_boss_names.get(logic_stage, boss_names.get(logic_stage, "보스"))
            # 보스 이미지 로드 (썸네일용)
            boss_thumb = None
            try:
                # 스테이지 5 (네메시스)는 배틀크루저 직접 그리기
                if logic_stage == 5:
                    boss_thumb = _create_nemesis_battlecruiser_thumb(boss_thumb_size)
                else:
                    # 다른 보스는 이미지 파일 로드
                    img_path = resource_path(f"boss_stage{logic_stage}.png")
                    if os.path.exists(img_path):
                        boss_thumb = pygame.image.load(img_path).convert_alpha()
                        boss_thumb = pygame.transform.smoothscale(boss_thumb, (boss_thumb_size, boss_thumb_size))
            except Exception:
                pass
            cleared_bosses.append({"display_stage": logic_stage, "name": name, "thumb": boss_thumb})
    except Exception:
        pass

    # 전투 결과
    final_wins = round_wins
    final_losses = round_losses
    display_stage = stage_logic_to_display(current_stage)
    current_boss_name = get_boss_name(current_stage)

    # === 폰트 설정 ===
    font_body = FontStyle.small()      # 18pt
    font_detail = FontStyle.tiny()     # 12pt
    font_hint = FontStyle.tiny()       # 12pt

    # === 패널 설정 ===
    panel_width = 620
    panel_height = 700
    panel_x = (WIDTH - panel_width) // 2
    panel_y = (HEIGHT - panel_height) // 2
    panel_rect = pygame.Rect(panel_x, panel_y, panel_width, panel_height)
    content_x = panel_x + 20
    content_width = panel_width - 40

    # 잔여 이벤트 제거
    try:
        pygame.event.clear()
    except Exception:
        pass

    # === 메인 루프 ===
    freeze_awaken = False
    freeze_superspeed = False
    freeze_spawn_anim = False
    while True:
        # 구슬 접기 애니메이션 업데이트
        if is_orb_collapse_animation_active():
            update_orb_collapse_animation()

        # 이벤트 처리 (먼저!)
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()
            if event.type == pygame.KEYDOWN:
                if event.key in (pygame.K_ESCAPE, pygame.K_SPACE):
                    return
            elif event.type == pygame.MOUSEBUTTONDOWN:
                if event.button == 1:
                    return

        # === 렌더링 ===
        try:
            # 배경
            draw_field()
            draw_shaking_screen()
            draw_objects()

            # 어두운 오버레이 - 캐시된 Surface 사용
            overlay = get_cached_overlay(WIDTH, HEIGHT, 200)
            SCREEN.blit(overlay, (0, 0))

            # 메인 패널
            draw_modern_panel(SCREEN, panel_rect, "게임 오버 요약", (255, 100, 100))

            y_cursor = panel_y + 55

            # === 섹션 1: 골드 / 플레이타임 ===
            section1_h = 65
            section1_rect = pygame.Rect(content_x, y_cursor, content_width, section1_h)
            draw_section_container(SCREEN, section1_rect, "골드 / 플레이타임", "trophy")

            gold_text = font_body.render(_t("ui.accumulated_gold_fmt", "누적 골드: {}G").format(accumulated_gold), True, (255, 215, 0))
            SCREEN.blit(gold_text, (content_x + 20, y_cursor + 40))

            time_text = font_body.render(_t("ui.playtime_fmt", "플레이타임: {}").format(f"{game_minutes:02d}:{game_seconds:02d}"), True, (200, 220, 255))
            time_rect = time_text.get_rect(right=content_x + content_width - 20, top=y_cursor + 40)
            SCREEN.blit(time_text, time_rect)

            y_cursor += section1_h + 8

            # === 섹션 2: 클리어한 보스 ===
            bosses_per_row = 8
            if cleared_bosses:
                boss_rows = max(1, (len(cleared_bosses) + bosses_per_row - 1) // bosses_per_row)
                section2_h = 40 + boss_rows * (boss_thumb_size + 18) + 5
            else:
                section2_h = 60
            section2_rect = pygame.Rect(content_x, y_cursor, content_width, section2_h)
            draw_section_container(SCREEN, section2_rect, "클리어한 보스", "medal")

            if cleared_bosses:
                boss_spacing = boss_thumb_size + 12
                for i, boss in enumerate(cleared_bosses):
                    row = i // bosses_per_row
                    col = i % bosses_per_row
                    # 현재 행의 보스 수 계산하여 중앙 정렬
                    bosses_in_row = min(bosses_per_row, len(cleared_bosses) - row * bosses_per_row)
                    row_width = bosses_in_row * boss_spacing - 12
                    row_start_x = content_x + (content_width - row_width) // 2
                    bx = row_start_x + col * boss_spacing
                    by = y_cursor + 38 + row * (boss_thumb_size + 18)
                    # 보스 이미지 그리기
                    if boss.get("thumb"):
                        SCREEN.blit(boss["thumb"], (bx, by))
                    else:
                        pygame.draw.rect(SCREEN, (80, 80, 100), (bx, by, boss_thumb_size, boss_thumb_size), border_radius=6)
                        pygame.draw.rect(SCREEN, (120, 120, 140), (bx, by, boss_thumb_size, boss_thumb_size), 1, border_radius=6)
                    # 보스 이름 (이미지 아래)
                    name_surf = font_detail.render(boss["name"], True, (220, 220, 220))
                    name_rect = name_surf.get_rect(centerx=bx + boss_thumb_size // 2, top=by + boss_thumb_size + 2)
                    SCREEN.blit(name_surf, name_rect)
            else:
                no_boss = font_detail.render(_t("ui.no_bosses_cleared", "클리어한 보스가 없습니다."), True, (150, 150, 150))
                SCREEN.blit(no_boss, (content_x + 20, y_cursor + 42))

            y_cursor += section2_h + 8

            # === 섹션 3: 획득 아이템 (패시브/액티브 분리) ===
            icon_size = 32
            icons_per_row = 13
            icon_gap = 8
            max_display_items = icons_per_row * 2  # 카테고리별 최대 2줄

            total_items = len(acquired_passive_items) + len(acquired_active_items)
            # 섹션 높이 계산
            section3_h = 38  # 헤더
            if acquired_passive_items:
                p_rows = min(2, max(1, (len(acquired_passive_items) + icons_per_row - 1) // icons_per_row))
                section3_h += 20 + p_rows * (icon_size + icon_gap)
            if acquired_active_items:
                a_rows = min(2, max(1, (len(acquired_active_items) + icons_per_row - 1) // icons_per_row))
                section3_h += 20 + a_rows * (icon_size + icon_gap)
            if not acquired_passive_items and not acquired_active_items:
                section3_h = 60
            section3_h += 8

            section3_rect = pygame.Rect(content_x, y_cursor, content_width, section3_h)
            draw_section_container(SCREEN, section3_rect, f"획득 아이템 ({total_items}개)", "trophy")

            item_y = y_cursor + 38

            def _draw_item_icons(item_list, start_y, label, label_color):
                """아이템 아이콘 행 렌더링 헬퍼"""
                lbl = font_detail.render(f"{label} ({len(item_list)})", True, label_color)
                SCREEN.blit(lbl, (content_x + 15, start_y))
                grid_y = start_y + 16
                display = item_list[:max_display_items]
                for i, item in enumerate(display):
                    row = i // icons_per_row
                    col = i % icons_per_row
                    ix = content_x + 15 + col * (icon_size + icon_gap)
                    iy = grid_y + row * (icon_size + icon_gap)
                    try:
                        icon_surface = get_item_icon(item.get("name", ""))
                        if icon_surface:
                            if icon_surface.get_size() != (icon_size, icon_size):
                                icon_surface = pygame.transform.smoothscale(icon_surface, (icon_size, icon_size))
                            SCREEN.blit(icon_surface, (ix, iy))
                        else:
                            pygame.draw.rect(SCREEN, (80, 80, 100), (ix, iy, icon_size, icon_size), border_radius=4)
                            pygame.draw.rect(SCREEN, (120, 120, 140), (ix, iy, icon_size, icon_size), 1, border_radius=4)
                    except Exception:
                        pygame.draw.rect(SCREEN, (80, 80, 100), (ix, iy, icon_size, icon_size), border_radius=4)
                overflow = len(item_list) - len(display)
                rows_used = max(1, (len(display) + icons_per_row - 1) // icons_per_row) if display else 0
                if overflow > 0:
                    more_text = font_detail.render(f"+{overflow}", True, (200, 200, 200))
                    SCREEN.blit(more_text, (content_x + 15 + min(len(display), icons_per_row) * (icon_size + icon_gap) + 4, grid_y + 8))
                return 20 + rows_used * (icon_size + icon_gap)

            if acquired_passive_items:
                item_y += _draw_item_icons(acquired_passive_items, item_y, _t("ui.passive_tab", "패시브"), (100, 200, 255))
            if acquired_active_items:
                item_y += _draw_item_icons(acquired_active_items, item_y, _t("ui.active_tab", "액티브"), (255, 180, 100))
            if not acquired_passive_items and not acquired_active_items:
                no_item = font_detail.render(_t("ui.no_items_acquired", "획득한 아이템이 없습니다."), True, (150, 150, 150))
                SCREEN.blit(no_item, (content_x + 20, y_cursor + 42))

            y_cursor += section3_h + 8

            # === 섹션 4: 획득 퍽 (아이콘 표시) ===
            perk_icon_size = 32
            perk_spacing = 38
            perks_per_row = 13
            max_display_perks = perks_per_row * 2  # 최대 2줄

            if acquired_perks:
                perk_rows = min(2, max(1, (len(acquired_perks) + perks_per_row - 1) // perks_per_row))
                section4_h = 42 + perk_rows * (perk_icon_size + 8) + 5
            else:
                section4_h = 60
            section4_rect = pygame.Rect(content_x, y_cursor, content_width, section4_h)
            draw_section_container(SCREEN, section4_rect, f"획득 퍽 ({len(acquired_perks)}개)", "idea")

            if acquired_perks:
                display_perks = acquired_perks[:max_display_perks]
                overflow_perks = len(acquired_perks) - len(display_perks)

                for i, perk_data in enumerate(display_perks):
                    row = i // perks_per_row
                    col = i % perks_per_row
                    # 현재 행의 퍽 수 계산하여 중앙 정렬
                    perks_in_row = min(perks_per_row, len(display_perks) - row * perks_per_row)
                    row_width = perks_in_row * perk_spacing - (perk_spacing - perk_icon_size)
                    row_start_x = content_x + (content_width - row_width) // 2
                    px = row_start_x + col * perk_spacing
                    py = y_cursor + 40 + row * (perk_icon_size + 8)

                    # 퍽 박스 배경
                    perk_box = pygame.Surface((perk_icon_size + 4, perk_icon_size + 4), pygame.SRCALPHA)
                    pygame.draw.rect(perk_box, (20, 25, 40, 200), (0, 0, perk_icon_size + 4, perk_icon_size + 4), border_radius=5)
                    pygame.draw.rect(perk_box, perk_data["icon_color"], (0, 0, perk_icon_size + 4, perk_icon_size + 4), width=1, border_radius=5)
                    SCREEN.blit(perk_box, (px - 2, py - 2))

                    # 퍽 아이콘 그리기
                    try:
                        draw_skill_icon_mini(SCREEN, perk_data, px, py, perk_icon_size, scale_multiplier=1.5)
                    except Exception:
                        pass

                    # 레벨 표시 (우하단)
                    if perk_data["level"] > 1:
                        try:
                            level_font = pygame.font.Font(None, 14)
                            level_text = level_font.render(f"{perk_data['level']}", True, (255, 255, 255))
                            SCREEN.blit(level_text, (px + perk_icon_size - 8, py + perk_icon_size - 10))
                        except Exception:
                            pass

                if overflow_perks > 0:
                    more_perk = font_detail.render(_t("ui.plus_count_fmt", "+{}개").format(overflow_perks), True, (180, 180, 180))
                    SCREEN.blit(more_perk, (content_x + content_width - 50, y_cursor + section4_h - 18))
            else:
                no_perk = font_detail.render(_t("ui.no_perks_acquired", "획득한 퍽이 없습니다."), True, (150, 150, 150))
                SCREEN.blit(no_perk, (content_x + 20, y_cursor + 42))

            y_cursor += section4_h + 8

            # === 섹션 5: 전투 결과 ===
            section5_h = 60
            section5_rect = pygame.Rect(content_x, y_cursor, content_width, section5_h)
            draw_section_container(SCREEN, section5_rect, _t("ui.battle_result", "전투 결과"), "analysis")

            score_text = font_body.render(_t("ui.final_score", "최종 스코어: {wins} - {losses}").format(wins=final_wins, losses=final_losses), True, WHITE)
            SCREEN.blit(score_text, (content_x + 20, y_cursor + 38))

            stage_text = font_body.render(_t("ui.stage_boss", "스테이지 {stage}: {boss}").format(stage=display_stage, boss=current_boss_name), True, (200, 200, 255))
            stage_rect = stage_text.get_rect(right=content_x + content_width - 20, top=y_cursor + 38)
            SCREEN.blit(stage_text, stage_rect)

            # === 하단 안내 ===
            hint_text = font_hint.render(_t("ui.back_hint", "ESC / SPACE / 클릭: 돌아가기"), True, (140, 140, 140))
            hint_rect = hint_text.get_rect(center=(panel_rect.centerx, panel_rect.bottom - 12))
            SCREEN.blit(hint_text, hint_rect)

        except Exception as e:
            print(f"show_death_evaluation rendering error: {e}")
            import traceback
            traceback.print_exc()
            try:
                error_font = FontStyle.body()
                error_text = error_font.render(_t("ui.summary_unavailable", "요약 정보를 표시할 수 없습니다."), True, (255, 100, 100))
                SCREEN.blit(error_text, error_text.get_rect(center=(WIDTH // 2, HEIGHT // 2)))
            except Exception:
                pass

        pygame.display.flip()

def start_nemesis_death_animation():
    """네메시스 보스 패배 애니메이션 시작 (게임 루프 내에서 상태 기반으로 동작)"""
    global nemesis_death_active, nemesis_death_start_time, nemesis_death_particles
    global nemesis_death_explosions, nemesis_death_phase
    global nemesis_death_boss_fragments, nemesis_death_boss_opacity, nemesis_death_star_dropped

    nemesis_death_active = True
    nemesis_death_start_time = pygame.time.get_ticks()
    nemesis_death_particles = []
    nemesis_death_explosions = []
    nemesis_death_phase = 0
    nemesis_death_boss_fragments = []
    nemesis_death_boss_opacity = 255
    nemesis_death_star_dropped = False  # 별 드랍 플래그 초기화

    # 보스 파편 초기화 (보스를 여러 조각으로 나눔)
    boss_center_x = BOSS.centerx
    boss_center_y = BOSS.centery
    boss_width = BOSS.width
    boss_height = BOSS.height

    # 보스를 6x4 그리드로 분할하여 파편 생성
    grid_cols = 6
    grid_rows = 4
    frag_width = boss_width // grid_cols
    frag_height = boss_height // grid_rows

    for row in range(grid_rows):
        for col in range(grid_cols):
            frag_x = BOSS.left + col * frag_width + frag_width // 2
            frag_y = BOSS.top + row * frag_height + frag_height // 2
            # 중심에서의 거리 계산 (바깥쪽 파편이 먼저 떨어짐)
            dist_from_center = math.sqrt((frag_x - boss_center_x)**2 + (frag_y - boss_center_y)**2)
            max_dist = math.sqrt((boss_width/2)**2 + (boss_height/2)**2)
            delay = (1 - dist_from_center / max_dist) * 2000  # 중심 파편은 늦게 떨어짐

            nemesis_death_boss_fragments.append({
                'x': frag_x,
                'y': frag_y,
                'orig_x': frag_x,  # 원래 위치
                'orig_y': frag_y,
                'width': frag_width,
                'height': frag_height,
                'vx': 0,
                'vy': 0,
                'angle': 0,
                'angular_vel': 0,
                'detached': False,  # 분리 여부
                'detach_delay': delay,  # 분리 지연 시간
                'col': col,
                'row': row,
                'opacity': 255
            })

    # BGM 페이드아웃
    try:
        pygame.mixer.music.fadeout(1000)
    except Exception:
        pass

    # print("[Nemesis] 패배 애니메이션 시작!")


def update_nemesis_death_animation():
    """네메시스 패배 애니메이션 업데이트 (매 프레임 호출)"""
    global nemesis_death_active, nemesis_death_particles, nemesis_death_explosions
    global nemesis_death_phase, nemesis_death_start_time
    global nemesis_death_boss_fragments, nemesis_death_boss_opacity, nemesis_death_star_dropped

    if not nemesis_death_active:
        return False  # 애니메이션 비활성

    current_time = pygame.time.get_ticks()
    elapsed = current_time - nemesis_death_start_time

    # 보스 위치
    boss_center_x = BOSS.centerx
    boss_center_y = BOSS.centery
    boss_width = BOSS.width
    boss_height = BOSS.height

    # === Phase 0: 보스 분해 + 파편이 튀기면서 연속 폭발 (0~3.5초) ===
    if elapsed < NEMESIS_FINAL_EXPLOSION_TIME:
        nemesis_death_phase = 0
        progress = elapsed / NEMESIS_FINAL_EXPLOSION_TIME

        # 보스 투명도 점점 감소 (분해되면서)
        nemesis_death_boss_opacity = int(255 * (1 - progress * 0.7))  # 최대 70%까지 투명해짐

        # 보스 파편 업데이트 (점점 분리)
        for frag in nemesis_death_boss_fragments:
            if not frag['detached'] and elapsed > frag['detach_delay']:
                # 파편 분리 시작
                frag['detached'] = True
                # 바깥쪽으로 튀어나가는 속도
                dir_x = frag['orig_x'] - boss_center_x
                dir_y = frag['orig_y'] - boss_center_y
                dist = math.sqrt(dir_x**2 + dir_y**2) + 0.1
                frag['vx'] = (dir_x / dist) * random.uniform(1, 3)
                frag['vy'] = (dir_y / dist) * random.uniform(1, 2) + random.uniform(-1, 0)
                frag['angular_vel'] = random.uniform(-5, 5)

                # 분리 시 작은 폭발
                nemesis_death_explosions.append({
                    'x': frag['x'], 'y': frag['y'],
                    'radius': 5, 'max_radius': 20,
                    'alpha': 200, 'color': (255, 150, 50)
                })

            # 분리된 파편 움직임
            if frag['detached']:
                frag['x'] += frag['vx']
                frag['y'] += frag['vy']
                frag['vy'] += 0.15  # 중력
                frag['angle'] += frag['angular_vel']
                frag['opacity'] = max(0, frag['opacity'] - 2)  # 서서히 사라짐

        # 폭발 빈도 증가
        explosion_chance = 0.08 + progress * 0.35

        if random.random() < explosion_chance:
            spawn_x = boss_center_x + random.randint(-boss_width//2, boss_width//2)
            spawn_y = boss_center_y + random.randint(-boss_height//2, boss_height//2)

            # 파편 추가
            for _ in range(random.randint(3, 8)):
                angle = random.uniform(0, math.pi * 2)
                speed = random.uniform(2, 6)
                nemesis_death_particles.append({
                    'x': spawn_x, 'y': spawn_y,
                    'vx': math.cos(angle) * speed,
                    'vy': math.sin(angle) * speed - 1,
                    'size': random.randint(2, 5),
                    'color': random.choice([(255, 100, 0), (255, 200, 0), (255, 50, 0), (200, 200, 200), (100, 150, 255)]),
                    'life': random.randint(20, 60),
                    'gravity': 0.1
                })

            # 폭발 이펙트
            nemesis_death_explosions.append({
                'x': spawn_x, 'y': spawn_y,
                'radius': random.randint(10, 25),
                'max_radius': random.randint(30, 60),
                'alpha': 255,
                'color': random.choice([(255, 150, 0), (255, 200, 50), (255, 100, 50)])
            })

            # 폭발 사운드
            if random.random() < 0.2:
                try:
                    play_sound_with_volume(SOUND_STAGE6_INTERCEPTOR_HIT, sfx_volume * 0.5)
                except Exception:
                    pass

    # === Phase 1: 대폭발 + 보스 완전 산산조각 (3.5초~4초) ===
    elif elapsed < NEMESIS_DEATH_DURATION:
        if nemesis_death_phase == 0:
            nemesis_death_phase = 1
            nemesis_death_boss_opacity = 0  # 보스 완전히 사라짐

            # 모든 남은 파편 폭발시키기
            for frag in nemesis_death_boss_fragments:
                if not frag['detached'] or frag['opacity'] > 0:
                    # 강제로 바깥으로 튕겨나감
                    dir_x = frag['x'] - boss_center_x
                    dir_y = frag['y'] - boss_center_y
                    dist = math.sqrt(dir_x**2 + dir_y**2) + 0.1
                    frag['vx'] = (dir_x / dist) * random.uniform(8, 15)
                    frag['vy'] = (dir_y / dist) * random.uniform(8, 15)
                    frag['angular_vel'] = random.uniform(-15, 15)
                    frag['detached'] = True

            # 대폭발 파티클 대량 생성
            for _ in range(150):
                angle = random.uniform(0, math.pi * 2)
                speed = random.uniform(5, 18)
                nemesis_death_particles.append({
                    'x': boss_center_x, 'y': boss_center_y,
                    'vx': math.cos(angle) * speed,
                    'vy': math.sin(angle) * speed,
                    'size': random.randint(3, 10),
                    'color': random.choice([(255, 255, 255), (255, 200, 0), (255, 100, 0), (100, 200, 255), (200, 200, 200)]),
                    'life': random.randint(50, 120),
                    'gravity': 0.02
                })

            # 대폭발 이펙트 (여러 개)
            nemesis_death_explosions.append({
                'x': boss_center_x, 'y': boss_center_y,
                'radius': 10, 'max_radius': 250,
                'alpha': 255, 'color': (255, 255, 255)
            })
            for _ in range(5):
                offset_x = random.randint(-50, 50)
                offset_y = random.randint(-30, 30)
                nemesis_death_explosions.append({
                    'x': boss_center_x + offset_x, 'y': boss_center_y + offset_y,
                    'radius': 5, 'max_radius': 100,
                    'alpha': 255, 'color': random.choice([(255, 200, 0), (255, 150, 50)])
                })

            # 대폭발 사운드
            try:
                play_sound_with_volume(SOUND_STAGE6_BEAM, sfx_volume)
            except Exception:
                pass

            # 스타포인트 드랍 (3~6개 랜덤) - 1회만!
            if trade_point_system and not nemesis_death_star_dropped:
                nemesis_death_star_dropped = True  # 플래그 설정
                num_stars = random.randint(3, 6)
                for i in range(num_stars):
                    star_angle = (i / num_stars) * math.pi * 2
                    star_x = boss_center_x + math.cos(star_angle) * 60
                    star_y = boss_center_y + math.sin(star_angle) * 60
                    try:
                        trade_point_system.spawn_star(star_x, star_y, "nemesis_defeat")
                    except Exception:
                        pass
                # print(f"[Nemesis] 패배! 스타포인트 {num_stars}개 드랍!")

    # === Phase 2: 화면 정지 + 대기 후 종료 (4초~9초, 5초간 정지) ===
    else:
        if nemesis_death_phase != 2:
            nemesis_death_phase = 2
            # print(f"[Nemesis] Phase 2 시작! 5초간 화면 정지...")
        post_elapsed = elapsed - NEMESIS_DEATH_DURATION

        # 파편들 계속 업데이트 (서서히 사라짐)
        for frag in nemesis_death_boss_fragments:
            if frag['detached']:
                frag['x'] += frag['vx'] * 0.3  # 속도 감소
                frag['y'] += frag['vy'] * 0.3
                frag['vy'] += 0.05
                frag['opacity'] = max(0, frag['opacity'] - 3)

        if post_elapsed >= NEMESIS_POST_DELAY:
            # 애니메이션 종료 → show_result 호출
            nemesis_death_active = False
            nemesis_death_particles.clear()
            nemesis_death_explosions.clear()
            nemesis_death_boss_fragments.clear()
            # print("[Nemesis] 패배 애니메이션 완료! → show_result(True) 호출 예정")
            return True  # 애니메이션 완료, show_result 호출 필요

    # 파티클 업데이트
    new_particles = []
    for p in nemesis_death_particles:
        p['x'] += p['vx']
        p['y'] += p['vy']
        p['vy'] += p['gravity']
        p['life'] -= 1
        if p['life'] > 0:
            new_particles.append(p)
    nemesis_death_particles = new_particles

    # 폭발 이펙트 업데이트
    new_explosions = []
    for exp in nemesis_death_explosions:
        exp['radius'] += (exp['max_radius'] - exp['radius']) * 0.15
        exp['alpha'] -= 10
        if exp['alpha'] > 0:
            new_explosions.append(exp)
    nemesis_death_explosions = new_explosions

    return False  # 애니메이션 진행 중


def draw_nemesis_death_animation(screen):
    """네메시스 패배 애니메이션 그리기 (draw_objects 등에서 호출)"""
    if not nemesis_death_active:
        return

    elapsed = pygame.time.get_ticks() - nemesis_death_start_time

    # Phase 0: 보스 깜빡임 + 화면 흔들림
    if nemesis_death_phase == 0:
        progress = min(1.0, elapsed / NEMESIS_FINAL_EXPLOSION_TIME)
        shake_intensity = int(progress * 12)
        shake_x = random.randint(-shake_intensity, shake_intensity)
        shake_y = random.randint(-shake_intensity, shake_intensity)

        # 흔들림 효과를 위한 오프셋 반환 (호출자가 적용)
        globals()['nemesis_shake_x'] = shake_x
        globals()['nemesis_shake_y'] = shake_y
    else:
        globals()['nemesis_shake_x'] = 0
        globals()['nemesis_shake_y'] = 0

    # === 보스 파편 그리기 (분해 효과) ===
    for frag in nemesis_death_boss_fragments:
        if frag['opacity'] > 0:
            try:
                # 파편 크기
                frag_w = frag['width']
                frag_h = frag['height']

                # 파편 서피스 생성
                frag_surface = pygame.Surface((frag_w + 4, frag_h + 4), pygame.SRCALPHA)

                # 파편 색상 (네메시스 전함 색상 - 회색/금속)
                base_color = (80, 90, 100)  # 진한 회색 (금속)
                highlight_color = (120, 130, 140)  # 밝은 회색

                # 파편 본체 그리기
                pygame.draw.rect(frag_surface, (*base_color, int(frag['opacity'])),
                               (2, 2, frag_w, frag_h))
                # 하이라이트
                pygame.draw.rect(frag_surface, (*highlight_color, int(frag['opacity'] * 0.7)),
                               (2, 2, frag_w, 2))
                # 테두리
                pygame.draw.rect(frag_surface, (50, 55, 60, int(frag['opacity'])),
                               (2, 2, frag_w, frag_h), 1)

                # 분리된 파편은 회전 적용
                if frag['detached'] and abs(frag['angle']) > 0.1:
                    rotated = pygame.transform.rotate(frag_surface, frag['angle'])
                    rot_rect = rotated.get_rect(center=(int(frag['x']), int(frag['y'])))
                    screen.blit(rotated, rot_rect)
                else:
                    screen.blit(frag_surface, (int(frag['x'] - frag_w//2 - 2), int(frag['y'] - frag_h//2 - 2)))

                # 분리된 파편에 불꽃 효과
                if frag['detached'] and frag['opacity'] > 50:
                    if random.random() < 0.3:
                        spark_x = frag['x'] + random.randint(-frag_w//2, frag_w//2)
                        spark_y = frag['y'] + random.randint(-frag_h//2, frag_h//2)
                        spark_size = random.randint(2, 4)
                        spark_color = random.choice([(255, 150, 0), (255, 200, 50), (255, 100, 0)])
                        pygame.draw.circle(screen, spark_color, (int(spark_x), int(spark_y)), spark_size)
            except Exception:
                pass

    # 폭발 이펙트 그리기
    for exp in nemesis_death_explosions:
        if exp['alpha'] > 0:
            try:
                exp_surface = pygame.Surface((int(exp['radius'] * 2 + 10), int(exp['radius'] * 2 + 10)), pygame.SRCALPHA)
                center = int(exp['radius'] + 5)
                # 외부 링
                pygame.draw.circle(exp_surface, (*exp['color'], int(exp['alpha'] * 0.6)),
                                 (center, center), int(exp['radius']), 4)
                # 내부 글로우
                pygame.draw.circle(exp_surface, (*exp['color'], int(exp['alpha'] * 0.3)),
                                 (center, center), int(exp['radius'] * 0.6))
                screen.blit(exp_surface, (int(exp['x'] - exp['radius'] - 5), int(exp['y'] - exp['radius'] - 5)))
            except Exception:
                pass

    # 파티클 그리기
    for p in nemesis_death_particles:
        if p['life'] > 0:
            try:
                alpha = min(255, p['life'] * 5)
                p_surface = pygame.Surface((p['size'] * 2, p['size'] * 2), pygame.SRCALPHA)
                pygame.draw.circle(p_surface, (*p['color'], alpha), (p['size'], p['size']), p['size'])
                screen.blit(p_surface, (int(p['x'] - p['size']), int(p['y'] - p['size'])))
            except Exception:
                pass

    # Phase 1: 화면 플래시
    if nemesis_death_phase == 1:
        flash_elapsed = elapsed - NEMESIS_FINAL_EXPLOSION_TIME
        if flash_elapsed < 500:
            flash_alpha = int(220 * (1 - flash_elapsed / 500))
            flash_surface = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
            flash_surface.fill((255, 255, 255, flash_alpha))
            screen.blit(flash_surface, (0, 0))

    # Phase 2: VICTORY 텍스트 (5초 정지 중에 표시)
    if nemesis_death_phase == 2:
        post_elapsed = elapsed - NEMESIS_DEATH_DURATION
        if post_elapsed > 500:
            try:
                victory_alpha = min(255, int((post_elapsed - 500) / 500 * 255))
                victory_font = pygame.font.Font(None, 90)
                victory_text = victory_font.render("VICTORY", True, (255, 215, 0))
                victory_text.set_alpha(victory_alpha)
                text_rect = victory_text.get_rect(center=(WIDTH // 2, HEIGHT // 2))

                # 그림자 효과
                shadow_text = victory_font.render("VICTORY", True, (100, 80, 0))
                shadow_text.set_alpha(int(victory_alpha * 0.5))
                shadow_rect = shadow_text.get_rect(center=(WIDTH // 2 + 3, HEIGHT // 2 + 3))
                screen.blit(shadow_text, shadow_rect)
                screen.blit(victory_text, text_rect)
            except Exception:
                pass


def show_result(won):
    global medal_score, current_stage, session_medal_earned
    global special_gauge, special_ready, special_active
    global speedboots_obtained, speedgear_obtained  #  패시브 아이템 효과 초기화용
    global game_session_active  #  게임 세션 상태

    # 🎬 결과 화면 전환 페이드아웃
    try:
        play_fade_out(12)
    except Exception:
        pass
    global aipill_active  #  AI 필 변수 추가
    global final_round_wins, final_round_losses, round_wins, round_losses  #  최종 점수 저장
    global battery_obtained  #  배터리 변수 추가
    global revival_obtained, revival_used  #  부활 변수 추가
    global master_obtained, cooltime_obtained  #  장인, 쿨타임 변수 추가
    global chargebag_obtained, spikeboots_obtained, dashgear_obtained  #  충전가방, 스파이크부츠, 대쉬기어 변수 추가
    global bulkup_obtained, dashholder_obtained, gravitybelt_obtained  #  벌크업, 대쉬홀더, 무중력벨트 변수 추가
    global danger_sensor_obtained, sensor_obtained  #  센서 관련 변수 추가
    global rolling_charges  #  대쉬 토큰 수, 시너지 효과 변수 추가
    global walls, pending_wall, wall_installing, wall_install_timer, wall_install_gauge_visible, passive_item_list, round_losses  #  벽돌 변수 추가
    global deuce_mode, deuce_wins, deuce_losses, deuce_goal  #  듀스 시스템 변수 추가
    global whip_sound  #  상모돌리기 사운드 추가
    # global balloon_active, balloon_timer, balloons, balloon_used_this_round  # Stage 1 보스 풍선파티 스킬 제거됨
    global boss_hit_animation_active, boss_hit_animation_timer  #  보스 충돌 애니메이션 변수 추가
    global whip_active, whip_timer, whip_hit_by_player, whip_original_ball_speed  #  상모돌리기 관련 변수 추가
    global emotional_overdrive_active, emotional_overdrive_timer, overdrive_flash_timer, overdrive_trails  #  사이코볼 관련 변수 추가
    global boss_special_gauge, boss_special_ready, boss_special_waiting, boss_red_intensity  #  멘헤라걸 관련 변수 추가
    global enraged_boss_active  # 광폭화 보스 상태 확인용
    global quest_completion_glow_active, quest_completion_glow_timer  # 퀘스트 완료 빛 효과

    # 투기장 모드에서는 결과 화면 건너뛰기 (투기장 자체 결과 UI 사용)
    # 단, 배틀 결과는 저장하여 main()에서 반환할 수 있도록 함
    global arena_battle_result
    global arena_capture_phase, arena_capture_timer, arena_capture_result_flag
    global arena_capture_flee_x, arena_capture_flee_y, arena_capture_flee_vx
    global arena_capture_shots_left, arena_capture_net_active
    if arena_mode_enabled:
        # 이미 결과가 설정되어 있으면 중복 호출 방지
        if arena_battle_result is not None:
            return
        # 포획 페이즈 진행 중이면 결과 설정 차단
        if arena_capture_phase is not None:
            return
        # 승리 + 포획 활성화 → 포획 페이즈 시작 (배틀 종료 대신)
        if won and arena_capture_do_capture and arena_capture_phase is None:
            # 포획 튜토리얼 (첫 포획 시 1회)
            global _arena_capture_tutorial_shown, _arena_capture_tutorial_active, _arena_capture_tutorial_step
            if _arena_tutorial_enabled and not _arena_capture_tutorial_shown:
                _arena_capture_tutorial_step = 0
                _arena_capture_tutorial_active = True
                # print("[ArenaTutorial] 포획 튜토리얼 시작!")
            arena_capture_phase = "active"
            arena_capture_timer = 0.0
