                    raw_mx, raw_my = _original_mouse_get_pos()

                    # Surface 내부 좌표로 변환 (스케일링 적용)
                    local_x = (raw_mx - surf_offset_x) / GAME_SCALE_FACTOR if GAME_SCALE_FACTOR != 1.0 else (raw_mx - surf_offset_x)
                    local_y = (raw_my - surf_offset_y) / GAME_SCALE_FACTOR if GAME_SCALE_FACTOR != 1.0 else (raw_my - surf_offset_y)

                    # 클릭 판정 - 히트박스를 약간 확장
                    click_padding = 5
                    for weapon_name, slot_rect in _pillar_weapon_slots:
                        expanded_rect = slot_rect.inflate(click_padding * 2, click_padding * 2)
