                if not items_to_show:
                    no_item_text = font_medium.render(_t("ui.no_passive_items_short", "소지한 패시브 아이템이 없습니다"), True, (150, 150, 150))
                    no_item_rect = no_item_text.get_rect(center=(panel_x + panel_width // 2, item_list_y + 100))
