            draw.rect((80, 120, 200) if not _is_sage_ring else (160, 120, 255), (desc_panel_x, desc_panel_y, desc_panel_width, desc_panel_height), 2)
            # 설명 텍스트를 여러 줄로 나누기 (개선된 버전)
            def smart_text_wrap(text, max_width_chars=30):
                """텍스트를 보기 좋게 줄바꿈하는 함수"""
                if len(text) <= max_width_chars:
                    return [text]
                # 특수 문자로 구분할 수 있는 위치 찾기
                split_chars = [',', '/', '|', '·', ':', ';', '-']
                words = []
                # 먼저 공백으로 나누기
                temp_words = text.split()
                # 각 단어를 특수문자 기준으로 더 세분화
                for word in temp_words:
                    current_word = ""
                    for char in word:
                        current_word += char
                        if char in split_chars and len(current_word) > 1:
                            words.append(current_word)
                            current_word = "" 
                    if current_word:
                        words.append(current_word)
                if not words:
                    words = temp_words
                # 2줄로 나누는 경우 길이 균등하게 분배
                if len(' '.join(words)) <= max_width_chars * 2:
                    mid_point = len(words) // 2
                    # 최적의 분할점 찾기 (길이가 비슷하도록)
                    best_split = mid_point
                    target_length = len(text) // 2
                    min_diff = float('inf')
                    for i in range(1, len(words)):
                        line1_len = len(' '.join(words[:i]))
                        line2_len = len(' '.join(words[i:]))
                        diff = abs(line1_len - target_length) + abs(line2_len - target_length)
                        if diff < min_diff and line1_len <= max_width_chars and line2_len <= max_width_chars:
                            min_diff = diff
                            best_split = i
                    line1 = ' '.join(words[:best_split])
                    line2 = ' '.join(words[best_split:])
                    if line1 and line2:
                        return [line1, line2]
                # 기본 방식으로 폴백
                lines = []
                current_line = ""
                for word in words:
                    test_line = current_line + " " + word if current_line else word
                    if len(test_line) <= max_width_chars:
                        current_line = test_line
                    else:
                        if current_line:
                            lines.append(current_line)
                        current_line = word
                if current_line:
                    lines.append(current_line)
                return lines if lines else [text]
            if _is_sage_ring:
                # ── 현자의 반지 2탭 레이아웃 ──
                divider_x = desc_panel_x + desc_panel_width * 3 // 5
                # 좌측: 설명
                _sr_desc = "고대 현자가 남긴 신비로운 반지. 장착 시 모든 퍽 레벨이 1 증가합니다."
                _sr_lines = smart_text_wrap(_sr_desc, max_width_chars=22)
                _sr_font = get_font(13)
