def get_item_display_name(item) -> str:
    """수식어(옵션 품질)에 따른 표시 이름을 반환."""
    try:
        if isinstance(item, dict):
            name_key = item.get("name", "")
            prefix = item.get("name_prefix", "")
            # 호위무사 인장: 영웅 이름 포함 동적 표시
            if name_key == "hero_seal":
                hero_name = item.get("hero_name", "")
                if hero_name:
                    base_name = f"{hero_name}의 인장"
                else:
                    base_name = "호위무사의 인장"
                if prefix:
                    return f"{prefix} {base_name}".strip()
                return base_name
            # 초급/중급인장: 영웅 이름 포함 동적 표시
            if name_key in ("minor_hero_seal", "intermediate_hero_seal"):
                hero_name = item.get("hero_name", "")
                grade = item.get("seal_grade", "초급" if name_key == "minor_hero_seal" else "중급")
                if hero_name:
                    base_name = f"{hero_name}의 {grade}인장"
                else:
                    base_name = f"{grade}인장"
                if prefix:
                    return f"{prefix} {base_name}".strip()
                return base_name
        else:
            name_key = str(item)
            prefix = ""
        base_name = get_item_name_korean(name_key)
        if prefix:
            return f"{prefix} {base_name}".strip()
        return base_name
    except Exception:
        # 방어적 폴백
        if isinstance(item, dict):
            return str(item.get("name", item))
        return str(item)


def get_item_quality_color(item) -> tuple[int, int, int] | None:
    """아이템 품질 색상(수식어 등급 기준)을 반환."""
    try:
        if isinstance(item, dict):
            tier = item.get("quality_tier")
            if item.get("type") == "legendary":
                return (255, 215, 0)  # 황금색
        else:
            tier = None
        if tier:
            return QUALITY_TIER_COLOR.get(tier, _OPTION_COLOR_LOW)
    except Exception:
        pass
    return None
