        # 파일에 저장
        try:
            with open(log_file, "w", encoding="utf-8") as f:
                f.write(error_msg)
            # print(f"\n로그 파일이 저장되었습니다: {log_file}")
            # print("\n이 파일을 열어서 내용을 복사해주세요.")
        except Exception as log_error:
            print(f"\n로그 파일 저장 실패: {log_error}")

        # print("\n아무 키나 누르면 종료됩니다...")
